INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('9ea71d6f-fa42-4cd2-a582-56ae7c9f7d0a', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 31, 'Navegando el 25 de junio de 2022 hacia la Bahía de Tánger obtenemos una Demora de aguja al Faro de Punta Malabata de 093º, en ese mismo instante obtenemos una Demora de aguja a la luz [Fl(3)12s14M] del puerto de Tánger de 190º. Sabemos que el Desvío de la aguja es 1º(-). ¿Cuál de las siguientes coordenadas se aproxima más a nuestra posición?', 'c', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '9a90bb61c8f6ab8c', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.790682+00', '2025-09-13 13:53:10.790682+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('59a5f7e3-02bb-451a-a0fe-9428d7506849', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 32, 'El 4 de junio de 2022, situados en 30°50’N 006°15’W, navegamos al Rumbo de aguja = 244° con desvío de 3°(-). Tras 2 horas de navegación cambiamos a Ra=285°, el desvío no cambia, y navegamos a este nuevo rumbo otras 2 horas. Después navegamos 1 hora a Ra=260° con desvío de 1°(+). Por último, cambiamos a Ra=175°, el desvío no cambia, manteniendo rumbo otras 4 horas. La velocidad de máquinas es 12 nudos, siendo constante toda la navegación. ¿Qué coordenadas se aproximan más a la situación estimada?', 'b', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '7ce3c81a67a491b5', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.791365+00', '2025-09-13 13:53:10.791365+00', false);
