INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('07c67615-bfb9-4b4c-99a5-87293dc3fe65', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 34, 'El día 14 de junio de 2022, a las 08:30 HRB situados en la oposición de los Faros de Punta de Gracia y Cabo Espartel, a 3 millas de éste último navegamos con Rumbo verdadero = 270º a una velocidad de 4 nudos. A las 10:00 HRB tras navegar a mismo rumbo y velocidad, nos encontramos en latitud 025º 49´N y longitud 006º01´W. ¿Cuál de las siguientes respuestas se aproxima más al Rumbo de la corriente (Rc) e Intensidad horaria de la corriente (Ih) que nos afecta durante la navegación?', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '6d99dba7764ec64c', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.792953+00', '2025-09-13 13:53:10.792953+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('9f39c6e5-a673-404b-8e7b-f2382bf229a7', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 35, 'Navegando en la Ría de Arousa el día 9 de mayo de 2018 a una velocidad de 7 nudos y Rumbo de aguja = 002,5º, pasadas dos horas tras el crepúsculo vespertino tomamos un Azimut de Aguja a la estrella Polar igual a 2,5º (+). ¿Cuál de los siguientes resultados se aproxima más a nuestra', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '0ce22a03b4f46c40', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.793644+00', '2025-09-13 13:53:10.793644+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('9a2c10d0-cf05-4001-b9e0-97265d6850cd', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 36, 'Situados en posición 36º40´N 005º15´W con viento del NW que nos abate 4º, nos dirigimos al Faro aguja (Ra) se aproxima más al de nuestra embarcación?', 'a', NULL, NULL, 'Meteorología', NULL, NULL, 'b3831ee0293cf172', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.79438+00', '2025-09-13 13:53:10.79438+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('e7b2f3b6-bd55-4caf-a4fb-f9eaaf469bcf', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 37, 'El día 1 de junio de 2022 a las 05:20 HRB nos encontramos en situación 36° 00,6´N 005° 24,0´W navegando al Rumbo de aguja 254° con un desvío de 3° (-), a una velocidad de máquinas de 8 nudos. Situados, entramos en una zona de corriente desconocida. A las 06:35 HRB tomamos una Demora de aguja al Faro de Punta Malabata de 230,5° y una Demora de aguja al Faro de la Isla de Tarifa de 314°. Indique el rumbo de la corriente que se aproxima más de entre los siguientes:', 'b', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '0c5e7e32201d2121', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.795075+00', '2025-09-13 13:53:10.795075+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('4c5d1ede-62cb-4ee2-89db-73650aef66c5', '64a6d572-f6f1-413e-bf26-f3e6d69e7c92', 38, 'Nos encontramos navegando al Rumbo de aguja 265° con una velocidad de máquinas de 12 nudos. Malabata igual a 140°. Posteriormente, a las 06:08 HRB del mismo día tomamos una marcación de 157° babor al mismo faro. Sabemos que el desvío es 2°(-). ¿Cuál de las siguientes coordenadas se aproxima más a nuestra posición a las 06:08 HRB?', 'b', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '6c5271b2fc1f69a6', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.796021+00', '2025-09-13 13:53:10.796021+00', false);
