INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('73545f59-bfc1-40d8-b513-6af028a93974', 'f626284e-d97c-49f9-aefd-6a351a88ac4b', 31, 'Nos encontramos navegando al Rumbo de aguja 265° con una velocidad de máquinas de 12 nudos. Malabata igual a 140°. Posteriormente, a las 06:08 HRB del mismo día tomamos una marcación de 157° babor al mismo faro. Sabemos que el desvío es 2°(-). ¿Cuál de las siguientes coordenadas se aproxima más a nuestra posición a las 06:08 HRB?', 'b', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '6c5271b2fc1f69a6', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.82096+00', '2025-09-13 13:53:10.82096+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('2f81755b-83ba-4057-bd9f-f90063628a8d', 'f626284e-d97c-49f9-aefd-6a351a88ac4b', 32, 'Nos encontramos el día 24 de mayo de 2022 en el Faro de Cabo Trafalgar y ponemos rumbo para pasar a 3 millas de la marca cardinal Este de la granja acuícola de Barbate. El desvío es 3° (-). Seguimos navegando y una vez que tenemos el Faro de Punta de Gracia por babor nos afecta una corriente que nos produce una deriva de 4º al SW. ¿Cuál de los siguientes Rumbos efectivo y de aguja se aproxima más al que tendríamos en este momento?', 'a', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '7bd83b55157639f9', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.821812+00', '2025-09-13 13:53:10.821812+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('81e9e0e5-56f1-4455-a343-e149b77b79a0', 'f626284e-d97c-49f9-aefd-6a351a88ac4b', 33, 'El día 1 de junio de 2022 a las 05:20 HRB nos encontramos en situación 36° 00,6´N 005° 24,0´W navegando al Rumbo de aguja 254° con un desvío de 3° (-), a una velocidad de máquinas de 8 nudos. Situados, entramos en una zona de corriente desconocida. A las 06:35 HRB tomamos una Demora de aguja al Faro de Punta Malabata de 230,5° y una Demora de aguja al Faro de la Isla de Tarifa de 314°. Indique el rumbo de la corriente que se aproxima más de entre los siguientes:', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '0c5e7e32201d2121', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.822503+00', '2025-09-13 13:53:10.822503+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('dce3c59f-e36a-4d3d-a403-87f08066e31f', 'f626284e-d97c-49f9-aefd-6a351a88ac4b', 34, 'El día 14 de junio de 2022, a las 08:30 HRB situados en la oposición de los Faros de Punta de Gracia y Cabo Espartel, a 3 millas de éste último navegamos con Rumbo verdadero = 270º a una velocidad de 4 nudos. A las 10:00 HRB tras navegar a mismo rumbo y velocidad, nos encontramos en latitud 025º 49´N y longitud 006º01´W. ¿Cuál de las siguientes respuestas se aproxima más al Rumbo de la corriente (Rc) e Intensidad horaria de la corriente (Ih) que nos afecta durante la navegación?', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '6d99dba7764ec64c', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.823248+00', '2025-09-13 13:53:10.823248+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('37550747-964f-4a99-99ab-7c5a2f2a560c', 'f626284e-d97c-49f9-aefd-6a351a88ac4b', 35, 'Navegando en la Ría de Arousa el día 9 de mayo de 2018 a una velocidad de 7 nudos y Rumbo de aguja = 002,5º, pasadas dos horas tras el crepúsculo vespertino tomamos un Azimut de Aguja a la estrella Polar igual a 2,5º (+). ¿Cuál de los siguientes resultados se aproxima más a nuestra', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '0ce22a03b4f46c40', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.823956+00', '2025-09-13 13:53:10.823956+00', false);
