INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('deaf350c-ed5c-47ca-a9a6-cc3e9b704622', '381685b5-d8d2-4648-8e6c-21925fa0a086', 42, 'Nos encontramos el día 24 de mayo de 2022 en el Faro de Cabo Trafalgar y queremos poner rumbo para pasar a 3 millas de la marca cardinal Este de la granja acuícola de Barbate. El desvío es 3° (-). ¿Cuál de los siguientes Rumbos Verdadero y de Aguja más se aproximan para pasar a 3 millas de la marca cardinal Este de la granja acuícola de Barbate?', 'c', NULL, NULL, 'Carta de navegación', NULL, NULL, 'bde106d747eb8265', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-06-RECREO"}', '2025-09-13 13:53:10.960673+00', '2025-09-13 13:53:10.960673+00', false);
