INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('495fde3e-5033-4689-82fb-7cbabd14d2dc', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 32, 'Navegando al Rumbo verdadero=072º a una velocidad de máquinas de 8 nudos, observamos a la Hrb 16:06 el Faro de Punta Europa con una demora verdadera= 020º. Manteniendo rumbo y velocidad observamos el Faro de Punta Almina con una demora verdadera = 175º a la Hrb 16:36. Hallar la situación no simultánea más aproximada a la Hrb 16:36.', 'a', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '7be4f4b71fb60a9c', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.381501+00', '2025-09-13 13:53:11.381501+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('0641974a-5cb0-47c6-8a14-d04a8d6cbdf4', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 33, 'Situados el 12 de diciembre de 2022 a Hrb=08:45 en posición 35° 57,0´N; 005° 20,0´W nos encontramos en zona de corriente de Rc=N45W e Ih=2 nudos, navegando al Ra=275°. El desvío es 2° (-), la declinación magnética será la del año en curso y nuestra velocidad de máquinas es de 8 nudos. A las 09:30 decidimos proceder al puerto de Tarifa. Se pide determinar cuál de las siguientes respuestas más se aproxima al Rumbo y velocidad efectivos a las 9:30.', 'c', NULL, NULL, 'Meteorología', NULL, NULL, '8a2a8e0d85643fcb', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.382202+00', '2025-09-13 13:53:11.382202+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('2b7ce36a-90e8-445d-a78f-13ecb94fdf49', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 34, 'Hallar nuestra situación simultánea más aproximada estando situados en la oposición del Faro de Punta de Gracia y la punta del espigón norte del Puerto de Tánger observando el Faro de Punta Paloma con una demora verdadera=070º.', 'd', NULL, NULL, 'Meteorología', NULL, NULL, '478f86772ca308c9', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.382866+00', '2025-09-13 13:53:11.382866+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('521ca976-2207-4306-9361-93798acd579a', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 35, 'Situados en la posición A (35º55´N; 005º05´W) nos dirigimos en una embarcación a vela a una velocidad de 5 nudos hacia la posición B (36º10´N; 006º25´W). ¿Cuál de las siguientes respuestas más se aproxima al Rumbo y distancia entre la posición A y B?', 'd', NULL, NULL, 'Meteorología', NULL, NULL, '55e5011c4c3463c6', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.383534+00', '2025-09-13 13:53:11.383534+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('7d45e404-61a1-418a-a934-4e95c7e7fe23', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 36, 'Situados en la punta del espigón sur del puerto de Barbate, damos Rumbo para pasar a 3 millas del Faro de Cabo Trafalgar. Calcular el Rumbo de aguja más aproximado si el desvío de la aguja es 3ºW, la declinación magnética es la de la carta para el año en curso y tenemos un viento del NW que nos provoca un abatimiento de 4º.', 'c', NULL, NULL, 'Meteorología', NULL, NULL, 'e047ad5431dc1a34', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.384195+00', '2025-09-13 13:53:11.384195+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('4cdbc77d-2f78-40e8-b6f5-da04c2578a15', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 37, 'El dia 1 de diciembre de 2022, navegando con Rumbo de aguja 284º a una velocidad de 4,5 nudos a las 17:15 UTC, tomamos la demora de aguja a los Faros del Cabo Trafalgar y Cabo Espartel obteniendo respectivamente las siguientes lecturas, 330º y 204º. Durante la navegación nos encontramos bajo la influencia de un ligero viento Noroeste que nos abate 3º y una corriente de rumbo 180º e intensidad horaria 2 nudos. Sabiendo que el desvío de aguja es 3º (­), ¿cuál de las siguientes coordenadas más se aproxima a nuestra posición a las 20:15 Hrb?', 'b', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '0071a4a07690b86e', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.385057+00', '2025-09-13 13:53:11.385057+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('79b3de60-89cc-4be6-af02-4060dbe4fd3f', 'c2da70c9-abfd-40e3-806c-97195738978e', 18, 'Al sistema frontal complejo que ocurre cuando un frente frío alcanza a un frente cálido,', 'b', NULL, NULL, 'Reglamento (RIPA)', NULL, NULL, '90a96d82f08bc789', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.400278+00', '2025-09-13 13:53:11.400278+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('1f281680-80a4-4772-b231-a225c563e95d', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 38, 'Situados el 4 de diciembre de 2022 a Hrb= 11:45 en posición 35º53,8´N; 005º52,0´W nos encontramos en zona de corriente de dirección S35W e Ihc = 3 nudos. Así mismo ha comenzado a soplar un viento en la zona de componente Norte que nos abate 4º. Nuestro rumbo de aguja es de 052º, el desvío es de 1º(+) y la declinación magnetica será la del año en curso. Se pide determinar cuál de las siguientes respuestas más se aproxima a nuestra velocidad de máquinas para estar en el Faro de la Isla de Tarifa a Hrb= 13:45.', 'd', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '0fb34d5f1a907794', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.385736+00', '2025-09-13 13:53:11.385736+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('b2dd8e7e-ba81-4452-8997-47cfdf1b9169', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 39, 'El día 7 de diciembre de 2022 a Hrb= 6:45 nos encontramos en situación 36º05,6''N; 006º10,0''W navegando al rumbo de aguja 109º, el desvío es de 2º (+), la declinación magnética será la del año en curso y nuestra velocidad de máquinas es de 11 nudos. Situados, entramos en una zona de corriente desconocida. A Hrb= 07:15 tomamos una demora de aguja al Faro de Cabo Trafalgar de 002º y simultáneamente otra demora de aguja al Faro de Cabo Esparte de 156º. Se pide determinar cuál de las siguientes respuestas más se aproxima al rumbo e intensidad de la corriente.', 'a', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '0bf5d774f9cf9715', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.386466+00', '2025-09-13 13:53:11.386466+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('c8837683-7547-4c47-9459-c29484f40e02', 'fc852699-3330-415b-bf8a-9bc7e96fa50f', 40, 'El 28 de noviembre de 2022, situados en las coordenadas 36º05''N; 005º15''W, nos encontramos navegando al Ra= 235º, el desvío es de 4º (­). Tras 2 horas de navegación, cambiamos al Ra= 254º y navegamos a este nuevo rumbo durante 1 hora, el desvío es de 3º (­). Seguidamente navegamos durante 2 horas y 24 minutos al Ra=263º, manteniéndose el desvío constante respecto al rumbo anterior. Por último, cambiamos al Ra=227º, manteniendo este nuevo rumbo durante 3 horas, el desvío es de 4º (­). La declinación magnética será de 1º (­). La velocidad de máquinas es de 8 nudos siendo constante durante toda la navegación. ¿Cuál de las siguientes respuestas más se aproxima a la posición final estimada de nuestra embarcación?', 'a', NULL, NULL, 'Teoría de la navegación', NULL, NULL, 'c758fbd417893e12', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.387181+00', '2025-09-13 13:53:11.387181+00', false);
