INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('b68e76cc-15cf-412e-a823-c8c0b675db61', 'c2da70c9-abfd-40e3-806c-97195738978e', 31, 'El día 1 de diciembre de 2022, navegando con Rumbo de aguja 284º a una velocidad de 4,5 nudos a las 17:15 UTC, tomamos la demora de aguja a los Faros del Cabo Trafalgar y Cabo Espartel obteniendo respectivamente las siguientes lecturas, 330º y 204º. Durante la navegación nos encontramos bajo la influencia de un ligero viento Noroeste que nos abate 3º y una corriente de rumbo 180º e intensidad horaria 2 nudos. Sabiendo que el desvío de aguja es 3º (­), ¿cúal de las siguientes coordenadas más se aproxima a nuestra posición a las 20:15 Hrb?', 'd', NULL, NULL, 'Emergencias en la mar', NULL, NULL, 'dca1660f6dc8acc3', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.410172+00', '2025-09-13 13:53:11.410172+00', false);
