INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('ff99a7df-22f5-43d3-a1b1-859ba8c973ce', 'c2da70c9-abfd-40e3-806c-97195738978e', 33, 'Situados el 4 de diciembre de 2022 a Hrb= 11:45 en posición 35º53,8''N; 005º 52,0''W nos encontramos en zona de corriente de dirección S35W e Ih= 3 nudos. Así mismo ha comenzado a soplar un viento en la zona de componente Norte que nos abate 4º. Nuestro rumbo de aguja es de 052º, el desvío es de 1º (+) y la declinación magnética será la del año en curso. Se pide determinar cuál de las siguientes respuestas más se aproxima a nuestra velocidad de máquinas para estar en el Faro de la Isla de Tarifa a Hrb= 13:45.', 'a', NULL, NULL, 'Meteorología', NULL, NULL, 'cd9fbfda9d25745e', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.411939+00', '2025-09-13 13:53:11.411939+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('0e44584f-4035-4e1c-ac22-346422c160e7', 'c2da70c9-abfd-40e3-806c-97195738978e', 34, 'Situados en la punta del espigón sur del puerto de Barbate, damos Rumbo para pasar a 3 millas del Faro de Cabo Trafalgar. Calcular el Rumbo de aguja más aproximado si el desvío de la aguja es 3ºW, la declinación magnética es la de la carta para el año en curso y tenemos un viento del NW que nos provoca un abatimiento de 4º.', 'd', NULL, NULL, 'Meteorología', NULL, NULL, 'e047ad5431dc1a34', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.41277+00', '2025-09-13 13:53:11.41277+00', false);
