INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('292b2b89-89bc-43bf-a1ec-ce427de9c5ef', 'c2da70c9-abfd-40e3-806c-97195738978e', 36, 'Navegando al Rumbo verdadero=072º a una velocidad de máquinas de 8 nudos, observamos a la Hrb 16:06 el Faro de Punta Europa con una demora verdadera= 020º. Manteniendo rumbo y velocidad observamos el Faro de Punta Almina con una demora verdadera = 175º a la Hrb 16:36. Hallar la situación no simultánea más aproximada a la Hrb 16:36.', 'b', NULL, NULL, 'Meteorología', NULL, NULL, '7be4f4b71fb60a9c', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.414433+00', '2025-09-13 13:53:11.414433+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('308c5e98-e103-4a87-89a6-7dc04a17ed55', 'c2da70c9-abfd-40e3-806c-97195738978e', 37, 'El dia 7 de diciembre de 2022 a Hrb= 06:45 nos encontramos en situación 36º05,6''N; 006º10,0''W navegando al rumbo de aguja 109º, el desvío es de 2º (+), la declinación magnética será la del año en curso y nuestra velocidad de máquinas es de 11 nudos. Situados, entramos en una zona de corriente desconocida. A Hrb=07:15 tomamos una demora de aguja al Faro de Cabo Trafalgar de 002º y simultáneamente otra demora de aguja al Faro de Cabo Espartel de 156º. Se pide determinar cuál de las siguientes respuestas más se aproxima al rumbo e intensidad de la corriente.', 'c', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '732e949a86869d4e', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.41526+00', '2025-09-13 13:53:11.41526+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('ace6aa06-290c-464a-9f8d-d80c797e1bea', 'c2da70c9-abfd-40e3-806c-97195738978e', 38, 'Situados en la posición A (35º55´N; 005º05´W) nos dirigimos en una embarcación a vela a una velocidad de 5 nudos hacia la posición B (36º10´N; 006º25´W). ¿Cuál de las siguientes respuestas más se aproxima al Rumbo y distancia entre la posición A y B?', 'c', NULL, NULL, 'Teoría de la navegación', NULL, NULL, '55e5011c4c3463c6', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.416119+00', '2025-09-13 13:53:11.416119+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('19bec463-6bbf-4064-9cdd-602be5aefb02', 'c2da70c9-abfd-40e3-806c-97195738978e', 39, 'El 28 de noviembre de 2022, situados en las coordenadas 36º05''N; 005º15''W, nos encontramos navegando al Ra= 235º, el desvío es de 4º (­). Tras 2 horas de navegación, cambiamos al Ra= 254º y navegamos a este nuevo rumbo durante 1 hora, el desvío es de 3º (­). Seguidamente navegamos durante 2 horas y 24 minutos al Ra=263º, manteniéndose el desvío constante respecto al rumbo anterior. Por último, cambiamos al Ra=227º, manteniendo este nuevo rumbo durante 3 horas, el desvío es de 4º (­). La declinación magnética será de 1º (­). La velocidad de máquinas es de 8 nudos siendo constante durante toda la navegación. ¿Cuál de las siguientes respuestas más se aproxima a la posición final estimada de nuestra embarcación?', 'a', NULL, NULL, 'Teoría de la navegación', NULL, NULL, 'cd24c5f3549455e2', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2022-12-RECREO"}', '2025-09-13 13:53:11.416945+00', '2025-09-13 13:53:11.416945+00', false);
