INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('6ce13942-aa92-451f-90f8-c6a0a7590338', '78b3c731-55a5-458e-81cc-14b1c80274ff', 31, 'Situados el 13 de marzo de 2023 a Hrb 14:15 en posición 36° 13,0´N; 005° 13,0´W nos encontramos en zona de corriente de dirección N20W e Ih = 2,4 nudos, y ha comenzado a soplar un viento en la zona de componente Sur que nos abate 2°. Nuestro rumbo de aguja es de 215°, el desvío es de 1° (+) y la declinación magnética es 1°W. Calcular nuestra velocidad de máquinas más aproximada para estar en el Faro de Punta Europa a Hrb 14:45.', 'd', NULL, NULL, 'Emergencias en la mar', NULL, NULL, 'eadb30b6da904267', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.556732+00', '2025-09-13 13:53:11.556732+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('cc16b886-eaee-41cb-80a4-f83b8154ad61', '78b3c731-55a5-458e-81cc-14b1c80274ff', 32, 'Navegando al rumbo verdadero=115º a una velocidad de máquinas de 10 nudos, observamos a la Hrb 16:06 el Faro de Cabo Trafalgar con una demora verdadera de 005º. Manteniendo rumbo y velocidad observamos el Faro de Punta Gracia con una demora verdadera= 032º a la Hrb 16:36. Hallar la situación no simultánea más aproximada a la Hrb 16:36.', 'a', NULL, NULL, 'Emergencias en la mar', NULL, NULL, 'c751df277b07d3ca', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.557519+00', '2025-09-13 13:53:11.557519+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('dfade01f-6016-4719-aff4-4e820a5244b2', '78b3c731-55a5-458e-81cc-14b1c80274ff', 33, 'Situados el 4 de marzo de 2023 a Hrb 10:15 en posición 36° 05,6´N; 006° 09,0´W nos encontramos en zona de corriente de Rc=S45E e Ih=4 nudos, navegando al Ra=115°. El desvío es 3° (-), la declinación magnética será la del año en curso y nuestra velocidad de máquinas es de 6 nudos. Se pide el rumbo y velocidad efectivos más aproximados a Hrb 11:30, suponiendo que las condiciones de navegación se mantienen estables desde Hrb 10:15.', 'a', NULL, NULL, 'Meteorología', NULL, NULL, '99ba46163fd93b0e', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.558198+00', '2025-09-13 13:53:11.558198+00', false);
