INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('0672386c-43ec-42af-9c60-c066a333239c', '78b3c731-55a5-458e-81cc-14b1c80274ff', 35, 'Nos encontramos el día 1 de mayo de 2023 en el Faro de Punta Europa y ponemos rumbo para pasar a 1,6 millas del Faro de Punta Cires. El desvío es 4° (-), la declinación magnética será la del año en curso. ¿Cuál de los siguientes rumbos más se aproximan al escenario planteado una vez nos encontramos navegando al rumbo verdadero, teniendo en cuenta que en la zona tenemos una corriente que nos produce una deriva de 2° al NNW?', 'c', NULL, NULL, 'Meteorología', NULL, NULL, 'bc94930e3c374e71', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.559559+00', '2025-09-13 13:53:11.559559+00', false);
