INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('88f5733a-445e-4d12-bbdf-09ef9fe49f03', '7f6eacb2-4db4-46b3-9109-94922c47e09b', 32, 'Nos encontramos el día 1 de mayo de 2023 en el Faro de Punta Europa y ponemos rumbo para pasar a 1,6 millas del Faro de Punta Cires. El desvío es 4° (-), la declinación magnética será la del año en curso. ¿Cuál de los siguientes rumbos más se aproximan al escenario planteado una vez nos encontramos navegando al rumbo verdadero, teniendo en cuenta que en la zona tenemos una corriente que nos produce una deriva de 2° al NNW?', 'a', NULL, NULL, 'Emergencias en la mar', NULL, NULL, 'bc94930e3c374e71', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.586172+00', '2025-09-13 13:53:11.586172+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('06aec59b-4348-4b17-b33f-60004b3c06d9', '7f6eacb2-4db4-46b3-9109-94922c47e09b', 33, 'El día 1 de febrero de 2023 a Hrb 04:45 nos encontramos en situación 35° 51,0´N; 006° 11,0´W navegando al rumbo de aguja 083°, el desvío es de 2° (+), la declinación magnética será de 1°W y nuestra velocidad de máquinas es de 4,5 nudos. Situados, entramos en una zona de corriente desconocida. A Hrb 07:05 tomamos una demora de aguja al Faro de Punta de Gracia de 035° y simultáneamente otra demora de aguja al Faro de Cabo Espartel de 150°. Determinar el Rumbo e intensidad de la corriente.', 'b', NULL, NULL, 'Meteorología', NULL, NULL, '6a715f0403c85fac', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.586861+00', '2025-09-13 13:53:11.586861+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('a88a959e-30e2-43a2-9b9c-8f317f797c2e', '7f6eacb2-4db4-46b3-9109-94922c47e09b', 34, 'Situados el 13 de marzo de 2023 a Hrb 14:15 en posición 36° 13,0´N; 005° 13,0´W nos encontramos en zona de corriente de dirección N20W e Ih = 2,4 nudos, y ha comenzado a soplar un viento en la zona de componente Sur que nos abate 2°. Nuestro rumbo de aguja es de 215°, el desvío es de 1° (+) y la declinación magnética es 1°W. Calcular nuestra velocidad de máquinas más aproximada para estar en el Faro de Punta Europa a Hrb 14:45.', 'a', NULL, NULL, 'Meteorología', NULL, NULL, 'eadb30b6da904267', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-04-RECREO"}', '2025-09-13 13:53:11.587533+00', '2025-09-13 13:53:11.587533+00', false);
