INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('7ed78222-49a3-4052-8b30-7633fe61eae5', '63d5982e-07e3-4b5e-aa21-7881b58e4fb1', 44, 'Encontrándonos a Hrb 16:00 en la oposición Punta Europa ­ Punta Almina, con un desvío de aguja de 2º(­) tomamos demora de aguja a Punta Carnero=302º. Situados damos rumbo para pasar a 2 millas al Sur verdadero de Isla Tarifa; puestos a rumbo el desvío es de 4º(­). Cuando Punta Cires nos demora por el 137º de aguja, ponemos rumbo a la punta del espigón del Puerto de Tánger. Sabiendo que la declinación magnética en la zona para ese día es de 3ºW y que la velocidad de máquinas durante todo el ejercicio es de 10 nudos, se pide calcular la Hrb a la que Punta Alcazar [Fl(4)12s8M] estará a nuestro través de babor.', 'c', NULL, NULL, 'Carta de navegación', NULL, NULL, '0619f7374bf2218b', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2023-06-RECREO"}', '2025-09-13 13:53:11.878882+00', '2025-09-13 13:53:11.878882+00', false);
