INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('7c065360-af1c-4912-9096-20d616b0d033', '525a4274-1709-4a50-b436-96e482e76f6c', 35, 'El 16 de octubre de 2023, situados en las coordenadas l=35°50’N; L=006°10’W, nos encontramos navegando al Ra= 080° y el desvío es de 3° (+). Transcurrida 1 hora de navegación, variamos al Ra= 090° y navegamos a este nuevo rumbo durante 3 horas, el desvío es de 2° (+). Seguidamente navegamos durante 1 hora y 30 minutos al Ra= 075°, el desvío es 0°. Por último, cambiamos al Ra= 085°, manteniendo este nuevo rumbo durante 2 horas, el desvío es de 2° (-). La declinación magnética será de 2º(­) y la velocidad de máquinas es de 12 nudos, siendo constante durante toda la navegación. Calcular la posición final estimada de nuestro buque.', 'a', NULL, NULL, 'Meteorología', NULL, NULL, '06b38ce6f28c8851', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.141286+00', '2025-09-13 13:53:12.141286+00', false);
