INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('a0b34a7b-090f-4ecc-9eaf-0250054a680d', '4a523d83-a7e0-4ee2-b62c-22b0a0d8966a', 31, 'Situados el 1 de noviembre de 2023 a Hrb 18:15 en posición l= 35° 50,0´N; L= 005° 59,0´W, nos encontramos en zona de corriente de Rc=NNE e Ihc= 4,5 nudos, navegando al Ra= 330°. El desvío es 1°(-), la declinación magnética será la del año en curso y nuestra velocidad de máquinas es de 8 nudos. Se pide rumbo y velocidad efectivos más aproximados de entre los siguientes a Hrb 19:00, suponiendo que las condiciones de navegación se mantienen estables desde Hrb 18:15.', 'd', NULL, NULL, 'Emergencias en la mar', NULL, NULL, '2518518e86b1999e', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.1668+00', '2025-09-13 13:53:12.1668+00', false);
