INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('24938591-066f-45f7-81ca-bfcf52798759', '4a523d83-a7e0-4ee2-b62c-22b0a0d8966a', 33, 'Situados en la Marca cardinal norte cercana a Punta Malabata, damos rumbo para pasar a 3 millas del Faro de Cabo Espartel. Calcular el Rumbo de aguja más aproximado, si el desvío de la aguja es 2ºE, la declinación magnética es la de la carta para el año en curso y tenemos un viento del S que nos provoca un abatimiento de 6º.', 'd', NULL, NULL, 'Meteorología', NULL, NULL, '7debcabd1cad4f60', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.168289+00', '2025-09-13 13:53:12.168289+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('d616bd3b-c065-4f85-824a-ab005152a03e', '4a523d83-a7e0-4ee2-b62c-22b0a0d8966a', 34, 'Siendo las 10:15, situados en la oposición entre los Faros de Cabo Trafalgar y Punta Gracia, a 4 millas de este último nos encontramos navegando a vela con un Rumbo de aguja 190º y velocidad de máquinas de 4 nudos. Durante la navegación el viento del sureste nos abate 8º y nos afecta una corriente de rumbo 280º, con una Ihc de 2,5 nudos. ¿Cuál de las siguientes opciones se aproxima', 'a', NULL, NULL, 'Meteorología', NULL, NULL, 'ab83f84164442580', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.168982+00', '2025-09-13 13:53:12.168982+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('9cd0a6e6-4b14-4a3b-93e7-c5dd45de7629', '4a523d83-a7e0-4ee2-b62c-22b0a0d8966a', 35, 'Navegando al Rumbo verdadero=110º a una velocidad de máquinas de 9 nudos, observamos a la Hrb 11:06 el Faro de Cabo Trafalgar, con una demora verdadera de 045º. Manteniendo rumbo y velocidad observamos el Faro de Punta de Gracia a una distancia de 7 millas a la Hrb 12:00. Hallar la situación no simultánea más aproximada a la Hrb 12:00.', 'd', NULL, NULL, 'Meteorología', NULL, NULL, 'a6d7d697f180d840', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.169675+00', '2025-09-13 13:53:12.169675+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('b37710e1-c669-4e6c-a82b-b138a069dfbc', '4a523d83-a7e0-4ee2-b62c-22b0a0d8966a', 36, 'El 16 de octubre de 2023, situados en las coordenadas l= 35°50’N; L= 006°10’W, nos encontramos navegando al Ra=080° y el desvío es de 3° (+). Transcurrida 1 hora de navegación, variamos al Ra= 090° y navegamos a este nuevo rumbo durante 3 horas, el desvío es de 2° (+). Seguidamente navegamos durante 1 hora y 30 minutos al Ra=075°, el desvío es 0°. Por último, cambiamos al Ra= 085°, manteniendo este nuevo rumbo durante 2 horas, el desvío es de 2° (-). La declinación magnética será de 2º(­) y la velocidad de máquinas es de 12 nudos, siendo constante durante toda la navegación. Calcular la posición final estimada de nuestro buque.', 'd', NULL, NULL, 'Meteorología', NULL, NULL, '06b38ce6f28c8851', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2023-11-RECREO"}', '2025-09-13 13:53:12.170382+00', '2025-09-13 13:53:12.170382+00', false);
