INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('8477e8bf-e4fd-42ca-8196-6e0c667720ea', '320cbdea-651f-4a19-a1f1-9157dac18ccd', 42, 'A Hrb: 10:00, navegando con un desvío de aguja de 3°(-) tomamos simultáneamente demora de aguja a Isla Tarifa = 074° y a Cabo Espartel = 176°. Situados, ponemos rumbo para pasar a 2 millas al Norte verdadero de Punta Cires, con una velocidad de máquinas de 5 nudos. Seguimos navegando, manteniendo rumbo y velocidad, hasta Hrb= 15:00, momento en el que damos rumbo a la boya cardinal Este en las inmediaciones de la Ensenada de Getares (Bahía de Algeciras) manteniendo la velocidad de máquinas de 5 nudos. Sabiendo que la declinación magnética en la zona para ese día es de 2°(E), se pide calcular la situación de estima a Hrb: 16:24.', 'a', NULL, NULL, 'Carta de navegación', NULL, NULL, 'a097add97e0ebaee', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2024-11-RECREO"}', '2025-09-13 13:53:12.854757+00', '2025-09-13 13:53:12.854757+00', false);
