INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('8bffb925-f35a-4831-b631-cc26e8e50d21', '6e59026c-0eab-4443-b6ec-3a4d341bec6a', 32, 'Situados a 3 millas al Oeste verdadero de Cabo Trafalgar siendo la Hrb= 14:00, ponemos Ra= 240º con declinación magnética = 2º W y desvío = 2º W, estando afectado por un viento del Norte que nos abate 10°, con una velocidad de máquinas de 10 nudos. A la Hrb=15:00 ponemos rumbo al Faro de Cabo Espartel, sabiendo que hemos entrado en zona de corriente con Rc=90º e Ihc=3 nudos, desvío al nuevo rumbo= 1º W y rolando el viento a poniente abatiendo unos 15°. A la Hrb= 15:30 cesa el viento y la corriente y ponemos Ra=60º con desvío al nuevo rumbo de 10ºE. Determinar la situación estimada a Hrb=17:00h.', 'b', NULL, NULL, 'Emergencias en la mar', NULL, NULL, 'c81bbead320a1bf7', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-04-RECREO"}', '2025-09-13 13:53:13.331706+00', '2025-09-13 13:53:13.331706+00', false);
