INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('8ed09c24-d3c4-4000-ab7f-867ed9ea2aba', 'a451f3a1-1feb-483f-a640-2a12140576a7', 27, 'En relación con la Regla 26 de la parte C del RIPA sobre “Luces y Marcas”, si durante la navegación diurna divisamos una embarcación que exhibe, en el lugar más visible, dos marcas: la primera marca consistente en dos conos unidos por sus vértices en línea vertical, uno sobre el otro; y la segunda, un cono con el vértice hacia arriba, ¿de qué tipo de embarcación se trata?', 'b', NULL, NULL, 'Reglamento (RIPA)', NULL, NULL, '598a3f3764f26fe6', '{"es_duplicada": false, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.706166+00', '2025-09-14 14:34:33.491277+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('6eb12d3c-9b91-430b-b2db-56347cbcc1b7', 'a451f3a1-1feb-483f-a640-2a12140576a7', 40, 'En un determinado lugar, actualizando la declinación magnética que viene en la carta, nos da 11°NW y el desvío al rumbo que navegamos, obtenido de la tablilla de desvíos, es de 4º(+), ¿cuál será la corrección total?', 'b', NULL, NULL, 'Teoría de la navegación', '', NULL, 'd5bd0a7609a728d7', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.719679+00', '2025-09-15 11:35:53.361556+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('1e830ab8-8ae1-42e4-b5e5-3ed0fe5bdba8', 'a451f3a1-1feb-483f-a640-2a12140576a7', 43, 'A Hrb= 11:30, navegando con rumbo de aguja= 220º y un desvío= 3° (-), se toma simultáneamente demora de aguja al Faro Punta Europa= 280° y demora de aguja al Faro Punta Almina= 201º. Una vez situados se da rumbo al Faro de Isla de Tarifa con un desvío de aguja de 4º (-) y una velocidad de máquinas de 7,5 nudos. Calcular el rumbo de aguja al Faro de Isla de Tarifa y la Hrb cuando nos encontremos al Norte verdadero del Faro de Punta Cires. En el momento de la navegación la declinación magnética en toda la zona es de 5°(E).', 'a', NULL, NULL, 'Carta de navegación', NULL, NULL, '295a94106e05bc03', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.722851+00', '2025-09-13 13:53:13.722851+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('1b590c76-0555-4e98-96cc-ff62f872af8c', 'a451f3a1-1feb-483f-a640-2a12140576a7', 44, 'A Hrb= 09:00 nos encontramos situados al Sur verdadero de Isla Tarifa, cuando con nuestra aguja obtenemos demora de Punta Alcázar = 109°. El desvío es 3° (+). En ese momento damos rumbo para pasar a 2 millas al Norte verdadero de Punta Cires. El desvío de la aguja para este rumbo es 2°(+). Mantenemos rumbo y velocidad hasta que obtenemos demora de aguja a Punta Carnero= 270° y demora de aguja a Punta Europa= 295°. En dicho instante damos rumbo al extremo Sur del espigón del Puerto de Sotogrande [Fl(3)G.11s4M], en las inmediaciones del Río Guadiaro. Se pide calcular nuestra posición a Hrb= 13:00, sabiendo que nuestra velocidad de máquinas para todo el ejercicio es de 6 nudos y la declinación magnética en la zona para ese día es de 2°(W).', 'd', NULL, NULL, 'Carta de navegación', NULL, NULL, '6e2568eb1bb7e14a', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.723936+00', '2025-09-13 13:53:13.723936+00', false);
