INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('34f6ddcb-318d-4ea9-8a49-65912b218fa4', 'c6af08ff-dba0-4498-b527-45335cb147f1', 42, 'A Hrb= 09:00 nos encontramos situados al Sur verdadero de Isla Tarifa, cuando con nuestra aguja obtenemos demora de Punta Alcázar = 109°. El desvío es 3° (+). En ese momento damos rumbo para pasar a 2 millas al Norte verdadero de Punta Cires. El desvío de la aguja para este rumbo es 2°(+). Mantenemos rumbo y velocidad hasta que obtenemos demora de aguja a Punta Carnero= 270° y demora de aguja a Punta Europa= 295°. En dicho instante damos rumbo al extremo Sur del espigón del Puerto de Sotogrande [Fl(3)G.11s4M], en las inmediaciones del Río Guadiaro. Se pide calcular nuestra posición a Hrb= 13:00, sabiendo que nuestra velocidad de máquinas para todo el ejercicio es de 6 nudos y la declinación magnética en la zona para ese día es de 2°(W).', 'd', NULL, NULL, 'Carta de navegación', NULL, NULL, '6e2568eb1bb7e14a', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.740641+00', '2025-09-13 13:53:13.740641+00', false);
