INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('3f54cb99-aba2-4355-a7f5-78a99fda2aaa', 'e73c5e06-38ec-4353-9153-5bc14fc07a0f', 42, 'Encontrándonos con nuestra embarcación en la oposición Isla Tarifa – Punta Alcázar, tomamos simultáneamente demora de aguja a Isla Tarifa= 344º y demora de aguja a Punta Cires= 117, 5º. Se pide calcular la situación verdadera.', 'a', NULL, NULL, 'Carta de navegación', NULL, NULL, 'fd0e8739608ae63e', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.759505+00', '2025-09-13 13:53:13.759505+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('28a46444-1b00-4d19-9a60-cb40821c9f8f', 'e73c5e06-38ec-4353-9153-5bc14fc07a0f', 43, 'A Hrb= 11:30, navegando con rumbo de aguja= 220º y un desvío= 3° (-), se toma simultáneamente demora de aguja al Faro Punta Europa= 280° y demora de aguja al Faro Punta Almina= 201º. Una vez situados se da rumbo al Faro de Isla de Tarifa con un desvío de aguja de 4º (-) y una velocidad de máquinas de 7,5 nudos. Calcular el rumbo de aguja al Faro de Isla de Tarifa y la Hrb cuando nos encontremos al Norte verdadero del Faro de Punta Cires. En el momento de la navegación la declinación magnética en toda la zona es de 5°(E).', 'a', NULL, NULL, 'Carta de navegación', NULL, NULL, '295a94106e05bc03', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.760582+00', '2025-09-13 13:53:13.760582+00', false);
INSERT INTO public.questions (id, exam_id, numero_pregunta, texto_pregunta, respuesta_correcta, imagen_pregunta, imagen_respuesta, categoria, subcategoria, dificultad, hash_pregunta, metadata, created_at, updated_at, anulada) VALUES ('b1bafd4b-87b0-4b96-af38-843b75993b39', 'e73c5e06-38ec-4353-9153-5bc14fc07a0f', 44, 'A Hrb= 09:00 nos encontramos situados al Sur verdadero de Isla Tarifa, cuando con nuestra aguja obtenemos demora de Punta Alcázar = 109°. El desvío es 3° (+). En ese momento damos rumbo para pasar a 2 millas al Norte verdadero de Punta Cires. El desvío de la aguja para este rumbo es 2°(+). Mantenemos rumbo y velocidad hasta que obtenemos demora de aguja a Punta Carnero= 270° y demora de aguja a Punta Europa= 295°. En dicho instante damos rumbo al extremo Sur del espigón del Puerto de Sotogrande [Fl(3)G.11s4M], en las inmediaciones del Río Guadiaro. Se pide calcular nuestra posición a Hrb= 13:00, sabiendo que nuestra velocidad de máquinas para todo el ejercicio es de 6 nudos y la declinación magnética en la zona para ese día es de 2°(W).', 'd', NULL, NULL, 'Carta de navegación', NULL, NULL, '6e2568eb1bb7e14a', '{"es_duplicada": true, "hash_explicacion": null, "convocatoria_original": "2025-06-RECREO"}', '2025-09-13 13:53:13.761608+00', '2025-09-13 13:53:13.761608+00', false);
