INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a28834c-7500-48e0-972e-ef372ec5dac5', '48b24b12-f71f-4480-96d6-425bcf2ac402', 'c', 'Se permite la descarga, si las aguas sucias han sido previamente desmenuzadas y desinfectadas y la velocidad de la embarcación es superior a 4 nudos.', false, '2025-09-13 13:53:09.597769+00');
