INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab0443ad-da2c-4587-aac3-a96e2599b4d6', '9932c003-e981-464a-896c-f976fbe21e2e', 'a', 'Dar máquina toda atrás cuando nos percatemos de su caída.', false, '2025-09-13 13:53:09.628733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9918984-a04e-4780-b774-1e2887786ed7', '9932c003-e981-464a-896c-f976fbe21e2e', 'b', 'Realizar la maniobra de Anderson o la maniobra de Beaufort.', false, '2025-09-13 13:53:09.628862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1bfe924-72af-4133-ab72-322d69cdbcca', '9932c003-e981-464a-896c-f976fbe21e2e', 'c', 'Realizar una maniobra de exploración en espiral cuadrada.', false, '2025-09-13 13:53:09.628991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb48ea91-4f01-441f-af67-121748edad9a', '9932c003-e981-464a-896c-f976fbe21e2e', 'd', 'Realizar la maniobra de Boutakow.', true, '2025-09-13 13:53:09.629123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42353a07-40f3-452d-8f63-71b78db0ef22', '8ac6e077-b6a6-44ef-9fa4-2bd3d764fd51', 'a', 'Es recomendable empujar por la popa en lugar de tirar por proa, ya que de esta forma se acortan las distancias de maniobra.', false, '2025-09-13 13:53:09.629393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f470c699-f80a-43a5-8ba7-85163df04697', '8ac6e077-b6a6-44ef-9fa4-2bd3d764fd51', 'b', 'Hay que intentar mantener una distancia entre el remolcador y el remolcado equivalente a 7 esloras de la embarcación remolcada.', false, '2025-09-13 13:53:09.629524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56f41837-e106-4a92-b7c8-07c36e8debdc', '8ac6e077-b6a6-44ef-9fa4-2bd3d764fd51', 'c', 'El remolcador y el remolcado deberán navegar lo más juntos posible, teniendo en cuenta que a menor velocidad deberá ser mayor la longitud del remolque.', false, '2025-09-13 13:53:09.629654+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac1ea4c5-2ced-42ed-bda8-69a8723a6beb', '8ac6e077-b6a6-44ef-9fa4-2bd3d764fd51', 'd', 'Ambas embarcaciones estarán abarloadas y unidas por los cabos oportunos.', true, '2025-09-13 13:53:09.629799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07ee0971-8531-4f6f-896a-e6cd8fd0ce5f', '735870ea-4ea7-442d-8dcf-170b7a45831e', 'a', 'Estar en cubierta, fuera de su embalaje y listas para su uso en caso de emergencia.', false, '2025-09-13 13:53:09.630086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93646036-ee75-48ef-afdc-d60842b37333', '735870ea-4ea7-442d-8dcf-170b7a45831e', 'b', 'Mantenerse dentro de su embalaje, salvo en las comprobaciones periódicas de funcionamiento.', false, '2025-09-13 13:53:09.630217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6892956f-e23a-42e1-94dc-0001458efe44', '735870ea-4ea7-442d-8dcf-170b7a45831e', 'c', 'Guardarse en lugar húmedo para evitar su encendido accidental y llevar siempre impresas sus instrucciones de uso.', false, '2025-09-13 13:53:09.630368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03301f3f-056c-4aae-8161-ad1e4b0d3c6e', '735870ea-4ea7-442d-8dcf-170b7a45831e', 'd', 'Guardarse en un recipiente completamente estanco, fácilmente accesible y llevar siempre impresas sus instrucciones de uso.', true, '2025-09-13 13:53:09.630517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a029e379-f091-4f76-af44-71dcd136434f', '23247a39-ada6-4bcb-90ab-1f252ceda637', 'a', 'Tener todos los objetos a bordo correctamente estibados y trincados.', false, '2025-09-13 13:53:09.630797+00');
