INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55b45d3c-455d-4b91-a7a9-878297f0e751', '42c62b26-8929-4204-9752-647d198b1b07', 'd', 'Mortero.', false, '2025-09-13 13:53:09.686637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1c7bee1-1bf2-4999-b118-d3d8031139e3', '55427cbd-1abb-46cf-9537-de7c9a96e8af', 'b', 'Hay que intentar mantener una distancia entre el remolcador y el remolcado equivalente a 7 esloras de la embarcación remolcada.', false, '2025-09-13 13:53:09.694481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80ade4fe-8611-4657-975b-1eddc3edf721', '55427cbd-1abb-46cf-9537-de7c9a96e8af', 'c', 'El remolcador y el remolcado deberán navegar lo más juntos posible, teniendo en cuenta que a menor velocidad deberá ser mayor la longitud del remolque.', false, '2025-09-13 13:53:09.694624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f356b3a-288f-4860-bb8e-8e7a9b78e234', '55427cbd-1abb-46cf-9537-de7c9a96e8af', 'd', 'Ambas embarcaciones estarán abarloadas y unidas por los cabos oportunos.', true, '2025-09-13 13:53:09.694758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3909ba4-d38d-4fca-aa7d-18dfccf5f9d2', '8ede7a7a-cdeb-49cd-a654-f4bc364a9fe2', 'a', 'Tener todos los objetos a bordo correctamente estibados y trincados.', false, '2025-09-13 13:53:09.695051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6390b70b-7c96-4bc7-ab2f-b3b3151bba2f', '8ede7a7a-cdeb-49cd-a654-f4bc364a9fe2', 'b', 'No permitir la existencia de carenas líquidas a bordo.', false, '2025-09-13 13:53:09.695186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc65c704-c3cf-4d29-949b-f782b8eb9d14', '8ede7a7a-cdeb-49cd-a654-f4bc364a9fe2', 'c', 'Mantener cerrados los grifos de fondo y cualquier conducto bajo la línea de flotación no necesario para la navegación.', true, '2025-09-13 13:53:09.695321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aefa20c3-cf4e-4cfd-b61d-ad45afd7713e', '8ede7a7a-cdeb-49cd-a654-f4bc364a9fe2', 'd', 'Aumentar si es posible el calado para incrementar la estabilidad.', false, '2025-09-13 13:53:09.695454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57c99a12-e1c1-433f-96ed-910b0308be07', 'b9bf563a-3fc7-4fea-9dad-ebd4c29b97f9', 'a', 'Estar en cubierta, fuera de su embalaje y listas para su uso en caso de emergencia.', false, '2025-09-13 13:53:09.695735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d8cdec8-454b-4c1e-bcf5-3129c758bd1c', 'b9bf563a-3fc7-4fea-9dad-ebd4c29b97f9', 'b', 'Mantenerse dentro de su embalaje, salvo en las comprobaciones periódicas de funcionamiento.', false, '2025-09-13 13:53:09.695891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12b66e73-7cc3-498e-85f4-b31a68c295db', 'b9bf563a-3fc7-4fea-9dad-ebd4c29b97f9', 'c', 'Guardarse en lugar húmedo para evitar su encendido accidental y llevar siempre impresas sus instrucciones de uso.', false, '2025-09-13 13:53:09.696026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0e1ac9e-0903-432c-b56e-3684e4817b6f', 'b9bf563a-3fc7-4fea-9dad-ebd4c29b97f9', 'd', 'Guardarse en un recipiente completamente estanco, fácilmente accesible y llevar siempre impresas sus instrucciones de uso.', true, '2025-09-13 13:53:09.696161+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22c4c4c4-d081-45e1-9e69-9124937fed68', 'c397e379-c2f5-4368-b1f1-7a280c012eac', 'a', 'Dar máquina toda atrás cuando nos percatemos de su caída.', false, '2025-09-13 13:53:09.696449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('deac169f-dfbb-4975-937a-e87b531f0f14', 'c397e379-c2f5-4368-b1f1-7a280c012eac', 'b', 'Realizar la maniobra de Anderson o la maniobra de Beaufort.', false, '2025-09-13 13:53:09.696588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5300b023-149f-43a9-b2e7-34c5d087b0e1', 'c397e379-c2f5-4368-b1f1-7a280c012eac', 'c', 'Realizar una maniobra de exploración en espiral cuadrada.', false, '2025-09-13 13:53:09.696728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9da50eb0-363d-42d1-a55f-5d1b2c71ff4a', 'c397e379-c2f5-4368-b1f1-7a280c012eac', 'd', 'Realizar la maniobra de Boutakow.', true, '2025-09-13 13:53:09.696879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b4a95c7-35af-415a-9614-8fe83967c029', '7ae496a7-462c-4ad9-b464-d48d88b25c6c', 'a', 'Espacio marino del Tinto y del Odiel.', true, '2025-09-13 13:53:09.697172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9045277-436a-4dbc-84c7-f87e6c357776', '7ae496a7-462c-4ad9-b464-d48d88b25c6c', 'b', 'Cabo de Creus.', false, '2025-09-13 13:53:09.697307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9514d399-65b7-4538-b155-a82a235ff3ed', '7ae496a7-462c-4ad9-b464-d48d88b25c6c', 'c', 'Isla Medes.', false, '2025-09-13 13:53:09.697582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ff132dd-98be-4eb3-9175-948b440de47f', '7ae496a7-462c-4ad9-b464-d48d88b25c6c', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:09.697717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3272271c-c1bb-458d-a397-0b76c8f3a979', '2fb46e9f-7807-49f9-9977-64742c9d30b3', 'a', 'Navegarán a una velocidad de seguridad que según la Regla 6 del RIPA se estima en 3 nudos.', false, '2025-09-13 13:53:09.698011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32f175fe-e9d5-4c79-a375-605bcb93b409', '2fb46e9f-7807-49f9-9977-64742c9d30b3', 'b', 'Evitarán interferir el tráfico normal de los mismos, no debiendo en ningún caso dar ocasión a que los buques que se encuentren navegando se vean obligados a maniobrarles.', true, '2025-09-13 13:53:09.698145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5c8dec8-a101-49fe-8f2b-4f23f67a523c', '2fb46e9f-7807-49f9-9977-64742c9d30b3', 'c', 'No podrán navegar por el interior de los puertos.', false, '2025-09-13 13:53:09.69828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56e816be-5fc7-4ebb-9e03-94cfcb39ebdc', '2fb46e9f-7807-49f9-9977-64742c9d30b3', 'd', 'Sólo están obligadas a navegar a velocidades que no formen olas que puedan producir situaciones peligrosas para embarcaciones de pequeño porte.', false, '2025-09-13 13:53:09.698417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34e7840d-e53e-4a7f-9ae0-ab901f8c45fc', '0c3f47cf-3382-4cd0-9e35-8d2a08662779', 'a', 'Dos conos superpuestos con los vértices hacia arriba.', true, '2025-09-13 13:53:09.698699+00');
