INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b1e8e96-bcf2-4846-81bc-6cbd92c296df', '00dc0107-b16d-4af0-9b4e-e81a88c8a153', 'c', 'Marcas de peligro aislado.', false, '2025-09-13 13:53:09.70192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89c57f34-5050-450b-bbf8-88bb244eb072', '9ed01aff-59c3-49ef-af0e-0696c612f3b9', 'a', 'Cuando un peligro de navegación, riesgo de abordaje o circunstancias especiales, incluidas las limitaciones de los buques interesados, que han de tomarse en consideración al interpretar y cumplir el Reglamento, hagan necesario apartarse del mismo para evitar un peligro inmediato.', true, '2025-09-13 13:53:09.70234+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('760866ac-59b0-4e31-995e-74b27257ca53', '9ed01aff-59c3-49ef-af0e-0696c612f3b9', 'b', 'Cuando un peligro de navegación, riesgo de abordaje o circunstancias especiales, incluidas las limitaciones de los buques interesados, que han de tomarse en consideración al interpretar y cumplir el Reglamento, hagan necesario apartarse del mismo para evitar un peligro potencial.', false, '2025-09-13 13:53:09.702474+00');
