INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f620486-502f-4760-8e27-a1bf845485ff', '9ed01aff-59c3-49ef-af0e-0696c612f3b9', 'd', 'Sólo para cumplir una regla especial establecida por la autoridad competente.', false, '2025-09-13 13:53:09.702744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7553907-9b59-48a7-904d-43199ef49c23', '066a684e-f2c7-43ad-9a51-2a8c88177b00', 'a', 'Una bandera cuadrada que tenga debajo de ella una bola.', true, '2025-09-13 13:53:09.703037+00');
