INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93aa3a89-c9b6-41f0-a90e-3e9f3dcec160', 'd289f6da-4418-4515-a89d-e571ac36264a', 'a', 'i) en la parte de proa, una luz roja todo horizonte o una bola; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz roja todo horizonte.', false, '2025-09-13 13:53:09.703708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d89e48e8-93ba-4899-a7cb-94b8ca3f337d', 'c0ad61d9-982b-4289-bcc3-1a52402c1303', 'a', 'De día.', true, '2025-09-13 13:53:09.739798+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b425081e-7d9d-4941-93c4-0a7a0a12028a', '00dc0107-b16d-4af0-9b4e-e81a88c8a153', 'd', 'Marcas cardinales.', false, '2025-09-13 13:53:09.702057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('677d88e8-562a-4b54-b6a2-329f113c237e', 'd289f6da-4418-4515-a89d-e571ac36264a', 'b', 'i) en la parte de proa, una luz roja todo horizonte o un cilindro; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz roja todo horizonte.', false, '2025-09-13 13:53:09.703848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('824a66bf-f55e-4667-aa4c-d8cf629a6d17', 'd289f6da-4418-4515-a89d-e571ac36264a', 'c', 'i) en la parte de proa, una luz blanca todo horizonte o una bola; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz blanca todo horizonte.', true, '2025-09-13 13:53:09.70399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5556bf54-3864-4045-a90c-4a442d6f6dfd', 'd289f6da-4418-4515-a89d-e571ac36264a', 'd', 'i) en la parte de proa, una luz blanca todo horizonte o una marca bicónica; y ii) en la popa, o cerca de ella, y a una altura superior a la de la luz prescrita en el apartado i), una luz blanca todo', false, '2025-09-13 13:53:09.704123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d901e131-a31c-4565-a4e8-f0ecf899fdf7', '95ddddca-4580-4f60-a9ad-a64f9d1de2c8', 'a', 'La derrota de un buque dedicado a la pesca.', true, '2025-09-13 13:53:09.704395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('539fc95c-66ec-48e0-b115-63513f6ceb92', '95ddddca-4580-4f60-a9ad-a64f9d1de2c8', 'b', 'La derrota de un buque de propulsión mecánica.', false, '2025-09-13 13:53:09.704526+00');
