INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3862f6c9-f603-431d-a708-308329ef75f0', '7ed25791-9a6d-4869-8d51-7987e0c729d8', 'a', 'El buque remolcador y el remolcado pueden apartarse, en todo caso, de mi derrota sin problemas.', false, '2025-09-13 13:53:09.705065+00');
