INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ce27596-8744-4c78-8bec-30e572d61f80', 'a2f006a5-ee0e-4c75-a34d-fa3ed6abeed2', 'a', 'Dar máquina toda atrás cuando nos percatemos de su caída.', false, '2025-09-13 13:53:09.7275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f6480bf-e22e-4555-9233-0619dc2e796e', 'a2f006a5-ee0e-4c75-a34d-fa3ed6abeed2', 'b', 'Realizar la maniobra de Anderson o la maniobra de Beaufort.', false, '2025-09-13 13:53:09.727752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e5a1242-43a3-4d62-8b32-86d5a334e694', 'a2f006a5-ee0e-4c75-a34d-fa3ed6abeed2', 'c', 'Realizar una maniobra de exploración en espiral cuadrada.', false, '2025-09-13 13:53:09.727898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23f4db48-adb7-4a7e-bd63-1d1a7435c72b', 'a2f006a5-ee0e-4c75-a34d-fa3ed6abeed2', 'd', 'Realizar la maniobra de Boutakow.', true, '2025-09-13 13:53:09.728032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('feb1fc4b-7eeb-4090-ac1f-72e0f8a1a338', 'abdbc458-9bbc-406f-8c1b-93010945df22', 'a', 'Es recomendable empujar por la popa en lugar de tirar por proa, ya que de esta forma se acortan las distancias de maniobra.', false, '2025-09-13 13:53:09.728316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aa80895-0dc9-4625-9e21-ac491f80c10c', 'abdbc458-9bbc-406f-8c1b-93010945df22', 'b', 'Hay que intentar mantener una distancia entre el remolcador y el remolcado equivalente a 7 esloras de la embarcación remolcada.', false, '2025-09-13 13:53:09.728451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6eebdf33-e424-4d19-ae51-26a8389d16e1', 'abdbc458-9bbc-406f-8c1b-93010945df22', 'c', 'El remolcador y el remolcado deberán navegar lo más juntos posible, teniendo en cuenta que a menor velocidad deberá ser mayor la longitud del remolque.', false, '2025-09-13 13:53:09.728587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('689e5f0e-f6df-4688-89b2-767c5e0bb1b3', 'abdbc458-9bbc-406f-8c1b-93010945df22', 'd', 'Ambas embarcaciones estarán abarloadas y unidas por los cabos oportunos.', true, '2025-09-13 13:53:09.728722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4c9dd95-4927-4ecd-b038-8d03f9320524', 'affba4f2-4376-4f50-96da-aac717c467b5', 'd', 'Cero Hidrográfico.', false, '2025-09-13 13:53:09.719808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58da97f5-0a46-4ba4-ba0c-6c7f4da972ad', '0d1f4807-9b9a-49e6-9e32-a9dfe59fb07c', 'a', 'Estar en cubierta, fuera de su embalaje y listas para su uso en caso de emergencia.', false, '2025-09-13 13:53:09.729037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2e080a2-c285-4100-b415-539bb4415210', '0d1f4807-9b9a-49e6-9e32-a9dfe59fb07c', 'b', 'Mantenerse dentro de su embalaje, salvo en las comprobaciones periódicas de funcionamiento.', false, '2025-09-13 13:53:09.729186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21865222-970d-4f34-9f7a-4b430deefd6c', '0d1f4807-9b9a-49e6-9e32-a9dfe59fb07c', 'c', 'Guardarse en lugar húmedo para evitar su encendido accidental y llevar siempre impresas sus instrucciones de uso.', false, '2025-09-13 13:53:09.729326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37af24f8-d36d-4265-bd2b-3d013c34651a', '0d1f4807-9b9a-49e6-9e32-a9dfe59fb07c', 'd', 'Guardarse en un recipiente completamente estanco, fácilmente accesible y llevar siempre impresas sus instrucciones de uso.', true, '2025-09-13 13:53:09.729462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15d3cb94-4236-4ab7-bac0-2c27a6aec001', '92c8d453-0a70-402b-b604-ce8031083739', 'a', 'Tener todos los objetos a bordo correctamente estibados y trincados.', false, '2025-09-13 13:53:09.729741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('596f116c-6fe6-4f4b-8c24-9ebbdb2aa3b2', '92c8d453-0a70-402b-b604-ce8031083739', 'b', 'No permitir la existencia de carenas líquidas a bordo.', false, '2025-09-13 13:53:09.729884+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3df836b5-d69a-4638-bf06-f213fee55006', '92c8d453-0a70-402b-b604-ce8031083739', 'c', 'Mantener cerrados los grifos de fondo y cualquier conducto bajo la línea de flotación no necesario para la navegación.', true, '2025-09-13 13:53:09.730017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b62878fa-416d-4f17-9d82-7066f496d1da', '92c8d453-0a70-402b-b604-ce8031083739', 'd', 'Aumentar si es posible el calado para incrementar la estabilidad.', false, '2025-09-13 13:53:09.73015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc9342c4-91f9-4f80-8e8d-8c1db5fbc3f4', '95c57b55-12ea-43ad-8b2a-89b7fac7b9a2', 'a', 'Espacio marino del Tinto y del Odiel.', true, '2025-09-13 13:53:09.730428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0712ce5-d860-4ea9-8ad4-81f3bee7677b', '95c57b55-12ea-43ad-8b2a-89b7fac7b9a2', 'b', 'Cabo de Creus.', false, '2025-09-13 13:53:09.730565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c974203-855d-41f9-9ac8-be6d0adc8b6f', '95c57b55-12ea-43ad-8b2a-89b7fac7b9a2', 'c', 'Isla Medes.', false, '2025-09-13 13:53:09.730696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e43c513-7098-495e-b564-26110c9bcd05', '95c57b55-12ea-43ad-8b2a-89b7fac7b9a2', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:09.730832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e44349b0-a98b-4827-bf26-f2b6dcecf958', 'f8b80933-773a-4e4d-bbc3-1b55798e0794', 'a', 'Navegarán a una velocidad de seguridad que según la Regla 6 del RIPA se estima en 3 nudos.', false, '2025-09-13 13:53:09.731194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5d54222-154f-4be7-9df8-9b26901942a2', 'f8b80933-773a-4e4d-bbc3-1b55798e0794', 'b', 'Evitarán interferir el tráfico normal de los mismos, no debiendo en ningún caso dar ocasión a que los buques que se encuentren navegando se vean obligados a maniobrarles.', true, '2025-09-13 13:53:09.731359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23316c32-908e-4872-90fa-ea8cdb2c23ed', 'f8b80933-773a-4e4d-bbc3-1b55798e0794', 'c', 'No podrán navegar por el interior de los puertos.', false, '2025-09-13 13:53:09.731526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5979cc9f-5d3c-44af-8af8-522586935005', 'f8b80933-773a-4e4d-bbc3-1b55798e0794', 'd', 'Sólo están obligadas a navegar a velocidades que no formen olas que puedan producir situaciones peligrosas para embarcaciones de pequeño porte.', false, '2025-09-13 13:53:09.731685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5c433fa-6aa3-4323-a334-5e52b2ffeeb2', '3acd9b8a-8f7f-441d-9f00-e5b9d356462c', 'a', 'Marcas de aguas navegables.', true, '2025-09-13 13:53:09.732043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d681eeb0-3946-4b46-a648-9d235071a042', '3acd9b8a-8f7f-441d-9f00-e5b9d356462c', 'b', 'Marcas especiales.', false, '2025-09-13 13:53:09.73221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47546133-b69b-4138-a785-b0dfe45b15eb', '3acd9b8a-8f7f-441d-9f00-e5b9d356462c', 'c', 'Marcas de peligro aislado.', false, '2025-09-13 13:53:09.73237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8c508c7-1b26-4943-a439-6b885182728c', '3acd9b8a-8f7f-441d-9f00-e5b9d356462c', 'd', 'Marcas cardinales.', false, '2025-09-13 13:53:09.732535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d57d684-76b8-4322-baaf-e36e002ac398', '0c686716-d2a5-43dc-9efc-f8f2078e836d', 'a', 'La marca de peligro aislado se coloca siempre sobre o próxima a un peligro rodeado por todas partes de aguas navegables, especificando siempre el tamaño del peligro.', false, '2025-09-13 13:53:09.732877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8778104-9081-4d5b-84cc-b5f6184bbb89', '0c686716-d2a5-43dc-9efc-f8f2078e836d', 'b', 'La marca de peligro aislado se coloca siempre sobre o próxima a un peligro rodeado por todas partes de aguas navegables, especificando siempre la distancia a la marca a la que se puede navegar', false, '2025-09-13 13:53:09.73304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fbf059a-b9a0-4ace-b759-a85e48131338', '0c686716-d2a5-43dc-9efc-f8f2078e836d', 'c', 'La marca de peligro aislado contendrá toda la información necesaria sobre dicho peligro, de modo que no será necesario consultar cartas ni publicaciones náuticas.', false, '2025-09-13 13:53:09.733297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27ffc92a-2421-41a2-843f-8c85ba648615', '0c686716-d2a5-43dc-9efc-f8f2078e836d', 'd', 'La marca de peligro aislado no puede especificar el tamaño del peligro y la distancia al mismo a la que se puede navegar con seguridad, por lo que el navegante deberá consultar la carta y las publicaciones náuticas.', true, '2025-09-13 13:53:09.733468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('817d8bfd-2835-42c9-8d21-a5af52a769f3', '324545c3-217b-45ec-9a44-1ba80bb20b58', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:09.733801+00');
