INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a7ceda7-dc5d-4662-a11f-9016aa700942', 'e3713800-c139-4d98-87e7-48bcbcf630c6', 'a', 'El buque remolcador y el remolcado pueden apartarse, en todo caso, de mi derrota sin problemas.', false, '2025-09-13 13:53:09.740502+00');
