INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15df365b-337d-4046-bd71-73c3ac3772b9', 'cabf3c34-b9c8-4330-bf0b-9fa39e6397fa', 'a', 'Es recomendable empujar por la popa en lugar de tirar por proa, ya que de esta forma se acortan las distancias de maniobra.', false, '2025-09-13 13:53:09.747694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('179a9fba-1626-4ca9-90c0-0ab1d2b203a5', 'cabf3c34-b9c8-4330-bf0b-9fa39e6397fa', 'b', 'Hay que intentar mantener una distancia entre el remolcador y el remolcado equivalente a 7 esloras de la embarcación remolcada.', false, '2025-09-13 13:53:09.747863+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4468aaf8-549b-4cd5-9c28-5952db9d4c56', 'cabf3c34-b9c8-4330-bf0b-9fa39e6397fa', 'c', 'El remolcador y el remolcado deberán navegar lo más juntos posible, teniendo en cuenta que a menor velocidad deberá ser mayor la longitud del remolque.', false, '2025-09-13 13:53:09.748005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3e34021-65ed-46b6-a3b2-f2e76350cf40', 'cabf3c34-b9c8-4330-bf0b-9fa39e6397fa', 'd', 'Ambas embarcaciones estarán abarloadas y unidas por los cabos oportunos.', true, '2025-09-13 13:53:09.748145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eccbb34c-b098-4917-8b4a-4ef290838c40', '57c8f6ee-d482-4411-9c0a-5f3c25ff95b2', 'a', 'Tener todos los objetos a bordo correctamente estibados y trincados.', false, '2025-09-13 13:53:09.748438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da9f09d8-d67b-4eef-bcc2-b3f04b8a2b46', '57c8f6ee-d482-4411-9c0a-5f3c25ff95b2', 'b', 'No permitir la existencia de carenas líquidas a bordo.', false, '2025-09-13 13:53:09.74857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e106731a-d6b1-45ad-a150-a74a16d34b74', '57c8f6ee-d482-4411-9c0a-5f3c25ff95b2', 'c', 'Mantener cerrados los grifos de fondo y cualquier conducto bajo la línea de flotación no necesario para la navegación.', true, '2025-09-13 13:53:09.748701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d66c390e-f13e-470d-96e4-29a7a85e04a6', '57c8f6ee-d482-4411-9c0a-5f3c25ff95b2', 'd', 'Aumentar si es posible el calado para incrementar la estabilidad.', false, '2025-09-13 13:53:09.748851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e62c22b-809e-4421-8a67-2e5c2c849228', '878bc9cc-2ae1-4088-98ac-cb61631f0f7f', 'a', 'Estar en cubierta, fuera de su embalaje y listas para su uso en caso de emergencia.', false, '2025-09-13 13:53:09.749267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ddbfc8d-564e-4eec-b94e-5d06ea32e3f5', '878bc9cc-2ae1-4088-98ac-cb61631f0f7f', 'b', 'Mantenerse dentro de su embalaje, salvo en las comprobaciones periódicas de funcionamiento.', false, '2025-09-13 13:53:09.749405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1229bb21-755e-4f7f-bd23-6c676d4ad451', '878bc9cc-2ae1-4088-98ac-cb61631f0f7f', 'c', 'Guardarse en lugar húmedo para evitar su encendido accidental y llevar siempre impresas sus instrucciones de uso.', false, '2025-09-13 13:53:09.749535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d0a6c5f-ccda-474d-93d1-e14822e898ba', '878bc9cc-2ae1-4088-98ac-cb61631f0f7f', 'd', 'Guardarse en un recipiente completamente estanco, fácilmente accesible y llevar siempre impresas sus instrucciones de uso.', true, '2025-09-13 13:53:09.749667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('492b1152-e426-4574-a1d1-7ac5789abe43', 'c2cee229-1a01-41f6-a875-308e5ea33570', 'a', 'Dar máquina toda atrás cuando nos percatemos de su caída.', false, '2025-09-13 13:53:09.749944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c11f9f1-36b3-4f01-b0f8-168f5c03618c', 'c2cee229-1a01-41f6-a875-308e5ea33570', 'b', 'Realizar la maniobra de Anderson o la maniobra de Beaufort.', false, '2025-09-13 13:53:09.750075+00');
