INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dff144b2-2803-472d-889b-96efeae1821a', '1a24d7c4-910f-45a0-a9a1-81e08f3afcfc', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:09.751114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ea157a4-9454-4c46-bf46-93a597f9eeb3', 'e0b7342c-389e-4021-852b-8dc348d4ef4f', 'a', 'Navegarán a una velocidad de seguridad que según la Regla 6 del RIPA se estima en 3 nudos.', false, '2025-09-13 13:53:09.751441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('739e7760-95b2-429d-a903-9a34ecce92a2', 'e0b7342c-389e-4021-852b-8dc348d4ef4f', 'b', 'Evitarán interferir el tráfico normal de los mismos, no debiendo en ningún caso dar ocasión a que los buques que se encuentren navegando se vean obligados a maniobrarles.', true, '2025-09-13 13:53:09.751594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a3759a8-2990-49da-89c3-d51f74535271', 'e0b7342c-389e-4021-852b-8dc348d4ef4f', 'c', 'No podrán navegar por el interior de los puertos.', false, '2025-09-13 13:53:09.751752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26530191-92de-43f5-8559-212b7f3c35f4', 'e0b7342c-389e-4021-852b-8dc348d4ef4f', 'd', 'Sólo están obligadas a navegar a velocidades que no formen olas que puedan producir situaciones peligrosas para embarcaciones de pequeño porte.', false, '2025-09-13 13:53:09.751917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01dceab2-724e-404d-8732-5cbd74d76114', '4dc604c1-7f31-43e5-92fa-5ad179d8cefb', 'a', 'Dos conos superpuestos con los vértices hacia arriba.', true, '2025-09-13 13:53:09.752244+00');
