INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fd8e179-b56e-4761-b206-a28bfc7d2ac1', 'cd35872b-9a89-4e8b-bd8c-da7098b82da0', 'a', 'La marca de peligro aislado se coloca siempre sobre o próxima a un peligro rodeado por todas partes de aguas navegables, especificando siempre el tamaño del peligro.', false, '2025-09-13 13:53:09.753691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72b00627-6d9f-42fe-aa6e-cb4782feb0dd', 'cd35872b-9a89-4e8b-bd8c-da7098b82da0', 'b', 'La marca de peligro aislado se coloca siempre sobre o próxima a un peligro rodeado por todas partes de aguas navegables, especificando siempre la distancia a la marca a la que se puede navegar', false, '2025-09-13 13:53:09.753827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89fa2aa5-ebec-4fe4-8f38-2ce6394bb37f', 'cd35872b-9a89-4e8b-bd8c-da7098b82da0', 'c', 'La marca de peligro aislado contendrá toda la información necesaria sobre dicho peligro, de modo que no será necesario consultar cartas ni publicaciones náuticas.', false, '2025-09-13 13:53:09.753957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('083f485e-4d77-48eb-9262-6f305ead6cec', 'cd35872b-9a89-4e8b-bd8c-da7098b82da0', 'd', 'La marca de peligro aislado no puede especificar el tamaño del peligro y la distancia al mismo a la que se puede navegar con seguridad, por lo que el navegante deberá consultar la carta y las publicaciones náuticas.', true, '2025-09-13 13:53:09.754087+00');
