INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40336e64-c4b9-405f-8d96-90ec21e97a81', '2ee6325d-b29f-4ff8-9e9b-97a2c711d68e', 'b', 'Cuando un peligro de navegación, riesgo de abordaje o circunstancias especiales, incluidas las limitaciones de los buques interesados, que han de tomarse en consideración al interpretar y cumplir el Reglamento, hagan necesario apartarse del mismo para evitar un peligro potencial.', false, '2025-09-13 13:53:09.755946+00');
