INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5464d62d-3684-46cd-acf7-5f65da923e42', '6b3563b7-bfcd-4344-80cc-f307cb3f515a', 'a', 'Línea que coincide aproximadamente con el meridiano de 180º y en la cual comienza primero cada día del calendario; el límite entre los husos horarios -12 y +12.', false, '2025-09-13 13:53:09.79656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5136a7f8-0901-4aa3-9408-032ba5d8aa5a', '6b3563b7-bfcd-4344-80cc-f307cb3f515a', 'b', 'Línea que coincide aproximadamente con el meridiano de 90º y en la cual comienza primero cada día del calendario; el límite entre los husos horarios -24 y +24.', false, '2025-09-13 13:53:09.796691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('453a3f04-5289-4b4b-8b28-37f73dae413e', '6b3563b7-bfcd-4344-80cc-f307cb3f515a', 'c', 'Línea que coincide aproximadamente con el meridiano de 180º y en la cual comienza primero cada día del calendario; el límite entre los husos horarios -24 y +24.', true, '2025-09-13 13:53:09.796821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb291f27-6ca8-4cbd-8779-b7dc43f65cbd', '6b3563b7-bfcd-4344-80cc-f307cb3f515a', 'd', 'Línea que coincide aproximadamente con el meridiano de 90º y en la cual comienza primero cada día del calendario; el límite entre los husos horarios -12 y +12.', false, '2025-09-13 13:53:09.796954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7d4d1ab-d13e-4d73-a58c-0ce8ead15b40', '19ceb869-a6b5-45ea-9c36-85ca82280ccb', 'a', 'Es el meridiano que se toma como origen de medida de la longitud, siendo Este en el sentido de las agujas del reloj visto desde el Norte, de 0º a 180º, y Oeste en sentido contrario. Tambien se le denomina Meridiano cero.', false, '2025-09-13 13:53:09.797227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff4495bd-f480-4c42-b983-a8a07f0b6711', '19ceb869-a6b5-45ea-9c36-85ca82280ccb', 'b', 'Es el plano vertical en el que se sitúa una aguja imantada, suspendida libremente en el campo magnético terrestre y que no sufre la influencia de otros campos magnéticos accidentales o', false, '2025-09-13 13:53:09.797359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40dbe476-2d81-4d36-a710-9d9b999e2cb5', '19ceb869-a6b5-45ea-9c36-85ca82280ccb', 'c', 'Es el meridiano que se toma como origen de medida de la longitud, siendo Oeste en el sentido de las agujas del reloj visto desde el Norte, de 0º a 180º, y Este en sentido contrario.', false, '2025-09-13 13:53:09.797489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9e37fd9-470e-4313-a56b-ae3c2472081f', '19ceb869-a6b5-45ea-9c36-85ca82280ccb', 'd', 'Es el meridiano que pasa por un lugar determinado y que sirve de referencia para la hora local en contraposición al meridiano de Greenwich. Tambien se le denomina Meridiano cero.', true, '2025-09-13 13:53:09.79762+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a39063de-2a4b-45d7-840e-7aae15071dca', 'f83bfb63-a2f8-418f-8c76-8c91e2ed7b34', 'a', 'No es posible si el sextante está recien calibrado.', false, '2025-09-13 13:53:09.797906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55ef3b14-371c-4af4-8c44-1b90af6a3378', 'f83bfb63-a2f8-418f-8c76-8c91e2ed7b34', 'b', 'Es posible únicamente por medio del sol.', false, '2025-09-13 13:53:09.798038+00');
