INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1bd8bad-d04f-4a24-98ef-bd2a5922af2e', 'f83bfb63-a2f8-418f-8c76-8c91e2ed7b34', 'd', 'Sí, por medio del sol, las estrellas, los planetas y el horizonte de la mar.', true, '2025-09-13 13:53:09.79831+00');
