INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('faa166de-f108-44c3-8362-c0d2180fa5f8', 'a318ce1f-e2c3-47a8-909c-1d116b144084', 'a', 'Debemos cortar la driza que une la balsa salvavidas con la embarcación antes de embarcar a bordo de esta última.', true, '2025-09-13 13:53:09.821747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bd00597-fbbb-4199-8833-11afeef3116e', 'a318ce1f-e2c3-47a8-909c-1d116b144084', 'b', 'Debe ser siempre la última opción. No debemos abandonar la embarcación sin evaluar que sería', false, '2025-09-13 13:53:09.821907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50a7246a-2b7d-486b-9e72-5a7d140d4105', 'a318ce1f-e2c3-47a8-909c-1d116b144084', 'c', 'Antes de abandonar la embarcación, debemos hacer una llamada de socorro y activar la radiobaliza EPIRB.', false, '2025-09-13 13:53:09.82206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf132909-c32b-4210-8423-6edeac36cab3', 'a318ce1f-e2c3-47a8-909c-1d116b144084', 'd', 'Amarrar a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:09.822197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5e1d935-196a-4910-ba7a-e864f4c9cdca', '94667f85-3954-4445-aa14-3322a51623cb', 'a', 'Transmite el MMSI de la embarcación.', false, '2025-09-13 13:53:09.822475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ef3c54a-6afa-4ec7-b363-904052b28293', '94667f85-3954-4445-aa14-3322a51623cb', 'b', 'Las antenas utilizadas para el AIS deben instalarse lo más cerca posible de las antenas de radar para su buen funcionamiento.', true, '2025-09-13 13:53:09.822607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca034052-e770-46c5-bbbc-2b3668ac509c', '94667f85-3954-4445-aa14-3322a51623cb', 'c', 'Opera en las frecuencias LF, HF y VHF.', false, '2025-09-13 13:53:09.822737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05f9f2a5-858b-403f-8b15-5fac7a8a58ba', '94667f85-3954-4445-aa14-3322a51623cb', 'd', 'Es un sistema independiente del GPS que nos permite localizar e identificar otras embarcaciones que también dispongan de AIS, pero no ver su derrota.', false, '2025-09-13 13:53:09.822892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a946e5bf-3dda-443a-8e2b-27d8fa4a96d7', 'a841e658-b691-4944-a116-a9ba3f946dc4', 'a', 'Aumenta la altura metacéntrica y el buque pierde estabilidad.', false, '2025-09-13 13:53:09.823175+00');
