INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf9ffecf-f31f-448a-9b92-691597dd5ee6', 'b99af715-3bf1-4f67-a2c6-b8c2645dceb6', 'd', 'Cuando se accione involuntariamente, sin que exista motivo para ello, el patrón deberá comunicarlo a la Administración Marítima.', false, '2025-09-13 13:53:09.825138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e075abdf-507c-4939-9786-9afa7bb1c291', '85fc42a0-14cc-467f-be05-e0835e3d8f57', 'a', 'De noche las bengalas de mano tienen un alcance visual superior al de un cohete con paracaídas.', false, '2025-09-13 13:53:09.825449+00');
