INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb314d43-cc74-4caa-b0ff-f209a0e57fea', '85fc42a0-14cc-467f-be05-e0835e3d8f57', 'c', 'La duración de un cohete con paracaídas es superior al de una bengala de mano.', false, '2025-09-13 13:53:09.825727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6134544d-6458-4261-86ed-76fd5d7fedc3', '85fc42a0-14cc-467f-be05-e0835e3d8f57', 'd', 'Las señales de socorro deben dispararse siempre hacia sotavento.', false, '2025-09-13 13:53:09.825864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3128947d-06c0-4d3c-98cd-dae884d2b454', '10aeecfd-3e26-43f5-b901-a104f796fb11', 'a', 'Dejar que el cable que envía el helicóptero toque antes el agua.', false, '2025-09-13 13:53:09.826148+00');
