INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c946023b-a98f-4a39-be7c-1c35f8961876', '10aeecfd-3e26-43f5-b901-a104f796fb11', 'c', 'A bordo, no amarrar el cable que envía el helicoptero a ningún lugar, debe mantenerse asido con', false, '2025-09-13 13:53:09.826418+00');
