INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72ead530-f272-466f-9887-2f4dbd7d3cc4', 'd27c3045-9cf5-49eb-89d4-26ff059b3462', 'a', 'Se puede instalar permanentemente en el bote salvavidas o funcionar al zafarse y flotar o sustentado por un náufrago.', false, '2025-09-13 13:53:09.827522+00');
