INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bc5ca10-c743-433b-9e20-975dfcf1464b', 'd27c3045-9cf5-49eb-89d4-26ff059b3462', 'c', 'Su señal solo es recibida por satélites, los barcos que están en las proximidades no saben que otro barco tiene un problema, hasta que se les comunica desde tierra.', false, '2025-09-13 13:53:09.827804+00');
