INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcb7e344-4fee-47aa-845f-7317720f4a11', 'e6f22fce-2f01-46b6-b716-1fea3fb5bc73', 'a', 'Nunca, ya que la declinación magnética depende del rumbo.', false, '2025-09-13 13:53:09.837405+00');
