INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3043c2bc-338e-485e-9986-7729ef01dd53', 'e6f22fce-2f01-46b6-b716-1fea3fb5bc73', 'c', 'Cuando sus desvíos de aguja coincidan.', true, '2025-09-13 13:53:09.837672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80cdff91-208a-423f-b161-00927df24d1d', 'e6f22fce-2f01-46b6-b716-1fea3fb5bc73', 'd', 'Sólo en el caso de que ambos buques naveguen con rumbo norte.', false, '2025-09-13 13:53:09.837803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e75a39b5-a349-41e8-9133-a1bc6c535e7a', 'deec31a1-43ee-4839-bfb6-e377505a84f4', 'a', 'El abatimiento es el efecto del viento que da como resultado siempre el rumbo efectivo.', false, '2025-09-13 13:53:09.838071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adfd40eb-c535-41f7-a565-932e83c8cf25', 'deec31a1-43ee-4839-bfb6-e377505a84f4', 'b', 'El efecto de la dirección del viento y su intensidad horaria se denomina deriva.', true, '2025-09-13 13:53:09.838201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d035545-12e8-4cff-abbf-195c8756f356', 'deec31a1-43ee-4839-bfb6-e377505a84f4', 'c', 'La derrota resultante debida a la intensidad horaria de la corriente es el rumbo de superficie.', false, '2025-09-13 13:53:09.838336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('162f6ec1-5af3-421d-913b-0f52caf54e0f', 'deec31a1-43ee-4839-bfb6-e377505a84f4', 'd', 'El ángulo que forma la dirección de la proa con la estela del buque se llama abatimiento.', false, '2025-09-13 13:53:09.838465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1edeefb8-0e82-4974-997c-53f157019b5e', '568a3532-d0c1-4a9e-99d7-9f25897821bf', 'a', 'Son avisos de carácter urgente que se radian en frecuencias que figuran en el Libro de Radioseñales previo aviso en Canal 16.', true, '2025-09-13 13:53:09.838883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03956277-c5b0-46d4-b485-fc9e9518a537', '568a3532-d0c1-4a9e-99d7-9f25897821bf', 'b', 'Son avisos importantes que se radian en frecuencia de trabajo sin aviso previo en Canal 16.', false, '2025-09-13 13:53:09.839017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8eed103-8bbd-411a-ab26-076f222ed376', '568a3532-d0c1-4a9e-99d7-9f25897821bf', 'c', 'Son avisos de largo alcance que se reciben en el IHM que los remite una vez traducidos y ordenados a la estación Radionaval en Madrid con aviso posterior en Canal 16.', false, '2025-09-13 13:53:09.839146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bd2a065-cdad-4cc7-8b76-c5c9f6854a4d', '568a3532-d0c1-4a9e-99d7-9f25897821bf', 'd', 'Son avisos costeros de emisión programada previo aviso en Canal 16.', false, '2025-09-13 13:53:09.839277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09011f7a-c6ef-41f9-a183-4ee2f6fd71e0', 'f5364f7a-51ab-41ea-8446-37a4b3b9de8d', 'a', 'La diferencia entre el rumbo verdadero y rumbo de compás.', true, '2025-09-13 13:53:09.83956+00');
