INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f341a739-b153-4821-b7ca-6d9c1110c4dd', '8f599266-c2e2-4785-a12d-84913f5867a1', 'a', 'Debemos cortar la driza que une la balsa salvavidas con la embarcación antes de embarcar a bordo de esta última.', false, '2025-09-13 13:53:09.852475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21a6271f-574f-4b32-a5f3-b9794ec37840', '8f599266-c2e2-4785-a12d-84913f5867a1', 'b', 'Debe ser siempre la última opción. No debemos abandonar la embarcación sin evaluar que sería', false, '2025-09-13 13:53:09.852605+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c89f48a-dfea-4f02-92d3-0f8df8ef519b', '8f599266-c2e2-4785-a12d-84913f5867a1', 'c', 'Antes de abandonar la embarcación, debemos hacer una llamada de socorro y activar la radiobaliza EPIRB.', true, '2025-09-13 13:53:09.852734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('616b187e-79d9-4497-9133-a778f37de935', '8f599266-c2e2-4785-a12d-84913f5867a1', 'd', 'Amarrar a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:09.852876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dff1ede-729c-4b3b-8bc2-2549ca70dd74', '3fd25117-b25c-4714-87f9-12f5cc67d599', 'a', 'Hay que respetar los plazos de las revisiones (batería y zafa hidrostática).', true, '2025-09-13 13:53:09.853149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('590a2be7-9873-4df9-89cd-7d418243dc00', '3fd25117-b25c-4714-87f9-12f5cc67d599', 'b', 'Activarla de vez en cuando para comprobar su buen funcionamiento.', false, '2025-09-13 13:53:09.853284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7afb7f7-5740-4659-b7df-1c6c506ff0f7', '3fd25117-b25c-4714-87f9-12f5cc67d599', 'c', 'Comprobar el estado de la batería antes de zarpar.', false, '2025-09-13 13:53:09.853421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9bb1df7-f44e-4fa3-8f1e-d9fbaabfcf44', '3fd25117-b25c-4714-87f9-12f5cc67d599', 'd', 'Cuando se accione involuntariamente, sin que exista motivo para ello, el patrón deberá comunicarlo a la Administración Marítima.', false, '2025-09-13 13:53:09.853551+00');
