INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec8d699e-912c-403d-8011-5bd031169eff', '845f421a-db9c-445d-8fb5-d131e171169b', 'b', 'Las antenas utilizadas para el AIS deben instalarse lo más cerca posible de las antenas de radar para su buen funcionamiento.', false, '2025-09-13 13:53:09.85614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b76667e4-c900-4203-bf73-38e1fbca3145', '845f421a-db9c-445d-8fb5-d131e171169b', 'c', 'Opera en las frecuencias LF, HF y VHF.', false, '2025-09-13 13:53:09.856273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53c6e976-39d2-461b-bc72-081a43929573', '845f421a-db9c-445d-8fb5-d131e171169b', 'd', 'Es un sistema independiente del GPS que nos permite localizar e identificar otras embarcaciones que también dispongan de AIS, pero no ver su derrota.', true, '2025-09-13 13:53:09.8564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3259a6c-72d5-4bb0-abd1-3edb052585cb', '93366e60-4039-4563-a09a-803406eea8f4', 'a', 'Se puede instalar permanentemente en el bote salvavidas o funcionar al zafarse y flotar o sustentado por un náufrago.', false, '2025-09-13 13:53:09.85667+00');
