INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0155236b-9389-44ce-aa56-ca7d0dfb3574', 'cf2e7dd6-7742-414d-be8f-a81ad23ab892', 'a', 'La velocidad del viento es cero.', false, '2025-09-13 13:53:09.865957+00');
