INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d68f5517-442c-4ed8-95c6-778fe687e28c', '597d2a1c-2e6c-4097-bbb7-4ea4b08dae0c', 'a', 'El abatimiento es el efecto del viento que da como resultado siempre el rumbo efectivo.', false, '2025-09-13 13:53:09.866728+00');
