INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7b71edc-3746-4536-b6a1-6712bdf6cbf3', '7eed221e-a3f4-4618-bad1-8b4641afe15d', 'a', 'Es lo mismo que manejar la rueda del timón.', false, '2025-09-13 13:53:09.897407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd440d8b-b559-4ff4-a2d4-6b845e8862cd', '7eed221e-a3f4-4618-bad1-8b4641afe15d', 'b', 'Si se mete la caña a estribor, la pala del timón cae a babor y viceversa.', true, '2025-09-13 13:53:09.897537+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3148f28a-fa8a-4dd3-b808-ca5bc3928237', '7eed221e-a3f4-4618-bad1-8b4641afe15d', 'c', 'La pala cae a la misma banda de accionamiento de la rueda del timón.', false, '2025-09-13 13:53:09.897667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca45da0f-94ce-4a0c-bf07-98a5e4e3c889', '7eed221e-a3f4-4618-bad1-8b4641afe15d', 'd', 'Si se mete la caña a babor, la pala del timón cae a babor y viceversa.', false, '2025-09-13 13:53:09.897824+00');
