INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7db2d70-8d08-4de8-a43b-359c63e1fe84', 'a7ac20c8-c5f4-40fc-af18-fa6931d85c1d', 'a', 'En las hemorragias arteriales la sangre mana de la herida de forma continua y en las hemorragias venosas hay que aplicar torniquetes por encima de la herida.', false, '2025-09-13 13:53:09.898786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('132e880d-fc92-4585-90c8-46c72ecffe5f', 'a7ac20c8-c5f4-40fc-af18-fa6931d85c1d', 'b', 'El síntoma más claro de las quemaduras de tercer grado es la aparición de vesículas o ampollas llenas de líquido.', false, '2025-09-13 13:53:09.898918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e015f68-cf60-4b68-8eb2-f00701af1f50', 'a7ac20c8-c5f4-40fc-af18-fa6931d85c1d', 'c', 'En caso de insolación hay que mojar la cabeza del afectado aplicando compresas de agua fría en frente y nuca, e hidratarlo dándole pequeños sorbos de agua fresca.', true, '2025-09-13 13:53:09.899047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ee0859a-7e87-431f-8bb4-fcddbbbe19a5', 'a7ac20c8-c5f4-40fc-af18-fa6931d85c1d', 'd', 'El Centro Radio-Médico Español (CRME) depende del Instituto Social de Medicina Preventiva y en caso de necesidad, siempre deberemos contactar con él por teléfono.', false, '2025-09-13 13:53:09.899177+00');
