INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee17ff31-757c-4572-b70d-07c16257a444', '973d72ae-91aa-4425-a6a3-cb831bfb762a', 'a', 'Pieza sólida de madera o metal que, afirmada en cubierta, se utiliza para el amarre de cabos.', true, '2025-09-13 13:53:09.913209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('836c295d-0a33-4813-b6bf-89a8f2941d05', '973d72ae-91aa-4425-a6a3-cb831bfb762a', 'b', 'Cuerpo ligero y flotante que se mantiene sujeto al fondo mediante un lastre y se utiliza para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:09.913376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a7b2abe-475d-4f58-9a57-edc513784c92', '973d72ae-91aa-4425-a6a3-cb831bfb762a', 'c', 'Rueda de madera o metal para direccionar los cabos de amarre desde el muelle a los elementos de amarre en cubierta.', false, '2025-09-13 13:53:09.913522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ba8c2dc-e0b7-4d67-98ca-0500203d5b6c', '973d72ae-91aa-4425-a6a3-cb831bfb762a', 'd', 'Piezas de hierro fundido fijadas a los muelles para redireccionar las amarras.', false, '2025-09-13 13:53:09.913662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59d61955-a4e2-4ba2-bdcc-515d7e9228bd', '5f17659f-da8d-4325-9849-2d6d0410b2e9', 'a', 'En la maniobra de fondeo hay que elegir el fondeadero y el orinque en función, entre otros aspectos, de la sonda y naturaleza del fondo.', false, '2025-09-13 13:53:09.91401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85ec3dde-07df-4666-9ceb-1e4d0a335f44', '5f17659f-da8d-4325-9849-2d6d0410b2e9', 'b', 'Se denomina fondeo a la gira, a la maniobra de fondeo con un ancla por popa, en la que se deja filar la cadena unida al ancla, quedando esta como elemento único de fijación.', false, '2025-09-13 13:53:09.914161+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee874d39-73c2-40f0-b13a-70780c0584c5', '5f17659f-da8d-4325-9849-2d6d0410b2e9', 'c', 'Al cabo que se amarra por un chicote a una boya y por el otro al ancla, se le denomina tenedero.', false, '2025-09-13 13:53:09.914303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c171a16-1353-455d-8ccc-b49ad2092eb4', '5f17659f-da8d-4325-9849-2d6d0410b2e9', 'd', 'Se dice que un barco que está fondeado garrea, cuando el ancla no ha agarrado bien al fondo, se desliza y el barco se desplaza.', true, '2025-09-13 13:53:09.914436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd13ce21-77d5-44c6-8965-09b36896d5f0', 'f081a448-063e-4141-89a2-e6b90082e71c', 'a', 'Atravesándose a la mar.', false, '2025-09-13 13:53:09.914723+00');
