INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32bb540c-c561-4447-a083-e28489b8c6c2', 'd4dbe18a-cf0a-45bb-b4fe-3e7eda92872a', 'c', 'La correspondiente al número máximo de personas autorizadas a bordo.', true, '2025-09-13 13:53:09.915671+00');
