INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('950bf1a9-fff1-43b2-951f-8a052fbe6932', '12c782c8-30e6-4352-a05a-90e5e2a62fec', 'a', 'Cambiaremos el rumbo hacia puerto para atracar en él inmediatamente.', false, '2025-09-13 13:53:09.916261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfb4b9cf-115d-47e5-b50d-fa939689f66d', '12c782c8-30e6-4352-a05a-90e5e2a62fec', 'b', 'Aumentaremos la velocidad para salir de la zona de baja visibilidad cuanto antes.', false, '2025-09-13 13:53:09.916412+00');
