INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f8682d4-66a7-42ed-8f7c-4fe6d3c97fe0', 'e552b014-cc55-4043-827f-2c32e54cd0ea', 'a', 'Que las aguas navegables se encuentran en la dirección contraria.', false, '2025-09-13 13:53:09.92118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27f26932-1d18-4e25-977e-d1c4ee9520fc', 'e552b014-cc55-4043-827f-2c32e54cd0ea', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:09.92131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f2d5829-30d8-4994-a929-8407da8988f4', 'e552b014-cc55-4043-827f-2c32e54cd0ea', 'c', 'La ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:09.921573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd67dc2c-9d3a-4ca5-a395-b075007955f2', 'e552b014-cc55-4043-827f-2c32e54cd0ea', 'd', 'Que las aguas son navegables alrededor de la marca.', true, '2025-09-13 13:53:09.921706+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1dec8e9b-7e32-44a2-a78b-b47bc5cb932a', '94464614-9540-4341-aa24-8a8d6ddb042c', 'a', 'Negro con una o varias anchas bandas horizontales rojas .', true, '2025-09-13 13:53:09.922004+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac8699c0-62ba-4e75-901f-90e8f444a28e', '94464614-9540-4341-aa24-8a8d6ddb042c', 'b', 'Amarillo con una franja ancha negra horizontal.', false, '2025-09-13 13:53:09.92214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09b1b613-b033-48ba-a860-2e40d5471797', '94464614-9540-4341-aa24-8a8d6ddb042c', 'c', 'Rojo con una o varias anchas bandas verticales blancas.', false, '2025-09-13 13:53:09.922273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d731ab50-5b41-4fdb-bc75-2e55f086a283', '1655a4af-6dd2-43c2-87a4-94ff2633e56b', 'a', 'Tendrán obligación de llevar los dispositivos de señales acústicas prescritos en la Regla 33.a.', false, '2025-09-13 13:53:09.922686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9ad0448-1b25-4e56-b07e-cc08b21b6262', '1040bbaa-7b71-420e-b0da-ba122f798f47', 'd', 'Borda.', false, '2025-09-13 13:53:09.912896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad28749f-741b-4ebb-8bcd-b7e0521e4af9', '94464614-9540-4341-aa24-8a8d6ddb042c', 'd', 'Amarillo en toda su superficie.', false, '2025-09-13 13:53:09.922405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c40bcc9f-4cd9-4074-8bbd-0e1b864c7cd4', '1655a4af-6dd2-43c2-87a4-94ff2633e56b', 'b', 'Irán dotados de un pito y de una campana siempre.', false, '2025-09-13 13:53:09.92282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94901f48-0644-455b-8aca-f88703d341ce', '1655a4af-6dd2-43c2-87a4-94ff2633e56b', 'c', 'Irán dotados de un pito, de una campana y un gong.', false, '2025-09-13 13:53:09.922963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5937ae3f-11cc-4736-85ab-7dee8f689aa7', '1655a4af-6dd2-43c2-87a4-94ff2633e56b', 'd', 'Si no llevan los dispositivos de señales acústicas prescritos en la Regla 33, deberán ir dotados de otros medios para hacer las señales acústicas eficaces.', true, '2025-09-13 13:53:09.923098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('870913ad-4eb7-4635-9da1-a7fbd9d62482', 'd1b48886-7967-4a2c-be7d-49d236591961', 'a', 'La conducta de los buques en condiciones de visibilidad reducida es de aplicación a los buques que estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', false, '2025-09-13 13:53:09.923373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('697bb40f-8e1e-4814-a096-5fc680ce6fd2', 'd1b48886-7967-4a2c-be7d-49d236591961', 'b', 'Cuando haya riesgo de abordaje, todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, o que no pueda evitar una situación de aproximación excesiva con otro buque situado a proa de su través, deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:09.923505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7515f7d1-6a3a-4216-97ee-7ba7a0898a4e', 'd1b48886-7967-4a2c-be7d-49d236591961', 'c', 'Todos los buques navegarán a una velocidad de navegación constante atendiendo a las condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:09.923638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2110112d-965e-4aac-9ce8-8452c9e7cbc1', 'd1b48886-7967-4a2c-be7d-49d236591961', 'd', 'Todo buque que detecte por cualquier medio la presencia de otro buque, deteminará si se está creando una situación de aproximación excesiva y/o un riesgo de abordaje.', false, '2025-09-13 13:53:09.923771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab1840ca-6137-4991-ba5f-b89a71d1e9f8', '2bfd2299-3e43-4332-808c-4ae26b9ff906', 'a', 'Una luz roja de centelleos todo horizonte.', false, '2025-09-13 13:53:09.924058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15be8b7b-1eda-4ecb-8b3a-71660baa1e1e', '2bfd2299-3e43-4332-808c-4ae26b9ff906', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:09.924189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b62b8f7-c8a6-4c7a-9fdb-4cf2e125808b', '2bfd2299-3e43-4332-808c-4ae26b9ff906', 'c', 'Luces de tope.', false, '2025-09-13 13:53:09.924327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0c90b13-394f-4e02-bbe1-edeea0d6c164', '2bfd2299-3e43-4332-808c-4ae26b9ff906', 'd', 'Luces de remolque.', false, '2025-09-13 13:53:09.92446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fda1628-f75e-423d-9df8-04cc2ff6000b', '4864277d-a370-40ad-9478-4ac4a42c0f90', 'a', 'Cumplirán las especificaciones del anexo I de este Reglamento.', true, '2025-09-13 13:53:09.924882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('744a4200-6398-4127-a90e-399316ffda63', '4864277d-a370-40ad-9478-4ac4a42c0f90', 'b', 'Cumplirán las especificaciones del anexo I de este Reglamento, solo en cuanto a su posición.', false, '2025-09-13 13:53:09.925095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35da929b-629e-4e03-a299-4272381d7742', '4864277d-a370-40ad-9478-4ac4a42c0f90', 'c', 'Cumplirán las especificaciones del anexo I de este Reglamento, solo en cuanto a sus características técnicas.', false, '2025-09-13 13:53:09.925228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23102243-c379-413e-8787-2f5fe5e3bdb9', '4864277d-a370-40ad-9478-4ac4a42c0f90', 'd', 'No hay especificaciones concretas, pero se debe verificar su correcto funcionamiento.', false, '2025-09-13 13:53:09.925495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27b1a177-3f34-4ecd-85cc-5ce14561fac3', '7ef2aadf-724b-4297-b196-32b48915ffd3', 'a', 'Un buque con propulsión mecánica.', false, '2025-09-13 13:53:09.925783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebed85f8-23cd-45aa-b14e-5c3228039bc2', '7ef2aadf-724b-4297-b196-32b48915ffd3', 'b', 'Un hidroavión.', false, '2025-09-13 13:53:09.925913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b91c1f5c-e75e-4186-a413-2f287e705046', '7ef2aadf-724b-4297-b196-32b48915ffd3', 'c', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:09.926051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44135752-3746-471e-9e8e-541078d7e37d', '7ef2aadf-724b-4297-b196-32b48915ffd3', 'd', 'Un buque con plena capacidad de maniobra.', false, '2025-09-13 13:53:09.926185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5404959-4130-4ddb-a859-53a34e2e17d2', '7cc5235d-5514-4cb9-a260-61d85e1193be', 'a', 'Una marca consistente en dos conos unidos por sus vértices en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:09.926487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f5d04b7-3bdf-45b0-8797-2c5ceb716705', '7cc5235d-5514-4cb9-a260-61d85e1193be', 'b', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:09.926627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0af90d37-1bcd-4417-97b5-f91baf22f432', '7cc5235d-5514-4cb9-a260-61d85e1193be', 'c', 'Una marca cónica con el vértice hacia abajo.', true, '2025-09-13 13:53:09.926767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d57fd353-1673-43ad-9aea-ed36eca1d94d', '7cc5235d-5514-4cb9-a260-61d85e1193be', 'd', 'Una marca consistente en dos conos unidos por sus bases en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:09.926898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a062e3c-ab32-45bf-890c-8b9156a55482', '4b93ddda-35ef-4b04-a22d-5ec53bf5559f', 'a', 'Con independencia de su zona de navegación.', false, '2025-09-13 13:53:09.927174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92dc20fa-c046-4b47-aeb3-366c76ccdaa5', '4b93ddda-35ef-4b04-a22d-5ec53bf5559f', 'b', 'En alta mar y en todas las aguas marítimas que tengan comunicación con ella y sean navegables por los buques de navegación marítima.', true, '2025-09-13 13:53:09.927306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('790e7795-379f-41b6-89d5-ff43d5e60294', '4b93ddda-35ef-4b04-a22d-5ec53bf5559f', 'c', 'En alta mar y en todas las aguas marítimas que tengan comunicación con ella, sean o no navegables por los buques de navegación marítima.', false, '2025-09-13 13:53:09.927438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e718581-4ff8-4003-94b7-f82921ad0f01', '4b93ddda-35ef-4b04-a22d-5ec53bf5559f', 'd', 'En alta mar y en todas las aguas en las que España ejerce jurisdicción o derechos soberanos.', false, '2025-09-13 13:53:09.927569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d401ff43-5837-416e-beae-b1cd6f9a597c', '01ef962f-c8d0-4fca-b69a-769fc2bc5e8c', 'a', 'Todo buque que por una circunstancia excepcional tiene reducida su capacidad de maniobra.', false, '2025-09-13 13:53:09.927858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('681cb002-aca6-4406-927e-ae44012af92a', '01ef962f-c8d0-4fca-b69a-769fc2bc5e8c', 'b', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', true, '2025-09-13 13:53:09.928002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac7e1037-285f-42b0-8ba0-e5319c7a8b41', '01ef962f-c8d0-4fca-b69a-769fc2bc5e8c', 'c', 'Todo buque que esté fondeado.', false, '2025-09-13 13:53:09.928138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f15e374d-8749-496a-80bf-9f982bba5617', '01ef962f-c8d0-4fca-b69a-769fc2bc5e8c', 'd', 'Todo buque que esté varado.', false, '2025-09-13 13:53:09.928272+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac039d19-7239-478b-b73b-605408ce4b35', '5c2a152c-890f-4d2c-88d3-df3f618fcc7b', 'a', 'Corresponde a un buque que está remolcando a otro.', false, '2025-09-13 13:53:09.928547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48a1aed3-2492-4d6d-9f30-de69f7cd94c3', '5c2a152c-890f-4d2c-88d3-df3f618fcc7b', 'b', 'Indica peligro y necesidad de ayuda.', true, '2025-09-13 13:53:09.928678+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('837a734e-0304-43f1-bc56-dbe2169165b4', '5c2a152c-890f-4d2c-88d3-df3f618fcc7b', 'c', 'Corresponde a un buque dedicado a la pesca de arrastre.', false, '2025-09-13 13:53:09.928809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a699535-689e-42f5-b11b-5beda9569c21', '5c2a152c-890f-4d2c-88d3-df3f618fcc7b', 'd', 'Corresponde a un buque que está tendiendo cables submarinos.', false, '2025-09-13 13:53:09.928941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27505763-3a67-4090-a078-e6d38c9e68c3', '83deed3c-1453-455f-8312-9d13bdfd7348', 'a', 'Ciando despacio.', false, '2025-09-13 13:53:09.930794+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5360e181-f354-4706-b058-2867aa15937e', '83deed3c-1453-455f-8312-9d13bdfd7348', 'b', 'A favor del viento o de la corriente.', false, '2025-09-13 13:53:09.930929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16e9aaf0-b8b6-486c-9eaf-dc6c17d43a7e', '83deed3c-1453-455f-8312-9d13bdfd7348', 'c', 'En contra del viento o de la corriente.', true, '2025-09-13 13:53:09.931091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74ec4236-e329-4cca-bf2c-161405aa1348', 'dfdbe966-1f2b-45b8-890b-a99f5fb4185a', 'a', 'Usar los botes de humo.', false, '2025-09-13 13:53:09.931519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70c8fd39-0918-4985-a6e2-c63c0b91dfc7', 'dfdbe966-1f2b-45b8-890b-a99f5fb4185a', 'b', 'Usar las bengalas.', true, '2025-09-13 13:53:09.931656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31055193-23cb-4dea-9d22-5e04cf9f5818', 'dfdbe966-1f2b-45b8-890b-a99f5fb4185a', 'c', 'Lanzar un cohete provisto de paracaídas para iluminar el lugar.', false, '2025-09-13 13:53:09.931796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6696b35-f4d1-4cfd-a9d5-86298d275fb7', 'dfdbe966-1f2b-45b8-890b-a99f5fb4185a', 'd', 'Hacer una llamada de urgencia PAN-PAN.', false, '2025-09-13 13:53:09.931937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eacf1c47-6c33-4961-b069-4b98c6504a7c', '83deed3c-1453-455f-8312-9d13bdfd7348', 'd', 'No influye el viento ni la corriente.', false, '2025-09-13 13:53:09.931224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f951641-006d-43e0-b448-05fcbeeca01c', '39df9b09-d8ac-4fef-b54c-29401f8afd5a', 'a', 'Disco de goma, fieltro o lona atravesado por un eje roscado con un brazo articulado transversal.', false, '2025-09-13 13:53:09.932213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22e17004-7113-4794-afc5-5a1a694313b2', '39df9b09-d8ac-4fef-b54c-29401f8afd5a', 'b', 'Orificio más pequeño que un imbornal por donde se produce una vía de agua.', false, '2025-09-13 13:53:09.932352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bea651d2-0ce9-4ff1-a08e-800cca2f3dcc', '39df9b09-d8ac-4fef-b54c-29401f8afd5a', 'c', 'Cuña cónica de madera para tapar vías de agua por orificios de forma circular.', true, '2025-09-13 13:53:09.93248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c65fe9b0-8076-41c9-86a2-d14b0a646295', '39df9b09-d8ac-4fef-b54c-29401f8afd5a', 'd', 'Tablero de contrachapado marino sellado al casco con silicona para tapar vías de agua.', false, '2025-09-13 13:53:09.932609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e579de1-6a6b-4bf3-b5e9-68086d7b3119', '81d6439a-1941-451f-8210-ba7af1053a36', 'a', 'Localizar inmediatamente el origen de la vía de agua, ya que puede perder la embarcación.', false, '2025-09-13 13:53:09.932886+00');
