INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('679c0cb6-9384-433c-aa8f-6ed36790c86f', 'ac40a446-9556-48e3-b563-e605a4d2ff8d', 'b', 'En la parte de proa, una luz verde todo horizonte o una bola.', false, '2025-09-13 13:53:09.958132+00');
