INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c571d27d-5b2e-4761-9859-9b34ed9b01ce', 'efd0504a-d960-49d8-9244-b23b673e75e8', 'a', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea superior a 200 metros.', true, '2025-09-13 13:53:09.958664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd1bd093-6e2b-4dd2-b604-a728a824edbe', 'efd0504a-d960-49d8-9244-b23b673e75e8', 'b', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea inferior a 100 metros.', false, '2025-09-13 13:53:09.958802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7167eb8-51b8-4e9a-91ee-c396dbe0c56e', 'efd0504a-d960-49d8-9244-b23b673e75e8', 'c', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea superior a 150 metros.', false, '2025-09-13 13:53:09.958932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('423e38e2-e4d7-4981-b562-7b0bc83a806f', 'efd0504a-d960-49d8-9244-b23b673e75e8', 'd', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea inferior a 150 metros.', false, '2025-09-13 13:53:09.959073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('970e6b80-94d6-4a78-bc61-21911849ed4f', 'a55e926c-a16b-4543-b081-1919cdf10bf7', 'a', 'Ser sustituidos por cualquier otro equipo del mismo tamaño.', false, '2025-09-13 13:53:09.959362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c94d8229-3f81-4904-b1d9-e507f708de75', 'a55e926c-a16b-4543-b081-1919cdf10bf7', 'b', 'Ser sustituidos por otro equipo que tenga las mismas características acústicas respectivamente, a condición de que siempre sea posible hacer manualmente las señales acústicas prescritas.', true, '2025-09-13 13:53:09.959494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17630f32-280d-45c3-9a0f-3c8c1c20ba11', 'a55e926c-a16b-4543-b081-1919cdf10bf7', 'c', 'Ser sustituidos por otro equipo que tenga las mismas características acústicas respectivamente, a condición de que tenga programadas las señales prescritas y funcione como único modo en automático, evitando su posible manipulación.', false, '2025-09-13 13:53:09.959635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39d8f50e-7bce-4fe3-a2c0-fc2aef0739b3', 'a55e926c-a16b-4543-b081-1919cdf10bf7', 'd', 'Ser intercambiados el uno por el otro indistintamente.', false, '2025-09-13 13:53:09.959765+00');
