INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51b621d2-2394-4068-8bbb-e1e54c9a9962', '1db15132-e119-4aca-b169-54e89aa870af', 'b', 'Si se mete la caña a estribor, la pala del timón cae a babor y viceversa.', true, '2025-09-13 13:53:09.963765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('948369c0-5b33-4a7d-a33a-c61432421642', '5a634073-a4a5-4be7-bdfa-60842c9727ea', 'b', 'Una marca cardinal Norte.', false, '2025-09-13 13:53:09.975357+00');
