INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca659d9f-66a2-4158-be63-e7d8c48c5e9a', 'bacabb4f-d107-4efe-a6d7-16ad5e56a59a', 'a', 'Cuando ha quedado varado en seco.', false, '2025-09-13 13:53:09.964303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('240a6b65-8aa4-4e49-800d-852ca99c7b00', 'bacabb4f-d107-4efe-a6d7-16ad5e56a59a', 'b', 'Cuando ha quedado varado en fondo fangoso.', true, '2025-09-13 13:53:09.964461+00');
