INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8199d722-89f7-4500-b28e-ddf67443dab2', '1c4710c4-0584-4369-bfd1-bd55ee6c3201', 'a', 'En las hemorragias arteriales la sangre mana de la herida de forma continua y en las hemorragias venosas hay que aplicar torniquetes por encima de la herida.', false, '2025-09-13 13:53:09.965058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a364d713-6c18-497b-bde3-2b14e4e426bc', '1c4710c4-0584-4369-bfd1-bd55ee6c3201', 'b', 'El síntoma más claro de las quemaduras de tercer grado es la aparición de vesículas o ampollas llenas de líquido.', false, '2025-09-13 13:53:09.965194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40386357-3030-4fe2-bc36-4c1bd17d6d0b', '1c4710c4-0584-4369-bfd1-bd55ee6c3201', 'c', 'En caso de insolación hay que mojar la cabeza del afectado aplicando compresas de agua fría en frente y nuca, e hidratarlo dándole pequeños sorbos de agua fresca.', true, '2025-09-13 13:53:09.965327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a80cd60-65a8-4c93-9b25-9d3fbd3d2c65', '1c4710c4-0584-4369-bfd1-bd55ee6c3201', 'd', 'El Centro Radio-Médico Español (CRME) depende del Instituto Social de Medicina Preventiva y en caso de necesidad, siempre deberemos contactar con él por teléfono.', false, '2025-09-13 13:53:09.965463+00');
