INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41176b05-64e5-435a-9afd-173a377a6326', 'c67e1cf0-676d-4354-b2c9-12707142b1ad', 'c', 'El tubo dentro del cual gira el eje del timón.', false, '2025-09-13 13:53:09.978408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1f96f8a-b12d-4658-9d3f-a8a0bb9c2e43', 'c67e1cf0-676d-4354-b2c9-12707142b1ad', 'd', 'La abertura que se abre a un lado de la roda para dar paso a la cadena del ancla. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:09.978543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d99b6bc9-855c-4b0a-bb98-99a69ad089b2', '1267bd63-5221-41ca-bf49-33dd1e26978c', 'a', 'Pieza sólida de madera o metal que, afirmada en cubierta, se utiliza para el amarre de cabos.', true, '2025-09-13 13:53:09.978817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('034b31a0-cff6-426d-b832-8f31858a80b4', '1267bd63-5221-41ca-bf49-33dd1e26978c', 'b', 'Cuerpo ligero y flotante que se mantiene sujeto al fondo mediante un lastre y se utiliza para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:09.97895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e07a9986-031a-4951-84bc-768d711ae14b', '1267bd63-5221-41ca-bf49-33dd1e26978c', 'c', 'Rueda de madera o metal para direccionar los cabos de amarre desde el muelle a los elementos de amarre en cubierta.', false, '2025-09-13 13:53:09.979081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('014a26b2-890c-45fb-a2a9-55d5569ccd08', '1267bd63-5221-41ca-bf49-33dd1e26978c', 'd', 'Piezas de hierro fundido fijadas a los muelles para redireccionar las amarras.', false, '2025-09-13 13:53:09.979211+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2775dc3-4035-41f6-a57b-2811ce792d0d', '1f404e51-bea7-43e0-b185-0f59aad3d7d8', 'a', 'En la maniobra de fondeo hay que elegir el fondeadero y el orinque en función, entre otros aspectos, de la sonda y naturaleza del fondo.', false, '2025-09-13 13:53:09.979631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('019d1c71-cae6-4c20-b6be-6f60392b9e03', '1f404e51-bea7-43e0-b185-0f59aad3d7d8', 'b', 'Se denomina fondeo a la gira, a la maniobra de fondeo con un ancla por popa, en la que se deja filar la cadena unida al ancla, quedando esta como elemento único de fijación.', false, '2025-09-13 13:53:09.979791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91e47c0b-a29a-4400-be21-3175c0964b29', '1f404e51-bea7-43e0-b185-0f59aad3d7d8', 'c', 'Al cabo que se amarra por un chicote a una boya y por el otro al ancla, se le denomina tenedero.', false, '2025-09-13 13:53:09.979945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d57a31b2-0e13-42e0-876e-947749a3be25', '1f404e51-bea7-43e0-b185-0f59aad3d7d8', 'd', 'Se dice que un barco que está fondeado garrea, cuando el ancla no ha agarrado bien al fondo, se desliza y el barco se desplaza.', true, '2025-09-13 13:53:09.980083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2513a30-a2ef-4236-a29a-6df2e908ce38', 'd374813a-ebe6-4d88-969b-74ffadd8a419', 'a', 'Atravesándose a la mar.', false, '2025-09-13 13:53:09.980374+00');
