INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf69e24b-352e-4527-ac01-c69c95ca463c', 'd374813a-ebe6-4d88-969b-74ffadd8a419', 'c', 'Aumentando la velocidad.', false, '2025-09-13 13:53:09.980656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b48af0d-b757-4d7c-b33e-208443ae4b58', 'd374813a-ebe6-4d88-969b-74ffadd8a419', 'd', 'Largando cabos por popa.', false, '2025-09-13 13:53:09.980801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5376dfa7-7d86-499f-8c4f-6ff3d4fc9aca', 'd5310fc8-3a02-4e98-ab6a-6a03882264d2', 'a', 'El temporal se “capeará” recibiendo el mar por la amura.', false, '2025-09-13 13:53:09.981095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f230ec9d-2698-4a9b-ae2b-30a4654e0a8b', 'd5310fc8-3a02-4e98-ab6a-6a03882264d2', 'b', '“Correr el temporal” es recibir la mar por popa avanzando con el oleaje y el viento.', false, '2025-09-13 13:53:09.981237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1b92d52-8dff-4c0a-8cf2-e5dfd7b3af6a', 'd5310fc8-3a02-4e98-ab6a-6a03882264d2', 'c', 'Una maniobra válida para hacer frente a la mala mar es echar el ancla de capa o flotante.', false, '2025-09-13 13:53:09.981373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c183eaab-c0c8-40c8-bf1c-463c19f2146f', 'd5310fc8-3a02-4e98-ab6a-6a03882264d2', 'd', '“A son de mar” es el término referido a las maniobras de timón para hacer frente a la mala mar.', true, '2025-09-13 13:53:09.981503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4026ff5f-f25d-42f0-bd44-32df1c7d4352', '5d092b56-fb21-4e86-a85a-5404627c9160', 'a', 'Cambiaremos el rumbo hacia puerto para atracar en él inmediatamente.', false, '2025-09-13 13:53:09.981789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcde63ff-8d07-4c8e-92a7-95c01d3de557', '5d092b56-fb21-4e86-a85a-5404627c9160', 'b', 'Aumentaremos la velocidad para salir de la zona de baja visibilidad cuanto antes.', false, '2025-09-13 13:53:09.981936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af5ad7bc-ac0c-4f8b-a067-251027bc81f0', '5d092b56-fb21-4e86-a85a-5404627c9160', 'c', 'Reduciremos la velocidad sin detenerse y modificaremos el rumbo a babor o estribor hasta encontrar una referencia.', false, '2025-09-13 13:53:09.982071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27e9056c-2fd2-488e-99b7-5c0061dfbd73', '5d092b56-fb21-4e86-a85a-5404627c9160', 'd', 'Reduciremos la velocidad, y si es preciso pararemos la embarcación.', true, '2025-09-13 13:53:09.982204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cef23eb0-4592-41c0-a68f-f716fa199328', 'a27ec86d-140b-47e3-92ed-2ccaf699ddfd', 'a', '4 personas.', false, '2025-09-13 13:53:09.98248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e804c60b-ba05-4224-9889-0a8bab8ae7f9', 'a27ec86d-140b-47e3-92ed-2ccaf699ddfd', 'b', '6 personas.', false, '2025-09-13 13:53:09.982611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76a63a9f-21d7-4dc8-b6ce-c61b4523de8d', 'a27ec86d-140b-47e3-92ed-2ccaf699ddfd', 'c', 'La correspondiente al número máximo de personas autorizadas a bordo.', true, '2025-09-13 13:53:09.982741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f9d860c-4ac1-4b4f-8de7-53eac4036566', 'a27ec86d-140b-47e3-92ed-2ccaf699ddfd', 'd', 'La indicada en las normas ISO o SOLAS correspondiente según la zona de navegación.', false, '2025-09-13 13:53:09.982882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79df8e20-5620-47ef-a1f3-4bcc320a5074', '534c2960-d120-4b65-8ffc-08815f4c9c9e', 'a', 'Las embarcaciones de eslora superior a 6 metros, registradas en la lista 6ª.', false, '2025-09-13 13:53:09.983156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('282585e5-b463-45e5-a1e5-30c85aff7fe4', '534c2960-d120-4b65-8ffc-08815f4c9c9e', 'b', 'Las embarcaciones de eslora superior a 6 metros, registradas en la lista 7ª.', false, '2025-09-13 13:53:09.983292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6db2630-4a8c-41b0-9abb-c7fbcd46ef1d', '534c2960-d120-4b65-8ffc-08815f4c9c9e', 'c', 'Las embarcaciones de eslora inferior a 6 metros, registradas en la lista 6ª.', false, '2025-09-13 13:53:09.983422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8517f306-11b8-43d5-9495-1b58282e785c', '534c2960-d120-4b65-8ffc-08815f4c9c9e', 'd', 'Las embarcaciones de eslora inferior a 6 metros, registradas en la lista 7ª.', true, '2025-09-13 13:53:09.983554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b45dfb69-d5c3-4225-a7fd-4287dbb7f6a2', '2d9c6f50-d380-4cd5-b8ea-d0b7783e7274', 'a', '10.', false, '2025-09-13 13:53:09.983828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51253167-cd51-453f-98c3-a71751a97092', '2d9c6f50-d380-4cd5-b8ea-d0b7783e7274', 'b', '9.', true, '2025-09-13 13:53:09.983959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67e046dd-1bcf-45bf-aa24-8e7b5f08d281', '2d9c6f50-d380-4cd5-b8ea-d0b7783e7274', 'c', '8.', false, '2025-09-13 13:53:09.98409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b940deef-91b2-4b4b-a246-4b14ee3ed81f', '2d9c6f50-d380-4cd5-b8ea-d0b7783e7274', 'd', '7.', false, '2025-09-13 13:53:09.984219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf791ae7-59d7-418d-906c-b51333f17f77', '5626ae33-7152-49e1-b25a-6eecb932dc6e', 'a', 'La entrada de un canal, la aproximación a un puerto o estuario o un punto de recalada.', false, '2025-09-13 13:53:09.984488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc12606f-6cbe-4d34-a715-e6226ee84116', '5626ae33-7152-49e1-b25a-6eecb932dc6e', 'c', 'El lado por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:09.984908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b904c7c9-8dc0-41fc-8743-7f65016e4595', '5626ae33-7152-49e1-b25a-6eecb932dc6e', 'd', 'Los lados de babor y estribor de la derrota que debe seguirse, asociadas a un sentido convencional del balizamiento.', false, '2025-09-13 13:53:09.985064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1c0a6f9-d948-4575-969a-31bd41cb3dc3', '5626ae33-7152-49e1-b25a-6eecb932dc6e', 'b', 'Zonas de separación de tráfico donde el balizamiento convencional del canal puede prestarse a confusión.', true, '2025-09-13 13:53:09.984745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef4c5124-5154-4105-9b90-ebe7d1cb0cf0', '2f8167e2-7e1f-4dde-9770-4635dae8e6be', 'a', 'Dos conos negros superpuestos con los vértices hacia arriba.', false, '2025-09-13 13:53:09.985349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('632b950d-4bb9-4339-897f-f778e70a92bd', '2f8167e2-7e1f-4dde-9770-4635dae8e6be', 'b', 'Dos conos negros superpuestos opuestos por los vértices.', true, '2025-09-13 13:53:09.985489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c650bda-d765-441c-ab11-5ccb71ed58c5', '2f8167e2-7e1f-4dde-9770-4635dae8e6be', 'c', 'Dos conos negros superpuestos opuestos por la base.', false, '2025-09-13 13:53:09.985621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('241fe031-e14c-4d9a-ac92-8a77a396cf1e', '2f8167e2-7e1f-4dde-9770-4635dae8e6be', 'd', 'Dos bolas negras superpuestas.', false, '2025-09-13 13:53:09.98575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4abecda0-7c15-43d3-884b-570d3b83d067', '539ff650-d3cc-496b-9cb8-94ed6c7b14f7', 'a', 'Negro con una o varias anchas bandas horizontales rojas .', true, '2025-09-13 13:53:09.986051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b53f9ee1-d118-4791-9f1e-4c640e667be9', '539ff650-d3cc-496b-9cb8-94ed6c7b14f7', 'b', 'Amarillo con una franja ancha negra horizontal.', false, '2025-09-13 13:53:09.98619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db161755-8516-4260-a0b7-9c57c3c09ef5', '539ff650-d3cc-496b-9cb8-94ed6c7b14f7', 'c', 'Rojo con una o varias anchas bandas verticales blancas.', false, '2025-09-13 13:53:09.98632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6b67470-971e-4aa1-9bad-7d48ad156355', '539ff650-d3cc-496b-9cb8-94ed6c7b14f7', 'd', 'Amarillo en toda su superficie.', false, '2025-09-13 13:53:09.986448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a35051dc-c5ef-4a37-b4a6-4ca53da900a7', '166eb096-aa6b-4a32-973c-c655ca61ca80', 'a', 'La dejaremos por babor.', true, '2025-09-13 13:53:09.986723+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4873568c-b9d8-4374-963a-3ae652797def', '166eb096-aa6b-4a32-973c-c655ca61ca80', 'b', 'La dejaremos por estribor.', false, '2025-09-13 13:53:09.986851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff293bba-0f49-4f1d-bd29-14b47f3e4d03', '166eb096-aa6b-4a32-973c-c655ca61ca80', 'c', 'Significa aguas peligrosas.', false, '2025-09-13 13:53:09.986978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49754d01-2510-4250-a890-35847bbb8b54', '166eb096-aa6b-4a32-973c-c655ca61ca80', 'd', 'Se puede dejar por cualquier banda.', false, '2025-09-13 13:53:09.987105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('990840cb-4bf4-4c89-bb12-bc7c67f0aec6', '75832195-6d19-4e5b-ab17-e5f4e4246707', 'a', 'Que las aguas navegables se encuentran en la dirección contraria.', false, '2025-09-13 13:53:09.987375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91cce8f2-c6b9-4490-ad2f-fc7d009ea591', '75832195-6d19-4e5b-ab17-e5f4e4246707', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:09.987502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8121367f-a805-4696-8e2d-6c1afc07ae9d', '75832195-6d19-4e5b-ab17-e5f4e4246707', 'c', 'La ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:09.987756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbe3167c-46e0-42a5-95e6-7702629b0b78', '14e28af5-2fb8-4877-88f3-fe3edb09d908', 'a', 'Una marca consistente en dos conos unidos por sus vértices en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:09.988167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe0cea0b-b94a-4d0f-8815-ba99695586a9', '14e28af5-2fb8-4877-88f3-fe3edb09d908', 'b', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:09.988318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09ea6e85-d09c-4b1d-89eb-5e9bf567ac1a', '14e28af5-2fb8-4877-88f3-fe3edb09d908', 'c', 'Una marca cónica con el vértice hacia abajo.', true, '2025-09-13 13:53:09.988454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca255146-5084-4711-afd7-8a4e04b4681d', '14e28af5-2fb8-4877-88f3-fe3edb09d908', 'd', 'Una marca consistente en dos conos unidos por sus bases en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:09.988588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83449cdb-8ee4-41e7-a714-f8da4521bb3c', '191d81ab-5adf-48b7-9f72-a6b37b19c949', 'a', 'La conducta de los buques en condiciones de visibilidad reducida es de aplicación a los buques que estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', false, '2025-09-13 13:53:09.988877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('213bb093-d4c6-4b3c-8f62-acd20d94e800', '191d81ab-5adf-48b7-9f72-a6b37b19c949', 'b', 'Cuando haya riesgo de abordaje, todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, o que no pueda evitar una situación de aproximación excesiva con otro buque situado a proa de su través, deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:09.989013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c22303c-bb44-4754-af28-e592c37eca4a', '191d81ab-5adf-48b7-9f72-a6b37b19c949', 'c', 'Todos los buques navegarán a una velocidad de navegación constante atendiendo a las condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:09.989152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d58c6b5-3137-45a9-a17d-96cb05136c96', '191d81ab-5adf-48b7-9f72-a6b37b19c949', 'd', 'Todo buque que detecte por cualquier medio la presencia de otro buque, deteminará si se está creando una situación de aproximación excesiva y/o un riesgo de abordaje.', false, '2025-09-13 13:53:09.989285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d62583a1-45bf-4892-aaca-aa9c0ce17dd4', '1dd3db0c-12d4-455a-aa86-4986b2300f7c', 'a', 'Tendrán obligación de llevar los dispositivos de señales acústicas prescritos en la Regla 33.a.', false, '2025-09-13 13:53:09.989582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e1dfddb-d4bc-40de-a287-46ecc82adfad', '1dd3db0c-12d4-455a-aa86-4986b2300f7c', 'b', 'Irán dotados de un pito y de una campana siempre.', false, '2025-09-13 13:53:09.989731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32ee6dff-e7b4-4ee0-86b6-ede969aa3b02', '1dd3db0c-12d4-455a-aa86-4986b2300f7c', 'c', 'Irán dotados de un pito, de una campana y un gong.', false, '2025-09-13 13:53:09.989875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4d684e4-f28f-4bad-9ba2-677353aad771', '1dd3db0c-12d4-455a-aa86-4986b2300f7c', 'd', 'Si no llevan los dispositivos de señales acústicas prescritos en la Regla 33, deberán ir dotados de otros medios para hacer las señales acústicas eficaces.', true, '2025-09-13 13:53:09.99001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('924dad53-3b0d-4ba3-ae3a-7a3eae712856', '184ea3a3-91b7-4bc1-b08a-cbad181d6c43', 'a', 'Todo buque que por una circunstancia excepcional tiene reducida su capacidad de maniobra.', false, '2025-09-13 13:53:09.990293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01fb23db-e766-4768-9677-2d84a38f17c3', '184ea3a3-91b7-4bc1-b08a-cbad181d6c43', 'b', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', true, '2025-09-13 13:53:09.990431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99500f2d-d4be-472e-8684-7b19bf3eb1c9', '184ea3a3-91b7-4bc1-b08a-cbad181d6c43', 'c', 'Todo buque que esté fondeado.', false, '2025-09-13 13:53:09.990566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d86c45f9-a462-4136-94cb-e1038b09658d', '184ea3a3-91b7-4bc1-b08a-cbad181d6c43', 'd', 'Todo buque que esté varado.', false, '2025-09-13 13:53:09.9907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc1ab10b-3822-47ca-82ee-5eaae42ddc82', 'aa04e2a6-e277-4d5b-92ee-34d394470b83', 'a', 'Una luz roja de centelleos todo horizonte.', false, '2025-09-13 13:53:09.990979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9743d13c-7edc-4c2a-b384-611fcf9521f8', 'aa04e2a6-e277-4d5b-92ee-34d394470b83', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:09.991116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de2db273-da2b-431b-9a93-e5324d2128b9', 'aa04e2a6-e277-4d5b-92ee-34d394470b83', 'c', 'Luces de tope.', false, '2025-09-13 13:53:09.991249+00');
