INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66db7e88-f425-4b7e-b712-8a2ebfff0270', '0ffef68d-99c2-4a24-a5fc-a076ab370980', 'c', 'Al cabo que se amarra por un chicote a una boya y por el otro al ancla, se le denomina tenedero.', false, '2025-09-13 13:53:10.038767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('229b7d97-2c87-4dd0-b7ea-05f275adbe62', '0ffef68d-99c2-4a24-a5fc-a076ab370980', 'd', 'Se dice que un barco que está fondeado garrea, cuando el ancla no ha agarrado bien al fondo, se desliza y el barco se desplaza.', true, '2025-09-13 13:53:10.038899+00');
