INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05ac4980-6b27-4aa0-b363-9f02ea64239a', 'e7d8562a-26e8-4992-a8f3-5b1fdce2a102', 'a', '4 personas.', false, '2025-09-13 13:53:10.039874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9427d705-bd28-4fbc-a0a7-868f58f01eea', 'e7d8562a-26e8-4992-a8f3-5b1fdce2a102', 'b', '6 personas.', false, '2025-09-13 13:53:10.04001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ff8ee61-8ae5-4f48-8b43-7ca203fb04ae', 'e7d8562a-26e8-4992-a8f3-5b1fdce2a102', 'c', 'La correspondiente al número máximo de personas autorizadas a bordo.', true, '2025-09-13 13:53:10.040144+00');
