INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa1cfad3-f639-4186-8c9d-75f0703d5ce4', '83d15f79-8e07-4d5d-bb04-28dc48e196af', 'a', 'l=35º50,0´N; L=005º48,6´W.', false, '2025-09-13 13:53:10.032696+00');
