INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9283de1-8282-4461-bea1-aff89c7089fb', '83d15f79-8e07-4d5d-bb04-28dc48e196af', 'c', 'l=35º54,0´N; L=005º53,6´W.', false, '2025-09-13 13:53:10.032956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('102858f9-051b-48c5-932f-0c4f82e0127b', '4517d1b7-f6ec-433e-98d5-977cae109513', 'b', 'Los valores del desvío, una vez calculados para los diferentes rumbos, permanecen inalterables en el tiempo.', false, '2025-09-13 13:53:10.030809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75a5ce2d-61a3-45ec-bf33-a7e21e897767', '144996ec-9a9b-4854-84dc-c2d87234c1b0', 'a', 'Cambiaremos el rumbo hacia puerto para atracar en él inmediatamente.', false, '2025-09-13 13:53:10.040693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa7573f3-c443-4268-9b71-f2271e057a2a', '144996ec-9a9b-4854-84dc-c2d87234c1b0', 'b', 'Aumentaremos la velocidad para salir de la zona de baja visibilidad cuanto antes.', false, '2025-09-13 13:53:10.040872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('747c1c19-8aa0-4ed4-9c8f-319fc77e0984', '144996ec-9a9b-4854-84dc-c2d87234c1b0', 'c', 'Reduciremos la velocidad sin detenerse y modificaremos el rumbo a babor o estribor hasta encontrar una referencia.', false, '2025-09-13 13:53:10.041007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('132bd150-869c-4781-855b-0178d83100dd', '144996ec-9a9b-4854-84dc-c2d87234c1b0', 'd', 'Reduciremos la velocidad, y si es preciso pararemos la embarcación.', true, '2025-09-13 13:53:10.04114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e03c1d2f-c57a-49be-a5d7-9d7d96356614', '24dea4b7-77d0-41f3-8311-9b24b73a7304', 'a', 'El temporal se “capeará” recibiendo el mar por la amura.', false, '2025-09-13 13:53:10.04142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1a3b490-5ff3-4d71-b6f8-060bf25acfea', '24dea4b7-77d0-41f3-8311-9b24b73a7304', 'b', '“Correr el temporal” es recibir la mar por popa avanzando con el oleaje y el viento.', false, '2025-09-13 13:53:10.041554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a424beee-94fa-4a4e-a76f-65abf5a8be03', '24dea4b7-77d0-41f3-8311-9b24b73a7304', 'c', 'Una maniobra válida para hacer frente a la mala mar es echar el ancla de capa o flotante.', false, '2025-09-13 13:53:10.041687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9eb73c1-8860-460e-a8d8-4d38e0bbf370', '24dea4b7-77d0-41f3-8311-9b24b73a7304', 'd', '“A son de mar” es el término referido a las maniobras de timón para hacer frente a la mala mar.', true, '2025-09-13 13:53:10.041821+00');
