INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4efdee11-8a12-45e5-9972-7d2d2115f303', 'a1f70542-2d08-4e48-a386-ab644d33f57e', 'a', 'La dejaremos por babor.', true, '2025-09-13 13:53:10.044158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd5eed14-51fa-47b3-925d-2c500c26809a', 'a1f70542-2d08-4e48-a386-ab644d33f57e', 'b', 'La dejaremos por estribor.', false, '2025-09-13 13:53:10.044289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('856a0d57-0ad6-4801-b4df-7531398891ef', 'a1f70542-2d08-4e48-a386-ab644d33f57e', 'c', 'Significa aguas peligrosas.', false, '2025-09-13 13:53:10.044419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93ea5807-2ab1-4843-a71a-32bbc0180fa0', 'a1f70542-2d08-4e48-a386-ab644d33f57e', 'd', 'Se puede dejar por cualquier banda.', false, '2025-09-13 13:53:10.04455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd5a4027-d53c-426c-9bf7-646b76e58072', 'd8de0709-2c2f-41cd-a112-1db0e24edf25', 'a', 'La entrada de un canal, la aproximación a un puerto o estuario o un punto de recalada.', false, '2025-09-13 13:53:10.044952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77602fbf-ec8a-45f1-bfcf-b47681ada982', 'd8de0709-2c2f-41cd-a112-1db0e24edf25', 'b', 'Zonas de separación de tráfico donde el balizamiento convencional del canal puede prestarse a', true, '2025-09-13 13:53:10.045081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1c1ee66-91ed-433c-add3-73fe86db9bcd', 'd8de0709-2c2f-41cd-a112-1db0e24edf25', 'c', 'El lado por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:10.045216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f10ed44a-025f-4760-bbbe-c7e3d0c7f808', 'd8de0709-2c2f-41cd-a112-1db0e24edf25', 'd', 'Los lados de babor y estribor de la derrota que debe seguirse, asociadas a un sentido convencional del balizamiento.', false, '2025-09-13 13:53:10.045347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b12b324a-0eba-4be7-aaa9-2a5925267b17', '91980d7e-e460-4c8e-880e-eb3b2d2fb10a', 'a', 'Que las aguas navegables se encuentran en la dirección contraria.', false, '2025-09-13 13:53:10.045616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c05f21e4-b6b1-497e-b606-3835150fe37a', '91980d7e-e460-4c8e-880e-eb3b2d2fb10a', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:10.045748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c214fdc8-c419-4d2e-9c94-13e27173f645', '91980d7e-e460-4c8e-880e-eb3b2d2fb10a', 'c', 'La ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:10.045898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51da0cc2-b636-40ab-ac9e-6809911c92a2', '91980d7e-e460-4c8e-880e-eb3b2d2fb10a', 'd', 'Que las aguas son navegables alrededor de la marca.', true, '2025-09-13 13:53:10.046028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a08a9c04-4a52-4378-8a30-bcced59f6803', '3e40d7c7-8acb-4d84-8dbe-d24ba9ffbe6b', 'a', 'Negro con una o varias anchas bandas horizontales rojas .', true, '2025-09-13 13:53:10.046296+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b162ef30-c6c2-4524-a1d1-b0462ae1224f', '3e40d7c7-8acb-4d84-8dbe-d24ba9ffbe6b', 'b', 'Amarillo con una franja ancha negra horizontal.', false, '2025-09-13 13:53:10.046428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48e4e804-82b0-4024-8680-1f46e367125e', '3e40d7c7-8acb-4d84-8dbe-d24ba9ffbe6b', 'c', 'Rojo con una o varias anchas bandas verticales blancas.', false, '2025-09-13 13:53:10.046559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac8ce2e1-7aa1-4cf5-b576-62860b66c01c', '3e40d7c7-8acb-4d84-8dbe-d24ba9ffbe6b', 'd', 'Amarillo en toda su superficie. Reglamento (RIPA).', false, '2025-09-13 13:53:10.046688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c516920a-81df-4b4d-8e0f-26ca939bf159', 'd624cb67-a731-4101-9941-0e681ea30bbd', 'a', 'Tendrán obligación de llevar los dispositivos de señales acústicas prescritos en la Regla 33.a.', false, '2025-09-13 13:53:10.047024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4ae41a3-b30e-4326-bf90-7ad31ac4ac04', 'd624cb67-a731-4101-9941-0e681ea30bbd', 'b', 'Irán dotados de un pito y de una campana siempre.', false, '2025-09-13 13:53:10.047163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3045c40f-a4dd-4c77-83fd-296c44fa32d8', 'd624cb67-a731-4101-9941-0e681ea30bbd', 'c', 'Irán dotados de un pito, de una campana y un gong.', false, '2025-09-13 13:53:10.047293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc509547-1899-4e40-ad5f-fd409ff817c7', 'd624cb67-a731-4101-9941-0e681ea30bbd', 'd', 'Si no llevan los dispositivos de señales acústicas prescritos en la Regla 33, deberán ir dotados de otros medios para hacer las señales acústicas eficaces.', true, '2025-09-13 13:53:10.047423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('280d1cf3-1c80-4b77-b5d2-1b2214691944', '06ed7b66-36e3-4d6d-874a-ad02e1b46266', 'a', 'La conducta de los buques en condiciones de visibilidad reducida es de aplicación a los buques que estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad', false, '2025-09-13 13:53:10.047692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1640949a-6227-4359-aee6-4673f72a4d78', '06ed7b66-36e3-4d6d-874a-ad02e1b46266', 'b', 'Cuando haya riesgo de abordaje, todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, o que no pueda evitar una situación de aproximación excesiva con otro buque situado a proa de su través, deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.047985+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71f19487-df18-4397-b116-98583a9dbac9', '06ed7b66-36e3-4d6d-874a-ad02e1b46266', 'c', 'Todos los buques navegarán a una velocidad de navegación constante atendiendo a las condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:10.048122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ded2a7e3-3e8e-4033-9556-882104ddc2c9', '06ed7b66-36e3-4d6d-874a-ad02e1b46266', 'd', 'Todo buque que detecte por cualquier medio la presencia de otro buque, deteminará si se está creando una situación de aproximación excesiva y/o un riesgo de abordaje.', false, '2025-09-13 13:53:10.048257+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35f23c8c-ffc7-4ffb-b4fb-5687ee2e117f', 'fe9bd936-ffce-4b87-9c73-55a37b5e26af', 'a', 'Una luz roja de centelleos todo horizonte.', false, '2025-09-13 13:53:10.048536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f03f45da-d9a9-42df-83c3-911e0686cb2d', 'fe9bd936-ffce-4b87-9c73-55a37b5e26af', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:10.048677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbf9a38e-c5b8-4898-b59a-33173bddd973', 'fe9bd936-ffce-4b87-9c73-55a37b5e26af', 'c', 'Luces de tope.', false, '2025-09-13 13:53:10.048825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db4c94a5-ea48-440b-b46c-6cec39b8ec6b', 'fe9bd936-ffce-4b87-9c73-55a37b5e26af', 'd', 'Luces de remolque.', false, '2025-09-13 13:53:10.048964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed56ef3f-1630-4875-8461-035181e80d75', '78d8cbc6-257d-403b-aea6-096f9e42261f', 'a', 'Cumplirán las especificaciones del anexo I de este Reglamento.', true, '2025-09-13 13:53:10.049254+00');
