INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d94bcdde-e197-4bf0-a3fa-ad1031239249', '4ef21394-d6c4-4cc5-8b23-d816baa8a7ec', 'c', 'En alta mar y en todas las aguas marítimas que tengan comunicación con ella, sean o no navegables por los buques de navegación marítima.', false, '2025-09-13 13:53:10.05158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71088539-e354-4795-a3d1-c3c5be0c5245', '4ef21394-d6c4-4cc5-8b23-d816baa8a7ec', 'd', 'En alta mar y en todas las aguas en las que España ejerce jurisdicción o derechos soberanos.', false, '2025-09-13 13:53:10.051715+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e011250-8a7d-4357-94e6-5e584503803b', '128a3fbf-2fd4-4b76-93d4-6778d6b91275', 'a', 'Todo buque que por una circunstancia excepcional tiene reducida su capacidad de maniobra.', false, '2025-09-13 13:53:10.051991+00');
