INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e239ced-dfeb-4d0b-b8e8-561c7cd5408a', 'e2b4e878-f906-4188-96fa-ffaeb57bb71a', 'c', 'El tubo dentro del cual gira el eje del timón.', false, '2025-09-13 13:53:10.056636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95d87dfa-4108-4f7c-86f0-4e7b44c06937', 'e2b4e878-f906-4188-96fa-ffaeb57bb71a', 'd', 'La abertura que se abre a un lado de la roda para dar paso a la cadena del ancla. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.056768+00');
