INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9f96265-30f7-4eb8-9e67-18924808b71c', 'eb6d6334-c4c3-4be5-96a5-4a084cc9667e', 'd', 'Piezas de hierro fundido fijadas a los muelles para redireccionar las amarras.', false, '2025-09-13 13:53:10.057547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e9ccaae-8487-43ac-96a5-975ec9176def', '371b8536-d581-4a10-82da-a0131fb213b6', 'a', 'En la maniobra de fondeo hay que elegir el fondeadero y el orinque en función, entre otros aspectos, de la sonda y naturaleza del fondo.', false, '2025-09-13 13:53:10.057843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01f58bd2-1f04-4edd-895c-c78214e10fdd', '371b8536-d581-4a10-82da-a0131fb213b6', 'b', 'Se denomina fondeo a la gira, a la maniobra de fondeo con un ancla por popa, en la que se deja filar la cadena unida al ancla, quedando esta como elemento único de fijación.', false, '2025-09-13 13:53:10.057997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('395bd7f4-da7d-4091-bf65-3825501130e8', '371b8536-d581-4a10-82da-a0131fb213b6', 'c', 'Al cabo que se amarra por un chicote a una boya y por el otro al ancla, se le denomina tenedero.', false, '2025-09-13 13:53:10.058132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c6ee959-fb2c-45b8-81ae-fd3e79badc03', '371b8536-d581-4a10-82da-a0131fb213b6', 'd', 'Se dice que un barco que está fondeado garrea, cuando el ancla no ha agarrado bien al fondo, se desliza y el barco se desplaza.', true, '2025-09-13 13:53:10.058268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9b0728a-87cb-4dd3-8f6f-67ac83e8c4b1', '5f6593c7-8b4e-4428-9102-c180c1aeb88b', 'a', 'Atravesándose a la mar.', false, '2025-09-13 13:53:10.05855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('640e3c1f-0593-4b9d-8a08-98cc00f6b177', '5f6593c7-8b4e-4428-9102-c180c1aeb88b', 'b', 'Reduciendo la velocidad.', true, '2025-09-13 13:53:10.058684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7f94274-c312-4bd5-a4b2-13f0d445b369', '5f6593c7-8b4e-4428-9102-c180c1aeb88b', 'c', 'Aumentando la velocidad.', false, '2025-09-13 13:53:10.058843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89407bbf-5896-416a-b29e-a51aaac0e2ef', '5f6593c7-8b4e-4428-9102-c180c1aeb88b', 'd', 'Largando cabos por popa.', false, '2025-09-13 13:53:10.05899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('594bc1f8-ac2e-4b1b-9a0f-bd67366e2c50', '1c4053dc-c313-47c2-83ef-12f91eb1c059', 'a', 'El temporal se “capeará” recibiendo el mar por la amura.', false, '2025-09-13 13:53:10.059291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8312d3b9-3454-4217-b2ee-071b8a674974', '1c4053dc-c313-47c2-83ef-12f91eb1c059', 'b', '“Correr el temporal” es recibir la mar por popa avanzando con el oleaje y el viento.', false, '2025-09-13 13:53:10.059425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fc045cd-5408-4789-ada2-cca68794a5ff', '1c4053dc-c313-47c2-83ef-12f91eb1c059', 'c', 'Una maniobra válida para hacer frente a la mala mar es echar el ancla de capa o flotante.', false, '2025-09-13 13:53:10.059557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1fac273-4969-41ee-9265-99988397377c', '1c4053dc-c313-47c2-83ef-12f91eb1c059', 'd', '“A son de mar” es el término referido a las maniobras de timón para hacer frente a la mala mar.', true, '2025-09-13 13:53:10.059696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30002f05-ca30-48ef-8006-b148c608a076', '43cd09d1-7709-44b7-84c3-a32eb863a501', 'a', 'Cambiaremos el rumbo hacia puerto para atracar en él inmediatamente.', false, '2025-09-13 13:53:10.059972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9337dd4-b4e7-4eec-a96a-42934df19b40', '43cd09d1-7709-44b7-84c3-a32eb863a501', 'b', 'Aumentaremos la velocidad para salir de la zona de baja visibilidad cuanto antes.', false, '2025-09-13 13:53:10.060106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51311c16-41a2-42eb-9666-52d8be9e594e', '43cd09d1-7709-44b7-84c3-a32eb863a501', 'c', 'Reduciremos la velocidad sin detenerse y modificaremos el rumbo a babor o estribor hasta encontrar una referencia.', false, '2025-09-13 13:53:10.060244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65e51a45-523f-4c49-8b91-145590d411ff', '43cd09d1-7709-44b7-84c3-a32eb863a501', 'd', 'Reduciremos la velocidad, y si es preciso pararemos la embarcación.', true, '2025-09-13 13:53:10.06041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5123f7c6-a688-4c84-ada4-8eeefe2a373c', '32ec6202-4aff-4570-9120-0c44bf324a62', 'a', '4 personas.', false, '2025-09-13 13:53:10.060733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84bf79f3-114b-49e7-8a65-e5a7c3f1a576', '32ec6202-4aff-4570-9120-0c44bf324a62', 'b', '6 personas.', false, '2025-09-13 13:53:10.060904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42884926-ac29-4c27-9af2-89b051e23ca4', '32ec6202-4aff-4570-9120-0c44bf324a62', 'c', 'La correspondiente al número máximo de personas autorizadas a bordo.', true, '2025-09-13 13:53:10.06106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a05fe836-a6da-4b2f-b5a9-9166d1264ea7', '32ec6202-4aff-4570-9120-0c44bf324a62', 'd', 'La indicada en las normas ISO o SOLAS correspondiente según la zona de navegación.', false, '2025-09-13 13:53:10.061195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50f022f0-a98d-437f-b8c6-2d712ea01c66', '3e2064e8-abd6-4a8a-bb42-0aaee35ef434', 'a', 'Las embarcaciones de eslora superior a 6 metros, registradas en la lista 6ª.', false, '2025-09-13 13:53:10.061495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38316236-a3bf-4845-8e28-3f60e35bf7d4', '3e2064e8-abd6-4a8a-bb42-0aaee35ef434', 'b', 'Las embarcaciones de eslora superior a 6 metros, registradas en la lista 7ª.', false, '2025-09-13 13:53:10.061754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a44db493-8d17-4cf1-9043-93ae5ebbea9d', '3e2064e8-abd6-4a8a-bb42-0aaee35ef434', 'c', 'Las embarcaciones de eslora inferior a 6 metros, registradas en la lista 6ª.', false, '2025-09-13 13:53:10.061919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb3f257c-09db-4f18-94dc-475e3619b0cd', '3e2064e8-abd6-4a8a-bb42-0aaee35ef434', 'd', 'Las embarcaciones de eslora inferior a 6 metros, registradas en la lista 7ª.', true, '2025-09-13 13:53:10.062065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('004d9aee-2035-4503-97a5-a673c0b5a1b6', 'ecbeeb19-ec77-46ef-badf-242b6157a723', 'a', '10.', false, '2025-09-13 13:53:10.062361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e000cd0-3457-4b09-8a9c-ce7899ff4b32', 'ecbeeb19-ec77-46ef-badf-242b6157a723', 'b', '9.', true, '2025-09-13 13:53:10.062517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9ed741c-d39e-423c-acda-1c4c7b491691', 'ecbeeb19-ec77-46ef-badf-242b6157a723', 'c', '8.', false, '2025-09-13 13:53:10.062667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4ae4a2d-79b9-4fb6-b87d-c1265831e81e', 'ecbeeb19-ec77-46ef-badf-242b6157a723', 'd', '7.', false, '2025-09-13 13:53:10.062815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48132a1d-73d5-4f26-92cf-6d942aa31db6', '668f6fdd-2a17-4a09-b442-3758a7e83d71', 'a', 'La entrada de un canal, la aproximación a un puerto o estuario o un punto de recalada.', false, '2025-09-13 13:53:10.063097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('628b89b0-9611-4b5f-854b-8504b8b84074', '668f6fdd-2a17-4a09-b442-3758a7e83d71', 'b', 'Zonas de separación de tráfico donde el balizamiento convencional del canal puede prestarse a', true, '2025-09-13 13:53:10.063227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06ae167f-26a5-4477-b785-c398b6c6adb5', '668f6fdd-2a17-4a09-b442-3758a7e83d71', 'c', 'El lado por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:10.063356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe28b8f8-f689-4874-a6f7-08c81ab04d4f', '668f6fdd-2a17-4a09-b442-3758a7e83d71', 'd', 'Los lados de babor y estribor de la derrota que debe seguirse, asociadas a un sentido convencional del balizamiento.', false, '2025-09-13 13:53:10.063485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c4df3c6-fd2c-453b-ac57-5a457c4f864a', '229e0b9e-a8b1-4f3a-b1b8-9bbfe983373b', 'a', 'Dos conos negros superpuestos con los vértices hacia arriba.', false, '2025-09-13 13:53:10.06379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46d3224f-b9a9-44a2-91ff-f2fe125ac29f', '229e0b9e-a8b1-4f3a-b1b8-9bbfe983373b', 'b', 'Dos conos negros superpuestos opuestos por los vértices.', true, '2025-09-13 13:53:10.063931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd1c72aa-032a-4d70-be23-93e6800defb1', '229e0b9e-a8b1-4f3a-b1b8-9bbfe983373b', 'c', 'Dos conos negros superpuestos opuestos por la base.', false, '2025-09-13 13:53:10.064062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e57ce29e-722d-442e-a797-7f6ee250fee7', '229e0b9e-a8b1-4f3a-b1b8-9bbfe983373b', 'd', 'Dos bolas negras superpuestas.', false, '2025-09-13 13:53:10.064194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edd79fbb-8a03-428e-906b-d37f6dd269fd', 'd49b38c9-4750-47d3-9c4b-14815b5a3a06', 'a', 'Negro con una o varias anchas bandas horizontales rojas .', true, '2025-09-13 13:53:10.064469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b02c6b6-7d37-4f80-ab97-143d36a8b9b0', 'd49b38c9-4750-47d3-9c4b-14815b5a3a06', 'b', 'Amarillo con una franja ancha negra horizontal.', false, '2025-09-13 13:53:10.064615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e6989c6-bca0-4b81-bf9c-da1049a3e45c', 'd49b38c9-4750-47d3-9c4b-14815b5a3a06', 'c', 'Rojo con una o varias anchas bandas verticales blancas.', false, '2025-09-13 13:53:10.064751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1bd207a-aad9-4af5-aaa8-b738dd9329a3', 'd49b38c9-4750-47d3-9c4b-14815b5a3a06', 'd', 'Amarillo en toda su superficie.', false, '2025-09-13 13:53:10.064901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78c7e79c-73af-4f9a-9a53-e89c8071595f', 'd0097702-fde2-41eb-a9b7-8f94c8eee59b', 'a', 'La dejaremos por babor.', true, '2025-09-13 13:53:10.065183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ee02a5b-65c6-4fd0-a977-1d30a7fea814', 'd0097702-fde2-41eb-a9b7-8f94c8eee59b', 'b', 'La dejaremos por estribor.', false, '2025-09-13 13:53:10.06532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02e9ce6c-2a22-40d9-bd8f-c887f49c5f00', 'd0097702-fde2-41eb-a9b7-8f94c8eee59b', 'c', 'Significa aguas peligrosas.', false, '2025-09-13 13:53:10.065453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dde22bd9-258b-4db7-8353-c4c994e30dcd', 'd0097702-fde2-41eb-a9b7-8f94c8eee59b', 'd', 'Se puede dejar por cualquier banda.', false, '2025-09-13 13:53:10.065586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34b212d5-e161-4403-9b53-479da32c30dc', '5970a128-22e8-47a2-a0f5-ab5960a42a03', 'a', 'Que las aguas navegables se encuentran en la dirección contraria.', false, '2025-09-13 13:53:10.06597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('802f5b4c-0a17-47fd-964e-402ae8c7c13a', '5970a128-22e8-47a2-a0f5-ab5960a42a03', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:10.066104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72699a7d-2959-4fb6-a92c-5d398cd36055', '5970a128-22e8-47a2-a0f5-ab5960a42a03', 'c', 'La ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:10.066254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0d9609c-8154-42f6-a7e1-c75a1f3b5f40', '5970a128-22e8-47a2-a0f5-ab5960a42a03', 'd', 'Que las aguas son navegables alrededor de la marca. Reglamento (RIPA).', true, '2025-09-13 13:53:10.066385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ca8d79d-121a-4a36-919e-558977be026b', '4be40a7c-b6e9-4778-bbf4-7fc2ca362617', 'a', 'Una marca consistente en dos conos unidos por sus vértices en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:10.066661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7e87d76-6c94-4dd7-afe7-63382fc37c10', '4be40a7c-b6e9-4778-bbf4-7fc2ca362617', 'b', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:10.06681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ed5f8ef-49f4-4717-9bed-9f8b72ce9c0b', '4be40a7c-b6e9-4778-bbf4-7fc2ca362617', 'c', 'Una marca cónica con el vértice hacia abajo.', true, '2025-09-13 13:53:10.066972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51f7c99d-45e7-47c3-95eb-35b26a1fe645', '4be40a7c-b6e9-4778-bbf4-7fc2ca362617', 'd', 'Una marca consistente en dos conos unidos por sus bases en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:10.067117+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86a772ab-a519-460d-bb02-89f809e4b753', '7100577d-ef6b-435e-8480-5a1645c24042', 'a', 'La conducta de los buques en condiciones de visibilidad reducida es de aplicación a los buques que estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad', false, '2025-09-13 13:53:10.067419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('876b4bca-4823-4b70-819e-58054ff39e02', '7100577d-ef6b-435e-8480-5a1645c24042', 'b', 'Cuando haya riesgo de abordaje, todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, o que no pueda evitar una situación de aproximación excesiva con otro buque situado a proa de su través, deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.067556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49dacd42-1543-4cd2-a74f-8d1a23ff2903', '7100577d-ef6b-435e-8480-5a1645c24042', 'c', 'Todos los buques navegarán a una velocidad de navegación constante atendiendo a las condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:10.067694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1641ae21-da35-4f6e-af4c-12106bf19aed', '7100577d-ef6b-435e-8480-5a1645c24042', 'd', 'Todo buque que detecte por cualquier medio la presencia de otro buque, deteminará si se está creando una situación de aproximación excesiva y/o un riesgo de abordaje.', false, '2025-09-13 13:53:10.067835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11336bc0-7a6d-4a78-8701-45147ddbb17f', '050e0130-0300-4195-a34a-70a69511d534', 'a', 'Tendrán obligación de llevar los dispositivos de señales acústicas prescritos en la Regla 33.a.', false, '2025-09-13 13:53:10.068118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59ccb6bc-ec9f-4c02-be9e-f5533e387c42', '050e0130-0300-4195-a34a-70a69511d534', 'b', 'Irán dotados de un pito y de una campana siempre.', false, '2025-09-13 13:53:10.068256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a55e808-9987-4d59-be6e-63333fb9cae5', '050e0130-0300-4195-a34a-70a69511d534', 'c', 'Irán dotados de un pito, de una campana y un gong.', false, '2025-09-13 13:53:10.068392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9c45588-275c-40a7-a718-71aad1ed4efa', '050e0130-0300-4195-a34a-70a69511d534', 'd', 'Si no llevan los dispositivos de señales acústicas prescritos en la Regla 33, deberán ir dotados de otros medios para hacer las señales acústicas eficaces.', true, '2025-09-13 13:53:10.068524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db60bf93-a358-497c-8dd7-58784097bc23', '77ea1b43-29b7-44f6-94f8-5d8694eb7de6', 'a', 'Todo buque que por una circunstancia excepcional tiene reducida su capacidad de maniobra.', false, '2025-09-13 13:53:10.068804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ef7112a-4f0b-4d8e-9c63-fb1b81df7f81', '77ea1b43-29b7-44f6-94f8-5d8694eb7de6', 'b', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', true, '2025-09-13 13:53:10.068936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('667e43e4-87d1-424b-8969-8ca86a3c6c5e', '77ea1b43-29b7-44f6-94f8-5d8694eb7de6', 'c', 'Todo buque que esté fondeado.', false, '2025-09-13 13:53:10.069066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e8fdc1a-dba6-4277-83f1-0ed366957f5f', '77ea1b43-29b7-44f6-94f8-5d8694eb7de6', 'd', 'Todo buque que esté varado.', false, '2025-09-13 13:53:10.069196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dfb637b-9af1-4ff2-aeeb-5f0971ced042', '864a130b-b9cc-4ceb-89c9-a237880b4af6', 'a', 'Una luz roja de centelleos todo horizonte.', false, '2025-09-13 13:53:10.069465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93e82cc8-fd34-466f-84af-3d4951ce296c', '864a130b-b9cc-4ceb-89c9-a237880b4af6', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:10.069601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4eea041c-6cdd-4c37-b9bb-820f80595c15', '864a130b-b9cc-4ceb-89c9-a237880b4af6', 'c', 'Luces de tope.', false, '2025-09-13 13:53:10.069736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81bc5155-053d-410c-b724-ef0e3709a7d3', '864a130b-b9cc-4ceb-89c9-a237880b4af6', 'd', 'Luces de remolque.', false, '2025-09-13 13:53:10.069883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef0af2e1-9282-47ef-aa46-13f49939a043', 'a726c119-515d-481b-a211-4d2abd0a510d', 'a', 'Con independencia de su zona de navegación.', false, '2025-09-13 13:53:10.070301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30094227-15ae-491b-afea-061841b792ad', 'a726c119-515d-481b-a211-4d2abd0a510d', 'b', 'En alta mar y en todas las aguas marítimas que tengan comunicación con ella y sean navegables por los buques de navegación marítima.', true, '2025-09-13 13:53:10.070434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40c64cb0-cea5-4513-9608-bb70499d10e3', 'a726c119-515d-481b-a211-4d2abd0a510d', 'c', 'En alta mar y en todas las aguas marítimas que tengan comunicación con ella, sean o no navegables por los buques de navegación marítima.', false, '2025-09-13 13:53:10.070563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13788698-2ab2-4805-916c-9003d907ce23', 'a726c119-515d-481b-a211-4d2abd0a510d', 'd', 'En alta mar y en todas las aguas en las que España ejerce jurisdicción o derechos soberanos.', false, '2025-09-13 13:53:10.070692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be3d86d0-cdb5-48fd-964c-fb0800c46c64', 'fb0d0eea-8ab0-4bcc-be57-5473e6a02ea6', 'a', 'Un sonido continuo producido por cualquier aparato de señales de niebla.', false, '2025-09-13 13:53:10.070992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b21fe10d-d822-45cb-b4ab-1075b832c375', 'fb0d0eea-8ab0-4bcc-be57-5473e6a02ea6', 'b', 'La señal de peligro «NC» del Código internacional de señales.', false, '2025-09-13 13:53:10.071153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('361a9b3a-d4a0-4a2c-9610-6fedaaba4185', 'fb0d0eea-8ab0-4bcc-be57-5473e6a02ea6', 'c', 'Una alerta de socorro buque-costera transmitido por la estación terrena de buque de Inmarsat u otro proveedor de servicios móviles por satélite.', false, '2025-09-13 13:53:10.071313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee1c8420-4920-42b1-905d-122916c9f1a5', 'fb0d0eea-8ab0-4bcc-be57-5473e6a02ea6', 'd', 'Una alerta de socorro mediante llamada selectiva digital que se transmita en el canal 3 de ondas', true, '2025-09-13 13:53:10.07147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5ba059c-c667-4eaf-8069-52d362a4f878', 'a4134c65-229b-45d2-9446-a3ec189c115a', 'a', 'Cumplirán las especificaciones del anexo I de este Reglamento.', true, '2025-09-13 13:53:10.071805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6200960-27c7-4abb-acaa-8a962aa3a819', 'a4134c65-229b-45d2-9446-a3ec189c115a', 'b', 'Cumplirán las especificaciones del anexo I de este Reglamento, solo en cuanto a su posición.', false, '2025-09-13 13:53:10.071964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0f28bf0-ba3e-4cdf-815e-a900f0556c58', 'a4134c65-229b-45d2-9446-a3ec189c115a', 'c', 'Cumplirán las especificaciones del anexo I de este Reglamento, solo en cuanto a sus características técnicas.', false, '2025-09-13 13:53:10.072128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b9a501e-20e5-4fce-9615-e8135328d987', 'a4134c65-229b-45d2-9446-a3ec189c115a', 'd', 'No hay especificaciones concretas, pero se debe verificar su correcto funcionamiento.', false, '2025-09-13 13:53:10.072288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fcfb013-3a95-4538-a5b6-924cfee2825c', '48e05041-1d56-4bac-ba55-9f65d1ac8044', 'a', 'Corresponde a un buque que está remolcando a otro.', false, '2025-09-13 13:53:10.072621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49d97227-27a2-41df-b8d4-0012ab4cfee2', '48e05041-1d56-4bac-ba55-9f65d1ac8044', 'b', 'Indica peligro y necesidad de ayuda.', true, '2025-09-13 13:53:10.072787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93ac931b-a694-4321-996e-0aaf21c177a9', '48e05041-1d56-4bac-ba55-9f65d1ac8044', 'c', 'Corresponde a un buque dedicado a la pesca de arrastre.', false, '2025-09-13 13:53:10.072936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b6bb6ad-a666-4a23-8ea6-42baf6b9506c', '48e05041-1d56-4bac-ba55-9f65d1ac8044', 'd', 'Corresponde a un buque que está tendiendo cables submarinos.', false, '2025-09-13 13:53:10.073068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbbbbd5d-5ace-4d7b-9bea-019b2c76a1c0', 'e601213b-08fd-4734-83cc-8ee407e4de15', 'a', 'Un buque con propulsión mecánica.', false, '2025-09-13 13:53:10.073341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b06c253e-c275-43ae-addf-0a28916c987c', 'e601213b-08fd-4734-83cc-8ee407e4de15', 'b', 'Un hidroavión.', false, '2025-09-13 13:53:10.073471+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f3e9cc1-cd84-4970-aa3c-564cd3151a02', 'e601213b-08fd-4734-83cc-8ee407e4de15', 'c', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:10.073604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e229accd-e602-4bcc-8459-96aea89a7f2a', 'e601213b-08fd-4734-83cc-8ee407e4de15', 'd', 'Un buque con plena capacidad de maniobra.', false, '2025-09-13 13:53:10.073735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24f912b9-80fe-4c27-a53e-0bbce6aef8c2', '56fe2a87-a835-4114-bfaf-336c4496420c', 'a', 'Siempre que una embarcación tiene asiento, el calado de popa es mayor que el de proa.', false, '2025-09-13 13:53:10.074142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d83a428-ccce-4f15-ac5b-6ab99e674be4', '56fe2a87-a835-4114-bfaf-336c4496420c', 'b', 'El asiento es la distancia entre la parte más baja del barco y la línea de flotación.', false, '2025-09-13 13:53:10.07427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2adcc377-9478-4560-9ad3-d797d3470708', '56fe2a87-a835-4114-bfaf-336c4496420c', 'c', 'Es la inclinación que toma un buque cuando este se aparta de la vertical al sufrir un corrimiento de la carga u otros motivos.', false, '2025-09-13 13:53:10.074398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12a807c5-f63c-47ba-a010-37d312ca7896', '56fe2a87-a835-4114-bfaf-336c4496420c', 'd', 'Se define como la diferencia entre el calado de popa y el calado de proa para una línea de flotación determinada.', true, '2025-09-13 13:53:10.074527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39fe5f11-d406-4367-9bec-8e475f767b4d', '3e0cfd2e-d936-4f24-8579-7b487135f272', 'a', 'La parte del casco que de forma permanente, y con la máxima carga admisible, está sumergida.', false, '2025-09-13 13:53:10.074811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('828978df-86a8-4d51-9695-fae21d234ea8', '3e0cfd2e-d936-4f24-8579-7b487135f272', 'b', 'La parte del casco más los apéndices que de forma permanente, y con la máxima carga admisible, está sumergida.', false, '2025-09-13 13:53:10.07506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e79a72b-1280-46dc-9735-0316a3353fdb', '3e0cfd2e-d936-4f24-8579-7b487135f272', 'c', 'Es la parte emergente del casco sobre la línea de flotación hasta la borda del buque.', true, '2025-09-13 13:53:10.075194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('547a2531-7371-4801-9f62-dfa1e58cb263', '3e0cfd2e-d936-4f24-8579-7b487135f272', 'd', 'La parte del casco más la superestructura que de forma permanente, está fuera del agua cuando el barco está a plena carga.', false, '2025-09-13 13:53:10.075325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7354cb34-8a4d-4582-870e-891b4d062fa1', '08eda14a-4479-4a10-98f0-e51d4762781a', 'a', 'Se conectan directamente a la máquina, motor, bomba o desagüe que lo necesite.', false, '2025-09-13 13:53:10.076266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('846385e9-2194-4737-b45b-797a20fddd54', '08eda14a-4479-4a10-98f0-e51d4762781a', 'b', 'Son llaves de paso que, instaladas por encima de la línea de flotación, si son para instalar desagües, permiten tener bajo control los orificios necesarios en el casco de una embarcación.', false, '2025-09-13 13:53:10.076397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec6e4f7a-59ee-4f14-bd67-956a48639c0b', '08eda14a-4479-4a10-98f0-e51d4762781a', 'c', 'Son válvulas ubicadas por debajo de la línea de flotación cuya función es tomar agua de mar para refrigerar los motores y permitir el desaguado de los servicios.', true, '2025-09-13 13:53:10.076527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99e5016f-088a-488b-8800-508f264e32f9', '08eda14a-4479-4a10-98f0-e51d4762781a', 'd', 'Hay que asegurarse que estén correctamente cerrados durante la navegación para que no entre agua en la embarcación. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.076657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f014c65-2b08-4379-a384-83227e6f40ce', '4a036aaf-5928-4e53-8830-2a30f01d63ca', 'a', 'Nudo llano.', false, '2025-09-13 13:53:10.07693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f375311-7bed-4aa6-b38a-70eb6fc415cb', '4a036aaf-5928-4e53-8830-2a30f01d63ca', 'b', 'Vuelta de rezón.', false, '2025-09-13 13:53:10.077063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b96b3217-2a99-4f9d-884f-1bd9f25513bd', '4a036aaf-5928-4e53-8830-2a30f01d63ca', 'c', 'As de guía.', false, '2025-09-13 13:53:10.077192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddb79ce1-44b0-4ac1-b1eb-c8564c8a8dfa', '4a036aaf-5928-4e53-8830-2a30f01d63ca', 'd', 'Ballestrinque.', true, '2025-09-13 13:53:10.077324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08d3fcd1-b727-43b6-ab2a-daaa3fdef3e4', '22e99680-2c4a-485a-857c-278cad49c049', 'a', 'Accesorio que sirve de protección contra golpes y rozaduras en el casco de la embarcación.', false, '2025-09-13 13:53:10.077593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fb2ded8-b991-4b2b-abe7-069f2206740f', '22e99680-2c4a-485a-857c-278cad49c049', 'b', 'Percha larga, con un gancho en un extremo que se utiliza para coger la guía o las amarras.', true, '2025-09-13 13:53:10.077722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ebe2a7d-af47-4eda-8d23-8368add752e7', '22e99680-2c4a-485a-857c-278cad49c049', 'c', 'Cuerpo flotante sujeto al fondo mediante un muerto, para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:10.077862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bcd06ec-5355-4d81-b27d-859c05f350b0', '22e99680-2c4a-485a-857c-278cad49c049', 'd', 'Pieza sólida afirmada sobre cubierta que sirve para amarrar cabos.', false, '2025-09-13 13:53:10.077994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3c2e10d-5ea9-4dba-a6e9-7c4810e623ca', 'cbb396c6-8be5-47ea-87f9-20b61e4cd4b1', 'a', 'Cerrar todos los grifos de fondo.', true, '2025-09-13 13:53:10.078273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fb65dcb-db10-4e0b-bab9-9aedade5dacf', 'cbb396c6-8be5-47ea-87f9-20b61e4cd4b1', 'b', 'Comprobar los niveles de aceite.', false, '2025-09-13 13:53:10.078404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('530f4b6a-db9f-4865-933b-1dc5d3cd200c', 'cbb396c6-8be5-47ea-87f9-20b61e4cd4b1', 'c', 'Comprobar la tensión de la correa del alternador.', false, '2025-09-13 13:53:10.078533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7753e650-1a44-4817-8a3a-e89dccaae251', 'cbb396c6-8be5-47ea-87f9-20b61e4cd4b1', 'd', 'Comprobar la ausencia de gases explosivos.', false, '2025-09-13 13:53:10.078661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74f60d35-6e26-468c-ac8b-8bfd23bb2a40', 'f0b763cd-42bc-4542-81b7-924d1d9aad8b', 'a', 'Inferior a 35ºC.', true, '2025-09-13 13:53:10.078946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f237cfb-52b8-485e-be34-e00c0441025d', 'f0b763cd-42bc-4542-81b7-924d1d9aad8b', 'b', 'Inferior a 31ºC.', false, '2025-09-13 13:53:10.079075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5cdd9625-b5a3-4c67-b43a-45fc2ea71e94', 'f0b763cd-42bc-4542-81b7-924d1d9aad8b', 'c', 'Inferior a 30ºC.', false, '2025-09-13 13:53:10.07942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a389dc7-4452-4f90-8bdb-26d5227b240d', 'f0b763cd-42bc-4542-81b7-924d1d9aad8b', 'd', 'Depende de las condiciones físicas de la persona.', false, '2025-09-13 13:53:10.079574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92990ba7-3e01-4153-bff9-300e17f069ad', '68f948d5-195d-4e6e-a161-3e3eaccb8c8f', 'a', 'No, en ningún caso, pero sí es recomendable.', false, '2025-09-13 13:53:10.07992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9745f933-ac93-405b-afc9-4174069ccf49', '68f948d5-195d-4e6e-a161-3e3eaccb8c8f', 'b', 'Sí, pero sólo en embarcaciones de más de 12 metros de eslora de casco.', false, '2025-09-13 13:53:10.080083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc80c333-1b5f-420e-a1c9-367c31a52d22', '68f948d5-195d-4e6e-a161-3e3eaccb8c8f', 'c', 'Sí, en cualquier tipo de embarcación de recreo.', false, '2025-09-13 13:53:10.080242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d9e9eea-e663-4a3e-b621-4a7083d8d1c3', '68f948d5-195d-4e6e-a161-3e3eaccb8c8f', 'd', 'Sí, pero sólo en embarcaciones de recreo de casco no metálico.', true, '2025-09-13 13:53:10.080402+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2d681f9-ac23-44cb-90f4-06db52c91c35', '3ad06837-2497-42e6-9b06-9a037b7c5e12', 'a', 'Localizaremos un veril de seguridad.', true, '2025-09-13 13:53:10.080728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29904a0e-2579-4a5e-8b5c-676691a6e983', '3ad06837-2497-42e6-9b06-9a037b7c5e12', 'b', 'Activaremos y visualizaremos el RADAR para detectar los bajos, rocas o pecios que haga que nuestra embarcación toque fondo.', false, '2025-09-13 13:53:10.080878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d187b9f-859b-460b-9707-3c25b43ffa79', '3ad06837-2497-42e6-9b06-9a037b7c5e12', 'c', 'Encenderemos las luces de navegación y haremos las señales fónicas reglamentarias.', false, '2025-09-13 13:53:10.08101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cccfaed1-02a7-4a4c-9e41-a2013ef40628', '3ad06837-2497-42e6-9b06-9a037b7c5e12', 'd', 'Aumentaremos la velocidad para alejarnos rápidamente de la costa y de la zona.', false, '2025-09-13 13:53:10.08114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fa3d3ac-8b07-423a-9f7b-58271c32f426', 'a89619b7-cb31-4c53-b334-14a0bf6f71b3', 'a', 'A una distancia de seguridad mínima de 50 millas náuticas de la zona de buceo.', false, '2025-09-13 13:53:10.082127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14987295-14a7-4961-bbd9-10b8546587c7', 'a89619b7-cb31-4c53-b334-14a0bf6f71b3', 'b', 'Siempre a una distancia prudencial. De ser necesario aproximarse a la zona de buceo, se hará a una velocidad no superior a 3 nudos, para minimizar el riesgo.', false, '2025-09-13 13:53:10.08226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5a3d2ed-892b-4423-be90-7ac1b515fb1b', 'a89619b7-cb31-4c53-b334-14a0bf6f71b3', 'c', 'A una distancia de seguridad mínima de 50 metros de la zona de buceo.', true, '2025-09-13 13:53:10.082396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf0ec037-cf7f-4c80-b7b2-d8b9734be935', 'a89619b7-cb31-4c53-b334-14a0bf6f71b3', 'd', 'Siempre a una distancia prudencial. De ser necesario aproximarse a la zona de buceo, se hará a una velocidad superior a 3 nudos, para minimizar el riesgo.', false, '2025-09-13 13:53:10.082528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('187986e4-ccc2-4a3c-bee1-fe5728c8169a', '60b8ab4e-26a1-466f-bd50-b958fcb55f26', 'a', 'GPS.', false, '2025-09-13 13:53:10.082816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b95545d-9ea8-4a46-99ac-26f07e5cbe75', '60b8ab4e-26a1-466f-bd50-b958fcb55f26', 'b', 'Sonda.', false, '2025-09-13 13:53:10.082949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5aab7bb8-98fe-4fc9-bd4d-4b9fa452a329', '60b8ab4e-26a1-466f-bd50-b958fcb55f26', 'c', 'Compás.', true, '2025-09-13 13:53:10.08308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b58bd8d-168b-4273-8f79-c2185a535ccb', '60b8ab4e-26a1-466f-bd50-b958fcb55f26', 'd', 'Radar.', false, '2025-09-13 13:53:10.083212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63daa3ce-c25e-4c52-b951-fccac8fbeefe', 'cd5e5425-e548-4c8f-a385-4262117369bf', 'a', 'Cilíndrica, de castillete o espeque.', false, '2025-09-13 13:53:10.083485+00');
