INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e16018c1-2b39-4a1c-bb60-31a83c1c199b', '3d97907d-0ddf-4fee-a02b-c82418aa323a', 'a', 'Dos conos negros superpuestos opuestos por sus vértices.', true, '2025-09-13 13:53:10.084325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15faf459-9e6d-4dd4-b790-7f03e3a9fd9a', '3d97907d-0ddf-4fee-a02b-c82418aa323a', 'b', 'Dos conos negros superpuestos opuestos por sus bases.', false, '2025-09-13 13:53:10.08446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e891037-7258-4961-a306-d7679d912999', '3d97907d-0ddf-4fee-a02b-c82418aa323a', 'c', 'Dos conos negros superpuestos con sus vértices hacia arriba.', false, '2025-09-13 13:53:10.084598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e8c59d-aa45-4484-91df-f525a0e32bb0', '3d97907d-0ddf-4fee-a02b-c82418aa323a', 'd', 'Dos conos negros superpuestos con sus vértices hacia abajo.', false, '2025-09-13 13:53:10.084736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3c6b7af-1a72-4829-9c4d-ebc0f53e370d', 'a54caad6-e45d-4479-bef3-6ec6f6511de5', 'a', 'El color será rojo y la forma cilíndrica, de castillete o espeque.', true, '2025-09-13 13:53:10.085015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7d74f93-cac8-41f6-aadd-e82ea3b27598', 'a54caad6-e45d-4479-bef3-6ec6f6511de5', 'b', 'El color será verde y la forma cilíndrica, de castillete o espeque.', false, '2025-09-13 13:53:10.085147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('850cca29-cb1a-4f6b-ad10-de5f5b6283d7', 'a54caad6-e45d-4479-bef3-6ec6f6511de5', 'c', 'El color será rojo y la forma cónica.', false, '2025-09-13 13:53:10.08528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5f6f426-54c1-41f9-a27a-fb279a3a0d59', 'a54caad6-e45d-4479-bef3-6ec6f6511de5', 'd', 'El color será verde y la forma cónica.', false, '2025-09-13 13:53:10.085415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daf414b9-4dd2-4df5-866d-2e99642dbf70', '8b20f162-51a2-4020-81a2-8b27b10cc0c9', 'a', 'Dos esferas negras superpuestas.', false, '2025-09-13 13:53:10.085697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66949c2d-bca5-4793-9270-aeff1d19bf65', '8b20f162-51a2-4020-81a2-8b27b10cc0c9', 'b', 'Una esfera roja.', true, '2025-09-13 13:53:10.085832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64a6493d-1d8d-46df-b43a-5d3748953d33', '8b20f162-51a2-4020-81a2-8b27b10cc0c9', 'c', 'Una esfera negra.', false, '2025-09-13 13:53:10.085971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7074949-0603-432d-9b3d-547ae20e754f', '31a4dc49-a2d9-43cb-aac8-63bc20011a78', 'a', 'El estado de visibilidad.', false, '2025-09-13 13:53:10.086383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('123bcedf-ad6a-4b62-befc-0dc97434f271', '31a4dc49-a2d9-43cb-aac8-63bc20011a78', 'b', 'La densidad del tráfico.', false, '2025-09-13 13:53:10.086517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('babee6aa-e408-41a7-91aa-243e64b7184d', '31a4dc49-a2d9-43cb-aac8-63bc20011a78', 'c', 'La maniobrabilidad del buque.', false, '2025-09-13 13:53:10.086648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('677b0a51-8287-4ef6-bafc-551fcb1b8f0b', '31a4dc49-a2d9-43cb-aac8-63bc20011a78', 'd', 'La titulación requerida para pilotar el buque.', true, '2025-09-13 13:53:10.086791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d3f2876-b450-4bee-a38c-36a5c0781f4a', 'eaf5d8fe-71f1-4c74-bf83-64bc64982576', 'a', 'En aerodeslizadores, cuando operen en la condición sin desplazamiento.', false, '2025-09-13 13:53:10.087067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a34ee290-e99c-40cb-9cc8-20bee9f6a341', 'eaf5d8fe-71f1-4c74-bf83-64bc64982576', 'b', 'En aerodeslizadores, cuando operen en la condición con desplazamiento.', false, '2025-09-13 13:53:10.087202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acbfe01b-8ca2-4366-b0b3-34964dc6b948', 'eaf5d8fe-71f1-4c74-bf83-64bc64982576', 'd', 'En naves de vuelo rasante, en cualquier situación y durante todo el tiempo que dure el vuelo.', false, '2025-09-13 13:53:10.087474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d1adf4a-8ceb-4517-9138-981c5861e3b6', '8fa2323a-433b-40e2-b890-31ecb465a240', 'a', 'Los buques de propulsión mecánica navegarán a cualquier velocidad, pero tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:10.087756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de9ac261-6371-4b8a-9bfd-9e4759ad5316', '8fa2323a-433b-40e2-b890-31ecb465a240', 'c', 'Los buques de vela navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida.', true, '2025-09-13 13:53:10.088038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d09ce51f-db6a-4d39-b520-4e69863f2125', '8fa2323a-433b-40e2-b890-31ecb465a240', 'd', 'Los buques que detecten a otros sólo con el radar no tomarán ninguna medida ya que el radar no nos da datos de posición fiables, y esperaremos a estar a la vista uno del otro.', false, '2025-09-13 13:53:10.088173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3055bef1-2c82-4d89-ae47-5663d3874204', '81da69c9-c75b-476d-b80f-aef7b3d5b5d6', 'a', 'Cuatro pitadas consecutivas, a saber, una pitada larga seguida de tres cortas.', false, '2025-09-13 13:53:10.088454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c95e57e-b2f6-4134-8ccb-e46c3520fe8d', '81da69c9-c75b-476d-b80f-aef7b3d5b5d6', 'b', 'Cuatro pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ellas.', false, '2025-09-13 13:53:10.08859+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('802f0910-31be-4124-87c1-b2fedee15d42', '81da69c9-c75b-476d-b80f-aef7b3d5b5d6', 'c', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:10.088727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8dc6fc7f-6101-44b3-a2a4-020f43714e11', '81da69c9-c75b-476d-b80f-aef7b3d5b5d6', 'd', 'Una pitada larga.', false, '2025-09-13 13:53:10.088882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28fc4928-3af7-4e45-80c0-019622b30121', 'dc59290b-b0a7-4447-8856-27e74db00ef1', 'a', 'Una pitada corta.', false, '2025-09-13 13:53:10.08929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('183d03ab-47a6-4a63-9fa6-f3be7d969a0c', 'dc59290b-b0a7-4447-8856-27e74db00ef1', 'b', 'Una pitada larga.', false, '2025-09-13 13:53:10.089425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fd99626-1522-4563-bb0c-faa72582c74f', 'dc59290b-b0a7-4447-8856-27e74db00ef1', 'c', 'Tres pitadas cortas.', true, '2025-09-13 13:53:10.089564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebdca7a6-36f7-4204-808a-8207d7a6c27c', 'dc59290b-b0a7-4447-8856-27e74db00ef1', 'd', 'Tres pitadas largas.', false, '2025-09-13 13:53:10.089695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a7392e7-7567-491b-b1a2-7847035b1064', '84260b80-9a6b-4f43-9e5f-fd6342a8fd36', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.089975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77baafb8-cd7f-45c6-89fd-126ed3c05e09', '8fa2323a-433b-40e2-b890-31ecb465a240', 'b', 'Los buques mantendrán rumbo y velocidad hasta que desaparezcan las condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.087902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95c96fa5-8a41-46ba-a508-1877e2802014', '8b20f162-51a2-4020-81a2-8b27b10cc0c9', 'd', 'Dos esferas rojas superpuestas.', false, '2025-09-13 13:53:10.086105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62323853-db7b-44db-b41d-4380e3d5562a', 'eaf5d8fe-71f1-4c74-bf83-64bc64982576', 'c', 'En naves de vuelo rasante, únicamente cuando despeguen, aterricen o vuelen cerca de la superficie.', true, '2025-09-13 13:53:10.087338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9dc86b9-3e77-4dfd-a3ef-c5ff20125451', '84260b80-9a6b-4f43-9e5f-fd6342a8fd36', 'b', 'No podrán adelantar a los buques que los precedan.', false, '2025-09-13 13:53:10.090109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb51eb31-c122-419a-a2f9-6fb2288627ef', '84260b80-9a6b-4f43-9e5f-fd6342a8fd36', 'c', 'Bajo ninguna circunstancia, se podrá fondear en dicho paso o canal.', false, '2025-09-13 13:53:10.090247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86e61237-7768-4c3e-b584-48d52404ee31', '84260b80-9a6b-4f43-9e5f-fd6342a8fd36', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', true, '2025-09-13 13:53:10.090383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b66ff38-d02f-4bba-a7e5-137eb6403905', 'a4463168-ba49-499a-b83c-9722c24ed7ee', 'd', 'Es el buque que va a ser alcanzado y está indicando que “debe ser alcanzado por su banda de', false, '2025-09-13 13:53:10.091069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e607eef-65ca-4c86-ba7e-961f9ea9ce1d', 'd1786cbe-ae87-4ae3-9582-4fc8312c205c', 'a', 'Se detendrá por precaución.', false, '2025-09-13 13:53:10.092026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67219f13-b05e-486f-9d6a-4175acecc918', 'd1786cbe-ae87-4ae3-9582-4fc8312c205c', 'b', 'No podrá actuar para evitar el abordaje.', false, '2025-09-13 13:53:10.092158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a669ca1b-0264-4059-b3bb-af2bd689ae54', 'd1786cbe-ae87-4ae3-9582-4fc8312c205c', 'c', 'Mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:10.09229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7238460-8682-466d-9d99-969f407dae45', 'd1786cbe-ae87-4ae3-9582-4fc8312c205c', 'd', 'Solamente el buque que cede el paso podrá ejecutar la maniobra que mejor pueda ayudar a evitar', false, '2025-09-13 13:53:10.092422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9138f95d-1c04-433c-bb37-afb2feb56819', 'c6232d25-7baa-43ef-a6d5-66a8c16417f3', 'a', 'Deberá aumentar su velocidad hasta la máxima de gobierno.', false, '2025-09-13 13:53:10.092699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fca61079-029a-4314-99fe-dc55ef7dda1b', 'c6232d25-7baa-43ef-a6d5-66a8c16417f3', 'b', 'Deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.092833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f98c70f0-4f96-4550-9aea-3f73f5377fa7', 'c6232d25-7baa-43ef-a6d5-66a8c16417f3', 'c', 'No suprimirá su arrancada.', false, '2025-09-13 13:53:10.092963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51997152-b314-400c-91fd-9bc2a80c2bca', 'e81a57a1-acea-419b-8d32-3724d6125190', 'a', 'Adujar.', true, '2025-09-13 13:53:10.093365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af193cd0-6794-4966-8c39-01856855bfb0', 'e81a57a1-acea-419b-8d32-3724d6125190', 'b', 'Amollar.', false, '2025-09-13 13:53:10.093496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1531444b-144c-426a-84ad-7cc2f42f1e71', 'e81a57a1-acea-419b-8d32-3724d6125190', 'c', 'Templar.', false, '2025-09-13 13:53:10.093626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c4476fa-08b0-4dce-a043-52bd054ae67e', 'e81a57a1-acea-419b-8d32-3724d6125190', 'd', 'Lascar.', false, '2025-09-13 13:53:10.093758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a455152-d77f-4223-856b-f4bee1e191a3', '70b3c870-6096-4936-8172-44e1a1d0e574', 'a', 'Fase de inicial, fase variable y fase uniforme.', false, '2025-09-13 13:53:10.094044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22341de6-c4d6-4d6f-9cbf-4dfd466724e3', '70b3c870-6096-4936-8172-44e1a1d0e574', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:10.094275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1110586a-4e75-4956-bfe9-1fba42b11169', '70b3c870-6096-4936-8172-44e1a1d0e574', 'c', 'Fase de inicial, fase de maniobra y fase final.', false, '2025-09-13 13:53:10.094406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('367091f3-6777-44a5-9468-deed26acd36b', '000cea89-5b22-42a5-af8c-99dcb13076d6', 'a', 'Instantes previos al abandono de la embarcación, es muy recomendable su uso. De esta forma se consigue señalar el lugar del abandono y podremos ser avistados desde otra embarcación, unidad aérea o desde la costa cercana.', false, '2025-09-13 13:53:10.094808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9064b3b-1a1e-4f70-8e70-6f5e6ce4c3e7', '000cea89-5b22-42a5-af8c-99dcb13076d6', 'b', 'Las bengalas se deben encender por barlovento, prácticamente en vertical y con el brazo alargado y hacia arriba.', false, '2025-09-13 13:53:10.094945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8e07777-8635-41c4-893c-e7fb82aca23d', '000cea89-5b22-42a5-af8c-99dcb13076d6', 'c', 'Para su uso es recomendable equiparse con guantes y gafas de seguridad y sujetar la bengala con una sola mano por la parte inferior de esta o su empuñadura, con la flecha indicadora hacia arriba.', true, '2025-09-13 13:53:10.095076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a10b3a0b-f171-488d-8d6d-a0af88247fff', '000cea89-5b22-42a5-af8c-99dcb13076d6', 'd', 'Debe utilizarse por el día ya que es más eficaz, si cabe, que los botes de humo o cohetes, por ser más visible a gran distancia.', false, '2025-09-13 13:53:10.095205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c48ceb3-228f-4032-84e6-d73414e567b1', '5f3d7c1d-1f0d-4a92-bea5-52f62b7e1aeb', 'a', 'La fuerza de Coriolis.', false, '2025-09-13 13:53:10.096791+00');
