INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b16fe3c4-81be-4932-871a-99c95e251c2f', '5f3d7c1d-1f0d-4a92-bea5-52f62b7e1aeb', 'c', 'La fuerza intermolecular.', false, '2025-09-13 13:53:10.097049+00');
