INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b41ced14-e5ab-475a-a98a-1aea36d9a7d0', '2751d7aa-4c1a-46f0-a492-e6d16269ef29', 'a', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:10.098795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('806fe1b0-057c-4965-a7d8-ca1bdbb7001d', '2751d7aa-4c1a-46f0-a492-e6d16269ef29', 'b', 'La temperatura aparece como una propiedad termodinámica y no en función de las propiedades de una sustancia.', false, '2025-09-13 13:53:10.099042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcd24e04-9d34-4fcf-b7c1-39e2def122c2', '2751d7aa-4c1a-46f0-a492-e6d16269ef29', 'c', 'Para indicar la temperatura de un cuerpo se usan escalas arbitrarias de referencia, entre las que se encuentra la escala Celsius.', false, '2025-09-13 13:53:10.099174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f93b6965-d536-4b8b-a0bc-05e5b4097652', 'a6402a67-00e4-43b5-8473-4b4a7c83fda6', 'c', 'As de guía.', false, '2025-09-13 13:53:10.108825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72265f0d-a464-481b-81b8-a6ba8e97c23b', 'a4463168-ba49-499a-b83c-9722c24ed7ee', 'a', 'Es el buque que pretende alcanzar al otro y está indicando que “pretende alcanzarle por su banda de estribor”.', true, '2025-09-13 13:53:10.090659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97f11418-7f02-4e3b-9742-e70b04d525a3', 'a4463168-ba49-499a-b83c-9722c24ed7ee', 'b', 'Es el buque que pretende alcanzar al otro y está indicando que “pretende alcanzarle por su banda de estribor”.', false, '2025-09-13 13:53:10.0908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('482bac15-1b15-4fbe-b785-35f6a183fa09', 'a4463168-ba49-499a-b83c-9722c24ed7ee', 'c', 'Es el buque que va a ser alcanzado y está indicando que “debe ser alcanzado por su banda de estribor”.', false, '2025-09-13 13:53:10.090935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc7e3a42-adf4-4f96-866d-edf623ce10b7', 'c6232d25-7baa-43ef-a6d5-66a8c16417f3', 'd', 'Navegará con extremada precaución y caerá a estribor.', false, '2025-09-13 13:53:10.093094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('915fd1da-b533-4d83-86b6-2aa4fea07e0e', '70b3c870-6096-4936-8172-44e1a1d0e574', 'd', 'Fase de maniobra, fase variable y fase final.', false, '2025-09-13 13:53:10.094533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2854b352-3f3f-412e-9f23-f4b78ad2e896', '2751d7aa-4c1a-46f0-a492-e6d16269ef29', 'd', 'Dos cuerpos en equilibrio térmico deben estar a la misma presión y temperatura. Teoría de la navegación.', true, '2025-09-13 13:53:10.099302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73bf1e4d-f199-4477-8b99-b8017ad677ac', 'dd775210-ab38-4422-8396-786cb4e03e47', 'b', 'Es la línea que une dos puntos de la costa situados uno a proa y otro a popa del buque.', false, '2025-09-13 13:53:10.099703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22af740b-a3de-4c6c-af15-7667b04954c6', 'dd775210-ab38-4422-8396-786cb4e03e47', 'c', 'Es una línea de posición que permite calcular la corrección total.', true, '2025-09-13 13:53:10.099849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7895da90-b86e-49cd-b1c7-6c23d45d24b3', 'dd775210-ab38-4422-8396-786cb4e03e47', 'd', 'Es una línea de posición en la que el buque se encuentra sobre la línea que une dos puntos de la costa y entre ellos.', false, '2025-09-13 13:53:10.099978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd23f8d3-ff35-4316-be90-4698e68150bb', 'fcf4395b-cfda-49e0-82da-56791e1963ab', 'a', 'El norte verdadero hasta el norte magnético.', false, '2025-09-13 13:53:10.100256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2b59d4c-dccf-4b02-9873-75c4cc1f4a61', 'fcf4395b-cfda-49e0-82da-56791e1963ab', 'b', 'El norte magnético hasta el norte de aguja.', false, '2025-09-13 13:53:10.100385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d67118b0-cd63-49a4-87d0-f71eb0217bfd', 'fcf4395b-cfda-49e0-82da-56791e1963ab', 'c', 'El norte geográfico hasta el norte magnético.', false, '2025-09-13 13:53:10.100513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d603bd42-a5ff-48a8-90f1-680412e11df8', 'fcf4395b-cfda-49e0-82da-56791e1963ab', 'd', 'El norte verdadero hasta el norte de aguja.', true, '2025-09-13 13:53:10.100642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('080ef54b-d61e-4bbd-b25e-e8616d399015', 'db100589-65f5-4d3e-b0e7-72b80b2f1fef', 'a', 'Es la relación entre la velocidad aparente y la velocidad por corredera.', false, '2025-09-13 13:53:10.100933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aec5a760-6c84-48dc-9de4-8be0c803f04d', 'db100589-65f5-4d3e-b0e7-72b80b2f1fef', 'b', 'Es la relación entre la distancia verdadera y la velocidad por corredera.', false, '2025-09-13 13:53:10.101064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f3f70dc-0167-4b0d-8b98-3a9aa1895dbc', 'db100589-65f5-4d3e-b0e7-72b80b2f1fef', 'c', 'Se utiliza para el cálculo de la distancia verdadera navegada.', true, '2025-09-13 13:53:10.101193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('696bbefa-7611-4b9c-a82e-c7ea1c9bc0d3', 'db100589-65f5-4d3e-b0e7-72b80b2f1fef', 'd', 'Se utiliza para el cálculo de la velocidad por corredera y es constante para todos los buques.', false, '2025-09-13 13:53:10.101321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b6072a8-e967-44bb-a45d-e635940a9b5b', 'f185f0b4-8405-4998-a0dc-2c9997871b7f', 'a', 'Las líneas de posición deben cortarse con un ángulo próximo a 90º.', true, '2025-09-13 13:53:10.101591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e160537-eaa6-4486-a5d1-543892d5e97e', 'f185f0b4-8405-4998-a0dc-2c9997871b7f', 'b', 'Las líneas isobáticas son más fiables que las enfilaciones.', false, '2025-09-13 13:53:10.101721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1003800a-c801-449f-a9fc-15b67acb835b', 'f185f0b4-8405-4998-a0dc-2c9997871b7f', 'c', 'La situación del barco es la intersección de al menos tres líneas de posición.', false, '2025-09-13 13:53:10.101862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('812e6d2b-1185-48da-a19e-adf1b54ba96a', 'f185f0b4-8405-4998-a0dc-2c9997871b7f', 'd', 'La enfilación puede ser imprecisa si se cometen errores en el desvío.', false, '2025-09-13 13:53:10.101992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('698d1752-7ae5-43e6-b17f-6da89006a407', '398ef768-92cb-4397-b71d-3e9ec8451f39', 'a', 'Es la hora del puerto de salida y se utiliza para calcular la latitud.', false, '2025-09-13 13:53:10.102271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7bb504e-ec93-4989-a2ed-1c778f771bc1', '398ef768-92cb-4397-b71d-3e9ec8451f39', 'b', 'Es la hora por la que se guían las actividades a bordo y es recomendable ajustarla a medida que se cambia de huso.', true, '2025-09-13 13:53:10.1024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca18b3bf-962f-4f8b-86f9-7b54417b9ce3', '398ef768-92cb-4397-b71d-3e9ec8451f39', 'c', 'Siempre es igual a la Hora Oficial.', false, '2025-09-13 13:53:10.102531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('433a6e6b-8698-4f54-b676-9c514e944151', '33234cc3-bf1e-4d91-a63a-aba50a9e184a', 'a', '4,40 metros.', false, '2025-09-13 13:53:10.102936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b81590a-34b0-4d15-8734-22dedbb8e65f', '33234cc3-bf1e-4d91-a63a-aba50a9e184a', 'b', '4,76 metros.', false, '2025-09-13 13:53:10.103062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3385e3ff-d48b-4d10-9142-96df84e9123a', '33234cc3-bf1e-4d91-a63a-aba50a9e184a', 'c', '4,71 metros.', true, '2025-09-13 13:53:10.103188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b17e6fa1-ec54-410d-b5b6-49e2ff15833a', '33234cc3-bf1e-4d91-a63a-aba50a9e184a', 'd', '3,50 metros.', false, '2025-09-13 13:53:10.103313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffb1753b-e807-4531-b7e8-128ee4152412', '13e3c984-009f-4b86-baa0-ec20ed63e5b2', 'd', 'l=36°05,3´N; L=005°50,4´W', false, '2025-09-13 13:53:10.104053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb7532a7-d2fb-4083-861b-c102e62b6ee0', '7e780a7b-02ad-4c85-a20e-5dd6ce0a1461', 'd', 'l=36º 12´N L=005º 12,8´W', false, '2025-09-13 13:53:10.104704+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3921c671-763e-4bde-bac6-156c69498107', 'e9b67e7e-fea4-4d8a-883a-5efcf7db2100', 'a', '157º', false, '2025-09-13 13:53:10.104972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46edff53-3d1f-4bfb-a2f8-a9a394ba89f1', 'e9b67e7e-fea4-4d8a-883a-5efcf7db2100', 'b', '153º', false, '2025-09-13 13:53:10.105097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cb4ef23-1a99-4ef1-85aa-a74e1082869a', 'e9b67e7e-fea4-4d8a-883a-5efcf7db2100', 'c', '165,5º', true, '2025-09-13 13:53:10.105232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87101cc4-5003-433a-8bd1-c6086ee9405a', 'e9b67e7e-fea4-4d8a-883a-5efcf7db2100', 'd', '149,5º DE TRANSPORTES, MOVILIDAD                                                                            DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                      Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 03 Nomenclatura náutica.', false, '2025-09-13 13:53:10.105361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fa3c45d-0f46-4371-b9c4-8a9a7d38b1c4', '24fab1c7-1cd4-4457-a091-f0c1c8519965', 'a', 'Siempre que una embarcación tiene asiento, el calado de popa es mayor que el de proa.', false, '2025-09-13 13:53:10.10577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bdb97d2-736b-4e37-82cb-7a860ad4ef0b', '24fab1c7-1cd4-4457-a091-f0c1c8519965', 'b', 'El asiento es la distancia entre la parte más baja del barco y la línea de flotación.', false, '2025-09-13 13:53:10.105898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1050c3d0-9a42-41fc-a2b8-33916ce5880e', '24fab1c7-1cd4-4457-a091-f0c1c8519965', 'c', 'Es la inclinación que toma un buque cuando este se aparta de la vertical al sufrir un corrimiento de la carga u otros motivos.', false, '2025-09-13 13:53:10.106023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be481b39-5ddf-46fc-b07f-b745724a0d69', '24fab1c7-1cd4-4457-a091-f0c1c8519965', 'd', 'Se define como la diferencia entre el calado de popa y el calado de proa para una línea de flotación determinada.', true, '2025-09-13 13:53:10.106149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e72d68e-ccd4-494e-96c2-071225babfb0', '774460f4-44f7-4b9c-bcec-aade96728904', 'a', 'Se conectan directamente a la máquina, motor, bomba o desagüe que lo necesite.', false, '2025-09-13 13:53:10.106422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ade2f05-39d5-4970-a7b3-b7ee932889f0', '774460f4-44f7-4b9c-bcec-aade96728904', 'b', 'Son llaves de paso que, instaladas por encima de la línea de flotación, si son para instalar desagües, permiten tener bajo control los orificios necesarios en el casco de una embarcación.', false, '2025-09-13 13:53:10.106548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb056dd5-acce-4203-81ef-b2d7144e2d1b', '774460f4-44f7-4b9c-bcec-aade96728904', 'c', 'Son válvulas ubicadas por debajo de la línea de flotación cuya función es tomar agua de mar para refrigerar los motores y permitir el desaguado de los servicios.', true, '2025-09-13 13:53:10.106674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0a1adb8-4df6-4b5e-a617-731944b576ee', '774460f4-44f7-4b9c-bcec-aade96728904', 'd', 'Hay que asegurarse que estén correctamente cerrados durante la navegación para que no entre agua en la embarcación.', false, '2025-09-13 13:53:10.106811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75ad0f6c-7844-44bb-81a9-af59fc9b1df5', '9078ac30-6acd-4b4d-bd03-6b95a8077a09', 'a', 'La parte del casco que de forma permanente, y con la máxima carga admisible, está sumergida.', false, '2025-09-13 13:53:10.10772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e106824-ef16-4ab3-bc98-66ce42552b35', '9078ac30-6acd-4b4d-bd03-6b95a8077a09', 'b', 'La parte del casco más los apéndices que de forma permanente, y con la máxima carga admisible, está sumergida.', false, '2025-09-13 13:53:10.107851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cebd68fb-30e3-4a42-951a-660c111cf1f0', '9078ac30-6acd-4b4d-bd03-6b95a8077a09', 'c', 'Es la parte emergente del casco sobre la línea de flotación hasta la borda del buque.', true, '2025-09-13 13:53:10.10799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8f42de9-1ee7-4d26-96d2-8b64244201f1', '9078ac30-6acd-4b4d-bd03-6b95a8077a09', 'd', 'La parte del casco más la superestructura que de forma permanente, está fuera del agua cuando el barco está a plena carga. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.10812+00');
