INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe9c21e3-0b52-4d67-b469-dc3b968321b8', 'a7625bea-b2f9-4218-94ac-8f3acfb1f3af', 'b', 'Es el buque que pretende alcanzar al otro y está indicando que “pretende alcanzarle por su banda de estribor”.', false, '2025-09-13 13:53:10.11761+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28ef28b4-c4bf-4c25-a704-6f61ee0d43f9', 'a7625bea-b2f9-4218-94ac-8f3acfb1f3af', 'c', 'Es el buque que va a ser alcanzado y está indicando que “debe ser alcanzado por su banda de estribor”.', false, '2025-09-13 13:53:10.117742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d878788e-0480-4c74-927c-1ea8980371d4', '1fecb403-1836-4d39-939f-8272d86dc154', 'd', 'Dos conos negros superpuestos con sus vértices hacia abajo.', false, '2025-09-13 13:53:10.117079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('950585d6-0627-4fe7-bbf5-d17a2979a089', 'a7625bea-b2f9-4218-94ac-8f3acfb1f3af', 'a', 'Es el buque que pretende alcanzar al otro y está indicando que “pretende alcanzarle por su banda de estribor”.', true, '2025-09-13 13:53:10.117472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c96d3ffe-e7e5-414e-81da-aa1543bd7200', '1d405f40-45e8-4755-87d0-8d2348532de2', 'b', 'Cuatro pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ellas.', false, '2025-09-13 13:53:10.119618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d59a4ce8-b135-473b-8d1a-5cb040126f99', '1d405f40-45e8-4755-87d0-8d2348532de2', 'c', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:10.119752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4710bfc-1223-46c0-b1c9-eb3d9f2e3911', '1d405f40-45e8-4755-87d0-8d2348532de2', 'd', 'Una pitada larga.', false, '2025-09-13 13:53:10.119896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('899dea83-c77b-42d8-a255-f2e014551a2f', '91edb2b5-f468-4b9b-ab73-2817658dfcba', 'a', 'En aerodeslizadores, cuando operen en la condición sin desplazamiento.', false, '2025-09-13 13:53:10.120173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a876603f-fcb9-488c-9a6f-359fcbe441cb', '91edb2b5-f468-4b9b-ab73-2817658dfcba', 'b', 'En aerodeslizadores, cuando operen en la condición con desplazamiento.', false, '2025-09-13 13:53:10.120308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b65c2f69-41a7-4c4a-b52f-d737af2d454f', '91edb2b5-f468-4b9b-ab73-2817658dfcba', 'd', 'En naves de vuelo rasante, en cualquier situación y durante todo el tiempo que dure el vuelo.', false, '2025-09-13 13:53:10.120577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6a04906-0454-4326-9fec-e959cece75d5', '96c7daab-59eb-4442-af01-3f5a8dbf4d33', 'a', 'Se detendrá por precaución.', false, '2025-09-13 13:53:10.120859+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33bc9321-8d68-46cb-a499-39a568c595f8', '96c7daab-59eb-4442-af01-3f5a8dbf4d33', 'b', 'No podrá actuar para evitar el abordaje.', false, '2025-09-13 13:53:10.120992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b4e949d-1da2-4d4f-9d03-7703b2928cc6', '96c7daab-59eb-4442-af01-3f5a8dbf4d33', 'c', 'Mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:10.12112+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b1492e7-6602-439a-9287-1a0b284771c7', '96c7daab-59eb-4442-af01-3f5a8dbf4d33', 'd', 'Solamente el buque que cede el paso podrá ejecutar la maniobra que mejor pueda ayudar a evitar', false, '2025-09-13 13:53:10.121251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d07ab36a-a942-4467-b46a-cdb3566fa7cd', '63cc3798-074b-4d82-9e43-791676b72324', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.121529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b85cd7b3-0390-499e-8fb3-bb7bf453f7b2', '63cc3798-074b-4d82-9e43-791676b72324', 'b', 'No podrán adelantar a los buques que los precedan.', false, '2025-09-13 13:53:10.121664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70d53ae9-b65a-4eab-9992-b55813d65c2b', '63cc3798-074b-4d82-9e43-791676b72324', 'c', 'Bajo ninguna circunstancia, se podrá fondear en dicho paso o canal.', false, '2025-09-13 13:53:10.121799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6af57541-79eb-4266-9f35-918aa52de6f9', '63cc3798-074b-4d82-9e43-791676b72324', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', true, '2025-09-13 13:53:10.12193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37e30921-6042-43ef-a640-c031a9887d9e', '74ffae3d-42f4-4082-a8a7-1c019e3ce780', 'a', 'Los buques de propulsión mecánica navegarán a cualquier velocidad, pero tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:10.122307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b998384d-c8ac-4561-ba6e-1d5dcaf61139', '74ffae3d-42f4-4082-a8a7-1c019e3ce780', 'c', 'Los buques de vela navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida.', true, '2025-09-13 13:53:10.122566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bfbdb5b-3688-49a8-b428-d22967164889', '74ffae3d-42f4-4082-a8a7-1c019e3ce780', 'd', 'Los buques que detecten a otros sólo con el radar no tomarán ninguna medida ya que el radar no nos da datos de posición fiables, y esperaremos a estar a la vista uno del otro.', false, '2025-09-13 13:53:10.122697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a18c2a8-f955-4e91-aa85-9d03d25ec97c', 'da344969-42c9-4b7b-9a5c-c3d13622676e', 'c', 'Por regla general, se considerará que existe riesgo de abordaje, si la demora de un buque que se aproxima varía en forma apreciable.', false, '2025-09-13 13:53:10.123242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96cbab04-bb80-4829-9b62-30a1e4ba018b', 'da344969-42c9-4b7b-9a5c-c3d13622676e', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-13 13:53:10.123378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf31a4e6-d534-4df7-97ff-265536d72a7c', '1e45c590-0587-4e68-9283-a563d1553ed9', 'a', 'Deberá aumentar su velocidad hasta la máxima de gobierno.', false, '2025-09-13 13:53:10.123659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('730905f0-93c4-44fe-aca0-e84e8299bbe4', '1e45c590-0587-4e68-9283-a563d1553ed9', 'b', 'Deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.123788+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90fd2e82-8734-4c4d-ad16-ae1ff1cb5ed0', '1e45c590-0587-4e68-9283-a563d1553ed9', 'c', 'No suprimirá su arrancada.', false, '2025-09-13 13:53:10.123917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94386b1f-3712-4a48-9f32-0325505a3501', 'cb1f4260-52cb-4924-8df1-6ba6f634b81f', 'a', 'Adujar.', true, '2025-09-13 13:53:10.124324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('553a3817-aae8-4164-997a-e93bad18164d', 'cb1f4260-52cb-4924-8df1-6ba6f634b81f', 'b', 'Amollar.', false, '2025-09-13 13:53:10.124455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d95b636-f37f-4386-989d-4b0212a939dc', 'cb1f4260-52cb-4924-8df1-6ba6f634b81f', 'c', 'Templar.', false, '2025-09-13 13:53:10.124583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('643bad05-a9f8-4887-99ff-4c298bfcda96', 'cb1f4260-52cb-4924-8df1-6ba6f634b81f', 'd', 'Lascar.', false, '2025-09-13 13:53:10.124712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05350e6d-f55a-4984-8908-a916661a39d7', 'e19eb0ea-b094-447d-beda-318186b2b725', 'a', 'Fase de inicial, fase variable y fase uniforme.', false, '2025-09-13 13:53:10.124989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad0ca3d8-dc4a-443d-8c97-8fb102ca4256', 'e19eb0ea-b094-447d-beda-318186b2b725', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:10.125119+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c4e1f1e-a1bf-4cd2-9d11-97779464c2c9', 'e19eb0ea-b094-447d-beda-318186b2b725', 'c', 'Fase de inicial, fase de maniobra y fase final.', false, '2025-09-13 13:53:10.125247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('124ac492-a877-4fba-a478-387b161b7a89', 'fa9aa75c-510b-4957-bf3e-d962beaef466', 'a', 'Si tras la varada ha quedado en seco, hay que apuntalarla y reflotarla en bajamar mediante remolque y escora.', false, '2025-09-13 13:53:10.125653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c5776b6-dac0-4c36-afa8-7e63b27837b2', 'fa9aa75c-510b-4957-bf3e-d962beaef466', 'd', 'Si se trata de un velero, se arriará todo el aparejo y se templará una driza desde la perilla del palo a la popa del remolque, que dará avante para provocar una escora que permita al velero dando atrás salir reflotado.', false, '2025-09-13 13:53:10.126052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47abdddd-75f2-4eb1-9345-e5d5de244311', '546aad0e-40ef-43f4-9040-76954aed7468', 'a', 'Realizar una evaluación de los daños sufridos.', false, '2025-09-13 13:53:10.126319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73ae90f7-249d-434b-81ba-5c705b1c1de9', '546aad0e-40ef-43f4-9040-76954aed7468', 'b', 'Separar los dos barcos que se hayan visto involucrados.', true, '2025-09-13 13:53:10.126448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fddbb9d-4af4-4e97-8252-5ef5e76c5d7f', '546aad0e-40ef-43f4-9040-76954aed7468', 'c', 'Proporcionar ayuda al barco que haya sufrido daños.', false, '2025-09-13 13:53:10.126576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9e28009-74d1-4175-b23a-22931d079782', '546aad0e-40ef-43f4-9040-76954aed7468', 'd', 'Comprobar si los tripulantes y personas a bordo han sufridos daños físicos.', false, '2025-09-13 13:53:10.126703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef0b99c6-469b-4aa7-9c21-2912a293d616', 'b8efbb44-dff2-4bdd-8b58-7f012b4f344d', 'a', 'Instantes previos al abandono de la embarcación, es muy recomendable su uso. De esta forma se consigue señalar el lugar del abandono y podremos ser avistados desde otra embarcación, unidad aérea o desde la costa cercana.', false, '2025-09-13 13:53:10.127085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('224647f9-568c-4938-9d7c-92d459efdc6c', 'b8efbb44-dff2-4bdd-8b58-7f012b4f344d', 'b', 'Las bengalas se deben encender por barlovento, prácticamente en vertical y con el brazo alargado y hacia arriba.', false, '2025-09-13 13:53:10.127214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7a5382c-621b-4ed5-bbc5-f6c3c727fb57', 'b8efbb44-dff2-4bdd-8b58-7f012b4f344d', 'c', 'Para su uso es recomendable equiparse con guantes y gafas de seguridad y sujetar la bengala con una sola mano por la parte inferior de esta o su empuñadura, con la flecha indicadora hacia arriba.', true, '2025-09-13 13:53:10.127343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f0b67e1-5c55-4082-8ffb-1acb93d1dfcd', 'b8efbb44-dff2-4bdd-8b58-7f012b4f344d', 'd', 'Debe utilizarse por el día ya que es más eficaz, si cabe, que los botes de humo o cohetes, por ser más visible a gran distancia. Meteorología', false, '2025-09-13 13:53:10.127475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55282028-285e-4e7f-9e53-44ad9a6db43f', '9e4d6e7b-3582-4127-995e-54c1a5376706', 'a', 'La página web de AEMET.', false, '2025-09-13 13:53:10.127745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef935e73-6164-4e4c-abdb-896086605643', '9e4d6e7b-3582-4127-995e-54c1a5376706', 'b', 'La página web de la Dirección General de la Marina Mercante.', true, '2025-09-13 13:53:10.127887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ec02e69-2fdd-470d-bb56-e3125faf385e', '9e4d6e7b-3582-4127-995e-54c1a5376706', 'c', 'La proporcionada por el club náutico.', false, '2025-09-13 13:53:10.128017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25de9ce0-0294-4b1d-8111-6b73847c9001', '9e4d6e7b-3582-4127-995e-54c1a5376706', 'd', 'La proporcionada por el puerto deportivo.', false, '2025-09-13 13:53:10.128152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95381663-7799-4551-92e6-1f89d48b1dd7', 'da344969-42c9-4b7b-9a5c-c3d13622676e', 'b', 'En caso de abrigarse alguna duda respecto a si existe riesgo de abordaje, se considerará que no existe.', false, '2025-09-13 13:53:10.12311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb4b4b9c-cd59-41c6-b884-ecade92954be', 'fa9aa75c-510b-4957-bf3e-d962beaef466', 'b', 'Si la varada se produjo en fondo rocoso, y no se detectan vías de agua, se dará rápidamente avante.', false, '2025-09-13 13:53:10.125792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51b2d943-8706-45e9-8ced-b9a3084a98f0', 'fa9aa75c-510b-4957-bf3e-d962beaef466', 'c', 'Si la varada es en fondo fangoso, hay que trasladar pesos para cambiar el asiento, mover lateralmente a uno y otro lado la embarcación para abrir la cama y esperar el mejor momento de la marea.', true, '2025-09-13 13:53:10.125923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('369798be-455e-4221-befb-45379f7326c7', '1e45c590-0587-4e68-9283-a563d1553ed9', 'd', 'Navegará con extremada precaución y caerá a estribor.', false, '2025-09-13 13:53:10.124053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c760fd98-2c37-4f44-a550-853da357e6c5', 'da344969-42c9-4b7b-9a5c-c3d13622676e', 'a', 'Se evitarán las suposiciones basadas en información insuficiente, especialmente la obtenida por radar.', true, '2025-09-13 13:53:10.122978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4624662a-c0e9-4838-b3a7-989c20dcd06d', 'e19eb0ea-b094-447d-beda-318186b2b725', 'd', 'Fase de maniobra, fase variable y fase final.', false, '2025-09-13 13:53:10.125375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0956d4ac-6123-4a34-99ac-9836fed8b313', '5d31776c-4ba0-4150-aa36-7afbda0f7826', 'a', 'La fuerza de Coriolis.', false, '2025-09-13 13:53:10.128424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('594631b1-5ee0-41e3-b326-b4ce9e31590b', '5d31776c-4ba0-4150-aa36-7afbda0f7826', 'b', 'La fuerza de gravedad.', true, '2025-09-13 13:53:10.128561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37fc0213-715f-492c-b1ee-4d9f1becf0c0', '5d31776c-4ba0-4150-aa36-7afbda0f7826', 'c', 'La fuerza intermolecular.', false, '2025-09-13 13:53:10.128694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dec7f3c-744e-4517-a765-18813f520713', '5d31776c-4ba0-4150-aa36-7afbda0f7826', 'd', 'La fuerza de rozamiento.', false, '2025-09-13 13:53:10.128841+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ba86df3-2206-40b4-8e34-1aec1d353bc9', '24227af7-6b9d-406e-b8ab-ad98004f8a9e', 'a', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:10.129132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96e77384-9714-4e72-9ebc-c6a233642434', '24227af7-6b9d-406e-b8ab-ad98004f8a9e', 'b', 'La temperatura aparece como una propiedad termodinámica y no en función de las propiedades de una sustancia.', false, '2025-09-13 13:53:10.129269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('156ccf4f-89f1-4140-a85d-f0c574e0c57c', '24227af7-6b9d-406e-b8ab-ad98004f8a9e', 'c', 'Para indicar la temperatura de un cuerpo se usan escalas arbitrarias de referencia, entre las que se encuentra la escala Celsius.', false, '2025-09-13 13:53:10.129405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1be24363-2df5-4e0c-bd1d-1f0f40797b49', '24227af7-6b9d-406e-b8ab-ad98004f8a9e', 'd', 'Dos cuerpos en equilibrio térmico deben estar a la misma presión y temperatura.', true, '2025-09-13 13:53:10.129539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9d0e5fc-90d3-4d49-b7ab-88d336f2aa35', '4b87cba0-24e4-4369-9667-46a3d73e99fb', 'a', 'Ventolina.', false, '2025-09-13 13:53:10.12982+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8b3b083-0a4e-4448-b437-91c618254cfc', '4b87cba0-24e4-4369-9667-46a3d73e99fb', 'b', 'Fetch.', false, '2025-09-13 13:53:10.129955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfd46a42-c3da-443a-9284-d70ad4b3d306', '4b87cba0-24e4-4369-9667-46a3d73e99fb', 'c', 'Virazón.', true, '2025-09-13 13:53:10.130087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c2be202-f7b2-415f-b408-b849b5cb91c5', 'd9e1b3c5-97e3-40d2-b352-6bf09a45828c', 'b', 'Es la línea que une dos puntos de la costa situados uno a proa y otro a popa del buque.', false, '2025-09-13 13:53:10.13063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dfd12fb-7051-49eb-9c95-4e85a8e6310c', 'd9e1b3c5-97e3-40d2-b352-6bf09a45828c', 'c', 'Es una línea de posición que permite calcular la corrección total.', true, '2025-09-13 13:53:10.130774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f092c219-6c4a-4a0e-bfac-0a11ec247e40', 'd9e1b3c5-97e3-40d2-b352-6bf09a45828c', 'd', 'Es una línea de posición en la que el buque se encuentra sobre la línea que une dos puntos de la costa y entre ellos.', false, '2025-09-13 13:53:10.130912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('718fbe34-624e-4d54-bc92-397e02ab2216', '913642b1-ed82-4cd0-a672-2cf6014dc486', 'a', 'El norte verdadero hasta el norte magnético.', false, '2025-09-13 13:53:10.1312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('104dbd17-eb63-4c0d-bd0b-6d69bf9a1ceb', '913642b1-ed82-4cd0-a672-2cf6014dc486', 'b', 'El norte magnético hasta el norte de aguja.', false, '2025-09-13 13:53:10.131333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('709665bf-ec3e-46b6-9833-5bde1db91814', '913642b1-ed82-4cd0-a672-2cf6014dc486', 'c', 'El norte geográfico hasta el norte magnético.', false, '2025-09-13 13:53:10.131587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1658ed81-7078-4127-98b8-3b61f4f7b21c', '913642b1-ed82-4cd0-a672-2cf6014dc486', 'd', 'El norte verdadero hasta el norte de aguja.', true, '2025-09-13 13:53:10.131717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cb42625-c32a-4d01-bb61-565d1f0d2436', '3f3e942d-6955-4362-9c7d-9284d90e0e09', 'a', 'Es la relación entre la velocidad aparente y la velocidad por corredera.', false, '2025-09-13 13:53:10.13199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c6e1b3f-f35f-4c70-bfac-b56fc11626aa', '3f3e942d-6955-4362-9c7d-9284d90e0e09', 'b', 'Es la relación entre la distancia verdadera y la velocidad por corredera.', false, '2025-09-13 13:53:10.132122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b050bf3a-598e-4c2c-846d-3c8518b2c941', '3f3e942d-6955-4362-9c7d-9284d90e0e09', 'c', 'Se utiliza para el cálculo de la distancia verdadera navegada.', true, '2025-09-13 13:53:10.132252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('841ab2e5-19cc-4c20-a260-5aeb5aa1b873', '3f3e942d-6955-4362-9c7d-9284d90e0e09', 'd', 'Se utiliza para el cálculo de la velocidad por corredera y es constante para todos los buques.', false, '2025-09-13 13:53:10.132383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0e35e7c-a892-49f0-91d6-ade5e90d8a12', '4d88206d-bbd5-4d3c-824a-4559968aeb33', 'a', 'Es la hora del puerto de salida y se utiliza para calcular la latitud.', false, '2025-09-13 13:53:10.132654+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8dcf8648-d9d3-4b65-89da-af6e7533c8ad', '4d88206d-bbd5-4d3c-824a-4559968aeb33', 'b', 'Es la hora por la que se guían las actividades a bordo y es recomendable ajustarla a medida que se cambia de huso.', true, '2025-09-13 13:53:10.132797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('319c28c5-8eda-4250-b3a8-f3b19f4f53e3', '4d88206d-bbd5-4d3c-824a-4559968aeb33', 'c', 'Siempre es igual a la Hora Oficial.', false, '2025-09-13 13:53:10.13294+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1932ef2d-1716-4134-b805-3c1fd5f9f37f', '4d88206d-bbd5-4d3c-824a-4559968aeb33', 'd', 'Siempre es igual a la Hora Legal.', false, '2025-09-13 13:53:10.133073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92d31e47-618c-42a0-9264-770fefe621b6', '313e8521-3495-4780-acda-863a11258ea9', 'a', 'Las líneas de posición deben cortarse con un ángulo próximo a 90º.', true, '2025-09-13 13:53:10.133354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e10951a6-5f54-4342-a2f6-cca68d38f328', '313e8521-3495-4780-acda-863a11258ea9', 'b', 'Las líneas isobáticas son más fiables que las enfilaciones.', false, '2025-09-13 13:53:10.133485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43699242-0437-4ceb-aeb3-1be74b1ab16f', '313e8521-3495-4780-acda-863a11258ea9', 'c', 'La situación del barco es la intersección de al menos tres líneas de posición.', false, '2025-09-13 13:53:10.133616+00');
