INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86e9a7b4-815b-4b77-89bd-22c2b732b2b7', '52327466-30b4-4de1-8699-ac24874119c5', 'd', '149,5º DE TRANSPORTES, MOVILIDAD                                                                            Y AGENDA URBANA Y AGENDA URBANA                                                                                      SECRETARÍA GENERAL DE TRANSPORTES Y MOVILIDAD PNB LIBERADO Código de Test 02 Maniobra y navegación.', false, '2025-09-13 13:53:10.136552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1677035f-365a-4a31-9f78-a94cb21dfd5d', 'a3e5a90c-5fd2-4f3f-9947-37802a82ded4', 'a', 'Es la mínima velocidad que debe desarrollar la embarcación sin que pierda el gobierno, permitiéndole efectuar una maniobra para que la proa o popa caigan a una determinada banda.', false, '2025-09-13 13:53:10.137153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c96c682-0c47-4cf9-bb44-6aea60b3106f', 'a3e5a90c-5fd2-4f3f-9947-37802a82ded4', 'b', 'Es la marcha que lleva el barco, que puede ser avante o atrás. Se dice que el barco no tiene arrancada cuando está totalmente parado.', true, '2025-09-13 13:53:10.137285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce5ae469-46c5-4708-9ea9-de45daa11a50', 'a3e5a90c-5fd2-4f3f-9947-37802a82ded4', 'c', 'Es el estado con el que se define a un buque cuando está completamente parado, pero con el motor en funcionamiento.', false, '2025-09-13 13:53:10.137418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffc2a80e-ca66-46c6-a723-f70d6fb8b16e', 'a3e5a90c-5fd2-4f3f-9947-37802a82ded4', 'd', 'Es la velocidad inicial del buque, medida siempre en marcha avante. 29 “Adujar” consiste en:', false, '2025-09-13 13:53:10.137549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ced98134-7819-43f1-9f26-4f39257267c3', '09ea1395-9e8c-404c-9524-5896f69a8de2', 'a', 'Recoger, formando vueltas en espiral, un cabo, cable o cadena, a fin de evitar que forme cocas y facilitar su uso inmediato.', true, '2025-09-13 13:53:10.137842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca65868e-577c-4e49-9a52-748d2c23a56d', '09ea1395-9e8c-404c-9524-5896f69a8de2', 'b', 'Dar un medio nudo y encima otro hecho al revés, uniendo dos cabos por sus chicotes.', false, '2025-09-13 13:53:10.13797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f43d252-3613-4233-aa54-4bc5a71cbcc7', '09ea1395-9e8c-404c-9524-5896f69a8de2', 'c', 'Amarrar un cabo a una bita o cornamusa sujetándolo en forma de ocho.', false, '2025-09-13 13:53:10.138107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9c500c6-a75d-4f19-be96-0cac99a42bf7', '09ea1395-9e8c-404c-9524-5896f69a8de2', 'd', 'Es sinónimo de trincar, y se refiere a sujetar una amarra de forma que no se mueva. Emergencias en la mar.', false, '2025-09-13 13:53:10.138237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('657dd974-bad7-4d63-a692-5fb5e72c81e7', '277f1ed8-4216-40d0-9491-98343e214c12', 'a', 'Si descubre agua en la sentina, se pondrán en marcha de inmediato las bombas de achique.', false, '2025-09-13 13:53:10.138644+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58ed36aa-ab60-428d-a7fa-05130f130f64', '277f1ed8-4216-40d0-9491-98343e214c12', 'b', 'Uno de los puntos de mayor riesgo donde puede tener lugar una vía de agua es la hélice.', true, '2025-09-13 13:53:10.138786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('650da96a-9126-4203-858b-1b5d05f234d3', '8daeaab8-1964-469f-bca0-9ca37ea1c6a4', 'b', 'l=36°08,4´N; L=005°55,4´W.', false, '2025-09-13 13:53:10.13417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec587f6c-6658-491f-939c-fbe5e46c0823', '8daeaab8-1964-469f-bca0-9ca37ea1c6a4', 'c', 'l=36°07,7´N; L=005°54,2´W.', true, '2025-09-13 13:53:10.1343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1f15be4-573b-40db-b3d3-85bf93bab5cf', 'b0f23977-e8e8-44f0-a773-f97474e49973', 'a', 'l=36º 12´N L=006º 10,4´W.', false, '2025-09-13 13:53:10.134707+00');
