INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67b952aa-85f1-4cc0-9711-e74a69ff9280', '4b87cba0-24e4-4369-9667-46a3d73e99fb', 'd', 'Bonancible.', false, '2025-09-13 13:53:10.13022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8d7cd0b-5734-4053-a9dc-67a560b478ae', '8daeaab8-1964-469f-bca0-9ca37ea1c6a4', 'a', 'l=36°08,5´N; L=005°54,8´W.', false, '2025-09-13 13:53:10.134038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a76b41e2-b5eb-4bbd-8c24-f570c4683873', '313e8521-3495-4780-acda-863a11258ea9', 'd', 'La enfilación puede ser imprecisa si se cometen errores en el desvío.', false, '2025-09-13 13:53:10.133747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0f0a623-d921-4553-afc7-0e703474d87e', '277f1ed8-4216-40d0-9491-98343e214c12', 'c', 'A la cuña cónica de madera para tapar vías de agua cuyo orificio de entrada tiene forma circular se le denomina espiche.', false, '2025-09-13 13:53:10.138917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ba3a137-85b8-4bef-8f79-66351e5b6ca0', '277f1ed8-4216-40d0-9491-98343e214c12', 'd', 'Ante la certeza de una vía de agua, se empleará la bomba de refrigeración del motor para achicar el agua si ésta tiene la tubería de aspiración próxima al compartimento inundado.', false, '2025-09-13 13:53:10.139065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24953c13-b15a-446f-8308-e21d96b94e29', '59b690f2-8980-4e92-b01d-86b39bdee1a9', 'b', 'Si tras la varada ha quedado en seco, hay que apuntalarla y reflotarla en bajamar mediante remolque y escora.', false, '2025-09-13 13:53:10.139476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('846ba73f-4698-43bd-a7f3-941f20caa8d6', '59b690f2-8980-4e92-b01d-86b39bdee1a9', 'd', 'Si se trata de un velero, se arriará todo el aparejo y se templará una driza desde la perilla del palo a la popa del remolque, que dará avante para provocar una escora que permita al velero dando atrás salir reflotado.', false, '2025-09-13 13:53:10.139741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ecb5f4c-3aec-4860-860f-1b5a7243d56f', '4f2e908b-d3aa-4078-94c9-523c5de52bc3', 'a', 'Es la maniobra consistente en poner la embarcación a un rumbo tal que el foco principal del incendio quede a barlovento para evitar la propagación de un incendio.', false, '2025-09-13 13:53:10.140022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4df5d320-9765-4448-a23a-1c75a24a7968', '4f2e908b-d3aa-4078-94c9-523c5de52bc3', 'c', 'Cortar el paso al aire cerrando todas las ventilaciones posibles como portillos, escotillas, puertas y lumbreras, de tal manera que no circule el aire y que no avive la llama.', false, '2025-09-13 13:53:10.140283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e69aec99-45af-4b70-8a46-f3ff02f8883d', '4f2e908b-d3aa-4078-94c9-523c5de52bc3', 'd', 'Es la maniobra que consiste en poner la embarcación en la misma dirección que sopla el viento y a la misma velocidad, para que el viento aparente sea cero. Meteorología', true, '2025-09-13 13:53:10.140539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ccfe73d-88cb-4fc4-a662-6624ab67d0aa', '842c1da5-f098-4ed9-8a7b-89e089bc79bc', 'a', 'Su intersección señala los centros de borrascas y anticiclones.', false, '2025-09-13 13:53:10.140828+00');
