INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bebb43e1-7be5-40bb-97ee-3bab9aa3c151', '5a35c66c-9300-40b7-9389-3252821e0e9f', 'b', 'También se conoce como escala Fahrenheit.', false, '2025-09-13 13:53:10.143081+00');
