INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1451c6af-429b-492b-a50b-4613af43c487', '1c4bec8a-a001-44ad-b1b1-37e56da1a5bd', 'a', 'Generalmente hay dos pleamares y dos bajamares en un día lunar.', false, '2025-09-13 13:53:10.144535+00');
