INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9829b848-78b2-42b2-bc2d-02232dc4ea92', 'd4b5419e-8a50-4014-95a5-a8c4b6465dfd', 'a', 'Es la mínima velocidad que debe desarrollar la embarcación sin que pierda el gobierno, permitiéndole efectuar una maniobra para que la proa o popa caigan a una determinada banda.', false, '2025-09-13 13:53:10.150596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ad0fcb9-3935-46bc-89b7-8a2b49f21e19', 'd4b5419e-8a50-4014-95a5-a8c4b6465dfd', 'b', 'Es la marcha que lleva el barco, que puede ser avante o atrás. Se dice que el barco no tiene arrancada cuando está totalmente parado.', true, '2025-09-13 13:53:10.150746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28995aaa-cbb5-42c8-92cb-396a18d2789c', 'd4b5419e-8a50-4014-95a5-a8c4b6465dfd', 'c', 'Es el estado con el que se define a un buque cuando está completamente parado, pero con el motor en funcionamiento.', false, '2025-09-13 13:53:10.150928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3f67bdc-15b3-47cf-b478-987a3897d8a6', 'd4b5419e-8a50-4014-95a5-a8c4b6465dfd', 'd', 'Es la velocidad inicial del buque, medida siempre en marcha avante. 29 “Adujar” consiste en:', false, '2025-09-13 13:53:10.151081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e4991b6-ae74-45ff-9670-f7c7c6b95bb6', 'c78ac6b2-3427-4fd2-8d1d-5c7c8e42ff7c', 'a', 'Recoger, formando vueltas en espiral, un cabo, cable o cadena, a fin de evitar que forme cocas y facilitar su uso inmediato.', true, '2025-09-13 13:53:10.151377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2a027d5-3f8d-405f-8092-fe40cbede336', 'c78ac6b2-3427-4fd2-8d1d-5c7c8e42ff7c', 'b', 'Dar un medio nudo y encima otro hecho al revés, uniendo dos cabos por sus chicotes.', false, '2025-09-13 13:53:10.151514+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fef7282-b773-4df7-bbfc-41e627b62dca', 'c78ac6b2-3427-4fd2-8d1d-5c7c8e42ff7c', 'c', 'Amarrar un cabo a una bita o cornamusa sujetándolo en forma de ocho.', false, '2025-09-13 13:53:10.151646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be426364-af39-466d-9b67-0387722e7526', 'c78ac6b2-3427-4fd2-8d1d-5c7c8e42ff7c', 'd', 'Es sinónimo de trincar, y se refiere a sujetar una amarra de forma que no se mueva. Emergencias en la mar.', false, '2025-09-13 13:53:10.151784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a625168a-d70d-410c-9e5a-885f603ca387', 'e55ed76f-7ef6-489e-af4c-141b79412386', 'a', 'Si descubre agua en la sentina, se pondrán en marcha de inmediato las bombas de achique.', false, '2025-09-13 13:53:10.152083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b39d054-806c-4a3d-9d88-7c3ea05c548f', 'e55ed76f-7ef6-489e-af4c-141b79412386', 'b', 'Uno de los puntos de mayor riesgo donde puede tener lugar una vía de agua es la hélice.', true, '2025-09-13 13:53:10.152225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1572b9fe-ccb9-4556-be68-1713e7bb3e3b', 'e55ed76f-7ef6-489e-af4c-141b79412386', 'c', 'A la cuña cónica de madera para tapar vías de agua cuyo orificio de entrada tiene forma circular se le denomina espiche.', false, '2025-09-13 13:53:10.152376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80ef56b5-781b-42d8-955b-97c849267a4c', 'e55ed76f-7ef6-489e-af4c-141b79412386', 'd', 'Ante la certeza de una vía de agua, se empleará la bomba de refrigeración del motor para achicar el agua si ésta tiene la tubería de aspiración próxima al compartimento inundado.', false, '2025-09-13 13:53:10.152524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93250825-a6d1-4443-b061-57a79b46730d', '76d31edf-99e9-44e9-96a1-02a5b2ae657f', 'a', 'Es la maniobra consistente en poner la embarcación a un rumbo tal que el foco principal del incendio quede a barlovento para evitar la propagación de un incendio.', false, '2025-09-13 13:53:10.152817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f92df771-36b8-4237-ad44-12255f7c2498', '76d31edf-99e9-44e9-96a1-02a5b2ae657f', 'c', 'Cortar el paso al aire cerrando todas las ventilaciones posibles como portillos, escotillas, puertas y lumbreras, de tal manera que no circule el aire y que no avive la llama.', false, '2025-09-13 13:53:10.153088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5234bb95-2358-4ec9-aee1-fee57ecf64e4', '76d31edf-99e9-44e9-96a1-02a5b2ae657f', 'd', 'Es la maniobra que consiste en poner la embarcación en la misma dirección que sopla el viento y a la misma velocidad, para que el viento aparente sea cero.', true, '2025-09-13 13:53:10.153225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01687cae-ce5c-443b-83c1-303826fa94c1', '44efe46e-e4eb-4b89-b18e-a00c802c091f', 'b', 'Si tras la varada ha quedado en seco, hay que apuntalarla y reflotarla en bajamar mediante remolque y escora.', false, '2025-09-13 13:53:10.153638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f048916d-fa84-4463-9ef7-10360e075393', '44efe46e-e4eb-4b89-b18e-a00c802c091f', 'd', 'Si se trata de un velero, se arriará todo el aparejo y se templará una driza desde la perilla del palo a la popa del remolque, que dará avante para provocar una escora que permita al velero dando atrás salir reflotado. Meteorología', false, '2025-09-13 13:53:10.153928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('209bdba6-d505-4bba-8a6f-7e4e82959d8a', '8fb483fd-6820-4b14-9bc2-1961a9977aac', 'a', 'Su intersección señala los centros de borrascas y anticiclones.', false, '2025-09-13 13:53:10.154312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9cb26ba-3543-42a6-a765-708c7ec6ca44', '8fb483fd-6820-4b14-9bc2-1961a9977aac', 'b', 'Unen puntos con igual valor de temperatura en una superficie dada.', false, '2025-09-13 13:53:10.154449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9517a761-a245-4db5-a516-5c37eed522e8', '8fb483fd-6820-4b14-9bc2-1961a9977aac', 'c', 'La proximidad entre ellas indica variaciones de presión más bruscas.', true, '2025-09-13 13:53:10.15458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6ee2e25-3718-424c-b87f-7c259ad4e5d7', '8fb483fd-6820-4b14-9bc2-1961a9977aac', 'd', 'Son líneas paralelas y concéntricas.', false, '2025-09-13 13:53:10.154711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4efa841-26aa-4a28-9161-3c57f4e1e03d', '05028e76-f693-4dde-8245-33528b6c7072', 'a', '1023 hPa.', false, '2025-09-13 13:53:10.154992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d17dbe1f-0c3e-4d93-9738-c2a37e2b59df', '05028e76-f693-4dde-8245-33528b6c7072', 'b', '1013 hPa.', true, '2025-09-13 13:53:10.155126+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e508a86c-3f01-4e26-a0ab-7a475ce230bb', '05028e76-f693-4dde-8245-33528b6c7072', 'c', '1 milibar.', false, '2025-09-13 13:53:10.15526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('500d4aa7-ed9c-4675-9ded-d3fc55c6cb6a', '05028e76-f693-4dde-8245-33528b6c7072', 'd', '1023 milibares.', false, '2025-09-13 13:53:10.155423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f1c02c8-ef3b-4be8-9b58-db686bdc8c70', '49f60cca-e6a6-43f3-9e69-edcc1e658c39', 'a', 'Las cápsulas aneroides emplean agua destilada para medir.', false, '2025-09-13 13:53:10.155729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b5e6847-1bef-4981-ab07-7ede2706926e', '49f60cca-e6a6-43f3-9e69-edcc1e658c39', 'b', 'Las cápsulas aneroides emplean mercurio para medir.', false, '2025-09-13 13:53:10.155874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d45c1ab-a6f1-4dbf-a45b-96e5a74f7567', '49f60cca-e6a6-43f3-9e69-edcc1e658c39', 'c', 'Las cápsulas aneroides emplean el vacío parcial para medir.', true, '2025-09-13 13:53:10.156009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2772349c-bdaa-4662-8736-02ed2190bdb5', '49f60cca-e6a6-43f3-9e69-edcc1e658c39', 'd', 'Calcula la presión a partir de la velocidad del viento.', false, '2025-09-13 13:53:10.156142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bb0962b-21ec-4c61-b518-2b5c93e4c150', '69982f6d-28df-4411-9345-2b81e93694fd', 'b', 'También se conoce como escala Fahrenheit.', false, '2025-09-13 13:53:10.156563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae43ab5d-01f0-4de8-86fd-8e8574b61073', '69982f6d-28df-4411-9345-2b81e93694fd', 'c', 'Para medir la temperatura de un cuerpo se utiliza esta escala arbitraria de referencia.', true, '2025-09-13 13:53:10.156695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60fde1f0-7012-4d52-ae64-cff2bf23b3f3', '69982f6d-28df-4411-9345-2b81e93694fd', 'd', 'Sólo permite medir la temperatura de cuerpos líquidos, por eso se emplea el mercurio. Teoría de la navegación.', false, '2025-09-13 13:53:10.156836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fb1f2ca-5ff6-453a-89b0-1ca7f3c1f2ba', '04f1a331-3b60-4b32-b154-9fd81a0501f9', 'a', 'Generalmente hay dos pleamares y dos bajamares en un día lunar.', false, '2025-09-13 13:53:10.157135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad5a26cc-6c1e-4889-a3ee-46247efd384e', '04f1a331-3b60-4b32-b154-9fd81a0501f9', 'b', 'En las mareas vivas el Sol, la Luna y la Tierra forman un ángulo recto.', true, '2025-09-13 13:53:10.157271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13e4d52a-4616-4b84-8897-e26047674ffe', '04f1a331-3b60-4b32-b154-9fd81a0501f9', 'c', 'En las mareas vivas el Sol, la Luna y la Tierra forman un ángulo plano.', false, '2025-09-13 13:53:10.157405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1b78e5f-33c4-4425-a3bb-a2fcb63d3cf7', '04f1a331-3b60-4b32-b154-9fd81a0501f9', 'd', 'Entre dos pleamares sucesivas transcurren cerca de 12 h 30 minutos.', false, '2025-09-13 13:53:10.157538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f57a377-960c-472d-b6ff-3f527e8d404f', 'c31d71ac-e747-4e6b-9d60-f817a9d0b117', 'a', 'Rumbo.', false, '2025-09-13 13:53:10.157815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c405c6b-ad7a-480f-9a5c-e711a84fe8ef', 'c31d71ac-e747-4e6b-9d60-f817a9d0b117', 'b', 'Demora.', false, '2025-09-13 13:53:10.157947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a3b6f3d-d050-48f4-8c9a-4277ed89b3a6', 'c31d71ac-e747-4e6b-9d60-f817a9d0b117', 'c', 'Meridiano.', false, '2025-09-13 13:53:10.158078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1aaa686-a3ff-4bc9-8e51-1af1f1069dbf', 'c31d71ac-e747-4e6b-9d60-f817a9d0b117', 'd', 'Marcación.', true, '2025-09-13 13:53:10.158209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea8c3062-b66e-4d4e-b445-b056183ac2c1', '7ce4e739-c8c3-45da-ab9e-6d8fd58f688e', 'a', 'Los rumbos se expresan mediante tres cifras en cuadrantal.', false, '2025-09-13 13:53:10.158484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a89463e-124b-4ecc-8ec4-7bcc7595fc39', '7ce4e739-c8c3-45da-ab9e-6d8fd58f688e', 'b', 'Los rumbos expresados en cuadrantal en el cuarto cuadrante tienen signo negativo.', true, '2025-09-13 13:53:10.158618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0b5a8a0-dc42-411d-9ef3-dfa0115a76c2', '08cb2faf-79b0-4b19-aa58-bc0a38beb81f', 'd', '02 h 30 m del día 11 de abril.', false, '2025-09-13 13:53:10.244448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('036b92da-3184-401f-8797-149a1f4f119b', '69982f6d-28df-4411-9345-2b81e93694fd', 'a', 'La temperatura estará siempre en esta escala entre.', false, '2025-09-13 13:53:10.156425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bd38b0f-39b2-4016-a8a4-ed64a22c8dc5', '44efe46e-e4eb-4b89-b18e-a00c802c091f', 'c', 'Si la varada se produjo en fondo rocoso, y no se detectan vías de agua, se dará rápidamente avante.', false, '2025-09-13 13:53:10.153789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc057126-7812-44d9-8267-b4537e5ba338', '7ce4e739-c8c3-45da-ab9e-6d8fd58f688e', 'c', 'El sistema cuadrantal expresa los rumbos entre 000º y 180º.', false, '2025-09-13 13:53:10.158749+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28cad835-1101-47e8-bf24-846e809bf67d', '7ce4e739-c8c3-45da-ab9e-6d8fd58f688e', 'd', 'Todos los rumbos en circular son negativos.', false, '2025-09-13 13:53:10.158901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23f2dddc-b561-4d34-aad3-ebfa8731aec4', '073ef97b-f325-4c4b-8b27-0dcb918cbd6c', 'a', 'Cada segundo equivale a una milla.', false, '2025-09-13 13:53:10.159201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc3bf753-14fb-48e2-a5ac-bebd177974c2', '073ef97b-f325-4c4b-8b27-0dcb918cbd6c', 'b', 'Mide ángulos, y por tanto no guarda relación con las distancias.', false, '2025-09-13 13:53:10.159375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbd16cac-c29e-40bc-89c1-5f49016d5cbd', '073ef97b-f325-4c4b-8b27-0dcb918cbd6c', 'c', 'Cada minuto equivale a una milla.', true, '2025-09-13 13:53:10.159653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b067c676-da04-45c1-933c-5d41a4f1a709', '073ef97b-f325-4c4b-8b27-0dcb918cbd6c', 'd', 'Los valores obtenidos tienen que ser corregidos utilizando la tablilla de desvíos.', false, '2025-09-13 13:53:10.159795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7948e25-b6b4-49b2-9b7e-d54a2753660c', '92c98928-76ac-4bf2-ba97-2d07765a6dc7', 'a', 'Es el ángulo que forma la visual dirigida a un objeto con la línea Norte-Sur.', false, '2025-09-13 13:53:10.160094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7306d0e-ab2b-4ded-9d6e-60d1b7c49725', '92c98928-76ac-4bf2-ba97-2d07765a6dc7', 'b', 'La demora de aguja se obtiene restando la corrección total a la demora verdadera.', false, '2025-09-13 13:53:10.160228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ca907c3-1d7a-4de6-b74d-2f316b9a19a0', '92c98928-76ac-4bf2-ba97-2d07765a6dc7', 'c', 'Es el ángulo que forma la visual dirigida a un objeto con el rumbo verdadero.', true, '2025-09-13 13:53:10.160366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d8f66af-9f04-4e3e-9a43-30faf6f57002', '4bf14b74-a62a-4e4e-ae9f-b44406ef3acb', 'd', 'Ra=319º; l= 35º 56,4´N; L=005º 39,2´W', true, '2025-09-13 13:53:10.161205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ac113fe-ad13-443a-8502-0bbe844bb773', '764a77b0-bff7-4f63-8f9b-0d9f907acc03', 'a', '09,86 m.', false, '2025-09-13 13:53:10.161484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2812f3b5-42fc-47e8-93fe-cfff6589240c', '764a77b0-bff7-4f63-8f9b-0d9f907acc03', 'b', '10,36 m.', false, '2025-09-13 13:53:10.161634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3809744-af20-40bf-a4ee-071a74d3c037', '764a77b0-bff7-4f63-8f9b-0d9f907acc03', 'c', '10,41 m.', false, '2025-09-13 13:53:10.161789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('877e056c-5743-4a93-b51d-38e7483308ec', '764a77b0-bff7-4f63-8f9b-0d9f907acc03', 'd', '10,31 m.', true, '2025-09-13 13:53:10.161931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b4e8ddd-24d7-479b-ad06-ae496b52f42a', '90a8e137-24ec-48f9-a60f-d9316f023464', 'd', 'l=36º 12´N; L=005º 12,8´W', false, '2025-09-13 13:53:10.162615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f39e762-0597-4051-a25b-681e27cce762', '17b61b2a-aa47-4082-9726-d9ed991c0f9d', 'a', '029°', false, '2025-09-13 13:53:10.162909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('504487cf-4548-4a72-870a-402a3c7383b4', '17b61b2a-aa47-4082-9726-d9ed991c0f9d', 'b', '025°', false, '2025-09-13 13:53:10.163046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fab9f38-9c6a-40ac-9d88-77d015aa58ac', '17b61b2a-aa47-4082-9726-d9ed991c0f9d', 'c', '021°', false, '2025-09-13 13:53:10.163173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc86fd2f-8b47-4409-9d48-ac23a769f5e8', '17b61b2a-aa47-4082-9726-d9ed991c0f9d', 'd', '027° DE TRANSPORTES, MOVILIDAD                                                                         DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                   Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 02 Nomenclatura náutica.', true, '2025-09-13 13:53:10.163304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a55bc627-89d7-407a-807e-0e223cf52a7e', '12bd5534-8465-4af7-a0af-04644daf2d52', 'a', 'El barbotén es la pieza del molinete con forma de corona y muescas o moldes donde se encastran o acoplan los eslabones de la cadena según se va cobrando el ancla.', false, '2025-09-13 13:53:10.163881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff239591-8dbb-4c7c-b4a4-048a93b829cd', '12bd5534-8465-4af7-a0af-04644daf2d52', 'b', 'Si se deja libre el eje, soltando su embrague, se arria el ancla.', false, '2025-09-13 13:53:10.16402+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26f54b5d-f709-4d13-b88d-d477ee81baf7', '12bd5534-8465-4af7-a0af-04644daf2d52', 'c', 'Es un gran cabrestante de eje horizontal o vertical destinado a echar o levar anclas de forma rápida, sencilla y fiable.', false, '2025-09-13 13:53:10.164157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46b7e0ef-e04a-4935-a76d-eaa3d93ddab2', '12bd5534-8465-4af7-a0af-04644daf2d52', 'd', 'Es una maquinilla con eje de giro horizontal que permite levar el ancla.', true, '2025-09-13 13:53:10.164288+00');
