INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea150f29-b4d3-43c5-a351-62101db3da1a', '8eae9b20-6092-4bce-9046-c6bf778c7b44', 'a', 'El tenedero es la superficie del fondo marino donde se afirma el ancla, siendo los mejores los de fango duro, arena fangosa y arena dura.', false, '2025-09-13 13:53:10.167321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84f9dc8e-b23e-49d2-aeb0-2bfb5ab10b59', '8eae9b20-6092-4bce-9046-c6bf778c7b44', 'b', 'El orinque es un cabo fino que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder levar y recuperar el ancla o señalizar la vertical del ancla en caso de no poder', false, '2025-09-13 13:53:10.167452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f952da82-a1f6-4020-96d6-44357eebaddf', '8eae9b20-6092-4bce-9046-c6bf778c7b44', 'c', 'Un barco bornea cuando da vueltas alrededor del ancla por acción del viento o la corriente.', false, '2025-09-13 13:53:10.167583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e064615-7418-40cd-93be-78e8524181d6', '8eae9b20-6092-4bce-9046-c6bf778c7b44', 'd', 'En la maniobra de levar ancla, se dará un poco atrás mientras cobramos elemento de fondeo hasta que el ancla se desclave del fondo, momento en el que tomaremos arrancada dando avante.', true, '2025-09-13 13:53:10.167711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c542d48-434e-440a-978f-342ea9b49789', '3b732750-e1ff-46ad-973f-60f90bf36d37', 'a', 'Son obligatorios para cualquier embarcación que navegue en cualquiera de las zonas.', true, '2025-09-13 13:53:10.16805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d0690b6-6753-4f3d-a675-c1b0e0788c90', '3b732750-e1ff-46ad-973f-60f90bf36d37', 'b', 'No son obligatorios para las embarcaciones que naveguen en zona 7 y que realicen exclusivamente navegación diurna.', false, '2025-09-13 13:53:10.168212+00');
