INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a012f2b-283e-4d12-9c29-4e78e987e3d5', 'af851f91-92c8-4ca5-b14c-95b7197e3f47', 'a', 'Parando máquinas se mete el timón hacia la banda donde haya caído hasta navegar a rumbo', false, '2025-09-13 13:53:10.168984+00');
