INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddb04cb9-ba85-4f43-a009-977347e983bc', 'c565a07b-1f32-4157-a5fd-34516c0501dc', 'd', 'Isofase, de ocultaciones, un destello largo cada 0,5 segundos.', false, '2025-09-13 13:53:10.174656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91613768-6fe9-4047-ae1c-0fd8f794a557', '7bf7cb9c-a4da-47b4-9d90-ab5bab2e7ad2', 'a', 'Únicamente luces sincronizadas.', false, '2025-09-13 13:53:10.174935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3be28353-4159-4899-966f-584bc41bf297', '7bf7cb9c-a4da-47b4-9d90-ab5bab2e7ad2', 'b', 'Únicamente luces secuenciadas.', false, '2025-09-13 13:53:10.175068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c6cce71-1204-419d-8b28-4c922c12ba83', '7bf7cb9c-a4da-47b4-9d90-ab5bab2e7ad2', 'c', 'Se tendrá que elegir entre luces sincronizadas o luces secuenciales, no admitiéndose una combinación de ambas.', false, '2025-09-13 13:53:10.175202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1eabc1f-b512-4d86-b2ad-c22566f6c9ad', '7bf7cb9c-a4da-47b4-9d90-ab5bab2e7ad2', 'd', 'Luces sincronizadas, luces secuenciadas o una combinación de ambas.', true, '2025-09-13 13:53:10.175331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b51575dc-117f-49ea-a476-b9afe6979ba9', 'abaf21ae-e8cc-4c6e-9a67-8490124fb9d9', 'a', 'El ritmo de la luz, si tiene, será una luz azul 1 segundo y una luz amarilla 1 segundo, con 0,5 segundos de ocultación entre ambas.', false, '2025-09-13 13:53:10.175608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c8d1b8a-d991-4d69-b3c6-c85decdc8645', 'abaf21ae-e8cc-4c6e-9a67-8490124fb9d9', 'b', 'La luz, si tiene, será de color amarillo y su ritmo puede ser cualquiera excepto los establecidos para las marcas cardinales.', false, '2025-09-13 13:53:10.175739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('620e76ba-0a39-495f-aa1b-9d270692c20e', 'abaf21ae-e8cc-4c6e-9a67-8490124fb9d9', 'c', 'El ritmo de la luz, si tiene, puede utilizarse para indicar el mejor lugar de paso bajo un puente.', true, '2025-09-13 13:53:10.175879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3830c85a-ab75-4d41-a3b6-18f1f2d87e8b', 'abaf21ae-e8cc-4c6e-9a67-8490124fb9d9', 'd', 'La luz, que tiene siempre, será de color amarillo y su ritmo puede ser cualquiera excepto los establecidos para las marcas cardinales. Reglamento (RIPA).', false, '2025-09-13 13:53:10.176009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13687080-9566-4e40-9a2e-cc87184160cc', '3c528e21-8cd4-4fa7-8a11-059e78ad2b4d', 'a', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:10.176288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e1430b4-a017-4185-ad68-587f8b5858f3', '3c528e21-8cd4-4fa7-8a11-059e78ad2b4d', 'b', 'Se mantendrá lo más cerca posible de la derrota del buque alcanzado.', false, '2025-09-13 13:53:10.17642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d5f8de4-dad6-484e-836c-57a74b36b805', '3c528e21-8cd4-4fa7-8a11-059e78ad2b4d', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:10.176555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdec0079-dc0e-4e17-891f-c2e28fe6f2b8', '3c528e21-8cd4-4fa7-8a11-059e78ad2b4d', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:10.176688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f339192f-edda-4b9b-8947-9a2eea006db7', 'f1acbb82-38ce-42a7-ba0d-cecc24d4a216', 'a', 'Debe ceder el paso siempre al primero.', false, '2025-09-13 13:53:10.176993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfee660a-b6b3-4a81-877a-69df8f0ac6aa', 'f1acbb82-38ce-42a7-ba0d-cecc24d4a216', 'b', 'Mantendrá rumbo y velocidad, en todo caso, para no confundir al otro buque.', false, '2025-09-13 13:53:10.177136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62acdde4-c0ca-48df-98ae-7a2fb062511d', 'f1acbb82-38ce-42a7-ba0d-cecc24d4a216', 'c', 'Debe maniobrar, si fuera necesario, para evitar el abordaje.', true, '2025-09-13 13:53:10.177269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('789a60da-eb4c-4cb1-9f3f-b6e59ab771d0', 'f1acbb82-38ce-42a7-ba0d-cecc24d4a216', 'd', 'Nunca debe maniobrar para no confundir al otro buque.', false, '2025-09-13 13:53:10.177401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b372c2f-92eb-4b60-9942-0edb472a207f', '4021db6a-5bcf-4d12-81f8-c91ffe65ec6f', 'a', 'Dará cinco golpes de campana claros y separados inmediatamente antes y después del repique rápido de la campana.', false, '2025-09-13 13:53:10.177677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d583948a-93f3-4fd8-9c6f-58ae85b7d759', '4021db6a-5bcf-4d12-81f8-c91ffe65ec6f', 'b', 'Dará tres golpes de campana claros y separados inmediatamente antes y después del repique rápido de la campana.', true, '2025-09-13 13:53:10.17781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e129bce-3d30-49d3-96eb-6a7cf0665dfb', '4021db6a-5bcf-4d12-81f8-c91ffe65ec6f', 'c', 'Dará un repique rápido de la campana inmediatamente antes y después de dar cinco golpes de campana claros y separados.', false, '2025-09-13 13:53:10.177943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b17d91a3-ecba-4d73-b823-7056fa98062c', '4021db6a-5bcf-4d12-81f8-c91ffe65ec6f', 'd', 'Dará un repique rápido de la campana inmediatamente antes y después de dar tres golpes de campana claros y separados.', false, '2025-09-13 13:53:10.178075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab0559de-7b6f-4bfb-afb1-7bf06b562d6c', '4af32b04-095d-4d3c-95b5-99fccb9e7836', 'a', 'Se aplica a los buques que no estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:10.178349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4690099e-b417-42c4-91c3-c2b8f5c39bf5', '3ee65e19-d6bc-43a6-b30b-b94ed8e2b2f5', 'd', 'Un aro salvavidas con luz y rabiza y un aro adicional que no necesitará luz y rabiza.', false, '2025-09-13 13:53:10.188804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a3cafb2-8940-4585-ac9d-0f166b46e34d', '4af32b04-095d-4d3c-95b5-99fccb9e7836', 'b', 'Se aplica a los buques que estén a la vista uno de otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', false, '2025-09-13 13:53:10.178482+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d660d92a-b608-4954-b8f6-cab39b5983bb', '4af32b04-095d-4d3c-95b5-99fccb9e7836', 'c', 'Establece que todos los buques deberán aumentar su velocidad.', false, '2025-09-13 13:53:10.178622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ff41066-369d-4fb4-bfba-3d67a09bf747', '4af32b04-095d-4d3c-95b5-99fccb9e7836', 'd', 'Establece que todos los buques deberán fondear inmediatamente.', false, '2025-09-13 13:53:10.178754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a19db6c-6624-4e51-b33a-44ad06ef04e5', '35c23b6a-6586-4573-a3c8-7c0aa1af93b2', 'a', 'La densidad del tráfico.', false, '2025-09-13 13:53:10.1792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec004f35-a03f-46f3-a4c5-f1696fd23753', '35c23b6a-6586-4573-a3c8-7c0aa1af93b2', 'b', 'La manga en relación con la distancia a otras embarcaciones.', true, '2025-09-13 13:53:10.179336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a93f90e2-9cb5-479a-9b73-de9011b49902', '35c23b6a-6586-4573-a3c8-7c0aa1af93b2', 'c', 'El calado en relación con la profundidad disponible de agua.', false, '2025-09-13 13:53:10.179468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e12245dc-2627-4118-b130-f1b938cc7421', '35c23b6a-6586-4573-a3c8-7c0aa1af93b2', 'd', 'El estado de la visibilidad.', false, '2025-09-13 13:53:10.179601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1464996a-2806-480a-bcdc-bf9662d46871', '03694ae5-677b-49fc-8b64-e0a1f1c1fda1', 'a', 'Blanca.', false, '2025-09-13 13:53:10.179891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2f681c3-930c-4187-baf9-9aaacf164116', '03694ae5-677b-49fc-8b64-e0a1f1c1fda1', 'b', 'Verde.', false, '2025-09-13 13:53:10.180026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6d8b0fc-6dfa-443a-adbf-c5e2fc18e806', '03694ae5-677b-49fc-8b64-e0a1f1c1fda1', 'c', 'Amarilla.', true, '2025-09-13 13:53:10.180157+00');
