INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f359903-3b40-4824-8d4a-a81d47166ed8', 'fac6b726-986c-48d8-8049-15d273470010', 'a', 'Un buque restringido por su calado.', false, '2025-09-13 13:53:10.180568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d08a47cf-cee4-41de-aabf-5afcd521bde8', 'fac6b726-986c-48d8-8049-15d273470010', 'b', 'Un buque especialmente protegido.', false, '2025-09-13 13:53:10.180701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30b998ae-be20-4544-83e9-7fb61e7d832b', 'fac6b726-986c-48d8-8049-15d273470010', 'c', 'Un buque sin gobierno.', false, '2025-09-13 13:53:10.180831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a6983c5-65d4-43cc-b1e3-b72e33b8d113', 'fac6b726-986c-48d8-8049-15d273470010', 'd', 'Un buque con capacidad de maniobra restringida.', true, '2025-09-13 13:53:10.180962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f5f9c82-65e0-49c4-ba77-da0a185798d1', 'e21ee99e-cf3b-40ed-b5a8-7e0a06d9300b', 'a', 'Solamente se aplica cuando se navega en alta mar.', false, '2025-09-13 13:53:10.181238+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5823237-3fca-485f-81d8-a083081b0b5b', 'e21ee99e-cf3b-40ed-b5a8-7e0a06d9300b', 'b', 'Es de aplicación únicamente a los buques mercantes de propulsión mecánica.', false, '2025-09-13 13:53:10.181368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a3606dd-0097-4650-a7f6-26138598ed2d', 'e21ee99e-cf3b-40ed-b5a8-7e0a06d9300b', 'c', 'Es de aplicación a todos los buques en alta mar y en todas las aguas que tengan comunicación con', true, '2025-09-13 13:53:10.181501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ab6fc77-03a5-4389-b91b-42ec1c29f335', 'e21ee99e-cf3b-40ed-b5a8-7e0a06d9300b', 'd', 'No es de aplicación cuando se navega por canales que dan salida al mar.', false, '2025-09-13 13:53:10.181631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64fef67b-dd6b-4b85-af88-a4ef8366ee96', 'f86548bb-23a4-4440-a5ef-bc4d2bc5fff5', 'a', 'Una marca consistente en dos conos unidos por sus vértices en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:10.181924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c0bf3ce-a5d0-4176-8d58-36e82a9abf72', 'f86548bb-23a4-4440-a5ef-bc4d2bc5fff5', 'b', 'Una marca bicónica.', false, '2025-09-13 13:53:10.182054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('564186a1-acbb-46ab-8a0e-b422d439d92b', 'f86548bb-23a4-4440-a5ef-bc4d2bc5fff5', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:10.182183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcc248df-c69d-4ed8-ae7f-4f52f25dcac9', 'f86548bb-23a4-4440-a5ef-bc4d2bc5fff5', 'd', 'Una marca cónica con el vértice hacia abajo.', true, '2025-09-13 13:53:10.18231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4963befe-4adf-4b58-92dc-b61608120c51', 'beed4647-cd17-4933-bb81-6f3a2541bbe6', 'a', 'Exhibirán dos luces blancas todo horizonte adicionales encima de las luces de costado del buque', false, '2025-09-13 13:53:10.182583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87aba1ca-ad51-45e4-8c6f-87e40ec2897d', 'beed4647-cd17-4933-bb81-6f3a2541bbe6', 'b', 'Exhibirán dos luces blancas todo horizonte adicionales en los puntos extremos de esa anchura o cerca de éstos.', true, '2025-09-13 13:53:10.182714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62ae779b-0d5d-4349-b865-e2761e69823f', 'beed4647-cd17-4933-bb81-6f3a2541bbe6', 'c', 'Exhibirán dos luces de costado adicionales encima de las luces de costado del buque remolcador.', false, '2025-09-13 13:53:10.182854+00');
