INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d49987a-7c24-4b65-af86-1933a87ebfa2', '2d96b9c1-44d6-4f93-84fa-7b97df7260b9', 'a', 'Hacer que la embarcación retome su rumbo.', false, '2025-09-13 13:53:10.183391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b20bbdf6-4e6a-43d2-bd9a-09d8c0546145', '2d96b9c1-44d6-4f93-84fa-7b97df7260b9', 'b', 'Hacer que el plano diametral la embarcación se sitúe en vertical.', true, '2025-09-13 13:53:10.18352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8c336b0-ac44-4bc0-b3c7-57b4af9e9b49', '2d96b9c1-44d6-4f93-84fa-7b97df7260b9', 'c', 'Colocar una embarcación al lado de otra o de un muelle.', false, '2025-09-13 13:53:10.183648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6d14d32-c3bd-445f-8809-89d2f9e6f437', '2d96b9c1-44d6-4f93-84fa-7b97df7260b9', 'd', 'Inclinarse la embarcación alrededor de su eje transversal.', false, '2025-09-13 13:53:10.183785+00');
