INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25b8c193-e1f2-4e20-b2dd-2f3f5f2f3b7c', '97b26db6-9a41-4a9e-9d94-4f256269dc2b', 'b', 'El diámetro de la rueda.', false, '2025-09-13 13:53:10.184331+00');
