INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('715d0059-70b2-4092-97c2-758a9be5fe8b', '97b26db6-9a41-4a9e-9d94-4f256269dc2b', 'd', 'La superficie total de la pala.', true, '2025-09-13 13:53:10.184597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8116c5b6-695d-4ce9-89e3-ab1937768584', '6e24390f-a95c-48ee-82f3-7ef6d264b3e9', 'a', 'El barbotén es la pieza del molinete con forma de corona y muescas o moldes donde se encastran o acoplan los eslabones de la cadena según se va cobrando el ancla.', false, '2025-09-13 13:53:10.184867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae1f3399-eb34-46ee-9bbd-c4eb1f57dfe1', '6e24390f-a95c-48ee-82f3-7ef6d264b3e9', 'b', 'Si se deja libre el eje, soltando su embrague, se arria el ancla.', false, '2025-09-13 13:53:10.184998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('695ce14a-126b-4b9b-b017-b7ba37449624', '6e24390f-a95c-48ee-82f3-7ef6d264b3e9', 'c', 'Es un gran cabrestante de eje horizontal o vertical destinado a echar o levar anclas de forma rápida, sencilla y fiable.', false, '2025-09-13 13:53:10.185127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4b8fda2-cf62-4ffe-b4fa-479e158058a6', '6e24390f-a95c-48ee-82f3-7ef6d264b3e9', 'd', 'Es una maquinilla con eje de giro horizontal que permite levar el ancla.', true, '2025-09-13 13:53:10.185255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a7ee9c2-f635-43f9-a03f-24f378d861b6', '1caf7d5b-8fda-468e-808d-500847c62275', 'a', 'La cruz, el mapa, la caña y el arganeo.', true, '2025-09-13 13:53:10.185536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3dead87-59fc-4277-ad21-7d47b4446163', '1caf7d5b-8fda-468e-808d-500847c62275', 'b', 'La cruceta, la uña, la caña y el arganeo.', false, '2025-09-13 13:53:10.18567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70e857b9-0568-4535-a8f9-25e80b448b74', '1caf7d5b-8fda-468e-808d-500847c62275', 'c', 'La cruceta, el brazo, la caña y el ojo del arganeo.', false, '2025-09-13 13:53:10.185802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9786bd3-8cb1-4d47-a951-32f60fa5d199', '1caf7d5b-8fda-468e-808d-500847c62275', 'd', 'La cruz, el brazo, la caña y el rezón. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.185934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5211b8cb-2bec-40aa-8b7e-01f2aa91e1f8', '0a15f892-93eb-4161-b760-7efacc1d92b0', 'a', 'El tenedero es la superficie del fondo marino donde se afirma el ancla, siendo los mejores los de fango duro, arena fangosa y arena dura.', false, '2025-09-13 13:53:10.186206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00a53c50-3e90-47d3-9910-82399a7421d3', '0a15f892-93eb-4161-b760-7efacc1d92b0', 'b', 'El orinque es un cabo fino que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder levar y recuperar el ancla o señalizar la vertical del ancla en caso de no poder', false, '2025-09-13 13:53:10.186338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af9b97ca-c35f-47ad-992d-9ed37bacb73e', '0a15f892-93eb-4161-b760-7efacc1d92b0', 'c', 'Un barco bornea cuando da vueltas alrededor del ancla por acción del viento o la corriente.', false, '2025-09-13 13:53:10.186479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3981ed08-76a4-4067-9ce4-b2c1714f45d2', '0a15f892-93eb-4161-b760-7efacc1d92b0', 'd', 'En la maniobra de levar ancla, se dará un poco atrás mientras cobramos elemento de fondeo hasta que el ancla se desclave del fondo, momento en el que tomaremos arrancada dando avante.', true, '2025-09-13 13:53:10.186614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68193dd5-ca87-4a77-a257-eab0bb22ad5c', 'f5ace38c-e47b-4085-b303-7a11a271ef5d', 'a', 'Firme.', false, '2025-09-13 13:53:10.186909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7d360a6-9b6b-4c52-b8d6-ef01147b35be', 'f5ace38c-e47b-4085-b303-7a11a271ef5d', 'b', 'Seno.', true, '2025-09-13 13:53:10.187044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f547c9d3-c1b4-4bfd-877b-a0343415661b', 'f5ace38c-e47b-4085-b303-7a11a271ef5d', 'c', 'Chicote.', false, '2025-09-13 13:53:10.187178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa753531-27a3-4e11-85a4-e1b2e22e4e2c', 'f5ace38c-e47b-4085-b303-7a11a271ef5d', 'd', 'Gaza.', false, '2025-09-13 13:53:10.18731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a981c7c8-f3b0-4bce-b2d9-a19575f4caaf', '07aa131d-1014-49bf-8b5b-af77be7d2f59', 'a', 'Variar el rumbo.', false, '2025-09-13 13:53:10.187584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d62747b-6d2c-4825-bdf5-8821b064a25d', '07aa131d-1014-49bf-8b5b-af77be7d2f59', 'b', 'Modificar la velocidad.', true, '2025-09-13 13:53:10.187716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3de4e10c-53c8-4969-9ee9-b6a514bfe820', '07aa131d-1014-49bf-8b5b-af77be7d2f59', 'c', 'Atravesarse a la mar.', false, '2025-09-13 13:53:10.187867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d3f6077-71d9-4120-a030-197289544d2e', '07aa131d-1014-49bf-8b5b-af77be7d2f59', 'd', 'Poner la embarcación para recibir el mar por una aleta.', false, '2025-09-13 13:53:10.188131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4067182d-8b9a-4eba-b101-f87f58fe4e38', '3ee65e19-d6bc-43a6-b30b-b94ed8e2b2f5', 'a', 'Un aro salvavidas sin luz ni rabiza.', false, '2025-09-13 13:53:10.188407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90042392-3b8f-4782-8381-b3d41609d72d', '3ee65e19-d6bc-43a6-b30b-b94ed8e2b2f5', 'b', 'Dos aros salvavidas sin luz ni rabiza.', false, '2025-09-13 13:53:10.18854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71d4f6c9-fda5-4993-9b3b-17771d798d25', '3ee65e19-d6bc-43a6-b30b-b94ed8e2b2f5', 'c', 'Un aro salvavidas con luz y rabiza.', true, '2025-09-13 13:53:10.188672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bc2f849-ee71-4d63-b3bb-fcf7a86ee6c6', '96924e22-f949-4dc3-90ec-8894ef7469c1', 'a', '14h 56,8m', false, '2025-09-13 13:53:10.244734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4237b53-bf98-4021-90e0-90169636841b', 'b0893156-6cae-49cc-8682-8b5a091ee2c7', 'a', 'Parando máquinas se mete el timón hacia la banda donde haya caído hasta navegar a rumbo', false, '2025-09-13 13:53:10.189081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80c2a21d-3b2e-41d2-8823-e461fc36afe4', 'b0893156-6cae-49cc-8682-8b5a091ee2c7', 'b', 'Con toda la máquina avante se mete el timón hacia la banda donde haya caído el hombre hasta que la proa haya caído 240º, en cuyo momento se cambia a la otra banda hasta que caiga 20º, aproximándonos con poca máquina.', false, '2025-09-13 13:53:10.189221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('760fcf6e-d494-4dc4-9ce5-151ff2f08597', 'b0893156-6cae-49cc-8682-8b5a091ee2c7', 'c', 'Con toda la máquina avante se mete el timón hacia la banda donde haya caído el hombre hasta que la proa haya caído 70º, en cuyo momento se cambia a la otra banda hasta rumbo opuesto, aproximándonos con poca máquina.', true, '2025-09-13 13:53:10.189355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('452ef0f3-f031-44b4-a801-7e8ba387d46b', 'b0893156-6cae-49cc-8682-8b5a091ee2c7', 'd', 'Con toda la máquina avante se mete el timón hacia la banda contraria donde haya caído el hombre hasta que la proa haya caído 70º, en cuyo momento se cambia a la otra banda, aproximándonos con poca máquina.', false, '2025-09-13 13:53:10.189488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cb38390-0eb3-4fbd-8953-ab86368e3d6c', '45984560-1ea8-445b-a0a1-a7b06719017b', 'a', 'Son obligatorios para cualquier embarcación que navegue en cualquiera de las zonas.', true, '2025-09-13 13:53:10.189764+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcd7a789-1015-43a0-b106-2148827e9a8e', '45984560-1ea8-445b-a0a1-a7b06719017b', 'b', 'No son obligatorios para las embarcaciones que naveguen en zona 7 y que realicen exclusivamente navegación diurna.', false, '2025-09-13 13:53:10.189898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d456e6b4-5daf-4983-8448-4459c661cf44', '45984560-1ea8-445b-a0a1-a7b06719017b', 'c', 'Sólo son obligatorios para las que naveguen en zonas 1, 2 y 3.', false, '2025-09-13 13:53:10.190031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3918d4c-fdee-4b41-92a1-77251ea9335b', '45984560-1ea8-445b-a0a1-a7b06719017b', 'd', 'Sólo son obligatorios para embarcaciones de más de 6 metros de eslora de casco.', false, '2025-09-13 13:53:10.190164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69c91df3-851b-4cda-8218-d03f51b3ebb6', 'd8d3a50e-19c4-426c-9b98-a0484b4a2bea', 'a', 'De inmediato y por el medio más rápido posible.', true, '2025-09-13 13:53:10.190449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae9e6192-47a0-4bfb-8ded-2cd497e2478f', 'd8d3a50e-19c4-426c-9b98-a0484b4a2bea', 'b', 'Dentro de las 24 horas hábiles siguientes a que se produzca u observe el episodio.', false, '2025-09-13 13:53:10.190602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecb6b478-4663-4901-951e-efa354d546c2', 'd8d3a50e-19c4-426c-9b98-a0484b4a2bea', 'c', 'Dentro de las 24 horas naturales siguientes a que se produzca u observe el episodio.', false, '2025-09-13 13:53:10.190755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ad3a203-ef31-4fb4-9f8a-83392b73a20e', 'd8d3a50e-19c4-426c-9b98-a0484b4a2bea', 'd', 'En el menor tiempo posible y a través del Canal 16 VHF.', false, '2025-09-13 13:53:10.190923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e573afe5-1216-4614-8832-b0cb0a624f2c', '00f3e00d-18d2-4a14-9143-9943bf536b9f', 'a', 'Restringir los movimientos de la embarcación o imponerle un rumbo determinado. Esta exigencia exime de responsabilidad al propietario en lo que respecta a episodios de contaminación de su', false, '2025-09-13 13:53:10.191239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4946c883-8363-474f-b09b-ad7383de7670', '00f3e00d-18d2-4a14-9143-9943bf536b9f', 'b', 'Restringir los movimientos de la embarcación o imponerle un rumbo determinado. Esta exigencia no afecta a la responsabilidad del patrón en lo que respecta al gobierno seguro de su embarcación.', true, '2025-09-13 13:53:10.191373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98ca036b-a3bb-4c89-ac40-14849a43c84b', '00f3e00d-18d2-4a14-9143-9943bf536b9f', 'c', 'Restringir los movimientos de la embarcación o imponerle un rumbo determinado. Esta exigencia exime de la responsabilidad al patrón en lo que respecta al gobierno seguro de su embarcación.', false, '2025-09-13 13:53:10.191505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91b6d237-b996-40d2-a081-28392f928ab8', '00f3e00d-18d2-4a14-9143-9943bf536b9f', 'd', 'Restringir los movimientos de la embarcación o imponerle un rumbo determinado. Esta exigencia exime de la responsabilidad al propietario en lo que respecta al gobierno seguro de su embarcación', false, '2025-09-13 13:53:10.191649+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('785833b3-29a9-4c57-b5cd-95c5cdecc6cd', 'aeb70628-99d5-4f93-97f3-a26561507433', 'a', 'Canales u obstrucciones donde el Sistema de Balizamiento Marítimo ofrece alternativas', false, '2025-09-13 13:53:10.191955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3697b64-400a-4e32-8fc1-da8dde0e7d8f', 'aeb70628-99d5-4f93-97f3-a26561507433', 'b', 'Zonas especiales cuya naturaleza se indica en la carta u otro documento náutico.', true, '2025-09-13 13:53:10.192095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('129b582e-2b19-4b3f-b689-6a82964b35c8', 'aeb70628-99d5-4f93-97f3-a26561507433', 'c', 'Una zona o configuración particular como canales u obstrucciones.', false, '2025-09-13 13:53:10.192227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78518b7b-de81-48cf-9a36-46abddcf2915', 'aeb70628-99d5-4f93-97f3-a26561507433', 'd', 'Zonas especiales que, por su naturaleza, no se pueden indicar en la carta u otro documento', false, '2025-09-13 13:53:10.192361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62e06daf-3ca9-41d6-a425-a54200123bfd', '28dda67f-67bb-4594-90ab-3c7d263087f2', 'a', 'Luz azul 1 segundo y luz roja 1 segundo, con 0,5 segundos de ocultación entre ambas.', false, '2025-09-13 13:53:10.192785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ea7bf8f-43ac-42e9-82d0-7709f9565b20', '28dda67f-67bb-4594-90ab-3c7d263087f2', 'b', 'Luz azul 1 segundo y luz amarilla 1 segundo, con 10 segundos de ocultación entre ambas.', false, '2025-09-13 13:53:10.192916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e69303b-574c-491c-8cf1-267ff25dae6a', '28dda67f-67bb-4594-90ab-3c7d263087f2', 'c', 'Isofase, de ocultaciones, un destello largo cada 10 segundos.', true, '2025-09-13 13:53:10.193045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7711277a-698c-4b87-b181-fe2fb2efdbd7', '28dda67f-67bb-4594-90ab-3c7d263087f2', 'd', 'Isofase, de ocultaciones, un destello largo cada 0,5 segundos.', false, '2025-09-13 13:53:10.193183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e217c84c-c852-4318-8d4e-2528ca53d184', 'fb13935b-9432-4e95-bb96-c28f56c0c851', 'a', 'El ritmo de la luz, si tiene, será una luz azul 1 segundo y una luz amarilla 1 segundo, con 0,5 segundos de ocultación entre ambas.', false, '2025-09-13 13:53:10.193465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c48adda9-2a2b-4744-8913-8a0c170a589a', 'fb13935b-9432-4e95-bb96-c28f56c0c851', 'b', 'La luz, si tiene, será de color amarillo y su ritmo puede ser cualquiera excepto los establecidos para las marcas cardinales.', false, '2025-09-13 13:53:10.193597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3587604f-6416-4999-a385-3ed61147caba', 'fb13935b-9432-4e95-bb96-c28f56c0c851', 'c', 'El ritmo de la luz, si tiene, puede utilizarse para indicar el mejor lugar de paso bajo un puente.', true, '2025-09-13 13:53:10.193731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fd0f91f-3007-4e8d-bc14-e9d759aad91b', 'fb13935b-9432-4e95-bb96-c28f56c0c851', 'd', 'La luz, que tiene siempre, será de color amarillo y su ritmo puede ser cualquiera excepto los establecidos para las marcas cardinales.', false, '2025-09-13 13:53:10.193875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d777cf9e-ae02-4bf9-b424-a84e0464ffff', '6253bd93-82c7-445b-8ea7-3cca4d21fe6b', 'a', 'Únicamente luces sincronizadas.', false, '2025-09-13 13:53:10.194203+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f65f18a-4dba-4e5f-9485-5092c955423a', '6253bd93-82c7-445b-8ea7-3cca4d21fe6b', 'b', 'Únicamente luces secuenciadas.', false, '2025-09-13 13:53:10.194352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4891b874-c8ae-4de5-b8cf-eda7f6070a6e', '6253bd93-82c7-445b-8ea7-3cca4d21fe6b', 'c', 'Se tendrá que elegir entre luces sincronizadas o luces secuenciales, no admitiéndose una combinación de ambas.', false, '2025-09-13 13:53:10.194482+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53d5008a-7807-4ce9-8e55-16d908468d67', '6253bd93-82c7-445b-8ea7-3cca4d21fe6b', 'd', 'Luces sincronizadas, luces secuenciadas o una combinación de ambas.', true, '2025-09-13 13:53:10.19461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c06d718e-ee4f-4a27-b7e9-e659fcb2db29', '1cee9e2c-b0b9-4119-876b-3f87e7111920', 'a', 'Color.', false, '2025-09-13 13:53:10.194902+00');
