INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90cbda06-750d-48b0-9724-33cb125d5b4c', 'd4a155fc-637b-4f4a-9127-7e3e26770d37', 'b', 'Mantendrá rumbo y velocidad, en todo caso, para no confundir al otro buque.', false, '2025-09-13 13:53:10.200152+00');
