INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8a9ab31-d0c8-46b0-9594-9c7e2fc3f662', '25b44a8b-0e8d-4fd5-84ce-51778984e318', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:10.20114+00');
