INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa73028c-7464-46ce-a2af-56871794f762', '75e035f4-5932-451f-99f6-7564cccb62e2', 'c', 'Son la manifestación violenta procedente de nubes de desarrollo vertical en las que el aire ascendente cálido y húmedo encuentra sobre él aire frío y denso.', false, '2025-09-13 13:53:10.219296+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e836cee-1867-4ca4-a23d-ecda651b0828', '75e035f4-5932-451f-99f6-7564cccb62e2', 'd', 'Se disipan cuando las corrientes de aire descendentes van aumentando.', false, '2025-09-13 13:53:10.219466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40fd3e31-920a-491a-a8db-69670163b8b6', 'e26290aa-c014-4fab-b614-50083f6a135d', 'a', 'NW en el hemisferio norte y SW en el hemisferio sur.', false, '2025-09-13 13:53:10.219831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10223ec1-bfb5-413f-b258-1527db221e43', 'e26290aa-c014-4fab-b614-50083f6a135d', 'b', 'SW en el hemisferio norte y NW en el hemisferio sur.', true, '2025-09-13 13:53:10.220005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9910122-98c5-4a85-aeba-13740ff7c90a', 'e26290aa-c014-4fab-b614-50083f6a135d', 'c', 'NE en el hemisferio norte y SE en el hemisferio sur.', false, '2025-09-13 13:53:10.220172+00');
