INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f418dd11-5635-49f0-a598-cb1556b364e3', 'ce5ec765-4afc-4871-a923-9cfeb632421a', 'b', 'Primavera y verano.', false, '2025-09-13 13:53:10.220839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f76e5c87-caaf-452d-a80c-bdc98f13698b', 'ce5ec765-4afc-4871-a923-9cfeb632421a', 'c', 'Verano y otoño.', false, '2025-09-13 13:53:10.220986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3922fe9a-07d7-4b25-ad4a-ea235a6d5451', 'ce5ec765-4afc-4871-a923-9cfeb632421a', 'd', 'Invierno y verano.', true, '2025-09-13 13:53:10.221124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4be04346-a72f-4562-a445-7c2c77de0a15', '25e8e7f0-813a-4f61-8738-0fe3e338142b', 'a', 'Al hielo en el que se producen de forma activa procesos de deformación, resultando un impedimento o peligro para la navegación.', true, '2025-09-13 13:53:10.221415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23878c77-1d47-4467-892f-88a25b6ef42e', '25e8e7f0-813a-4f61-8738-0fe3e338142b', 'b', 'Al área observada por satélite en la que la concentración o espesor del hielo es considerablemente inferior a la de los alrededores, resultando un impedimento o peligro para la navegación.', false, '2025-09-13 13:53:10.22155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7f49de1-9185-42ab-a4db-1dbe5e1035e6', '25e8e7f0-813a-4f61-8738-0fe3e338142b', 'c', 'Al área observada por satélite que indica que las condiciones de hielo prevalentes en un área dificultan la navegación.', false, '2025-09-13 13:53:10.221684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('313c4db8-1b0b-431b-8e80-9cac8d1da5c1', '25e8e7f0-813a-4f61-8738-0fe3e338142b', 'd', 'Al techo de hielo que no contiene grandes manchas translúcidas que indican que se puede navegar en superficie moderando siempre la velocidad.', false, '2025-09-13 13:53:10.221819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa84cbed-5f69-42a6-a7ff-d018a2f63834', '026b658d-a1d0-4316-8308-cd29411873d0', 'a', 'Corriente de Kuroshio.', false, '2025-09-13 13:53:10.222105+00');
