INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b14b6244-8354-494d-8c0b-544deb5eeac9', '7619ab38-9b0a-4f68-bc58-8bf70cb710f9', 'a', 'Está compuesta principalmente por Hidrógeno, Oxígeno, Argón y otros gases. El vapor de agua aumenta con la altura hasta la troposfera.', false, '2025-09-13 13:53:10.22279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a5c39ba-0286-4bb8-b9c9-4d299fd3dce5', '7619ab38-9b0a-4f68-bc58-8bf70cb710f9', 'b', 'La Estratosfera presenta una variación térmica muy alta con la altura.', false, '2025-09-13 13:53:10.22293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39925d23-d260-43a0-bdf8-e8b244af2f31', '7619ab38-9b0a-4f68-bc58-8bf70cb710f9', 'c', 'La Troposfera es la parte de la atmósfera donde se producen la mayor parte de los fenómenos meteorológicos.', true, '2025-09-13 13:53:10.223066+00');
