INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1442962b-4c90-4664-b933-bce3a3d585b0', '9ae508e6-63e1-49cd-a53f-6c6de22b10d7', 'a', 'Todas las personas embarcadas.', false, '2025-09-13 13:53:10.248229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('108cf34d-9146-442b-8e24-86e2eba9954c', '9ae508e6-63e1-49cd-a53f-6c6de22b10d7', 'b', 'Los miembros de la tripulación solamente.', false, '2025-09-13 13:53:10.248364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7b1573c-b8b2-42a5-83df-c041090d7151', '9ae508e6-63e1-49cd-a53f-6c6de22b10d7', 'c', 'Los buques que se hallen cercanos.', true, '2025-09-13 13:53:10.248496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27deab20-3622-4cff-b5fd-88a86b8041af', '9ae508e6-63e1-49cd-a53f-6c6de22b10d7', 'd', 'El Centro Nacional de Emergencias por Climatología Extrema (CENECE).', false, '2025-09-13 13:53:10.24864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d6fef27-4d09-46e5-9c19-7a6a89af5d99', 'ac76ff54-6483-4434-ba8a-0c5480dd3f7b', 'a', 'Se produce por la diferencia de potencial eléctrico entre barco y nubes.', false, '2025-09-13 13:53:10.248931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('846de3fe-e5ee-4ea9-8f29-d34ab23ce3c6', 'ac76ff54-6483-4434-ba8a-0c5480dd3f7b', 'b', 'Es un fenómeno óptico debido a la refracción en cristales de hielo en la atmósfera de los colores que forman la luz blanca.', false, '2025-09-13 13:53:10.249068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e53ec8a-05f1-4788-8bc8-42d014e1f6f5', 'ac76ff54-6483-4434-ba8a-0c5480dd3f7b', 'c', 'Es un fenómeno eléctrico que se produce por la estratificación de las capas de la atmósfera por su', true, '2025-09-13 13:53:10.249201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('825d460f-0c7e-4ba6-ac49-6324bfb5909e', 'ac76ff54-6483-4434-ba8a-0c5480dd3f7b', 'd', 'Es un fenómeno acústico que, en ocasiones, precede a los rayos de una tormenta.', false, '2025-09-13 13:53:10.249334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e75ec486-f4a2-45b6-a636-22d16b0c09ee', 'b3b140be-f56e-418e-b1ff-01c8dc1c2caa', 'a', 'Son fenómenos espontáneos.', false, '2025-09-13 13:53:10.249755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('364177f2-0e5c-4fca-9e6e-fc0098c5afed', 'b3b140be-f56e-418e-b1ff-01c8dc1c2caa', 'b', 'Se producen cuando el aire cálido y húmedo en altura encuentra debajo de él aire frio y más', true, '2025-09-13 13:53:10.249901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a172ae2b-950e-4cd7-a27b-a59d2d53b245', 'b3b140be-f56e-418e-b1ff-01c8dc1c2caa', 'c', 'Son la manifestación violenta procedente de nubes de desarrollo vertical en las que el aire ascendente cálido y húmedo encuentra sobre él aire frío y denso.', false, '2025-09-13 13:53:10.25003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8be593c-e804-43ca-9f3f-6ed1cd917763', 'b3b140be-f56e-418e-b1ff-01c8dc1c2caa', 'd', 'Se disipan cuando las corrientes de aire descendentes van aumentando.', false, '2025-09-13 13:53:10.25016+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('663617be-42ab-4455-8d48-d143447e91ef', '4745ade5-8d3c-48e8-8da0-dc42bb9d9eb9', 'a', 'NW en el hemisferio norte y SW en el hemisferio sur.', false, '2025-09-13 13:53:10.250431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a75ee40-c125-4870-805c-63542a63b3b5', '4745ade5-8d3c-48e8-8da0-dc42bb9d9eb9', 'b', 'SW en el hemisferio norte y NW en el hemisferio sur.', false, '2025-09-13 13:53:10.25056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('227909da-c7c1-44f2-b1f4-9e2ed1bd5f5f', '4745ade5-8d3c-48e8-8da0-dc42bb9d9eb9', 'c', 'NE en el hemisferio norte y SE en el hemisferio sur.', true, '2025-09-13 13:53:10.250689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89e9e409-7a0b-484e-8467-ce52418e52e0', '4745ade5-8d3c-48e8-8da0-dc42bb9d9eb9', 'd', 'SE en el hemisferio norte y NE en el hemisferio sur.', false, '2025-09-13 13:53:10.250838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6313b6a-ff15-4965-8396-11af4c8b58e2', '3b349ab3-abe8-4c55-8b41-5b86ead9f591', 'a', 'Está compuesta principalmente por Hidrógeno, Oxígeno, Argón y otros gases. El vapor de agua aumenta con la altura hasta la troposfera.', false, '2025-09-13 13:53:10.251155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd7fb010-4854-4247-a72b-e7740e000a26', '3b349ab3-abe8-4c55-8b41-5b86ead9f591', 'b', 'La Estratosfera presenta una variación térmica muy alta con la altura.', true, '2025-09-13 13:53:10.251292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2935497b-95c9-4993-8882-d5d1e4dc983d', '3b349ab3-abe8-4c55-8b41-5b86ead9f591', 'c', 'La Troposfera es la parte de la atmósfera donde se producen la mayor parte de los fenómenos meteorológicos.', false, '2025-09-13 13:53:10.251426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f4853ed-95c8-4dc0-b4c9-92fa50e369c5', '3b349ab3-abe8-4c55-8b41-5b86ead9f591', 'd', 'La temperatura más alta de la atmósfera se encuentra en la Mesosfera.', false, '2025-09-13 13:53:10.251559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('448e5072-ea08-4223-9dd0-3bc5a2630cf9', '1b7a6ec9-9296-4401-93c4-1833d6497c3a', 'a', 'No tienen frentes porque están constituidos por una sola masa de aire ecuatorial homogéneo.', false, '2025-09-13 13:53:10.251836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2ea35aa-52f9-4a5b-b803-3c9dc74e4df1', '1b7a6ec9-9296-4401-93c4-1833d6497c3a', 'b', 'La energía de los ciclones tropicales proviene del calor latente de evaporación liberado por el aire muy húmedo al condensarse.', false, '2025-09-13 13:53:10.251967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dac16b8-84de-4fa5-a49d-19d7567898d1', '1b7a6ec9-9296-4401-93c4-1833d6497c3a', 'c', 'La escala para catalogarlos, Saffir-Simpson, tiene 12 categorías en función de la velocidad del', true, '2025-09-13 13:53:10.252098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a26aee2d-979a-4cd1-9443-269b724b1345', '1b7a6ec9-9296-4401-93c4-1833d6497c3a', 'd', 'Se forman en las latitudes bajas próximas a un cinturón de bajas presiones que se conoce como la I.T.C.Z. (Zona de convergencia intertropical).', false, '2025-09-13 13:53:10.252226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('291678da-bed0-402c-9216-223b12227c35', '52cb26ba-a7b7-4d71-ac91-227ddb05b6c8', 'a', 'Invierno y otoño.', false, '2025-09-13 13:53:10.252491+00');
