INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7e1f8a3-383f-43c3-8091-a09bff3072b9', '3d2b9d35-105b-459f-b743-0ab28d978474', 'a', 'Una bengala de mano.', false, '2025-09-13 13:53:10.263267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('004e5535-a891-4355-b8ec-df93d29dced8', '3d2b9d35-105b-459f-b743-0ab28d978474', 'b', 'Un cohete lanza bengalas con paracaídas.', false, '2025-09-13 13:53:10.263395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c94dbe8-ddab-4a43-9a79-b1895b90214a', '3d2b9d35-105b-459f-b743-0ab28d978474', 'c', 'Cualquier señal fumígena.', false, '2025-09-13 13:53:10.263532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6776a72-085a-425a-b632-533227ffce3c', '3d2b9d35-105b-459f-b743-0ab28d978474', 'd', 'Una radiobaliza.', true, '2025-09-13 13:53:10.263666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca422c6a-0e0e-4c9b-a165-2bc5a2cdacb0', 'c4ab2900-1dc9-412c-8f6f-3b573591b1d0', 'a', 'Los baldes contraincendios pueden utilizarse para achique y transvase de combustible o líquidos', false, '2025-09-13 13:53:10.263942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c328f305-17f9-4e5b-a2da-0dbc6f0be099', 'dbfa9d3d-f477-4855-943b-9061b34e0592', 'b', '36°01,4´ N; 006°00,3´ W', false, '2025-09-13 13:53:10.284252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3161a726-bc2e-4704-b73c-844751b5f05d', 'c4ab2900-1dc9-412c-8f6f-3b573591b1d0', 'b', 'Los extintores adecuados para la extinción de fuegos de origen eléctrico son los de espuma.', false, '2025-09-13 13:53:10.264072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('381bbb5a-95a1-46f0-adab-fad6feb0ebdb', 'c4ab2900-1dc9-412c-8f6f-3b573591b1d0', 'c', 'La función de un arnés de seguridad es evitar que una persona caiga al agua y quede desconectada de la embarcación.', false, '2025-09-13 13:53:10.264208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee568c9d-badd-4ceb-9f2c-ad764dec592f', 'c4ab2900-1dc9-412c-8f6f-3b573591b1d0', 'd', 'Las balsas salvavidas tiene una estabilidad tal que, con su asignación completa de personas y equipo, pueden ser remolcadas hasta una velocidad de 6 nudos en aguas tranquilas.', true, '2025-09-13 13:53:10.264346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7468336a-5eef-43fb-b77a-b0f938ecba0d', '9213d091-4d0f-435e-9993-3e8679220a48', 'a', 'El centro de carena coincide con el centro de gravedad.', true, '2025-09-13 13:53:10.264627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1da2fd0c-cd87-483a-90c4-ca01a83c7d39', '9213d091-4d0f-435e-9993-3e8679220a48', 'b', 'El centro de gravedad coincide con el metacentro.', false, '2025-09-13 13:53:10.264758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fff5782d-03df-477c-805d-f079edec136a', '9213d091-4d0f-435e-9993-3e8679220a48', 'c', 'El centro de gravedad está situado por debajo del metacentro.', false, '2025-09-13 13:53:10.2649+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de6acd1c-92e2-4a64-afc8-f52d3a09e80d', '9213d091-4d0f-435e-9993-3e8679220a48', 'd', 'El centro de carena está situado por encima del metacentro.', false, '2025-09-13 13:53:10.265031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d4c1109-d717-450f-9b4c-cad3de7c5c98', 'd03459ae-0530-417f-b847-d4debe002bad', 'a', 'Se detendrá completamente la embarcación.', false, '2025-09-13 13:53:10.265304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba611779-3a85-4ee6-9e6e-d7462dacd84f', 'd03459ae-0530-417f-b847-d4debe002bad', 'b', 'Se hará una llamada de socorro y se activará la radiobaliza manualmente.', true, '2025-09-13 13:53:10.265441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82ab2335-e62f-42c7-9cd4-376205b6f319', 'd03459ae-0530-417f-b847-d4debe002bad', 'c', 'Se esperará hasta que la zafa hidrostática de la balsa se active automáticamente.', false, '2025-09-13 13:53:10.265573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de9913bb-7200-4fd4-9c7d-6d9bc9fbef2e', 'd03459ae-0530-417f-b847-d4debe002bad', 'd', 'Se amarrará a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:10.265701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67f63c21-dcdc-4bc8-853f-6e44daa5cf76', '4d05f278-6f6f-43b1-974c-3b0e7191b210', 'a', 'Para voltear una balsa hay que colocarse a barlovento y subir sobre la botella de aire comprimido para tirar de las cinchas que cruzan la parte inferior de la balsa, mientras otros náufragos levantan desde sotavento.', true, '2025-09-13 13:53:10.265973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b319782-98ad-4620-a12b-a5627e5fa6d0', '4d05f278-6f6f-43b1-974c-3b0e7191b210', 'b', 'Para voltear una balsa hay que colocarse a sotavento y, sin subirse sobre la botella de aire comprimido, tirar de las cinchas que cruzan la parte inferior de la balsa, mientras otros náufragos levantan desde barlovento.', false, '2025-09-13 13:53:10.266102+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad5e1eda-472d-469e-abcc-33d2f2f4c921', '4d05f278-6f6f-43b1-974c-3b0e7191b210', 'c', 'Para voltear una balsa hay que colocarse a sotavento y subir sobre la botella de aire comprimido para tirar de las cinchas que cruzan la parte inferior de la balsa, mientras otros náufragos levantan desde barlovento.', false, '2025-09-13 13:53:10.266232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efc64894-5d3a-4cd5-ad21-8191c2d2d725', '4d05f278-6f6f-43b1-974c-3b0e7191b210', 'd', 'No deben tratar de voltear la balsa, deben nadar para alejarse de la embarcación y mantenerse todos unidos para evitar la hipotermia.', false, '2025-09-13 13:53:10.266362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff3acb80-115c-4620-b416-f78464999559', '62f36923-8e10-487b-9557-c8b5fd9dbcfa', 'a', 'No se impaciente aguardando la llegada.', false, '2025-09-13 13:53:10.266629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('924f1ff0-ec28-4b96-abad-b2b186c111e6', '62f36923-8e10-487b-9557-c8b5fd9dbcfa', 'b', 'Antes de la llegada del helicóptero, contacte con sus tripulantes por el Canal 72 de VHF y atienda a su información e instrucciones.', true, '2025-09-13 13:53:10.266758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e573037-5cff-4742-855a-7eb1ea8d399a', '62f36923-8e10-487b-9557-c8b5fd9dbcfa', 'c', 'Todas las personas a bordo deben ponerse el chaleco salvavidas y recoger la documentación más imprescindible.', false, '2025-09-13 13:53:10.266894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a886e347-dc4e-4e36-a2c5-9fa543b01707', '62f36923-8e10-487b-9557-c8b5fd9dbcfa', 'd', 'En veleros, arríe las velas y arranque el motor.', false, '2025-09-13 13:53:10.267024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd89f641-f109-45ef-bcf2-34593870c782', '98d0efd4-a592-4919-8758-f915b72efd96', 'a', 'El helicóptero enviará primero un cable que debe recoger. Pero deje antes que toque el agua, para descargar la electrícidad estática.', false, '2025-09-13 13:53:10.267308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('781e58ce-d14b-43b1-99c5-cd34785c18fd', '98d0efd4-a592-4919-8758-f915b72efd96', 'b', 'Si le envían un arnés, deje que contacte con el agua antes de tocarlo y colóqueselo.', true, '2025-09-13 13:53:10.267449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84f787c7-eff0-4bab-a3c8-93ee2fa25b7d', '98d0efd4-a592-4919-8758-f915b72efd96', 'c', 'Al llegar a la puerta del helicóptero, no toque nada y sea pasivo. Déjese introducir a bordo por los', false, '2025-09-13 13:53:10.26777+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('437ae0b7-c1b2-4b4a-b214-1ba4f9c28861', '98d0efd4-a592-4919-8758-f915b72efd96', 'd', 'A bordo, amarre el cable que le envía el helicóptero a un lugar fijo. No lo mantenga asido con las', false, '2025-09-13 13:53:10.267906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95ddb120-5bf9-4c43-b417-5299a22247ce', '3cfcd13a-cab8-4528-a872-ab4d7294e5ad', 'a', 'La posición del metacentro respecto al centro de carena determina que el equilibrio sea estable o', false, '2025-09-13 13:53:10.26818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15312966-d3ae-4aaf-a6c2-8993f81e4323', '3cfcd13a-cab8-4528-a872-ab4d7294e5ad', 'b', 'Una embarcación con altura metacéntrica grande tiene poca estabilidad.', true, '2025-09-13 13:53:10.26831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('276c8fda-1378-40fa-a27d-6c054577b176', '3cfcd13a-cab8-4528-a872-ab4d7294e5ad', 'c', 'Si partimos de una situación de equilibrio y se vacía un tanque a popa del centro de flotación, por debajo del centro de gravedad, provocaremos una disminución de la estabilidad.', false, '2025-09-13 13:53:10.268439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e99eaa00-cb49-47b5-9704-c303f85397f7', '3cfcd13a-cab8-4528-a872-ab4d7294e5ad', 'd', 'El centro de gravedad es el punto donde se concentran todas las fuerzas de empuje que sufre el casco por estar sumergido en un líquido. Meteorología', false, '2025-09-13 13:53:10.268569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a1e112c-9dc6-4c03-bfee-99eb2188f11b', '2d548d8d-f75a-479f-8197-762701d015a5', 'a', 'Es la densidad de moléculas de vapor de agua en el aire.', false, '2025-09-13 13:53:10.268868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb6f7dd7-7e78-470a-be44-3f92b8f59021', '2d548d8d-f75a-479f-8197-762701d015a5', 'b', 'Cuanto mayor sea la temperatura del aire, más cantidad de vapor puede llegar a contener hasta llegar a la saturación.', true, '2025-09-13 13:53:10.269003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8347b8da-61d0-450f-ab01-3e9093aaaa68', '2d548d8d-f75a-479f-8197-762701d015a5', 'c', 'Su valor máximo se alcanza en el Punto de Rocío.', false, '2025-09-13 13:53:10.269156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ea174a7-81af-4fee-afe6-4ae384c5bf0b', '2d548d8d-f75a-479f-8197-762701d015a5', 'd', 'Su valor se expresa en tanto por ciento.', false, '2025-09-13 13:53:10.269287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90f0e116-11fd-48cb-b9d6-416bdbb435f4', 'a04812eb-a577-4581-9ab9-721dd8d43a3a', 'a', 'El gradiente de temperatura y densidad del agua.', true, '2025-09-13 13:53:10.269563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c41347e3-9f28-4904-bf88-c308afef32bc', 'a04812eb-a577-4581-9ab9-721dd8d43a3a', 'b', 'La atracción de la luna.', false, '2025-09-13 13:53:10.269691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c67a419d-214d-4ca7-9cfd-3cba5126c486', 'a04812eb-a577-4581-9ab9-721dd8d43a3a', 'c', 'El viento.', false, '2025-09-13 13:53:10.269819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e690dbd-6dd1-43cb-8f10-6311babba1ee', 'a04812eb-a577-4581-9ab9-721dd8d43a3a', 'd', 'Coriolis.', false, '2025-09-13 13:53:10.26995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c63615a0-ad7c-4ebb-9458-c910c0e02ba5', 'd898ff35-c7e0-4455-b325-cc8781ce299f', 'a', 'Niebla de radiación.', false, '2025-09-13 13:53:10.270218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e3baddf-6d48-495c-a845-5d961b5cf05e', 'd898ff35-c7e0-4455-b325-cc8781ce299f', 'b', 'Niebla de advección.', false, '2025-09-13 13:53:10.270347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b28b56f-8181-4bc3-9ecd-1ca0caace767', 'd898ff35-c7e0-4455-b325-cc8781ce299f', 'c', 'Niebla orográfica.', true, '2025-09-13 13:53:10.270478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7475515b-3b84-43ab-930c-fee8ee78aee0', 'd898ff35-c7e0-4455-b325-cc8781ce299f', 'd', 'Niebla de vapor.', false, '2025-09-13 13:53:10.270605+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e88d1cb-1d5b-45cc-8e4a-91a87c486be3', 'bac222ce-c571-4402-877b-dac9dbde0d45', 'a', 'Entraremos en las tablas psicrométricas con los valores tomados en el psicrómetro del termómetro seco y la diferencia de entre el termómetro seco y húmedo.', false, '2025-09-13 13:53:10.270886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1f4217d-d769-48c1-b473-8e7d8a1b5188', 'bac222ce-c571-4402-877b-dac9dbde0d45', 'b', 'Entraremos en las tablas psicrométricas con los valores tomados en el psicrómetro del termómetro seco y el termómetro húmedo.', true, '2025-09-13 13:53:10.271016+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07a27fda-fc60-483b-bebf-32dc8ca6462c', 'bac222ce-c571-4402-877b-dac9dbde0d45', 'c', 'El psicómetro nos da directamente la humedad relativa del aire y el punto de rocío.', false, '2025-09-13 13:53:10.271144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ede23d83-8a94-4628-a409-67c125ffae8e', 'bac222ce-c571-4402-877b-dac9dbde0d45', 'd', 'Entraremos en las tablas psicrométricas con los valores tomados en el psicrómetro del termómetro seco y la temperatura del agua de mar.', false, '2025-09-13 13:53:10.271276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d38929d9-eba3-4c0a-84e5-748df3ba0d3c', '98616214-3905-4771-8940-42908c621f4d', 'a', 'Frente frío.', true, '2025-09-13 13:53:10.271682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('493660ab-ff34-494a-9dfc-e4b142c40b95', '98616214-3905-4771-8940-42908c621f4d', 'b', 'Frente ocluido.', false, '2025-09-13 13:53:10.27182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98fde195-f97b-4536-ae7d-9dce6ab4d3a4', '98616214-3905-4771-8940-42908c621f4d', 'c', 'Frente térmico.', false, '2025-09-13 13:53:10.271951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c013def-c3a9-4399-ac6a-188ee146eba5', '98616214-3905-4771-8940-42908c621f4d', 'd', 'Frente cálido.', false, '2025-09-13 13:53:10.27208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c98f01c2-e033-4e78-8ad6-53d1f5c0ef3e', 'e2f79e05-961c-478b-b461-b4406d62a3fd', 'a', 'Siroco.', false, '2025-09-13 13:53:10.272347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97ac7070-59b6-42f6-a00b-47bb94ecbac5', 'e2f79e05-961c-478b-b461-b4406d62a3fd', 'b', 'Cudo.', false, '2025-09-13 13:53:10.272475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c43ff1e1-8182-46d0-a854-b538e2527557', 'e2f79e05-961c-478b-b461-b4406d62a3fd', 'c', 'Gregal.', false, '2025-09-13 13:53:10.272604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25e861d4-b87a-49d2-afef-c1562e66a1db', 'e2f79e05-961c-478b-b461-b4406d62a3fd', 'd', 'Lebeche.', true, '2025-09-13 13:53:10.272734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0777c606-1a08-441e-86a7-7d2d58b6f350', 'a3dacc7f-4252-4c86-b128-bb2fc317b3d5', 'a', 'La cantidad de vapor de agua que contiene una masa de aire es la máxima posible.', false, '2025-09-13 13:53:10.273057+00');
