INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f45108e9-f44f-4c24-a6c8-675758a4a1e3', '8c66af80-54cd-4f48-a5c1-c0316270b80a', 'd', 'Rc= 123º; Ihc=2,3 nudos. DE TRANSPORTES, MOVILIDAD                                                                        DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                  Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 03 Seguridad en la mar', true, '2025-09-13 13:53:10.290357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d45b553-2dbd-4d61-adea-8f777956bc60', '85c6b71b-2005-4d7d-9c0f-d05ea4499105', 'a', 'Una bengala de mano.', false, '2025-09-13 13:53:10.290768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8ff1fcd-de8e-4155-b9fa-48dfab95f0ea', '85c6b71b-2005-4d7d-9c0f-d05ea4499105', 'b', 'Un cohete lanza bengalas con paracaídas.', true, '2025-09-13 13:53:10.290902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09b1a66d-40a5-44ff-bbf2-6bc8ea7fa68b', '85c6b71b-2005-4d7d-9c0f-d05ea4499105', 'c', 'Cualquier señal fumígena.', false, '2025-09-13 13:53:10.291034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd0df67f-9f05-4b6e-98c3-f8c8c95aef50', '85c6b71b-2005-4d7d-9c0f-d05ea4499105', 'd', 'Una radiobaliza.', false, '2025-09-13 13:53:10.291171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('501442a7-79e1-4b10-9ab3-1e65fdada34b', '9a5d0162-5e62-4f9a-82eb-f99fb8bc3c04', 'a', 'Los baldes contraincendios pueden utilizarse para achique y transvase de combustible o líquidos', false, '2025-09-13 13:53:10.291446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73f737ca-f328-4990-bdd2-23dc9bf39c54', '9a5d0162-5e62-4f9a-82eb-f99fb8bc3c04', 'b', 'Los extintores adecuados para la extinción de fuegos de origen eléctrico son los de espuma.', false, '2025-09-13 13:53:10.291581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e478a073-f214-423e-b219-89bfb1d4250d', '9a5d0162-5e62-4f9a-82eb-f99fb8bc3c04', 'c', 'La función de un arnés de seguridad es evitar que una persona caiga al agua y quede desconectada de la embarcación.', true, '2025-09-13 13:53:10.291713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4414411-c469-4f93-9dc1-aa9e1804340d', '9a5d0162-5e62-4f9a-82eb-f99fb8bc3c04', 'd', 'Las balsas salvavidas tiene una estabilidad tal que, con su asignación completa de personas y equipo, pueden ser remolcadas hasta una velocidad de 6 nudos en aguas tranquilas.', false, '2025-09-13 13:53:10.291848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97cdb68d-e76f-4f6d-973d-1cbd5ec2e74f', 'e92eb56a-9527-4393-a496-90ecc422550d', 'a', 'No se impaciente aguardando la llegada.', false, '2025-09-13 13:53:10.292128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18147ce6-8257-4f9c-a2e0-7867d9a984fd', 'e92eb56a-9527-4393-a496-90ecc422550d', 'b', 'Antes de la llegada del helicóptero, contacte con sus tripulantes por el Canal 72 de VHF y atienda a su información e instrucciones.', true, '2025-09-13 13:53:10.292259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78f91e5d-aeae-4bf0-b58c-b0153183a5e9', 'e92eb56a-9527-4393-a496-90ecc422550d', 'c', 'Todas las personas a bordo deben ponerse el chaleco salvavidas y recoger la documentación más imprescindible.', false, '2025-09-13 13:53:10.292391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cbb70a9-e4b4-4521-8fa9-bdaf0e8179dc', 'e92eb56a-9527-4393-a496-90ecc422550d', 'd', 'En veleros, arríe las velas y arranque el motor.', false, '2025-09-13 13:53:10.292527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a63d143-cb61-415e-82f4-29b9195a0216', 'abdf91b0-47fe-4901-a071-0103a7474db7', 'a', 'Solo es obligatorio llevar un aro salvavidas con luz y rabiza.', false, '2025-09-13 13:53:10.29281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43e3f52f-a5f5-443a-87c1-1f5e1035d099', 'abdf91b0-47fe-4901-a071-0103a7474db7', 'b', 'La balsa o balsas salvavidas tendrán capacidad para el total de personas a bordo y dispondrán de paquete de emergencia SOLAS tipo A.', true, '2025-09-13 13:53:10.292955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2aa913b-7646-4dd8-b648-68cc6b5b1f10', 'abdf91b0-47fe-4901-a071-0103a7474db7', 'c', 'El número total de chalecos salvavidas dotados con luz será igual al número de personas a bordo.', false, '2025-09-13 13:53:10.293095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95761631-9ecc-4d11-b7a6-59c4d5f3285d', 'abdf91b0-47fe-4901-a071-0103a7474db7', 'd', 'La embarcación estará dotada siempre de un reflector de radar.', false, '2025-09-13 13:53:10.29323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9c7509d-1e73-436c-a51d-5993362603df', '11fe3e95-37a3-4cda-9182-86045eb853eb', 'a', 'El centro de carena coincide con el centro de gravedad.', false, '2025-09-13 13:53:10.29351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36462665-f17f-4efa-b488-7c8ca662e9c3', '11fe3e95-37a3-4cda-9182-86045eb853eb', 'b', 'El centro de gravedad coincide con el metacentro.', false, '2025-09-13 13:53:10.293647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dca95635-7c43-49bd-8ab6-5b2121a7824b', '11fe3e95-37a3-4cda-9182-86045eb853eb', 'c', 'El centro de gravedad está situado por debajo del metacentro.', true, '2025-09-13 13:53:10.293784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19a00d5d-6bbc-4415-9855-e84bc822a3a3', '11fe3e95-37a3-4cda-9182-86045eb853eb', 'd', 'El centro de carena está situado por encima del metacentro.', false, '2025-09-13 13:53:10.293917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f62f483-1d8c-4a7b-b0b2-13709d5ec00e', '64f74593-1baf-4139-b416-39e92ee5fa24', 'a', 'La posición del metacentro respecto al centro de carena determina que el equilibrio sea estable o', false, '2025-09-13 13:53:10.294331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7a60fce-ec6c-4190-aa99-d1f3d0685ce0', '64f74593-1baf-4139-b416-39e92ee5fa24', 'b', 'Una embarcación con altura metacéntrica grande tiene poca estabilidad.', false, '2025-09-13 13:53:10.294468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eeb42e47-573a-4e84-87f7-6d2e913fd43d', '64f74593-1baf-4139-b416-39e92ee5fa24', 'c', 'Si partimos de una situación de equilibrio y se vacía un tanque a popa del centro de flotación, por debajo del centro de gravedad, provocaremos una disminución de la estabilidad.', true, '2025-09-13 13:53:10.2946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f96c2b8f-6609-44a2-a4cb-b9c412e95238', '64f74593-1baf-4139-b416-39e92ee5fa24', 'd', 'El centro de gravedad es el punto donde se concentran todas las fuerzas de empuje que sufre el casco por estar sumergido en un líquido.', false, '2025-09-13 13:53:10.294731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a21f290-3f47-4fd5-a6cd-a127674b4ad6', '71d02e9a-f6c7-425b-9b3a-96c9c53922b4', 'a', 'Se detendrá completamente la embarcación.', false, '2025-09-13 13:53:10.295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ead108b2-9003-4ead-9678-d93f9ffe3fc8', '71d02e9a-f6c7-425b-9b3a-96c9c53922b4', 'b', 'Se hará una llamada de socorro y se activará la radiobaliza manualmente.', false, '2025-09-13 13:53:10.295137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('090efa81-c094-482a-8d23-590534c27e64', '71d02e9a-f6c7-425b-9b3a-96c9c53922b4', 'c', 'Se esperará hasta que la zafa hidrostática de la balsa se active automáticamente.', true, '2025-09-13 13:53:10.295294+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad986e3f-6a65-422d-9836-d68d893d0f9e', '71d02e9a-f6c7-425b-9b3a-96c9c53922b4', 'd', 'Se amarrará a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:10.295437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63eb79b8-abed-4bc0-9418-e5ce4ac4b77a', '1c974e07-e1f1-4276-8bc8-985750ef9157', 'a', 'Aumenta la altura metacéntrica y el buque pierde estabilidad.', false, '2025-09-13 13:53:10.295708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ff9db1e-91d5-4945-9fb6-d4b88812d040', '1c974e07-e1f1-4276-8bc8-985750ef9157', 'b', 'Disminuye la altura metacéntrica y el buque pierde estabilidad.', true, '2025-09-13 13:53:10.295861+00');
