INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e561fc5-0c52-4c26-90c2-6628b7ca945b', '91941c47-1729-4b5e-810f-ed2a4600216d', 'a', 'Para voltear una balsa hay que colocarse a barlovento y subir sobre la botella de aire comprimido para tirar de las cinchas que cruzan la parte inferior de la balsa, mientras otros náufragos levantan desde sotavento.', false, '2025-09-13 13:53:10.296422+00');
