INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d99a826a-2d2f-4372-aa99-539e23fe6606', 'e30a667d-b11b-4e36-aa31-f7386efe54b1', 'c', 'Es un sistema de información que emite datos captados a bordo y que, además, permite obtener los datos de otras embarcaciones que dispongan de él y que lo estén utilizando.', true, '2025-09-13 13:53:10.310722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26f6e64c-1cf9-401c-aa79-3f030f18bfc8', 'e30a667d-b11b-4e36-aa31-f7386efe54b1', 'd', 'Permite ver las embarcaciones a nuestro alrededor, con datos adicionales tales como nombre, MMSI, puerto destino, etc., y además permite tomar demoras.', false, '2025-09-13 13:53:10.310854+00');
