INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d09c9cd8-8544-4a5e-9d4f-3d491d203682', 'df3ee3eb-dc18-4da5-86d9-4e38fe89c662', 'a', 'El francobordo influye en la estabilidad transversal, ya que, al aumentar el francobordo, el ángulo para el cual se anula la estabilidad disminuye.', false, '2025-09-13 13:53:10.320891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e48a3b61-1577-45c2-a519-e0d12183cf09', 'df3ee3eb-dc18-4da5-86d9-4e38fe89c662', 'b', 'El francobordo influye en la estabilidad longitudinal, ya que, al aumentar el francobordo, el ángulo para el cual se anula la estabilidad, también aumenta.', false, '2025-09-13 13:53:10.321032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f9b8779-c03e-47cf-9a75-f0c0b999e881', 'df3ee3eb-dc18-4da5-86d9-4e38fe89c662', 'c', 'El desplazamiento se define como la distancia recorrida por una embarcación.', false, '2025-09-13 13:53:10.321193+00');
