INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c95f8561-e5e7-4aca-afa8-4fcb0d25483b', '0969da7a-b3d2-46a6-bdd6-99eaee548c82', 'c', 'Esféricas, o de castillete o espeque, con franjas verticales rojas o blancas.', false, '2025-09-13 13:53:10.330429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79b29ee3-0535-46ef-bc25-663da97c2158', '0969da7a-b3d2-46a6-bdd6-99eaee548c82', 'd', 'Esféricas, o de castillete o espeque, con franjas horizontales rojas o blancas.', false, '2025-09-13 13:53:10.330567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd259b61-baef-42f7-9764-8771b37eb2bc', '3572fd8e-ba26-4094-ae86-500ba9cc2004', 'a', 'La luz, si tiene, será siempre de color blanco.', false, '2025-09-13 13:53:10.330853+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08bb63c8-f4ca-4c29-adbf-692278d459c2', '3572fd8e-ba26-4094-ae86-500ba9cc2004', 'b', 'Las boyas serán esféricas.', false, '2025-09-13 13:53:10.330994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9474be40-0c38-4860-905d-6264a77eb4b8', '3572fd8e-ba26-4094-ae86-500ba9cc2004', 'c', 'El ritmo de la luz, si tiene, será isofase, de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:10.331135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37f76313-b567-4a5b-8160-fe56bcdd008f', '3572fd8e-ba26-4094-ae86-500ba9cc2004', 'd', 'La marca de tope, si tiene, será un aspa amarilla.', true, '2025-09-13 13:53:10.331276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1ba46f4-5a27-4c27-a6e5-2e9c7e2719d0', 'abb9403a-5256-4a0f-8a7c-72716e4bdffa', 'a', 'El color será blanco y emitirá grupos de dos destellos.', false, '2025-09-13 13:53:10.331571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0708832-e8b5-420b-ad8a-724f6ecf941f', 'abb9403a-5256-4a0f-8a7c-72716e4bdffa', 'b', 'El color será verde y emitirá grupos de dos destellos.', false, '2025-09-13 13:53:10.331716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d50ab4e-b244-4ac2-8553-33a1cb4094c2', 'abb9403a-5256-4a0f-8a7c-72716e4bdffa', 'c', 'El color será verde y emitirá grupos de dos más un destello.', true, '2025-09-13 13:53:10.331881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83b06d63-3040-4f21-8dc8-214a084b7e41', 'e8b492ec-eed9-4920-ae45-8b2846553d11', 'a', 'La longitud del remolque es superior a 100 metros.', false, '2025-09-13 13:53:10.332325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c8b070f-e232-4032-bf20-15b10eaf31c5', 'e8b492ec-eed9-4920-ae45-8b2846553d11', 'b', 'La longitud del remolque es inferior a 100 metros.', false, '2025-09-13 13:53:10.332463+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bcc260f-3730-4bee-b44f-9bafa1a99730', 'e8b492ec-eed9-4920-ae45-8b2846553d11', 'c', 'La longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:10.332602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1b961d1-632a-42f1-ace0-27d384582dad', 'e8b492ec-eed9-4920-ae45-8b2846553d11', 'd', 'La longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:10.332743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6f54750-3c61-4439-a389-369f77b501b0', 'a3fb5428-bbf3-4ba3-8078-eaa0b1ef3183', 'a', 'Existirá riesgo, si la demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:10.33305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1de98629-6f97-438d-9f1a-71092fa2ed71', 'a3fb5428-bbf3-4ba3-8078-eaa0b1ef3183', 'b', 'Siempre existirá riesgo si es evidente una variación apreciable de la demora.', false, '2025-09-13 13:53:10.333186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4737cfd9-267a-4ebf-8601-86210bf3db51', 'a3fb5428-bbf3-4ba3-8078-eaa0b1ef3183', 'c', 'Si existe alguna duda sobre el riesgo de abordaje, se considerará que no existe.', false, '2025-09-13 13:53:10.333318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('347d74cb-e1ea-4f1d-a125-7d62c3a87d1a', 'a3fb5428-bbf3-4ba3-8078-eaa0b1ef3183', 'd', 'La información obtenida por radar tendrá preferencia respecto a la obtenida por otros medios de que disponga el buque a bordo.', false, '2025-09-13 13:53:10.333451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d480c0d-40e0-4e24-92a7-03f7297240b2', '9773b5ce-86f8-4a52-8e34-cb102b91ba34', 'a', 'Deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.333727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d1a8ee5-7381-46f8-a77c-194d09c285c2', '9773b5ce-86f8-4a52-8e34-cb102b91ba34', 'b', 'Deberá mantener rumbo y velocidad.', false, '2025-09-13 13:53:10.333861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0151e07c-e449-40ba-96a7-6558d56cf6e7', '9773b5ce-86f8-4a52-8e34-cb102b91ba34', 'd', 'Deberá caer a la banda de babor y hará sonar su señal de niebla para que el otro buque caiga a también a babor.', false, '2025-09-13 13:53:10.334264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8420384-5de3-4e7a-b6e9-c32d45206d6a', '6a3b6d98-f96c-439b-801e-c55192dd4816', 'a', 'Navegar en la vía de circulación apropiada, siguiendo la dirección general de la corriente de tráfico indicada para dicha vía.', false, '2025-09-13 13:53:10.334548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e8f3ec1-36a7-463f-adb1-6267d1ae553b', '6a3b6d98-f96c-439b-801e-c55192dd4816', 'b', 'Mantener su rumbo fuera de la línea de separación o de la zona de separación del tráfico.', false, '2025-09-13 13:53:10.334683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eb52c01-0d88-4f04-bf23-524e857b683a', '6a3b6d98-f96c-439b-801e-c55192dd4816', 'c', 'Al entrar o salir de una vía de circulación, hacerlo por sus extremos.', false, '2025-09-13 13:53:10.334822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65175395-21ec-4dd4-9a7c-96f101495a68', '6a3b6d98-f96c-439b-801e-c55192dd4816', 'd', 'Fondear dentro de un dispositivo de separación del tráfico o en las zonas próximas a sus', true, '2025-09-13 13:53:10.334964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad85d001-4fb1-444b-8d9f-1ba636b8b1b8', 'f62d3bfc-a3a5-4a95-8193-07c72b9af2c2', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:10.335253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09fb84ba-6138-46f1-bc50-d404a58970b6', 'f62d3bfc-a3a5-4a95-8193-07c72b9af2c2', 'b', 'Cada uno de ellos caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:10.335386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7841ed1-9f20-4bd6-b423-56664538ccdc', 'f62d3bfc-a3a5-4a95-8193-07c72b9af2c2', 'c', 'Si existe dudas sobre tal situación, se supondrá que no existe.', false, '2025-09-13 13:53:10.33552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64daecca-c4f4-4dc0-a0a2-cc9406634734', 'f62d3bfc-a3a5-4a95-8193-07c72b9af2c2', 'd', 'Tras maniobrar, no podrán seguir navegando a rumbos opuestos o casi opuestos.', false, '2025-09-13 13:53:10.335659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18a7219d-56e4-48c7-94d2-7d7ed9f8b155', 'ecde8360-9c24-4339-91fd-6114b16cd961', 'a', 'Encenderá la luz de alcance intermitentemente para avisar del peligro al otro buque.', false, '2025-09-13 13:53:10.335948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5777364-8b6e-4a0b-9faf-d6e53d2769f3', 'ecde8360-9c24-4339-91fd-6114b16cd961', 'b', 'Maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', true, '2025-09-13 13:53:10.33608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7232a541-180a-49fa-a51a-ce1b042bbb22', 'ecde8360-9c24-4339-91fd-6114b16cd961', 'c', 'No debe maniobrar en ningún caso, sino que parará máquinas y suprimirá la arrancada hasta que le haya rebasado el otro buque.', false, '2025-09-13 13:53:10.336218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d40dce13-abd1-417e-b0fa-7ed759ad5242', 'ecde8360-9c24-4339-91fd-6114b16cd961', 'd', 'Caerá obligatoriamente a estribor de forma que pase por la banda de babor del otro.', false, '2025-09-13 13:53:10.336351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2168792-8ae8-4de7-a727-1117a0344ef5', 'f0779571-6099-4912-9906-862b76649e48', 'a', 'En determinadas circunstancias el capitán puede ser eximido de dicha responsabilidad.', false, '2025-09-13 13:53:10.336634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adee4822-3e3a-4930-93f6-58bc45034577', 'f0779571-6099-4912-9906-862b76649e48', 'b', 'Se limita la responsabilidad únicamente al propietario.', false, '2025-09-13 13:53:10.336767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fea9cfc-a6ec-4fe5-ae43-6e3449348855', 'f0779571-6099-4912-9906-862b76649e48', 'c', 'La dotación está eximida de toda responsabilidad.', false, '2025-09-13 13:53:10.336901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52c1a0f2-8c19-49f0-8692-990d654e763a', 'df9eb9a0-2eb0-465c-95eb-47c584709213', 'c', 'No se mueve.', false, '2025-09-13 13:53:10.357861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da6c5144-2ae2-4d8f-b5ef-500ceafd1d99', 'abb9403a-5256-4a0f-8a7c-72716e4bdffa', 'd', 'El color será amarillo y emitirá grupos de tres más un destello.', false, '2025-09-13 13:53:10.332031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5089cb85-27ff-4a94-8d7c-edeee4aeda8d', 'f0779571-6099-4912-9906-862b76649e48', 'd', 'Ninguna disposición exime a un buque, o a su propietario, al Capitán o a la dotación del mismo.', true, '2025-09-13 13:53:10.337037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33adac05-e71f-4c2b-b27e-f6d35cd043a3', '37f087b0-3353-422b-a9f3-7b46a4944ce9', 'a', 'Una señal fumígena que produzca una densa humareda de color naranja.', true, '2025-09-13 13:53:10.33732+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1045082-46d9-455f-afda-afc2394b15f0', '37f087b0-3353-422b-a9f3-7b46a4944ce9', 'b', 'Un disparo de cañón u otra señal detonante aislada.', false, '2025-09-13 13:53:10.337452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91f15d01-5866-406d-bf48-a27d2f596bb7', '37f087b0-3353-422b-a9f3-7b46a4944ce9', 'c', 'Un sonido intermitente producido por un aparato de señales de niebla.', false, '2025-09-13 13:53:10.337583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12ff23dd-db96-45db-a861-cfeb5a422089', '37f087b0-3353-422b-a9f3-7b46a4944ce9', 'd', 'La señal "HL" del Código Internacional de Señales.', false, '2025-09-13 13:53:10.337714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cbe5420-3248-427b-9196-dc1bbde32537', 'b0cb3d37-f946-4ee9-897a-7762bc4dba2b', 'a', 'Una nave de vuelo rasante que navegue por la superficie.', false, '2025-09-13 13:53:10.338007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffaffd23-571c-44a3-bc7b-39548e8f6984', 'b0cb3d37-f946-4ee9-897a-7762bc4dba2b', 'b', 'Un buque de vela.', false, '2025-09-13 13:53:10.338143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7475924-c730-44c7-a5ba-7f201525537e', 'b0cb3d37-f946-4ee9-897a-7762bc4dba2b', 'c', 'Un buque con capacidad de maniobra restringida.', true, '2025-09-13 13:53:10.338277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('474f12e1-fa2e-4a01-a1b7-949b1318d57a', 'b0cb3d37-f946-4ee9-897a-7762bc4dba2b', 'd', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:10.338413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46d4227f-e08a-43ac-9ed6-9c5b6856cf14', '174cb106-b6d9-4827-bb91-665c4e42209a', 'a', 'El buque reducirá su velocidad, pero sin llegar nunca a suprimir su arrancada.', false, '2025-09-13 13:53:10.338702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afea5138-bf62-451d-8330-1120919b5a53', '174cb106-b6d9-4827-bb91-665c4e42209a', 'b', 'En ningún caso el buque llegará a invertir sus medios de propulsión.', false, '2025-09-13 13:53:10.338839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9790caf2-a379-4404-8942-e9f29a9f241c', '174cb106-b6d9-4827-bb91-665c4e42209a', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasado y en franquía.', true, '2025-09-13 13:53:10.338974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fafa63d-eb4f-44dd-9683-0655910d4fce', '174cb106-b6d9-4827-bb91-665c4e42209a', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños. Maniobra y navegación.', false, '2025-09-13 13:53:10.339214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b08d73f-09ea-45d8-9ef4-c2ce61d964fb', 'e7311e08-b353-4ec2-b026-928fbe98778d', 'a', 'Fase inicial.', false, '2025-09-13 13:53:10.339495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8390ef4-6cf4-4085-b925-eb543ff0cab3', 'e7311e08-b353-4ec2-b026-928fbe98778d', 'b', 'Fase variable.', true, '2025-09-13 13:53:10.339632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98b9f61f-8a98-4347-afdf-a63bb7160538', 'e7311e08-b353-4ec2-b026-928fbe98778d', 'c', 'Fase de maniobra.', false, '2025-09-13 13:53:10.339767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ed27fbf-0f95-4430-8189-7e58ec20fdca', 'e7311e08-b353-4ec2-b026-928fbe98778d', 'd', 'Fase uniforme.', false, '2025-09-13 13:53:10.339904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d80faaa-249f-443b-a51d-dba463958d9b', 'de7eb812-f475-4480-a926-5ac007c58feb', 'a', 'Disminuye la acción del timón con marcha avante y hélice avante.', false, '2025-09-13 13:53:10.340188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82cd285d-0bec-4d40-a977-62b886e144f6', 'de7eb812-f475-4480-a926-5ac007c58feb', 'b', 'Aumenta la acción del timón con marcha avante y hélice avante.', true, '2025-09-13 13:53:10.340323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a639e3fb-4625-4bf9-a739-23dd09540497', 'de7eb812-f475-4480-a926-5ac007c58feb', 'c', 'Disminuye la acción del timón con marcha atrás y hélice atrás.', false, '2025-09-13 13:53:10.340458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96afca23-4cda-462f-b4d2-4fcfbcf05ff0', 'e58cd4c2-5ea0-42ba-a433-7b0cc9766032', 'a', 'Los daños en la obra viva y las posibles vías de agua.', false, '2025-09-13 13:53:10.340872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f92ff6df-5525-48c7-96a8-fefe7f5edf64', 'e58cd4c2-5ea0-42ba-a433-7b0cc9766032', 'b', 'La resistencia estructural del casco y su estabilidad.', false, '2025-09-13 13:53:10.341009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b7cf2b9-388c-4c6d-a999-5c9089b81145', 'e58cd4c2-5ea0-42ba-a433-7b0cc9766032', 'c', 'La naturaleza del fondo en el que ha varado.', false, '2025-09-13 13:53:10.341145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3c816ff-2e3b-4ffa-a8d0-246408704ba7', 'e58cd4c2-5ea0-42ba-a433-7b0cc9766032', 'd', 'La disponibilidad del ancla y del equipo de fondeo para facilitar la operación.', true, '2025-09-13 13:53:10.341279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f69395d-fc9b-473b-8b09-3f91112c456d', '58d4db27-35e7-40ed-a0ca-57b74d700efc', 'a', 'La mejor manera de prevenir un abordaje es navegar siempre a un régimen moderado, no superando nunca los 6 nudos.', false, '2025-09-13 13:53:10.341556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8eb9956f-bf55-4457-9865-ffb01ac682e1', '58d4db27-35e7-40ed-a0ca-57b74d700efc', 'b', 'La maniobra que se efectúe para evitar un abordaje será tal que el buque pase a una distancia segura del otro, comprobándose su eficacia hasta que el otro buque esté pasado y en franquía.', true, '2025-09-13 13:53:10.34169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('418b2f56-fcf7-46cb-ba6d-541b351328f6', '58d4db27-35e7-40ed-a0ca-57b74d700efc', 'c', 'Tras un abordaje hay que abandonar inmediatamente la embarcación.', false, '2025-09-13 13:53:10.34183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e832365-c8b2-4efd-b736-8b3c8a665518', '58d4db27-35e7-40ed-a0ca-57b74d700efc', 'd', 'Cuando se tenga la certeza de no ser el culpable del abordaje es muy conveniente formular una declaración de lesividad ante el juzgado.', false, '2025-09-13 13:53:10.341968+00');
