INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('613fe169-e97d-496d-bcef-d472726655d3', '9c4061af-cb10-492a-8de3-c5245856c295', 'c', 'Cuando el ancla no se queda firme en el fondo, provocando un desplazamiento del barco a sotavento, se dice que garrea.', true, '2025-09-13 13:53:10.355171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d0110d2-a036-48b7-97a1-5dd1c630edc4', '9c4061af-cb10-492a-8de3-c5245856c295', 'd', 'Un barco fondea a la gira utilizando dos anclas por la proa, procurando que la longitud de las líneas de fondeo sea idéntica para las dos anclas.', false, '2025-09-13 13:53:10.355303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13065dde-632b-47d1-b47a-8910a8993481', '06d3005b-9626-4eea-8a5a-8da79f72f5f4', 'a', 'Mantendremos el rumbo de aguja.', false, '2025-09-13 13:53:10.355572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdad256a-d592-4d71-91a5-d6846ef55d53', '06d3005b-9626-4eea-8a5a-8da79f72f5f4', 'b', 'Orientaremos la proa de la embarcación a barlovento.', true, '2025-09-13 13:53:10.355705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fc47f44-052e-4cb0-84af-93d6c1950dc0', '06d3005b-9626-4eea-8a5a-8da79f72f5f4', 'c', 'Echaremos el ancla flotante y seguiremos a rumbo.', false, '2025-09-13 13:53:10.355845+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2258ec1c-fe61-476e-826c-737b36db660e', '06d3005b-9626-4eea-8a5a-8da79f72f5f4', 'd', 'Haremos sonar la bocina.', false, '2025-09-13 13:53:10.355975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('292d8c8a-c712-463a-9f6a-a39b058b12da', '33e9b4d8-5311-4248-baa0-7e3377536de0', 'a', '900 061 061', false, '2025-09-13 13:53:10.356268+00');
