INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30332793-480a-47c4-b152-14da68bff83e', '33e9b4d8-5311-4248-baa0-7e3377536de0', 'c', '900 202 202', true, '2025-09-13 13:53:10.356528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e8d9781-3b1b-4d9d-8cf7-fce62094ffcf', '33e9b4d8-5311-4248-baa0-7e3377536de0', 'd', '900 112 112', false, '2025-09-13 13:53:10.356656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ac6bdff-55df-4838-8494-2d1224739479', '53347d75-9e1c-4b0b-9063-706d2891e5eb', 'a', 'Mejoraremos la navegación con el mar por la amura.', true, '2025-09-13 13:53:10.356928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24e36cbc-74e3-4aaf-8692-dda2c7454d38', '53347d75-9e1c-4b0b-9063-706d2891e5eb', 'b', 'Mejoraremos la maniobrabilidad si aumentamos la velocidad.', false, '2025-09-13 13:53:10.357064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0ae8b13-7058-4b8e-b522-8345ee8a619d', '53347d75-9e1c-4b0b-9063-706d2891e5eb', 'c', 'Al disminuir la sonda aumentará la velocidad de la embarcación.', false, '2025-09-13 13:53:10.357195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f32a45c3-f035-42e1-82bf-82051b186112', '53347d75-9e1c-4b0b-9063-706d2891e5eb', 'd', 'Disminuirán las cabezadas al reducirse la altura de la ola.', false, '2025-09-13 13:53:10.357326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a9b2936-85bf-42c2-a711-8c13cfca26a2', 'df9eb9a0-2eb0-465c-95eb-47c584709213', 'a', 'Cabecea lentamente.', false, '2025-09-13 13:53:10.357594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9693515-17ae-4ffa-82bb-36b451c7128b', '7aade994-79cb-4f8f-b2ee-a3ae4fbb1748', 'c', 'l=36º 05,3´N L=005º 55,6´W.', false, '2025-09-13 13:53:10.350607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a65c9d4-608d-4641-b679-7e6337c694ec', '7aade994-79cb-4f8f-b2ee-a3ae4fbb1748', 'a', 'l=36º 05,3´N L=005º 55,6´W.', false, '2025-09-13 13:53:10.350339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9529bed4-4456-4a7f-b5d0-57249a3f5c1c', '7aade994-79cb-4f8f-b2ee-a3ae4fbb1748', 'b', 'l=36º 06,5´N L=006º 02,4´W.', false, '2025-09-13 13:53:10.350474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7d6fefe-7775-4786-9b1f-0c5d2a8bbe21', 'df9eb9a0-2eb0-465c-95eb-47c584709213', 'd', 'Balancea rápidamente.', true, '2025-09-13 13:53:10.357996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc48b2bb-dd25-4363-bd52-bc56554c58dc', '1821028c-853e-430a-ab42-a71b1bb1343c', 'a', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 25 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', false, '2025-09-13 13:53:10.358275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a3e804f-a646-475d-9261-2610106d04a3', '1821028c-853e-430a-ab42-a71b1bb1343c', 'b', 'Los desechos de los alimentos deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', false, '2025-09-13 13:53:10.358405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b412f55-28b8-47ea-ab0e-fb5374e6995f', '1821028c-853e-430a-ab42-a71b1bb1343c', 'c', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', true, '2025-09-13 13:53:10.358534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce3df06c-5df1-4220-919c-53f991cc21b9', '1821028c-853e-430a-ab42-a71b1bb1343c', 'd', 'Los desechos de los alimentos podrán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:10.35877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f968afb-4a1c-4944-8c22-6d50dbb4048a', 'f15286e2-6f21-4622-ba46-b3e4135a234f', 'a', 'Deberá alejarse de la zona al menos 200 metros, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.359043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8c9f12c-6822-4242-abcd-2435eedbf80a', 'f15286e2-6f21-4622-ba46-b3e4135a234f', 'b', 'Deberá alejarse de la zona al menos 200 millas náuticas, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.359176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c702f38-aeb9-4322-8012-9766345f0634', 'f15286e2-6f21-4622-ba46-b3e4135a234f', 'c', 'En ningún caso podrá fondear la embarcación, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:10.359306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e78ed377-2f12-40ad-9d42-1217189966eb', 'f15286e2-6f21-4622-ba46-b3e4135a234f', 'd', 'Se podrá fondear con finalidad exclusiva de recreo, siempre que no pongan en peligro la seguridad de la vida humana en la mar o de la navegación, debiendo navegar a una velocidad no superior a 3 nudos, adoptando las precauciones necesarias.', true, '2025-09-13 13:53:10.359436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e26e864f-71a2-44df-89a0-685aa96e01da', '5e11bfc3-1521-4909-bb14-31efdf350d7f', 'a', 'Blanca y grupos de dos destellos.', true, '2025-09-13 13:53:10.359713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38189596-16d8-4bef-bcd2-f8593fa7d71a', '5e11bfc3-1521-4909-bb14-31efdf350d7f', 'b', 'Roja y grupos de dos destellos.', false, '2025-09-13 13:53:10.359852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a485d5e-293f-4118-8879-ceba813b02cc', '5e11bfc3-1521-4909-bb14-31efdf350d7f', 'c', 'Blanca y grupos de tres destellos.', false, '2025-09-13 13:53:10.359987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39e7e102-fa26-48a6-9612-0f09645111f7', '5e11bfc3-1521-4909-bb14-31efdf350d7f', 'd', 'Roja y grupos de tres destellos.', false, '2025-09-13 13:53:10.360122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ae4b9a1-5d96-4945-ae45-10adb1cef7a3', '010cd457-a806-4b26-bc5c-03a4e32cb389', 'a', 'Un cono verde con el vértice hacia arriba.', true, '2025-09-13 13:53:10.360397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72a591b9-8fee-4b1e-bb12-8a9dd416f390', '010cd457-a806-4b26-bc5c-03a4e32cb389', 'b', 'Un cono verde con el vértice hacia abajo.', false, '2025-09-13 13:53:10.360531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('151fe1e8-849a-434a-afe2-918e9b944f41', '010cd457-a806-4b26-bc5c-03a4e32cb389', 'c', 'Un cono rojo con el vértice hacia arriba.', false, '2025-09-13 13:53:10.360662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f8421b1-ab8f-451a-a202-c97f25630958', '010cd457-a806-4b26-bc5c-03a4e32cb389', 'd', 'Un cono rojo con el vértice hacia abajo.', false, '2025-09-13 13:53:10.360802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90628a79-041c-4a4a-a952-c6f3dde6b779', 'fe20ca7c-f9b1-48cf-a48f-adfec61dbc36', 'a', 'Una marca cardinal recibe el nombre del cuadrante en el que está colocada.', false, '2025-09-13 13:53:10.361077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79aebd01-a81a-45cc-845f-a3927dc5a009', 'fe20ca7c-f9b1-48cf-a48f-adfec61dbc36', 'b', 'Las marcas cardinales y su uso, son las mismas para la Región A y la Región B.', false, '2025-09-13 13:53:10.361212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6513b65-70be-4dd8-ab9f-5a84a5f5e352', 'fe20ca7c-f9b1-48cf-a48f-adfec61dbc36', 'c', 'El nombre de una marca cardinal indica que se ha de evitar pasar por el cuadrante correspondiente a ese nombre.', true, '2025-09-13 13:53:10.361341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb5fb7a8-78ec-4b7b-9f29-b56d4778bc3e', 'fe20ca7c-f9b1-48cf-a48f-adfec61dbc36', 'd', 'Una marca cardinal puede ser utilizada para llamar la atención sobre una configuración especial', false, '2025-09-13 13:53:10.36147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a5103e9-bb6a-43f0-b937-c7fffab71ad7', '4938cf61-bd54-4bac-ad98-d5d4843cf543', 'a', 'Marca especial.', false, '2025-09-13 13:53:10.361737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c30a07a2-4406-42f2-9473-bcee7c8f72f4', '4938cf61-bd54-4bac-ad98-d5d4843cf543', 'b', 'Marca de peligros nuevos.', false, '2025-09-13 13:53:10.361898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1cf1e4b-7488-4210-9e08-256b3b420bc6', '4938cf61-bd54-4bac-ad98-d5d4843cf543', 'c', 'Marca de peligro aislado.', true, '2025-09-13 13:53:10.362035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1ca9d51-275e-4dca-be5f-f7f8ee310b2d', '4938cf61-bd54-4bac-ad98-d5d4843cf543', 'd', 'Marca cardinal.', false, '2025-09-13 13:53:10.362168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cc35d1a-4c2f-45d7-9ebc-789617dc4873', '067bee5d-21d5-4b5c-9da4-b14fdd00f7db', 'a', 'Deben llevar letras o cifras, así como un pictograma, para indicar su objetivo, utilizando la simbología apropiada de la Organización Hidrográfica Internacional.', false, '2025-09-13 13:53:10.362445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8b03457-058a-437d-a799-99a8bf093143', '067bee5d-21d5-4b5c-9da4-b14fdd00f7db', 'b', 'Pueden llevar letras o cifras, añadiendo siempre un pictograma, para indicar su objetivo, utilizando la simbología apropiada del Sistema de Balizamiento Marítimo español.', false, '2025-09-13 13:53:10.362577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b627d554-c8d3-4913-ab64-e4260451d649', '067bee5d-21d5-4b5c-9da4-b14fdd00f7db', 'c', 'Pueden llevar letras o cifras y también pueden incluir un pictograma, para indicar su objetivo, utilizando la simbología apropiada de la Organización Hidrográfica Internacional.', true, '2025-09-13 13:53:10.362708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f12210cf-613f-46fe-af39-d5eff4fdf394', '067bee5d-21d5-4b5c-9da4-b14fdd00f7db', 'd', 'Deben llevar letras o cifras, y pueden incluir un pictograma, para indicar su objetivo, utilizando la simbología apropiada del Sistema de Balizamiento Marítimo. Reglamento (RIPA).', false, '2025-09-13 13:53:10.362847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('005ef8b9-0455-4b1f-8985-d39df42e9036', 'ed8e006a-428d-4819-86af-18a12e23e128', 'a', 'Los buques de eslora igual o superior a 12 metros.', false, '2025-09-13 13:53:10.363118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff27c577-e7a1-4753-aa62-e1d0b7e62ac1', 'ed8e006a-428d-4819-86af-18a12e23e128', 'b', 'Los buques de eslora inferior a 12 metros.', false, '2025-09-13 13:53:10.363247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bec0b48-83fb-4df8-a3fc-da294dc2e622', 'ed8e006a-428d-4819-86af-18a12e23e128', 'c', 'Los buques de eslora inferior a 20 metros.', false, '2025-09-13 13:53:10.36348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51ac9e10-acf6-43cf-a77d-6a7df3b1d7b6', 'ed8e006a-428d-4819-86af-18a12e23e128', 'd', 'Los buques de eslora igual o superior a 20 metros.', true, '2025-09-13 13:53:10.363611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7c43f79-3b8a-4a85-a070-adb6278ef747', '2695534e-7eea-4e26-8e70-f4620a6535a2', 'a', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por estribor se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:10.363901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04809708-aa74-449b-96ea-7f98e4f6b2b4', '2695534e-7eea-4e26-8e70-f4620a6535a2', 'b', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a sotavento se mantendrá apartado de la derrota del que esté a barlovento.', false, '2025-09-13 13:53:10.364035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08c79459-8d02-4f29-a25a-87d7e6f28668', '2695534e-7eea-4e26-8e70-f4620a6535a2', 'c', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a barlovento se mantendrá apartado de la derrota del que esté a sotavento.', true, '2025-09-13 13:53:10.364169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c5a9a53-c2a8-4aaf-885c-d686ea8b4ca5', '2695534e-7eea-4e26-8e70-f4620a6535a2', 'd', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor mantendrá el mismo rumbo y velocidad.', false, '2025-09-13 13:53:10.364321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef15dc49-1a88-4cba-a2ac-4d1112104f18', '7c00aad9-e03c-453b-b20a-6abd1bd6079d', 'a', 'Por lo menos tres pitadas cortas y rápidas.', false, '2025-09-13 13:53:10.364617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beeb7c21-4494-4254-a4d6-003211e835d7', '7c00aad9-e03c-453b-b20a-6abd1bd6079d', 'b', 'Por lo menos cinco pitadas cortas y rápidas.', true, '2025-09-13 13:53:10.364758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11c90a52-1e78-493b-be0e-a1f07aa12076', '7c00aad9-e03c-453b-b20a-6abd1bd6079d', 'c', 'Por lo menos tres pitadas largas y rápidas.', false, '2025-09-13 13:53:10.364917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80d71307-d705-4c76-ad4e-e8665deb8936', '7c00aad9-e03c-453b-b20a-6abd1bd6079d', 'd', 'Por lo menos cinco pitadas largas y rápidas.', false, '2025-09-13 13:53:10.365055+00');
