INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aba2c947-f09d-4e62-86a4-f4b9f67e1952', 'd677e7f2-0f16-4548-bb61-001b48e1381d', 'a', 'La luz de tope.', true, '2025-09-13 13:53:10.366769+00');
