INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6390e46a-6f77-4533-8528-805a94f6036c', 'e6f8bd54-7514-4a0f-a3d3-6c8b163bafb1', 'a', 'Que no está navegando.', false, '2025-09-13 13:53:10.36746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9da4772-d0ab-4087-a1cd-68e96a522587', 'e6f8bd54-7514-4a0f-a3d3-6c8b163bafb1', 'b', 'Que no le es de aplicación el citado reglamento.', false, '2025-09-13 13:53:10.367594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14ea0103-2e33-4dab-b20b-20182ff8c64e', 'e6f8bd54-7514-4a0f-a3d3-6c8b163bafb1', 'c', 'En navegación.', true, '2025-09-13 13:53:10.367733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb556126-ade3-4656-bfe8-9fe71c7b605c', 'e6f8bd54-7514-4a0f-a3d3-6c8b163bafb1', 'd', 'A la espera de órdenes.', false, '2025-09-13 13:53:10.367868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a26d4f6-0d1c-4679-a696-575b0d397a89', '3138df8e-b9a1-45b2-8eed-85a539c2b595', 'a', 'Los buques de propulsión mecánica que naveguen en una vía de circulación.', true, '2025-09-13 13:53:10.368146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c33d4d6-ea45-4491-8887-61437b56b655', '3138df8e-b9a1-45b2-8eed-85a539c2b595', 'b', 'Los buques de vela que naveguen en una vía de circulación.', false, '2025-09-13 13:53:10.368297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f13d579c-a11e-4104-a03a-bca3c0d69757', '3138df8e-b9a1-45b2-8eed-85a539c2b595', 'c', 'Cualquier buque que naveguen en una vía de circulación.', false, '2025-09-13 13:53:10.368587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a65b8f47-7994-40d2-94ab-01f3bfb955bb', '3138df8e-b9a1-45b2-8eed-85a539c2b595', 'd', 'Los buques dedicados a la pesca que naveguen en una vía de circulación.', false, '2025-09-13 13:53:10.368757+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5739b0d3-f55e-428c-b5b2-50dbd1d0d066', '17fc5faf-b158-4a9b-991b-88c6a39d4e1c', 'a', 'Aumentar la velocidad.', false, '2025-09-13 13:53:10.369084+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b028b5d6-75ec-400d-a42c-f9db159c3916', '17fc5faf-b158-4a9b-991b-88c6a39d4e1c', 'b', 'Cambiar solamente de rumbo.', true, '2025-09-13 13:53:10.369223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9b5a8c5-f1ee-4b21-8dec-b9915f8456df', '17fc5faf-b158-4a9b-991b-88c6a39d4e1c', 'c', 'Suprimir toda su arrancada parando.', false, '2025-09-13 13:53:10.369356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('368968f5-b7d3-4366-9212-79eac42d262a', '17fc5faf-b158-4a9b-991b-88c6a39d4e1c', 'd', 'Invertir sus medios de propulsión.', false, '2025-09-13 13:53:10.369487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a995cf7d-9f30-467f-8833-016177045c7e', 'e5ec9112-cf3d-4599-8a75-1ff172a7796e', 'b', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste otro, evitando cortarle la popa.', false, '2025-09-13 13:53:10.369942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d16be36-13b8-4dc3-952f-9cc46d300f9d', 'e5ec9112-cf3d-4599-8a75-1ff172a7796e', 'c', 'El de mayor tonelaje tendrá que detenerse para facilitar el paso.', false, '2025-09-13 13:53:10.370086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0186b2e2-a010-4bad-a7e7-6035a884a766', 'e5ec9112-cf3d-4599-8a75-1ff172a7796e', 'd', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste Maniobra y navegación.', true, '2025-09-13 13:53:10.370221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9124f756-6fea-47d0-b99c-102471d15291', '625ce2c1-410b-4415-aac9-f94f1727241a', 'a', 'La popa cae a estribor.', false, '2025-09-13 13:53:10.370502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ee53689-efcd-4076-bd14-cf098a72f9f2', '625ce2c1-410b-4415-aac9-f94f1727241a', 'b', 'La popa cae a babor.', true, '2025-09-13 13:53:10.370636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3a751a5-7246-4849-9bc4-9d01ff87e127', '625ce2c1-410b-4415-aac9-f94f1727241a', 'c', 'La popa no cae a ningún costado.', false, '2025-09-13 13:53:10.370786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da20bdd6-2a13-4253-9c05-52052344bf9d', '625ce2c1-410b-4415-aac9-f94f1727241a', 'd', 'La popa cae inicialmente a estribor y luego a babor.', false, '2025-09-13 13:53:10.370929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70e5f47b-c9d2-4e5e-90bc-5435302f8527', 'b432a41e-232f-41ec-94e9-280ed016f702', 'a', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de babor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', true, '2025-09-13 13:53:10.371207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25a95e2c-eb10-4f54-8438-0ac1edb2c40e', 'b432a41e-232f-41ec-94e9-280ed016f702', 'b', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de estribor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', false, '2025-09-13 13:53:10.371341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6024fcc7-c058-498e-be65-efe01ec17c15', 'b432a41e-232f-41ec-94e9-280ed016f702', 'c', 'Atracar de punta con la proa a otra embarcación; se recomienda abarloarse por la sencillez de la', false, '2025-09-13 13:53:10.371473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f4f750c-57fd-47cb-83da-05da028e4751', 'b432a41e-232f-41ec-94e9-280ed016f702', 'd', 'Atracar con la popa a otra embarcación; siempre se recomienda cuando es necesario desembarcar mejor y tener la maniobra de salida más clara. Emergencias en la mar.', false, '2025-09-13 13:53:10.371607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5379481d-77a6-4476-85fc-4daebe2d1429', '62fcf580-5323-4baa-995b-daa04499f8a0', 'a', 'Saltando en parejas cogidos por los brazos, con el fin de poder agruparnos lo más rápido posible y ser más visibles.', false, '2025-09-13 13:53:10.371896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d5e11cc-f229-4496-9e00-bc7db6506447', '62fcf580-5323-4baa-995b-daa04499f8a0', 'b', 'Saltando por barlovento de pie y con el chaleco puesto. Solo en determinados casos, como por ejemplo un incendio en esa banda, se podría saltar por sotavento.', false, '2025-09-13 13:53:10.372027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91466b25-d9a2-4d07-9873-08a1ef03ce8b', '62fcf580-5323-4baa-995b-daa04499f8a0', 'c', 'Saltando al agua de pie, con las piernas y rodillas juntas, sujetando el chaleco y tapándose la nariz. Si una vez en el agua hubiera que nadar, deberá hacerse de espaldas.', true, '2025-09-13 13:53:10.372157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e9ba97b-583d-49e6-a954-eb6028f729f9', '62fcf580-5323-4baa-995b-daa04499f8a0', 'd', 'Se deberá lanzar al agua el chaleco salvavidas y saltar al agua adoptando la postura fetal. Una vez en el agua habrá que ponérselo e intentar nadar lo más rápidamente posible hacia cualquier objeto flotante para reducir la hipotermia.', false, '2025-09-13 13:53:10.372399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('686ff5ac-6d99-4429-8d6d-144a4f397b10', '8779bf6d-1d46-4ff6-ba42-8aa43c874cba', 'a', 'Disco de goma, fieltro o lona atravesado por un eje roscado con un brazo articulado transversal.', false, '2025-09-13 13:53:10.372675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bc7394d-4b73-446c-8d18-bec1ef0dbb3b', '8779bf6d-1d46-4ff6-ba42-8aa43c874cba', 'b', 'Orificio más pequeño que un imbornal por donde se produce una vía de agua.', false, '2025-09-13 13:53:10.372824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3222db52-a0e9-4e8b-8b46-7cfb7b2aa700', '8779bf6d-1d46-4ff6-ba42-8aa43c874cba', 'c', 'Cuña cónica de madera para tapar vías de agua por orificios de forma circular.', true, '2025-09-13 13:53:10.372978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae43c512-1ad7-44ab-98e8-a53440cfb295', '8779bf6d-1d46-4ff6-ba42-8aa43c874cba', 'd', 'Tablero de contrachapado marino sellado al casco con silicona para tapar vías de agua.', false, '2025-09-13 13:53:10.373115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4df9acce-3ac4-423c-b966-2b86372d9799', '123a27a1-c13d-4960-b370-915829b63828', 'a', 'Si una persona sufre una fuerte contusión en el abdomen, se le proporcionara reposo absoluto, manteniéndose en observación y se realizarán consultas radiomédicas.', false, '2025-09-13 13:53:10.373392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a3d5899-ad89-4d2d-ad1d-4bd6642f6702', '123a27a1-c13d-4960-b370-915829b63828', 'b', 'En una hemorragia arterial la sangre mana a impulsos y habrá que realizar un torniquete un poco por encima de la herida.', false, '2025-09-13 13:53:10.373531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d467bd63-94be-4beb-8de4-835d11f3abea', '123a27a1-c13d-4960-b370-915829b63828', 'd', 'Las quemaduras de tercer grado son las producidas por acción intensa y directa de una llama o sólido incandescente y la costra que se produce no debe ser destruida. Meteorología', false, '2025-09-13 13:53:10.373817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('347512cf-6046-468b-8d3f-dec35f2121ab', '9a428242-1109-4c47-8939-61722355f872', 'a', 'Una tendencia a la mejoría.', false, '2025-09-13 13:53:10.374099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9764ea4-0955-45b3-8029-f69972b6623d', '9a428242-1109-4c47-8939-61722355f872', 'b', 'Una tendencia a la mejoría, pero con vientos fuertes.', false, '2025-09-13 13:53:10.374232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0461404b-e5fe-49ca-8be1-382705769369', '9a428242-1109-4c47-8939-61722355f872', 'c', 'Una tendencia al empeoramiento.', true, '2025-09-13 13:53:10.374385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06ce9e2e-294a-4c80-ba0c-fa6fbf825b67', '9a428242-1109-4c47-8939-61722355f872', 'd', 'Una tendencia al empeoramiento, que va acompañada con fuertes vientos, precipitaciones y riesgo de temporal.', false, '2025-09-13 13:53:10.374521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8aa5d0ab-e911-4a48-9eb1-e27538c9936b', 'e8bf87bd-4864-4c8b-abdf-0080ff0a2b27', 'a', 'Incremento de la fuerza del viento.', false, '2025-09-13 13:53:10.374806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3124f6da-b937-427a-8da9-844cb1789774', 'e8bf87bd-4864-4c8b-abdf-0080ff0a2b27', 'b', 'Disminución de la fuerza del viento o de la mar, total o parcialmente.', false, '2025-09-13 13:53:10.374943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbeac7b7-e033-4f27-830b-14d449857a4b', 'e8bf87bd-4864-4c8b-abdf-0080ff0a2b27', 'c', 'Disminución progresiva del viento.', false, '2025-09-13 13:53:10.375075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d7d10f5-9360-43f5-9fc1-85aefdd7fe5c', 'e8bf87bd-4864-4c8b-abdf-0080ff0a2b27', 'd', 'Variación de la dirección del viento.', true, '2025-09-13 13:53:10.375207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dad43604-72dd-4344-a9cf-2802ec7051ca', 'c4ea37ad-2692-45a9-b229-a7a6c2f8fe5a', 'b', 'El aire fluye hacia su interior y allí asciende.', false, '2025-09-13 13:53:10.375611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('362df8ca-5843-491c-9202-6711fa92f467', 'c4ea37ad-2692-45a9-b229-a7a6c2f8fe5a', 'd', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:10.375891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04b187f7-55cd-4281-a281-690b0b79c39c', '515b3f03-7e65-42cc-b435-db2c057b1797', 'a', 'Terral.', false, '2025-09-13 13:53:10.376271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8bdcf73-e389-4658-a633-2f90ccc77c8c', '515b3f03-7e65-42cc-b435-db2c057b1797', 'b', 'Fetch.', false, '2025-09-13 13:53:10.376403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f27595ce-d7c1-477f-b82b-4cc31b5c8db7', '515b3f03-7e65-42cc-b435-db2c057b1797', 'c', 'Virazón.', true, '2025-09-13 13:53:10.376531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a636d3b-dc44-42e9-9122-90a599b26379', 'c4ea37ad-2692-45a9-b229-a7a6c2f8fe5a', 'c', 'El aire asciende en su interior, lo que se conoce como subsidencia, y fluye hacia el exterior del mismo.', false, '2025-09-13 13:53:10.375745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6a315f4-6dd6-4a9b-b815-00ea57f8602f', '123a27a1-c13d-4960-b370-915829b63828', 'c', 'En caso de insolación hay que sumergir al afectado en agua fría para bajar la temperatura hasta los 35º.', true, '2025-09-13 13:53:10.37367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('790ba355-302b-4a8f-b551-3def0b3b49f2', 'd3da1b46-5c6c-46a5-9ac7-2a957493d7a7', 'a', 'Es el ángulo formado entre el Rumbo de aguja y el Rumbo de superficie.', true, '2025-09-13 13:53:10.37694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f4c9595-37ba-4953-9b39-8657018e179b', 'd3da1b46-5c6c-46a5-9ac7-2a957493d7a7', 'b', 'Es el ángulo formado entre el Rumbo verdadero y el Rumbo de superficie.', false, '2025-09-13 13:53:10.377073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('912b7983-290d-4420-a923-38e647aedc73', 'd3da1b46-5c6c-46a5-9ac7-2a957493d7a7', 'c', 'Si el viento nos entra por el costado de estribor, el abatimiento será a babor y su signo será', false, '2025-09-13 13:53:10.377202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d650643-138a-40e9-8f42-91e45fccf434', 'd3da1b46-5c6c-46a5-9ac7-2a957493d7a7', 'd', 'Es el ángulo que se desvía la proa del barco hacia sotavento por la fuerza del viento.', false, '2025-09-13 13:53:10.37733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2774e3a0-24e7-44c4-8364-eb56cb20e6b5', '11ae2c09-d6ac-4327-960d-cb7ae6079221', 'a', 'Su valor para una posición dada lo encontramos en la carta náutica.', false, '2025-09-13 13:53:10.377602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('890d7c05-0274-48b5-b2f0-5e679d884097', '11ae2c09-d6ac-4327-960d-cb7ae6079221', 'b', 'Es el ángulo formado entre el Norte magnético y el Norte de aguja.', true, '2025-09-13 13:53:10.37773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf04ab8c-f433-47f6-9a6c-61dfa9d78467', '11ae2c09-d6ac-4327-960d-cb7ae6079221', 'c', 'No ha de tenerse en cuenta en el cálculo de la Corrección total.', false, '2025-09-13 13:53:10.377881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecf3b619-4ee1-4684-9e99-d66cdc1692d5', '11ae2c09-d6ac-4327-960d-cb7ae6079221', 'd', 'Es positivo cuando el desvío es hacia el Noroeste.', false, '2025-09-13 13:53:10.378017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c716386f-01fb-4de5-b914-ef011394b837', '58c4075c-86d5-45d5-96d0-51805b122006', 'a', 'Desde 0 a 360 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.378288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12687693-7f98-44d3-98d0-949adf65ad20', '58c4075c-86d5-45d5-96d0-51805b122006', 'b', 'Desde 0 a 180 grados por estribor (positivas) y por babor (negativas).', true, '2025-09-13 13:53:10.378418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b28ea850-9d58-4e28-a563-0fd0442a9bf3', '58c4075c-86d5-45d5-96d0-51805b122006', 'c', 'Desde 0 a 90 grados en sentido horario (negativas) y antihorario (positivas).', false, '2025-09-13 13:53:10.378546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bd7ea48-f87a-40ee-a490-5e0deb07adb4', '58c4075c-86d5-45d5-96d0-51805b122006', 'd', 'Desde 0 a 180 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.378674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf8f0354-15fb-4cd5-b96b-2ad738d42495', '15df33ae-1489-46a0-9667-ee87312a04d9', 'a', 'Varía con los años y según el lugar en que nos encontremos.', true, '2025-09-13 13:53:10.378943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ac841e4-53f6-4772-a030-742a0e158fd0', '15df33ae-1489-46a0-9667-ee87312a04d9', 'b', 'Depende únicamente del lugar en que nos encontremos.', false, '2025-09-13 13:53:10.379072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9885e51-2b97-4cd7-b9a1-f9c6d3618b73', '15df33ae-1489-46a0-9667-ee87312a04d9', 'c', 'No se incluye en las cartas náuticas.', false, '2025-09-13 13:53:10.3792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8696dd66-7550-4f2e-9849-91243a9145df', '15df33ae-1489-46a0-9667-ee87312a04d9', 'd', 'Es el ángulo que forman el norte magnético y el norte de aguja.', false, '2025-09-13 13:53:10.379328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24262f85-caf7-4f3c-a7ec-727bb0501e2e', '7a237e84-bd6d-4f70-ad6e-c7b0ce54cd34', 'a', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte aumentan hacia arriba y en el sur hacia abajo.', true, '2025-09-13 13:53:10.379618+00');
