INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2721eaf-144d-4c1f-bfbe-0312228ec3d7', '7a237e84-bd6d-4f70-ad6e-c7b0ce54cd34', 'c', 'Están situadas en los márgenes superior e inferior y sus valores van aumentando al dirigirnos al oeste desde el meridiano 0º.', false, '2025-09-13 13:53:10.379884+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88e46158-5773-4126-8101-d9978ab9edfe', '7a237e84-bd6d-4f70-ad6e-c7b0ce54cd34', 'd', 'Están situadas a los márgenes izquierdo y derecho de la carta y sus valores van aumentando al dirigirnos al este desde el meridiano 0º. Carta de navegación.', false, '2025-09-13 13:53:10.380012+00');
