INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fd4027e-e30c-475d-95b7-ca6b514d044e', 'ea6188d6-e036-4201-894c-83abf07eaf73', 'a', 'El francobordo influye en la estabilidad transversal, ya que, al aumentar el francobordo, el ángulo para el cual se anula la estabilidad disminuye.', false, '2025-09-13 13:53:10.38406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49d21af4-c83d-4917-81df-ce98248e554f', 'ea6188d6-e036-4201-894c-83abf07eaf73', 'b', 'El francobordo influye en la estabilidad longitudinal, ya que, al aumentar el francobordo, el ángulo para el cual se anula la estabilidad, también aumenta.', false, '2025-09-13 13:53:10.384217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41084fca-b83f-454c-9a45-a16501987553', 'ea6188d6-e036-4201-894c-83abf07eaf73', 'c', 'El desplazamiento se define como la distancia recorrida por una embarcación.', false, '2025-09-13 13:53:10.384374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('251db3de-9980-40ff-a8c8-a250b0388b1f', 'ea6188d6-e036-4201-894c-83abf07eaf73', 'd', 'El desplazamiento se define como la cantidad de agua que desplaza el volumen sumergido de la embarcación y es equivalente al peso del barco.', true, '2025-09-13 13:53:10.38453+00');
