INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94fd7825-6a2a-426d-8903-b9c327fe213a', 'f70679c7-0eb9-4ada-9bc8-f07a1856f801', 'a', 'La embarcación se vuelve más inestable al elevarse el centro de gravedad.', true, '2025-09-13 13:53:10.38856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('826cf399-bd05-4cbe-9508-b8b56642c18c', 'f70679c7-0eb9-4ada-9bc8-f07a1856f801', 'b', 'La embarcación se vuelve más estable al bajar el centro de gravedad.', false, '2025-09-13 13:53:10.388691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63d438cd-d020-4ada-a22c-df972d1bf4ce', 'f70679c7-0eb9-4ada-9bc8-f07a1856f801', 'c', 'La embarcación se vuelve más estable al tener más peso.', false, '2025-09-13 13:53:10.388833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('127fbadd-888b-4d2d-8717-bb90d351e7f5', 'f70679c7-0eb9-4ada-9bc8-f07a1856f801', 'd', 'La embarcación pierde flotabilidad al bajar el centro de gravedad.', false, '2025-09-13 13:53:10.38899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7f0831b-b755-4f49-859b-5283240910d5', '7c107f45-4bd6-474d-ab50-2ada1a783acd', 'a', 'Evitar el balance excesivo.', false, '2025-09-13 13:53:10.389276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52ac1e02-a936-439d-8f9b-607e91a8e1a3', '7c107f45-4bd6-474d-ab50-2ada1a783acd', 'b', 'Evitar la cabezada excesiva.', true, '2025-09-13 13:53:10.389414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5388d99-22cf-4014-83ae-6f4f0b86d068', '7c107f45-4bd6-474d-ab50-2ada1a783acd', 'c', 'Evitar el sincronismo transversal.', false, '2025-09-13 13:53:10.38955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6adf5c1f-e3bb-4b0c-9a9a-fbbd3533fb94', '7c107f45-4bd6-474d-ab50-2ada1a783acd', 'd', 'No atravesarse a la mar.', false, '2025-09-13 13:53:10.389684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('909abbbd-b375-4972-aaf7-196f926ab3c2', 'dd36ec70-bfe5-4641-b6f2-9f16bb5a85e0', 'a', '6 cohetes con luz roja y paracaídas, 6 Bengalas de mano y 1 Señal fumígena flotante.', false, '2025-09-13 13:53:10.389972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e310494-4346-4cbf-9c3a-c4e584ddf6c7', 'dd36ec70-bfe5-4641-b6f2-9f16bb5a85e0', 'b', '3 Cohetes con luz roja y paracaídas y 3 Bengalas de mano.', true, '2025-09-13 13:53:10.390106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('066df71a-50b9-4369-8cc6-e5b35a4ec147', 'dd36ec70-bfe5-4641-b6f2-9f16bb5a85e0', 'c', '3 Bengalas de mano y 1 Señal fumígena flotante.', false, '2025-09-13 13:53:10.390238+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c70fd887-bd45-4e4a-bb68-b68f18169694', 'dd36ec70-bfe5-4641-b6f2-9f16bb5a85e0', 'd', '6 cohetes con luz roja y paracaídas, 6 Bengalas de mano y 2 Señales fumígenas flotantes.', false, '2025-09-13 13:53:10.390536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3844134-0862-4d82-81b7-f091ceaec276', '6a5a1f7b-1b21-4da4-8aa9-1ee9ded89127', 'a', 'Las aguas sucias que hayan estado almacenadas en los sistemas de retención no se descargarán instantáneamente, sino a un régimen moderado, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', true, '2025-09-13 13:53:10.390818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11da6d80-fb88-4535-aee1-f3f2226d269d', '6a5a1f7b-1b21-4da4-8aa9-1ee9ded89127', 'b', 'Las aguas sucias que hayan estado almacenadas en los sistemas de retención no se descargarán instantáneamente, sino a un régimen moderado, hallándose la embarcación en ruta navegando a velocidad no inferior a 3 nudos.', false, '2025-09-13 13:53:10.390953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e6aaf04-0d1d-427a-9e11-9d60c9565698', '6a5a1f7b-1b21-4da4-8aa9-1ee9ded89127', 'c', 'Las aguas sucias que hayan estado almacenadas en los sistemas de retención se descargarán instantáneamente o a un régimen moderado, hallándose la embarcación en ruta navegando a velocidad no inferior a 3 nudos.', false, '2025-09-13 13:53:10.391086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3c5a686-1a78-476e-86f3-9556ee0bfc96', '6a5a1f7b-1b21-4da4-8aa9-1ee9ded89127', 'd', 'Las aguas sucias que hayan estado almacenadas en los sistemas de retención se descargarán instantáneamente o a un régimen moderado, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', false, '2025-09-13 13:53:10.391219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e686b94-dce6-430e-bb1e-910960be4e68', 'b1199850-1040-49c1-a07e-fd9b3789ee2d', 'a', 'Las banderas y enseñas reconocidas en los Estatutos de las Comunidades Autónomas podrán permanecer izadas en puertos nacionales y aguas interiores españolas, aun cuando no esté izada la Bandera de España.', false, '2025-09-13 13:53:10.3915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e56508b-2d35-4ca8-80b8-bd57d11ea3f7', 'b1199850-1040-49c1-a07e-fd9b3789ee2d', 'b', 'Se reservará el asta de popa y el pico del palo mayor para la Bandera de España.', true, '2025-09-13 13:53:10.391633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f7162ce-a111-4642-9d90-b7bd48fb4516', 'b1199850-1040-49c1-a07e-fd9b3789ee2d', 'c', 'Las dimensiones de las banderas y enseñas reconocidas en los Estatutos de las Comunidades Autónomas serán superiores a un tercio del área del pabellón nacional.', false, '2025-09-13 13:53:10.391765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6aadc5b5-a095-499a-8f2e-37a3c49e1a67', 'b1199850-1040-49c1-a07e-fd9b3789ee2d', 'd', 'No hará falta llevar izado su pabellón nacional cuando naveguen por las aguas interiores marítimas españolas o se hallen surtos en puerto o terminal nacional.', false, '2025-09-13 13:53:10.391922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ab2057f-4b39-425d-8ff3-ceb8f554d4af', '162ad6e1-386f-4027-bf06-bd652aef740c', 'a', 'Esféricas, o de castillete o espeque, con franjas verticales rojas y blancas.', true, '2025-09-13 13:53:10.392201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92981bae-ec8e-4c93-ba7e-c0771af42819', '162ad6e1-386f-4027-bf06-bd652aef740c', 'b', 'Esféricas, o de castillete o espeque, con franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:10.392335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ca3066f-cb89-4767-a863-a027eed3999f', '162ad6e1-386f-4027-bf06-bd652aef740c', 'c', 'Esféricas, o de castillete o espeque, con franjas verticales rojas o blancas.', false, '2025-09-13 13:53:10.392466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0db1c89f-0f9e-48da-9434-9276c6279d29', '162ad6e1-386f-4027-bf06-bd652aef740c', 'd', 'Esféricas, o de castillete o espeque, con franjas horizontales rojas o blancas.', false, '2025-09-13 13:53:10.392598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c74ea0f-c5d8-4d79-8ac8-3eabf2b7df9c', 'c4ca1f7c-c900-4e4a-b932-771ddf25db79', 'a', 'El color será blanco y emitirá grupos de dos destellos.', false, '2025-09-13 13:53:10.392886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd23b0b0-e93a-45d6-8628-1077cc92df2d', 'c4ca1f7c-c900-4e4a-b932-771ddf25db79', 'b', 'El color será verde y emitirá grupos de dos destellos.', false, '2025-09-13 13:53:10.393018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9509815d-99b9-4582-b831-af85ee1c7ea6', 'c4ca1f7c-c900-4e4a-b932-771ddf25db79', 'c', 'El color será verde y emitirá grupos de dos más un destello.', true, '2025-09-13 13:53:10.39315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac7570ff-c67b-4b84-a538-f13239a9f847', 'c4ca1f7c-c900-4e4a-b932-771ddf25db79', 'd', 'El color será amarillo y emitirá grupos de tres más un destello.', false, '2025-09-13 13:53:10.393281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('202f097f-c291-4c79-b01c-800f29c11186', '8e8e240c-c31a-4be5-b1b0-3aad7975465a', 'a', 'Franjas verticales rojas y blancas.', false, '2025-09-13 13:53:10.393567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8673f55c-046f-442d-b771-06279993c981', '8e8e240c-c31a-4be5-b1b0-3aad7975465a', 'b', 'Negro con una o varias bandas anchas horizontales rojas.', true, '2025-09-13 13:53:10.393698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87d82199-d816-406d-ae51-6f233c99f7b5', '8e8e240c-c31a-4be5-b1b0-3aad7975465a', 'c', 'Franjas verticales amarillas y blancas.', false, '2025-09-13 13:53:10.393964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45473937-678b-4044-ba7b-b08a7a5a0b7d', '8e8e240c-c31a-4be5-b1b0-3aad7975465a', 'd', 'Negro con una o varias bandas anchas horizontales amarillas.', false, '2025-09-13 13:53:10.3941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56b8a24d-336b-4163-804b-612f90ba2572', '4d664b0b-2322-40c1-a47f-a9c5641b4de1', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:10.394378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc68334c-bb27-48f8-9e03-9a3b4b9b5646', '4d664b0b-2322-40c1-a47f-a9c5641b4de1', 'b', 'Una esfera amarilla.', false, '2025-09-13 13:53:10.394516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3abb9983-8525-4192-b1eb-77c5df9b034f', '4d664b0b-2322-40c1-a47f-a9c5641b4de1', 'c', 'Dos esferas negras superpuestas.', true, '2025-09-13 13:53:10.39465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d089321-ee2b-4864-9746-b8e6e53b80cc', '4d664b0b-2322-40c1-a47f-a9c5641b4de1', 'd', 'Dos esferas amarillas superpuestas.', false, '2025-09-13 13:53:10.394787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7c1cd17-52e2-4d5c-8271-a161032a7ceb', 'b2f1060c-c6ab-4ed2-a1eb-797c153594de', 'a', 'La luz, si tiene, será siempre de color blanco.', false, '2025-09-13 13:53:10.395076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('111aeddb-014b-4bed-aeaf-744632ee330c', 'b2f1060c-c6ab-4ed2-a1eb-797c153594de', 'b', 'Las boyas serán esféricas.', false, '2025-09-13 13:53:10.395216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bff04376-d71c-40d8-aead-784b9b7864a0', 'b2f1060c-c6ab-4ed2-a1eb-797c153594de', 'c', 'El ritmo de la luz, si tiene, será isofase, de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:10.395357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d14e3df5-40d7-45b7-98a0-d8571551662f', '31ce8a7a-4251-4979-b4ba-e5553a51b3ca', 'a', 'Encenderá la luz de alcance intermitentemente para avisar del peligro al otro buque.', false, '2025-09-13 13:53:10.395783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f538732-a924-445c-aff9-3ce451fc284c', '31ce8a7a-4251-4979-b4ba-e5553a51b3ca', 'b', 'Maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', true, '2025-09-13 13:53:10.39592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f29f86ed-4e59-4e01-a486-46b53ee5e80d', '31ce8a7a-4251-4979-b4ba-e5553a51b3ca', 'c', 'No debe maniobrar en ningún caso, sino que parará máquinas y suprimirá la arrancada hasta que le haya rebasado el otro buque.', false, '2025-09-13 13:53:10.396055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72b8d088-5465-4d47-9a5e-3d15de2c450a', '31ce8a7a-4251-4979-b4ba-e5553a51b3ca', 'd', 'Caerá obligatoriamente a estribor de forma que pase por la banda de babor del otro.', false, '2025-09-13 13:53:10.396189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d7013c2-8a93-4e9c-afe9-ab664927fdcf', 'c8865d29-e4f1-405a-8ed3-ef9cdb70d6f4', 'a', 'Una nave de vuelo rasante que navegue por la superficie.', false, '2025-09-13 13:53:10.396469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7ad33c9-d124-41d0-863d-7d83fc18218f', 'c8865d29-e4f1-405a-8ed3-ef9cdb70d6f4', 'b', 'Un buque de vela.', false, '2025-09-13 13:53:10.396605+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08bf6f93-1ab6-464d-b9dc-97935911942e', 'c8865d29-e4f1-405a-8ed3-ef9cdb70d6f4', 'c', 'Un buque con capacidad de maniobra restringida.', true, '2025-09-13 13:53:10.396739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('805ac279-081f-4571-9e5e-581f69b45c7b', 'c8865d29-e4f1-405a-8ed3-ef9cdb70d6f4', 'd', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:10.396884+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('079c6d9f-ee9e-4f11-9b87-59b2d8b1186d', '2da0780d-76a5-410c-bc77-f4b536ff6702', 'a', 'Existirá riesgo, si la demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:10.397163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47e9882f-bb9b-4118-bc2f-d5ca15cc22fa', '2da0780d-76a5-410c-bc77-f4b536ff6702', 'b', 'Siempre existirá riesgo si es evidente una variación apreciable de la demora.', false, '2025-09-13 13:53:10.397302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0527d23-0638-4eb7-bc8b-4c6ccfa15f20', '2da0780d-76a5-410c-bc77-f4b536ff6702', 'c', 'Si existe alguna duda sobre el riesgo de abordaje, se considerará que no existe.', false, '2025-09-13 13:53:10.397434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53fab42a-ee3c-4ee7-9675-6364bd69a68a', '2da0780d-76a5-410c-bc77-f4b536ff6702', 'd', 'La información obtenida por radar tendrá preferencia respecto a la obtenida por otros medios de que disponga el buque a bordo.', false, '2025-09-13 13:53:10.397566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e6caa42-c9bc-419d-9ea3-58067cd3bd8e', 'e882a946-bc23-4617-8aae-2165394bfae5', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:10.397862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d56c2ddc-98a2-4b4b-a772-6522085eb1d9', 'e882a946-bc23-4617-8aae-2165394bfae5', 'b', 'Cada uno de ellos caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:10.398145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15dbcd1e-d4c7-42c9-8979-fd1855609204', 'e882a946-bc23-4617-8aae-2165394bfae5', 'c', 'Si existe dudas sobre tal situación, se supondrá que no existe.', false, '2025-09-13 13:53:10.398284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc5ae1ee-39c9-4b56-9a81-1a7a1a2a08c6', 'e882a946-bc23-4617-8aae-2165394bfae5', 'd', 'Tras maniobrar, no podrán seguir navegando a rumbos opuestos o casi opuestos.', false, '2025-09-13 13:53:10.398421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51eb14c6-ef1d-4c53-865b-205e4ca261d9', '76551469-e978-427e-8608-ee00747ffafa', 'a', 'Una señal fumígena que produzca una densa humareda de color naranja.', true, '2025-09-13 13:53:10.398709+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e5ea35f-4b86-4cad-95a8-fe2d95648e35', '76551469-e978-427e-8608-ee00747ffafa', 'b', 'Un disparo de cañón u otra señal detonante aislada.', false, '2025-09-13 13:53:10.398855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('190fc949-4eec-44f1-b2f4-c2e1120873ca', '76551469-e978-427e-8608-ee00747ffafa', 'c', 'Un sonido intermitente producido por un aparato de señales de niebla.', false, '2025-09-13 13:53:10.398993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5781af1-7773-427b-85fd-dc91234b892a', '76551469-e978-427e-8608-ee00747ffafa', 'd', 'La señal "HL" del Código Internacional de Señales.', false, '2025-09-13 13:53:10.39914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1232343e-3512-4881-a9ab-795b8d5bbb9e', '04374311-ddbf-4216-b18c-88ab097bfd07', 'a', 'La longitud del remolque es superior a 100 metros.', false, '2025-09-13 13:53:10.399433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d5d68bf-9fd9-4bbe-83fc-16c524e3ab79', '04374311-ddbf-4216-b18c-88ab097bfd07', 'b', 'La longitud del remolque es inferior a 100 metros.', false, '2025-09-13 13:53:10.399569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80e608fb-dada-4e9a-9195-52f5dcd23549', '04374311-ddbf-4216-b18c-88ab097bfd07', 'c', 'La longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:10.399706+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a3dcc03-c4c9-48bd-9a49-cf5a2187c5c8', '04374311-ddbf-4216-b18c-88ab097bfd07', 'd', 'La longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:10.399851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ac0b8fc-6375-44db-8273-52c5328e228e', '106cce80-54f6-475e-8818-fe2c9a003946', 'a', 'Deberá reducir su velocidad hasta la mínima de gobierno.', true, '2025-09-13 13:53:10.400134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69961435-0a2a-4ea4-a460-ee5186786fcc', '106cce80-54f6-475e-8818-fe2c9a003946', 'b', 'Deberá mantener rumbo y velocidad.', false, '2025-09-13 13:53:10.400271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62342332-c552-45d9-83db-fb1396b28926', '106cce80-54f6-475e-8818-fe2c9a003946', 'd', 'Deberá caer a la banda de babor y hará sonar su señal de niebla para que el otro buque caiga a también a babor.', false, '2025-09-13 13:53:10.400546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('981d261c-66ea-4056-a57e-30914e6ef63f', 'da60e0a3-c905-414f-8535-7d3a0dcf55ee', 'a', 'El buque reducirá su velocidad, pero sin llegar nunca a suprimir su arrancada.', false, '2025-09-13 13:53:10.400829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b47e94c-bca8-46a6-8400-50d3a057ebc4', 'da60e0a3-c905-414f-8535-7d3a0dcf55ee', 'b', 'En ningún caso el buque llegará a invertir sus medios de propulsión.', false, '2025-09-13 13:53:10.40097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54d173a6-a188-49b7-a199-dad25bfa5a3d', 'da60e0a3-c905-414f-8535-7d3a0dcf55ee', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasado y en franquía.', true, '2025-09-13 13:53:10.401108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efe0077d-db77-47a4-84c0-26349a16aa77', 'da60e0a3-c905-414f-8535-7d3a0dcf55ee', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños.', false, '2025-09-13 13:53:10.401262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('203d0b77-63c9-4bdc-a48f-23d1cc2f25b4', '32a5bb39-1193-441f-ac64-b99455377691', 'a', 'Navegar en la vía de circulación apropiada, siguiendo la dirección general de la corriente de tráfico indicada para dicha vía.', false, '2025-09-13 13:53:10.401669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8319fd37-cd42-4915-a214-3eba2d6d3545', '32a5bb39-1193-441f-ac64-b99455377691', 'b', 'Mantener su rumbo fuera de la línea de separación o de la zona de separación del tráfico.', false, '2025-09-13 13:53:10.40181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46c8186e-532b-47f3-96d4-4fcb1640d8c3', '32a5bb39-1193-441f-ac64-b99455377691', 'c', 'Al entrar o salir de una vía de circulación, hacerlo por sus extremos.', false, '2025-09-13 13:53:10.401948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbc5e09f-5bbe-44fb-989c-cb7e6116ee90', '32a5bb39-1193-441f-ac64-b99455377691', 'd', 'Fondear dentro de un dispositivo de separación del tráfico o en las zonas próximas a sus', true, '2025-09-13 13:53:10.402087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('935333ea-4c82-4e25-b238-e905636eca67', '4620f693-ab4e-4a13-ae87-03701e87272e', 'a', 'En determinadas circunstancias el capitán puede ser eximido de dicha responsabilidad.', false, '2025-09-13 13:53:10.402365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95cb5de9-6346-48c8-b14b-210097571258', '4620f693-ab4e-4a13-ae87-03701e87272e', 'b', 'Se limita la responsabilidad únicamente al propietario.', false, '2025-09-13 13:53:10.402496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b644f2a-ccde-4f49-bc1b-0c1b6e520fe3', '4620f693-ab4e-4a13-ae87-03701e87272e', 'c', 'La dotación está eximida de toda responsabilidad.', false, '2025-09-13 13:53:10.402627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c57df42-6ebb-4dd5-bcd1-c4e325ea7f20', '4620f693-ab4e-4a13-ae87-03701e87272e', 'd', 'Ninguna disposición exime a un buque, o a su propietario, al Capitán o a la dotación del mismo. Maniobra y navegación.', true, '2025-09-13 13:53:10.402756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('102360b8-3fd7-4daa-bfe0-c3b9e1690d8b', 'af8c4342-2424-46a5-9b46-2702749c8488', 'a', 'Fase inicial.', false, '2025-09-13 13:53:10.40335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0896093-0d6d-41a6-bd77-c02189d35157', 'af8c4342-2424-46a5-9b46-2702749c8488', 'b', 'Fase variable.', true, '2025-09-13 13:53:10.403503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c78bbcff-78de-4fa6-bbb1-29d6f513a937', 'af8c4342-2424-46a5-9b46-2702749c8488', 'c', 'Fase de maniobra.', false, '2025-09-13 13:53:10.403635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3c01c6b-0c44-4f48-87d9-abcdafe06abd', 'af8c4342-2424-46a5-9b46-2702749c8488', 'd', 'Fase uniforme.', false, '2025-09-13 13:53:10.403766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdf6f4f6-1315-4000-8a8e-9c46b88a6dd0', '8aa79386-520f-4f35-979c-9406252e1059', 'a', 'En caso de sufrir “mal de mar”, al afectado se le mantendrá sentado en cubierta, para que esté fresco y aireado, y permanecerá en ayunas hasta que remita el mareo.', false, '2025-09-13 13:53:10.404749+00');
