INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b23bbcf-e680-4ca3-9c04-69cb9b90a8d4', '8aa79386-520f-4f35-979c-9406252e1059', 'd', 'La gravedad de las quemaduras reside en la extensión superficial de piel quemada, considerándose grave si abarca más del 33% de la piel y leve si es menos del 10%.', true, '2025-09-13 13:53:10.405171+00');
