INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09e21c79-c000-4730-96b4-21fc8a70e3e6', 'df83f5fd-1df5-488d-b24b-19ccd95254c8', 'c', 'La embarcación de estribor está a barlovento.', true, '2025-09-13 13:53:10.412946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae1186d6-e7ac-4c1c-9242-bd31ec97058b', 'df83f5fd-1df5-488d-b24b-19ccd95254c8', 'd', 'La embarcación de babor recibe el viento por la banda opuesta a la de estribor.', false, '2025-09-13 13:53:10.413106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a3a63c4-7e4c-43fa-9a23-b679b141de8e', '905fdfad-ed5c-4fa7-9a78-4d915217b019', 'a', 'Es la pieza que corre de proa a popa, a lo largo de la línea media más baja del buque, siendo el principal refuerzo longitudinal, en el cual descargan los demás.', false, '2025-09-13 13:53:10.413411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6eee1ca6-901a-4bda-851d-61eb2c4ddc2b', '905fdfad-ed5c-4fa7-9a78-4d915217b019', 'b', 'Es un elemento estructural que se encastra en la quilla.', true, '2025-09-13 13:53:10.413543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c552c38-deee-40b6-afa8-18ea7b0c7b2e', '905fdfad-ed5c-4fa7-9a78-4d915217b019', 'c', 'Es la “columna vertebral” del buque en la que se encastran las cuadernas, la quilla y el codaste.', false, '2025-09-13 13:53:10.413674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99889846-782f-4726-ac3f-b8e2da072262', '905fdfad-ed5c-4fa7-9a78-4d915217b019', 'd', 'Elemento estructural que continúa la quilla en la popa.', false, '2025-09-13 13:53:10.413806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ed184b4-628f-4db6-a6df-47188a77cdc5', 'b8b47505-26d9-4c98-8954-068c583ee6b3', 'a', 'La hélice.', true, '2025-09-13 13:53:10.41413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d9610ee-2ed2-4c56-876e-eab0a3dac851', 'b8b47505-26d9-4c98-8954-068c583ee6b3', 'b', 'El motor.', false, '2025-09-13 13:53:10.414271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5112f6b2-816b-45a7-bef5-c8cdac7002a8', 'b8b47505-26d9-4c98-8954-068c583ee6b3', 'c', 'El timón.', false, '2025-09-13 13:53:10.414406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5852b037-c078-446a-bbb4-f38a5310871c', 'b8b47505-26d9-4c98-8954-068c583ee6b3', 'd', 'La vela.', false, '2025-09-13 13:53:10.414539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09e7d9d0-3433-4848-a236-35eea10a5def', 'd7c57a6e-e83d-462c-bfc8-b971767c663e', 'a', 'El círculo de borneo tiene como radio la cadena de fondeo.', false, '2025-09-13 13:53:10.415577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('057d0aad-a0ea-4fc7-99d5-09cd3f1c8b14', '058b5bdd-4c8f-4d82-9514-410d33339456', 'b', 'Los buques de vela que naveguen en una vía de circulación.', false, '2025-09-13 13:53:10.42561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aabeaaac-81d4-4dec-8d6a-24905403bb96', '71f71722-c068-427a-9b46-c354cc078b9d', 'b', 'La escala Douglas clasifica los estados de la mar en.', true, '2025-09-13 13:53:10.406988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7002949a-2a26-4166-b6ee-2944958aabdc', '71f71722-c068-427a-9b46-c354cc078b9d', 'c', 'La escala Beaufort mide la intensidad del viento en.', false, '2025-09-13 13:53:10.407123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5455b7d3-097a-4d35-afd5-d7b38e2a807f', '907b7e0b-284d-42f2-b39c-723b17d2710e', 'a', 'Es la extensión o alcance que tiene el viento sobre la mar cuando sopla con dirección y fuerza constantes.', false, '2025-09-13 13:53:10.409156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b29b0772-c0c2-4515-8820-48f11c80cb04', '640210d4-5401-47ed-91e5-62d8f1625191', 'a', 'l=36º 05,3´N L=005º 55,6´W.', false, '2025-09-13 13:53:10.411569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3be1ef6-e429-44cf-9b4a-0422ec56f6b8', '640210d4-5401-47ed-91e5-62d8f1625191', 'c', 'l=36º 05,3´N L=005º 55,6´W.', false, '2025-09-13 13:53:10.411884+00');
