INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('521ebf4b-9884-4b92-9482-4b9f91f51d4a', '640210d4-5401-47ed-91e5-62d8f1625191', 'b', 'l=36º 06,5´N L=006º 02,4´W.', false, '2025-09-13 13:53:10.411727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f1c2f13-9370-45d4-8c8c-299a3241c6f6', 'd7c57a6e-e83d-462c-bfc8-b971767c663e', 'b', 'El tenedero es el cabo que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder recuperar el ancla.', false, '2025-09-13 13:53:10.415712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecf15b0a-9149-4341-bf91-0a38c29f5708', 'd7c57a6e-e83d-462c-bfc8-b971767c663e', 'c', 'Cuando el ancla no se queda firme en el fondo, provocando un desplazamiento del barco a sotavento, se dice que garrea.', true, '2025-09-13 13:53:10.415856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea16a8df-7d2d-4284-bd6f-ae02ab4bce96', 'd7c57a6e-e83d-462c-bfc8-b971767c663e', 'd', 'Un barco fondea a la gira utilizando dos anclas por la proa, procurando que la longitud de las líneas de fondeo sea idéntica para las dos anclas.', false, '2025-09-13 13:53:10.415994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68231bd6-1fc3-463d-8ca2-e562b19f72d3', '5a4131dd-7197-4fd5-be53-b6afecd48276', 'a', 'Roldana.', false, '2025-09-13 13:53:10.416278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f45846c-cab8-4bd4-a6e6-60fa162ad7b8', '5a4131dd-7197-4fd5-be53-b6afecd48276', 'b', 'Bita.', false, '2025-09-13 13:53:10.416412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b790c495-d465-47ea-8eda-728b04a41692', '5a4131dd-7197-4fd5-be53-b6afecd48276', 'c', 'Guía-cabos.', true, '2025-09-13 13:53:10.416547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9b89343-43cd-4f3a-9596-af3f9d41edc5', '5a4131dd-7197-4fd5-be53-b6afecd48276', 'd', 'Cornamusa.', false, '2025-09-13 13:53:10.416682+00');
