INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ceabee81-a6ab-4b22-b522-3fa326dd4208', 'd9c6ef05-fda2-486f-b657-c27b48c864c0', 'b', 'Balancea lentamente.', false, '2025-09-13 13:53:10.417117+00');
