INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('917012fd-ed1a-4ef6-ad45-5b37374e178d', 'd1b946ff-bc63-414d-bf4a-2927404589fd', 'a', '900 061 061', false, '2025-09-13 13:53:10.417674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe5c40d8-a383-43bf-a163-4b6f4c5073d6', 'd1b946ff-bc63-414d-bf4a-2927404589fd', 'b', '900 091 091', false, '2025-09-13 13:53:10.417818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('429b6d28-6a77-4573-b1c8-e38f5b79575b', 'd1b946ff-bc63-414d-bf4a-2927404589fd', 'c', '900 202 202', true, '2025-09-13 13:53:10.417953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7822df7-c00a-4b50-820f-ad57cd5f4666', 'd1b946ff-bc63-414d-bf4a-2927404589fd', 'd', '900 112 112', false, '2025-09-13 13:53:10.418092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a22254dd-1fea-4fe8-9ac9-621845b3b481', '212044a2-031c-4e32-a034-55aae4b80437', 'a', 'Mantendremos el rumbo de aguja.', false, '2025-09-13 13:53:10.418515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a598b763-38ab-4e9b-841c-291765d74880', '212044a2-031c-4e32-a034-55aae4b80437', 'b', 'Orientaremos la proa de la embarcación a barlovento.', true, '2025-09-13 13:53:10.418646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('850e4343-16e5-4cc8-8da7-3684280189cb', '212044a2-031c-4e32-a034-55aae4b80437', 'c', 'Echaremos el ancla flotante y seguiremos a rumbo.', false, '2025-09-13 13:53:10.418794+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5145e000-c257-4e74-a5bc-2f8371df9fba', '212044a2-031c-4e32-a034-55aae4b80437', 'd', 'Haremos sonar la bocina.', false, '2025-09-13 13:53:10.418935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03e1705e-bb50-404c-b3a7-9958dc99e2b8', '2f6d0386-57fb-43b6-8bcb-809cb8f921e8', 'a', 'Mejoraremos la navegación con el mar por la amura.', true, '2025-09-13 13:53:10.419212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8aba6229-9e7a-422a-9333-fdc0fe9c57cc', '2f6d0386-57fb-43b6-8bcb-809cb8f921e8', 'b', 'Mejoraremos la maniobrabilidad si aumentamos la velocidad.', false, '2025-09-13 13:53:10.419342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('443b4672-8487-43ba-bb64-5e5ff4dbffee', '2f6d0386-57fb-43b6-8bcb-809cb8f921e8', 'c', 'Al disminuir la sonda aumentará la velocidad de la embarcación.', false, '2025-09-13 13:53:10.419478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8afe0368-cb80-4fa9-8745-0298d524dc36', '2f6d0386-57fb-43b6-8bcb-809cb8f921e8', 'd', 'Disminuirán las cabezadas al reducirse la altura de la ola.', false, '2025-09-13 13:53:10.419609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8734f0b-fe04-4a63-b02b-be2932ae8260', '64bc1812-ea7c-459c-9d26-30e333662326', 'a', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 25 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', false, '2025-09-13 13:53:10.419898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a1c51ba-c0c3-4f87-9acd-f52ea328eb14', '64bc1812-ea7c-459c-9d26-30e333662326', 'b', 'Los desechos de los alimentos deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', false, '2025-09-13 13:53:10.420028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d447835-f0df-4dfa-9978-2672bd66f38e', '64bc1812-ea7c-459c-9d26-30e333662326', 'c', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', true, '2025-09-13 13:53:10.420157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('317b9bd9-b46c-4c03-ac22-e2cefddb2fe3', '64bc1812-ea7c-459c-9d26-30e333662326', 'd', 'Los desechos de los alimentos podrán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:10.420287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f54134ed-5154-45ef-b1e4-23a8f5556f15', '60894993-274f-465a-a6c9-6d257707b455', 'a', 'Deberá alejarse de la zona al menos 200 metros, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.420557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf92f081-feb0-41a9-a65f-2898403b7cc1', '60894993-274f-465a-a6c9-6d257707b455', 'b', 'Deberá alejarse de la zona al menos 200 millas náuticas, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.420689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a6f7eb6-5b2a-4234-99df-af7aec4b304d', '60894993-274f-465a-a6c9-6d257707b455', 'c', 'En ningún caso podrá fondear la embarcación, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:10.420825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4c38796-985e-493e-9290-7cf71ca9d724', '60894993-274f-465a-a6c9-6d257707b455', 'd', 'Se podrá fondear con finalidad exclusiva de recreo, siempre que no pongan en peligro la seguridad de la vida humana en la mar o de la navegación, debiendo navegar a una velocidad no superior a 3 nudos, adoptando las precauciones necesarias.', true, '2025-09-13 13:53:10.420962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31f2df57-78c2-4d0a-806e-6ec15af6d75a', 'e6ee475b-e02d-49ac-a09a-3f68b28a483b', 'a', 'Marca especial.', false, '2025-09-13 13:53:10.421236+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80eca339-46d2-4173-9f71-ffe26add04c0', 'e6ee475b-e02d-49ac-a09a-3f68b28a483b', 'b', 'Marca de peligros nuevos.', false, '2025-09-13 13:53:10.421367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2357ba8a-ff4f-4ca3-9131-92060ead1e68', 'e6ee475b-e02d-49ac-a09a-3f68b28a483b', 'c', 'Marca de peligro aislado.', true, '2025-09-13 13:53:10.421497+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0624dbec-184b-40ea-b11e-3e93179eb5df', 'e6ee475b-e02d-49ac-a09a-3f68b28a483b', 'd', 'Marca cardinal.', false, '2025-09-13 13:53:10.421626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10946dfd-3373-4978-8129-127dc4905e24', '137c0f55-753b-462b-baf5-34eb4224b900', 'a', 'Una marca cardinal recibe el nombre del cuadrante en el que está colocada.', false, '2025-09-13 13:53:10.42191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0817f3a7-dabe-4bf0-8cdd-85ab56f939ff', '137c0f55-753b-462b-baf5-34eb4224b900', 'b', 'Las marcas cardinales y su uso, son las mismas para la Región A y la Región B.', false, '2025-09-13 13:53:10.42204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bcf21ea-27cd-4653-8fb7-ac441eb7d289', '137c0f55-753b-462b-baf5-34eb4224b900', 'c', 'El nombre de una marca cardinal indica que se ha de evitar pasar por el cuadrante correspondiente a ese nombre.', true, '2025-09-13 13:53:10.422172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5642c933-5b09-45c5-98f4-b4ee4f9a3098', '137c0f55-753b-462b-baf5-34eb4224b900', 'd', 'Una marca cardinal puede ser utilizada para llamar la atención sobre una configuración especial', false, '2025-09-13 13:53:10.422304+00');
