INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('487c6663-c2d3-43f3-9f81-81b254a756a1', '8ac608dd-80cb-4388-aac7-6e8e8926f8e4', 'b', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste otro, evitando cortarle la popa.', false, '2025-09-13 13:53:10.429174+00');
