INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdc7591d-55bf-4530-876e-39e1ca2c4038', '8ac608dd-80cb-4388-aac7-6e8e8926f8e4', 'd', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste', true, '2025-09-13 13:53:10.429435+00');
