INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1561afd-2ebc-4de1-8daf-9679b33d6d00', 'bef0fef4-b961-4d29-9f3a-8a4fb1711cb4', 'b', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a sotavento se mantendrá apartado de la derrota del que esté a barlovento.', false, '2025-09-13 13:53:10.429857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5190fa6b-4d20-4093-8bc6-d92e908e74eb', 'bef0fef4-b961-4d29-9f3a-8a4fb1711cb4', 'c', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a barlovento se mantendrá apartado de la derrota del que esté a sotavento.', true, '2025-09-13 13:53:10.42999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('caa314e8-82b6-448c-a618-1ad841060589', 'bef0fef4-b961-4d29-9f3a-8a4fb1711cb4', 'd', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor mantendrá el mismo rumbo y velocidad.', false, '2025-09-13 13:53:10.430122+00');
