INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45b8b158-3635-497a-b2df-72816286684c', '57109250-cbad-48c1-baab-c1570086287f', 'a', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de babor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', true, '2025-09-13 13:53:10.431748+00');
