INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7ecd102-a38b-4b20-9e5e-9157bcb43c55', '57109250-cbad-48c1-baab-c1570086287f', 'd', 'Atracar con la popa a otra embarcación; siempre se recomienda cuando es necesario desembarcar mejor y tener la maniobra de salida más clara.', false, '2025-09-13 13:53:10.432168+00');
