INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbdfb644-e405-4d31-bbfb-cd9799bd98c9', '89f3d731-38fe-4b42-88a7-b9b71b4b5907', 'd', 'Tablero de contrachapado marino sellado al casco con silicona para tapar vías de agua.', false, '2025-09-13 13:53:10.433672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b32e8270-8d09-4275-ad88-e65a7da81280', '0c5ad6a2-b438-480a-9268-adb39227436d', 'a', 'Saltando en parejas cogidos por los brazos, con el fin de poder agruparnos lo más rápido posible y ser más visibles.', false, '2025-09-13 13:53:10.433945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44aca17c-d1d9-45a4-bf6b-336c42167cc5', '0c5ad6a2-b438-480a-9268-adb39227436d', 'b', 'Saltando por barlovento de pie y con el chaleco puesto. Solo en determinados casos, como por ejemplo un incendio en esa banda, se podría saltar por sotavento.', false, '2025-09-13 13:53:10.434081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecdcbc46-f77d-4ba8-8285-9a54dccfb43e', '0c5ad6a2-b438-480a-9268-adb39227436d', 'c', 'Saltando al agua de pie, con las piernas y rodillas juntas, sujetando el chaleco y tapándose la nariz. Si una vez en el agua hubiera que nadar, deberá hacerse de espaldas.', true, '2025-09-13 13:53:10.434212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32feb686-41a8-40c0-be5f-4df2bf22ae34', '0c5ad6a2-b438-480a-9268-adb39227436d', 'd', 'Se deberá lanzar al agua el chaleco salvavidas y saltar al agua adoptando la postura fetal. Una vez en el agua habrá que ponérselo e intentar nadar lo más rápidamente posible hacia cualquier objeto flotante para reducir la hipotermia.', false, '2025-09-13 13:53:10.434342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5cd94449-f85a-486d-97c4-f5ea737dafd9', 'a6e71045-151d-41f5-bbdf-d545458ae282', 'a', 'Si una persona sufre una fuerte contusión en el abdomen, se le proporcionara reposo absoluto, manteniéndose en observación y se realizarán consultas radiomédicas.', false, '2025-09-13 13:53:10.434622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7159847-145e-4837-972b-caf8b34547d6', 'f53596c0-dace-4861-b6f7-71179a92d2a8', 'd', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:10.431468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c188f5df-faba-480d-a873-f30f8e28df83', 'c06edc43-57c4-4e3e-9bfb-de31f698896c', 'd', 'La popa cae inicialmente a estribor y luego a babor.', false, '2025-09-13 13:53:10.432856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('144f916c-eebc-4103-bd8f-c4651f31bb18', 'a6e71045-151d-41f5-bbdf-d545458ae282', 'b', 'En una hemorragia arterial la sangre mana a impulsos y habrá que realizar un torniquete un poco por encima de la herida.', false, '2025-09-13 13:53:10.434767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c50eabc4-9fad-4d5b-b044-e1a0327c4c6c', 'a6e71045-151d-41f5-bbdf-d545458ae282', 'd', 'Las quemaduras de tercer grado son las producidas por acción intensa y directa de una llama o sólido incandescente y la costra que se produce no debe ser destruida. Meteorología', false, '2025-09-13 13:53:10.435034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7280d1de-929a-45c7-a9c8-70aac3454939', '4bb7793e-5f62-4a95-ba5d-8ffba5d02901', 'a', 'Terral.', false, '2025-09-13 13:53:10.435325+00');
