INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f49c1d2d-4509-4084-88c5-02564d0d32ea', '2effed6f-1d47-4c36-a151-c5e6d332671c', 'a', 'Una tendencia a la mejoría.', false, '2025-09-13 13:53:10.436019+00');
