INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfaf9d87-378a-4456-8e74-fdb27eaa33f8', '2effed6f-1d47-4c36-a151-c5e6d332671c', 'c', 'Una tendencia al empeoramiento.', true, '2025-09-13 13:53:10.436288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d0e003f-7829-4913-bc6f-9dffef15e23a', '2effed6f-1d47-4c36-a151-c5e6d332671c', 'd', 'Una tendencia al empeoramiento, que va acompañada con fuertes vientos, precipitaciones y riesgo de temporal.', false, '2025-09-13 13:53:10.43642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e30e382b-a659-469c-b312-7acdf316efc1', 'e426b8e2-6160-4469-8379-1a87257cff23', 'a', 'Incremento de la fuerza del viento.', false, '2025-09-13 13:53:10.437509+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce4963c0-fda7-4727-8006-13aec1e1a70c', 'e426b8e2-6160-4469-8379-1a87257cff23', 'b', 'Disminución de la fuerza del viento o de la mar, total o parcialmente.', false, '2025-09-13 13:53:10.437638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d38e235-a7e4-4ee0-9dfa-214c443ccdbc', 'e426b8e2-6160-4469-8379-1a87257cff23', 'c', 'Disminución progresiva del viento.', false, '2025-09-13 13:53:10.437767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08005bc1-fb01-4899-9500-9517e3e8fae4', '1df12d80-cc36-45ca-bec7-4aed8b004557', 'a', 'Su valor para una posición dada lo encontramos en la carta náutica.', false, '2025-09-13 13:53:10.438179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59592470-b0a9-451f-bcd7-e999814e32f5', '1df12d80-cc36-45ca-bec7-4aed8b004557', 'b', 'Es el ángulo formado entre el Norte magnético y el Norte de aguja.', true, '2025-09-13 13:53:10.438314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d17f2c98-0ad6-4bec-8853-87f5debe1255', '1df12d80-cc36-45ca-bec7-4aed8b004557', 'c', 'No ha de tenerse en cuenta en el cálculo de la Corrección total.', false, '2025-09-13 13:53:10.438446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf3ee370-4be1-4995-a0c9-c1fc920effe1', '1df12d80-cc36-45ca-bec7-4aed8b004557', 'd', 'Es positivo cuando el desvío es hacia el Noroeste.', false, '2025-09-13 13:53:10.438578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb992f3a-107a-4925-953e-2228871ebf94', '3572efce-b295-42f9-ad6d-6626d304fb12', 'a', 'Varía con los años y según el lugar en que nos encontremos.', true, '2025-09-13 13:53:10.438873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f05f362-5a0c-48a6-8f4c-b68729058819', '3572efce-b295-42f9-ad6d-6626d304fb12', 'b', 'Depende únicamente del lugar en que nos encontremos.', false, '2025-09-13 13:53:10.439008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('783ad549-f85e-4601-bfb9-d6a7bb700c90', '3572efce-b295-42f9-ad6d-6626d304fb12', 'c', 'No se incluye en las cartas náuticas.', false, '2025-09-13 13:53:10.439141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('082b4dee-2047-4f7f-aa23-67bee394baec', '3572efce-b295-42f9-ad6d-6626d304fb12', 'd', 'Es el ángulo que forman el norte magnético y el norte de aguja.', false, '2025-09-13 13:53:10.439276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a3d1996-1206-4b62-b76d-80d6537a3981', '364831c5-68ce-43bf-85cc-4de310f74ae9', 'a', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte aumentan hacia arriba y en el sur hacia abajo.', true, '2025-09-13 13:53:10.439563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1264bae8-0039-4e90-86b5-744e5cb60b47', '364831c5-68ce-43bf-85cc-4de310f74ae9', 'b', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte disminuyen hacia arriba y en el sur hacia abajo.', false, '2025-09-13 13:53:10.439698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90a038b9-5a9c-420c-8733-5ff5ec4e48f4', '364831c5-68ce-43bf-85cc-4de310f74ae9', 'c', 'Están situadas en los márgenes superior e inferior y sus valores van aumentando al dirigirnos al oeste desde el meridiano 0º.', false, '2025-09-13 13:53:10.439833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a01385c2-5ffa-48eb-a162-2768200eb187', '364831c5-68ce-43bf-85cc-4de310f74ae9', 'd', 'Están situadas a los márgenes izquierdo y derecho de la carta y sus valores van aumentando al dirigirnos al este desde el meridiano 0º.', false, '2025-09-13 13:53:10.439968+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28a4f7fc-61a9-4186-8738-48c99c92a510', '87df4895-04fe-42a1-88a8-89a5da4e0066', 'a', 'Es el ángulo formado entre el Rumbo de aguja y el Rumbo de superficie.', true, '2025-09-13 13:53:10.440269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4190c7b5-1dfc-4a68-9ae8-74cac8cdb760', '87df4895-04fe-42a1-88a8-89a5da4e0066', 'b', 'Es el ángulo formado entre el Rumbo verdadero y el Rumbo de superficie.', false, '2025-09-13 13:53:10.440403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfe55b6c-3336-46e1-848a-7e20e96758c8', '87df4895-04fe-42a1-88a8-89a5da4e0066', 'c', 'Si el viento nos entra por el costado de estribor, el abatimiento será a babor y su signo será', false, '2025-09-13 13:53:10.440542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2693682e-e3ca-412e-8148-5391fd0e4a22', '87df4895-04fe-42a1-88a8-89a5da4e0066', 'd', 'Es el ángulo que se desvía la proa del barco hacia sotavento por la fuerza del viento.', false, '2025-09-13 13:53:10.440805+00');
