INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e286556a-370e-43d5-8f69-1892b95447bb', 'a6e71045-151d-41f5-bbdf-d545458ae282', 'c', 'En caso de insolación hay que sumergir al afectado en agua fría para bajar la temperatura hasta los 35º.', true, '2025-09-13 13:53:10.434904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fccea78f-bf23-445e-98f0-49055db598b1', '610f63d4-503a-4750-baeb-8dc31165254d', 'd', 'Desde 0 a 180 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.441481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bf64729-106c-4aab-82c2-38d891261863', '9db48ec2-57fa-4588-9ae1-f76ea70fd7e7', 'c', 'La popa no cae a ningún costado.', false, '2025-09-13 13:53:10.444923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84333086-32bb-42f4-b41a-649aaf78a799', '9db48ec2-57fa-4588-9ae1-f76ea70fd7e7', 'd', 'La popa cae inicialmente a estribor y luego a babor.', false, '2025-09-13 13:53:10.445061+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ffdc757-9406-4a2c-8827-6412d14996fe', 'a1cce6c6-cd5b-47e0-94d2-d4aa663cf0f9', 'a', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de babor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', true, '2025-09-13 13:53:10.445331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('589d1682-7daf-4876-8d43-e70d4c81fb92', 'a1cce6c6-cd5b-47e0-94d2-d4aa663cf0f9', 'b', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de estribor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', false, '2025-09-13 13:53:10.445462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bdf669b-0740-42e3-8929-5636d18a07eb', 'a1cce6c6-cd5b-47e0-94d2-d4aa663cf0f9', 'd', 'Atracar con la popa a otra embarcación; siempre se recomienda cuando es necesario desembarcar mejor y tener la maniobra de salida más clara. Emergencias en la mar.', false, '2025-09-13 13:53:10.445916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3568dd12-ac1c-457d-ab7f-66c98141ed16', '219fc5bf-7fb4-4b65-b341-616b495a0e5c', 'a', 'Saltando en parejas cogidos por los brazos, con el fin de poder agruparnos lo más rápido posible y ser más visibles.', false, '2025-09-13 13:53:10.446186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e4bf187-c14c-4259-bd00-64fd969fb5ad', '219fc5bf-7fb4-4b65-b341-616b495a0e5c', 'b', 'Saltando por barlovento de pie y con el chaleco puesto. Solo en determinados casos, como por ejemplo un incendio en esa banda, se podría saltar por sotavento.', false, '2025-09-13 13:53:10.446317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b8996fd-293e-47cd-9e52-359faef4d4af', '219fc5bf-7fb4-4b65-b341-616b495a0e5c', 'c', 'Saltando al agua de pie, con las piernas y rodillas juntas, sujetando el chaleco y tapándose la nariz. Si una vez en el agua hubiera que nadar, deberá hacerse de espaldas.', true, '2025-09-13 13:53:10.446456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a755027-050d-42b5-b66d-906cbb604caa', '219fc5bf-7fb4-4b65-b341-616b495a0e5c', 'd', 'Se deberá lanzar al agua el chaleco salvavidas y saltar al agua adoptando la postura fetal. Una vez en el agua habrá que ponérselo e intentar nadar lo más rápidamente posible hacia cualquier objeto flotante para reducir la hipotermia.', false, '2025-09-13 13:53:10.446592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81ba0451-cb62-4fbe-9de0-e083bae457f0', 'ecc02381-7730-4b7a-933a-8e43577562a5', 'a', 'Disco de goma, fieltro o lona atravesado por un eje roscado con un brazo articulado transversal.', false, '2025-09-13 13:53:10.446864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72a43fc9-c7e5-49ed-b44b-29e6ca642fa4', 'ecc02381-7730-4b7a-933a-8e43577562a5', 'b', 'Orificio más pequeño que un imbornal por donde se produce una vía de agua.', false, '2025-09-13 13:53:10.447014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a7ba227-23ab-4da7-abd7-828ae5aff26a', 'ecc02381-7730-4b7a-933a-8e43577562a5', 'c', 'Cuña cónica de madera para tapar vías de agua por orificios de forma circular.', true, '2025-09-13 13:53:10.447145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e816de2-2c5c-4d9c-ae05-e5d8821781e0', 'ecc02381-7730-4b7a-933a-8e43577562a5', 'd', 'Tablero de contrachapado marino sellado al casco con silicona para tapar vías de agua.', false, '2025-09-13 13:53:10.447275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a4e6fd4-9d88-4473-88ff-3b2480feb2c8', '43683b50-e2c9-4081-ab82-ebefad29f0f3', 'a', 'Una tendencia a la mejoría.', false, '2025-09-13 13:53:10.448231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('128e901e-adf2-416a-9784-607a4c43c796', '43683b50-e2c9-4081-ab82-ebefad29f0f3', 'b', 'Una tendencia a la mejoría, pero con vientos fuertes.', false, '2025-09-13 13:53:10.448367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ee21e21-646d-40d3-8c24-f81e1a8d2003', '43683b50-e2c9-4081-ab82-ebefad29f0f3', 'c', 'Una tendencia al empeoramiento.', true, '2025-09-13 13:53:10.4485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c4c6394-e463-4cff-b94f-28a77185b40c', '43683b50-e2c9-4081-ab82-ebefad29f0f3', 'd', 'Una tendencia al empeoramiento, que va acompañada con fuertes vientos, precipitaciones y riesgo de temporal.', false, '2025-09-13 13:53:10.448633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e583960-f5c1-4d66-96cd-5dc69071e6c6', 'a480a390-03ab-4bb4-8eb5-09ed2af7f9df', 'a', 'Incremento de la fuerza del viento.', false, '2025-09-13 13:53:10.448914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e157b82-7781-43e1-95ba-3af8dc9434c9', 'a480a390-03ab-4bb4-8eb5-09ed2af7f9df', 'b', 'Disminución de la fuerza del viento o de la mar, total o parcialmente.', false, '2025-09-13 13:53:10.449044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe530d9f-670d-4e6a-82cb-b9ef448f4e41', 'a480a390-03ab-4bb4-8eb5-09ed2af7f9df', 'c', 'Disminución progresiva del viento.', false, '2025-09-13 13:53:10.44918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82202980-dadd-43c2-82db-be7f3fbb68f9', 'a480a390-03ab-4bb4-8eb5-09ed2af7f9df', 'd', 'Variación de la dirección del viento.', true, '2025-09-13 13:53:10.44944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fd830e0-9e20-4f4c-94c2-1a6e3b474cb2', 'b58271c5-d27e-47a9-9db5-f8cba005990b', 'b', 'El aire fluye hacia su interior y allí asciende.', false, '2025-09-13 13:53:10.449846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ca888a9-2106-4141-a93c-3493e3cf5444', 'b58271c5-d27e-47a9-9db5-f8cba005990b', 'd', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:10.450106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('712f88c4-3e67-4473-bf3f-0ec6ee311c09', '0cd4e1f1-3a31-4199-9cdf-f70dfc4aa5ac', 'a', 'Terral.', false, '2025-09-13 13:53:10.450382+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('176c21d9-baba-4748-a36f-f70a78fdef29', '0cd4e1f1-3a31-4199-9cdf-f70dfc4aa5ac', 'b', 'Fetch.', false, '2025-09-13 13:53:10.450516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8178d99-4ac0-4408-b0f0-9ee489e4f8bb', '0cd4e1f1-3a31-4199-9cdf-f70dfc4aa5ac', 'c', 'Virazón.', true, '2025-09-13 13:53:10.450645+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9518849a-0b78-4205-9a90-e64cf2ca78e9', '15196f40-16ba-414e-bf50-a893ab1d9517', 'a', 'Es el ángulo formado entre el Rumbo de aguja y el Rumbo de superficie.', true, '2025-09-13 13:53:10.451064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9aacc385-849f-4d2c-b9b8-5ee20d9dded7', '15196f40-16ba-414e-bf50-a893ab1d9517', 'b', 'Es el ángulo formado entre el Rumbo verdadero y el Rumbo de superficie.', false, '2025-09-13 13:53:10.451196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('003a3f3a-bbf6-45d9-9d64-0589be1b6261', '15196f40-16ba-414e-bf50-a893ab1d9517', 'd', 'Es el ángulo que se desvía la proa del barco hacia sotavento por la fuerza del viento.', false, '2025-09-13 13:53:10.451454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34263e48-d10c-436d-81f9-7c6073dd5be4', '80904d3e-f166-4932-b2cc-40b76efd316d', 'a', 'Su valor para una posición dada lo encontramos en la carta náutica.', false, '2025-09-13 13:53:10.451723+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dccd0c3-5542-48e5-93ed-0e24ad234323', '80904d3e-f166-4932-b2cc-40b76efd316d', 'b', 'Es el ángulo formado entre el Norte magnético y el Norte de aguja.', true, '2025-09-13 13:53:10.451872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3ad3ef0-49ae-4f9e-8ac4-b96de294822b', '80904d3e-f166-4932-b2cc-40b76efd316d', 'c', 'No ha de tenerse en cuenta en el cálculo de la Corrección total.', false, '2025-09-13 13:53:10.452006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('656518f8-0be7-4328-bdf7-2dab5a2d5054', '80904d3e-f166-4932-b2cc-40b76efd316d', 'd', 'Es positivo cuando el desvío es hacia el Noroeste.', false, '2025-09-13 13:53:10.452143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27749450-26b9-4137-b24c-aaa52600bff0', '1bd90b96-e991-428d-9074-0e8867df9925', 'a', 'Desde 0 a 360 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.452415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11f4db15-a3bb-48e0-9857-9e46648e5c58', '1bd90b96-e991-428d-9074-0e8867df9925', 'b', 'Desde 0 a 180 grados por estribor (positivas) y por babor (negativas).', true, '2025-09-13 13:53:10.452546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0286ec4-c9c9-4f2f-97bf-ea06e4b2252b', '1bd90b96-e991-428d-9074-0e8867df9925', 'c', 'Desde 0 a 90 grados en sentido horario (negativas) y antihorario (positivas).', false, '2025-09-13 13:53:10.452675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f19b1ed-9007-4174-815b-0aec195f62cc', '1bd90b96-e991-428d-9074-0e8867df9925', 'd', 'Desde 0 a 180 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.452812+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6387a78-1b01-413d-9827-c3497eae979c', '3feeebd0-ccd8-45c5-aa63-e52a05c2aa78', 'a', 'Varía con los años y según el lugar en que nos encontremos.', true, '2025-09-13 13:53:10.453086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b430a27-81e6-4cfd-935f-c6b19f50462a', '3feeebd0-ccd8-45c5-aa63-e52a05c2aa78', 'b', 'Depende únicamente del lugar en que nos encontremos.', false, '2025-09-13 13:53:10.453217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f90a5a5a-645e-4beb-9ffa-3f73527105ba', '3feeebd0-ccd8-45c5-aa63-e52a05c2aa78', 'c', 'No se incluye en las cartas náuticas.', false, '2025-09-13 13:53:10.453347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('439007de-15ee-4dc2-a066-7e93db4c06ef', '3feeebd0-ccd8-45c5-aa63-e52a05c2aa78', 'd', 'Es el ángulo que forman el norte magnético y el norte de aguja.', false, '2025-09-13 13:53:10.453476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c847f827-e0b3-4334-838f-a36026ebffec', 'b58271c5-d27e-47a9-9db5-f8cba005990b', 'a', 'Son regiones donde la presión atmosférica es más elevada que la de sus alrededores para el mismo nivel.', true, '2025-09-13 13:53:10.449708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b975702-83af-4f79-90ac-0708b4b8832e', 'b58271c5-d27e-47a9-9db5-f8cba005990b', 'c', 'El aire asciende en su interior, lo que se conoce como subsidencia, y fluye hacia el exterior del mismo.', false, '2025-09-13 13:53:10.449976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a938dd8a-dbe4-462b-ae12-3f965df18b15', '15196f40-16ba-414e-bf50-a893ab1d9517', 'c', 'Si el viento nos entra por el costado de estribor, el abatimiento será a babor y su signo será positivo.', false, '2025-09-13 13:53:10.451325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('926e2387-821c-43e5-bff2-73d760e7b148', '0cd4e1f1-3a31-4199-9cdf-f70dfc4aa5ac', 'd', 'Viento aparente.', false, '2025-09-13 13:53:10.450786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3ae7743-ea85-4417-966c-0fdca5d0a352', 'a1cce6c6-cd5b-47e0-94d2-d4aa663cf0f9', 'c', 'Atracar de punta con la proa a otra embarcación; se recomienda abarloarse por la sencillez de la maniobra.', false, '2025-09-13 13:53:10.445784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cab2af2e-fe18-4e6f-9b91-acf5c6e788d1', '6d8d7250-102a-46f6-aa07-f289e5e58974', 'a', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte aumentan hacia arriba y en el sur hacia abajo.', true, '2025-09-13 13:53:10.453745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af8ee0d6-1b7c-4e21-b112-7b4a62c158ff', '6d8d7250-102a-46f6-aa07-f289e5e58974', 'b', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte disminuyen hacia arriba y en el sur hacia abajo.', false, '2025-09-13 13:53:10.453892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be7c068b-0c58-442b-817e-81f8b8ccb2d5', '6d8d7250-102a-46f6-aa07-f289e5e58974', 'c', 'Están situadas en los márgenes superior e inferior y sus valores van aumentando al dirigirnos al oeste desde el meridiano 0º.', false, '2025-09-13 13:53:10.454021+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc37abf8-1fb1-41be-8a74-b45369b9c0bf', '6d8d7250-102a-46f6-aa07-f289e5e58974', 'd', 'Están situadas a los márgenes izquierdo y derecho de la carta y sus valores van aumentando al dirigirnos al este desde el meridiano 0º. Carta de navegación.', false, '2025-09-13 13:53:10.454154+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82c074f7-f580-4dcb-b5f7-4dd8cb6af12d', 'e2b2955a-1c5b-4b9c-9893-5a2d21b473aa', 'd', 'Ra=295º; l= 35º 56,40´N; L=005º 39,20´W', true, '2025-09-13 13:53:10.454961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f37438f-da23-4656-bd58-a8c53620520e', 'bc8b704c-d31b-4884-8167-8797300b7d4a', 'd', 'l=36º 12´N L=005º 12,8´W', false, '2025-09-13 13:53:10.455663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('597b1a06-90c6-4927-9ea1-c2398c8a7d21', '5485d1ab-f149-4a93-94eb-c247052f8e02', 'a', '280º.', false, '2025-09-13 13:53:10.455984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d24cb5a3-edf1-48eb-b2c6-d1f961523689', '5485d1ab-f149-4a93-94eb-c247052f8e02', 'b', '283º.', false, '2025-09-13 13:53:10.456121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dc4befa-4c49-44ff-be07-57b02a00a1fd', '5485d1ab-f149-4a93-94eb-c247052f8e02', 'c', '258º.', false, '2025-09-13 13:53:10.456267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cbea5c3-d741-4a3d-99bf-feb3d7884157', '5485d1ab-f149-4a93-94eb-c247052f8e02', 'd', '264º.', true, '2025-09-13 13:53:10.456403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bac1942e-047a-4aa0-a919-eeb8149caf96', 'd5b461cf-0107-4322-b37d-b2dcb986543b', 'a', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de babor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', true, '2025-09-13 13:53:10.457489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe0648e6-7501-416d-a39b-f7c48ba0cf08', 'd5b461cf-0107-4322-b37d-b2dcb986543b', 'b', 'Atracar de costado a otra embarcación. Es mejor atracar por el costado de estribor, metiendo primero la proa, porque después al dar marcha atrás la popa atraca más fácilmente porque la presión lateral de las palas y la corriente de expulsión nos favorecen.', false, '2025-09-13 13:53:10.457621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ac02d47-35a2-4c69-9d97-63600462ded3', 'd5b461cf-0107-4322-b37d-b2dcb986543b', 'd', 'Atracar con la popa a otra embarcación; siempre se recomienda cuando es necesario desembarcar mejor y tener la maniobra de salida más clara.', false, '2025-09-13 13:53:10.457893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5003cba-c2c7-49ea-b202-274f98f921d6', '29ebae9d-7798-4835-b584-7615ebd7d2d6', 'a', 'La popa cae a estribor.', false, '2025-09-13 13:53:10.458309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53f72029-45d2-4639-b115-f929bae2bc80', '29ebae9d-7798-4835-b584-7615ebd7d2d6', 'b', 'La popa cae a babor.', true, '2025-09-13 13:53:10.458446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bb20e70-0077-40f1-a906-f9b09fed1e4d', '29ebae9d-7798-4835-b584-7615ebd7d2d6', 'c', 'La popa no cae a ningún costado.', false, '2025-09-13 13:53:10.458579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4851cfa-e516-4ea2-b2a7-ea9d2ce15a2d', '2f14b5bb-5326-4749-b99f-d129b22a517d', 'a', 'Disco de goma, fieltro o lona atravesado por un eje roscado con un brazo articulado transversal.', false, '2025-09-13 13:53:10.458987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b785dd9d-f096-4b01-a202-06168fce5a38', '2f14b5bb-5326-4749-b99f-d129b22a517d', 'b', 'Orificio más pequeño que un imbornal por donde se produce una vía de agua.', false, '2025-09-13 13:53:10.459118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b5630ef-2276-4360-b819-2c41a7ca2f0e', '2f14b5bb-5326-4749-b99f-d129b22a517d', 'c', 'Cuña cónica de madera para tapar vías de agua por orificios de forma circular.', true, '2025-09-13 13:53:10.459256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90dffca2-e199-4f30-b457-77d023093fd7', '2f14b5bb-5326-4749-b99f-d129b22a517d', 'd', 'Tablero de contrachapado marino sellado al casco con silicona para tapar vías de agua.', false, '2025-09-13 13:53:10.459389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0793ee65-0a7e-4cf8-a286-6ebb8fd2d085', 'e7b71b70-7cc0-4470-80d3-9022a526fabd', 'a', 'Saltando en parejas cogidos por los brazos, con el fin de poder agruparnos lo más rápido posible y ser más visibles.', false, '2025-09-13 13:53:10.459656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3dcf1d89-75f9-42a9-9d74-eed47b21ca40', 'e7b71b70-7cc0-4470-80d3-9022a526fabd', 'b', 'Saltando por barlovento de pie y con el chaleco puesto. Solo en determinados casos, como por ejemplo un incendio en esa banda, se podría saltar por sotavento.', false, '2025-09-13 13:53:10.459795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f037a44-5a82-4d0e-aee3-66ddf629e318', 'e7b71b70-7cc0-4470-80d3-9022a526fabd', 'c', 'Saltando al agua de pie, con las piernas y rodillas juntas, sujetando el chaleco y tapándose la nariz. Si una vez en el agua hubiera que nadar, deberá hacerse de espaldas.', true, '2025-09-13 13:53:10.459946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ddacfa1-2329-456b-bcca-549fb9b89204', 'e7b71b70-7cc0-4470-80d3-9022a526fabd', 'd', 'Se deberá lanzar al agua el chaleco salvavidas y saltar al agua adoptando la postura fetal. Una vez en el agua habrá que ponérselo e intentar nadar lo más rápidamente posible hacia cualquier objeto flotante para reducir la hipotermia.', false, '2025-09-13 13:53:10.460079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52c0ca00-eab9-4bd8-a6c2-07741bb33565', 'b8d5e4b3-6e16-4ea0-bec9-e6616985a122', 'a', 'Si una persona sufre una fuerte contusión en el abdomen, se le proporcionara reposo absoluto, manteniéndose en observación y se realizarán consultas radiomédicas.', false, '2025-09-13 13:53:10.460358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b893f5c0-d923-496a-ae59-5d12afc5b95c', 'b8d5e4b3-6e16-4ea0-bec9-e6616985a122', 'b', 'En una hemorragia arterial la sangre mana a impulsos y habrá que realizar un torniquete un poco por encima de la herida.', false, '2025-09-13 13:53:10.460491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c920d694-86ae-4794-8147-513bb8409eae', 'b8d5e4b3-6e16-4ea0-bec9-e6616985a122', 'd', 'Las quemaduras de tercer grado son las producidas por acción intensa y directa de una llama o sólido incandescente y la costra que se produce no debe ser destruida. Meteorología', false, '2025-09-13 13:53:10.460749+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4482f01-1478-483e-97a2-0cd41e0e0e22', '114968c7-6592-4cbd-99b2-8b7a791a408b', 'a', 'Terral.', false, '2025-09-13 13:53:10.461027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c1f8311-43cc-43d7-8104-108e4de78856', '114968c7-6592-4cbd-99b2-8b7a791a408b', 'b', 'Fetch.', false, '2025-09-13 13:53:10.461163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f00bf13f-aeec-4a52-a117-37f21bd829e7', '114968c7-6592-4cbd-99b2-8b7a791a408b', 'c', 'Virazón.', true, '2025-09-13 13:53:10.461297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84b0299d-ac84-4686-b5c8-edc2387af937', '114968c7-6592-4cbd-99b2-8b7a791a408b', 'd', 'Viento aparente.', false, '2025-09-13 13:53:10.461425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('553e72ad-990a-4959-950e-e72d1149965d', 'a94d36c2-e568-4d1f-ba18-2a635085a614', 'a', 'Una tendencia a la mejoría.', false, '2025-09-13 13:53:10.461828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6e7ae21-90da-47e4-b8d0-d2f8501f93df', 'a94d36c2-e568-4d1f-ba18-2a635085a614', 'b', 'Una tendencia a la mejoría, pero con vientos fuertes.', false, '2025-09-13 13:53:10.461962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7acfa730-8c8d-40dd-9758-f2f1149e78e5', 'a94d36c2-e568-4d1f-ba18-2a635085a614', 'c', 'Una tendencia al empeoramiento.', true, '2025-09-13 13:53:10.462092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88a1a3ad-d8e3-4399-9e98-c8f5a639e458', 'a94d36c2-e568-4d1f-ba18-2a635085a614', 'd', 'Una tendencia al empeoramiento, que va acompañada con fuertes vientos, precipitaciones y riesgo de temporal.', false, '2025-09-13 13:53:10.462227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8af34df-a192-4935-8f6f-17db37f10561', 'da925cb7-63b1-4d60-aef2-03ef7c5c3b1f', 'b', 'El aire fluye hacia su interior y allí asciende.', false, '2025-09-13 13:53:10.462633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('400d7984-f997-46e7-be44-4d464e62a7b5', 'b8d5e4b3-6e16-4ea0-bec9-e6616985a122', 'c', 'En caso de insolación hay que sumergir al afectado en agua fría para bajar la temperatura hasta los 35º.', true, '2025-09-13 13:53:10.46062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30b83a21-a8af-4999-a813-2b0cf664d6bc', 'da925cb7-63b1-4d60-aef2-03ef7c5c3b1f', 'a', 'Son regiones donde la presión atmosférica es más elevada que la de sus alrededores para el mismo nivel.', true, '2025-09-13 13:53:10.462503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a4b5d48-aa56-4b57-b3d7-f856b05f6eb0', 'e2b2955a-1c5b-4b9c-9893-5a2d21b473aa', 'a', 'Ra=294º; l= 35º 56,60´N; L=005º 40,70´W.', false, '2025-09-13 13:53:10.454558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('965d2844-ac31-4a19-9f85-09071217c9f8', 'e2b2955a-1c5b-4b9c-9893-5a2d21b473aa', 'b', 'Ra=296º; l= 35º 56,40´N; L=005º 39,20´W.', false, '2025-09-13 13:53:10.454689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7600808-fc28-4e3d-88d4-2608453f66b6', 'e2b2955a-1c5b-4b9c-9893-5a2d21b473aa', 'c', 'Ra=295º; l= 35º 56,40´N; L=005º 40,70´W.', false, '2025-09-13 13:53:10.454824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37eec7bc-69cd-4077-9757-9ed358626214', 'bc8b704c-d31b-4884-8167-8797300b7d4a', 'a', 'l=35º 12´N ; L=005º 7´W.', false, '2025-09-13 13:53:10.455234+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4e9579f-5dbf-4a9f-9f29-16dbb8c23e56', 'bc8b704c-d31b-4884-8167-8797300b7d4a', 'b', 'l=35º 35´N; L=005º 10,8´W.', false, '2025-09-13 13:53:10.455364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f27f9bb8-4528-469b-9ef1-1b983883ba59', 'bc8b704c-d31b-4884-8167-8797300b7d4a', 'c', 'l=35º 50´N; L=005º 14´W.', true, '2025-09-13 13:53:10.455498+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99f9cdc3-b1ba-4fc7-be45-8f8239702edc', '29ebae9d-7798-4835-b584-7615ebd7d2d6', 'd', 'La popa cae inicialmente a estribor y luego a babor.', false, '2025-09-13 13:53:10.458712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cfe3a14-f24d-41cf-b6c7-44f9971b8d08', 'd5b461cf-0107-4322-b37d-b2dcb986543b', 'c', 'Atracar de punta con la proa a otra embarcación; se recomienda abarloarse por la sencillez de la maniobra.', false, '2025-09-13 13:53:10.45775+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e188e5b-d6d2-4d26-a435-d0a0c76bfcdc', 'da925cb7-63b1-4d60-aef2-03ef7c5c3b1f', 'd', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:10.462909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c94e5ef2-fc94-469b-828a-df76b99a3025', 'c1f5057a-1e62-4716-899e-7c86497a880a', 'a', 'Incremento de la fuerza del viento.', false, '2025-09-13 13:53:10.463179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d5b66ed-a3c1-48ac-afcb-a7e36f736086', 'c1f5057a-1e62-4716-899e-7c86497a880a', 'b', 'Disminución de la fuerza del viento o de la mar, total o parcialmente.', false, '2025-09-13 13:53:10.463308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('212dff6a-90eb-48f1-951e-8800e88e8360', 'c1f5057a-1e62-4716-899e-7c86497a880a', 'c', 'Disminución progresiva del viento.', false, '2025-09-13 13:53:10.463437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('717433e3-6025-4fb4-bf59-86e552dfa0db', '5cce633f-3da0-4e35-8bf5-b46458293c86', 'a', 'Su valor para una posición dada lo encontramos en la carta náutica.', false, '2025-09-13 13:53:10.463838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cbb3c63-a7ff-4a11-afcd-009fb28582ad', '5cce633f-3da0-4e35-8bf5-b46458293c86', 'b', 'Es el ángulo formado entre el Norte magnético y el Norte de aguja.', true, '2025-09-13 13:53:10.463979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0377144-ffdb-4409-b98a-e211eb622435', '5cce633f-3da0-4e35-8bf5-b46458293c86', 'c', 'No ha de tenerse en cuenta en el cálculo de la Corrección total.', false, '2025-09-13 13:53:10.464118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bf3fa0d-30ac-409a-8157-abd2bb6b2b6c', '5cce633f-3da0-4e35-8bf5-b46458293c86', 'd', 'Es positivo cuando el desvío es hacia el Noroeste.', false, '2025-09-13 13:53:10.464255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56daa276-5606-41dc-977b-53337c3fff38', '88103fa1-d586-47d9-b054-2bc9dcf9aa0b', 'a', 'Varía con los años y según el lugar en que nos encontremos.', true, '2025-09-13 13:53:10.464528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2555e4dc-aba8-4a28-9b3b-0b41acbfbad8', '88103fa1-d586-47d9-b054-2bc9dcf9aa0b', 'b', 'Depende únicamente del lugar en que nos encontremos.', false, '2025-09-13 13:53:10.464661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7fd55c9-ce83-4733-99b9-e95f4a10731d', '88103fa1-d586-47d9-b054-2bc9dcf9aa0b', 'c', 'No se incluye en las cartas náuticas.', false, '2025-09-13 13:53:10.464796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c924ade-d138-4ef1-8374-297e2c77079a', '88103fa1-d586-47d9-b054-2bc9dcf9aa0b', 'd', 'Es el ángulo que forman el norte magnético y el norte de aguja.', false, '2025-09-13 13:53:10.464927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1818a93-7061-45f8-a607-14079fe36ac8', 'f52b92c9-6892-49e2-80b2-54504ded987c', 'a', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte aumentan hacia arriba y en el sur hacia abajo.', true, '2025-09-13 13:53:10.465195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b8fd998-3446-4027-8bff-ded549959901', 'f52b92c9-6892-49e2-80b2-54504ded987c', 'b', 'Están situadas a los márgenes izquierdo y derecho de la carta. En el hemisferio norte disminuyen hacia arriba y en el sur hacia abajo.', false, '2025-09-13 13:53:10.465329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8f28816-cdbc-4d97-84ad-b2d04911c1c0', 'f52b92c9-6892-49e2-80b2-54504ded987c', 'c', 'Están situadas en los márgenes superior e inferior y sus valores van aumentando al dirigirnos al oeste desde el meridiano 0º.', false, '2025-09-13 13:53:10.465461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62ca1546-7a3a-458e-abb7-e802746103e7', 'f52b92c9-6892-49e2-80b2-54504ded987c', 'd', 'Están situadas a los márgenes izquierdo y derecho de la carta y sus valores van aumentando al dirigirnos al este desde el meridiano 0º.', false, '2025-09-13 13:53:10.46559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54add84e-54ea-4e84-81b0-c35fa2363cd7', '11385290-e3be-4be9-ad3f-0970b58a77be', 'a', 'Es el ángulo formado entre el Rumbo de aguja y el Rumbo de superficie.', true, '2025-09-13 13:53:10.465879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ac35f8d-c25a-4fe4-b8d3-19a9b64b1109', '11385290-e3be-4be9-ad3f-0970b58a77be', 'b', 'Es el ángulo formado entre el Rumbo verdadero y el Rumbo de superficie.', false, '2025-09-13 13:53:10.466024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6812d92-2d62-4086-8e6a-817889227d2a', '11385290-e3be-4be9-ad3f-0970b58a77be', 'd', 'Es el ángulo que se desvía la proa del barco hacia sotavento por la fuerza del viento.', false, '2025-09-13 13:53:10.466325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e00248f-7485-46d2-bf41-9a0b76ef7d85', '3da1c6ec-d794-418d-a9b9-a7492deef9c5', 'a', 'Desde 0 a 360 grados en sentido antihorario (positivas).', false, '2025-09-13 13:53:10.466646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03cc09dd-7ba3-4cae-a381-7f4b9f273c1e', '3da1c6ec-d794-418d-a9b9-a7492deef9c5', 'b', 'Desde 0 a 180 grados por estribor (positivas) y por babor (negativas).', true, '2025-09-13 13:53:10.466914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('223761c0-9f9c-4263-bbdc-65f868b3fb32', '3da1c6ec-d794-418d-a9b9-a7492deef9c5', 'c', 'Desde 0 a 90 grados en sentido horario (negativas) y antihorario (positivas).', false, '2025-09-13 13:53:10.467046+00');
