INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2cb03d2-82b9-4587-a283-138fa586da80', 'fafae9e5-d728-425f-9a1f-10b1ef579958', 'a', 'Ventana abierta en un techo o en la parte superior de una pared, generalmente con derrame hacia', false, '2025-09-13 13:53:10.471708+00');
