INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e9f3baa-c222-4605-9c47-13bbd86ecfd0', 'fafae9e5-d728-425f-9a1f-10b1ef579958', 'c', 'Escotilla, generalmente con cubierta de cristales, cuyo objeto casi único es proporcionar luz y ventilación a determinados lugares del buque y principalmente a las cámaras.', true, '2025-09-13 13:53:10.472113+00');
