INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f39498e2-391a-4e9a-b27c-bba516deee98', 'f57f4d33-70ed-4d2a-bce8-0459f518a5ec', 'a', 'Es la pieza que corre de proa a popa, a lo largo de la línea media más baja del buque, siendo el principal refuerzo longitudinal, en el cual descargan los demás.', false, '2025-09-13 13:53:10.473833+00');
