INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4a1209c-027a-4cbf-be90-165f9d9a7558', '4d6fdf7f-d480-456e-9da4-12ee8aea621e', 'c', 'Cuando el ancla no se queda firme en el fondo, provocando un desplazamiento del barco a sotavento, se dice que garrea.', true, '2025-09-13 13:53:10.476894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ef17ed6-bf1d-4805-9096-0e1a4f185e54', '4d6fdf7f-d480-456e-9da4-12ee8aea621e', 'd', 'Un barco fondea a la gira utilizando dos anclas por la proa, procurando que la longitud de las líneas de fondeo sea idéntica para las dos anclas.', false, '2025-09-13 13:53:10.477074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('563383f2-5a82-4001-a291-6b6d2996b87d', 'a48e1c97-cc8e-4f9a-acad-5f7495805628', 'a', 'Mantendremos el rumbo de aguja.', false, '2025-09-13 13:53:10.477381+00');
