INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94aa5120-2b86-4811-bbb9-8f9a01fea522', '71ea148b-dadf-4cf2-bad8-69f5320a418e', 'c', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', true, '2025-09-13 13:53:10.480796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12d61992-f28c-49a4-94d5-1e97f82c2ffd', '71ea148b-dadf-4cf2-bad8-69f5320a418e', 'd', 'Los desechos de los alimentos podrán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:10.480932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1881af9-46d3-4d6e-9073-b7d90f20d6aa', 'cf579796-478b-426e-9109-d95e13c0cfab', 'a', 'Deberá alejarse de la zona al menos 200 metros, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.481242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6201617-24ed-4499-911d-5741520d1980', 'cf579796-478b-426e-9109-d95e13c0cfab', 'b', 'Deberá alejarse de la zona al menos 200 millas náuticas, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.481378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87f641de-9b15-46f2-ada0-4f842c449704', 'cf579796-478b-426e-9109-d95e13c0cfab', 'c', 'En ningún caso podrá fondear la embarcación, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:10.481513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ab2c77f-5049-4b46-ba8a-55c7df0ff13e', 'cf579796-478b-426e-9109-d95e13c0cfab', 'd', 'Se podrá fondear con finalidad exclusiva de recreo, siempre que no pongan en peligro la seguridad de la vida humana en la mar o de la navegación, debiendo navegar a una velocidad no superior a 3 nudos, adoptando las precauciones necesarias.', true, '2025-09-13 13:53:10.481646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('022cc66a-a1ca-4d97-bc29-f5452c58910e', '179d4b6b-bf4c-46c4-bbb8-932d5c1ed7d5', 'a', 'Blanca y grupos de dos destellos.', true, '2025-09-13 13:53:10.481949+00');
