INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c627e42-437b-407e-b889-94afa3d49284', '0b6b3cbd-05c2-4202-8ef7-e4a8a90a2266', 'a', 'El buque que tenga al otro por su costado de babor, se mantendrá apartado de la derrota de éste', false, '2025-09-13 13:53:10.492598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d74a5adc-1584-496f-9c3a-b276e7084487', '0b6b3cbd-05c2-4202-8ef7-e4a8a90a2266', 'b', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste otro, evitando cortarle la popa.', false, '2025-09-13 13:53:10.49274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('422a9518-f693-4d88-b76b-296cfb1a0495', '0b6b3cbd-05c2-4202-8ef7-e4a8a90a2266', 'c', 'El de mayor tonelaje tendrá que detenerse para facilitar el paso.', false, '2025-09-13 13:53:10.492888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c626355d-dd41-4944-b6e8-e0ae0f96a5f4', '0b6b3cbd-05c2-4202-8ef7-e4a8a90a2266', 'd', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste DE TRANSPORTES, MOVILIDAD                                                                         DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                   Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 06 Nomenclatura náutica.', true, '2025-09-13 13:53:10.493024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8bfccd4-d06a-459c-ae3f-cc46ad9b07f9', '5521b54e-b4af-4575-a8fb-a521d2c2bb1f', 'a', 'La embarcación de estribor está a sotavento.', false, '2025-09-13 13:53:10.493441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af2a32d8-e193-4417-8e7c-ad790512354f', '5521b54e-b4af-4575-a8fb-a521d2c2bb1f', 'b', 'La embarcación de babor está a barlovento.', false, '2025-09-13 13:53:10.493575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92c92251-754b-46b8-8a74-4e7be90b6fba', '5521b54e-b4af-4575-a8fb-a521d2c2bb1f', 'c', 'La embarcación de estribor está a barlovento.', true, '2025-09-13 13:53:10.493712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be6c0e72-6cf8-49ad-8ec4-034c095a3cb9', '5521b54e-b4af-4575-a8fb-a521d2c2bb1f', 'd', 'La embarcación de babor recibe el viento por la banda opuesta a la de estribor.', false, '2025-09-13 13:53:10.493874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3e240a5-573b-4fa7-9685-05e2d8ed56bb', 'ce694e18-0254-4b3c-b571-4abc891486ab', 'a', 'Es la pieza que corre de proa a popa, a lo largo de la línea media más baja del buque, siendo el principal refuerzo longitudinal, en el cual descargan los demás.', false, '2025-09-13 13:53:10.494162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f0203a9-f80c-4028-835b-081162d25645', 'ce694e18-0254-4b3c-b571-4abc891486ab', 'b', 'Es un elemento estructural que se encastra en la quilla.', true, '2025-09-13 13:53:10.4943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27152689-e9ff-4832-a3a6-51f1dbfa918f', 'ce694e18-0254-4b3c-b571-4abc891486ab', 'c', 'Es la “columna vertebral” del buque en la que se encastran las cuadernas, la quilla y el codaste.', false, '2025-09-13 13:53:10.494432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aaafd36-9589-49a0-8cc3-68e4d2e8cf6b', 'ce694e18-0254-4b3c-b571-4abc891486ab', 'd', 'Elemento estructural que continúa la quilla en la popa.', false, '2025-09-13 13:53:10.494571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10d1fe48-fcc0-4b77-9a56-d4bb1729fcc7', '51a715b0-f34f-48fb-b48d-124e1b7d9848', 'a', 'La hélice.', true, '2025-09-13 13:53:10.494874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('603d4c0c-3e86-4a6d-80ed-2f3b4f5d27f5', '51a715b0-f34f-48fb-b48d-124e1b7d9848', 'b', 'El motor.', false, '2025-09-13 13:53:10.495151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fd2683c-c04f-44f0-99ad-f72d1062f1a4', '51a715b0-f34f-48fb-b48d-124e1b7d9848', 'c', 'El timón.', false, '2025-09-13 13:53:10.495289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f95cfef-e595-40c6-bbef-8b43edec780b', '51a715b0-f34f-48fb-b48d-124e1b7d9848', 'd', 'La vela.', false, '2025-09-13 13:53:10.49543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('304097a9-b8e8-435e-a636-e2cb62cdc076', '8b518013-1a00-427f-986b-b083fb155528', 'a', 'Ventana abierta en un techo o en la parte superior de una pared, generalmente con derrame hacia', false, '2025-09-13 13:53:10.495721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e704cf2-979f-422b-9cfa-de547f5e6d95', '8b518013-1a00-427f-986b-b083fb155528', 'b', 'Abertura estanca, generalmente redonda, que se encuentra en las cámaras o casco de la embarcación, para dar luz y ventilación.', false, '2025-09-13 13:53:10.495882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e460ce3d-f14d-464d-955d-3d67e0541b29', '8b518013-1a00-427f-986b-b083fb155528', 'c', 'Escotilla, generalmente con cubierta de cristales, cuyo objeto casi único es proporcionar luz y ventilación a determinados lugares del buque y principalmente a las cámaras.', true, '2025-09-13 13:53:10.496023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43a960df-9430-465b-ae55-8badb556152f', '8b518013-1a00-427f-986b-b083fb155528', 'd', 'Cada una de las aberturas que hay en las diversas cubiertas para el servicio del buque. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.496157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('909d51d6-b0bc-42fe-a1c8-f5f814c58766', '7e60b501-64e6-48ce-b593-2a560e3c738f', 'a', 'El círculo de borneo tiene como radio la cadena de fondeo.', false, '2025-09-13 13:53:10.496444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94be7c8d-49bb-4f0a-b820-9027e021b8a5', '7c32ce30-f80d-4c23-ba77-833d5f5ab02c', 'd', 'Plan.', true, '2025-09-13 13:53:10.866136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84de1576-9d1e-4503-9c3b-2a7f2913f737', '7e60b501-64e6-48ce-b593-2a560e3c738f', 'b', 'El tenedero es el cabo que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder recuperar el ancla.', false, '2025-09-13 13:53:10.496589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1604f9fe-3e53-420f-8818-60cbcdab64e0', '7e60b501-64e6-48ce-b593-2a560e3c738f', 'c', 'Cuando el ancla no se queda firme en el fondo, provocando un desplazamiento del barco a sotavento, se dice que garrea.', true, '2025-09-13 13:53:10.496738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f63306a-9fd3-4568-b01c-5e65c85f2478', '7e60b501-64e6-48ce-b593-2a560e3c738f', 'd', 'Un barco fondea a la gira utilizando dos anclas por la proa, procurando que la longitud de las líneas de fondeo sea idéntica para las dos anclas.', false, '2025-09-13 13:53:10.496927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bb16bc0-ddf9-4601-bdc7-63b08e912d4a', '72a2d036-1138-4bc3-adfe-ae72025a7831', 'a', 'Roldana.', false, '2025-09-13 13:53:10.497328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd3500c4-ab02-400e-9bd2-2a00b2adaa5c', '72a2d036-1138-4bc3-adfe-ae72025a7831', 'b', 'Bita.', false, '2025-09-13 13:53:10.497466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ebfa7de-d43f-4b0c-92cb-65bede4399af', '72a2d036-1138-4bc3-adfe-ae72025a7831', 'c', 'Guía-cabos.', true, '2025-09-13 13:53:10.497601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0e899e6-9842-424e-b0f1-38187378e368', '72a2d036-1138-4bc3-adfe-ae72025a7831', 'd', 'Cornamusa.', false, '2025-09-13 13:53:10.497742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99b40380-0111-4436-ab08-75c1c707019d', '16da7505-6ef2-464b-b676-a3e205d8a41b', 'a', 'Cabecea lentamente.', false, '2025-09-13 13:53:10.498347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5df34042-0856-4a1c-bd70-5fd90a872a17', '16da7505-6ef2-464b-b676-a3e205d8a41b', 'b', 'Balancea lentamente.', false, '2025-09-13 13:53:10.4986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c79f3049-6f07-461c-81c1-f6166fcc2cea', '16da7505-6ef2-464b-b676-a3e205d8a41b', 'c', 'No se mueve.', false, '2025-09-13 13:53:10.498935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('593815cb-b743-41a6-94fd-af03052433e2', '16da7505-6ef2-464b-b676-a3e205d8a41b', 'd', 'Balancea rápidamente.', true, '2025-09-13 13:53:10.499111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('547fd398-2fb8-4613-87ad-26f49195150c', '6b7cd057-1762-4b92-aa7c-c5f7421cb48c', 'a', '900 061 061', false, '2025-09-13 13:53:10.49943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25ab167b-92f9-42d8-9945-b3420bb8c84a', '6b7cd057-1762-4b92-aa7c-c5f7421cb48c', 'b', '900 091 091', false, '2025-09-13 13:53:10.499594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d59e29ac-5810-43e9-a244-8142ea58afca', '6b7cd057-1762-4b92-aa7c-c5f7421cb48c', 'c', '900 202 202', true, '2025-09-13 13:53:10.499737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68b48cc0-3789-4194-8c2e-f764206a9a12', '6b7cd057-1762-4b92-aa7c-c5f7421cb48c', 'd', '900 112 112', false, '2025-09-13 13:53:10.500005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42fc461f-83d9-4af5-93af-06bba4fcfb8c', '809715ba-8c78-4497-90cb-9a0c3aae1340', 'a', 'Mantendremos el rumbo de aguja.', false, '2025-09-13 13:53:10.500771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19167188-fdeb-4408-8050-8b8e19f24eed', '809715ba-8c78-4497-90cb-9a0c3aae1340', 'b', 'Orientaremos la proa de la embarcación a barlovento.', true, '2025-09-13 13:53:10.501149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff195dd2-40db-4f34-b161-88ee10032d4a', '809715ba-8c78-4497-90cb-9a0c3aae1340', 'c', 'Echaremos el ancla flotante y seguiremos a rumbo.', false, '2025-09-13 13:53:10.501343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03591775-d3f3-4c01-81aa-a77371553693', '809715ba-8c78-4497-90cb-9a0c3aae1340', 'd', 'Haremos sonar la bocina.', false, '2025-09-13 13:53:10.501529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08c527d0-f439-4f7f-9adb-ab69785e2151', '58e0dead-e993-4fb3-ba9d-4d30f4c2ae61', 'a', 'Mejoraremos la navegación con el mar por la amura.', true, '2025-09-13 13:53:10.501948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c94263ec-4139-414c-a124-aca2e545282e', '58e0dead-e993-4fb3-ba9d-4d30f4c2ae61', 'b', 'Mejoraremos la maniobrabilidad si aumentamos la velocidad.', false, '2025-09-13 13:53:10.502109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77d989ad-5222-430b-9454-4e8561b6b3b5', '58e0dead-e993-4fb3-ba9d-4d30f4c2ae61', 'c', 'Al disminuir la sonda aumentará la velocidad de la embarcación.', false, '2025-09-13 13:53:10.502251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48a3b2ff-5906-457c-ab92-2d1808f5c8f5', '58e0dead-e993-4fb3-ba9d-4d30f4c2ae61', 'd', 'Disminuirán las cabezadas al reducirse la altura de la ola.', false, '2025-09-13 13:53:10.502394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('058b68e8-5312-4df4-8007-d9a87a14efc5', '9992b470-3150-4314-8be3-f0cc92618e62', 'a', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 25 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', false, '2025-09-13 13:53:10.502839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a0fc62b-0e05-463d-a5a3-1817d8d8bfe0', '9992b470-3150-4314-8be3-f0cc92618e62', 'b', 'Los desechos de los alimentos deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', false, '2025-09-13 13:53:10.502979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06947b6a-9051-40b0-a52c-8ff9f20139e4', '9992b470-3150-4314-8be3-f0cc92618e62', 'c', 'Tan lejos como sea posible de la tierra más próxima, pero a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', true, '2025-09-13 13:53:10.503121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b4e57b0-388c-4290-a7e5-9d3b4b1d8323', '9992b470-3150-4314-8be3-f0cc92618e62', 'd', 'Los desechos de los alimentos podrán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:10.503262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2af6ca4f-0faf-4554-a287-2b94310cb454', '908e901c-f884-4ade-8bfc-590586f18a06', 'a', 'Deberá alejarse de la zona al menos 200 metros, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.503546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c67baa4c-2fb3-4e17-9aba-a1a88ef7fa0e', '908e901c-f884-4ade-8bfc-590586f18a06', 'b', 'Deberá alejarse de la zona al menos 200 millas náuticas, lo antes posible, por estar prohibida la navegación deportiva a menos de esa distancia.', false, '2025-09-13 13:53:10.503684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cbb9eb7-a681-4eb5-b8f8-f6146c8155c8', '908e901c-f884-4ade-8bfc-590586f18a06', 'c', 'En ningún caso podrá fondear la embarcación, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:10.503821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7605403a-2f99-4d04-852d-b817de799e3e', '908e901c-f884-4ade-8bfc-590586f18a06', 'd', 'Se podrá fondear con finalidad exclusiva de recreo, siempre que no pongan en peligro la seguridad de la vida humana en la mar o de la navegación, debiendo navegar a una velocidad no superior a 3 nudos, adoptando las precauciones necesarias.', true, '2025-09-13 13:53:10.503959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('706429dd-9a85-4f15-a6a5-18080c3bb386', '84b91be2-8c26-4369-a251-9cd01273fcb4', 'a', 'Marca especial.', false, '2025-09-13 13:53:10.504239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88d167b0-6447-41e1-a77b-33d632011c48', '84b91be2-8c26-4369-a251-9cd01273fcb4', 'b', 'Marca de peligros nuevos.', false, '2025-09-13 13:53:10.504374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72cb6e94-9a66-4cdf-afe6-70f9a5eeaf07', '84b91be2-8c26-4369-a251-9cd01273fcb4', 'c', 'Marca de peligro aislado.', true, '2025-09-13 13:53:10.504508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5f96990-20a2-4e72-83bc-38a0aba89a0a', '84b91be2-8c26-4369-a251-9cd01273fcb4', 'd', 'Marca cardinal.', false, '2025-09-13 13:53:10.504641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce2b6bd2-5974-4ebe-ae85-dc3cfa1727c8', '4b862a01-b096-471c-a6a8-a2907323739a', 'a', 'Una marca cardinal recibe el nombre del cuadrante en el que está colocada.', false, '2025-09-13 13:53:10.504935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c7cd913-dce4-4ea7-af39-dc75995c1db4', '4b862a01-b096-471c-a6a8-a2907323739a', 'b', 'Las marcas cardinales y su uso, son las mismas para la Región A y la Región B.', false, '2025-09-13 13:53:10.505069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d07dd26a-5ff4-4d86-9a6f-3ecb249bc747', '4b862a01-b096-471c-a6a8-a2907323739a', 'c', 'El nombre de una marca cardinal indica que se ha de evitar pasar por el cuadrante correspondiente a ese nombre.', true, '2025-09-13 13:53:10.5052+00');
