INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c717b79-3cc6-443c-9cf3-3f43ddc5e12c', '75f66ea3-10a7-4ddb-a705-772adacf9223', 'b', 'Capacete.', false, '2025-09-13 13:53:10.518131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0117d8e1-ed99-43fc-9b96-55ce69f314b9', '75f66ea3-10a7-4ddb-a705-772adacf9223', 'c', 'Bocina.', false, '2025-09-13 13:53:10.518264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37519919-158c-4109-8f56-e5d74181fe78', '999ac109-d02e-42b7-bfbe-ee768e05e6d5', 'a', 'Las embarcaciones deben disponer de una línea de fondeo cuya longitud no será inferior a cinco veces la eslora de la embarcación.', false, '2025-09-13 13:53:10.518662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('991f52de-8a30-49a5-8328-cce62fa51448', '999ac109-d02e-42b7-bfbe-ee768e05e6d5', 'b', 'Para levar el ancla se dará un poco atrás mientras se cobra el elemento de fondeo hasta que el ancla esté a pique y tocando el fondo.', true, '2025-09-13 13:53:10.518816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('987a672f-1b82-45cb-a503-1b94e8a1bf24', '999ac109-d02e-42b7-bfbe-ee768e05e6d5', 'c', 'A la hora de fondear los mejores tenederos son los de arena fina y compacta, los de arcilla, fango compacto o arena fangosa.', false, '2025-09-13 13:53:10.518954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca436fdd-7530-4326-bd8b-dffdefacac0b', '999ac109-d02e-42b7-bfbe-ee768e05e6d5', 'd', 'El orinque es el cabo que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder recuperar el ancla.', false, '2025-09-13 13:53:10.519083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5809d12-5d15-4cad-82c5-ed040a02bb9e', '9817fc9a-3ef9-463b-a359-3bb2e46340dd', 'a', 'Las cornamusas son piezas de hierro, de forma cilíndrica ensanchadas en su parte superior, fijadas en los muelles para hacer firmes las amarras de los barcos.', false, '2025-09-13 13:53:10.519352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e78eb0f9-ffd7-4964-8b31-96fb84172686', '9817fc9a-3ef9-463b-a359-3bb2e46340dd', 'b', 'El chicote es el extremo libre de un cabo y el seno es la costura corta o nudo que se hace a un cabo para formar un ojo o anillo.', false, '2025-09-13 13:53:10.519481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('564aa23c-7cb7-44e6-9065-203c23f17cfd', '9817fc9a-3ef9-463b-a359-3bb2e46340dd', 'c', 'El as de guía es un nudo que permite realizar una gaza no corrediza para encapillar un cabo.', true, '2025-09-13 13:53:10.519611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87e1da01-ddb3-452a-be7f-99af4669e217', '9817fc9a-3ef9-463b-a359-3bb2e46340dd', 'd', 'El ballestrinque es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:10.51974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26f433cd-21da-4c53-bdd2-f4efa9e60881', '75f66ea3-10a7-4ddb-a705-772adacf9223', 'd', 'Limera.', true, '2025-09-13 13:53:10.518394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18b26d43-0e0f-497c-86b1-885b00fc4336', 'c95cae74-abd8-41d9-ada8-e8a790132ec1', 'a', 'Llevar la mar por la proa o amuras con poca arrancada en condiciones de mal tiempo.', true, '2025-09-13 13:53:10.520058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed135515-33f4-42da-b857-b08af331e113', 'c95cae74-abd8-41d9-ada8-e8a790132ec1', 'b', 'Poner proa a la mar y parar la arrancada en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.520223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c9728c8-9018-4c3e-87ae-0bfe4ed5bb88', 'c95cae74-abd8-41d9-ada8-e8a790132ec1', 'c', 'Llevar la mar por popa para evitar los embarques de agua por proa.', false, '2025-09-13 13:53:10.520379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64b4e901-ebf9-435e-a808-6b14352e7972', 'c95cae74-abd8-41d9-ada8-e8a790132ec1', 'd', 'Poner popa a la mar y parar la arrancada en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.520536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6b8e5e8-e8ab-4bbc-ba1f-f54d3e07f388', '43be924e-b2cb-4032-9cfe-1e460c616b26', 'a', 'Maniobrar hasta que la proa haya caído 70º hacia la banda donde ha caído el náufrago y en ese momento meter el timón a la banda contraria hasta navegar a rumbo opuesto a la inicial.', true, '2025-09-13 13:53:10.520859+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69a0d4d6-cf33-4efa-ae9f-344fa4053e8e', '43be924e-b2cb-4032-9cfe-1e460c616b26', 'b', 'Maniobrar hasta que la proa haya caído 70º hacia la banda opuesta a donde ha caído el náufrago y en ese momento meter el timón a la banda contraria hasta navegar a rumbo opuesto a la inicial.', false, '2025-09-13 13:53:10.521016+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb91f191-1e35-41a4-bc6e-fe58dbeb93cc', '43be924e-b2cb-4032-9cfe-1e460c616b26', 'c', 'Meter el timón hacia la banda donde haya caído el náufrago hasta que la proa haya caído 270° y después nos mantenemos a rumbo.', false, '2025-09-13 13:53:10.52117+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9bab1d9-801a-4898-8f2e-dd1003fd9b3b', '43be924e-b2cb-4032-9cfe-1e460c616b26', 'd', 'Meter el timón hacia la banda donde haya caído el náufrago hasta que la proa haya caído 250° y después nos mantenemos a rumbo. El barco seguirá cayendo por inercia hasta lograr los 270°.', false, '2025-09-13 13:53:10.521326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('754801e7-699f-4829-a2c4-5ddfa8417610', '5910187c-8640-4c4e-9f67-814bd5eb0766', 'a', '75 N.', false, '2025-09-13 13:53:10.521659+00');
