INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5c0b306-89b0-4605-a8fa-61a392c42202', 'bd805639-0b98-441b-ba9d-855b93dc1aa5', 'b', 'La cabezada es el movimiento del buque alrededor de su eje transversal, levantando y bajando alternativamente la proa.', false, '2025-09-13 13:53:10.522719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44b7ad53-4ee0-46c2-8dfd-9db6638ec5ed', 'bd805639-0b98-441b-ba9d-855b93dc1aa5', 'd', 'La cabezada se puede romper modificando la velocidad, al modificarse el periodo de cabeceo.', false, '2025-09-13 13:53:10.523022+00');
