INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8dc72cb-b3eb-4ccd-b1f8-c720b41db979', '0363146f-6fce-424e-a9d4-fde0b454c274', 'd', 'Un buque sin gobierno.', true, '2025-09-13 13:53:10.52961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1363b55-57a7-406a-bf99-dafe506e7688', '59e03364-fb9d-4b31-a54f-b3d3d31132c5', 'a', 'Visual y Auditiva, en todo momento.', true, '2025-09-13 13:53:10.52997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05786f4e-9ae9-460a-a86f-2a537517ca30', '59e03364-fb9d-4b31-a54f-b3d3d31132c5', 'b', 'Visual y Auditiva, sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.530126+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16dbf20a-ceb7-4e43-98b1-b2ac2bb3c72f', '1270fe60-a9ff-4a00-b8c2-2b7595cac833', 'b', 'En todo caso, igual que las marcas para ayuda a la navegación, en forma de X, con dos luces blancas.', false, '2025-09-13 13:53:10.524901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8fb0628-cf32-4e65-8209-d7ff0b4b998a', 'eb2e3fcb-77e5-4891-8379-4c143d7afa4d', 'c', 'Todos los buques en alta mar y en todas las aguas que tengan comunicación con ella y sean navegables.', true, '2025-09-13 13:53:10.528639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f35819c-99db-476a-b526-af2d6098925a', '1270fe60-a9ff-4a00-b8c2-2b7595cac833', 'c', 'Ninguna.', false, '2025-09-13 13:53:10.52503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d40bb88-052d-45e5-a7fd-5d9a3e3cb1e6', 'bd805639-0b98-441b-ba9d-855b93dc1aa5', 'c', 'La manera más adecuada de reducir el balance es modificando la velocidad, para evitar la mar de través.', true, '2025-09-13 13:53:10.522855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f35fb58f-8a6a-4963-8de4-88a6d8c16546', 'da079ad1-9be7-41e1-89a4-bc3636dc8790', 'd', 'Al navegante, asociadas al compás de la embarcación, dónde están las aguas navegables.', false, '2025-09-13 13:53:10.528023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('faed8021-b8a8-4cf7-8eed-3433989916c0', '59e03364-fb9d-4b31-a54f-b3d3d31132c5', 'c', 'Visual y Auditiva, sólo si existe algún peligro de abordaje.', false, '2025-09-13 13:53:10.530282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e1a0bd0-7fb3-4f95-8625-8c5d06aa8217', '59e03364-fb9d-4b31-a54f-b3d3d31132c5', 'd', 'Auditiva, cuando no lleve todos los elementos de ayuda a la navegación encendidos.', false, '2025-09-13 13:53:10.530444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e14733b-ec46-4a70-8c54-493a80749e1f', '0e70d255-8b49-4cd3-85c1-cd01ef10f1e3', 'a', 'Un buque sin gobierno.', false, '2025-09-13 13:53:10.530896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79d9a178-7711-4c09-89fa-2e676f4b3b53', '0e70d255-8b49-4cd3-85c1-cd01ef10f1e3', 'b', 'Un buque empujado por otro.', false, '2025-09-13 13:53:10.531033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d57af2b0-6647-49a6-96d7-b002475285c4', '0e70d255-8b49-4cd3-85c1-cd01ef10f1e3', 'c', 'Un buque empujando a otro.', false, '2025-09-13 13:53:10.531166+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3959205d-81f1-491b-8287-928badbab851', '0e70d255-8b49-4cd3-85c1-cd01ef10f1e3', 'd', 'Un buque de propulsión mecánica restringido por su calado.', true, '2025-09-13 13:53:10.531303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d129c939-2966-446a-bc34-b1ea59bd4f50', 'f01e9434-9b1f-4457-a1f4-d5366d88ccc3', 'a', 'Deberán cumplirse de día y en todas las condiciones meteorológicas.', true, '2025-09-13 13:53:10.531582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fecc890e-b605-4880-8893-3962bfd77312', 'f01e9434-9b1f-4457-a1f4-d5366d88ccc3', 'b', 'Son de cumplimiento voluntario.', false, '2025-09-13 13:53:10.531719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f371b913-0f59-4876-8aff-0dc47817fb34', 'f01e9434-9b1f-4457-a1f4-d5366d88ccc3', 'c', 'No son preceptivas debido a que siempre complementan a las Reglas de luces.', false, '2025-09-13 13:53:10.531855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8f1ddfb-ee9f-40dd-8092-22ac2a0739be', 'f01e9434-9b1f-4457-a1f4-d5366d88ccc3', 'd', 'Sólo son obligatorias en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.531992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5d8a275-cf52-4c9c-a951-a7666ab9e37e', 'abb4e265-a945-4d99-be96-a8a5b7675492', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:10.532268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30266c88-0953-46a3-8e34-8c27811d3974', 'abb4e265-a945-4d99-be96-a8a5b7675492', 'b', 'Cada uno de ellos caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:10.532403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f46217ca-6dd4-48f8-a527-71b894f14a8e', 'abb4e265-a945-4d99-be96-a8a5b7675492', 'c', 'Si existe dudas sobre tal situación, se supondrá que no existe.', false, '2025-09-13 13:53:10.532535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59d1a07c-13c6-4db6-8bba-01ee53d4ab49', 'abb4e265-a945-4d99-be96-a8a5b7675492', 'd', 'De noche, verían las luces de costado y la luz de alcance del otro, respectivamente.', false, '2025-09-13 13:53:10.532666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55ff51df-7444-48fb-89ce-023559d3e9f6', '96334ebd-059b-4266-b043-75d2884e8686', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.532941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('432e747d-9b48-4902-aeae-96c897cf8330', '96334ebd-059b-4266-b043-75d2884e8686', 'b', 'Los buques de eslora inferior a 20 metros, los buques de vela y los buques dedicados a la pesca, navegarán libremente dentro de un paso o canal angosto.', false, '2025-09-13 13:53:10.533074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98221c2a-ac97-41ba-9097-1f1630970cfc', '96334ebd-059b-4266-b043-75d2884e8686', 'c', 'Siempre que las circunstancias lo permitan, los buques evitarán fondear en un canal angosto.', true, '2025-09-13 13:53:10.533206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ffee2f8-638d-44f3-b350-9a4c9970c585', '96334ebd-059b-4266-b043-75d2884e8686', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de babor, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.53334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5b6ffc8-1123-445d-8f09-6b2516bd63f4', 'd9510b68-617b-461c-9b47-41be246bd59f', 'a', 'Una luz blanca colocada sobre el eje longitudinal del buque, que muestra su luz sin interrupción en todo un arco de horizonte de 225 grados.', true, '2025-09-13 13:53:10.533739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9119e63-6792-4e18-8529-d2285097bd0b', 'd9510b68-617b-461c-9b47-41be246bd59f', 'b', 'Una luz blanca colocada lo más cerca posible de la popa, que muestra su luz sin interrupción en todo un arco de horizonte de hasta 135 grados.', false, '2025-09-13 13:53:10.533909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f83ab0d-0f73-464c-a37e-33c2e234b195', 'd9510b68-617b-461c-9b47-41be246bd59f', 'c', 'Una luz amarilla colocada lo más cerca posible de la popa, que muestra su luz sin interrupción en todo un arco de horizonte de hasta 135 grados.', false, '2025-09-13 13:53:10.534055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64ac9702-f7b9-4c5d-8412-7f9ee29ebe0d', 'd9510b68-617b-461c-9b47-41be246bd59f', 'd', 'Una luz que es visible sin interrupción en un arco de horizonte de 360 grados.', false, '2025-09-13 13:53:10.534191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('756d8ea7-ff7c-4810-a69c-693f3d16fbca', '2b4d4b62-157f-4ef7-bce0-cb1d421fead3', 'a', 'Una pitada larga.', true, '2025-09-13 13:53:10.534642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0ed12ff-19d3-40db-a145-0e6eee3955fb', '2b4d4b62-157f-4ef7-bce0-cb1d421fead3', 'b', 'Una pitada corta.', false, '2025-09-13 13:53:10.534786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58ced840-5f69-4684-b8cc-f07af3c2d0d7', '2b4d4b62-157f-4ef7-bce0-cb1d421fead3', 'c', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:10.534917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc048809-a172-462d-bd64-a82399a902b9', '2b4d4b62-157f-4ef7-bce0-cb1d421fead3', 'd', 'Cuatro pitadas consecutivas, a saber, una pitada larga seguida de tres cortas.', false, '2025-09-13 13:53:10.535052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bea1fae4-a090-43fa-a26c-8533d0180f97', '21dd4c3f-7918-45fe-b958-d4b8d0fe71e3', 'a', 'Encenderá la luz de alcance intermitentemente para avisar del peligro al otro buque, y mantendrá rumbo y velocidad.', false, '2025-09-13 13:53:10.535326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be0cd961-c513-45f0-885e-9316d232fd70', '21dd4c3f-7918-45fe-b958-d4b8d0fe71e3', 'b', 'Se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:10.535459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e621c914-b4f9-4aaa-ac6f-440b7f264310', '21dd4c3f-7918-45fe-b958-d4b8d0fe71e3', 'c', 'No debe maniobrar en ningún caso, sino que parará máquinas y suprimirá la arrancada hasta que le haya rebasado el otro buque.', false, '2025-09-13 13:53:10.535584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6d97c8b-a738-448e-8d10-92f86bfc8b5d', '21dd4c3f-7918-45fe-b958-d4b8d0fe71e3', 'd', 'Caerá obligatoriamente a estribor de forma que pase por la banda de babor del otro. Maniobra y navegación.', false, '2025-09-13 13:53:10.535713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29996fa5-393b-477d-a11b-a46cec2bd083', '818b3fd1-e635-48a1-8296-c37333232a7e', 'a', 'Dar vueltas al cabrestante para levar las anclas o suspender otras cosas de mucho peso que hay que meter en la embarcación o sacar de ella.', false, '2025-09-13 13:53:10.536001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76ff703a-db28-49c8-a536-6080037ea180', '818b3fd1-e635-48a1-8296-c37333232a7e', 'b', 'Poner tirantes los cabos y cadenas, velas, toldos y cosas semejantes.', true, '2025-09-13 13:53:10.536135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87e70822-c6d9-46bf-a5f7-17b656cb7872', '818b3fd1-e635-48a1-8296-c37333232a7e', 'c', 'Dar igual grado de tensión a varios cables o hacer que empiece a trabajar uno de ellos.', false, '2025-09-13 13:53:10.536264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('686e4b1a-ad2c-4cbb-a094-cf1cc7d83868', '818b3fd1-e635-48a1-8296-c37333232a7e', 'd', 'Soltar o aflojar la escota u otro cabo para disminuir su trabajo.', false, '2025-09-13 13:53:10.536395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9307a307-7451-4d74-8cca-4c543f0d6dd3', '2b05969f-e632-4508-9552-28e03ed9e7c3', 'a', 'Si la hélice es dextrógira la popa caerá a babor.', false, '2025-09-13 13:53:10.536667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b538922-298b-4074-9487-3da4407e883f', '2b05969f-e632-4508-9552-28e03ed9e7c3', 'b', 'Si la hélice es levógira la popa caerá a estribor.', false, '2025-09-13 13:53:10.536806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d83302f-059f-45fc-8038-e0bc494cbed1', '2b05969f-e632-4508-9552-28e03ed9e7c3', 'c', 'Si la hélice es dextrógira la popa caerá a estribor.', true, '2025-09-13 13:53:10.536936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23e3644a-df28-40fb-a930-3aac9bab9bf1', '2b05969f-e632-4508-9552-28e03ed9e7c3', 'd', 'La caída de la popa es independiente del tipo de hélice, dependerá de la banda a la que esté metido el timón. Emergencias en la mar.', false, '2025-09-13 13:53:10.537065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0b441db-4194-4411-8c89-7498dc7aa863', '518f9cdb-4de8-4f84-b36a-1e71c19e3318', 'a', 'Cortar el gas y la energía eléctrica y alejar del fuego todo material inflamable.', false, '2025-09-13 13:53:10.537357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0ca9706-c8b1-4739-a8f8-74d271c7e054', '518f9cdb-4de8-4f84-b36a-1e71c19e3318', 'b', 'Cerrar todas las escotillas, puertas y tomas de aire para no alimentar el fuego.', false, '2025-09-13 13:53:10.537515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3298f0c3-fc12-4fec-8955-03360607fbb2', '518f9cdb-4de8-4f84-b36a-1e71c19e3318', 'd', 'Posicionar la embarcación de forma que el foco principal del incendio quede a barlovento, para evitar la propagación del fuego.', true, '2025-09-13 13:53:10.537807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ca3b446-a6e5-4353-af08-e2a61ae60408', '3ff96ca1-f614-40aa-97ad-81a5b3a9fa86', 'a', 'La asistencia médica de urgencia a distancia es gratuita y se realiza en español e inglés.', false, '2025-09-13 13:53:10.538109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('779fcd25-acfc-44ce-8442-b24df93b8f07', '3ff96ca1-f614-40aa-97ad-81a5b3a9fa86', 'b', 'Se puede contactar directamente por telefonía móvil en el número 91 308 33 02.', false, '2025-09-13 13:53:10.538247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cc9078d-b5d1-431d-b523-031d76df8181', '3ff96ca1-f614-40aa-97ad-81a5b3a9fa86', 'c', 'La asistencia médica está disponible todos los días del año, las 24 horas del día.', true, '2025-09-13 13:53:10.538387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a47b4b7-63b4-4c89-b581-9d2ccaf748c9', '3ff96ca1-f614-40aa-97ad-81a5b3a9fa86', 'd', 'Se recomienda realizar las consultas no urgentes o de control entre las 15:00 y las 20:00 horas (hora de Madrid).', false, '2025-09-13 13:53:10.538516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3721f494-992d-4381-9540-979d6f69a9f2', 'c1e6fd34-d8fb-4e48-bc0d-eeed6209cfc3', 'a', 'Tras una varada involuntaria es primordial tener en cuenta los daños en la obra viva y las posibles vías de agua, a la hora de reflotar la embarcación.', false, '2025-09-13 13:53:10.538906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3e02d11-03f1-4bfb-a20d-81ddab7c3d2f', '4a469d0d-ae25-425d-9a4b-8dfcb734c380', 'd', 'Navegar con poco fondo para no golpearlo.', false, '2025-09-13 13:53:10.551452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca11a589-ab47-41ff-b1d0-e8f57b6768b8', '734b04f2-5b69-4b1b-8c75-b1cf0b5daf3d', 'a', 'Plano de crujía.', false, '2025-09-13 13:53:10.551731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37e55c46-dc5b-4c81-a44f-e6c7d267ac42', 'c1e6fd34-d8fb-4e48-bc0d-eeed6209cfc3', 'c', 'Tras una varada en las rocas lo prioritario es comprobar la distribución de los pesos a bordo, compensando la escora, y dar atrás con el motor.', true, '2025-09-13 13:53:10.539177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b9a43d7-384c-4f9f-814f-b12e29dfdf30', 'c1e6fd34-d8fb-4e48-bc0d-eeed6209cfc3', 'd', 'Si se ha producido una vía de agua cerca de la línea de flotación, es conveniente escorar la embarcación a la banda contraria para reducir la inundación. Meteorología', false, '2025-09-13 13:53:10.539322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c24ed559-ebbe-4ef9-8ff9-6183887dead5', '705a107c-80e1-4d0b-a87b-7fa3f263d3c0', 'a', 'Calmar.', false, '2025-09-13 13:53:10.539602+00');
