INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21f8e2e9-a446-457d-929b-fe6c04c0cf4b', '705a107c-80e1-4d0b-a87b-7fa3f263d3c0', 'd', 'Caer.', false, '2025-09-13 13:53:10.540002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fa8ef91-d230-4587-884f-c158534c88c0', '562bbfed-8b72-4c89-8f7b-00d43bdc50dd', 'a', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:10.540302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cabb810-4fa2-4ddf-add2-8b8639eead88', '562bbfed-8b72-4c89-8f7b-00d43bdc50dd', 'b', 'El aire fluye hacia su interior.', false, '2025-09-13 13:53:10.540446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9805f3ae-d36f-4656-8aff-4b7a9ecd0aaa', '562bbfed-8b72-4c89-8f7b-00d43bdc50dd', 'c', 'El aire desciende en su interior.', true, '2025-09-13 13:53:10.540579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('305a9ff3-0a61-40bb-8076-9c35c1f575bc', '562bbfed-8b72-4c89-8f7b-00d43bdc50dd', 'd', 'El movimiento de aire asociado produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:10.540718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42c2ccf8-dde0-48b2-ba08-719cbe143553', '783b7a11-ab77-4c2c-9ba7-1f4b309fea99', 'a', 'Agencia Estatal de Meteorología (AEMET).', false, '2025-09-13 13:53:10.541001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c869588-fc3e-40bf-a3b7-8dd5c080e0ca', '783b7a11-ab77-4c2c-9ba7-1f4b309fea99', 'b', 'Agencia Mundial de Meteorología (AMMET).', true, '2025-09-13 13:53:10.54114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42bebc42-eec1-4bbd-a134-962458275789', '783b7a11-ab77-4c2c-9ba7-1f4b309fea99', 'c', 'Boletines informativos de Radio Televisión Española (RTVE).', false, '2025-09-13 13:53:10.541278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7db886dd-aa16-4f64-bb6f-b48e0d3d6ce0', '783b7a11-ab77-4c2c-9ba7-1f4b309fea99', 'd', 'Anuncios en redes sociales del Organismo competente del Ministerio para Transición Ecológica y el Reto Demográfico.', false, '2025-09-13 13:53:10.541416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d480b97b-a4e5-40f8-a2ac-99283974e2a2', '3b02456f-3761-48dc-8042-976b58ba5683', 'a', 'Es una tabla admitida internacionalmente con los grados de intensidad de la mar y la altura de ola equivalente.', false, '2025-09-13 13:53:10.541697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf9257dc-799a-4abf-825a-119cf887fe2a', '3b02456f-3761-48dc-8042-976b58ba5683', 'b', 'Clasifica la intensidad del viento siendo 10 el máximo de la escala.', false, '2025-09-13 13:53:10.541848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c6f27c0-40d4-49fc-abbf-6f2dad4c1757', '3b02456f-3761-48dc-8042-976b58ba5683', 'c', 'Es una medida empírica de la intensidad del viento en el medio marino y su escala va de 0 a 12.', true, '2025-09-13 13:53:10.542023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9aa5ba50-634e-400a-b592-0bf3018ecc8b', '6f0590b2-8c01-4e83-99b1-9966c58997ff', 'a', 'Corrección total.', false, '2025-09-13 13:53:10.542534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e28eaee3-2ba2-445e-a893-f5f9bc5a12f5', '6f0590b2-8c01-4e83-99b1-9966c58997ff', 'b', 'Declinación magnética.', true, '2025-09-13 13:53:10.542698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbf21f9f-3ea1-4f98-9e0b-31269b169761', '6f0590b2-8c01-4e83-99b1-9966c58997ff', 'c', 'Ángulo isogónico.', false, '2025-09-13 13:53:10.542862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42707762-3ada-46c1-ada0-94af9d822b12', '6f0590b2-8c01-4e83-99b1-9966c58997ff', 'd', 'Desvío.', false, '2025-09-13 13:53:10.543026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33a298f7-0e69-4013-87a6-f9e946b1a64d', 'fb8650b5-4feb-4e16-a71c-45b9e60bbe1a', 'a', 'El viento actúa sobre la obra viva del barco produciendo una deriva respecto del rumbo.', true, '2025-09-13 13:53:10.543371+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05b1a011-a9e9-4697-a17b-434bb4e626c0', 'fb8650b5-4feb-4e16-a71c-45b9e60bbe1a', 'b', 'La deriva es la desviación de la derrota de una embarcación por efecto de la corriente.', false, '2025-09-13 13:53:10.54353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cffdba4-c70c-4b67-8d19-ef96fe898bab', 'fb8650b5-4feb-4e16-a71c-45b9e60bbe1a', 'c', 'El ángulo entre la línea de crujía y el nuevo rumbo que toma el barco por la acción del viento se llama abatimiento.', false, '2025-09-13 13:53:10.543692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4c353d8-03bd-40f1-924a-c23f67c86c50', 'fb8650b5-4feb-4e16-a71c-45b9e60bbe1a', 'd', 'El abatimiento es positivo si el barco abate a estribor y negativo si abate a babor.', false, '2025-09-13 13:53:10.54386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e52fef6-4b44-4cd2-9cac-791144808612', '2ba6cdcf-98e4-4c07-abd4-ea87a2c1082f', 'a', 'Hay que modificar el rumbo verdadero en el sentido contrario al abatimiento.', true, '2025-09-13 13:53:10.544274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe4a3f69-0dc9-4b48-951e-6fc60815e232', '2ba6cdcf-98e4-4c07-abd4-ea87a2c1082f', 'b', 'Hay que modificar el rumbo verdadero en el sentido del abatimiento.', false, '2025-09-13 13:53:10.544414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0198fdb1-9581-4275-8ed0-fcd2c5227205', '2ba6cdcf-98e4-4c07-abd4-ea87a2c1082f', 'c', 'Hay que modificar el rumbo de superficie sumándole el abatimiento.', false, '2025-09-13 13:53:10.544548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f09fafcd-3f67-4db7-bf72-38456c326e6f', '2ba6cdcf-98e4-4c07-abd4-ea87a2c1082f', 'd', 'Hay que modificar el rumbo hacia la banda contraria por la que viene el viento.', false, '2025-09-13 13:53:10.544684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7c8566b-035c-4ffe-8eee-abca616d6d72', '624cf463-8c2f-4067-b9f0-1087ff648f66', 'a', 'Sufrirá un abatimiento a estribor.', false, '2025-09-13 13:53:10.544957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47aa749f-ae85-441d-b6c4-1e6d55fe83d4', '624cf463-8c2f-4067-b9f0-1087ff648f66', 'b', 'Sufrirá un abatimiento a babor.', false, '2025-09-13 13:53:10.545091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d54f8f9-632e-450a-9ee9-fac967a99b7c', '624cf463-8c2f-4067-b9f0-1087ff648f66', 'c', 'Derivará a estribor.', true, '2025-09-13 13:53:10.545225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('589aaefe-8f36-4180-8bb3-8d24702e5cad', '624cf463-8c2f-4067-b9f0-1087ff648f66', 'd', 'Derivará a babor.', false, '2025-09-13 13:53:10.545359+00');
