INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f62c9fff-32ac-442b-ba41-ad57c70e9f5e', '4a469d0d-ae25-425d-9a4b-8dfcb734c380', 'c', 'Ocupar poco espacio cuando la embarcación está atracada.', false, '2025-09-13 13:53:10.551322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e25e03d-789e-4ef0-892c-2ea79aa492f4', '734b04f2-5b69-4b1b-8c75-b1cf0b5daf3d', 'b', 'Cubierta.', false, '2025-09-13 13:53:10.551878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67979717-c5e0-4bf4-955e-d7da7252b0f8', '3b02456f-3761-48dc-8042-976b58ba5683', 'd', 'Va de 0 a 12, siendo la escala de velocidad del viento decreciente.', false, '2025-09-13 13:53:10.542193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('373549eb-a9e8-4861-b273-6a0a13cf7b30', 'f9a7db31-d6e0-4324-89ea-a1310033184b', 'a', 'Las cornamusas son piezas de hierro, de forma cilíndrica ensanchadas en su parte superior, fijadas en los muelles para hacer firmes las amarras de los barcos.', false, '2025-09-13 13:53:10.552456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5765e060-1b5c-49e6-a840-c6a6994e41de', 'f9a7db31-d6e0-4324-89ea-a1310033184b', 'b', 'El chicote es el extremo libre de un cabo y el seno es la costura corta o nudo que se hace a un cabo para formar un ojo o anillo.', false, '2025-09-13 13:53:10.552588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e5345c5-7a4e-4db9-927f-692f0fc0b330', 'f9a7db31-d6e0-4324-89ea-a1310033184b', 'c', 'El as de guía es un nudo que permite realizar una gaza no corrediza para encapillar un cabo.', true, '2025-09-13 13:53:10.552719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91dbd2c3-5fe0-40f2-8cb4-252a3da8d445', 'f9a7db31-d6e0-4324-89ea-a1310033184b', 'd', 'El ballestrinque es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:10.552857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e343f15d-0fc9-41a6-ba3b-d88920210f2b', 'e938d794-4133-440f-85a4-e37c23215197', 'a', 'Las embarcaciones deben disponer de una línea de fondeo cuya longitud no será inferior a cinco veces la eslora de la embarcación.', false, '2025-09-13 13:53:10.553138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23d6a373-83ee-4a60-b643-27bba8403c82', 'e938d794-4133-440f-85a4-e37c23215197', 'b', 'Para levar el ancla se dará un poco atrás mientras se cobra el elemento de fondeo hasta que el ancla esté a pique y tocando el fondo.', true, '2025-09-13 13:53:10.553268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25e042b6-93c8-4b0d-bf2c-f24f9efbdfa9', 'e938d794-4133-440f-85a4-e37c23215197', 'c', 'A la hora de fondear los mejores tenederos son los de arena fina y compacta, los de arcilla, fango compacto o arena fangosa.', false, '2025-09-13 13:53:10.553624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9500bf4f-40c5-454b-957a-d332ca16bd43', 'e938d794-4133-440f-85a4-e37c23215197', 'd', 'El orinque es el cabo que se anuda a la cruz del ancla por un chicote y a un boyarín por el otro para poder recuperar el ancla.', false, '2025-09-13 13:53:10.553771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95ec6da9-93d9-40b5-8fe0-05d2769ef384', 'cf7c48c8-ade8-4953-8ff6-ca87c49d487e', 'a', 'Maniobrar hasta que la proa haya caído 70º hacia la banda donde ha caído el náufrago y en ese momento meter el timón a la banda contraria hasta navegar a rumbo opuesto a la inicial.', true, '2025-09-13 13:53:10.554094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a100592c-9f31-431b-9662-b5a0aee9d0c0', 'cf7c48c8-ade8-4953-8ff6-ca87c49d487e', 'b', 'Maniobrar hasta que la proa haya caído 70º hacia la banda opuesta a donde ha caído el náufrago y en ese momento meter el timón a la banda contraria hasta navegar a rumbo opuesto a la inicial.', false, '2025-09-13 13:53:10.554233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78711619-255d-4191-a85d-034c35a55543', 'cf7c48c8-ade8-4953-8ff6-ca87c49d487e', 'c', 'Meter el timón hacia la banda donde haya caído el náufrago hasta que la proa haya caído 270° y después nos mantenemos a rumbo.', false, '2025-09-13 13:53:10.554376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ecad5e5-2937-4e08-87e1-b7986e8bc3a9', 'cf7c48c8-ade8-4953-8ff6-ca87c49d487e', 'd', 'Meter el timón hacia la banda donde haya caído el náufrago hasta que la proa haya caído 250° y después nos mantenemos a rumbo. El barco seguirá cayendo por inercia hasta lograr los 270°.', false, '2025-09-13 13:53:10.554513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77a6460e-f166-43af-a536-43a92d6c48b4', 'e8018b78-9a34-4864-a635-844094c0258d', 'a', '75 N.', false, '2025-09-13 13:53:10.554805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e224abf-c306-4058-9308-fcf6c39f2ceb', 'e8018b78-9a34-4864-a635-844094c0258d', 'b', '100 N.', false, '2025-09-13 13:53:10.554944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a817a5d5-31d6-49b1-935b-acbbf8745b71', 'e8018b78-9a34-4864-a635-844094c0258d', 'c', '150 N.', true, '2025-09-13 13:53:10.555091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b779185-830b-4231-8485-48fdec06f615', 'e8018b78-9a34-4864-a635-844094c0258d', 'd', '275 N.', false, '2025-09-13 13:53:10.555231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d300344-6047-41bf-87b7-005a9ce93ddb', '92fb82a3-200f-4121-a5b8-d4a1d3e70068', 'b', 'La cabezada es el movimiento del buque alrededor de su eje transversal, levantando y bajando alternativamente la proa.', false, '2025-09-13 13:53:10.555651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('940f58ef-2d5b-4d51-8aa9-7eb323a6413f', '92fb82a3-200f-4121-a5b8-d4a1d3e70068', 'd', 'La cabezada se puede romper modificando la velocidad, al modificarse el periodo de cabeceo.', false, '2025-09-13 13:53:10.555929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73f4571c-7d2b-49a7-8abc-374ea5e9d2dc', 'f26bad83-e17e-4c48-8a20-03b40e508b65', 'a', 'Llevar la mar por la proa o amuras con poca arrancada en condiciones de mal tiempo.', true, '2025-09-13 13:53:10.556214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cbcf57f-5c9b-4882-800f-755e11e590ca', 'f26bad83-e17e-4c48-8a20-03b40e508b65', 'b', 'Poner proa a la mar y parar la arrancada en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.556349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1910e603-0c86-4330-8a9b-6c8e7e6def36', 'f26bad83-e17e-4c48-8a20-03b40e508b65', 'c', 'Llevar la mar por popa para evitar los embarques de agua por proa.', false, '2025-09-13 13:53:10.556487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('476d7721-c086-430e-961a-3cf055ca5182', 'f26bad83-e17e-4c48-8a20-03b40e508b65', 'd', 'Poner popa a la mar y parar la arrancada en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.556624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48f966f1-631a-45f2-8114-2014ce7abd8a', 'd84978a3-213e-4a58-88d8-a0724e4277f1', 'a', 'A tierra que permita acoplar el conducto de las instalaciones de recepción con el conducto de descarga de la embarcación.', true, '2025-09-13 13:53:10.556904+00');
