INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8dd0be0-ce40-450b-ab9b-f9f301afb6f9', '0238063e-6af5-45f2-89e3-e1896fb57c50', 'c', 'En su zona de navegación asignada en función del equipo de seguridad y de prevención de la contaminación a bordo.', true, '2025-09-13 13:53:10.557977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fd4b870-fd49-4bce-a167-7eb07bb7749b', '0238063e-6af5-45f2-89e3-e1896fb57c50', 'd', 'En su zona de navegación asignada por el fabricante, en función del equipo de propulsión y de', false, '2025-09-13 13:53:10.558107+00');
