INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8856c66-efb9-499f-96a6-20a9d5e09a15', '6387ca57-7995-4b6e-80e6-e3fae97f1a30', 'd', 'Siempre esférica con una luz, si tiene, de color blanco.', false, '2025-09-13 13:53:10.558806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a73e5a0-d89e-4b9e-82b8-7231957a4c99', 'a2622ca2-dadf-4312-ba7c-d1d7b4160157', 'a', 'El navegante deberá consultar la carta para trazar un rumbo seguro.', true, '2025-09-13 13:53:10.560268+00');
