INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e8f9918-c348-43a4-8bf5-1748ef55d949', 'a2622ca2-dadf-4312-ba7c-d1d7b4160157', 'd', 'La dejaremos por babor o estribor, alejándonos una distancia mínima de 50 metros de la marca.', false, '2025-09-13 13:53:10.560791+00');
