INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ad12249-609a-4551-b5f6-d901113e3e9d', '25518a46-01e2-48eb-8304-042c403426ff', 'c', 'Un hidroavión.', false, '2025-09-13 13:53:10.565089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1afbfbe8-a98f-4c28-8bcb-fa6b43269f5d', '25518a46-01e2-48eb-8304-042c403426ff', 'd', 'Un buque sin gobierno.', true, '2025-09-13 13:53:10.565222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b08b4382-258d-4f9a-97e4-2eb5c2732f9b', '7eebcef8-5f25-4b11-8667-95082564fe4e', 'a', 'Visual y Auditiva, en todo momento.', true, '2025-09-13 13:53:10.565546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('078f986a-a91d-4809-b45e-c0da21a88ef0', '7eebcef8-5f25-4b11-8667-95082564fe4e', 'b', 'Visual y Auditiva, sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.565683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88ee1e6a-21fa-40cf-a824-df80a80a7727', '7eebcef8-5f25-4b11-8667-95082564fe4e', 'c', 'Visual y Auditiva, sólo si existe algún peligro de abordaje.', false, '2025-09-13 13:53:10.565814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7c8e50a-d2ab-48ab-9d88-30d0c3a9ecab', '7eebcef8-5f25-4b11-8667-95082564fe4e', 'd', 'Auditiva, cuando no lleve todos los elementos de ayuda a la navegación encendidos.', false, '2025-09-13 13:53:10.565948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfaf8ce4-300e-4820-a2d1-87de23a0a8f7', 'ce82cefd-c218-4efc-81f0-ce120756041e', 'a', 'Encenderá la luz de alcance intermitentemente para avisar del peligro al otro buque, y mantendrá rumbo y velocidad.', false, '2025-09-13 13:53:10.566227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a968e351-15e7-4cf9-9e19-bed6624d3873', 'ce82cefd-c218-4efc-81f0-ce120756041e', 'b', 'Se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:10.566357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f6384f3-83e7-41d5-a17f-e313a4ba0956', 'ce82cefd-c218-4efc-81f0-ce120756041e', 'c', 'No debe maniobrar en ningún caso, sino que parará máquinas y suprimirá la arrancada hasta que le haya rebasado el otro buque.', false, '2025-09-13 13:53:10.566489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f335d9ef-44c9-4486-b393-22c6a88988b5', 'ce82cefd-c218-4efc-81f0-ce120756041e', 'd', 'Caerá obligatoriamente a estribor de forma que pase por la banda de babor del otro.', false, '2025-09-13 13:53:10.566622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14dd145a-f122-4ab0-acf6-efc480620d8b', 'ceaa38d7-efd9-418d-abb4-fb8bf00bee0d', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.566923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('892ea8a8-10c4-44c0-8dd6-bd57a21e5be1', 'ceaa38d7-efd9-418d-abb4-fb8bf00bee0d', 'b', 'Los buques de eslora inferior a 20 metros, los buques de vela y los buques dedicados a la pesca, navegarán libremente dentro de un paso o canal angosto.', false, '2025-09-13 13:53:10.567053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb9d1ac1-1140-4d43-9226-71b5b2616200', 'ceaa38d7-efd9-418d-abb4-fb8bf00bee0d', 'c', 'Siempre que las circunstancias lo permitan, los buques evitarán fondear en un canal angosto.', true, '2025-09-13 13:53:10.567187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bfac336-24a4-4242-84a6-0ebe0fa1e892', 'ceaa38d7-efd9-418d-abb4-fb8bf00bee0d', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de babor, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:10.567318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b117b02e-1be8-4adf-beab-601f7e9c67f3', '62d0be13-5e98-4c1e-9f81-65b74121f954', 'a', 'Una pitada larga.', true, '2025-09-13 13:53:10.567604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff635856-d197-45c5-a1cf-1592aef3401e', '62d0be13-5e98-4c1e-9f81-65b74121f954', 'b', 'Una pitada corta.', false, '2025-09-13 13:53:10.567735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dbdbfaf-c933-4341-b166-73b9041ae678', '62d0be13-5e98-4c1e-9f81-65b74121f954', 'c', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:10.567871+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e1511db-b336-432c-9378-3df2daf2832a', '62d0be13-5e98-4c1e-9f81-65b74121f954', 'd', 'Cuatro pitadas consecutivas, a saber, una pitada larga seguida de tres cortas.', false, '2025-09-13 13:53:10.56801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dcff239-0243-4a58-bf48-6c8964c43778', '6033e1b6-27df-413d-88a2-86c83e1cf8c6', 'a', 'Una luz blanca colocada sobre el eje longitudinal del buque, que muestra su luz sin interrupción en todo un arco de horizonte de 225 grados.', true, '2025-09-13 13:53:10.568286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b962b4bf-ddf9-461c-867e-5af23dabc87b', '6033e1b6-27df-413d-88a2-86c83e1cf8c6', 'b', 'Una luz blanca colocada lo más cerca posible de la popa, que muestra su luz sin interrupción en todo un arco de horizonte de hasta 135 grados.', false, '2025-09-13 13:53:10.568417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d54dcb58-aba8-498d-9bc5-6455d3396c46', '6033e1b6-27df-413d-88a2-86c83e1cf8c6', 'c', 'Una luz amarilla colocada lo más cerca posible de la popa, que muestra su luz sin interrupción en todo un arco de horizonte de hasta 135 grados.', false, '2025-09-13 13:53:10.568548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9742508c-3eb4-4622-a7e6-68d5c953f1b2', '6033e1b6-27df-413d-88a2-86c83e1cf8c6', 'd', 'Una luz que es visible sin interrupción en un arco de horizonte de 360 grados.', false, '2025-09-13 13:53:10.568679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('711682f1-61ac-469a-b77e-3c6c75f7c05d', '4a514149-b73e-4a41-bed9-f3806ca1e4bb', 'a', 'Deberán cumplirse de día y en todas las condiciones meteorológicas.', true, '2025-09-13 13:53:10.569097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba9b15be-e57a-4df8-ab48-0b3bf6e86713', '4a514149-b73e-4a41-bed9-f3806ca1e4bb', 'b', 'Son de cumplimiento voluntario.', false, '2025-09-13 13:53:10.569227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17373642-ed3b-468c-81ba-92fdce97d083', '4a514149-b73e-4a41-bed9-f3806ca1e4bb', 'c', 'No son preceptivas debido a que siempre complementan a las Reglas de luces.', false, '2025-09-13 13:53:10.56936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f417b97-f736-44a2-ba85-0f98ed9caaf2', '4a514149-b73e-4a41-bed9-f3806ca1e4bb', 'd', 'Sólo son obligatorias en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.569495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50665880-7fcb-4193-8922-d73212561e65', '747a7b4e-b8b2-4eed-b5dc-713139ad2fc6', 'a', 'Un buque sin gobierno.', false, '2025-09-13 13:53:10.569767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcc630d5-081d-4776-95c2-d5fe1994c251', '747a7b4e-b8b2-4eed-b5dc-713139ad2fc6', 'b', 'Un buque empujado por otro.', false, '2025-09-13 13:53:10.569901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1abb7a0b-5a09-47ee-b2e1-bd1a7e5683c8', '747a7b4e-b8b2-4eed-b5dc-713139ad2fc6', 'c', 'Un buque empujando a otro.', false, '2025-09-13 13:53:10.570031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('829e35bc-8209-41be-bcdd-1e1a00005945', '0b8d5c83-e1b5-44ce-9931-3e998c06a41b', 'a', 'Dar vueltas al cabrestante para levar las anclas o suspender otras cosas de mucho peso que hay que meter en la embarcación o sacar de ella.', false, '2025-09-13 13:53:10.570451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74caa5c1-787e-434b-b716-1b33e6744ebe', '0b8d5c83-e1b5-44ce-9931-3e998c06a41b', 'b', 'Poner tirantes los cabos y cadenas, velas, toldos y cosas semejantes.', true, '2025-09-13 13:53:10.570582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16379015-fe21-4e14-a6e0-2dfaf5116cdf', '0b8d5c83-e1b5-44ce-9931-3e998c06a41b', 'c', 'Dar igual grado de tensión a varios cables o hacer que empiece a trabajar uno de ellos.', false, '2025-09-13 13:53:10.570715+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a912b79c-671f-45d3-a90d-cf7e686b3758', '0b8d5c83-e1b5-44ce-9931-3e998c06a41b', 'd', 'Soltar o aflojar la escota u otro cabo para disminuir su trabajo.', false, '2025-09-13 13:53:10.570851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbcca353-f1ea-4cb1-8ffd-790c97386990', 'a11d0d19-d590-458c-a138-9835c369668c', 'a', 'Si la hélice es dextrógira la popa caerá a babor.', false, '2025-09-13 13:53:10.571124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2a6075c-cf64-4b6c-9247-66867298ecf7', 'a11d0d19-d590-458c-a138-9835c369668c', 'b', 'Si la hélice es levógira la popa caerá a estribor.', false, '2025-09-13 13:53:10.571254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20d4b128-5a0d-4fc6-b83c-18e822fd0511', 'a11d0d19-d590-458c-a138-9835c369668c', 'c', 'Si la hélice es dextrógira la popa caerá a estribor.', true, '2025-09-13 13:53:10.571386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba155e55-aab8-4db4-99d2-d886ef5cbaed', 'a11d0d19-d590-458c-a138-9835c369668c', 'd', 'La caída de la popa es independiente del tipo de hélice, dependerá de la banda a la que esté metido el timón. Emergencias en la mar.', false, '2025-09-13 13:53:10.571516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ffa81fd-61f4-4e73-bf58-f06a57de3d94', '5184d337-d86c-4f34-bd83-481df1c8aa7e', 'a', 'Tras una varada involuntaria es primordial tener en cuenta los daños en la obra viva y las posibles vías de agua, a la hora de reflotar la embarcación.', false, '2025-09-13 13:53:10.571791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('972b5b04-308b-42f0-bd47-7fe075840b6c', '51731ffc-ca95-40c7-a9b8-b3440038ad8e', 'd', 'Al navegante, asociadas al compás de la embarcación, dónde están las aguas navegables.', false, '2025-09-13 13:53:10.562933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('697c0d8f-4780-4751-9a47-9695c59b50fc', '747a7b4e-b8b2-4eed-b5dc-713139ad2fc6', 'd', 'Un buque de propulsión mecánica restringido por su calado.', true, '2025-09-13 13:53:10.570162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c7b1a05-79eb-4c69-ad8c-138fefaeebfd', '5184d337-d86c-4f34-bd83-481df1c8aa7e', 'c', 'Tras una varada en las rocas lo prioritario es comprobar la distribución de los pesos a bordo, compensando la escora, y dar atrás con el motor.', true, '2025-09-13 13:53:10.572073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1310b6bc-168a-40dc-b31e-cdfe50d7c7af', '5184d337-d86c-4f34-bd83-481df1c8aa7e', 'd', 'Si se ha producido una vía de agua cerca de la línea de flotación, es conveniente escorar la embarcación a la banda contraria para reducir la inundación.', false, '2025-09-13 13:53:10.572204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efa1f41a-6d80-4a0b-a93d-543e6e677a14', 'e28c94b3-4085-4864-89ed-41059cb9181c', 'a', 'La asistencia médica de urgencia a distancia es gratuita y se realiza en español e inglés.', false, '2025-09-13 13:53:10.572478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73196985-c3b8-487e-b56e-f2421e5b64cd', 'e28c94b3-4085-4864-89ed-41059cb9181c', 'b', 'Se puede contactar directamente por telefonía móvil en el número 91 308 33 02.', false, '2025-09-13 13:53:10.572608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8185b1c5-80a2-4f2f-b161-6be66f8f1e9b', 'e28c94b3-4085-4864-89ed-41059cb9181c', 'c', 'La asistencia médica está disponible todos los días del año, las 24 horas del día.', true, '2025-09-13 13:53:10.572744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('432e3880-d32d-4cce-b296-7a8c08fc92d7', 'e28c94b3-4085-4864-89ed-41059cb9181c', 'd', 'Se recomienda realizar las consultas no urgentes o de control entre las 15:00 y las 20:00 horas (hora de Madrid).', false, '2025-09-13 13:53:10.572888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4239b7aa-1c82-462e-84d5-03d3a97cb679', 'e59b23c1-b025-4f8a-a199-956bd761c241', 'a', 'Cortar el gas y la energía eléctrica y alejar del fuego todo material inflamable.', false, '2025-09-13 13:53:10.573159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8a4209e-f362-44ba-8fb3-2d91ee595aba', 'e59b23c1-b025-4f8a-a199-956bd761c241', 'b', 'Cerrar todas las escotillas, puertas y tomas de aire para no alimentar el fuego.', false, '2025-09-13 13:53:10.573289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ae7b1d4-6aaf-4e5c-9833-d898f99cdc12', 'e59b23c1-b025-4f8a-a199-956bd761c241', 'd', 'Posicionar la embarcación de forma que el foco principal del incendio a quede a barlovento, para evitar la propagación del fuego. Meteorología', true, '2025-09-13 13:53:10.573548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29498714-260f-4324-98dd-fe24a1bc91dc', '87738a3b-56ab-4ed9-889c-4a93a139f545', 'a', 'Agencia Estatal de Meteorología (AEMET).', false, '2025-09-13 13:53:10.573957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdb121a6-f2c8-45ba-81f7-31c5263a21e2', '87738a3b-56ab-4ed9-889c-4a93a139f545', 'b', 'Agencia Mundial de Meteorología (AMMET).', true, '2025-09-13 13:53:10.574087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c13d78be-fa58-45ab-ba4c-28ab3ed1c998', '87738a3b-56ab-4ed9-889c-4a93a139f545', 'c', 'Boletines informativos de Radio Televisión Española (RTVE).', false, '2025-09-13 13:53:10.574217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1734e73a-fe41-4355-8b24-d2e1665df1fa', '87738a3b-56ab-4ed9-889c-4a93a139f545', 'd', 'Anuncios en redes sociales del Organismo competente del Ministerio para Transición Ecológica y el Reto Demográfico.', false, '2025-09-13 13:53:10.574372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec61347d-20d6-44e1-b1dc-822ba68647c5', 'fa322ac5-ac71-47ef-b9fc-908d87ca7349', 'a', 'Calmar.', false, '2025-09-13 13:53:10.574666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53fc9d0a-9358-4841-9dcf-588fa771278f', 'fa322ac5-ac71-47ef-b9fc-908d87ca7349', 'b', 'Refrescar.', false, '2025-09-13 13:53:10.574808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc175827-fcc3-4d25-a0e6-7f77c9f9edab', 'fa322ac5-ac71-47ef-b9fc-908d87ca7349', 'c', 'Rolar.', true, '2025-09-13 13:53:10.574956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0e9a40f-42e8-4971-98a0-06da729edfae', 'fa322ac5-ac71-47ef-b9fc-908d87ca7349', 'd', 'Caer.', false, '2025-09-13 13:53:10.575096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1afd00c6-b448-4596-915d-ab5f3ddba547', 'a80391ae-6070-41cb-95e0-c80a40d80560', 'a', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:10.575385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff535d4b-14ab-4ea6-802e-34db8a637d5f', 'a80391ae-6070-41cb-95e0-c80a40d80560', 'b', 'El aire fluye hacia su interior.', false, '2025-09-13 13:53:10.575525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bcf50cf-c4fe-4a97-b7cb-2fe15e4c43c5', 'a80391ae-6070-41cb-95e0-c80a40d80560', 'c', 'El aire desciende en su interior.', true, '2025-09-13 13:53:10.575656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('610f75d2-1a7f-4831-9d1c-bf268580c0fd', 'a80391ae-6070-41cb-95e0-c80a40d80560', 'd', 'El movimiento de aire asociado produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:10.575786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78721005-2c49-43fa-94fc-8f0e8190e548', '2f5cb66e-3df5-45cc-9f9d-ed4cd4d83e33', 'a', 'Es una tabla admitida internacionalmente con los grados de intensidad de la mar y la altura de ola equivalente.', false, '2025-09-13 13:53:10.576072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8b4a3ce-ca8f-4c1c-98ac-9ff657d04c8a', '2f5cb66e-3df5-45cc-9f9d-ed4cd4d83e33', 'b', 'Clasifica la intensidad del viento siendo 10 el máximo de la escala.', false, '2025-09-13 13:53:10.576207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2111ef72-ffeb-45b5-b052-612f291048ad', '2f5cb66e-3df5-45cc-9f9d-ed4cd4d83e33', 'c', 'Es una medida empírica de la intensidad del viento en el medio marino y su escala va de 0 a 12.', true, '2025-09-13 13:53:10.576344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d99d8833-e41e-4c63-b8a7-d0932b9424f9', 'bc948799-f763-4720-98b3-aeffb677b70e', 'a', 'Corrección total.', false, '2025-09-13 13:53:10.576765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b966ee37-e6bd-4597-a400-b8582aaf5254', 'bc948799-f763-4720-98b3-aeffb677b70e', 'b', 'Declinación magnética.', true, '2025-09-13 13:53:10.576901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccf572f7-ace4-4a95-9d3a-d3913dedbeb2', 'bc948799-f763-4720-98b3-aeffb677b70e', 'c', 'Ángulo isogónico.', false, '2025-09-13 13:53:10.577037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1b28238-d656-4851-8b86-3fa057204826', 'bc948799-f763-4720-98b3-aeffb677b70e', 'd', 'Desvío.', false, '2025-09-13 13:53:10.57717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('936a2df0-4d3a-48b4-ab00-3ae3e5309f47', 'e3148735-088a-47a1-a581-421b00583d56', 'a', 'Hay que modificar el rumbo verdadero en el sentido contrario al abatimiento.', true, '2025-09-13 13:53:10.577445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1e9095f-5a97-4734-aa0b-6a72555de1a7', 'e3148735-088a-47a1-a581-421b00583d56', 'b', 'Hay que modificar el rumbo verdadero en el sentido del abatimiento.', false, '2025-09-13 13:53:10.577577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74f33ad6-b793-433a-827a-32d5105b428a', 'e3148735-088a-47a1-a581-421b00583d56', 'c', 'Hay que modificar el rumbo de superficie sumándole el abatimiento.', false, '2025-09-13 13:53:10.577729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c3f438b-d76e-45a8-811f-d2919874a79c', 'e3148735-088a-47a1-a581-421b00583d56', 'd', 'Hay que modificar el rumbo hacia la banda contraria por la que viene el viento.', false, '2025-09-13 13:53:10.578012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97714e62-e2ce-4c68-886e-e1a127815163', '41b0ce55-8b67-4ab7-a9af-00d4952d8acf', 'a', 'El viento actúa sobre la obra viva del barco produciendo una deriva respecto del rumbo.', true, '2025-09-13 13:53:10.578315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bf2b17a-dfb4-4b4d-8268-3fd7509b32f7', '41b0ce55-8b67-4ab7-a9af-00d4952d8acf', 'b', 'La deriva es la desviación de la derrota de una embarcación por efecto de la corriente.', false, '2025-09-13 13:53:10.578453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37eabe44-f2e9-4ba4-b3e5-f12c97c92c30', '41b0ce55-8b67-4ab7-a9af-00d4952d8acf', 'c', 'El ángulo entre la línea de crujía y el nuevo rumbo que toma el barco por la acción del viento se llama abatimiento.', false, '2025-09-13 13:53:10.578591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1ab2b98-cb15-40ba-9521-f6b7b21a1bba', '41b0ce55-8b67-4ab7-a9af-00d4952d8acf', 'd', 'El abatimiento es positivo si el barco abate a estribor y negativo si abate a babor.', false, '2025-09-13 13:53:10.578725+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8f0bd61-fd6e-4445-8832-489886654a29', '563ba5e5-b04f-47c0-9f06-6a954f8da17d', 'a', 'Sufrirá un abatimiento a estribor.', false, '2025-09-13 13:53:10.579002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68b45563-e14b-4331-865a-428510cad6e1', '563ba5e5-b04f-47c0-9f06-6a954f8da17d', 'b', 'Sufrirá un abatimiento a babor.', false, '2025-09-13 13:53:10.579135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6707c6c1-86ab-408d-89db-2b528babffdc', '563ba5e5-b04f-47c0-9f06-6a954f8da17d', 'c', 'Derivará a estribor.', true, '2025-09-13 13:53:10.579289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7db01543-8961-408a-9472-5a6281c7246e', '563ba5e5-b04f-47c0-9f06-6a954f8da17d', 'd', 'Derivará a babor.', false, '2025-09-13 13:53:10.579422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4a00b34-8e9c-407c-b5a1-fe47d03f3d8b', 'c50fab6d-2666-4ba0-82dd-d721f7733118', 'a', 'Un minuto de arco de ecuador.', true, '2025-09-13 13:53:10.579698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de348218-75e9-4eaf-9a1b-f1a350a62012', 'c50fab6d-2666-4ba0-82dd-d721f7733118', 'b', 'Un minuto de longitud.', false, '2025-09-13 13:53:10.579833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d295a306-0484-42cb-be48-ee1ff89680ad', 'c50fab6d-2666-4ba0-82dd-d721f7733118', 'c', 'Un minuto de latitud.', false, '2025-09-13 13:53:10.579965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32be8ec2-61f0-49a5-9977-b9aee1441863', 'c50fab6d-2666-4ba0-82dd-d721f7733118', 'd', 'Un minuto de arco de paralelo. Carta de navegación.', false, '2025-09-13 13:53:10.580096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2a5d801-cf68-406b-a325-f4ff96aa1ad9', '50a2730e-7437-4f76-9b2d-5a82eb61b2b8', 'a', 'Es el pico más alto de la Sierra de la Plata, dentro del parque natural del Estrecho, cerca de la Ensenada de Bolonia.', true, '2025-09-13 13:53:10.580373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6ee1d0d-2752-4f22-8750-efa0fb8f4875', '50a2730e-7437-4f76-9b2d-5a82eb61b2b8', 'b', 'Es un faro.', false, '2025-09-13 13:53:10.580508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36408d19-f528-4181-8496-dd93fc8bd716', '50a2730e-7437-4f76-9b2d-5a82eb61b2b8', 'c', 'Se trata de la Torre de Gracia.', false, '2025-09-13 13:53:10.580641+00');
