INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89f2a922-5864-4e32-b9b8-c31252867123', '78350434-2ca4-44a9-b23c-9591ee37bb6f', 'a', '35° 59,6´N 005° 53,4´W.', true, '2025-09-13 13:53:10.582457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9802153-811c-4587-881d-9821378c868d', '78350434-2ca4-44a9-b23c-9591ee37bb6f', 'b', '36° 01,6´N 005° 50,2´W.', false, '2025-09-13 13:53:10.58259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13032eaa-2918-44f8-9d15-96c6a1833509', '78350434-2ca4-44a9-b23c-9591ee37bb6f', 'c', '36° 02,8´N 005° 50,8´W.', false, '2025-09-13 13:53:10.582722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4d54721-7ebc-49d1-90e3-2b7cbc020d45', '2f5cb66e-3df5-45cc-9f9d-ed4cd4d83e33', 'd', 'Va de 0 a 12, siendo la escala de velocidad del viento decreciente.', false, '2025-09-13 13:53:10.576481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41ca7ce3-837f-4b8a-ad2c-422099cab05c', 'e59b23c1-b025-4f8a-a199-956bd761c241', 'c', 'Luchar contra el fuego con extintores apropiados al tipo de incendio, atacando la base del fuego, no las llamas.', false, '2025-09-13 13:53:10.573419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad38536e-dd69-4002-89a6-311c2b683d0e', '78350434-2ca4-44a9-b23c-9591ee37bb6f', 'd', '35° 59,4´N 005° 55,3´W. DE TRANSPORTES, MOVILIDAD                                                                           DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                     Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 03 Nomenclatura náutica.', false, '2025-09-13 13:53:10.582851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b99d0729-45d2-4ecd-b010-a1c5a07c0574', '229c2c18-ca2c-44dd-9683-2f67a16d1d9a', 'a', 'Los manguerotes.', false, '2025-09-13 13:53:10.583401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('caa8e611-feed-4a11-955f-1f660c27f6cd', '229c2c18-ca2c-44dd-9683-2f67a16d1d9a', 'b', 'Los grifos de fondo.', true, '2025-09-13 13:53:10.583529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4150a67-5871-4d78-b796-5496d2e19943', '229c2c18-ca2c-44dd-9683-2f67a16d1d9a', 'c', 'Los imbornales.', false, '2025-09-13 13:53:10.583656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c1975e8-5c15-45fe-9055-7c7c335c2f24', '229c2c18-ca2c-44dd-9683-2f67a16d1d9a', 'd', 'Los desagües.', false, '2025-09-13 13:53:10.583787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca160cab-2d98-42f1-b0f3-91c40dad436e', '60e244a6-96e4-4d93-82cf-d081e206fef3', 'a', 'Incide por sotavento.', false, '2025-09-13 13:53:10.584064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb9b3d03-6286-4003-b78e-4ff46ea7d9dc', '60e244a6-96e4-4d93-82cf-d081e206fef3', 'b', 'Ejerce su presión solamente sobre las velas y es lo que hace que la embarcación avance.', false, '2025-09-13 13:53:10.584195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6bdc63b-9ef1-4674-8731-0187b5553c2a', '60e244a6-96e4-4d93-82cf-d081e206fef3', 'c', 'Ejerce su presión sobre la obra muerta.', true, '2025-09-13 13:53:10.584324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd9ca41c-4712-4874-bdda-f0eecff7d034', '60e244a6-96e4-4d93-82cf-d081e206fef3', 'd', 'Ejerce su presión sobre la obra viva de la embarcación.', false, '2025-09-13 13:53:10.584451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e86175ad-3092-4b68-9385-db5e20a3ba12', '7cd483da-aa18-4d16-bff8-67db03f3c607', 'a', 'La anchura del casco en su proyección horizontal y medida a la cara exterior del forro.', true, '2025-09-13 13:53:10.584723+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da2ed233-f83c-460c-bcf4-4e4ab47bd4d6', '7cd483da-aa18-4d16-bff8-67db03f3c607', 'b', 'La distancia medida paralelamente a la línea de flotación y al eje de la embarcación, entre dos planos verticales perpendiculares al plano central de la embarcación situados uno en la parte más a proa y el otro en la parte más a popa.', false, '2025-09-13 13:53:10.584854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b276f0b-6718-480c-a9c2-b92e22b4b0dd', '7cd483da-aa18-4d16-bff8-67db03f3c607', 'c', 'La distancia vertical medida a la mitad de la eslora desde la cara superior de la línea de cubierta hasta el canto superior de la quilla.', false, '2025-09-13 13:53:10.584983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('211c28f0-11fb-460e-9f91-e1b9886de09f', '7cd483da-aa18-4d16-bff8-67db03f3c607', 'd', 'La altura medida sobre el costado de la embarcación desde la línea de flotación, en su condición de máxima carga, hasta la cubierta estanca más alta.', false, '2025-09-13 13:53:10.585111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a6dafc8-fa8a-44fd-8173-95a6c1d46187', 'fda04ee1-332f-4e3f-a835-e94896e2fb64', 'a', 'Molinete.', false, '2025-09-13 13:53:10.58538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb24fddd-20d3-4715-9598-f4de2bbf64f8', 'fda04ee1-332f-4e3f-a835-e94896e2fb64', 'b', 'Barbotén.', true, '2025-09-13 13:53:10.585516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfb196cf-3f5b-4ebc-9640-827f56bedd94', 'fda04ee1-332f-4e3f-a835-e94896e2fb64', 'c', 'Chigre.', false, '2025-09-13 13:53:10.585652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('962b89cc-9c9e-47aa-9dfa-0d5624f00308', '6019f67d-3727-4343-8e93-cf1a56ba9332', 'a', 'Las boyas son piezas que se colocan en el costado de la embarcación para evitar que se dañe cuando está atracada.', false, '2025-09-13 13:53:10.586053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cce8aac0-4223-4b51-acc7-dc7a9938a762', '6019f67d-3727-4343-8e93-cf1a56ba9332', 'b', 'El guía-cabos es una rueda acanalada por donde corre el cabo en un motón.', false, '2025-09-13 13:53:10.586184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f492e110-42f2-470c-9029-c2c1d3924ac7', '6019f67d-3727-4343-8e93-cf1a56ba9332', 'c', 'El nudo llano permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:10.586312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5748d31b-8171-4e66-a02e-b4dbc2e7e8ef', '6019f67d-3727-4343-8e93-cf1a56ba9332', 'd', 'El bichero es un palo largo con un gancho y punta en uno de sus extremos, que se utiliza para coger la guía o las amarras.', true, '2025-09-13 13:53:10.586439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e331926d-34ce-4e2f-bc8c-2e417daf3c13', '1d0470e2-f225-42ce-bd37-366d84b9dfab', 'a', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear un segundo ancla o aguantar con máquina avante.', true, '2025-09-13 13:53:10.586716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8189238-d90f-4cde-aa6f-868e73f18539', '1d0470e2-f225-42ce-bd37-366d84b9dfab', 'b', 'Durante el fondeo, solo se precisa vigilar la sonda, marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:10.586858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f1a9395-386b-426a-822b-4a6b2c697ddd', '1d0470e2-f225-42ce-bd37-366d84b9dfab', 'c', 'El circulo de borneo lo describe el centro de gravedad de la embarcación y tiene como radio la cadena más la mitad de la eslora.', false, '2025-09-13 13:53:10.58699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e9f8011-eb56-42cd-9c44-67a15c18d51c', '1d0470e2-f225-42ce-bd37-366d84b9dfab', 'd', 'Un barco fondea a la gira cuando utiliza dos anclas, cuyas líneas de fondeo forman un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:10.58712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a3c0e42-daf9-436e-b4d9-51019be2a94d', '4d796745-5e69-4566-8b97-0aed3e9c5d48', 'a', 'Si tiene una instalación eléctrica de más de 50 voltios, uno de los extintores debe ser adecuado para riesgo eléctrico.', false, '2025-09-13 13:53:10.587385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c808641a-e002-4ad4-bea6-f4055f700aa0', '4d796745-5e69-4566-8b97-0aed3e9c5d48', 'b', 'Si se dedica a fines comerciales o lucrativos llevará un extintor adicional al que tiene que llevar reglamentariamente.', false, '2025-09-13 13:53:10.587516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29b8ac5c-4aa4-4468-a7c9-68df2d3c913b', '4d796745-5e69-4566-8b97-0aed3e9c5d48', 'c', 'Aunque lleve instalados un sistema fijo de contraincendios debe llevar al menos un extintor.', false, '2025-09-13 13:53:10.587646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7ab3015-5e61-4462-9b62-4edcd5e36508', '4d796745-5e69-4566-8b97-0aed3e9c5d48', 'd', 'Llevará al menos un extintor y todos ellos se estibarán en una zona de fácil acceso y alejada del puesto principal de gobierno de la embarcación.', true, '2025-09-13 13:53:10.587909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3f27014-d43e-4cd4-8407-bc565a6ee31d', '73af0618-6653-47b4-8936-ff89227cee81', 'a', 'A correr el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.588184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ef9c293-7b28-41e9-bbc8-c65bd1ac079c', '73af0618-6653-47b4-8936-ff89227cee81', 'b', 'A capear el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.588316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05536c4d-1502-4be5-8d1b-d84198a16682', '73af0618-6653-47b4-8936-ff89227cee81', 'c', 'A navegar con la proa a la mar para evitar el vuelco del barco en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.588445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('479b50d9-2a4c-49fd-a7e9-22ff8bfd4af8', '73af0618-6653-47b4-8936-ff89227cee81', 'd', 'A la estiba y trinca más adecuadas a bordo de los objetos, carga, aparejos, etc., para que no se muevan durante condiciones de mal tiempo.', true, '2025-09-13 13:53:10.588584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ea89e54-7e12-4a3a-bad3-c93a6159d985', '8aa85990-c40f-4d27-8d61-64e939992c13', 'a', 'Evitar nadar y mantener una posición fetal en el agua con el chaleco salvavidas puesto.', false, '2025-09-13 13:53:10.588855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dc14263-f7c7-44b5-9dbc-0daa7aae212b', '8aa85990-c40f-4d27-8d61-64e939992c13', 'b', 'Abrigar al afectado a resguardo del viento.', false, '2025-09-13 13:53:10.588995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b48d3f7-f1b5-4969-86e3-b5fff5e8f1cf', '8aa85990-c40f-4d27-8d61-64e939992c13', 'c', 'Mantener al afectado con la ropa puesta y frotar enérgicamente para que entre en calor.', true, '2025-09-13 13:53:10.589127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd0d8d1c-06b9-4c7f-a4bd-a7f2e5acdac5', '8aa85990-c40f-4d27-8d61-64e939992c13', 'd', 'Trasladar al afectado en posición horizontal.', false, '2025-09-13 13:53:10.589254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('061c7596-2305-4a8a-b3cf-e29ad670469e', '6906570b-8a07-462d-b853-8165b9e46ecf', 'a', '091.', false, '2025-09-13 13:53:10.589521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ed95b9c-3420-452e-a467-1c44daaf0e53', '6906570b-8a07-462d-b853-8165b9e46ecf', 'b', '900 112 112.', false, '2025-09-13 13:53:10.589653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7066d225-239b-4fbf-aef0-f5a576cee7e3', '6906570b-8a07-462d-b853-8165b9e46ecf', 'c', '900 102 102.', false, '2025-09-13 13:53:10.589789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39fed28f-73fb-40b0-b374-f5db054920bb', '6906570b-8a07-462d-b853-8165b9e46ecf', 'd', '900 202 202.', true, '2025-09-13 13:53:10.589918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('287b1e5c-ac4c-461d-bf00-7bd7cac53165', '52cf71ba-d869-4e40-9fb3-4e07f620dfd7', 'd', 'Está obligado a informar de ello a las personas en peligro en el mar y a mantener contacto con ellos, a intervalos de no más de 3 horas, hasta que llegue al lugar otro buque y considere que el auxilio ya no es necesario.', false, '2025-09-13 13:53:10.590627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5adfb1a8-baae-4f0b-bc58-4367b97d1332', '3764238b-699b-426c-a825-4894b7c8c6c6', 'a', 'A una distancia inferior a 3 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.590938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff9909a8-7a85-4e77-8985-4e3a83c5923b', '3764238b-699b-426c-a825-4894b7c8c6c6', 'b', 'Dentro de zona 7, utilizando una instalación de tratamiento de aguas sucias, y que el efluente produzca sólidos flotantes visibles y ocasione coloración en las aguas circundantes.', false, '2025-09-13 13:53:10.591074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c34bcdd9-01d0-4c67-bc43-a6462371f62f', 'fda04ee1-332f-4e3f-a835-e94896e2fb64', 'd', 'Grillete.', false, '2025-09-13 13:53:10.585783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de332c8c-72be-478a-945c-31dd189bf4e2', '52cf71ba-d869-4e40-9fb3-4e07f620dfd7', 'b', 'Anotará en el diario de navegación la razón por la cual no acudió en auxilio de las personas en peligro.', true, '2025-09-13 13:53:10.59033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fab94b1-ee0a-4d0a-9e4d-67aeb0d7011e', '3764238b-699b-426c-a825-4894b7c8c6c6', 'c', 'Fuera de aguas costeras protegidas, puertos, radas, rías, bahías abrigadas y aguas protegidas en general, utilizando una instalación de tratamiento de aguas sucias y que el efluente no produzca sólidos flotantes visibles ni ocasione coloración en las aguas circundantes.', true, '2025-09-13 13:53:10.591208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da6be701-34d6-4673-8b9c-c29317fdfbb0', '3764238b-699b-426c-a825-4894b7c8c6c6', 'd', 'A una distancia inferior a 12 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias no han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.591347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bd10b08-a2ff-4c9a-87f6-fdacab21ffaf', 'd356d15b-1083-47af-993e-ef531c74d684', 'a', 'Reciben el nombre del cuadrante en el que están colocadas.', false, '2025-09-13 13:53:10.591621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9742fced-47dd-42ef-aaa6-2d53d21e68ca', 'd356d15b-1083-47af-993e-ef531c74d684', 'b', 'El nombre indica que se ha de pasar por el cuadrante correspondiente a ese nombre.', false, '2025-09-13 13:53:10.591751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('289ddeb1-85e0-48cf-b942-b0095571cc7f', 'd356d15b-1083-47af-993e-ef531c74d684', 'c', 'Los cuatro cuadrantes (Norte, Este, Sur, Oeste) están limitados por las marcaciones NW-NE, NE-SE, SE-SW, SW-NW, tomadas desde el punto que interesa balizar.', true, '2025-09-13 13:53:10.591893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f5ecfa8-6e62-4fea-b3f6-4191904e6663', 'd356d15b-1083-47af-993e-ef531c74d684', 'd', 'Pueden ser utilizadas para llamar la atención sobre una configuración especial de un canal.', false, '2025-09-13 13:53:10.592022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d223e11-b4c2-4699-9f2e-c233e7c2d6e7', '2ef020ca-2f70-4737-b275-cc17b5547220', 'a', 'El canal principal está a babor.', true, '2025-09-13 13:53:10.592428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('744dd349-ceda-44d6-a38b-8cedfe803579', '2ef020ca-2f70-4737-b275-cc17b5547220', 'b', 'El canal principal está a estribor.', false, '2025-09-13 13:53:10.592565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27c2a0ea-7347-4ccf-ba91-a50ca506bc16', '2ef020ca-2f70-4737-b275-cc17b5547220', 'c', 'El canal es temporalmente no navegable.', false, '2025-09-13 13:53:10.5927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf20aac2-70ca-4eda-800e-737028b57829', '2ef020ca-2f70-4737-b275-cc17b5547220', 'd', 'El centro del canal y debemos dejarla por nuestro babor.', false, '2025-09-13 13:53:10.592838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adeb47ba-8a32-494d-96e4-b2346680149a', '217e93dd-b268-4966-921a-a1be4771971e', 'a', 'La que indica el canal principal, siguiendo el sentido convencional del balizamiento, en un punto de bifurcación de un canal.', false, '2025-09-13 13:53:10.593134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e866ec7-f843-4aff-a3cf-56708588b8ca', '217e93dd-b268-4966-921a-a1be4771971e', 'b', 'La que indica la configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:10.593267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7e16629-2257-49d5-8f0f-0d1ffbf4643b', '217e93dd-b268-4966-921a-a1be4771971e', 'c', 'La utilizada para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.593396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f4fcab3-c79a-447c-be63-e57f7d000249', '217e93dd-b268-4966-921a-a1be4771971e', 'd', 'La utilizada para indicar los límites de un área con peligros aislados de dimensiones limitadas.', false, '2025-09-13 13:53:10.593526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('342fa233-7310-4527-8eb7-c4b9c03d2664', 'a6451dbb-53af-42aa-9c26-0d14868af555', 'a', 'Si tiene, esta será una esfera roja.', true, '2025-09-13 13:53:10.593815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('391648dc-38b1-4510-ba0b-8e922972955d', 'a6451dbb-53af-42aa-9c26-0d14868af555', 'b', 'Será dos esferas rojas superpuestas con una clara separación entre ambas.', false, '2025-09-13 13:53:10.593949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f8e3fc8-ac29-4b52-939e-9bbb3d36a6f3', 'a6451dbb-53af-42aa-9c26-0d14868af555', 'c', 'Si tiene, esta será dos esferas cuyo color será de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:10.59408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34756e18-9228-4e35-ba68-1b1a3b670a0c', 'a6451dbb-53af-42aa-9c26-0d14868af555', 'd', 'Será una esfera, de color a elegir, pero sin que pueda prestarse a confusión con las marcas', false, '2025-09-13 13:53:10.594215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72ec9068-6b95-499b-b950-f1259a443993', '75cbb69d-9fc5-47b5-97d1-20aca8a72377', 'a', 'Marcas de peligro aislado.', true, '2025-09-13 13:53:10.594486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab889978-1f3c-42be-aa2f-a1df6a291890', '75cbb69d-9fc5-47b5-97d1-20aca8a72377', 'b', 'Marcas de aguas navegables.', false, '2025-09-13 13:53:10.594624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e60e0527-8a6b-40ab-962c-c92569e5feae', '75cbb69d-9fc5-47b5-97d1-20aca8a72377', 'c', 'Marcas especiales.', false, '2025-09-13 13:53:10.594756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('108f4e82-6e26-416c-b1b4-0e287b93be7f', '6b2b3caf-6852-4ecc-8712-17d6ba987587', 'a', 'Dos luces todo horizonte en línea vertical, blanca la superior y roja la inferior.', false, '2025-09-13 13:53:10.595176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3650fc7-fb4e-47c7-9a36-536a335df5d2', '6b2b3caf-6852-4ecc-8712-17d6ba987587', 'b', 'Dos luces todo horizonte en línea vertical, roja la superior y blanca la inferior.', false, '2025-09-13 13:53:10.595309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ddaa479-11c7-466a-ae5e-33f1c560a019', '6b2b3caf-6852-4ecc-8712-17d6ba987587', 'c', 'Dos luces todo horizonte en línea vertical, blanca la superior y verde la inferior.', false, '2025-09-13 13:53:10.595441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f00c21c-1a97-48cd-b3ed-21fd0bbd3209', '6b2b3caf-6852-4ecc-8712-17d6ba987587', 'd', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', true, '2025-09-13 13:53:10.595573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e2ebb81-558e-48af-bd76-8bb0bd2c04a9', 'fb768011-2cee-4087-ba3b-cf208533bfaa', 'a', 'Una demora menor de 225 grados a popa del través de este último.', false, '2025-09-13 13:53:10.595849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4e3b1eb-9e41-4ea7-9999-adcb1922a717', 'fb768011-2cee-4087-ba3b-cf208533bfaa', 'b', 'Una marcación mayor de 22,5 grados a proa del través de este último.', false, '2025-09-13 13:53:10.595981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d90fd30-d2f6-4eb9-ac66-140853639939', 'fb768011-2cee-4087-ba3b-cf208533bfaa', 'c', 'Una marcación mayor de 22,5 grados a popa del través de este último.', true, '2025-09-13 13:53:10.596115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4300bce5-18a5-4d15-bc70-1a14dc6e3c7e', 'fb768011-2cee-4087-ba3b-cf208533bfaa', 'd', 'Una demora menor de 225 grados a proa del través de este último.', false, '2025-09-13 13:53:10.596245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d8208d1-b067-4ae1-b0cf-3a79d3fb2c0b', '20e53730-9d92-4079-a393-94632ed78c08', 'b', 'Los dispositivos de separación de tráfico podrán ser adoptados de manera bilateral por los Gobiernos de dos Estados.', false, '2025-09-13 13:53:10.596651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef112bf7-073c-441c-8626-5a2b34a38430', '20e53730-9d92-4079-a393-94632ed78c08', 'c', 'Ninguna disposición del Reglamento eximirá a un buque, o a su propietario, al Capitán o a la dotación del mismo, de las consecuencias de cualquier negligencia en la aplicación del mismo.', true, '2025-09-13 13:53:10.596783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41220d76-3df9-46f0-b685-e8ea0991d473', '20e53730-9d92-4079-a393-94632ed78c08', 'd', 'Se considerarán buques dedicados a la pesca aquellos que pesquen con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:10.596916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64f65307-c482-4ddd-bf27-78b6c1cc1f49', '9dc64571-c17e-4124-9f6b-7d0f3431500f', 'a', 'Una nave de vuelo rasante que navegue por la superficie.', false, '2025-09-13 13:53:10.597383+00');
