INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf00fd22-cd20-479e-898e-8112fa0a1cf6', 'd68c30d3-5870-44f3-8cc9-5bef31c10aba', 'b', 'Cónica, de castillete o espeque.', false, '2025-09-13 13:53:10.609932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ccbba53-0d14-482c-a9ff-a19c38d44bdd', 'd68c30d3-5870-44f3-8cc9-5bef31c10aba', 'c', 'De aspa, castillete o espeque.', false, '2025-09-13 13:53:10.610059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aa0e61d-53a7-436a-bca3-3270bc09f8af', 'd68c30d3-5870-44f3-8cc9-5bef31c10aba', 'd', 'Ninguna de las anteriores es correcta.', false, '2025-09-13 13:53:10.610187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b0fcb78-118f-4a3a-a235-d0409ac96cec', 'a90e1d79-b287-4654-bc44-7809279b386e', 'a', 'Una línea que une puntos naturales de la costa.', false, '2025-09-13 13:53:10.610487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e216bba5-1708-4f3b-8676-517cdfb1d609', 'a90e1d79-b287-4654-bc44-7809279b386e', 'b', 'Una línea que une puntos artificiales de la costa.', false, '2025-09-13 13:53:10.610619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d79499da-f000-4a39-868f-a97ee3f1705f', 'a90e1d79-b287-4654-bc44-7809279b386e', 'c', 'Una línea que une puntos de la misma profundidad.', true, '2025-09-13 13:53:10.610751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9ef9757-71cb-45ba-bf8f-21cb4498d30d', 'aceb8694-04f6-4d26-bd8e-7fa5289070ca', 'c', 'Si dispone de balsa salvavidas, deberá amarrar a bordo la driza de la balsa antes de lanzarla al agua.', false, '2025-09-13 13:53:10.603898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31ec2f37-4573-49ad-96b7-d531505c0189', '88b65055-9b86-47c9-8c75-e163970d9d11', 'c', 'Si una quemadura afecta a una articulación y es al menos de 2º grado, es necesario inmovilizar la zona.', false, '2025-09-13 13:53:10.605242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3997f15a-75c5-4547-b6b1-539f8df52562', 'c773da95-1cc5-4180-8836-af64fab700e4', 'c', 'La extensión o alcance que tiene el viento sobre la mar cuando sopla con dirección y fuerza constantes.', true, '2025-09-13 13:53:10.606609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dadd723-e081-489b-99c3-59a16cc2a83d', '61463b33-0751-4c61-b662-88f5ab0cd325', 'a', 'Son regiones donde la presión atmosférica es más elevada que la de sus alrededores para el mismo nivel.', false, '2025-09-13 13:53:10.607044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8658a0c-97b8-4ffb-b2f6-418a37f19527', '3cda1bc8-7be8-41e1-bc88-bd66b219295c', 'd', 'La hora de llegada a puerto.', true, '2025-09-13 13:53:10.601853+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09fd2fbd-afd6-4928-a1d5-476b2ca19a47', 'd1450210-7a96-4ab9-8fc1-43db92907d86', 'b', 'Un buque fondeado y pretende señalar su posición y la posibilidad de abordaje a un buque que se aproxime.', true, '2025-09-13 13:53:10.600241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f610670d-c0a1-4532-85d6-ef7403b9b6cc', 'ec7ef35f-00b2-4c8e-a55b-5a64dc30b598', 'd', 'Ángulo de abatimiento.', true, '2025-09-13 13:53:10.603362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd2a0e85-121a-4415-896c-c50a6ef920eb', 'd292ad60-c1ec-493c-91dc-a83b10246334', 'a', 'Son círculos menores cuyo centro coincide con el centro de la tierra.', false, '2025-09-13 13:53:10.61117+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('638973e0-927c-4951-88a6-6c711e26df87', 'd292ad60-c1ec-493c-91dc-a83b10246334', 'b', 'Son cualquiera de los círculos máximos formados por la intersección de la esfera terrestre y un plano que contiene al eje de la tierra.', true, '2025-09-13 13:53:10.611312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc747990-e4a3-49be-a3c0-815ecea2083d', 'd292ad60-c1ec-493c-91dc-a83b10246334', 'c', 'El Ecuador es el meridiano que pasa por el centro de la tierra.', false, '2025-09-13 13:53:10.611448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dfef6c7-d1a0-4f77-ae5a-4b5f6f789afd', 'd292ad60-c1ec-493c-91dc-a83b10246334', 'd', 'Son cualquiera de los círculos menores formados por la intersección de la esfera terrestre con planos paralelos al ecuador. Carta de navegación.', false, '2025-09-13 13:53:10.611578+00');
