INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d05e37d-3f3e-494b-8df3-1cf94c204a5f', 'd5ac8aac-bbe2-482b-9f65-8ea0d9c58f12', 'd', '8,73 m. DE TRANSPORTES, MOVILIDAD                                                                           DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                     Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 04 Nomenclatura náutica.', false, '2025-09-13 13:53:10.614373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82bcf8e6-05ee-4dde-9114-0d4fcbf38c68', '5a937beb-c9b2-4ca2-8b26-a68d820356ab', 'a', 'La anchura del casco en su proyección horizontal y medida a la cara exterior del forro.', true, '2025-09-13 13:53:10.61479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e52fe39b-159b-4e30-9b7c-2585f9763297', '5a937beb-c9b2-4ca2-8b26-a68d820356ab', 'b', 'La distancia medida paralelamente a la línea de flotación y al eje de la embarcación, entre dos planos verticales perpendiculares al plano central de la embarcación situados uno en la parte más a proa y el otro en la parte más a popa.', false, '2025-09-13 13:53:10.614933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c81f7cf2-485f-404c-871f-d2145bf10528', '5a937beb-c9b2-4ca2-8b26-a68d820356ab', 'c', 'La distancia vertical medida a la mitad de la eslora desde la cara superior de la línea de cubierta hasta el canto superior de la quilla.', false, '2025-09-13 13:53:10.615062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48579c8d-00cb-48ff-bf8d-f50e484d8232', '5a937beb-c9b2-4ca2-8b26-a68d820356ab', 'd', 'La altura medida sobre el costado de la embarcación desde la línea de flotación, en su condición de máxima carga, hasta la cubierta estanca más alta.', false, '2025-09-13 13:53:10.615189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('023a6dd8-70d2-4fc0-9aeb-e836062d8c18', '68602df2-dd72-4fac-be28-3ee0097d532d', 'a', 'Los manguerotes.', false, '2025-09-13 13:53:10.615457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ab39c73-dd93-489d-b2d1-5edf24ce3ddb', '68602df2-dd72-4fac-be28-3ee0097d532d', 'b', 'Los grifos de fondo.', true, '2025-09-13 13:53:10.615585+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9530721-6601-4db1-8215-98ce9c093bd6', '68602df2-dd72-4fac-be28-3ee0097d532d', 'c', 'Los imbornales.', false, '2025-09-13 13:53:10.615712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2890ba8e-932b-4aaa-8da5-aff615250796', '68602df2-dd72-4fac-be28-3ee0097d532d', 'd', 'Los desagües.', false, '2025-09-13 13:53:10.615856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c472038-b11a-4463-87bb-de4ea6393a87', '26bdecea-fb63-4762-9e52-c69a75790185', 'a', 'Molinete.', false, '2025-09-13 13:53:10.616135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('886db6ee-b92e-40bd-b10f-6338e97bddba', '26bdecea-fb63-4762-9e52-c69a75790185', 'b', 'Barbotén.', true, '2025-09-13 13:53:10.616285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d676cd1f-da61-4b20-8ddb-76d018c3512e', '26bdecea-fb63-4762-9e52-c69a75790185', 'c', 'Chigre.', false, '2025-09-13 13:53:10.616419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2651d6e8-1323-463a-9733-8ce818350ef1', '26bdecea-fb63-4762-9e52-c69a75790185', 'd', 'Grillete.', false, '2025-09-13 13:53:10.616552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f7c95ab-ce7b-4d5f-a399-ce582634e9db', '2f1fbb62-25c2-4bf4-8345-bbe0608b85ff', 'a', 'Incide por sotavento.', false, '2025-09-13 13:53:10.616831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb8385a4-de9c-4c52-9d43-130f43bc7999', '2f1fbb62-25c2-4bf4-8345-bbe0608b85ff', 'b', 'Ejerce su presión solamente sobre las velas y es lo que hace que la embarcación avance.', false, '2025-09-13 13:53:10.616974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8248a1e1-89b6-4d75-8d16-3b6d64086d93', '2f1fbb62-25c2-4bf4-8345-bbe0608b85ff', 'c', 'Ejerce su presión sobre la obra muerta.', true, '2025-09-13 13:53:10.617111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a60b3754-c917-4c45-8513-f0d42564e9cd', '9fec9f6a-2c6c-48d5-8576-42e5550bc4d7', 'a', 'Las boyas son piezas que se colocan en el costado de la embarcación para evitar que se dañe cuando está atracada.', false, '2025-09-13 13:53:10.617635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e25e48f9-57c4-427e-a76b-66c7357774fc', '9fec9f6a-2c6c-48d5-8576-42e5550bc4d7', 'b', 'El guía-cabos es una rueda acanalada por donde corre el cabo en un motón.', false, '2025-09-13 13:53:10.617786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5bd9de9-879c-4831-af92-d44dfd2b5076', '9fec9f6a-2c6c-48d5-8576-42e5550bc4d7', 'c', 'El nudo llano permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:10.617935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('045e8160-ba01-4b69-8d96-a7aa3f6ee01d', '9fec9f6a-2c6c-48d5-8576-42e5550bc4d7', 'd', 'El bichero es un palo largo con un gancho y punta en uno de sus extremos, que se utiliza para coger la guía o las amarras.', true, '2025-09-13 13:53:10.618078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b79b0054-eb35-41b7-bb11-3f21968e6d60', 'b77f6ec1-93a0-4c83-9550-ec76c0925565', 'a', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear un segundo ancla o aguantar con máquina avante.', true, '2025-09-13 13:53:10.618367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a49a60a0-18a4-4c6c-beeb-8828561cfcc0', 'b77f6ec1-93a0-4c83-9550-ec76c0925565', 'b', 'Durante el fondeo, solo se precisa vigilar la sonda, marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:10.618503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19362f22-9f84-4831-9ae6-238edb17411c', 'b77f6ec1-93a0-4c83-9550-ec76c0925565', 'c', 'El circulo de borneo lo describe el centro de gravedad de la embarcación y tiene como radio la cadena más la mitad de la eslora.', false, '2025-09-13 13:53:10.618638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46306a7f-be85-4322-b8aa-ba93ebeacf01', 'b77f6ec1-93a0-4c83-9550-ec76c0925565', 'd', 'Un barco fondea a la gira cuando utiliza dos anclas, cuyas líneas de fondeo forman un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:10.618774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a49d1345-0fa9-470a-a76c-5b7dbc6c0005', '02f13c99-9b50-4467-b3ed-2112315511d7', 'a', 'Evitar nadar y mantener una posición fetal en el agua con el chaleco salvavidas puesto.', false, '2025-09-13 13:53:10.619059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59ce298a-45ee-475a-b969-dbbd4c90e583', '02f13c99-9b50-4467-b3ed-2112315511d7', 'b', 'Abrigar al afectado a resguardo del viento.', false, '2025-09-13 13:53:10.619204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b58a441e-ca6e-4b6f-98ff-5e1b493c89a5', '02f13c99-9b50-4467-b3ed-2112315511d7', 'c', 'Mantener al afectado con la ropa puesta y frotar enérgicamente para que entre en calor.', true, '2025-09-13 13:53:10.61934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccfdea30-3530-46d9-821c-891c4692150a', '02f13c99-9b50-4467-b3ed-2112315511d7', 'd', 'Trasladar al afectado en posición horizontal.', false, '2025-09-13 13:53:10.619473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d1604da-8be4-47d2-8b2d-d9f9fc13d2b4', 'b4427f60-dca8-4e46-96ca-e1ff5eb6fbd8', 'a', 'Si tiene una instalación eléctrica de más de 50 voltios, uno de los extintores debe ser adecuado para riesgo eléctrico.', false, '2025-09-13 13:53:10.61975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a81e9a59-a118-432c-bfd3-fb6377416857', 'b4427f60-dca8-4e46-96ca-e1ff5eb6fbd8', 'b', 'Si se dedica a fines comerciales o lucrativos llevará un extintor adicional al que tiene que llevar reglamentariamente.', false, '2025-09-13 13:53:10.619931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53bd2aac-c524-4d76-a0c1-21b93a640c65', 'b4427f60-dca8-4e46-96ca-e1ff5eb6fbd8', 'c', 'Aunque lleve instalados un sistema fijo de contraincendios debe llevar al menos un extintor.', false, '2025-09-13 13:53:10.62008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c069be5f-bdc4-4a6e-ae38-81ea52dde4e1', 'b4427f60-dca8-4e46-96ca-e1ff5eb6fbd8', 'd', 'Llevará al menos un extintor y todos ellos se estibarán en una zona de fácil acceso y alejada del puesto principal de gobierno de la embarcación.', true, '2025-09-13 13:53:10.620216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f9c5062-8a03-4c1b-915a-73c5c322dc0c', 'ad077816-b0e5-469e-94d3-99281b50f37e', 'a', '091.', false, '2025-09-13 13:53:10.620497+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4b60944-fb87-473f-bef7-c8c1c60ecc62', 'ad077816-b0e5-469e-94d3-99281b50f37e', 'b', '900 112 112.', false, '2025-09-13 13:53:10.620631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee22053d-a8e5-49a5-aba2-d6712798f248', 'ad077816-b0e5-469e-94d3-99281b50f37e', 'c', '900 102 102.', false, '2025-09-13 13:53:10.62077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bd3ba2d-00e3-4099-ae18-26e384653456', 'ad077816-b0e5-469e-94d3-99281b50f37e', 'd', '900 202 202.', true, '2025-09-13 13:53:10.620903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8008022c-6a03-4f83-be67-d0acd95798bf', '203e8d05-78c7-472f-b97e-c73757a981a0', 'a', 'A correr el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.621177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30ee72c0-5f71-4ffa-bf70-f739d1d8071e', '203e8d05-78c7-472f-b97e-c73757a981a0', 'b', 'A capear el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.62131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6dad758-5831-406a-887c-6f6e29d4a84c', '203e8d05-78c7-472f-b97e-c73757a981a0', 'c', 'A navegar con la proa a la mar para evitar el vuelco del barco en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.621443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e89a4a6-1227-48ec-b6ba-3e1046cf05f6', '203e8d05-78c7-472f-b97e-c73757a981a0', 'd', 'A la estiba y trinca más adecuadas a bordo de los objetos, carga, aparejos, etc., para que no se muevan durante condiciones de mal tiempo.', true, '2025-09-13 13:53:10.621582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d13789b-d6b3-400d-bba4-614fbec0c097', '55a8fd59-a452-49b1-bff9-808c37c23a14', 'a', 'A una distancia inferior a 3 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.62186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e689f1c-6291-464c-8e95-f64adfd7ac31', '55a8fd59-a452-49b1-bff9-808c37c23a14', 'b', 'Dentro de zona 7, utilizando una instalación de tratamiento de aguas sucias, y que el efluente produzca sólidos flotantes visibles y ocasione coloración en las aguas circundantes.', false, '2025-09-13 13:53:10.621993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1039b589-5e7d-454e-ba1d-e84c89b4516d', '55a8fd59-a452-49b1-bff9-808c37c23a14', 'c', 'Fuera de aguas costeras protegidas, puertos, radas, rías, bahías abrigadas y aguas protegidas en general, utilizando una instalación de tratamiento de aguas sucias y que el efluente no produzca sólidos flotantes visibles ni ocasione coloración en las aguas circundantes.', true, '2025-09-13 13:53:10.622127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5f1c4c3-3049-4d69-b3b3-7eab1fd66fab', '55a8fd59-a452-49b1-bff9-808c37c23a14', 'd', 'A una distancia inferior a 12 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias no han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.622429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f35fad1-f9d5-471f-a02d-a0b8d044c235', '3e83c699-80de-4aa4-b20e-27331253f6d0', 'd', 'Está obligado a informar de ello a las personas en peligro en el mar y a mantener contacto con ellos, a intervalos de no más de 3 horas, hasta que llegue al lugar otro buque y considere que el auxilio ya no es necesario.', false, '2025-09-13 13:53:10.623137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef389a2f-1859-4de0-93de-8ad7cfaf5377', '4beef85b-10d6-4d6d-a3dc-f409e7240f75', 'a', 'Si tiene, esta será una esfera roja.', true, '2025-09-13 13:53:10.623413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0612016-b358-4a8e-ba50-e0688dcfe2de', '4beef85b-10d6-4d6d-a3dc-f409e7240f75', 'b', 'Será dos esferas rojas superpuestas con una clara separación entre ambas.', false, '2025-09-13 13:53:10.623544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77705595-2260-4c11-a5d6-eae644b0ff8e', '4beef85b-10d6-4d6d-a3dc-f409e7240f75', 'c', 'Si tiene, esta será dos esferas cuyo color será de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:10.623675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05b63e83-1cc2-4c2c-ac11-9ae5eb6c97a6', '4beef85b-10d6-4d6d-a3dc-f409e7240f75', 'd', 'Será una esfera, de color a elegir, pero sin que pueda prestarse a confusión con las marcas', false, '2025-09-13 13:53:10.623821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a2400b7-f782-4b63-b9c4-0df804cefcfb', '98b1bda1-d978-46b5-9de3-52f01e1d2369', 'a', 'Marcas de peligro aislado.', true, '2025-09-13 13:53:10.624121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c97bb99-4385-4d1d-b766-ee09096a1597', '98b1bda1-d978-46b5-9de3-52f01e1d2369', 'b', 'Marcas de aguas navegables.', false, '2025-09-13 13:53:10.624255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b073c01-e182-42de-b906-58cc0660dfdb', '98b1bda1-d978-46b5-9de3-52f01e1d2369', 'c', 'Marcas especiales.', false, '2025-09-13 13:53:10.624386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf432598-7fe6-43bc-9d4e-b477bfb0d4a2', '98b1bda1-d978-46b5-9de3-52f01e1d2369', 'd', 'Marcas cardinales norte.', false, '2025-09-13 13:53:10.624517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c5c3ee3-de87-4776-a947-1a1b2a4f97ab', 'b13acbfd-75e1-412b-83ee-2eaf050cd0e5', 'a', 'Reciben el nombre del cuadrante en el que están colocadas.', false, '2025-09-13 13:53:10.624801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85718f4d-5ee2-4c37-93f8-7ea87275c1dd', 'b13acbfd-75e1-412b-83ee-2eaf050cd0e5', 'b', 'El nombre indica que se ha de pasar por el cuadrante correspondiente a ese nombre.', false, '2025-09-13 13:53:10.624934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0c02547-c5ad-45fa-a24c-bd97bbd28f4e', 'b13acbfd-75e1-412b-83ee-2eaf050cd0e5', 'c', 'Los cuatro cuadrantes (Norte, Este, Sur, Oeste) están limitados por las marcaciones NW-NE, NE-SE, SE-SW, SW-NW, tomadas desde el punto que interesa balizar.', true, '2025-09-13 13:53:10.625064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9221e8b0-179d-4df6-a099-59443f4528db', 'b13acbfd-75e1-412b-83ee-2eaf050cd0e5', 'd', 'Pueden ser utilizadas para llamar la atención sobre una configuración especial de un canal.', false, '2025-09-13 13:53:10.625195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eef2e5a-3255-44ab-bf80-e0d78c358c38', '4f103b52-154f-47cc-b2b7-f416771833c4', 'a', 'El canal principal está a babor.', true, '2025-09-13 13:53:10.625466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cea41f41-b78c-49e9-9ec9-0b9f8de0f9f7', '4f103b52-154f-47cc-b2b7-f416771833c4', 'b', 'El canal principal está a estribor.', false, '2025-09-13 13:53:10.625598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da8ea5c7-ce35-4ce4-ba98-e5aa38498f3d', '4f103b52-154f-47cc-b2b7-f416771833c4', 'c', 'El canal es temporalmente no navegable.', false, '2025-09-13 13:53:10.625729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('981d9870-8b91-4865-8f98-c77757dc3642', '4f103b52-154f-47cc-b2b7-f416771833c4', 'd', 'El centro del canal y debemos dejarla por nuestro babor.', false, '2025-09-13 13:53:10.62586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('030f73cd-d998-4afc-990d-c9e2de719deb', 'aec3e27d-21f2-42ab-9f99-6cf13e9193e2', 'a', 'La que indica el canal principal, siguiendo el sentido convencional del balizamiento, en un punto de bifurcación de un canal.', false, '2025-09-13 13:53:10.626152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9bc31c1-b906-49e5-bafc-bb61552f6c70', 'aec3e27d-21f2-42ab-9f99-6cf13e9193e2', 'b', 'La que indica la configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:10.626319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5e1575e-fa59-40b8-89d0-714eb3c20cc2', 'aec3e27d-21f2-42ab-9f99-6cf13e9193e2', 'c', 'La utilizada para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.626463+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd00a5ce-4a08-41db-b682-cf02745b6370', 'aec3e27d-21f2-42ab-9f99-6cf13e9193e2', 'd', 'La utilizada para indicar los límites de un área con peligros aislados de dimensiones limitadas. Reglamento (RIPA).', false, '2025-09-13 13:53:10.626601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4e798ac-285c-45d0-b29f-6f74eb9f5112', 'cc9a41da-4214-436d-9d98-15749d28183a', 'a', 'El estado del viento, mar y corriente, y la proximidad de peligros para la navegación.', false, '2025-09-13 13:53:10.626903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3df75462-3f58-456c-8e9c-a5b1dfeaf80b', 'cc9a41da-4214-436d-9d98-15749d28183a', 'b', 'El calado en relación con la profundidad disponible de agua.', false, '2025-09-13 13:53:10.627037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0882b32c-b358-42f3-a02c-ef51d8da6a74', 'cc9a41da-4214-436d-9d98-15749d28183a', 'c', 'De noche, la existencia de resplandor.', false, '2025-09-13 13:53:10.627281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99373c41-07bb-49a1-bdc9-3904bb39e930', 'cc9a41da-4214-436d-9d98-15749d28183a', 'd', 'La hora de llegada a puerto.', true, '2025-09-13 13:53:10.627423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40445b23-f9fc-498a-8d08-3559b5237850', 'e700979b-c618-49ab-bc78-81c1c2fc919d', 'a', 'Una nave de vuelo rasante que navegue por la superficie.', false, '2025-09-13 13:53:10.627698+00');
