INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54956bb5-defd-4ced-a34d-cc3c4159eda1', 'f03c6d10-927d-4e0a-bf5b-f99fcaef0a45', 'b', 'Los dispositivos de separación de tráfico podrán ser adoptados de manera bilateral por los Gobiernos de dos Estados.', false, '2025-09-13 13:53:10.632103+00');
