INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68299daf-8cea-43db-8fd4-e5e6ceb53c23', 'f03c6d10-927d-4e0a-bf5b-f99fcaef0a45', 'd', 'Se considerarán buques dedicados a la pesca aquellos que pesquen con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:10.632376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af72aebf-3f76-4fd3-b350-ed12bf1eae40', '007f56f0-7bd1-4694-905e-2a63b6a929b1', 'a', 'El buque que tenga al otro por su costado de babor, se mantendrá apartado de la derrota de éste otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:10.632653+00');
