INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd776d19-73e8-4546-8876-d9d3a83273a0', '007f56f0-7bd1-4694-905e-2a63b6a929b1', 'd', 'El buque que tenga al otro por su costado de estribor, se mantendrá apartado de la derrota de éste otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:10.633052+00');
