INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('448d2e31-b420-4765-912d-59e1d5adbe97', '6230af7f-914e-45ec-82b8-71f3ff808a82', 'a', 'Las boyas son piezas que se colocan en el costado de la embarcación para evitar que se dañe cuando está atracada.', false, '2025-09-13 13:53:10.676087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a71673b-0a8c-4c11-bb04-a02da4d89ef4', '6230af7f-914e-45ec-82b8-71f3ff808a82', 'b', 'El guía-cabos es una rueda acanalada por donde corre el cabo en un motón.', false, '2025-09-13 13:53:10.676222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6fbc494-1a61-4314-842a-163cf105bd1b', '6230af7f-914e-45ec-82b8-71f3ff808a82', 'c', 'El nudo llano permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:10.67646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b02a28e-29f2-403a-8817-6f66efc50cc8', '6230af7f-914e-45ec-82b8-71f3ff808a82', 'd', 'El bichero es un palo largo con un gancho y punta en uno de sus extremos, que se utiliza para coger la guía o las amarras.', true, '2025-09-13 13:53:10.676595+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a8dd7c7-13ce-400d-a59b-c3e0eb0c54c5', 'b470256f-77a6-4b72-ad7a-1b69bd0225e5', 'a', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear un segundo ancla o aguantar con máquina avante.', true, '2025-09-13 13:53:10.67688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47bf7274-572e-48e9-bdc2-5025642855ae', 'b470256f-77a6-4b72-ad7a-1b69bd0225e5', 'b', 'Durante el fondeo, solo se precisa vigilar la sonda, marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:10.677028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('331cbfbe-7bae-4ddb-a9a9-aff0f24af6c1', 'b470256f-77a6-4b72-ad7a-1b69bd0225e5', 'c', 'El circulo de borneo lo describe el centro de gravedad de la embarcación y tiene como radio la cadena más la mitad de la eslora.', false, '2025-09-13 13:53:10.677167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('358a380b-d5de-476b-a108-6f018b1a1dff', 'b470256f-77a6-4b72-ad7a-1b69bd0225e5', 'd', 'Un barco fondea a la gira cuando utiliza dos anclas, cuyas líneas de fondeo forman un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:10.677303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aa42a83-b9b6-4800-ba02-dd4795c2b596', 'a02894af-a583-4ff4-b247-b6d61bd9c620', 'a', 'Si tiene una instalación eléctrica de más de 50 voltios, uno de los extintores debe ser adecuado para riesgo eléctrico.', false, '2025-09-13 13:53:10.677587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c23cc8f-8aca-4689-8af4-67b1af54847b', 'a02894af-a583-4ff4-b247-b6d61bd9c620', 'b', 'Si se dedica a fines comerciales o lucrativos llevará un extintor adicional al que tiene que llevar reglamentariamente.', false, '2025-09-13 13:53:10.677721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81a5351d-03f5-40b3-8620-259b47feedf3', 'a02894af-a583-4ff4-b247-b6d61bd9c620', 'c', 'Aunque lleve instalados un sistema fijo de contraincendios debe llevar al menos un extintor.', false, '2025-09-13 13:53:10.677858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fde86f0-a85f-4253-a5f5-8864a049d5a8', 'a02894af-a583-4ff4-b247-b6d61bd9c620', 'd', 'Llevará al menos un extintor y todos ellos se estibarán en una zona de fácil acceso y alejada del puesto principal de gobierno de la embarcación.', true, '2025-09-13 13:53:10.677993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92a8d38a-9e54-4287-88a5-da7a92f0d1c9', '90a394a1-bfd5-4bd7-b5c4-6e2d5309305f', 'a', 'A correr el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.678267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b2b70f2-d2aa-425f-92de-8c255f2f1836', '90a394a1-bfd5-4bd7-b5c4-6e2d5309305f', 'b', 'A capear el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.678397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edb4c57c-ee48-4af3-ac31-9bb33ab1dfd1', '90a394a1-bfd5-4bd7-b5c4-6e2d5309305f', 'c', 'A navegar con la proa a la mar para evitar el vuelco del barco en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.678548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09c328ef-ce4c-4a8a-90a6-2bfdd7afb665', '90a394a1-bfd5-4bd7-b5c4-6e2d5309305f', 'd', 'A la estiba y trinca más adecuadas a bordo de los objetos, carga, aparejos, etc., para que no se muevan durante condiciones de mal tiempo.', true, '2025-09-13 13:53:10.67868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18009f2f-9491-4630-9e88-f320cd155e75', 'b9143db2-78ea-4bc3-bc56-07432fd437e4', 'a', 'Evitar nadar y mantener una posición fetal en el agua con el chaleco salvavidas puesto.', false, '2025-09-13 13:53:10.679009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b2f31d5-aff1-4be7-9e80-234cb343f8a7', 'b9143db2-78ea-4bc3-bc56-07432fd437e4', 'b', 'Abrigar al afectado a resguardo del viento.', false, '2025-09-13 13:53:10.679145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb147e88-3dd9-4c4f-bca0-a606fd6b0f69', 'b9143db2-78ea-4bc3-bc56-07432fd437e4', 'c', 'Mantener al afectado con la ropa puesta y frotar enérgicamente para que entre en calor.', true, '2025-09-13 13:53:10.679282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2237ae7-5eaa-4d00-b8cd-4e36fb0185bd', 'b9143db2-78ea-4bc3-bc56-07432fd437e4', 'd', 'Trasladar al afectado en posición horizontal.', false, '2025-09-13 13:53:10.679416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66e70f12-88ee-4326-a2ad-f6114fbb3a16', 'd579fcd3-8534-4bae-8032-1bbab8a407b2', 'a', '091.', false, '2025-09-13 13:53:10.679691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54a5a32a-29fc-452a-8601-6d63cbafdb1a', 'd579fcd3-8534-4bae-8032-1bbab8a407b2', 'b', '900 112 112.', false, '2025-09-13 13:53:10.679822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('760caa22-2430-4aee-a5af-9c925ed4fc21', 'd579fcd3-8534-4bae-8032-1bbab8a407b2', 'c', '900 102 102.', false, '2025-09-13 13:53:10.67997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21f8b4d4-bfa6-4673-b9e9-d71544a0fc27', 'd579fcd3-8534-4bae-8032-1bbab8a407b2', 'd', '900 202 202.', true, '2025-09-13 13:53:10.680252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d9255a5-7c0d-4d5e-adb8-6986f40b92d8', 'a4d5ca71-8c29-481d-aa5b-3f2e402a207b', 'a', 'Está obligado a acudir a toda máquina en auxilio de las personas en peligro en el mar y a transmitir la información, por todos los medios de que disponga, a los buques que se hallen', false, '2025-09-13 13:53:10.680537+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5cff686-51aa-4582-9a73-6a744ffe2211', 'a4d5ca71-8c29-481d-aa5b-3f2e402a207b', 'b', 'Anotará en el diario de navegación la razón por la cual no acudió en auxilio de las personas en', true, '2025-09-13 13:53:10.680666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4650049-74c8-4a57-b400-3610c4c72c2a', 'a4d5ca71-8c29-481d-aa5b-3f2e402a207b', 'c', 'Está obligado a transmitir la información, por todos los medios de que disponga, a los buques que se hallen cercanos, señalando la razón por la cual no puede acudir en auxilio de las personas en', false, '2025-09-13 13:53:10.680795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0a8a93f-b01e-41b0-9bf8-266d498255cc', 'a4d5ca71-8c29-481d-aa5b-3f2e402a207b', 'd', 'Está obligado a informar de ello a las personas en peligro en el mar y a mantener contacto con ellos, a intervalos de no más de 3 horas, hasta que llegue al lugar otro buque y considere que el auxilio ya no es necesario.', false, '2025-09-13 13:53:10.680924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71d53811-faf1-40d9-af44-d1af7447b37d', '37e5b2fb-a978-4e45-a956-f9474e4a4370', 'a', 'A una distancia inferior a 3 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.681233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('203b93bc-e31c-43e6-b810-8e71f3ce5093', '37e5b2fb-a978-4e45-a956-f9474e4a4370', 'b', 'Dentro de zona 7, utilizando una instalación de tratamiento de aguas sucias, y que el efluente produzca sólidos flotantes visibles y ocasione coloración en las aguas circundantes.', false, '2025-09-13 13:53:10.681371+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d2b73f1-ed1f-4630-ab46-31f967b05d5d', '37e5b2fb-a978-4e45-a956-f9474e4a4370', 'c', 'Fuera de aguas costeras protegidas, puertos, radas, rías, bahías abrigadas y aguas protegidas en general, utilizando una instalación de tratamiento de aguas sucias y que el efluente no produzca sólidos flotantes visibles ni ocasione coloración en las aguas circundantes.', true, '2025-09-13 13:53:10.681526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07777571-22fe-41bf-8cb2-2cddc0b06461', '37e5b2fb-a978-4e45-a956-f9474e4a4370', 'd', 'A una distancia inferior a 12 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias no han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.68169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ade38b4-8856-4042-9a71-8cad0c4bdc83', '83e27899-8395-4811-939d-41ca8f98ec9e', 'a', 'Reciben el nombre del cuadrante en el que están colocadas.', false, '2025-09-13 13:53:10.682041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1d0647e-e582-4ced-8a0b-d2e75590ec66', '83e27899-8395-4811-939d-41ca8f98ec9e', 'b', 'El nombre indica que se ha de pasar por el cuadrante correspondiente a ese nombre.', false, '2025-09-13 13:53:10.682207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('084fc42f-3f8b-4e9b-99bf-8492dc8f0b72', '83e27899-8395-4811-939d-41ca8f98ec9e', 'c', 'Los cuatro cuadrantes (Norte, Este, Sur, Oeste) están limitados por las marcaciones NW-NE, NE-SE, SE-SW, SW-NW, tomadas desde el punto que interesa balizar.', true, '2025-09-13 13:53:10.682372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8eb6391b-d667-4f18-a99c-06ddc9cac368', '83e27899-8395-4811-939d-41ca8f98ec9e', 'd', 'Pueden ser utilizadas para llamar la atención sobre una configuración especial de un canal.', false, '2025-09-13 13:53:10.682535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7416fa2e-77a9-41b1-ae00-6fc69036062b', 'e11ad8ad-be16-4015-a1c2-59a29f98bc39', 'c', 'El canal es temporalmente no navegable.', false, '2025-09-13 13:53:10.683157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfd6e297-af15-4f22-8adf-818038f52563', 'e11ad8ad-be16-4015-a1c2-59a29f98bc39', 'd', 'El centro del canal y debemos dejarla por nuestro babor.', false, '2025-09-13 13:53:10.6833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1705e6f1-43c9-4ce4-85a1-791bd6c8f11f', '1431cf94-5faf-46d3-9725-1c5fd70ca2dd', 'a', 'La que indica el canal principal, siguiendo el sentido convencional del balizamiento, en un punto de bifurcación de un canal.', false, '2025-09-13 13:53:10.683587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1f6902e-468f-45f6-b344-1759e186c700', '1431cf94-5faf-46d3-9725-1c5fd70ca2dd', 'b', 'La que indica la configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:10.683718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ee6ece5-4a4f-4400-873f-b7fe5dff896c', '1431cf94-5faf-46d3-9725-1c5fd70ca2dd', 'c', 'La utilizada para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.68385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4cfdcd9-d4fa-45c5-b1dc-76d76c578f53', '1431cf94-5faf-46d3-9725-1c5fd70ca2dd', 'd', 'La utilizada para indicar los límites de un área con peligros aislados de dimensiones limitadas.', false, '2025-09-13 13:53:10.683978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67c1bee3-32cf-4e73-942f-dd7e6673239d', 'a04194e5-54b7-4219-bc41-14712b8b7508', 'a', 'Si tiene, esta será una esfera roja.', true, '2025-09-13 13:53:10.684253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('087b0887-893d-4974-9911-af91fcdccb86', 'a04194e5-54b7-4219-bc41-14712b8b7508', 'b', 'Será dos esferas rojas superpuestas con una clara separación entre ambas.', false, '2025-09-13 13:53:10.684381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3a43546-b032-4c7c-81b0-b1c83e4a660d', 'a04194e5-54b7-4219-bc41-14712b8b7508', 'c', 'Si tiene, esta será dos esferas cuyo color será de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:10.684508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d2b0c20-1373-4926-9bd0-be88a25144c5', 'a04194e5-54b7-4219-bc41-14712b8b7508', 'd', 'Será una esfera, de color a elegir, pero sin que pueda prestarse a confusión con las marcas', false, '2025-09-13 13:53:10.684635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fadce068-686d-483b-b087-31cb2670a708', '616ffe92-a39e-4779-9337-b66c5df0b78a', 'a', 'Marcas de peligro aislado.', true, '2025-09-13 13:53:10.685107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0da28dae-afed-40ab-920d-0aad9ef467b7', '616ffe92-a39e-4779-9337-b66c5df0b78a', 'b', 'Marcas de aguas navegables.', false, '2025-09-13 13:53:10.685248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85f7f547-5545-4e50-95ca-4bdf507c794d', '616ffe92-a39e-4779-9337-b66c5df0b78a', 'c', 'Marcas especiales.', false, '2025-09-13 13:53:10.685383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6937817-dc2a-4d98-9b2d-c97d941f6e7a', '616ffe92-a39e-4779-9337-b66c5df0b78a', 'd', 'Marcas cardinales norte. Reglamento (RIPA).', false, '2025-09-13 13:53:10.685518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccc64d13-21f8-4074-8bd7-a29139eb05ef', 'e046851c-13f9-4764-9cbc-1c27fe527d0d', 'a', 'Dos luces todo horizonte en línea vertical, blanca la superior y roja la inferior.', false, '2025-09-13 13:53:10.685788+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eaee56b-e712-46b4-a55c-01fb57435400', 'e046851c-13f9-4764-9cbc-1c27fe527d0d', 'b', 'Dos luces todo horizonte en línea vertical, roja la superior y blanca la inferior.', false, '2025-09-13 13:53:10.685919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a0a1bf4-7e97-4ff6-89ad-6f7d01b01308', 'e046851c-13f9-4764-9cbc-1c27fe527d0d', 'c', 'Dos luces todo horizonte en línea vertical, blanca la superior y verde la inferior.', false, '2025-09-13 13:53:10.686046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('269fc6e7-d2cb-4038-b873-13dde2b1c4f4', 'e046851c-13f9-4764-9cbc-1c27fe527d0d', 'd', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', true, '2025-09-13 13:53:10.686182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84a0fc23-ecf9-4593-89ca-fa9833728006', '6fae02a4-68cb-4584-aa82-aab176bc502f', 'a', 'Una demora menor de 225 grados a popa del través de este último.', false, '2025-09-13 13:53:10.68645+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca810ef9-812f-4f69-a308-192a8695c7b6', '6fae02a4-68cb-4584-aa82-aab176bc502f', 'b', 'Una marcación mayor de 22,5 grados a proa del través de este último.', false, '2025-09-13 13:53:10.686577+00');
