INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ab3312a-c454-40fa-8916-05542404c610', '6976d7d9-6f2c-44f3-b506-45d9ec81b993', 'd', 'Un barco fondea a la gira cuando utiliza dos anclas, cuyas líneas de fondeo forman un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:10.696733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f75ff356-9d76-42d0-9f5d-6f9219ef0dca', '87789e7c-5b5a-4923-900b-4a06e55c04e4', 'a', 'Evitar nadar y mantener una posición fetal en el agua con el chaleco salvavidas puesto.', false, '2025-09-13 13:53:10.697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64e6acb3-aadf-487f-8a96-16e59d17154c', '87789e7c-5b5a-4923-900b-4a06e55c04e4', 'b', 'Abrigar al afectado a resguardo del viento.', false, '2025-09-13 13:53:10.697142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c5b0668-5c0f-4a6e-8707-517faee329a9', '87789e7c-5b5a-4923-900b-4a06e55c04e4', 'c', 'Mantener al afectado con la ropa puesta y frotar enérgicamente para que entre en calor.', true, '2025-09-13 13:53:10.697291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59b8745f-1928-4d3c-9b2d-70ad79b44606', '87789e7c-5b5a-4923-900b-4a06e55c04e4', 'd', 'Trasladar al afectado en posición horizontal.', false, '2025-09-13 13:53:10.697421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa91071c-79d9-4a7d-ab1f-9d34f665edc5', '13690b66-9c61-4bb5-98fd-055c1a755936', 'a', 'Si tiene una instalación eléctrica de más de 50 voltios, uno de los extintores debe ser adecuado para riesgo eléctrico.', false, '2025-09-13 13:53:10.697688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1763b8bc-f49c-459d-995e-08497c033667', '13690b66-9c61-4bb5-98fd-055c1a755936', 'b', 'Si se dedica a fines comerciales o lucrativos llevará un extintor adicional al que tiene que llevar reglamentariamente.', false, '2025-09-13 13:53:10.697832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a52e9ba-1b36-48dc-baa1-7c6d46670bf8', '13690b66-9c61-4bb5-98fd-055c1a755936', 'c', 'Aunque lleve instalados un sistema fijo de contraincendios debe llevar al menos un extintor.', false, '2025-09-13 13:53:10.69799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d98846d-0dff-4d02-a400-1c32c0b752dc', '13690b66-9c61-4bb5-98fd-055c1a755936', 'd', 'Llevará al menos un extintor y todos ellos se estibarán en una zona de fácil acceso y alejada del puesto principal de gobierno de la embarcación.', true, '2025-09-13 13:53:10.698128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9421fa14-3215-408b-b37a-7bd3ca299dc6', '171924d6-a43b-4f68-9e17-90dd04107c46', 'a', '091.', false, '2025-09-13 13:53:10.69841+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18cde766-3e32-4579-8ed9-48f4a78307c3', '171924d6-a43b-4f68-9e17-90dd04107c46', 'b', '900 112 112.', false, '2025-09-13 13:53:10.69854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc86094b-6034-451d-bc5b-437b27434aa2', '171924d6-a43b-4f68-9e17-90dd04107c46', 'c', '900 102 102.', false, '2025-09-13 13:53:10.698676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4a55772-7785-4749-a441-f3711882d5b5', '171924d6-a43b-4f68-9e17-90dd04107c46', 'd', '900 202 202.', true, '2025-09-13 13:53:10.698936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51952874-67e2-4238-8d8a-9baabbf8bccf', 'd02b8cae-e7a2-4d48-9ea5-79d5ebbdaba8', 'a', 'A correr el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.699218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59d6e0eb-835a-4331-ba57-073cf953162c', 'd02b8cae-e7a2-4d48-9ea5-79d5ebbdaba8', 'b', 'A capear el temporal en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.699351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bac16490-5c48-4094-8b11-8b77ee275d99', 'd02b8cae-e7a2-4d48-9ea5-79d5ebbdaba8', 'c', 'A navegar con la proa a la mar para evitar el vuelco del barco en condiciones de mal tiempo.', false, '2025-09-13 13:53:10.69948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc1f50dd-9410-4e76-9805-9bed3ea20104', 'd02b8cae-e7a2-4d48-9ea5-79d5ebbdaba8', 'd', 'A la estiba y trinca más adecuadas a bordo de los objetos, carga, aparejos, etc., para que no se muevan durante condiciones de mal tiempo.', true, '2025-09-13 13:53:10.699609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fb165d7-d676-4947-84b4-a8668ed3de74', '14d36173-f878-4e41-8218-f6c6b9f3bd3c', 'a', 'A una distancia inferior a 3 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.699897+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90da89c6-9c89-4852-9dbe-1326d1727919', '14d36173-f878-4e41-8218-f6c6b9f3bd3c', 'b', 'Dentro de zona 7, utilizando una instalación de tratamiento de aguas sucias, y que el efluente produzca sólidos flotantes visibles y ocasione coloración en las aguas circundantes.', false, '2025-09-13 13:53:10.700028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('620f19e7-2e8d-41a4-b4dc-7b25ee8e34c2', '14d36173-f878-4e41-8218-f6c6b9f3bd3c', 'c', 'Fuera de aguas costeras protegidas, puertos, radas, rías, bahías abrigadas y aguas protegidas en general, utilizando una instalación de tratamiento de aguas sucias y que el efluente no produzca sólidos flotantes visibles ni ocasione coloración en las aguas circundantes.', true, '2025-09-13 13:53:10.700159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcfd67b7-dbde-4d5d-b663-b2ff39407bec', '14d36173-f878-4e41-8218-f6c6b9f3bd3c', 'd', 'A una distancia inferior a 12 millas náuticas de la tierra más próxima, entendida esta como la línea de base a partir de la cual se establece el mar territorial, si las aguas sucias no han sido previamente desmenuzadas y desinfectadas mediante un sistema que cumpla las prescripciones del artículo 22.3.c) del citado real decreto.', false, '2025-09-13 13:53:10.700289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a8f3848-914e-4660-9bed-a88a92a028fc', '22fca24e-7991-4943-9703-a1a625f77363', 'a', 'Está obligado a acudir a toda máquina en auxilio de las personas en peligro en el mar y a transmitir la información, por todos los medios de que disponga, a los buques que se hallen', false, '2025-09-13 13:53:10.700559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8703b429-ee66-464e-a194-a65e3d6d302a', '22fca24e-7991-4943-9703-a1a625f77363', 'c', 'Está obligado a transmitir la información, por todos los medios de que disponga, a los buques que se hallen cercanos, señalando la razón por la cual no puede acudir en auxilio de las personas en', false, '2025-09-13 13:53:10.700839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3f65f29-7eec-47f0-baed-0f9e4a5fc183', '22fca24e-7991-4943-9703-a1a625f77363', 'd', 'Está obligado a informar de ello a las personas en peligro en el mar y a mantener contacto con ellos, a intervalos de no más de 3 horas, hasta que llegue al lugar otro buque y considere que el auxilio ya no es necesario.', false, '2025-09-13 13:53:10.700989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae485b12-a9e6-4a35-84fa-5533075c5326', '6ff11db0-80d6-4845-8b40-452217ab6533', 'a', 'Si tiene, esta será una esfera roja.', true, '2025-09-13 13:53:10.701268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f685f29-b768-490c-9107-faf2a2086f4d', '6ff11db0-80d6-4845-8b40-452217ab6533', 'b', 'Será dos esferas rojas superpuestas con una clara separación entre ambas.', false, '2025-09-13 13:53:10.701396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab49e1dc-16cc-4e19-a387-117d31c2ebb9', '6ff11db0-80d6-4845-8b40-452217ab6533', 'c', 'Si tiene, esta será dos esferas cuyo color será de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:10.701524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5179b1b4-807a-4004-bafe-03950eadb8c9', '6ff11db0-80d6-4845-8b40-452217ab6533', 'd', 'Será una esfera, de color a elegir, pero sin que pueda prestarse a confusión con las marcas', false, '2025-09-13 13:53:10.701651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96963280-0779-4e64-92d8-337d86e87df2', '80272070-2f94-4e5a-b78b-25f4478b266c', 'a', 'Marcas de peligro aislado.', true, '2025-09-13 13:53:10.701943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37593ee2-17a7-44b8-aa90-8641152c2767', '80272070-2f94-4e5a-b78b-25f4478b266c', 'b', 'Marcas de aguas navegables.', false, '2025-09-13 13:53:10.702077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00374f9d-10e3-4603-8301-48bee5a2e478', '80272070-2f94-4e5a-b78b-25f4478b266c', 'c', 'Marcas especiales.', false, '2025-09-13 13:53:10.702204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b29ddbc6-3804-412d-b4c6-3f88925d6dd2', '80272070-2f94-4e5a-b78b-25f4478b266c', 'd', 'Marcas cardinales norte.', false, '2025-09-13 13:53:10.702333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc626f71-0f86-405f-962e-b013f46ae78a', '9356deaf-9913-4b2d-8082-0da464444e26', 'a', 'Reciben el nombre del cuadrante en el que están colocadas.', false, '2025-09-13 13:53:10.702597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0217ad0d-64be-40eb-a552-7eef85ff06e7', '9356deaf-9913-4b2d-8082-0da464444e26', 'b', 'El nombre indica que se ha de pasar por el cuadrante correspondiente a ese nombre.', false, '2025-09-13 13:53:10.702725+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fd90f6a-ac38-45b1-bb90-89322f9b5b02', '9356deaf-9913-4b2d-8082-0da464444e26', 'c', 'Los cuatro cuadrantes (Norte, Este, Sur, Oeste) están limitados por las marcaciones NW-NE, NE-SE, SE-SW, SW-NW, tomadas desde el punto que interesa balizar.', true, '2025-09-13 13:53:10.702858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf4a9a2e-9f2b-4216-b0c3-170f8bef7adc', '9356deaf-9913-4b2d-8082-0da464444e26', 'd', 'Pueden ser utilizadas para llamar la atención sobre una configuración especial de un canal.', false, '2025-09-13 13:53:10.702989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf5a59da-b482-4086-8c64-8c096cd1a711', 'f7d19de1-c53a-4fe0-b647-a4910cb37b0a', 'a', 'El canal principal está a babor.', true, '2025-09-13 13:53:10.703388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc935519-66bd-489a-a566-5b532c8c3b0c', 'f7d19de1-c53a-4fe0-b647-a4910cb37b0a', 'b', 'El canal principal está a estribor.', false, '2025-09-13 13:53:10.703516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb92900f-dfba-4d63-be92-c2d74d9a84d7', 'f7d19de1-c53a-4fe0-b647-a4910cb37b0a', 'c', 'El canal es temporalmente no navegable.', false, '2025-09-13 13:53:10.703643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d17ef6b-49ef-4c72-83bb-4ab80a354652', 'f7d19de1-c53a-4fe0-b647-a4910cb37b0a', 'd', 'El centro del canal y debemos dejarla por nuestro babor.', false, '2025-09-13 13:53:10.703773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e63b4724-6cfe-48e2-b08e-4d543518e455', 'b69dd215-48e8-40ca-93f4-327c33563424', 'a', 'La que indica el canal principal, siguiendo el sentido convencional del balizamiento, en un punto de bifurcación de un canal.', false, '2025-09-13 13:53:10.704043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f67d078c-a3c2-4c8b-9a91-abeac8abf110', 'b69dd215-48e8-40ca-93f4-327c33563424', 'b', 'La que indica la configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:10.704171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4766b2e-73ab-430c-bd06-2aa9c20dd812', 'b69dd215-48e8-40ca-93f4-327c33563424', 'c', 'La utilizada para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.7043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc6c0e9a-ba5d-45cc-92d9-047376ddb559', 'b69dd215-48e8-40ca-93f4-327c33563424', 'd', 'La utilizada para indicar los límites de un área con peligros aislados de dimensiones limitadas. Reglamento (RIPA).', false, '2025-09-13 13:53:10.704427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdcae69d-0d2e-4cea-a344-961e2edeef37', '0cb07451-f3fa-49c9-b4de-aa2a578592eb', 'a', 'El estado del viento, mar y corriente, y la proximidad de peligros para la navegación.', false, '2025-09-13 13:53:10.704691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7e06acf-7075-4f4a-a6b8-7339e3e3df22', '0cb07451-f3fa-49c9-b4de-aa2a578592eb', 'b', 'El calado en relación con la profundidad disponible de agua.', false, '2025-09-13 13:53:10.704819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9268379-31b9-4724-9ef5-b22e3529e27f', '0cb07451-f3fa-49c9-b4de-aa2a578592eb', 'c', 'De noche, la existencia de resplandor.', false, '2025-09-13 13:53:10.704948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f6e98e3-0758-4f05-a0ae-5e21bc37293e', '0cb07451-f3fa-49c9-b4de-aa2a578592eb', 'd', 'La hora de llegada a puerto.', true, '2025-09-13 13:53:10.705081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb848895-4359-4432-bf77-61f20f11aab9', '39be70fb-6b33-4dfc-a49c-e17d41be30ec', 'a', 'Una nave de vuelo rasante que navegue por la superficie.', false, '2025-09-13 13:53:10.705348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c59a290-cf48-46eb-a7ea-eb0b6bc4b517', '39be70fb-6b33-4dfc-a49c-e17d41be30ec', 'b', 'Todo buque, al tener una capacidad de gobierno mayor que los demás.', false, '2025-09-13 13:53:10.705476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9256142-f8d3-4bce-b03e-b8c379413676', '39be70fb-6b33-4dfc-a49c-e17d41be30ec', 'c', 'Un buque con capacidad de maniobra restringida.', true, '2025-09-13 13:53:10.705602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5bbbcee-c91d-4702-b8c4-23cdfd72d91f', '39be70fb-6b33-4dfc-a49c-e17d41be30ec', 'd', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:10.705731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7673ded-6ddd-496a-b176-ad140288bcc6', 'e5a6eb86-b8ac-4b86-aabd-cd7eb72bcca7', 'a', 'En todo momento y lugar.', false, '2025-09-13 13:53:10.706054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31cea3a4-80cc-484c-b667-98e1639a31e0', 'e5a6eb86-b8ac-4b86-aabd-cd7eb72bcca7', 'b', 'Nunca.', false, '2025-09-13 13:53:10.706207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9024854-96a2-4226-831d-5cdbfa81d2f6', 'e5a6eb86-b8ac-4b86-aabd-cd7eb72bcca7', 'c', 'En la medida necesaria para poder llevar a cabo la operación de mantenimiento, cuando tengan capacidad de maniobra restringida.', true, '2025-09-13 13:53:10.706342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4917324-fade-423f-8a6a-f51320cfc60c', 'e5a6eb86-b8ac-4b86-aabd-cd7eb72bcca7', 'd', 'En la medida necesaria para poder llevar a cabo la operación de remolque portuario, cuando tengan capacidad de maniobra restringida.', false, '2025-09-13 13:53:10.706478+00');
