INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e12d6da-42e9-4085-b256-a3182abc3747', 'a1e8bf73-b10f-4a5e-a5de-d1ce54abd939', 'c', 'La escala para catalogarlos Saffir-Simpson tiene 12 categorías en función de la velocidad del', true, '2025-09-13 13:53:10.726486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a23420c7-f9d6-4f2d-ac25-32c8b7da2cee', 'a1e8bf73-b10f-4a5e-a5de-d1ce54abd939', 'd', 'Se forman en las latitudes bajas próximas a un cinturón de bajas presiones que se conoce como la I.T.C.Z. (Zona de convergencia intertropical).', false, '2025-09-13 13:53:10.726621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('809f3734-c125-498c-8b20-21979126790a', '8ecf9147-ac1f-4231-b240-3de00274654d', 'a', 'Hielo marino que se ha alveolado en el proceso de fusión y que se encuentra en un estado avanzado de desintegración.', false, '2025-09-13 13:53:10.726901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c8d9dbd-3fb0-4a11-bfa7-a868ae66300c', '8ecf9147-ac1f-4231-b240-3de00274654d', 'b', 'Hielo sobre escurrido en el que los bandejones se asemejan a dedos entrelazados o alternados uno arriba y otro abajo.', false, '2025-09-13 13:53:10.72703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('505a6337-8df1-4b4b-835e-3d24ebab0ff7', '8ecf9147-ac1f-4231-b240-3de00274654d', 'c', 'Hielo marino que sobrevive al menos un derretimiento o fusión de verano de un espesor típico de hasta 3 m o más. En la mayoría de los casos sus rasgos topográficos son más lisos que el hielo del', true, '2025-09-13 13:53:10.727159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eda3dc64-3633-49c0-9d11-81d88218ad6a', '8ecf9147-ac1f-4231-b240-3de00274654d', 'd', 'Hielo marino de cuya superficie ha desaparecido el agua líquida tras la formación de grietas y alvéolos de fusión.', false, '2025-09-13 13:53:10.727291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28d9f595-1b1e-47af-aa04-b953ea2fe397', 'df68a7e2-4c53-4613-920f-42b58e9ae240', 'a', 'Luz zodiacal.', true, '2025-09-13 13:53:10.727555+00');
