INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6411b482-922f-4fc5-9e16-d82163d86525', 'ba2a0511-32c7-4025-af9b-d19a7f55c6e0', 'a', 'Hielo marino que se ha alveolado en el proceso de fusión y que se encuentra en un estado avanzado de desintegración.', false, '2025-09-13 13:53:10.757088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3e98dce-0f0c-464e-8a20-3f76ce02ef1e', 'ba2a0511-32c7-4025-af9b-d19a7f55c6e0', 'b', 'Hielo sobre escurrido en el que los bandejones se asemejan a dedos entrelazados o alternados uno arriba y otro abajo.', true, '2025-09-13 13:53:10.757228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd352ae7-9413-46b8-b115-b831c3e63444', '58c21946-b539-4fcd-ac1b-3293441bf112', 'd', 'El buque está en aguas estables (en el presente).', true, '2025-09-13 13:53:10.766007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65c33bb4-cfe8-486b-a1df-53dd4f68a2ae', 'ba2a0511-32c7-4025-af9b-d19a7f55c6e0', 'c', 'Hielo marino que sobrevive al menos un derretimiento o fusión de verano de un espesor típico de hasta 3 m o más. En la mayoría de los casos sus rasgos topográficos son más lisos que el hielo del', false, '2025-09-13 13:53:10.757373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a13887c-ce94-4db4-a746-a559670aa9b4', 'ba2a0511-32c7-4025-af9b-d19a7f55c6e0', 'd', 'Hielo marino de cuya superficie ha desaparecido el agua líquida tras la formación de grietas y alvéolos de fusión.', false, '2025-09-13 13:53:10.757518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f278449e-c1ec-418f-affe-d0f0e493eaf7', 'fdd3274e-5ca2-4143-80cf-2707477a5d05', 'a', 'En el hemisferio norte los vientos generales del oeste se dirigen hacia el norte desde las altas presiones subtropicales.', false, '2025-09-13 13:53:10.757933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af47f142-8dc0-4688-a058-b34a4f0ed87e', 'fdd3274e-5ca2-4143-80cf-2707477a5d05', 'b', 'En el hemisferio sur los vientos alisios son de componente oeste y se dirigen hacia el cinturón subtropical de altas presiones.', false, '2025-09-13 13:53:10.75807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97cfd8a1-316a-4fb7-8a1c-9c037b440f0c', 'fdd3274e-5ca2-4143-80cf-2707477a5d05', 'c', 'Los vientos polares dominantes son de componente oeste.', false, '2025-09-13 13:53:10.758204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2e66d39-09bd-4227-9209-96415e87d781', 'fdd3274e-5ca2-4143-80cf-2707477a5d05', 'd', 'Las calmas tropicales se producen alrededor del ecuador.', true, '2025-09-13 13:53:10.758337+00');
