INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d4d7a04-e4fe-449f-9a21-88fa47d60f27', 'dce5108d-63e0-4183-a9e7-906e963f6519', 'a', 'No tienen frentes porque están constituidos por una sola masa de aire ecuatorial homogéneo.', false, '2025-09-13 13:53:10.759286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c40b497e-39e8-410f-b81a-cf146a329e84', 'dce5108d-63e0-4183-a9e7-906e963f6519', 'b', 'La energía de los ciclones tropicales proviene del calor latente de evaporación liberado por el aire muy húmedo al condensarse.', false, '2025-09-13 13:53:10.759417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca3609d0-e4d8-49c2-a32b-bee66eaf45fa', 'dce5108d-63e0-4183-a9e7-906e963f6519', 'c', 'La escala para catalogarlos Saffir-Simpson tiene 12 categorías en función de la velocidad del', false, '2025-09-13 13:53:10.759548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad06528b-cb55-4ad1-a958-b3d36e04a004', 'dce5108d-63e0-4183-a9e7-906e963f6519', 'd', 'Se forman en las latitudes bajas próximas a un cinturón de bajas presiones que se conoce como la I.T.C.Z. (Zona de convergencia intertropical).', true, '2025-09-13 13:53:10.759677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e07cf53e-5a71-42b5-a271-62123e52d854', '9d9af3f3-bfc3-4a07-85e2-45b6cc35d7b7', 'a', 'Son violentos remolinos que giran en sentido contrario a las agujas del reloj.', true, '2025-09-13 13:53:10.759996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2069203c-e0a5-408f-85bb-b739793f8ace', '9d9af3f3-bfc3-4a07-85e2-45b6cc35d7b7', 'b', 'Son una manifestación violenta procedente de nubes de desarrollo vertical (cumulonimbos) debida a la presencia en altura de aire frio y denso sobre el aire cálido y húmedo ascendente.', false, '2025-09-13 13:53:10.760134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17a3ec44-ee0f-4a40-b46a-215273fefbf1', '9d9af3f3-bfc3-4a07-85e2-45b6cc35d7b7', 'c', 'Son un fenómeno atmosférico de corta duración y que comienza y acaba de forma repentina.', false, '2025-09-13 13:53:10.76027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cf75f90-4b0b-474b-b238-ab48ddafacb3', '9d9af3f3-bfc3-4a07-85e2-45b6cc35d7b7', 'd', 'Tienen la forma de un cono invertido bajo el cumulonimbo de 10 a 20m de diámetro.', false, '2025-09-13 13:53:10.7604+00');
