INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ba09558-6c36-40cd-a3a5-f934d7ed83ef', '92ac9788-61a7-49f9-9f93-2961923730ab', 'a', 'La posición del metacentro respecto al centro de gravedad determina que el equilibrio sea estable', true, '2025-09-13 13:53:10.770733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d09c624-6cd8-40c9-9bc2-0c368f4d9286', '92ac9788-61a7-49f9-9f93-2961923730ab', 'b', 'Una embarcación con altura metacéntrica pequeña tiene mucha estabilidad.', false, '2025-09-13 13:53:10.770872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e526a59-75a3-4485-8bd0-a1c593e806fa', '92ac9788-61a7-49f9-9f93-2961923730ab', 'c', 'El centro de carena es el centro de gravedad de la obra muerta.', false, '2025-09-13 13:53:10.771005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07c3c0bc-0616-4393-bf60-8008a5b0f81c', '92ac9788-61a7-49f9-9f93-2961923730ab', 'd', 'Cuando el empuje y el peso están en la misma vertical con el barco escorado, nos encontramos ante una situación de equilibrio estable.', false, '2025-09-13 13:53:10.77114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a6afb3e-c76e-4385-bd57-7f3a05106faf', '2a59b6d4-36c4-4be9-8890-ceaa4f4e5660', 'a', 'Los extintores de dióxido de carbono (CO2) son adecuados para la extinción de fuegos de origen', false, '2025-09-13 13:53:10.771421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3984d2be-7cb6-4ec5-91bb-64c391757afc', '2a59b6d4-36c4-4be9-8890-ceaa4f4e5660', 'b', 'Las bengalas de mano deben dispararse siempre hacia barlovento, con el brazo alargado por fuera de la cubierta y con la bengala prácticamente vertical.', false, '2025-09-13 13:53:10.771559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03b2f683-baf8-4482-a9b7-782e2dd426af', '2a59b6d4-36c4-4be9-8890-ceaa4f4e5660', 'c', 'Las balsas salvavidas, una vez a flote, resistirán 30 días de exposición a la intemperie, en cualquier estado de mar.', true, '2025-09-13 13:53:10.771698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('163e4bc9-5c89-4e7f-bf5d-85bcd3fd91e0', '2a59b6d4-36c4-4be9-8890-ceaa4f4e5660', 'd', 'La utilización de un reflector de radar, en una embarcación de casco no metálico, permite un buen eco en los radares de otros buques.', false, '2025-09-13 13:53:10.771847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1514a7b9-a3d9-4b5f-bb4e-e951f7796e87', '205f4034-a595-4059-8701-2ea80a2d74cf', 'a', 'Recoger la documentación más imprescindible.', false, '2025-09-13 13:53:10.772144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45adbf61-c723-4f4d-af2c-969ee7b9ae02', '205f4034-a595-4059-8701-2ea80a2d74cf', 'b', 'Despejar la cubierta de todo material y equipos que puedan salir volando.', false, '2025-09-13 13:53:10.772385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eccb2970-6d98-4073-9b55-0f91867f8b2d', '205f4034-a595-4059-8701-2ea80a2d74cf', 'c', 'Antes de la llegada del helicóptero, contactar con sus tripulantes realizando una LSD.', true, '2025-09-13 13:53:10.772525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6065e0e8-b5e8-4c9d-b87f-43f7f4ea041f', '205f4034-a595-4059-8701-2ea80a2d74cf', 'd', 'En veleros, arriar las velas y arrancar el motor.', false, '2025-09-13 13:53:10.772665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0184e0cd-85b1-4671-8244-a8437b90ebe5', 'ecab065e-f4e1-4e43-8885-4968c6de0582', 'a', 'Es obligatorio llevar un aro salvavidas con luz y rabiza.', false, '2025-09-13 13:53:10.772958+00');
