INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a405ad2b-6840-4ad3-9dee-adf71aeb385e', 'ecab065e-f4e1-4e43-8885-4968c6de0582', 'c', 'El número total de chalecos salvavidas dotados con luz será igual al número de personas a bordo y tendrá una flotabilidad mínima de 100 N.', false, '2025-09-13 13:53:10.773232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('012e93b6-4aa7-4cef-afbb-f34247526fc5', 'ecab065e-f4e1-4e43-8885-4968c6de0582', 'd', 'La embarcación estará dotada con dos baldes con capacidad mínima de 5 litros.', false, '2025-09-13 13:53:10.773372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa5c829e-a9c5-4423-833b-cc0320762241', 'e12d3db3-1644-4580-b710-5f7e519bedd9', 'a', 'Varía la posición de los centros de gravedad y de carena.', false, '2025-09-13 13:53:10.77366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ee508e3-5098-44d3-b2d1-80075433554d', 'e12d3db3-1644-4580-b710-5f7e519bedd9', 'b', 'Varía la posición del centro de gravedad, pero no la del centro de carena.', false, '2025-09-13 13:53:10.773814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16c23297-d57a-4bc0-af1d-f741ccb8e626', 'e12d3db3-1644-4580-b710-5f7e519bedd9', 'c', 'Varía la posición del centro de carena, pero no la del centro de gravedad.', false, '2025-09-13 13:53:10.773951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8686e8db-1619-445e-9b88-14c8ddd959b9', 'e12d3db3-1644-4580-b710-5f7e519bedd9', 'd', 'Las posiciones de los centros de gravedad y de carena no varían.', true, '2025-09-13 13:53:10.774089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26082076-aa81-4f1e-b9aa-bbb5bb26bff7', '0383292e-f3c5-4518-bcfd-0223d355b810', 'a', 'Encender una bengala.', false, '2025-09-13 13:53:10.774392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35f2c44a-af36-43b4-bb0a-1b9be1f49e83', '0383292e-f3c5-4518-bcfd-0223d355b810', 'b', 'Lanzar un cohete provisto de paracaídas.', false, '2025-09-13 13:53:10.774544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b798302-e26c-4376-9ed7-7ddf2107957a', '0383292e-f3c5-4518-bcfd-0223d355b810', 'c', 'Lanzar un bote fumígeno.', false, '2025-09-13 13:53:10.774707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('943e0dfa-ec0b-4e0a-a732-4213e6e5b390', '0383292e-f3c5-4518-bcfd-0223d355b810', 'd', 'Hacer señales con espejos.', true, '2025-09-13 13:53:10.774856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('957c8726-c122-4ede-8be8-5c5b9b2f9c13', '00bf56d2-83f6-41e5-a8bf-9ff7a87f2697', 'a', 'Emiten en la frecuencia de 406 Mhz.', true, '2025-09-13 13:53:10.775152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dc2e1e4-7a2e-4d08-85fb-667dee3e856c', '00bf56d2-83f6-41e5-a8bf-9ff7a87f2697', 'b', 'Deben tener una batería de al menos 24 horas de duración.', false, '2025-09-13 13:53:10.775287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1293f6a-d86f-4360-ab78-a729483f359d', '00bf56d2-83f6-41e5-a8bf-9ff7a87f2697', 'c', 'Sólo se activan cuando actúa la zafa hidrostática.', false, '2025-09-13 13:53:10.775428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5ac5980-b28e-422f-9e77-344702ab04b4', '00bf56d2-83f6-41e5-a8bf-9ff7a87f2697', 'd', 'Deben tener obligatoriamente botón de “auto test”.', false, '2025-09-13 13:53:10.775567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('023e71f7-8e6b-4b65-bd65-0c150120d4ce', '517e2b03-4310-44a1-8b8e-287d6a8fbca6', 'a', 'Requiere una revisión de su estado cada 2 años.', false, '2025-09-13 13:53:10.775857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3498592e-f8ea-4b93-ae2f-3e016f4fab9f', '41decd89-5a54-409f-ae27-afea04f2ae58', 'c', '028º.', false, '2025-09-13 13:53:10.971145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f77cbcff-1076-43b4-83e8-952021fe344c', '517e2b03-4310-44a1-8b8e-287d6a8fbca6', 'b', 'No requiere mantenimiento. Requiere reemplazo 5 años después de la instalación a bordo.', false, '2025-09-13 13:53:10.775993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('842061af-6e84-4ed0-8073-869835685bbd', '517e2b03-4310-44a1-8b8e-287d6a8fbca6', 'c', 'Debe estar homologada y permite sujetar los aparatos de emergencia (balsas, balizas, etc.) al buque de una forma segura, permitiendo su disparo a flote automáticamente en caso de hundimiento.', true, '2025-09-13 13:53:10.776145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afa73709-aea6-4419-8934-753f1978c269', '517e2b03-4310-44a1-8b8e-287d6a8fbca6', 'd', 'El mecanismo se activa automáticamente, en caso de hundimiento, en una profundidad de entre 4 y 5 m, lo que permite inflar y separar la balsa salvavidas del barco que se hunde. Meteorología', false, '2025-09-13 13:53:10.77629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('456b42d7-abf3-4c5f-9a93-7daaef704d1d', '30c80c0d-e7a1-499d-8c33-268cd8a933da', 'a', 'El tiempo transcurrido entre el paso de una cresta y un seno consecutivos, por el mismo lugar.', false, '2025-09-13 13:53:10.776687+00');
