INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ee95cc2-74fc-44cc-b671-de2abb71b66e', '773847ae-1741-43bf-9b99-48986bec174a', 'd', 'El efecto Coriolis.', false, '2025-09-13 13:53:10.777832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c30d5ca-4d8f-453f-8b8d-ec4008bddd6f', 'acabcb7d-4874-4529-8abf-4cab1872cded', 'a', 'Nunca puede alcanzarse su valor máximo en una masa de aire ya que éste se transformaría en una', true, '2025-09-13 13:53:10.778135+00');
