INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c617dc0-5b2d-4950-bc58-ef5c6b6d9956', 'acabcb7d-4874-4529-8abf-4cab1872cded', 'c', 'Su valor mínimo se alcanza en el Punto de Rocío.', false, '2025-09-13 13:53:10.778405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6583a125-1b37-42ca-a968-c5d8fadb691f', 'acabcb7d-4874-4529-8abf-4cab1872cded', 'd', 'Su valor se expresa en tanto por ciento.', false, '2025-09-13 13:53:10.778537+00');
