INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07a0563f-b33e-4c49-81ea-25146c86e250', '97f9e585-6bdf-4204-b719-eb425977746e', 'b', 'Con el ascenso de una masa de aire húmedo, que se comprime y enfría.', false, '2025-09-13 13:53:10.778945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc738fdc-03d5-4cf6-804a-68c5e05296c7', '97f9e585-6bdf-4204-b719-eb425977746e', 'c', 'Con el descenso de una masa de aire húmedo, que se expande y enfría.', false, '2025-09-13 13:53:10.77908+00');
