INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7f86c56-85d5-4d3f-9e2e-57ee7d67defe', '299eab29-9fcc-4b9b-b9d8-d9457bee7873', 'd', 'La relación entre la presión de vapor efectiva y la tensión del vapor saturante con respecto al agua a la misma temperatura y presión es la mínima posible.', true, '2025-09-13 13:53:10.780574+00');
