INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de0eeb81-6eaa-4470-849a-ebb75bff5173', '831295d0-b323-4cc3-b079-5d43d5f2d470', 'd', 'Entraremos en las tablas psicrométricas con los valores tomados en el psicrómetro del termómetro seco y la temperatura del agua de mar.', false, '2025-09-13 13:53:10.781274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d78ab345-06e4-439d-9cc2-ccf13289efbb', '2fa1bc16-fa61-428d-a6c4-34b0a9a09c8d', 'a', 'Son líneas que unen puntos con igual valor de temperatura en una superficie dada.', true, '2025-09-13 13:53:10.781679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acc64f29-15dd-4e0c-a1cb-aeeeea1d77c6', '2fa1bc16-fa61-428d-a6c4-34b0a9a09c8d', 'b', 'Son líneas paralelas y concéntricas al nivel del mar.', false, '2025-09-13 13:53:10.781813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8334b0e7-0548-440b-bb54-7a941c2152ed', '2fa1bc16-fa61-428d-a6c4-34b0a9a09c8d', 'c', 'Son líneas paralelas y concéntricas a una altura dada.', false, '2025-09-13 13:53:10.781946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e1f84f0-40b8-4cae-b401-475b47da26bc', '2fa1bc16-fa61-428d-a6c4-34b0a9a09c8d', 'd', 'La proximidad entre ellas indica variaciones de presión más bruscas.', false, '2025-09-13 13:53:10.78209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('001001e3-09ce-451d-828c-fbbb01f502bd', '639e1719-fce4-468a-a1b6-35543c8292be', 'a', 'Berg.', false, '2025-09-13 13:53:10.782372+00');
