INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9129559f-c1a7-4966-a7e1-d866011f8fc8', '82fc689c-212b-4eca-abb5-72aa76b91921', 'a', 'El rumbo verdadero es la suma algebraica del rumbo de superficie y el rumbo efectivo.', false, '2025-09-13 13:53:10.783717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('838bfc80-30b3-4532-9bc8-83e867e59f64', '82fc689c-212b-4eca-abb5-72aa76b91921', 'b', 'El rumbo de superficie es la suma algebraica del rumbo verdadero y el ángulo de abatimiento.', false, '2025-09-13 13:53:10.783873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fe2456f-2f99-43e6-8ea5-62221d258b99', '82fc689c-212b-4eca-abb5-72aa76b91921', 'c', 'El abatimiento es el desvío del rumbo debido a la corriente.', true, '2025-09-13 13:53:10.784008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce538511-355f-4ef7-bb15-32392b66c5ed', '82fc689c-212b-4eca-abb5-72aa76b91921', 'd', 'El rumbo efectivo es el rumbo resultante teniendo en cuenta únicamente el desvío producido por la acción del viento.', false, '2025-09-13 13:53:10.784146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d64b4a65-b24c-4e55-bc26-9ea0912732b5', '5cecec99-b1b4-46a9-9235-1f83fc8f33cf', 'a', 'El efecto de la corriente sobre la embarcación.', false, '2025-09-13 13:53:10.784433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4b723e3-aa74-46de-8ca5-08c2d3c00365', '5cecec99-b1b4-46a9-9235-1f83fc8f33cf', 'b', 'El ángulo que se forma entre la línea de crujía y el rumbo de superficie.', false, '2025-09-13 13:53:10.784574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86da58c9-39db-451e-a2bd-9dd1e898fc05', '5cecec99-b1b4-46a9-9235-1f83fc8f33cf', 'c', 'El ángulo entre la línea de crujía y la estela del barco, en el caso de no haber corriente.', true, '2025-09-13 13:53:10.784708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b696789-fb51-4497-bd85-4db9dc918845', '5cecec99-b1b4-46a9-9235-1f83fc8f33cf', 'd', 'El ángulo entre el rumbo de aguja y el rumbo efectivo, en el caso de no haber viento.', false, '2025-09-13 13:53:10.784848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64284522-cb04-4668-b55c-dfecc89c6962', '1a14d401-b4fa-4d61-ba9e-e711cd44ef38', 'a', 'Se aplique el filtro de perturbaciones de lluvia (rain clutter) al 100% para eliminar totalmente los chubascos y percibir el tráfico con más detalle.', true, '2025-09-13 13:53:10.785136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bf59cf7-88ce-4680-9fcc-51f1ac397b3f', '1a14d401-b4fa-4d61-ba9e-e711cd44ef38', 'b', 'Se aplique el filtro de perturbaciones de lluvia (rain clutter) con precaución, teniendo siempre en cuenta que su aplicación podría eliminar ecos de embarcaciones pequeñas.', false, '2025-09-13 13:53:10.785271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cff761c3-7c67-47c5-86e8-67941aec6dc1', '1a14d401-b4fa-4d61-ba9e-e711cd44ef38', 'c', 'Se aplique el filtro de perturbaciones de mar (sea clutter) para eliminar totalmente las perturbaciones producidas en la superficie del mar por la lluvia.', false, '2025-09-13 13:53:10.785408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3344c1f4-3f3c-478c-a262-854165c33d36', '1a14d401-b4fa-4d61-ba9e-e711cd44ef38', 'd', 'No se aplique el filtro de perturbaciones de lluvia (rain clutter) ya que esto eliminaría los ecos del', false, '2025-09-13 13:53:10.78554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca177a1a-9407-4bb4-9982-ed4254cc35e5', 'f04e67c6-b499-496d-abc4-5750167c09d8', 'a', 'Aunque una embarcación lleve AIS, éste no tiene por qué estar en funcionamiento si la embarcación está fondeada.', true, '2025-09-13 13:53:10.785824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('233568cb-83e2-4514-bde7-d5c3605aeb21', 'f04e67c6-b499-496d-abc4-5750167c09d8', 'b', 'El AIS puede considerarse como sustituto del radar ya que permite tomar demoras.', false, '2025-09-13 13:53:10.785962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c226daa-67ff-42f8-8466-e17a99fc3e33', 'f04e67c6-b499-496d-abc4-5750167c09d8', 'c', 'El AIS puede superar una elevación o el recodo de un canal indicando la posición de un buque que de otra forma no aparecería en los radares.', false, '2025-09-13 13:53:10.786097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59f77385-afac-497c-8977-b65868b6c387', 'f04e67c6-b499-496d-abc4-5750167c09d8', 'd', 'Entre la información que transmite el AIS están el nombre de la embarcación, identificación de llamada selectiva digital (MMSI), posición, rumbo y velocidad, pero en ningún caso dimensiones de la embarcación.', false, '2025-09-13 13:53:10.786241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79d4d150-ac96-4721-8823-ccdeb0a402bb', 'b673f8d8-633b-470b-bea9-50341cb59e14', 'a', 'El Ministerio de Transportes, Movilidad y Agenda Urbana.', true, '2025-09-13 13:53:10.786666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b97563a-06bc-43bb-8264-725f00887f1d', 'b673f8d8-633b-470b-bea9-50341cb59e14', 'b', 'El Instituto Hidrográfico de la Marina.', false, '2025-09-13 13:53:10.786807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77a350e9-163d-447e-95ee-59f5a7adb65c', 'b673f8d8-633b-470b-bea9-50341cb59e14', 'c', 'La Sociedad de Salvamento y Seguridad Marítima (SASEMAR).', false, '2025-09-13 13:53:10.786953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fd7c9aa-f003-42f5-8892-b1ef82d7fb42', 'b673f8d8-633b-470b-bea9-50341cb59e14', 'd', 'La Dirección General de la Marina Mercante.', false, '2025-09-13 13:53:10.787088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61a4a8ad-2883-45d3-a4ce-899aaddba5d5', 'abd75625-9fd1-4d22-adeb-d75eb677b899', 'a', 'Es el ángulo entre la dirección del norte verdadero y el norte de aguja.', false, '2025-09-13 13:53:10.787376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92168eac-54ec-48be-93c2-e80de3077383', 'abd75625-9fd1-4d22-adeb-d75eb677b899', 'b', 'Es la suma algebraica de la declinación magnética y el desvío del compás.', true, '2025-09-13 13:53:10.787511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d976da96-8d82-4db1-a621-d305a952e197', 'abd75625-9fd1-4d22-adeb-d75eb677b899', 'c', 'Su valor en un punto dado permanece invariable en el tiempo.', false, '2025-09-13 13:53:10.787647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('743171b5-1d43-4372-8466-8987be2546de', 'abd75625-9fd1-4d22-adeb-d75eb677b899', 'd', 'Su valor depende de los hierros de cada barco y del rumbo.', false, '2025-09-13 13:53:10.787783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a616b7e3-987f-4626-9c13-c5a6d59983df', '73c22808-1c9a-4820-997a-7740e561c835', 'a', 'La latitud es el arco de meridiano contado desde el ecuador hasta el observador y se cuenta de 0º', true, '2025-09-13 13:53:10.788068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f156683d-ae5a-4062-b147-94900221415e', '73c22808-1c9a-4820-997a-7740e561c835', 'b', 'La longitud es el arco de meridiano que va desde Greenwich hasta el observador y se cuenta de 0º', false, '2025-09-13 13:53:10.788202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d356147e-94cf-4be5-acb4-46d199ed449e', '73c22808-1c9a-4820-997a-7740e561c835', 'c', 'La diferencia en latitud es el arco de meridiano entre dos paralelos, que es igual a la latitud de llegada menos la latitud de salida, pudiendo ser norte o sur y siempre menor de 180º.', false, '2025-09-13 13:53:10.788336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cac7202-e9d0-4e19-9d7b-c9fb50d43922', '73c22808-1c9a-4820-997a-7740e561c835', 'd', 'La diferencia de longitud es el arco de ecuador entre dos meridianos, que es igual a la longitud de llegada menos la longitud de salida, pudiendo ser este u oeste y siempre menor de 90º.', false, '2025-09-13 13:53:10.788469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9df9a12-a5ac-4dc5-a0f5-6b81ff6691c1', 'a0e6e6af-4f3b-4a74-99e0-8b92a4509e84', 'a', 'Extra Track Enhance.', false, '2025-09-13 13:53:10.788749+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b1cf419-a524-4647-aab1-0b88ed1ea778', 'a0e6e6af-4f3b-4a74-99e0-8b92a4509e84', 'b', 'Extra Track Error.', true, '2025-09-13 13:53:10.788894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f83348f-84d9-4594-b885-5ef72241b0fd', 'a0e6e6af-4f3b-4a74-99e0-8b92a4509e84', 'c', 'X-ray Track Enhance.', false, '2025-09-13 13:53:10.789028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aeea0a0-fc18-411e-acd2-f75e228cfbaf', 'a0e6e6af-4f3b-4a74-99e0-8b92a4509e84', 'd', 'Cross Track Error.', false, '2025-09-13 13:53:10.789168+00');
