INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5cc71a0-db92-4c05-bc64-5252162e1bf4', '61a71925-32f4-4843-a667-b73742c680bd', 'd', 'Con la diferencia del desvío de aguja y la declinación magnética.', true, '2025-09-13 13:53:10.789865+00');
