INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c2d5d16-be73-4da2-bcb7-9f24310f4cc6', '17da0512-a4a8-43c9-8d02-431d4ac90b23', 'b', 'Ref=145°; Ra=149°.', false, '2025-09-13 13:53:10.798039+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd446050-c41e-4693-8fe5-89b5c9f99f3b', '17da0512-a4a8-43c9-8d02-431d4ac90b23', 'c', 'Ref=145°; Ra=145°.', true, '2025-09-13 13:53:10.798173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf5bf1c6-fc75-4659-8726-aefd626dbddc', '17da0512-a4a8-43c9-8d02-431d4ac90b23', 'd', 'Ref=149°; Ra=145°. DE TRANSPORTES, MOVILIDAD                                                                         DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                   Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 02 Seguridad en la mar', false, '2025-09-13 13:53:10.798306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd4f7248-2156-43bf-a31c-43c3da5bea3e', 'a78e5f5e-86c0-47d8-8ebf-1bc556590f36', 'a', 'Requiere una revisión de su estado cada 2 años.', true, '2025-09-13 13:53:10.79878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('392ba312-5335-4bf9-8274-fc61476a9a6f', 'a78e5f5e-86c0-47d8-8ebf-1bc556590f36', 'b', 'No requiere mantenimiento. Requiere reemplazo 5 años después de la instalación a bordo.', false, '2025-09-13 13:53:10.798922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f47407ae-c832-4bed-ad57-d2afb9d1ae50', 'a78e5f5e-86c0-47d8-8ebf-1bc556590f36', 'c', 'Debe estar homologada y permite sujetar los aparatos de emergencia (balsas, balizas, etc.) al buque de una forma segura, permitiendo su disparo a flote automáticamente en caso de hundimiento.', false, '2025-09-13 13:53:10.799054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('797d645b-c387-4b6e-9527-b33973f0b4a9', 'a78e5f5e-86c0-47d8-8ebf-1bc556590f36', 'd', 'El mecanismo se activa automáticamente, en caso de hundimiento, en una profundidad de entre 4 y 5 m, lo que permite inflar y separar la balsa salvavidas del barco que se hunde.', false, '2025-09-13 13:53:10.799196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7aa51af3-b72a-4174-82dd-96ab6dec73c7', '6fd1d3e7-3de0-46a1-af7a-63565a7bbb33', 'a', 'La posición del metacentro respecto al centro de gravedad determina que el equilibrio sea estable', false, '2025-09-13 13:53:10.79948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59481e9e-bb98-4358-b6a6-dd5ab0b1aeae', '6fd1d3e7-3de0-46a1-af7a-63565a7bbb33', 'b', 'Una embarcación con altura metacéntrica pequeña tiene mucha estabilidad.', false, '2025-09-13 13:53:10.799617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3850a98-439b-438d-9dec-018a7bacca33', '6fd1d3e7-3de0-46a1-af7a-63565a7bbb33', 'c', 'El centro de carena es el centro de gravedad de la obra muerta.', false, '2025-09-13 13:53:10.799754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e4af082-82be-4cea-900e-f02a7632a658', '6fd1d3e7-3de0-46a1-af7a-63565a7bbb33', 'd', 'Cuando el empuje y el peso están en la misma vertical con el barco escorado, nos encontramos ante una situación de equilibrio estable.', true, '2025-09-13 13:53:10.799907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8ee0971-64fe-4a3a-b4fd-4fd9a6e5b967', 'db7e8227-c288-41b3-b075-199375145cd9', 'a', 'Aumenta la altura metacéntrica y el buque gana estabilidad.', true, '2025-09-13 13:53:10.800199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f40b1929-e181-4f8e-8219-7982ff7efeaa', 'db7e8227-c288-41b3-b075-199375145cd9', 'b', 'Disminuye la altura metacéntrica y el buque pierde estabilidad.', false, '2025-09-13 13:53:10.800338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e382a8e-1540-4173-b22f-442ac7d962b8', 'db7e8227-c288-41b3-b075-199375145cd9', 'c', 'Aumenta la altura metacéntrica y el buque pierde estabilidad.', false, '2025-09-13 13:53:10.800475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63155d33-62d1-4512-886a-66678fc9a194', 'db7e8227-c288-41b3-b075-199375145cd9', 'd', 'Disminuye la altura metacéntrica y el buque gana estabilidad.', false, '2025-09-13 13:53:10.800612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e93dfbb8-c53d-45e6-a46a-2c32ea7b6a82', 'b29d94f1-ec5b-4036-a533-044011497cbc', 'a', 'Es obligatorio llevar un aro salvavidas con luz y rabiza.', false, '2025-09-13 13:53:10.800932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1c8e286-f6bb-44bd-a1a9-004cea1670bb', 'b29d94f1-ec5b-4036-a533-044011497cbc', 'b', 'La balsa o balsas salvavidas tendrán capacidad para el total de personas a bordo y dispondrán de paquete de emergencia SOLAS tipo B.', true, '2025-09-13 13:53:10.801189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8737742-db83-47d6-a6d9-71bcd7099c78', 'b29d94f1-ec5b-4036-a533-044011497cbc', 'c', 'El número total de chalecos salvavidas dotados con luz será igual al número de personas a bordo y tendrá una flotabilidad mínima de 100 N.', false, '2025-09-13 13:53:10.801329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25bc14de-938e-4042-aa4d-707332d475bd', 'b29d94f1-ec5b-4036-a533-044011497cbc', 'd', 'La embarcación estará dotada con dos baldes con capacidad mínima de 5 litros.', false, '2025-09-13 13:53:10.801466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80f1e983-56c0-4c9b-ba75-d8fd9f461e0b', '4c9ec927-ea1c-4993-a3ae-cdd3ef1d78c0', 'a', 'Varía la posición de los centros de gravedad y de carena.', false, '2025-09-13 13:53:10.801754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80475f0c-5395-4f2b-b707-653f496fde94', '4c9ec927-ea1c-4993-a3ae-cdd3ef1d78c0', 'b', 'Varía la posición del centro de gravedad, pero no la del centro de carena.', false, '2025-09-13 13:53:10.801903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31adcd92-898a-49c2-821c-e42a2aa9058c', '4c9ec927-ea1c-4993-a3ae-cdd3ef1d78c0', 'c', 'Varía la posición del centro de carena, pero no la del centro de gravedad.', false, '2025-09-13 13:53:10.802036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7da0f3a-04f0-4dd5-bf71-587f81d95a6e', '4c9ec927-ea1c-4993-a3ae-cdd3ef1d78c0', 'd', 'Las posiciones de los centros de gravedad y de carena no varían.', true, '2025-09-13 13:53:10.802172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6897ed3-31f7-41f7-85a5-843e63bbd452', '551f1db7-71ac-4deb-89f6-7e049d7de785', 'a', 'Encender una bengala.', false, '2025-09-13 13:53:10.802446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6790a16c-388c-4135-afcb-25d399c4fbe9', '551f1db7-71ac-4deb-89f6-7e049d7de785', 'b', 'Lanzar un cohete provisto de paracaídas.', false, '2025-09-13 13:53:10.80258+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb3f3ccb-47f2-4610-92dc-3536fc916fc1', '551f1db7-71ac-4deb-89f6-7e049d7de785', 'c', 'Lanzar un bote fumígeno.', false, '2025-09-13 13:53:10.802732+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6101ff10-d1ad-4bf5-9887-e3e8b2c8cfb2', '551f1db7-71ac-4deb-89f6-7e049d7de785', 'd', 'Hacer señales con espejos.', true, '2025-09-13 13:53:10.80287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb25fa9-87d3-4d70-873c-e1e94d5cad2b', 'ad17c45c-8823-4d29-84eb-ba9f8b405292', 'a', 'Recoger la documentación más imprescindible.', false, '2025-09-13 13:53:10.803157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('618a73f6-85d1-4cbf-8d13-7000b81f1c4b', 'ad17c45c-8823-4d29-84eb-ba9f8b405292', 'b', 'Despejar la cubierta de todo material y equipos que puedan salir volando.', false, '2025-09-13 13:53:10.803298+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a26ca52d-6abd-4bea-8735-a85400878d41', 'ad17c45c-8823-4d29-84eb-ba9f8b405292', 'c', 'Antes de la llegada del helicóptero, contactar con sus tripulantes realizando una LSD.', true, '2025-09-13 13:53:10.80344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64249aa7-e918-4059-b483-5863559a499d', 'ad17c45c-8823-4d29-84eb-ba9f8b405292', 'd', 'En veleros, arriar las velas y arrancar el motor.', false, '2025-09-13 13:53:10.803573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ce6fcfb-418f-4d01-b9b4-c2b6079fb0b4', '81f090be-adb3-425d-82a7-925602f286c9', 'a', 'Los extintores de dióxido de carbono (CO2) son adecuados para la extinción de fuegos de origen', false, '2025-09-13 13:53:10.803877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('751ee259-442b-4b9a-86fc-acc1069dce5b', '81f090be-adb3-425d-82a7-925602f286c9', 'b', 'Las bengalas de mano deben dispararse siempre hacia barlovento, con el brazo alargado por fuera de la cubierta y con la bengala prácticamente vertical.', true, '2025-09-13 13:53:10.804042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1de0cb00-d73d-456d-896e-1f934d40eab2', '81f090be-adb3-425d-82a7-925602f286c9', 'c', 'Las balsas salvavidas, una vez a flote, resistirán 30 días de exposición a la intemperie, en cualquier estado de mar.', false, '2025-09-13 13:53:10.804187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9cb46c09-c419-4f08-8ab8-dd7f98d3f793', '81f090be-adb3-425d-82a7-925602f286c9', 'd', 'La utilización de un reflector de radar, en una embarcación de casco no metálico, permite un buen eco en los radares de otros buques.', false, '2025-09-13 13:53:10.804326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3f8f959-7c4d-4420-b87d-95e69ff21bc2', '6b037b8a-bbc3-48cb-8462-4ee9aede3bcf', 'a', 'Emiten en la frecuencia de 406 Mhz.', false, '2025-09-13 13:53:10.804633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f2df4f8-9dc1-49e5-9729-813633e6e0f6', '6b037b8a-bbc3-48cb-8462-4ee9aede3bcf', 'b', 'Deben tener una batería de al menos 24 horas de duración.', true, '2025-09-13 13:53:10.804785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30479d2d-b70b-4fb4-9438-5f7f778a0624', '6b037b8a-bbc3-48cb-8462-4ee9aede3bcf', 'c', 'Sólo se activan cuando actúa la zafa hidrostática.', false, '2025-09-13 13:53:10.804938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36f832b6-f3fa-4aa3-9988-fb5cf5d5a278', '6b037b8a-bbc3-48cb-8462-4ee9aede3bcf', 'd', 'Deben tener obligatoriamente botón de “auto test”.', false, '2025-09-13 13:53:10.805078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2a7681f-5c57-46d8-aad1-17fed7b78bdb', '46672ff7-1c1a-4fca-85fa-081241d3e5a7', 'a', 'Irán en un estuche hidrorresistente.', false, '2025-09-13 13:53:10.805374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('906ca9d1-3234-4ba6-a8ab-b5b0713d4362', '46672ff7-1c1a-4fca-85fa-081241d3e5a7', 'b', 'Arderán con un color verde brillante.', false, '2025-09-13 13:53:10.80551+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73690aa8-6298-4893-a71d-9756d7274370', '46672ff7-1c1a-4fca-85fa-081241d3e5a7', 'c', 'Tendrán medios autónomos de ignición.', true, '2025-09-13 13:53:10.805648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('562d653c-849e-452d-acff-eab32c858d42', '46672ff7-1c1a-4fca-85fa-081241d3e5a7', 'd', 'Llevará impresos en el estuche instrucciones breves o diagramas que indiquen claramente el modo de empleo. Meteorología', false, '2025-09-13 13:53:10.805783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cebf64fe-eee2-48df-8663-de1205814498', 'c02da420-9600-4a05-8a09-d360911a39e8', 'a', 'Niebla de radiación.', false, '2025-09-13 13:53:10.806066+00');
