INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99c1fd46-2647-400d-a93f-ee38916fa96e', '76a577e2-0c62-4978-b765-be570721c616', 'c', 'El AIS puede superar una elevación o el recodo de un canal indicando la posición de un buque que de otra forma no aparecería en los radares.', false, '2025-09-13 13:53:10.815454+00');
