INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6a0c212-831b-4c74-830f-65a64eaed326', '7f794270-3250-4b55-b979-1050c44f003c', 'a', 'Se aplique el filtro de perturbaciones de lluvia (rain clutter) al 100% para eliminar totalmente los chubascos y percibir el tráfico con más detalle.', false, '2025-09-13 13:53:10.815962+00');
