INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4de44543-d37d-4d8a-b92a-374f98abb147', '7f794270-3250-4b55-b979-1050c44f003c', 'd', 'No se aplique el filtro de perturbaciones de lluvia (rain clutter) ya que esto eliminaría los ecos del', false, '2025-09-13 13:53:10.816393+00');
