INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48e68aaa-a1a3-4469-b98e-78b51f1284ba', '4a74403b-b4a0-4d14-bd61-7c8ffbc458e9', 'd', 'Su valor depende de los hierros de cada barco y del rumbo.', false, '2025-09-13 13:53:10.817993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94bd928d-1ffd-4ca6-9f55-88073e0baad7', '4bf94de7-7ccf-4320-87f5-39db6bec23bb', 'a', 'La latitud es el arco de meridiano contado desde el ecuador hasta el observador y se cuenta de 0º', false, '2025-09-13 13:53:10.818282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c296ffca-ed36-4520-8937-dff94b48c8c7', '4bf94de7-7ccf-4320-87f5-39db6bec23bb', 'b', 'La longitud es el arco de meridiano que va desde Greenwich hasta el observador y se cuenta de 0º', false, '2025-09-13 13:53:10.81842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79f1f754-8819-46fa-ba8f-2073f6c78355', '4bf94de7-7ccf-4320-87f5-39db6bec23bb', 'c', 'La diferencia en latitud es el arco de meridiano entre dos paralelos, que es igual a la latitud de llegada menos la latitud de salida, pudiendo ser norte o sur y siempre menor de 180º.', false, '2025-09-13 13:53:10.818557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6029b8d-2d0e-4f3d-8369-865be5bf4097', '4bf94de7-7ccf-4320-87f5-39db6bec23bb', 'd', 'La diferencia de longitud es el arco de ecuador entre dos meridianos, que es igual a la longitud de llegada menos la longitud de salida, pudiendo ser este u oeste y siempre menor de 90º.', true, '2025-09-13 13:53:10.818703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fed63ccf-3491-4c0d-b235-823ed2a0b161', '0ec900ba-f621-4e04-8b33-1f5733dfa94e', 'a', 'Con la diferencia de la demora verdadera y la demora de aguja de una enfilación.', true, '2025-09-13 13:53:10.81901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6967dfb-fc61-40f8-ad8f-532eb9baf584', '0ec900ba-f621-4e04-8b33-1f5733dfa94e', 'b', 'Con la diferencia del norte verdadero y el azimut verdadero de la Polar.', false, '2025-09-13 13:53:10.819157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fe5c8e4-fbbb-460a-85a5-6d9417ef7d55', '0ec900ba-f621-4e04-8b33-1f5733dfa94e', 'c', 'Con la diferencia de la demora del norte verdadero y la demora de aguja de una oposición.', false, '2025-09-13 13:53:10.819292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('903074a8-4c4a-4c21-808d-ba42c0a094c9', '0ec900ba-f621-4e04-8b33-1f5733dfa94e', 'd', 'Con la diferencia del desvío de aguja y la declinación magnética.', false, '2025-09-13 13:53:10.819428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bd7f190-8db7-4bbf-ab33-6e2d857e3b0c', '081cb2e7-a8db-43d8-be5f-21912c74369c', 'a', 'El rumbo verdadero es la suma algebraica del rumbo de superficie y el rumbo efectivo.', false, '2025-09-13 13:53:10.819713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb033b97-d070-4780-bfcf-4401d8975003', '081cb2e7-a8db-43d8-be5f-21912c74369c', 'b', 'El rumbo de superficie es la suma algebraica del rumbo verdadero y el ángulo de abatimiento.', false, '2025-09-13 13:53:10.819851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccb9bd3a-8300-4c66-b5ad-11fd40f3e1d8', '081cb2e7-a8db-43d8-be5f-21912c74369c', 'c', 'El abatimiento es el desvío del rumbo debido a la corriente.', false, '2025-09-13 13:53:10.819987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2025a269-2b63-49ad-a42f-51ad860faff9', '081cb2e7-a8db-43d8-be5f-21912c74369c', 'd', 'El rumbo efectivo es el rumbo resultante teniendo en cuenta únicamente el desvío producido por la acción del viento.', true, '2025-09-13 13:53:10.820123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2fc9da5-01e1-45c4-b26b-4f44ece90151', 'bde91a5c-3156-4550-9617-2c5262c27862', 'a', 'Extra Track Enhance.', false, '2025-09-13 13:53:10.820403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23ec428f-7458-4ddd-a04c-aead95675fd8', 'bde91a5c-3156-4550-9617-2c5262c27862', 'b', 'Extra Track Error.', false, '2025-09-13 13:53:10.82054+00');
