INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ad4552b-ddf8-4145-be7b-bd9fe1b5435c', 'e868727d-1cb1-4022-bab1-4e97517ea558', 'b', 'Caña.', false, '2025-09-13 13:53:10.831025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1fee5ae-103b-4e69-8743-63c7b4579bd2', 'e868727d-1cb1-4022-bab1-4e97517ea558', 'c', 'Guardín.', false, '2025-09-13 13:53:10.831301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9ee6af3-001f-4433-8c67-76efade020aa', 'e868727d-1cb1-4022-bab1-4e97517ea558', 'd', 'Limera.', false, '2025-09-13 13:53:10.831637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0caa7f0-9e3c-485e-8f3b-282a67f1d96c', '64736ca1-e5df-47b5-b6ef-41dba5cb0ca2', 'a', 'Las hélices levógiras giran en el sentido horario para generar impulso hacia adelante.', false, '2025-09-13 13:53:10.832046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b129018c-0a3c-4016-8be8-003f4761fff2', '64736ca1-e5df-47b5-b6ef-41dba5cb0ca2', 'b', 'Las hélices dextrógiras giran en contra del sentido horario para generar impulso hacia adelante.', false, '2025-09-13 13:53:10.832219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffafec42-207a-4500-87fb-d98a166bc301', '64736ca1-e5df-47b5-b6ef-41dba5cb0ca2', 'c', 'Las hélices gemelas de giro al exterior compensan mutuamente la caída de la embarcación.', true, '2025-09-13 13:53:10.832401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a16295de-b7de-432a-a0a0-4715111c5e7f', '955e9936-01ed-4119-befd-32637af9da9a', 'c', 'Se tendrá que elegir entre luces sincronizadas o luces secuenciales, no admitiéndose una combinación de ambas.', false, '2025-09-13 13:53:10.842274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de6590c5-a75a-41d8-8bff-ef633ed97baa', '31428d39-9230-4bb9-b930-4b3b11f4ce69', 'a', 'Un noray es una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio en cubierta, sirve para amarrar los cabos.', false, '2025-09-13 13:53:10.83283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f8214b8-c689-4652-8768-5d3279937085', '31428d39-9230-4bb9-b930-4b3b11f4ce69', 'b', 'La gaza es el arco o curvatura que forma el cabo entre los extremos cuando éste no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:10.832992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52184ae3-348b-4e1e-8c96-8c64ace6623a', '31428d39-9230-4bb9-b930-4b3b11f4ce69', 'c', 'El nudo llano sirve para unir por sus chicotes dos cabos de la misma mena.', true, '2025-09-13 13:53:10.833135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3b5f355-26a4-42f0-990b-4fabd9a116b7', '31428d39-9230-4bb9-b930-4b3b11f4ce69', 'd', 'El ballestrinque es un nudo que permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:10.833275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4647abf1-7909-4066-ab61-b8022dfb87e3', '30a29ca9-209b-4f90-94ea-3cc0d8b22eed', 'a', 'Una embarcación de recreo de 6 metros de eslora tiene que llevar una línea de fondeo de 30 metros como mínimo.', false, '2025-09-13 13:53:10.83357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b830cb6-58b9-4c26-9997-af8e81c1ce5f', '30a29ca9-209b-4f90-94ea-3cc0d8b22eed', 'b', 'El círculo de borneo tiene un radio igual a la longitud de cadena filada.', true, '2025-09-13 13:53:10.833705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e33f632-9911-4cda-9866-288becc90434', '30a29ca9-209b-4f90-94ea-3cc0d8b22eed', 'd', 'Se dice que un ancla garrea cuando no se queda firme en el fondo, provocando un desplazamiento de la embarcación a sotavento.', false, '2025-09-13 13:53:10.833998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd6c82c7-83cf-4a11-baeb-daa168365664', '29b6eb8b-09b1-43d9-8c39-c68f9b1fb4b1', 'a', 'Todas las embarcaciones de recreo, independientemente de la zona de navegación.', false, '2025-09-13 13:53:10.83428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b9bad1d-da10-4a52-884c-70d3871128ac', '29b6eb8b-09b1-43d9-8c39-c68f9b1fb4b1', 'b', 'Ninguna embarcación de recreo está obligada, aunque es recomendable.', false, '2025-09-13 13:53:10.834419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a58e9ed0-1310-415f-ad59-5f3ddef70dc5', '29b6eb8b-09b1-43d9-8c39-c68f9b1fb4b1', 'c', 'Todas las embarcaciones de recreo que naveguen en zonas 1, 2, 3 o 4 y las que naveguen por la noche en zonas 5, 6 y 7.', false, '2025-09-13 13:53:10.834558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65a70a12-6eb7-4233-ad0a-e59115373ee1', '29b6eb8b-09b1-43d9-8c39-c68f9b1fb4b1', 'd', 'Todas las embarcaciones de recreo que naveguen en zonas 1, 2, 3 o 4.', true, '2025-09-13 13:53:10.834693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c4e91c0-149a-4356-b0a3-4ab075010928', 'b4c45102-72e5-4081-b76a-e02857d6cbc4', 'a', 'Ninguna está obligada, con independencia de su material de construcción.', false, '2025-09-13 13:53:10.83501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0c1bcad-8c27-40d9-9e78-58234baf68f8', 'b4c45102-72e5-4081-b76a-e02857d6cbc4', 'b', 'Las embarcaciones con casco de madera.', false, '2025-09-13 13:53:10.835186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d723f95d-9fa5-45f6-a233-fd1a25ee6691', 'b4c45102-72e5-4081-b76a-e02857d6cbc4', 'c', 'Las embarcaciones con casco de fibra.', false, '2025-09-13 13:53:10.835357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e41deee1-2b63-4766-b5e2-4abb99bd4fda', 'b4c45102-72e5-4081-b76a-e02857d6cbc4', 'd', 'Las embarcaciones con casco metálico.', true, '2025-09-13 13:53:10.835527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daa2b415-6fd7-49d6-9cb4-c6ab8416afec', '7dd71cd8-05ca-4e84-bcaf-9ad4864345fd', 'a', 'Mantenerse lo más quieto posible en posición fetal.', true, '2025-09-13 13:53:10.836118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7754e3b6-38e9-43bd-857d-5e062ae253c9', '7dd71cd8-05ca-4e84-bcaf-9ad4864345fd', 'b', 'Realizar movimientos rápidos para entrar en calor.', false, '2025-09-13 13:53:10.836285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbf40e13-dea1-4372-b487-955e96b4d4ec', '7dd71cd8-05ca-4e84-bcaf-9ad4864345fd', 'c', 'Nadar lo más rápido posible para mantener el calor.', false, '2025-09-13 13:53:10.836437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d563658-895c-4365-8a26-9366503fadc1', '7dd71cd8-05ca-4e84-bcaf-9ad4864345fd', 'd', 'Aumentar la frecuencia de respiración para que llegue mayor cantidad de oxígeno al cerebro.', false, '2025-09-13 13:53:10.836581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59a5e589-0d79-4f15-9883-6d55172b93d8', '8b564256-d6ce-42b8-ad88-a13732ff5e72', 'a', 'Cuando el periodo del balance coindice con el periodo de la ola se produce una situación de peligro que puede evitarse únicamente variando la velocidad.', false, '2025-09-13 13:53:10.83693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('965500aa-80be-45c3-aef3-934df7131bbb', '8b564256-d6ce-42b8-ad88-a13732ff5e72', 'b', 'Cuando el periodo de cabezada coincide con el periodo de la ola se produce una situación de peligro que puede evitarse atravesándose a la mar.', false, '2025-09-13 13:53:10.837099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b6eadc9-f7c0-415a-9c51-2cedd9815d79', '8b564256-d6ce-42b8-ad88-a13732ff5e72', 'c', 'Cuando el periodo de balance o el de cabezada coinciden con el de la ola se produce una situación de peligro que puede evitarse variando el rumbo o la velocidad.', true, '2025-09-13 13:53:10.837259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9b35efa-77f8-4348-8db4-0837df24a9d6', '8b564256-d6ce-42b8-ad88-a13732ff5e72', 'd', 'Cuando el periodo del balance o el de cabezada coincide con el periodo de la ola no existirá peligro y será la situación más favorable de navegación.', false, '2025-09-13 13:53:10.837443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13d2fa9c-f9f0-4fae-9d34-65fd98432f14', '3b29f44f-3288-4fca-874a-738a458596d9', 'a', 'Cuando la nacionalidad del patrón coincide con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación del país de residencia del patrón.', false, '2025-09-13 13:53:10.837808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2265f302-90ec-42ef-a61d-3fa3e970ffe6', '3b29f44f-3288-4fca-874a-738a458596d9', 'b', 'Cuando no coincidan la nacionalidad del patrón con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación del país del pabellón, si éste pertenece a la Unión Europea. En caso contrario se exigirá la titulación española requerida de acuerdo con la legislación nacional.', false, '2025-09-13 13:53:10.837967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('105c4db3-ba9e-4e17-98d9-7c5551b1c442', '3b29f44f-3288-4fca-874a-738a458596d9', 'c', 'Cuando no coincidan la nacionalidad del patrón con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación de la nacionalidad del patrón o, en su defecto, con la de su país de residencia.', false, '2025-09-13 13:53:10.83811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18b20562-83c5-4178-ba19-49eaa41b9fef', '3b29f44f-3288-4fca-874a-738a458596d9', 'd', 'Cuando la nacionalidad del patrón coincide con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación de la nacionalidad del patrón.', true, '2025-09-13 13:53:10.838252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1189558d-9093-48fe-9645-afb555643661', '86ee7477-984b-4eb9-8355-cb43cc0f921d', 'b', 'Serán solidariamente responsables para el pago de la multa que se imponga, el naviero, el propietario, el asegurador de la responsabilidad civil y el capitán o patrón, quedando además todos ellos obligados solidariamente a reparar el daño causado.', true, '2025-09-13 13:53:10.83877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43802d93-d941-488d-81c5-2492356fcfc3', '86ee7477-984b-4eb9-8355-cb43cc0f921d', 'c', 'Serán responsables del pago de la multa el propietario o naviero y, subsidiariamente el asegurador de la responsabilidad civil. El patrón o capitán ejecutará a su costa las operaciones que, con carácter de urgencia, pudieran resultar necesarias para la preservación del medio marino.', false, '2025-09-13 13:53:10.838917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3f10fea-0ba9-4fb6-8f8e-f6337622eea4', '86ee7477-984b-4eb9-8355-cb43cc0f921d', 'd', 'Será responsable del pago de la multa la persona física o jurídica propietaria de la embarcación y, subsidiariamente su capitán o patrón.', false, '2025-09-13 13:53:10.839083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eea915a5-0047-4bea-a6ce-d9aeda034eb5', '2b326303-0535-41fc-87f7-b0870635aa9e', 'a', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:10.839426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70039ddf-581a-4c34-87d8-c3bc0e8e3168', '2b326303-0535-41fc-87f7-b0870635aa9e', 'b', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:10.839591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee951f1a-1ba4-4666-b81e-4cf553862129', '2b326303-0535-41fc-87f7-b0870635aa9e', 'c', 'Franjas verticales azules y amarillas.', false, '2025-09-13 13:53:10.839753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3dfaf2d-af58-4a93-a042-5cf04902a6f5', '2b326303-0535-41fc-87f7-b0870635aa9e', 'd', 'Franjas horizontales azules y amarillas.', false, '2025-09-13 13:53:10.839939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a9d6c05-2197-40cc-a851-f63d495ef2c5', 'a04e5611-40c6-446b-9d37-98f36450e93e', 'b', 'La zona de peligro señalada es superior a 25 metros de radio desde la Marca.', false, '2025-09-13 13:53:10.840397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb091ab1-c2b3-4783-ac04-5e1b15970afa', 'a04e5611-40c6-446b-9d37-98f36450e93e', 'c', 'La zona de peligro señalada es superior a 50 metros de radio desde la Marca.', false, '2025-09-13 13:53:10.840538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0b19e71-c3dc-41ae-93fb-69efc7a695fe', 'a04e5611-40c6-446b-9d37-98f36450e93e', 'd', 'Las Marcas de peligro aislado nunca pueden utilizarse por duplicado.', false, '2025-09-13 13:53:10.840695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f0f8db9-876e-4333-9408-5c7275f58882', '69c3cdf8-a388-4a41-93c2-9dca2f2c098c', 'a', 'Color.', false, '2025-09-13 13:53:10.841133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f20312e3-17e4-4aca-af74-55193c60832e', '69c3cdf8-a388-4a41-93c2-9dca2f2c098c', 'b', 'Forma.', false, '2025-09-13 13:53:10.841279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ece5e572-3488-4f53-81ad-ecbddc3a94f6', '69c3cdf8-a388-4a41-93c2-9dca2f2c098c', 'c', 'Ritmo.', false, '2025-09-13 13:53:10.841413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('798a1628-8858-4038-82e6-e2229f9dc184', '69c3cdf8-a388-4a41-93c2-9dca2f2c098c', 'd', 'Marca de tope.', true, '2025-09-13 13:53:10.841681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fef143a4-9b18-44ff-8972-adbbf6739eab', '955e9936-01ed-4119-befd-32637af9da9a', 'a', 'Únicamente luces sincronizadas.', false, '2025-09-13 13:53:10.841999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfd09f4d-23f1-4262-87cc-d66055ba4f57', '955e9936-01ed-4119-befd-32637af9da9a', 'b', 'Únicamente luces secuenciadas.', false, '2025-09-13 13:53:10.84214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84837080-f850-4073-9471-f8c976d1f7ff', '0b0bc59f-1622-4b58-b048-52d6557705f7', 'a', 'Los de origen eléctrico.', false, '2025-09-13 13:53:10.853474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2939a157-7332-400d-b199-fd490c6e39d0', 'a04e5611-40c6-446b-9d37-98f36450e93e', 'a', 'La autoridad competente considera que el riesgo para la navegación resulta especialmente elevado.', true, '2025-09-13 13:53:10.840258+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20c618e6-79ee-4df7-8e7a-cfeeff166387', '955e9936-01ed-4119-befd-32637af9da9a', 'd', 'Luces sincronizadas, luces secuenciadas o una combinación de ambas.', true, '2025-09-13 13:53:10.842409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2689ea4-4551-4f95-9864-14e521abe94e', '870050e5-dab6-4002-bb14-e51aba8d9aeb', 'a', 'Grupos de (2+1) destello.', true, '2025-09-13 13:53:10.842783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96b120d9-b485-4085-9d3d-403f45ec3fad', '870050e5-dab6-4002-bb14-e51aba8d9aeb', 'b', 'Centelleante de grupos de seis centelleos Q (6) más 9 centelleos Q-(9) cada 15 segundos.', false, '2025-09-13 13:53:10.842959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3130e64b-550a-44a3-bdd6-efed85e10598', '870050e5-dab6-4002-bb14-e51aba8d9aeb', 'c', 'Centelleante de grupos de 3 centelleos Q-(3) cada 10 segundos.', false, '2025-09-13 13:53:10.843152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b96069e-416e-4438-b29a-efc72766cced', '870050e5-dab6-4002-bb14-e51aba8d9aeb', 'd', 'Grupos de dos destellos GpD (2). Reglamento (RIPA).', false, '2025-09-13 13:53:10.843308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3df0fc38-a6a5-4f99-ae6e-855c9c73d524', '5f38d47c-1e61-4f70-9216-e9c9431f7156', 'a', 'Estar combinadas en un solo farol llevado en el eje longitudinal del buque.', true, '2025-09-13 13:53:10.843622+00');
