INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db2587e6-0c6d-4a7d-80ef-40a78ccb9f5e', '383940af-f551-4e43-a9ae-1155abcba7ed', 'b', 'El estado de la mar.', false, '2025-09-13 13:53:10.844456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d48316a-3d13-4961-a765-eb0dda95e633', '383940af-f551-4e43-a9ae-1155abcba7ed', 'c', 'El calado en relación con la profundidad disponible de agua.', false, '2025-09-13 13:53:10.844593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('577d801b-6fe2-40b6-8c73-88b8c91b092d', '383940af-f551-4e43-a9ae-1155abcba7ed', 'd', 'Las características, eficacia y limitaciones del equipo de la carta electrónica.', true, '2025-09-13 13:53:10.84473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eea50675-2864-4528-ac4d-0f6d354cd6a8', 'c9b3cfe7-46b6-40e9-a277-8a36992ccfa4', 'a', 'Dos conos unidos por sus vértices en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:10.845021+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0778e72-b2e4-4adc-83f1-669cd31de2ab', 'c9b3cfe7-46b6-40e9-a277-8a36992ccfa4', 'b', 'Dos conos unidos por sus bases en línea vertical, uno sobre el otro.', false, '2025-09-13 13:53:10.845154+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1f34492-ff30-4344-9a45-2f0747f7f522', 'c9b3cfe7-46b6-40e9-a277-8a36992ccfa4', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:10.845285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69a7034d-a760-4850-9b24-7883e1515251', 'c9b3cfe7-46b6-40e9-a277-8a36992ccfa4', 'd', 'Una marca cónica con el vértice hacia abajo.', true, '2025-09-13 13:53:10.845415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba393ef8-4f92-4c0e-b6b2-f54c1a7ee879', '06936f3a-cec9-4a9f-a6ca-e06b83b59b51', 'a', 'Los buques de vela.', false, '2025-09-13 13:53:10.845701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8568af6-22f0-41ff-8957-1db9ada08f7b', '06936f3a-cec9-4a9f-a6ca-e06b83b59b51', 'b', 'Las embarcaciones de recreo.', false, '2025-09-13 13:53:10.845849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b3752a2-4d32-4ff7-a1f7-5c62e40d0817', '06936f3a-cec9-4a9f-a6ca-e06b83b59b51', 'c', 'Los buques en navegación que estén haciendo combustible.', true, '2025-09-13 13:53:10.846002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0859869c-719a-4059-8030-5e7b7fa12be5', '06936f3a-cec9-4a9f-a6ca-e06b83b59b51', 'd', 'Los hidroaviones.', false, '2025-09-13 13:53:10.846141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2be8c9fa-63eb-42f4-bc9f-ca2e49dc1947', 'a4b72926-4612-4bb1-8492-c9355d87220f', 'b', 'Se tendrá en cuenta la experiencia de la tripulación, en especial la del patrón.', false, '2025-09-13 13:53:10.846572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7efada3-2a0d-43d5-bfbd-e254ada3b255', 'a4b72926-4612-4bb1-8492-c9355d87220f', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-13 13:53:10.846856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d5f6383-6039-4db5-a19e-e631cf5b0a52', '04d1f377-5f25-47eb-b4e3-12b26f3df76b', 'a', '120 o más centelleos por minuto.', true, '2025-09-13 13:53:10.847317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37412b0d-3dad-4df8-8abc-025b44a9c4a4', '04d1f377-5f25-47eb-b4e3-12b26f3df76b', 'b', '110 o más centelleos por minuto.', false, '2025-09-13 13:53:10.847457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa3966b2-8541-45e2-af00-6520824f125f', '04d1f377-5f25-47eb-b4e3-12b26f3df76b', 'c', '100 o más centelleos por minuto.', false, '2025-09-13 13:53:10.847594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efd23b2b-b839-42e8-a61e-7b994b5a0a06', '04d1f377-5f25-47eb-b4e3-12b26f3df76b', 'd', '60 o más centelleos por minuto.', false, '2025-09-13 13:53:10.84773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b4ec0c2-7b3e-43d3-a69b-0f735b09b512', '4c3a0966-31b1-4802-af73-3f4f13a70f59', 'a', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor se mantendrá apartado de la derrota del otro.', true, '2025-09-13 13:53:10.848068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef064e38-1d57-4ce5-bcfb-42ee077a2a55', '4c3a0966-31b1-4802-af73-3f4f13a70f59', 'b', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a sotavento se mantendrá apartado de la derrota del que esté a barlovento.', false, '2025-09-13 13:53:10.848214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('463fe2bd-3535-4568-ab3e-5065bf9c1f83', '4c3a0966-31b1-4802-af73-3f4f13a70f59', 'c', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por estribor se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:10.848354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76823254-0a48-4692-b1e8-f9db3779cb27', '4c3a0966-31b1-4802-af73-3f4f13a70f59', 'd', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor mantendrá el mismo rumbo y velocidad.', false, '2025-09-13 13:53:10.848503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ec779d3-9520-4ff1-9ad0-5cfc0cf3e2c8', '9cf7f919-4762-4b01-8614-8ae15b74143b', 'a', 'Ejecutará la maniobra que mejor pueda ayudar a evitar el abordaje.', true, '2025-09-13 13:53:10.848799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8991c990-d105-46d1-be93-94ad837db312', '9cf7f919-4762-4b01-8614-8ae15b74143b', 'b', 'Siempre mantendrá rumbo y velocidad para no restar efectividad a la maniobra del otro buque.', false, '2025-09-13 13:53:10.848935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aafe5507-fa4b-4a2e-942d-ff7c5526afcb', '9cf7f919-4762-4b01-8614-8ae15b74143b', 'c', 'Sujetará firmemente el timón esperando el abordaje.', false, '2025-09-13 13:53:10.849071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad35b7f2-f610-47e5-8649-a30814a8fb6e', '9cf7f919-4762-4b01-8614-8ae15b74143b', 'd', 'Parará máquinas para evitar incendios por el abordaje.', false, '2025-09-13 13:53:10.849203+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad7b83a3-c7a6-4a0d-b231-a272a6676c60', '5e262b15-3377-4df1-82f2-86a67ad446d4', 'a', 'No podrá ceder el paso si existe riesgo de abordaje.', false, '2025-09-13 13:53:10.849513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c754e33-7ed9-4ce9-a96d-7594b4e32128', '5e262b15-3377-4df1-82f2-86a67ad446d4', 'b', 'Se realizará con antelación suficiente y de forma decidida para quedar bien franco del otro buque.', true, '2025-09-13 13:53:10.849651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ada1ee5a-00bc-454b-87fa-0cf5a27b62ac', '5e262b15-3377-4df1-82f2-86a67ad446d4', 'c', 'Se cederá el paso solamente ante buques de mayor tonelaje.', false, '2025-09-13 13:53:10.849787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9fe24f4-ddd4-4f65-8c9b-81b831cbd8db', '5e262b15-3377-4df1-82f2-86a67ad446d4', 'd', 'Se cederá el paso solamente a los buques que vienen por babor.', false, '2025-09-13 13:53:10.849937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6e16fbc-9691-472c-b34f-bab17ed56dcf', 'a4856923-d1fe-4607-97fc-33a8383da039', 'a', 'Una luz blanca todo horizonte visible a una distancia mínima de cinco millas.', true, '2025-09-13 13:53:10.850231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6475bc3f-1f42-49ed-8a4c-6b3e8d96a9be', 'a4856923-d1fe-4607-97fc-33a8383da039', 'b', 'Una luz blanca todo horizonte visible a una distancia mínima de dos millas.', false, '2025-09-13 13:53:10.850363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1c74a74-7a99-42e4-b74a-7b47e83bc1dc', 'a4856923-d1fe-4607-97fc-33a8383da039', 'c', 'Una luz verde todo horizonte visible a una distancia mínima de dos millas.', false, '2025-09-13 13:53:10.850496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fd36d95-f643-4d1e-81f2-7e1e65820baf', 'fe38f2a6-a742-43d1-b195-9a17f428c99f', 'a', 'Esprines.', false, '2025-09-13 13:53:10.850944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0afdfd82-f98e-4c6b-b5c8-ed1465c13a3d', 'fe38f2a6-a742-43d1-b195-9a17f428c99f', 'b', 'Coderas.', true, '2025-09-13 13:53:10.851099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62b95735-79ca-4b98-97ce-97fdb4927bec', 'fe38f2a6-a742-43d1-b195-9a17f428c99f', 'c', 'Traveses.', false, '2025-09-13 13:53:10.851242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c201c30-68bd-4e38-9708-cba7c6e367af', 'fe38f2a6-a742-43d1-b195-9a17f428c99f', 'd', 'Largos.', false, '2025-09-13 13:53:10.851398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eaf2360-3e0b-4382-a9aa-b1fbce56ca96', '4b532a2c-5658-4a0a-b21d-14de87a5bfe2', 'a', 'Fase inicial, Fase variable y Fase uniforme.', false, '2025-09-13 13:53:10.851789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8df95854-8240-4199-b335-49ac136ad6b8', '4b532a2c-5658-4a0a-b21d-14de87a5bfe2', 'b', 'Fase inicial, Fase de maniobra y Fase final.', false, '2025-09-13 13:53:10.851963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3fb5e72-493b-4437-aeb4-aa731f281a45', '4b532a2c-5658-4a0a-b21d-14de87a5bfe2', 'c', 'Fase de maniobra, Fase variable y Fase final.', false, '2025-09-13 13:53:10.852116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b66cd6f-1766-477a-9142-85f44b55e1ad', 'f96006d0-ddab-487f-b28c-7deda53325d2', 'c', 'Si una válvula o pasa cascos falla, cierre o coloque un espiche cónico de madera a la medida.', false, '2025-09-13 13:53:10.853014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f969bc11-2cce-4d9b-86db-04ed8b33fd05', 'f96006d0-ddab-487f-b28c-7deda53325d2', 'd', 'Si no puede detener la entrada de agua, haga una llamada de socorro, y mientras espera la ayuda, vacíe el depósito de agua dulce al mínimo imprescindible y arroje peso inútil por la borda.', false, '2025-09-13 13:53:10.853145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('609f2370-acff-4f71-8a2e-7546efa3a52a', 'f96006d0-ddab-487f-b28c-7deda53325d2', 'a', 'Los puntos de mayor riesgo para producirse una vía de agua son la bocina, la limera y los grifos de fondo.', false, '2025-09-13 13:53:10.852735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba55c842-e654-40fd-ba6c-bc861076345e', 'f96006d0-ddab-487f-b28c-7deda53325d2', 'b', 'Si detecta agua en la sentina, apague el motor y ponga en marcha de inmediato todas las bombas de achique.', true, '2025-09-13 13:53:10.852882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb33205e-08e9-4801-9044-826128efa8d3', 'a4856923-d1fe-4607-97fc-33a8383da039', 'd', 'Una luz roja todo horizonte visible a una distancia mínima de cinco millas.', false, '2025-09-13 13:53:10.850631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8eeb9c8f-acfb-421f-9bde-e2a9a58a9154', 'a4b72926-4612-4bb1-8492-c9355d87220f', 'c', 'En caso de abrigarse alguna duda respecto a si existe riesgo de abordaje, se considerará que existe.', true, '2025-09-13 13:53:10.846701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38d69a07-baa3-452a-8413-426f6fa0c2e1', '4b532a2c-5658-4a0a-b21d-14de87a5bfe2', 'd', 'Fase de maniobra, Fase variable y Fase uniforme.', true, '2025-09-13 13:53:10.852274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a82da0b-9a04-47cd-bcbb-26f600d0a774', '0b0bc59f-1622-4b58-b048-52d6557705f7', 'b', 'Los provocados por un combustible sólido, como por ejemplo el caucho o la madera.', false, '2025-09-13 13:53:10.853613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37318c40-87d1-4868-81e7-d472274c0224', '0b0bc59f-1622-4b58-b048-52d6557705f7', 'c', 'Los provocados por un combustible líquido como la gasolina o el aceite.', true, '2025-09-13 13:53:10.853771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a693be38-ae38-474b-bdb9-af95f031c5e8', '0b0bc59f-1622-4b58-b048-52d6557705f7', 'd', 'Los provocados por un combustible gaseoso como el butano.', false, '2025-09-13 13:53:10.853915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7da602b-c1f9-4bca-91e9-a19f0b32d60a', 'b6aab570-ea5a-44c1-9962-ee0a12ee5f4a', 'a', 'Si se realiza un torniquete, hay que aflojarlo cada 20 minutos para que circule la sangre por el resto del miembro, y si continua la hemorragia se volverá a comprimir transcurrido 1 minuto.', false, '2025-09-13 13:53:10.85421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa1a2dd1-cfd5-427c-b51b-203bef2e490e', 'b6aab570-ea5a-44c1-9962-ee0a12ee5f4a', 'b', 'En las quemaduras que afectan a brazos y piernas, es importante elevar la extremidad para disminuir la inflamación.', true, '2025-09-13 13:53:10.854351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7240656-36ba-47ee-a356-f3404f9cfb77', 'b6aab570-ea5a-44c1-9962-ee0a12ee5f4a', 'c', 'En caso de sufrir “mal de mar”, al afectado se le mantendrá quieto, caliente y en ayunas, en posición tumbada y a ser posible en un camarote situado a proa.', false, '2025-09-13 13:53:10.85449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beef4f16-a6ad-401f-991c-1d9ceefa5080', 'b6aab570-ea5a-44c1-9962-ee0a12ee5f4a', 'd', 'La asistencia médica del Centro Radio-Médico Español se realiza en español e inglés y se puede solicitar en el número de contacto directo 91 308 34 75. Meteorología', false, '2025-09-13 13:53:10.854625+00');
