INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8610580-7da6-4f57-8069-512117b3bf8f', '9eca44da-352b-4b1c-aab4-88dfbb3bd3ff', 'b', 'Son publicaciones que muestran derrotas seguras en función de la variable calado/profundidad.', false, '2025-09-13 13:53:10.860198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5439fc8a-5b8c-412f-95e4-63cff1883ebe', '9eca44da-352b-4b1c-aab4-88dfbb3bd3ff', 'c', 'Son libros que describen la costa en detalle, indicando peligros para la navegación. Entre otra información se indican las radas y puertos de abrigo.', true, '2025-09-13 13:53:10.86034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3807352-6c95-4b71-8ab2-2ec78fe9f145', '9eca44da-352b-4b1c-aab4-88dfbb3bd3ff', 'd', 'Son libros en los que se identifican los faros y sus características. Entre otra información se indican las derrotas recomendables teniendo en cuenta el registro de agua bajo la quilla, deriva y abatimiento de una embarcación de recreo.', false, '2025-09-13 13:53:10.860476+00');
