INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d68939cc-9306-4140-8a3f-89dbbdebf9e6', '2a947b7a-2b92-4e35-984a-8fe14f25851f', 'a', 'Es la inclinación del buque hacia un costado, por la acción del viento u otra fuerza.', true, '2025-09-13 13:53:10.866479+00');
