INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4d010cb-04df-42cb-8118-91eaf6eec1a0', '3fa3e78e-8dd9-4153-839d-53c819d12fbe', 'c', 'Zarpar.', false, '2025-09-13 13:53:10.867529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c686142f-4965-428b-99ac-c772f1cba210', '8effb626-ee44-4279-a78b-eeaa1165305a', 'a', 'Un muerto es un cuerpo flotante sujeto al fondo del mar mediante un lastre, que se coloca para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:10.867976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e17b9a2d-1250-4e03-991b-037c992110d8', '8effb626-ee44-4279-a78b-eeaa1165305a', 'b', 'El noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', false, '2025-09-13 13:53:10.868118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d21baef5-e021-4f32-a5a5-3b1cc799d483', '8effb626-ee44-4279-a78b-eeaa1165305a', 'c', 'El nudo llano se utiliza para afirmar una amarra a una argolla, mediante una gaza no corrediza.', false, '2025-09-13 13:53:10.868264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f652464-4bff-4d8a-aa23-1ac51293573a', '8effb626-ee44-4279-a78b-eeaa1165305a', 'd', 'La gaza es el lazo que se forma en el extremo de un cabo doblándolo y uniéndolo con costura o ligada, y que sirve para enganchar o ceñir algo o suspenderlo de alguna parte.', true, '2025-09-13 13:53:10.868423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dca534c-ef8b-4807-81cc-1662aa682bfd', '37854fe4-d81b-44a4-a8be-6432111dbd5e', 'a', 'En una embarcación de 10 metros de eslora, la línea de fondeo deberá tener un tramo de cadena de 5 metros de longitud.', false, '2025-09-13 13:53:10.868739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e904d8dd-23a3-417a-bfc2-6a2c2d5d6016', '37854fe4-d81b-44a4-a8be-6432111dbd5e', 'd', 'Se conoce como fondeo a la gira, al fondeo con un ancla por proa donde la embarcación puede girar de manera libre alrededor de esta.', true, '2025-09-13 13:53:10.869378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6bc4c5d-e038-4888-9e50-be43aa583cdc', '5d8369fe-f048-4f78-908d-cdfaf45c4355', 'a', 'Ninguna.', false, '2025-09-13 13:53:10.86967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a790bc40-436f-4751-87b3-b9fe9a705808', '5d8369fe-f048-4f78-908d-cdfaf45c4355', 'b', '1.', false, '2025-09-13 13:53:10.869809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24076b0e-12c5-4dd3-b575-f5ffd02286f5', '5d8369fe-f048-4f78-908d-cdfaf45c4355', 'c', '3.', true, '2025-09-13 13:53:10.869945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09b45849-fab1-4ff5-8112-fee8b0081988', '5d8369fe-f048-4f78-908d-cdfaf45c4355', 'd', '6.', false, '2025-09-13 13:53:10.870081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d35f108-7d9e-41e5-99c9-9b443dbbc8ad', 'b1fdb720-cafc-4ba8-a86a-9781e8bdefe6', 'a', 'Encender todas las luces de navegación reglamentarias.', false, '2025-09-13 13:53:10.87052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f1a140a-56a7-4456-bc04-a7e0d11291cb', 'b1fdb720-cafc-4ba8-a86a-9781e8bdefe6', 'b', 'Reducir la velocidad parando siempre la embarcación.', true, '2025-09-13 13:53:10.870666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e0c4225-eb48-4035-bdb1-ceaae941bfe5', 'b1fdb720-cafc-4ba8-a86a-9781e8bdefe6', 'c', 'Emitir las señales fónicas que sean reglamentarias.', false, '2025-09-13 13:53:10.870807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('297eb8c8-b445-43af-b482-241f3fcc9d5a', 'b1fdb720-cafc-4ba8-a86a-9781e8bdefe6', 'd', 'Tener listas las balsas salvavidas, si las llevamos, y tener colocados los chalecos salvavidas.', false, '2025-09-13 13:53:10.870965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29bc0c5d-7ad2-4300-ada6-1fea6704404f', '0d936c86-efed-403b-b628-717143557a95', 'a', 'Poniendo la popa al viento.', false, '2025-09-13 13:53:10.871267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbca111e-dcb9-4835-8bb0-2989cbe357c1', '0d936c86-efed-403b-b628-717143557a95', 'b', 'Poniendo la amura a la mar.', true, '2025-09-13 13:53:10.87141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5161c81c-e584-4ddd-bc32-c7786507e8cc', '0d936c86-efed-403b-b628-717143557a95', 'c', 'Llevando la mar por la aleta.', false, '2025-09-13 13:53:10.871547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae7de8b3-f240-4e74-94e5-4e452ff67f5a', '0d936c86-efed-403b-b628-717143557a95', 'd', 'Reduciendo la arrancada por debajo de la velocidad de gobierno.', false, '2025-09-13 13:53:10.871687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c2d8353-5daf-47b9-8905-7b4891555a89', 'ace39c35-d418-43b8-b1ac-8a70de3de841', 'a', 'Cuando veamos caer al náufrago, meter el timón a la banda que haya caído el náufrago hasta caer 250º y en ese momento poner el timón a la vía y parar máquinas.', false, '2025-09-13 13:53:10.87198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef8b6783-2e68-4422-852c-05f68e1f9f82', 'ace39c35-d418-43b8-b1ac-8a70de3de841', 'b', 'Cuando veamos caer al náufrago, con toda la máquina avante meter el timón a la banda que haya caído el náufrago hasta caer 70º, y en ese momento cambiar a la otra banda hasta alcanzar el rumbo opuesto al inicial.', false, '2025-09-13 13:53:10.872123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e1012ee-1d1c-4e13-874f-e63d54b8dc1e', 'ace39c35-d418-43b8-b1ac-8a70de3de841', 'c', 'Cuando veamos caer al náufrago, meter el timón a la banda contraria a la que haya caído el náufrago hasta caer 240°, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto al inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', true, '2025-09-13 13:53:10.872262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95dfa803-e98c-41c3-a231-fa4ad4a09312', 'ace39c35-d418-43b8-b1ac-8a70de3de841', 'd', 'Cuando no se ve caer al náufrago, activar el M.O.B. (Man Over Board) del GPS.', false, '2025-09-13 13:53:10.8724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b86e9e01-8428-47ac-8afb-b0e012816017', '84691e74-e3fa-4006-8f72-4bef5f061514', 'b', 'La navegación de cualquier buque o embarcación de recreo está permitida en la franja de mar contigua a la costa de una anchura de 50 metros en las playas y 200 metros de la costa, y siempre que no se exceda el límite de velocidad de tres nudos.', false, '2025-09-13 13:53:10.872842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78c6a7c9-b38c-444f-be11-b21f86800c22', '84691e74-e3fa-4006-8f72-4bef5f061514', 'c', 'Se entenderá que la zona de baño ocupa una franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto de la costa, no pudiendo navegar dentro de estas zonas a una velocidad superior a tres nudos.', true, '2025-09-13 13:53:10.872997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75d15e0a-0c80-45f4-b99c-8b093783f8ce', '84691e74-e3fa-4006-8f72-4bef5f061514', 'd', 'Está prohibida la navegación de cualquier buque o embarcación, salvo que estén dedicados exclusivamente al recreo, que podrán hacerlo sin limitaciones si su finalidad es fondear en calas o lugares de baño. 12', false, '2025-09-13 13:53:10.873138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bf18732-f75e-446e-ad49-982b86b07e70', '29d8e054-867d-4c1c-ae63-9a236646541d', 'a', 'Espacio marino del Odiel.', true, '2025-09-13 13:53:10.873453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('062c8589-1e0c-4c9d-83ca-123f22ac29a7', '29d8e054-867d-4c1c-ae63-9a236646541d', 'b', 'Cabo de Creus.', false, '2025-09-13 13:53:10.873592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4cb372f-722b-4d19-8040-d77a61847233', '29d8e054-867d-4c1c-ae63-9a236646541d', 'c', 'Islas Medes.', false, '2025-09-13 13:53:10.873732+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6d1c229-bc6f-4c8b-b438-3d27f1107450', '29d8e054-867d-4c1c-ae63-9a236646541d', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:10.87387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d51447b-5bcf-4266-bfca-1d9efc9a1cd0', '14de870e-e939-405f-afae-2e8670d48161', 'a', 'Corredera.', false, '2025-09-13 13:53:10.874266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38976ced-64cb-49b2-a3ba-80bad0678395', '14de870e-e939-405f-afae-2e8670d48161', 'b', 'Compás.', true, '2025-09-13 13:53:10.874401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50f8188e-7840-4f3b-b2a1-b30157454df4', '14de870e-e939-405f-afae-2e8670d48161', 'c', 'Sonda.', false, '2025-09-13 13:53:10.874534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de76b5ff-c6cc-445a-a8ae-5e76dc8931d7', '14de870e-e939-405f-afae-2e8670d48161', 'd', 'Radar.', false, '2025-09-13 13:53:10.874681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4f74c2e-bc70-442d-b0e0-c4f5543d68dc', '720fb2a8-f304-4e85-8c4b-c6a368c9cd30', 'a', 'Un destello largo cada 10 segundos.', true, '2025-09-13 13:53:10.874969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('104237ad-f394-4b65-8e1b-72445d7c1332', '720fb2a8-f304-4e85-8c4b-c6a368c9cd30', 'b', 'Un destello largo cada 5 segundos.', false, '2025-09-13 13:53:10.875101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dddc400e-ea24-412a-9193-b15666847046', '720fb2a8-f304-4e85-8c4b-c6a368c9cd30', 'c', 'Grupos de dos destellos GpD (2), cada 10 segundos.', false, '2025-09-13 13:53:10.875232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51f5b61b-5027-413a-ab47-96e01f722804', '720fb2a8-f304-4e85-8c4b-c6a368c9cd30', 'd', 'Grupos de dos destellos GpD (2), cada 5 segundos.', false, '2025-09-13 13:53:10.875363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd934832-8c3e-4230-8daa-1232bce0ecee', 'bc8876ce-6e66-42ff-a2ce-0c6078acfb51', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:10.875636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7e001db-b75b-4c98-83bb-4c583e81c797', 'bc8876ce-6e66-42ff-a2ce-0c6078acfb51', 'b', 'Una esfera amarilla.', false, '2025-09-13 13:53:10.875769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('842a17b5-5727-4b79-b51d-14837df84ab8', 'bc8876ce-6e66-42ff-a2ce-0c6078acfb51', 'c', 'Dos esferas negras.', true, '2025-09-13 13:53:10.875904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ec9c01a-9cdd-4980-949a-356894723bdd', 'bc8876ce-6e66-42ff-a2ce-0c6078acfb51', 'd', 'Dos esferas amarillas.', false, '2025-09-13 13:53:10.876035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d1cc1c8-4f02-48d2-9aa8-b9a43a5d09e6', 'f55ce4c4-3ddb-4ca9-8fa5-a15919f47b4d', 'a', 'Por lo general, están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:10.876334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03bbbc04-82c3-4a9c-bf08-f153c20deb46', '41decd89-5a54-409f-ae27-afea04f2ae58', 'd', '032º.', false, '2025-09-13 13:53:10.971415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71abc4cd-1b29-46f7-b58c-78883458eff7', '3fa3e78e-8dd9-4153-839d-53c819d12fbe', 'd', 'Filar.', false, '2025-09-13 13:53:10.867669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f60d2d2-1af1-4147-8cd3-fb62336aa416', '37854fe4-d81b-44a4-a8be-6432111dbd5e', 'c', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a la proa de la embarcación.', false, '2025-09-13 13:53:10.869239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6177c71c-803e-4735-8cd6-8e23c297d613', 'f55ce4c4-3ddb-4ca9-8fa5-a15919f47b4d', 'b', 'Se pueden usar para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.876472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3daecb6e-4603-43d8-bdb3-5ee00550f353', 'f55ce4c4-3ddb-4ca9-8fa5-a15919f47b4d', 'c', 'Se pueden usar para definir los ejes de los canales y las marcas de centro de canal.', false, '2025-09-13 13:53:10.876616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('907711af-86f5-4b72-bc3b-8fe80e6147a5', 'f55ce4c4-3ddb-4ca9-8fa5-a15919f47b4d', 'd', 'Por lo general, están destinadas para indicar el canal principal en el punto de bifurcación de este.', false, '2025-09-13 13:53:10.876751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c461544a-e2f0-4b9d-84bb-cd45d6c247d6', '8c96dd2d-c16e-4082-ad35-58887f14fea3', 'a', 'El canal principal queda a estribor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', false, '2025-09-13 13:53:10.877057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05f21579-0b9b-439f-96b9-98718f13d08c', '8c96dd2d-c16e-4082-ad35-58887f14fea3', 'b', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en sentido opuesto al convencional de balizamiento.', false, '2025-09-13 13:53:10.8772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75756256-da97-4be5-afde-4c286c53f2e5', '8c96dd2d-c16e-4082-ad35-58887f14fea3', 'c', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', true, '2025-09-13 13:53:10.877339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af2530ef-8286-4c99-b4ac-81ec0e0c9006', '8c96dd2d-c16e-4082-ad35-58887f14fea3', 'd', 'El canal principal queda a babor, si estamos en una bifurcación y navegando hacia alta mar. Reglamento (RIPA).', false, '2025-09-13 13:53:10.877478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e49c01fb-0a6f-4a08-856b-8e05496477f2', 'cdfbe259-9abe-40c8-afe5-399330ccb952', 'a', 'La responsabilidad estará limitada en todo caso al propietario del buque.', false, '2025-09-13 13:53:10.877769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d0b9cc1-d945-4deb-a132-f2286794fbd3', 'cdfbe259-9abe-40c8-afe5-399330ccb952', 'b', 'Únicamente el Capitán será responsable de las consecuencias de cualquier negligencia en el cumplimiento de este Reglamento.', false, '2025-09-13 13:53:10.877906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aa42f08-a6e5-442f-823e-9cf0fea3fc41', 'cdfbe259-9abe-40c8-afe5-399330ccb952', 'c', 'Ninguna disposición del Reglamento eximirá a un buque, o a su propietario, al Capitán o a la dotación del mismo de las consecuencias de cualquier negligencia en el cumplimiento de éste.', true, '2025-09-13 13:53:10.878042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2f0af7c-e761-4352-b59d-3a9d5f255f4b', 'cdfbe259-9abe-40c8-afe5-399330ccb952', 'd', 'En ningún caso la dotación será responsable.', false, '2025-09-13 13:53:10.878177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a758961-46c2-4f94-9a7e-80f53076eda2', 'bb697e73-0438-42cd-a915-83480483d6fa', 'a', 'Para no quedar bien franco del otro buque.', false, '2025-09-13 13:53:10.878459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d60fd38c-939f-4c0f-9638-266b2a28faff', 'bb697e73-0438-42cd-a915-83480483d6fa', 'b', 'De forma decidida.', true, '2025-09-13 13:53:10.878592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54928bac-96f9-4936-b682-10831a3c2b34', 'bb697e73-0438-42cd-a915-83480483d6fa', 'c', 'Manteniendo siempre el rumbo inicial y variando sólo la velocidad.', false, '2025-09-13 13:53:10.878724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c86f1a6-a253-4c08-9d13-f177d7346338', 'bb697e73-0438-42cd-a915-83480483d6fa', 'd', 'Con maniobras suaves y contrarias para indicar al otro buque que va a maniobrar y que aquél debe mantener su derrota.', false, '2025-09-13 13:53:10.87889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af67b0cb-f893-4aa7-975e-8ec7b023879d', '050e2960-4f40-433b-a16b-fae750977d3e', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y ninguna de las luces de costado.', true, '2025-09-13 13:53:10.87925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fdaf8db-b2cc-4759-9dc2-a882e4be8792', '050e2960-4f40-433b-a16b-fae750977d3e', 'b', 'Se mantendrá lo más cerca posible de la derrota del buque alcanzado.', false, '2025-09-13 13:53:10.87954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc55bbe5-fb27-4b60-a47b-271458938108', '050e2960-4f40-433b-a16b-fae750977d3e', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:10.879679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8d19e06-89aa-4463-90ee-859f8ea4ecd8', '050e2960-4f40-433b-a16b-fae750977d3e', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:10.879817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f73549e4-9d4f-4440-8910-268db982255a', '762e4d7b-7618-4df8-84b0-4290b6a06de8', 'a', 'Es siempre la misma para un buque de vela.', false, '2025-09-13 13:53:10.880143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8af4e86d-0d5a-49c0-bd1a-3ba5d16375a9', '762e4d7b-7618-4df8-84b0-4290b6a06de8', 'b', 'Sólo se utilizará en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.880285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7efb2cb-d417-4b0a-9c7c-d2f049773214', '762e4d7b-7618-4df8-84b0-4290b6a06de8', 'c', 'Para determinarla no se tendrá en cuenta la densidad del tráfico.', false, '2025-09-13 13:53:10.880424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85eb6a40-85f9-4e48-a134-fd20f75358ce', '762e4d7b-7618-4df8-84b0-4290b6a06de8', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje.', true, '2025-09-13 13:53:10.880562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0653632-ad26-42f1-8416-9220cbf9df52', 'f7f1e353-c539-4b02-9f7f-8ab02af5b9bc', 'a', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:10.880849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('998957d3-ca83-4e57-a727-e258d4d69fb1', 'f7f1e353-c539-4b02-9f7f-8ab02af5b9bc', 'b', 'Una pitada larga a intervalos que no excedan de dos minutos.', true, '2025-09-13 13:53:10.880988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4636d9e3-34e1-4e98-b1b8-a4c68d630cf1', 'f7f1e353-c539-4b02-9f7f-8ab02af5b9bc', 'c', 'Una pitada corta a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:10.881142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9a29457-243e-4aaf-a85a-e27ae168ce01', 'f7f1e353-c539-4b02-9f7f-8ab02af5b9bc', 'd', 'Una pitada larga a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:10.881306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e5f276a-58cb-479e-a769-7f2cb3e474b8', 'fe19e624-e886-4a46-b76d-c244b531c9a8', 'a', 'De forma cónica con el que se refuerza el sonido emitido, muy útil para hablar desde lejos.', false, '2025-09-13 13:53:10.881608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('774ebe8b-33f7-4bec-9b48-263b6a2c8098', 'fe19e624-e886-4a46-b76d-c244b531c9a8', 'b', 'Metálico, generalmente en forma de copa invertida, que suena al ser golpeado por un badajo.', false, '2025-09-13 13:53:10.881743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01cc8491-d904-47c9-8e8b-bceedb2b0d19', 'fe19e624-e886-4a46-b76d-c244b531c9a8', 'c', 'De percusión formado por un disco que vibra al ser golpeado.', false, '2025-09-13 13:53:10.881887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03963357-2759-4d82-8d90-59b15d60dcee', 'fe19e624-e886-4a46-b76d-c244b531c9a8', 'd', 'Capaz de producir las pitadas reglamentarias y que cumple con las especificaciones del anexo III del Reglamento.', true, '2025-09-13 13:53:10.882027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29f03142-fad1-4823-a3c8-71fb7dc537ba', 'ffb3eb18-073a-41ea-b6f2-e601b4532643', 'a', 'Cuya velocidad máxima no sea superior a quince nudos.', false, '2025-09-13 13:53:10.882998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a692fedf-1fd3-457e-b96f-f35d677355aa', 'ffb3eb18-073a-41ea-b6f2-e601b4532643', 'b', 'Cuya velocidad máxima no sea superior a doce nudos.', false, '2025-09-13 13:53:10.883132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36efaa1c-2559-4891-b6c7-9271e402b841', 'ffb3eb18-073a-41ea-b6f2-e601b4532643', 'c', 'De eslora inferior a 20 metros.', false, '2025-09-13 13:53:10.883264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd658767-40d5-424a-9051-ce7620ec2af5', 'ffb3eb18-073a-41ea-b6f2-e601b4532643', 'd', 'De eslora inferior a 12 metros.', true, '2025-09-13 13:53:10.883398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05443a2f-f922-4ff9-8893-506e035d1cee', '3e6a78a7-fd96-4ef0-b062-38fd4a97c792', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:10.883679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67087a7d-2226-4ceb-b3bb-62cc967ef88f', '3e6a78a7-fd96-4ef0-b062-38fd4a97c792', 'b', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:10.883816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cf085cf-b7d2-49c5-81b1-a5a80f7908d1', '3e6a78a7-fd96-4ef0-b062-38fd4a97c792', 'c', 'Una luz de alcance y luces de costado.', false, '2025-09-13 13:53:10.883953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b49304a-5542-41c8-9edf-88f2ad4a5c74', '3e6a78a7-fd96-4ef0-b062-38fd4a97c792', 'd', 'Una luz de alcance, luces de costado y una luz centelleante.', false, '2025-09-13 13:53:10.884087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cf9a989-73d0-4442-b2d0-aa9a214613e4', '7a9f56b8-dd61-4f45-b22d-4b33ab0a2d49', 'a', 'Como regla general, toda maniobra que se efectúe para evitar un abordaje será llevada a cabo en forma clara, con la debida antelación y respetando las buenas prácticas marineras.', false, '2025-09-13 13:53:10.884365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('950ee62c-a71e-4700-a61a-6d65ea465645', '7a9f56b8-dd61-4f45-b22d-4b33ab0a2d49', 'b', 'Si es necesario con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad.', false, '2025-09-13 13:53:10.884635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc385075-2812-4cde-90a6-6e96d08aa78f', '7a9f56b8-dd61-4f45-b22d-4b33ab0a2d49', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasando al otro.', false, '2025-09-13 13:53:10.884769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b272866-3464-48f1-aaa9-90afb11c44fe', '7a9f56b8-dd61-4f45-b22d-4b33ab0a2d49', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños. Maniobra y navegación.', true, '2025-09-13 13:53:10.884906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38dd7f83-c0d1-4b28-b918-076186e3f206', '8f5b5123-24f6-4859-a117-6efe67503f51', 'a', 'Un esprín de proa.', true, '2025-09-13 13:53:10.885186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eda3d125-8096-4744-a25a-2d7b523f23a7', '8f5b5123-24f6-4859-a117-6efe67503f51', 'b', 'Un largo de proa.', false, '2025-09-13 13:53:10.885319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12ecfbc7-5480-4041-b3dc-796fbb2d696e', '8f5b5123-24f6-4859-a117-6efe67503f51', 'c', 'Un través a proa.', false, '2025-09-13 13:53:10.885462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cc7bf48-a50b-4195-8aa3-397acb48a321', '8f5b5123-24f6-4859-a117-6efe67503f51', 'd', 'Un esprín de popa.', false, '2025-09-13 13:53:10.885594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec9a0bc0-2e56-4e40-a8f6-3b881fa841b6', 'd2fa5724-64b9-43da-82ed-6d57ec08777c', 'a', 'Las quemaduras de 2º grado afectan a la capa profunda y aparecen ampollas con líquido claro y dolor intenso. Las ampollas deben recortarse sólo si ya se han roto.', false, '2025-09-13 13:53:10.886558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddfa9ec8-1c40-43f3-80a3-6fbc8428c3ca', 'd2fa5724-64b9-43da-82ed-6d57ec08777c', 'b', 'Una herida que esté infectada o presente una hemorragia se considerará una herida grave y en ese caso, se cubrirá con un apósito estéril y no se aplicarán antisépticos ni pomadas.', false, '2025-09-13 13:53:10.886689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('505229f4-2dbc-4ee4-85b4-d4ca94ae2318', 'd2fa5724-64b9-43da-82ed-6d57ec08777c', 'c', 'En el caso de que se produzca un golpe de calor con temperatura corporal por encima de 40ºC, hay que bajar la temperatura hasta los 39º C y controlarlo cada 10 minutos.', false, '2025-09-13 13:53:10.886821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1df37d67-ffef-44e7-945a-405eba96ea56', 'd2fa5724-64b9-43da-82ed-6d57ec08777c', 'd', 'La asistencia médica del Centro Radio-Médico Español está disponible todos los días del año, entre las 6:00 y las 00:00 horas (hora de Madrid).', true, '2025-09-13 13:53:10.886962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc60fee1-5794-4719-b8e1-f62236a78cdd', '574b7ac5-932e-4eb2-96d2-fbf7fb752e64', 'a', 'Determinar la posición y avisar inmediatamente a Salvamento Marítimo.', false, '2025-09-13 13:53:10.887244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('321d135f-30f4-4161-bffc-ffc31595a1c6', '574b7ac5-932e-4eb2-96d2-fbf7fb752e64', 'c', 'Abandonar la embarcación.', false, '2025-09-13 13:53:10.887517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f8749ad-72b8-4b71-b30e-675fd5326f71', '574b7ac5-932e-4eb2-96d2-fbf7fb752e64', 'd', 'Dar atrás toda con timón a la vía, para salir de la varada antes de que el casco sufra más daños.', false, '2025-09-13 13:53:10.887652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b6ced78-a0e5-4543-8c23-3f99f6544167', 'c4b1de56-ab04-4f12-a7c4-4f07aee7a968', 'a', 'Un cohete lanzabengalas con paracaídas.', true, '2025-09-13 13:53:10.887941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0789b181-f68a-4716-a978-73ab916847c7', 'c4b1de56-ab04-4f12-a7c4-4f07aee7a968', 'b', 'Una bengala de mano.', false, '2025-09-13 13:53:10.888077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20e92806-78fb-46e2-b999-4bec2d545b21', 'c4b1de56-ab04-4f12-a7c4-4f07aee7a968', 'c', 'Una señal fumígena flotante.', false, '2025-09-13 13:53:10.888212+00');
