INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('147e36b9-7fc6-42ee-b6e4-e2958044ee08', '4f1308d8-442e-4f9f-a8f9-84ca85c79db4', 'a', 'Es una magnitud física.', false, '2025-09-13 13:53:10.888628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89e1c3cb-6d1d-4ebd-a2ff-bec9bf91b5e2', '4f1308d8-442e-4f9f-a8f9-84ca85c79db4', 'b', 'Para indicarla se puede usar la escala Celsius.', false, '2025-09-13 13:53:10.888764+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecb64f23-6a5d-46a1-aedf-c1ac2d32f491', '4f1308d8-442e-4f9f-a8f9-84ca85c79db4', 'c', 'Disminuye cuando aumenta la presión atmosférica.', true, '2025-09-13 13:53:10.888918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84f2e023-9864-42de-ac41-286a9dbbc6ab', '4f1308d8-442e-4f9f-a8f9-84ca85c79db4', 'd', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:10.88906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3815ed50-01f9-45bb-a0b8-83d4da1bdcf2', '0cb4ff63-9f43-4bbe-ac3e-14efc45fbd25', 'a', 'Veleta.', false, '2025-09-13 13:53:10.88935+00');
