INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40624e61-16ba-42ec-9822-ef18a38ab515', '05eb7538-78fd-485b-940d-fb934c7d422c', 'c', 'Nadar lo más rápido posible para mantener el calor.', false, '2025-09-13 13:53:10.902652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51f2ced1-6eb7-4975-b921-be286f4a9991', '05eb7538-78fd-485b-940d-fb934c7d422c', 'd', 'Aumentar la frecuencia de respiración para que llegue mayor cantidad de oxígeno al cerebro.', false, '2025-09-13 13:53:10.902792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66c7736d-5595-42d5-ad33-720bcdeebe91', '8bdd643e-7cd1-4be5-b909-09171826b509', 'a', 'Todas las embarcaciones de recreo, independientemente de la zona de navegación.', false, '2025-09-13 13:53:10.90307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a52cb31-57c3-44ec-89ad-aab1d413c7fc', '8bdd643e-7cd1-4be5-b909-09171826b509', 'b', 'Ninguna embarcación de recreo está obligada, aunque es recomendable.', false, '2025-09-13 13:53:10.903201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38e25c36-23b4-4200-8eb7-af2e9ff44119', '8bdd643e-7cd1-4be5-b909-09171826b509', 'c', 'Todas las embarcaciones de recreo que naveguen en zonas 1, 2, 3 o 4 y las que naveguen por la noche en zonas 5, 6 y 7.', false, '2025-09-13 13:53:10.903329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2160b569-34a9-41e5-a7c2-e555a34261f7', '8bdd643e-7cd1-4be5-b909-09171826b509', 'd', 'Todas las embarcaciones de recreo que naveguen en zonas 1, 2, 3 o 4.', true, '2025-09-13 13:53:10.903457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a672c0e6-64a3-4c2b-8336-a22c1b3ddd36', '56fc2029-de78-4406-8df9-51c1da08d98d', 'a', 'Ninguna está obligada, con independencia de su material de construcción.', false, '2025-09-13 13:53:10.903873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d522c53a-34d5-4d84-b0d6-82c0105b6300', '56fc2029-de78-4406-8df9-51c1da08d98d', 'b', 'Las embarcaciones con casco de madera.', false, '2025-09-13 13:53:10.904005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('859b69d7-b38b-450b-8fc2-c8df08f6fe49', '56fc2029-de78-4406-8df9-51c1da08d98d', 'c', 'Las embarcaciones con casco de fibra.', false, '2025-09-13 13:53:10.90414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59a4f20c-fccc-43c1-8482-fc99507c2a3d', '56fc2029-de78-4406-8df9-51c1da08d98d', 'd', 'Las embarcaciones con casco metálico.', true, '2025-09-13 13:53:10.904269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4262fa7f-60d2-4a48-95a9-f644b268e77f', '60deb826-7c80-44e0-af2a-e74b3b14064f', 'a', 'Cuando el periodo del balance coindice con el periodo de la ola se produce una situación de peligro que puede evitarse únicamente variando la velocidad.', false, '2025-09-13 13:53:10.904535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08373b0f-14d5-4ec3-bc0f-e757bcbe8d4d', '60deb826-7c80-44e0-af2a-e74b3b14064f', 'b', 'Cuando el periodo de cabezada coincide con el periodo de la ola se produce una situación de peligro que puede evitarse atravesándose a la mar.', false, '2025-09-13 13:53:10.904665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d50c9179-58cc-4d8e-b0f3-92648e0fcd9b', '60deb826-7c80-44e0-af2a-e74b3b14064f', 'c', 'Cuando el periodo de balance o el de cabezada coinciden con el de la ola se produce una situación de peligro que puede evitarse variando el rumbo o la velocidad.', true, '2025-09-13 13:53:10.904813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f76d7a46-4357-4dc6-a5ed-306c6d753306', '60deb826-7c80-44e0-af2a-e74b3b14064f', 'd', 'Cuando el periodo del balance o el de cabezada coincide con el periodo de la ola no existirá peligro y será la situación más favorable de navegación.', false, '2025-09-13 13:53:10.904968+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a346a011-3feb-4a3f-8f08-002f4fb8141b', 'c98ab5e6-bc5f-4f0e-8be7-6f7fc4e6d217', 'a', 'Cuando la nacionalidad del patrón coincide con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación del país de residencia del patrón.', false, '2025-09-13 13:53:10.905248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbc0b721-4df6-4e4e-8fe0-9302b3c1b3e3', 'c98ab5e6-bc5f-4f0e-8be7-6f7fc4e6d217', 'b', 'Cuando no coincidan la nacionalidad del patrón con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación del país del pabellón, si éste pertenece a la Unión Europea. En caso contrario se exigirá la titulación española requerida de acuerdo con la legislación nacional.', false, '2025-09-13 13:53:10.905379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06bc659b-5fd4-4f3b-93ec-9a3fc8b92321', 'c98ab5e6-bc5f-4f0e-8be7-6f7fc4e6d217', 'c', 'Cuando no coincidan la nacionalidad del patrón con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación de la nacionalidad del patrón o, en su defecto, con la de su país de residencia.', false, '2025-09-13 13:53:10.905511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dc0aef3-064a-4e5d-aefb-8c18e58e0add', 'c98ab5e6-bc5f-4f0e-8be7-6f7fc4e6d217', 'd', 'Cuando la nacionalidad del patrón coincide con la del pabellón, deberá estar en posesión de la titulación requerida de acuerdo con la legislación de la nacionalidad del patrón.', true, '2025-09-13 13:53:10.905643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce045a0e-287e-4e9d-98a8-4d60d8f812a9', 'dabb8b36-7d1c-408f-bf8b-2aab56818973', 'b', 'Serán solidariamente responsables para el pago de la multa que se imponga, el naviero, el propietario, el asegurador de la responsabilidad civil y el capitán o patrón, quedando además todos ellos obligados solidariamente a reparar el daño causado.', true, '2025-09-13 13:53:10.906077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fcd2cd3-9cb5-41c3-8e42-d93df93fff3a', '93155620-df2a-4da7-bab7-c88de4bd0ce5', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-13 13:53:10.916522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5765875-e14f-48ce-937d-71743b8cdf22', '698680ae-2e74-460f-829b-f5383872d3ac', 'd', 'Limera.', false, '2025-09-13 13:53:10.900629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51611d6c-69f3-4fce-b8c6-6ac5be1055f1', 'dabb8b36-7d1c-408f-bf8b-2aab56818973', 'a', 'El patrón es responsable del pago de la multa que se imponga sólo en defecto del propietario o del naviero.', false, '2025-09-13 13:53:10.905936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ffacf47-1eb5-49c4-9d78-8b9fc12812cd', 'dabb8b36-7d1c-408f-bf8b-2aab56818973', 'c', 'Serán responsables del pago de la multa el propietario o naviero y, subsidiariamente el asegurador de la responsabilidad civil. El patrón o capitán ejecutará a su costa las operaciones que, con carácter de urgencia, pudieran resultar necesarias para la preservación del medio marino.', false, '2025-09-13 13:53:10.906206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71d577b7-c1c0-4545-9f06-d567b9b5108d', 'dabb8b36-7d1c-408f-bf8b-2aab56818973', 'd', 'Será responsable del pago de la multa la persona física o jurídica propietaria de la embarcación y, subsidiariamente su capitán o patrón.', false, '2025-09-13 13:53:10.906343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af8cfdfd-9ac0-4c69-ad90-0a62a053fd87', '9ad504df-504c-4627-a228-10d3c2026131', 'b', 'La zona de peligro señalada es superior a 25 metros de radio desde la Marca.', false, '2025-09-13 13:53:10.90674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8546f376-25a4-42f0-bf0b-2b3d1053e7ec', '9ad504df-504c-4627-a228-10d3c2026131', 'c', 'La zona de peligro señalada es superior a 50 metros de radio desde la Marca.', false, '2025-09-13 13:53:10.906878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a3bf887-0eae-4236-9c64-bb8f68880dde', '9ad504df-504c-4627-a228-10d3c2026131', 'd', 'Las Marcas de peligro aislado nunca pueden utilizarse por duplicado.', false, '2025-09-13 13:53:10.907005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25dd6c8b-fd7b-4ff4-b395-eae304665f07', '12f44c41-fe2b-43c3-983f-a67b6f53ff60', 'a', 'Únicamente luces sincronizadas.', false, '2025-09-13 13:53:10.907267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0764dd7-3c10-4adf-be26-cf37736e6bd8', '12f44c41-fe2b-43c3-983f-a67b6f53ff60', 'b', 'Únicamente luces secuenciadas.', false, '2025-09-13 13:53:10.907394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3e11ac6-0f0a-4d51-b8db-97119c1a693a', '12f44c41-fe2b-43c3-983f-a67b6f53ff60', 'c', 'Se tendrá que elegir entre luces sincronizadas o luces secuenciales, no admitiéndose una combinación de ambas.', false, '2025-09-13 13:53:10.907684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19dbb680-3b10-4339-95de-de5a4b8cfa69', '12f44c41-fe2b-43c3-983f-a67b6f53ff60', 'd', 'Luces sincronizadas, luces secuenciadas o una combinación de ambas.', true, '2025-09-13 13:53:10.907824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d97ad13-a415-462d-bbc1-8a4950b2056c', '1b373afd-40f1-46bd-87be-4c18fea50ad4', 'a', 'Color.', false, '2025-09-13 13:53:10.908165+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('117f73df-70e4-417a-82b2-8ed259cf9834', '1b373afd-40f1-46bd-87be-4c18fea50ad4', 'b', 'Forma.', false, '2025-09-13 13:53:10.908333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecf88f3a-6263-4de3-b728-e4903c4195e3', '1b373afd-40f1-46bd-87be-4c18fea50ad4', 'c', 'Ritmo.', false, '2025-09-13 13:53:10.908494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('208caf32-35b0-4185-9e1b-08ab889eb728', '1b373afd-40f1-46bd-87be-4c18fea50ad4', 'd', 'Marca de tope.', true, '2025-09-13 13:53:10.908657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b40c9ac0-f7a9-4a0b-b779-dc9f964c217e', 'c606db24-3303-42d8-975d-107d75547563', 'a', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:10.908984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('500502f9-7333-406d-b45d-1bf19edabbba', 'c606db24-3303-42d8-975d-107d75547563', 'b', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:10.90912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('670d789b-5010-48d3-956d-bdfc2c87a4ec', 'c606db24-3303-42d8-975d-107d75547563', 'c', 'Franjas verticales azules y amarillas.', false, '2025-09-13 13:53:10.909253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46d99ba3-53a8-4453-a619-72b85cf96e88', 'c606db24-3303-42d8-975d-107d75547563', 'd', 'Franjas horizontales azules y amarillas.', false, '2025-09-13 13:53:10.909385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86f4a7e0-25ba-4825-8712-47a21bc21f25', '31f8d4ae-3eb5-43c6-b637-ca0db1b23099', 'a', 'Grupos de (2+1) destello.', true, '2025-09-13 13:53:10.909685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b2574eb-b112-49ea-adc4-a5bb63262866', '31f8d4ae-3eb5-43c6-b637-ca0db1b23099', 'b', 'Centelleante de grupos de seis centelleos Q (6) más 9 centelleos Q-(9) cada 15 segundos.', false, '2025-09-13 13:53:10.90983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9bb43d3-930a-4f27-9a86-3b5192cf7b58', '31f8d4ae-3eb5-43c6-b637-ca0db1b23099', 'c', 'Centelleante de grupos de 3 centelleos Q-(3) cada 10 segundos.', false, '2025-09-13 13:53:10.909967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83e9aaea-0199-4eff-b58a-e8c8264e5ed9', '31f8d4ae-3eb5-43c6-b637-ca0db1b23099', 'd', 'Grupos de dos destellos GpD (2). Reglamento (RIPA).', false, '2025-09-13 13:53:10.910103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2205af42-a5db-48ed-b577-8e7f5ce1d0d6', '470c6319-a346-4395-8063-d44f76d88235', 'a', 'Los buques de vela.', false, '2025-09-13 13:53:10.910412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9efa286f-3d5b-48ec-9119-4bf6d586428c', '470c6319-a346-4395-8063-d44f76d88235', 'b', 'Las embarcaciones de recreo.', false, '2025-09-13 13:53:10.91055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aaca1fed-2bcb-4d04-8822-bc332cf480ba', '470c6319-a346-4395-8063-d44f76d88235', 'c', 'Los buques en navegación que estén haciendo combustible.', true, '2025-09-13 13:53:10.910681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e345fb8-aac0-4e59-b78e-5dfce5cc36d9', '470c6319-a346-4395-8063-d44f76d88235', 'd', 'Los hidroaviones.', false, '2025-09-13 13:53:10.910813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34bea130-14a8-41e0-9463-88f29f374fee', 'eda89917-602c-4534-8a21-df873d2f3b8a', 'a', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor se mantendrá apartado de la derrota del otro.', true, '2025-09-13 13:53:10.911096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('823b26ff-e2a9-45cc-ba1b-c6a344c1543a', 'eda89917-602c-4534-8a21-df873d2f3b8a', 'b', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a sotavento se mantendrá apartado de la derrota del que esté a barlovento.', false, '2025-09-13 13:53:10.911229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('701a8297-01c0-4c92-bc42-5d7e86459cda', 'eda89917-602c-4534-8a21-df873d2f3b8a', 'c', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por estribor se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:10.911361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('934d2180-d92a-41c9-9e36-3298eb4f92d9', 'eda89917-602c-4534-8a21-df873d2f3b8a', 'd', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por babor mantendrá el mismo rumbo y velocidad.', false, '2025-09-13 13:53:10.911498+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('933242cf-8bde-4d65-bbb9-4b0f901dbba7', '65130bc0-7faa-4ab5-a174-d7a2c26ff3a4', 'a', 'Una luz blanca todo horizonte visible a una distancia mínima de cinco millas.', true, '2025-09-13 13:53:10.911784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48a5f3b5-98ee-4c68-8013-808ee01e154e', '65130bc0-7faa-4ab5-a174-d7a2c26ff3a4', 'b', 'Una luz blanca todo horizonte visible a una distancia mínima de dos millas.', false, '2025-09-13 13:53:10.911919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec704065-c40f-469f-85d2-d1c209cb1917', '65130bc0-7faa-4ab5-a174-d7a2c26ff3a4', 'c', 'Una luz verde todo horizonte visible a una distancia mínima de dos millas.', false, '2025-09-13 13:53:10.912053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8df06a1e-2880-46ef-b739-734f69b8608a', '65130bc0-7faa-4ab5-a174-d7a2c26ff3a4', 'd', 'Una luz roja todo horizonte visible a una distancia mínima de cinco millas.', false, '2025-09-13 13:53:10.912183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d55f9909-97b1-49f4-a7af-4b8d3a818bde', '5b005f8f-4713-4e83-aa61-4d0fbf19eda6', 'a', 'No podrá ceder el paso si existe riesgo de abordaje.', false, '2025-09-13 13:53:10.912454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eaaa6e4f-04f2-466e-abcb-d82b1a732782', '5b005f8f-4713-4e83-aa61-4d0fbf19eda6', 'b', 'Se realizará con antelación suficiente y de forma decidida para quedar bien franco del otro buque.', true, '2025-09-13 13:53:10.912741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfbcc5d4-10a8-4115-a139-7728a3df97a9', '5b005f8f-4713-4e83-aa61-4d0fbf19eda6', 'c', 'Se cederá el paso solamente ante buques de mayor tonelaje.', false, '2025-09-13 13:53:10.912919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eac42ae3-ae5a-471c-8ed8-8a865ea85bb8', '5b005f8f-4713-4e83-aa61-4d0fbf19eda6', 'd', 'Se cederá el paso solamente a los buques que vienen por babor.', false, '2025-09-13 13:53:10.913073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9803ce5-3594-4039-b6e2-90f4f89adfb9', '98685624-1f53-4f84-95ab-27a37e423e54', 'a', 'Estar combinadas en un solo farol llevado en el eje longitudinal del buque.', true, '2025-09-13 13:53:10.913361+00');
