INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e193f28-7b1e-4450-9cd4-ecd445ef1425', '45351c6c-6e66-4fc0-8321-2a4cfc3231fb', 'c', 'Si una válvula o pasa cascos falla, cierre o coloque un espiche cónico de madera a la medida.', false, '2025-09-13 13:53:10.919258+00');
