INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('298c9df0-83c5-4fe4-aa09-27c01271a518', '63a3c462-47a1-4c95-a2ef-34c60b119069', 'a', 'Si se realiza un torniquete, hay que aflojarlo cada 20 minutos para que circule la sangre por el resto del miembro, y si continua la hemorragia se volverá a comprimir transcurrido 1 minuto.', false, '2025-09-13 13:53:10.919656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0257134-ed2f-4b44-b2dc-6a68aa941380', '63a3c462-47a1-4c95-a2ef-34c60b119069', 'b', 'En las quemaduras que afectan a brazos y piernas, es importante elevar la extremidad para disminuir la inflamación.', true, '2025-09-13 13:53:10.919785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('827ca090-1208-4d3b-b07b-55dd36928226', '63a3c462-47a1-4c95-a2ef-34c60b119069', 'c', 'En caso de sufrir “mal de mar”, al afectado se le mantendrá quieto, caliente y en ayunas, en posición tumbada y a ser posible en un camarote situado a proa.', false, '2025-09-13 13:53:10.919921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c6e5ea2-9001-4b17-b2c6-019b56eb70b4', '63a3c462-47a1-4c95-a2ef-34c60b119069', 'd', 'La asistencia médica del Centro Radio-Médico Español se realiza en español e inglés y se puede solicitar en el número de contacto directo 91 308 34 75.', false, '2025-09-13 13:53:10.920063+00');
