INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65dac524-836e-465f-a1d6-cd08cdf30927', '22c4b00b-ccde-4160-a27b-ecaa5834cd39', 'a', 'Fondear.', false, '2025-09-13 13:53:10.93177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('248598f2-6038-49a0-a58c-2ae99d54172d', '22c4b00b-ccde-4160-a27b-ecaa5834cd39', 'b', 'Virar.', true, '2025-09-13 13:53:10.931905+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcd8701f-916d-4937-b2c0-300fb48519fa', '22c4b00b-ccde-4160-a27b-ecaa5834cd39', 'c', 'Zarpar.', false, '2025-09-13 13:53:10.932036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4a33824-be4b-4f2e-843e-5dc2d7103348', '22c4b00b-ccde-4160-a27b-ecaa5834cd39', 'd', 'Filar.', false, '2025-09-13 13:53:10.932167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3339953b-ca72-4e27-8455-01578b8d6140', '983eb756-0880-4947-8c37-f56ab751b100', 'a', 'Es la inclinación del buque hacia un costado, por la acción del viento u otra fuerza.', true, '2025-09-13 13:53:10.932446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7607c53-9010-43d2-8c16-45b250c7dc1a', '983eb756-0880-4947-8c37-f56ab751b100', 'b', 'Es colocar una embarcación al lado de otra o de un muelle, de forma tal que quede en contacto por su costado.', false, '2025-09-13 13:53:10.932579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c294007-baf5-417a-9101-d7d57a9858c5', '983eb756-0880-4947-8c37-f56ab751b100', 'c', 'Es la caída del buque hacia sotavento por efecto del viento.', false, '2025-09-13 13:53:10.93271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5a670bf-08c4-4b19-b677-b054b8047bf6', '983eb756-0880-4947-8c37-f56ab751b100', 'd', 'Es la distancia que recorre un barco por efecto de la corriente, es decir, por el desplazamiento de la masa de agua en la que se encuentra. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:10.932872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3a9e7b2-d95d-48cd-ba9e-892dc7f96b87', '4d733a6c-98f9-4e58-9681-f8bfe69450c6', 'a', 'Un muerto es un cuerpo flotante sujeto al fondo del mar mediante un lastre, que se coloca para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:10.933365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fae0e452-c8c3-4e8e-a1cd-ea0608760c13', '4d733a6c-98f9-4e58-9681-f8bfe69450c6', 'b', 'El noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', false, '2025-09-13 13:53:10.933502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ba6a8d3-2e3f-49ec-8b6e-4f5ffc6f5337', '4d733a6c-98f9-4e58-9681-f8bfe69450c6', 'c', 'El nudo llano se utiliza para afirmar una amarra a una argolla, mediante una gaza no corrediza.', false, '2025-09-13 13:53:10.933637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d09c800e-aa77-440b-9c11-eae7a9279b15', '4d733a6c-98f9-4e58-9681-f8bfe69450c6', 'd', 'La gaza es el lazo que se forma en el extremo de un cabo doblándolo y uniéndolo con costura o ligada, y que sirve para enganchar o ceñir algo o suspenderlo de alguna parte.', true, '2025-09-13 13:53:10.933781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4f2d677-dea7-4366-96a4-eb556e7bc30c', '1e64aa3c-4a17-4db7-921b-5bb87cf49041', 'a', 'En una embarcación de 10 metros de eslora, la línea de fondeo deberá tener un tramo de cadena de 5 metros de longitud.', false, '2025-09-13 13:53:10.934066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43ee3e02-ab64-4996-b679-9d102da297ec', '1e64aa3c-4a17-4db7-921b-5bb87cf49041', 'd', 'Se conoce como fondeo a la gira, al fondeo con un ancla por proa donde la embarcación puede girar de manera libre alrededor de esta.', true, '2025-09-13 13:53:10.934494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('684fc0a6-3382-446a-8939-495f8f27d049', '6d162b86-5ae6-4c13-8842-11a23a129958', 'a', 'Poniendo la popa al viento.', false, '2025-09-13 13:53:10.934781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9679a548-6621-44e2-b0d0-ca344620f003', '6d162b86-5ae6-4c13-8842-11a23a129958', 'b', 'Poniendo la amura a la mar.', true, '2025-09-13 13:53:10.934933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8903065-3d9d-4bc8-a8ad-b6cb2f9d37f8', '6d162b86-5ae6-4c13-8842-11a23a129958', 'c', 'Llevando la mar por la aleta.', false, '2025-09-13 13:53:10.935075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfe952b5-a98b-41c2-bb37-ad3a76994742', '6d162b86-5ae6-4c13-8842-11a23a129958', 'd', 'Reduciendo la arrancada por debajo de la velocidad de gobierno.', false, '2025-09-13 13:53:10.935216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8084340-7df4-4819-8233-0ca97c2b353d', '05a59696-68e0-48e5-9368-0f1481b1a14f', 'a', 'Encender todas las luces de navegación reglamentarias.', false, '2025-09-13 13:53:10.935511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1396e689-869b-4acc-ad8a-5e1e4851c561', '05a59696-68e0-48e5-9368-0f1481b1a14f', 'b', 'Reducir la velocidad parando siempre la embarcación.', true, '2025-09-13 13:53:10.935644+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0363128f-9b40-4f57-83f5-a0f05857b498', '05a59696-68e0-48e5-9368-0f1481b1a14f', 'c', 'Emitir las señales fónicas que sean reglamentarias.', false, '2025-09-13 13:53:10.935782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7defd0f3-63c1-4579-b65b-35922aa9b4df', '05a59696-68e0-48e5-9368-0f1481b1a14f', 'd', 'Tener listas las balsas salvavidas, si las llevamos, y tener colocados los chalecos salvavidas.', false, '2025-09-13 13:53:10.935914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df9e73df-876e-471c-a036-6cbecc59312a', '7e24cec8-4e87-4e0f-82b8-66636a9cb0ff', 'a', 'Cuando veamos caer al náufrago, meter el timón a la banda que haya caído el náufrago hasta caer 250º y en ese momento poner el timón a la vía y parar máquinas.', false, '2025-09-13 13:53:10.936192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccb3ee56-2906-4e41-a973-89ea45a6d7f1', '7e24cec8-4e87-4e0f-82b8-66636a9cb0ff', 'b', 'Cuando veamos caer al náufrago, con toda la máquina avante meter el timón a la banda que haya caído el náufrago hasta caer 70º, y en ese momento cambiar a la otra banda hasta alcanzar el rumbo opuesto al inicial.', false, '2025-09-13 13:53:10.936325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2dd8a97-8854-46ec-a2f4-d7e2e9d934da', '7e24cec8-4e87-4e0f-82b8-66636a9cb0ff', 'c', 'Cuando veamos caer al náufrago, meter el timón a la banda contraria a la que haya caído el náufrago hasta caer 240°, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto al inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', true, '2025-09-13 13:53:10.936458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('767534e7-c7a7-47f9-9cbe-1a5c40375b11', '7e24cec8-4e87-4e0f-82b8-66636a9cb0ff', 'd', 'Cuando no se ve caer al náufrago, activar el M.O.B. (Man Over Board) del GPS.', false, '2025-09-13 13:53:10.936589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5ce5b76-d6fe-4116-9813-5ac69206c088', '42735b63-b570-423a-91a8-4178db5fc928', 'a', 'Ninguna.', false, '2025-09-13 13:53:10.936996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc0c2b6d-dd95-4ee9-b499-4ce59b15dc7d', '42735b63-b570-423a-91a8-4178db5fc928', 'b', '1.', false, '2025-09-13 13:53:10.937131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('123ab33b-39c8-475b-ba81-05698cbd3ba2', '42735b63-b570-423a-91a8-4178db5fc928', 'c', '3.', true, '2025-09-13 13:53:10.937267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8089741-94e9-4071-a3a4-ca5006a81028', '42735b63-b570-423a-91a8-4178db5fc928', 'd', '6. 11', false, '2025-09-13 13:53:10.937398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14148782-cbd1-439a-9fb5-8020e0e5e262', '80cd9204-174a-4f69-9aef-9b50af46f659', 'a', 'Espacio marino del Odiel.', true, '2025-09-13 13:53:10.937816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e67630b-8e18-424d-8e2e-48570beb0b58', '80cd9204-174a-4f69-9aef-9b50af46f659', 'b', 'Cabo de Creus.', false, '2025-09-13 13:53:10.937983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('157c0f11-012e-4ef1-a1ae-cd5df0abc097', '80cd9204-174a-4f69-9aef-9b50af46f659', 'c', 'Islas Medes.', false, '2025-09-13 13:53:10.938145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fefb483-9cbc-4422-b25b-8107e04f80cf', '80cd9204-174a-4f69-9aef-9b50af46f659', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:10.938305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dce18baf-e6f0-4bd8-95de-60819ac95c71', 'b8b3a86c-1a07-49fd-b281-c632c7629c88', 'b', 'Sólo se utilizará en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:10.948031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7130913b-9300-45a9-833c-a2e25f0bf0ab', '8883b804-6463-46dc-b050-5b2ed9d4f27a', 'd', '6.', false, '2025-09-13 13:53:10.99399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7f9b32a-d3c7-4327-8460-4e6cf55ecf3d', 'e9d1df19-7481-4e15-b46d-1c64751dffba', 'd', '36º 0,0´N 005º 16 W.', false, '2025-09-13 13:53:10.92785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a18e6a13-aac2-486f-af5c-c0095738d3c4', '1e64aa3c-4a17-4db7-921b-5bb87cf49041', 'c', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a la proa de la embarcación.', false, '2025-09-13 13:53:10.934358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e990f481-1377-4e22-a1e4-a087d04130ee', 'ba966ec9-e17a-41ef-a957-4f6b2babae37', 'b', 'La navegación de cualquier buque o embarcación de recreo está permitida en la franja de mar contigua a la costa de una anchura de 50 metros en las playas y 200 metros de la costa, y siempre que no se exceda el límite de velocidad de tres nudos.', false, '2025-09-13 13:53:10.938832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('024ab026-3b10-4438-8c3a-8ab0052a7854', 'ba966ec9-e17a-41ef-a957-4f6b2babae37', 'c', 'Se entenderá que la zona de baño ocupa una franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto de la costa, no pudiendo navegar dentro de estas zonas a una velocidad superior a tres nudos.', true, '2025-09-13 13:53:10.938997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69225aa9-f2e3-4675-9848-f7b94672e522', 'ba966ec9-e17a-41ef-a957-4f6b2babae37', 'd', 'Está prohibida la navegación de cualquier buque o embarcación, salvo que estén dedicados exclusivamente al recreo, que podrán hacerlo sin limitaciones si su finalidad es fondear en calas o lugares de baño.', false, '2025-09-13 13:53:10.939163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96315c32-68a9-4b59-b17c-56e6870e9e82', '2e7cb0fc-21d2-4ac2-9e60-6f7f95c81f55', 'a', 'Corredera.', false, '2025-09-13 13:53:10.939493+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35a6ae8d-bad5-442b-b6eb-f3a51759028b', '2e7cb0fc-21d2-4ac2-9e60-6f7f95c81f55', 'b', 'Compás.', true, '2025-09-13 13:53:10.939663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3715d750-6890-4241-b73e-e56fc9388994', '2e7cb0fc-21d2-4ac2-9e60-6f7f95c81f55', 'c', 'Sonda.', false, '2025-09-13 13:53:10.939824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e82084a-4f01-4a02-ab09-47823cd07702', '2e7cb0fc-21d2-4ac2-9e60-6f7f95c81f55', 'd', 'Radar.', false, '2025-09-13 13:53:10.940014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e4c17b5-cf16-4492-b01e-6aecf410371a', '1ce7d754-7a2e-469a-b377-41f891b36c37', 'a', 'Por lo general, están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:10.940385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3561460-5243-4dc3-9e39-78a9ad4c6dda', '1ce7d754-7a2e-469a-b377-41f891b36c37', 'b', 'Se pueden usar para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:10.940541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e17433e-0959-4e9c-a544-d93a114bb467', '1ce7d754-7a2e-469a-b377-41f891b36c37', 'c', 'Se pueden usar para definir los ejes de los canales y las marcas de centro de canal.', false, '2025-09-13 13:53:10.940696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7df10d55-e998-445a-b621-1b894dcd8e08', '1ce7d754-7a2e-469a-b377-41f891b36c37', 'd', 'Por lo general, están destinadas para indicar el canal principal en el punto de bifurcación de este.', false, '2025-09-13 13:53:10.940875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02aff01c-c5f6-47f2-8be5-63d7cfebd799', '74204abd-600e-443d-beb5-e88d2178de79', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:10.941212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7bd2ac5-877e-486c-b613-d4f3ab9f49c8', '74204abd-600e-443d-beb5-e88d2178de79', 'b', 'Una esfera amarilla.', false, '2025-09-13 13:53:10.941374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4fb2f7d-601c-409d-a2f6-3c133898a007', '74204abd-600e-443d-beb5-e88d2178de79', 'c', 'Dos esferas negras.', true, '2025-09-13 13:53:10.941535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2851c7fe-e059-46d9-aa8e-29322d180f07', '74204abd-600e-443d-beb5-e88d2178de79', 'd', 'Dos esferas amarillas.', false, '2025-09-13 13:53:10.941695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30485476-0577-4856-b301-e83c9a5cc9cd', 'a08a503c-2f85-4645-88ae-20695d165ad0', 'a', 'El canal principal queda a estribor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', false, '2025-09-13 13:53:10.942036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a171382-2296-4e80-8f95-86131bcb3a30', 'a08a503c-2f85-4645-88ae-20695d165ad0', 'b', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en sentido opuesto al convencional de balizamiento.', false, '2025-09-13 13:53:10.942195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5332851d-9235-490a-9091-3a1129808506', 'a08a503c-2f85-4645-88ae-20695d165ad0', 'c', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', true, '2025-09-13 13:53:10.942355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e97010a5-101b-4d90-8ab2-ed4d38af2eb7', 'a08a503c-2f85-4645-88ae-20695d165ad0', 'd', 'El canal principal queda a babor, si estamos en una bifurcación y navegando hacia alta mar.', false, '2025-09-13 13:53:10.942516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3af99cd-8dc6-47a3-b815-acd2ba233364', '93ae0869-5270-4026-bd5b-b894992cd5d1', 'a', 'Un destello largo cada 10 segundos.', true, '2025-09-13 13:53:10.942979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8e1a1e3-ef9d-4338-b003-b5f4e897cf97', '93ae0869-5270-4026-bd5b-b894992cd5d1', 'b', 'Un destello largo cada 5 segundos.', false, '2025-09-13 13:53:10.943126+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b7961c2-f6f2-4965-a964-8f5dd751cc81', '93ae0869-5270-4026-bd5b-b894992cd5d1', 'c', 'Grupos de dos destellos GpD (2), cada 10 segundos.', false, '2025-09-13 13:53:10.943261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83adffef-b3fd-46c6-9de4-8254f933eee5', '933d6c13-85ec-448d-8a90-600fbca84026', 'a', 'De forma cónica con el que se refuerza el sonido emitido, muy útil para hablar desde lejos.', false, '2025-09-13 13:53:10.943682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36c7af7e-5718-4079-936c-889a466a0fb6', '933d6c13-85ec-448d-8a90-600fbca84026', 'b', 'Metálico, generalmente en forma de copa invertida, que suena al ser golpeado por un badajo.', false, '2025-09-13 13:53:10.943818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d69b9250-36a8-4e97-a676-b3b50c260f30', '933d6c13-85ec-448d-8a90-600fbca84026', 'c', 'De percusión formado por un disco que vibra al ser golpeado.', false, '2025-09-13 13:53:10.943951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cb7c937-c775-415e-8dfd-a24fdf28dd83', '933d6c13-85ec-448d-8a90-600fbca84026', 'd', 'Capaz de producir las pitadas reglamentarias y que cumple con las especificaciones del anexo III del Reglamento.', true, '2025-09-13 13:53:10.944082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bbb9f03-eae4-4d99-ac63-3891802a90d1', '8e2ec195-00ef-4ca1-8efb-ba23d1e0fdaa', 'a', 'La responsabilidad estará limitada en todo caso al propietario del buque.', false, '2025-09-13 13:53:10.944355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30cb51c1-b8c4-43a0-b7cc-007b11371f21', '8e2ec195-00ef-4ca1-8efb-ba23d1e0fdaa', 'b', 'Únicamente el Capitán será responsable de las consecuencias de cualquier negligencia en el cumplimiento de este Reglamento.', false, '2025-09-13 13:53:10.944487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc0d79b1-661b-466f-abb2-de17fc9590cd', '8e2ec195-00ef-4ca1-8efb-ba23d1e0fdaa', 'c', 'Ninguna disposición del Reglamento eximirá a un buque, o a su propietario, al Capitán o a la dotación del mismo de las consecuencias de cualquier negligencia en el cumplimiento de éste.', true, '2025-09-13 13:53:10.944622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d3f31d5-6cf6-4e83-bbc8-fc17dda9b33b', '8e2ec195-00ef-4ca1-8efb-ba23d1e0fdaa', 'd', 'En ningún caso la dotación será responsable.', false, '2025-09-13 13:53:10.944752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e6c31e7-3982-4b12-bdc1-0b7afb90cd7f', 'd62a2694-666e-4669-943c-c021d88af6d5', 'a', 'Para no quedar bien franco del otro buque.', false, '2025-09-13 13:53:10.945033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08d1e3f7-d343-4ad6-a0c2-e4e6022e1ba5', 'd62a2694-666e-4669-943c-c021d88af6d5', 'b', 'De forma decidida.', true, '2025-09-13 13:53:10.94517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ffeff08-9aa3-4d80-8527-8bc8e0e79f1e', 'd62a2694-666e-4669-943c-c021d88af6d5', 'c', 'Manteniendo siempre el rumbo inicial y variando sólo la velocidad.', false, '2025-09-13 13:53:10.945304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19d5b9ee-fb3d-42a3-9928-368c264cc60c', 'd62a2694-666e-4669-943c-c021d88af6d5', 'd', 'Con maniobras suaves y contrarias para indicar al otro buque que va a maniobrar y que aquél debe mantener su derrota.', false, '2025-09-13 13:53:10.945437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4960458b-f611-4acb-95b6-2b3adcbbe036', '42da2670-a169-496f-ba7d-fb897d8ae305', 'a', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:10.945705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47830ee6-91e9-4c14-80d0-501d82eded57', '42da2670-a169-496f-ba7d-fb897d8ae305', 'b', 'Una pitada larga a intervalos que no excedan de dos minutos.', true, '2025-09-13 13:53:10.945851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb4670c4-1f49-4260-bf0b-7771c6a9a43d', '42da2670-a169-496f-ba7d-fb897d8ae305', 'c', 'Una pitada corta a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:10.94598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a4e0400-6043-412e-9908-32f0b2423f53', '42da2670-a169-496f-ba7d-fb897d8ae305', 'd', 'Una pitada larga a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:10.946108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dd50743-718c-4c63-b3c5-9f3829fe5faf', '248c9e2a-24e1-48bc-81b6-2cf72317759e', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y ninguna de las luces de costado.', true, '2025-09-13 13:53:10.946375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7d41092-b1f2-46a2-aaee-978d89fb4cf4', '248c9e2a-24e1-48bc-81b6-2cf72317759e', 'b', 'Se mantendrá lo más cerca posible de la derrota del buque alcanzado.', false, '2025-09-13 13:53:10.946504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2baaa0ef-746f-48f1-82ab-745b7429f658', '248c9e2a-24e1-48bc-81b6-2cf72317759e', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:10.946631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b75a8d8a-5d53-4c28-8c20-1b567f9ed7b6', '248c9e2a-24e1-48bc-81b6-2cf72317759e', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:10.946759+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12814116-dbf3-4fef-80d0-a905805ac053', '005055a6-4d76-41ed-be2b-2c155ef66fbf', 'a', 'Como regla general, toda maniobra que se efectúe para evitar un abordaje será llevada a cabo en forma clara, con la debida antelación y respetando las buenas prácticas marineras.', false, '2025-09-13 13:53:10.947042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb80faf-6e00-49c7-bd4f-420e4f7ef2a1', '005055a6-4d76-41ed-be2b-2c155ef66fbf', 'b', 'Si es necesario con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad.', false, '2025-09-13 13:53:10.947174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00997975-ee0c-4ad2-bb04-2479e6b7aa47', '005055a6-4d76-41ed-be2b-2c155ef66fbf', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasando al otro.', false, '2025-09-13 13:53:10.947306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00b64c8c-7e7f-4a8b-821f-c2d9e5f524fc', '005055a6-4d76-41ed-be2b-2c155ef66fbf', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños.', true, '2025-09-13 13:53:10.947434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34a13b3e-4117-481a-9b33-1ad479d32b25', 'b8b3a86c-1a07-49fd-b281-c632c7629c88', 'a', 'Es siempre la misma para un buque de vela.', false, '2025-09-13 13:53:10.947891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb596431-8af2-448a-ae6a-a0c52b8c49f7', '93ae0869-5270-4026-bd5b-b894992cd5d1', 'd', 'Grupos de dos destellos GpD (2), cada 5 segundos.', false, '2025-09-13 13:53:10.943393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e681aad-70d9-48b7-be40-15bcdd411dbf', 'b8b3a86c-1a07-49fd-b281-c632c7629c88', 'c', 'Para determinarla no se tendrá en cuenta la densidad del tráfico.', false, '2025-09-13 13:53:10.948164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb7ef32a-4fff-49c3-a447-8767bec27c60', 'b8b3a86c-1a07-49fd-b281-c632c7629c88', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje.', true, '2025-09-13 13:53:10.948302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01eb1919-7f2a-41b6-98a2-7491df059cbb', 'ccf9fd94-a04b-491e-95ad-eea741d5e392', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:10.948582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab7aa0b7-ef37-4cd5-bf59-83b08585cfc3', 'ccf9fd94-a04b-491e-95ad-eea741d5e392', 'b', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:10.948713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c39e65a-c2ce-40c0-b1df-11cefdf2201d', 'ccf9fd94-a04b-491e-95ad-eea741d5e392', 'c', 'Una luz de alcance y luces de costado.', false, '2025-09-13 13:53:10.948856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32a9c842-8978-4799-8660-c6d97964b231', 'ccf9fd94-a04b-491e-95ad-eea741d5e392', 'd', 'Una luz de alcance, luces de costado y una luz centelleante.', false, '2025-09-13 13:53:10.948989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a06f22e7-bfe9-406b-818b-60686ca083cd', '9c0dd731-380f-4256-921b-4f32bffe01db', 'a', 'Cuya velocidad máxima no sea superior a quince nudos.', false, '2025-09-13 13:53:10.949266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6fae62d-5d6f-4c49-a18b-f91a98cbd230', '9c0dd731-380f-4256-921b-4f32bffe01db', 'b', 'Cuya velocidad máxima no sea superior a doce nudos.', false, '2025-09-13 13:53:10.949398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f90b644e-5fb8-428a-a4bf-725af97a0e03', '9c0dd731-380f-4256-921b-4f32bffe01db', 'c', 'De eslora inferior a 20 metros.', false, '2025-09-13 13:53:10.94953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40231a65-710e-47df-a70c-95575b7337d3', '9c0dd731-380f-4256-921b-4f32bffe01db', 'd', 'De eslora inferior a 12 metros.', true, '2025-09-13 13:53:10.949661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f808b896-6261-49d8-82f9-fa585bbd529e', '30ee0982-3f5b-4b56-844c-a6afe715d570', 'a', 'El buque que deba mantenerse apartado de la derrota del otro mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:10.949942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8857790a-1238-497b-bb24-69a6a267a2b8', '30ee0982-3f5b-4b56-844c-a6afe715d570', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último se detendrá obligatoriamente. Maniobra y navegación.', false, '2025-09-13 13:53:10.950487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93e15463-d4b0-46ec-bb66-94b0b4789ff0', 'a68c49f8-c996-4d45-8929-10535ea27bd9', 'a', 'Todo a estribor.', false, '2025-09-13 13:53:10.95077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce306de6-13bd-4c51-84c9-a70fe9ce7eaa', 'a68c49f8-c996-4d45-8929-10535ea27bd9', 'b', 'Todo a babor.', false, '2025-09-13 13:53:10.950922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce1d990c-8bd8-40c2-84bf-a7c42483d060', 'a68c49f8-c996-4d45-8929-10535ea27bd9', 'c', 'Trincar el timón.', false, '2025-09-13 13:53:10.951057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9318bfa3-1eab-414a-914f-075a67835812', 'a68c49f8-c996-4d45-8929-10535ea27bd9', 'd', 'Que el plano del timón coincide con el plano de crujía de la embarcación.', true, '2025-09-13 13:53:10.951191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1ee30a4-1df6-4540-8d99-f4dfaea61fb3', 'f28a6fe0-9027-49a5-ad42-62a5ecbc368e', 'a', 'Un esprín de proa.', true, '2025-09-13 13:53:10.951468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54e1dfd7-04d5-406e-828a-e6c3fec82804', 'f28a6fe0-9027-49a5-ad42-62a5ecbc368e', 'b', 'Un largo de proa.', false, '2025-09-13 13:53:10.9516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73236be6-c5e7-4808-bc5b-d7bcf2333615', 'f28a6fe0-9027-49a5-ad42-62a5ecbc368e', 'c', 'Un través a proa.', false, '2025-09-13 13:53:10.951731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cee92523-7a3f-4e1b-8427-948bb2438ba2', 'fdc63425-e35d-4a9e-8a36-0f73258a313f', 'a', 'Un cohete lanzabengalas con paracaídas.', true, '2025-09-13 13:53:10.952142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51e9c758-29aa-4816-bafc-f6ff5b8a09a9', 'fdc63425-e35d-4a9e-8a36-0f73258a313f', 'b', 'Una bengala de mano.', false, '2025-09-13 13:53:10.952273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66896b45-8e4d-4187-b7bd-43f407329806', 'fdc63425-e35d-4a9e-8a36-0f73258a313f', 'c', 'Una señal fumígena flotante.', false, '2025-09-13 13:53:10.952404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cdf3ae7-d929-47f2-9a62-5218e768c675', 'fdc63425-e35d-4a9e-8a36-0f73258a313f', 'd', 'Una bengala flotante con señal fumígena alterna.', false, '2025-09-13 13:53:10.952534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bb1ade9-6fef-4c02-98c3-9ba05e729e7b', '7aca349c-a931-4322-9a73-24ced2250a6e', 'a', 'Las quemaduras de 2º grado afectan a la capa profunda y aparecen ampollas con líquido claro y dolor intenso. Las ampollas deben recortarse sólo si ya se han roto.', false, '2025-09-13 13:53:10.952809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acbee7c0-1ce3-4b10-a517-fa22a5fd5352', '7aca349c-a931-4322-9a73-24ced2250a6e', 'b', 'Una herida que esté infectada o presente una hemorragia se considerará una herida grave y en ese caso, se cubrirá con un apósito estéril y no se aplicarán antisépticos ni pomadas.', false, '2025-09-13 13:53:10.952948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36183aff-9523-459f-9783-326e2cb3a850', '7aca349c-a931-4322-9a73-24ced2250a6e', 'c', 'En el caso de que se produzca un golpe de calor con temperatura corporal por encima de 40ºC, hay que bajar la temperatura hasta los 39º C y controlarlo cada 10 minutos.', false, '2025-09-13 13:53:10.95309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bddb2df-faaf-4d00-adba-03d09237150c', '7aca349c-a931-4322-9a73-24ced2250a6e', 'd', 'La asistencia médica del Centro Radio-Médico Español está disponible todos los días del año, entre las 6:00 y las 00:00 horas (hora de Madrid).', true, '2025-09-13 13:53:10.953223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aad8aae5-5ccf-4c9c-a3d3-1eca55ddc91d', 'ee7b7ba3-dacb-4e2d-9667-e210d76350e1', 'a', 'Determinar la posición y avisar inmediatamente a Salvamento Marítimo.', false, '2025-09-13 13:53:10.953501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07899c41-0028-4a38-b8e2-97dc11a3d437', 'ee7b7ba3-dacb-4e2d-9667-e210d76350e1', 'c', 'Abandonar la embarcación.', false, '2025-09-13 13:53:10.953758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d309439-e42e-4f85-9a0e-4d1f6d058435', 'ee7b7ba3-dacb-4e2d-9667-e210d76350e1', 'd', 'Dar atrás toda con timón a la vía, para salir de la varada antes de que el casco sufra más daños. Meteorología', false, '2025-09-13 13:53:10.953901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1055968f-e82a-4a44-b12f-d515991b9fd4', '32117562-8e40-4733-aaf7-8681c95bba71', 'a', 'Veleta.', false, '2025-09-13 13:53:10.954169+00');
