INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8f49087-cb1e-49e7-84ad-676a3dd95181', 'f404d8d8-3f0d-4e77-9e1f-f3e2a5015910', 'b', 'Para indicarla se puede usar la escala Celsius.', false, '2025-09-13 13:53:10.955051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aff4cde9-3806-48c2-a133-f1871897ec84', 'f404d8d8-3f0d-4e77-9e1f-f3e2a5015910', 'c', 'Disminuye cuando aumenta la presión atmosférica.', true, '2025-09-13 13:53:10.955189+00');
