INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16c4a36d-b144-4865-9e49-ffba472f304d', '45715404-a3bf-45a1-968a-180e208d6728', 'a', 'La zona central posee una presión mayor que la de la periferia.', false, '2025-09-13 13:53:10.956438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c351c34d-6f06-497d-b56e-6e2c8ba8bb48', '45715404-a3bf-45a1-968a-180e208d6728', 'b', 'El aire circula en sentido horario en el hemisferio norte.', false, '2025-09-13 13:53:10.956597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c77cf6e-4f7f-4e45-8b2c-b23839160126', '45715404-a3bf-45a1-968a-180e208d6728', 'c', 'La zona central posee una presión menor que la de la periferia.', true, '2025-09-13 13:53:10.956746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67ee82e0-6d72-4389-8359-05dd7ac61746', '3c7f04b2-72d7-461b-84c5-09e2738d401a', 'a', 'Declinación magnética y siempre es positivo en el hemisferio norte.', false, '2025-09-13 13:53:10.95721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8777766-5507-4b4e-903f-ea21207934b6', '3c7f04b2-72d7-461b-84c5-09e2738d401a', 'c', 'Declinación magnética y su valor es positivo cuando el Norte magnético queda a la derecha del Norte verdadero y negativo en caso contrario.', true, '2025-09-13 13:53:10.957488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44951c7b-533a-44d6-9c91-5202e9088bb2', '3c7f04b2-72d7-461b-84c5-09e2738d401a', 'd', 'Declinación magnética y su valor es positivo cuando el Norte magnético queda a la izquierda del Norte verdadero y negativo en caso contrario.', false, '2025-09-13 13:53:10.957621+00');
