INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45bc5eb2-921c-45a2-8c90-09961b2e1623', '52a9c0c2-e89d-4d1a-b7ed-b56cd4fa3e4f', 'b', 'El periodo es de 6 segundos.', false, '2025-09-13 13:53:10.958716+00');
