INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('167f1003-a9a2-4364-80ec-74ab34e516c0', '3826233b-307b-4988-8a7f-85822ef06a03', 'a', 'Es la inclinación del buque hacia un costado, por la acción del viento u otra fuerza.', true, '2025-09-13 13:53:10.990808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a7fec0f-b071-48b8-8e97-3f5e6756ff88', '3826233b-307b-4988-8a7f-85822ef06a03', 'b', 'Es colocar una embarcación al lado de otra o de un muelle, de forma tal que quede en contacto por su costado.', false, '2025-09-13 13:53:10.990941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39242e24-3eec-4dfc-b25b-75075f4700b2', '3826233b-307b-4988-8a7f-85822ef06a03', 'c', 'Es la caída del buque hacia sotavento por efecto del viento.', false, '2025-09-13 13:53:10.99107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56a66a46-3518-4528-946b-9b476879e6dc', '3826233b-307b-4988-8a7f-85822ef06a03', 'd', 'Es la distancia que recorre un barco por efecto de la corriente, es decir, por el desplazamiento de la masa de agua en la que se encuentra.', false, '2025-09-13 13:53:10.991197+00');
