INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cde9052f-64fa-4d6e-aafb-19c5de2e864a', '74accc38-09a4-4dc0-bbf4-783e105f668a', 'b', 'El noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', false, '2025-09-13 13:53:10.992255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('303a366c-8c39-43df-86a4-f9b4bdf6bacc', '74accc38-09a4-4dc0-bbf4-783e105f668a', 'c', 'El nudo llano se utiliza para afirmar una amarra a una argolla, mediante una gaza no corrediza.', false, '2025-09-13 13:53:10.992413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50092589-6229-4cf4-a875-29b93c5c5dd3', '74accc38-09a4-4dc0-bbf4-783e105f668a', 'd', 'La gaza es el lazo que se forma en el extremo de un cabo doblándolo y uniéndolo con costura o ligada, y que sirve para enganchar o ceñir algo o suspenderlo de alguna parte.', true, '2025-09-13 13:53:10.99255+00');
