INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('968abd24-e483-4376-950e-074f39070ca6', 'a624dc59-f1f8-471c-acf4-16f99406a2fd', 'c', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a la proa de la', false, '2025-09-13 13:53:10.993083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74e227f6-14f0-40cf-8e7a-0fe5f0c69e35', 'a624dc59-f1f8-471c-acf4-16f99406a2fd', 'd', 'Se conoce como fondeo a la gira, al fondeo con un ancla por proa donde la embarcación puede girar de manera libre alrededor de esta.', true, '2025-09-13 13:53:10.99321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82b9d9c0-2bfb-41b3-919a-ffde4ac21709', '8883b804-6463-46dc-b050-5b2ed9d4f27a', 'a', 'Ninguna.', false, '2025-09-13 13:53:10.993475+00');
