INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9cee13d-7921-48c5-b976-c3b44f46e3c7', '1b071ecc-d520-40d2-8f1c-5ede3e8b0a75', 'd', 'Varía a lo largo del tiempo.', false, '2025-09-13 13:53:10.986244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8de868ee-6d01-4768-b3a0-a7a20bbe10b9', '3c1ff4f4-2ce2-439d-adb5-f7902195d6f1', 'b', 'Desvío y su valor positivo o negativo depende de la compensación, debido a los hierros dulces de abordo.', false, '2025-09-13 13:53:10.983137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0cc7ade-4416-400a-a08d-1a14ac883e78', 'c6001f6b-226c-49b3-ad3f-b9c8baf0b196', 'b', 'Reducir la velocidad parando siempre la embarcación.', true, '2025-09-13 13:53:10.994512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dfc1206-6cae-4528-8806-52e864e50859', 'c6001f6b-226c-49b3-ad3f-b9c8baf0b196', 'c', 'Emitir las señales fónicas que sean reglamentarias.', false, '2025-09-13 13:53:10.994665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('395d5ca9-3eaf-4c0a-bc6d-9f14995d02a5', 'c6001f6b-226c-49b3-ad3f-b9c8baf0b196', 'd', 'Tener listas las balsas salvavidas, si las llevamos, y tener colocados los chalecos salvavidas.', false, '2025-09-13 13:53:10.994796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6886fd7b-f76b-4efb-8e72-2c7c7cb40fd5', '15848214-fb88-4029-8339-32b871b16abc', 'a', 'Poniendo la popa al viento.', false, '2025-09-13 13:53:10.995218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76e382a9-5842-4dc9-b154-647064f453fc', '15848214-fb88-4029-8339-32b871b16abc', 'b', 'Poniendo la amura a la mar.', true, '2025-09-13 13:53:10.995348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47b89b3c-9c82-4d60-822b-08c1b8b84516', '15848214-fb88-4029-8339-32b871b16abc', 'c', 'Llevando la mar por la aleta.', false, '2025-09-13 13:53:10.995473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1886e1fa-6613-47ef-b4ce-57e17cfb5df3', '15848214-fb88-4029-8339-32b871b16abc', 'd', 'Reduciendo la arrancada por debajo de la velocidad de gobierno.', false, '2025-09-13 13:53:10.995604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed56b6d6-c768-407b-8e4a-b93ba9c57a7f', '7209ee3a-ba16-4168-ab81-f106c5b1b9bd', 'a', 'Cuando veamos caer al náufrago, meter el timón a la banda que haya caído el náufrago hasta caer 250º y en ese momento poner el timón a la vía y parar máquinas.', false, '2025-09-13 13:53:10.99589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9be6f549-c214-45cc-acd1-af14cac4352e', '7209ee3a-ba16-4168-ab81-f106c5b1b9bd', 'b', 'Cuando veamos caer al náufrago, con toda la máquina avante meter el timón a la banda que haya caído el náufrago hasta caer 70º, y en ese momento cambiar a la otra banda hasta alcanzar el rumbo opuesto al inicial.', false, '2025-09-13 13:53:10.99602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b54639fa-ae2a-4d82-9d50-c38325e17e28', '7209ee3a-ba16-4168-ab81-f106c5b1b9bd', 'c', 'Cuando veamos caer al náufrago, meter el timón a la banda contraria a la que haya caído el náufrago hasta caer 240°, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto al inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', true, '2025-09-13 13:53:10.996148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90dcc5e1-fe2b-4f3e-a397-3309daa9291b', '7209ee3a-ba16-4168-ab81-f106c5b1b9bd', 'd', 'Cuando no se ve caer al náufrago, activar el M.O.B. (Man Over Board) del GPS.', false, '2025-09-13 13:53:10.99628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a820e42c-9e34-4291-b286-74e4bca99847', '4cc08361-e779-42d9-9e9d-e1854ec56701', 'a', 'La navegación de cualquier buque o embarcación de recreo está completamente prohibida en la franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto', false, '2025-09-13 13:53:10.996616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9e1b790-c7bd-4220-a2df-c6a4eaa267f6', '4cc08361-e779-42d9-9e9d-e1854ec56701', 'b', 'La navegación de cualquier buque o embarcación de recreo está permitida en la franja de mar contigua a la costa de una anchura de 50 metros en las playas y 200 metros de la costa, y siempre que no se exceda el límite de velocidad de tres nudos.', false, '2025-09-13 13:53:10.996765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('684f7640-019e-4341-8020-34c03a062db0', '4cc08361-e779-42d9-9e9d-e1854ec56701', 'c', 'Se entenderá que la zona de baño ocupa una franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto de la costa, no pudiendo navegar dentro de estas zonas a una velocidad superior a tres nudos.', true, '2025-09-13 13:53:10.996902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69a70324-5e49-49b9-b5a4-91d7e27ab626', '4cc08361-e779-42d9-9e9d-e1854ec56701', 'd', 'Está prohibida la navegación de cualquier buque o embarcación, salvo que estén dedicados exclusivamente al recreo, que podrán hacerlo sin limitaciones si su finalidad es fondear en calas o lugares de baño. 12', false, '2025-09-13 13:53:10.997037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('245cddb7-b375-4aca-b594-ca03faa41e8a', '37076be7-aa46-4b2f-9c09-76daca93d704', 'a', 'Espacio marino del Odiel.', true, '2025-09-13 13:53:10.99732+00');
