INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('110c467c-0b44-45d3-a391-9f3b111be24b', '37996b9e-7a36-45b4-ba3f-d3809130e6ae', 'a', 'Corredera.', false, '2025-09-13 13:53:10.998155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff3d7340-7a9b-4619-acd2-9fcec1acab39', '37996b9e-7a36-45b4-ba3f-d3809130e6ae', 'b', 'Compás.', true, '2025-09-13 13:53:10.998292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb12dc16-56b5-4ad7-b237-647649e6fcdd', '37996b9e-7a36-45b4-ba3f-d3809130e6ae', 'c', 'Sonda.', false, '2025-09-13 13:53:10.998441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8890189-9285-4ef5-ad82-fd67b3ba7b83', '37996b9e-7a36-45b4-ba3f-d3809130e6ae', 'd', 'Radar.', false, '2025-09-13 13:53:10.998573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('302d6508-4053-4956-93a9-add87bd44b9c', '6eb8eafc-31cf-4dca-8a45-8cd728f6df26', 'a', 'Un destello largo cada 10 segundos.', true, '2025-09-13 13:53:10.99885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9ebe503-fd54-4a50-b3ff-10ce5a1fa1a0', '6eb8eafc-31cf-4dca-8a45-8cd728f6df26', 'b', 'Un destello largo cada 5 segundos.', false, '2025-09-13 13:53:10.998983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10b0c7cb-3108-4a46-9fa0-d4edcf660439', '6eb8eafc-31cf-4dca-8a45-8cd728f6df26', 'c', 'Grupos de dos destellos GpD (2), cada 10 segundos.', false, '2025-09-13 13:53:10.999113+00');
