INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3dcb1fdd-1fd7-4ec6-a69b-0273e95094e0', '7dcfdfd4-1bda-477a-aa08-f31d749728d0', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:10.999516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a21f0830-ad18-4fc7-b013-53c97529a91a', '7dcfdfd4-1bda-477a-aa08-f31d749728d0', 'b', 'Una esfera amarilla.', false, '2025-09-13 13:53:10.999646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f643f111-05f6-4dae-bfa8-295456cc7793', '7dcfdfd4-1bda-477a-aa08-f31d749728d0', 'c', 'Dos esferas negras.', true, '2025-09-13 13:53:10.999801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e11ad383-c75f-4efc-9b6b-9e541c479d86', '7dcfdfd4-1bda-477a-aa08-f31d749728d0', 'd', 'Dos esferas amarillas.', false, '2025-09-13 13:53:10.999932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('feabd559-9dc2-452f-938a-dabc13c801fa', '9fcdc1f6-6370-4aff-a620-6fa69f07d6a7', 'a', 'Por lo general, están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:11.000203+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('442e8c04-d34f-4ce6-9970-148dc5ac151c', '9fcdc1f6-6370-4aff-a620-6fa69f07d6a7', 'b', 'Se pueden usar para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:11.000339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79853273-859f-44fe-89b6-805ea78478f3', '9fcdc1f6-6370-4aff-a620-6fa69f07d6a7', 'c', 'Se pueden usar para definir los ejes de los canales y las marcas de centro de canal.', false, '2025-09-13 13:53:11.000472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a224ea9-66bd-4e13-9ce2-9539268d5358', '9fcdc1f6-6370-4aff-a620-6fa69f07d6a7', 'd', 'Por lo general, están destinadas para indicar el canal principal en el punto de bifurcación de este.', false, '2025-09-13 13:53:11.000607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9c0b6b2-831b-4ec2-a903-6b8a8aec8aee', '69bdf11d-b5da-45ce-8827-c507bb93a0e8', 'a', 'El canal principal queda a estribor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', false, '2025-09-13 13:53:11.001023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb3a941b-a342-407b-b4ca-821f0d1a9369', '69bdf11d-b5da-45ce-8827-c507bb93a0e8', 'b', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en sentido opuesto al convencional de balizamiento.', false, '2025-09-13 13:53:11.001155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('673809cc-c6c5-434b-8291-116e797ea847', '69bdf11d-b5da-45ce-8827-c507bb93a0e8', 'c', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', true, '2025-09-13 13:53:11.001285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e2d5b3e-da9c-4cf1-9920-36bcd5fdb38a', '69bdf11d-b5da-45ce-8827-c507bb93a0e8', 'd', 'El canal principal queda a babor, si estamos en una bifurcación y navegando hacia alta mar. Reglamento (RIPA).', false, '2025-09-13 13:53:11.001421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1855ceaa-3b9b-4373-96a6-607b85cdc771', 'c2b7c5d6-82f5-47cd-b3d2-0e9ac10e8301', 'a', 'La responsabilidad estará limitada en todo caso al propietario del buque.', false, '2025-09-13 13:53:11.001703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('118934ed-b295-4c28-a52e-00a34edea686', 'c2b7c5d6-82f5-47cd-b3d2-0e9ac10e8301', 'b', 'Únicamente el Capitán será responsable de las consecuencias de cualquier negligencia en el cumplimiento de este Reglamento.', false, '2025-09-13 13:53:11.001848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd74769e-5663-4d66-ba37-beec35ae582a', 'c2b7c5d6-82f5-47cd-b3d2-0e9ac10e8301', 'c', 'Ninguna disposición del Reglamento eximirá a un buque, o a su propietario, al Capitán o a la dotación del mismo de las consecuencias de cualquier negligencia en el cumplimiento de éste.', true, '2025-09-13 13:53:11.001987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26aede72-23fb-45c7-857c-a0ca138452d7', 'c2b7c5d6-82f5-47cd-b3d2-0e9ac10e8301', 'd', 'En ningún caso la dotación será responsable.', false, '2025-09-13 13:53:11.002123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14647f91-f465-4439-b463-18e870f9a460', '0b4946c2-1354-4ae1-8950-f5512cb37faf', 'a', 'Para no quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.002414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0de1c31f-aa2f-4848-b6eb-aa0e548fb6f0', '0b4946c2-1354-4ae1-8950-f5512cb37faf', 'b', 'De forma decidida.', true, '2025-09-13 13:53:11.002554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2e772aa-855b-4605-a519-e1c067c7eb64', '0b4946c2-1354-4ae1-8950-f5512cb37faf', 'c', 'Manteniendo siempre el rumbo inicial y variando sólo la velocidad.', false, '2025-09-13 13:53:11.002688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f4c4183-edfd-4982-a67b-0125c68b2938', '0b4946c2-1354-4ae1-8950-f5512cb37faf', 'd', 'Con maniobras suaves y contrarias para indicar al otro buque que va a maniobrar y que aquél debe mantener su derrota.', false, '2025-09-13 13:53:11.002823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2587237-5a6b-4ed4-89e4-557e994be8c4', 'a84cd272-b829-485f-b010-0e1a7464bef4', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y ninguna de las luces de costado.', true, '2025-09-13 13:53:11.003099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9db4cfca-04a4-417c-a2ee-9c6d5fe377a7', 'a84cd272-b829-485f-b010-0e1a7464bef4', 'b', 'Se mantendrá lo más cerca posible de la derrota del buque alcanzado.', false, '2025-09-13 13:53:11.003233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ea12f3c-c49d-4282-b740-64c3856d6682', 'a84cd272-b829-485f-b010-0e1a7464bef4', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:11.003363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5777c56b-f547-4dc7-bfdf-d46bddea7dcb', 'bab81ce1-a555-44ef-bbbb-f76abf6f3ea5', 'd', 'En ningún caso la dotación será responsable.', false, '2025-09-13 13:53:11.0219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4270cd3e-9d8d-4de8-b5d9-d9b2557901d2', 'a84cd272-b829-485f-b010-0e1a7464bef4', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:11.003494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96338aa0-c8fb-495e-a297-e20f3e0ee439', '2bcb6ff0-6f06-4a4e-91b8-b6da2543aa18', 'a', 'Es siempre la misma para un buque de vela.', false, '2025-09-13 13:53:11.003786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee7900a6-2fc3-438e-a65a-5b4931266cb2', '2bcb6ff0-6f06-4a4e-91b8-b6da2543aa18', 'b', 'Sólo se utilizará en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.00392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcd203cd-d72d-4056-a2cf-58a9e3ba6b08', '2bcb6ff0-6f06-4a4e-91b8-b6da2543aa18', 'c', 'Para determinarla no se tendrá en cuenta la densidad del tráfico.', false, '2025-09-13 13:53:11.00405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31705a53-2eb1-4e07-93fa-94e558d931c4', '2bcb6ff0-6f06-4a4e-91b8-b6da2543aa18', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje.', true, '2025-09-13 13:53:11.004179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7db0dc8-dd0e-4576-84e9-2a5e9f5d6119', '64ddfc46-fb5c-4ccb-89cd-ef3f3cc77101', 'a', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:11.004491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb40de60-8f31-4a50-8479-f583bfd4074e', '64ddfc46-fb5c-4ccb-89cd-ef3f3cc77101', 'b', 'Una pitada larga a intervalos que no excedan de dos minutos.', true, '2025-09-13 13:53:11.004623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('206864fe-0d6c-4d37-adad-e647b4700428', '64ddfc46-fb5c-4ccb-89cd-ef3f3cc77101', 'c', 'Una pitada corta a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:11.004755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f06454f8-2db0-44bb-b48e-138e9c4f0a0d', '64ddfc46-fb5c-4ccb-89cd-ef3f3cc77101', 'd', 'Una pitada larga a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:11.004899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7afecf6-7e49-4195-8a31-91e6f4bb9c5c', '8ebc8511-b26d-42e6-9525-49f896bcd09a', 'a', 'De forma cónica con el que se refuerza el sonido emitido, muy útil para hablar desde lejos.', false, '2025-09-13 13:53:11.005191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73a95073-0698-4a3f-8370-a60475766ce8', '8ebc8511-b26d-42e6-9525-49f896bcd09a', 'b', 'Metálico, generalmente en forma de copa invertida, que suena al ser golpeado por un badajo.', false, '2025-09-13 13:53:11.005326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('502f7246-7afd-4a7f-bf15-e54e2dc95bf5', '8ebc8511-b26d-42e6-9525-49f896bcd09a', 'c', 'De percusión formado por un disco que vibra al ser golpeado.', false, '2025-09-13 13:53:11.005453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5efd9cb5-58a2-4de6-b62b-3c7bd4685a9a', '8ebc8511-b26d-42e6-9525-49f896bcd09a', 'd', 'Capaz de producir las pitadas reglamentarias y que cumple con las especificaciones del anexo III del Reglamento.', true, '2025-09-13 13:53:11.005584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fa81b27-3d6b-4ecb-848f-355e46bc1a4e', 'f5fd927a-3ee5-4daf-a7cf-b253245c6346', 'a', 'El buque que deba mantenerse apartado de la derrota del otro mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:11.005992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b902471f-495d-4d4a-9139-ddcde7d25c92', 'f5fd927a-3ee5-4daf-a7cf-b253245c6346', 'b', 'No exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del', true, '2025-09-13 13:53:11.006124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e3e5780-1808-4504-9edd-71de1054ab0b', 'f5fd927a-3ee5-4daf-a7cf-b253245c6346', 'c', 'Solamente el buque que ceda el paso podrá ejecutar la maniobra que mejor pueda ayudar a evitar', false, '2025-09-13 13:53:11.006262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc819364-aef8-4e79-83db-e59c4300a261', 'f5fd927a-3ee5-4daf-a7cf-b253245c6346', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último se detendrá obligatoriamente.', false, '2025-09-13 13:53:11.006397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2a46e00-b658-426a-8355-1fa005eb2640', '4204984d-a504-4918-907f-a2d393978ab4', 'a', 'Cuya velocidad máxima no sea superior a quince nudos.', false, '2025-09-13 13:53:11.006676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51ddc1d2-69c5-4279-987f-a64891d1e2b3', '4204984d-a504-4918-907f-a2d393978ab4', 'b', 'Cuya velocidad máxima no sea superior a doce nudos.', false, '2025-09-13 13:53:11.00683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f0da474-52fb-4d49-90ff-46ea1456b3df', '4204984d-a504-4918-907f-a2d393978ab4', 'c', 'De eslora inferior a 20 metros.', false, '2025-09-13 13:53:11.006964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d639c5d9-42ea-4471-a367-6453a926c439', '4204984d-a504-4918-907f-a2d393978ab4', 'd', 'De eslora inferior a 12 metros.', true, '2025-09-13 13:53:11.007092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7a50fd9-f4a3-498d-b79a-1016ab952176', '190bed76-ae6f-478a-941e-2816d7268d1a', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.007355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf1ace16-5bf8-4ab0-9f59-b6f80ef618d7', '190bed76-ae6f-478a-941e-2816d7268d1a', 'b', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:11.007484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96a16dad-4c61-4154-b952-cb1de183ea95', '190bed76-ae6f-478a-941e-2816d7268d1a', 'c', 'Una luz de alcance y luces de costado.', false, '2025-09-13 13:53:11.007612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ccd8d64-398e-4446-985a-af1db81b7086', '190bed76-ae6f-478a-941e-2816d7268d1a', 'd', 'Una luz de alcance, luces de costado y una luz centelleante.', false, '2025-09-13 13:53:11.007738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('526cca93-7c8c-47ad-9eda-86bd51c06fa3', 'd17847ba-14ef-4e35-8472-82a9c4ca4af1', 'a', 'Como regla general, toda maniobra que se efectúe para evitar un abordaje será llevada a cabo en forma clara, con la debida antelación y respetando las buenas prácticas marineras.', false, '2025-09-13 13:53:11.008017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9371ab6-b1a1-4c58-bb03-128bec284b6c', 'd17847ba-14ef-4e35-8472-82a9c4ca4af1', 'b', 'Si es necesario con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad.', false, '2025-09-13 13:53:11.008147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c55d112d-6d98-440a-9d99-858a21e452af', 'd17847ba-14ef-4e35-8472-82a9c4ca4af1', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasando al otro.', false, '2025-09-13 13:53:11.008278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f319fe3b-c71c-4f3f-a9c2-8e15e339299a', 'd17847ba-14ef-4e35-8472-82a9c4ca4af1', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños. DE TRANSPORTES, MOVILIDAD                                                                            DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                      Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 04 Nomenclatura náutica.', true, '2025-09-13 13:53:11.008406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e3bd1af-933d-4bb5-8133-1647c679bb8c', 'fca25f03-4326-4e83-b4e0-04b8a65caf21', 'a', 'Calado.', true, '2025-09-13 13:53:11.0088+00');
