INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26128035-11fc-4ebf-a686-d34f92ffa6dc', 'fca25f03-4326-4e83-b4e0-04b8a65caf21', 'c', 'Puntal.', false, '2025-09-13 13:53:11.009053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('300e61c0-7537-477f-b975-1988e0de8252', 'fca25f03-4326-4e83-b4e0-04b8a65caf21', 'd', 'Asiento.', false, '2025-09-13 13:53:11.009178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11f5496b-777f-48f6-9cfe-2b26f6c656c7', 'aeebf807-620a-4374-8e55-aa85db6d20eb', 'a', 'Quilla.', false, '2025-09-13 13:53:11.009441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e720283c-e8ea-404c-8a83-4a56baeb344a', 'aeebf807-620a-4374-8e55-aa85db6d20eb', 'b', 'Sentina.', false, '2025-09-13 13:53:11.009567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('922a09aa-e22e-4b37-b5ab-9e746f512f3c', 'aeebf807-620a-4374-8e55-aa85db6d20eb', 'c', 'Codaste.', false, '2025-09-13 13:53:11.009693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c42fde55-ce2f-41ca-b97d-b7de2a022bf0', 'aeebf807-620a-4374-8e55-aa85db6d20eb', 'd', 'Plan.', true, '2025-09-13 13:53:11.009825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c82871e-f23e-4393-a3cf-5c47e829f8ef', 'a45ef159-4483-435c-881f-3b87af3ce73a', 'a', 'Fondear.', false, '2025-09-13 13:53:11.010119+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('190a705a-79ac-4f6b-9b5c-8404b65a857b', 'a45ef159-4483-435c-881f-3b87af3ce73a', 'b', 'Virar.', true, '2025-09-13 13:53:11.010256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27eacd09-428b-4753-b822-3f26eee44b22', 'a45ef159-4483-435c-881f-3b87af3ce73a', 'c', 'Zarpar.', false, '2025-09-13 13:53:11.01039+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b92dc651-811e-422e-9d25-98d97e36565e', 'a45ef159-4483-435c-881f-3b87af3ce73a', 'd', 'Filar.', false, '2025-09-13 13:53:11.010648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fbbced0-6b52-4485-af23-66e090a9cff5', '02f0c90d-56d5-4024-bce4-796d9682f2fe', 'a', 'Es la inclinación del buque hacia un costado, por la acción del viento u otra fuerza.', true, '2025-09-13 13:53:11.010927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b699647f-b7dc-4a11-877a-d714e091e964', '02f0c90d-56d5-4024-bce4-796d9682f2fe', 'b', 'Es colocar una embarcación al lado de otra o de un muelle, de forma tal que quede en contacto por su costado.', false, '2025-09-13 13:53:11.011055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34634037-e2b2-4390-89c1-8904e5637d1e', '02f0c90d-56d5-4024-bce4-796d9682f2fe', 'c', 'Es la caída del buque hacia sotavento por efecto del viento.', false, '2025-09-13 13:53:11.011186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dacd5002-752e-4e8f-bff4-828338dd59f6', '02f0c90d-56d5-4024-bce4-796d9682f2fe', 'd', 'Es la distancia que recorre un barco por efecto de la corriente, es decir, por el desplazamiento de la masa de agua en la que se encuentra. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.011325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47469d52-7109-4359-98e9-5ad7e820c141', '5d3d7286-c2d5-4d61-b363-00966937e37d', 'a', 'Un muerto es un cuerpo flotante sujeto al fondo del mar mediante un lastre, que se coloca para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:11.01159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76c5af5f-efdf-4ba3-802b-49252468abe2', '5d3d7286-c2d5-4d61-b363-00966937e37d', 'b', 'El noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', false, '2025-09-13 13:53:11.011718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d59f83f9-91b0-47bf-b16c-d48570260655', '5d3d7286-c2d5-4d61-b363-00966937e37d', 'c', 'El nudo llano se utiliza para afirmar una amarra a una argolla, mediante una gaza no corrediza.', false, '2025-09-13 13:53:11.011868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c0d0dcb-a09c-49c2-9463-c7ac0019eb18', '5d3d7286-c2d5-4d61-b363-00966937e37d', 'd', 'La gaza es el lazo que se forma en el extremo de un cabo doblándolo y uniéndolo con costura o ligada, y que sirve para enganchar o ceñir algo o suspenderlo de alguna parte.', true, '2025-09-13 13:53:11.012009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98eb0fc9-1e9f-457f-8503-f96c666065d3', 'e3e993c1-ff69-47a0-9f3b-a155f6a6df89', 'a', 'En una embarcación de 10 metros de eslora, la línea de fondeo deberá tener un tramo de cadena de 5 metros de longitud.', false, '2025-09-13 13:53:11.012293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2426ab7d-2ddd-4462-b4ac-3d63a4071711', 'e3e993c1-ff69-47a0-9f3b-a155f6a6df89', 'b', 'Para evitar el garreo de un ancla, se cobrará cadena y se cambiará a un tenedero de gravilla o', false, '2025-09-13 13:53:11.012427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee0a78a4-cfea-47c2-8c10-a81260acf7ad', 'e3e993c1-ff69-47a0-9f3b-a155f6a6df89', 'c', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a la proa de la', false, '2025-09-13 13:53:11.012557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b937e49d-4d5c-4026-9fce-4903fd562068', '70152033-0854-4df5-86bc-c20622918307', 'b', 'Llano.', false, '2025-09-13 13:53:11.031823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa16afc3-9b72-4009-b110-3ee9dd515ffa', 'e3e993c1-ff69-47a0-9f3b-a155f6a6df89', 'd', 'Se conoce como fondeo a la gira, al fondeo con un ancla por proa donde la embarcación puede girar de manera libre alrededor de esta.', true, '2025-09-13 13:53:11.012684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b0fee9f-ff3d-4add-ab61-4ccbe2ad94a6', '971c5988-aed5-4909-bca2-84afb33d88c1', 'a', 'Poniendo la popa al viento.', false, '2025-09-13 13:53:11.012984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cee67cd-ee18-4929-bea9-de9883a1a1fe', '971c5988-aed5-4909-bca2-84afb33d88c1', 'b', 'Poniendo la amura a la mar.', true, '2025-09-13 13:53:11.013113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1abc14b4-7053-4b75-af8e-abe5bfca57af', '971c5988-aed5-4909-bca2-84afb33d88c1', 'c', 'Llevando la mar por la aleta.', false, '2025-09-13 13:53:11.013241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9b60de8-8ffe-44bc-b7fc-a1c5e0ded17a', '971c5988-aed5-4909-bca2-84afb33d88c1', 'd', 'Reduciendo la arrancada por debajo de la velocidad de gobierno.', false, '2025-09-13 13:53:11.013367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ac31635-c3a1-433d-b03a-86f0bbfca82d', 'c20f4203-9d7b-4737-8479-7c974c52a194', 'a', 'Encender todas las luces de navegación reglamentarias.', false, '2025-09-13 13:53:11.013632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be8a63a8-9170-46bd-a6d1-7d5484aab352', 'c20f4203-9d7b-4737-8479-7c974c52a194', 'b', 'Reducir la velocidad parando siempre la embarcación.', true, '2025-09-13 13:53:11.013768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5dfafb6-775f-47d5-82c3-de1210630152', 'c20f4203-9d7b-4737-8479-7c974c52a194', 'c', 'Emitir las señales fónicas que sean reglamentarias.', false, '2025-09-13 13:53:11.013902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b7af461-4aa2-46a0-88f6-7e4abd7a96c4', 'c20f4203-9d7b-4737-8479-7c974c52a194', 'd', 'Tener listas las balsas salvavidas, si las llevamos, y tener colocados los chalecos salvavidas.', false, '2025-09-13 13:53:11.014033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5181771a-050e-4f9d-a5bd-74499179bbcc', '88c962fb-80ef-48cd-9789-94626c349332', 'a', 'Cuando veamos caer al náufrago, meter el timón a la banda que haya caído el náufrago hasta caer 250º y en ese momento poner el timón a la vía y parar máquinas.', false, '2025-09-13 13:53:11.014306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c13e942-e143-4c24-af9d-51547ce8b78a', '88c962fb-80ef-48cd-9789-94626c349332', 'b', 'Cuando veamos caer al náufrago, con toda la máquina avante meter el timón a la banda que haya caído el náufrago hasta caer 70º, y en ese momento cambiar a la otra banda hasta alcanzar el rumbo opuesto al inicial.', false, '2025-09-13 13:53:11.014437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c95ba3d1-ff85-44a4-ad8f-1318359a048d', '88c962fb-80ef-48cd-9789-94626c349332', 'c', 'Cuando veamos caer al náufrago, meter el timón a la banda contraria a la que haya caído el náufrago hasta caer 240°, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto al inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', true, '2025-09-13 13:53:11.014568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f8399c9-91af-436d-9538-7acec01280fa', '88c962fb-80ef-48cd-9789-94626c349332', 'd', 'Cuando no se ve caer al náufrago, activar el M.O.B. (Man Over Board) del GPS.', false, '2025-09-13 13:53:11.0147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e428e6d3-1b99-485b-b061-55423ac43ef1', '3f1a251f-0f06-4404-9f3b-6ec48fa149c6', 'a', 'Ninguna.', false, '2025-09-13 13:53:11.015032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e897f891-e5d7-4920-9243-09602a2a0d54', '3f1a251f-0f06-4404-9f3b-6ec48fa149c6', 'b', '1.', false, '2025-09-13 13:53:11.015173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e91fbc3-52b8-4907-82bd-e647a72a3d6a', '3f1a251f-0f06-4404-9f3b-6ec48fa149c6', 'c', '3.', true, '2025-09-13 13:53:11.015314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa5b3263-6283-46bd-b001-6f54c8f8c578', '3f1a251f-0f06-4404-9f3b-6ec48fa149c6', 'd', '6. 11', false, '2025-09-13 13:53:11.015575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5dba031-a3df-4e3f-905b-03c2baef4179', 'cbd7186d-07aa-4967-9887-517afc6db984', 'a', 'Espacio marino del Odiel.', true, '2025-09-13 13:53:11.015954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31622764-f9ee-4f45-9778-a54cac5b84ca', 'cbd7186d-07aa-4967-9887-517afc6db984', 'b', 'Cabo de Creus.', false, '2025-09-13 13:53:11.016086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1630c79f-7cb9-40d3-ab99-ef1d4259772c', 'cbd7186d-07aa-4967-9887-517afc6db984', 'c', 'Islas Medes.', false, '2025-09-13 13:53:11.016225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93ce576e-da8e-4689-8bd2-251d5f6bbbe4', 'cbd7186d-07aa-4967-9887-517afc6db984', 'd', 'Acantilados de Maro-Cerro Gordo.', false, '2025-09-13 13:53:11.016357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('abe18763-45d3-442f-9a66-16a62aaf88b4', 'b8c9faa0-894c-499c-a9fa-cb0c9272a3ae', 'a', 'La navegación de cualquier buque o embarcación de recreo está completamente prohibida en la franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto', false, '2025-09-13 13:53:11.01663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('705acbcc-ebbf-4270-bad8-72f5384f81dd', 'b8c9faa0-894c-499c-a9fa-cb0c9272a3ae', 'b', 'La navegación de cualquier buque o embarcación de recreo está permitida en la franja de mar contigua a la costa de una anchura de 50 metros en las playas y 200 metros de la costa, y siempre que no se exceda el límite de velocidad de tres nudos.', false, '2025-09-13 13:53:11.016769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('503dfae7-3862-4bb2-8a3a-6930f0179c53', 'b8c9faa0-894c-499c-a9fa-cb0c9272a3ae', 'c', 'Se entenderá que la zona de baño ocupa una franja de mar contigua a la costa de una anchura de 200 metros en las playas y 50 metros en el resto de la costa, no pudiendo navegar dentro de estas zonas a una velocidad superior a tres nudos.', true, '2025-09-13 13:53:11.016898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a242fa2-b58b-4f24-a0c6-7cba572c6b7f', 'b8c9faa0-894c-499c-a9fa-cb0c9272a3ae', 'd', 'Está prohibida la navegación de cualquier buque o embarcación, salvo que estén dedicados exclusivamente al recreo, que podrán hacerlo sin limitaciones si su finalidad es fondear en calas o lugares de baño.', false, '2025-09-13 13:53:11.017036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61eec2ee-b333-40a4-9d1e-ff69cc6b82a7', '675e7d80-d851-4cda-ba54-c4faed67b5ad', 'a', 'Corredera.', false, '2025-09-13 13:53:11.017307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fb5082e-83b7-48e8-8aa4-3fdd31070da6', '675e7d80-d851-4cda-ba54-c4faed67b5ad', 'b', 'Compás.', true, '2025-09-13 13:53:11.017437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58aae5c6-6185-4193-af30-7e9a07331986', '675e7d80-d851-4cda-ba54-c4faed67b5ad', 'c', 'Sonda.', false, '2025-09-13 13:53:11.017566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('746eaee3-444c-48c1-ab1a-f9bdc4d1c510', '675e7d80-d851-4cda-ba54-c4faed67b5ad', 'd', 'Radar.', false, '2025-09-13 13:53:11.017692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37a7fe09-f84a-4d40-b262-b3f89d50bc1c', 'ddc98c43-e408-4b78-8fce-95d8b763862f', 'a', 'Por lo general, están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:11.01796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ae31902-1e55-4460-9885-d5b96e0ec501', 'ddc98c43-e408-4b78-8fce-95d8b763862f', 'b', 'Se pueden usar para indicar los límites de un área de fondeo.', true, '2025-09-13 13:53:11.018091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47ed6888-d9bc-4af1-b238-b769960e8d8e', 'ddc98c43-e408-4b78-8fce-95d8b763862f', 'c', 'Se pueden usar para definir los ejes de los canales y las marcas de centro de canal.', false, '2025-09-13 13:53:11.018221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0ea9984-f881-42d2-acc7-18771bc41a20', 'ddc98c43-e408-4b78-8fce-95d8b763862f', 'd', 'Por lo general, están destinadas para indicar el canal principal en el punto de bifurcación de este.', false, '2025-09-13 13:53:11.018347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('199bce4a-abbc-4ca7-aed2-bebff940556a', 'e5e16bfa-61cc-4769-bbc5-e9a6775c4c50', 'a', 'Una esfera negra.', false, '2025-09-13 13:53:11.018611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('878415fa-c8dd-4e57-ae9d-42a1835b3b08', 'e5e16bfa-61cc-4769-bbc5-e9a6775c4c50', 'b', 'Una esfera amarilla.', false, '2025-09-13 13:53:11.018738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6dc178bd-1d74-4700-a067-2859589e56b1', 'e5e16bfa-61cc-4769-bbc5-e9a6775c4c50', 'c', 'Dos esferas negras.', true, '2025-09-13 13:53:11.018872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53e46b35-ed25-4ac2-9ddb-32a65bf95d9e', 'e5e16bfa-61cc-4769-bbc5-e9a6775c4c50', 'd', 'Dos esferas amarillas.', false, '2025-09-13 13:53:11.018999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e4191a7-40cd-4d9c-a717-75b279e3d4ab', '2b4ec01e-3e07-4f87-90f2-471de4d32926', 'a', 'El canal principal queda a estribor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', false, '2025-09-13 13:53:11.019263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45b0ef78-dbe2-4bc4-8f55-7a65330d89e1', '2b4ec01e-3e07-4f87-90f2-471de4d32926', 'b', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en sentido opuesto al convencional de balizamiento.', false, '2025-09-13 13:53:11.019392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82e135d8-a62b-4913-855c-6861b261b71b', '2b4ec01e-3e07-4f87-90f2-471de4d32926', 'c', 'El canal principal queda a babor, si estamos en una bifurcación y navegando en el sentido convencional del balizamiento.', true, '2025-09-13 13:53:11.01953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5370a45-0cb6-47f1-9d51-aeade3ed8757', '2b4ec01e-3e07-4f87-90f2-471de4d32926', 'd', 'El canal principal queda a babor, si estamos en una bifurcación y navegando hacia alta mar.', false, '2025-09-13 13:53:11.019657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5ee1859-f195-4bcb-9a78-3e575884ac57', '2f945bab-c6e8-4623-bda2-2e62b1363ec1', 'a', 'Un destello largo cada 10 segundos.', true, '2025-09-13 13:53:11.019969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c42c76b-138f-4355-8e79-cc7cecff6cda', '2f945bab-c6e8-4623-bda2-2e62b1363ec1', 'b', 'Un destello largo cada 5 segundos.', false, '2025-09-13 13:53:11.020111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d877824-ded2-4ade-a4f7-2bda88323e74', '2f945bab-c6e8-4623-bda2-2e62b1363ec1', 'c', 'Grupos de dos destellos GpD (2), cada 10 segundos.', false, '2025-09-13 13:53:11.020246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d2134e6-ef26-4dfa-97e8-63755151c71c', '2f945bab-c6e8-4623-bda2-2e62b1363ec1', 'd', 'Grupos de dos destellos GpD (2), cada 5 segundos. Reglamento (RIPA).', false, '2025-09-13 13:53:11.020511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('246ba906-08f9-40cd-916a-bc910a81fb5d', '444b40e6-8b16-4a53-8e73-1e9c2c254011', 'a', 'De forma cónica con el que se refuerza el sonido emitido, muy útil para hablar desde lejos.', false, '2025-09-13 13:53:11.020797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49675291-2b6b-439a-b35a-b2e573c4bdbf', '444b40e6-8b16-4a53-8e73-1e9c2c254011', 'b', 'Metálico, generalmente en forma de copa invertida, que suena al ser golpeado por un badajo.', false, '2025-09-13 13:53:11.020931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a39492a6-2ae9-4cd4-9180-34edfb7fb8d9', '444b40e6-8b16-4a53-8e73-1e9c2c254011', 'c', 'De percusión formado por un disco que vibra al ser golpeado.', false, '2025-09-13 13:53:11.021084+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('276e3ad7-8f36-4e20-9762-b003de7b0534', '444b40e6-8b16-4a53-8e73-1e9c2c254011', 'd', 'Capaz de producir las pitadas reglamentarias y que cumple con las especificaciones del anexo III del Reglamento.', true, '2025-09-13 13:53:11.021216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5ed47b2-3f10-4c21-98b3-ce12207a5f92', 'bab81ce1-a555-44ef-bbbb-f76abf6f3ea5', 'a', 'La responsabilidad estará limitada en todo caso al propietario del buque.', false, '2025-09-13 13:53:11.021491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b391f13-8854-48a1-8b90-3eb3993c6fce', 'bab81ce1-a555-44ef-bbbb-f76abf6f3ea5', 'b', 'Únicamente el Capitán será responsable de las consecuencias de cualquier negligencia en el cumplimiento de este Reglamento.', false, '2025-09-13 13:53:11.021624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5a16494-c999-4005-af0c-aa89d08c7237', 'bab81ce1-a555-44ef-bbbb-f76abf6f3ea5', 'c', 'Ninguna disposición del Reglamento eximirá a un buque, o a su propietario, al Capitán o a la dotación del mismo de las consecuencias de cualquier negligencia en el cumplimiento de éste.', true, '2025-09-13 13:53:11.021758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11a63190-b883-4b8c-ba30-1b432dbeb3d5', 'c345cdd9-3d93-4644-b81e-54f9b64e2b4c', 'a', 'Para no quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.022182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be97042b-02bb-426e-99bb-ddb36d35062c', 'c345cdd9-3d93-4644-b81e-54f9b64e2b4c', 'b', 'De forma decidida.', true, '2025-09-13 13:53:11.02232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44c58d9f-3a22-4c72-b891-7e66469e16d7', 'c345cdd9-3d93-4644-b81e-54f9b64e2b4c', 'c', 'Manteniendo siempre el rumbo inicial y variando sólo la velocidad.', false, '2025-09-13 13:53:11.022451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e166108-a0bb-4c8a-91a3-94b8ee63e007', 'c345cdd9-3d93-4644-b81e-54f9b64e2b4c', 'd', 'Con maniobras suaves y contrarias para indicar al otro buque que va a maniobrar y que aquél debe mantener su derrota.', false, '2025-09-13 13:53:11.022583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bc4d8c8-c5f5-4502-b1e3-b6eb05ee1201', '3d92009c-5be1-41b4-9901-63febd7af96c', 'a', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:11.02287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2e021a3-ceb1-43d6-87cd-1ec5db5d22dc', '3d92009c-5be1-41b4-9901-63febd7af96c', 'b', 'Una pitada larga a intervalos que no excedan de dos minutos.', true, '2025-09-13 13:53:11.023005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b064a6b-fcf3-427c-97c4-d31e241f7931', '3d92009c-5be1-41b4-9901-63febd7af96c', 'c', 'Una pitada corta a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:11.023138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4157bf9a-0671-449a-9889-1f77894fe81d', '3d92009c-5be1-41b4-9901-63febd7af96c', 'd', 'Una pitada larga a intervalos que no excedan de tres minutos.', false, '2025-09-13 13:53:11.023269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42762d5b-500c-4e9f-a161-a3305ace8ad4', '7bf2eeeb-736c-4c61-9bcc-7719aefced7c', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y ninguna de las luces de costado.', true, '2025-09-13 13:53:11.023541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88fc43b8-acb8-4096-8772-ad7eb584ac6d', '7bf2eeeb-736c-4c61-9bcc-7719aefced7c', 'b', 'Se mantendrá lo más cerca posible de la derrota del buque alcanzado.', false, '2025-09-13 13:53:11.023672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('febf1b03-afc5-428b-8b4a-cdeb6f4f3565', '7bf2eeeb-736c-4c61-9bcc-7719aefced7c', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:11.023814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a36b6778-f99a-4f28-b2d5-9ebd2f7a85c9', '7bf2eeeb-736c-4c61-9bcc-7719aefced7c', 'd', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance de dicho buque y una luz de costado.', false, '2025-09-13 13:53:11.023946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d0065f9-4fe6-47c4-b461-c928be4891de', '6d44f6f7-2091-401e-8676-a56718359289', 'a', 'Como regla general, toda maniobra que se efectúe para evitar un abordaje será llevada a cabo en forma clara, con la debida antelación y respetando las buenas prácticas marineras.', false, '2025-09-13 13:53:11.024367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5251166d-5f08-45a4-82a2-1c9c6b4d9f46', '6d44f6f7-2091-401e-8676-a56718359289', 'b', 'Si es necesario con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad.', false, '2025-09-13 13:53:11.024506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbf412d3-120b-4c1d-9807-8d4cf11fd30f', '6d44f6f7-2091-401e-8676-a56718359289', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el otro buque esté pasando al otro.', false, '2025-09-13 13:53:11.024643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('523e0c28-d5e0-4cae-945b-6550d803492a', '6d44f6f7-2091-401e-8676-a56718359289', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán sucesivos y pequeños.', true, '2025-09-13 13:53:11.024787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20ceb47d-6e34-4e52-9527-f05fb1da4841', '1ee75817-c567-44af-9b60-d2e81d9a9cbd', 'a', 'Es siempre la misma para un buque de vela.', false, '2025-09-13 13:53:11.02507+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('348cff35-bded-426c-9848-4ab4567a318c', '1ee75817-c567-44af-9b60-d2e81d9a9cbd', 'b', 'Sólo se utilizará en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.025205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ee80d63-66e4-41c2-95aa-4b17db333d96', '1ee75817-c567-44af-9b60-d2e81d9a9cbd', 'c', 'Para determinarla no se tendrá en cuenta la densidad del tráfico.', false, '2025-09-13 13:53:11.025341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66f103d6-c58f-4afa-83f4-958d3790ac4c', '1ee75817-c567-44af-9b60-d2e81d9a9cbd', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje.', true, '2025-09-13 13:53:11.025476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('052de5bf-2aa9-4f2a-b9d6-0383ab9468ce', '2b20e40a-848e-48ee-95b2-a41da88576c3', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.025758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a81d185-e008-44b6-8155-e0a83782e803', '2b20e40a-848e-48ee-95b2-a41da88576c3', 'b', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:11.025906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d15a514-dba7-4e75-b305-6879e9e10b10', '2b20e40a-848e-48ee-95b2-a41da88576c3', 'c', 'Una luz de alcance y luces de costado.', false, '2025-09-13 13:53:11.026043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ffb3546-93be-46cc-9308-6b5e7d6302c6', '2b20e40a-848e-48ee-95b2-a41da88576c3', 'd', 'Una luz de alcance, luces de costado y una luz centelleante.', false, '2025-09-13 13:53:11.026181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0d4d7b5-8fac-4f87-9994-8f435a25464b', 'c1869e48-6739-44dd-a046-971d9c03a11b', 'a', 'Cuya velocidad máxima no sea superior a quince nudos.', false, '2025-09-13 13:53:11.026466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc9da5df-4f39-48cb-bf80-f09c3f9159e6', 'c1869e48-6739-44dd-a046-971d9c03a11b', 'b', 'Cuya velocidad máxima no sea superior a doce nudos.', false, '2025-09-13 13:53:11.026601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8de859f-0a03-454b-a205-0139964938da', 'c1869e48-6739-44dd-a046-971d9c03a11b', 'c', 'De eslora inferior a 20 metros.', false, '2025-09-13 13:53:11.026733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba295c9a-27b3-4e93-9eda-c4779481b8cf', 'c1869e48-6739-44dd-a046-971d9c03a11b', 'd', 'De eslora inferior a 12 metros.', true, '2025-09-13 13:53:11.026865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3873f1ce-5867-4754-b4e0-5f4b82a45c20', 'bad93bef-4099-4e7a-acf3-1b1891165505', 'a', 'El buque que deba mantenerse apartado de la derrota del otro mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:11.027141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d51ec14d-f22c-4192-ad0a-25ae37feb175', 'bad93bef-4099-4e7a-acf3-1b1891165505', 'b', 'No exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del', true, '2025-09-13 13:53:11.027274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('975d7a50-ee06-4e08-a453-ada3135b30dc', 'bad93bef-4099-4e7a-acf3-1b1891165505', 'c', 'Solamente el buque que ceda el paso podrá ejecutar la maniobra que mejor pueda ayudar a evitar', false, '2025-09-13 13:53:11.027407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c6ab038-e76c-4181-80c2-9b63652cacc0', 'bad93bef-4099-4e7a-acf3-1b1891165505', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último se detendrá obligatoriamente.', false, '2025-09-13 13:53:11.02754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00f3eb14-1f1e-48ec-a15d-e4d4b7cf2e54', '21b97bd3-4e5c-4870-ae9d-16554077ce99', 'a', 'Cuaderna.', false, '2025-09-13 13:53:11.027971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbe51aba-ba34-4af8-9aa7-88e2bf60e94d', '21b97bd3-4e5c-4870-ae9d-16554077ce99', 'b', 'Bao.', true, '2025-09-13 13:53:11.02812+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01c49822-fa49-4a1f-9f4a-80e22fbdd62b', '21b97bd3-4e5c-4870-ae9d-16554077ce99', 'c', 'Mamparo.', false, '2025-09-13 13:53:11.028256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e0fc0d2-cdb5-4b9f-a98a-2d938676e93f', '21b97bd3-4e5c-4870-ae9d-16554077ce99', 'd', 'Amura.', false, '2025-09-13 13:53:11.028391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aaebeb00-8d55-4045-a252-c71836cb9674', 'ab3885bc-97b5-4558-bc3a-7d7ff4ea9af8', 'a', 'La hélice es el elemento propulsor del buque, formado por unas palas planas acopladas a un eje, que al girar hacen moverse al buque.', true, '2025-09-13 13:53:11.028707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c53a33cd-1845-4cbd-96f4-45a876922345', 'ab3885bc-97b5-4558-bc3a-7d7ff4ea9af8', 'b', 'La hélice dextrógira o de paso a la derecha, es la que en marcha avante y vista desde popa gira en sentido de las agujas del reloj.', false, '2025-09-13 13:53:11.028886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9bf991f-abb3-460c-aa84-c6e1a132dede', 'ab3885bc-97b5-4558-bc3a-7d7ff4ea9af8', 'c', 'La hélice levógira o de paso a la izquierda, es la que en marcha avante y vista desde popa gira en sentido contrario a las agujas del reloj.', false, '2025-09-13 13:53:11.029036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49b9124b-c544-48b4-a59b-9efb55688df0', 'ab3885bc-97b5-4558-bc3a-7d7ff4ea9af8', 'd', 'Un sistema de propulsión con hélice de palas abatibles o plegables se emplea para reducir al mínimo el rozamiento.', false, '2025-09-13 13:53:11.029284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c8926b4-5ebd-4635-a733-3a8d4230b205', 'f2b2bb82-a8db-49c1-834e-a2be626d6614', 'a', 'La diferencia entre el puntal de proa y popa, descontando el francobordo.', false, '2025-09-13 13:53:11.029584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76764fbd-d5c2-4269-827c-f7a11a8c7320', 'f2b2bb82-a8db-49c1-834e-a2be626d6614', 'b', 'La media aritmética de los calados de proa y popa.', true, '2025-09-13 13:53:11.029728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a61aae85-422c-4487-b36b-3c4d23659afe', 'f2b2bb82-a8db-49c1-834e-a2be626d6614', 'c', 'La media aritmética de los calados de popa y proa, descontando el francobordo.', false, '2025-09-13 13:53:11.029867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c72f8d80-9b03-483a-82ef-f4886e1e7deb', 'f2b2bb82-a8db-49c1-834e-a2be626d6614', 'd', 'La diferencia entre el calado de proa y popa.', false, '2025-09-13 13:53:11.030005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('925ed50f-9506-4c24-8a06-4fc8fa5dd0f1', '22f245df-1e6e-4872-915b-094aef94f062', 'a', 'Pieza horizontal que forma parte de la barandilla del barco.', false, '2025-09-13 13:53:11.03029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fa3c8bc-991d-45ec-b401-5631b1f28173', '22f245df-1e6e-4872-915b-094aef94f062', 'b', 'Piezas de madera, cabo, cable, etc. que sujetas a mamparos sirven para asirse o para protección.', false, '2025-09-13 13:53:11.030426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9ae5134-f918-485a-8c31-79be2c40d51d', 'bba50447-fb67-4436-9d97-68f9c2dfefe4', 'a', 'La calidad del fondo con respecto a la adherencia del ancla.', true, '2025-09-13 13:53:11.03099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d51dbc2d-91b4-4300-a3db-ce3f270b4766', 'bba50447-fb67-4436-9d97-68f9c2dfefe4', 'b', 'El lugar donde se fijan las amarras de las embarcaciones cuando atracan.', false, '2025-09-13 13:53:11.031127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e81fe2dd-4145-425b-a903-65fa6b13dcfb', 'bba50447-fb67-4436-9d97-68f9c2dfefe4', 'c', 'El cuerpo flotante sujeto al fondo que se coloca como señal para indicar un sitio peligroso o un objeto sumergido.', false, '2025-09-13 13:53:11.031261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb2bd57c-10cb-47a1-8408-339d4358c605', 'bba50447-fb67-4436-9d97-68f9c2dfefe4', 'd', 'El palo largo con remate en forma de gancho que sirve para atracar y desatracar.', false, '2025-09-13 13:53:11.031395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95821da4-4692-4c02-8ce5-7a76d25ece4a', '70152033-0854-4df5-86bc-c20622918307', 'a', 'Ballestrinque.', false, '2025-09-13 13:53:11.031679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8ac83e2-e285-4f77-8446-2915aa45d67a', '22f245df-1e6e-4872-915b-094aef94f062', 'd', 'Puede tener orificios por los que pasan los guardamancebos, y sirven también para afirmar los pasamanos.', true, '2025-09-13 13:53:11.030696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ac358c4-b075-4687-a5e6-fda0198876a2', '70152033-0854-4df5-86bc-c20622918307', 'c', 'Vuelta de rezón.', false, '2025-09-13 13:53:11.031963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aa39746-d1e4-4a2e-8692-d5b42180a017', '70152033-0854-4df5-86bc-c20622918307', 'd', 'As de guía.', true, '2025-09-13 13:53:11.032108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ac1253a-88da-4a6c-ac3a-b1bbeb9af56f', '6630130e-de4e-40a0-815b-f3669d7a556a', 'a', 'Acercarse a la costa para navegar lo más próximo a ella.', false, '2025-09-13 13:53:11.032396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8bd4a9f-4cba-4711-afe2-ed1ee0c8fbc6', '6630130e-de4e-40a0-815b-f3669d7a556a', 'b', 'Evitar el tráfico marítimo.', true, '2025-09-13 13:53:11.032535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9402ab90-a793-4950-8d7e-e8f4482488a8', '6630130e-de4e-40a0-815b-f3669d7a556a', 'c', 'Evitar las radiobalizas.', false, '2025-09-13 13:53:11.032673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96a823ec-f85d-45b1-9502-e88d8649a157', '6630130e-de4e-40a0-815b-f3669d7a556a', 'd', 'Realizar una secuencia de dos destellos de luz cortos y uno largo.', false, '2025-09-13 13:53:11.03281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41e45cde-2201-4bfc-bf9f-011c5b54fd3c', '9453676e-452d-49a4-920b-4ac015075a79', 'b', 'Zafar la trinca, asegurar la fijación al barco de la tira de disparo, lanzar el contenedor de la balsa al agua, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado, embarcar en la balsa y soltar la tira de disparo que mantiene la balsa unida al barco.', true, '2025-09-13 13:53:11.033232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3576be9-03a2-4e6d-96b3-bcf77ec939df', '9453676e-452d-49a4-920b-4ac015075a79', 'c', 'Zafar la trinca, soltar la tira de disparo que mantiene la balsa unida al barco, lanzar el contenedor de la balsa al agua, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado y embarcar en la balsa.', false, '2025-09-13 13:53:11.033378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18ccb77f-a7b9-406f-8cf2-3ec980d0b542', '9453676e-452d-49a4-920b-4ac015075a79', 'd', 'Zafar la trinca, lanzar el contenedor al agua, asegurar la fijación al barco de la tira de disparo, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado, embarcar en la balsa y soltar la tira de disparo que mantiene la balsa unida al barco.', false, '2025-09-13 13:53:11.033512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbb7995d-f906-4f94-b6e5-a3f9be42b12e', '8f9f13c4-4889-4fc6-922c-cdae40634d22', 'a', 'El estado de las radiocomunicaciones.', false, '2025-09-13 13:53:11.033814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31c40689-1834-42f6-881c-decfb4ef36f0', '8f9f13c4-4889-4fc6-922c-cdae40634d22', 'b', 'La estiba de las anclas y cabos de la embarcación.', false, '2025-09-13 13:53:11.033953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5904d17a-ae15-429c-93aa-f964448558e4', '8f9f13c4-4889-4fc6-922c-cdae40634d22', 'c', 'Que los grifos de fondo de refrigeración están cerrados.', true, '2025-09-13 13:53:11.034096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18acd107-6758-4fef-95c5-3c935052ad3b', '8f9f13c4-4889-4fc6-922c-cdae40634d22', 'd', 'El filtro de decantación de agua.', false, '2025-09-13 13:53:11.034235+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2880ecab-9886-4f63-bc6b-c22eab0307ae', '51221c4c-2b52-4abc-97e0-722ffec4d3dc', 'a', 'En la maniobra de aproximación, el barco que va a remolcar se dirige a poca máquina a barlovento del que va a ser remolcado.', false, '2025-09-13 13:53:11.034616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb7a9296-67c7-4f1d-957a-9d20eb161cea', '51221c4c-2b52-4abc-97e0-722ffec4d3dc', 'b', 'Cuando el barco averiado se encuentre aproado al viento, el remolcador maniobrará para mantenerse siempre con su proa al viento, sin atravesarse, y dará la maniobra del remolque desde su popa a la proa del barco averiado.', true, '2025-09-13 13:53:11.034752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('673085bc-090a-4fc9-8b02-60590fb1477f', '51221c4c-2b52-4abc-97e0-722ffec4d3dc', 'c', 'Convendrá que la longitud del cabo del remolque sea tal que el remolcador y el barco remolcado se encuentren simultáneamente en un seno o en una cresta de ola.', false, '2025-09-13 13:53:11.03491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ce9d883-4875-499d-a68f-7dacf6d8adab', '51221c4c-2b52-4abc-97e0-722ffec4d3dc', 'd', 'En el caso de remolque abarloado se tendrá en cuenta la maniobra del conjunto como si se tratara de un sólo barco.', false, '2025-09-13 13:53:11.035055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f200478d-ef8c-40fa-9bd5-956a9eed4da8', '3b6951e0-63d5-49c0-b5ea-8ff33d0be354', 'a', 'Sin excepción alguna.', false, '2025-09-13 13:53:11.035339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f232208-bb41-490c-979a-d3d6ad2f242a', '3b6951e0-63d5-49c0-b5ea-8ff33d0be354', 'c', 'Salvo que se haga a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', false, '2025-09-13 13:53:11.035606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ef9b4a2-1ee4-404f-b6ea-d0c633e78f49', '3b6951e0-63d5-49c0-b5ea-8ff33d0be354', 'd', 'Salvo que dicho producto se haya tratado para su esterilización.', false, '2025-09-13 13:53:11.035736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e737b3ed-1c8b-4b5b-aa90-53f0f68230a4', '240cb2e6-dd08-47f9-94dc-bd3337f98fdb', 'b', 'Áreas que, por albergar ecosistemas endogámicos de la zona mediterránea o hábitats de especies en endemismo, son importantes para la conservación de los componentes de la diversidad micológica en el Mediterráneo.', false, '2025-09-13 13:53:11.036167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb210ceb-bfe3-4a8b-aed7-4d81ac4a5fba', '240cb2e6-dd08-47f9-94dc-bd3337f98fdb', 'd', 'Áreas que, por albergar ecosistemas específicos de la zona mediterránea o hábitats de especies en peligro, son importantes para la conservación de los componentes de la diversidad biológica en el', true, '2025-09-13 13:53:11.036431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4b31618-839d-48e3-b725-673fda249455', 'b69cf06a-0e0f-4ca1-9272-5a9a84ce4a1c', 'a', 'Roja.', false, '2025-09-13 13:53:11.036699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17d0538a-f5e1-4a0c-b56a-584abb8197c0', 'b69cf06a-0e0f-4ca1-9272-5a9a84ce4a1c', 'b', 'Roja con una ancha banda horizontal verde.', true, '2025-09-13 13:53:11.036831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daf4f0ea-4acb-4a97-ad6a-b960c3391136', 'b69cf06a-0e0f-4ca1-9272-5a9a84ce4a1c', 'c', 'Verde con una ancha banda horizontal roja.', false, '2025-09-13 13:53:11.036962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47d74684-bd95-43a0-b113-1ce47714f80c', 'b69cf06a-0e0f-4ca1-9272-5a9a84ce4a1c', 'd', 'Verde.', false, '2025-09-13 13:53:11.03709+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('697a019a-f6e5-42c8-8955-2661f8058549', 'e7ec6ccc-020b-40da-9fc9-2b6e77f86553', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', false, '2025-09-13 13:53:11.037359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('278ec0a2-9323-4c39-9cd9-730f015b5296', 'e7ec6ccc-020b-40da-9fc9-2b6e77f86553', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', true, '2025-09-13 13:53:11.037488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23cb6f58-cc96-4e67-af45-39306b5e243c', 'e7ec6ccc-020b-40da-9fc9-2b6e77f86553', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.037621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a38b0b62-40cf-4647-9233-06a833e687e0', 'e7ec6ccc-020b-40da-9fc9-2b6e77f86553', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', false, '2025-09-13 13:53:11.037753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a07eb12-868f-46fb-84da-ab6e7116d9e8', '08411a2e-72cd-4d75-8b08-c6d422dff8a6', 'a', 'Señalar canales u obstrucciones a los que hace se hace referencia en las publicaciones náuticas.', false, '2025-09-13 13:53:11.038032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65855df1-3737-42e3-a84c-483b383f1a01', '08411a2e-72cd-4d75-8b08-c6d422dff8a6', 'd', 'Señalar los accesos desde alta mar donde existen áreas con elevada concentración de tráfico marítimo, porque no están indicados en la carta u otro documento náutico.', false, '2025-09-13 13:53:11.038416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5ce4341-c2df-4bcb-b34b-23abcafbb479', '559df384-77ce-4be5-811c-65a6f827d7ca', 'a', 'Blanca en grupo de dos destellos GpD (2).', true, '2025-09-13 13:53:11.038681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdbec9e2-d68a-45e2-ac82-802ef6a69f1b', '559df384-77ce-4be5-811c-65a6f827d7ca', 'b', 'Blanca con la señal de Morse “A”.', false, '2025-09-13 13:53:11.038821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72facaae-8dc9-422c-bba5-d68194a5a321', '559df384-77ce-4be5-811c-65a6f827d7ca', 'c', 'Blanca centelleante rápido continuo VQ.', false, '2025-09-13 13:53:11.039054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e73e71d5-b143-4eee-96e6-d8e653443062', '559df384-77ce-4be5-811c-65a6f827d7ca', 'd', 'Amarilla en grupos de (2+1) destello.', false, '2025-09-13 13:53:11.039183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cf1055c-a1b9-4418-800d-1fd6f1d84195', '0edb9bdc-8bed-4cc5-9b5d-339952c202b0', 'a', 'Como marcas de eje de un canal o como marcas de recalada.', true, '2025-09-13 13:53:11.039461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42528cd5-5e11-446f-a5a5-fdcf40dded34', '0edb9bdc-8bed-4cc5-9b5d-339952c202b0', 'b', 'Para indicar, en el punto de bifurcación de un canal, la ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:11.039595+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ece19b89-24d6-4bd9-94a0-1af7337516d2', '0edb9bdc-8bed-4cc5-9b5d-339952c202b0', 'c', 'Para ayudar a la navegación o proporcionar información, indicando las bandas de babor y estribor de la ruta a seguir, para la seguridad de la navegación.', false, '2025-09-13 13:53:11.039746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ba72bd3-ff65-4d08-8b35-10c27a6d0029', '240cb2e6-dd08-47f9-94dc-bd3337f98fdb', 'c', 'Áreas que, por albergar ecosistemas endogámicos de la zona mediterránea o hábitats de especies extintas, son importantes para la conservación de los componentes de la diversidad geológica en el Mediterráneo.', false, '2025-09-13 13:53:11.036297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5500d58a-5d40-489b-b486-1d638481571c', '08411a2e-72cd-4d75-8b08-c6d422dff8a6', 'b', 'Indicar zonas o configuraciones cuya naturaleza exacta está indicada en la carta u otro documento náutico.', true, '2025-09-13 13:53:11.03816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4b87890-29e9-4e86-932c-7a3621b21390', '08411a2e-72cd-4d75-8b08-c6d422dff8a6', 'c', 'Indicar el sentido convencional del balizamiento, porque este no se indica en las publicaciones náuticas.', false, '2025-09-13 13:53:11.038289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('886fe0cb-51eb-4771-bd9e-ae0471858758', '0edb9bdc-8bed-4cc5-9b5d-339952c202b0', 'd', 'Para indicar, colocadas sobre o próximas a un peligro, las zonas de aguas navegables.', false, '2025-09-13 13:53:11.039892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dffe3605-b99f-4d15-9c11-2a2cfe27655e', '3b6951e0-63d5-49c0-b5ea-8ff33d0be354', 'b', 'Salvo que sea una pérdida accidental resultante de averías sufridas por un buque o por sus equipos.', true, '2025-09-13 13:53:11.035475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6158030-5e9a-4a18-bf49-ced14778d12d', 'b37f8c28-7074-4f4c-83f0-e658fe60a669', 'a', 'Naves de vuelo rasante.', false, '2025-09-13 13:53:11.040164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1b43748-d18b-44f4-819d-3cd4534d5918', 'b37f8c28-7074-4f4c-83f0-e658fe60a669', 'b', 'Hidroaviones.', false, '2025-09-13 13:53:11.040304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1b67cd7-d079-4def-bd0e-e20679f9eccc', 'b37f8c28-7074-4f4c-83f0-e658fe60a669', 'c', 'Buques dedicados a la pesca.', false, '2025-09-13 13:53:11.040438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78ae9005-4cf8-47ef-8bd7-14a08e2bb8d4', 'b37f8c28-7074-4f4c-83f0-e658fe60a669', 'd', 'Embarcaciones en pantanos y embalses.', true, '2025-09-13 13:53:11.040568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('118856e5-73c8-4df0-af95-77f350bdb9c6', '59868bdc-7831-4f82-b8e8-9d73e943aceb', 'a', 'Como si fueran buques con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.040842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0113dc7d-e336-486a-97ce-f8516fd30698', '59868bdc-7831-4f82-b8e8-9d73e943aceb', 'b', 'Como si fueran buques de propulsión mecánica.', true, '2025-09-13 13:53:11.040973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75893ef9-dc27-47c2-b23f-1474ebab7e28', '59868bdc-7831-4f82-b8e8-9d73e943aceb', 'c', 'Como si fueran buques de vela.', false, '2025-09-13 13:53:11.041101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4277915c-99c1-455a-9f15-dd4d1a157835', '59868bdc-7831-4f82-b8e8-9d73e943aceb', 'd', 'Como si fueran buques dedicados a la pesca.', false, '2025-09-13 13:53:11.041227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('318d50b5-c435-4dc4-9c1e-129a433074a1', 'f7c4012d-e6a7-49b4-ae6b-7579a5536d24', 'a', 'Blanca que muestra luz sin interrupción.', true, '2025-09-13 13:53:11.041492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d227ea1a-f5cf-4b5c-a6e8-4b1b468e036e', 'f7c4012d-e6a7-49b4-ae6b-7579a5536d24', 'b', 'Amarilla que muestra luz sin interrupción.', false, '2025-09-13 13:53:11.041625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec3a9cdf-0a5b-42bd-b8d3-bd3692cdd050', 'f7c4012d-e6a7-49b4-ae6b-7579a5536d24', 'c', 'Blanca que muestra luz centelleante.', false, '2025-09-13 13:53:11.041758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2eb33d67-2fa3-4839-be9f-3aedaab0aeed', 'f7c4012d-e6a7-49b4-ae6b-7579a5536d24', 'd', 'Amarilla que muestra luz centelleante.', false, '2025-09-13 13:53:11.041904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('152a642e-bb8b-4520-9b59-47aecc718664', '1fdec3a7-115b-43f8-a9ee-2c383c89ac44', 'b', 'El buque que tenga al otro por su costado de estribor mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:11.042308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f3f3ec4-f832-471a-b02e-a0d2ed131d89', '1fdec3a7-115b-43f8-a9ee-2c383c89ac44', 'c', 'Aumentarán su velocidad para cruzarse lo antes posible.', false, '2025-09-13 13:53:11.042437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7348e27-baa3-46f5-abd3-b0cccd16333c', '1fdec3a7-115b-43f8-a9ee-2c383c89ac44', 'd', 'El buque que tenga al otro por su costado de babor, se mantendrá apartado de la derrota de éste', false, '2025-09-13 13:53:11.042567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54b17aee-fdcb-4b28-b326-814b272474a7', '7ebf6529-7086-44c3-84ee-1ea5f1fdd0ca', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:11.04294+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4af10773-6671-4a43-b193-e4d726ae87be', '7ebf6529-7086-44c3-84ee-1ea5f1fdd0ca', 'b', 'Los buques de eslora inferior a 20 metros, o los buques de vela, tendrán prioridad de tránsito respecto a cualquier otro buque dentro de un paso o canal angosto.', false, '2025-09-13 13:53:11.043071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a51f7626-1e0d-4aee-905c-ddaa4609fc73', '7ebf6529-7086-44c3-84ee-1ea5f1fdd0ca', 'c', 'En ningún caso los buques podrán fondear en un canal angosto.', false, '2025-09-13 13:53:11.043201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7089f29d-5321-4cf2-90d2-e61999d8a956', '7ebf6529-7086-44c3-84ee-1ea5f1fdd0ca', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', true, '2025-09-13 13:53:11.04333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89283b19-b5a5-45e0-83d7-b1d61d09454e', 'de5b1913-30d0-4ab5-ae18-d9fa19001ffd', 'a', 'De tal índole que no pueda confundirse con ninguna ayuda a la navegación.', true, '2025-09-13 13:53:11.043602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e38d7d99-cb52-4f3e-99d9-425ece7eee23', 'de5b1913-30d0-4ab5-ae18-d9fa19001ffd', 'b', 'Intermitente.', false, '2025-09-13 13:53:11.043735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd5b7ae9-dd90-447b-8af2-42a2a817906c', 'de5b1913-30d0-4ab5-ae18-d9fa19001ffd', 'c', 'Giratoria de gran intensidad.', false, '2025-09-13 13:53:11.043881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a43c3dd-0c6c-4014-b44d-66587267d45d', 'de5b1913-30d0-4ab5-ae18-d9fa19001ffd', 'd', 'Estroboscópica.', false, '2025-09-13 13:53:11.044015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a13cc09-839e-48fc-9681-2bdcd27bbab3', 'b8fa780e-eee0-4c98-aa08-16c91a93dc7a', 'b', 'Si la demora o la marcación de un buque que se aproxima no varía de forma apreciable, se considerará que no existe riesgo de abordaje.', false, '2025-09-13 13:53:11.044425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ca3f635-9210-45ee-bdb8-0b0f8017ebad', 'b8fa780e-eee0-4c98-aa08-16c91a93dc7a', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-13 13:53:11.044688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ecc7c20-a3f1-4def-b117-79a20985224b', 'edfc4fcc-0061-48d8-869d-c54c0dd394ad', 'a', 'Tres luces amarillas todo horizonte en línea horizontal o un cilindro.', false, '2025-09-13 13:53:11.044962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bba68a81-076c-4e05-b824-bcc4884b4336', 'edfc4fcc-0061-48d8-869d-c54c0dd394ad', 'b', 'Tres luces amarillas todo horizonte en línea vertical o un cilindro.', false, '2025-09-13 13:53:11.045096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ea5a44b-d796-41b2-b9ba-57a230448491', 'edfc4fcc-0061-48d8-869d-c54c0dd394ad', 'c', 'Tres luces rojas todo horizonte en línea horizontal o un cilindro.', false, '2025-09-13 13:53:11.04523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f80bf366-8fcb-4eb7-bb52-fc36f8704712', 'edfc4fcc-0061-48d8-869d-c54c0dd394ad', 'd', 'Tres luces rojas todo horizonte en línea vertical o un cilindro.', true, '2025-09-13 13:53:11.045361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce8fd734-1818-4777-abfd-a246ec969a99', 'f2bf3620-337c-499c-a64a-496b66c44d89', 'b', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, cambiará su rumbo a babor para maniobrar a un buque que se encuentre por esa misma banda, si las circunstancias del caso lo permiten.', false, '2025-09-13 13:53:11.045769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1098524a-352f-415e-bb6d-636f4c47a45f', 'f2bf3620-337c-499c-a64a-496b66c44d89', 'c', 'Cuando exista riesgo de abordaje, sólo podrá ejecutar la maniobra que mejor pueda ayudar a evitarlo el buque que ceda el paso.', false, '2025-09-13 13:53:11.045899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb010933-65c7-4d63-974b-4927c2960ae8', 'f2bf3620-337c-499c-a64a-496b66c44d89', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:11.046028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc9e58e1-fb51-4cbd-93b6-a04ec5d4dca7', '7a5d8442-05e2-43ce-b793-101facc0ef50', 'a', 'NC.', true, '2025-09-13 13:53:11.046296+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94cd51d7-ebe8-438a-8071-c8dd4d30dc65', '7a5d8442-05e2-43ce-b793-101facc0ef50', 'b', 'NA.', false, '2025-09-13 13:53:11.046432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3c9f355-b16e-4a57-b2cc-b6b39dfce2f9', '7a5d8442-05e2-43ce-b793-101facc0ef50', 'c', 'SM.', false, '2025-09-13 13:53:11.046559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cda1194-4062-45f1-ada5-73ba18aab2c8', 'a3c29b8a-a8cb-420a-8ad3-f8e4576ef7de', 'a', 'Poder largar cómodamente desde el barco facilitando el desamarre.', true, '2025-09-13 13:53:11.046965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99d35ad6-a956-4f8b-8437-f92e1b9d601f', 'a3c29b8a-a8cb-420a-8ad3-f8e4576ef7de', 'b', 'Que la embarcación quede más segura mientras no salimos.', false, '2025-09-13 13:53:11.047097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9e9f453-53c9-4c7d-b62c-6896769946bf', 'a3c29b8a-a8cb-420a-8ad3-f8e4576ef7de', 'c', 'Que sea necesario el uso de una codera en popa para poder salir.', false, '2025-09-13 13:53:11.047229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('220d5ee5-c97d-45c6-94f8-0293a37275fa', 'a3c29b8a-a8cb-420a-8ad3-f8e4576ef7de', 'd', 'Que la embarcación quede firme al muelle dificultando el desamarre.', false, '2025-09-13 13:53:11.047357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3220f4d-96da-41fe-93fc-40700de7c776', 'd95ccf08-abd1-4cc1-b92c-8e9d6329da3e', 'a', 'La embarcación tenderá a evolucionar con caída de popa a estribor y proa a babor.', false, '2025-09-13 13:53:11.047734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c07454d-07de-4d5f-b583-5a5b4fdbd1dd', 'd95ccf08-abd1-4cc1-b92c-8e9d6329da3e', 'b', 'La embarcación tenderá a evolucionar con caída de popa a babor y proa a estribor.', true, '2025-09-13 13:53:11.04787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eaea83c7-e44d-4c60-973f-2a74b0404021', 'd95ccf08-abd1-4cc1-b92c-8e9d6329da3e', 'c', 'La caída de popa y proa será indiferente, no viéndose afectada por el efecto combinado de la hélice y el timón.', false, '2025-09-13 13:53:11.047998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfb93919-56fa-4821-9255-2aa28f3bd5e6', '4b6e87c8-7006-4335-ac0c-85004381e9ee', 'a', 'Para prevenir una vía de agua, se deben cerrar las válvulas que no se utilicen, asegurar la estanqueidad de portillos y escotillas y fijar el ancla para que no golpee el casco.', false, '2025-09-13 13:53:11.048412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73f4ee6f-f187-4b1f-ba62-2947e431b522', '4b6e87c8-7006-4335-ac0c-85004381e9ee', 'b', 'Si se detecta agua en la sentina, deben ponerse en marcha de inmediato todas las bombas de achique y mantener encendido el motor.', false, '2025-09-13 13:53:11.048545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20a0ddb3-4273-48e8-bca9-ac4554173cca', '4b6e87c8-7006-4335-ac0c-85004381e9ee', 'c', 'Para reforzar el trabajo de las bombas de achique, se puede soltar la toma de agua de mar de refrigeración del motor, cerrar el paso y hacer que succione el agua embarcada.', false, '2025-09-13 13:53:11.048672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('252ca59f-52b4-4c88-b5b1-b63ea37f1f02', '4b6e87c8-7006-4335-ac0c-85004381e9ee', 'd', 'Los puntos de mayor riesgo para producirse una vía de agua son las lumbreras, los imbornales de cubierta y la hélice.', true, '2025-09-13 13:53:11.0488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69822581-a31a-4631-add1-62d8db3b4deb', '4f2273a5-470a-421f-99b1-f2a66bd5799d', 'b', 'Ra= 006,5º; HRB= 16:26.', false, '2025-09-13 13:53:11.058717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b3a7105-07be-4d04-b11a-0534021d9c08', 'b8fa780e-eee0-4c98-aa08-16c91a93dc7a', 'c', 'En caso de abrigarse alguna duda respecto a si existe riesgo de abordaje, se considerará que no existe.', false, '2025-09-13 13:53:11.044557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d69bcff2-10bb-4e8d-990a-c5f9d5d3e764', 'f2bf3620-337c-499c-a64a-496b66c44d89', 'a', 'Se exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', false, '2025-09-13 13:53:11.045638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b76a56de-d107-4573-a9dd-7e3559d0c248', '7a5d8442-05e2-43ce-b793-101facc0ef50', 'd', 'CS.', false, '2025-09-13 13:53:11.046686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52e62f30-74e8-4953-aa71-6940650e56df', 'b8fa780e-eee0-4c98-aa08-16c91a93dc7a', 'a', 'Se evitarán las suposiciones basadas en información insuficiente, especialmente la obtenida por radar.', true, '2025-09-13 13:53:11.044293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d40dcd79-6b6c-45ef-9747-5985e161d1c7', 'd95ccf08-abd1-4cc1-b92c-8e9d6329da3e', 'd', 'No se producirá movimiento transversal de la embarcación.', false, '2025-09-13 13:53:11.048129+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e261dd7-28ab-4d23-b38b-47e6f4a9cb45', '3503e687-1931-49f8-9174-c17ded1cc106', 'a', 'La asistencia médica se realiza en español y está disponible las 24 horas, todos los días del año.', false, '2025-09-13 13:53:11.049066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78973b7b-801f-4bd8-b04a-48e8d0385c5a', '3503e687-1931-49f8-9174-c17ded1cc106', 'b', 'Los buques que dispongan de sistema de comunicación vía satélite o de telefonía móvil, pueden contactar directamente en el número 91 310 34 75.', false, '2025-09-13 13:53:11.049207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a35884c-20c1-4098-be34-f102d97ef669', '3503e687-1931-49f8-9174-c17ded1cc106', 'c', 'Se recomienda realizar las consultas no urgentes entre las 9:00 y las 15:00 horas (hora de Madrid), reservando el resto para consultas urgentes.', false, '2025-09-13 13:53:11.049334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33235055-296f-4aed-bc4f-154cabe3f461', '3503e687-1931-49f8-9174-c17ded1cc106', 'd', 'Depende del Instituto Social de Medicina Preventiva y Salud Pública de la Marina.', true, '2025-09-13 13:53:11.049464+00');
