INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('745fc97f-e1ef-46c3-9633-7d807e3d1023', 'a0ee0a38-b0b7-4627-b2e6-d6f5e3f1d61b', 'a', 'La hélice es el elemento propulsor del buque, formado por unas palas planas acopladas a un eje, que al girar hacen moverse al buque.', true, '2025-09-13 13:53:11.060062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b15fc65-ceb6-4383-9377-cc3285032a12', 'a0ee0a38-b0b7-4627-b2e6-d6f5e3f1d61b', 'b', 'La hélice dextrógira o de paso a la derecha, es la que en marcha avante y vista desde popa gira en sentido de las agujas del reloj.', false, '2025-09-13 13:53:11.06019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b840b21-7032-4f27-8c7c-ea81bfe4bf77', 'a0ee0a38-b0b7-4627-b2e6-d6f5e3f1d61b', 'c', 'La hélice levógira o de paso a la izquierda, es la que en marcha avante y vista desde popa gira en sentido contrario a las agujas del reloj.', false, '2025-09-13 13:53:11.060445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35cf7572-517f-4667-a2a7-32072ee5ebee', 'a0ee0a38-b0b7-4627-b2e6-d6f5e3f1d61b', 'd', 'Un sistema de propulsión con hélice de palas abatibles o plegables se emplea para reducir al mínimo el rozamiento.', false, '2025-09-13 13:53:11.060573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a30a725c-2ab0-4b0e-b620-1ff41a3e0d5e', 'b83a89bb-cf5d-4f32-b6b4-875a767b7dd6', 'a', 'Pieza horizontal que forma parte de la barandilla del barco.', false, '2025-09-13 13:53:11.060851+00');
