INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6896aa5a-2836-4099-b332-83588867c4d6', '9d6572c0-51dc-44b6-800c-0ad46df6374b', 'a', 'En la maniobra de aproximación, el barco que va a remolcar se dirige a poca máquina a barlovento del que va a ser remolcado.', false, '2025-09-13 13:53:11.063486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7638b03c-8b6a-4a28-9dee-7c1a95322c97', '9d6572c0-51dc-44b6-800c-0ad46df6374b', 'b', 'Cuando el barco averiado se encuentre aproado al viento, el remolcador maniobrará para mantenerse siempre con su proa al viento, sin atravesarse, y dará la maniobra del remolque desde su popa a la proa del barco averiado.', true, '2025-09-13 13:53:11.063617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('883b1e7e-96fa-498a-91e4-346ac522f861', '9d6572c0-51dc-44b6-800c-0ad46df6374b', 'c', 'Convendrá que la longitud del cabo del remolque sea tal que el remolcador y el barco remolcado se encuentren simultáneamente en un seno o en una cresta de ola.', false, '2025-09-13 13:53:11.063747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9f39f0a-8522-4a58-8b9c-cf6b0c8969f8', '9d6572c0-51dc-44b6-800c-0ad46df6374b', 'd', 'En el caso de remolque abarloado se tendrá en cuenta la maniobra del conjunto como si se tratara de un sólo barco.', false, '2025-09-13 13:53:11.063885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99152d55-7f15-4efe-9d14-941ee4856bcc', 'ea93bd75-3cea-4093-993f-78d3a25ab75b', 'a', 'El estado de las radiocomunicaciones.', false, '2025-09-13 13:53:11.064148+00');
