INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95e04137-dc02-4f03-b4e5-8f14a64fa607', 'ea93bd75-3cea-4093-993f-78d3a25ab75b', 'd', 'El filtro de decantación de agua.', false, '2025-09-13 13:53:11.064527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebc1d816-ddf2-43d1-87ea-2580562756d2', 'b2803bf8-bfee-4f57-813d-ede9d6705bdf', 'a', 'Acercarse a la costa para navegar lo más próximo a ella.', false, '2025-09-13 13:53:11.064905+00');
