INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bc1901e-6fb8-45d7-a389-830930a05026', 'b2803bf8-bfee-4f57-813d-ede9d6705bdf', 'c', 'Evitar las radiobalizas.', false, '2025-09-13 13:53:11.065157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5da1eb6-f7d6-4997-be7f-9a2e6e06f757', 'b2803bf8-bfee-4f57-813d-ede9d6705bdf', 'd', 'Realizar una secuencia de dos destellos de luz cortos y uno largo.', false, '2025-09-13 13:53:11.065286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bab0fac6-cfeb-4506-be27-4caa6f054cce', '61acca79-977d-4ef6-83aa-8bd44d2357f1', 'b', 'Zafar la trinca, asegurar la fijación al barco de la tira de disparo, lanzar el contenedor de la balsa al agua, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado, embarcar en la balsa y soltar la tira de disparo que mantiene la balsa unida al barco.', true, '2025-09-13 13:53:11.065686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3617c847-811f-429d-95bc-66d719832025', '61acca79-977d-4ef6-83aa-8bd44d2357f1', 'c', 'Zafar la trinca, soltar la tira de disparo que mantiene la balsa unida al barco, lanzar el contenedor de la balsa al agua, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado y embarcar en la balsa.', false, '2025-09-13 13:53:11.065814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86aa8356-40d7-4879-9d9c-3c130ddce2bc', '61acca79-977d-4ef6-83aa-8bd44d2357f1', 'd', 'Zafar la trinca, lanzar el contenedor al agua, asegurar la fijación al barco de la tira de disparo, cobrar la tira de disparo dando un tirón fuerte que provoque el inflado, embarcar en la balsa y soltar la tira de disparo que mantiene la balsa unida al barco.', false, '2025-09-13 13:53:11.065943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f3b61d6-a77b-4e64-bae2-f538202c4f71', '18de6b21-b957-492f-8a26-cb75259c6829', 'a', 'Sin excepción alguna.', false, '2025-09-13 13:53:11.066206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('415ffc9f-42a9-4549-a70f-8145fc4618ff', '18de6b21-b957-492f-8a26-cb75259c6829', 'c', 'Salvo que se haga a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', false, '2025-09-13 13:53:11.06646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dceeff34-804d-426d-9c61-9fc7bb19c641', '18de6b21-b957-492f-8a26-cb75259c6829', 'd', 'Salvo que dicho producto se haya tratado para su esterilización.', false, '2025-09-13 13:53:11.066586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f53445b-af06-4da7-a4b5-24b6cc8180f5', '961b3c51-2993-435f-8832-b449532b7518', 'b', 'Áreas que, por albergar ecosistemas endogámicos de la zona mediterránea o hábitats de especies en endemismo, son importantes para la conservación de los componentes de la diversidad micológica en el Mediterráneo.', false, '2025-09-13 13:53:11.066979+00');
