INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fb2fbde-4b44-4813-a735-67ac3f1bb516', 'c7c12a65-d0b1-44f6-9198-78bccf11d3d6', 'd', 'Amura.', false, '2025-09-13 13:53:11.061915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ef4e87d-e948-4950-9574-28f8b1d8d1ed', '961b3c51-2993-435f-8832-b449532b7518', 'd', 'Áreas que, por albergar ecosistemas específicos de la zona mediterránea o hábitats de especies en peligro, son importantes para la conservación de los componentes de la diversidad biológica en el', true, '2025-09-13 13:53:11.067239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c37735bb-6253-4bdf-8e88-4afa662af5c5', '5235500f-5347-4529-9afd-5a5e04db6ab6', 'a', 'Señalar canales u obstrucciones a los que hace se hace referencia en las publicaciones náuticas.', false, '2025-09-13 13:53:11.067511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26583435-863e-41d1-802c-095b2976062a', '5235500f-5347-4529-9afd-5a5e04db6ab6', 'd', 'Señalar los accesos desde alta mar donde existen áreas con elevada concentración de tráfico marítimo, porque no están indicados en la carta u otro documento náutico.', false, '2025-09-13 13:53:11.067922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b807adb-067c-4348-bf8b-7e53d6f3c20a', '77c91e8c-56a0-47c8-8d4b-1f3ffe75e748', 'a', 'Como marcas de eje de un canal o como marcas de recalada.', true, '2025-09-13 13:53:11.068306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bab085a2-a8d3-492c-9065-c920389db49d', '77c91e8c-56a0-47c8-8d4b-1f3ffe75e748', 'b', 'Para indicar, en el punto de bifurcación de un canal, la ruta que el servicio de señales marítimas competente considera más apropiada para navegar.', false, '2025-09-13 13:53:11.068447+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1a9c740-2809-47cd-99fc-f94ece03bb66', '77c91e8c-56a0-47c8-8d4b-1f3ffe75e748', 'c', 'Para ayudar a la navegación o proporcionar información, indicando las bandas de babor y estribor de la ruta a seguir, para la seguridad de la navegación.', false, '2025-09-13 13:53:11.068577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71942864-1b1d-4f74-bc8f-f19a61f81db8', '77c91e8c-56a0-47c8-8d4b-1f3ffe75e748', 'd', 'Para indicar, colocadas sobre o próximas a un peligro, las zonas de aguas navegables.', false, '2025-09-13 13:53:11.068705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cce8574-31c3-47e4-b8c4-b28b3799072a', '1e3f9c13-4a3c-49a1-8101-2ea0d9dda317', 'a', 'Blanca en grupo de dos destellos GpD (2).', true, '2025-09-13 13:53:11.068999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee7d0f2d-577a-4620-b70e-03ff3a873384', '1e3f9c13-4a3c-49a1-8101-2ea0d9dda317', 'b', 'Blanca con la señal de Morse “A”.', false, '2025-09-13 13:53:11.069125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c599c458-a35a-4b67-a6cd-8b776425c903', '1e3f9c13-4a3c-49a1-8101-2ea0d9dda317', 'c', 'Blanca centelleante rápido continuo VQ.', false, '2025-09-13 13:53:11.069257+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba388caa-ea4c-49a5-9367-af6a960390e0', '1e3f9c13-4a3c-49a1-8101-2ea0d9dda317', 'd', 'Amarilla en grupos de (2+1) destello.', false, '2025-09-13 13:53:11.069384+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17d416df-a7fd-4946-b4a9-6640a23329ab', '4d104891-73f7-4eea-9795-9d5eecbcb45a', 'a', 'Roja.', false, '2025-09-13 13:53:11.069657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e3a5117-8bcb-495e-bdd6-ac9cdcabbcf2', '4d104891-73f7-4eea-9795-9d5eecbcb45a', 'b', 'Roja con una ancha banda horizontal verde.', true, '2025-09-13 13:53:11.069793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1a28887-4cc5-4841-87fd-b9aa73c5baa7', '4d104891-73f7-4eea-9795-9d5eecbcb45a', 'c', 'Verde con una ancha banda horizontal roja.', false, '2025-09-13 13:53:11.069934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fec2d7e2-eaaa-43c1-b8aa-858caaa3cbab', '4d104891-73f7-4eea-9795-9d5eecbcb45a', 'd', 'Verde.', false, '2025-09-13 13:53:11.070066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab976ddb-185c-41c4-86d6-52de60f345f6', 'de93fefc-17ae-474b-aa4f-259948bff07f', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', false, '2025-09-13 13:53:11.070337+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d7e6479-71e6-420a-803f-db98d3261f65', 'de93fefc-17ae-474b-aa4f-259948bff07f', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', true, '2025-09-13 13:53:11.070469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66235db5-029f-42b8-9733-0e99c746a866', 'de93fefc-17ae-474b-aa4f-259948bff07f', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.070596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c027f57-a01c-4ffb-9803-3f53339eb44e', '17839a73-6907-4bb3-aa9e-401aac1dd61b', 'a', 'Tres luces amarillas todo horizonte en línea horizontal o un cilindro.', false, '2025-09-13 13:53:11.070994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c1c314f-232b-42e5-9a50-6665c585884a', '17839a73-6907-4bb3-aa9e-401aac1dd61b', 'b', 'Tres luces amarillas todo horizonte en línea vertical o un cilindro.', false, '2025-09-13 13:53:11.07113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28386d6d-f270-420b-ae48-e63eb40029c4', '17839a73-6907-4bb3-aa9e-401aac1dd61b', 'c', 'Tres luces rojas todo horizonte en línea horizontal o un cilindro.', false, '2025-09-13 13:53:11.071264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a15e0aa-007f-45d4-ad62-2cd97d8ea65f', '17839a73-6907-4bb3-aa9e-401aac1dd61b', 'd', 'Tres luces rojas todo horizonte en línea vertical o un cilindro.', true, '2025-09-13 13:53:11.071392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30a85a71-52b7-4db0-94a3-75001d4a7e8e', 'bf2d3bb4-3a56-4734-ba51-89ecee772964', 'a', 'Naves de vuelo rasante.', false, '2025-09-13 13:53:11.071659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9683d4f7-7215-4f55-a0fa-8c724beec5ef', 'bf2d3bb4-3a56-4734-ba51-89ecee772964', 'b', 'Hidroaviones.', false, '2025-09-13 13:53:11.0718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('685ef4b8-fbcd-4091-95da-463527c623a8', 'bf2d3bb4-3a56-4734-ba51-89ecee772964', 'c', 'Buques dedicados a la pesca.', false, '2025-09-13 13:53:11.071927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41789b65-1eb4-4265-a7d2-fa86ec2caa62', 'bf2d3bb4-3a56-4734-ba51-89ecee772964', 'd', 'Embarcaciones en pantanos y embalses.', true, '2025-09-13 13:53:11.072053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7ced206-4fe4-4d89-89dd-b01541a7d8e0', 'dacc5c8a-743f-494a-ae88-65ec1e71a9e6', 'b', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, cambiará su rumbo a babor para maniobrar a un buque que se encuentre por esa misma banda, si las circunstancias del caso lo permiten.', false, '2025-09-13 13:53:11.072444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54de8c53-855d-4114-8966-cef41a3733c7', 'dacc5c8a-743f-494a-ae88-65ec1e71a9e6', 'c', 'Cuando exista riesgo de abordaje, sólo podrá ejecutar la maniobra que mejor pueda ayudar a evitarlo el buque que ceda el paso.', false, '2025-09-13 13:53:11.072571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbbef336-faeb-4a20-ac94-dd7f4daed82e', 'dacc5c8a-743f-494a-ae88-65ec1e71a9e6', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:11.072698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e45016a-459d-4859-8130-345505a757b6', '837d7815-3ad1-4503-8d3f-357c36faf9a3', 'a', 'Como si fueran buques con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.073114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7f39af7-c42f-4edd-a4b8-cde72023fa27', '837d7815-3ad1-4503-8d3f-357c36faf9a3', 'b', 'Como si fueran buques de propulsión mecánica.', true, '2025-09-13 13:53:11.073257+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b391ea1e-28d5-4a9d-bcdc-a08956845a69', '837d7815-3ad1-4503-8d3f-357c36faf9a3', 'c', 'Como si fueran buques de vela.', false, '2025-09-13 13:53:11.073391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39125997-29ad-4c69-b3e2-14866bd9c188', '837d7815-3ad1-4503-8d3f-357c36faf9a3', 'd', 'Como si fueran buques dedicados a la pesca.', false, '2025-09-13 13:53:11.073519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e70b78f0-03c4-4793-8d76-4dcc4e09473a', 'de67b544-1c56-47cc-8cff-631a0075d486', 'a', 'NC.', true, '2025-09-13 13:53:11.073807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('029704f6-665f-4e34-b384-5cc7be1cdd26', 'de67b544-1c56-47cc-8cff-631a0075d486', 'b', 'NA.', false, '2025-09-13 13:53:11.07394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e683de65-9c8e-4947-85c3-073c29a774f5', 'de67b544-1c56-47cc-8cff-631a0075d486', 'c', 'SM.', false, '2025-09-13 13:53:11.074067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16566031-3237-4d15-8166-2cf59c256b0b', 'de67b544-1c56-47cc-8cff-631a0075d486', 'd', 'CS.', false, '2025-09-13 13:53:11.074194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1dd40d3-a945-4169-b813-caf8df7c7190', 'ba4840f2-2457-4589-95c1-63f42efd53f7', 'a', 'Se mantendrán lo más cerca posible del límite interior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', false, '2025-09-13 13:53:11.074462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f14587d-24d6-4b44-99f1-8eb75c17e456', 'ba4840f2-2457-4589-95c1-63f42efd53f7', 'b', 'Los buques de eslora inferior a 20 metros, o los buques de vela, tendrán prioridad de tránsito respecto a cualquier otro buque dentro de un paso o canal angosto.', false, '2025-09-13 13:53:11.074592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7dffe91a-acaa-40b9-bcf1-ec8fc0c20f3b', 'ba4840f2-2457-4589-95c1-63f42efd53f7', 'c', 'En ningún caso los buques podrán fondear en un canal angosto.', false, '2025-09-13 13:53:11.074719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c1e19f3-2cae-4405-b486-1317e14f60a4', 'ba4840f2-2457-4589-95c1-63f42efd53f7', 'd', 'Se mantendrán lo más cerca posible del límite exterior del paso o canal que quede por su costado de estribor, siempre que puedan hacerlo sin que ello entrañe peligro.', true, '2025-09-13 13:53:11.074847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0015ae3c-5637-42ab-83d0-acc834b4e67a', 'b77592a2-31f4-4090-8cd9-f5046a1f3ae9', 'a', 'De tal índole que no pueda confundirse con ninguna ayuda a la navegación.', true, '2025-09-13 13:53:11.075122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cedb06d-dec6-45b7-9f25-07aa54e9c71d', 'b77592a2-31f4-4090-8cd9-f5046a1f3ae9', 'b', 'Intermitente.', false, '2025-09-13 13:53:11.075252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a360665-2ecb-4a66-ba7b-069290b44e04', 'b77592a2-31f4-4090-8cd9-f5046a1f3ae9', 'c', 'Giratoria de gran intensidad.', false, '2025-09-13 13:53:11.07538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11a26c1e-e7f2-49e9-b634-7687c7a162d6', 'b77592a2-31f4-4090-8cd9-f5046a1f3ae9', 'd', 'Estroboscópica.', false, '2025-09-13 13:53:11.075518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('486ef427-6937-4683-a655-df11ec2eb000', 'abdab7f8-de94-4260-b520-461c55b6ccc2', 'b', 'Si la demora o la marcación de un buque que se aproxima no varía de forma apreciable, se considerará que no existe riesgo de abordaje.', false, '2025-09-13 13:53:11.075946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e1643e9-8dab-4dd3-af6e-847e253fc425', '5235500f-5347-4529-9afd-5a5e04db6ab6', 'c', 'Indicar el sentido convencional del balizamiento, porque este no se indica en las publicaciones náuticas.', false, '2025-09-13 13:53:11.067793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46ef5c4c-c5f4-4a77-908b-c990450269aa', 'dacc5c8a-743f-494a-ae88-65ec1e71a9e6', 'a', 'Se exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', false, '2025-09-13 13:53:11.072316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6dac65c1-a31d-46e6-8fd7-c3f3a6c6998d', 'abdab7f8-de94-4260-b520-461c55b6ccc2', 'a', 'Se evitarán las suposiciones basadas en información insuficiente, especialmente la obtenida por radar.', true, '2025-09-13 13:53:11.075812+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1c58f4e-a308-4337-84df-eb3980b0b0e5', 'abdab7f8-de94-4260-b520-461c55b6ccc2', 'c', 'En caso de abrigarse alguna duda respecto a si existe riesgo de abordaje, se considerará que no existe.', false, '2025-09-13 13:53:11.076076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd0fc0ac-f61d-49db-b103-582a198e7121', 'de93fefc-17ae-474b-aa4f-259948bff07f', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', false, '2025-09-13 13:53:11.070722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6e3dd61-70c0-4a2a-acca-c237c08842f2', '5235500f-5347-4529-9afd-5a5e04db6ab6', 'b', 'Indicar zonas o configuraciones cuya naturaleza exacta está indicada en la carta u otro documento náutico.', true, '2025-09-13 13:53:11.067642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d698553d-0879-44ad-b01b-f6b224926df1', 'abdab7f8-de94-4260-b520-461c55b6ccc2', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-13 13:53:11.076203+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53445af5-2203-4852-9520-5f15746bbeba', 'fc34f04d-6b1a-4237-875d-bf12fe342f5b', 'a', 'Blanca que muestra luz sin interrupción.', true, '2025-09-13 13:53:11.076476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('460a727b-a559-4d23-a991-0d66fc82cec7', 'fc34f04d-6b1a-4237-875d-bf12fe342f5b', 'b', 'Amarilla que muestra luz sin interrupción.', false, '2025-09-13 13:53:11.076604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e26b4bd-e0cb-47f9-9f5c-670e0916fbf5', 'fc34f04d-6b1a-4237-875d-bf12fe342f5b', 'c', 'Blanca que muestra luz centelleante.', false, '2025-09-13 13:53:11.076731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('901f2081-f520-4855-b4eb-096d64118e81', 'fc34f04d-6b1a-4237-875d-bf12fe342f5b', 'd', 'Amarilla que muestra luz centelleante.', false, '2025-09-13 13:53:11.076857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('588a37cd-4565-46f2-9ec9-227144b0639a', '2cc0beb9-6035-48a0-8b4c-953182fb6a93', 'b', 'El buque que tenga al otro por su costado de estribor mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:11.077264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4f9c177-37ae-4211-9380-46774f65aed6', '2cc0beb9-6035-48a0-8b4c-953182fb6a93', 'c', 'Aumentarán su velocidad para cruzarse lo antes posible.', false, '2025-09-13 13:53:11.077391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90ed830e-0565-41a6-b0e4-5d7e2deef32a', '2cc0beb9-6035-48a0-8b4c-953182fb6a93', 'd', 'El buque que tenga al otro por su costado de babor, se mantendrá apartado de la derrota de éste Maniobra y navegación.', false, '2025-09-13 13:53:11.077521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d1540d4-73dc-48e7-a376-235a26a8d4b2', '63938b38-c4ea-4f38-8b72-1d31415633a1', 'a', 'Poder largar cómodamente desde el barco facilitando el desamarre.', true, '2025-09-13 13:53:11.077919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f734db8e-ae8f-48af-9691-e003631cecfc', '63938b38-c4ea-4f38-8b72-1d31415633a1', 'b', 'Que la embarcación quede más segura mientras no salimos.', false, '2025-09-13 13:53:11.078068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bba69259-ff95-45cc-ae18-e0e4c0761391', '63938b38-c4ea-4f38-8b72-1d31415633a1', 'c', 'Que sea necesario el uso de una codera en popa para poder salir.', false, '2025-09-13 13:53:11.078204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eecea23-16b3-4abf-b8ce-249c95466490', '63938b38-c4ea-4f38-8b72-1d31415633a1', 'd', 'Que la embarcación quede firme al muelle dificultando el desamarre.', false, '2025-09-13 13:53:11.078338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a77e780-41e2-4661-ab9d-0534661a485b', '28c74867-3d33-410a-8c77-00947b37be94', 'a', 'La embarcación tenderá a evolucionar con caída de popa a estribor y proa a babor.', false, '2025-09-13 13:53:11.078624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0989617-5375-4c5a-b74e-18f5c5951b57', '28c74867-3d33-410a-8c77-00947b37be94', 'b', 'La embarcación tenderá a evolucionar con caída de popa a babor y proa a estribor.', true, '2025-09-13 13:53:11.078758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9186c97d-2eb4-47ed-b01a-03c0b406df73', '28c74867-3d33-410a-8c77-00947b37be94', 'c', 'La caída de popa y proa será indiferente, no viéndose afectada por el efecto combinado de la hélice y el timón.', false, '2025-09-13 13:53:11.0789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92ba5c1f-abd1-44c0-8f60-17d7c4b4761e', '160ff291-2655-4fe7-ba1a-de82dd721ae5', 'a', 'Para prevenir una vía de agua, se deben cerrar las válvulas que no se utilicen, asegurar la estanqueidad de portillos y escotillas y fijar el ancla para que no golpee el casco.', false, '2025-09-13 13:53:11.079338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13d9f969-0c28-4f6d-9fa8-143d5d9b36db', '160ff291-2655-4fe7-ba1a-de82dd721ae5', 'b', 'Si se detecta agua en la sentina, deben ponerse en marcha de inmediato todas las bombas de achique y mantener encendido el motor.', false, '2025-09-13 13:53:11.079483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e15aca40-88a5-4dbc-8af7-3b865b12d6de', '160ff291-2655-4fe7-ba1a-de82dd721ae5', 'c', 'Para reforzar el trabajo de las bombas de achique, se puede soltar la toma de agua de mar de refrigeración del motor, cerrar el paso y hacer que succione el agua embarcada.', false, '2025-09-13 13:53:11.079623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0223e29e-8b56-4728-bb61-2da8fe485157', '160ff291-2655-4fe7-ba1a-de82dd721ae5', 'd', 'Los puntos de mayor riesgo para producirse una vía de agua son las lumbreras, los imbornales de cubierta y la hélice.', true, '2025-09-13 13:53:11.07977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab6f80bf-b8de-4587-9364-5ca775e02066', '2cb1f49c-0092-48ae-a185-fce73ca01fb5', 'a', 'Materiales sólidos, generalmente de naturaleza orgánica, cuya combustión se realiza normalmente con formación de brasas.', true, '2025-09-13 13:53:11.080059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68916d58-361f-42c9-a3ad-6675ce670297', '2cb1f49c-0092-48ae-a185-fce73ca01fb5', 'b', 'Líquidos o de sólidos licuables.', false, '2025-09-13 13:53:11.080198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a8b05a7-51f5-456e-b882-99f592ed462d', '2cb1f49c-0092-48ae-a185-fce73ca01fb5', 'c', 'Metales.', false, '2025-09-13 13:53:11.080335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c45f45d3-9a94-4271-b2c2-99bb79b01878', '2cb1f49c-0092-48ae-a185-fce73ca01fb5', 'd', 'Los derivados de la utilización de ingredientes para cocinar (aceites y grasa vegetales o animales) en los aparatos de cocina.', false, '2025-09-13 13:53:11.080472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e295f4f0-d452-428f-8952-9d49720aa9a7', 'fbbd5c97-bbe0-4d5a-894b-ab3dd900b2ce', 'a', 'La asistencia médica se realiza en español y está disponible las 24 horas, todos los días del año.', false, '2025-09-13 13:53:11.080756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e74d2ee-6884-49e5-a35c-3108e39f63cd', 'fbbd5c97-bbe0-4d5a-894b-ab3dd900b2ce', 'b', 'Los buques que dispongan de sistema de comunicación vía satélite o de telefonía móvil, pueden contactar directamente en el número 91 310 34 75.', false, '2025-09-13 13:53:11.080928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c139909-d874-4ec2-aebc-2767313fa8c3', 'fbbd5c97-bbe0-4d5a-894b-ab3dd900b2ce', 'c', 'Se recomienda realizar las consultas no urgentes entre las 9:00 y las 15:00 horas (hora de Madrid), reservando el resto para consultas urgentes.', false, '2025-09-13 13:53:11.081076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9cd9cb29-f50f-454b-9d79-862dfa7418c6', 'fbbd5c97-bbe0-4d5a-894b-ab3dd900b2ce', 'd', 'Depende del Instituto Social de Medicina Preventiva y Salud Pública de la Marina. Meteorología', true, '2025-09-13 13:53:11.081214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45395c81-2bc2-42a8-8271-261c39c057c1', 'ec7d58b7-cd27-453e-9899-68564b606b7a', 'a', 'Es una región donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:11.081495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fb7655c-3e8f-4dc6-943d-d86ae7fce865', 'ec7d58b7-cd27-453e-9899-68564b606b7a', 'b', 'El aire fluye hacia el interior de las borrascas y asciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.081629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b96f029-a55a-4882-9f6d-4286827d9209', 'ec7d58b7-cd27-453e-9899-68564b606b7a', 'd', 'El proceso de formación de una borrasca se denomina ciclogénesis.', false, '2025-09-13 13:53:11.081908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1830c19e-0cbe-4768-9dfc-30449f4bfecc', '8026437a-b266-4f4d-b829-1e7ab8788ef8', 'a', 'Representa los grados de intensidad del estado de la mar u oleaje, con los indicadores aproximados para clasificarla, y la altura de ola equivalente.', true, '2025-09-13 13:53:11.0822+00');
