INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25da70bb-2925-4d12-aef8-6da7dfa3bcde', '8026437a-b266-4f4d-b829-1e7ab8788ef8', 'd', 'Va de cero a 12 siendo decreciente la altura de ola equivalente.', false, '2025-09-13 13:53:11.082602+00');
