INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7c4e744-4a34-4554-a830-ee8a6fd78063', '799da7ce-10ad-48c5-a336-bde5aec4969e', 'c', 'En dirección contraria a la corriente y amarrando primero por popa.', false, '2025-09-13 13:53:11.09137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94b4bc50-a32a-4bb5-b890-5f98b5dc29a7', '799da7ce-10ad-48c5-a336-bde5aec4969e', 'd', 'En dirección contraria a la corriente y amarrando primero por proa.', true, '2025-09-13 13:53:11.091502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad4ae174-f8ee-4d06-967b-cbb317d3c4e0', '82651960-53ee-437a-8517-5639395ba6fe', 'a', 'Dando avante poca, rueda a estribor y el esprín de proa firme.', true, '2025-09-13 13:53:11.091786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aef9db80-2a48-4fe9-93f8-5be5558a5603', '82651960-53ee-437a-8517-5639395ba6fe', 'b', 'Dando atrás poca, rueda a babor y el esprín de popa firme.', false, '2025-09-13 13:53:11.091921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d5bb882-69eb-480a-a2e7-136167efa3df', '82651960-53ee-437a-8517-5639395ba6fe', 'c', 'Sin emplear máquina ni timón, iremos lascando poco a poco el largo de popa.', false, '2025-09-13 13:53:11.092055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d69fc124-7606-4e00-998b-184104d3c0ef', 'de2cef17-3173-4308-a694-a3094897e2c1', 'a', 'A la hora de reflotar la embarcación se tendrá en cuenta, entre otros, los daños en la obra viva, la resistencia estructural del casco y la naturaleza del fondo en que ha varado.', false, '2025-09-13 13:53:11.092464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60045eb0-0958-4be4-aa90-241b9217ca0d', 'de2cef17-3173-4308-a694-a3094897e2c1', 'b', 'Si el fondo es fangoso, se trasladarán pesos para cambiar el asiento, mover lateralmente a uno y otro lado la embarcación para abrir la cama y esperar el mejor momento de la marea.', false, '2025-09-13 13:53:11.0926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50f4a517-c801-44b2-8b3d-b5820bcbab03', 'de2cef17-3173-4308-a694-a3094897e2c1', 'c', 'Tras la varada, y antes de evaluar los daños sufridos, hay que avisar inmediatamente a Salvamento Marítimo y abandonar la embarcación.', true, '2025-09-13 13:53:11.092735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f444b0e5-0690-46b1-a60a-53c1340ff495', 'de2cef17-3173-4308-a694-a3094897e2c1', 'd', 'Si se ha varado en fondo rocoso, y no se detectan vías de agua, se dará rápidamente atrás.', false, '2025-09-13 13:53:11.092881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cde17647-d0d9-4b54-b37c-50ee65a0aaa8', '88b1b913-748a-4ee6-bc61-5a530e5d9c33', 'b', 'En el caso de insolación o golpe de calor, no se deben administrar bebidas alcohólicas ni estimulantes y se debe bajar la temperatura corporal, pero no por debajo de los 38,5º.', true, '2025-09-13 13:53:11.093304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da69fd5d-9413-4666-9160-2fad052d1c5a', '88b1b913-748a-4ee6-bc61-5a530e5d9c33', 'c', 'Una herida que presente cuerpos extraños se considerará una herida grave y en ese caso, se aplicarán antisépticos y pomadas una vez se hayan extraído estos.', false, '2025-09-13 13:53:11.093455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f393460-ad69-4e9b-b9e7-09498421758e', '88b1b913-748a-4ee6-bc61-5a530e5d9c33', 'd', 'En el caso de quemaduras, se enfriarán las áreas quemadas con agua fría, se romperán las ampollas y se pondrá un apósito estéril.', false, '2025-09-13 13:53:11.093587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('903d9e91-236b-449d-b5f6-8d1a1d2c9e0f', 'bf6566ea-184d-475b-85d3-670aec954cf1', 'a', 'Combustible, Comburente y Calor.', false, '2025-09-13 13:53:11.093888+00');
