INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfc5a1ff-7355-4d69-8007-cc0b34c06817', '811238e0-9206-4388-b29d-22bdac51ab04', 'a', 'El desvío puede corregirlo cualquier persona de a bordo, bastando para ello colocar unos imanes alrededor del compás.', true, '2025-09-13 13:53:11.100173+00');
