INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9faf8d1-37af-409b-90c2-4cdc3180627c', '8f76fc31-dfd9-42c8-8c4c-37327e03d229', 'c', 'Combustible, Comburente, Calor y Reacción en cadena.', true, '2025-09-13 13:53:11.106607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ad4c166-9f05-4688-8af2-230920f4b903', '8f76fc31-dfd9-42c8-8c4c-37327e03d229', 'd', 'Oxígeno, Combustible y Chispa.', false, '2025-09-13 13:53:11.106752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ee021e8-0ef6-4777-8be9-93772dd9a3a8', '8663536d-2586-4869-a01b-106e77722b88', 'a', 'A la hora de reflotar la embarcación se tendrá en cuenta, entre otros, los daños en la obra viva, la resistencia estructural del casco y la naturaleza del fondo en que ha varado.', false, '2025-09-13 13:53:11.107072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec0d771b-a5ee-494f-80e9-ca6127df1bee', '8663536d-2586-4869-a01b-106e77722b88', 'b', 'Si el fondo es fangoso, se trasladarán pesos para cambiar el asiento, mover lateralmente a uno y otro lado la embarcación para abrir la cama y esperar el mejor momento de la marea.', false, '2025-09-13 13:53:11.107246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7fe2fc8-a835-43a1-b213-177de2e890f6', 'f50e0d34-a21f-42d6-af0e-d191152aefdc', 'd', 'Una pitada larga.', false, '2025-09-13 13:53:11.241638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('240842dd-3573-4ce5-9a84-d022818a193c', '6c6a0809-28f8-4192-a8a8-c13e8d5e3a33', 'd', 'Su valor es constante en la superficie del mar.', false, '2025-09-13 13:53:11.097664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03938530-c231-46bb-b8dd-195d2340f671', 'b19a16fa-91b9-4718-bc91-779080085eeb', 'd', 'Es un círculo menor perpendicular al ecuador.', false, '2025-09-13 13:53:11.101264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc056751-1ba7-46cd-921a-48c10a59b141', '8663536d-2586-4869-a01b-106e77722b88', 'c', 'Tras la varada, y antes de evaluar los daños sufridos, hay que avisar inmediatamente a Salvamento Marítimo y abandonar la embarcación.', true, '2025-09-13 13:53:11.107398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3df4796d-ccde-48a5-9b24-27cfe3ff142c', '8663536d-2586-4869-a01b-106e77722b88', 'd', 'Si se ha varado en fondo rocoso, y no se detectan vías de agua, se dará rápidamente atrás.', false, '2025-09-13 13:53:11.107562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01fa4644-3550-4000-afae-112985916c91', '66b7bee8-6991-43e6-8c07-d2ccc07815ef', 'b', 'En el caso de insolación o golpe de calor, no se deben administrar bebidas alcohólicas ni estimulantes y se debe bajar la temperatura corporal, pero no por debajo de los 38,5º.', true, '2025-09-13 13:53:11.108023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1afd200-b1cb-4e2d-b3db-1e0c613debe5', '66b7bee8-6991-43e6-8c07-d2ccc07815ef', 'c', 'Una herida que presente cuerpos extraños se considerará una herida grave y en ese caso, se aplicarán antisépticos y pomadas una vez se hayan extraído estos.', false, '2025-09-13 13:53:11.108173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c8a2d76-c41e-48f3-bef0-6830324f3c50', '66b7bee8-6991-43e6-8c07-d2ccc07815ef', 'd', 'En el caso de quemaduras, se enfriarán las áreas quemadas con agua fría, se romperán las ampollas y se pondrá un apósito estéril. Meteorología', false, '2025-09-13 13:53:11.108326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcaad144-8532-423e-8c4b-496a8f539db4', '9b5f4a79-7cdc-4be8-9361-8e617c63ff69', 'a', 'Es la relación entre los pesos del aire y del mercurio.', false, '2025-09-13 13:53:11.108619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46d88e38-f697-4e70-9d47-85140a8b656a', '9b5f4a79-7cdc-4be8-9361-8e617c63ff69', 'b', 'Su valor es mínimo a nivel del mar.', false, '2025-09-13 13:53:11.108769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f2e9a73-0b1a-4f42-b67c-89937c6995e7', '9b5f4a79-7cdc-4be8-9361-8e617c63ff69', 'c', 'Es consecuencia de la atracción gravitatoria.', true, '2025-09-13 13:53:11.108909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f061ad61-65df-49ae-ac61-a10c8d761b43', '9b5f4a79-7cdc-4be8-9361-8e617c63ff69', 'd', 'Su valor es constante en la superficie del mar.', false, '2025-09-13 13:53:11.109043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5a9ab46-6a35-4a77-94ed-54fcc56ebb2c', '4b98e21c-9b1a-4041-b41a-ef06f03b531c', 'a', 'Viento intenso que se produce en invierno en la zona tropical al rolar los alisios.', false, '2025-09-13 13:53:11.109329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f48b640-b810-4f44-bea5-e34267426156', '4b98e21c-9b1a-4041-b41a-ef06f03b531c', 'c', 'Brisa que se produce del mar a la tierra en épocas de calor durante las horas centrales del día.', true, '2025-09-13 13:53:11.109601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dda1dbcd-b17a-48fb-a3c3-57d246f67043', '4b98e21c-9b1a-4041-b41a-ef06f03b531c', 'd', 'Vientos locales, que se producen de noche desde la tierra al mar durante periodos invernales.', false, '2025-09-13 13:53:11.109885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eb97c07-1830-43a8-81be-450c896b96f1', '9d3612dd-daa7-4134-8486-8668418d44af', 'a', 'Velocidad y dirección.', false, '2025-09-13 13:53:11.110176+00');
