INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e598bf0-c704-4dd8-998c-eb30a65da7db', '8950e22b-3b55-44d4-a5dc-d2614a8491e3', 'a', 'En sentido horario.', true, '2025-09-13 13:53:11.110899+00');
