INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bfe6d00-4325-491f-90d7-3bab3342bd6b', 'bae53731-2b88-4cf7-8262-b796de501c1a', 'a', 'El guardín es el aparejo que permite sujetar el timón al codaste.', true, '2025-09-13 13:53:11.119911+00');
