INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b11f0f41-76de-420b-a32f-fff8a8d92931', '332efdf6-313d-49a4-ba6c-1e264f2edc86', 'a', 'Su posición de equilibrio adrizado.', true, '2025-09-13 13:53:11.124367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6270b399-40f7-4e21-b4a7-218d2bde58d5', '332efdf6-313d-49a4-ba6c-1e264f2edc86', 'b', 'Su flotabilidad bajo la acción de olas transversales.', false, '2025-09-13 13:53:11.124501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96b0fa18-b479-4b55-b739-8e12dc1eda54', '332efdf6-313d-49a4-ba6c-1e264f2edc86', 'c', 'Su balance.', false, '2025-09-13 13:53:11.124633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db520072-3880-454d-af09-b58eb348140b', '332efdf6-313d-49a4-ba6c-1e264f2edc86', 'd', 'Su posición de asiento en equilibrio.', false, '2025-09-13 13:53:11.12477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a35d320e-8e44-4e8e-88f8-132a52ae90d9', '6445d254-6990-4120-bbe2-c58738eacc8f', 'a', 'En el momento en que la proa haya caído 70º, meter el timón a la banda contraria por la que haya caído el naufrago hasta navegar a un rumbo opuesto al inicio de la maniobra.', true, '2025-09-13 13:53:11.125041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34f6cca4-eebc-435e-84e6-954342e3216a', '6445d254-6990-4120-bbe2-c58738eacc8f', 'b', 'En el momento en que la proa haya caído 70º, meter el timón a la banda por donde haya caído el naufrago hasta navegar a un rumbo opuesto al inicio de la maniobra.', false, '2025-09-13 13:53:11.125173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d02f303-8a90-48fe-8ea4-c336facf6482', '6445d254-6990-4120-bbe2-c58738eacc8f', 'c', 'Meter el timón a la banda de caída del náufrago hasta que la proa haya caído 250°, en cuyo momento se pone el timón al medio y se para la máquina. El barco seguirá cayendo por inercia hasta lograr los 270°.', false, '2025-09-13 13:53:11.125303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8394e550-91a0-4313-913d-0ebff4285503', '6445d254-6990-4120-bbe2-c58738eacc8f', 'd', 'Meter el timón a la banda de caída más rápida hasta lograr 250° con respecto al rumbo primitivo, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto a la inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', false, '2025-09-13 13:53:11.125434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62e46728-fc34-4517-ab39-c1c4317b5ae6', '1e4a19cb-9d3e-4c7b-a1b2-093df6479b57', 'a', 'Se podrá descargar en el mar materia plástica, siempre que no se trate en ningún caso de la cabuyería y redes de pesca de fibras sintéticas, las bolsas de plástico para la basura y las cenizas de incinerador de productos de plástico, sin que esta enumeración sea exhaustiva.', false, '2025-09-13 13:53:11.125716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ef826f3-87ed-4529-a6c0-6db3012a9f11', '1e4a19cb-9d3e-4c7b-a1b2-093df6479b57', 'b', 'Se prohíbe descargar en el mar toda materia plástica, salvo cuando ello sea necesario para proteger la seguridad del buque y de las personas a bordo o para salvar vidas en el mar.', true, '2025-09-13 13:53:11.125996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1445e984-6f57-415a-80c5-27d4186dfb2a', '1e4a19cb-9d3e-4c7b-a1b2-093df6479b57', 'c', 'Se prohíbe descargar en el mar toda materia plástica sin excepción alguna, incluidas, sin que la enumeración sea exhaustiva, la cabuyería y redes de pesca de fibras sintéticas, las bolsas de plástico para la basura y las cenizas de incinerador de productos de plástico.', false, '2025-09-13 13:53:11.12614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3357eeb-a79a-4fe9-9b5a-e7a50830d1fd', '1e4a19cb-9d3e-4c7b-a1b2-093df6479b57', 'd', 'Se podrá descargar en el mar materia plástica, salvo las bolsas de plástico para la basura, a no ser que quede claro que mantener dichos desechos a bordo representa un riesgo inminente para la salud de las personas a bordo.', false, '2025-09-13 13:53:11.126283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16597569-71d0-4537-bfc0-5b1fc20a9bd9', 'e51d1127-e37b-4137-b526-2b98428de4be', 'a', 'Áreas del territorio nacional y del medio marino mediterráneo, junto con la zona económica exclusiva y la plataforma continental, más adecuados en número y en superficie para la conservación de las especies de aves incluidas en él.', false, '2025-09-13 13:53:11.12657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e461728e-9840-465e-ba29-3bbc4df8c46f', 'e51d1127-e37b-4137-b526-2b98428de4be', 'b', 'Áreas que por sus especiales características se consideren adecuadas para la regeneración de los recursos pesqueros, contribuyendo a la preservación de la riqueza natural de determinadas zonas, la conservación de las diferentes especies marinas o la recuperación de los ecosistemas en el', false, '2025-09-13 13:53:11.126705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7aeaf14-d979-4d16-9e5a-f8a0e85743b6', 'e51d1127-e37b-4137-b526-2b98428de4be', 'c', 'Áreas naturales mediterráneas, que, en razón a la belleza de sus paisajes, la representatividad de sus ecosistemas o la singularidad de su flora, de su fauna o de su diversidad geológica, incluidas sus formaciones geomorfológicas, posean unos valores ecológicos, estéticos, educativos y científicos cuya conservación merece una atención preferente.', false, '2025-09-13 13:53:11.126849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb152eef-9efe-4393-80b6-231ed213c850', 'e51d1127-e37b-4137-b526-2b98428de4be', 'd', 'Áreas que, por albergar ecosistemas específicos de la zona mediterránea o hábitats de especies en peligro, sean importantes para la conservación de los componentes de la diversidad biológica en el Mediterráneo y tienen un interés científico, estético, cultural o educativo especial.', true, '2025-09-13 13:53:11.126982+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38c0f914-dfdb-4352-bc12-c5fa261dfcf6', '3b1defec-9e94-4ea5-8f91-906f21853826', 'a', 'En el cuadrante Norte.', false, '2025-09-13 13:53:11.127279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37cd74d1-b441-4533-82d8-46ea917ce627', '3b1defec-9e94-4ea5-8f91-906f21853826', 'b', 'En el cuadrante Oeste.', true, '2025-09-13 13:53:11.12741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca42b3a3-2afc-40ab-b717-5be884753325', '3b1defec-9e94-4ea5-8f91-906f21853826', 'c', 'En el cuadrante Este.', false, '2025-09-13 13:53:11.127543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84f43c63-790a-4549-ad3a-0994e9be4639', '3b1defec-9e94-4ea5-8f91-906f21853826', 'd', 'En el cuadrante Sur.', false, '2025-09-13 13:53:11.127676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4782dd9e-1c10-443c-8863-54ed7ae01237', '839107f2-7044-4c87-92a3-df7ce2a5b619', 'a', 'Un aspa amarilla, en forma de X.', true, '2025-09-13 13:53:11.12797+00');
