INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a68231fe-fbff-4b57-9a63-a07052b8c693', '839107f2-7044-4c87-92a3-df7ce2a5b619', 'c', 'Un aspa amarilla, en forma esférica.', false, '2025-09-13 13:53:11.12824+00');
