INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('794a3cea-6798-497b-8657-129d611d671b', 'af1b824a-4b36-483d-9030-4e5812b13a5a', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.128701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9234da3b-2729-4677-b881-86fa2328796f', 'af1b824a-4b36-483d-9030-4e5812b13a5a', 'b', 'Aguas Navegables.', false, '2025-09-13 13:53:11.12886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('238a17b4-58bf-41a4-8508-0ccd75a51df9', 'af1b824a-4b36-483d-9030-4e5812b13a5a', 'c', 'Especial.', false, '2025-09-13 13:53:11.129003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8da84b6-4433-4ab0-b531-dee8d5f14791', 'af1b824a-4b36-483d-9030-4e5812b13a5a', 'd', 'Peligro nuevo.', false, '2025-09-13 13:53:11.129134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70f8aa70-6a74-490c-bb26-d97b03c18509', '5de1c44d-52e4-4990-8a54-e68b9816f56c', 'a', 'Canal principal a estribor.', false, '2025-09-13 13:53:11.129415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82161d5f-24c9-418c-9b5b-b2b13b9acfad', '5de1c44d-52e4-4990-8a54-e68b9816f56c', 'b', 'Canal principal a babor.', true, '2025-09-13 13:53:11.129546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3d17302-b9e0-4b43-8be7-a9757bef2196', '5de1c44d-52e4-4990-8a54-e68b9816f56c', 'c', 'Marca cardinal Este.', false, '2025-09-13 13:53:11.129677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d3ec641-033e-4b11-b44c-bbbc0c9bea5a', '5de1c44d-52e4-4990-8a54-e68b9816f56c', 'd', 'Marca de aguas navegables.', false, '2025-09-13 13:53:11.129828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46b37c81-db44-4153-aa6d-2e77aea747b5', 'bb2854c2-8826-48d5-b4c7-12ef03b79a0c', 'a', 'Marcas para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.130288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80043eac-97df-4c7a-9864-689be3105909', 'bb2854c2-8826-48d5-b4c7-12ef03b79a0c', 'b', 'Marcas que indican los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:11.130424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ecc227c-dea6-4b41-8be4-c056574915ef', 'bb2854c2-8826-48d5-b4c7-12ef03b79a0c', 'c', 'Marcas que, asociadas al compás del buque, indican al navegante dónde están las aguas', false, '2025-09-13 13:53:11.130558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef0fab67-911b-454f-ac91-61484186d238', 'bb2854c2-8826-48d5-b4c7-12ef03b79a0c', 'd', 'Marcas que definen los ejes de los canales. Reglamento (RIPA).', true, '2025-09-13 13:53:11.130691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b92f2eda-d5bf-48f0-8c3e-3885b1c89a3b', 'a35c038f-d539-4261-abe3-1e7871dcb93a', 'a', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca o de cualquier otra', false, '2025-09-13 13:53:11.130969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a422468c-3a19-4b24-a636-04b09653c501', 'a35c038f-d539-4261-abe3-1e7871dcb93a', 'b', 'La maniobrabilidad del buque, teniendo muy en cuenta la distancia de parada y la capacidad de giro en las condiciones del momento.', false, '2025-09-13 13:53:11.131103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c39306fb-a94e-48f3-a248-99ba7e890572', 'a35c038f-d539-4261-abe3-1e7871dcb93a', 'c', 'El estado de visibilidad.', false, '2025-09-13 13:53:11.131237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dda5d43d-c095-43a0-8956-846396c6e1a9', 'a35c038f-d539-4261-abe3-1e7871dcb93a', 'd', 'La potencia del motor.', true, '2025-09-13 13:53:11.131371+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2285f40a-34a6-43ac-b31a-342d1a49872d', 'b9e47e24-07aa-4efe-893a-e9ffda9f17d6', 'a', 'A popa, cuando tengan menos de 30 metros de eslora.', false, '2025-09-13 13:53:11.131653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b0eba0b-e3bb-4cf3-b351-3e925ac591d2', 'b9e47e24-07aa-4efe-893a-e9ffda9f17d6', 'b', 'A popa, cuando tengan al menos 50 metros de eslora.', true, '2025-09-13 13:53:11.131805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bc983c5-e6a4-478a-81eb-56d946afa218', 'b9e47e24-07aa-4efe-893a-e9ffda9f17d6', 'c', 'A proa y más alta que la de popa.', false, '2025-09-13 13:53:11.131941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9056d98-5d4c-4cc8-bba7-6b725b6c6fc5', 'b9e47e24-07aa-4efe-893a-e9ffda9f17d6', 'd', 'A popa y más baja que la de proa.', false, '2025-09-13 13:53:11.132075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('113858f7-731a-4c13-9e71-46ae31e33e6a', 'b59cab75-74e6-453c-84bf-d5edf9652b2f', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de costado de dicho buque.', false, '2025-09-13 13:53:11.132355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4eeacd4-ef09-4f63-969d-1246e5efcd84', 'b59cab75-74e6-453c-84bf-d5edf9652b2f', 'b', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance y una luz de costado de dicho buque.', false, '2025-09-13 13:53:11.13249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dc193e8-41df-40ad-84f7-ca7afb7747cd', 'b59cab75-74e6-453c-84bf-d5edf9652b2f', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:11.132623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a238651e-86d3-45a6-820a-1d102acd6c2e', 'b59cab75-74e6-453c-84bf-d5edf9652b2f', 'd', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:11.132755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0db7d8d1-a202-48f2-b0e3-701f55486ec2', 'c286adba-c042-423f-b980-7050b8b52b83', 'a', 'Habrán de iluminarse como si fueran un solo buque.', true, '2025-09-13 13:53:11.133039+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a29803b9-857a-4295-9eff-e8c92a1afc21', 'c286adba-c042-423f-b980-7050b8b52b83', 'b', 'Exhibirán luces de costado en el extremo de popa cuando el buque sea empujado hacia proa, sin que llegue a constituirse una unidad compuesta.', false, '2025-09-13 13:53:11.13317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07a3cb28-d043-4bdd-8878-2bcf8bb18bdc', 'c286adba-c042-423f-b980-7050b8b52b83', 'c', 'Habrán de iluminarse como si fueran buques independientes.', false, '2025-09-13 13:53:11.133301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afe96f5e-fea9-4bf2-8008-c62cb8b25772', 'c286adba-c042-423f-b980-7050b8b52b83', 'd', 'Exhibirán una luz de alcance y en el extremo de popa luces de costado cuando el buque sea remolcado por el costado.', false, '2025-09-13 13:53:11.133433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2815fb24-ab35-4fcd-b9a4-9cc3890df482', '332fc941-210a-4f89-8b50-e19af670fcb2', 'a', 'Mediante el GNSS instalado a bordo, transmitiendo en el canal 70 de ondas hectométricas.', false, '2025-09-13 13:53:11.133711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b06b6e5-53b8-4806-9f0e-3f65952373bc', '332fc941-210a-4f89-8b50-e19af670fcb2', 'b', 'Mediante la llamada selectiva digital, que se transmite en el canal 16 de ondas hectométricas.', false, '2025-09-13 13:53:11.133866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f23e2285-405a-43cd-88d6-609c467989e3', '332fc941-210a-4f89-8b50-e19af670fcb2', 'c', 'Mediante el GNSS instalado a bordo, transmitiendo en el canal 16 de ondas métricas.', false, '2025-09-13 13:53:11.134013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e05d644-eb64-4329-961d-8c4b63fb6f30', '332fc941-210a-4f89-8b50-e19af670fcb2', 'd', 'Mediante la llamada selectiva digital, que se transmite en el canal 70 de ondas métricas.', true, '2025-09-13 13:53:11.134149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c54964a-1257-4c3f-a0a5-40cc2f8f91ed', '73100b13-7f22-4454-aa99-999ea489efde', 'a', 'Toda maniobra que se efectúe para evitar un abordaje será llevada a cabo con la debida antelación y maniobrando a babor.', false, '2025-09-13 13:53:11.134436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('871fd312-6697-4582-b6a1-2abe36c15b4f', '73100b13-7f22-4454-aa99-999ea489efde', 'b', 'Si es necesario, con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad o suprimirá toda su arrancada.', true, '2025-09-13 13:53:11.134575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bbae4a8-63c2-44d9-82d4-a5b89575def9', '73100b13-7f22-4454-aa99-999ea489efde', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el buque esté pasando al otro.', false, '2025-09-13 13:53:11.134839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1e16d7c-cf3f-4ce5-8e01-1e27cd74c150', '73100b13-7f22-4454-aa99-999ea489efde', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán pequeños.', false, '2025-09-13 13:53:11.134974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb8a1de2-03ee-4e28-9b72-a9d29fc89b62', '19ec43af-3cce-4f16-a20e-1a8ac489f19c', 'a', 'Si el buque A es un buque de vela y el B es un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.135273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c2cf27f-0479-4064-9da4-b7078b4a906e', '19ec43af-3cce-4f16-a20e-1a8ac489f19c', 'b', 'Si ambos buques A y B son de propulsión mecánica.', true, '2025-09-13 13:53:11.135413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fba86b89-bcfc-4e2a-b16a-08c24a17185e', '19ec43af-3cce-4f16-a20e-1a8ac489f19c', 'c', 'Si el buque A es un buque dedicado a la pesca y el B es un buque de vela.', false, '2025-09-13 13:53:11.135554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bd5820a-47a9-44de-aad6-baf898f40742', '19ec43af-3cce-4f16-a20e-1a8ac489f19c', 'd', 'Si el buque A es un buque con capacidad de maniobra restringida y el B un buque dedicado a la', false, '2025-09-13 13:53:11.135686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b50fc94-bee7-40a8-bb3e-f7c6301cc30e', '999a68ed-bd4e-480e-bebb-4e20fd3ad420', 'a', 'Se aplica sólo a los buques de propulsión mecánica en cualquier circunstancia de navegación.', false, '2025-09-13 13:53:11.135961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0eb466e9-de9c-476a-ba6d-44583f56bac1', '999a68ed-bd4e-480e-bebb-4e20fd3ad420', 'b', 'Se aplica a los buques de vela dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.136094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae908c93-18f3-4f21-84a5-8fcebcaaf28d', '999a68ed-bd4e-480e-bebb-4e20fd3ad420', 'c', 'Se aplica a todos los buques que estén a la vista el uno del otro.', false, '2025-09-13 13:53:11.136227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8b20393-7f1d-48d0-b6ea-6cdaa3946210', '999a68ed-bd4e-480e-bebb-4e20fd3ad420', 'd', 'Se aplica a los buques de propulsión mecánica sólo cuando no estén a la vista el uno del otro y naveguen cerca.', false, '2025-09-13 13:53:11.136366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97687f06-bb09-4339-8c3c-ba7453ce1313', '3621e94b-54e5-4758-bc8e-765391092e03', 'a', 'Tiene dudas sobre si estamos efectuando la maniobra adecuada para evitar el abordaje.', false, '2025-09-13 13:53:11.136644+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b59cb4cb-1c36-4fc3-b868-0d853389d79f', '3621e94b-54e5-4758-bc8e-765391092e03', 'b', 'Está conforme con la maniobra que estamos ejecutando.', false, '2025-09-13 13:53:11.136788+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22fef73f-332b-4e85-8167-9af947e434f3', '3621e94b-54e5-4758-bc8e-765391092e03', 'c', 'Pretende alcanzarnos por nuestra banda de estribor.', false, '2025-09-13 13:53:11.136926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('936b8e99-f90b-4440-8d6d-4ba659a8348f', '3621e94b-54e5-4758-bc8e-765391092e03', 'd', 'Pretende alcanzarnos por nuestra banda de babor.', true, '2025-09-13 13:53:11.137068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6ad3e99-d5be-4f81-91e2-9d6af5cd0eb6', 'f149f33b-1425-41c6-a7b6-eaf2c8bb838f', 'a', 'Buque de vela.', false, '2025-09-13 13:53:11.137348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e052997f-bf39-4121-871e-d28d39da9db4', 'f149f33b-1425-41c6-a7b6-eaf2c8bb838f', 'b', 'Buque de propulsión mecánica.', true, '2025-09-13 13:53:11.137483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6831c041-74bb-4e8e-a2ba-748d305e293d', 'f149f33b-1425-41c6-a7b6-eaf2c8bb838f', 'c', 'Buque de vela y buque de propulsión mecánica.', false, '2025-09-13 13:53:11.137617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e4d2afb-de7a-410a-b27f-a212eb8cb955', 'f149f33b-1425-41c6-a7b6-eaf2c8bb838f', 'd', 'Embarcaciones en pantanos y embalses. DE TRANSPORTES, MOVILIDAD                                                                                                  Y AGENDA URBANA Y AGENDA URBANA TRANSPORTE Y MOVILIDAD Código de Test 03 Nomenclatura náutica.', false, '2025-09-13 13:53:11.137751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b232d7a3-1678-4331-bbbb-8fb83f6cf1a9', 'ec5fadf5-b2c5-4c9f-bc24-14c2bc058fe3', 'a', 'Los eslabones de la cadena del ancla encajan en el tambor liso, llamado cabirón, que forma parte', false, '2025-09-13 13:53:11.138181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfc248ea-4e44-4e80-8e80-5586b4c6d3a5', 'ec5fadf5-b2c5-4c9f-bc24-14c2bc058fe3', 'b', 'El embrague es el mecanismo del molinete que sirve para separar el barbotén de la rueda lisa que', false, '2025-09-13 13:53:11.138318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03e67bd7-9a07-447f-968e-00700160827f', 'ec5fadf5-b2c5-4c9f-bc24-14c2bc058fe3', 'c', 'El freno tiene como misión el frenado del barbotén con una cinta, incidiendo sobre el eje horizontal del molinete.', true, '2025-09-13 13:53:11.138452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee82d4b0-38ac-4295-b4f8-5f99dc4e96f3', 'ec5fadf5-b2c5-4c9f-bc24-14c2bc058fe3', 'd', 'El molinete sólo se utiliza para levar el ancla, pero nunca para cazar cabos, escotas o drizas.', false, '2025-09-13 13:53:11.138587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bd9298d-98f4-41e3-a9b4-251a2df87320', '21ce739c-aa28-4cd0-90f7-8d38ef4ccc44', 'a', 'El guardín es el aparejo que permite sujetar el timón al codaste.', true, '2025-09-13 13:53:11.138867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df31a016-8b86-4747-8c04-636cead4d60c', '21ce739c-aa28-4cd0-90f7-8d38ef4ccc44', 'b', 'La limera es el tubo dentro del cual gira el eje del timón.', false, '2025-09-13 13:53:11.139003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a273e592-3851-4e72-bd1e-35883f05901a', '21ce739c-aa28-4cd0-90f7-8d38ef4ccc44', 'c', 'El timón es la plancha o pala que se instala en la popa de la embarcación y, girando sobre un eje, sirve para darle dirección.', false, '2025-09-13 13:53:11.139136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b82e5bca-34aa-4fd7-968c-5d9ada011552', '21ce739c-aa28-4cd0-90f7-8d38ef4ccc44', 'd', 'La caña es la palanca unida a la cabeza del timón y con la cual se lo maneja.', false, '2025-09-13 13:53:11.13927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9005edee-aed1-4a50-92cd-c25ab813eb56', 'bfe236b2-a0e5-456c-b654-0f31391d4378', 'a', 'La parte del casco que sobresale de la superficie del agua.', false, '2025-09-13 13:53:11.139552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0ecbb51-b3ee-404a-969a-9e2494d1548e', 'bfe236b2-a0e5-456c-b654-0f31391d4378', 'b', 'La parte del casco bajo la línea de flotación, también denominada carena.', true, '2025-09-13 13:53:11.139822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47c4fb2e-6ed5-4bf7-ae6c-7d5e6d0b375e', 'bfe236b2-a0e5-456c-b654-0f31391d4378', 'c', 'La parte del casco sin incluir la quilla hasta la línea de flotación.', false, '2025-09-13 13:53:11.139958+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af2f2e8e-bb8c-46b0-b093-1834d73c20ee', 'bfe236b2-a0e5-456c-b654-0f31391d4378', 'd', 'Los lados de un casco de proa a popa y desde la línea de flotación hasta la cubierta.', false, '2025-09-13 13:53:11.140093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ffeb366-f47c-45c9-a20b-0d71e82b0960', 'e62a6394-1a49-41fb-91dc-1f40de65268d', 'a', 'La escora es la inclinación de un barco con respecto a la vertical sobre uno de sus costados.', false, '2025-09-13 13:53:11.140364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('547c18aa-0e8f-46c8-af1b-10bed848d579', 'e62a6394-1a49-41fb-91dc-1f40de65268d', 'b', 'La capacidad de maniobra varía al escorar la embarcación.', false, '2025-09-13 13:53:11.140496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bf237f6-75c2-40a8-a2bf-2ae986b576ba', 'e62a6394-1a49-41fb-91dc-1f40de65268d', 'c', 'Debido a la acción del viento el buque escorará hacia barlovento.', true, '2025-09-13 13:53:11.140629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3357c99-e89e-4de2-8e77-57ca29a50c75', 'e62a6394-1a49-41fb-91dc-1f40de65268d', 'd', 'La escora se produce por la acción del viento, oleaje o por un desplazamiento de pesos. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.140768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4caa43ed-c291-4aa9-b726-3a9fff8b42d9', '0aa61520-b0c3-402b-a95b-03874377cee0', 'a', 'Noray.', false, '2025-09-13 13:53:11.141064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cee60970-54af-4d3a-af66-2583e6cbbbc2', '0aa61520-b0c3-402b-a95b-03874377cee0', 'b', 'Bita.', false, '2025-09-13 13:53:11.141196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b081088e-0650-4c87-b3fd-eaa9ccfc5dc1', '0aa61520-b0c3-402b-a95b-03874377cee0', 'c', 'Cornamusa.', true, '2025-09-13 13:53:11.141326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1eb0ad40-6abf-455f-8a71-43001bd06c14', '0aa61520-b0c3-402b-a95b-03874377cee0', 'd', 'Muerto.', false, '2025-09-13 13:53:11.141458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2513175d-949a-4ba1-9864-7d690f1847b1', 'b41dd823-de48-4bd8-be81-df06fe65ff41', 'a', 'Proteger el casco de la embarcación del roce contra el muelle.', false, '2025-09-13 13:53:11.141754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0748a6c9-ed43-4b21-9d03-d472cd26d457', 'b41dd823-de48-4bd8-be81-df06fe65ff41', 'b', 'Señalizar el lugar en donde está el ancla y facilitar la labor de recuperación de ésta.', true, '2025-09-13 13:53:11.141941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5216c223-507b-485d-9ea7-704db8295b53', 'b41dd823-de48-4bd8-be81-df06fe65ff41', 'c', 'Señalizar un peligro a la navegación.', false, '2025-09-13 13:53:11.142193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab7c5dd0-9e29-4989-87b5-71c35752a382', 'b41dd823-de48-4bd8-be81-df06fe65ff41', 'd', 'Medir la profundidad y conocer el tipo de fondo.', false, '2025-09-13 13:53:11.142343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6eb024f2-65ab-4627-a9b0-41c6c5a44623', 'c1b36d59-a4e6-4133-815b-82ab277e245b', 'a', 'Correr el temporal.', false, '2025-09-13 13:53:11.142627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a07d834-84ed-43c9-b50e-5abc2088d0a3', 'c1b36d59-a4e6-4133-815b-82ab277e245b', 'b', 'Navegar “a son de mar”.', false, '2025-09-13 13:53:11.142771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f94d2337-f7d1-4d2e-ac28-cca05e47bc09', 'c1b36d59-a4e6-4133-815b-82ab277e245b', 'c', 'Capear el temporal.', true, '2025-09-13 13:53:11.14292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79bbb43e-395a-4136-bf6a-5fbe68bd8626', 'c1b36d59-a4e6-4133-815b-82ab277e245b', 'd', 'Trimar el temporal.', false, '2025-09-13 13:53:11.143088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dee9c5e8-f2fa-4e66-a31c-b83a04ff612c', 'f23c4994-d4e4-4bf7-b44b-daa97d48dd43', 'a', 'La resistencia a la propulsión disminuye.', false, '2025-09-13 13:53:11.143396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe841020-0849-48ec-b670-3fe21af2d837', 'f23c4994-d4e4-4bf7-b44b-daa97d48dd43', 'b', 'La maniobrabilidad de la embarcación disminuye.', true, '2025-09-13 13:53:11.143537+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4d75d23-777c-41b5-95fa-5be6abeb77e5', 'f23c4994-d4e4-4bf7-b44b-daa97d48dd43', 'c', 'La velocidad de la embarcación aumenta.', false, '2025-09-13 13:53:11.143678+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38879cc4-07c6-485c-9ce0-3f041a4a153c', 'f23c4994-d4e4-4bf7-b44b-daa97d48dd43', 'd', 'La medida de la sonda aumenta.', false, '2025-09-13 13:53:11.143825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0090fb76-1f55-47b9-9c7a-028e4bcf8b5d', '6b8dbdbf-34f5-4a3e-8f0b-19a831235c82', 'a', 'Su posición de equilibrio adrizado.', true, '2025-09-13 13:53:11.144253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e866e299-7557-465f-b40d-157184403716', '6b8dbdbf-34f5-4a3e-8f0b-19a831235c82', 'b', 'Su flotabilidad bajo la acción de olas transversales.', false, '2025-09-13 13:53:11.144387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c52adcaf-d8a1-4236-ba18-8f6fb2f530cc', '6b8dbdbf-34f5-4a3e-8f0b-19a831235c82', 'c', 'Su balance.', false, '2025-09-13 13:53:11.144524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4db93eb9-eeea-42cb-8d36-fa9fb6303885', '6b8dbdbf-34f5-4a3e-8f0b-19a831235c82', 'd', 'Su posición de asiento en equilibrio.', false, '2025-09-13 13:53:11.144653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08c95d47-cbc1-4124-83d9-e4a70eacd15e', '86a6681d-e38b-4a52-a526-5a1a4233adcd', 'a', 'En el momento en que la proa haya caído 70º, meter el timón a la banda contraria por la que haya caído el naufrago hasta navegar a un rumbo opuesto al inicio de la maniobra.', true, '2025-09-13 13:53:11.144925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b5370c1-dd0b-4224-bd14-9a7b93892331', '86a6681d-e38b-4a52-a526-5a1a4233adcd', 'b', 'En el momento en que la proa haya caído 70º, meter el timón a la banda por donde haya caído el naufrago hasta navegar a un rumbo opuesto al inicio de la maniobra.', false, '2025-09-13 13:53:11.145058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8f522c8-02f8-47df-8d22-61f87158abe1', '86a6681d-e38b-4a52-a526-5a1a4233adcd', 'c', 'Meter el timón a la banda de caída del náufrago hasta que la proa haya caído 250°, en cuyo momento se pone el timón al medio y se para la máquina. El barco seguirá cayendo por inercia hasta lograr los 270°.', false, '2025-09-13 13:53:11.145187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0646d7d-050c-4c9d-9139-ab75bf62ce62', '86a6681d-e38b-4a52-a526-5a1a4233adcd', 'd', 'Meter el timón a la banda de caída más rápida hasta lograr 250° con respecto al rumbo primitivo, en cuyo momento se mete el timón a la banda opuesta hasta que falten 20° para estar al rumbo opuesto a la inicial; se deja el timón al medio y se para la máquina hasta alcanzar el rumbo opuesto.', false, '2025-09-13 13:53:11.145317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1804cea5-1ffe-4523-8ec0-bb799d6c135c', '487401c8-16a8-4588-bb84-148dca073ab5', 'a', 'Áreas del territorio nacional y del medio marino mediterráneo, junto con la zona económica exclusiva y la plataforma continental, más adecuados en número y en superficie para la conservación de las especies de aves incluidas en él.', false, '2025-09-13 13:53:11.145587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c22eecf-a9c8-43d4-be6f-95fad433a23f', '487401c8-16a8-4588-bb84-148dca073ab5', 'b', 'Áreas que por sus especiales características se consideren adecuadas para la regeneración de los recursos pesqueros, contribuyendo a la preservación de la riqueza natural de determinadas zonas, la conservación de las diferentes especies marinas o la recuperación de los ecosistemas en el', false, '2025-09-13 13:53:11.145718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cf29d59-e1ec-46a2-9247-69628b9c0f77', '487401c8-16a8-4588-bb84-148dca073ab5', 'c', 'Áreas naturales mediterráneas, que, en razón a la belleza de sus paisajes, la representatividad de sus ecosistemas o la singularidad de su flora, de su fauna o de su diversidad geológica, incluidas sus formaciones geomorfológicas, posean unos valores ecológicos, estéticos, educativos y científicos cuya conservación merece una atención preferente.', false, '2025-09-13 13:53:11.145861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc7d154d-b5b2-41b3-a371-d5665d06e1bf', '4ecf282b-75a8-463a-9dcf-ab5a761272a4', 'b', 'Mediante la llamada selectiva digital, que se transmite en el canal 16 de ondas hectométricas.', false, '2025-09-13 13:53:11.155079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aab0b9f4-f3a7-496c-bfee-e91e1d07915b', '487401c8-16a8-4588-bb84-148dca073ab5', 'd', 'Áreas que, por albergar ecosistemas específicos de la zona mediterránea o hábitats de especies en peligro, sean importantes para la conservación de los componentes de la diversidad biológica en el Mediterráneo y tienen un interés científico, estético, cultural o educativo especial.', true, '2025-09-13 13:53:11.145999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce52887b-4690-4304-865b-f9a940c61507', '42b9fe7e-5d61-4e52-9dd2-30aff8d98c59', 'a', 'Se podrá descargar en el mar materia plástica, siempre que no se trate en ningún caso de la cabuyería y redes de pesca de fibras sintéticas, las bolsas de plástico para la basura y las cenizas de incinerador de productos de plástico, sin que esta enumeración sea exhaustiva.', false, '2025-09-13 13:53:11.146281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5774f916-78f9-41ee-93d0-577167fb670c', '42b9fe7e-5d61-4e52-9dd2-30aff8d98c59', 'b', 'Se prohíbe descargar en el mar toda materia plástica, salvo cuando ello sea necesario para proteger la seguridad del buque y de las personas a bordo o para salvar vidas en el mar.', true, '2025-09-13 13:53:11.146415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98b4ec39-608c-48c2-a500-ec6abf1abd91', '42b9fe7e-5d61-4e52-9dd2-30aff8d98c59', 'c', 'Se prohíbe descargar en el mar toda materia plástica sin excepción alguna, incluidas, sin que la enumeración sea exhaustiva, la cabuyería y redes de pesca de fibras sintéticas, las bolsas de plástico para la basura y las cenizas de incinerador de productos de plástico.', false, '2025-09-13 13:53:11.146545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e5855fb-9ef1-4457-8238-01a6e77df30f', '42b9fe7e-5d61-4e52-9dd2-30aff8d98c59', 'd', 'Se podrá descargar en el mar materia plástica, salvo las bolsas de plástico para la basura, a no ser que quede claro que mantener dichos desechos a bordo representa un riesgo inminente para la salud de las personas a bordo.', false, '2025-09-13 13:53:11.146677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc296ece-688f-40cd-83a5-2476e2515477', 'af652bfe-1253-45a1-9495-7caa75773cd3', 'a', 'Marcas para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.146945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02047942-35c5-4578-b420-e858d5baf23f', 'af652bfe-1253-45a1-9495-7caa75773cd3', 'b', 'Marcas que indican los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:11.147078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('876d51a3-1e65-4b28-9406-ab2e5c86f456', 'af652bfe-1253-45a1-9495-7caa75773cd3', 'c', 'Marcas que, asociadas al compás del buque, indican al navegante dónde están las aguas', false, '2025-09-13 13:53:11.147206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3a37395-8cf3-41d9-9873-9a110ff731c0', 'af652bfe-1253-45a1-9495-7caa75773cd3', 'd', 'Marcas que definen los ejes de los canales.', true, '2025-09-13 13:53:11.147334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b444c07d-2c95-4b9c-a935-8d97fce38302', '99f0f455-09a4-4463-bff9-d139e8525e30', 'a', 'Canal principal a estribor.', false, '2025-09-13 13:53:11.1476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9481274a-59df-4cea-ad65-4c0e31d1e4b9', '99f0f455-09a4-4463-bff9-d139e8525e30', 'b', 'Canal principal a babor.', true, '2025-09-13 13:53:11.147731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3ce573c-c8bd-48b0-a7ed-30e946d42292', '99f0f455-09a4-4463-bff9-d139e8525e30', 'c', 'Marca cardinal Este.', false, '2025-09-13 13:53:11.147873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('769ff953-7911-4077-ba12-76db4c2cbf75', '99f0f455-09a4-4463-bff9-d139e8525e30', 'd', 'Marca de aguas navegables.', false, '2025-09-13 13:53:11.148028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('934fede0-8003-421f-9d02-edff29eb034d', 'dfce3feb-a876-4178-9d29-7a8f3d41db83', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.148333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d921c0ad-9519-476c-994b-cdc7c0023c00', 'dfce3feb-a876-4178-9d29-7a8f3d41db83', 'b', 'Aguas Navegables.', false, '2025-09-13 13:53:11.148487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2311fb67-ecf2-48ea-89db-acfcbe0c4167', 'dfce3feb-a876-4178-9d29-7a8f3d41db83', 'c', 'Especial.', false, '2025-09-13 13:53:11.148627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e66a79b-1258-480e-a0c5-46c44e14eb34', 'dfce3feb-a876-4178-9d29-7a8f3d41db83', 'd', 'Peligro nuevo.', false, '2025-09-13 13:53:11.148896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2e6f096-6e4a-4186-ae5f-c64b0b866a2f', '4e412669-c616-4c93-8fe9-d02509049d97', 'a', 'En el cuadrante Norte.', false, '2025-09-13 13:53:11.149185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b59c614-deab-49c1-93d0-326021df5a20', '4e412669-c616-4c93-8fe9-d02509049d97', 'b', 'En el cuadrante Oeste.', true, '2025-09-13 13:53:11.14932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('193393a7-63cc-4e27-8965-b1f17440f13c', '4e412669-c616-4c93-8fe9-d02509049d97', 'c', 'En el cuadrante Este.', false, '2025-09-13 13:53:11.149474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d793d1d4-6f29-41e0-ab5a-3ea94dcfb2cc', '4e412669-c616-4c93-8fe9-d02509049d97', 'd', 'En el cuadrante Sur.', false, '2025-09-13 13:53:11.149607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48f04d67-cd30-4846-aaa3-75ae0aeb1c59', 'df11590a-e00b-4280-af0d-0e497dcefee4', 'a', 'Un aspa amarilla, en forma de X.', true, '2025-09-13 13:53:11.149892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46ca51fb-f919-43a2-93d3-1445dd55466e', 'df11590a-e00b-4280-af0d-0e497dcefee4', 'b', 'Un aspa con franjas negras sobre amarillas, en forma de +.', false, '2025-09-13 13:53:11.150032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00c5f1ad-99d7-4aae-9836-1d7f724b09d1', 'df11590a-e00b-4280-af0d-0e497dcefee4', 'c', 'Un aspa amarilla, en forma esférica.', false, '2025-09-13 13:53:11.150179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02f36332-a8d2-44c2-a2d3-0742f811b9f4', 'df11590a-e00b-4280-af0d-0e497dcefee4', 'd', 'Un aspa con franjas negras sobre amarillas, en forma de castillete o espeque. Reglamento (RIPA).', false, '2025-09-13 13:53:11.150316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fe25189-f17a-4807-8980-9180b1aa38c7', '17e3ce6e-db2b-4186-8a5c-0f9a602fd5c0', 'a', 'Toda maniobra que se efectúe para evitar un abordaje será llevada a cabo con la debida antelación y maniobrando a babor.', false, '2025-09-13 13:53:11.150596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1e394da-226f-4386-88e6-e73244b4a714', '17e3ce6e-db2b-4186-8a5c-0f9a602fd5c0', 'b', 'Si es necesario, con objeto de evitar el abordaje o de disponer de más tiempo para estudiar la situación, el buque reducirá su velocidad o suprimirá toda su arrancada.', true, '2025-09-13 13:53:11.15073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25beb359-e752-4aa4-a4d9-293cf7dc6477', '17e3ce6e-db2b-4186-8a5c-0f9a602fd5c0', 'c', 'La eficacia de la maniobra se deberá ir comprobando hasta el momento en que el buque esté pasando al otro.', false, '2025-09-13 13:53:11.150869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80b08ed7-67b2-4eae-8a16-97ce9e2a1a9d', '17e3ce6e-db2b-4186-8a5c-0f9a602fd5c0', 'd', 'Si las circunstancias del caso lo permiten, los cambios de rumbo y/o velocidad que se efectúen para evitar un abordaje serán pequeños.', false, '2025-09-13 13:53:11.151013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('459d0ea1-f601-40ff-9f0f-c3e8cc7843b7', '1f4b3fa3-495e-4472-9c8b-8f25bb538eee', 'a', 'Habrán de iluminarse como si fueran un solo buque.', true, '2025-09-13 13:53:11.151299+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f0f8c61-078b-40cb-b853-4d4f08971521', '1f4b3fa3-495e-4472-9c8b-8f25bb538eee', 'b', 'Exhibirán luces de costado en el extremo de popa cuando el buque sea empujado hacia proa, sin que llegue a constituirse una unidad compuesta.', false, '2025-09-13 13:53:11.151434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c41a10b3-126a-45f0-a484-2db677d9a184', '1f4b3fa3-495e-4472-9c8b-8f25bb538eee', 'c', 'Habrán de iluminarse como si fueran buques independientes.', false, '2025-09-13 13:53:11.151582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d828d5a-33cc-4dfa-9e17-d945af4eef0d', '1f4b3fa3-495e-4472-9c8b-8f25bb538eee', 'd', 'Exhibirán una luz de alcance y en el extremo de popa luces de costado cuando el buque sea remolcado por el costado.', false, '2025-09-13 13:53:11.151743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96e8003a-78d3-4c55-8247-eea4ea7626f5', '142a066c-bbae-4f34-a500-85a84c45c54a', 'a', 'Se aplica sólo a los buques de propulsión mecánica en cualquier circunstancia de navegación.', false, '2025-09-13 13:53:11.152065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a2de852-e1c9-45b4-97a8-67e3447db26c', '142a066c-bbae-4f34-a500-85a84c45c54a', 'b', 'Se aplica a los buques de vela dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.152201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e53259b0-a26c-419c-954d-6eb4e48c1548', '142a066c-bbae-4f34-a500-85a84c45c54a', 'c', 'Se aplica a todos los buques que estén a la vista el uno del otro.', false, '2025-09-13 13:53:11.15233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef1825a4-5bb6-4dde-8244-9937e3b05807', '142a066c-bbae-4f34-a500-85a84c45c54a', 'd', 'Se aplica a los buques de propulsión mecánica sólo cuando no estén a la vista el uno del otro y naveguen cerca.', false, '2025-09-13 13:53:11.152458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59f94c2b-9e67-4075-81fb-f96275773cca', 'cee01fc0-40a2-44a1-9101-948ef6c26ab2', 'a', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de costado de dicho buque.', false, '2025-09-13 13:53:11.152872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1ee8420-009a-426a-9f1f-c464f85e252a', 'cee01fc0-40a2-44a1-9101-948ef6c26ab2', 'b', 'Se encontrará en una posición tal respecto del buque alcanzado, que de noche sólo le será posible ver la luz de alcance y una luz de costado de dicho buque.', false, '2025-09-13 13:53:11.153014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5d35660-9c29-435e-8975-5f2a1202ca5f', 'cee01fc0-40a2-44a1-9101-948ef6c26ab2', 'c', 'Si abriga dudas de si lo está alcanzando, se considerará que no lo está haciendo.', false, '2025-09-13 13:53:11.153146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11708d55-06cb-403e-8830-cccd740cfd5f', 'cee01fc0-40a2-44a1-9101-948ef6c26ab2', 'd', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:11.153274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fc2fe1c-aea3-491e-989a-5658257fa757', 'e1efe235-0815-424d-a31d-3f6d96985400', 'a', 'Si el buque A es un buque de vela y el B es un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.153561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('579d3112-0a49-4879-a97e-b4247b79221d', 'e1efe235-0815-424d-a31d-3f6d96985400', 'b', 'Si ambos buques A y B son de propulsión mecánica.', true, '2025-09-13 13:53:11.153712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2b36999-7b48-4d45-8790-930240573eaf', 'e1efe235-0815-424d-a31d-3f6d96985400', 'c', 'Si el buque A es un buque dedicado a la pesca y el B es un buque de vela.', false, '2025-09-13 13:53:11.153868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbc99e4f-fa56-4a49-9ff3-4c99571ce860', 'e1efe235-0815-424d-a31d-3f6d96985400', 'd', 'Si el buque A es un buque con capacidad de maniobra restringida y el B un buque dedicado a la', false, '2025-09-13 13:53:11.154005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7471be03-f880-441b-9857-b45ce8f3c5cc', 'dbff6494-81a3-47da-ad8a-d4f1865c5f9d', 'a', 'A popa, cuando tengan menos de 30 metros de eslora.', false, '2025-09-13 13:53:11.154287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55d2ce3f-4ab4-4eda-9c1b-3cb0c6b2e5c5', 'dbff6494-81a3-47da-ad8a-d4f1865c5f9d', 'b', 'A popa, cuando tengan al menos 50 metros de eslora.', true, '2025-09-13 13:53:11.154419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('673b3644-f19e-4c93-bc09-f445bc4fbded', 'dbff6494-81a3-47da-ad8a-d4f1865c5f9d', 'c', 'A proa y más alta que la de popa.', false, '2025-09-13 13:53:11.15455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('081a7432-c9b1-46fa-8bfb-a157e20a8924', 'dbff6494-81a3-47da-ad8a-d4f1865c5f9d', 'd', 'A popa y más baja que la de proa.', false, '2025-09-13 13:53:11.154682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e679616-9720-425d-9d47-e4469be3d618', '4ecf282b-75a8-463a-9dcf-ab5a761272a4', 'a', 'Mediante el GNSS instalado a bordo, transmitiendo en el canal 70 de ondas hectométricas.', false, '2025-09-13 13:53:11.154951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d28f913-810d-4cbb-be40-bd2d46334e3d', '308c5e98-e103-4a87-89a6-7dc04a17ed55', 'a', 'Rc= 162º; Ihc= 2,5 nudos.', false, '2025-09-13 13:53:11.415444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2318146a-1b56-4447-bf36-7fa958c75ea9', '4ecf282b-75a8-463a-9dcf-ab5a761272a4', 'c', 'Mediante el GNSS instalado a bordo, transmitiendo en el canal 16 de ondas métricas.', false, '2025-09-13 13:53:11.155211+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c905b04-0308-4648-927c-16608097decf', '4ecf282b-75a8-463a-9dcf-ab5a761272a4', 'd', 'Mediante la llamada selectiva digital, que se transmite en el canal 70 de ondas métricas.', true, '2025-09-13 13:53:11.155345+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f6c32b4-8320-429d-874f-ce968e31bd9d', '3b5c08b4-edb7-4c21-a95e-857853648390', 'a', 'Tiene dudas sobre si estamos efectuando la maniobra adecuada para evitar el abordaje.', false, '2025-09-13 13:53:11.155614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7123f90-da8e-456b-8491-ad69f5f66fe3', '3b5c08b4-edb7-4c21-a95e-857853648390', 'b', 'Está conforme con la maniobra que estamos ejecutando.', false, '2025-09-13 13:53:11.155745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c389058e-6cad-42ce-b91d-02e79f83a754', '3b5c08b4-edb7-4c21-a95e-857853648390', 'c', 'Pretende alcanzarnos por nuestra banda de estribor.', false, '2025-09-13 13:53:11.15592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfaaafa4-e743-41d1-aefa-e0a2a144327d', '3b5c08b4-edb7-4c21-a95e-857853648390', 'd', 'Pretende alcanzarnos por nuestra banda de babor.', true, '2025-09-13 13:53:11.156062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('310aee2b-e00c-4501-8e98-4f2b6579d0c9', '19573935-0d91-459d-be87-7e3f246fe300', 'a', 'Buque de vela.', false, '2025-09-13 13:53:11.156343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8d16503-b9a3-46ab-9e36-65d794ebd6e3', '19573935-0d91-459d-be87-7e3f246fe300', 'b', 'Buque de propulsión mecánica.', true, '2025-09-13 13:53:11.156472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aeaf6968-f53f-43e5-b27d-8ca7fb8e51c5', '19573935-0d91-459d-be87-7e3f246fe300', 'c', 'Buque de vela y buque de propulsión mecánica.', false, '2025-09-13 13:53:11.156601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5c6539d-1c2c-47b8-8387-79291eb6498b', '19573935-0d91-459d-be87-7e3f246fe300', 'd', 'Embarcaciones en pantanos y embalses.', false, '2025-09-13 13:53:11.156731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f691f14-6529-4a9f-baed-05ceb27de04e', '183fd083-0d6f-4080-9d1c-58080440529e', 'a', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca o de cualquier otra', false, '2025-09-13 13:53:11.157009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccf6be95-fccc-4fd1-8dd9-c2ce3095a023', '183fd083-0d6f-4080-9d1c-58080440529e', 'b', 'La maniobrabilidad del buque, teniendo muy en cuenta la distancia de parada y la capacidad de giro en las condiciones del momento.', false, '2025-09-13 13:53:11.157144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('280f265e-b76b-44e5-82ee-26880cfcb740', '183fd083-0d6f-4080-9d1c-58080440529e', 'c', 'El estado de visibilidad.', false, '2025-09-13 13:53:11.157276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae9ba1b6-9f7c-465e-b81f-b54f9160c5d8', '183fd083-0d6f-4080-9d1c-58080440529e', 'd', 'La potencia del motor.', true, '2025-09-13 13:53:11.15741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf647a66-2d74-4157-b402-d87a6eb4bafe', '5b6fd001-539c-46b6-b2b3-3b04fd2ad64a', 'a', 'Virar es dar vueltas al cabrestante para levar el ancla.', false, '2025-09-13 13:53:11.157959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2667162-c155-4ddd-ad7f-2b7f7dabe515', '5b6fd001-539c-46b6-b2b3-3b04fd2ad64a', 'b', 'Filar es arriar progresivamente un cabo o cadena que está trabajando.', true, '2025-09-13 13:53:11.158093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('082ea83b-000e-41be-8ec0-4b5aece23242', '5b6fd001-539c-46b6-b2b3-3b04fd2ad64a', 'c', 'Levar es recoger, arrancar y suspender el ancla que está fondeada.', false, '2025-09-13 13:53:11.158229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f4e92b8-ea95-45ff-aaad-09a9fd7b8cc1', '5b6fd001-539c-46b6-b2b3-3b04fd2ad64a', 'd', 'Zarpar es salir un barco del lugar en que estaba atracado.', false, '2025-09-13 13:53:11.158361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a178864c-c95f-40d5-a275-65523dcd9e86', 'd3c56fae-4f29-47e9-b4e2-60ecb36b8102', 'a', 'La hélice es el conjunto de palas que giran alrededor de un eje y empujan el fluido ambiente produciendo en él una fuerza de reacción que se utiliza principalmente para la propulsión de barcos', false, '2025-09-13 13:53:11.158644+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fde3ec2b-f2a3-4197-8aba-9312f1d6f11d', 'd3c56fae-4f29-47e9-b4e2-60ecb36b8102', 'b', 'La bocina es el orificio que permite que el eje de la hélice gire a través del casco y entre agua para su refrigeración.', false, '2025-09-13 13:53:11.158789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32b76e0a-6508-405a-b25c-38ef6931931f', 'd3c56fae-4f29-47e9-b4e2-60ecb36b8102', 'c', 'El capacete es la pieza esférica que cierra el núcleo de la hélice.', false, '2025-09-13 13:53:11.158924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2abae8f7-61f5-4ad9-ba02-52654822d74a', 'd3c56fae-4f29-47e9-b4e2-60ecb36b8102', 'd', 'Las palas son placas planas en las que se provoca una diferencia de velocidades del fluido entre una cara y la otra de la hélice.', true, '2025-09-13 13:53:11.159058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('831bb1e8-ee1d-47b7-b327-b0aca917cc49', 'd5d10ff8-e998-45b7-9275-43fd5812f12c', 'a', 'La quilla es la pieza, que va de popa a proa por la parte inferior del barco y en que se asienta todo', false, '2025-09-13 13:53:11.159327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c92af584-47f7-4fc5-bbc6-2dc970d0bbfa', 'd5d10ff8-e998-45b7-9275-43fd5812f12c', 'b', 'La roda es la pieza gruesa y curva, que forma la proa de la embarcación.', false, '2025-09-13 13:53:11.159454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b3100bb-e3b5-42df-abc7-c42ceda115ad', 'd5d10ff8-e998-45b7-9275-43fd5812f12c', 'c', 'El codaste es la pieza gruesa dispuesta verticalmente sobre el extremo de la quilla inmediato a la popa, que sirve de fundamento a toda la armazón de esta parte del buque.', true, '2025-09-13 13:53:11.159586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f1187a6-cb5a-41d2-af3e-3ea5d227f676', 'd5d10ff8-e998-45b7-9275-43fd5812f12c', 'd', 'Los baos son cada una de las piezas curvas cuya base o parte inferior encaja en la quilla del buque y desde allí arrancan a babor y estribor, en dos ramas simétricas, formando las “costillas” del', false, '2025-09-13 13:53:11.159716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b04bf4e-8f25-4db5-a938-ca07bc7ffb28', '2c7a881c-a465-4091-9dcb-8812bc4be16f', 'a', 'Escorar es desviarse una embarcación de su rumbo por el impulso del viento o de una corriente.', false, '2025-09-13 13:53:11.16003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fd36c0a-8efe-471c-9696-478f7048fe63', '2c7a881c-a465-4091-9dcb-8812bc4be16f', 'b', 'Adrizar es poner derecha o vertical una embarcación que estaba inclinada.', false, '2025-09-13 13:53:11.160164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d55a96e-aabe-4026-b07f-2201ae1597ff', '2c7a881c-a465-4091-9dcb-8812bc4be16f', 'c', 'Barlovento es la parte opuesta a aquella de donde viene el viento con respecto a un punto o lugar', true, '2025-09-13 13:53:11.160294+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92e95456-58ef-4f73-ad1b-9e59bd0cc4e8', '2c7a881c-a465-4091-9dcb-8812bc4be16f', 'd', 'Sotavento es la parte de donde viene el viento, con respecto a un punto o lugar determinado. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.160432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28dc70c1-88bc-428c-b9ca-f2df0c55a685', 'b5783da4-96cb-4bc5-9600-4e90ad75f187', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del', false, '2025-09-13 13:53:11.16071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51bae041-4ba7-402f-b987-4ef1f4f0d700', 'b5783da4-96cb-4bc5-9600-4e90ad75f187', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no ha garreado, y vigilar la sonda marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:11.160851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7213064-6669-4778-bb63-562691e372d8', 'b5783da4-96cb-4bc5-9600-4e90ad75f187', 'c', 'La embarcación debe disponer de una línea de fondeo cuya longitud será tres veces su eslora.', false, '2025-09-13 13:53:11.160981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('abe35c14-855d-42a0-a423-c491f056b2ac', 'b5783da4-96cb-4bc5-9600-4e90ad75f187', 'd', 'Si optamos por el fondeo a la gira, utilizaremos dos anclas de forma que las líneas de fondeo formen un ángulo de entre 90º y 120º.', true, '2025-09-13 13:53:11.161113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6644fe1e-0264-469f-be82-348ebec37903', 'c15657c2-04b0-47b9-89d5-3f9c90a40cff', 'a', 'Firme.', true, '2025-09-13 13:53:11.161404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d56ed39-5afd-4ac9-91d4-6f00449fe299', 'c15657c2-04b0-47b9-89d5-3f9c90a40cff', 'b', 'Chicote.', false, '2025-09-13 13:53:11.161532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bc8dd27-c5e3-4409-a872-b453ba85c82c', 'c15657c2-04b0-47b9-89d5-3f9c90a40cff', 'c', 'Gaza.', false, '2025-09-13 13:53:11.161658+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e23fb455-3d2a-4573-a105-ad593fa199be', 'c15657c2-04b0-47b9-89d5-3f9c90a40cff', 'd', 'Seno.', false, '2025-09-13 13:53:11.161787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69697b9c-b4fa-4e08-bfb1-9ce07d75b70d', '91a269b7-a37a-420d-876b-f03a95b13d6b', 'a', 'Existe una mayor maniobrabilidad al aumentar la sonda.', false, '2025-09-13 13:53:11.162064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c39fb219-b56e-4f5e-b33d-697f9f71f237', '91a269b7-a37a-420d-876b-f03a95b13d6b', 'b', 'Navegaremos con mayor seguridad llevando la mar por la amura.', false, '2025-09-13 13:53:11.162196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b22141b9-8b24-4e16-9de4-afa7e9cc4d77', '91a269b7-a37a-420d-876b-f03a95b13d6b', 'c', 'Navegaremos con mayor seguridad aumentando la velocidad.', false, '2025-09-13 13:53:11.162335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac9eafb8-628a-47fd-8bfc-b38598fc1bc7', '91a269b7-a37a-420d-876b-f03a95b13d6b', 'd', 'La maniobrabilidad no se ve afectada.', true, '2025-09-13 13:53:11.162465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be6c8b05-7747-4c89-937c-63fe14e38b37', '5ca3af2a-9104-4506-8870-53fd20ea4a9c', 'a', 'Por vía telefónica llamando al 900 222 222.', false, '2025-09-13 13:53:11.162886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c7be607-b50e-4f71-a6d6-d728d5386cf2', '5ca3af2a-9104-4506-8870-53fd20ea4a9c', 'b', 'Únicamente por vía telefónica llamando al 900 202 202 o al 112.', true, '2025-09-13 13:53:11.163025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('351111ac-2832-44f9-8840-c5e1493671fd', '5ca3af2a-9104-4506-8870-53fd20ea4a9c', 'c', 'Exclusivamente con el uso de la estación de radio a bordo.', false, '2025-09-13 13:53:11.163153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d62852c-412c-4b11-8ae3-2c48a1f9ac8e', '5ca3af2a-9104-4506-8870-53fd20ea4a9c', 'd', 'Por vía telefónica o con el uso de la estación de radio a bordo.', false, '2025-09-13 13:53:11.163282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03a6119f-ba9c-447f-86d6-1a59b24bd375', 'cd164726-c1d9-4269-8dfc-2d3e07e4021e', 'a', 'Cuando la frecuencia del movimiento de balance es alta.', false, '2025-09-13 13:53:11.163555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('468702b5-751f-4d96-b93d-24665b02af47', 'cd164726-c1d9-4269-8dfc-2d3e07e4021e', 'b', 'Cuando la frecuencia del movimiento de balance es baja o casi nula.', false, '2025-09-13 13:53:11.163686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9cd4dcb1-ea31-40ca-aca3-1cda7c4f424d', 'cd164726-c1d9-4269-8dfc-2d3e07e4021e', 'c', 'Cuando la frecuencia del movimiento de cabezada es alta.', false, '2025-09-13 13:53:11.163821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bbfe015-9b36-4ca6-b6c8-8e1d3a96f6e5', 'cd164726-c1d9-4269-8dfc-2d3e07e4021e', 'd', 'Cuando la frecuencia del movimiento de cabezada es baja o casi nula.', true, '2025-09-13 13:53:11.163949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a38f68cf-64d3-46ca-b7dc-d6c5944010b9', '730d0cd1-5992-4288-9bbc-19f37ab87679', 'a', '50 N.', false, '2025-09-13 13:53:11.164254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('277ea988-ae1b-4979-9afc-e98d5e293880', '730d0cd1-5992-4288-9bbc-19f37ab87679', 'b', '100 N.', false, '2025-09-13 13:53:11.164395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54062d32-30a8-4051-b094-98f9cedf7a68', '730d0cd1-5992-4288-9bbc-19f37ab87679', 'c', '150 N.', true, '2025-09-13 13:53:11.164535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55aedb32-7a5a-4c73-b068-acc329142e83', '730d0cd1-5992-4288-9bbc-19f37ab87679', 'd', '275 N.', false, '2025-09-13 13:53:11.16467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0911c61c-584c-4392-838f-b1a37a8308e3', '49ebe7c6-36f6-4a2d-b7fe-510fc048e4db', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', true, '2025-09-13 13:53:11.174136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c82991a1-5500-4ded-ad7d-255ec6111719', 'a12cb504-ddb5-4101-a45e-da08da8e8e26', 'a', 'Entre las medidas legales adoptadas se establecen limitaciones al fondeo de embarcaciones para evitar que malas técnicas de fondeo arrastren y barran el fondo marino arrancando matas, deteriorando las praderas de posidonia.', false, '2025-09-13 13:53:11.164956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('899fde3d-9789-4d8c-bc17-ae6fbb56a866', 'a12cb504-ddb5-4101-a45e-da08da8e8e26', 'b', 'La única medida adoptada en España es cartografiar y catalogar las praderas e insertar esos datos en sistemas de información accesibles a los navegantes y al público en general y, en la medida de lo posible, en las cartas náuticas.', true, '2025-09-13 13:53:11.165097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c29e80b-b439-47eb-893e-3050c6f8b97e', 'a12cb504-ddb5-4101-a45e-da08da8e8e26', 'c', 'Todavía no existe normativa concreta, sólo recomendaciones de las consejerías de pesca y medio ambiente de las diferentes comunidades autónomas sobre cómo actuar allí donde se localizan las praderas de posidonia.', false, '2025-09-13 13:53:11.165227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d29dd12-3950-464d-aa34-ac8ca666dd27', 'a12cb504-ddb5-4101-a45e-da08da8e8e26', 'd', 'No hay normativa específica ni limitación alguna para fondear sobre praderas de posidonia, pero un navegante responsable con el medio ambiente, antes de fondear, debería observar el fondo marino por su propia cuenta para procurar no dañar la posidonia.', false, '2025-09-13 13:53:11.165358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b06ab5d-6035-448b-bd5a-5f73ad094300', 'caf246cf-aae0-4bb3-856a-cf2b4b77d173', 'a', 'Podrá fondear con finalidad exclusiva de recreo y en esa zona deberá navegar a una velocidad no superior a 3 nudos.', true, '2025-09-13 13:53:11.165633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beb2bb4d-6ca7-4dde-b335-d7a817476f04', 'caf246cf-aae0-4bb3-856a-cf2b4b77d173', 'b', 'No podrá continuar la navegación. Deberá fondear y avisar a los servicios de salvamento para que lo remolquen con seguridad.', false, '2025-09-13 13:53:11.165781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25606d04-5e39-4572-8131-22eab2631f0b', 'caf246cf-aae0-4bb3-856a-cf2b4b77d173', 'c', 'Deberá alejarse de la zona al menos 200 metros, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:11.165915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c346330-c80b-40f1-be4c-2f15b37ae0e0', 'caf246cf-aae0-4bb3-856a-cf2b4b77d173', 'd', 'Está absolutamente prohibida la navegación a esa distancia, al poner en peligro la seguridad de la vida humana en la mar o de la navegación.', false, '2025-09-13 13:53:11.166044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07b90428-faa3-4410-91bf-b0d4f191e9e8', 'c64bffd4-9c4e-4f97-a2a9-3608ff3f0c28', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', true, '2025-09-13 13:53:11.166315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5922e803-cebb-461e-bcbd-5ea1913ee2c7', 'c64bffd4-9c4e-4f97-a2a9-3608ff3f0c28', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:11.166446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5787c27d-9407-4186-89f9-043a2688545a', 'c64bffd4-9c4e-4f97-a2a9-3608ff3f0c28', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.166576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75b92f49-61fc-421f-892d-0c1d8206622b', 'c64bffd4-9c4e-4f97-a2a9-3608ff3f0c28', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', false, '2025-09-13 13:53:11.166705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ceae567-2a1e-4247-ae0e-d6379d1ac3fb', 'f903020f-f603-4a22-8f5e-44214f9ab63e', 'a', 'De libre elección, pero que no se preste a confusión con las Marcas para ayuda a la navegación.', false, '2025-09-13 13:53:11.166984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d763b7f-25d6-4b35-981b-017eb7cf7c83', 'f903020f-f603-4a22-8f5e-44214f9ab63e', 'b', 'Franjas verticales rojas y blancas.', false, '2025-09-13 13:53:11.167114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59a7e562-13f5-4f81-bbda-c65890b5f965', 'f903020f-f603-4a22-8f5e-44214f9ab63e', 'c', 'Franjas horizontales rojas y blancas.', true, '2025-09-13 13:53:11.167244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84bfe2fe-76ba-47b3-8d5f-ef91742e2e2c', 'f903020f-f603-4a22-8f5e-44214f9ab63e', 'd', 'Amarillo.', false, '2025-09-13 13:53:11.167373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f390168e-c9a7-469b-8db0-200245e60883', '6eb6686c-2cce-4ac0-ac84-55f963176b5e', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.167786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d0b63d7-ff8b-4fb9-a4d8-885754c60cf1', '6eb6686c-2cce-4ac0-ac84-55f963176b5e', 'b', 'Peligro nuevo.', false, '2025-09-13 13:53:11.167925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c957c83-11da-44aa-8235-36428eb27faf', '6eb6686c-2cce-4ac0-ac84-55f963176b5e', 'c', 'Especial.', false, '2025-09-13 13:53:11.16806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8985f3c-b5b4-4b00-a30d-9a7bf0e38182', '6eb6686c-2cce-4ac0-ac84-55f963176b5e', 'd', 'Lateral estribor.', false, '2025-09-13 13:53:11.168192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0d49bf9-679d-4167-8c0f-b837c56bf43a', '2a883db0-764e-4ca7-9592-a1def0cdb169', 'a', 'Nunca tienen marca de tope.', false, '2025-09-13 13:53:11.168462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f566528-38da-4187-9954-ced32941acd6', '2a883db0-764e-4ca7-9592-a1def0cdb169', 'b', 'Siempre tienen marca de tope que será dos esferas negras.', false, '2025-09-13 13:53:11.168593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1486dd15-d983-4189-bbb9-bc19c0b534a2', '2a883db0-764e-4ca7-9592-a1def0cdb169', 'c', 'Pueden tener marca de tope. En ese caso, será una esfera roja.', false, '2025-09-13 13:53:11.168724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9657cc4c-0f26-4706-9877-b417b94aa44a', '2a883db0-764e-4ca7-9592-a1def0cdb169', 'd', 'Si tienen marca de tope será un aspa amarilla.', true, '2025-09-13 13:53:11.168856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9065d23-2b1d-447c-81c2-f3696f3f23b4', 'da82b005-536c-4b87-8194-7bf23f93c09f', 'a', 'Por un canal principal.', false, '2025-09-13 13:53:11.169129+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22fa08cc-ee76-4cbd-a5ab-1f0957f8472c', 'da82b005-536c-4b87-8194-7bf23f93c09f', 'b', 'Por un canal secundario.', false, '2025-09-13 13:53:11.169256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9e68085-f69c-4289-9a85-b711fa32bfb4', 'da82b005-536c-4b87-8194-7bf23f93c09f', 'c', 'Entre una Marca lateral y una Marca cardinal norte.', false, '2025-09-13 13:53:11.169387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5186100-afb1-4e07-b722-3c45fbb4e8a0', 'da82b005-536c-4b87-8194-7bf23f93c09f', 'd', 'Entre una Marca lateral modificada y una Marca cardinal norte. Reglamento (RIPA).', true, '2025-09-13 13:53:11.169521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b790bde0-fc95-413c-a2cc-fa9ef27ff827', '27df09d8-38ea-4775-a371-b2e80d5a82a4', 'a', 'Dos pitadas cortas.', false, '2025-09-13 13:53:11.1698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54073d85-1860-4326-95e1-f1be4cb69258', '27df09d8-38ea-4775-a371-b2e80d5a82a4', 'b', 'Dos pitadas largas.', true, '2025-09-13 13:53:11.169934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a9ba141-b989-4828-9a5c-e77eaf34b931', '27df09d8-38ea-4775-a371-b2e80d5a82a4', 'c', 'Una pitada corta.', false, '2025-09-13 13:53:11.170062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e0c768f-1c6c-404a-9476-75db6b12fdd5', '27df09d8-38ea-4775-a371-b2e80d5a82a4', 'd', 'Una pitada larga.', false, '2025-09-13 13:53:11.17019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2af62d95-99bb-4db8-b8d8-e8b0db94608d', 'b20e0e4f-ac44-441d-9ffa-89bc32f7976e', 'a', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.17046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c47358e-4a38-483f-81d0-de9d65b07cbd', 'b20e0e4f-ac44-441d-9ffa-89bc32f7976e', 'b', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', true, '2025-09-13 13:53:11.170587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dac1f004-c6a5-484b-844d-5b2704c8a527', 'b20e0e4f-ac44-441d-9ffa-89bc32f7976e', 'c', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.170729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f09d97d1-0166-425d-8de4-81e93c71e1a7', 'b20e0e4f-ac44-441d-9ffa-89bc32f7976e', 'd', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.170882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5a99a7e-ee30-47a5-87e6-8013738f73f1', '65f9e945-de62-4540-b091-438670352ed3', 'a', 'Los buques de eslora inferior a 20 m.', false, '2025-09-13 13:53:11.171182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fea73328-6dd3-476f-8465-3a4a4fdd0eb8', '65f9e945-de62-4540-b091-438670352ed3', 'b', 'Los buques de vela.', false, '2025-09-13 13:53:11.171317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f150a801-6108-43d0-b3a5-f7c1c6daf0c1', '65f9e945-de62-4540-b091-438670352ed3', 'c', 'Los buques que puedan navegar con seguridad por la vía de circulación adecuada de un dispositivo de separación de tráfico.', true, '2025-09-13 13:53:11.171605+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('161ec119-d164-40a7-8ce7-f5b3bddf0178', '65f9e945-de62-4540-b091-438670352ed3', 'd', 'Los buques dedicados a la pesca.', false, '2025-09-13 13:53:11.171745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd6073d5-f17f-4cfa-92b5-d0715c698b20', '5ffd1e1a-9f71-42a9-b9fb-eb80fae2e7bb', 'a', 'El buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de éste', false, '2025-09-13 13:53:11.172054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05193f58-8366-4f87-8b72-81b48e1414fd', '5ffd1e1a-9f71-42a9-b9fb-eb80fae2e7bb', 'b', 'El buque que tenga al otro por su costado de babor maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.17219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53930914-2659-4c3e-9dff-82a64681b7f6', '5ffd1e1a-9f71-42a9-b9fb-eb80fae2e7bb', 'c', 'Ambos buques maniobrarán, si las circunstancias lo permiten, eligiendo siempre maniobras que eviten cortarle la proa al otro buque.', true, '2025-09-13 13:53:11.172329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8adac04-47be-4a9b-9dff-95536651294d', '5ffd1e1a-9f71-42a9-b9fb-eb80fae2e7bb', 'd', 'Dado que todo buque está obligado a mantenerse apartado de la derrota de otro buque, los buques realizarán maniobras simétricas.', false, '2025-09-13 13:53:11.172461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b3af003-016c-4ceb-bd8a-b02cc89d5c87', '3eef1621-856b-44e8-bdf8-e889bacdb040', 'a', 'Una luz amarilla.', false, '2025-09-13 13:53:11.17274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26fe8e8e-239a-4284-ad87-8b3f153da29f', '3eef1621-856b-44e8-bdf8-e889bacdb040', 'b', 'Una luz verde.', false, '2025-09-13 13:53:11.172883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8ae7543-5590-48ce-ba89-9fd1c17562b7', '3eef1621-856b-44e8-bdf8-e889bacdb040', 'c', 'Una luz roja.', true, '2025-09-13 13:53:11.173022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e586fa27-7c1f-466b-8864-c793f8e700de', '3eef1621-856b-44e8-bdf8-e889bacdb040', 'd', 'Una luz blanca.', false, '2025-09-13 13:53:11.173159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c30c203-71ae-40b2-8c88-8a1f17cc9d06', '73909634-4401-495d-8c07-549b2999eb30', 'a', 'Solamente a los buques sin gobierno.', false, '2025-09-13 13:53:11.173433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e1e5bcd-03f6-4ad6-badf-fa8a70d1f8b9', '73909634-4401-495d-8c07-549b2999eb30', 'b', 'En cualquier condición de visibilidad.', false, '2025-09-13 13:53:11.173565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46d30a1d-916b-4bbc-9217-61368e5b1b0a', '73909634-4401-495d-8c07-549b2999eb30', 'c', 'Sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.173701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19558d19-43f0-4556-b3b9-b77e91367558', '73909634-4401-495d-8c07-549b2999eb30', 'd', 'Sólo a los buques restringidos por su calado.', true, '2025-09-13 13:53:11.173848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea4affb2-95ee-4abd-986d-b07b1f7da12f', 'ecc16b1c-8dda-4abd-868c-cda61c22e539', 'a', 'Por vía telefónica llamando al 900 222 222.', false, '2025-09-13 13:53:11.18303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05243af5-6437-4cc5-a540-4593e95a0688', '49ebe7c6-36f6-4a2d-b7fe-510fc048e4db', 'b', 'Se considerará que tal situación existe cuando un buque no vea a otro por su proa.', false, '2025-09-13 13:53:11.174271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6786bf1e-aaa3-4d2a-9fd3-79fb332a8016', '49ebe7c6-36f6-4a2d-b7fe-510fc048e4db', 'c', 'Cuando un buque abrigue dudas de si existe tal situación, supondrá que existe y actuará en', false, '2025-09-13 13:53:11.17442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e7ad49c-924d-4a10-9b46-9ae8529db25a', '49ebe7c6-36f6-4a2d-b7fe-510fc048e4db', 'd', 'De noche, vería las luces de costado y la luz de alcance.', false, '2025-09-13 13:53:11.174551+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('177e417d-ee14-48a9-9e74-5994be68be4c', 'ca772f70-b49b-4095-afdc-9d199168fd9b', 'a', 'Los buques de propulsión mecánica tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:11.174825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d9e1fa0-0bd7-4c19-b2fa-a3a01721d8ee', 'ca772f70-b49b-4095-afdc-9d199168fd9b', 'b', 'Todos los buques navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:11.174957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dee675ed-0080-4266-8d87-a39c64f902a9', 'ca772f70-b49b-4095-afdc-9d199168fd9b', 'c', 'Es de aplicación a los buques que estén a la vista uno del otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.175088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbc5f8f9-9246-4557-b419-0b493217adc2', 'ca772f70-b49b-4095-afdc-9d199168fd9b', 'd', 'Todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, deberá reducir su velocidad hasta la mínima de su gobierno.', false, '2025-09-13 13:53:11.175219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa03903f-2459-41d5-aedb-69148a5d11c5', '0a7c679b-46e0-43ce-a0c2-e7230805d7f6', 'a', 'Todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de', true, '2025-09-13 13:53:11.175497+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8457aad8-b22c-4141-864d-e3f984b73449', '0a7c679b-46e0-43ce-a0c2-e7230805d7f6', 'b', 'Todo buque dedicado a operaciones de remolque que por su naturaleza restrinja fuertemente al buque remolcador y su remolque en su capacidad para apartarse de su derrota.', false, '2025-09-13 13:53:11.175634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58d333c8-526e-4d64-8603-d775f648b9d4', '0a7c679b-46e0-43ce-a0c2-e7230805d7f6', 'c', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', false, '2025-09-13 13:53:11.175767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a63ebd48-7713-4053-84c0-80f222aa19cd', '0a7c679b-46e0-43ce-a0c2-e7230805d7f6', 'd', 'Todo buque dedicado a dragados, trabajos hidrográficos, oceanográficos u operaciones', false, '2025-09-13 13:53:11.175936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49faab53-ad2d-49b0-99f8-d0cddd2d346b', '09a98ed2-5161-41b2-83af-3a0f22a7a35a', 'a', 'Realizando movimientos rápidos y repetidos, de manera circular con el brazo izquierdo', false, '2025-09-13 13:53:11.176336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c292919-6b1f-4763-8f56-34d91439c0c8', '09a98ed2-5161-41b2-83af-3a0f22a7a35a', 'b', 'Quedándonos estáticos en cubierta, con el brazo izquierdo extendido hacia arriba.', false, '2025-09-13 13:53:11.176472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e234f97-11d0-4ae7-addc-ed1d260979e0', '09a98ed2-5161-41b2-83af-3a0f22a7a35a', 'c', 'Quedándonos estáticos en cubierta, con el brazo derecho extendido hacia arriba.', true, '2025-09-13 13:53:11.176603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6895e204-b8d0-4e4b-a378-0aefe9dfe41a', '09a98ed2-5161-41b2-83af-3a0f22a7a35a', 'd', 'Realizando movimientos lentos y repetidos, subiendo y bajando los brazos extendidos DE TRANSPORTES, MOVILIDAD                                                                          DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                    Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 04 Nomenclatura náutica.', false, '2025-09-13 13:53:11.176733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95697c4f-8364-43a4-8887-f5a81340ceff', 'f9667de0-1b11-47f4-8c2e-1063d997dba8', 'a', 'Escorar es desviarse una embarcación de su rumbo por el impulso del viento o de una corriente.', false, '2025-09-13 13:53:11.177145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c4e4f03-4146-4dfc-abdf-8e17f63ed48b', 'f9667de0-1b11-47f4-8c2e-1063d997dba8', 'b', 'Adrizar es poner derecha o vertical una embarcación que estaba inclinada.', true, '2025-09-13 13:53:11.177279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a43e8c9-c766-40e8-abd2-7cc1f960d6af', 'f9667de0-1b11-47f4-8c2e-1063d997dba8', 'c', 'Barlovento es la parte opuesta a aquella de donde viene el viento con respecto a un punto o lugar', false, '2025-09-13 13:53:11.17741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9357ad5-7870-4a6b-af5f-ec9fe2ececea', 'f9667de0-1b11-47f4-8c2e-1063d997dba8', 'd', 'Sotavento es la parte de donde viene el viento, con respecto a un punto o lugar determinado.', false, '2025-09-13 13:53:11.177539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('447b59f0-41ab-4931-be2b-ae737cf563a2', '19692483-1515-4d4e-9921-df4eec4a3fbb', 'a', 'La hélice es el conjunto de palas que giran alrededor de un eje y empujan el fluido ambiente produciendo en él una fuerza de reacción que se utiliza principalmente para la propulsión de barcos', true, '2025-09-13 13:53:11.177814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c734c76b-a842-4c24-b95c-257b3b2bf05d', '19692483-1515-4d4e-9921-df4eec4a3fbb', 'b', 'La bocina es el orificio que permite que el eje de la hélice gire a través del casco y entre agua para su refrigeración.', false, '2025-09-13 13:53:11.177945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9378ca8a-713e-4643-8217-1ea30f3a13df', '19692483-1515-4d4e-9921-df4eec4a3fbb', 'c', 'El capacete es la pieza esférica que cierra el núcleo de la hélice.', false, '2025-09-13 13:53:11.178075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('456d23e7-2684-4f1f-8a50-ae1454c5222e', '19692483-1515-4d4e-9921-df4eec4a3fbb', 'd', 'Las palas son placas planas en las que se provoca una diferencia de velocidades del fluido entre una cara y la otra de la hélice.', false, '2025-09-13 13:53:11.178204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e4cd6c8-8c2d-46b8-9e27-b5f85f006273', '11527746-9168-44e9-a5df-f4c5fd8d3860', 'a', 'La quilla es la pieza, que va de popa a proa por la parte inferior del barco y en que se asienta todo', false, '2025-09-13 13:53:11.178479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4eb7714-66e1-4b29-9cc3-5c5b5b97f4ec', '11527746-9168-44e9-a5df-f4c5fd8d3860', 'b', 'La roda es la pieza gruesa y curva, que forma la proa de la embarcación.', false, '2025-09-13 13:53:11.17861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f130093-f767-4576-835f-dba319032df5', '11527746-9168-44e9-a5df-f4c5fd8d3860', 'c', 'El codaste es la pieza gruesa dispuesta verticalmente sobre el extremo de la quilla inmediato a la popa, que sirve de fundamento a toda la armazón de esta parte del buque.', false, '2025-09-13 13:53:11.17874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3be4445a-16ed-4912-8530-0b3d65db5cdd', '11527746-9168-44e9-a5df-f4c5fd8d3860', 'd', 'Los baos son cada una de las piezas curvas cuya base o parte inferior encaja en la quilla del buque y desde allí arrancan a babor y estribor, en dos ramas simétricas, formando las “costillas” del', true, '2025-09-13 13:53:11.17891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69f67e71-91d4-49f0-9640-ffccdfaff3cd', 'e322c834-09b5-4f9d-933c-84e5ea6dcaf7', 'a', 'Virar es dar vueltas al cabrestante para levar el ancla.', false, '2025-09-13 13:53:11.179193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5046f60-b55f-4fe3-94be-45ab9da0c3ea', 'e322c834-09b5-4f9d-933c-84e5ea6dcaf7', 'b', 'Filar es arriar progresivamente un cabo o cadena que está trabajando.', false, '2025-09-13 13:53:11.179327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64f44e4d-86c9-47d1-83d7-bc7ff3da330a', 'e322c834-09b5-4f9d-933c-84e5ea6dcaf7', 'c', 'Levar es recoger, arrancar y suspender el ancla que está fondeada.', false, '2025-09-13 13:53:11.179458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d807430e-491b-4bc7-8048-5c03ddfac679', 'e322c834-09b5-4f9d-933c-84e5ea6dcaf7', 'd', 'Zarpar es salir un barco del lugar en que estaba atracado. Elementos de amarre y fondeo.', true, '2025-09-13 13:53:11.179594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26d27e61-c027-404c-9314-6604af1977a2', '187f907e-7642-4a44-ba85-a607d3f43602', 'a', 'Firme.', false, '2025-09-13 13:53:11.179881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6abb5875-40fe-40c9-89c3-1fbc81448715', '187f907e-7642-4a44-ba85-a607d3f43602', 'b', 'Chicote.', false, '2025-09-13 13:53:11.180029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac06a9ad-90a7-4dd5-8a6d-454a5dbbb248', '187f907e-7642-4a44-ba85-a607d3f43602', 'c', 'Gaza.', true, '2025-09-13 13:53:11.18019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13e6f1cd-7c28-4a94-b7eb-8d324ec0f9c3', '187f907e-7642-4a44-ba85-a607d3f43602', 'd', 'Seno.', false, '2025-09-13 13:53:11.180353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1462e42-6d04-4fca-9303-febd4c6c90d8', '0d13e2ce-2f0e-4431-a966-2e77d35dcb38', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del', false, '2025-09-13 13:53:11.180686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e13f38f-706e-4759-a79a-47e878b8dc37', '0d13e2ce-2f0e-4431-a966-2e77d35dcb38', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no ha garreado, y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-13 13:53:11.180847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19b79e07-c7e3-41d4-9feb-ea5bb37ac5ab', '0d13e2ce-2f0e-4431-a966-2e77d35dcb38', 'c', 'La embarcación debe disponer de una línea de fondeo cuya longitud será tres veces su eslora.', false, '2025-09-13 13:53:11.181006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91655d8a-81bc-42c5-9481-46f010a478ba', '0d13e2ce-2f0e-4431-a966-2e77d35dcb38', 'd', 'Si optamos por el fondeo a la gira, utilizaremos dos anclas de forma que las líneas de fondeo formen un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:11.181164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4580abc8-f6a5-4f43-a211-3e1181b4d6d6', 'cb35c895-c655-4189-b1b1-06d6191fe7c6', 'a', 'Cuando la frecuencia del movimiento de balance es alta.', true, '2025-09-13 13:53:11.181601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14195814-f310-4ce4-b187-35ed987da835', 'cb35c895-c655-4189-b1b1-06d6191fe7c6', 'b', 'Cuando la frecuencia del movimiento de balance es baja o casi nula.', false, '2025-09-13 13:53:11.18177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('015ad8b7-8055-4073-8a20-7818bd51961a', 'cb35c895-c655-4189-b1b1-06d6191fe7c6', 'c', 'Cuando la frecuencia del movimiento de cabezada es alta.', false, '2025-09-13 13:53:11.181911+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('846aa465-3cbb-4c13-83af-042c75e355f7', 'cb35c895-c655-4189-b1b1-06d6191fe7c6', 'd', 'Cuando la frecuencia del movimiento de cabezada es baja o casi nula.', false, '2025-09-13 13:53:11.182047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6c42189-23b6-4863-b33d-1ea6875ba5de', 'a2148c88-88cf-4fc8-a602-59a1cadecca0', 'a', '50 N.', false, '2025-09-13 13:53:11.182341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9e60866-9c16-47d1-a331-31d7ba822608', 'a2148c88-88cf-4fc8-a602-59a1cadecca0', 'b', '100 N.', false, '2025-09-13 13:53:11.182476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50a5dbdf-d09f-472f-a51c-549cbc3e1a3d', 'a2148c88-88cf-4fc8-a602-59a1cadecca0', 'c', '150 N.', true, '2025-09-13 13:53:11.18261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7edd35ed-b170-47f7-a1d0-8bc4231850c7', 'a2148c88-88cf-4fc8-a602-59a1cadecca0', 'd', '275 N.', false, '2025-09-13 13:53:11.182742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9776d9c5-bfd0-4694-baf4-e0c302ef4123', 'ecc16b1c-8dda-4abd-868c-cda61c22e539', 'b', 'Únicamente por vía telefónica llamando al 900 202 202 o al 112.', false, '2025-09-13 13:53:11.183163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72508e61-4e6d-4132-af57-820d68c00e2d', 'ecc16b1c-8dda-4abd-868c-cda61c22e539', 'c', 'Exclusivamente con el uso de la estación de radio a bordo.', false, '2025-09-13 13:53:11.183301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2badff8-4743-429a-b1f1-f6eeaf519346', 'ecc16b1c-8dda-4abd-868c-cda61c22e539', 'd', 'Por vía telefónica o con el uso de la estación de radio a bordo.', true, '2025-09-13 13:53:11.183433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8148c408-2dd1-4638-85e5-42a18014e971', '8ee1afdc-e3a6-4b71-8636-82220369d42d', 'a', 'Existe una mayor maniobrabilidad al aumentar la sonda.', false, '2025-09-13 13:53:11.183708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2acb638d-99f2-4d96-b7e8-853717f93107', '8ee1afdc-e3a6-4b71-8636-82220369d42d', 'b', 'Navegaremos con mayor seguridad llevando la mar por la amura.', true, '2025-09-13 13:53:11.183872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db0e49cc-5b02-4569-9b07-48c1fab0e6a1', '8ee1afdc-e3a6-4b71-8636-82220369d42d', 'c', 'Navegaremos con mayor seguridad aumentando la velocidad.', false, '2025-09-13 13:53:11.184015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be8fe3ff-57de-40e3-810e-7ff31ad322df', '8ee1afdc-e3a6-4b71-8636-82220369d42d', 'd', 'La maniobrabilidad no se ve afectada.', false, '2025-09-13 13:53:11.184169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01a9cf07-37a7-4036-b0cd-5e046ec22a4b', 'a978674d-9dc4-4e3a-a059-3c5e1daf7eb6', 'a', 'Entre las medidas legales adoptadas se establecen limitaciones al fondeo de embarcaciones para evitar que malas técnicas de fondeo arrastren y barran el fondo marino arrancando matas, deteriorando las praderas de posidonia.', true, '2025-09-13 13:53:11.18445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edb36a51-ab8d-4bf7-8781-2c7e3e608518', 'a978674d-9dc4-4e3a-a059-3c5e1daf7eb6', 'b', 'La única medida adoptada en España es cartografiar y catalogar las praderas e insertar esos datos en sistemas de información accesibles a los navegantes y al público en general y, en la medida de lo posible, en las cartas náuticas.', false, '2025-09-13 13:53:11.184586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97e1f961-5e60-4279-87ed-d66851c92348', 'a978674d-9dc4-4e3a-a059-3c5e1daf7eb6', 'c', 'Todavía no existe normativa concreta, sólo recomendaciones de las consejerías de pesca y medio ambiente de las diferentes comunidades autónomas sobre cómo actuar allí donde se localizan las praderas de posidonia.', false, '2025-09-13 13:53:11.18472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9e229f7-b75d-44b5-9ad2-909f59320b05', 'a978674d-9dc4-4e3a-a059-3c5e1daf7eb6', 'd', 'No hay normativa específica ni limitación alguna para fondear sobre praderas de posidonia, pero un navegante responsable con el medio ambiente, antes de fondear, debería observar el fondo marino por su propia cuenta para procurar no dañar la posidonia.', false, '2025-09-13 13:53:11.184854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00fbffd0-9f67-49f5-ac7a-837418b50900', '1c724c9a-6529-45ef-9f38-774a117728ed', 'a', 'Podrá fondear con finalidad exclusiva de recreo y en esa zona deberá navegar a una velocidad no superior a 3 nudos.', true, '2025-09-13 13:53:11.185131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dc6d373-38e3-43ec-96c5-d7b6a8ecd854', '1c724c9a-6529-45ef-9f38-774a117728ed', 'b', 'No podrá continuar la navegación. Deberá fondear y avisar a los servicios de salvamento para que lo remolquen con seguridad.', false, '2025-09-13 13:53:11.185372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa3dcf1c-ec3d-45fe-8ca8-8b4c66c03e83', '1c724c9a-6529-45ef-9f38-774a117728ed', 'c', 'Deberá alejarse de la zona al menos 200 metros, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:11.185508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('963202d3-90e8-449c-b1bd-c8f6f8ad9b45', '1c724c9a-6529-45ef-9f38-774a117728ed', 'd', 'Está absolutamente prohibida la navegación a esa distancia, al poner en peligro la seguridad de la vida humana en la mar o de la navegación.', false, '2025-09-13 13:53:11.185641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0aeeafc-4fee-4550-b2c8-5fc433c44509', '11fba46f-545e-4771-b007-3bfd73e46f4b', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.185942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cce6163-e88c-4361-8924-768f92d9f84d', '11fba46f-545e-4771-b007-3bfd73e46f4b', 'b', 'Peligro nuevo.', false, '2025-09-13 13:53:11.186076+00');
