INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2acd0d2f-2873-493a-b57a-d1243051f309', '11fba46f-545e-4771-b007-3bfd73e46f4b', 'd', 'Lateral estribor.', false, '2025-09-13 13:53:11.186342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1436472d-87cb-4cb4-a0ab-ab90f92c4cd9', 'fcb1b0ef-3cab-4fe9-b76f-e23132fcf6ce', 'a', 'Nunca tienen marca de tope.', false, '2025-09-13 13:53:11.186616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a3ffba4-387d-4296-8e41-48bb04b53ac5', 'fcb1b0ef-3cab-4fe9-b76f-e23132fcf6ce', 'b', 'Siempre tienen marca de tope que será dos esferas negras.', false, '2025-09-13 13:53:11.186745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7d3682e-5b96-492e-bd43-b9546e6be248', 'fcb1b0ef-3cab-4fe9-b76f-e23132fcf6ce', 'c', 'Pueden tener marca de tope. En ese caso, será una esfera roja.', true, '2025-09-13 13:53:11.186902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a91d07f-baf2-4fe6-b650-dec0c3259be7', 'fcb1b0ef-3cab-4fe9-b76f-e23132fcf6ce', 'd', 'Si tienen marca de tope será un aspa amarilla.', false, '2025-09-13 13:53:11.187035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c03fc0ed-0cc6-452c-bf5e-d52b48d6eba1', '7bed9d8e-54b1-49c8-a2e3-9178f539cbbc', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', false, '2025-09-13 13:53:11.187306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59392f92-b420-416a-b377-5b3c74a26fa1', '7bed9d8e-54b1-49c8-a2e3-9178f539cbbc', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:11.187435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f412b8d9-4aac-4694-aba5-391312720d9c', '7bed9d8e-54b1-49c8-a2e3-9178f539cbbc', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.187566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f4dc724-cf6b-4a5a-bf71-f266eada583e', '7bed9d8e-54b1-49c8-a2e3-9178f539cbbc', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', true, '2025-09-13 13:53:11.187694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4794b098-1c25-43ba-88c8-9f36df00547a', '760ed105-3533-4ba3-af7a-e929aa394269', 'a', 'De libre elección, pero que no se preste a confusión con las Marcas para ayuda a la navegación.', false, '2025-09-13 13:53:11.187971+00');
