INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc1f3264-28c7-4adf-9a27-971966709489', 'dffd6263-4f02-4e74-990e-aab2fe22abc6', 'c', 'Entre una Marca lateral y una Marca cardinal norte.', false, '2025-09-13 13:53:11.188895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f530750-a9df-49ef-b1a0-7b49ab36560a', 'dffd6263-4f02-4e74-990e-aab2fe22abc6', 'd', 'Entre una Marca lateral modificada y una Marca cardinal norte. Reglamento (RIPA).', false, '2025-09-13 13:53:11.189026+00');
