INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8d3ace5-8f5b-4992-9827-91808d1e41c2', 'e0caa275-87cd-4c54-9989-854366aa9d1a', 'a', 'Todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de', false, '2025-09-13 13:53:11.19075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8c2aa26-4aeb-4ab0-aa19-83e0c794b0d7', 'e0caa275-87cd-4c54-9989-854366aa9d1a', 'b', 'Todo buque dedicado a operaciones de remolque que por su naturaleza restrinja fuertemente al buque remolcador y su remolque en su capacidad para apartarse de su derrota.', false, '2025-09-13 13:53:11.190891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d474328-8bd1-4cf1-9276-60984bded41c', 'e0caa275-87cd-4c54-9989-854366aa9d1a', 'c', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', true, '2025-09-13 13:53:11.191023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52bb15f0-6dc1-4e99-9590-09ecca60b29c', 'e0caa275-87cd-4c54-9989-854366aa9d1a', 'd', 'Todo buque dedicado a dragados, trabajos hidrográficos, oceanográficos u operaciones', false, '2025-09-13 13:53:11.191152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ed22c59-4c42-4cb5-93d6-ce241ee89435', '700a5c68-3234-4204-a13b-7defc67c28e1', 'a', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', true, '2025-09-13 13:53:11.191429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1eeb626d-f935-49dd-8378-17956db52f71', '700a5c68-3234-4204-a13b-7defc67c28e1', 'b', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.191564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('241fc2f2-02e5-41cb-8b79-647f91284636', '700a5c68-3234-4204-a13b-7defc67c28e1', 'c', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.191692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32f1731c-5d25-443c-bca4-b57eb54ca7b0', '700a5c68-3234-4204-a13b-7defc67c28e1', 'd', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.191821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72909c81-b345-4f97-8b29-831cf6dc5d93', 'f50e0d34-a21f-42d6-af0e-d191152aefdc', 'c', 'Una pitada corta.', false, '2025-09-13 13:53:11.241505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b50d7612-e508-460b-877e-920fd1342eb5', 'bfc29293-852e-41f4-9c03-76c34fc5f212', 'a', 'Los buques de propulsión mecánica tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:11.19209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17870aef-26cb-4a4c-a011-4bce3c3288e6', 'bfc29293-852e-41f4-9c03-76c34fc5f212', 'b', 'Todos los buques navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:11.192226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('075c044f-46d2-4078-bed1-be9a3e3833d5', 'bfc29293-852e-41f4-9c03-76c34fc5f212', 'c', 'Es de aplicación a los buques que estén a la vista uno del otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.192354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0b0eddd-77c2-4052-bc1d-686a95053ed1', 'bfc29293-852e-41f4-9c03-76c34fc5f212', 'd', 'Todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, deberá reducir su velocidad hasta la mínima de su gobierno.', false, '2025-09-13 13:53:11.192484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef47fecc-765a-43bc-8dad-0bac86e12205', 'bca4cf45-62fc-4f52-8762-b06c38c1c0bb', 'a', 'Los buques de eslora inferior a 20 m.', false, '2025-09-13 13:53:11.192755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7a5ba6f-edf7-4d79-af21-b98a30b3f78d', 'bca4cf45-62fc-4f52-8762-b06c38c1c0bb', 'b', 'Los buques de vela.', false, '2025-09-13 13:53:11.192898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00a93ea0-55f9-489e-8d02-fca136c75025', 'bca4cf45-62fc-4f52-8762-b06c38c1c0bb', 'c', 'Los buques que puedan navegar con seguridad por la vía de circulación adecuada de un dispositivo de separación de tráfico.', true, '2025-09-13 13:53:11.193027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30004975-96b5-421f-ad07-526c6f5d6d40', 'bca4cf45-62fc-4f52-8762-b06c38c1c0bb', 'd', 'Los buques dedicados a la pesca.', false, '2025-09-13 13:53:11.193157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87380e88-84ea-43a1-accd-bfe6bc16f330', 'dc99ad9c-5e12-4d8e-8d8d-eb20fe1f3032', 'a', 'El buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de éste', true, '2025-09-13 13:53:11.193432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('565f3120-7e7c-44fa-b05c-d52057b5c95a', 'dc99ad9c-5e12-4d8e-8d8d-eb20fe1f3032', 'b', 'El buque que tenga al otro por su costado de babor maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.193561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1f9ce73-e3a8-43b8-b5ba-4b2d08375696', 'dc99ad9c-5e12-4d8e-8d8d-eb20fe1f3032', 'c', 'Ambos buques maniobrarán, si las circunstancias lo permiten, eligiendo siempre maniobras que eviten cortarle la proa al otro buque.', false, '2025-09-13 13:53:11.193687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffb85a35-b81b-47aa-bad4-c1401eed0b7e', 'dc99ad9c-5e12-4d8e-8d8d-eb20fe1f3032', 'd', 'Dado que todo buque está obligado a mantenerse apartado de la derrota de otro buque, los buques realizarán maniobras simétricas.', false, '2025-09-13 13:53:11.193822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8120758-d863-496d-b27a-aeaeab48687c', '893a89d2-d528-4b21-be48-b226a5f25278', 'a', 'Solamente a los buques sin gobierno.', false, '2025-09-13 13:53:11.194095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b79fd8c8-7e2e-4cb2-949b-74f41f5c99f8', '893a89d2-d528-4b21-be48-b226a5f25278', 'b', 'En cualquier condición de visibilidad.', true, '2025-09-13 13:53:11.194225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b167c79a-d80a-4935-b129-5c9fa2a8b27f', '893a89d2-d528-4b21-be48-b226a5f25278', 'c', 'Sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.19436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d81fa4c6-40d2-4337-9149-d32a1a4940ab', '893a89d2-d528-4b21-be48-b226a5f25278', 'd', 'Sólo a los buques restringidos por su calado.', false, '2025-09-13 13:53:11.194494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36e6050b-c91a-427d-b2cd-a9ed7660f1ae', 'dae871c9-f519-4201-b4cf-a46cb7c2ebf4', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:11.194867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3a67284-6aca-4899-a6a5-44e20de1245f', 'dae871c9-f519-4201-b4cf-a46cb7c2ebf4', 'b', 'Se considerará que tal situación existe cuando un buque no vea a otro por su proa.', false, '2025-09-13 13:53:11.194998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6711c6cb-da21-4164-9659-acd68df27d7e', 'dae871c9-f519-4201-b4cf-a46cb7c2ebf4', 'c', 'Cuando un buque abrigue dudas de si existe tal situación, supondrá que existe y actuará en', true, '2025-09-13 13:53:11.195124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b4a2f51-103f-4223-8791-b5f13f8baccb', 'dae871c9-f519-4201-b4cf-a46cb7c2ebf4', 'd', 'De noche, vería las luces de costado y la luz de alcance.', false, '2025-09-13 13:53:11.195254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f506be5d-7494-4df7-b722-c86620a4308c', '79c8ab15-c6b0-4b9a-9ccf-e091c36eb9ff', 'a', 'Realizando movimientos rápidos y repetidos, de manera circular con el brazo izquierdo', false, '2025-09-13 13:53:11.195524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a7118b4-57b5-41ae-b5a7-b8e46ce8dc66', '79c8ab15-c6b0-4b9a-9ccf-e091c36eb9ff', 'b', 'Quedándonos estáticos en cubierta, con el brazo izquierdo extendido hacia arriba.', false, '2025-09-13 13:53:11.195656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acd02b76-ffab-4ca6-8784-761cd078dcaa', '79c8ab15-c6b0-4b9a-9ccf-e091c36eb9ff', 'c', 'Quedándonos estáticos en cubierta, con el brazo derecho extendido hacia arriba.', false, '2025-09-13 13:53:11.195785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21d859d0-da13-41c9-8c0d-602583c80651', '79c8ab15-c6b0-4b9a-9ccf-e091c36eb9ff', 'd', 'Realizando movimientos lentos y repetidos, subiendo y bajando los brazos extendidos DE TRANSPORTES, MOVILIDAD                                                                           DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                     Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 01 Nomenclatura náutica.', true, '2025-09-13 13:53:11.195915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d5c777c-c192-4629-a912-d70031e3cfa6', 'b80a1ece-e063-4e4e-95f1-9732d45f94fa', 'a', 'La eslora es la longitud que tiene la embarcación sobre la cubierta principal, desde el codaste a la roda, por la parte de adentro.', false, '2025-09-13 13:53:11.196322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62dbf56b-4a27-4c29-a29e-d0cdd53d802a', 'b80a1ece-e063-4e4e-95f1-9732d45f94fa', 'b', 'La manga es la anchura de la embarcación.', false, '2025-09-13 13:53:11.196452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27a11bd0-25fb-42c0-b065-b703d97b0406', 'b80a1ece-e063-4e4e-95f1-9732d45f94fa', 'c', 'El puntal es la altura de la embarcación desde su plan hasta la cubierta de francobordo.', true, '2025-09-13 13:53:11.196582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f49e85d2-3d23-468a-a561-5aec6f810a21', 'b80a1ece-e063-4e4e-95f1-9732d45f94fa', 'd', 'El calado de un barco es la distancia vertical entre un punto de la línea de flotación y la línea base o quilla, incluido el espesor del casco.', false, '2025-09-13 13:53:11.196707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36ee65e1-1994-4f6b-8e87-44be1254bf87', '26dd700d-97a5-404f-8a82-6abf40376497', 'a', 'El ancla, el tramo de cadena unida al ancla por un grillete, el tramo de estacha o cabo unido a la cadena y el molinete.', false, '2025-09-13 13:53:11.197004+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d2e60af-f659-4352-9dde-766e4f8c2cc1', '26dd700d-97a5-404f-8a82-6abf40376497', 'c', 'El tramo de cadena unida al ancla por un grillete, sin incluir el ancla, y el tramo de estacha o cabo unido a la cadena.', false, '2025-09-13 13:53:11.197264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ec872fa-fe55-41a5-8ea3-25dec39911e8', '26dd700d-97a5-404f-8a82-6abf40376497', 'd', 'El tramo de cadena unida al ancla, sin incluir el grillete y el ancla, y el tramo de estacha o cabo unido a la cadena.', true, '2025-09-13 13:53:11.197395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6047b9fd-ad14-4b45-83e0-3ef20daa06c9', '4c222f1d-7f9d-4022-9a4e-3dc8fc75fd9c', 'b', 'La parte del costado izquierdo donde el casco se estrecha formando la proa del barco.', false, '2025-09-13 13:53:11.197791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38ecda66-1744-4f46-bf28-fca469860761', '4c222f1d-7f9d-4022-9a4e-3dc8fc75fd9c', 'c', 'La parte del costado derecho donde el casco se estrecha formando la proa del barco.', false, '2025-09-13 13:53:11.197925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a12e038-be21-4b03-b8ee-77d3c5d59693', '59892904-9049-4a0b-b4cb-e229fd7c8903', 'a', 'La limera es la abertura en la bovedilla de popa, para el paso de la cabeza del timón.', false, '2025-09-13 13:53:11.198354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9f9f795-a1c7-43cd-bc32-73a88268aa69', '59892904-9049-4a0b-b4cb-e229fd7c8903', 'b', 'La pala es la parte plana del timón que sobresale en su totalidad del agua.', false, '2025-09-13 13:53:11.19849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5310ed31-f49c-4793-a816-ed49f342a4c2', '59892904-9049-4a0b-b4cb-e229fd7c8903', 'c', 'El timón es la pieza plana y móvil montada en la parte posterior de una embarcación, que sirve para controlar su dirección en el plano horizontal.', false, '2025-09-13 13:53:11.198622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07f71fda-4f42-4b91-ac36-c19c0dd8ba1a', '59892904-9049-4a0b-b4cb-e229fd7c8903', 'd', 'Los guardines son los cabos, cadenas o cables que trasmiten los movimientos de la rueda del timón a la caña de mismo, para gobernar el buque. Elementos de amarre y fondeo.', true, '2025-09-13 13:53:11.198754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d705d443-fb81-4361-a923-7fb401b9b407', '61de2ff8-2214-4ac5-ac32-1cfd063e110d', 'a', 'Fijar las amarras de las embarcaciones cuando atracan al muelle.', false, '2025-09-13 13:53:11.199036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('019e37d0-d25e-415e-ab48-d8d4eda48eab', '61de2ff8-2214-4ac5-ac32-1cfd063e110d', 'b', 'Guiar la unión de dos cabos de una misma mena.', false, '2025-09-13 13:53:11.199168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a5ec00b-4fd6-4554-a684-356c833eefef', '61de2ff8-2214-4ac5-ac32-1cfd063e110d', 'c', 'Proteger el casco de golpes y rozaduras.', true, '2025-09-13 13:53:11.199302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fba442c1-c372-491c-bbe0-a185c589dd99', '61de2ff8-2214-4ac5-ac32-1cfd063e110d', 'd', 'Pasar y guiar los cabos de amarre desde la embarcación hasta los elementos de amarre del muelle.', false, '2025-09-13 13:53:11.199542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c56dc53-a831-47d3-af70-8bdcfcc52cf0', '92173ca2-03f7-4e55-85db-11edad0fcf05', 'a', 'Se debe elegir siempre que sea posible un tenedero de fango duro, arena fangosa o arena dura, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:11.19984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d721061-82c7-470a-b1de-22cc8c52f6cb', '92173ca2-03f7-4e55-85db-11edad0fcf05', 'b', 'La embarcación debe disponer de una línea de fondeo cuya longitud será cuatro veces su eslora.', false, '2025-09-13 13:53:11.199986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43712dc5-0ead-472e-906d-f7113e71c01e', '4c222f1d-7f9d-4022-9a4e-3dc8fc75fd9c', 'd', 'La parte del costado izquierdo donde la manga va disminuyendo para cerrar y formar la popa del barco.', false, '2025-09-13 13:53:11.198072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e48c0d0-3906-446b-a3e1-4c0fd5b9ff68', '4c222f1d-7f9d-4022-9a4e-3dc8fc75fd9c', 'a', 'La parte del costado derecho donde la manga va disminuyendo para cerrar y formar la popa del barco.', true, '2025-09-13 13:53:11.197661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d76a4b35-dc21-490d-95ae-d2d4c99f672f', '92173ca2-03f7-4e55-85db-11edad0fcf05', 'c', 'El punto de fondeo debe elegirse de forma que en un círculo de radio como mínimo igual a la longitud de la cadena filada se mantenga libre de obstáculos.', false, '2025-09-13 13:53:11.20012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('783ec4f7-12e0-4532-bbec-41cde4b98bab', '92173ca2-03f7-4e55-85db-11edad0fcf05', 'd', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de gobierno, de través al', true, '2025-09-13 13:53:11.200273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7f6ac9f-ccad-4ad3-9b33-6bfbdfe9abbf', '9bd3bc5d-bdf6-4d6f-9ef3-a40e1b3ca7a1', 'a', 'Permite determinar la profundidad.', false, '2025-09-13 13:53:11.200557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a4e350b-4f14-4edf-9aa3-81f71adbfb70', '9bd3bc5d-bdf6-4d6f-9ef3-a40e1b3ca7a1', 'b', 'Es obligatorio en todas las embarcaciones.', false, '2025-09-13 13:53:11.200689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('714dd52a-0df6-4b4f-b766-c8eb30d88f47', '9bd3bc5d-bdf6-4d6f-9ef3-a40e1b3ca7a1', 'c', 'Permite a la embarcación ser más detectable.', true, '2025-09-13 13:53:11.20082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35949def-0f78-4aa5-b020-a7aee6715547', '9bd3bc5d-bdf6-4d6f-9ef3-a40e1b3ca7a1', 'd', 'Determina la posición exacta de otras embarcaciones.', false, '2025-09-13 13:53:11.20095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1503219-ab92-4d27-a198-35d7a3b5a102', '8634964c-f75a-41ec-a7e4-75aef8aaabff', 'a', '3 bengalas de mano.', false, '2025-09-13 13:53:11.201222+00');
