INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ff7f120-a61a-4918-805c-705dd29e8878', '69fdd7ba-058b-417d-91ea-b99838c1c98f', 'd', 'Si tienen marca de tope será un aspa amarilla.', false, '2025-09-13 13:53:11.207291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41e46e04-a2d7-4111-aa78-f3ca5c37d1a5', 'f9ead405-c2de-4387-9368-ef0c5b4720ba', 'a', 'La embarcación estaría entrando en una zona de peligro aislado.', true, '2025-09-13 13:53:11.207564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a450e1d-d459-41cc-a3e7-8a1a701f7718', 'f9ead405-c2de-4387-9368-ef0c5b4720ba', 'b', 'La embarcación estaría saliendo de puerto por dentro del canal.', false, '2025-09-13 13:53:11.2077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9771e3dd-5b23-4ebc-830d-988fd1daa035', 'f9ead405-c2de-4387-9368-ef0c5b4720ba', 'c', 'La embarcación estaría entrando en puerto por dentro del canal.', false, '2025-09-13 13:53:11.207863+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76e15a28-3c87-4cd1-97de-fbaa17345815', 'c43b3022-9186-41ee-9fb4-54d0ed121965', 'a', 'Las Reglas relativas a las marcas deberán cumplirse de día.', false, '2025-09-13 13:53:11.208287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('963ae438-283e-45e3-84d3-f1eb2fabca2c', 'c43b3022-9186-41ee-9fb4-54d0ed121965', 'b', 'Las Reglas relativas a las marcas deberán cumplirse las 24h.', true, '2025-09-13 13:53:11.208455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63b8fbd0-adc3-4e35-80c1-2f154a54b53f', 'c43b3022-9186-41ee-9fb4-54d0ed121965', 'c', 'Las Reglas relativas a luces y marcas deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:11.208603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac35c992-e930-4f8b-9f03-cc341795547f', 'c43b3022-9186-41ee-9fb4-54d0ed121965', 'd', 'Las Reglas relativas a luces deberán cumplirse desde la puesta de sol hasta su salida.', false, '2025-09-13 13:53:11.208745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae83d0ce-92c5-40e3-be22-8ae557a761cb', '0412efd0-a4ec-450d-ab13-5dbfcec33c32', 'a', 'Únicamente en condiciones de buena visibilidad.', true, '2025-09-13 13:53:11.209048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9762c920-db28-4e4d-aa33-c23b47cbf379', '0412efd0-a4ec-450d-ab13-5dbfcec33c32', 'b', 'Sólo a los buques de pesca que se encuentren pescando muy cerca unos de otros, en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.209188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73472f19-d785-4fa7-a5ba-f998791573bb', '0412efd0-a4ec-450d-ab13-5dbfcec33c32', 'c', 'Únicamente en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.20932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7d47ad4-9911-4a88-a9c7-ce6c0a099385', '0412efd0-a4ec-450d-ab13-5dbfcec33c32', 'd', 'En cualquier condición de visibilidad.', false, '2025-09-13 13:53:11.20945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('561740e9-3138-43b8-bad4-12aa70317699', 'c7cedee4-06be-4833-a96d-108fb146f1d4', 'a', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.209837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fe9524b-0327-45b5-9290-ef6124aa8b47', 'c7cedee4-06be-4833-a96d-108fb146f1d4', 'b', 'Un buque de vela utilizando el motor como máquina propulsora.', false, '2025-09-13 13:53:11.209991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37827318-1fd0-4c87-8c60-6497f33e84d5', 'c7cedee4-06be-4833-a96d-108fb146f1d4', 'c', 'Un hidroavión.', false, '2025-09-13 13:53:11.210142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cb002f2-a2ad-457c-b914-1336ac373a38', 'c7cedee4-06be-4833-a96d-108fb146f1d4', 'd', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.210303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a2bedce-fc20-4c9b-80b6-f76fa5f3851f', 'f6625dae-baf8-493c-9a55-d8b83d51d8bd', 'a', 'Se aplica a los buques de propulsión mecánica que se encuentren a la vista uno del otro.', false, '2025-09-13 13:53:11.210645+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a7aa1ec-431c-4f6b-9b2e-49fc5bb31aa9', 'f6625dae-baf8-493c-9a55-d8b83d51d8bd', 'b', 'Se aplica a los buques de vela dentro de una zona de visibilidad reducida.', false, '2025-09-13 13:53:11.210811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41360feb-fb02-4395-8991-82f6587f8035', 'f9ead405-c2de-4387-9368-ef0c5b4720ba', 'd', 'La embarcación navegaría fuera del canal saliendo de puerto.', false, '2025-09-13 13:53:11.207995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6ca131b-17a2-4708-b5ad-f32a3dbe8540', 'f6625dae-baf8-493c-9a55-d8b83d51d8bd', 'c', 'Se aplica a los buques de gran tonelaje sólo cuando la zona de visibilidad reducida está balizada.', true, '2025-09-13 13:53:11.210967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db4b9fbe-36b9-422e-9620-9af3888a821a', 'f6625dae-baf8-493c-9a55-d8b83d51d8bd', 'd', 'Los buques deben suprimir su arrancada al entrar en una zona de visibilidad reducida.', false, '2025-09-13 13:53:11.211136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26d08e19-d379-4aba-a2a4-79d979c106ac', '9a11bbdd-e85f-4779-8509-4384329cf8c5', 'a', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por estribor se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:11.211452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('550568ad-bf15-4ab8-940d-bd126dc066f0', '9a11bbdd-e85f-4779-8509-4384329cf8c5', 'b', 'Si un buque que recibe el viento por estribor avista a otro buque por barlovento y no puede determinar con certeza si el otro buque recibe el viento por babor o estribor, se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:11.211592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94ef318b-bfc9-49a4-bf57-0e0b7b28c0cf', '9a11bbdd-e85f-4779-8509-4384329cf8c5', 'c', 'Si un buque que recibe el viento por babor avista a otro buque por barlovento y no puede determinar con certeza si el otro buque recibe el viento por babor o estribor, mantendrá siempre rumbo y velocidad.', false, '2025-09-13 13:53:11.211728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dada06e-0261-4238-b9d7-2afe91e0b414', '9a11bbdd-e85f-4779-8509-4384329cf8c5', 'd', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a barlovento se mantendrá apartado de la derrota del que esté a sotavento.', true, '2025-09-13 13:53:11.211869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41f072b1-ef92-494a-9538-bfc2ecf0037d', 'b7981c30-5609-4ca4-815e-3d5b89858726', 'a', 'Amarilla de las mismas características que la luz de alcance.', true, '2025-09-13 13:53:11.212152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47e93791-44b8-4753-bd45-c689d80910a9', 'b7981c30-5609-4ca4-815e-3d5b89858726', 'b', 'Amarilla de las mismas características que la luz de tope.', false, '2025-09-13 13:53:11.212285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de5c36ef-145f-4030-80b6-5a65e0f2d575', 'b7981c30-5609-4ca4-815e-3d5b89858726', 'c', 'Blanca de las mismas características que la luz todo horizonte.', false, '2025-09-13 13:53:11.212418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eca533b-fbe2-4d2d-80c2-c68e998e39bc', 'b7981c30-5609-4ca4-815e-3d5b89858726', 'd', 'Blanca que muestra luz centelleante.', false, '2025-09-13 13:53:11.212549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0575fff3-acc8-4b6c-9da8-14125fca9546', 'd2b530d5-7d44-4d57-b7a5-9d3f686a9c9c', 'a', 'Un trozo de lona de color naranja con un cuadrado negro y un círculo, u otro símbolo pertinente.', true, '2025-09-13 13:53:11.212875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b42f1663-1c9e-484c-8735-75a376da69ac', 'd2b530d5-7d44-4d57-b7a5-9d3f686a9c9c', 'b', 'Una marca cónica adherida al casco de la embarcación.', false, '2025-09-13 13:53:11.213019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07756181-3d01-45c5-a596-0f86fe13aee4', 'd2b530d5-7d44-4d57-b7a5-9d3f686a9c9c', 'd', 'Una luz roja centelleante dispuesta sobre la cubierta de la embarcación.', false, '2025-09-13 13:53:11.213286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c8fa4bc-c424-4077-9e10-8db639b7acc4', 'bfe26a24-70bb-4f7e-93c0-3c0e69062a7c', 'a', 'Una embarcación de práctico.', false, '2025-09-13 13:53:11.213559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f22d5cc-04d9-448e-afbf-055cbd6b0de6', 'bfe26a24-70bb-4f7e-93c0-3c0e69062a7c', 'b', 'Una embarcación de remo.', false, '2025-09-13 13:53:11.213688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('999a58be-8da7-48ca-8a76-50776da9b63d', 'bfe26a24-70bb-4f7e-93c0-3c0e69062a7c', 'c', 'Un buque remolcando.', true, '2025-09-13 13:53:11.213817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d848c34-eff9-43ba-bf26-e0d9b78c5a8e', 'bfe26a24-70bb-4f7e-93c0-3c0e69062a7c', 'd', 'Un buque remolcado.', false, '2025-09-13 13:53:11.213945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3581452e-93f4-4e54-b89f-1a0170ed2c3e', 'a3186c43-b6d7-4c13-ad77-b9c0752e8ce5', 'a', 'La eslora en la flotación.', false, '2025-09-13 13:53:11.214214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c8302b5-fc74-40c8-a870-bd4d84db0b22', 'a3186c43-b6d7-4c13-ad77-b9c0752e8ce5', 'b', 'La eslora total del buque.', false, '2025-09-13 13:53:11.214344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58796a14-5c5d-491f-9df4-f1169c7a5bcf', 'a3186c43-b6d7-4c13-ad77-b9c0752e8ce5', 'c', 'La eslora entre perpendiculares.', true, '2025-09-13 13:53:11.214472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28c4f4cc-b124-4182-9370-ca41c236e534', 'a3186c43-b6d7-4c13-ad77-b9c0752e8ce5', 'd', 'La eslora al 80% del calado máximo.', false, '2025-09-13 13:53:11.2146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b94f0daa-4a4c-4e23-b49b-c23b340aa2e0', 'd6ed6a26-edc8-43fd-a6b0-3e3149370e82', 'a', 'Será la necesaria para llegar a destino a la hora estimada de llegada.', false, '2025-09-13 13:53:11.214981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4d4b983-e78c-4f0a-a043-d30e333f8110', 'd6ed6a26-edc8-43fd-a6b0-3e3149370e82', 'b', 'No vendrá determinada en ningún caso por la maniobrabilidad del buque.', false, '2025-09-13 13:53:11.21512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b11583cb-dfb9-4304-8d17-22266587fbe4', 'd6ed6a26-edc8-43fd-a6b0-3e3149370e82', 'c', 'Es independiente del estado de visibilidad.', true, '2025-09-13 13:53:11.215253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91a2219c-4b4e-4775-8612-71622d3549bd', 'd6ed6a26-edc8-43fd-a6b0-3e3149370e82', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje. Maniobra y navegación.', false, '2025-09-13 13:53:11.215383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26b0fdf2-6e46-4a0b-ad52-d594affbe83b', '545ab4f2-6e9b-49e9-b3c6-74097938be11', 'a', 'Amarrar por seno.', false, '2025-09-13 13:53:11.215672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cab63437-8dfd-4914-a862-d7ad6ff959bf', '545ab4f2-6e9b-49e9-b3c6-74097938be11', 'b', 'Tomar vueltas.', false, '2025-09-13 13:53:11.215833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3d31527-7421-43a4-bf27-7ac6ffd81e3c', '545ab4f2-6e9b-49e9-b3c6-74097938be11', 'c', 'Acotar.', false, '2025-09-13 13:53:11.215987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cae8fff-3cf1-45d3-80b3-c0692f5e1b9a', '545ab4f2-6e9b-49e9-b3c6-74097938be11', 'd', 'Adujar.', true, '2025-09-13 13:53:11.216124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31c80aea-440b-4e9c-8588-722186684764', '57c64612-2a39-4d82-ad9a-9ef835e1eb77', 'a', 'Dando avante poca, rueda a estribor y el esprín de proa firme.', false, '2025-09-13 13:53:11.216407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc14f7f4-fa7f-4c20-8e9b-c100cfb5cbae', '57c64612-2a39-4d82-ad9a-9ef835e1eb77', 'b', 'Dando atrás poca y con el esprín de popa firme.', false, '2025-09-13 13:53:11.216541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8312713-b5df-45a6-996d-5310859b3a59', '57c64612-2a39-4d82-ad9a-9ef835e1eb77', 'c', 'Sin emplear máquina ni timón, iremos lascando poco a poco el largo de popa.', false, '2025-09-13 13:53:11.216674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12858b6b-e1db-487c-8e49-eff48d609fa4', '27c5ab94-cab6-444a-a23f-9f82c3ce7dfb', 'a', 'Desnudar la zona afectada, limpiar la quemadura con agua fría, romper las ampollas y recortar con cuidado los tejidos muertos o desgarrados.', false, '2025-09-13 13:53:11.21709+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8deee287-744d-4f98-b2c9-5b511030421c', '27c5ab94-cab6-444a-a23f-9f82c3ce7dfb', 'b', 'Cubrir la quemadura, una vez limpia, con gasas grasas y un vendaje que comprima.', false, '2025-09-13 13:53:11.217224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('332c62ac-d3de-4f97-9d18-34c8318b1f09', '27c5ab94-cab6-444a-a23f-9f82c3ce7dfb', 'c', 'Inmovilizar la zona, si la quemadura afecta a una articulación y es al menos de 2º grado, y administrar un antibiótico para prevenir la infección.', true, '2025-09-13 13:53:11.217356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db6efd9b-1e7d-4a0f-8f52-e7d523ec5a8f', '27c5ab94-cab6-444a-a23f-9f82c3ce7dfb', 'd', 'Dar a beber al afectado, si está consciente, pequeños sorbos de una bebida estimulante para reponer los líquidos y un analgésico para calmar el dolor.', false, '2025-09-13 13:53:11.217492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2a59db2-ea38-42b4-9686-b2d8d0175435', 'fdf33738-0c2e-43d5-87b6-96c9d81b4ce9', 'a', 'Siempre se ha de utilizar agua para apagarlo ya que es la forma más efectiva en el mar.', false, '2025-09-13 13:53:11.217786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23e1d399-0a02-4b3c-8978-4112089f2b29', 'fdf33738-0c2e-43d5-87b6-96c9d81b4ce9', 'b', 'Cuando se produce un incendio dentro de un local hay que abrir todas las puertas y aberturas para facilitar la ventilación y que salga el humo.', false, '2025-09-13 13:53:11.217955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('575ea828-f639-4507-bb02-8a7b1a17cd62', 'fdf33738-0c2e-43d5-87b6-96c9d81b4ce9', 'c', 'Cuando arde un combustible líquido siempre se ha de utilizar para apagarlo agua a presión.', true, '2025-09-13 13:53:11.218127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6e3d8a1-2832-4f64-894d-5de98990360e', 'fdf33738-0c2e-43d5-87b6-96c9d81b4ce9', 'd', 'La acción de los extintores de polvo seco consiste en separar o quitar el oxígeno del fuego deteniendo así la combustión.', false, '2025-09-13 13:53:11.218297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6ef2aa9-b801-4829-9026-a253c86c21c4', 'ab65019b-6be7-4a85-b649-38e9e7f72653', 'a', 'Abandonaremos inmediatamente la embarcación.', true, '2025-09-13 13:53:11.218636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fab824e6-1df1-4fd7-9cca-79b3d0070ec2', 'ab65019b-6be7-4a85-b649-38e9e7f72653', 'b', 'Navegaremos a toda máquina para llegar lo antes posible a puerto.', false, '2025-09-13 13:53:11.218808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('072e0e50-04d8-48a3-9076-f4bd5e5f1409', 'ab65019b-6be7-4a85-b649-38e9e7f72653', 'c', 'Pondremos en marcha todas las bombas de achique y mantendremos encendido el motor.', false, '2025-09-13 13:53:11.218973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afd3c92a-4779-49cf-badf-7279c273d273', 'ab65019b-6be7-4a85-b649-38e9e7f72653', 'd', 'Si ésta tiene grandes dimensiones, utilizaremos un espiche para taponarla y pararemos el motor. Meteorología', false, '2025-09-13 13:53:11.21914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('012efbbf-518c-4589-b3ac-5a2b5c1d5db0', 'f324f10b-00f0-4372-83cb-ec3584509efa', 'a', 'Existen 100 divisiones entre el punto de congelación y ebullición del agua.', false, '2025-09-13 13:53:11.219474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35dd976d-ae89-4c65-9d49-8a9f4b6ac8e3', 'f324f10b-00f0-4372-83cb-ec3584509efa', 'b', 'El punto de congelación del agua es el valor de referencia inferior.', false, '2025-09-13 13:53:11.219637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2013c0f-64e5-4ff1-b857-d430991800cd', 'f324f10b-00f0-4372-83cb-ec3584509efa', 'c', 'Cada grado está dividido en 100 unidades, por esto se conoce esta unidad como centígrada.', true, '2025-09-13 13:53:11.219807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13fa0779-f2ac-4129-b7e3-9c6f38fab2c1', 'f324f10b-00f0-4372-83cb-ec3584509efa', 'd', 'El punto de ebullición del agua es el valor de referencia superior.', false, '2025-09-13 13:53:11.219954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d946496-c69b-4e28-a079-29c7f4ffa5f9', 'f0f3cd68-5d91-449d-8784-511ef3749cdd', 'a', 'Comúnmente se identifica con la brisa de tierra que sopla durante la noche desde la tierra hacia el mar al enfriarse la superficie de la tierra más rápidamente que la superficie del mar.', false, '2025-09-13 13:53:11.220252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93be1378-6162-4179-b2e2-6c228e222d54', 'f0f3cd68-5d91-449d-8784-511ef3749cdd', 'b', 'Sopla de manera regular de este a oeste desde las altas presiones subtropicales hacia las bajas presiones ecuatoriales.', false, '2025-09-13 13:53:11.220494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95b54934-7fa2-431e-b8b1-a1d2e1e85683', '57c64612-2a39-4d82-ad9a-9ef835e1eb77', 'd', 'Dando avante poca, rueda a estribor y el largo de popa firme.', true, '2025-09-13 13:53:11.216808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('add3636d-d222-4f24-8d78-c3f4f2025581', 'f0f3cd68-5d91-449d-8784-511ef3749cdd', 'c', 'Desciende desde las alturas hasta el fondo de los valles producido por el deslizamiento al ras de suelo del aire frío y denso desde los elementos del relieve más altos.', false, '2025-09-13 13:53:11.220638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e230520-6287-4e4f-856c-f03e7b0ffdeb', 'f0f3cd68-5d91-449d-8784-511ef3749cdd', 'd', 'Asciende desde las zonas más bajas hacia las más altas a medida que el sol calienta el relieve.', true, '2025-09-13 13:53:11.220792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06899cb3-8c25-4afe-ae49-c8dd4e4a3bfb', 'c505414f-2420-46d1-bc7f-42f60a325153', 'a', 'Es una región donde la presión atmosférica es más alta que la del aire circundante.', false, '2025-09-13 13:53:11.221088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae8d7d9c-dd89-49b5-9003-94a15af439fe', 'c505414f-2420-46d1-bc7f-42f60a325153', 'b', 'El aire fluye hacia el interior de las borrascas y desciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.221227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e820568-0861-42e2-9c0a-b72378a47098', 'c505414f-2420-46d1-bc7f-42f60a325153', 'd', 'El proceso de formación de una borrasca se denomina ciclogénesis.', true, '2025-09-13 13:53:11.22149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b94e95bd-e714-4307-970c-b2307285cdf4', 'dfd16c98-2b1d-4f59-a43c-7b7a47327c7a', 'a', 'Cuando éste aumenta de intensidad.', false, '2025-09-13 13:53:11.221767+00');
