INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af5ca3d7-fbad-45a7-aefe-aeb9720e5236', 'f293047a-8a5b-46e4-9ffd-1ea524ddf128', 'a', 'Virar es dar vueltas al cabrestante para levar el ancla.', false, '2025-09-13 13:53:11.229218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aafe29bb-5508-4277-a533-751e6ff0876a', 'f293047a-8a5b-46e4-9ffd-1ea524ddf128', 'b', 'Filar es arriar progresivamente un cabo o cadena que está trabajando.', true, '2025-09-13 13:53:11.229376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8517613-dced-46bb-9ec0-ff98be605233', 'f293047a-8a5b-46e4-9ffd-1ea524ddf128', 'c', 'Levar es recoger, arrancar y suspender el ancla que está fondeada.', false, '2025-09-13 13:53:11.229536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30651ef5-def0-447d-9e38-970f05466f1b', 'f293047a-8a5b-46e4-9ffd-1ea524ddf128', 'd', 'Zarpar es salir un barco del lugar en que estaba atracado.', false, '2025-09-13 13:53:11.229695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3ecaa21-4664-410c-b142-310e46caed9e', 'c95238f4-53ca-4417-9ee4-009160736732', 'b', 'La bocina es el orificio que permite que el eje de la hélice gire a través del casco y entre agua para su refrigeración.', false, '2025-09-13 13:53:11.230249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecf4a038-6cc1-4558-b09b-8708eb615a93', 'c95238f4-53ca-4417-9ee4-009160736732', 'c', 'El capacete es la pieza esférica que cierra el núcleo de la hélice.', false, '2025-09-13 13:53:11.230381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4ac57a6-9cd2-4d6f-9d87-32c7eee3fce3', 'c95238f4-53ca-4417-9ee4-009160736732', 'd', 'Las palas son placas planas en las que se provoca una diferencia de velocidades del fluido entre una cara y la otra de la hélice.', true, '2025-09-13 13:53:11.23051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d9b8e74-bc26-4a89-9a3e-f95c38056a14', '99dbd486-e89f-43de-8bf4-da4d89e291a0', 'a', 'Escorar es desviarse una embarcación de su rumbo por el impulso del viento o de una corriente.', false, '2025-09-13 13:53:11.231467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62194685-3d04-4bcb-bd7a-082813f96a56', '99dbd486-e89f-43de-8bf4-da4d89e291a0', 'b', 'Adrizar es poner derecha o vertical una embarcación que estaba inclinada.', false, '2025-09-13 13:53:11.231606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cc7d180-b67b-4b80-a918-b458380b837f', 'c505414f-2420-46d1-bc7f-42f60a325153', 'c', 'A escala sinóptica el aire circula en torno a una depresión en sentido horario en el hemisferio norte.', false, '2025-09-13 13:53:11.221362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29fba8f5-f190-4267-9b26-77144ffac7cc', 'dfd16c98-2b1d-4f59-a43c-7b7a47327c7a', 'd', 'Cuando éste refresca y cae su temperatura.', false, '2025-09-13 13:53:11.222238+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0b5f6ee-275e-4143-a840-747aafd9e3e7', '9fa9683a-12fc-4c2e-86bf-534ce3e1bd95', 'd', 'Abatimiento.', false, '2025-09-13 13:53:11.22604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd1ad32f-5cfe-4375-b24f-4b6694ecd3a3', '99dbd486-e89f-43de-8bf4-da4d89e291a0', 'd', 'Sotavento es la parte de donde viene el viento, con respecto a un punto o lugar determinado. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.231905+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7164f9ac-ed6f-483d-aae9-721321d99b57', 'bc251787-563b-40cc-bc58-444e049335aa', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no ha garreado, y vigilar la sonda marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:11.232314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('faeea6af-2e4d-40cf-a5c5-cf1398a3d8d2', 'bc251787-563b-40cc-bc58-444e049335aa', 'c', 'La embarcación debe disponer de una línea de fondeo cuya longitud será tres veces su eslora.', false, '2025-09-13 13:53:11.232444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46c983a9-a963-4985-9ef9-d8c693aff1a6', 'bc251787-563b-40cc-bc58-444e049335aa', 'd', 'Si optamos por el fondeo a la gira, utilizaremos dos anclas de forma que las líneas de fondeo formen un ángulo de entre 90º y 120º.', true, '2025-09-13 13:53:11.232581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6035a9d5-d8c7-4fed-82d4-264b46858a1e', '5a19d0d4-e056-4aaf-b7a6-708a0aa5457d', 'a', 'Firme.', true, '2025-09-13 13:53:11.232856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efc0943d-24bf-4d4f-9af2-605a864c72dc', '5a19d0d4-e056-4aaf-b7a6-708a0aa5457d', 'b', 'Chicote.', false, '2025-09-13 13:53:11.232989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2da1d3d6-b810-4cf4-932c-02e6bcecb9aa', '5a19d0d4-e056-4aaf-b7a6-708a0aa5457d', 'c', 'Gaza.', false, '2025-09-13 13:53:11.233116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a0af2a0-3e21-47ef-a55a-7bee733910f0', '5a19d0d4-e056-4aaf-b7a6-708a0aa5457d', 'd', 'Seno.', false, '2025-09-13 13:53:11.233245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c5ed5d1-f171-4bb5-a208-87c000bf05bb', 'e5cfaa3d-14c9-4a5e-82d0-dae0155bee6c', 'a', 'Existe una mayor maniobrabilidad al aumentar la sonda.', false, '2025-09-13 13:53:11.23351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('326a402d-bc6b-44f7-b310-943beb806b4f', 'e5cfaa3d-14c9-4a5e-82d0-dae0155bee6c', 'b', 'Navegaremos con mayor seguridad llevando la mar por la amura.', false, '2025-09-13 13:53:11.233639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9888d732-938c-4f78-ada9-1b410b26176f', 'e5cfaa3d-14c9-4a5e-82d0-dae0155bee6c', 'c', 'Navegaremos con mayor seguridad aumentando la velocidad.', false, '2025-09-13 13:53:11.233766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfaf3c2a-9ce7-43d5-95a0-dfe2cfd940b7', 'e5cfaa3d-14c9-4a5e-82d0-dae0155bee6c', 'd', 'La maniobrabilidad no se ve afectada.', true, '2025-09-13 13:53:11.233895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('816a0c48-bdbd-433a-a788-b8fd1ae7f9be', '2c140e6c-1dc0-414b-b599-8f85e7a13dda', 'a', 'Por vía telefónica llamando al 900 222 222.', false, '2025-09-13 13:53:11.234162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8afdd8ca-ff78-48a6-a5df-e11e09b8a0ea', '2c140e6c-1dc0-414b-b599-8f85e7a13dda', 'b', 'Únicamente por vía telefónica llamando al 900 202 202 o al 112.', true, '2025-09-13 13:53:11.23429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90f17b14-234f-4954-9026-817d5a00960d', '2c140e6c-1dc0-414b-b599-8f85e7a13dda', 'c', 'Exclusivamente con el uso de la estación de radio a bordo.', false, '2025-09-13 13:53:11.234437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc69e2b5-66c6-4a32-af37-f93f47b25f0f', '2c140e6c-1dc0-414b-b599-8f85e7a13dda', 'd', 'Por vía telefónica o con el uso de la estación de radio a bordo.', false, '2025-09-13 13:53:11.234566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b08d5626-5fb7-45fd-b5b6-f652125512bc', '51bfcc02-ef16-4fa4-984c-41a6aecea67f', 'a', 'Cuando la frecuencia del movimiento de balance es alta.', false, '2025-09-13 13:53:11.234955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbfa5b59-d145-49bf-a3b6-05965bdf8aff', '51bfcc02-ef16-4fa4-984c-41a6aecea67f', 'b', 'Cuando la frecuencia del movimiento de balance es baja o casi nula.', false, '2025-09-13 13:53:11.235087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('130662ec-811c-4b28-b734-ecc15f242343', '51bfcc02-ef16-4fa4-984c-41a6aecea67f', 'c', 'Cuando la frecuencia del movimiento de cabezada es alta.', false, '2025-09-13 13:53:11.235225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17827292-c18b-49bb-8ee9-e8bd2ee44869', '51bfcc02-ef16-4fa4-984c-41a6aecea67f', 'd', 'Cuando la frecuencia del movimiento de cabezada es baja o casi nula.', true, '2025-09-13 13:53:11.235355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('710ade85-5be4-4d04-91cd-df1058c67c0e', '3dce484f-bf5a-4c3a-a9f4-bb06aaeb55a3', 'a', '50 N.', false, '2025-09-13 13:53:11.235634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5178ef67-45d3-48dc-be9d-b2633cbb1d4c', '3dce484f-bf5a-4c3a-a9f4-bb06aaeb55a3', 'b', '100 N.', false, '2025-09-13 13:53:11.235776+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7ddf9c3-4918-47e6-9a6d-dd93e482a8a1', '3dce484f-bf5a-4c3a-a9f4-bb06aaeb55a3', 'c', '150 N.', true, '2025-09-13 13:53:11.235938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4882c8c-ad51-4a12-a2b0-96ecc4400e5c', '3dce484f-bf5a-4c3a-a9f4-bb06aaeb55a3', 'd', '275 N.', false, '2025-09-13 13:53:11.236071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cf40d33-bbdf-4363-ac07-e5e2426f5ba9', 'b909bdfd-0ee8-4ec4-a450-f38f0c2035be', 'a', 'Entre las medidas legales adoptadas se establecen limitaciones al fondeo de embarcaciones para evitar que malas técnicas de fondeo arrastren y barran el fondo marino arrancando matas, deteriorando las praderas de posidonia.', false, '2025-09-13 13:53:11.236355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b663afe3-e721-434d-8d09-169a27ac8ff7', 'b909bdfd-0ee8-4ec4-a450-f38f0c2035be', 'b', 'La única medida adoptada en España es cartografiar y catalogar las praderas e insertar esos datos en sistemas de información accesibles a los navegantes y al público en general y, en la medida de lo posible, en las cartas náuticas.', true, '2025-09-13 13:53:11.236485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('719bc50d-370f-4a8f-8ba0-d1d7b9d999a8', 'b909bdfd-0ee8-4ec4-a450-f38f0c2035be', 'c', 'Todavía no existe normativa concreta, sólo recomendaciones de las consejerías de pesca y medio ambiente de las diferentes comunidades autónomas sobre cómo actuar allí donde se localizan las praderas de posidonia.', false, '2025-09-13 13:53:11.236621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3208b4b7-449e-4c42-810d-fd1a5be245d5', 'b909bdfd-0ee8-4ec4-a450-f38f0c2035be', 'd', 'No hay normativa específica ni limitación alguna para fondear sobre praderas de posidonia, pero un navegante responsable con el medio ambiente, antes de fondear, debería observar el fondo marino por su propia cuenta para procurar no dañar la posidonia.', false, '2025-09-13 13:53:11.23675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c727ee3-be96-445c-ac07-6c28ac68cc67', 'afecf420-439b-4bec-a3f1-95826c0658f1', 'a', 'Podrá fondear con finalidad exclusiva de recreo y en esa zona deberá navegar a una velocidad no superior a 3 nudos.', true, '2025-09-13 13:53:11.237033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cdeb78d-6588-4ddc-bfcd-4daa0afc6775', 'afecf420-439b-4bec-a3f1-95826c0658f1', 'b', 'No podrá continuar la navegación. Deberá fondear y avisar a los servicios de salvamento para que lo remolquen con seguridad.', false, '2025-09-13 13:53:11.237163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa5b36ad-0e43-457b-a6f7-61de29d33ed0', 'afecf420-439b-4bec-a3f1-95826c0658f1', 'c', 'Deberá alejarse de la zona al menos 200 metros, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:11.237291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8294f850-a319-4202-9417-f059ff436b1e', 'afecf420-439b-4bec-a3f1-95826c0658f1', 'd', 'Está absolutamente prohibida la navegación a esa distancia, al poner en peligro la seguridad de la vida humana en la mar o de la navegación.', false, '2025-09-13 13:53:11.237419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc37c2ed-f995-4135-b96d-68bb84e19846', 'b5f21e0a-65f3-4c02-a2a8-0d1258dfd7fd', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', true, '2025-09-13 13:53:11.237685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34d5a08d-f88f-4e28-9bcd-fc3289b395e7', 'b5f21e0a-65f3-4c02-a2a8-0d1258dfd7fd', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:11.237816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5864b931-5d52-40e2-bb6c-fc5037cddb66', 'b5f21e0a-65f3-4c02-a2a8-0d1258dfd7fd', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.237943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3890a76-5b34-482d-a6db-63a47eca6278', 'b5f21e0a-65f3-4c02-a2a8-0d1258dfd7fd', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', false, '2025-09-13 13:53:11.238083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edc8e9cf-63d3-4cb5-a72c-9331aa08cf1b', 'f16dcfb4-6fb1-4b72-87b1-17cde5574e2e', 'a', 'De libre elección, pero que no se preste a confusión con las Marcas para ayuda a la navegación.', false, '2025-09-13 13:53:11.238351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebe6e6e8-0f0b-4580-9c06-171e68140c70', 'f16dcfb4-6fb1-4b72-87b1-17cde5574e2e', 'b', 'Franjas verticales rojas y blancas.', false, '2025-09-13 13:53:11.23861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ea93c8b-4253-4858-8b68-1d08697f58d8', 'f16dcfb4-6fb1-4b72-87b1-17cde5574e2e', 'c', 'Franjas horizontales rojas y blancas.', true, '2025-09-13 13:53:11.23874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30f95821-bde9-4489-b7aa-8ffe6587d8ea', 'f16dcfb4-6fb1-4b72-87b1-17cde5574e2e', 'd', 'Amarillo.', false, '2025-09-13 13:53:11.238879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70f9916e-cc71-46a8-b62f-816a1173e92b', 'cde1a554-ae07-4b52-b2b9-9cd9a1cc3a02', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.239145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80363d29-ef3b-44d9-ba13-68b7ee84d368', 'cde1a554-ae07-4b52-b2b9-9cd9a1cc3a02', 'b', 'Peligro nuevo.', false, '2025-09-13 13:53:11.239271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c33934f-7c1b-4246-aaa2-6c5376eb6b25', 'cde1a554-ae07-4b52-b2b9-9cd9a1cc3a02', 'c', 'Especial.', false, '2025-09-13 13:53:11.239399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a348eed2-479b-4824-8ddd-090bee302d67', 'cde1a554-ae07-4b52-b2b9-9cd9a1cc3a02', 'd', 'Lateral estribor.', false, '2025-09-13 13:53:11.239531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddf127b1-7a53-4efd-af06-54b0dd00ec3e', 'd53d1118-648d-4f8a-8663-5c0b39e0ce55', 'a', 'Nunca tienen marca de tope.', false, '2025-09-13 13:53:11.239802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0d0e8de-cc28-48b3-a47d-9dac4337d5e0', 'd53d1118-648d-4f8a-8663-5c0b39e0ce55', 'b', 'Siempre tienen marca de tope que será dos esferas negras.', false, '2025-09-13 13:53:11.239932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e3815b0-ffd7-4d9e-9b5b-d0465466ec08', 'd53d1118-648d-4f8a-8663-5c0b39e0ce55', 'd', 'Si tienen marca de tope será un aspa amarilla.', true, '2025-09-13 13:53:11.240248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1c2b792-2607-4429-a023-4ffd048b2300', '645d4ea5-7d6a-471c-95a7-dff1482e9f23', 'a', 'Por un canal principal.', false, '2025-09-13 13:53:11.240548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6b64aa8-ec13-4942-a062-f4cac7c0abd2', '645d4ea5-7d6a-471c-95a7-dff1482e9f23', 'b', 'Por un canal secundario.', false, '2025-09-13 13:53:11.240693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7126e38-4733-474c-a56a-01e91e86dbda', '645d4ea5-7d6a-471c-95a7-dff1482e9f23', 'c', 'Entre una Marca lateral y una Marca cardinal norte.', false, '2025-09-13 13:53:11.240829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2349935c-dcca-4ce2-a242-258bf06370a1', 'f50e0d34-a21f-42d6-af0e-d191152aefdc', 'a', 'Dos pitadas cortas.', false, '2025-09-13 13:53:11.241239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d07f1e3-82c3-4f7f-941e-20ccdfa58048', 'f50e0d34-a21f-42d6-af0e-d191152aefdc', 'b', 'Dos pitadas largas.', true, '2025-09-13 13:53:11.241369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6eeda901-bc68-4e14-b045-d537f0b7f81a', 'd53d1118-648d-4f8a-8663-5c0b39e0ce55', 'c', 'Pueden tener marca de tope.', false, '2025-09-13 13:53:11.240088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('191752da-979d-4f9f-906a-09b1d35df88f', 'bc251787-563b-40cc-bc58-444e049335aa', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:11.232175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c396ddb-6f7d-403d-963c-20dc9f534f28', '645d4ea5-7d6a-471c-95a7-dff1482e9f23', 'd', 'Entre una Marca lateral modificada y una Marca cardinal norte.', true, '2025-09-13 13:53:11.240963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('425b0b44-8be6-4943-b58e-552338671cd5', 'c8d25faa-9d2c-4123-92c6-cbbe956b4bab', 'a', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.241932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1752a14-6759-41bd-9d51-6321b06a0a38', 'c8d25faa-9d2c-4123-92c6-cbbe956b4bab', 'b', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', true, '2025-09-13 13:53:11.242074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('948beba4-2020-43ef-96cf-0b6b0ccbf905', 'c8d25faa-9d2c-4123-92c6-cbbe956b4bab', 'c', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.242206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92e634e1-9048-4f1b-af52-51c960e7e7f9', 'c8d25faa-9d2c-4123-92c6-cbbe956b4bab', 'd', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.242337+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27b21a68-0ac5-42b0-b94b-1728f780ccf1', 'f00f0688-a399-4c26-823e-b5d763440bea', 'a', 'Los buques de eslora inferior a 20 m.', false, '2025-09-13 13:53:11.242613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('042136de-a732-4193-8823-0476177db17d', 'f00f0688-a399-4c26-823e-b5d763440bea', 'b', 'Los buques de vela.', false, '2025-09-13 13:53:11.242748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e531d0f-e908-4952-8f9b-b97316617214', 'f00f0688-a399-4c26-823e-b5d763440bea', 'c', 'Los buques que puedan navegar con seguridad por la vía de circulación adecuada de un dispositivo de separación de tráfico.', true, '2025-09-13 13:53:11.242886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0e07086-46a7-41dc-9a69-1e6646e3b2b2', 'f00f0688-a399-4c26-823e-b5d763440bea', 'd', 'Los buques dedicados a la pesca.', false, '2025-09-13 13:53:11.243013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('288fd1e1-7686-4fa3-8542-5c74439c6967', 'e89abc48-c70f-4fa8-93ff-da6badf79fee', 'b', 'El buque que tenga al otro por su costado de babor maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.243415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea29e289-bf8d-4270-8c78-ad0711d1f0d5', 'e89abc48-c70f-4fa8-93ff-da6badf79fee', 'c', 'Ambos buques maniobrarán, si las circunstancias lo permiten, eligiendo siempre maniobras que eviten cortarle la proa al otro buque.', true, '2025-09-13 13:53:11.243674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44cae86a-6887-414c-b307-b6870bae79b6', 'e89abc48-c70f-4fa8-93ff-da6badf79fee', 'd', 'Dado que todo buque está obligado a mantenerse apartado de la derrota de otro buque, los buques realizarán maniobras simétricas.', false, '2025-09-13 13:53:11.243821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9ad6949-a213-43b2-a96f-017085c74c5b', '056a8cd1-3744-4260-99d5-5862360097f5', 'a', 'Una luz amarilla.', false, '2025-09-13 13:53:11.244128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d990505-4dbb-4b23-9e7f-7a8e5d630ac9', '056a8cd1-3744-4260-99d5-5862360097f5', 'b', 'Una luz verde.', false, '2025-09-13 13:53:11.244262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7616632-558c-4429-a3fd-ff08ea01e579', '056a8cd1-3744-4260-99d5-5862360097f5', 'c', 'Una luz roja.', true, '2025-09-13 13:53:11.244394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f261fcf0-f996-4938-9b23-17a3cce94a42', '056a8cd1-3744-4260-99d5-5862360097f5', 'd', 'Una luz blanca.', false, '2025-09-13 13:53:11.244529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0538270a-f479-4a2f-8b18-9b9e0dcf3d32', '1bcb78bd-d40b-4ecf-8e89-27a5bc8e193f', 'a', 'Solamente a los buques sin gobierno.', false, '2025-09-13 13:53:11.244804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d7886c1-cf2e-4d44-a43f-cd3f6aaaa22a', '1bcb78bd-d40b-4ecf-8e89-27a5bc8e193f', 'b', 'En cualquier condición de visibilidad.', false, '2025-09-13 13:53:11.244936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee174383-e0e7-4965-b20f-5f744183e8a5', '1bcb78bd-d40b-4ecf-8e89-27a5bc8e193f', 'c', 'Sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.245065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a5869a9-11aa-4ba3-a57b-36c1e20c1023', '1bcb78bd-d40b-4ecf-8e89-27a5bc8e193f', 'd', 'Sólo a los buques restringidos por su calado.', true, '2025-09-13 13:53:11.245195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d0387b0-3f62-4d70-bd4c-69c7e1703627', '64f649ab-ba44-4c91-9e97-d69cfac817c5', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', true, '2025-09-13 13:53:11.245473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7374369-6325-447d-b95c-2f1d9da1da12', '64f649ab-ba44-4c91-9e97-d69cfac817c5', 'b', 'Se considerará que tal situación existe cuando un buque no vea a otro por su proa.', false, '2025-09-13 13:53:11.245602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0964e8d-a67e-44d1-a9f1-73b240924b6e', '64f649ab-ba44-4c91-9e97-d69cfac817c5', 'd', 'De noche, vería las luces de costado y la luz de alcance.', false, '2025-09-13 13:53:11.245867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14354835-81df-48a4-b88c-c6e3990a46a4', '86a2112d-dc8c-4f56-b7ca-f47dd0de60ac', 'a', 'Los buques de propulsión mecánica tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:11.246136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddad860c-decb-43fb-b650-2b6450639583', '86a2112d-dc8c-4f56-b7ca-f47dd0de60ac', 'b', 'Todos los buques navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:11.246265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76c6deba-9225-470a-b94d-1b251439177e', '86a2112d-dc8c-4f56-b7ca-f47dd0de60ac', 'c', 'Es de aplicación a los buques que estén a la vista uno del otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.246397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c4936fe-9a84-403e-9609-1037cfb447f4', '86a2112d-dc8c-4f56-b7ca-f47dd0de60ac', 'd', 'Todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, deberá reducir su velocidad hasta la mínima de su gobierno.', false, '2025-09-13 13:53:11.246525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19e26944-fca5-4589-abe4-5fd1cfbac0de', '8e873d70-633c-4b36-9c6f-337a5fdfd889', 'b', 'Todo buque dedicado a operaciones de remolque que por su naturaleza restrinja fuertemente al buque remolcador y su remolque en su capacidad para apartarse de su derrota.', false, '2025-09-13 13:53:11.246931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ad763be-eafe-4411-aab4-f974e3cb40eb', '8e873d70-633c-4b36-9c6f-337a5fdfd889', 'c', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', false, '2025-09-13 13:53:11.247062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1041909-ceaa-4fa0-9b4c-69eb662d9553', '8e873d70-633c-4b36-9c6f-337a5fdfd889', 'd', 'Todo buque dedicado a dragados, trabajos hidrográficos, oceanográficos u operaciones', false, '2025-09-13 13:53:11.247191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4c374df-a555-4684-b327-7ea2738130ca', '76c50aed-610b-4ef1-9d07-6fd3d8211a76', 'b', 'Quedándonos estáticos en cubierta, con el brazo izquierdo extendido hacia arriba.', false, '2025-09-13 13:53:11.247589+00');
