INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('624df223-f7bc-4906-9559-2ccf24baf7e9', '52557a97-54d7-428e-9a5a-793c207aa4ee', 'a', 'Es una región donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:11.253847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91e9a681-d67d-4633-8f32-fa7dcde416e5', '52557a97-54d7-428e-9a5a-793c207aa4ee', 'b', 'El aire desciende por el interior de los anticiclones y fluye hacia afuera desde ellos.', true, '2025-09-13 13:53:11.253977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01536f16-4555-46b0-8bc9-637c15c48f74', '52557a97-54d7-428e-9a5a-793c207aa4ee', 'c', 'La presión más alta se localiza siempre en el centro.', false, '2025-09-13 13:53:11.25411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1b7cc75-6092-4aea-8cb1-a7ece96192aa', 'bca7743f-d2cc-4629-88cb-e73a45a8b7b3', 'a', 'Dividiendo el coeficiente entre la velocidad de corredera se obtiene la velocidad real.', false, '2025-09-13 13:53:11.254511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e851ff5-8248-4679-97a6-5591fcb06178', 'bca7743f-d2cc-4629-88cb-e73a45a8b7b3', 'b', 'Multiplicando el coeficiente por la velocidad real se obtiene la velocidad de corredera.', false, '2025-09-13 13:53:11.254646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23e9ae9c-3fb3-4482-953b-7b194272970e', 'bca7743f-d2cc-4629-88cb-e73a45a8b7b3', 'c', 'Multiplicando el coeficiente por la velocidad de corredera se obtiene la velocidad real.', true, '2025-09-13 13:53:11.254781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3684ccab-d42e-4b94-af2f-cfd8e08ba227', 'bca7743f-d2cc-4629-88cb-e73a45a8b7b3', 'd', 'Multiplicando el coeficiente por la velocidad de corredera se obtiene la amplitud de la marea.', false, '2025-09-13 13:53:11.254917+00');
