INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('993e268f-a39f-4edc-b6a0-a8599aa82d8f', '05105af2-fa41-4277-9219-013ac7c933e3', 'd', '295°. DE TRANSPORTES, MOVILIDAD                                                                           DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                     Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 03 Nomenclatura náutica.', false, '2025-09-13 13:53:11.260454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6bfc153-5226-4e87-8a1e-89c4fe3a7872', '81eb2ce2-d133-497f-8bad-a313af6802a6', 'a', 'La limera es la abertura en la bovedilla de popa, para el paso de la cabeza del timón.', false, '2025-09-13 13:53:11.260961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d6ac728-c950-42d5-b061-548f88956b7a', '81eb2ce2-d133-497f-8bad-a313af6802a6', 'b', 'La pala es la parte plana del timón que sobresale en su totalidad del agua.', true, '2025-09-13 13:53:11.261093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f059eb34-6ec7-48d1-bb03-703bdbf0328e', '81eb2ce2-d133-497f-8bad-a313af6802a6', 'c', 'El timón es la pieza plana y móvil montada en la parte posterior de una embarcación, que sirve para controlar su dirección en el plano horizontal.', false, '2025-09-13 13:53:11.261222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca338ee7-58bd-432d-97fa-33de19a9aba3', '81eb2ce2-d133-497f-8bad-a313af6802a6', 'd', 'Los guardines son los cabos, cadenas o cables que trasmiten los movimientos de la rueda del timón a la caña de mismo, para gobernar el buque.', false, '2025-09-13 13:53:11.261355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ed2f690-67a0-4ab3-8ea3-9ec1dff9cab3', '36bd5e14-fc6e-4685-b2b6-3b366c5d496e', 'a', 'La eslora es la longitud que tiene la embarcación sobre la cubierta principal, desde el codaste a la roda, por la parte de adentro.', false, '2025-09-13 13:53:11.261659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75ad1d0e-ec58-491f-94bc-b365a666314b', '36bd5e14-fc6e-4685-b2b6-3b366c5d496e', 'b', 'La manga es la anchura de la embarcación.', false, '2025-09-13 13:53:11.261801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a28e378-dcf8-455a-a829-d5ae3ecfdbac', '36bd5e14-fc6e-4685-b2b6-3b366c5d496e', 'c', 'El puntal es la altura de la embarcación desde su plan hasta la cubierta de francobordo.', true, '2025-09-13 13:53:11.261941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a733b102-e02e-4fe4-9190-841efabef9a4', '36bd5e14-fc6e-4685-b2b6-3b366c5d496e', 'd', 'El calado de un barco es la distancia vertical entre un punto de la línea de flotación y la línea base o quilla, incluido el espesor del casco.', false, '2025-09-13 13:53:11.262079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48d63de0-c942-4441-b73e-2c790bd0c775', '52557a97-54d7-428e-9a5a-793c207aa4ee', 'd', 'Se llama también alta presión o, simplemente, alta.', false, '2025-09-13 13:53:11.254239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c078d297-efe4-4ad3-86ac-916b2441d194', '677b3bed-695a-4429-9645-e145871de4b1', 'd', 'Coeficiente de marea.', false, '2025-09-13 13:53:11.257568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97d03616-113b-4b9c-9643-6497df8f921d', 'cee21c69-aa31-4b34-a24b-6748f479adb6', 'b', 'La parte del costado izquierdo donde el casco se estrecha formando la proa del barco.', false, '2025-09-13 13:53:11.263361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fdcb276-7f51-45d0-a78b-ae3d0bc5b4a0', 'cee21c69-aa31-4b34-a24b-6748f479adb6', 'c', 'La parte del costado derecho donde el casco se estrecha formando la proa del barco.', false, '2025-09-13 13:53:11.263488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2eb94686-5f86-4955-9152-3eb669c8973a', '81284e05-f683-42b9-98dc-b2ccbb1d23a2', 'a', 'Fijar las amarras de las embarcaciones cuando atracan al muelle.', false, '2025-09-13 13:53:11.264583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aae79d9-c803-4b20-99f8-0505a3fdf260', '81284e05-f683-42b9-98dc-b2ccbb1d23a2', 'b', 'Guiar la unión de dos cabos de una misma mena.', false, '2025-09-13 13:53:11.264716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b418195d-9233-44bf-9dbd-11d951d0e9bc', '81284e05-f683-42b9-98dc-b2ccbb1d23a2', 'c', 'Proteger el casco de golpes y rozaduras.', false, '2025-09-13 13:53:11.264843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6025107e-91be-4f58-bf8f-d72a666d65c3', '81284e05-f683-42b9-98dc-b2ccbb1d23a2', 'd', 'Pasar y guiar los cabos de amarre desde la embarcación hasta los elementos de amarre del muelle.', true, '2025-09-13 13:53:11.26499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41911fe3-bebf-4cc8-b735-22ab03101f6b', '1000e26f-84ce-4901-bd92-973bd79f4404', 'a', '“Capear el temporal” es recibir el oleaje por la amura.', false, '2025-09-13 13:53:11.265254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba45b6ca-67c8-4726-ab67-600a14ef144a', '1000e26f-84ce-4901-bd92-973bd79f4404', 'b', '“Correr el temporal” es recibir el oleaje por la proa.', true, '2025-09-13 13:53:11.265392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a1a5293-f6e4-4706-bc01-cfa83d60d6c9', '1000e26f-84ce-4901-bd92-973bd79f4404', 'c', 'Una maniobra válida para hacer frente a la mala mar es echar el ancla de capa o flotante.', false, '2025-09-13 13:53:11.265519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a92106a0-f557-4cad-aae9-9565e9ad055b', '1000e26f-84ce-4901-bd92-973bd79f4404', 'd', '“A son de mar” es el término referido a la correcta estiba y trincaje de los elementos a bordo para la navegación con mal tiempo.', false, '2025-09-13 13:53:11.265646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff3178ce-a558-4874-ba33-4594a6416a07', '6e623c37-f845-4821-8f72-263b3b65beec', 'a', 'Ciar inmediatamente.', false, '2025-09-13 13:53:11.265926+00');
