INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('512f0b23-4ec8-4962-a76e-3f13667ca169', '94fcf405-c164-417e-a970-a5c79b0e7ae5', 'a', 'Dedicadas exclusivamente al recreo que se detengan en calas o lugares de baño balizados como zona o lugar de baño, si fondean a menos de 50 metros de la costa.', false, '2025-09-13 13:53:11.268012+00');
