INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb4707bf-f79d-4c01-bedf-74b29b48eae8', '94fcf405-c164-417e-a970-a5c79b0e7ae5', 'd', 'Exclusivamente de recreo que se detengan con tal finalidad en calas o lugares de baño no balizados y no pongan en peligro la seguridad de la vida humana en la mar o de la navegación.', true, '2025-09-13 13:53:11.268418+00');
