INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2186b236-415f-48d1-9828-ee8ce5320541', '27c90c1c-ebc0-40c1-ae1e-947b59cefac7', 'a', 'Se aplica a los buques de propulsión mecánica que se encuentren a la vista uno del otro.', false, '2025-09-13 13:53:11.272913+00');
