INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b02b05a4-b263-43f0-bbc2-2127810810d1', '27c90c1c-ebc0-40c1-ae1e-947b59cefac7', 'd', 'Los buques deben suprimir su arrancada al entrar en una zona de visibilidad reducida.', false, '2025-09-13 13:53:11.273326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cf405fe-7d94-4098-8468-924c1e9f38a9', 'd85962e1-38c4-4e31-81c6-37b29581f9fa', 'a', 'La eslora en la flotación.', false, '2025-09-13 13:53:11.273608+00');
