INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e3dfca8-a75b-47fb-8434-cefd58f17c69', 'd85962e1-38c4-4e31-81c6-37b29581f9fa', 'c', 'La eslora entre perpendiculares.', false, '2025-09-13 13:53:11.273915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23108a7c-46d7-4564-9ff6-120fede4b801', 'd85962e1-38c4-4e31-81c6-37b29581f9fa', 'd', 'La eslora al 80% del calado máximo.', false, '2025-09-13 13:53:11.274058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a68d62b3-56c3-4eba-b735-05fb174a4470', '8a5708b7-bbd1-4c63-af64-8db0dbc41017', 'a', 'Será la necesaria para llegar a destino a la hora estimada de llegada.', false, '2025-09-13 13:53:11.274349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c6ae008-13b8-43d4-95ac-e57f52d662ee', '8a5708b7-bbd1-4c63-af64-8db0dbc41017', 'b', 'No vendrá determinada en ningún caso por la maniobrabilidad del buque.', false, '2025-09-13 13:53:11.274485+00');
