INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d507c85-e333-4502-9b4a-ba6a0f0ca275', '8a5708b7-bbd1-4c63-af64-8db0dbc41017', 'd', 'Será la que le permita al buque ejecutar la maniobra adecuada y eficaz para evitar el abordaje.', true, '2025-09-13 13:53:11.274898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dd0e0d8-bb7f-41a4-baec-02f0572b8875', '8356f781-dfd4-445f-9cb8-a4ff06a29cf4', 'a', 'Únicamente en condiciones de buena visibilidad.', false, '2025-09-13 13:53:11.275176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f79b6865-f090-4914-b2b3-60ef02cde4b5', '8356f781-dfd4-445f-9cb8-a4ff06a29cf4', 'b', 'Sólo a los buques de pesca que se encuentren pescando muy cerca unos de otros, en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.275312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e3fb648-9045-43dc-ade9-ce0ab61c4a5c', '8356f781-dfd4-445f-9cb8-a4ff06a29cf4', 'c', 'Únicamente en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.275447+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbe1b6ad-c7e9-43e5-8d8a-0db0d21e5a2f', '8356f781-dfd4-445f-9cb8-a4ff06a29cf4', 'd', 'En cualquier condición de visibilidad.', true, '2025-09-13 13:53:11.275581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e6543c4-f922-4d3d-a34e-28eda1ff75e5', '2ef530c1-84e1-4135-9d52-509e501280a5', 'a', 'Las Reglas relativas a las marcas deberán cumplirse de día.', false, '2025-09-13 13:53:11.27586+00');
