INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('717e2b85-2a1f-4827-8777-c91ff9bd620c', '2ef530c1-84e1-4135-9d52-509e501280a5', 'c', 'Las Reglas relativas a luces y marcas deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:11.276124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f5a603a-960a-4fe7-a9ac-a0b23ccfc3dc', '2ef530c1-84e1-4135-9d52-509e501280a5', 'd', 'Las Reglas relativas a luces deberán cumplirse desde la puesta de sol hasta su salida.', false, '2025-09-13 13:53:11.276256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b952e1e9-b5af-4146-9136-7b63b3778333', '9ee328e5-c70e-45fe-acf5-f146d30d09a9', 'a', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.276531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9caaf00-aedf-439f-84dc-7673c677df01', '9ee328e5-c70e-45fe-acf5-f146d30d09a9', 'b', 'Un buque de vela utilizando el motor como máquina propulsora.', false, '2025-09-13 13:53:11.276661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74123583-868b-421e-bd74-916046537cf6', '9ee328e5-c70e-45fe-acf5-f146d30d09a9', 'c', 'Un hidroavión.', false, '2025-09-13 13:53:11.276802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56802d9e-619f-4c03-88b9-c618adf9f2ce', '9ee328e5-c70e-45fe-acf5-f146d30d09a9', 'd', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.276934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d198debf-3460-4f50-9269-e7c8da29fd1b', '709f3db1-791f-45c3-bea2-59662c2c748c', 'a', 'Cuando cada uno de ellos reciba el viento por bandas contrarias, el que lo reciba por estribor se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:11.27721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35bf859c-86e9-4ab6-8d64-a4ab78b4c71d', '709f3db1-791f-45c3-bea2-59662c2c748c', 'b', 'Si un buque que recibe el viento por estribor avista a otro buque por barlovento y no puede determinar con certeza si el otro buque recibe el viento por babor o estribor, se mantendrá apartado de la derrota del otro.', false, '2025-09-13 13:53:11.277344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36d2a27a-da7e-4993-8a52-fdb3f5272704', '709f3db1-791f-45c3-bea2-59662c2c748c', 'c', 'Si un buque que recibe el viento por babor avista a otro buque por barlovento y no puede determinar con certeza si el otro buque recibe el viento por babor o estribor, mantendrá siempre rumbo y velocidad.', false, '2025-09-13 13:53:11.277479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8760ae89-c6ce-46ec-b62a-d29c6861acf0', '709f3db1-791f-45c3-bea2-59662c2c748c', 'd', 'Cuando ambos reciban el viento por la misma banda, el buque que esté a barlovento se mantendrá apartado de la derrota del que esté a sotavento.', true, '2025-09-13 13:53:11.277613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d281b62d-9555-4c2d-b1c0-6a7a5f8ed6d3', '42298eca-3a85-4d51-bc1a-1719ab746a9f', 'a', 'Una embarcación de práctico.', true, '2025-09-13 13:53:11.277907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cb7ca1a-5ab7-4feb-a3e8-a8fec7c44680', '42298eca-3a85-4d51-bc1a-1719ab746a9f', 'b', 'Una embarcación de remo.', false, '2025-09-13 13:53:11.278042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3db0d77f-54d2-45f5-a06e-5a9906539a0d', '42298eca-3a85-4d51-bc1a-1719ab746a9f', 'c', 'Un buque remolcando.', false, '2025-09-13 13:53:11.278176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36b2cc72-22aa-4513-980b-447fbbf4c57e', '42298eca-3a85-4d51-bc1a-1719ab746a9f', 'd', 'Un buque remolcado.', false, '2025-09-13 13:53:11.278311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b4468af-a2d6-4b37-b542-f13f826d390b', '01d7ad7c-58ea-4c85-98d9-cc890b4c334a', 'a', 'Amarilla de las mismas características que la luz de alcance.', true, '2025-09-13 13:53:11.278588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78fca303-7812-48bf-994c-d070f938d8f2', '01d7ad7c-58ea-4c85-98d9-cc890b4c334a', 'b', 'Amarilla de las mismas características que la luz de tope.', false, '2025-09-13 13:53:11.27872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('418691db-6e55-4251-af80-7e3793f78436', '01d7ad7c-58ea-4c85-98d9-cc890b4c334a', 'c', 'Blanca de las mismas características que la luz todo horizonte.', false, '2025-09-13 13:53:11.278851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4393890-6da5-4283-8484-1dca52cb1b4b', '01d7ad7c-58ea-4c85-98d9-cc890b4c334a', 'd', 'Blanca que muestra luz centelleante.', false, '2025-09-13 13:53:11.27898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e92be3f-2779-421f-8a20-57765a9e6a32', '5d1eb38f-e812-433a-ae49-92452ac6be5b', 'a', 'Un trozo de lona de color naranja con un cuadrado negro y un círculo, u otro símbolo pertinente.', true, '2025-09-13 13:53:11.279253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7c017bb-bff1-45d5-9ec9-90536cc7a547', '5d1eb38f-e812-433a-ae49-92452ac6be5b', 'b', 'Una marca cónica adherida al casco de la embarcación.', false, '2025-09-13 13:53:11.279519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d604798a-d623-43a0-8aba-b80b9d8ed4ec', '894c85b4-bfc5-49d4-b395-c1c23bdeee92', 'a', 'Amarrar por seno.', false, '2025-09-13 13:53:11.280098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f592a4ab-50fb-4cde-bab9-b11e88348fb8', '894c85b4-bfc5-49d4-b395-c1c23bdeee92', 'b', 'Tomar vueltas.', true, '2025-09-13 13:53:11.280231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('faf8abd3-a48d-4d11-bff5-441ea2939a29', '894c85b4-bfc5-49d4-b395-c1c23bdeee92', 'c', 'Acotar.', false, '2025-09-13 13:53:11.280366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20c78d65-0883-4b59-8565-b7231cbd55ca', '894c85b4-bfc5-49d4-b395-c1c23bdeee92', 'd', 'Adujar.', false, '2025-09-13 13:53:11.280498+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc69822c-734c-4ab2-96b5-c3efcc9d3a9a', '64e637a1-cc1d-4892-b861-d059fb97dcf1', 'a', 'Desnudar la zona afectada, limpiar la quemadura con agua fría, romper las ampollas y recortar con cuidado los tejidos muertos o desgarrados.', false, '2025-09-13 13:53:11.281433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('384f4ac1-6f2f-48d4-8aa1-3d2d150fa843', '64e637a1-cc1d-4892-b861-d059fb97dcf1', 'b', 'Cubrir la quemadura, una vez limpia, con gasas grasas y un vendaje que comprima.', false, '2025-09-13 13:53:11.281564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af6105bb-dc3a-443b-b1ad-c19bedcb4c98', '64e637a1-cc1d-4892-b861-d059fb97dcf1', 'c', 'Inmovilizar la zona, si la quemadura afecta a una articulación y es al menos de 2º grado, y administrar un antibiótico para prevenir la infección.', true, '2025-09-13 13:53:11.281694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09036d70-86d7-4d3d-a7b5-c272eb3ee446', '64e637a1-cc1d-4892-b861-d059fb97dcf1', 'd', 'Dar a beber al afectado, si está consciente, pequeños sorbos de una bebida estimulante para reponer los líquidos y un analgésico para calmar el dolor.', false, '2025-09-13 13:53:11.28184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d3a1a19-29e7-4e9f-84c6-9095e79e95ea', '589ca00b-db0c-4105-9071-387fa7bb9695', 'a', 'Siempre se ha de utilizar agua para apagarlo ya que es la forma más efectiva en el mar.', false, '2025-09-13 13:53:11.282141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dea4ac6-9c84-4dd9-8a62-8e7508b7f83b', '589ca00b-db0c-4105-9071-387fa7bb9695', 'b', 'Cuando se produce un incendio dentro de un local hay que abrir todas las puertas y aberturas para facilitar la ventilación y que salga el humo.', false, '2025-09-13 13:53:11.282274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('968dd69c-a911-458b-a6ad-e43d9ca4fb9a', '34c23954-12b6-4d94-804b-dfbf2e1c533f', 'b', 'Siempre tienen marca de tope que será dos esferas negras.', false, '2025-09-13 13:53:11.305062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7488b6a7-ad9a-4942-a7ad-20f2371af165', '5d1eb38f-e812-433a-ae49-92452ac6be5b', 'd', 'Una luz roja centelleante dispuesta sobre la cubierta de la embarcación.', false, '2025-09-13 13:53:11.279797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdc27edd-0964-41a8-85b4-a69c25056782', '5d1eb38f-e812-433a-ae49-92452ac6be5b', 'c', 'Una bandera cuadrada con un triángulo rojo superpuesto, colocada en la cubierta de la embarcación.', false, '2025-09-13 13:53:11.279649+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e20e134d-5f29-46af-a18f-32bf0b05272b', '589ca00b-db0c-4105-9071-387fa7bb9695', 'c', 'Cuando arde un combustible líquido siempre se ha de utilizar para apagarlo agua a presión.', false, '2025-09-13 13:53:11.282449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb724a98-40df-428e-93f6-bbefedbb6f09', '589ca00b-db0c-4105-9071-387fa7bb9695', 'd', 'La acción de los extintores de polvo seco consiste en separar o quitar el oxígeno del fuego deteniendo así la combustión.', true, '2025-09-13 13:53:11.28262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac041b44-eaac-4f2c-ad23-56f2be7b9eda', '56179a79-ae62-4290-b51e-45468c9ede55', 'a', 'Abandonaremos inmediatamente la embarcación.', false, '2025-09-13 13:53:11.282972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d94564a-788e-4d6d-ac94-9b04f01404a5', '56179a79-ae62-4290-b51e-45468c9ede55', 'b', 'Navegaremos a toda máquina para llegar lo antes posible a puerto.', false, '2025-09-13 13:53:11.283133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd523463-fb3f-4ff3-bc0e-eac336f9b5e4', '56179a79-ae62-4290-b51e-45468c9ede55', 'c', 'Pondremos en marcha todas las bombas de achique y mantendremos encendido el motor.', true, '2025-09-13 13:53:11.28329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('777b1736-35af-4cfc-9f55-6b94dc1a33d2', '56179a79-ae62-4290-b51e-45468c9ede55', 'd', 'Si ésta tiene grandes dimensiones, utilizaremos un espiche para taponarla y pararemos el motor. Meteorología', false, '2025-09-13 13:53:11.283458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24fae5ba-9890-4881-8db2-c6e9237005a5', '2ece1e40-cb6c-4162-942a-8856be9f616b', 'a', 'Comúnmente se identifica con la brisa de tierra que sopla durante la noche desde la tierra hacia el mar al enfriarse la superficie de la tierra más rápidamente que la superficie del mar.', true, '2025-09-13 13:53:11.283755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b31fc92b-37a0-451f-936c-18e9d52baac4', '2ece1e40-cb6c-4162-942a-8856be9f616b', 'b', 'Sopla de manera regular de este a oeste desde las altas presiones subtropicales hacia las bajas presiones ecuatoriales.', false, '2025-09-13 13:53:11.2839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7f060aa-6e9c-42d6-a747-07aa7315e3e0', '2ece1e40-cb6c-4162-942a-8856be9f616b', 'c', 'Desciende desde las alturas hasta el fondo de los valles producido por el deslizamiento al ras de suelo del aire frío y denso desde los elementos del relieve más altos.', false, '2025-09-13 13:53:11.284034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('166f9dc0-483e-4f7a-bfb6-36c746769ee2', '2ece1e40-cb6c-4162-942a-8856be9f616b', 'd', 'Asciende desde las zonas más bajas hacia las más altas a medida que el sol calienta el relieve.', false, '2025-09-13 13:53:11.284171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('827140b9-a206-4094-aa22-3b2cb6371679', 'f12ae19c-3fe7-4418-b657-5567e92649f1', 'a', 'Es una región donde la presión atmosférica es más alta que la del aire circundante.', false, '2025-09-13 13:53:11.284451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfc780e9-de03-4f3d-9cc4-66f0b0334392', 'f12ae19c-3fe7-4418-b657-5567e92649f1', 'b', 'El aire fluye hacia el interior de las borrascas y desciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.28472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5767540e-8dd0-49a7-8763-903ed8cfe0d6', 'f12ae19c-3fe7-4418-b657-5567e92649f1', 'd', 'El proceso de formación de una borrasca se denomina ciclogénesis.', true, '2025-09-13 13:53:11.285006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e534895-3d62-4ac6-93de-cc4f9ac0e4b9', 'ae3dc5be-8a6a-4d91-bfaa-c962f56a09f2', 'a', 'Existen 100 divisiones entre el punto de congelación y ebullición del agua.', false, '2025-09-13 13:53:11.285291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dcac65f-b784-4a86-ac86-3e56abbea710', 'ae3dc5be-8a6a-4d91-bfaa-c962f56a09f2', 'b', 'El punto de congelación del agua es el valor de referencia inferior.', false, '2025-09-13 13:53:11.285434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfc0fa0d-4852-4d73-8a40-8cae3d02f6c9', 'ae3dc5be-8a6a-4d91-bfaa-c962f56a09f2', 'c', 'Cada grado está dividido en 100 unidades, por esto se conoce esta unidad como centígrada.', true, '2025-09-13 13:53:11.28557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a35c0f2-7a8d-4f49-8ac4-7eb2fe2ed06e', 'ae3dc5be-8a6a-4d91-bfaa-c962f56a09f2', 'd', 'El punto de ebullición del agua es el valor de referencia superior.', false, '2025-09-13 13:53:11.285702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f56e32ea-407b-4840-8102-a98468cfd10b', '28c5558f-c30f-4102-85f8-7266ff3ccb73', 'a', 'Cuando éste aumenta de intensidad.', false, '2025-09-13 13:53:11.285998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0d8cd01-150a-4dab-9793-e752bd25b65f', '28c5558f-c30f-4102-85f8-7266ff3ccb73', 'b', 'Cuando éste rola de norte a sur.', false, '2025-09-13 13:53:11.28614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9c3d636-0b99-464a-b775-0eb10fa25caa', '28c5558f-c30f-4102-85f8-7266ff3ccb73', 'c', 'Cuando éste disminuye de intensidad.', true, '2025-09-13 13:53:11.286282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1bd8f09-9387-41d9-96bf-b84f05582a61', 'fb3d274a-6e1c-4acd-bdae-cb2b095b693c', 'a', 'Rumbo.', false, '2025-09-13 13:53:11.2867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbf6af45-facb-4dbf-b9b7-38f2f2fae637', 'fb3d274a-6e1c-4acd-bdae-cb2b095b693c', 'b', 'Marcación.', true, '2025-09-13 13:53:11.286834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ccd7198-d55c-4917-8319-262305e9b95a', 'fb3d274a-6e1c-4acd-bdae-cb2b095b693c', 'c', 'Demora.', false, '2025-09-13 13:53:11.286989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93790b67-f288-4705-a51a-e1fd05c5d5a8', 'fb3d274a-6e1c-4acd-bdae-cb2b095b693c', 'd', 'Abatimiento.', false, '2025-09-13 13:53:11.287119+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('839e5c16-080c-4a6e-b84c-992708c049d8', '8bb4ad5d-35a0-45bb-923e-0a0674cc4cc5', 'a', 'En el Almanaque Náutico.', false, '2025-09-13 13:53:11.287417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb252933-cc3b-42df-bf71-755708debb4b', '8bb4ad5d-35a0-45bb-923e-0a0674cc4cc5', 'b', 'En el Anuario de Mareas.', false, '2025-09-13 13:53:11.287573+00');
