INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f86fc22d-5c3d-4304-913d-84189bdee6b8', 'fbfd0e75-36ab-4f3d-906e-eefb93bc95a3', 'a', 'Escorar es desviarse una embarcación de su rumbo por el impulso del viento o de una corriente.', false, '2025-09-13 13:53:11.293745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b706078-ad5f-40d3-8695-2987b4949460', 'fbfd0e75-36ab-4f3d-906e-eefb93bc95a3', 'b', 'Adrizar es poner derecha o vertical una embarcación que estaba inclinada.', true, '2025-09-13 13:53:11.293897+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c1bb715-8c16-450e-8f93-46ff8a1a042f', '28c5558f-c30f-4102-85f8-7266ff3ccb73', 'd', 'Cuando éste refresca y cae su temperatura.', false, '2025-09-13 13:53:11.286416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1dde464-30e2-4d5b-87bb-e80c5c93bebc', 'f12ae19c-3fe7-4418-b657-5567e92649f1', 'c', 'A escala sinóptica el aire circula en torno a una depresión en sentido horario en el hemisferio norte.', false, '2025-09-13 13:53:11.28487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb7a6731-9f2a-43ae-b6b7-ea6a872ecb7c', 'fbfd0e75-36ab-4f3d-906e-eefb93bc95a3', 'd', 'Sotavento es la parte de donde viene el viento, con respecto a un punto o lugar determinado.', false, '2025-09-13 13:53:11.294166+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c61e976d-c6b8-4766-8698-83ce21e12fc7', '250fdf3d-278d-40be-892c-ebceac8beec8', 'b', 'La bocina es el orificio que permite que el eje de la hélice gire a través del casco y entre agua para su refrigeración.', false, '2025-09-13 13:53:11.294857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bfead0a-bdaf-4f5b-a297-40f55d100e7c', '250fdf3d-278d-40be-892c-ebceac8beec8', 'c', 'El capacete es la pieza esférica que cierra el núcleo de la hélice.', false, '2025-09-13 13:53:11.295001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5884d561-b729-46cc-8234-157d6cfcdac1', '250fdf3d-278d-40be-892c-ebceac8beec8', 'd', 'Las palas son placas planas en las que se provoca una diferencia de velocidades del fluido entre una cara y la otra de la hélice.', false, '2025-09-13 13:53:11.29513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcd768d7-2dd5-420e-b99b-83c6b9997bad', '7d773dd0-6836-4749-af09-f5a079eb6c94', 'a', 'Virar es dar vueltas al cabrestante para levar el ancla.', false, '2025-09-13 13:53:11.296076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10082e5a-363d-479d-bfcc-39953258b431', '7d773dd0-6836-4749-af09-f5a079eb6c94', 'b', 'Filar es arriar progresivamente un cabo o cadena que está trabajando.', false, '2025-09-13 13:53:11.29622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cc97838-d97f-4264-8d14-055baac932b2', '7d773dd0-6836-4749-af09-f5a079eb6c94', 'c', 'Levar es recoger, arrancar y suspender el ancla que está fondeada.', false, '2025-09-13 13:53:11.29636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('342b2d03-8712-4644-88ec-deda6ab80351', '72345c8a-e19e-41a4-9c90-5a5cc9c50c53', 'a', 'Firme.', false, '2025-09-13 13:53:11.296766+00');
