INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8be5db1a-527f-4a55-b7d6-ced5ccbff162', '316840a0-a3ff-405a-8697-7a2e66fe073a', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no ha garreado, y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-13 13:53:11.297736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b68f999-251e-4032-8910-b8b5f7deb2f8', '316840a0-a3ff-405a-8697-7a2e66fe073a', 'c', 'La embarcación debe disponer de una línea de fondeo cuya longitud será tres veces su eslora.', false, '2025-09-13 13:53:11.297912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70e2e434-5649-4e8e-8daf-0c149204fc56', '316840a0-a3ff-405a-8697-7a2e66fe073a', 'd', 'Si optamos por el fondeo a la gira, utilizaremos dos anclas de forma que las líneas de fondeo formen un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:11.298065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37f01095-3f9f-47e5-bf49-ba2bc4c8df5e', '79ca3598-ba35-4aa6-a7ba-aeb06f2aac6a', 'a', 'Cuando la frecuencia del movimiento de balance es alta.', true, '2025-09-13 13:53:11.298378+00');
