INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('659554d0-0c16-4da2-b540-6103cb9a0a75', '410cc509-5584-4732-a0d9-c9d109c33ea8', 'c', 'Navegaremos con mayor seguridad aumentando la velocidad.', false, '2025-09-13 13:53:11.301366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5fa7d2f-b44a-430c-b2f9-477dc73845f5', '410cc509-5584-4732-a0d9-c9d109c33ea8', 'd', 'La maniobrabilidad no se ve afectada.', false, '2025-09-13 13:53:11.301546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24580072-6146-429b-b6e9-9ee2a9fcb3ff', '12c83170-4202-4886-9793-42165cca98a7', 'a', 'Entre las medidas legales adoptadas se establecen limitaciones al fondeo de embarcaciones para evitar que malas técnicas de fondeo arrastren y barran el fondo marino arrancando matas, deteriorando las praderas de posidonia.', true, '2025-09-13 13:53:11.301946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9225b378-7702-42a8-bf76-8dfcacc78bed', '12c83170-4202-4886-9793-42165cca98a7', 'b', 'La única medida adoptada en España es cartografiar y catalogar las praderas e insertar esos datos en sistemas de información accesibles a los navegantes y al público en general y, en la medida de lo posible, en las cartas náuticas.', false, '2025-09-13 13:53:11.302116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ae87500-33a7-4df0-856c-b77818c93c52', '12c83170-4202-4886-9793-42165cca98a7', 'c', 'Todavía no existe normativa concreta, sólo recomendaciones de las consejerías de pesca y medio ambiente de las diferentes comunidades autónomas sobre cómo actuar allí donde se localizan las praderas de posidonia.', false, '2025-09-13 13:53:11.302449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5710b29-a7a5-4c98-9778-078595fbd7eb', '12c83170-4202-4886-9793-42165cca98a7', 'd', 'No hay normativa específica ni limitación alguna para fondear sobre praderas de posidonia, pero un navegante responsable con el medio ambiente, antes de fondear, debería observar el fondo marino por su propia cuenta para procurar no dañar la posidonia.', false, '2025-09-13 13:53:11.30265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35ef3f7b-a6b9-425e-9c87-cfe66806eb63', '9cebb805-6a30-466a-aa62-95431d56bcf6', 'a', 'Podrá fondear con finalidad exclusiva de recreo y en esa zona deberá navegar a una velocidad no superior a 3 nudos.', true, '2025-09-13 13:53:11.30299+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbb5edde-609b-4a83-80a2-c262648a69f3', '9cebb805-6a30-466a-aa62-95431d56bcf6', 'b', 'No podrá continuar la navegación. Deberá fondear y avisar a los servicios de salvamento para que lo remolquen con seguridad.', false, '2025-09-13 13:53:11.303141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d6e5fbb-6045-4d6d-a576-90a3836867c2', '9cebb805-6a30-466a-aa62-95431d56bcf6', 'c', 'Deberá alejarse de la zona al menos 200 metros, debiendo navegar a una velocidad superior a 3 nudos, adoptando las precauciones necesarias.', false, '2025-09-13 13:53:11.303287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc8c09b8-838b-4db0-a23d-67f18137edc3', '9cebb805-6a30-466a-aa62-95431d56bcf6', 'd', 'Está absolutamente prohibida la navegación a esa distancia, al poner en peligro la seguridad de la vida humana en la mar o de la navegación.', false, '2025-09-13 13:53:11.303538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da4114b3-88ab-4765-a0e2-065241b699ad', '72a38cb8-cb4f-4fad-80ab-a6695b6452fb', 'a', 'Peligro Aislado.', true, '2025-09-13 13:53:11.303973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d149acc4-117f-48d8-9d50-a77dff373f93', '72a38cb8-cb4f-4fad-80ab-a6695b6452fb', 'b', 'Peligro nuevo.', false, '2025-09-13 13:53:11.304145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee09ecb4-1e56-47e7-a827-50a4de05f92c', '72a38cb8-cb4f-4fad-80ab-a6695b6452fb', 'c', 'Especial.', false, '2025-09-13 13:53:11.30433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b40ab639-db32-4f64-970c-f0c2af599289', '72a38cb8-cb4f-4fad-80ab-a6695b6452fb', 'd', 'Lateral estribor.', false, '2025-09-13 13:53:11.304506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a79510e-cbfa-4434-afb6-b61542c0eed6', '34c23954-12b6-4d94-804b-dfbf2e1c533f', 'a', 'Nunca tienen marca de tope.', false, '2025-09-13 13:53:11.304871+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a71f3299-47db-49b4-a271-cb6f779ff5dd', 'c898c492-1957-4a04-8250-561917ab28a3', 'c', '290°.', true, '2025-09-13 13:53:11.343079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49ddeefb-ea82-4f10-a81a-9e1151329d7e', '316840a0-a3ff-405a-8697-7a2e66fe073a', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:11.297601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af0954d4-5172-4926-9022-b8bfca1a30f3', '7d773dd0-6836-4749-af09-f5a079eb6c94', 'd', 'Zarpar es salir un barco del lugar en que estaba atracado.', true, '2025-09-13 13:53:11.296492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61a08f15-ef59-4852-8de0-e828e779cb33', '34c23954-12b6-4d94-804b-dfbf2e1c533f', 'd', 'Si tienen marca de tope será un aspa amarilla.', false, '2025-09-13 13:53:11.305357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fec005ff-19e3-490d-a678-0fdf3bed99e0', 'cacd795d-9004-4e10-94f3-0bc34e8c2680', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la marca.', false, '2025-09-13 13:53:11.305653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ae1060d-c31b-4cfd-adf2-78231781b77b', 'cacd795d-9004-4e10-94f3-0bc34e8c2680', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:11.305862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83e8b81c-7f54-4b1f-94c7-67e4cda9451e', 'cacd795d-9004-4e10-94f3-0bc34e8c2680', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.306036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0b7548b-31cd-4a1c-b719-6847982c5ebb', 'cacd795d-9004-4e10-94f3-0bc34e8c2680', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la marca.', true, '2025-09-13 13:53:11.306182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c86dda46-a571-4089-bcc6-38ce50b35739', 'dc350b6d-fb57-451e-b367-8bd4d04baed3', 'a', 'De libre elección, pero que no se preste a confusión con las Marcas para ayuda a la navegación.', false, '2025-09-13 13:53:11.306499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('126a395a-8df9-4287-a516-301ab4f95637', 'dc350b6d-fb57-451e-b367-8bd4d04baed3', 'b', 'Franjas verticales rojas y blancas.', false, '2025-09-13 13:53:11.306643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dca0351c-a348-49cd-aa81-28997d0e25b3', 'dc350b6d-fb57-451e-b367-8bd4d04baed3', 'c', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:11.306791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6371b223-c24b-4658-ac8c-639b4919582a', 'dc350b6d-fb57-451e-b367-8bd4d04baed3', 'd', 'Amarillo.', true, '2025-09-13 13:53:11.306938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2e86171-1f55-4ef8-9818-09401a74898b', 'e5a94792-7255-4ec9-8c93-be4f9d261939', 'a', 'Por un canal principal.', true, '2025-09-13 13:53:11.307384+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd27827a-4fa1-4a9a-95a6-ea1d8eb8228f', 'e5a94792-7255-4ec9-8c93-be4f9d261939', 'b', 'Por un canal secundario.', false, '2025-09-13 13:53:11.307527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('141835f0-44c9-4c41-9ad2-a8db4ffe5fbc', 'e5a94792-7255-4ec9-8c93-be4f9d261939', 'c', 'Entre una Marca lateral y una Marca cardinal norte.', false, '2025-09-13 13:53:11.307667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c233ba8-7191-4746-8a18-aa927ae66a28', '3aff4294-5fd9-493f-b3a7-516b216593da', 'a', 'Una luz amarilla.', false, '2025-09-13 13:53:11.308123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ae7e93d-6f4c-46e9-a038-e0a8c5cb3bb1', '3aff4294-5fd9-493f-b3a7-516b216593da', 'b', 'Una luz verde.', false, '2025-09-13 13:53:11.308276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a451648f-9555-4b23-a4a2-d3cfa3211303', '3aff4294-5fd9-493f-b3a7-516b216593da', 'c', 'Una luz roja.', false, '2025-09-13 13:53:11.308409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e51e8c3-3d64-4e66-9b34-1c7cd8a1315d', '3aff4294-5fd9-493f-b3a7-516b216593da', 'd', 'Una luz blanca.', true, '2025-09-13 13:53:11.308545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6074de17-93ca-4351-980f-853715fb0fa3', 'e485553c-9710-4c34-ab73-0ce1edfc3930', 'a', 'Dos pitadas cortas.', false, '2025-09-13 13:53:11.308832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aeba721-300c-4cf7-ba37-62c7f7f017f8', 'e485553c-9710-4c34-ab73-0ce1edfc3930', 'b', 'Dos pitadas largas.', false, '2025-09-13 13:53:11.308969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7fbd4ce-c352-453c-9e08-46f890547b41', 'e485553c-9710-4c34-ab73-0ce1edfc3930', 'c', 'Una pitada corta.', false, '2025-09-13 13:53:11.309104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4876cd8-67b1-4e4e-82da-3197200107a6', 'e485553c-9710-4c34-ab73-0ce1edfc3930', 'd', 'Una pitada larga.', true, '2025-09-13 13:53:11.309239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6d9ffa4-5477-47ef-bc69-80e39fed2a95', '0b646db0-be33-4eee-a1a9-617e186500a8', 'b', 'Todo buque dedicado a operaciones de remolque que por su naturaleza restrinja fuertemente al buque remolcador y su remolque en su capacidad para apartarse de su derrota.', false, '2025-09-13 13:53:11.309662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ff5b0e7-585a-4f67-bfbd-8fedcf931cb5', '0b646db0-be33-4eee-a1a9-617e186500a8', 'c', 'Todo buque que por cualquier circunstancia excepcional es incapaz de maniobrar en la forma exigida por este Reglamento y, por consiguiente, no puede apartarse de la derrota de otro buque.', true, '2025-09-13 13:53:11.30981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e22b8aa-e17a-4660-afa2-0c2dabf8d954', '0b646db0-be33-4eee-a1a9-617e186500a8', 'd', 'Todo buque dedicado a dragados, trabajos hidrográficos, oceanográficos u operaciones', false, '2025-09-13 13:53:11.30995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('569967e9-1cda-4d25-94c7-5486dbc17b6f', 'f256bdc3-f41d-4a23-bab1-ae53a96dd788', 'a', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', true, '2025-09-13 13:53:11.310232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69aa27f3-c094-47bd-8cb3-913c6eb06b13', 'f256bdc3-f41d-4a23-bab1-ae53a96dd788', 'b', 'En todo un arco del horizonte de 112,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.31037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dac266cf-ff11-4bc2-ad94-0fe387d8584b', 'f256bdc3-f41d-4a23-bab1-ae53a96dd788', 'c', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la popa hasta 22,5 grados a proa del través de su costado respectivo.', false, '2025-09-13 13:53:11.310511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee550920-cb97-4bf9-8102-e37f52b252df', 'f256bdc3-f41d-4a23-bab1-ae53a96dd788', 'd', 'En todo un arco del horizonte de 67,5 grados, fijadas de forma que sean visibles desde la proa hasta 22,5 grados a popa del través de su costado respectivo.', false, '2025-09-13 13:53:11.310647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85d71841-8e35-4d4d-96fb-bcaa358b0236', '58a7b642-6f90-4d2f-8d08-97edf45fe0cd', 'a', 'Los buques de propulsión mecánica tendrán sus máquinas listas para maniobrar inmediatamente.', false, '2025-09-13 13:53:11.310934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('699e7efb-5d70-4501-bf37-b4e5a98858d2', '58a7b642-6f90-4d2f-8d08-97edf45fe0cd', 'b', 'Todos los buques navegarán a una velocidad de seguridad adaptada a las circunstancias y condiciones de visibilidad reducida del momento.', false, '2025-09-13 13:53:11.311068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e68665f-d0e7-46e5-8074-77e2d93eb442', '58a7b642-6f90-4d2f-8d08-97edf45fe0cd', 'c', 'Es de aplicación a los buques que estén a la vista uno del otro cuando naveguen cerca o dentro de una zona de visibilidad reducida.', true, '2025-09-13 13:53:11.311206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df94ac20-4fa6-42b2-a1c5-d5f6e2c6617d', '58a7b642-6f90-4d2f-8d08-97edf45fe0cd', 'd', 'Todo buque que oiga, al parecer a proa de su través, la señal de niebla de otro buque, deberá reducir su velocidad hasta la mínima de su gobierno.', false, '2025-09-13 13:53:11.311341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b33816f8-bb78-4614-b3e8-8a53ad16fcc4', '0ac9bac3-eb9f-4b65-b5bb-18ecabc4530a', 'a', 'Los buques de eslora inferior a 20 m.', false, '2025-09-13 13:53:11.311627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6ed412e-3cd1-44c5-aea8-cb3905763349', '0ac9bac3-eb9f-4b65-b5bb-18ecabc4530a', 'b', 'Los buques de vela.', false, '2025-09-13 13:53:11.311764+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f008ff8-2085-4c7d-8860-6e5a25c25dc2', '0ac9bac3-eb9f-4b65-b5bb-18ecabc4530a', 'c', 'Los buques que puedan navegar con seguridad por la vía de circulación adecuada de un dispositivo de separación de tráfico.', true, '2025-09-13 13:53:11.311909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fd4d21d-21c6-4e4b-8127-a20449c789a2', '0ac9bac3-eb9f-4b65-b5bb-18ecabc4530a', 'd', 'Los buques dedicados a la pesca.', false, '2025-09-13 13:53:11.312193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71417231-95f3-4eda-881e-0b25b06626d4', 'eeecb422-09b8-41de-9692-eb4f08176043', 'b', 'El buque que tenga al otro por su costado de babor maniobrará, en lo posible, con anticipación suficiente y de forma decidida para quedar bien franco del otro buque.', false, '2025-09-13 13:53:11.312621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5567a185-b295-440e-9f52-ca18049a6de1', 'eeecb422-09b8-41de-9692-eb4f08176043', 'c', 'Ambos buques maniobrarán, si las circunstancias lo permiten, eligiendo siempre maniobras que eviten cortarle la proa al otro buque.', false, '2025-09-13 13:53:11.312756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('065b08a8-a550-4030-9e7a-ed87b21246fd', 'eeecb422-09b8-41de-9692-eb4f08176043', 'd', 'Dado que todo buque está obligado a mantenerse apartado de la derrota de otro buque, los buques realizarán maniobras simétricas.', false, '2025-09-13 13:53:11.312901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b90eae16-1578-4aad-beb7-4794fe0a98aa', '7cad1fa4-d906-40f1-839e-a41d9d10078f', 'a', 'Solamente a los buques sin gobierno.', false, '2025-09-13 13:53:11.313183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1fe06cf-c3bf-443a-be92-d94bd663a354', '7cad1fa4-d906-40f1-839e-a41d9d10078f', 'b', 'En cualquier condición de visibilidad.', true, '2025-09-13 13:53:11.31332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf13550d-636a-4db6-9312-ee2b1a30fcf0', '7cad1fa4-d906-40f1-839e-a41d9d10078f', 'c', 'Sólo en condiciones de visibilidad reducida.', false, '2025-09-13 13:53:11.313454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d4e7a34-3ee6-49a6-a5a2-0e5fe78b2396', '7cad1fa4-d906-40f1-839e-a41d9d10078f', 'd', 'Sólo a los buques restringidos por su calado.', false, '2025-09-13 13:53:11.313588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ce3b9ec-6e76-4180-b30c-a40b927b15e7', '126fc85e-22ed-44fa-970a-53ad9546b836', 'a', 'Cada uno de ellos caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:11.313882+00');
