INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fb702cb-3fe7-4853-99e2-f5b86ead49bc', '4e8317b6-42d2-47bc-a6e0-4da7deed257e', 'c', 'Los extintores de dióxido de carbono (CO2) son adecuados para la extinción de fuegos de origen', false, '2025-09-13 13:53:11.360745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04019af1-fab5-4bb6-a1d0-b920dd4deff2', '4e8317b6-42d2-47bc-a6e0-4da7deed257e', 'd', 'La utilización de un reflector de radar en una embarcación de casco no metálico no es obligatoria en las zonas de navegación 5 y 6.', true, '2025-09-13 13:53:11.36094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e09eb7b9-f3fa-4e49-8d97-db3dd644313b', 'be1d6edd-72a0-4790-9b58-5e5564ca7844', 'a', 'Saltar al agua y nadar lentamente para reducir la hipotermia.', false, '2025-09-13 13:53:11.361257+00');
