INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe3da71a-4bd7-44d7-b743-8dbe96ff9f45', 'be1d6edd-72a0-4790-9b58-5e5564ca7844', 'd', 'Subirse a cualquier objeto flotante para reducir la hipotermia.', false, '2025-09-13 13:53:11.36179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00930e5a-f369-4c30-b529-d2c07e0e667a', '65d0491d-a8b8-45b0-9c3d-a974cdc1e253', 'a', 'Dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:11.362087+00');
