INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a70b4560-c2ff-4434-adfe-6862ced77a98', '65d0491d-a8b8-45b0-9c3d-a974cdc1e253', 'd', 'Tres extintores, tipo 34 B.', true, '2025-09-13 13:53:11.362489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5be4964d-b9b3-4ee2-b0a5-e44e223f68e4', '348df416-7c28-4d5b-ac99-ef50db666123', 'a', 'Entre 1 y 2 horas.', false, '2025-09-13 13:53:11.362914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('212f577e-00b0-477f-b88a-f61458a16be7', '348df416-7c28-4d5b-ac99-ef50db666123', 'b', 'Menos de 24 horas.', false, '2025-09-13 13:53:11.363055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69dac10a-25b4-47ab-892d-cfb19b640d77', '348df416-7c28-4d5b-ac99-ef50db666123', 'c', 'Indeterminado, ya que los helicópteros vuelan a relativamente baja velocidad.', true, '2025-09-13 13:53:11.363201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14f98de1-a624-4475-a009-c6b453373df8', '348df416-7c28-4d5b-ac99-ef50db666123', 'd', 'Inmediato, ya que los helicópteros vuelan a gran velocidad.', false, '2025-09-13 13:53:11.363387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c534757-c0fc-4d1d-9427-44fbbf9f2c7b', '0a6cef1b-61d6-4181-b851-18e0e316b367', 'a', 'Emitir un mensaje de socorro, según el procedimiento radiotelefónico.', false, '2025-09-13 13:53:11.363696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7098789e-57f1-4615-a0c4-1721342c90f4', '0a6cef1b-61d6-4181-b851-18e0e316b367', 'b', 'Detener la embarcación.', true, '2025-09-13 13:53:11.363852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f4fc59b-d288-4b4b-8453-c2630d7da26d', '0a6cef1b-61d6-4181-b851-18e0e316b367', 'c', 'Si hay que saltar al agua, hacerlo sujetándose las rodillas contra el pecho.', false, '2025-09-13 13:53:11.364006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d48c9b98-713c-4677-bef4-70efd590e69f', '0a6cef1b-61d6-4181-b851-18e0e316b367', 'd', 'Alistar balsas, aros, chalecos y cuanto material vaya a ser evacuado, incluyendo la radiobaliza.', false, '2025-09-13 13:53:11.364144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae0b80e6-f901-40d8-aec9-b08c3ef169ef', '5da4f5bd-e08e-4e88-8a99-ac91cb7ef101', 'a', 'Una radiobaliza de localización EPIRB es empleada como un sistema de alerta en caso de socorro indicando, a las autoridades SAR, la identidad y la posición de una persona o de un buque que está en peligro grave e inminente y requiere ayuda inmediata.', false, '2025-09-13 13:53:11.364441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eef068c3-5d1a-4df2-8ea0-76484e75b767', '5da4f5bd-e08e-4e88-8a99-ac91cb7ef101', 'b', 'Cada radiobaliza EPIRB se programa con una identidad única.', false, '2025-09-13 13:53:11.364583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55e0272a-ba6e-42f1-9eea-f550667084fc', '5da4f5bd-e08e-4e88-8a99-ac91cb7ef101', 'c', 'El país programado en su radiobaliza EPIRB no se puede encontrar en la etiqueta de la identidad donde están generalmente todos los datos necesarios.', false, '2025-09-13 13:53:11.364716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5b27e81-8c0c-406b-8a31-d2f25b295fd1', '5da4f5bd-e08e-4e88-8a99-ac91cb7ef101', 'd', 'Marcar el nombre del buque es responsabilidad de los clientes. El cliente tiene que registrar su radiobaliza EPIRB en las autoridades apropiadas en su país.', true, '2025-09-13 13:53:11.364849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff52caa2-5fbc-4be5-a5ec-d898d5933626', '68bb388b-10bd-4e34-86b6-be9182b750fc', 'a', 'Aumenta la estabilidad transversal.', false, '2025-09-13 13:53:11.365133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5564d65c-3210-4e5a-8493-b3104d27bbb6', '68bb388b-10bd-4e34-86b6-be9182b750fc', 'b', 'Disminuye la estabilidad transversal.', true, '2025-09-13 13:53:11.365274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f932a7ff-a031-4cb7-891e-a8c733fb1776', '68bb388b-10bd-4e34-86b6-be9182b750fc', 'c', 'Afecta solo al francobordo y a la estanqueidad, no a la estabilidad.', false, '2025-09-13 13:53:11.365408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e5e6619-ead7-4c38-93f8-9058156d2101', '68bb388b-10bd-4e34-86b6-be9182b750fc', 'd', 'No afecta a la estabilidad transversal, sólo a la longitudinal. Meteorología', false, '2025-09-13 13:53:11.365546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68393109-2d82-4fff-86ec-9262d6b2f83d', '2d57dda6-9218-432e-bf4e-121036565faf', 'a', 'Anticiclón.', false, '2025-09-13 13:53:11.365983+00');
