INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce4d4377-99ae-4855-a122-07db29e756d9', 'f9bd7e14-b7ad-4dae-81b9-1ef904bdd588', 'a', 'Son líneas que unen puntos con igual valor de presión en una superficie dada.', false, '2025-09-13 13:53:11.367863+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27c78b87-c2c2-48c6-91ae-597cfda9f1a2', 'f9bd7e14-b7ad-4dae-81b9-1ef904bdd588', 'b', 'Son líneas paralelas y concéntricas al nivel del mar.', false, '2025-09-13 13:53:11.368028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91921257-6c92-4c9f-8a88-9b2d8d63dd5a', 'f9bd7e14-b7ad-4dae-81b9-1ef904bdd588', 'c', 'En los mapas se trazan normalmente isobaras de presión reducida al nivel del mar.', false, '2025-09-13 13:53:11.368189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48487939-65a5-4ae1-9199-e0ccebcb7f70', 'f9bd7e14-b7ad-4dae-81b9-1ef904bdd588', 'd', 'La proximidad entre ellas indica variaciones de presión más bruscas.', true, '2025-09-13 13:53:11.368353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b97df19-70af-4bf6-9734-865921b00b97', '18257af8-cb54-4337-ae1e-50cd375b72d1', 'a', 'Su dirección siempre coincidirá con la dirección del mar de viento.', true, '2025-09-13 13:53:11.368688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2bca8af-aadf-4769-bd7b-0f1f64cbc806', '18257af8-cb54-4337-ae1e-50cd375b72d1', 'b', 'Se produce como consecuencia de la relación calado/fondo a bajas velocidades.', false, '2025-09-13 13:53:11.368865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9673e53-ddaa-41e7-b23c-0572a25a0263', '18257af8-cb54-4337-ae1e-50cd375b72d1', 'c', 'No tiene por qué ir con el mar de viento.', false, '2025-09-13 13:53:11.36901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d05fc5eb-8d27-4c9c-ba05-60a2bc0a407e', '18257af8-cb54-4337-ae1e-50cd375b72d1', 'd', 'Su dirección nunca coincidirá con la dirección del mar de viento, ya que la dirección del viento siempre será opuesta a la dirección de la mar de fondo.', false, '2025-09-13 13:53:11.36916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c955a6ab-0f0e-4d61-8fdc-17a7e27a5110', '2f243ae2-30e8-494c-b59e-6780e148efd0', 'a', 'Está relacionada con la corriente del Labrador.', false, '2025-09-13 13:53:11.369451+00');
