INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('405bcc42-84b7-481b-bb6c-2291461228e1', '2f243ae2-30e8-494c-b59e-6780e148efd0', 'c', 'Está relacionada con la corriente del Golfo.', false, '2025-09-13 13:53:11.36973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17843c3d-883b-4613-9fa6-47749015770f', '2f243ae2-30e8-494c-b59e-6780e148efd0', 'd', 'Recorre previamente la costa francesa y tiene una intensidad constante a lo largo del año superior', false, '2025-09-13 13:53:11.369869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38b2fafa-b1b9-45fe-8e18-d1e87a608b71', '6ee74996-8351-4658-aaf9-e52c86b6e6f0', 'a', 'Es la cantidad de vapor de agua que contiene una masa de aire.', false, '2025-09-13 13:53:11.37015+00');
