INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc120539-5e40-4c70-941f-44fa3e58dea8', 'd59eb1c2-162b-4dd3-96fa-582f1c34da7a', 'b', 'La publicación de avisos a los navegantes incluye la difusión de boletines meteorológicos.', false, '2025-09-13 13:53:11.376852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50de2a88-ec49-4daf-b454-be4a19f0e1e9', 'd59eb1c2-162b-4dd3-96fa-582f1c34da7a', 'c', 'La publicación de los avisos a los navegantes se edita cada semana.', true, '2025-09-13 13:53:11.377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('501849a5-ff4c-4575-b8e5-4b80e6d63e89', 'd59eb1c2-162b-4dd3-96fa-582f1c34da7a', 'd', 'Los avisos a los navegantes afectan a los derroteros, libro de faros, publicaciones de radioseñales, cartas y publicaciones náuticas.', false, '2025-09-13 13:53:11.37714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fed4129d-f5b3-4bf4-a2a0-a1fb6a5b9691', 'da63ef06-4f48-4200-905e-87de25860890', 'a', 'El rumbo y velocidad efectivos se definen como el vector resultante entre el rumbo y velocidad de superficie, por un lado, y el rumbo e intensidad horaria de la corriente por otro.', false, '2025-09-13 13:53:11.377418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f6e6367-b381-46a1-9c02-8b40f8ab96fd', 'da63ef06-4f48-4200-905e-87de25860890', 'b', 'La deriva se define como ángulo entre el rumbo de superficie y el rumbo de la corriente.', false, '2025-09-13 13:53:11.37755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fb7be02-3bd0-4c5f-8ffe-c2afb6e4d701', 'da63ef06-4f48-4200-905e-87de25860890', 'c', 'El abatimiento se define como el ángulo entre el rumbo verdadero y el rumbo efectivo.', true, '2025-09-13 13:53:11.377682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6435b916-cb0a-4744-8f93-d9cb18a702c6', 'da63ef06-4f48-4200-905e-87de25860890', 'd', 'El rumbo y velocidad de superficie se define como el vector resultante entre el rumbo verdadero y el rumbo del viento.', false, '2025-09-13 13:53:11.377819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('982d477c-b0f4-4371-aec9-5da574408a2c', 'df0a2a17-440a-4938-9e05-e6f82e4feea6', 'a', 'Facilita el intercambio de información entre barcos a fin de evitar colisiones.', false, '2025-09-13 13:53:11.378096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40493465-dac5-45fb-8698-dfaddadf72cf', 'df0a2a17-440a-4938-9e05-e6f82e4feea6', 'b', 'Aporta información a las autoridades marítimas sobre los buques y su cargamento.', false, '2025-09-13 13:53:11.378225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bd69934-c165-4248-9952-171224705fd6', 'df0a2a17-440a-4938-9e05-e6f82e4feea6', 'c', 'Es una herramienta complementaria en los dispositivos de control del tráfico marítimo y labores', true, '2025-09-13 13:53:11.378361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3540207-c4a0-49ed-8d7c-18b1da70a1b1', 'df0a2a17-440a-4938-9e05-e6f82e4feea6', 'd', 'Complementa las funciones del radar y lo sustituye en caso de fallo de este último.', false, '2025-09-13 13:53:11.378492+00');
