INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('474684c9-d0f4-437a-bd6a-d9a306ff9efd', 'a89a70bf-7614-4a4f-acec-1403f28fc5fb', 'a', 'El sistema ECDIS puede mostrar cartas náuticas electrónicas (ENC) pero no cartas náuticas ráster', false, '2025-09-13 13:53:11.379462+00');
