INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2cd3ebc-02ec-4b15-b814-15c395a8f1b2', 'a89a70bf-7614-4a4f-acec-1403f28fc5fb', 'c', 'Si a bordo se dispone únicamente de un sistema de cartas náuticas ENC como ayuda a la navegación, se podrá prescindir de las cartas de papel.', false, '2025-09-13 13:53:11.379891+00');
