INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af7dc9f4-cbfd-4292-9999-8ffd0ef6982e', '8669678c-4a4a-4174-9220-c43febcf46fa', 'c', 'Si hay que saltar al agua, hacerlo sujetándose las rodillas contra el pecho.', false, '2025-09-13 13:53:11.388563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09209211-fed5-4bf5-8d4d-871451bea88c', '8669678c-4a4a-4174-9220-c43febcf46fa', 'd', 'Alistar balsas, aros, chalecos y cuanto material vaya a ser evacuado, incluyendo la radiobaliza.', false, '2025-09-13 13:53:11.388695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16d047e4-39f9-4c52-b127-d5c26177e812', 'a0c056a2-a126-4a00-ab44-70e091bbcd8a', 'a', 'Dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:11.388979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51057bab-e9f7-4e55-83f8-e04458c94fa2', 'a0c056a2-a126-4a00-ab44-70e091bbcd8a', 'b', 'Seis bengalas de mano y tres cohetes con luz roja y paracaídas.', false, '2025-09-13 13:53:11.389115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0838b96b-76e5-40f3-a99f-3f4e5bfbb85f', 'a0c056a2-a126-4a00-ab44-70e091bbcd8a', 'c', 'Un balde contraincendios con capacidad mínima de 5 litros.', false, '2025-09-13 13:53:11.389251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00c2dada-6572-49f0-b25a-d96a1b83b0d3', 'a0c056a2-a126-4a00-ab44-70e091bbcd8a', 'd', 'Tres extintores, tipo 34 B.', true, '2025-09-13 13:53:11.389404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6430e24-b45c-479a-a99b-4922666aef3e', 'e5619aee-a03e-4941-b989-cef23fc7969d', 'a', 'La distancia entre el centro de carena y el punto de intersección del eje vertical del barco con la vertical trazada desde el centro de carena.', false, '2025-09-13 13:53:11.389699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e56fe3b3-d23e-40e2-91fc-2c0128b720e6', 'e5619aee-a03e-4941-b989-cef23fc7969d', 'b', 'La altura del centro de gravedad sobre el centro de carena.', false, '2025-09-13 13:53:11.389862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('090cadb0-1403-436c-86dd-cae32ee3b6fb', 'e5619aee-a03e-4941-b989-cef23fc7969d', 'c', 'El punto de intersección del eje vertical del barco con la vertical trazada desde el centro de', true, '2025-09-13 13:53:11.390136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22b1f26e-db4f-472e-a4fd-aa885ea10146', 'e5619aee-a03e-4941-b989-cef23fc7969d', 'd', 'El punto donde se aplica el empuje resultante de la presión del agua sobre el casco.', false, '2025-09-13 13:53:11.390277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c21072d3-c679-43c3-abf8-fae94f0cebc2', 'c1bd3fe1-d0f7-417e-95c8-91dfad7458ab', 'a', 'Aumenta la estabilidad transversal.', false, '2025-09-13 13:53:11.390552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('317b3588-705f-4507-a6b0-4624c92ecb5d', 'c1bd3fe1-d0f7-417e-95c8-91dfad7458ab', 'b', 'Disminuye la estabilidad transversal.', false, '2025-09-13 13:53:11.390683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e45fd257-a0c9-481b-be02-b2c01d4c8264', 'c1bd3fe1-d0f7-417e-95c8-91dfad7458ab', 'c', 'Afecta solo al francobordo y a la estanqueidad, no a la estabilidad.', true, '2025-09-13 13:53:11.390814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('070d32fb-3e8f-4c61-902d-f07e408498ee', 'c1bd3fe1-d0f7-417e-95c8-91dfad7458ab', 'd', 'No afecta a la estabilidad transversal, sólo a la longitudinal.', false, '2025-09-13 13:53:11.390943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c08724f-d2f4-4d79-9c77-d11e156f284c', '29241ad1-fca5-4c99-a3df-d112af476128', 'a', 'Entre 1 y 2 horas.', false, '2025-09-13 13:53:11.391224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4af8ed62-b9f7-4ec2-b8a2-3a8896765ab7', '29241ad1-fca5-4c99-a3df-d112af476128', 'b', 'Menos de 24 horas.', false, '2025-09-13 13:53:11.391363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48c9c781-46c2-45f6-8f0a-e1f431821d99', '29241ad1-fca5-4c99-a3df-d112af476128', 'c', 'Indeterminado, ya que los helicópteros vuelan a relativamente baja velocidad.', false, '2025-09-13 13:53:11.391531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aeefe2d9-e386-437d-aada-225f9320779f', '29241ad1-fca5-4c99-a3df-d112af476128', 'd', 'Inmediato, ya que los helicópteros vuelan a gran velocidad.', true, '2025-09-13 13:53:11.391703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2cadd08-c3a3-4cbd-8822-c990b658d218', '011c0cf2-7a33-488a-ba9b-203561341b7d', 'a', 'Las bengalas tienen un alcance visual superior al de un cohete con paracaídas, pero menor', true, '2025-09-13 13:53:11.392008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bbafa62-dfb5-4d4a-a9df-b3af41324240', '011c0cf2-7a33-488a-ba9b-203561341b7d', 'b', 'Las balsas salvavidas, una vez a flote, resistirán un período mínimo de 15 días de exposición a la intemperie, en cualquier estado de mar.', false, '2025-09-13 13:53:11.392159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79158972-31a2-4fc5-9024-4b8858f3a3bf', '011c0cf2-7a33-488a-ba9b-203561341b7d', 'c', 'Los extintores de dióxido de carbono (CO2) son adecuados para la extinción de fuegos de origen', false, '2025-09-13 13:53:11.392292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bc17fc9-e425-466a-a877-0a20b1c8af9c', '011c0cf2-7a33-488a-ba9b-203561341b7d', 'd', 'La utilización de un reflector de radar en una embarcación de casco no metálico no es obligatoria en las zonas de navegación 5 y 6.', false, '2025-09-13 13:53:11.392424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de942dee-afd6-4a83-a361-0b006348c86c', '7efe9a0a-7269-4083-b0fa-d4c8da17eeca', 'a', 'Saltar al agua y nadar lentamente para reducir la hipotermia.', false, '2025-09-13 13:53:11.392706+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9808aa24-c956-4d67-a32c-0c963ac99195', '7efe9a0a-7269-4083-b0fa-d4c8da17eeca', 'b', 'Llevar consigo la radiobaliza.', false, '2025-09-13 13:53:11.392849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('561fdf5a-bc3c-495e-8d9a-09f80fa26e4c', '7efe9a0a-7269-4083-b0fa-d4c8da17eeca', 'c', 'Mantener agrupada a toda la tripulación.', false, '2025-09-13 13:53:11.392981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d0004ae-3f45-4f0a-99b6-1f559c226787', '7efe9a0a-7269-4083-b0fa-d4c8da17eeca', 'd', 'Subirse a cualquier objeto flotante para reducir la hipotermia.', true, '2025-09-13 13:53:11.39311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84a076be-55fe-4d25-bccd-11be0081001e', 'ad31745d-87c6-40bf-b508-fa1d04cf6289', 'a', 'La del centro de gravedad respecto al centro de carena.', false, '2025-09-13 13:53:11.393391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a85fcd60-e90b-4880-9fc5-8684772e7132', 'ad31745d-87c6-40bf-b508-fa1d04cf6289', 'b', 'La del metacentro respecto al centro de gravedad, siempre que estos coincidan en el mismo', true, '2025-09-13 13:53:11.393525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40139a02-22ac-4c14-9ca3-9a69bb895786', 'ad31745d-87c6-40bf-b508-fa1d04cf6289', 'c', 'La del metacentro respecto al centro de gravedad.', false, '2025-09-13 13:53:11.393806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('739df0a4-8af3-49b1-a2bf-800616d9e8b0', 'ad31745d-87c6-40bf-b508-fa1d04cf6289', 'd', 'La del metacentro respecto al centro de carena.', false, '2025-09-13 13:53:11.393938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('321fb84b-5567-46c6-8e62-52124faac6ad', 'a56a6459-a411-42d9-a36e-56ae3f86ba4c', 'a', 'Una radiobaliza de localización EPIRB es empleada como un sistema de alerta en caso de socorro indicando, a las autoridades SAR, la identidad y la posición de una persona o de un buque que está en peligro grave e inminente y requiere ayuda inmediata.', false, '2025-09-13 13:53:11.394223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('194a2aac-ed43-498d-8f96-ac340ee2adc0', 'a56a6459-a411-42d9-a36e-56ae3f86ba4c', 'b', 'Cada radiobaliza EPIRB se programa con una identidad única.', false, '2025-09-13 13:53:11.394353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10965ec1-79a0-4c42-b12f-9ef083824a71', 'a56a6459-a411-42d9-a36e-56ae3f86ba4c', 'c', 'El país programado en su radiobaliza EPIRB no se puede encontrar en la etiqueta de la identidad donde están generalmente todos los datos necesarios.', false, '2025-09-13 13:53:11.394491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94a07a11-0c5b-4aa2-98d0-5b1347225280', 'a56a6459-a411-42d9-a36e-56ae3f86ba4c', 'd', 'Marcar el nombre del buque es responsabilidad de los clientes. El cliente tiene que registrar su radiobaliza EPIRB en las autoridades apropiadas en su país.', true, '2025-09-13 13:53:11.394624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('546c4a42-290f-433c-ad06-15b2f5cb45a2', '4a71ae2a-747b-4eba-a47c-f2542a19dde5', 'a', 'Lanzar un cohete provisto de paracaídas.', false, '2025-09-13 13:53:11.394904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9396551-5fb4-4ccf-8586-689d2d2c81ff', '4a71ae2a-747b-4eba-a47c-f2542a19dde5', 'b', 'Dejar que el cable que envíe el helicóptero toque primero el agua, antes de cogerlo.', false, '2025-09-13 13:53:11.395033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4203de9a-84fc-448d-94f6-8c51d7f38d3e', '4a71ae2a-747b-4eba-a47c-f2542a19dde5', 'c', 'Amarrar el cable que envía el helicóptero a algún lugar de la embarcación.', true, '2025-09-13 13:53:11.395162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3c40f71-a6f0-4ca6-8e5b-23b005dba13e', '4a71ae2a-747b-4eba-a47c-f2542a19dde5', 'd', 'Al llegar a la puerta del helicóptero ayudar activamente a los profesionales para entrar a bordo. Meteorología', false, '2025-09-13 13:53:11.39529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2291134-5d55-49a5-89e4-68b617bf2243', 'd7f262a9-c2f9-42be-a8b4-0bca174d3940', 'a', 'Su dirección siempre coincidirá con la dirección del mar de viento.', false, '2025-09-13 13:53:11.395555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7023e438-8c9e-4a1b-b3a1-90f1691dbff0', 'd7f262a9-c2f9-42be-a8b4-0bca174d3940', 'b', 'Se produce como consecuencia de la relación calado/fondo a bajas velocidades.', true, '2025-09-13 13:53:11.395683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef9711ee-6169-461e-bf95-a1c38d0a9adb', 'd7f262a9-c2f9-42be-a8b4-0bca174d3940', 'c', 'No tiene por qué ir con el mar de viento.', false, '2025-09-13 13:53:11.395821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e845d468-18cc-4e76-a615-a14a309253ed', 'd7f262a9-c2f9-42be-a8b4-0bca174d3940', 'd', 'Su dirección nunca coincidirá con la dirección del mar de viento, ya que la dirección del viento siempre será opuesta a la dirección de la mar de fondo.', false, '2025-09-13 13:53:11.395949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e19fbeb-cc01-494d-9d1c-09d6726998df', '860d5149-6dea-4262-94a6-0ae701cafaa7', 'a', 'Niebla helada.', true, '2025-09-13 13:53:11.396222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72938ac1-be2a-4d93-982d-72accf37ccc5', '860d5149-6dea-4262-94a6-0ae701cafaa7', 'b', 'Niebla de radiación.', false, '2025-09-13 13:53:11.396351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4d302d4-0464-4e0b-a938-b8403ad56d44', '860d5149-6dea-4262-94a6-0ae701cafaa7', 'c', 'Niebla de advección.', false, '2025-09-13 13:53:11.396478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24433863-2fd7-44b4-aa07-85d7dc907340', '860d5149-6dea-4262-94a6-0ae701cafaa7', 'd', 'Niebla frontal.', false, '2025-09-13 13:53:11.396606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f72d7f6-16d2-4a8b-bd1f-bc71931e0266', 'e32f5514-cf86-49a2-aee3-94aa2bd497bd', 'a', 'Está relacionada con la corriente del Labrador.', true, '2025-09-13 13:53:11.396889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('720205bc-417f-4674-bdd0-76aa7d0e4db5', 'e32f5514-cf86-49a2-aee3-94aa2bd497bd', 'b', 'Es de componente norte, invariable, de 1 nudo.', false, '2025-09-13 13:53:11.397017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('474adf58-0aa0-4dbb-9df4-2833d5a45544', 'e32f5514-cf86-49a2-aee3-94aa2bd497bd', 'c', 'Está relacionada con la corriente del Golfo.', false, '2025-09-13 13:53:11.397143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e9ade88-4c30-4476-a7a1-d7eb10473b1b', 'e32f5514-cf86-49a2-aee3-94aa2bd497bd', 'd', 'Recorre previamente la costa francesa y tiene una intensidad constante a lo largo del año superior', false, '2025-09-13 13:53:11.397269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87314d7b-34ab-4ed0-ab3e-3a961a53ea75', '76abe2c9-4dd6-4e2c-a778-7f3b84448eb5', 'a', 'Leung.', false, '2025-09-13 13:53:11.397533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bcfdff8-e6e7-4b15-8f3f-955ee9dcc049', '76abe2c9-4dd6-4e2c-a778-7f3b84448eb5', 'b', 'Garbí.', false, '2025-09-13 13:53:11.397662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('977363df-4f0d-4737-9ce3-1aa78bfcf5ae', '76abe2c9-4dd6-4e2c-a778-7f3b84448eb5', 'c', 'Gregal.', true, '2025-09-13 13:53:11.397798+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f026b770-ae57-457c-86df-befaeb3a8d9a', '76abe2c9-4dd6-4e2c-a778-7f3b84448eb5', 'd', 'Bora.', false, '2025-09-13 13:53:11.397935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31b88943-acba-40d4-afd0-843313ad02b2', 'fcf15de0-6fb9-482e-a18e-e33363ad1c2b', 'a', 'Es la densidad de moléculas de vapor de agua en el aire.', true, '2025-09-13 13:53:11.398205+00');
