INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e13022-9ee1-4cfa-ac05-d100f0fe20f0', '66273cb6-f7d2-45be-a602-f21b50a95bbf', 'a', 'Si prolongamos el segmento de recta definida por Merak y Dubhe, 4 veces más, hacia el Polo Elevado, encontraremos la estrella Polar.', false, '2025-09-13 13:53:11.423519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44cb8694-a924-4862-8d64-bc88eb8450cf', '66273cb6-f7d2-45be-a602-f21b50a95bbf', 'b', 'Si hallamos las bisectrices de los dos ángulos que definen las estrellas de Casiopea, Caph-Shedar-Navi y Navi-Ksora-Segín, y las prolongamos hacia el Polo Elevado, llegaremos a la', false, '2025-09-13 13:53:11.423655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9876296-0b77-4d1b-acaf-6850d99039b9', '66273cb6-f7d2-45be-a602-f21b50a95bbf', 'c', 'Es la estrella con brillo estable, más brillante de las 99 del almanaque náutico.', true, '2025-09-13 13:53:11.423797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97c89be7-8a56-467e-98f2-8117999dd2ca', '66273cb6-f7d2-45be-a602-f21b50a95bbf', 'd', 'Es un astro cuyo paralelo de declinación está muy próximo a 90º.', false, '2025-09-13 13:53:11.423936+00');
