INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5579eac6-41a7-403a-a899-bbf448f27306', '4e2cdaca-2304-465c-8db6-e043e213114e', 'a', 'Se diferencia siempre de la Hora Civil en Greenwich en las horas equivalentes a 12 Husos.', false, '2025-09-13 13:53:11.424906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('256c9ec1-4cd4-4df4-9c93-c17f049d540e', '4e2cdaca-2304-465c-8db6-e043e213114e', 'b', 'La diferencia máxima entre la Hora legal y la Hora civil del lugar es de 1 hora, ya que la hora legal es la misma que la del meridiano central del Huso.', false, '2025-09-13 13:53:11.425044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('401777ed-5dc4-4b40-bb47-da30724cb58a', '4e2cdaca-2304-465c-8db6-e043e213114e', 'c', 'Es la hora correspondiente al Huso Horario. En un instante existen 12 horas diferentes.', false, '2025-09-13 13:53:11.425175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92cdedec-b710-48a0-9970-42b0578846a2', '4e2cdaca-2304-465c-8db6-e043e213114e', 'd', 'El Huso 12 está dividido en dos partes por el Meridiano de 180º; todos llevan la misma hora, pero la mitad que tiene Longitud W cuentan una fecha menos que la otra mitad que tiene Longitud', true, '2025-09-13 13:53:11.425308+00');
