INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8e298a9-9d03-45ad-9a99-97b467b2f7b8', '42bb6dea-66e6-4391-9bfd-4c4a5577e8df', 'b', 'La escala Saffir-Simpson clasifica los ciclones tropicales según la intensidad del viento en ocho', false, '2025-09-13 13:53:11.434335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b16a3845-ac98-4e4e-a76c-1656dc74e826', '42bb6dea-66e6-4391-9bfd-4c4a5577e8df', 'c', 'Si el viento rola en el sentido de las agujas del reloj y disminuye la presión, nos encontramos en el semicírculo izquierdo, cuadrante posterior.', false, '2025-09-13 13:53:11.434469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('063ceec7-aa58-44bb-bce2-53e47b484ff5', '42bb6dea-66e6-4391-9bfd-4c4a5577e8df', 'd', 'Si el viento rola en el sentido contrario a las agujas del reloj y aumenta el viento, nos encontramos en el semicírculo izquierdo, cuadrante anterior.', true, '2025-09-13 13:53:11.434604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('994e27cf-cda1-4262-b786-dee94e262f1e', 'bd297b6b-04cc-44b9-8fc4-9a5c67b10070', 'a', 'Es un fuerte flujo de agua cálida, que forma parte de la corriente del golfo y fluye hacia el norte desde el mar Caribe entre Cuba y la península de Yucatán en México.', true, '2025-09-13 13:53:11.434895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbd8fa3e-77e6-4e74-8664-e5f32c370837', 'bd297b6b-04cc-44b9-8fc4-9a5c67b10070', 'b', 'Es un fuerte flujo de agua fría, que forma parte de la corriente del golfo y fluye hacia el norte desde el mar Caribe entre Cuba y la península de Yucatán en México.', false, '2025-09-13 13:53:11.435032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fb4de94-90b1-4de2-8589-b7fc15b80860', 'bd297b6b-04cc-44b9-8fc4-9a5c67b10070', 'c', 'Es un fuerte flujo de agua cálida, que parte de la corriente del golfo y fluye hacia el sur desde el mar Caribe entre Cuba y la península de Yucatán en México.', false, '2025-09-13 13:53:11.435169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e555665-eb66-40f4-ad75-51e8534c9b10', 'bd297b6b-04cc-44b9-8fc4-9a5c67b10070', 'd', 'Es un fuerte flujo de agua fría, que parte de la corriente del golfo y fluye hacia el sur desde el mar Caribe entre Cuba y la península de Yucatán en México.', false, '2025-09-13 13:53:11.435307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48692280-380e-4e8c-9a7c-fb71175aae6c', '8836ae14-99e3-4f96-8dc9-75ad7e967ffd', 'a', 'La región del globo terrestre donde convergen los vientos alisios del hemisferio norte con los del hemisferio sur.', true, '2025-09-13 13:53:11.435599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10aacbc4-f203-40db-81d8-979042226c9a', '8836ae14-99e3-4f96-8dc9-75ad7e967ffd', 'b', 'Una franja o cinturón de alta presión constituido por corrientes de aire ascendente.', false, '2025-09-13 13:53:11.435739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e16b921-c34b-4db6-8b5c-900ddd0646de', '8836ae14-99e3-4f96-8dc9-75ad7e967ffd', 'c', 'Una franja o cinturón de baja presión constituido por corrientes de aire descendente.', false, '2025-09-13 13:53:11.4359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d405572-234a-4941-afa6-128c27934af1', '8836ae14-99e3-4f96-8dc9-75ad7e967ffd', 'd', 'La región del globo terrestre donde convergen grandes masas de aire frio y seco provenientes del norte y sur de la zona intertropical.', false, '2025-09-13 13:53:11.436041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19b62f65-4196-4e1f-9ae7-360f984b2be7', '5c2e53fc-3bc4-4a1f-beff-533821ee2551', 'a', 'Son los vientos constantes planetarios predominantes en latitudes medias (entre los 35° y los 65° de latitud en cada hemisferio), que soplan generalmente de oeste a este.', false, '2025-09-13 13:53:11.436347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d80e5819-78b9-4d55-b3f0-6f1e3d1f0c45', '5c2e53fc-3bc4-4a1f-beff-533821ee2551', 'b', 'Rodean las altas presiones dinámicas sobre los océanos de latitudes tropicales y subtropicales, cerrando el bucle con los vientos alisios cercanos al ecuador.', false, '2025-09-13 13:53:11.436516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c460a589-0c05-4419-bfe7-f3561e7e3253', '5c2e53fc-3bc4-4a1f-beff-533821ee2551', 'c', 'Tienen una componente hacia los polos, por lo que en el hemisferio norte son predominantemente del noroeste y en el hemisferio sur, del suroeste.', true, '2025-09-13 13:53:11.436674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77248fc6-0c73-425f-a48f-175463766c53', '5c2e53fc-3bc4-4a1f-beff-533821ee2551', 'd', 'Estos vientos son especialmente intensos en el hemisferio sur, debido a la ausencia de tierra. En el hemisferio norte, ejercen una influencia moderadora en el clima de las costas occidentales.', false, '2025-09-13 13:53:11.436833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4219626-237c-4f4e-a48f-16a8666a60b4', 'fd2de028-5264-47a5-8da1-9e202713b086', 'a', 'Corriente de Perú.', false, '2025-09-13 13:53:11.437156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfed46c2-8c2d-474d-b80e-6472623af68b', 'fd2de028-5264-47a5-8da1-9e202713b086', 'b', 'Corriente de Auckland.', false, '2025-09-13 13:53:11.437444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('579c98c4-723f-46cf-8560-6a920c93fd39', 'fd2de028-5264-47a5-8da1-9e202713b086', 'c', 'Corriente de Benguela.', true, '2025-09-13 13:53:11.437604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e311daf1-3a92-430c-bad3-0bceab215429', 'fd2de028-5264-47a5-8da1-9e202713b086', 'd', 'Corriente de Nueva Guinea.', false, '2025-09-13 13:53:11.437756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bddc624-72cb-4fa2-9a67-61c49e82144e', '8a41beba-07d0-48db-b6fa-44ad168a8ae1', 'a', 'Estar formado por la refracción de la luz solar al atravesar cristales de hielo en suspensión en la', false, '2025-09-13 13:53:11.43809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b266273-db5a-44ac-aa88-7c9d4b3f0449', '8a41beba-07d0-48db-b6fa-44ad168a8ae1', 'b', 'Consistir en un grupo de arcos concéntricos, con colores que van desde el violeta hasta el rojo, producidos en la atmósfera sobre una pantalla de gotitas de agua de lluvia, llovizna o niebla.', false, '2025-09-13 13:53:11.438261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de71793d-e235-4e7a-9d08-1169d9614631', '8a41beba-07d0-48db-b6fa-44ad168a8ae1', 'c', 'Tener forma de anillo, arco, columna o puntos luminosos blanquecinos producidos por la reflexión o la refracción de la luz en los cristales de hielo que están en suspensión en la atmósfera de la Tierra y que pueden exhibir la coloración del prisma con el rojo en su zona interior y el azul en su parte exterior.', true, '2025-09-13 13:53:11.438429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dfffe8e-abd8-43a0-9e7b-14cd351371cb', '8a41beba-07d0-48db-b6fa-44ad168a8ae1', 'd', 'Consistir en un cambio del color del sol en el momento de desaparecer su limbo superior en el', false, '2025-09-13 13:53:11.438587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6e9e916-912d-4a07-a3c9-ef7e0b67cbe8', '14fe32f8-6170-4e7d-89fa-6f732cf2d6ce', 'a', 'Se forma en los casquetes polares circulando de este a oeste.', false, '2025-09-13 13:53:11.438904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9177b50f-e096-4848-877a-2da92503b94e', '14fe32f8-6170-4e7d-89fa-6f732cf2d6ce', 'b', 'Se produce por el choque entre una masa de aire subtropical y otra tropical formando un flujo hacia el oeste.', false, '2025-09-13 13:53:11.439043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51de8b31-ce4a-4472-8b56-2e81291209f3', '14fe32f8-6170-4e7d-89fa-6f732cf2d6ce', 'c', 'Es una corriente de aire que se encuentra entre la estratosfera y la mesosfera.', false, '2025-09-13 13:53:11.439174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa850f45-2b50-43a2-9a7e-7a34b8a967e5', '14fe32f8-6170-4e7d-89fa-6f732cf2d6ce', 'd', 'Es una fuerte corriente de aire que circula de oeste a este de forma constante en latitudes medias de ambos hemisferios.', true, '2025-09-13 13:53:11.439305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f32f1e34-1443-4409-9e1d-83c10062fe54', 'ea292a0f-ecf8-49b8-aa43-ce5cdbaa2d24', 'a', 'Es el hielo flotante en el cual la concentración es de 1/10 a 3/10 y donde el agua predomina sobre', false, '2025-09-13 13:53:11.43959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6082f9b1-65d4-4e18-94f9-bc884ccd197f', 'ea292a0f-ecf8-49b8-aa43-ce5cdbaa2d24', 'b', 'Es el hielo flotante en el cual la concentración es de 9/10 a menos de 10/10.', false, '2025-09-13 13:53:11.439728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17830036-8e57-4ceb-a9a6-5976269434aa', 'ea292a0f-ecf8-49b8-aa43-ce5cdbaa2d24', 'c', 'En el hielo flotante en el cual la concentración es de 4/10 a 6/10, con muchos canales y polinias y con bandejones que mayormente no están en contacto entre sí.', false, '2025-09-13 13:53:11.439892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af2a4e23-ac12-46cd-a547-0ccdc2f19aca', 'ea292a0f-ecf8-49b8-aa43-ce5cdbaa2d24', 'd', 'Es el hielo flotante en el cual la concentración es de 7/10 a 8/10 compuesto de bandejones, la mayoría de los cuales están en contacto.', true, '2025-09-13 13:53:11.440045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cc4021c-2707-4408-9397-83454d330c13', 'f5685b4d-ce47-4050-9a82-3f2ede3eb17f', 'a', 'Exosfera y Tropopausa.', false, '2025-09-13 13:53:11.440337+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26de4815-f551-4590-b6b6-caa103b1a263', 'f5685b4d-ce47-4050-9a82-3f2ede3eb17f', 'b', 'Troposfera y Estratosfera.', false, '2025-09-13 13:53:11.44047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('980d13d7-a199-48af-8477-69428620d479', 'f5685b4d-ce47-4050-9a82-3f2ede3eb17f', 'c', 'Ozonosfera e Ionosfera.', true, '2025-09-13 13:53:11.440602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56316378-c4f8-42a2-aeb4-8c967feae061', 'f5685b4d-ce47-4050-9a82-3f2ede3eb17f', 'd', 'Mesosfera y Termosfera. Inglés', false, '2025-09-13 13:53:11.440737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cdf11453-4103-4cae-9c5d-667b41b95334', 'e9799145-f78c-4c4d-aab2-75eb080e6d20', 'a', 'Estoy/la motonave … está sin gobierno y en peligro.', false, '2025-09-13 13:53:11.441021+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e13f4f49-b0c2-4f96-b6c2-d0eaf79a17ff', 'e9799145-f78c-4c4d-aab2-75eb080e6d20', 'b', 'Estoy/la motonave … está hundiéndose y en peligro.', false, '2025-09-13 13:53:11.441153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a32d6ded-94ba-4509-a6ee-bcdfc927bfd4', 'e9799145-f78c-4c4d-aab2-75eb080e6d20', 'c', 'Estoy/la motonave … yendo a la deriva hacia una situación de peligro.', true, '2025-09-13 13:53:11.441285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e09cf34-85db-4be9-835f-917331a8727f', 'e9799145-f78c-4c4d-aab2-75eb080e6d20', 'd', 'Estoy/la motonave … está dirigiéndose hacia una situación de peligro.', false, '2025-09-13 13:53:11.441419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b389cf12-dedd-4f61-a4c9-f376aa3540c4', '0ecd47a8-9e6b-4f1d-8de9-7ca1c0f30d99', 'a', '¿Qué parte del buque ha varado? La varada es a proa/en el medio/a popa/en toda la eslora.', true, '2025-09-13 13:53:11.441695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c61079a4-31ab-4e0b-980e-4e150e22194a', '0ecd47a8-9e6b-4f1d-8de9-7ca1c0f30d99', 'b', '¿Qué parte del buque está encallada? Encallada a popa/a lo ancho/a proa/a lo largo.', false, '2025-09-13 13:53:11.441827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ebbc2c7-eb98-4a2f-9571-51b08c9168fb', '0ecd47a8-9e6b-4f1d-8de9-7ca1c0f30d99', 'c', '¿Qué parte del buque ha colisionado? La colisión es a proa/en el medio/a popa/en toda la eslora.', false, '2025-09-13 13:53:11.44196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9aea3c48-6cb0-4fba-9917-a0e05076f215', '0ecd47a8-9e6b-4f1d-8de9-7ca1c0f30d99', 'd', '¿Qué parte del buque está en tierra? Está en tierra la popa/a lo ancho/la proa/a lo largo.', false, '2025-09-13 13:53:11.4421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b07b2ba-8532-4f55-849e-de5d4c955f24', 'd48f5dca-fa5f-4547-80b7-41ce5c969deb', 'a', 'Calado / Levar ancla / Garreo del ancla.', false, '2025-09-13 13:53:11.442379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad065dfd-9972-45bc-8e34-e60bfd87c670', 'd48f5dca-fa5f-4547-80b7-41ce5c969deb', 'b', 'Escape de agua / Arrastre del ancla / Garreo del ancla.', false, '2025-09-13 13:53:11.442644+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fab877e0-e234-4dfb-96c1-bd8a5ca74f4c', 'd48f5dca-fa5f-4547-80b7-41ce5c969deb', 'c', 'Calado / Garreo del ancla / Arrastre del ancla.', true, '2025-09-13 13:53:11.442797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0649be73-885e-4724-9ce7-a260ece4ebd7', 'd48f5dca-fa5f-4547-80b7-41ce5c969deb', 'd', 'Secado / Deriva del ancla / Garreo del ancla.', false, '2025-09-13 13:53:11.442932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7702b39e-7893-4dec-81db-dd2c8d23e8c1', '70313b42-3884-44ff-b0f1-fecdafe22bd0', 'a', '¡Pasajeros y tripulación! Sigan a la tripulación de los botes a la cubierta de embarque de las estaciones de los botes/balsas salvavidas en cubierta.', false, '2025-09-13 13:53:11.44321+00');
