INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef6fd5f6-b3e8-44f1-b2b5-1004ef9d4634', '1c0ba149-a3d4-4965-9a27-544388187443', 'a', '¿Están listos para largar?', false, '2025-09-13 13:53:11.443903+00');
