INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcd9e1f7-1365-4ec7-8a0e-c7525ce4afb8', 'dc715393-5eba-4385-ad4d-2647c1bbe695', 'a', 'El viento, las corrientes y la mar por la dirección de donde provienen.', false, '2025-09-13 13:53:11.449466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e276e6f-a16e-4e12-b489-24a49f2518da', 'dc715393-5eba-4385-ad4d-2647c1bbe695', 'b', 'El viento, las corrientes y la mar por la dirección hacia dónde va la masa de aire o agua.', false, '2025-09-13 13:53:11.449601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa07306e-1178-48c1-87ca-91e0033f1d22', 'dc715393-5eba-4385-ad4d-2647c1bbe695', 'c', 'Las corrientes y la mar por la dirección hacia dónde va la masa de agua y el viento por la dirección de donde proviene.', false, '2025-09-13 13:53:11.449733+00');
