INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53b5b2fd-e8f2-4606-a82f-9ea67ff5ac2f', '366e8583-466c-4342-9811-8339080d82ef', 'c', 'Horizonte verdadero.', true, '2025-09-13 13:53:11.450415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('577376b4-20da-4d39-ad8b-b3513052ff3c', '366e8583-466c-4342-9811-8339080d82ef', 'd', 'Horizonte aparente.', false, '2025-09-13 13:53:11.450547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93241fe1-cd9d-4b42-ba5f-f6687c5bcbe5', 'f413629f-c144-4dda-a41d-1c8d8ddddeef', 'a', 'Si prolongamos el segmento de recta definida por Merak y Dubhe, 4 veces más, hacia el Polo Elevado, encontraremos la estrella Polar.', false, '2025-09-13 13:53:11.450831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a6d9dcf-691a-48f0-8275-4bdc5fd4361f', 'f413629f-c144-4dda-a41d-1c8d8ddddeef', 'b', 'Si hallamos las bisectrices de los dos ángulos que definen las estrellas de Casiopea, Caph-Shedar-Navi y Navi-Ksora-Segín, y las prolongamos hacia el Polo Elevado, llegaremos a la', false, '2025-09-13 13:53:11.450965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc6b83f0-4548-42be-89a9-51200e6da333', 'f413629f-c144-4dda-a41d-1c8d8ddddeef', 'c', 'Es la estrella con brillo estable, más brillante de las 99 del almanaque náutico.', true, '2025-09-13 13:53:11.451098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d632ddf9-7285-4efc-8360-1da1d348823a', 'f413629f-c144-4dda-a41d-1c8d8ddddeef', 'd', 'Es un astro cuyo paralelo de declinación está muy próximo a 90º.', false, '2025-09-13 13:53:11.45123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('535261e9-e67e-489e-91a3-bd50d08e0640', 'ea9209a3-d001-4875-b5a7-59b53109cd03', 'a', 'Se diferencia siempre de la Hora Civil en Greenwich en las horas equivalentes a 12 Husos.', false, '2025-09-13 13:53:11.451504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74b9eee9-a4cd-4159-bbe1-263faea41b2d', 'ea9209a3-d001-4875-b5a7-59b53109cd03', 'b', 'La diferencia máxima entre la Hora legal y la Hora civil del lugar es de 1 hora, ya que la hora legal es la misma que la del meridiano central del Huso.', false, '2025-09-13 13:53:11.451634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb650c6e-4ff4-4dcc-b560-66408ddb690f', 'ea9209a3-d001-4875-b5a7-59b53109cd03', 'c', 'Es la hora correspondiente al Huso Horario. En un instante existen 12 horas diferentes.', false, '2025-09-13 13:53:11.451766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83618fa6-37b0-42af-9b14-fb1b925f1027', 'ea9209a3-d001-4875-b5a7-59b53109cd03', 'd', 'El Huso 12 está dividido en dos partes por el Meridiano de 180º; todos llevan la misma hora, pero la mitad que tiene Longitud W cuentan una fecha menos que la otra mitad que tiene Longitud', true, '2025-09-13 13:53:11.451898+00');
