INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('499a33dc-433e-4ba1-bd08-72d402cb24be', 'f404a4df-e9b1-437f-96da-e18830740194', 'a', 'Las estrellas circumpolares no tienen orto ni ocaso para el observador de una determinada latitud.', false, '2025-09-13 13:53:11.454411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('335a8013-2682-40a4-8329-2453ed9123b8', 'f404a4df-e9b1-437f-96da-e18830740194', 'b', 'Ninguna estrella tiene orto ni ocaso para un observador situado en el Polo Norte, es decir, a 90º', false, '2025-09-13 13:53:11.454541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab0661de-c990-42c1-9fb0-9e23c1a17d87', 'f404a4df-e9b1-437f-96da-e18830740194', 'c', 'Para un observador situado en el Ecuador, todas las estrellas tienen orto y ocaso, excepto la estrella Polar, que está en el horizonte.', false, '2025-09-13 13:53:11.454675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bc3bada-985a-49f8-9876-0a99b4213164', 'f404a4df-e9b1-437f-96da-e18830740194', 'd', 'Las estrellas no tienen orto ni ocaso si su distancia angular desde el polo es superior a la latitud del observador.', true, '2025-09-13 13:53:11.454846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be47fc87-0226-49b0-9abf-97c0a84b8b70', '2f39d528-d605-4161-b8c2-ec0c80f81ed2', 'a', 'La eclíptica.', false, '2025-09-13 13:53:11.455161+00');
