INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('762bb94d-fb34-480f-8bcc-328e04092a76', '1883f882-51b1-4bc0-b6be-e41f6fc52757', 'a', 'Estar formado por la refracción de la luz solar al atravesar cristales de hielo en suspensión en la', false, '2025-09-13 13:53:11.463275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac298df4-3d8a-4911-b492-f7fd6f48e3bb', '1883f882-51b1-4bc0-b6be-e41f6fc52757', 'b', 'Consistir en un grupo de arcos concéntricos, con colores que van desde el violeta hasta el rojo, producidos en la atmósfera sobre una pantalla de gotitas de agua de lluvia, llovizna o niebla.', false, '2025-09-13 13:53:11.463416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cbd6f70-7108-4166-b772-cc33adfb1a93', '1883f882-51b1-4bc0-b6be-e41f6fc52757', 'c', 'Tener forma de anillo, arco, columna o puntos luminosos blanquecinos producidos por la reflexión o la refracción de la luz en los cristales de hielo que están en suspensión en la atmósfera de la Tierra y que pueden exhibir la coloración del prisma con el rojo en su zona interior y el azul en su parte exterior.', true, '2025-09-13 13:53:11.463552+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80760c25-d0bd-401b-982f-6c58032ce128', '1883f882-51b1-4bc0-b6be-e41f6fc52757', 'd', 'Consistir en un cambio del color del sol en el momento de desaparecer su limbo superior en el', false, '2025-09-13 13:53:11.463693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('929e7fad-bb60-422c-a5c7-e93271efea2c', '1573beed-bded-47df-afc1-cecfcdd91a9c', 'a', 'Son los vientos constantes planetarios predominantes en latitudes medias (entre los 35° y los 65° de latitud en cada hemisferio), que soplan generalmente de oeste a este.', false, '2025-09-13 13:53:11.464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aae0eb2e-eaea-44b7-8ca0-313630847805', '1573beed-bded-47df-afc1-cecfcdd91a9c', 'b', 'Rodean las altas presiones dinámicas sobre los océanos de latitudes tropicales y subtropicales, cerrando el bucle con los vientos alisios cercanos al ecuador.', false, '2025-09-13 13:53:11.464136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c13751d0-4317-43e4-992a-b0895f9369bc', '1573beed-bded-47df-afc1-cecfcdd91a9c', 'c', 'Tienen una componente hacia los polos, por lo que en el hemisferio norte son predominantemente del noroeste y en el hemisferio sur, del suroeste.', true, '2025-09-13 13:53:11.464268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb0f0dab-151d-40b0-bad8-f854debb4184', '1573beed-bded-47df-afc1-cecfcdd91a9c', 'd', 'Estos vientos son especialmente intensos en el hemisferio sur, debido a la ausencia de tierra. En el hemisferio norte, ejercen una influencia moderadora en el clima de las costas occidentales.', false, '2025-09-13 13:53:11.464397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e26543b-38a1-428b-97b9-344303617c9a', '7977065b-82bd-4bb5-b4b5-fdf9f0fe63e5', 'a', 'En el hemisferio norte, el semicírculo manejable está a la derecha de la trayectoria y el semicírculo peligroso a la izquierda.', false, '2025-09-13 13:53:11.464677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('442bffb7-f4a7-471a-b1a3-9fe2e75860d9', '7977065b-82bd-4bb5-b4b5-fdf9f0fe63e5', 'b', 'La escala Saffir-Simpson clasifica los ciclones tropicales según la intensidad del viento en ocho', false, '2025-09-13 13:53:11.464818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b07d4a8-b7b6-44a6-bcb1-60bae0b81f57', '7977065b-82bd-4bb5-b4b5-fdf9f0fe63e5', 'c', 'Si el viento rola en el sentido de las agujas del reloj y disminuye la presión, nos encontramos en el semicírculo izquierdo, cuadrante posterior.', false, '2025-09-13 13:53:11.46495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('829f026d-28ee-48e5-bdf3-d8b38a4c43fe', '7977065b-82bd-4bb5-b4b5-fdf9f0fe63e5', 'd', 'Si el viento rola en el sentido contrario a las agujas del reloj y aumenta el viento, nos encontramos en el semicírculo izquierdo, cuadrante anterior.', true, '2025-09-13 13:53:11.465082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b47e894-df81-44e2-9b69-2ae51978ae53', '0d6ca96c-e8a3-45c7-8782-08d1cc29fdc3', 'a', 'La región del globo terrestre donde convergen los vientos alisios del hemisferio norte con los del hemisferio sur.', true, '2025-09-13 13:53:11.465354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71d8225b-242e-4c0b-a95c-d9b5fcd99135', '0d6ca96c-e8a3-45c7-8782-08d1cc29fdc3', 'b', 'Una franja o cinturón de alta presión constituido por corrientes de aire ascendente.', false, '2025-09-13 13:53:11.465619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9186a525-ddfd-4ad1-97fa-11a44ac4ccc5', '0d6ca96c-e8a3-45c7-8782-08d1cc29fdc3', 'c', 'Una franja o cinturón de baja presión constituido por corrientes de aire descendente.', false, '2025-09-13 13:53:11.465752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c056e17b-5539-4551-9085-e53ad7fbef4d', '0d6ca96c-e8a3-45c7-8782-08d1cc29fdc3', 'd', 'La región del globo terrestre donde convergen grandes masas de aire frio y seco provenientes del norte y sur de la zona intertropical.', false, '2025-09-13 13:53:11.465889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af0c0903-adf9-4beb-aa4b-39792f8c4854', 'd6dd1cb9-9f49-4eb2-91bb-c83c8f7f2052', 'a', 'Es una medida empírica de la intensidad del viento medio y se fundamenta en el estado del mar y', false, '2025-09-13 13:53:11.466173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d921ad0-7343-4e27-a1d7-3977e6e7b2f2', 'd6dd1cb9-9f49-4eb2-91bb-c83c8f7f2052', 'b', 'Es una escala meteorológica referida a las perturbaciones de menor tamaño y duración, típicamente inferiores a las de las tormentas individuales o a unos 2 km.', false, '2025-09-13 13:53:11.466302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1911c203-5390-482e-a02e-aa9e40ccb952', 'd6dd1cb9-9f49-4eb2-91bb-c83c8f7f2052', 'c', 'Cataloga la fuerza estimada de los tornados en función del daño que provocan.', true, '2025-09-13 13:53:11.466432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe9d4750-7eec-44de-95ca-68aaa3c4b151', 'd6dd1cb9-9f49-4eb2-91bb-c83c8f7f2052', 'd', 'Clasifica los diferentes estados de la mar en 10 grados tomando como referencia la altura de las', false, '2025-09-13 13:53:11.46656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74ba1a07-ed89-4df5-854a-d6e993159f09', 'a8c39179-855d-4fc6-85ef-58756eef3f66', 'a', 'Es un fuerte flujo de agua cálida, que forma parte de la corriente del golfo y fluye hacia el norte desde el mar Caribe entre Cuba y la península de Yucatán en México.', true, '2025-09-13 13:53:11.466835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d436efb-daa9-4902-98e0-3ba530a24364', 'a8c39179-855d-4fc6-85ef-58756eef3f66', 'b', 'Es un fuerte flujo de agua fría, que forma parte de la corriente del golfo y fluye hacia el norte desde el mar Caribe entre Cuba y la península de Yucatán en México.', false, '2025-09-13 13:53:11.466978+00');
