INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6619d7b4-7252-4e98-99e3-cf6daecf7ea2', 'ceba8fa7-09e0-4823-9edc-80c037df9447', 'a', 'Es el hielo flotante en el cual la concentración es de 1/10 a 3/10 y donde el agua predomina sobre', false, '2025-09-13 13:53:11.468829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57b2bffb-81d2-488a-a995-5ac9319d0305', 'ceba8fa7-09e0-4823-9edc-80c037df9447', 'b', 'Es el hielo flotante en el cual la concentración es de 9/10 a menos de 10/10.', false, '2025-09-13 13:53:11.468963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b0a88bc-be96-407b-bbe7-34c001af8b12', 'ceba8fa7-09e0-4823-9edc-80c037df9447', 'c', 'En el hielo flotante en el cual la concentración es de 4/10 a 6/10, con muchos canales y polinias y con bandejones que mayormente no están en contacto entre sí.', false, '2025-09-13 13:53:11.46909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21c3a367-ea28-464a-b1e7-76bb2940f6b1', 'ceba8fa7-09e0-4823-9edc-80c037df9447', 'd', 'Es el hielo flotante en el cual la concentración es de 7/10 a 8/10 compuesto de bandejones, la mayoría de los cuales están en contacto.', true, '2025-09-13 13:53:11.469217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bcad096-3efe-40a9-a8bc-3357850e3ddf', '51c8a823-2c13-4965-82a5-853b6a298416', 'a', 'Se forma en los casquetes polares circulando de este a oeste.', false, '2025-09-13 13:53:11.469613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('008c2b39-cd34-4a0d-ac7c-cf00de87af02', '51c8a823-2c13-4965-82a5-853b6a298416', 'b', 'Se produce por el choque entre una masa de aire subtropical y otra tropical formando un flujo hacia el oeste.', false, '2025-09-13 13:53:11.469741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8afb0d61-3576-4895-aec7-79e023e36a1f', '51c8a823-2c13-4965-82a5-853b6a298416', 'c', 'Es una corriente de aire que se encuentra entre la estratosfera y la mesosfera.', false, '2025-09-13 13:53:11.469911+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f4a5112-e4af-41be-9567-fd6ccee39a74', '51c8a823-2c13-4965-82a5-853b6a298416', 'd', 'Es una fuerte corriente de aire que circula de oeste a este de forma constante en latitudes medias de ambos hemisferios. Inglés', true, '2025-09-13 13:53:11.470076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c93b890-31db-41d6-a5c2-c18054df0af8', 'f5d264ac-e8c9-460c-8fe1-a4b0cc0422c0', 'a', '¡Pasajeros y tripulación! Sigan a la tripulación de los botes a la cubierta de embarque de las estaciones de los botes/balsas salvavidas en cubierta.', false, '2025-09-13 13:53:11.470412+00');
