INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7084423-a269-4dd2-bbeb-0bc16bddbe65', '0e727cff-7174-478b-837d-993cbe6f97d6', 'a', 'Es un fotometeoro formado por refracción de la luz solar al atravesar cristales de hielo en suspensión en la atmósfera.', false, '2025-09-13 13:53:11.493161+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4342e5c8-ca65-423c-84f1-e17ae74a4127', '0e727cff-7174-478b-837d-993cbe6f97d6', 'b', 'Es un fotometeoro formado por la ionización de la atmósfera en ciertas latitudes y bajo ciertas condiciones meteorológicas.', true, '2025-09-13 13:53:11.493309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f5abd3a-16f3-4e5e-ad0d-7133dedb9ceb', '0e727cff-7174-478b-837d-993cbe6f97d6', 'c', 'Es un fotometeoro que aparece a 44º del Sol cuando este se encuentra cercano a la línea del', false, '2025-09-13 13:53:11.493467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e1f129e-2c03-4c6b-81f7-bf3cf0c19428', '0e727cff-7174-478b-837d-993cbe6f97d6', 'd', 'También se conoce como corona o halo.', false, '2025-09-13 13:53:11.493604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59c721e3-1f04-478a-8759-a8fec470761b', '18ad48a7-adc9-41e1-95e2-d9dd137592e0', 'a', 'A aquella área observada por satélite en la que la concentración o el espesor del hielo es considerablemente inferior a la de los alrededores, en las que las condiciones de navegación son considerablemente más fáciles que en las zonas de los alrededores.', true, '2025-09-13 13:53:11.493926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f88c2f1a-66cb-4e4e-83c9-e193028361fd', '18ad48a7-adc9-41e1-95e2-d9dd137592e0', 'b', 'A aquella área observada por el capitán o patrón de la embarcación en la que se aprecia que la concentración o el espesor del hielo es débil, produciéndose orificios o agujeros verticales en el hielo marino, que lo atraviesan, que dificultan la navegación.', false, '2025-09-13 13:53:11.494066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b907a76b-fb6d-4849-8bbe-f5836193385b', '18ad48a7-adc9-41e1-95e2-d9dd137592e0', 'c', 'A aquella área en la que las condiciones de hielo prevalecientes son muy rigurosas y hacen dificultosa la navegación.', false, '2025-09-13 13:53:11.494204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ea4a476-36bb-42a1-a449-8f357d6c8eab', '18ad48a7-adc9-41e1-95e2-d9dd137592e0', 'd', 'Un área grande de agua libremente navegable en la cual no hay presente ningún hielo de origen', false, '2025-09-13 13:53:11.494338+00');
