INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c969d38b-da55-4788-8973-3419ad6d75ce', '4d23b0f6-4c83-4da6-9969-7087773d47a1', 'b', 'Alta presión en altura, con vientos divergentes que facilitan la convección del aire caliente.', false, '2025-09-13 13:53:11.49546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9f4e43d-e35d-4a21-b219-190132ee94fe', '4d23b0f6-4c83-4da6-9969-7087773d47a1', 'c', 'Baja temperatura del mar que favorezca la evaporación.', false, '2025-09-13 13:53:11.495591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2a4230e-3407-45d3-9f1a-bc1cf31fc51b', '4d23b0f6-4c83-4da6-9969-7087773d47a1', 'd', 'Ausencia de viento, o viento débil, en superficie para facilitar las corrientes ascendentes.', false, '2025-09-13 13:53:11.495729+00');
