INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f965ed5-1acb-4cee-b5b6-15a67244712e', '69daf92d-d084-4abc-810c-40d5adfdd562', 'a', 'Es la empleada para categorizar ciclones.', false, '2025-09-13 13:53:11.496674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9745d11c-af26-4cb2-b321-b14feecaca1c', '69daf92d-d084-4abc-810c-40d5adfdd562', 'b', 'Es la empleada para categorizar tornados.', true, '2025-09-13 13:53:11.496818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef8f1160-bdaa-4752-ad4f-e21ac1d5f93d', '69daf92d-d084-4abc-810c-40d5adfdd562', 'c', 'Tiene 8 categorías.', false, '2025-09-13 13:53:11.49695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ef02c63-4c49-461f-9359-080d6e292575', '69daf92d-d084-4abc-810c-40d5adfdd562', 'd', 'No tiene categorías, y solo nos habla sobre velocidades del viento y alturas de ola.', false, '2025-09-13 13:53:11.497213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('095a2b51-afa0-4fdf-893c-11eb3587a7fa', '20855bdb-6858-4124-809a-56d06c1327a3', 'a', 'Las bajas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Norte y sureste (SE) para los del hemisferio Sur.', false, '2025-09-13 13:53:11.497502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a574cfd-01cb-4846-96e6-ed2bf5d0cfe2', '20855bdb-6858-4124-809a-56d06c1327a3', 'b', 'Las altas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Norte y sureste (SE) para los del hemisferio Sur.', true, '2025-09-13 13:53:11.497634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a295869f-372b-46ac-941b-4b6702d71abe', '20855bdb-6858-4124-809a-56d06c1327a3', 'c', 'Las bajas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Sur y sureste (SE) para los del hemisferio Norte.', false, '2025-09-13 13:53:11.497776+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1add0aac-0425-47a4-aa1c-c83bfbd7fea0', '20855bdb-6858-4124-809a-56d06c1327a3', 'd', 'Las altas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Sur y sureste (SE) para los del hemisferio Norte.', false, '2025-09-13 13:53:11.497908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('070d0098-05c5-4de5-af6e-b7c5e7135cea', '87c15974-ec08-4075-ae12-103a0cdac3ce', 'a', 'La zona de calmas ecuatoriales o Doldrums es la zona que rodea a la Tierra próxima al ecuador, que coincide aproximadamente con el cinturón de bajas presiones conocido como la ITCZ.', false, '2025-09-13 13:53:11.498186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab2a8948-eea0-4eb3-ad2d-b0502f2f40c8', '87c15974-ec08-4075-ae12-103a0cdac3ce', 'b', 'En estas regiones reinan las altas presiones y se producen grandes corrientes ascendentes de aire alimentadas por los alisios que allí convergen.', true, '2025-09-13 13:53:11.498318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23d1cd30-d951-4783-aca8-0d70c335ece0', '87c15974-ec08-4075-ae12-103a0cdac3ce', 'c', 'Se denominan de esta manera debido a las corrientes de agua oceánica, en particular las ecuatorial norte y contracorriente ecuatorial.', false, '2025-09-13 13:53:11.498449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e6ce218-8fb0-4495-b0d1-2c0183db04ef', '87c15974-ec08-4075-ae12-103a0cdac3ce', 'd', 'También conocidas como «latitudes de los caballos», son las zonas comprendidas entre los alisios y los ponientes de las latitudes medias. Inglés', false, '2025-09-13 13:53:11.498581+00');
