INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bea77a52-baf7-4276-971e-30829843b8f9', 'acaa3461-788b-4392-966d-e73e9ffa7e43', 'c', 'Baja temperatura del mar que favorezca la evaporación.', false, '2025-09-13 13:53:11.522713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3846f00-0f2d-43bd-b4eb-c5f7cb4d194d', 'acaa3461-788b-4392-966d-e73e9ffa7e43', 'd', 'Ausencia de viento, o viento débil, en superficie para facilitar las corrientes ascendentes.', false, '2025-09-13 13:53:11.522844+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99280ad9-7a07-4d7d-bea9-491579d7b00a', '96119ec0-e409-4fe1-8dba-624461e3b771', 'a', 'A aquella área observada por satélite en la que la concentración o el espesor del hielo es considerablemente inferior a la de los alrededores, en las que las condiciones de navegación son considerablemente más fáciles que en las zonas de los alrededores.', true, '2025-09-13 13:53:11.523136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a44a32fc-c957-4125-8255-8052fb593bdf', '96119ec0-e409-4fe1-8dba-624461e3b771', 'b', 'A aquella área observada por el capitán o patrón de la embarcación en la que se aprecia que la concentración o el espesor del hielo es débil, produciéndose orificios o agujeros verticales en el hielo marino, que lo atraviesan, que dificultan la navegación.', false, '2025-09-13 13:53:11.523273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fffc8bef-0257-4db1-b3df-6ded40fb3677', '96119ec0-e409-4fe1-8dba-624461e3b771', 'c', 'A aquella área en la que las condiciones de hielo prevalecientes son muy rigurosas y hacen dificultosa la navegación.', false, '2025-09-13 13:53:11.523406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5c66399-23ee-4817-b9cd-4ec9e0b947de', '96119ec0-e409-4fe1-8dba-624461e3b771', 'd', 'Un área grande de agua libremente navegable en la cual no hay presente ningún hielo de origen', false, '2025-09-13 13:53:11.523543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41f73bd1-51b7-4d92-96bf-1426cf310679', '97df8ec9-c765-4a55-adc7-d0d63df1bcef', 'a', 'Corrientes de marea.', false, '2025-09-13 13:53:11.523827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('610bd1d2-c107-42c4-834d-e3e9d1be01ca', '97df8ec9-c765-4a55-adc7-d0d63df1bcef', 'b', 'Corrientes de flujo.', false, '2025-09-13 13:53:11.523961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80019afe-dd3c-4b05-977a-fdd95e586b16', '97df8ec9-c765-4a55-adc7-d0d63df1bcef', 'c', 'Corrientes de reflujo.', false, '2025-09-13 13:53:11.524098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69124e51-6a61-467f-9cb8-12de813050d9', '97df8ec9-c765-4a55-adc7-d0d63df1bcef', 'd', 'Corrientes de deriva.', true, '2025-09-13 13:53:11.524227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0197d14b-caf7-4172-9d9c-c06d4f3e819a', 'd8fe82a6-cf03-4df3-8397-3fe436c1bcd6', 'a', 'La Troposfera, la Estratosfera, la Mesosfera, la Termosfera y la Exosfera.', false, '2025-09-13 13:53:11.524503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53f4527e-6e2b-45c6-9c04-f4b09a831f6a', 'd8fe82a6-cf03-4df3-8397-3fe436c1bcd6', 'b', 'La Estratosfera, la Troposfera, la Mesosfera, la Termosfera y la Exosfera.', true, '2025-09-13 13:53:11.524635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f730dc98-91e5-4cf6-8ebe-c3edacb297fc', 'd8fe82a6-cf03-4df3-8397-3fe436c1bcd6', 'c', 'La Troposfera, la Estratosfera, la Mesosfera, la Exosfera y la Termosfera.', false, '2025-09-13 13:53:11.524765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33faed12-9521-4c16-85a9-b8b02a2e2ff1', 'd8fe82a6-cf03-4df3-8397-3fe436c1bcd6', 'd', 'La Estratosfera, la Troposfera, la Mesosfera, la Exosfera y la Termosfera.', false, '2025-09-13 13:53:11.524899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ab5dfa5-cf6b-4df4-947e-61b314613892', '5d6bd64e-1a8e-4870-8742-86d15e149076', 'a', 'La zona de calmas ecuatoriales o Doldrums es la zona que rodea a la Tierra próxima al ecuador, que coincide aproximadamente con el cinturón de bajas presiones conocido como la ITCZ.', true, '2025-09-13 13:53:11.525179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b964f0c-4d65-435d-b5f3-1e5fe99907d5', 'b0f4ff9b-ac29-4cfd-acea-eff458456b77', 'c', 'Son líneas que unen puntos con igual valor de temperatura en una superficie dada.', false, '2025-09-13 13:53:11.544868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecac827f-85f8-4de8-80ae-0f375249f623', '5d6bd64e-1a8e-4870-8742-86d15e149076', 'b', 'En estas regiones reinan las altas presiones y se producen grandes corrientes ascendentes de aire alimentadas por los alisios que allí convergen.', false, '2025-09-13 13:53:11.525311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('836e8e94-ac8b-4330-835b-f699d4dee128', '5d6bd64e-1a8e-4870-8742-86d15e149076', 'c', 'Se denominan de esta manera debido a las corrientes de agua oceánica, en particular las ecuatorial norte y contracorriente ecuatorial.', false, '2025-09-13 13:53:11.525452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c0f9bea-858a-4279-9b89-e4cd0a743a66', '5d6bd64e-1a8e-4870-8742-86d15e149076', 'd', 'También conocidas como «latitudes de los caballos», son las zonas comprendidas entre los alisios y los ponientes de las latitudes medias.', false, '2025-09-13 13:53:11.525594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4ab26b6-f15c-4de9-86cf-1e174edbb5f1', 'fd8f3eb8-496e-4acf-a8e1-b676cd4ec8af', 'a', 'Corriente de Guinea.', false, '2025-09-13 13:53:11.525883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80491c0b-0846-48fa-ab1a-b80a1da05558', 'fd8f3eb8-496e-4acf-a8e1-b676cd4ec8af', 'b', 'Corriente de Brasil.', false, '2025-09-13 13:53:11.526015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59fc5033-2488-4718-ac00-538da8df8966', 'fd8f3eb8-496e-4acf-a8e1-b676cd4ec8af', 'c', 'Corriente de Benguela.', false, '2025-09-13 13:53:11.526145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('214bd85b-97ff-481c-b1df-f6bc9b91b700', 'fd8f3eb8-496e-4acf-a8e1-b676cd4ec8af', 'd', 'Corriente de Nueva Guinea.', true, '2025-09-13 13:53:11.526277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9f8981c-ad56-4239-b84e-b98626c29783', '2e97c6c6-33ce-45f3-bcd2-90e29abe9ea3', 'a', 'Las bajas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Norte y sureste (SE) para los del hemisferio Sur.', false, '2025-09-13 13:53:11.526547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8648099c-4691-4332-bbc0-d403f0f5d2c8', '2e97c6c6-33ce-45f3-bcd2-90e29abe9ea3', 'b', 'Las altas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Norte y sureste (SE) para los del hemisferio Sur.', true, '2025-09-13 13:53:11.526683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c461fceb-e24c-40b2-be21-8e27869d9d41', '2e97c6c6-33ce-45f3-bcd2-90e29abe9ea3', 'c', 'Las bajas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Sur y sureste (SE) para los del hemisferio Norte.', false, '2025-09-13 13:53:11.526818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('695f3220-ce15-4a6d-b90b-1778c73d004d', '2e97c6c6-33ce-45f3-bcd2-90e29abe9ea3', 'd', 'Las altas presiones ecuatoriales. Las direcciones predominantes son nordeste (NE) para los alisios del hemisferio Sur y sureste (SE) para los del hemisferio Norte.', false, '2025-09-13 13:53:11.526953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca8febac-8d49-4cfe-ae4f-e5a479cb1c3f', '7eccbd47-5f1a-4d0e-9304-a3cf9685eb6a', 'a', 'Es un fotometeoro formado por refracción de la luz solar al atravesar cristales de hielo en suspensión en la atmósfera.', true, '2025-09-13 13:53:11.527226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dae8d519-8442-439f-b948-f83a157557eb', '7eccbd47-5f1a-4d0e-9304-a3cf9685eb6a', 'b', 'Es un fotometeoro formado por la ionización de la atmósfera en ciertas latitudes y bajo ciertas condiciones meteorológicas.', false, '2025-09-13 13:53:11.527464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f9ac947-645f-452e-8712-e1c5358cd781', '7eccbd47-5f1a-4d0e-9304-a3cf9685eb6a', 'c', 'Es un fotometeoro que aparece a 44º del Sol cuando este se encuentra cercano a la línea del', false, '2025-09-13 13:53:11.527597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3edf1f5e-b935-4f3c-a21c-bc822502ddf6', '7eccbd47-5f1a-4d0e-9304-a3cf9685eb6a', 'd', 'También se conoce como corona o halo. Inglés', false, '2025-09-13 13:53:11.527727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('491489fb-5a43-4683-867d-08bfdbe6499b', '7942b205-933b-40cb-aac7-4ebe062740df', 'a', 'Tengo/ la motonave ... tiene un incendio (como consecuencia de una explosión). ¿Dónde es el incendio? El incendio es en la(s) bodega(s).', false, '2025-09-13 13:53:11.52807+00');
