INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d031cf44-f09f-45c6-b461-10286c790b7d', '7942b205-933b-40cb-aac7-4ebe062740df', 'c', 'Tengo/ la motonave ... tuvo un incendio (por una explosión). ¿Cuándo el incendio? El incendio fue en la máquina.', true, '2025-09-13 13:53:11.528407+00');
