INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91bc8e77-01a4-46c7-8f38-ed2f557de809', '27ee5704-df9d-41cd-afb9-6c93f3e31c73', 'd', 'El buque ha averiado a proa/a media eslora/ a popa/en toda la eslora. DE TRANSPORTES, MOVILIDAD                                                                          DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                    Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 01 Seguridad en la mar', true, '2025-09-13 13:53:11.535111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc544bdc-b96f-4b99-b4b6-3dcd90cd67a1', 'f5a07aa8-3150-4927-916c-74cb438c641c', 'a', 'La embarcación tiene que llevar un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, con independencia de la zona de navegación y las condiciones de navegación.', true, '2025-09-13 13:53:11.535531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acfc316c-581a-43f8-b19b-880bd6319b4d', 'f5a07aa8-3150-4927-916c-74cb438c641c', 'b', 'Si estamos realizando exclusivamente navegaciones diurnas en zona de navegación 4, se llevará como mínimo un chaleco salvavidas por persona a bordo, sin necesidad de que éstos lleven luz.', false, '2025-09-13 13:53:11.535667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63a2032c-5719-49a7-a566-01d7038f71d7', 'f5a07aa8-3150-4927-916c-74cb438c641c', 'c', 'La flotabilidad mínima de los chalecos, con independencia de la zona de navegación, será de 150', false, '2025-09-13 13:53:11.53581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cf380dc-20e1-48ec-b131-fc5716feb829', 'f5a07aa8-3150-4927-916c-74cb438c641c', 'd', 'La embarcación tiene que llevar, con independencia de la zona de navegación y las condiciones de navegación, un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, más un chaleco adicional.', false, '2025-09-13 13:53:11.535943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f65f7e1-8bf6-49d7-b8d9-4f60da1c7d17', '908614bd-60ca-4e7c-a18f-2d2b111b2d46', 'a', 'El metacentro está situado por encima del centro de gravedad.', false, '2025-09-13 13:53:11.536222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfe8ea5e-66d0-4639-a190-563303e66d63', '908614bd-60ca-4e7c-a18f-2d2b111b2d46', 'b', 'KG es cero.', false, '2025-09-13 13:53:11.536354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5855091b-641d-4fd9-85b3-1a5cf3d10f1e', '908614bd-60ca-4e7c-a18f-2d2b111b2d46', 'c', 'El metacentro está situado por debajo del centro de gravedad.', false, '2025-09-13 13:53:11.536484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7007ad3-81f3-4fd1-9573-b08f13a1af0b', '908614bd-60ca-4e7c-a18f-2d2b111b2d46', 'd', 'GM es cero.', true, '2025-09-13 13:53:11.536726+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f59096f8-e30d-4f43-af0e-2ca29b393dbc', '5cdb5d40-1ed1-4e7b-852d-2dcbc5ad9d32', 'a', 'Ha de quitarse el chaleco salvavidas para poder utilizar el arnés con el que le izarán.', false, '2025-09-13 13:53:11.537007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0876f2fd-a4b4-4f16-8cf8-e0818725ee8f', '5cdb5d40-1ed1-4e7b-852d-2dcbc5ad9d32', 'b', 'En cuanto reciba el cabo del helicóptero ha de hacerlo firme a la embarcación.', true, '2025-09-13 13:53:11.53714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f9fe369-4c52-4f7c-801c-43d9ebda67dc', '5cdb5d40-1ed1-4e7b-852d-2dcbc5ad9d32', 'c', 'Si le envían un arnés desde el helicóptero debe dejar que contacte primero con el agua antes de tocarlo y colocárselo.', false, '2025-09-13 13:53:11.537279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f13a313-6eed-454a-a016-e57241fd64d0', '5cdb5d40-1ed1-4e7b-852d-2dcbc5ad9d32', 'd', 'En el caso de ir navegando a vela, se deben mantener izadas para asegurar el rumbo y la', false, '2025-09-13 13:53:11.537411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7094ca6-1d59-477f-bdc9-627b38dbb197', '6132849d-4ec6-4e18-b752-b5eb829be8a8', 'a', 'El centro de carena se eleva con lo que la estabilidad de la embarcación empeora.', false, '2025-09-13 13:53:11.537694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a954142e-9cfd-4069-a7cb-b2ddb278b955', '6132849d-4ec6-4e18-b752-b5eb829be8a8', 'b', 'Se produce una escora que dependerá de la distancia "d".', false, '2025-09-13 13:53:11.537826+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26119342-4548-4cca-81e9-acdee6528d7f', '6132849d-4ec6-4e18-b752-b5eb829be8a8', 'c', 'El centro de gravedad de la embarcación permanece invariable.', true, '2025-09-13 13:53:11.537958+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37e195c6-7dce-400c-8857-fac3e3d61708', '6132849d-4ec6-4e18-b752-b5eb829be8a8', 'd', 'La altura metacéntrica (GM) disminuye y la embarcación pierde estabilidad.', false, '2025-09-13 13:53:11.538093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1835b9c-2ef4-4963-b42f-c2fe4f1632af', '41cedbd8-a9cf-4640-8175-bc9e13265800', 'a', 'La función de un arnés de seguridad es mantenerse unido a la embarcación si se cae por la borda y por ello debe tener una longitud larga, más de dos metros por regla general.', false, '2025-09-13 13:53:11.538367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63fa3ccd-db7e-405b-b721-5eb0927f2e14', '41cedbd8-a9cf-4640-8175-bc9e13265800', 'b', 'Las bengalas tienen un alcance visual menor al de un cohete con paracaídas, pero mayor duración y se pueden usar como señal diurna o nocturna.', true, '2025-09-13 13:53:11.538501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1af4c36-913f-4b13-a49c-fd756d9965aa', '41cedbd8-a9cf-4640-8175-bc9e13265800', 'c', 'Los aros salvavidas tienen que colocarse en la proa y contar con un sistema rápido de soltado y lanzado al agua.', false, '2025-09-13 13:53:11.538632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdf83d32-54c4-413e-9881-46e19bcb400a', '41cedbd8-a9cf-4640-8175-bc9e13265800', 'd', 'La carga de los extintores tiene corta duración por lo que debe atacar prioritariamente las llamas del fuego para evitar su propagación.', false, '2025-09-13 13:53:11.538768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ca760c2-6b47-4c96-9e85-e11893aedbfd', '00587e48-c9a4-41e5-9d46-89ca812bd6e5', 'a', 'Ha de proceder con rapidez y no perder el tiempo con las instrucciones.', false, '2025-09-13 13:53:11.539045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f116d0c-4cda-49fc-883a-376c40cf7ba9', '00587e48-c9a4-41e5-9d46-89ca812bd6e5', 'b', 'Lance o encienda siempre a barlovento para conseguir un mejor efecto visual.', true, '2025-09-13 13:53:11.539175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd181aed-ab49-44cd-b580-66685a96ddea', '00587e48-c9a4-41e5-9d46-89ca812bd6e5', 'c', 'Para asegurar el efecto use el mayor número posible.', false, '2025-09-13 13:53:11.539305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d5cafb7-d3fc-473f-8a92-c5641797d1a0', '00587e48-c9a4-41e5-9d46-89ca812bd6e5', 'd', 'Manipúlelos con guantes o trapos.', false, '2025-09-13 13:53:11.539435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ea0a5b3-0887-4595-8ef5-9dc62091bd46', 'fbc9c979-be2c-4553-98d6-3e0a6d6db2c9', 'a', 'Mantener la embarcación en movimiento.', false, '2025-09-13 13:53:11.539712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dce795ef-625d-4ae9-85b9-c5530a607a88', 'fbc9c979-be2c-4553-98d6-3e0a6d6db2c9', 'b', 'Desvestirse y quedarse en ropa interior.', false, '2025-09-13 13:53:11.539862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('238b1d21-896e-4fdc-b390-bbcf37e83e23', 'fbc9c979-be2c-4553-98d6-3e0a6d6db2c9', 'c', 'Amarrar a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:11.539997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c41287eb-c566-4c15-bebf-5f392046214c', 'fbc9c979-be2c-4553-98d6-3e0a6d6db2c9', 'd', 'Dejar la radiobaliza a bordo de la embarcación.', true, '2025-09-13 13:53:11.540128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44171d02-3789-4967-b0b0-a0d21e76e869', '8912abff-6f0a-4f7e-9ef5-904705667b5d', 'a', 'En el canal 16.', false, '2025-09-13 13:53:11.540403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20e6762b-9d83-4078-aa75-76086e85639d', '8912abff-6f0a-4f7e-9ef5-904705667b5d', 'b', 'En el canal 12.', false, '2025-09-13 13:53:11.540536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c364817-5406-41e4-bbcb-578ffa083712', '8912abff-6f0a-4f7e-9ef5-904705667b5d', 'c', 'En el canal 9.', false, '2025-09-13 13:53:11.540666+00');
