INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('176200e4-a1c3-4330-9be7-4cf601b528e4', '1d00a93b-bf3e-44e6-a293-1707fd5bad49', 'a', 'Es un equipo radioeléctrico que funciona en la banda de 9 GHz.', true, '2025-09-13 13:53:11.54108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8986e36b-77db-440c-8630-9a8c09dddb85', '1d00a93b-bf3e-44e6-a293-1707fd5bad49', 'b', 'Solo se puede activar automáticamente, cuando entra en contacto con el agua.', false, '2025-09-13 13:53:11.541212+00');
