INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01d13dd4-a3d7-4adc-96dc-eb57c9fc3845', '78b011fb-1b8a-4d85-9362-778c80799b67', 'a', 'Es un equipo radioeléctrico que funciona en la banda de 9 GHz.', true, '2025-09-13 13:53:11.564974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5e44f34-f9c5-44b5-bc89-18e1f29c4936', '78b011fb-1b8a-4d85-9362-778c80799b67', 'b', 'Solo se puede activar automáticamente, cuando entra en contacto con el agua.', false, '2025-09-13 13:53:11.565108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9da2a407-6e97-4b10-b16b-c8b9e140b30e', '78b011fb-1b8a-4d85-9362-778c80799b67', 'c', 'Para alcanzar el rango máximo perceptible, el SART debe ubicarse al nivel del mar.', false, '2025-09-13 13:53:11.565248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c855512-e67f-4adb-b2e6-e9e2d049f266', '78b011fb-1b8a-4d85-9362-778c80799b67', 'd', 'El SART debe instalarse junto con el reflector del radar, para evitar que se generen zonas de sombra en la dirección de propagación del SART.', false, '2025-09-13 13:53:11.56538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5ef2391-2d13-4550-99a1-7a74992eb1d0', 'ba72d854-a8e3-418f-a98b-52e17f46ab94', 'a', 'Mantener la embarcación en movimiento.', false, '2025-09-13 13:53:11.565656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('365f92bf-9507-43e4-933a-b80d43c61145', 'ba72d854-a8e3-418f-a98b-52e17f46ab94', 'b', 'Desvestirse y quedarse en ropa interior.', false, '2025-09-13 13:53:11.565785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8901ab5b-72b7-415b-ad2d-263771e89f82', 'ba72d854-a8e3-418f-a98b-52e17f46ab94', 'c', 'Amarrar a bordo la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:11.565939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68baa3fe-bd12-4363-b2aa-6b1cbb61f409', 'ba72d854-a8e3-418f-a98b-52e17f46ab94', 'd', 'Dejar la radiobaliza a bordo de la embarcación.', true, '2025-09-13 13:53:11.566081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('012d1494-7e6a-4222-834d-940eda0c5a19', 'ca303beb-397b-43df-94a4-2396a87c36c4', 'a', 'La función de un arnés de seguridad es mantenerse unido a la embarcación si se cae por la borda y por ello debe tener una longitud larga, más de dos metros por regla general.', false, '2025-09-13 13:53:11.566365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79300a44-2bc5-4600-9203-6fb45741738f', 'ca303beb-397b-43df-94a4-2396a87c36c4', 'b', 'Las bengalas tienen un alcance visual menor al de un cohete con paracaídas, pero mayor duración y se pueden usar como señal diurna o nocturna.', false, '2025-09-13 13:53:11.566504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd2c6166-42ef-4869-9655-2687f925386f', 'ca303beb-397b-43df-94a4-2396a87c36c4', 'c', 'Los aros salvavidas tienen que colocarse en la proa y contar con un sistema rápido de soltado y lanzado al agua.', true, '2025-09-13 13:53:11.566637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0562df7c-81d4-4fc9-99d6-301756177ca9', 'ca303beb-397b-43df-94a4-2396a87c36c4', 'd', 'La carga de los extintores tiene corta duración por lo que debe atacar prioritariamente las llamas del fuego para evitar su propagación.', false, '2025-09-13 13:53:11.56677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04ba3e86-c644-4f33-a6b6-618bc3d94c79', 'fea7cb94-90f5-4b78-832e-afa558776b93', 'a', 'El metacentro está situado por encima del centro de gravedad.', false, '2025-09-13 13:53:11.567046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78f07839-97f9-4780-9257-12b176100f68', 'fea7cb94-90f5-4b78-832e-afa558776b93', 'b', 'KG es cero.', false, '2025-09-13 13:53:11.567179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06eb8671-4ca5-4fb4-836e-ccba80bed4b9', 'fea7cb94-90f5-4b78-832e-afa558776b93', 'c', 'El metacentro está situado por debajo del centro de gravedad.', true, '2025-09-13 13:53:11.567309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2b7938e-012c-421c-bae3-1d691f1f4736', 'fea7cb94-90f5-4b78-832e-afa558776b93', 'd', 'GM es cero.', false, '2025-09-13 13:53:11.567441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('248d2763-e138-424f-830e-4dfc663dd3dd', 'b7e25a3c-d1bb-46d1-8d5a-30394931fea8', 'a', 'Ha de quitarse el chaleco salvavidas para poder utilizar el arnés con el que le izarán.', false, '2025-09-13 13:53:11.567714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1542d14c-e42f-4e69-9962-f672a2783bdf', 'b7e25a3c-d1bb-46d1-8d5a-30394931fea8', 'b', 'En cuanto reciba el cabo del helicóptero ha de hacerlo firme a la embarcación.', false, '2025-09-13 13:53:11.567846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e564297-dce6-445b-9e52-50f09eb3fadd', 'b7e25a3c-d1bb-46d1-8d5a-30394931fea8', 'c', 'Si le envían un arnés desde el helicóptero debe dejar que contacte primero con el agua antes de tocarlo y colocárselo.', true, '2025-09-13 13:53:11.567976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6160f67a-8dd7-4d63-82bf-040053ab8afc', 'b7e25a3c-d1bb-46d1-8d5a-30394931fea8', 'd', 'En el caso de ir navegando a vela, se deben mantener izadas para asegurar el rumbo y la', false, '2025-09-13 13:53:11.568106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b837e89-5c1f-48f6-91b8-ed2a8f3ae8ff', 'bb50c4c9-ed8e-4364-bec4-fc5189fcbea7', 'a', 'La embarcación tiene que llevar un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, con independencia de la zona de navegación y las condiciones de navegación.', false, '2025-09-13 13:53:11.568404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f5f6f8b-5242-4b4e-9115-73c67f7d86bc', 'bb50c4c9-ed8e-4364-bec4-fc5189fcbea7', 'b', 'Si estamos realizando exclusivamente navegaciones diurnas en zona de navegación 4, se llevará como mínimo un chaleco salvavidas por persona a bordo, sin necesidad de que éstos lleven luz.', true, '2025-09-13 13:53:11.568541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5ca8e9f-9c21-45b0-8eb3-a9a077715f91', 'bb50c4c9-ed8e-4364-bec4-fc5189fcbea7', 'c', 'La flotabilidad mínima de los chalecos, con independencia de la zona de navegación, será de 150', false, '2025-09-13 13:53:11.568674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dd1bdc7-d660-4a5a-8a6f-11c6c345492d', 'bb50c4c9-ed8e-4364-bec4-fc5189fcbea7', 'd', 'La embarcación tiene que llevar, con independencia de la zona de navegación y las condiciones de navegación, un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, más un chaleco adicional.', false, '2025-09-13 13:53:11.568817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a7bae1f-417c-4503-b03c-012ea78ffec6', '4b178386-1227-43a8-9014-1a88a0a87340', 'a', 'Ha de proceder con rapidez y no perder el tiempo con las instrucciones.', false, '2025-09-13 13:53:11.569246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bc9aed1-25e1-44fd-b909-b2192be0c86f', '4b178386-1227-43a8-9014-1a88a0a87340', 'b', 'Lance o encienda siempre a barlovento para conseguir un mejor efecto visual.', false, '2025-09-13 13:53:11.569379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e062a31-898d-4ab6-a69c-130a7789098c', '4b178386-1227-43a8-9014-1a88a0a87340', 'c', 'Para asegurar el efecto use el mayor número posible.', false, '2025-09-13 13:53:11.56951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e475f971-24fd-4aa1-bf5d-9ba9e7c33414', '4b178386-1227-43a8-9014-1a88a0a87340', 'd', 'Manipúlelos con guantes o trapos.', true, '2025-09-13 13:53:11.569642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6ac5b77-18c0-434b-bb8a-2ad1238f9a3d', 'e72e9755-aaf3-4065-8fe6-6e2f4a9165f6', 'a', 'El centro de carena se eleva con lo que la estabilidad de la embarcación empeora.', true, '2025-09-13 13:53:11.569956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ea55c81-de79-414b-8384-4a17c16af108', 'e72e9755-aaf3-4065-8fe6-6e2f4a9165f6', 'b', 'Se produce una escora que dependerá de la distancia "d".', false, '2025-09-13 13:53:11.570096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b6e5855-5e1c-40d6-a192-047306c5a91e', 'e72e9755-aaf3-4065-8fe6-6e2f4a9165f6', 'c', 'El centro de gravedad de la embarcación permanece invariable.', false, '2025-09-13 13:53:11.570234+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ce527e6-03e0-451c-965b-5bcdb203b829', 'e72e9755-aaf3-4065-8fe6-6e2f4a9165f6', 'd', 'La altura metacéntrica (GM) disminuye y la embarcación pierde estabilidad.', false, '2025-09-13 13:53:11.570373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a33eaa78-15fa-4e83-989a-fd0cfebe14fa', '06c7bac3-2548-4db0-86cb-d8e4cc22fb0a', 'a', 'Centro de carena.', true, '2025-09-13 13:53:11.570659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fcef1c5-8387-4e9b-8d3e-1866bf7d2a35', '06c7bac3-2548-4db0-86cb-d8e4cc22fb0a', 'b', 'Centro de gravedad.', false, '2025-09-13 13:53:11.570807+00');
