INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1eb843ab-f4cd-442a-b93e-fa892c93a69f', '06c7bac3-2548-4db0-86cb-d8e4cc22fb0a', 'd', 'Centro de empuje. Meteorología', false, '2025-09-13 13:53:11.571086+00');
