INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bec17813-7a5c-4f82-8e05-fc7c0965eed0', 'd6043801-78c8-4a60-b519-608012995214', 'c', 'Con carácter general es de componente Sur.', false, '2025-09-13 13:53:11.572348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ad1227d-9237-41c1-9354-04f351af5e76', 'd6043801-78c8-4a60-b519-608012995214', 'd', 'En verano es de componente N y en invierno de componente E.', false, '2025-09-13 13:53:11.572487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8351adb2-d3ba-45aa-b001-75ebdd081dcc', 'e74baa41-4608-4f84-bf48-acc05fe11409', 'a', 'Es la relación entre la presión de vapor efectiva y la tensión del vapor saturante con respecto al agua a la misma temperatura y presión.', true, '2025-09-13 13:53:11.572766+00');
