INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b65362f9-095c-4a32-8ed1-53125c61a270', '32048ce0-810e-4124-9156-617bb41cffb3', 'a', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', false, '2025-09-13 13:53:11.595425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('337b6c71-f2fb-4bf6-bae2-71a7dd24005a', '32048ce0-810e-4124-9156-617bb41cffb3', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la sonda y naturaleza del fondo.', true, '2025-09-13 13:53:11.595555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b45bf3d-f302-42af-8444-5abc894baac1', '32048ce0-810e-4124-9156-617bb41cffb3', 'c', 'El orinque es el cabo que se amarra por un chicote a la cruz del ancla y por el otro a la proa de la embarcación para poder recuperar el ancla.', false, '2025-09-13 13:53:11.595691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10712006-c951-462f-8f05-d1434e13a07b', '32048ce0-810e-4124-9156-617bb41cffb3', 'd', 'Las embarcaciones deben disponer de una línea de fondeo cuya longitud será inferior a cuatro veces la eslora de la embarcación.', false, '2025-09-13 13:53:11.59583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('321f3767-ae46-436a-bfca-8c1abb45d31c', '1206ee12-e23d-40b1-a1f7-1956abd9a8e4', 'a', 'Una abertura practicada en el casco del barco para dar paso a la mecha del timón.', false, '2025-09-13 13:53:11.596118+00');
