INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7c587b8-67a4-4e3e-8ef8-3b0421343dd4', '1206ee12-e23d-40b1-a1f7-1956abd9a8e4', 'c', 'Una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio, sirve para amarrar los cabos.', false, '2025-09-13 13:53:11.596375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c14debe1-d3e1-4c3d-8855-7cd2cf013616', '1206ee12-e23d-40b1-a1f7-1956abd9a8e4', 'd', 'Un bloque de material pesado depositado en el fondo que, unido por un orinque a la superficie, permite amarrar una embarcación.', false, '2025-09-13 13:53:11.596502+00');
