INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec708a7e-84e1-4a36-a370-236c132dc1ed', '9c79b2d2-db0f-496f-8cd0-753206ccde07', 'a', 'Si estos están desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura mínima de 25 mm.', false, '2025-09-13 13:53:11.599538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf1036cd-f2a5-47fe-869b-a6245abc4d70', '9c79b2d2-db0f-496f-8cd0-753206ccde07', 'b', 'Cuando estos estén contaminados con algún otro tipo de basuras, si dichos productos han sido tratados para su esterilización.', false, '2025-09-13 13:53:11.599668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4250c21-8fdd-4ed2-bca4-f83ced48f795', '9c79b2d2-db0f-496f-8cd0-753206ccde07', 'c', 'Si se realiza tan lejos como sea posible de la tierra más próxima, pero a no menos de 12 millas marinas de la tierra más próxima o de la plataforma de hielo más próxima.', true, '2025-09-13 13:53:11.599801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0f03213-caa0-4f15-9e9c-21d68047dcc9', '9c79b2d2-db0f-496f-8cd0-753206ccde07', 'd', 'Siempre que sean productos avícolas introducidos, incluidas las aves o partes de aves.', false, '2025-09-13 13:53:11.599932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3054f794-28de-4bf6-9626-c4252155931c', 'efec6b12-07ac-4b0c-9eda-143148effa58', 'b', 'Contractual penal en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas y las personas que debidamente autorizadas por el propietario patroneen las mismas y los usuarios de cualquier objeto que pueda arrastrar la embarcación.', false, '2025-09-13 13:53:11.600322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa443758-3633-4b6b-83e1-0e10e0ca7b29', 'efec6b12-07ac-4b0c-9eda-143148effa58', 'c', 'Civil extracontractual en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas, las personas que debidamente autorizadas por el propietario patroneen las mismas, así como aquellas otras que les secunden en su gobierno, pero nunca la de los esquiadores o de otros usuarios de cualquier objeto que pueda arrastrar la embarcación.', false, '2025-09-13 13:53:11.600448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7063c0bb-62bb-4f91-a971-db05d0d107d2', 'efec6b12-07ac-4b0c-9eda-143148effa58', 'd', 'Contractual civil en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas y las personas que debidamente autorizadas por el propietario patroneen las mismas.', false, '2025-09-13 13:53:11.600575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe47538a-9fb0-4b37-a0c6-0be2a726ecd9', 'd62468bd-b8fa-48cf-aca1-ec48f2c6bf56', 'a', 'Zonas reservadas al recreo.', false, '2025-09-13 13:53:11.600872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81037273-e7af-463c-950d-6792c0b7414e', 'd62468bd-b8fa-48cf-aca1-ec48f2c6bf56', 'b', 'Vertederos.', false, '2025-09-13 13:53:11.601017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f25e844-3221-4bcd-8ca2-f9e8b851e943', 'd62468bd-b8fa-48cf-aca1-ec48f2c6bf56', 'c', 'Peligros aislados de dimensiones limitadas, que están enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:11.60115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cc64dee-674c-479b-86ac-9fb3a29c1a16', 'd62468bd-b8fa-48cf-aca1-ec48f2c6bf56', 'd', 'Los límites de un área de fondeo.', false, '2025-09-13 13:53:11.601281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05a7e35d-cea3-4c69-89d9-eb44620da754', '88b581b5-0fcb-4021-b70e-a91b93bc008a', 'a', 'Rojo y forma cilíndrica.', true, '2025-09-13 13:53:11.601548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82697963-5a59-4ac5-98f8-e75ce808bd16', '88b581b5-0fcb-4021-b70e-a91b93bc008a', 'b', 'Verde y forma cónica.', false, '2025-09-13 13:53:11.601675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b08431f-1714-4005-8e89-6db6c1641084', '88b581b5-0fcb-4021-b70e-a91b93bc008a', 'c', 'Rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.601809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e99ccd7-166a-45ab-9b99-ecb9a16e9722', '88b581b5-0fcb-4021-b70e-a91b93bc008a', 'd', 'Verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.601938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5687324e-23b1-48c1-a1e7-369f0cd3bba3', 'bb60f919-e84b-43d9-99df-d3ffc86c35d9', 'a', 'Con unos ritmos idénticos. No es posible confundirlas porque las Marcas de Aguas Navegables tienen un aspecto muy distinto de las de las boyas que balizan un peligro.', false, '2025-09-13 13:53:11.602214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fd17a53-2f24-4c3d-ab51-f28c5fd1c759', 'bb60f919-e84b-43d9-99df-d3ffc86c35d9', 'b', 'Con unos ritmos característicos que no se confunden con el ritmo de centelleos muy rápidos o rápidos de las Marcas Cardinales.', true, '2025-09-13 13:53:11.602361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8158972-1a0c-45d8-ae67-7ac3be75bb5f', 'bb60f919-e84b-43d9-99df-d3ffc86c35d9', 'd', 'Sólo las Marcas de Aguas Navegables utilizan luces blancas. La luz en las Marcas de Peligro Aislado (si tiene) es verde.', false, '2025-09-13 13:53:11.602624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38da5192-ac9b-4c54-9bd5-cb0ad0ee8d67', '3a6c862c-131d-4b01-8396-d63bc6b1fa53', 'a', 'Que las aguas más profundas en esa zona no se encuentran en el cuadrante correspondiente al nombre de la marca.', false, '2025-09-13 13:53:11.602901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b647fa29-f466-40d6-85fd-73e6fc02b638', '3a6c862c-131d-4b01-8396-d63bc6b1fa53', 'b', 'El lado por el que no se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:11.60303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b113ca7-4fe6-45dc-a725-4dd806d52cc8', '3a6c862c-131d-4b01-8396-d63bc6b1fa53', 'c', 'Dónde están las aguas navegables.', true, '2025-09-13 13:53:11.603157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f5673f8-c75e-461d-8799-b8a6d418740f', '3a6c862c-131d-4b01-8396-d63bc6b1fa53', 'd', 'Una configuración a la que se hace referencia en las publicaciones náuticas.', false, '2025-09-13 13:53:11.603283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85892d9b-8848-47a5-aeec-eee1226f671d', '8e139ee9-27b7-43d2-8342-1678ff86738d', 'a', 'Es siempre la misma: sólo se utilizan para indicar una zona reservada al recreo.', false, '2025-09-13 13:53:11.60369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76551832-1cf4-42b8-9d3d-6929fa02ed2f', '8e139ee9-27b7-43d2-8342-1678ff86738d', 'b', 'Se visualiza al consultar la carta u otra publicación náutica.', true, '2025-09-13 13:53:11.603828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e977270-ba6a-4aec-9bda-52e2af50834b', '8e139ee9-27b7-43d2-8342-1678ff86738d', 'c', 'Se conoce a través de los avisos a navegantes.', false, '2025-09-13 13:53:11.603961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a38918a4-d151-4d46-96a8-78b7c017c4a3', '8e139ee9-27b7-43d2-8342-1678ff86738d', 'd', 'Se encuentra definida por las normas de cada puerto que es publicada en el Boletín Oficial de la Provincia anualmente. Reglamento (RIPA).', false, '2025-09-13 13:53:11.604089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a252815-aea0-4600-9303-fd5953af3481', '57fbaa7a-32ab-4a1c-97ab-6de92bebeb44', 'a', 'Podría indicar la presencia de un buque fondeado de 75 metros de eslora.', true, '2025-09-13 13:53:11.604359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d82b5a0c-75db-4213-ab57-d52d4c13cb34', '57fbaa7a-32ab-4a1c-97ab-6de92bebeb44', 'b', 'Podría indicar la presencia de un buque fondeado de 45 metros de eslora.', false, '2025-09-13 13:53:11.604488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59578f67-a449-4120-9d0e-98a92bb2be77', '57fbaa7a-32ab-4a1c-97ab-6de92bebeb44', 'c', 'Podría indicar la presencia de un buque de propulsión mecánica en navegación, de 5 metros de eslora, con una velocidad máxima inferior a 7 nudos.', false, '2025-09-13 13:53:11.604617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a6b51d1-8c4f-4853-a01e-7c0e77d4ba3d', '57fbaa7a-32ab-4a1c-97ab-6de92bebeb44', 'd', 'Podría indicar la presencia de un buque de propulsión mecánica en navegación, de 6 metros de eslora, con una velocidad máxima inferior a 6 nudos.', false, '2025-09-13 13:53:11.604753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6af22481-77ed-4322-a621-1bd26d1684fd', '3a67610b-55d4-4146-919b-e428e263e6a8', 'a', '225 grados.', true, '2025-09-13 13:53:11.60508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf67337c-e1ae-4fba-b423-5d73d41ef2b7', '3a67610b-55d4-4146-919b-e428e263e6a8', 'b', '112,5 grados.', false, '2025-09-13 13:53:11.605215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef167682-8a76-4894-bf07-55c10b5f40a2', '3a67610b-55d4-4146-919b-e428e263e6a8', 'c', '135 grados.', false, '2025-09-13 13:53:11.605342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85555f38-03e4-48bb-a79b-e1bdfafec9e1', '3a67610b-55d4-4146-919b-e428e263e6a8', 'd', '360 grados.', false, '2025-09-13 13:53:11.60547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f24294e-b80c-4eeb-86c0-9cb9324efa82', '46ea31a5-b885-48a9-9dc2-7d705f3219b7', 'a', 'Al aproximarse un buque de gran tamaño, se considerará que puede existir riesgo de abordaje aun cuando sea evidente una variación apreciable de la demora.', false, '2025-09-13 13:53:11.605746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49716939-4d92-41dc-a750-cdac98edef93', '46ea31a5-b885-48a9-9dc2-7d705f3219b7', 'b', 'Al aproximarse a un buque a muy corta distancia, se considerará que puede existir riesgo de abordaje únicamente en el caso de que la demora no varíe.', true, '2025-09-13 13:53:11.605894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4734920-f398-4e19-a379-9bc0f2319d24', '46ea31a5-b885-48a9-9dc2-7d705f3219b7', 'c', 'Si la demora de un buque que se aproxima no varía en forma apreciable, se considerará que existe riesgo de abordaje.', false, '2025-09-13 13:53:11.606034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa82d17c-5471-45f8-ac7e-98260a2a7bcf', '46ea31a5-b885-48a9-9dc2-7d705f3219b7', 'd', 'Si la demora de un buque que se aproxima en la lejanía varía de forma apreciable, no se considerará riesgo de abordaje, pero el patrón se mantendrá atento a cualquier variación.', false, '2025-09-13 13:53:11.60618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('555e0ff7-173f-485d-a025-be641793e84b', 'c63e1277-e6e8-49ce-a682-1735669f8346', 'a', 'Navegar por la zona de separación del tráfico, y al salir o entrar en el dispositivo, hacerlo con el mayor ángulo posible en relación con la dirección general de la corriente del tráfico.', false, '2025-09-13 13:53:11.606504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb749c53-9431-43c3-a151-f8678a11b9d2', 'c63e1277-e6e8-49ce-a682-1735669f8346', 'b', 'Dado que se tendría prioridad de paso por ser los otros buques de propulsión mecánica, se podrá navegar indistintamente por cualquier zona del dispositivo.', false, '2025-09-13 13:53:11.606656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bdb0081-4172-4eba-b9d4-191b8a62cc5e', 'c63e1277-e6e8-49ce-a682-1735669f8346', 'c', 'Tratando de no estorbar a los buques circulando por el dispositivo, pudiendo para ello navegar en la zona de navegación costera adyacente.', true, '2025-09-13 13:53:11.606821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f02018e3-0557-4a55-a218-4c56ac01bfbe', 'c63e1277-e6e8-49ce-a682-1735669f8346', 'd', 'Priorizando cruzar las vías de circulación con un rumbo con el mayor ángulo posible en relación con la dirección general de la corriente del tráfico por ser este más ventajoso para transitar el dispositivo a vela.', false, '2025-09-13 13:53:11.606974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a5dd92d-3291-48a0-a1e9-786a11b6af60', 'fb5cbad3-da9d-4b97-8824-24b0b2d56353', 'a', 'Su proa viendo la luz de tope blanca y las luces de costado.', true, '2025-09-13 13:53:11.607295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f21af23e-5993-4e51-86c5-f7612b875d86', 'fb5cbad3-da9d-4b97-8824-24b0b2d56353', 'b', 'Su popa viendo la luz de alcance.', false, '2025-09-13 13:53:11.607449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fed865e-f043-402c-96c4-cbddb041997b', 'fb5cbad3-da9d-4b97-8824-24b0b2d56353', 'c', 'Su proa viendo la luz de alcance.', false, '2025-09-13 13:53:11.607599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b24389c4-ce3a-40e3-83d3-a9128eb5d24d', 'fb5cbad3-da9d-4b97-8824-24b0b2d56353', 'd', 'Su proa viendo la luz de tope y únicamente una de las luces de costado.', false, '2025-09-13 13:53:11.607767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5697f4b-bc0d-425d-bf32-f897622e8d5e', 'f219160a-9f3f-4e4b-93c3-7dd18f61b3ea', 'a', 'El buque remolcado tiene una anchura igual o superior a 25 metros.', false, '2025-09-13 13:53:11.608069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c486d33a-52fe-4d1d-9f48-589e46d61f27', 'f219160a-9f3f-4e4b-93c3-7dd18f61b3ea', 'b', 'La longitud de remolque es superior a 200 metros.', true, '2025-09-13 13:53:11.608207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f141d4d-2a58-4860-8047-9791014dce24', 'f219160a-9f3f-4e4b-93c3-7dd18f61b3ea', 'c', 'El buque remolcado tiene una anchura inferior a 25 metros.', false, '2025-09-13 13:53:11.60847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67576264-47a5-4261-bae8-7f1242695889', 'f219160a-9f3f-4e4b-93c3-7dd18f61b3ea', 'd', 'La longitud de remolque es igual o inferior a 200 metros.', false, '2025-09-13 13:53:11.608601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('256863f1-bd99-4db8-97ed-79185e2fd2c0', '67c46a47-2b1f-4517-b422-e4b5f479ad04', 'a', 'El Estado de pabellón de la embarcación.', true, '2025-09-13 13:53:11.608918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ee18559-0f84-42e8-8c53-18e3942fb1d2', '67c46a47-2b1f-4517-b422-e4b5f479ad04', 'c', 'Las circunstancias especiales, que pudieran hacer necesario apartarse del Reglamento.', false, '2025-09-13 13:53:11.60919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fee96e8-bacd-48cd-8556-86014b3cb3f2', '67c46a47-2b1f-4517-b422-e4b5f479ad04', 'd', 'Todos aquellos peligros de navegación y riesgos de abordaje.', false, '2025-09-13 13:53:11.60932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72a7557a-07c8-4029-a38f-cfd39f53d0e5', '1d48eb2a-9dc9-4a96-84a7-f1d0de18c684', 'a', '. . - - . .', false, '2025-09-13 13:53:11.60959+00');
