INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bccd850e-ff7c-476d-8977-57f2e6e24ebb', '89c1dc19-9aed-48be-b2d2-985d9193dab8', 'd', 'Una luz amarilla giratoria de gran intensidad.', false, '2025-09-13 13:53:11.610675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f57c5c00-e93b-4d79-9705-cb55e3350b15', 'a7068800-da54-4c9e-9a55-ca2396c20df8', 'a', 'Reducir su velocidad hasta la mínima de gobierno y si fuera necesario, suprimir su arrancada.', true, '2025-09-13 13:53:11.610955+00');
