INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67de297d-8304-4df3-8e78-f13352b32498', '67c46a47-2b1f-4517-b422-e4b5f479ad04', 'b', 'Las limitaciones de los buques interesados, que pudieran hacer necesario apartarse del Reglamento.', false, '2025-09-13 13:53:11.609059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('055f3d71-af1c-48a0-a1df-c41043ce8178', 'a7068800-da54-4c9e-9a55-ca2396c20df8', 'd', 'Prestar atención a otros Reglamentos, pero no a éste, ya que éste solo aplica a buques mercantes. Maniobra y navegación.', false, '2025-09-13 13:53:11.611351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1a09ce7-982f-41c2-afc7-f8224ab67b94', '818d2931-b3ad-4b24-9f43-78333479fbbf', 'a', 'Lascar.', false, '2025-09-13 13:53:11.611633+00');
