INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('414d1866-752d-4d41-8ece-e997bee1b5fe', '818d2931-b3ad-4b24-9f43-78333479fbbf', 'c', 'Amollar.', false, '2025-09-13 13:53:11.6119+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d8fde6f-e745-478d-9552-4a2efcaa2ffa', '818d2931-b3ad-4b24-9f43-78333479fbbf', 'd', 'Arriar.', false, '2025-09-13 13:53:11.61203+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a5ef88d-40d2-4632-b3fb-88bdf6ad4e4a', '496e308e-1496-4910-9945-00dbc2201906', 'a', 'Dejaremos caer la proa a estribor hasta dar la vuelta completa con muy poca máquina avante.', false, '2025-09-13 13:53:11.612444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53dcd2bc-93d4-4d65-ba95-22432953fe20', '496e308e-1496-4910-9945-00dbc2201906', 'd', 'No realizando tal maniobra ya que es una maniobra compleja pensada para espacios amplios y sin Emergencias en la mar.', false, '2025-09-13 13:53:11.612869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5947484b-4704-472b-860d-a91cd50ff39a', '90bf9c2c-0bc4-4c8a-a333-acb8d5daa9c0', 'a', 'En el procedimiento de extinción de incendios, la sofocación consiste en eliminar el combustible.', false, '2025-09-13 13:53:11.613163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6704bd73-39a0-405c-9e7d-ca3a35c8c148', '90bf9c2c-0bc4-4c8a-a333-acb8d5daa9c0', 'b', 'Se entiende por socairear el fuego a posicionar la embarcación en la misma dirección que sopla el viento y a la misma velocidad, para que el viento aparente sea cero.', true, '2025-09-13 13:53:11.6133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d94585a4-09f5-416d-9277-78071da58c5d', '90bf9c2c-0bc4-4c8a-a333-acb8d5daa9c0', 'c', 'Nada más detectar el incendio y antes de proceder a su extinción, haga una llamada de socorro y mantenga encendido el motor.', false, '2025-09-13 13:53:11.613434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48cc44b8-3a5d-4b03-8e9e-dc8810774bc3', '90bf9c2c-0bc4-4c8a-a333-acb8d5daa9c0', 'd', 'Los fuegos de líquidos inflamables son clase C y no se pueden apagar con extintores de espuma o dióxido de carbono.', false, '2025-09-13 13:53:11.613567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee3f69d4-fd80-41a6-bdd4-d5de569df428', '11e419e5-15ad-4a3f-adc6-3b6c73555cdc', 'a', 'El Centro Radio-Médico Español presta asistencia médica de urgencia gratuita a distancia, disponible todos los días del año las 24 horas del día.', false, '2025-09-13 13:53:11.613846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6357d7b0-bf94-4691-9f61-7c03965196dd', '11e419e5-15ad-4a3f-adc6-3b6c73555cdc', 'b', 'Las quemaduras de 3er grado profundas solo podrán ser tratadas a bordo si afectan a menos del 1% de la superficie corporal y siempre que no existan lesiones por inhalación.', false, '2025-09-13 13:53:11.613978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e72215a2-6aef-4f36-8ada-8d1c920d0ee0', '11e419e5-15ad-4a3f-adc6-3b6c73555cdc', 'c', 'En caso de accidente con hemorragia interna, se debe acostar al herido en posición horizontal, salvo si pierde el conocimiento; en este caso se colocará en la posición lateral de seguridad.', false, '2025-09-13 13:53:11.614109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54523666-6db3-454c-a23a-f2f4d268f0fc', '11e419e5-15ad-4a3f-adc6-3b6c73555cdc', 'd', 'La Guía Sanitaria a Bordo la edita el Instituto Social de la Marina y sólo se puede adquirir en sus direcciones provinciales.', true, '2025-09-13 13:53:11.614241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9379271-c9d2-448f-8072-39e50c2e6bab', '125c3a36-530d-4cae-9e08-3376f9f23898', 'a', 'Primeramente planificaremos qué pasos a seguir, se levantará un plano de sondas, estudiaremos la salida más conveniente, y se esperará, antes de iniciar actuaciones, hasta el momento de la pleamar para iniciar las maniobras.', true, '2025-09-13 13:53:11.614516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8172a63-0516-4c54-89c5-6153215dc54e', '125c3a36-530d-4cae-9e08-3376f9f23898', 'b', 'Primeramente planificaremos qué pasos a seguir, se levantará un plano de sondas, estudiaremos la salida más conveniente, y se esperará, antes de iniciar actuaciones, hasta el momento de la bajamar para iniciar las maniobras.', false, '2025-09-13 13:53:11.614648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f45b0a4-7366-4da3-9019-d9819d638810', '125c3a36-530d-4cae-9e08-3376f9f23898', 'c', 'Inmediatamente ocurrida la varada, utilizaremos la ayuda de un remolcador con toda su potencia disponible, independientemente de sus características, para que éste tire de nosotros rápidamente y nos libere lo antes posible.', false, '2025-09-13 13:53:11.614791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7523fd51-380f-4c87-b7ac-c19487faae45', '125c3a36-530d-4cae-9e08-3376f9f23898', 'd', 'Inmediatamente ocurrida la varada, utilizaremos la ayuda de un remolcador con toda su potencia disponible, independientemente de sus características, para que éste tire de nosotros lentamente y nos libere lo antes posible. Meteorología', false, '2025-09-13 13:53:11.614935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9692a575-9830-419a-bae2-9361ff5097d9', 'aa7fbc59-255c-4d76-82f8-714c22987758', 'a', 'La noche desde la tierra hacia el mar.', true, '2025-09-13 13:53:11.615211+00');
