INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32eb7bd8-6fd0-475c-8fe0-cfbea4891cc8', 'b2892ce0-2151-4352-8d51-e5f05367b413', 'a', 'Se le llama también alta presión o, simplemente, alta.', false, '2025-09-13 13:53:11.616603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e4a0f32-5f93-4834-9ae8-8743f3dd62b2', 'b2892ce0-2151-4352-8d51-e5f05367b413', 'b', 'La presión atmosférica aumenta a medida que nos acercamos al centro de la borrasca provocando que el aire fluya hacia su interior.', false, '2025-09-13 13:53:11.616735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b532264-3e93-437e-b3ea-1f107d492296', 'b2892ce0-2151-4352-8d51-e5f05367b413', 'c', 'El aire fluye hacia su interior y asciende desde allí.', true, '2025-09-13 13:53:11.616869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11d33f0c-da7f-4bd7-b047-70a6302ef3ec', 'b2892ce0-2151-4352-8d51-e5f05367b413', 'd', 'Cuanto mayor sea la separación entre sus líneas isobaras mayor será la velocidad del viento y la generación de olas.', false, '2025-09-13 13:53:11.617176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fc33475-4f12-4494-abc3-ee1958ea6fd2', '31b9d636-451d-47b6-9d0c-d9145ae1e6bd', 'a', 'Consiste en cintas o lanillas que se afirman en diversos lugares de las velas.', true, '2025-09-13 13:53:11.617468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e59f4232-af52-4273-9a29-fbd8526a7410', '31b9d636-451d-47b6-9d0c-d9145ae1e6bd', 'b', 'Consiste en unas cazoletas que sirven para medir la velocidad del viento.', false, '2025-09-13 13:53:11.617604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('042fcd56-a1fa-4801-81f4-42759c43baa7', '31b9d636-451d-47b6-9d0c-d9145ae1e6bd', 'c', 'Tiene forma de ala, perfil o aguja y sirve para indicar la dirección del viento.', false, '2025-09-13 13:53:11.617737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2142b122-5f6a-4dc0-97af-8109ec192bc9', 'a7fdcc2e-8f49-4302-a166-e30cf034545c', 'a', 'Cuando en una carta existe alguna zona que por su importancia merece representación más detallada, se le inserta a mayor escala dentro de marcos propios.', true, '2025-09-13 13:53:11.618143+00');
