INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('898a06fd-b5fb-41ea-b828-9a408e67e121', 'a7fdcc2e-8f49-4302-a166-e30cf034545c', 'd', 'Carta de escala 1/25.000, cuya misión es facilitar al navegante la aproximación a los puertos.', false, '2025-09-13 13:53:11.618539+00');
