INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65b0cb32-c693-47be-a930-51930000570b', 'd9b4118c-0080-4113-a9bb-c17c53a40906', 'c', 'Un barco fondea a la gira cuando utiliza dos anclas por proa, cuyas líneas de fondeo forman un ángulo de entre 60º y 120º.', true, '2025-09-13 13:53:11.628406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c08cb36-c34d-4681-b3cd-d46b00d2a2ac', 'd9b4118c-0080-4113-a9bb-c17c53a40906', 'd', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear una segunda ancla o aguantar con máquina avante.', false, '2025-09-13 13:53:11.628537+00');
