INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('effda010-f2a3-43a8-8559-d0ffaba937fb', 'e3a7754e-19b9-4479-a6b2-244b6bbc0c20', 'c', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, refrigeración, correa del alternador, nivel de combustible, agua dulce, baterías, luces de navegación, equipo de radio, que estén cerrados todos los grifos de fondo, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.631514+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40276c1f-2757-45a7-a24f-32f8930e4ad6', 'e3a7754e-19b9-4479-a6b2-244b6bbc0c20', 'd', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, correa del alternador, climatización a bordo, nivel de combustible, agua dulce, baterías, equipo de radio, estanqueidad, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.631683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52931cec-7be1-48f9-9df5-38f9994cbcc3', '66583481-073f-4c5a-a2fc-9ff870b61ebb', 'a', 'Sólo si el pabellón de estas es español.', false, '2025-09-13 13:53:11.632022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a646f4c5-2659-49f0-944f-09d76e8717ae', '66583481-073f-4c5a-a2fc-9ff870b61ebb', 'c', 'Si el pabellón de estas es español o, si es extranjero, siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:11.632343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc04a5bd-3d27-4eab-981e-20db9b59c9a8', '66583481-073f-4c5a-a2fc-9ff870b61ebb', 'd', 'Sólo si el pabellón de estas es español y siempre que tengan entrada o salida en un puerto extracomunitario.', false, '2025-09-13 13:53:11.632506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daa33baf-fca6-4fb2-b483-6fcba4978c29', '0eb3b17b-e372-4ee5-aa50-2da28ab0fa51', 'a', 'Se comunicará inmediatamente a la estación costera de la zona geográfica. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', true, '2025-09-13 13:53:11.632842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8071c54-e26d-422d-8d1f-ec8c02c87e13', '0eb3b17b-e372-4ee5-aa50-2da28ab0fa51', 'b', 'Se comunicará inmediatamente a las embarcaciones que se encuentren en la zona. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', false, '2025-09-13 13:53:11.633008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f5cb474-a31d-43df-be67-b3a05bf07c4f', '0eb3b17b-e372-4ee5-aa50-2da28ab0fa51', 'c', 'Se comunicará, una vez se encuentre la embarcación en puerto, a la Autoridad Portuaria, para que esta active los protocolos anticontaminación pertinentes.', false, '2025-09-13 13:53:11.633166+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66e8e99e-d5e2-42cc-9c7f-cade130a0529', '0eb3b17b-e372-4ee5-aa50-2da28ab0fa51', 'd', 'Se comunicará, antes de entrar en puerto, el siguiente mensaje: «vertidos o riesgo de vertidos de productos contaminantes en el mar», indicando la zona aproximada donde se produjo el', false, '2025-09-13 13:53:11.633327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd92b9e0-15f2-4f94-8ee5-a14da10fbebb', '3e28b4cf-f882-456b-b7eb-70728ad7f43a', 'a', 'Opuestos por sus bases.', true, '2025-09-13 13:53:11.633656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8843e0ef-aba5-4027-956e-f9e113483a3a', '3e28b4cf-f882-456b-b7eb-70728ad7f43a', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:11.633818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf2140c5-cdfc-492c-a074-68fc48283bce', '3e28b4cf-f882-456b-b7eb-70728ad7f43a', 'c', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.633962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8839895-61c9-4f03-ae2f-ce8ccb06261d', '3e28b4cf-f882-456b-b7eb-70728ad7f43a', 'd', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.634098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('027da3dc-c32e-4a9f-91db-911a4ab70123', 'f972297d-8ef7-4628-84f4-a50c03a19b72', 'a', 'Únicamente se utilizan para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.634556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0865fc3-fc6d-4168-8d1b-c9bbd85bfc94', 'f972297d-8ef7-4628-84f4-a50c03a19b72', 'b', 'Pueden indicar la presencia de cables o conductos submarinos.', true, '2025-09-13 13:53:11.634693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8469e22c-7941-4c58-b13b-151b6ec4e108', 'f972297d-8ef7-4628-84f4-a50c03a19b72', 'c', 'Son las únicas destinadas a señalar obstrucciones.', false, '2025-09-13 13:53:11.63483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c44daf18-874e-4fd8-81c0-6ab3fa259acc', 'f972297d-8ef7-4628-84f4-a50c03a19b72', 'd', 'Para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.634966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4b6e3a4-4b93-43b1-9882-00fddf14b91d', 'cd16d0e2-6477-4fee-9f86-ed0d44638d1a', 'a', 'Es blanca y tiene un ritmo de isofase de ocultaciones, 1 destello largo cada 10 segundos.', true, '2025-09-13 13:53:11.635248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bae8f862-ad94-4a34-98d2-dc6d9b8094f9', 'cd16d0e2-6477-4fee-9f86-ed0d44638d1a', 'b', 'Es blanca y su ritmo es un grupo de 2 destellos (GpD2).', false, '2025-09-13 13:53:11.635385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('423ce7f9-0632-4899-a1e8-637110aaef90', 'cd16d0e2-6477-4fee-9f86-ed0d44638d1a', 'c', 'Las Marcas de aguas navegables en ningún caso están provistas de luz alguna.', false, '2025-09-13 13:53:11.635546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('342619fe-da91-4a37-9f3e-de0d21290f78', 'cd16d0e2-6477-4fee-9f86-ed0d44638d1a', 'd', 'Es blanca y tiene un ritmo que se puede confundir con el ritmo de centelleos muy rápidos o rápidos de las Marcas cardinales.', false, '2025-09-13 13:53:11.63571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2dd7110-a895-47e7-bf07-d2e5c7dc9f5c', 'd03f15b9-27c3-44b3-b358-508cab1aae7c', 'a', 'Rojo y blanco.', false, '2025-09-13 13:53:11.636067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('796f5fbf-a255-4af6-83a8-21b148638055', 'd03f15b9-27c3-44b3-b358-508cab1aae7c', 'b', 'Amarillo.', false, '2025-09-13 13:53:11.63623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30bac2da-2b92-413b-875f-116aa58673b3', 'd03f15b9-27c3-44b3-b358-508cab1aae7c', 'c', 'Azul con franjas verticales amarillas.', false, '2025-09-13 13:53:11.636391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc8df7bc-744c-41c0-8939-745b0600b744', 'd03f15b9-27c3-44b3-b358-508cab1aae7c', 'd', 'Negro con una o varias anchas bandas horizontales rojas.', true, '2025-09-13 13:53:11.636556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d954d363-0030-4eb9-b40a-413cc503f624', 'e23fa9a6-e6c2-4b9e-a0b5-2f1137917361', 'a', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.637707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ff1d461-bed8-453b-a6c6-e6f68be5c5ca', 'e23fa9a6-e6c2-4b9e-a0b5-2f1137917361', 'b', 'Un buque pesquero que no se encuentre realizando en ese momento tareas de pesca.', false, '2025-09-13 13:53:11.637871+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa99e9ac-1d93-4c82-8392-49c1e328482a', 'e23fa9a6-e6c2-4b9e-a0b5-2f1137917361', 'c', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.638028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb22c3ef-4b68-489f-91cb-64623b71c4f3', 'e23fa9a6-e6c2-4b9e-a0b5-2f1137917361', 'd', 'Todos los buques que tenga a la vista.', false, '2025-09-13 13:53:11.638176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbd13d19-2cd9-47c5-b959-a83466a0d887', 'd69745b5-8731-4822-9af0-fa610db90292', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.638506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f24ae7a0-2cd5-467e-92d6-05a99a20e5dc', 'd69745b5-8731-4822-9af0-fa610db90292', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:11.638647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d074eed2-2b28-4177-b181-495611dd077a', 'd69745b5-8731-4822-9af0-fa610db90292', 'c', 'Una luz verde de centelleos todo horizonte.', false, '2025-09-13 13:53:11.638786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20f5f2c4-5f6a-4027-aecb-d6413cf4f619', 'd69745b5-8731-4822-9af0-fa610db90292', 'd', 'Una segunda luz de alcance.', false, '2025-09-13 13:53:11.638926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b3427b1-d0d0-4056-bb14-8e815e3675a3', 'c3052392-f6dd-405a-9555-53cd79407d77', 'b', 'Una marca cónica con el vértice hacia abajo.', false, '2025-09-13 13:53:11.639372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1eca52b-13bc-46dc-8c77-298eda951d0d', 'c3052392-f6dd-405a-9555-53cd79407d77', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:11.639506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66d97a90-7a05-4bd1-83de-e401d1115c22', 'c3052392-f6dd-405a-9555-53cd79407d77', 'd', 'Una linterna eléctrica que muestre una luz blanca.', true, '2025-09-13 13:53:11.639643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a9360d6-dd7e-4a3f-a1a0-7c29072e06bf', '389c4133-fa66-4cc2-9d73-4449875bffaf', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', true, '2025-09-13 13:53:11.639933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cd7f9da-1b19-4947-b784-00c56d0d7af8', '389c4133-fa66-4cc2-9d73-4449875bffaf', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.640184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1a27dcc-2568-4fb0-bbd1-500676738a1d', '389c4133-fa66-4cc2-9d73-4449875bffaf', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:11.640329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0211c88a-f632-4379-8ffb-97b987eca751', '389c4133-fa66-4cc2-9d73-4449875bffaf', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.640488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab33dd8b-c268-4a3e-a204-cd86baa6709f', 'd1617727-1b61-4475-9cae-5b3e360fe58b', 'a', 'Reciba el viento por estribor.', false, '2025-09-13 13:53:11.640768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5e9f320-730e-4cc3-88a5-2e716d6ef183', 'd1617727-1b61-4475-9cae-5b3e360fe58b', 'b', 'Reciba el viento por popa.', false, '2025-09-13 13:53:11.640907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42b9fe2b-7134-454c-a366-eb8546e48c94', 'd1617727-1b61-4475-9cae-5b3e360fe58b', 'c', 'Reciba el viento por babor.', true, '2025-09-13 13:53:11.641043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fb27e40-355a-4313-8204-40c71a31b969', 'd3abd228-e62b-4eae-a212-6a66f77cd807', 'd', 'Verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.668442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a658e100-6e91-4230-afb5-1edec7815c5f', 'c3052392-f6dd-405a-9555-53cd79407d77', 'a', 'Un farol que muestre una luz amarilla que permita diferenciar claramente que es una embarcación de remos.', false, '2025-09-13 13:53:11.639224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('562c2577-b9dc-4438-867d-ab0291df232e', '66583481-073f-4c5a-a2fc-9ff870b61ebb', 'b', 'Sólo si el pabellón de estas es extranjero, siempre que tengan entrada o salida en un puerto español.', false, '2025-09-13 13:53:11.632183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b631ff33-f5aa-42b0-8a6a-3af09a4afada', 'd1617727-1b61-4475-9cae-5b3e360fe58b', 'd', 'Esté a sotavento cuando ambos reciban el viento por la misma banda.', false, '2025-09-13 13:53:11.641181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3311d99-e98e-4494-a248-4ebb460e0754', '61109de6-8fdb-46ca-b642-c6815efd0788', 'a', 'Un buque restringido por su calado.', false, '2025-09-13 13:53:11.641481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58746144-71b7-4e3d-ae23-11d118dead8d', '61109de6-8fdb-46ca-b642-c6815efd0788', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:11.641619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7e25269-eb61-45a9-842a-dc04dbd38d37', '61109de6-8fdb-46ca-b642-c6815efd0788', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.641911+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8a89c97-7e6b-4e71-b463-9a19461b092e', '3ff4107b-a024-4e29-bb40-4f29b2755d7c', 'a', 'La expresión “buque con capacidad de maniobra restringida” incluirá los buques dedicados al lanzamiento o recuperación de aeronaves.', true, '2025-09-13 13:53:11.642206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('217bf289-04aa-41b0-8300-057c4b2dc2ff', '3ff4107b-a024-4e29-bb40-4f29b2755d7c', 'b', 'La expresión “buque sin gobierno” significa todo buque que maniobre sin capitán.', false, '2025-09-13 13:53:11.642349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa8c3cec-4639-4fb0-9420-28a2d24884ab', '3ff4107b-a024-4e29-bb40-4f29b2755d7c', 'c', 'La expresión “buque dedicado a la pesca” significa todo buque que pesque con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:11.642495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c52f6a4a-3de2-413d-aec4-996bf739c979', '3ff4107b-a024-4e29-bb40-4f29b2755d7c', 'd', 'La expresión “buque con capacidad de maniobra restringida” significa todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, puede apartarse de la derrota de otro buque.', false, '2025-09-13 13:53:11.642653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a6eadc6-87bf-40eb-aaa4-08f994718fb4', '8d9fae7e-f90d-49b3-99c9-b3ff559fff79', 'a', 'Al no tratarse de una nave proyectada para maniobrar sobre las aguas, no tiene que exhibir las luces con las características prescritas en el RIPA, por lo que no deberemos atender a las señales exhibidas por desconocer su intención.', false, '2025-09-13 13:53:11.642959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e98d3de0-0890-4b37-8c49-071135afd2b1', '8d9fae7e-f90d-49b3-99c9-b3ff559fff79', 'b', 'Exhibe luces destinadas al tráfico aéreo y estaremos obligados a consultar el Reglamento del aire para interpretar sus indicaciones.', false, '2025-09-13 13:53:11.643104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c130aa10-f43a-4d5f-89f5-95be2c9ea6d9', '8d9fae7e-f90d-49b3-99c9-b3ff559fff79', 'd', 'No le es posible exhibir las luces con las características prescritas y deberemos atender a las señales exhibidas como si se tratara de las luces reglamentariamente establecidas.', true, '2025-09-13 13:53:11.643382+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('715ae499-5b4f-4618-92f9-8709f9f836ac', 'fc5a48fd-9535-4fd1-873a-e97fc4b6e48d', 'a', 'No tendrán obligación de llevar ningún medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:11.643655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f37ef17-fc0a-44f2-992c-1a2143cde30f', 'fc5a48fd-9535-4fd1-873a-e97fc4b6e48d', 'b', 'No tendrán obligación de llevar ninguno de los dispositivos de señales acústicas prescritos para buques de eslora igual o superior a 12 metros, siempre que vayan dotados de otros medios para hacer señales acústicas eficaces.', true, '2025-09-13 13:53:11.64392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbf3aad4-50ab-4390-bde5-16d1522303e8', 'fc5a48fd-9535-4fd1-873a-e97fc4b6e48d', 'c', 'No tendrán obligación de llevar ningún dispositivo de señales acústicas siempre que vayan dotados de otros medios para hacer señales visuales eficaces.', false, '2025-09-13 13:53:11.644053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a28213f1-c38c-43db-967a-6c2b0db186c1', 'fc5a48fd-9535-4fd1-873a-e97fc4b6e48d', 'd', 'Tendrán obligación de ir dotados de un pito, en cualquier caso.', false, '2025-09-13 13:53:11.644183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1756d21b-e562-40c6-b9fc-6bd6f7ce9b4a', 'bf1385ba-0cd9-4aee-a5a4-e499a6199e3a', 'a', 'Que, al no realizar giro alguno, la proa realizará movimientos excesivos a ambas bandas.', false, '2025-09-13 13:53:11.645175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a312aa49-7d55-4ee7-a99d-0bb968f7ae2c', 'bf1385ba-0cd9-4aee-a5a4-e499a6199e3a', 'b', 'Que, al no realizar giro alguno, la proa realizará movimientos mínimos a ambas bandas.', false, '2025-09-13 13:53:11.645323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04796364-6a84-4d88-96fc-7685b1dd5db5', 'bf1385ba-0cd9-4aee-a5a4-e499a6199e3a', 'c', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo menor que el correspondiente a la trayectoria del punto giratorio.', false, '2025-09-13 13:53:11.645456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e53c4c8-7975-4c44-afcf-f22f66589eba', 'bf1385ba-0cd9-4aee-a5a4-e499a6199e3a', 'd', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo mayor que el correspondiente a la trayectoria del punto giratorio.', true, '2025-09-13 13:53:11.64559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0741b94a-e0af-4c54-9b7d-7f198aba8c01', '6f87e63e-dbaa-4da0-8b77-807a3e8ddb43', 'a', 'Largando amarras de proa y dando atrás toda a la par que largamos la del muerto.', false, '2025-09-13 13:53:11.64586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db3c4a2c-6ed7-4a45-8542-fa305ff300ab', '6f87e63e-dbaa-4da0-8b77-807a3e8ddb43', 'b', 'Largando amarras de proa, a continuación, la del muerto y después, dando atrás poca controlando el efecto de la hélice en la maniobra.', true, '2025-09-13 13:53:11.645991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb525017-416e-46d4-a5d5-c38f06bc121c', '6f87e63e-dbaa-4da0-8b77-807a3e8ddb43', 'c', 'Dando atrás poca a la par que largamos todas las amarras menos el esprín de proa que nos ayudará a salir girando lentamente la embarcación.', false, '2025-09-13 13:53:11.646126+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07984409-9611-4944-8395-9130f68e643f', '6f87e63e-dbaa-4da0-8b77-807a3e8ddb43', 'd', 'Largando amarras de popa y dando avante poca a la par que largamos la del muerto. Emergencias en la mar.', false, '2025-09-13 13:53:11.646259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57bacf96-6f5c-4597-98dc-982ebd11cfd0', '10677f64-b90b-46d5-a6d1-ae1167a81f8b', 'a', 'Para prevenir una vía de agua se debe, entre otras cosas, cerrar las válvulas que no se utilicen, asegurar la estanquidad de portillos y escotillas, fijar las baterías y todo el material pesado y evitar el agua en la sentina.', true, '2025-09-13 13:53:11.646533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3710f711-66e5-4173-8d5a-890c5a01f8cf', '10677f64-b90b-46d5-a6d1-ae1167a81f8b', 'b', 'Si falla una válvula o un pasa cascos, se taponará desde el interior con colchonetas, manteniendo apretado el cierre.', false, '2025-09-13 13:53:11.646666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbd95a8e-1c30-4667-b635-8f70783c1684', '10677f64-b90b-46d5-a6d1-ae1167a81f8b', 'd', 'Una embarcación medio hundida es peor lugar para esperar ayuda que una balsa, por lo que deberá pasar a esta en cuanto detecte una vía de agua a bordo.', false, '2025-09-13 13:53:11.646936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db90dadc-facb-40ab-91d3-98d88568aded', 'e9e8682d-3b43-471b-8c6f-e85769310881', 'a', 'Si no dispone de balsa salvavidas, salte al agua y nade para evitar los efectos de la hipotermia.', false, '2025-09-13 13:53:11.647213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8528bb81-ba40-4913-8a93-304ae9b4d40c', 'e9e8682d-3b43-471b-8c6f-e85769310881', 'b', 'Encienda una bengala con el brazo alargado por fuera de cubierta a barlovento, posicionando la bengala vertical y alejada de otras personas.', false, '2025-09-13 13:53:11.647346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed3030d8-5bea-446d-b804-1243a6b36671', 'e9e8682d-3b43-471b-8c6f-e85769310881', 'd', 'Deberá ponerse el chaleco salvavidas y saltar al agua de cabeza, para evitar que con el impacto pueda perder el chaleco.', false, '2025-09-13 13:53:11.647747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('869b226e-c23e-4f30-be7c-3fbe81bd23ae', 'd7992e9b-8a2f-4864-8364-298ae8ba3fd7', 'a', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con buen tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', true, '2025-09-13 13:53:11.648048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e15ac67-d8a9-42a2-a3fc-c990a9782cff', 'd7992e9b-8a2f-4864-8364-298ae8ba3fd7', 'b', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con mal tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', false, '2025-09-13 13:53:11.648183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7892c2cf-2571-456e-8f21-39990dfbe462', 'd7992e9b-8a2f-4864-8364-298ae8ba3fd7', 'c', 'En caso de vía de agua en la flotación, se deberá escorar el barco lo necesario para que el orificio de entrada quede debajo del agua.', false, '2025-09-13 13:53:11.648351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e14946d5-3e4c-42c3-82d4-4d1e3126b2c7', '5a91a7df-b37c-4ff0-9e4d-b59a52a89135', 'c', 'Un candelero que pase por los extremos de los guardamancebos.', false, '2025-09-13 13:53:11.659935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c419fe40-9510-4e08-a515-9a1b745a5db9', '8d9fae7e-f90d-49b3-99c9-b3ff559fff79', 'c', 'Exhibe luces destinadas al tráfico aéreo y no deberemos atender a las señales exhibidas en ningún caso.', false, '2025-09-13 13:53:11.643244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3a52834-e623-4ec2-ae30-c406750358bd', '10677f64-b90b-46d5-a6d1-ae1167a81f8b', 'c', 'Si a bordo detecta agua salada y fría, siempre indicará una fuga procedente de la refrigeración del motor.', false, '2025-09-13 13:53:11.646796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc5fc8ee-cb03-4beb-ab62-6238aae455e1', 'e9e8682d-3b43-471b-8c6f-e85769310881', 'c', 'Si dispone de balsa salvavidas, deberá amarrar a bordo la driza de la balsa antes de lanzarla al agua.', true, '2025-09-13 13:53:11.647614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('789872e3-3e2c-48c3-acb2-2d587fa0ec28', '61109de6-8fdb-46ca-b642-c6815efd0788', 'c', 'Un buque de vela exhibiendo una marca cónica con el vértice hacia abajo de eslora igual a.', false, '2025-09-13 13:53:11.641755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2acd474-74a4-467c-8f3b-86ee6dc2a1ef', 'd7992e9b-8a2f-4864-8364-298ae8ba3fd7', 'd', 'No es necesario intercambiar ninguna información de las embarcaciones involucradas, ni comunicar a la compañía aseguradora los hechos acontecidos. Meteorología', false, '2025-09-13 13:53:11.64849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7121ff57-d8a0-43a4-983e-36f644ebcb79', '2a0de1b8-8dea-423a-b9ff-275f7fdf3657', 'a', 'Informa del calor o energía térmica de una sustancia.', false, '2025-09-13 13:53:11.648785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a13ca41-6924-4b6b-bece-b5423c1ee8cf', '2a0de1b8-8dea-423a-b9ff-275f7fdf3657', 'c', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:11.649051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d65fca4-68e3-41f8-b35a-6eef1d1abd8f', '2a0de1b8-8dea-423a-b9ff-275f7fdf3657', 'd', 'La escala Celsius permite expresar la temperatura en grados centígrados o grados Celsius.', false, '2025-09-13 13:53:11.649185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aee2d722-7fb1-417e-ba53-3aca1ec4b940', '6a34dded-33d0-4a31-b2d5-4364de160289', 'a', 'Cambia de dirección.', true, '2025-09-13 13:53:11.649469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de527175-3417-4edc-a7ca-7567a723b93c', '6a34dded-33d0-4a31-b2d5-4364de160289', 'b', 'Ve disminuida su fuerza.', false, '2025-09-13 13:53:11.649604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('576c0e70-4a1f-4943-9eef-562f4be341ba', '6a34dded-33d0-4a31-b2d5-4364de160289', 'c', 'Ve aumentada su intensidad.', false, '2025-09-13 13:53:11.649736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c76e375-76af-44f8-9f18-55c6ef4480a7', '6a34dded-33d0-4a31-b2d5-4364de160289', 'd', 'Cesa, bien sea momentáneamente o por un periodo de tiempo más largo.', false, '2025-09-13 13:53:11.64988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6f9cc34-4f13-4ba3-89e4-f4cf9b60478c', '85637b91-504b-4e92-8006-6fdb23cdf273', 'a', 'El número de horas que el viento sopla o ha soplado en la misma dirección.', true, '2025-09-13 13:53:11.650156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e613a887-d484-4f23-92c8-23c991eb6a0d', '85637b91-504b-4e92-8006-6fdb23cdf273', 'b', 'La intensidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.650289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41786d68-cf11-4259-8cd0-7fc02690b0d3', '85637b91-504b-4e92-8006-6fdb23cdf273', 'c', 'La velocidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.65042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fecd3c0-bbb3-4fc4-b534-a8d8879d99c6', '85637b91-504b-4e92-8006-6fdb23cdf273', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes.', false, '2025-09-13 13:53:11.650553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68d9a4dd-e1cc-4ae7-b92b-de96b672fc56', 'e2ca26db-a8ea-4680-aba3-cae678560b7a', 'a', 'La presión atmosférica disminuye a medida que nos acercamos al centro del anticiclón provocando que el aire fluya hacia afuera de ellos.', false, '2025-09-13 13:53:11.65083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9bccdc8-d8ea-41e7-8ef4-80563409160c', 'e2ca26db-a8ea-4680-aba3-cae678560b7a', 'b', 'El proceso de formación de un anticiclón se denomina ciclogénesis.', false, '2025-09-13 13:53:11.650963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('119c7cfe-63d5-4ad3-bbd9-51b6b935e34b', 'e2ca26db-a8ea-4680-aba3-cae678560b7a', 'c', 'El aire desciende por el interior de los anticiclones.', true, '2025-09-13 13:53:11.651094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5f2a17e-756f-4f2a-8f3a-ae2f22c03951', 'e2ca26db-a8ea-4680-aba3-cae678560b7a', 'd', 'El movimiento de aire asociado produce formación de nubosidad y precipitaciones. Teoría de la navegación.', false, '2025-09-13 13:53:11.651229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc412111-4400-4072-b5d4-12a964d05496', 'ceb76ce3-1ed4-4ce1-8bee-b735b2ef9d28', 'a', 'El Instituto Superior de Investigaciones Científicas.', false, '2025-09-13 13:53:11.651633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3b8c48e-cfac-4f66-bbdd-988efc7675e0', 'ceb76ce3-1ed4-4ce1-8bee-b735b2ef9d28', 'b', 'El Instituto Hidrográfico de la Marina.', true, '2025-09-13 13:53:11.651771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('680a26b0-1f42-42d4-9339-eec516dd21a2', 'ceb76ce3-1ed4-4ce1-8bee-b735b2ef9d28', 'c', 'El Instituto Social de la Marina.', false, '2025-09-13 13:53:11.651911+00');
