INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b2712a8-5447-4e19-a7eb-36dc7ebbb8d9', 'eaafbec3-d932-43c6-bbb8-b484f324ab2a', 'a', 'La altura de la bajamar en el instante de la pleamar.', false, '2025-09-13 13:53:11.652344+00');
