INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30d76826-928c-40be-952e-4ef5515212e0', 'eaafbec3-d932-43c6-bbb8-b484f324ab2a', 'c', 'La altura de la bajamar en el instante de la bajamar.', false, '2025-09-13 13:53:11.65261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('456a48d8-4f55-46b4-8faa-6b7c6e79225c', 'eaafbec3-d932-43c6-bbb8-b484f324ab2a', 'd', 'El nivel del DATUM en el instante de la bajamar.', false, '2025-09-13 13:53:11.652738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b09447ea-c669-4139-9042-1770fd73ca00', '0d751333-876d-4637-a17a-20cf4afa34e2', 'a', 'Solo puede expresarse en circulares, de 0° a 360°.', false, '2025-09-13 13:53:11.653014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1da5bc6e-dac8-440b-baa8-f5bbc5b8824a', '0d751333-876d-4637-a17a-20cf4afa34e2', 'b', 'Se define como el ángulo que forma el Norte con la línea de la visual dirigida a ese punto.', false, '2025-09-13 13:53:11.653147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c717114-792b-4c15-b975-422af6cc1ca6', '0d751333-876d-4637-a17a-20cf4afa34e2', 'c', 'Es independiente del rumbo de nuestra embarcación.', false, '2025-09-13 13:53:11.65328+00');
