INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdb55bd1-34b7-40ed-99aa-6bdaf8d97008', 'b1995f06-d1b3-4f30-bbc3-9083043ca84a', 'a', 'La décima parte de un cable.', false, '2025-09-13 13:53:11.653678+00');
