INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aeddcce0-8084-4d94-9f94-31fbcd26921a', 'c965af1b-aeeb-4f19-892a-60377de41565', 'd', 'Un bloque de material pesado depositado en el fondo que, unido por un orinque a la superficie, permite amarrar una embarcación.', false, '2025-09-13 13:53:11.661549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a3f6ceb-1e2a-49ed-b78a-ae12712f7869', '3682fef6-8f2e-4799-8e38-60e852c72479', 'a', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', false, '2025-09-13 13:53:11.661818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d90686c-83a9-4015-a9aa-034c803ccf92', '3682fef6-8f2e-4799-8e38-60e852c72479', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la sonda y naturaleza del fondo.', true, '2025-09-13 13:53:11.66195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7772d1a0-e0ef-4012-af37-e9b28ac0054f', '3682fef6-8f2e-4799-8e38-60e852c72479', 'c', 'El orinque es el cabo que se amarra por un chicote a la cruz del ancla y por el otro a la proa de la embarcación para poder recuperar el ancla.', false, '2025-09-13 13:53:11.66208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18be1da5-577a-498a-8704-de2187082fab', '3682fef6-8f2e-4799-8e38-60e852c72479', 'd', 'Las embarcaciones deben disponer de una línea de fondeo cuya longitud será inferior a cuatro veces la eslora de la embarcación.', false, '2025-09-13 13:53:11.662208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d80c65d4-6469-43c8-8519-b7a8f23a7217', '374ef479-399c-404a-b6a2-a874ca619f21', 'a', 'Tener un ancla lista para fondear, y si lo hay disponible, un anclote a popa.', false, '2025-09-13 13:53:11.662479+00');
