INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a0e3779-e6a7-42e2-a0a9-9f61f0381ca3', '018682bf-e25c-43d7-8007-7c28715b8cf7', 'd', 'Siempre que sean productos avícolas introducidos, incluidas las aves o partes de aves.', false, '2025-09-13 13:53:11.665527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29ed7352-1dd0-4501-b66d-071dfd172e49', 'f2d49d3a-6011-4d73-8a64-eda7606e9295', 'b', 'Contractual penal en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas y las personas que debidamente autorizadas por el propietario patroneen las mismas y los usuarios de cualquier objeto que pueda arrastrar la embarcación.', false, '2025-09-13 13:53:11.666062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bae8dab1-8c40-4b5b-9cee-58bd91a1e8bc', 'f2d49d3a-6011-4d73-8a64-eda7606e9295', 'c', 'Civil extracontractual en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas, las personas que debidamente autorizadas por el propietario patroneen las mismas, así como aquellas otras que les secunden en su gobierno, pero nunca la de los esquiadores o de otros usuarios de cualquier objeto que pueda arrastrar la embarcación.', false, '2025-09-13 13:53:11.666193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('419f970d-9795-452d-b50a-e81ad26ee86a', 'f2d49d3a-6011-4d73-8a64-eda7606e9295', 'd', 'Contractual civil en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas y las personas que debidamente autorizadas por el propietario patroneen las mismas.', false, '2025-09-13 13:53:11.666323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76e8ace9-0f6d-4c03-a157-8e5e954e77ec', 'e4144fe4-760c-4353-9f42-56fe502d11eb', 'a', 'Con unos ritmos idénticos. No es posible confundirlas porque las Marcas de Aguas Navegables tienen un aspecto muy distinto de las de las boyas que balizan un peligro.', false, '2025-09-13 13:53:11.666591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f61514c-a16e-44ba-b950-09699659b16b', 'e4144fe4-760c-4353-9f42-56fe502d11eb', 'b', 'Con unos ritmos característicos que no se confunden con el ritmo de centelleos muy rápidos o rápidos de las Marcas Cardinales.', true, '2025-09-13 13:53:11.666724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52be704f-eba7-4cd7-8a9a-593f72074f02', 'e4144fe4-760c-4353-9f42-56fe502d11eb', 'd', 'Sólo las Marcas de Aguas Navegables utilizan luces blancas. La luz en las Marcas de Peligro Aislado (si tiene) es verde.', false, '2025-09-13 13:53:11.667017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84546836-d62c-4d79-b61a-ad60f14ad43d', 'ec390927-44f7-433f-ae21-6a3c4800177a', 'a', 'Que las aguas más profundas en esa zona no se encuentran en el cuadrante correspondiente al nombre de la marca.', false, '2025-09-13 13:53:11.66735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8dfe45fb-e44d-422c-8daf-d07232389e43', 'ec390927-44f7-433f-ae21-6a3c4800177a', 'b', 'El lado por el que no se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:11.667506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48c6b84d-aba2-4acc-9602-b5f40ce9d900', 'ec390927-44f7-433f-ae21-6a3c4800177a', 'c', 'Dónde están las aguas navegables.', true, '2025-09-13 13:53:11.667637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71a2012a-58f6-47c5-93a8-bb845ee19ea0', 'ec390927-44f7-433f-ae21-6a3c4800177a', 'd', 'Una configuración a la que se hace referencia en las publicaciones náuticas.', false, '2025-09-13 13:53:11.66777+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb5571cb-f15a-4753-b820-07ef108be258', 'd3abd228-e62b-4eae-a212-6a66f77cd807', 'a', 'Rojo y forma cilíndrica.', true, '2025-09-13 13:53:11.668051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d4eb119-f41b-44c9-891b-e9840b479347', 'd3abd228-e62b-4eae-a212-6a66f77cd807', 'b', 'Verde y forma cónica.', false, '2025-09-13 13:53:11.668183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d45df563-0ae6-423b-a6d9-5e15f817f718', 'e4144fe4-760c-4353-9f42-56fe502d11eb', 'c', 'Con unos ritmos distintos; el ritmo de la Marca de Aguas Navegables es un grupo de.', false, '2025-09-13 13:53:11.666864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f6d69c8-07da-4c7b-9801-614662ddde74', 'f2d49d3a-6011-4d73-8a64-eda7606e9295', 'a', 'Civil extracontractual en que puedan incurrir los propietarios de embarcaciones de recreo o deportivas, las personas que debidamente autorizadas por el propietario patroneen las mismas, así como aquellas otras que les secunden en su gobierno y los esquiadores que pueda arrastrar la embarcación.', true, '2025-09-13 13:53:11.665931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e77c647e-1450-4e20-bf36-064435e9509e', '8c39453c-defe-4a7a-91a3-eb93ad7f85e8', 'c', 'Peligros aislados de dimensiones limitadas, que están enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:11.669019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7a57f4c-68a6-4d89-9266-48f6b0826f2d', '8c39453c-defe-4a7a-91a3-eb93ad7f85e8', 'd', 'Los límites de un área de fondeo.', false, '2025-09-13 13:53:11.669162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6addfcf-7b90-459e-809f-a16eaa91cfaa', '8fa6286b-828d-4553-b066-d9f0604d2443', 'a', 'Es siempre la misma: sólo se utilizan para indicar una zona reservada al recreo.', false, '2025-09-13 13:53:11.669442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cada931-726b-45ce-afea-4905c8f202b9', '8fa6286b-828d-4553-b066-d9f0604d2443', 'b', 'Se visualiza al consultar la carta u otra publicación náutica.', true, '2025-09-13 13:53:11.669575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44fd14d5-23d6-4e0e-98eb-60a2fba5d5ad', '8fa6286b-828d-4553-b066-d9f0604d2443', 'c', 'Se conoce a través de los avisos a navegantes.', false, '2025-09-13 13:53:11.669709+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5261b555-99a6-4e03-a27c-61e8c3bc16f7', '8fa6286b-828d-4553-b066-d9f0604d2443', 'd', 'Se encuentra definida por las normas de cada puerto que es publicada en el Boletín Oficial de la Provincia anualmente. Reglamento (RIPA).', false, '2025-09-13 13:53:11.66986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eaaf76aa-ae40-4a90-80cc-fc55f9565697', 'a894ba1f-7315-4615-8804-126319657ba1', 'a', 'Una luz azul continua.', true, '2025-09-13 13:53:11.670151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79fd866d-2ea5-4e1f-a347-c583577adcc1', 'a894ba1f-7315-4615-8804-126319657ba1', 'b', 'Una luz blanca, con ritmo centelleante continuo, muy rápido o rápido.', false, '2025-09-13 13:53:11.670286+00');
