INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00094dfd-9a3a-46ff-9abe-417316f01d0e', 'a894ba1f-7315-4615-8804-126319657ba1', 'd', 'Una luz amarilla giratoria de gran intensidad.', false, '2025-09-13 13:53:11.670681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('630336c1-0e83-47d4-b3e0-a5c5fab1b041', 'e64209f6-03c6-4a54-9df2-595aa0d44c51', 'a', 'Reducir su velocidad hasta la mínima de gobierno y si fuera necesario, suprimir su arrancada.', true, '2025-09-13 13:53:11.670976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2c9867f-02a0-4e9c-8fbf-9a3eb84e20ee', 'e64209f6-03c6-4a54-9df2-595aa0d44c51', 'b', 'Aumentar su velocidad hasta la máxima de la máquina.', false, '2025-09-13 13:53:11.671112+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac65ddf1-8cd0-4041-8d1f-d50c350d7e25', 'e64209f6-03c6-4a54-9df2-595aa0d44c51', 'c', 'Reducir su velocidad hasta la mínima de gobierno y mantener en todo momento su arrancada.', false, '2025-09-13 13:53:11.671243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcbd0417-e2ed-4a47-85a6-b55a4b93e354', 'e64209f6-03c6-4a54-9df2-595aa0d44c51', 'd', 'Prestar atención a otros Reglamentos, pero no a éste, ya que éste solo aplica a buques mercantes.', false, '2025-09-13 13:53:11.671376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b5c1598-eb78-4a18-af21-ed547ead13d5', '9f1a3f15-1839-4b33-b74d-6214adec0d1c', 'a', '225 grados.', true, '2025-09-13 13:53:11.671652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03556b96-5608-465c-b83a-ecdd738c3ad2', '9f1a3f15-1839-4b33-b74d-6214adec0d1c', 'b', '112,5 grados.', false, '2025-09-13 13:53:11.671784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e9896af-ada6-4b47-8ce3-a834555acc4e', '9f1a3f15-1839-4b33-b74d-6214adec0d1c', 'c', '135 grados.', false, '2025-09-13 13:53:11.671919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f89050b9-d52f-464d-a0a9-0e3fcd47cb72', '9f1a3f15-1839-4b33-b74d-6214adec0d1c', 'd', '360 grados.', false, '2025-09-13 13:53:11.67205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce75884e-c891-4416-9f68-469a6fac5102', 'bfd9a10e-db85-42e2-a63b-3b39ff27a865', 'a', 'El buque remolcado tiene una anchura igual o superior a 25 metros.', false, '2025-09-13 13:53:11.672325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('067d4f2f-ab90-486b-9302-c11510be9dba', 'bfd9a10e-db85-42e2-a63b-3b39ff27a865', 'b', 'La longitud de remolque es superior a 200 metros.', true, '2025-09-13 13:53:11.672457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db32db1b-9638-4985-a917-753d7ebe0b24', 'bfd9a10e-db85-42e2-a63b-3b39ff27a865', 'c', 'El buque remolcado tiene una anchura inferior a 25 metros.', false, '2025-09-13 13:53:11.672589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9e88fb4-5fe9-4087-b78a-f1b67d27bbed', 'bfd9a10e-db85-42e2-a63b-3b39ff27a865', 'd', 'La longitud de remolque es igual o inferior a 200 metros.', false, '2025-09-13 13:53:11.67272+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eca00ada-3b30-4cef-9421-e39402f44395', '0f6cd227-a6ab-483f-a2c9-54b0f7ee3b0d', 'a', 'Al aproximarse un buque de gran tamaño, se considerará que puede existir riesgo de abordaje aun cuando sea evidente una variación apreciable de la demora.', false, '2025-09-13 13:53:11.673011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f28f5937-af3f-4fa2-91f5-4431e1f543ec', '0f6cd227-a6ab-483f-a2c9-54b0f7ee3b0d', 'b', 'Al aproximarse a un buque a muy corta distancia, se considerará que puede existir riesgo de abordaje únicamente en el caso de que la demora no varíe.', true, '2025-09-13 13:53:11.673149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6755d27-7b21-4fbc-96a2-4930f4855d7a', '0f6cd227-a6ab-483f-a2c9-54b0f7ee3b0d', 'c', 'Si la demora de un buque que se aproxima no varía en forma apreciable, se considerará que existe riesgo de abordaje.', false, '2025-09-13 13:53:11.673283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27e9590f-60ec-4941-9813-16dd1aed4d08', '0f6cd227-a6ab-483f-a2c9-54b0f7ee3b0d', 'd', 'Si la demora de un buque que se aproxima en la lejanía varía de forma apreciable, no se considerará riesgo de abordaje, pero el patrón se mantendrá atento a cualquier variación.', false, '2025-09-13 13:53:11.673417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21607858-428d-4c73-8e17-f8e430a98625', '086872c3-86e2-4407-9214-19ac3feea65b', 'a', 'Su proa viendo la luz de tope blanca y las luces de costado.', true, '2025-09-13 13:53:11.673711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f850dea-8237-4693-91f6-cf24e35c3b90', '086872c3-86e2-4407-9214-19ac3feea65b', 'b', 'Su popa viendo la luz de alcance.', false, '2025-09-13 13:53:11.673845+00');
