INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4281ef1-282e-4ce1-aac0-29948bada0ff', 'ad8dceb8-7120-4b3a-8ab0-094d4429a6b2', 'a', 'Navegar por la zona de separación del tráfico, y al salir o entrar en el dispositivo, hacerlo con el mayor ángulo posible en relación con la dirección general de la corriente del tráfico.', false, '2025-09-13 13:53:11.675222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca6aa5dc-8d42-452c-80f2-c9d738fe5f5c', 'ad8dceb8-7120-4b3a-8ab0-094d4429a6b2', 'b', 'Dado que se tendría prioridad de paso por ser los otros buques de propulsión mecánica, se podrá navegar indistintamente por cualquier zona del dispositivo.', false, '2025-09-13 13:53:11.675355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca2da33a-8bba-4cef-9bb2-ec8d7ac272bb', 'ad8dceb8-7120-4b3a-8ab0-094d4429a6b2', 'c', 'Tratando de no estorbar a los buques circulando por el dispositivo, pudiendo para ello navegar en la zona de navegación costera adyacente.', true, '2025-09-13 13:53:11.675487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e48ea208-84d6-4d9b-b67a-6fe113a607fb', 'ad8dceb8-7120-4b3a-8ab0-094d4429a6b2', 'd', 'Priorizando cruzar las vías de circulación con un rumbo con el mayor ángulo posible en relación con la dirección general de la corriente del tráfico por ser este más ventajoso para transitar el dispositivo a vela.', false, '2025-09-13 13:53:11.675622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09e3567e-4f2a-4c71-93a5-366d02abbf26', 'dd1ddd6d-46ed-433c-b2b9-58d9e605f657', 'a', 'El Estado de pabellón de la embarcación.', true, '2025-09-13 13:53:11.675913+00');
