INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a739803-720d-4061-810b-ca8a2e523c91', '00d48ecd-e67d-4816-9d32-0b20c75164ac', 'a', 'Dejaremos caer la proa a estribor hasta dar la vuelta completa con muy poca máquina avante.', false, '2025-09-13 13:53:11.677268+00');
