INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('565d621d-1f18-4685-a9cd-ab900f2e4c35', '99f19269-68fb-4ae1-b182-ff156a585329', 'a', 'La distancia a costa.', false, '2025-09-13 13:53:11.683637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a67672e-3366-469a-9d11-32c8c0618a0d', '99f19269-68fb-4ae1-b182-ff156a585329', 'b', 'El Rumbo.', true, '2025-09-13 13:53:11.683769+00');
