INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4f4f171-2a3a-4c4d-9785-881370387824', '9ea12f0a-31d5-4cd8-8ef3-e3d4cb5d4802', 'a', 'Formar una gaza que no sea corrediza y así poder encapillar un cabo.', false, '2025-09-13 13:53:11.692976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da3d562f-e4b5-4740-a908-83e2f10a2883', '9ea12f0a-31d5-4cd8-8ef3-e3d4cb5d4802', 'b', 'Afirmar rápidamente un cabo a un palo, cáncamo o argolla.', false, '2025-09-13 13:53:11.693105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6acc492e-0041-4c1d-bbf6-199e85a11396', '9ea12f0a-31d5-4cd8-8ef3-e3d4cb5d4802', 'c', 'Unir por sus chicotes dos cabos de una misma mena.', true, '2025-09-13 13:53:11.693365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac8eb9ab-e535-44cd-89a9-88ff338282a6', '9ea12f0a-31d5-4cd8-8ef3-e3d4cb5d4802', 'd', 'Amarrar los cabos de una defensa a un pasamanos.', false, '2025-09-13 13:53:11.693496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45f8f502-84b7-45ec-b5ea-4229cd9afe87', '1e2c6910-9315-427d-887b-a2c464fdef71', 'a', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:11.693774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f85fe557-ae5e-4e74-9eec-fd8f532590bb', '1e2c6910-9315-427d-887b-a2c464fdef71', 'b', 'El círculo de borneo tiene como centro el ancla y como radio, la longitud de cadena filada más la eslora de la embarcación.', false, '2025-09-13 13:53:11.693909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c51df0eb-d41a-48df-8215-d1711a3f2c56', '1e2c6910-9315-427d-887b-a2c464fdef71', 'c', 'Un barco fondea a la gira cuando utiliza dos anclas por proa, cuyas líneas de fondeo forman un ángulo de entre 60º y 120º.', true, '2025-09-13 13:53:11.694038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc9d0a89-509a-4cbc-9267-a9a559162fad', '1e2c6910-9315-427d-887b-a2c464fdef71', 'd', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear una segunda ancla o aguantar con máquina avante.', false, '2025-09-13 13:53:11.694167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f99327d0-eee6-4f5c-94cd-a38f69d9085b', 'a09c9dfa-7d13-4784-9259-76cc4367ecb1', 'a', 'Parar máquinas.', false, '2025-09-13 13:53:11.694441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('011f5255-50c0-44e0-9dbc-84c92513c938', 'a09c9dfa-7d13-4784-9259-76cc4367ecb1', 'b', 'Poner la popa o aleta a la mar.', true, '2025-09-13 13:53:11.694573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5cb45791-e697-4895-963f-56358a25fb55', 'a09c9dfa-7d13-4784-9259-76cc4367ecb1', 'c', 'Permanecer atravesados a la mar.', false, '2025-09-13 13:53:11.694708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('460a33c7-add5-4212-bcb3-95e7ed210290', 'a09c9dfa-7d13-4784-9259-76cc4367ecb1', 'd', 'Izar la vela mayor.', false, '2025-09-13 13:53:11.694846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e303b64-4504-4d7c-827f-b962b87373f3', 'd614b7ca-7e2f-45f2-98bb-8ab019feb781', 'a', '1.', false, '2025-09-13 13:53:11.695116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f684ad8-fe98-42c7-9329-7df854f87fab', 'd614b7ca-7e2f-45f2-98bb-8ab019feb781', 'b', '3.', false, '2025-09-13 13:53:11.695246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('221d4f99-6bfa-4d7b-a57a-a1631e3ed8c5', 'd614b7ca-7e2f-45f2-98bb-8ab019feb781', 'c', '6.', false, '2025-09-13 13:53:11.695374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90e8a150-aeec-4a9b-9383-42500db044d0', 'd614b7ca-7e2f-45f2-98bb-8ab019feb781', 'd', 'Ninguna.', true, '2025-09-13 13:53:11.695504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee97ee1b-9498-4c42-89a5-b5f6173e9807', '1d036d2f-e981-4836-8afd-e72516addb24', 'b', 'No dar de beber alcohol al afectado.', false, '2025-09-13 13:53:11.695952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88596739-af33-49ce-aaf1-0d4ee4319a64', '1d036d2f-e981-4836-8afd-e72516addb24', 'c', 'Hacer una llamada de socorro si el afectado está inconsciente.', false, '2025-09-13 13:53:11.696095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62885059-0e25-4c3e-ad05-9057cfa0ffee', '1d036d2f-e981-4836-8afd-e72516addb24', 'd', 'Trasladar al afectado horizontalmente.', false, '2025-09-13 13:53:11.696232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7062535-984f-4d66-ba8c-c173844659bc', '860e85b6-4d18-41b8-b8d2-6027619084af', 'a', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, refrigeración, correa del alternador, nivel de combustible, agua dulce, baterías, luces de navegación, equipo de radio, estanqueidad, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', true, '2025-09-13 13:53:11.696511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf4e4677-0e74-41ef-a877-849dd40349b9', '860e85b6-4d18-41b8-b8d2-6027619084af', 'b', 'Niveles de aceite, cierre de todas las aperturas de abordo herméticamente, líquido refrigerante, refrigeración, correa del alternador, nivel de combustible, agua dulce, baterías, luces de navegación, equipo de radio, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.696646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b12a567e-03ca-4531-bff0-9600e09b3630', '860e85b6-4d18-41b8-b8d2-6027619084af', 'c', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, refrigeración, correa del alternador, nivel de combustible, agua dulce, baterías, luces de navegación, equipo de radio, que estén cerrados todos los grifos de fondo, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.696787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5ac4d4f-c736-475a-a4a9-ca2f84bf3f66', '860e85b6-4d18-41b8-b8d2-6027619084af', 'd', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, correa del alternador, climatización a bordo, nivel de combustible, agua dulce, baterías, equipo de radio, estanqueidad, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.696918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b622c29-60be-463b-bbb9-746ec868e5f7', '3509e58e-f7bc-45e0-ae91-acaa86a3c7ae', 'a', 'Se comunicará inmediatamente a la estación costera de la zona geográfica. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', true, '2025-09-13 13:53:11.69719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('deb1c007-e7ea-4526-b92f-5a5a0aa19d4c', '3d0e5c48-11bb-48fb-94f5-52d324f71900', 'c', 'Una luz verde de centelleos todo horizonte.', false, '2025-09-13 13:53:11.705955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3d3c470-f07b-4fad-8222-c04d1235f8cd', 'ecdf8605-346e-4f15-965e-78da292d6fb3', 'd', 'Una bomba de abozar.', false, '2025-09-13 13:53:11.692693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcf6fc47-0ace-4a7d-b3c9-855299d4a933', '3509e58e-f7bc-45e0-ae91-acaa86a3c7ae', 'b', 'Se comunicará inmediatamente a las embarcaciones que se encuentren en la zona. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', false, '2025-09-13 13:53:11.697324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93a077bb-557a-4b36-ba79-69243f5979ab', '3509e58e-f7bc-45e0-ae91-acaa86a3c7ae', 'c', 'Se comunicará, una vez se encuentre la embarcación en puerto, a la Autoridad Portuaria, para que esta active los protocolos anticontaminación pertinentes.', false, '2025-09-13 13:53:11.697459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cbb453a-22c8-4f6f-9153-8c9ebf7a648a', '3509e58e-f7bc-45e0-ae91-acaa86a3c7ae', 'd', 'Se comunicará, antes de entrar en puerto, el siguiente mensaje: «vertidos o riesgo de vertidos de productos contaminantes en el mar», indicando la zona aproximada donde se produjo el', false, '2025-09-13 13:53:11.69759+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8e2683c-bf88-4c7d-a101-05ddf1d883d1', '43ab1755-b265-4dc3-a5f1-f287bc81daba', 'a', 'Sólo si el pabellón de estas es español.', false, '2025-09-13 13:53:11.697993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98d4115a-1bc9-4fe2-9a90-c8cdcfb2342e', '43ab1755-b265-4dc3-a5f1-f287bc81daba', 'c', 'Si el pabellón de estas es español o, si es extranjero, siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:11.698263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a73af2b3-4557-432f-9c5e-9d7a5a696534', '43ab1755-b265-4dc3-a5f1-f287bc81daba', 'd', 'Sólo si el pabellón de estas es español y siempre que tengan entrada o salida en un puerto extracomunitario.', false, '2025-09-13 13:53:11.698391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b5efcb1-eca1-4ec3-b099-12692a3fc1c8', '192f4563-27f9-4fdf-8161-15697900087f', 'a', 'Es blanca y tiene un ritmo de isofase de ocultaciones, 1 destello largo cada 10 segundos.', true, '2025-09-13 13:53:11.698661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0722f46f-0b12-4a84-95ca-3f3a77080b53', '192f4563-27f9-4fdf-8161-15697900087f', 'b', 'Es blanca y su ritmo es un grupo de 2 destellos (GpD2).', false, '2025-09-13 13:53:11.698805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1331d452-f920-433a-904e-fbd18d053589', '192f4563-27f9-4fdf-8161-15697900087f', 'c', 'Las Marcas de aguas navegables en ningún caso están provistas de luz alguna.', false, '2025-09-13 13:53:11.69894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a31953b8-a4d4-4ea1-87ce-11513603bb26', '192f4563-27f9-4fdf-8161-15697900087f', 'd', 'Es blanca y tiene un ritmo que se puede confundir con el ritmo de centelleos muy rápidos o rápidos de las Marcas cardinales.', false, '2025-09-13 13:53:11.699067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('259980f7-d239-4559-8a2d-8fba8716e195', 'f67e90b9-7e16-4cfa-a1a0-f79aa8b3474b', 'a', 'Opuestos por sus bases.', false, '2025-09-13 13:53:11.699336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26200b05-60f9-4470-9f5f-f316f4eded19', 'f67e90b9-7e16-4cfa-a1a0-f79aa8b3474b', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:11.699465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f71aa9f0-234e-4446-bb44-132a9728e855', 'f67e90b9-7e16-4cfa-a1a0-f79aa8b3474b', 'c', 'Opuestos por sus vértices.', true, '2025-09-13 13:53:11.6996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01324b63-7352-45ee-b1e3-4e0790ea8489', 'f67e90b9-7e16-4cfa-a1a0-f79aa8b3474b', 'd', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.699734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6245090f-f367-47bb-9561-4377a25279ea', '9961f76e-192d-4684-9427-7d3ee2f09adb', 'a', 'Números pares para las verdes, números impares para las rojas.', false, '2025-09-13 13:53:11.700012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('488ce466-b2bb-40e9-b340-0824dd401a36', '9961f76e-192d-4684-9427-7d3ee2f09adb', 'b', 'Números pares para las rojas, números impares para las blancas.', false, '2025-09-13 13:53:11.700143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d5f0f6c-908c-4a58-ac9e-c7858e374c9a', '9961f76e-192d-4684-9427-7d3ee2f09adb', 'c', 'Números pares para las verdes, números impares para las blancas.', false, '2025-09-13 13:53:11.700274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73b8c26b-7358-4e96-a604-dfc2565a173c', '9961f76e-192d-4684-9427-7d3ee2f09adb', 'd', 'Números pares para las rojas, números impares para las verdes.', true, '2025-09-13 13:53:11.700406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5bb98d3-73d7-4e5d-a428-f043fc111fa5', '8c4dcac5-800d-47cc-a780-f581d9c0b3e0', 'a', 'Únicamente se utilizan para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.700677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81dcea6e-cc96-4463-bb4c-f104fdde1d03', '8c4dcac5-800d-47cc-a780-f581d9c0b3e0', 'b', 'Pueden indicar la presencia de cables o conductos submarinos.', true, '2025-09-13 13:53:11.700809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34088145-2fdf-468d-92e2-6fbbfac08efe', '8c4dcac5-800d-47cc-a780-f581d9c0b3e0', 'c', 'Son las únicas destinadas a señalar obstrucciones.', false, '2025-09-13 13:53:11.700939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e07f57b1-d459-49da-9cf7-34c747dc0874', '8c4dcac5-800d-47cc-a780-f581d9c0b3e0', 'd', 'Para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.70107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dabea57-8f2e-4267-b5e0-43bcf41eb55c', 'e37ed1ac-b2c1-41d0-9e8e-11bcb4560b0a', 'a', 'Rojo y blanco.', false, '2025-09-13 13:53:11.701339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bacceb2f-6144-4345-bb89-ce4b67db266b', 'e37ed1ac-b2c1-41d0-9e8e-11bcb4560b0a', 'b', 'Amarillo.', false, '2025-09-13 13:53:11.701469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37149e63-4bba-4981-ad5c-eb35eb065e4c', 'e37ed1ac-b2c1-41d0-9e8e-11bcb4560b0a', 'c', 'Azul con franjas verticales amarillas.', false, '2025-09-13 13:53:11.701599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5705244-c2eb-4670-afdf-ab0ec3c9e51b', 'e79d25b9-28ef-4f79-bc34-b0fead490b92', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', true, '2025-09-13 13:53:11.702003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3b169ca-926a-402f-b3d7-e673a500ecc8', 'e79d25b9-28ef-4f79-bc34-b0fead490b92', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.702137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f5b399d-b0d5-4948-9c42-71abab4ef69d', 'e79d25b9-28ef-4f79-bc34-b0fead490b92', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:11.702267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96ce57c8-7528-4635-b5fb-21b2408dfe09', 'e79d25b9-28ef-4f79-bc34-b0fead490b92', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.702397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f366427-ff15-4b01-aa8e-8cb17d525484', 'a3189162-208c-4216-a894-30c66d23e500', 'a', 'No tendrán obligación de llevar ningún medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:11.702803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c99b2ae-5222-4107-bd08-ea0525d05ad6', 'a3189162-208c-4216-a894-30c66d23e500', 'b', 'No tendrán obligación de llevar ninguno de los dispositivos de señales acústicas prescritos para buques de eslora igual o superior a 12 metros, siempre que vayan dotados de otros medios para hacer señales acústicas eficaces.', true, '2025-09-13 13:53:11.702936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ee53da2-5a30-495b-ba63-667cea5c12d7', 'a3189162-208c-4216-a894-30c66d23e500', 'c', 'No tendrán obligación de llevar ningún dispositivo de señales acústicas siempre que vayan dotados de otros medios para hacer señales visuales eficaces.', false, '2025-09-13 13:53:11.703067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93f0e694-3b9a-4aea-9189-ab8c105569f1', 'a3189162-208c-4216-a894-30c66d23e500', 'd', 'Tendrán obligación de ir dotados de un pito, en cualquier caso.', false, '2025-09-13 13:53:11.703197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06f68571-025a-4382-8809-d5f401ec2e91', '08da1558-dd87-43b0-b80e-f1f16ddb753a', 'a', 'Al no tratarse de una nave proyectada para maniobrar sobre las aguas, no tiene que exhibir las luces con las características prescritas en el RIPA, por lo que no deberemos atender a las señales exhibidas por desconocer su intención.', false, '2025-09-13 13:53:11.703474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76298b41-12f4-41f4-827e-bc64a7c6d6ef', '08da1558-dd87-43b0-b80e-f1f16ddb753a', 'b', 'Exhibe luces destinadas al tráfico aéreo y estaremos obligados a consultar el Reglamento del aire para interpretar sus indicaciones.', false, '2025-09-13 13:53:11.703606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2861edb3-245e-4b49-9145-90441ee3d3b7', '08da1558-dd87-43b0-b80e-f1f16ddb753a', 'd', 'No le es posible exhibir las luces con las características prescritas y deberemos atender a las señales exhibidas como si se tratara de las luces reglamentariamente establecidas.', true, '2025-09-13 13:53:11.703872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b152a566-fbca-48d6-9438-ff68c6087ad5', '4dad2915-a2fa-4f02-ad5c-2654bc53d9c8', 'a', 'Un buque restringido por su calado.', false, '2025-09-13 13:53:11.704172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35c8919e-8063-43c5-960b-341d2cabc14d', '4dad2915-a2fa-4f02-ad5c-2654bc53d9c8', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:11.704308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e11ec7e8-e353-410b-8c96-9cb77e6bd394', '4dad2915-a2fa-4f02-ad5c-2654bc53d9c8', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.704584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7eaef90-214e-4bf4-ab71-e23d4b6625df', 'fef12ac1-275d-42da-8e9f-861fd0bb0caa', 'a', 'Un cohete-bengala con paracaídas que produzca una luz roja.', true, '2025-09-13 13:53:11.704911+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3236d91-2233-4d35-b68e-3b9372b5e8e8', 'fef12ac1-275d-42da-8e9f-861fd0bb0caa', 'b', 'Un cohete-bengala con paracaídas que produzca una luz blanca.', false, '2025-09-13 13:53:11.705138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4b8a091-3736-41d4-8dc7-91fce1c6b20b', 'fef12ac1-275d-42da-8e9f-861fd0bb0caa', 'c', 'Una luz continua roja, proyectada en la dirección del receptor.', false, '2025-09-13 13:53:11.705277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('408751ba-a179-4acd-a199-17d15631dedd', 'fef12ac1-275d-42da-8e9f-861fd0bb0caa', 'd', 'Una luz continua blanca, proyectada en la dirección del receptor.', false, '2025-09-13 13:53:11.705408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f26d5e98-e8f2-40bd-9380-b9e731e3bcb2', '3d0e5c48-11bb-48fb-94f5-52d324f71900', 'a', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.705694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('851835a1-4978-4b6b-a289-8e39a7084f50', '3d0e5c48-11bb-48fb-94f5-52d324f71900', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:11.705827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('307d86e5-300b-410e-b1b2-8ec9add8ac37', '4dad2915-a2fa-4f02-ad5c-2654bc53d9c8', 'c', 'Un buque de vela exhibiendo una marca cónica con el vértice hacia abajo de eslora igual a.', false, '2025-09-13 13:53:11.704439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35b82085-fc33-478a-9532-f1d78828258b', 'e37ed1ac-b2c1-41d0-9e8e-11bcb4560b0a', 'd', 'Negro con una o varias anchas bandas horizontales rojas.', true, '2025-09-13 13:53:11.701728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6523ae4a-780f-49fd-a52b-fc1cb7a32d4d', '08da1558-dd87-43b0-b80e-f1f16ddb753a', 'c', 'Exhibe luces destinadas al tráfico aéreo y no deberemos atender a las señales exhibidas en ningún caso.', false, '2025-09-13 13:53:11.703735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4053b060-5717-4912-9f12-b4928f50af08', '3d0e5c48-11bb-48fb-94f5-52d324f71900', 'd', 'Una segunda luz de alcance.', false, '2025-09-13 13:53:11.706083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3810999c-84d9-4a1d-b220-37844cdfe1e3', 'e3aa09d9-eaa2-4812-8048-a49c85e8ced4', 'a', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.706386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9c5bebc-7374-4ea2-b29e-e59f54767fc9', 'e3aa09d9-eaa2-4812-8048-a49c85e8ced4', 'b', 'Un buque pesquero que no se encuentre realizando en ese momento tareas de pesca.', false, '2025-09-13 13:53:11.706522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57f684d0-4bf1-4be7-890d-2932290668f6', 'e3aa09d9-eaa2-4812-8048-a49c85e8ced4', 'c', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.706657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cae91618-3c0d-49db-ae7b-a429b1e69c96', 'e3aa09d9-eaa2-4812-8048-a49c85e8ced4', 'd', 'Todos los buques que tenga a la vista.', false, '2025-09-13 13:53:11.706787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('513b90f0-1dec-4eab-8a07-229b8d5a6da3', 'fbde9ff2-be47-445c-b787-336b1eaab226', 'a', 'Reciba el viento por estribor.', false, '2025-09-13 13:53:11.707069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd909d58-3f0c-4e67-9b84-e476552f4843', 'fbde9ff2-be47-445c-b787-336b1eaab226', 'b', 'Reciba el viento por popa.', false, '2025-09-13 13:53:11.7072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3777522e-e0e9-43da-a34a-7b5d78a4ac99', 'fbde9ff2-be47-445c-b787-336b1eaab226', 'c', 'Reciba el viento por babor.', true, '2025-09-13 13:53:11.707329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('596b76fe-e840-4c0a-ab10-c2b3db12c239', 'fbde9ff2-be47-445c-b787-336b1eaab226', 'd', 'Esté a sotavento cuando ambos reciban el viento por la misma banda.', false, '2025-09-13 13:53:11.707459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e062c69-421f-4f36-82cb-77b3aaab5925', '41670fb2-9627-486e-a91b-4972295f97f9', 'b', 'Una marca cónica con el vértice hacia abajo.', false, '2025-09-13 13:53:11.708003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e34cb8c-4476-4b46-89e5-51049eb36756', '41670fb2-9627-486e-a91b-4972295f97f9', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:11.708135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe6f6ac3-b215-4d70-bc7b-1a56ff5f1e82', '41670fb2-9627-486e-a91b-4972295f97f9', 'd', 'Una linterna eléctrica que muestre una luz blanca.', true, '2025-09-13 13:53:11.708267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('710a9755-cd3e-43fd-8ebb-c350fd98f569', 'c620dbe0-d597-4488-ba2b-f949d4632725', 'a', 'La expresión “buque con capacidad de maniobra restringida” incluirá los buques dedicados al lanzamiento o recuperación de aeronaves.', true, '2025-09-13 13:53:11.70855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc129ceb-01b2-4a14-a74f-50f2c0dad271', 'c620dbe0-d597-4488-ba2b-f949d4632725', 'b', 'La expresión “buque sin gobierno” significa todo buque que maniobre sin capitán.', false, '2025-09-13 13:53:11.708684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd3cb571-e426-4558-bb1c-1bcb5b519d73', 'c620dbe0-d597-4488-ba2b-f949d4632725', 'c', 'La expresión “buque dedicado a la pesca” significa todo buque que pesque con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:11.708817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aea06ead-81b5-4fde-b88c-a0cc8159bb94', 'c620dbe0-d597-4488-ba2b-f949d4632725', 'd', 'La expresión “buque con capacidad de maniobra restringida” significa todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, puede apartarse de la derrota de otro buque. Maniobra y navegación.', false, '2025-09-13 13:53:11.708949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49da8195-dd1f-4012-a16a-74c28850baa1', 'b523d21a-49b1-4af0-b4b8-8552e71e1992', 'a', 'Que, al no realizar giro alguno, la proa realizará movimientos excesivos a ambas bandas.', false, '2025-09-13 13:53:11.709223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('abcf0770-c581-4729-a36f-551956dbc00c', 'b523d21a-49b1-4af0-b4b8-8552e71e1992', 'b', 'Que, al no realizar giro alguno, la proa realizará movimientos mínimos a ambas bandas.', false, '2025-09-13 13:53:11.709355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d3ce5f3-1de5-4b45-bada-a348300c914a', 'b523d21a-49b1-4af0-b4b8-8552e71e1992', 'c', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo menor que el correspondiente a la trayectoria del punto giratorio.', false, '2025-09-13 13:53:11.709486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92c87896-447c-40f3-bc31-13500eccf76d', 'b523d21a-49b1-4af0-b4b8-8552e71e1992', 'd', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo mayor que el correspondiente a la trayectoria del punto giratorio.', true, '2025-09-13 13:53:11.709616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0c4e79e-5fdd-43e8-accb-3cd4ab8946ea', 'c3e56ce0-1a30-4ef6-b0e1-d7f20fcd1b84', 'a', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con buen tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', true, '2025-09-13 13:53:11.710636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('532a6c50-86b2-408d-962e-b7616cc97987', 'c3e56ce0-1a30-4ef6-b0e1-d7f20fcd1b84', 'b', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con mal tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', false, '2025-09-13 13:53:11.710784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfe9e055-4f0a-4e40-bac3-82a777d4f9d6', 'c3e56ce0-1a30-4ef6-b0e1-d7f20fcd1b84', 'c', 'En caso de vía de agua en la flotación, se deberá escorar el barco lo necesario para que el orificio de entrada quede debajo del agua.', false, '2025-09-13 13:53:11.710929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e81e99b-ffcd-4834-8f16-8728247c31b7', 'c3e56ce0-1a30-4ef6-b0e1-d7f20fcd1b84', 'd', 'No es necesario intercambiar ninguna información de las embarcaciones involucradas, ni comunicar a la compañía aseguradora los hechos acontecidos.', false, '2025-09-13 13:53:11.711058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9382221-90bb-4157-88e2-13d27df0a8a1', '5cd772e7-d4fe-444a-9b6c-9ba536012689', 'a', 'Si no dispone de balsa salvavidas, salte al agua y nade para evitar los efectos de la hipotermia.', false, '2025-09-13 13:53:11.711355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c058917-5058-48ac-8a52-216816826265', '5cd772e7-d4fe-444a-9b6c-9ba536012689', 'b', 'Encienda una bengala con el brazo alargado por fuera de cubierta a barlovento, posicionando la bengala vertical y alejada de otras personas.', false, '2025-09-13 13:53:11.711521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1db226cd-d18b-4d0e-a508-e68474499b5e', '5cd772e7-d4fe-444a-9b6c-9ba536012689', 'd', 'Deberá ponerse el chaleco salvavidas y saltar al agua de cabeza, para evitar que con el impacto pueda perder el chaleco.', false, '2025-09-13 13:53:11.711846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1794a2d-7ec7-415a-bd96-b7d586dfeaa0', '2edc426b-b2b5-4e60-a2a4-e18f8628620e', 'a', 'Para prevenir una vía de agua se debe, entre otras cosas, cerrar las válvulas que no se utilicen, asegurar la estanquidad de portillos y escotillas, fijar las baterías y todo el material pesado y evitar el agua en la sentina.', true, '2025-09-13 13:53:11.71215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afa23dd6-f892-4d36-a0a1-301c2e1bfc85', '2edc426b-b2b5-4e60-a2a4-e18f8628620e', 'b', 'Si falla una válvula o un pasa cascos, se taponará desde el interior con colchonetas, manteniendo apretado el cierre.', false, '2025-09-13 13:53:11.719438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60fde98e-a679-4e93-8886-acdd7378ae38', '2edc426b-b2b5-4e60-a2a4-e18f8628620e', 'd', 'Una embarcación medio hundida es peor lugar para esperar ayuda que una balsa, por lo que deberá pasar a esta en cuanto detecte una vía de agua a bordo. Meteorología', false, '2025-09-13 13:53:11.719821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47eee85f-8003-455b-8677-c09fb325e155', 'da946d8a-ac21-4156-945b-33c358701190', 'a', 'El número de horas que el viento sopla o ha soplado en la misma dirección.', true, '2025-09-13 13:53:11.720139+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fcdfee7-bf18-43cc-b675-497e9792de02', 'da946d8a-ac21-4156-945b-33c358701190', 'b', 'La intensidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.720275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68518682-d984-4e83-a694-ca764e3516fa', 'da946d8a-ac21-4156-945b-33c358701190', 'c', 'La velocidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.720411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0290e23f-1f60-480f-a764-ad1bca2864ef', 'da946d8a-ac21-4156-945b-33c358701190', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes.', false, '2025-09-13 13:53:11.720543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a65cd2a-ca32-4298-94b8-b5e72343c81d', '4a905fd3-13c2-43f4-a89f-067e23dc50a1', 'a', 'Cambia de dirección.', true, '2025-09-13 13:53:11.720828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edb11dc7-0aca-4048-97f0-ae169fd0ad1b', '4a905fd3-13c2-43f4-a89f-067e23dc50a1', 'b', 'Ve disminuida su fuerza.', false, '2025-09-13 13:53:11.720969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a5c20d6-0ba4-4c86-9358-640d2b9c17fb', '4a905fd3-13c2-43f4-a89f-067e23dc50a1', 'c', 'Ve aumentada su intensidad.', false, '2025-09-13 13:53:11.721099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ac3e45d-19a1-4a53-a5e2-4865c189e191', '4a905fd3-13c2-43f4-a89f-067e23dc50a1', 'd', 'Cesa, bien sea momentáneamente o por un periodo de tiempo más largo.', false, '2025-09-13 13:53:11.721235+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('784435f3-14a0-4b4e-baa3-c364146d1c7a', 'd9fd2ad4-98fd-4b7c-b6df-b70dcdfe2654', 'a', 'Informa del calor o energía térmica de una sustancia.', false, '2025-09-13 13:53:11.721505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('170742df-f484-4377-bee3-b92bdd880f0c', '5cd772e7-d4fe-444a-9b6c-9ba536012689', 'c', 'Si dispone de balsa salvavidas, deberá amarrar a bordo la driza de la balsa antes de lanzarla al agua.', true, '2025-09-13 13:53:11.711681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e961201-563b-4b24-92bb-b5bd22f1a5d7', '2edc426b-b2b5-4e60-a2a4-e18f8628620e', 'c', 'Si a bordo detecta agua salada y fría, siempre indicará una fuga procedente de la refrigeración del motor.', false, '2025-09-13 13:53:11.719656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a541329f-da75-4637-8df7-e2ecf095debb', 'd9fd2ad4-98fd-4b7c-b6df-b70dcdfe2654', 'b', 'En la atmósfera, un aumento de la temperatura lleva asociada una disminución de la presión atmosférica.', true, '2025-09-13 13:53:11.721638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df916433-20ba-4a36-aa2f-b9eb80d69112', '41670fb2-9627-486e-a91b-4972295f97f9', 'a', 'Un farol que muestre una luz amarilla que permita diferenciar claramente que es una embarcación de remos.', false, '2025-09-13 13:53:11.707867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d243b29f-f0f0-46e4-8d17-9c495968aae0', 'd9fd2ad4-98fd-4b7c-b6df-b70dcdfe2654', 'c', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:11.721781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ed2e8be-f02a-4afa-bba0-7c7a04953e59', 'd9fd2ad4-98fd-4b7c-b6df-b70dcdfe2654', 'd', 'La escala Celsius permite expresar la temperatura en grados centígrados o grados Celsius.', false, '2025-09-13 13:53:11.721924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8c969c7-8dc2-455d-b074-96c4566126f9', '4cecb699-c940-41ac-a32a-8b4a072e800e', 'a', 'La presión atmosférica disminuye a medida que nos acercamos al centro del anticiclón provocando que el aire fluya hacia afuera de ellos.', false, '2025-09-13 13:53:11.722196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b783d66-0903-46ff-968d-0edf662ae333', '4cecb699-c940-41ac-a32a-8b4a072e800e', 'b', 'El proceso de formación de un anticiclón se denomina ciclogénesis.', false, '2025-09-13 13:53:11.722338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6167f465-78f2-4808-b2de-68f690227b89', '4cecb699-c940-41ac-a32a-8b4a072e800e', 'c', 'El aire desciende por el interior de los anticiclones.', true, '2025-09-13 13:53:11.722477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db4e2036-16a8-49be-bd93-25f3a3d222fb', '4cecb699-c940-41ac-a32a-8b4a072e800e', 'd', 'El movimiento de aire asociado produce formación de nubosidad y precipitaciones. Teoría de la navegación.', false, '2025-09-13 13:53:11.72261+00');
