INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad5c674f-90cb-45d4-b639-d893a2b73b1c', '7909c53b-7049-4f53-90db-d6f66138be29', 'd', '12,7º.', true, '2025-09-13 13:53:11.728132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5cf7281-6f17-40b2-8888-86b18dad4efa', '48980cf0-faf0-413a-b72f-0d43f5a531e9', 'a', '2º (+).', false, '2025-09-13 13:53:11.728422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8d745fa-ed39-474a-90b8-7f45f7eabbbb', '48980cf0-faf0-413a-b72f-0d43f5a531e9', 'b', '2º (-).', true, '2025-09-13 13:53:11.728555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('869736ab-63fc-46cc-a6d4-4a7e3b07859b', '48980cf0-faf0-413a-b72f-0d43f5a531e9', 'c', '168º (+).', false, '2025-09-13 13:53:11.728687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('664452d2-825e-443c-a302-884d4bdb8987', '48980cf0-faf0-413a-b72f-0d43f5a531e9', 'd', '167º (+). DE TRANSPORTES, MOVILIDAD                                                                          DE TRANSPORTES, MOVILIDAD Y AGENDA URBANA                                                                                    Y AGENDA URBANA DE TRANSPORTES Y MOVILIDAD Código de Test 02 (Con PNB Liberado) Maniobra y navegación.', false, '2025-09-13 13:53:11.72882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ecaa490-7cbc-437d-b9b5-ff70231e7488', '79d3be0a-1243-4421-996b-ddb6d881b5c3', 'a', 'Que, al no realizar giro alguno, la proa realizará movimientos excesivos a ambas bandas.', false, '2025-09-13 13:53:11.729231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('378f2e7f-81f7-41fb-8989-20df13b3ff78', '79d3be0a-1243-4421-996b-ddb6d881b5c3', 'b', 'Que, al no realizar giro alguno, la proa realizará movimientos mínimos a ambas bandas.', false, '2025-09-13 13:53:11.729361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5699e8f5-587d-4008-91e1-06db96ab0947', '79d3be0a-1243-4421-996b-ddb6d881b5c3', 'c', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo menor que el correspondiente a la trayectoria del punto giratorio.', false, '2025-09-13 13:53:11.729493+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc53b413-3961-43fa-959c-c72ff276b0f9', '79d3be0a-1243-4421-996b-ddb6d881b5c3', 'd', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo mayor que el correspondiente a la trayectoria del punto giratorio.', true, '2025-09-13 13:53:11.729632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf59acc5-e0ff-4466-b1a8-a465574c6a4e', '85919698-2b93-4159-948f-bc478f27df68', 'a', 'Largando amarras de proa y dando atrás toda a la par que largamos la del muerto.', false, '2025-09-13 13:53:11.729904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d36b5219-5fd5-4c51-81ea-39d2c9123ebb', '85919698-2b93-4159-948f-bc478f27df68', 'b', 'Largando amarras de proa, a continuación, la del muerto y después, dando atrás poca controlando el efecto de la hélice en la maniobra.', true, '2025-09-13 13:53:11.730035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('301ba241-c765-4fd1-928e-6a2b5480376e', '85919698-2b93-4159-948f-bc478f27df68', 'c', 'Dando atrás poca a la par que largamos todas las amarras menos el esprín de proa que nos ayudará a salir girando lentamente la embarcación.', false, '2025-09-13 13:53:11.730165+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7711055e-65a1-49c8-a220-28ecab7e5cc1', '85919698-2b93-4159-948f-bc478f27df68', 'd', 'Largando amarras de popa y dando avante poca a la par que largamos la del muerto. Emergencias en la mar.', false, '2025-09-13 13:53:11.730306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f10f3da-61d9-445f-8034-8e01afe12893', '2970461f-08e2-4fc7-8901-e3f886957e31', 'a', 'Para prevenir una vía de agua se debe, entre otras cosas, cerrar las válvulas que no se utilicen, asegurar la estanquidad de portillos y escotillas, fijar las baterías y todo el material pesado y evitar el agua en la sentina.', true, '2025-09-13 13:53:11.730579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3d1a3c5-9f8c-4e9a-9b88-fdaae353456f', '2970461f-08e2-4fc7-8901-e3f886957e31', 'b', 'Si falla una válvula o un pasa cascos, se taponará desde el interior con colchonetas, manteniendo apretado el cierre.', false, '2025-09-13 13:53:11.730712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c00e0b35-6fba-40d4-ac98-c3f75c61d156', '2970461f-08e2-4fc7-8901-e3f886957e31', 'd', 'Una embarcación medio hundida es peor lugar para esperar ayuda que una balsa, por lo que deberá pasar a esta en cuanto detecte una vía de agua a bordo.', false, '2025-09-13 13:53:11.730992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32d12946-9f08-45f3-b3e8-52f6c3bb34c4', '6c922068-9809-4808-bc72-285a59471791', 'a', 'Si no dispone de balsa salvavidas, salte al agua y nade para evitar los efectos de la hipotermia.', false, '2025-09-13 13:53:11.731278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0801572-b151-4d4c-aa2a-8641f51cc210', '6c922068-9809-4808-bc72-285a59471791', 'b', 'Encienda una bengala con el brazo alargado por fuera de cubierta a barlovento, posicionando la bengala vertical y alejada de otras personas.', false, '2025-09-13 13:53:11.731433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff91f191-899b-455a-8521-ab42fc124aab', '6c922068-9809-4808-bc72-285a59471791', 'd', 'Deberá ponerse el chaleco salvavidas y saltar al agua de cabeza, para evitar que con el impacto pueda perder el chaleco.', false, '2025-09-13 13:53:11.731778+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58389e07-c34a-49ce-9064-d257347ef1f7', '71cb8185-d413-4257-9435-33b73892ec4b', 'a', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con buen tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', true, '2025-09-13 13:53:11.732105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0290018-25ef-4a47-bc8c-e4aadaff9c04', '71cb8185-d413-4257-9435-33b73892ec4b', 'b', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con mal tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', false, '2025-09-13 13:53:11.732267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d15ba901-d6f2-4c90-838b-b0af18ec531c', '71cb8185-d413-4257-9435-33b73892ec4b', 'c', 'En caso de vía de agua en la flotación, se deberá escorar el barco lo necesario para que el orificio de entrada quede debajo del agua.', false, '2025-09-13 13:53:11.732421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89e02d55-33c1-40f8-bc52-0f88da25dcef', '71cb8185-d413-4257-9435-33b73892ec4b', 'd', 'No es necesario intercambiar ninguna información de las embarcaciones involucradas, ni comunicar a la compañía aseguradora los hechos acontecidos. Meteorología', false, '2025-09-13 13:53:11.732576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5a2cd42-c49c-45e3-bd2e-35c1362d5da6', '3b91b7ce-4a32-47fa-a783-d9f284121080', 'a', 'Informa del calor o energía térmica de una sustancia.', false, '2025-09-13 13:53:11.732912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('290794d0-bc84-43ef-976b-0fe18785b367', '3b91b7ce-4a32-47fa-a783-d9f284121080', 'c', 'Dos cuerpos en equilibrio térmico con un tercero están en equilibrio térmico entre sí.', false, '2025-09-13 13:53:11.733222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5508debe-0fd0-4bb6-87e8-502af2aa09f8', '3b91b7ce-4a32-47fa-a783-d9f284121080', 'd', 'La escala Celsius permite expresar la temperatura en grados centígrados o grados Celsius.', false, '2025-09-13 13:53:11.733374+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3a7d40d-221f-4b8f-8f4e-687e06c58ffa', 'a67a1178-d8fc-453d-a639-92030232fed3', 'a', 'Cambia de dirección.', true, '2025-09-13 13:53:11.733693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1176ec1-2656-4f11-ab5a-7cdc79ffc1e0', 'a67a1178-d8fc-453d-a639-92030232fed3', 'b', 'Ve disminuida su fuerza.', false, '2025-09-13 13:53:11.733866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c18b7f2c-fd81-49d3-b7a9-42e28f7b47b4', 'a67a1178-d8fc-453d-a639-92030232fed3', 'c', 'Ve aumentada su intensidad.', false, '2025-09-13 13:53:11.734006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ea5243b-00c5-46ab-ac80-8989929a05b5', 'a67a1178-d8fc-453d-a639-92030232fed3', 'd', 'Cesa, bien sea momentáneamente o por un periodo de tiempo más largo.', false, '2025-09-13 13:53:11.734162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a10cd9d-8e95-49de-a3fd-b55152bb4b01', '879e8f20-32b1-4daa-aaa0-ed99457b3a72', 'a', 'El número de horas que el viento sopla o ha soplado en la misma dirección.', true, '2025-09-13 13:53:11.734505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01d48bb3-f24a-474c-b986-128d898e0d5a', '879e8f20-32b1-4daa-aaa0-ed99457b3a72', 'b', 'La intensidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.734677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5602f59c-27af-463a-88c1-2c1d0c8a829e', '879e8f20-32b1-4daa-aaa0-ed99457b3a72', 'c', 'La velocidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.734842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32f8a093-c79a-4663-9a56-1399b0b453e7', '879e8f20-32b1-4daa-aaa0-ed99457b3a72', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes.', false, '2025-09-13 13:53:11.73501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2845d41b-282f-4371-b745-3cb0a05aa76a', '9fda1716-a299-4d1a-9f79-b9343ce8da3b', 'a', 'La presión atmosférica disminuye a medida que nos acercamos al centro del anticiclón provocando que el aire fluya hacia afuera de ellos.', false, '2025-09-13 13:53:11.735356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39913c0d-0d7c-4eac-b6f3-680294593494', '9fda1716-a299-4d1a-9f79-b9343ce8da3b', 'b', 'El proceso de formación de un anticiclón se denomina ciclogénesis.', false, '2025-09-13 13:53:11.735523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fa1898e-159a-4809-9327-3c0c3edc15fc', '9fda1716-a299-4d1a-9f79-b9343ce8da3b', 'c', 'El aire desciende por el interior de los anticiclones.', true, '2025-09-13 13:53:11.735684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25d8f521-bf0e-42c9-ad46-607180f6766c', '9fda1716-a299-4d1a-9f79-b9343ce8da3b', 'd', 'El movimiento de aire asociado produce formación de nubosidad y precipitaciones. Teoría de la navegación.', false, '2025-09-13 13:53:11.735854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0257cd8f-ed16-4ae8-b77f-ba835ab70c5f', '16872d96-f0e7-45e2-9c87-67b3e2ae99d3', 'a', 'El Instituto Superior de Investigaciones Científicas.', false, '2025-09-13 13:53:11.736147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbaa5e1f-1039-4c39-9510-3ab035a3af82', '16872d96-f0e7-45e2-9c87-67b3e2ae99d3', 'b', 'El Instituto Hidrográfico de la Marina.', true, '2025-09-13 13:53:11.736284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d747cd52-d2e8-49e9-ac00-b80913abcadf', '16872d96-f0e7-45e2-9c87-67b3e2ae99d3', 'c', 'El Instituto Social de la Marina.', false, '2025-09-13 13:53:11.736419+00');
