INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a4c96b5-a614-4c62-8f23-fe9e872231fb', 'bfe5fd5b-4b1b-41ac-8997-adcc6582b752', 'a', 'Solo puede expresarse en circulares, de 0° a 360°.', false, '2025-09-13 13:53:11.737496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a513b905-56fa-4221-8f40-c5c4c26b252d', 'bfe5fd5b-4b1b-41ac-8997-adcc6582b752', 'b', 'Se define como el ángulo que forma el Norte con la línea de la visual dirigida a ese punto.', false, '2025-09-13 13:53:11.737627+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f86686c5-ed00-4214-9b80-cc2429ae2a9c', 'bfe5fd5b-4b1b-41ac-8997-adcc6582b752', 'c', 'Es independiente del rumbo de nuestra embarcación.', false, '2025-09-13 13:53:11.737755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4dc9e48-bf61-4e5c-aa32-d2873ed5f0a3', 'bfe5fd5b-4b1b-41ac-8997-adcc6582b752', 'd', 'Es el ángulo formado por la línea proa-popa y la línea de la visual dirigida a dicho punto.', true, '2025-09-13 13:53:11.737908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd5239bf-62a6-4c6c-9665-589205b35b04', 'ba7b1e63-e764-40e0-8655-760712fd6557', 'a', 'La décima parte de un cable.', false, '2025-09-13 13:53:11.738249+00');
