INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a65d418-2fef-4f12-a695-9b45723b3fcb', 'ad6ff087-e05b-4329-8fd8-59559799232d', 'a', 'Que, al no realizar giro alguno, la proa realizará movimientos excesivos a ambas bandas.', false, '2025-09-13 13:53:11.742749+00');
