INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d42b2041-f67e-47f2-80eb-536ef0b830d3', '3b91b7ce-4a32-47fa-a783-d9f284121080', 'b', 'En la atmósfera, un aumento de la temperatura lleva asociada una disminución de la presión atmosférica.', true, '2025-09-13 13:53:11.733066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5db68665-07b3-4628-8d8a-2305e092653d', 'ad6ff087-e05b-4329-8fd8-59559799232d', 'b', 'Que, al no realizar giro alguno, la proa realizará movimientos mínimos a ambas bandas.', false, '2025-09-13 13:53:11.74289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfc7f11b-426d-4071-a9e7-2e3a8171e2c8', 'ad6ff087-e05b-4329-8fd8-59559799232d', 'c', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo menor que el correspondiente a la trayectoria del punto giratorio.', false, '2025-09-13 13:53:11.743051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52b468e2-15e1-4747-ab5b-2de41535f7f4', 'ad6ff087-e05b-4329-8fd8-59559799232d', 'd', 'Que, al efectuar un giro, el radio de curvatura de la trayectoria descrita por la popa es algo mayor que el correspondiente a la trayectoria del punto giratorio.', true, '2025-09-13 13:53:11.74318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63251917-9883-4265-94de-3a66932e9461', '00ddd29a-eb5e-460e-8f06-4a157c1d0735', 'a', 'Largando amarras de proa y dando atrás toda a la par que largamos la del muerto.', false, '2025-09-13 13:53:11.743474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42d84c91-c531-48ec-bcb8-29b786614a37', '00ddd29a-eb5e-460e-8f06-4a157c1d0735', 'b', 'Largando amarras de proa, a continuación, la del muerto y después, dando atrás poca controlando el efecto de la hélice en la maniobra.', true, '2025-09-13 13:53:11.743603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4838816-1439-4d59-ad39-69da88564b9a', '00ddd29a-eb5e-460e-8f06-4a157c1d0735', 'c', 'Dando atrás poca a la par que largamos todas las amarras menos el esprín de proa que nos ayudará a salir girando lentamente la embarcación.', false, '2025-09-13 13:53:11.743735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6425bb5a-0f56-45e4-bf09-a6675ed04943', '00ddd29a-eb5e-460e-8f06-4a157c1d0735', 'd', 'Largando amarras de popa y dando avante poca a la par que largamos la del muerto. Emergencias en la mar.', false, '2025-09-13 13:53:11.743867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc9a7d77-c77f-4549-b188-bda49f4c609d', 'c03706e8-28c1-423e-8ef1-4d8518fd884c', 'a', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con buen tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', true, '2025-09-13 13:53:11.744144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75fb52b7-607a-4ef7-8108-099563b50fd7', 'c03706e8-28c1-423e-8ef1-4d8518fd884c', 'b', 'Se realizará inmediatamente una evaluación rápida de los daños sufridos. Con mal tiempo se evitará despegar ambas embarcaciones hasta haber controlado la avería.', false, '2025-09-13 13:53:11.744276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08c88223-9a3a-429f-aca2-03dffc1b182e', 'c03706e8-28c1-423e-8ef1-4d8518fd884c', 'c', 'En caso de vía de agua en la flotación, se deberá escorar el barco lo necesario para que el orificio de entrada quede debajo del agua.', false, '2025-09-13 13:53:11.744405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d536d2af-b221-452f-acee-c1999b72d50e', 'c03706e8-28c1-423e-8ef1-4d8518fd884c', 'd', 'No es necesario intercambiar ninguna información de las embarcaciones involucradas, ni comunicar a la compañía aseguradora los hechos acontecidos.', false, '2025-09-13 13:53:11.744538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6adc9040-6e44-4eca-85f8-80cab11f5380', '2601cc35-06d7-4f91-ac22-b3be57699006', 'a', 'Si no dispone de balsa salvavidas, salte al agua y nade para evitar los efectos de la hipotermia.', false, '2025-09-13 13:53:11.744814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f75576b-e71f-413b-9563-b84bfeeef00a', '2601cc35-06d7-4f91-ac22-b3be57699006', 'b', 'Encienda una bengala con el brazo alargado por fuera de cubierta a barlovento, posicionando la bengala vertical y alejada de otras personas.', false, '2025-09-13 13:53:11.744948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('142d2360-c05b-4225-8d30-a6326b06e1d8', '2601cc35-06d7-4f91-ac22-b3be57699006', 'd', 'Deberá ponerse el chaleco salvavidas y saltar al agua de cabeza, para evitar que con el impacto pueda perder el chaleco.', false, '2025-09-13 13:53:11.74521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5facc1e0-c982-4a7c-a67b-5742ddd902cc', '3add61c7-de94-448a-a96e-dcf58109bb43', 'a', 'El número de horas que el viento sopla o ha soplado en la misma dirección.', true, '2025-09-13 13:53:11.746179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e07f588-7406-432a-b0f4-361b45aee1e4', '3add61c7-de94-448a-a96e-dcf58109bb43', 'b', 'La intensidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.746311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('157787f0-1749-4cd4-8520-3b72431ad7b8', '3add61c7-de94-448a-a96e-dcf58109bb43', 'c', 'La velocidad con la que sopla o ha soplado el viento.', false, '2025-09-13 13:53:11.746441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2a84b90-3b9f-4ccf-8328-e1fb84decf4b', '3add61c7-de94-448a-a96e-dcf58109bb43', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes.', false, '2025-09-13 13:53:11.746571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4423cc41-fb0e-4456-9d9b-1a332f3b0550', '747ac911-edb1-4f85-9f32-eeaaef276353', 'a', 'Cambia de dirección.', true, '2025-09-13 13:53:11.74685+00');
