INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12bbd702-dbae-4bdf-b738-afb6ecc5e1af', '747ac911-edb1-4f85-9f32-eeaaef276353', 'd', 'Cesa, bien sea momentáneamente o por un periodo de tiempo más largo.', false, '2025-09-13 13:53:11.74724+00');
