INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d8ee174-394d-478a-81ee-6244a8d1a3ee', '2c57c60e-1168-45b1-9714-53dfa12cd6e7', 'a', 'La presión atmosférica disminuye a medida que nos acercamos al centro del anticiclón provocando que el aire fluya hacia afuera de ellos.', false, '2025-09-13 13:53:11.748193+00');
