INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b3bd9e4-f7e9-4d3c-95a0-a1ed0364ada5', 'b1583ddc-5b0c-4a14-a2b8-a90d6eecc833', 'c', 'Un barco fondea a la gira cuando utiliza dos anclas por proa, cuyas líneas de fondeo forman un ángulo de entre 60º y 120º.', true, '2025-09-13 13:53:11.759465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d40259e-b3cc-48a9-af51-0b84ce66cd14', 'b1583ddc-5b0c-4a14-a2b8-a90d6eecc833', 'd', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear una segunda ancla o aguantar con máquina avante.', false, '2025-09-13 13:53:11.759595+00');
