INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('deff371b-ad33-4098-8211-6685e946d5b1', 'b31482db-f62f-4fac-8264-b6651c7ac42a', 'c', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, refrigeración, correa del alternador, nivel de combustible, agua dulce, baterías, luces de navegación, equipo de radio, que estén cerrados todos los grifos de fondo, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.762173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6ea5f88-c56d-4e61-a944-6551a47cb3a8', 'b31482db-f62f-4fac-8264-b6651c7ac42a', 'd', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, correa del alternador, climatización a bordo, nivel de combustible, agua dulce, baterías, equipo de radio, estanqueidad, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.762306+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c12cf452-9e60-4a8a-a09f-fad83dd40694', 'f00731b7-efad-4d17-86a0-8ec7c048b085', 'a', 'Sólo si el pabellón de estas es español.', false, '2025-09-13 13:53:11.762594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb729c90-ad31-4c68-99c8-4a4e4500cabf', 'f00731b7-efad-4d17-86a0-8ec7c048b085', 'b', 'Sólo si el pabellón de estas es extranjero, siempre que tengan entrada o salida en un puerto', false, '2025-09-13 13:53:11.762727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd24ae49-6dc4-4af1-91a0-9ad0c3778e22', 'f00731b7-efad-4d17-86a0-8ec7c048b085', 'c', 'Si el pabellón de estas es español o, si es extranjero, siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:11.762858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdcf79c8-6670-4d03-b9fa-ce417e39fbe3', 'f00731b7-efad-4d17-86a0-8ec7c048b085', 'd', 'Sólo si el pabellón de estas es español y siempre que tengan entrada o salida en un puerto extracomunitario.', false, '2025-09-13 13:53:11.762992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b416a3a8-ff25-45af-adca-7909115228de', '1c3f31cb-f843-41df-a664-4d5b04659190', 'a', 'Se comunicará inmediatamente a la estación costera de la zona geográfica. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', true, '2025-09-13 13:53:11.763272+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77159f0f-d724-4acd-888b-753683c04bc0', '1c3f31cb-f843-41df-a664-4d5b04659190', 'b', 'Se comunicará inmediatamente a las embarcaciones que se encuentren en la zona. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', false, '2025-09-13 13:53:11.763407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d236e01-3943-4c85-8f3b-98006f00e154', '1c3f31cb-f843-41df-a664-4d5b04659190', 'c', 'Se comunicará, una vez se encuentre la embarcación en puerto, a la Autoridad Portuaria, para que esta active los protocolos anticontaminación pertinentes.', false, '2025-09-13 13:53:11.763542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c196e476-e076-4ec7-8c2b-aeb39f0df36b', '1c3f31cb-f843-41df-a664-4d5b04659190', 'd', 'Se comunicará, antes de entrar en puerto, el siguiente mensaje: «vertidos o riesgo de vertidos de productos contaminantes en el mar», indicando la zona aproximada donde se produjo el', false, '2025-09-13 13:53:11.763674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7696afb6-0398-4a26-8a81-df62f0aca8c1', '8e4c2297-b997-468a-976f-134568eb9c14', 'a', 'Opuestos por sus bases.', true, '2025-09-13 13:53:11.76398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c59a56a9-e371-4c52-86d0-53125bafab86', '8e4c2297-b997-468a-976f-134568eb9c14', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:11.764121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91c7d591-102f-4499-8cf7-d4bccde747f9', '8e4c2297-b997-468a-976f-134568eb9c14', 'c', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.76426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7501c18d-6c9f-43ee-8ab5-841452edc704', '8e4c2297-b997-468a-976f-134568eb9c14', 'd', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.764394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ab6de30-10fd-478d-a25f-58d586c57577', '33ac1874-bdb0-43e2-9272-a24600b6f453', 'a', 'Únicamente se utilizan para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.764674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c7c0502-90f6-450b-9ce4-f5b9049c1c01', '33ac1874-bdb0-43e2-9272-a24600b6f453', 'b', 'Pueden indicar la presencia de cables o conductos submarinos.', true, '2025-09-13 13:53:11.76481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22738448-a191-45cc-ada8-c5b910e75f29', '33ac1874-bdb0-43e2-9272-a24600b6f453', 'c', 'Son las únicas destinadas a señalar obstrucciones.', false, '2025-09-13 13:53:11.764946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf7a60ae-182c-47cc-8f23-eaf8873a54ee', '33ac1874-bdb0-43e2-9272-a24600b6f453', 'd', 'Para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.765079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d01261d4-da11-4985-b6bc-7333103db6de', '5448145c-f80b-40eb-a1a3-3109d6c439b1', 'a', 'Es blanca y tiene un ritmo de isofase de ocultaciones, 1 destello largo cada 10 segundos.', true, '2025-09-13 13:53:11.765354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd881fef-43ad-4ae3-9643-465c7ea97a79', '5448145c-f80b-40eb-a1a3-3109d6c439b1', 'b', 'Es blanca y su ritmo es un grupo de 2 destellos (GpD2).', false, '2025-09-13 13:53:11.765489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31e9cc50-8640-4744-acfa-32c0685403ad', '5448145c-f80b-40eb-a1a3-3109d6c439b1', 'c', 'Las Marcas de aguas navegables en ningún caso están provistas de luz alguna.', false, '2025-09-13 13:53:11.765622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8ba2cb6-712b-46db-9e31-99e643f65091', '5448145c-f80b-40eb-a1a3-3109d6c439b1', 'd', 'Es blanca y tiene un ritmo que se puede confundir con el ritmo de centelleos muy rápidos o rápidos de las Marcas cardinales.', false, '2025-09-13 13:53:11.765769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8827406b-fa31-4d5c-9d2a-ba8ef4fabb58', '059f2261-d903-45e9-a2ae-e55d20587cec', 'a', 'Rojo y blanco.', false, '2025-09-13 13:53:11.766041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46b6b2ae-b599-4686-b578-a9c15843fc59', '059f2261-d903-45e9-a2ae-e55d20587cec', 'b', 'Amarillo.', false, '2025-09-13 13:53:11.766182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79f39e5c-69dc-4a78-9765-b8cd0837157c', '059f2261-d903-45e9-a2ae-e55d20587cec', 'c', 'Azul con franjas verticales amarillas.', false, '2025-09-13 13:53:11.766315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed1f8013-e379-45ef-af1e-315e30d4aab7', '059f2261-d903-45e9-a2ae-e55d20587cec', 'd', 'Negro con una o varias anchas bandas horizontales rojas.', true, '2025-09-13 13:53:11.76645+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01184791-70e5-4ee8-b98b-5e85841f6ade', '63522961-a5a9-42f8-8c8a-740c7f76323c', 'a', 'Números pares para las verdes, números impares para las rojas.', false, '2025-09-13 13:53:11.766732+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfd4a749-e3a8-44fb-8a92-62c222a9062e', '63522961-a5a9-42f8-8c8a-740c7f76323c', 'b', 'Números pares para las rojas, números impares para las blancas.', false, '2025-09-13 13:53:11.766865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed73c666-4c55-4c56-b7e0-57b98d168e35', '63522961-a5a9-42f8-8c8a-740c7f76323c', 'c', 'Números pares para las verdes, números impares para las blancas.', false, '2025-09-13 13:53:11.766996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d91c69e-87d7-4dcd-8432-0f7341e23ead', '63522961-a5a9-42f8-8c8a-740c7f76323c', 'd', 'Números pares para las rojas, números impares para las verdes. Reglamento (RIPA).', true, '2025-09-13 13:53:11.767125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45ef77e6-cb87-4ad9-ba70-19f226158e29', '0fc6f482-9122-4c03-8f31-9c38e289ee47', 'a', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.767408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('559dd431-c0bf-4741-9803-1c58dc227bc6', '0fc6f482-9122-4c03-8f31-9c38e289ee47', 'b', 'Un buque pesquero que no se encuentre realizando en ese momento tareas de pesca.', false, '2025-09-13 13:53:11.767569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb62191f-51df-4e0a-8acf-f265197675d4', '0fc6f482-9122-4c03-8f31-9c38e289ee47', 'c', 'Un buque de propulsión mecánica.', false, '2025-09-13 13:53:11.767725+00');
