INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('318f5371-d191-4bb1-8028-88e099b8e571', '2b748ed7-d603-41cb-83ed-feb50e4387bb', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:11.768307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68a22485-8736-46ed-8500-5e6042f1f9aa', '2b748ed7-d603-41cb-83ed-feb50e4387bb', 'c', 'Una luz verde de centelleos todo horizonte.', false, '2025-09-13 13:53:11.768443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25916101-2283-4e9a-b964-8326737f0df1', '2b748ed7-d603-41cb-83ed-feb50e4387bb', 'd', 'Una segunda luz de alcance.', false, '2025-09-13 13:53:11.768583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b8288aa-6b2d-487a-be9e-21366ef59363', '71d2ed9c-a6e5-4097-be58-d8440e041fbf', 'a', 'Un farol que muestre una luz amarilla que permita diferenciar claramente que es una embarcación', false, '2025-09-13 13:53:11.768861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2eaded9-c43b-47c0-b0f9-f1d52365c6db', '71d2ed9c-a6e5-4097-be58-d8440e041fbf', 'b', 'Una marca cónica con el vértice hacia abajo.', false, '2025-09-13 13:53:11.768998+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c648aabc-31f1-493d-83f4-80ff2c3868a5', '71d2ed9c-a6e5-4097-be58-d8440e041fbf', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:11.769128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f24c316b-5b47-49ce-ad9b-7439b0568b8c', '71d2ed9c-a6e5-4097-be58-d8440e041fbf', 'd', 'Una linterna eléctrica que muestre una luz blanca.', true, '2025-09-13 13:53:11.769259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ac36386-e014-4daf-bb6d-a8517f488ef4', 'f2f852c4-37d7-4016-99f2-7447481732cf', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', true, '2025-09-13 13:53:11.769527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e27a046c-1b03-40dd-8904-d62d6c9ccff1', 'f2f852c4-37d7-4016-99f2-7447481732cf', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.76966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9126f630-e281-4cd3-8105-4450adc1b92d', 'f2f852c4-37d7-4016-99f2-7447481732cf', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:11.769792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e0d20d-fad8-4961-9af0-2502e44b0973', 'f2f852c4-37d7-4016-99f2-7447481732cf', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.769926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5e3cce7-0c33-4b85-8f89-d2209237e7ed', 'f143e62a-7602-4927-97dd-97ffeed26854', 'a', 'Reciba el viento por estribor.', false, '2025-09-13 13:53:11.770199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b338982-28db-4866-b136-f61a641a9b63', 'f143e62a-7602-4927-97dd-97ffeed26854', 'b', 'Reciba el viento por popa.', false, '2025-09-13 13:53:11.770333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('170a6c47-eb64-44f2-8d8f-513449831cd0', 'f143e62a-7602-4927-97dd-97ffeed26854', 'c', 'Reciba el viento por babor.', true, '2025-09-13 13:53:11.77046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba30a60b-cb14-4048-b761-64b3f54eefa6', 'f143e62a-7602-4927-97dd-97ffeed26854', 'd', 'Esté a sotavento cuando ambos reciban el viento por la misma banda.', false, '2025-09-13 13:53:11.770589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3cf4fa5-0a05-4eda-9682-a78d9c8fc9f9', '5796c7d9-bb45-4165-a56a-e4a199a6d10a', 'a', 'Un buque restringido por su calado.', false, '2025-09-13 13:53:11.770857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('828f7c22-fc67-4a30-b1db-2044d46832eb', '5796c7d9-bb45-4165-a56a-e4a199a6d10a', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:11.770987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d0661c3-4955-45e6-9738-8348a163c68f', '5796c7d9-bb45-4165-a56a-e4a199a6d10a', 'c', 'Un buque de vela exhibiendo una marca cónica con el vértice hacia abajo de eslora igual a 25', false, '2025-09-13 13:53:11.771115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('375473e7-d546-4a1c-9bb7-000e93046fa5', 'c5364466-5384-41af-b6a8-2e3955c7bec8', 'c', 'Filar la cadena del ancla.', true, '2025-09-13 13:53:12.025078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ffc2b74-853d-4340-870c-76e509c7d0ea', '5796c7d9-bb45-4165-a56a-e4a199a6d10a', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.771243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98150bc8-0dca-4e89-a5e5-40b457532b56', 'f69acbf4-e24d-45cd-a43e-b3fb7975d6fd', 'a', 'La expresión “buque con capacidad de maniobra restringida” incluirá los buques dedicados al lanzamiento o recuperación de aeronaves.', true, '2025-09-13 13:53:11.771523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1393b79-0ddc-4769-8263-e572cd9a2817', 'f69acbf4-e24d-45cd-a43e-b3fb7975d6fd', 'b', 'La expresión “buque sin gobierno” significa todo buque que maniobre sin capitán.', false, '2025-09-13 13:53:11.771659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25dd5a33-8dbb-4940-94d1-16a446cd0ca5', 'f69acbf4-e24d-45cd-a43e-b3fb7975d6fd', 'c', 'La expresión “buque dedicado a la pesca” significa todo buque que pesque con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:11.771803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dc4d0e1-844d-4ac8-ad7b-a5377a467083', 'f69acbf4-e24d-45cd-a43e-b3fb7975d6fd', 'd', 'La expresión “buque con capacidad de maniobra restringida” significa todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, puede apartarse de la derrota de otro buque.', false, '2025-09-13 13:53:11.771962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('583f6413-56d5-47a0-af11-ff66f316ca6f', 'b48f1391-0802-44dc-bce3-325c6c5fe9d9', 'a', 'Al no tratarse de una nave proyectada para maniobrar sobre las aguas, no tiene que exhibir las luces con las características prescritas en el RIPA, por lo que no deberemos atender a las señales exhibidas por desconocer su intención.', false, '2025-09-13 13:53:11.772247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa69911e-a5aa-47fd-a941-549679e10400', 'b48f1391-0802-44dc-bce3-325c6c5fe9d9', 'b', 'Exhibe luces destinadas al tráfico aéreo y estaremos obligados a consultar el Reglamento del aire para interpretar sus indicaciones.', false, '2025-09-13 13:53:11.772381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fd9afdb-1afa-4309-bcd8-0a3b11844ada', 'b48f1391-0802-44dc-bce3-325c6c5fe9d9', 'c', 'Exhibe luces destinadas al tráfico aéreo y no deberemos atender a las señales exhibidas en ningún', false, '2025-09-13 13:53:11.772513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('227fee8e-b9cf-4be2-a68e-57957418b2cb', 'b48f1391-0802-44dc-bce3-325c6c5fe9d9', 'd', 'No le es posible exhibir las luces con las características prescritas y deberemos atender a las señales exhibidas como si se tratara de las luces reglamentariamente establecidas.', true, '2025-09-13 13:53:11.772646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('655d6fc1-f5a3-4aba-853b-d42ea9214522', 'f6ac1200-e78e-4f98-be80-8dbd2b9d83d1', 'a', 'No tendrán obligación de llevar ningún medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:11.772952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f7dfb46-3798-4f03-a33c-5fb16c2d8598', 'f6ac1200-e78e-4f98-be80-8dbd2b9d83d1', 'b', 'No tendrán obligación de llevar ninguno de los dispositivos de señales acústicas prescritos para buques de eslora igual o superior a 12 metros, siempre que vayan dotados de otros medios para hacer señales acústicas eficaces.', true, '2025-09-13 13:53:11.773088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('546d315c-b728-4f28-b4a4-d54a9674604d', 'f6ac1200-e78e-4f98-be80-8dbd2b9d83d1', 'c', 'No tendrán obligación de llevar ningún dispositivo de señales acústicas siempre que vayan dotados de otros medios para hacer señales visuales eficaces.', false, '2025-09-13 13:53:11.773229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b8b07ca-d838-4c31-973b-a203e9d28e0b', 'f6ac1200-e78e-4f98-be80-8dbd2b9d83d1', 'd', 'Tendrán obligación de ir dotados de un pito, en cualquier caso.', false, '2025-09-13 13:53:11.773369+00');
