INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da1540d7-3808-4489-aad7-06915a8de16a', '6c9a5700-8e6e-46df-8895-49c1f1c336e2', 'a', 'Espacio, generalmente cerrado, situado por debajo del nivel del plan.', false, '2025-09-13 13:53:11.774507+00');
