INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa3bff6d-3ec7-45a9-9a6e-4585ac3168b2', '57041101-395c-4e91-8634-ea95427f26c4', 'a', 'Formar una gaza que no sea corrediza y así poder encapillar un cabo.', false, '2025-09-13 13:53:11.777307+00');
