INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22b7846d-c423-4931-b89d-b900c75c33ba', '441fc86d-2743-4a72-8b41-b5403d522e86', 'a', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:11.778003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e8f39da-2ebe-43a7-b193-b85662bfe3d8', '441fc86d-2743-4a72-8b41-b5403d522e86', 'b', 'El círculo de borneo tiene como centro el ancla y como radio, la longitud de cadena filada más la eslora de la embarcación.', false, '2025-09-13 13:53:11.778134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('844cf99a-f137-4239-b28b-45a02b5fdb30', '441fc86d-2743-4a72-8b41-b5403d522e86', 'c', 'Un barco fondea a la gira cuando utiliza dos anclas por proa, cuyas líneas de fondeo forman un ángulo de entre 60º y 120º.', true, '2025-09-13 13:53:11.778263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06e493ed-8597-4c00-98e2-53743d6e6e3c', '441fc86d-2743-4a72-8b41-b5403d522e86', 'd', 'Para evitar el garreo de un ancla se puede, entre otras opciones, filar más cadena, cambiar el tenedero, fondear una segunda ancla o aguantar con máquina avante.', false, '2025-09-13 13:53:11.778392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('402d281b-049c-4faf-9278-6642838fcce4', '4162a444-22c6-4a8b-a994-fa78c10c29ad', 'a', 'Parar máquinas.', false, '2025-09-13 13:53:11.778665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('032e1ffe-eec4-43e9-8e7f-f8e1ad578ba4', '4162a444-22c6-4a8b-a994-fa78c10c29ad', 'b', 'Poner la popa o aleta a la mar.', true, '2025-09-13 13:53:11.778796+00');
