INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50ef1451-f2fc-4750-bf68-91c119a8abb5', '9e47419e-4cdc-4e3e-838b-82c8f9a667e5', 'd', 'Niveles de aceite, filtros decantación de agua e impurezas, líquido refrigerante, correa del alternador, climatización a bordo, nivel de combustible, agua dulce, baterías, equipo de radio, estanqueidad, sistema de gobierno y propulsión, ausencia de gases explosivos, fugas de aceite o combustible, parte meteorológico, existencia y estado de elemento de seguridad.', false, '2025-09-13 13:53:11.781142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b825be6e-6212-4356-9876-5712e371878f', 'cf6aa9ba-cb68-4199-9b68-2475d3c8552d', 'a', 'Se comunicará inmediatamente a la estación costera de la zona geográfica. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', true, '2025-09-13 13:53:11.781428+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec39135d-64a3-46e7-b663-fb88e8053737', 'cf6aa9ba-cb68-4199-9b68-2475d3c8552d', 'b', 'Se comunicará inmediatamente a las embarcaciones que se encuentren en la zona. El mensaje de aviso deberá incluir la información pertinente mencionada en la Resolución A.851 (20) de la OMI.', false, '2025-09-13 13:53:11.781561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88a15403-f648-42b4-a19f-e3828a522c96', 'cf6aa9ba-cb68-4199-9b68-2475d3c8552d', 'c', 'Se comunicará, una vez se encuentre la embarcación en puerto, a la Autoridad Portuaria, para que esta active los protocolos anticontaminación pertinentes.', false, '2025-09-13 13:53:11.781694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8ca6e40-3f72-4cb5-baa3-ddb8de8eff2c', 'cf6aa9ba-cb68-4199-9b68-2475d3c8552d', 'd', 'Se comunicará, antes de entrar en puerto, el siguiente mensaje: «vertidos o riesgo de vertidos de productos contaminantes en el mar», indicando la zona aproximada donde se produjo el', false, '2025-09-13 13:53:11.781825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f1d386c-c922-4545-baef-b94211ae75e1', '33889d9c-3cef-455b-bbde-47f182612c98', 'a', 'Sólo si el pabellón de estas es español.', false, '2025-09-13 13:53:11.782102+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99171d70-8804-49d4-96c4-2b047a06f859', '33889d9c-3cef-455b-bbde-47f182612c98', 'b', 'Sólo si el pabellón de estas es extranjero, siempre que tengan entrada o salida en un puerto', false, '2025-09-13 13:53:11.782233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e980bc09-5972-4ffa-9d95-5f4d8dd99e9a', '33889d9c-3cef-455b-bbde-47f182612c98', 'c', 'Si el pabellón de estas es español o, si es extranjero, siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:11.782362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('415bf905-d566-42b7-a27c-056f7a95662f', '33889d9c-3cef-455b-bbde-47f182612c98', 'd', 'Sólo si el pabellón de estas es español y siempre que tengan entrada o salida en un puerto extracomunitario.', false, '2025-09-13 13:53:11.782492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7acfa13-a397-499e-9f1b-4f08bedad22e', '7a395a60-e4f1-475c-b6bf-c5be3d1c284a', 'a', 'Es blanca y tiene un ritmo de isofase de ocultaciones, 1 destello largo cada 10 segundos.', true, '2025-09-13 13:53:11.78277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5c3eae7-0489-4e32-b03a-605282be20e7', '7a395a60-e4f1-475c-b6bf-c5be3d1c284a', 'b', 'Es blanca y su ritmo es un grupo de 2 destellos (GpD2).', false, '2025-09-13 13:53:11.782902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97a9cf18-6d20-4c6c-968b-c8cfbb79b32a', '7a395a60-e4f1-475c-b6bf-c5be3d1c284a', 'c', 'Las Marcas de aguas navegables en ningún caso están provistas de luz alguna.', false, '2025-09-13 13:53:11.783031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbbe35ea-2e0e-416a-8c0b-f8e6ed79f8e3', '7a395a60-e4f1-475c-b6bf-c5be3d1c284a', 'd', 'Es blanca y tiene un ritmo que se puede confundir con el ritmo de centelleos muy rápidos o rápidos de las Marcas cardinales.', false, '2025-09-13 13:53:11.783159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('820bb8e5-fe00-4f85-bc37-64d75428d723', '1c701211-78a1-4029-8ecf-b0f48b1977fd', 'a', 'Opuestos por sus bases.', false, '2025-09-13 13:53:11.783427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ecc2a6a-e293-4916-8207-4446d98092bb', '1c701211-78a1-4029-8ecf-b0f48b1977fd', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:11.78356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a1d602c-1aac-41a3-9610-0509a7bae75a', '1c701211-78a1-4029-8ecf-b0f48b1977fd', 'c', 'Opuestos por sus vértices.', true, '2025-09-13 13:53:11.783689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e2d9d7e-4c9d-48b5-9147-98ba3aff6d51', '1c701211-78a1-4029-8ecf-b0f48b1977fd', 'd', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:11.783836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e67f6fe6-3a1f-4729-b4e8-2cc35ec0f074', '83480551-f408-4d42-b75b-d012c80e9fef', 'a', 'Números pares para las verdes, números impares para las rojas.', false, '2025-09-13 13:53:11.784124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a7c044d-74f5-4fb4-b6c7-90af673b8a58', '83480551-f408-4d42-b75b-d012c80e9fef', 'b', 'Números pares para las rojas, números impares para las blancas.', false, '2025-09-13 13:53:11.784255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ecdbcd3-2b21-4636-8bf0-73265f89be17', '83480551-f408-4d42-b75b-d012c80e9fef', 'c', 'Números pares para las verdes, números impares para las blancas.', false, '2025-09-13 13:53:11.784383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c556b901-00d3-434d-a63d-983f3be9b386', '83480551-f408-4d42-b75b-d012c80e9fef', 'd', 'Números pares para las rojas, números impares para las verdes.', true, '2025-09-13 13:53:11.784511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0528dab-f3d6-4714-b172-5f1816aab70e', '8ec396be-35c5-459c-912b-8cbf2944fb52', 'a', 'Únicamente se utilizan para indicar los límites de un área de fondeo.', false, '2025-09-13 13:53:11.784799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90247a02-68f9-4c27-9e86-b3d34a633b14', '8ec396be-35c5-459c-912b-8cbf2944fb52', 'b', 'Pueden indicar la presencia de cables o conductos submarinos.', true, '2025-09-13 13:53:11.784928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('358ecff7-412e-432a-9969-4bb20bfe9ed1', '8ec396be-35c5-459c-912b-8cbf2944fb52', 'c', 'Son las únicas destinadas a señalar obstrucciones.', false, '2025-09-13 13:53:11.785056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c6a140a-8baf-4235-bd61-702fc665fb22', '8ec396be-35c5-459c-912b-8cbf2944fb52', 'd', 'Para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.78519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61417d23-7bab-4dac-b0e2-5a06dbb1c06a', '21e08a19-1725-4139-a0db-faeb8b5a7e06', 'a', 'Rojo y blanco.', false, '2025-09-13 13:53:11.78547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12ca335d-08af-478a-9ec8-9dd49d4952ca', '21e08a19-1725-4139-a0db-faeb8b5a7e06', 'b', 'Amarillo.', false, '2025-09-13 13:53:11.785601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22440eec-092c-442f-a6b7-9f82782b2768', '21e08a19-1725-4139-a0db-faeb8b5a7e06', 'c', 'Azul con franjas verticales amarillas.', false, '2025-09-13 13:53:11.78573+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c579f595-4170-4d0d-9709-43fb149e5439', '21e08a19-1725-4139-a0db-faeb8b5a7e06', 'd', 'Negro con una o varias anchas bandas horizontales rojas. Reglamento (RIPA).', true, '2025-09-13 13:53:11.785861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b146b593-82f2-4c04-bdb7-0b261be71c70', '74d084d8-8d9b-486f-9fad-b7faa7524311', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', true, '2025-09-13 13:53:11.786136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c612ae93-bf18-40b5-b4f2-d4a5e2488c99', '74d084d8-8d9b-486f-9fad-b7faa7524311', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.786267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('850f174a-60e0-428a-b3c5-98a9106a77e4', '74d084d8-8d9b-486f-9fad-b7faa7524311', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:11.786396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a61d6d1-4da4-4a83-ba1d-dc1bf61fb97f', '74d084d8-8d9b-486f-9fad-b7faa7524311', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.786524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5328e063-42b9-44c7-beae-cface51000fa', 'f101289e-9bfb-4dcc-91ac-7c8daf899dda', 'a', 'No tendrán obligación de llevar ningún medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:11.786799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a7c2e80-dc91-4e54-a61c-9dba1f67b701', 'f101289e-9bfb-4dcc-91ac-7c8daf899dda', 'b', 'No tendrán obligación de llevar ninguno de los dispositivos de señales acústicas prescritos para buques de eslora igual o superior a 12 metros, siempre que vayan dotados de otros medios para hacer señales acústicas eficaces.', true, '2025-09-13 13:53:11.786929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5cbf874-5eea-4314-8823-f96771f91d87', 'f101289e-9bfb-4dcc-91ac-7c8daf899dda', 'c', 'No tendrán obligación de llevar ningún dispositivo de señales acústicas siempre que vayan dotados de otros medios para hacer señales visuales eficaces.', false, '2025-09-13 13:53:11.78706+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4fd1f30-67b3-43d1-8c10-e94b4818036b', 'f101289e-9bfb-4dcc-91ac-7c8daf899dda', 'd', 'Tendrán obligación de ir dotados de un pito, en cualquier caso.', false, '2025-09-13 13:53:11.787187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0d62a44-bb87-4f15-80cc-28d63bbfd2a3', 'c5364466-5384-41af-b6a8-2e3955c7bec8', 'd', 'Dejar clara el ancla.', false, '2025-09-13 13:53:12.025214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8efd60f-b5e7-4028-a029-47d2c7d600ad', '48098078-036d-4b4c-9282-44722a81aa7b', 'a', 'Al no tratarse de una nave proyectada para maniobrar sobre las aguas, no tiene que exhibir las luces con las características prescritas en el RIPA, por lo que no deberemos atender a las señales exhibidas por desconocer su intención.', false, '2025-09-13 13:53:11.787458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc6338b4-7335-4ba1-ab29-36649dac5181', '48098078-036d-4b4c-9282-44722a81aa7b', 'b', 'Exhibe luces destinadas al tráfico aéreo y estaremos obligados a consultar el Reglamento del aire para interpretar sus indicaciones.', false, '2025-09-13 13:53:11.787593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('268d8540-4f78-4d95-8951-c23b4dd07582', '48098078-036d-4b4c-9282-44722a81aa7b', 'c', 'Exhibe luces destinadas al tráfico aéreo y no deberemos atender a las señales exhibidas en ningún', false, '2025-09-13 13:53:11.787721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4537632e-2431-4df6-b2cc-822b111b4d2d', '48098078-036d-4b4c-9282-44722a81aa7b', 'd', 'No le es posible exhibir las luces con las características prescritas y deberemos atender a las señales exhibidas como si se tratara de las luces reglamentariamente establecidas.', true, '2025-09-13 13:53:11.787881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daaaec0e-1252-4307-9c30-0ba758cfb44d', '6a1b7f66-f438-428f-bdf9-e1ad31c5246c', 'a', 'Un buque restringido por su calado.', false, '2025-09-13 13:53:11.788172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42d9a754-f3c3-4a84-b9c6-99f41ca85a42', '6a1b7f66-f438-428f-bdf9-e1ad31c5246c', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:11.788301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eec9d58-df02-4d9e-8b04-6aa5761ecf44', '6a1b7f66-f438-428f-bdf9-e1ad31c5246c', 'c', 'Un buque de vela exhibiendo una marca cónica con el vértice hacia abajo de eslora igual a 25', false, '2025-09-13 13:53:11.788429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44d60f53-5c48-4298-aefa-50410dab1fba', '6a1b7f66-f438-428f-bdf9-e1ad31c5246c', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.788557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bccd0d0-0f43-4ae3-bad1-f0ed7f40d7f3', '44bf8045-2394-4afb-a2d5-4cf1d5a05d35', 'a', 'Un cohete-bengala con paracaídas que produzca una luz roja.', true, '2025-09-13 13:53:11.788826+00');
