INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1481ad9e-ed83-4e0e-ae3d-007355c5de27', 'd1289c58-edfd-4daa-bf5d-7c17266fd723', 'd', 'Una segunda luz de alcance.', false, '2025-09-13 13:53:11.789919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ae2e426-4144-473f-ace7-6f113e83bd45', 'bf1e74b0-b55b-4639-8ec1-546cd458f710', 'a', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.79019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80c74aed-8857-4741-8890-93858572bb03', 'bf1e74b0-b55b-4639-8ec1-546cd458f710', 'b', 'Un buque pesquero que no se encuentre realizando en ese momento tareas de pesca.', false, '2025-09-13 13:53:11.790318+00');
