INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3300559a-1add-427d-9e6c-d68135b6d20b', 'bf1e74b0-b55b-4639-8ec1-546cd458f710', 'd', 'Todos los buques que tenga a la vista.', false, '2025-09-13 13:53:11.790581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2de2f35c-aaf1-4a4b-953a-eaef0c6a2798', '86618248-2ca3-431b-bfd2-cfadde4f11fd', 'a', 'Reciba el viento por estribor.', false, '2025-09-13 13:53:11.790866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4290c5db-dc55-45f1-8d24-df39f6a33d36', '86618248-2ca3-431b-bfd2-cfadde4f11fd', 'b', 'Reciba el viento por popa.', false, '2025-09-13 13:53:11.790995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a44af07-cc7d-40cc-a274-d237b8f0bf34', '86618248-2ca3-431b-bfd2-cfadde4f11fd', 'c', 'Reciba el viento por babor.', true, '2025-09-13 13:53:11.791147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49bc8f4c-d510-49c7-a7c6-cd7424090fe8', '86618248-2ca3-431b-bfd2-cfadde4f11fd', 'd', 'Esté a sotavento cuando ambos reciban el viento por la misma banda.', false, '2025-09-13 13:53:11.791275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a1eaaac-e3e0-4b36-b5af-07ddc3b07927', '4415273d-83d8-4faf-bd22-fe9188c9c3d0', 'a', 'Un farol que muestre una luz amarilla que permita diferenciar claramente que es una embarcación', false, '2025-09-13 13:53:11.791545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f7d7dd3-8910-4ed8-a301-e9c10bb39ef1', '4415273d-83d8-4faf-bd22-fe9188c9c3d0', 'b', 'Una marca cónica con el vértice hacia abajo.', false, '2025-09-13 13:53:11.791673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42252c2f-17b5-408d-8d0c-75439d8b8d35', '4415273d-83d8-4faf-bd22-fe9188c9c3d0', 'c', 'Una marca cónica con el vértice hacia arriba.', false, '2025-09-13 13:53:11.791813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5686fa1-6e1b-4876-9c9f-ce049b6e878d', '4415273d-83d8-4faf-bd22-fe9188c9c3d0', 'd', 'Una linterna eléctrica que muestre una luz blanca.', true, '2025-09-13 13:53:11.791941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a01e9fce-8f76-4953-909c-f11ff1d839e9', 'd6356840-91d8-49f8-8f7a-b6d38a9ecd75', 'a', 'La expresión “buque con capacidad de maniobra restringida” incluirá los buques dedicados al lanzamiento o recuperación de aeronaves.', true, '2025-09-13 13:53:11.792209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ce8cad6-505a-4c0e-b375-a014079b1ec3', 'd6356840-91d8-49f8-8f7a-b6d38a9ecd75', 'b', 'La expresión “buque sin gobierno” significa todo buque que maniobre sin capitán.', false, '2025-09-13 13:53:11.792339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df254a39-f334-4435-a91a-8571cd4fbdd0', 'd6356840-91d8-49f8-8f7a-b6d38a9ecd75', 'c', 'La expresión “buque dedicado a la pesca” significa todo buque que pesque con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:11.79247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef183094-538d-468f-af00-e30c84b6dead', 'd6356840-91d8-49f8-8f7a-b6d38a9ecd75', 'd', 'La expresión “buque con capacidad de maniobra restringida” significa todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad para maniobrar en la forma exigida por este Reglamento y, por consiguiente, puede apartarse de la derrota de otro buque.', false, '2025-09-13 13:53:11.792599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b3a0279-d573-480f-bdd6-6fb212da518c', '17b85c8b-b705-460d-929c-4879246241f6', 'a', 'Cabos utilizados para amarrar la embarcación por proa.', false, '2025-09-13 13:53:11.793003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f7ef0c8-6fb5-4056-930f-64dbeb6fbcc3', '17b85c8b-b705-460d-929c-4879246241f6', 'b', 'Condensación de vapor de agua en las superficies.', false, '2025-09-13 13:53:11.793132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a99e5c6-440d-4256-8b81-c85914230eca', '17b85c8b-b705-460d-929c-4879246241f6', 'c', 'Elementos de madera que suelen colocarse cerca de la proa para poder sujetarse al desplazarse sobre cubierta.', false, '2025-09-13 13:53:11.793259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a298083b-76f0-4bdb-abbd-cc8a9f50c4fe', '17b85c8b-b705-460d-929c-4879246241f6', 'd', 'Cada uno de los elementos estructurales que atraviesan el barco de babor a estribor y que sirven para aguantar los costados y sostener las cubiertas.', true, '2025-09-13 13:53:11.793392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ae42f6d-ab1d-4b8f-b576-0efc98c5c3f1', 'd3eafc48-5f06-42ed-8198-3a78dbf3d109', 'a', 'La abertura practicada en el fondo del casco para el paso de la mecha del timón.', false, '2025-09-13 13:53:11.793663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f27449ab-2314-4c8a-aa87-2cfc282ba64e', 'd3eafc48-5f06-42ed-8198-3a78dbf3d109', 'b', 'La abertura en la cubierta de un buque, con tapa de cristal que permite la entrada de luz.', false, '2025-09-13 13:53:11.793815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f25d6052-3dd8-4647-a7eb-ae86be2e226a', 'd3eafc48-5f06-42ed-8198-3a78dbf3d109', 'c', 'El orificio practicado en algún miembro estructural para permitir el paso del agua.', true, '2025-09-13 13:53:11.793949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65df0f98-afab-4b6b-9b98-226418e807b0', 'd3eafc48-5f06-42ed-8198-3a78dbf3d109', 'd', 'El conducto que permite que el eje de la hélice gire a través del casco sin que entre agua.', false, '2025-09-13 13:53:11.794081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f964d659-b4af-4508-a4f9-1b258cb6ce13', '88e11408-6e33-405a-9158-713ce495be83', 'a', 'El eje del timón y vincula la caña con la pala.', true, '2025-09-13 13:53:11.794358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8568af30-fd35-4599-a125-cc1a1a4480a6', '88e11408-6e33-405a-9158-713ce495be83', 'b', 'La parte unida a la cabeza del timón y con la cual se maneja.', false, '2025-09-13 13:53:11.794497+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('024454ac-9637-46e8-bfa7-a8b533048f21', '88e11408-6e33-405a-9158-713ce495be83', 'c', 'La abertura en la bovedilla de popa, para el paso de la cabeza del timón.', false, '2025-09-13 13:53:11.794633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0df0dda-b308-4357-8d05-d1bc208a7fa0', '88e11408-6e33-405a-9158-713ce495be83', 'd', 'El madero grueso puesto verticalmente sobre el extremo del timón, que sirve de fundamento a toda la armazón de esta parte del buque.', false, '2025-09-13 13:53:11.794766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb1f83ca-5cb8-41a0-b79c-6e021d4c0705', 'cfdce7e2-4f77-48f3-aa29-0c37a22ac2cb', 'a', 'La distancia medida verticalmente desde la línea de flotación hasta la cubierta.', true, '2025-09-13 13:53:11.795048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cbbe295-8b7c-40d6-9017-67638600e4ed', 'cfdce7e2-4f77-48f3-aa29-0c37a22ac2cb', 'b', 'La máxima dimensión vertical medida en la mitad de la eslora, desde la cara superior del trancanil hasta la cara inferior del casco en su intersección con la quilla.', false, '2025-09-13 13:53:11.795181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18850672-4e78-43a1-bfd0-35209abdec69', 'cfdce7e2-4f77-48f3-aa29-0c37a22ac2cb', 'c', 'La altura de la obra viva de un barco.', false, '2025-09-13 13:53:11.795315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f21e27a-c0e0-4fb5-8fef-8570d52002c0', 'd2af825f-a705-46e8-abb7-72868be2190b', 'a', 'Noray.', false, '2025-09-13 13:53:11.795725+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ca594c8-eb38-4f4b-9276-e76d1d328b6d', 'd2af825f-a705-46e8-abb7-72868be2190b', 'b', 'Bita.', true, '2025-09-13 13:53:11.795878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('363f3516-8899-42d7-86a7-178870729740', 'd2af825f-a705-46e8-abb7-72868be2190b', 'c', 'Cornamusa.', false, '2025-09-13 13:53:11.796017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fa34af5-d579-41a8-93ab-850dd5902b12', 'd2af825f-a705-46e8-abb7-72868be2190b', 'd', 'Boya.', false, '2025-09-13 13:53:11.79616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52920a4d-f704-49aa-b061-98b47744c7f3', 'bfeace42-b621-4e30-99ae-5e9e14be7077', 'a', 'Ayudar en las faenas de atraque y desatraque y para recoger objetos flotantes.', false, '2025-09-13 13:53:11.796444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cb6e179-9773-47f8-967f-97603bc3b20c', 'bfeace42-b621-4e30-99ae-5e9e14be7077', 'b', 'Balizar el lugar donde se encuentra el ancla.', true, '2025-09-13 13:53:11.796576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66d0c3b1-8e38-49ec-904f-f4750e47b1f1', 'bfeace42-b621-4e30-99ae-5e9e14be7077', 'c', 'Proteger el casco de la embarcación del roce contra el muelle.', false, '2025-09-13 13:53:11.796708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e5997e2-d241-4c10-99b8-0606ada70750', 'bfeace42-b621-4e30-99ae-5e9e14be7077', 'd', 'Delimitar zonas de difícil navegación.', false, '2025-09-13 13:53:11.796846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('013b2d48-9a27-4fa6-a78a-4fd3b9e90669', 'f6518b5f-b415-4e23-b5ad-a9e93ce1d404', 'a', '50 N.', false, '2025-09-13 13:53:11.797122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e900064a-34fb-4df0-8fc0-edce339f8f43', 'f6518b5f-b415-4e23-b5ad-a9e93ce1d404', 'b', '100 N.', false, '2025-09-13 13:53:11.797256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7f47151-afb9-4a43-9712-8d90e8b45590', 'f6518b5f-b415-4e23-b5ad-a9e93ce1d404', 'c', '150 N.', true, '2025-09-13 13:53:11.797388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8b7c043-0550-4be6-8f69-e92da9f799c7', 'f6518b5f-b415-4e23-b5ad-a9e93ce1d404', 'd', '275 N.', false, '2025-09-13 13:53:11.797518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f07dcf1b-38a2-4cb9-b8df-74cbe3a5a1b8', 'bada1774-6ac0-4c7a-a999-07d301d75912', 'a', 'Llevar la mar por la proa o amuras.', false, '2025-09-13 13:53:11.797795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c282f57-6d9c-4df1-9dc6-082c184a5caf', 'bada1774-6ac0-4c7a-a999-07d301d75912', 'b', 'Llevar la mar por la popa o aletas.', true, '2025-09-13 13:53:11.797935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0400241f-8743-4b22-94d9-78236d1803bd', 'bada1774-6ac0-4c7a-a999-07d301d75912', 'c', 'Llevar la mar por la proa o por la popa.', false, '2025-09-13 13:53:11.798067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb2ed5c-d2e5-4372-8bf8-fb1b158ecab7', 'bada1774-6ac0-4c7a-a999-07d301d75912', 'd', 'Navegar sin máquina dejándose gobernar por el viento y las olas.', false, '2025-09-13 13:53:11.798197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24180347-427d-4849-9fdc-e3f24621578d', '4470c9b6-3a0c-4b44-ac14-d3f2377d89ff', 'a', 'Meter el timón a la banda de caída del náufrago hasta que la proa caiga 70º, entonces, cambiar todo el timón a la otra banda y navegar a rumbo opuesto.', false, '2025-09-13 13:53:11.798468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6f9b1a5-f895-412d-ad20-2849918e6d7f', '4470c9b6-3a0c-4b44-ac14-d3f2377d89ff', 'c', 'A partir de un punto de origen o datum, hacer una exploración recorriendo tramos de distancias iguales cambiando el rumbo 120º a estribor después de cada tramo hasta llegar al punto de origen, donde cambiaremos el rumbo 150º a estribor y realizaremos una nueva exploración.', true, '2025-09-13 13:53:11.79873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bd3ad0c-e289-4a91-a080-0ee129e48c28', '4470c9b6-3a0c-4b44-ac14-d3f2377d89ff', 'd', 'Meter el timón a la banda contraria a la que suponemos ha caído el naufrago hasta navegar a rumbo contrario.', false, '2025-09-13 13:53:11.798872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('136c8d36-d78b-4e72-888d-38f1e8c69e15', 'f4d9a02c-78d5-483e-bad8-38e209b8f6b2', 'a', 'Aumenta la estabilidad de la embarcación.', false, '2025-09-13 13:53:11.799171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39204d4e-72af-4d35-8f86-fe3fe5477bb8', 'f4d9a02c-78d5-483e-bad8-38e209b8f6b2', 'b', 'Disminuye la estabilidad de la embarcación.', true, '2025-09-13 13:53:11.799304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a68c337d-2f40-4b6d-9651-d08f46994062', 'f4d9a02c-78d5-483e-bad8-38e209b8f6b2', 'c', 'No influye en ningún caso en la estabilidad.', false, '2025-09-13 13:53:11.799434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd20c345-e9d8-4123-8962-9c1dba03aa79', 'f4d9a02c-78d5-483e-bad8-38e209b8f6b2', 'd', 'Influye en la estabilidad sólo cuando hay mala mar.', false, '2025-09-13 13:53:11.799565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('635859e1-7b5a-4448-8366-669a11a694c5', '224e3ed8-37c8-46ee-bb70-6a2b09d16608', 'a', 'Debe aportarse en el momento de la obtención de la tarjeta acreditativa del título y que sólo hay que volver a realizar si se produce alguna modificación de las condiciones psicofísicas del patrón, cuando este considere que pudiera afectar a sus aptitudes.', false, '2025-09-13 13:53:11.799865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19c20dfc-703b-40e1-8fc7-6864d82245d9', '224e3ed8-37c8-46ee-bb70-6a2b09d16608', 'b', 'Debe realizarse periódicamente, cada dos años, desde la fecha de obtención o renovación de su permiso de conducir vehículos terrestres a motor.', false, '2025-09-13 13:53:11.800002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f673153-58f7-4927-b792-fd8a5b1e0dec', '224e3ed8-37c8-46ee-bb70-6a2b09d16608', 'c', 'Será realizado únicamente por los Centros de Reconocimiento de Conductores, sin que se admita ningún otro certificado de reconocimiento médico expedido por otra entidad.', false, '2025-09-13 13:53:11.800138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d4af0ff-d069-46e1-a199-8ab846c11966', '224e3ed8-37c8-46ee-bb70-6a2b09d16608', 'd', 'No será necesario realizarlo de nuevo por aquellos ciudadanos que acrediten que no han pasado más de dos años desde la fecha de obtención o renovación de su permiso de conducir vehículos terrestres a motor en vigor, aunque sí se exige una revisión de la visión ocular a los efectos de diferenciar los colores.', true, '2025-09-13 13:53:11.800273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0db7291-8745-4870-a729-1a22db799747', '0f0fac17-2322-40df-b51b-c315bb305dcc', 'a', 'Hay buceadores cerca de la embarcación.', true, '2025-09-13 13:53:11.800584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13f507cd-e450-44df-8938-1441679f4b21', '0f0fac17-2322-40df-b51b-c315bb305dcc', 'b', 'Estoy cargando, descargando o transportando mercancías peligrosas.', false, '2025-09-13 13:53:11.80072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('031f38a4-8a19-4231-95a2-8c38a889199b', '0f0fac17-2322-40df-b51b-c315bb305dcc', 'c', 'Manténgase alejado de mí, estoy pescando al arrastre en pareja.', false, '2025-09-13 13:53:11.800855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85783062-7f06-4be1-a6a2-8708f0e099c1', '0f0fac17-2322-40df-b51b-c315bb305dcc', 'd', 'Manténgase alejado de mí, estoy maniobrando con dificultad.', false, '2025-09-13 13:53:11.801004+00');
