INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f3726a0-965f-4935-8b65-a2fcbe349f72', 'dcd9e148-7e4e-4d6d-85aa-7c81e38b2738', 'a', 'Indican los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:11.803335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a354caa1-f709-4d65-9e33-a0f0229e759d', 'dcd9e148-7e4e-4d6d-85aa-7c81e38b2738', 'b', 'Se encuentran generalmente fuera de los canales definidos y no indican el lado de babor o de estribor de la ruta a seguir ni las obstrucciones que deben evitarse.', false, '2025-09-13 13:53:11.803468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c15e033d-8dc9-4ff5-9a60-c720f70104b7', 'dcd9e148-7e4e-4d6d-85aa-7c81e38b2738', 'c', 'Indican zonas o configuraciones especiales cuya naturaleza se visualiza al consultar la carta u otra publicación náutica.', true, '2025-09-13 13:53:11.803599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('667cf5ed-c60e-43de-81cd-9fbb34b569c8', 'dcd9e148-7e4e-4d6d-85aa-7c81e38b2738', 'd', 'Se encuentran en el cuadrante correspondiente a la marca e indican las aguas más profundas en', false, '2025-09-13 13:53:11.803729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae160e17-7bf2-46de-b10f-d901cdc4b87b', '6b8cab46-2c81-42b8-951d-ae2e7d50564d', 'a', 'El ritmo de la luz también puede utilizarse para indicar el mejor lugar de paso bajo un puente.', true, '2025-09-13 13:53:11.804018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d4fa9b3-ef8f-44e4-830e-843a5e37c9d1', '6b8cab46-2c81-42b8-951d-ae2e7d50564d', 'd', 'El ritmo de la luz también puede utilizarse para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo Reglamento (RIPA).', false, '2025-09-13 13:53:11.80442+00');
