INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b366a7cb-17c0-47ab-b0db-e70f22ebacf6', '8d35017e-668e-4908-9d7e-9b0426c60e2a', 'd', 'Confiaremos en que todo el mundo respeta el RIPA y consideraremos que en todo momento somos oídos y escuchados. Meteorología', false, '2025-09-13 13:53:11.815137+00');
