INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63a7dbe9-7770-4357-8196-525ab8287350', 'c6af538f-428b-4c2b-8a23-976132ed3e24', 'a', 'Una disminución de la temperatura lleva asociada un aumento de la presión atmosférica.', false, '2025-09-13 13:53:11.816148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02f6ab08-8f6f-42a2-ba04-12fcfe45d80a', 'c6af538f-428b-4c2b-8a23-976132ed3e24', 'b', 'Un aumento de la temperatura no lleva asociada ninguna variación de la presión atmosférica.', false, '2025-09-13 13:53:11.81628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c71ae289-8883-47d4-9b02-d5ff8219d88e', 'c6af538f-428b-4c2b-8a23-976132ed3e24', 'c', 'Un aumento de la temperatura lleva asociada una disminución de la presión atmosférica.', false, '2025-09-13 13:53:11.816409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf2fb507-bfe3-4060-bfa4-4c37424c863c', '41ff68b4-2a45-404d-879b-38745e5f7ee3', 'd', 'Adujar.', false, '2025-09-13 13:53:11.81303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('166fa44c-58ff-41de-85cb-60d44e1207e6', '495f25ce-ebe0-45fb-bccd-c25cfc42568a', 'a', 'Se limita a los buques dedicados a operaciones de remolque o a los dedicados a dragados submarinos.', false, '2025-09-13 13:53:11.80914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a422c069-a1c2-4f94-9406-8172143893b2', 'c6af538f-428b-4c2b-8a23-976132ed3e24', 'd', 'Un aumento de la temperatura lleva asociada un aumento de la presión atmosférica.', true, '2025-09-13 13:53:11.816539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92df95d7-c443-4ac6-a14a-b16266280216', 'b506c081-925d-4865-bae2-604edbf651e4', 'a', 'Son las regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:11.81682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e7ff37b-a97a-4b0c-a5bf-f5876a8c0b9c', 'b506c081-925d-4865-bae2-604edbf651e4', 'b', 'El aire fluye hacia el interior de las borrascas y asciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.81695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('210a101e-2ce6-404e-8964-efb2c57811ff', 'b506c081-925d-4865-bae2-604edbf651e4', 'd', 'También se conocen como ciclones, bajas presiones o, simplemente, bajas.', false, '2025-09-13 13:53:11.81721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c6250cb-c3da-4e0f-a223-e1024a371dfc', '20bc4d0a-658b-4014-ab57-514428b0bce4', 'a', 'A menor grado en la escala, mayor altura de ola.', true, '2025-09-13 13:53:11.81749+00');
