INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('673517f9-4608-4dd3-97e1-dce2762fa39e', 'f4d7a949-418c-4f43-b4b5-d6630def4ad5', 'a', 'Va ligada a la embarcación, invariable durante toda la vida útil de la misma, independientemente de la zona de navegación.', false, '2025-09-13 13:53:11.819592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70345d3d-2689-4be0-9a85-b4a154951775', 'f4d7a949-418c-4f43-b4b5-d6630def4ad5', 'b', 'Puede variar en función de la zona de navegación y materiales del casco.', true, '2025-09-13 13:53:11.819721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e01a4172-d669-45a7-a9f4-f5a3ef9a132a', 'f4d7a949-418c-4f43-b4b5-d6630def4ad5', 'c', 'Se emite una tablilla de desvíos durante la construcción de la embarcación, sin caducidad, que variará en función del rumbo.', false, '2025-09-13 13:53:11.819895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d30edaf4-6af9-49df-9540-9e3a37f83839', 'f4d7a949-418c-4f43-b4b5-d6630def4ad5', 'd', 'La información de la tablilla de desvíos se aplica siempre sumando el valor de la misma a la declinación magnética en valor absoluto.', false, '2025-09-13 13:53:11.820061+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7daf7e83-54c0-43aa-9e91-1eb1ec3de175', '995f59ae-3539-4132-a95f-bc5e8f4b35f2', 'a', 'Es un círculo menor paralelo al ecuador.', false, '2025-09-13 13:53:11.820386+00');
