INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a213b06-4ec2-4606-8952-6f801f97dd9a', '690f8d18-5535-42fe-96b8-79a63ce65e98', 'a', 'Meter el timón a la banda de caída del náufrago hasta que la proa caiga 70º, entonces, cambiar todo el timón a la otra banda y navegar a rumbo opuesto.', false, '2025-09-13 13:53:11.829664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f92b1f2c-c745-4160-90c6-cddabc4407fc', '690f8d18-5535-42fe-96b8-79a63ce65e98', 'c', 'A partir de un punto de origen o datum, hacer una exploración recorriendo tramos de distancias iguales cambiando el rumbo 120º a estribor después de cada tramo hasta llegar al punto de origen, donde cambiaremos el rumbo 150º a estribor y realizaremos una nueva exploración.', true, '2025-09-13 13:53:11.829933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ea13954-6c41-494c-8304-6d236d018e28', '690f8d18-5535-42fe-96b8-79a63ce65e98', 'd', 'Meter el timón a la banda contraria a la que suponemos ha caído el naufrago hasta navegar a rumbo contrario.', false, '2025-09-13 13:53:11.830062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d892e43c-f9a0-4dbf-8579-e3492eb029c3', 'bf016682-47f6-4f9d-92b2-e64040c31d8f', 'a', 'Aumenta la estabilidad de la embarcación.', false, '2025-09-13 13:53:11.830329+00');
