INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('850a369d-1d22-47b7-8194-dd03f0d74b75', 'bf016682-47f6-4f9d-92b2-e64040c31d8f', 'd', 'Influye en la estabilidad sólo cuando hay mala mar.', false, '2025-09-13 13:53:11.830716+00');
