INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a3c838b-a1b4-47df-a559-6092aa005e51', '6c90f752-509f-40c7-a539-b411820262fa', 'a', 'Debe aportarse en el momento de la obtención de la tarjeta acreditativa del título y que sólo hay que volver a realizar si se produce alguna modificación de las condiciones psicofísicas del patrón, cuando este considere que pudiera afectar a sus aptitudes.', false, '2025-09-13 13:53:11.832417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff6ab1a8-9cd5-46f8-97d5-88d7abc75dd1', '6c90f752-509f-40c7-a539-b411820262fa', 'b', 'Debe realizarse periódicamente, cada dos años, desde la fecha de obtención o renovación de su permiso de conducir vehículos terrestres a motor.', false, '2025-09-13 13:53:11.832555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ebe791a-1f2f-43d7-82a3-ea44c9f98fec', '6c90f752-509f-40c7-a539-b411820262fa', 'c', 'Será realizado únicamente por los Centros de Reconocimiento de Conductores, sin que se admita ningún otro certificado de reconocimiento médico expedido por otra entidad.', false, '2025-09-13 13:53:11.832685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49be6729-c15d-49ac-9b3e-092a42b04405', '6c90f752-509f-40c7-a539-b411820262fa', 'd', 'No será necesario realizarlo de nuevo por aquellos ciudadanos que acrediten que no han pasado más de dos años desde la fecha de obtención o renovación de su permiso de conducir vehículos terrestres a motor en vigor, aunque sí se exige una revisión de la visión ocular a los efectos de diferenciar los colores.', true, '2025-09-13 13:53:11.832817+00');
