INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc0ee024-35e8-4db6-a8df-a6dd30b764d3', '541efad9-cf8c-473d-bf60-e3113c84b0e2', 'b', 'Un cilindro verde.', false, '2025-09-13 13:53:11.834561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf888f61-d861-484a-b96f-653bd4a457f6', '541efad9-cf8c-473d-bf60-e3113c84b0e2', 'c', 'Un cono rojo con el vértice hacia abajo.', false, '2025-09-13 13:53:11.834689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1ff4a11-33ea-46de-8645-4e2846438c09', '541efad9-cf8c-473d-bf60-e3113c84b0e2', 'd', 'Un cono verde con el vértice hacia arriba.', true, '2025-09-13 13:53:11.83482+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19b5edc7-0844-48e4-8d71-27c5446456ff', '651c09a1-216f-49d2-a6c4-e12c8d82eafa', 'a', 'Indican los lados de babor y estribor de la derrota que debe seguirse.', false, '2025-09-13 13:53:11.83509+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3dcb431f-a6b1-4a19-a831-6ca5c0b768a2', '651c09a1-216f-49d2-a6c4-e12c8d82eafa', 'b', 'Se encuentran generalmente fuera de los canales definidos y no indican el lado de babor o de estribor de la ruta a seguir ni las obstrucciones que deben evitarse.', false, '2025-09-13 13:53:11.835218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df69755a-2a40-427b-87bd-f4aa1c8b52f8', '651c09a1-216f-49d2-a6c4-e12c8d82eafa', 'c', 'Indican zonas o configuraciones especiales cuya naturaleza se visualiza al consultar la carta u otra publicación náutica.', true, '2025-09-13 13:53:11.835346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6772922a-de79-42a3-ad63-1af851786276', '651c09a1-216f-49d2-a6c4-e12c8d82eafa', 'd', 'Se encuentran en el cuadrante correspondiente a la marca e indican las aguas más profundas en', false, '2025-09-13 13:53:11.83548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0d568f0-6578-4267-b506-921cac7082b1', 'd3a51153-80f7-4441-acfe-af8625bbb4d8', 'a', 'El ritmo de la luz también puede utilizarse para indicar el mejor lugar de paso bajo un puente.', true, '2025-09-13 13:53:11.835754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b804473f-5291-4b4d-88c4-fb8775ff412a', 'd3a51153-80f7-4441-acfe-af8625bbb4d8', 'd', 'El ritmo de la luz también puede utilizarse para llamar la atención sobre una configuración especial de un canal, tal como un recodo, una confluencia, una bifurcación o el extremo de un bajo Reglamento (RIPA).', false, '2025-09-13 13:53:11.836212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0879accd-2a28-4ea3-a013-15433504213c', 'f71c6263-e411-49c4-a3fd-df4347e6f8d2', 'a', 'Las luces de costado y una luz de alcance.', true, '2025-09-13 13:53:11.836495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdc8fbbb-017c-41fe-9fa1-394e63302616', 'f71c6263-e411-49c4-a3fd-df4347e6f8d2', 'b', 'En la parte de proa, una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.836654+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b877a147-b1d0-446c-9dd2-6c054867a07f', 'd3a51153-80f7-4441-acfe-af8625bbb4d8', 'b', 'Su marca de tope, formada por dos esferas superpuestas, es su característica diurna más importante.', false, '2025-09-13 13:53:11.835926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b0c7488-fdb9-4b01-ac24-09cb05666c39', 'f71c6263-e411-49c4-a3fd-df4347e6f8d2', 'd', 'Las luces de costado y dos luces rojas todo horizonte en el lugar más visible.', false, '2025-09-13 13:53:11.836922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbaea086-aa4b-4d66-a42a-dbb739da71fc', '91227b03-be40-4621-861f-85f5b8de9f21', 'a', 'Un buque sin gobierno.', true, '2025-09-13 13:53:11.837217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2a8a8f7-ee8b-44be-b865-e4aa578371c8', '91227b03-be40-4621-861f-85f5b8de9f21', 'b', 'Un hidroavión amarado.', false, '2025-09-13 13:53:11.837352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3ecd7cc-d18d-4bd9-8662-59fcf1f4c103', '91227b03-be40-4621-861f-85f5b8de9f21', 'c', 'Un buque sin capacidad de maniobra restringida.', false, '2025-09-13 13:53:11.837484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1095a7f0-302c-4115-abe7-cda2c02f9663', '91227b03-be40-4621-861f-85f5b8de9f21', 'd', 'Todos los buques sin excepción, siempre.', false, '2025-09-13 13:53:11.837616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67e783a6-5787-4d64-9ccb-ef2a63d6d197', 'f0f439bf-0d96-487e-b7d7-d6522763f195', 'b', 'No incluye a los buques dedicados a reparar o recoger marcas de navegación.', false, '2025-09-13 13:53:11.838024+00');
