INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85d30790-dd5f-4a32-9473-417609bd7ce4', 'f0f439bf-0d96-487e-b7d7-d6522763f195', 'd', 'Significa todo buque que, debido a la naturaleza de su trabajo, tiene reducida su capacidad de maniobrar en la forma exigida por este Reglamento.', true, '2025-09-13 13:53:11.838282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8481929-afd4-4b18-8e22-9b3de7e2b91b', '88ff7e9c-560d-4cf5-8152-1ab130f360a0', 'a', 'Las luces de costado.', false, '2025-09-13 13:53:11.838551+00');
