INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('468f19c1-ea96-4ec4-a174-dd6ada35d6b4', '26e9d255-32a3-4cee-9136-53f8624f9a46', 'a', 'Navegar por la zona de navegación costera, manteniendo así una adecuada distancia de seguridad de los buques que lo transitan.', false, '2025-09-13 13:53:11.842621+00');
