INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6a8f54d-57e0-4e70-a283-7e47d94a88b8', '26e9d255-32a3-4cee-9136-53f8624f9a46', 'd', 'Navegar por el dispositivo de tráfico entrando y saliendo siempre con el mayor ángulo posible en relación con la dirección general de la corriente. Maniobra y navegación.', false, '2025-09-13 13:53:11.843032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8042d860-2bc9-4e70-af03-985ecfb88fa7', 'f47aee0d-4b11-4921-85f7-0616380d025d', 'a', 'Del esprín de proa.', true, '2025-09-13 13:53:11.843305+00');
