INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6db008c2-eb5b-4235-a951-739ee7f2d7c3', 'a4de6657-d8db-42b6-bc5e-028d6387ed9c', 'c', 'Amollar.', false, '2025-09-13 13:53:11.844335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('785c39c8-8d4c-4ed0-bf80-ca9c6a229966', '5f657008-2198-45de-ab40-0f0ad782e35c', 'a', 'En caso de estar equipados con un reflector de radar, izarlo lo más elevado posible.', true, '2025-09-13 13:53:11.844752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3249e276-d013-4b6e-9847-c0fe4b566513', '5f657008-2198-45de-ab40-0f0ad782e35c', 'b', 'No debemos hacer uso del VHF para alertar a un buque que nos puede abordar.', false, '2025-09-13 13:53:11.8449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5262a917-6080-437a-8148-9e41d0946515', '5f657008-2198-45de-ab40-0f0ad782e35c', 'c', 'En caso de navegar a vela, no debemos arrancar el motor para evitar un abordaje.', false, '2025-09-13 13:53:11.845047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adfe6784-2bc1-4df3-87d4-b50457c76523', '5f657008-2198-45de-ab40-0f0ad782e35c', 'd', 'Confiaremos en que todo el mundo respeta el RIPA y consideraremos que en todo momento somos oídos y escuchados.', false, '2025-09-13 13:53:11.845183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b15b135e-2958-48fb-807a-1729ddcbaef9', 'f10c153c-370f-4ddf-8906-5244add15cfd', 'a', 'Las quemaduras de 1er grado con extensión menor del 20% de la superficie corporal.', false, '2025-09-13 13:53:11.845467+00');
