INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5101569d-9684-4417-bad2-8974b29e2c1d', '72f5771d-9207-4843-8a4e-42eeb7795bc6', 'd', 'El día, desde el mar hacia la tierra.', true, '2025-09-13 13:53:11.847202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1b772cc-4fb7-4fa4-b338-e05652a78cda', 'de4921e2-23e1-4231-9a28-d13233d18f90', 'a', 'Son las regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-13 13:53:11.847475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35f7b8ae-d627-419f-bd02-116af0918a79', 'de4921e2-23e1-4231-9a28-d13233d18f90', 'b', 'El aire fluye hacia el interior de las borrascas y asciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.847603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2226d33b-f989-4057-80a1-70daa5ac6a33', 'de4921e2-23e1-4231-9a28-d13233d18f90', 'd', 'También se conocen como ciclones, bajas presiones o, simplemente, bajas.', false, '2025-09-13 13:53:11.847872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa796f42-15f1-462a-a54d-6444e8ab8439', '92d2c44f-c3e4-4d23-a6f1-523ffa4d3e25', 'a', 'A menor grado en la escala, mayor altura de ola.', true, '2025-09-13 13:53:11.848172+00');
