INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('990c6fcf-626f-45d4-b226-99b2caf173f2', '92d2c44f-c3e4-4d23-a6f1-523ffa4d3e25', 'c', 'Los niveles de ola varían entre “0” y “9”.', false, '2025-09-13 13:53:11.848455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18bb3aed-a7ed-4c1e-9ea5-b9da7c9bcf1a', '92d2c44f-c3e4-4d23-a6f1-523ffa4d3e25', 'd', 'A mayor grado en la escala, mayor altura de ola.', false, '2025-09-13 13:53:11.848586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d0c1582-da6a-4916-9ad5-b0062245e51a', '3219413e-8df0-48e8-b42b-e97df89e95d2', 'a', 'Una disminución de la temperatura lleva asociada un aumento de la presión atmosférica.', false, '2025-09-13 13:53:11.848858+00');
