INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4786706-a22b-4a32-aa06-8a84326bec1d', '3219413e-8df0-48e8-b42b-e97df89e95d2', 'c', 'Un aumento de la temperatura lleva asociada una disminución de la presión atmosférica.', false, '2025-09-13 13:53:11.849117+00');
