INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('563e3dd9-a9f5-4aab-86ff-e4391ae3b3e9', '8f99f032-492b-4de9-8e03-646377c9f47f', 'a', '1 milla náutica.', false, '2025-09-13 13:53:11.851538+00');
