INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43dccb02-9f46-4435-8192-9bbbf6db1a7b', '0a00bf12-d44b-4204-930b-823ee52bbd69', 'c', 'Es el movimiento uniforme de caída que se crea una vez se ha alcanzado el grado deseado con la acción del timón y las fuerzas actuantes se han equilibrado.', false, '2025-09-13 13:53:11.855979+00');
