INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b421d6aa-00de-45f7-95fc-ee0e8965f77a', 'e2d5211f-7d01-49ad-a40e-08ffe174e0f1', 'a', 'Maniobrar con la corriente por el través para mantener la proa estable y la capacidad de gobierno.', false, '2025-09-13 13:53:11.856392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2613acd4-c1f1-47b0-86f0-df8a032321af', 'e2d5211f-7d01-49ad-a40e-08ffe174e0f1', 'b', 'Maniobrar con la corriente por el través siempre y cuando la velocidad de gobierno de la embarcación sea mayor que la de la corriente.', false, '2025-09-13 13:53:11.856526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60f6f6ce-0c8f-4748-b13d-0b7262a5e75d', 'e2d5211f-7d01-49ad-a40e-08ffe174e0f1', 'c', 'Maniobrar proa a la corriente para mantener la capacidad de gobierno.', true, '2025-09-13 13:53:11.85667+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82b8cab1-c670-449a-8063-b464aedadd00', 'bb30c4f2-9b91-4b09-8c51-504a369f788c', 'a', 'Salte al agua, de pie, con las piernas y rodillas juntas, sujetando el chaleco y tapándose la nariz.', false, '2025-09-13 13:53:11.857131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9ea8472-9ddc-40fd-b796-c26c1cb57ae0', 'bb30c4f2-9b91-4b09-8c51-504a369f788c', 'b', 'Manténgase en continuo movimiento para generar calor corporal.', true, '2025-09-13 13:53:11.857285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30872ac3-915b-4a56-b841-2e09737a17c5', 'bb30c4f2-9b91-4b09-8c51-504a369f788c', 'c', 'Lleve consigo la radiobaliza.', false, '2025-09-13 13:53:11.857418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fcbee04-656b-48ce-8605-cc5d10aaf8a1', 'e2d5211f-7d01-49ad-a40e-08ffe174e0f1', 'd', 'Maniobrar popa a la corriente para mantener la capacidad de gobierno.', false, '2025-09-13 13:53:11.856817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59cb6505-db7f-414d-8d5f-413c3706b1ab', '9f9ea9f6-6515-4bd5-b9a4-d44e79145d36', 'd', 'Es un círculo menor perpendicular al ecuador.', false, '2025-09-13 13:53:11.852618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eed6266-ea42-4d56-ba22-3b5521cb5d56', 'bb30c4f2-9b91-4b09-8c51-504a369f788c', 'd', 'Adopte la postura fetal y flote abrazando a sus compañeros.', false, '2025-09-13 13:53:11.85755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99f4b483-357e-484d-be94-50b2eb312521', 'aec34be4-aab6-4f23-90b5-142775b07375', 'a', 'Realice una llamada de socorro.', true, '2025-09-13 13:53:11.857829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50029b9a-624c-47a4-8d64-687569e43fd5', 'aec34be4-aab6-4f23-90b5-142775b07375', 'b', 'Aumente la flotabilidad vaciando el depósito de agua dulce al mínimo imprescindible.', false, '2025-09-13 13:53:11.85796+00');
