INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd58e702-47ec-43bd-901b-414eebd6f68b', '4cf78309-8128-4253-aa45-163c1f88fa04', 'c', 'Se deberá esperar a la bajamar. El tiempo que transcurre entre 2 pleamares o 2 bajamares es, aproximadamente, de 12 horas y media.', false, '2025-09-13 13:53:11.858771+00');
