INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16328e3d-4afc-48aa-b958-ee9935037c14', 'a652704b-afe0-465f-bb12-474668cafd5b', 'a', 'El viento real es el que se mide con la embarcación parada.', false, '2025-09-13 13:53:11.859184+00');
