INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('492417e4-e612-4a69-9b62-0fa1a3343b00', 'a652704b-afe0-465f-bb12-474668cafd5b', 'c', 'El viento aparente es la resultante de la suma vectorial de los vientos real y relativo.', false, '2025-09-13 13:53:11.859442+00');
