INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75dfdba4-35a5-4a4b-8f3b-82fb7d2d7493', '765845ad-c4cc-4722-961c-6a7c9056865f', 'a', 'A la colocación más adecuada de los elementos de a bordo, para la navegación, a fin de que no se produzca su corrimiento.', true, '2025-09-13 13:53:11.884784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97483e53-8dc1-43d6-9d1b-de26e58c8dc4', '765845ad-c4cc-4722-961c-6a7c9056865f', 'b', 'A llevar la mar por proa durante un temporal, es decir, capear el temporal.', false, '2025-09-13 13:53:11.884917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d70ac14b-8fc5-4898-a301-dbe57e9f0157', '765845ad-c4cc-4722-961c-6a7c9056865f', 'c', 'A llevar la mar por popa durante un temporal, es decir, correr el temporal.', false, '2025-09-13 13:53:11.885049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c20f3f3-d6e5-4e42-b509-9040f7ad7600', '765845ad-c4cc-4722-961c-6a7c9056865f', 'd', 'A realizar una navegación adecuada que nos permita capear o correr el temporal.', false, '2025-09-13 13:53:11.885176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('240d504d-7186-4c9c-85c0-6075c119bdbb', '7374ab19-29e5-4646-ac37-3e5ad0b1b74b', 'a', 'Es obligatorio en todas las embarcaciones de recreo, en cualquier zona de navegación.', false, '2025-09-13 13:53:11.88544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6bdb8f1-d8ba-4754-af80-8548b9286122', '7374ab19-29e5-4646-ac37-3e5ad0b1b74b', 'b', 'Es obligatorio en todas las embarcaciones de recreo navegando en cualquier zona, excepto en la', false, '2025-09-13 13:53:11.885566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbdece22-460a-4d1d-92ce-7d7a1bcc5370', '7374ab19-29e5-4646-ac37-3e5ad0b1b74b', 'c', 'Es obligatorio en embarcaciones con casco de fibra.', true, '2025-09-13 13:53:11.885697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef543b73-d55e-4e93-879c-9655bebaea5e', '7374ab19-29e5-4646-ac37-3e5ad0b1b74b', 'd', 'No es obligatorio en ningún caso, pero sí absolutamente recomendable.', false, '2025-09-13 13:53:11.885825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db3650f7-ee31-4baa-9f83-782650a36300', 'c75baf88-7068-4e7a-bf27-803ccef508c3', 'a', 'Llamando al 900 202 220 o al 061.', false, '2025-09-13 13:53:11.886092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7af1263-24e2-4ae8-b330-eb0066d1bd9a', 'c75baf88-7068-4e7a-bf27-803ccef508c3', 'b', 'Llamando al 900 202 202 o al 112.', true, '2025-09-13 13:53:11.886222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6518f43f-6ad7-4433-abcd-72f3145c63ff', 'c75baf88-7068-4e7a-bf27-803ccef508c3', 'c', 'Llamando al teléfono de la Capitanía Marítima más cercana.', false, '2025-09-13 13:53:11.886349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16dea585-d826-4897-89f8-a7defaa7f3a9', 'c75baf88-7068-4e7a-bf27-803ccef508c3', 'd', 'Mediante comunicación por el NAVTEX.', false, '2025-09-13 13:53:11.886475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32daa6b2-15dd-411a-8131-1b5bac7b1c47', '1009ecc6-5f27-4ccb-9a97-5af1770d430a', 'a', 'Solamente en navegaciones en las zonas 1, 2.', false, '2025-09-13 13:53:11.886738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1939fb6f-171c-48fd-b8b8-aabec8b0cffd', '1009ecc6-5f27-4ccb-9a97-5af1770d430a', 'b', 'Solamente en navegaciones en las zonas 1, 2 ó 3.', false, '2025-09-13 13:53:11.886873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f01ee7e-b6a2-42e1-9786-00c7fe6cd1b2', '1009ecc6-5f27-4ccb-9a97-5af1770d430a', 'c', 'Solamente en navegaciones en las zonas 1, 2, 3 ó 4.', true, '2025-09-13 13:53:11.886999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1068c58d-e193-4d37-b54f-5ed92c81acd9', '1009ecc6-5f27-4ccb-9a97-5af1770d430a', 'd', 'Navegando en cualquier zona.', false, '2025-09-13 13:53:11.887127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6865330b-e3a3-4371-9bd0-a6568b25616a', '20e693e6-feb7-49c9-b265-95c8c63996c8', 'a', 'Que tengan permiso provisional de navegación cualquiera que sea su categoría de diseño podrán navegar en el mar territorial español sin ninguna limitación en cuanto a zona de navegación.', false, '2025-09-13 13:53:11.887395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a4c95a6-30ec-479b-9a92-837f4f58cff5', '20e693e6-feb7-49c9-b265-95c8c63996c8', 'b', 'De eslora total inferior a 20 metros no estorbarán el tránsito del resto de buques y embarcaciones en las aguas de servicio de los puertos comerciales.', true, '2025-09-13 13:53:11.887528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b1edace-b273-4f90-ae7f-c597c1033cdb', '20e693e6-feb7-49c9-b265-95c8c63996c8', 'c', 'No tienen obligación de tener a bordo el certificado de navegabilidad. En caso de que las autoridades competentes se lo requieran al patrón, se dispondrá de un plazo de cinco días hábiles para justificar ante estas su existencia y vigencia.', false, '2025-09-13 13:53:11.887656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7e72982-1f34-4d81-8a39-aee37e0106e0', '20e693e6-feb7-49c9-b265-95c8c63996c8', 'd', 'Que, estando en el mar, reciban una señal del servicio de búsqueda y salvamento, que les indique que hay personas en peligro en el mar, están siempre obligadas a acudir a toda máquina en su auxilio, sin eximente alguna.', false, '2025-09-13 13:53:11.887802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ff7f7a2-9dcd-43eb-b072-38882ae90c97', '822df3ea-c09d-4a80-b580-a3ded1bfe905', 'a', 'Tengo un buzo sumergido. Manténgase alejado de mí y reduzca la velocidad.', true, '2025-09-13 13:53:11.888152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b059bb42-6140-4393-89d7-f5e0f8686298', '822df3ea-c09d-4a80-b580-a3ded1bfe905', 'b', 'Tengo un buzo sumergido. Póngase en comunicación con su embarcación de apoyo.', false, '2025-09-13 13:53:11.888295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85747f4e-0b48-4845-bb02-2db7b6098781', '822df3ea-c09d-4a80-b580-a3ded1bfe905', 'c', 'Tengo un buzo sumergido en problemas. Póngase en comunicación con Salvamento Marítimo.', false, '2025-09-13 13:53:11.888425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8967bad-2c35-448b-9842-4706693b2ecd', '822df3ea-c09d-4a80-b580-a3ded1bfe905', 'd', 'Manténgase alejado de mí, estoy maniobrando con dificultad porque hay buzo sumergido.', false, '2025-09-13 13:53:11.888553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9533c2f5-876d-48ad-8340-3c17a007e651', '6ad4d6af-f87e-43f5-8031-53bc3379a8b4', 'a', 'Marca de tope en cruz vertical.', false, '2025-09-13 13:53:11.888821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4918a72-ee45-4f23-bc4d-fbe7f85af0ef', '6ad4d6af-f87e-43f5-8031-53bc3379a8b4', 'b', 'Marcas de tope cilíndricas.', true, '2025-09-13 13:53:11.88895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a130f71-7cbb-42de-961c-784e182334e6', '6ad4d6af-f87e-43f5-8031-53bc3379a8b4', 'c', 'Marcas de tope esféricas.', false, '2025-09-13 13:53:11.889081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77344f5f-04d4-423a-9867-ec8990f27442', '6ad4d6af-f87e-43f5-8031-53bc3379a8b4', 'd', 'Marcas de tope en cruz diagonal.', false, '2025-09-13 13:53:11.889207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e438643-f7b7-4419-b9df-1a4d97d8630b', 'f6f359da-205c-4411-94c0-b750bcfb8106', 'a', 'Esférica, también de castillete o espeque con una marca de tope esférica.', false, '2025-09-13 13:53:11.889472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3598acf3-b388-438b-b421-4a7ba7e6465d', 'f6f359da-205c-4411-94c0-b750bcfb8106', 'b', 'De castillete o espeque.', false, '2025-09-13 13:53:11.889607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26806313-dee8-4f5a-976e-b7bf232b77bc', 'f6f359da-205c-4411-94c0-b750bcfb8106', 'c', 'Ninguna. Solamente luz.', false, '2025-09-13 13:53:11.889733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b441be6d-9c71-4c50-974b-7a6e57688996', 'f6f359da-205c-4411-94c0-b750bcfb8106', 'd', 'De libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', true, '2025-09-13 13:53:11.889871+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('510ba764-ebab-4df4-b718-848ba4098d66', 'c20dbe1f-6719-4608-b0fb-e7c31c9ecdb6', 'a', 'Son de color amarillo y bandas blancas.', false, '2025-09-13 13:53:11.890149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d26cf47-4185-4a1a-b93b-5491aa986926', 'c20dbe1f-6719-4608-b0fb-e7c31c9ecdb6', 'b', 'Su marca de tope está formada por dos esferas negras superpuestas.', true, '2025-09-13 13:53:11.890277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6b2ab35-8a34-4a40-9a3b-6df154c2f10d', 'c20dbe1f-6719-4608-b0fb-e7c31c9ecdb6', 'c', 'Su luz es roja.', false, '2025-09-13 13:53:11.890418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44f54eb4-3c92-4ebe-b06d-96fa2129ba70', 'c20dbe1f-6719-4608-b0fb-e7c31c9ecdb6', 'd', 'Tienen el mismo ritmo de destellos que las Marcas cardinales.', false, '2025-09-13 13:53:11.890549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4db09a84-38d2-4cf4-a4ef-8c3378868dfe', '257d1244-0804-47dc-82b5-825be3a95298', 'a', 'Grupos de 3 centelleos cada 10 segundos.', true, '2025-09-13 13:53:11.890842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b8ebd93-5e8d-4a1b-a53f-b5e509b34ef9', '257d1244-0804-47dc-82b5-825be3a95298', 'b', 'Centelleante rápido (sin grupos).', false, '2025-09-13 13:53:11.890991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('225961b7-0b6b-498b-b8e4-038586d72ca7', '257d1244-0804-47dc-82b5-825be3a95298', 'c', 'Grupos de 6 centelleos más un centelleo largo cada 15 segundos.', false, '2025-09-13 13:53:11.891121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dde78d4-f07e-48c5-b2be-c9254e55cb42', '257d1244-0804-47dc-82b5-825be3a95298', 'd', 'Grupos de 9 centelleos cada 15 segundos.', false, '2025-09-13 13:53:11.89125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a258e9d3-3c3a-4e6b-850f-646042ba2fa8', '778ac7e9-11db-4104-942b-0218e18ba437', 'a', 'Incluyen las marcas que definen los ejes de los canales y las marcas de centro de canal.', true, '2025-09-13 13:53:11.891523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d0071f3-6953-4f60-aa0d-ca33145bffc1', '778ac7e9-11db-4104-942b-0218e18ba437', 'b', 'Pueden utilizarse para proporcionar información direccional en un canal de navegación.', false, '2025-09-13 13:53:11.891656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5534c9c1-547d-414f-8fc6-93be9d157131', '778ac7e9-11db-4104-942b-0218e18ba437', 'c', 'No se utilizarán si existe una señal más adecuada dentro del Sistema de Balizamiento Marítimo.', false, '2025-09-13 13:53:11.891786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e20dc138-7931-4d0d-b58a-8d9414c6416e', '778ac7e9-11db-4104-942b-0218e18ba437', 'd', 'Sirven para indicar las aguas que son navegables alrededor de un peligro concreto. Reglamento (RIPA).', false, '2025-09-13 13:53:11.891914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d8e199c-369d-4a6b-882f-83e7545534ca', 'a0098eb4-2707-496a-8ec7-99314641d58d', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:11.89222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7af5734-8c69-4f66-9c5f-d6412f95435e', 'a0098eb4-2707-496a-8ec7-99314641d58d', 'b', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.892361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d4388fe-3115-4c27-816d-b49a50633b36', 'a0098eb4-2707-496a-8ec7-99314641d58d', 'c', 'Se denomina situación de cruce cuando dos buques naveguen en rumbos opuestos, pero sin riesgo', false, '2025-09-13 13:53:11.892496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9f6b45c-06df-4a0c-bf65-5eb57d2dbf8b', 'a0098eb4-2707-496a-8ec7-99314641d58d', 'd', 'Ambos buques mantendrán tanto su rumbo como su velocidad, pero permanecerán atentos a que el otro buque comience a maniobrar, ya que en esta situación no se han definido preferencias de maniobra para los buques.', false, '2025-09-13 13:53:11.892628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('835287f1-daca-447b-b292-81587900cf9f', 'c8ace11b-1ae7-4001-bf26-53efe48f6be9', 'a', 'Mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:11.892906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8579378-6f45-4669-808f-620e0cbd0af8', 'c8ace11b-1ae7-4001-bf26-53efe48f6be9', 'b', 'Mantendrá su rumbo, pero variará su velocidad para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.893044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c72592cc-a143-4789-b74a-2e66a6b5045d', 'c8ace11b-1ae7-4001-bf26-53efe48f6be9', 'c', 'Mantendrá su velocidad, pero variará su rumbo para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.893172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed853ff8-26c2-4e85-9b9c-876a66a58995', 'c8ace11b-1ae7-4001-bf26-53efe48f6be9', 'd', 'Alterará tanto su rumbo como su velocidad para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.893301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d4f2217-1cae-4e48-a9bb-75a2a183c584', 'c25a3c32-1b41-45d3-bfe5-f6bdc9f94435', 'a', 'Los buques de propulsión mecánica de eslora inferior a 12 metros.', false, '2025-09-13 13:53:11.893571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d08b9ccf-28f1-47b9-a6d2-81991b01fdf3', 'c25a3c32-1b41-45d3-bfe5-f6bdc9f94435', 'b', 'Los aerodeslizadores cuando operen en la condición sin desplazamiento.', true, '2025-09-13 13:53:11.893708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3652aa33-dd75-4274-b69f-55264db82daa', 'c25a3c32-1b41-45d3-bfe5-f6bdc9f94435', 'c', 'Los buques de propulsión mecánica de eslora inferior a 7 metros y cuya velocidad máxima no sea superior a 7 nudos.', false, '2025-09-13 13:53:11.893843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b897147-111f-4bea-a70f-7ebcad6267a6', 'c25a3c32-1b41-45d3-bfe5-f6bdc9f94435', 'd', 'Los buques de propulsión mecánica de eslora inferior a 12 metros y superior a 7 metros, con cualquier velocidad máxima.', false, '2025-09-13 13:53:11.893973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e247897-1bec-44a5-9e2a-e04ebafa145e', '40a72bac-c407-47ae-9845-6d060f3ba28d', 'a', 'Deberá mantener rumbo y velocidad.', false, '2025-09-13 13:53:11.894262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eae05eaa-0932-4a4e-81b8-36be1e0b2668', '40a72bac-c407-47ae-9845-6d060f3ba28d', 'b', 'No estorbará el tránsito del buque ya que éste solo puede navegar con seguridad dentro del canal', true, '2025-09-13 13:53:11.894398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b94a479-62f5-4173-a59e-b8367b3b4a4b', '40a72bac-c407-47ae-9845-6d060f3ba28d', 'c', 'Deberá maniobrar de acuerdo con lo recogido en la regla 15, “Situación de cruce”.', false, '2025-09-13 13:53:11.894534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22c3d5dc-40b1-492b-9268-88ae3461c5de', '40a72bac-c407-47ae-9845-6d060f3ba28d', 'd', 'Deberá dar una pitada larga indicando su preferencia de paso y aumentar velocidad para estorbar lo mínimo posible con su entrada a puerto.', false, '2025-09-13 13:53:11.894666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0212d165-bf93-4835-ac07-a9d0e34dcef0', '1c2224f4-44e6-44d4-8d0d-07dec2f93aa6', 'a', 'Con una pitada larga.', false, '2025-09-13 13:53:11.894942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca050ab6-f57a-442f-8e8a-4497ecdb58bb', '1c2224f4-44e6-44d4-8d0d-07dec2f93aa6', 'b', 'Con una pitada larga a intervalos que no excedan de un minuto.', false, '2025-09-13 13:53:11.89508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcd02df7-938f-43a7-84e9-4c4b7f08312c', '1c2224f4-44e6-44d4-8d0d-07dec2f93aa6', 'c', 'Con una serie de sonidos discontinuos producidos por cualquier aparato de señales de niebla.', false, '2025-09-13 13:53:11.895221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c72db17-a0e5-450a-9b47-314fbd93b5ac', '1c2224f4-44e6-44d4-8d0d-07dec2f93aa6', 'd', 'Con un sonido continuo producido por cualquier aparato de señales de niebla.', true, '2025-09-13 13:53:11.895364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98785ca4-4e6c-43bc-a255-0a80c07e269e', '0477e66f-fdb1-48f6-a215-6816fc08879b', 'a', 'Los buques de menos de 50 metros de eslora, cuando exhiban una luz blanca todo horizonte en el lugar más visible.', false, '2025-09-13 13:53:11.895653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9d02f82-0ca4-40ae-bd7d-a65a1e524456', '0477e66f-fdb1-48f6-a215-6816fc08879b', 'b', 'Los buques de menos de 50 metros de eslora.', false, '2025-09-13 13:53:11.895785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04be344f-1e0a-4d20-b2b3-630c04af3475', '0477e66f-fdb1-48f6-a215-6816fc08879b', 'c', 'Los buques de menos de 24 metros de eslora.', false, '2025-09-13 13:53:11.895915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e3a7016-30c5-4d78-9286-0f18687eb30c', '0477e66f-fdb1-48f6-a215-6816fc08879b', 'd', 'Los buques de menos de 12 metros de eslora.', true, '2025-09-13 13:53:11.896064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('794eb7be-cb12-4a4c-acf5-128b2eb018cb', '06254c2b-64df-4a8c-89f2-8ff2ffd12179', 'a', 'Una luz de tope y las luces de costado.', false, '2025-09-13 13:53:11.896353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e7a62d7-abfc-4e67-bc67-b01332cd3ca3', '06254c2b-64df-4a8c-89f2-8ff2ffd12179', 'b', 'Una luz de alcance y una luz de tope.', false, '2025-09-13 13:53:11.896486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03026cac-eccc-47b6-b1c0-78aa1369d11f', '06254c2b-64df-4a8c-89f2-8ff2ffd12179', 'c', 'Una luz de alcance, una luz de tope y las luces de costado.', false, '2025-09-13 13:53:11.896623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ee278be-62ff-426b-bbf3-1e78aa317c81', '06254c2b-64df-4a8c-89f2-8ff2ffd12179', 'd', 'Una luz de alcance y las luces de costado.', true, '2025-09-13 13:53:11.896753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5624ebb4-aea2-453f-8a7b-a266f2f2861c', 'c0a1a030-35f3-4601-bdb2-1958fee8d636', 'a', 'Se maniobrará únicamente realizando una sucesión de pequeños cambios de rumbo.', false, '2025-09-13 13:53:11.897046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57f8ce95-5c0d-4d6f-bf6b-fcc9108f1856', 'c0a1a030-35f3-4601-bdb2-1958fee8d636', 'b', 'La maniobra de cambio de rumbo puede ser por sí sola la más eficaz.', true, '2025-09-13 13:53:11.897198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fe2546e-7cc7-4f0a-ae4d-a388dbcb6c65', 'c0a1a030-35f3-4601-bdb2-1958fee8d636', 'c', 'La maniobra de aumento de velocidad por sí sola será la más eficaz.', false, '2025-09-13 13:53:11.897329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d474fc1d-32d1-4512-af61-b0185bdb9464', 'c0a1a030-35f3-4601-bdb2-1958fee8d636', 'd', 'Se priorizará la maniobra de marcha atrás en los casos de vuelta encontrada.', false, '2025-09-13 13:53:11.89746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1278a2b4-3a98-413a-80ba-b4fa17981709', 'f0ec519c-5097-407a-add7-f93de0ff2f5a', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:11.89774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7ea2473-b443-4f27-89df-188483ab0907', 'f0ec519c-5097-407a-add7-f93de0ff2f5a', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.897882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cde28c3-9fee-4a4c-94fe-13d71eaecf16', 'f0ec519c-5097-407a-add7-f93de0ff2f5a', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', true, '2025-09-13 13:53:11.898013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5114703d-8b15-4285-b3bd-2c42ed0c41a9', 'f0ec519c-5097-407a-add7-f93de0ff2f5a', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.898147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d59b295f-0beb-4e60-8ec3-612851656350', '9900ace8-3c61-42b0-91c8-267b63bfc723', 'a', 'Una pitada larga.', false, '2025-09-13 13:53:11.898421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36018ca6-029a-41d1-a8f2-786f95250a4f', '9900ace8-3c61-42b0-91c8-267b63bfc723', 'b', 'Una pitada corta.', false, '2025-09-13 13:53:11.898552+00');
