INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efecf5cc-fa31-494f-b122-edab18fffbe6', '5f779f73-d026-40b7-a7ab-ccdc47523961', 'a', 'Es obligatorio en todas las embarcaciones de recreo, en cualquier zona de navegación.', false, '2025-09-13 13:53:11.90494+00');
