INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22106952-37c4-41f4-ad0c-90219ca33605', '7dac7156-55bd-49c1-8390-8b80c79918cd', 'a', 'A la colocación más adecuada de los elementos de a bordo, para la navegación, a fin de que no se produzca su corrimiento.', true, '2025-09-13 13:53:11.905592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('552998cc-3cbc-43b6-9b51-824cc0eb44df', '7dac7156-55bd-49c1-8390-8b80c79918cd', 'b', 'A llevar la mar por proa durante un temporal, es decir, capear el temporal.', false, '2025-09-13 13:53:11.905728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b52f6072-7dd2-4948-9771-3de55fab6010', '7dac7156-55bd-49c1-8390-8b80c79918cd', 'c', 'A llevar la mar por popa durante un temporal, es decir, correr el temporal.', false, '2025-09-13 13:53:11.90587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('550e6642-8b1a-4292-a277-c928a5210966', '7dac7156-55bd-49c1-8390-8b80c79918cd', 'd', 'A realizar una navegación adecuada que nos permita capear o correr el temporal.', false, '2025-09-13 13:53:11.906002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b7a9b38-d59b-45d7-b36a-cb091dd35e7e', '55572133-bb28-4ac7-a557-f33f26244c15', 'a', 'Tengo un buzo sumergido. Manténgase alejado de mí y reduzca la velocidad.', true, '2025-09-13 13:53:11.906285+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad7f387d-719a-43b6-9665-a29320e04e8c', '55572133-bb28-4ac7-a557-f33f26244c15', 'b', 'Tengo un buzo sumergido. Póngase en comunicación con su embarcación de apoyo.', false, '2025-09-13 13:53:11.906418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a73ebe57-6f82-47e3-937a-f6c506f3951a', '55572133-bb28-4ac7-a557-f33f26244c15', 'c', 'Tengo un buzo sumergido en problemas. Póngase en comunicación con Salvamento Marítimo.', false, '2025-09-13 13:53:11.906548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e70c9789-02ca-40e2-a2e1-717ed5eb20cb', '55572133-bb28-4ac7-a557-f33f26244c15', 'd', 'Manténgase alejado de mí, estoy maniobrando con dificultad porque hay buzo sumergido.', false, '2025-09-13 13:53:11.906684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('453d5158-fb6a-4d30-bb48-570547b03c86', '586cdbbe-5196-4b84-a8e9-5393b0723cae', 'a', 'Que tengan permiso provisional de navegación cualquiera que sea su categoría de diseño podrán navegar en el mar territorial español sin ninguna limitación en cuanto a zona de navegación.', false, '2025-09-13 13:53:11.906956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdce4557-6773-446a-9950-9551249ffa27', '586cdbbe-5196-4b84-a8e9-5393b0723cae', 'b', 'De eslora total inferior a 20 metros no estorbarán el tránsito del resto de buques y embarcaciones en las aguas de servicio de los puertos comerciales.', true, '2025-09-13 13:53:11.907089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9703a846-9b1c-44d5-ae77-2fde99f44b06', '586cdbbe-5196-4b84-a8e9-5393b0723cae', 'c', 'No tienen obligación de tener a bordo el certificado de navegabilidad. En caso de que las autoridades competentes se lo requieran al patrón, se dispondrá de un plazo de cinco días hábiles para justificar ante estas su existencia y vigencia.', false, '2025-09-13 13:53:11.907226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beba7951-6a42-432b-91e1-756aa676f723', '586cdbbe-5196-4b84-a8e9-5393b0723cae', 'd', 'Que, estando en el mar, reciban una señal del servicio de búsqueda y salvamento, que les indique que hay personas en peligro en el mar, están siempre obligadas a acudir a toda máquina en su auxilio, sin eximente alguna.', false, '2025-09-13 13:53:11.907358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('659929b1-dd4f-4020-8c24-0a9972ff888e', '1567df8c-beb8-48e6-b80b-f8442e13baa8', 'a', 'Grupos de 3 centelleos cada 10 segundos.', true, '2025-09-13 13:53:11.907628+00');
