INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('793ca63a-db54-45b2-ad21-75e8c0f4c7cf', '1bf600eb-1305-4e82-a6bf-3add16904a8c', 'b', 'De castillete o espeque.', false, '2025-09-13 13:53:11.90928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4de3bca-b6dd-481a-b168-4de93e1a9084', '1bf600eb-1305-4e82-a6bf-3add16904a8c', 'c', 'Ninguna. Solamente luz.', false, '2025-09-13 13:53:11.909411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('abc01ad8-ed3b-4409-9ce3-88f561de4e1b', '1bf600eb-1305-4e82-a6bf-3add16904a8c', 'd', 'De libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', true, '2025-09-13 13:53:11.909562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a4614e0-7c96-450f-afac-0bd9a5d9f42c', '37274af8-4912-436d-a861-5bcc7eec7fc4', 'a', 'Incluyen las marcas que definen los ejes de los canales y las marcas de centro de canal.', true, '2025-09-13 13:53:11.909925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('943f8c48-b102-4705-a91a-340d161802a9', '37274af8-4912-436d-a861-5bcc7eec7fc4', 'b', 'Pueden utilizarse para proporcionar información direccional en un canal de navegación.', false, '2025-09-13 13:53:11.910062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87b68c92-8e7c-40ac-b2ab-091b01a6055f', '37274af8-4912-436d-a861-5bcc7eec7fc4', 'c', 'No se utilizarán si existe una señal más adecuada dentro del Sistema de Balizamiento Marítimo.', false, '2025-09-13 13:53:11.910195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b774a4b4-1116-4f22-96ba-0a53c1811574', '37274af8-4912-436d-a861-5bcc7eec7fc4', 'd', 'Sirven para indicar las aguas que son navegables alrededor de un peligro concreto.', false, '2025-09-13 13:53:11.910348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29d9f88b-3b56-4109-8d5d-8822c7dad56d', '1bb145da-5306-4786-bdaf-6b3993a79817', 'a', 'Son de color amarillo y bandas blancas.', false, '2025-09-13 13:53:11.910669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('576f46e2-8d31-4d58-bf7f-3f805de3758f', '1bb145da-5306-4786-bdaf-6b3993a79817', 'b', 'Su marca de tope está formada por dos esferas negras superpuestas.', true, '2025-09-13 13:53:11.910819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44871465-21ce-41c0-bb4a-b39dcf435f8d', '1bb145da-5306-4786-bdaf-6b3993a79817', 'c', 'Su luz es roja.', false, '2025-09-13 13:53:11.910951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3fc622c-f001-4ed3-9ed5-0d91c8287b77', '1bb145da-5306-4786-bdaf-6b3993a79817', 'd', 'Tienen el mismo ritmo de destellos que las Marcas cardinales. Reglamento (RIPA).', false, '2025-09-13 13:53:11.911094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('692d5baa-ebc8-4b62-a438-35f986dce03d', '5d46223f-c4b2-4fc0-8647-4503f6cda4cc', 'a', 'Mantendrá su rumbo y velocidad.', true, '2025-09-13 13:53:11.911393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98c8a511-0001-4ce4-9208-5c604bf85678', '5d46223f-c4b2-4fc0-8647-4503f6cda4cc', 'b', 'Mantendrá su rumbo, pero variará su velocidad para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.911534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1ddf1a1-05c2-49cc-bb17-a96d21704aa3', '5d46223f-c4b2-4fc0-8647-4503f6cda4cc', 'c', 'Mantendrá su velocidad, pero variará su rumbo para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.911663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1283d6fe-de50-4a22-a66b-ee517a32caac', '5d46223f-c4b2-4fc0-8647-4503f6cda4cc', 'd', 'Alterará tanto su rumbo como su velocidad para intentar anticiparse a nuestras maniobras.', false, '2025-09-13 13:53:11.911821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23d94680-5488-4e40-98ee-f159f33ab60a', 'f9dfbe63-4d31-473d-a86a-885e72f303f2', 'a', 'Los buques de menos de 50 metros de eslora, cuando exhiban una luz blanca todo horizonte en el lugar más visible.', false, '2025-09-13 13:53:11.912107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c70afcd4-2cff-45c2-8389-3aa030d7e449', 'f9dfbe63-4d31-473d-a86a-885e72f303f2', 'b', 'Los buques de menos de 50 metros de eslora.', false, '2025-09-13 13:53:11.912244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56bb618b-f21f-4fd5-a9bb-849ded979fde', 'f9dfbe63-4d31-473d-a86a-885e72f303f2', 'c', 'Los buques de menos de 24 metros de eslora.', false, '2025-09-13 13:53:11.912376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10dd79c1-7f44-4344-b5f1-9ffcc031ad58', 'f9dfbe63-4d31-473d-a86a-885e72f303f2', 'd', 'Los buques de menos de 12 metros de eslora.', true, '2025-09-13 13:53:11.912505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7305c2d0-1403-4996-8289-287461c8a593', 'fa3e42cc-4db0-4220-99af-2f4cee8e1795', 'a', 'Los buques de propulsión mecánica de eslora inferior a 12 metros.', false, '2025-09-13 13:53:11.912785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5811033-d041-4deb-b0cb-4f7ffdbfc1e6', 'fa3e42cc-4db0-4220-99af-2f4cee8e1795', 'b', 'Los aerodeslizadores cuando operen en la condición sin desplazamiento.', true, '2025-09-13 13:53:11.912916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a68a88a5-d08e-4db4-a4c9-1e0d2ddac4e1', 'fa3e42cc-4db0-4220-99af-2f4cee8e1795', 'c', 'Los buques de propulsión mecánica de eslora inferior a 7 metros y cuya velocidad máxima no sea superior a 7 nudos.', false, '2025-09-13 13:53:11.913044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('455846ed-7343-45c9-8b31-ffefd2f12ae9', 'fa3e42cc-4db0-4220-99af-2f4cee8e1795', 'd', 'Los buques de propulsión mecánica de eslora inferior a 12 metros y superior a 7 metros, con cualquier velocidad máxima.', false, '2025-09-13 13:53:11.913172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e0fe646-0da6-4a2e-b48d-45676c85b451', '5a3b497a-ab3f-417a-818f-f348c9e262a4', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:11.913455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0085333d-d5b6-402e-ba63-e6d4341d4df1', '5a3b497a-ab3f-417a-818f-f348c9e262a4', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.913587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6bf472e-743a-499d-a62a-28e7e92b1e67', '5a3b497a-ab3f-417a-818f-f348c9e262a4', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', true, '2025-09-13 13:53:11.913724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f325509-b765-4646-9029-0ee882aad1a1', '5a3b497a-ab3f-417a-818f-f348c9e262a4', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.913868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25868680-b345-425d-bd00-c989cdccbbd1', '0d1f431e-7a67-4522-afc6-dd08aa195701', 'a', 'Con una pitada larga.', false, '2025-09-13 13:53:11.914148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43ae578e-6c26-4e7e-a8ba-4f9e7f4bf68a', '0d1f431e-7a67-4522-afc6-dd08aa195701', 'b', 'Con una pitada larga a intervalos que no excedan de un minuto.', false, '2025-09-13 13:53:11.914279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5bcff0f-c820-4066-88e1-22164bcf9f31', '0d1f431e-7a67-4522-afc6-dd08aa195701', 'c', 'Con una serie de sonidos discontinuos producidos por cualquier aparato de señales de niebla.', false, '2025-09-13 13:53:11.914411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('756b8824-d945-4e01-8607-2fa58df6190a', '0d1f431e-7a67-4522-afc6-dd08aa195701', 'd', 'Con un sonido continuo producido por cualquier aparato de señales de niebla.', true, '2025-09-13 13:53:11.914541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('297e8e16-2639-43ab-abcc-8344bc99a10c', '22325ea3-9b42-43d2-92b0-185eefad62bc', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:11.914811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd3b8105-5a20-4175-80da-1ed5a0976ad7', '22325ea3-9b42-43d2-92b0-185eefad62bc', 'b', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.914941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fef6570-ef8b-4bfc-9fd8-539de336d896', '22325ea3-9b42-43d2-92b0-185eefad62bc', 'c', 'Se denomina situación de cruce cuando dos buques naveguen en rumbos opuestos, pero sin riesgo', false, '2025-09-13 13:53:11.915073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44f7e0fc-45b5-42bd-bc7d-fade9e5ee176', '22325ea3-9b42-43d2-92b0-185eefad62bc', 'd', 'Ambos buques mantendrán tanto su rumbo como su velocidad, pero permanecerán atentos a que el otro buque comience a maniobrar, ya que en esta situación no se han definido preferencias de maniobra para los buques.', false, '2025-09-13 13:53:11.915206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('256edabe-4eb6-4a35-b317-8271d09ce6c9', '2ab9c4cb-ac83-4c54-aad5-a5e0d6c92c0b', 'a', 'Deberá mantener rumbo y velocidad.', false, '2025-09-13 13:53:11.915487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e475f36-0e26-4784-aaf1-571893affe9c', '2ab9c4cb-ac83-4c54-aad5-a5e0d6c92c0b', 'b', 'No estorbará el tránsito del buque ya que éste solo puede navegar con seguridad dentro del canal', true, '2025-09-13 13:53:11.915626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70948ce9-1277-412b-9e09-a370e5d2a2f7', '2ab9c4cb-ac83-4c54-aad5-a5e0d6c92c0b', 'c', 'Deberá maniobrar de acuerdo con lo recogido en la regla 15, “Situación de cruce”.', false, '2025-09-13 13:53:11.915774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('724db793-7713-4dac-88ef-b4c111df789e', '2ab9c4cb-ac83-4c54-aad5-a5e0d6c92c0b', 'd', 'Deberá dar una pitada larga indicando su preferencia de paso y aumentar velocidad para estorbar lo mínimo posible con su entrada a puerto.', false, '2025-09-13 13:53:11.915935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4462501d-f671-4d83-a2d6-311cbef6a63e', '6d1b5c8e-c134-48a5-a70e-4f0d7aae1ed2', 'a', 'Se maniobrará únicamente realizando una sucesión de pequeños cambios de rumbo.', false, '2025-09-13 13:53:11.916223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2585318f-ff08-4457-8f5e-3ba221dbd339', '6d1b5c8e-c134-48a5-a70e-4f0d7aae1ed2', 'b', 'La maniobra de cambio de rumbo puede ser por sí sola la más eficaz.', true, '2025-09-13 13:53:11.916356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2bde5be-6a06-4cbc-b387-1c371b5120c2', '6d1b5c8e-c134-48a5-a70e-4f0d7aae1ed2', 'c', 'La maniobra de aumento de velocidad por sí sola será la más eficaz.', false, '2025-09-13 13:53:11.916489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ff0ec14-5f4c-45a7-a60e-9bde91d36697', '6d1b5c8e-c134-48a5-a70e-4f0d7aae1ed2', 'd', 'Se priorizará la maniobra de marcha atrás en los casos de vuelta encontrada.', false, '2025-09-13 13:53:11.916622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b366ccd-9561-480d-b326-4023cd410409', 'a7a3c490-b125-4e4b-a3d8-191ff4bf1edf', 'a', 'Una luz de tope y las luces de costado.', false, '2025-09-13 13:53:11.916937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a1f4fb4-d2ec-4fb8-b20a-d56d9e5ba530', 'a7a3c490-b125-4e4b-a3d8-191ff4bf1edf', 'b', 'Una luz de alcance y una luz de tope.', false, '2025-09-13 13:53:11.917074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0c98c12-6e7d-4358-a6fc-844694501743', 'a7a3c490-b125-4e4b-a3d8-191ff4bf1edf', 'c', 'Una luz de alcance, una luz de tope y las luces de costado.', false, '2025-09-13 13:53:11.917209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4ad7baf-628b-40e5-8132-fe5685bf5a3b', 'a7a3c490-b125-4e4b-a3d8-191ff4bf1edf', 'd', 'Una luz de alcance y las luces de costado.', true, '2025-09-13 13:53:11.917358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d53cef8-48ff-4e94-976a-d2e079bfb846', 'b33344dc-f79e-4bd7-a41a-c322757d27f9', 'a', 'Una pitada larga.', false, '2025-09-13 13:53:11.917691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5794752e-2426-4796-850a-1effa8cc48fd', 'b33344dc-f79e-4bd7-a41a-c322757d27f9', 'b', 'Una pitada corta.', false, '2025-09-13 13:53:11.917831+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa627c83-eb75-466c-9da2-00d4bb13ef54', 'b33344dc-f79e-4bd7-a41a-c322757d27f9', 'c', 'Tres pitadas largas.', false, '2025-09-13 13:53:11.91797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d4ab3de-8de7-4da1-b70f-95275d9cc542', 'b33344dc-f79e-4bd7-a41a-c322757d27f9', 'd', 'Tres pitadas cortas.', true, '2025-09-13 13:53:11.918101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee87233e-3626-4fa0-8157-741d5f0a95c5', '637cc348-3377-4e4a-8879-9e3b2a5cd65a', 'a', 'Gira en el sentido de las agujas del reloj cuando la embarcación avanza.', false, '2025-09-13 13:53:11.91851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('002cbfd4-f53c-4e96-8017-ec7552329220', '637cc348-3377-4e4a-8879-9e3b2a5cd65a', 'b', 'Gira en el sentido de las agujas del reloj cuando la embarcación retrocede.', false, '2025-09-13 13:53:11.91864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4daef97-50c1-4065-8212-74a7651a2390', '637cc348-3377-4e4a-8879-9e3b2a5cd65a', 'c', 'En marcha avante hace que la popa caiga a babor.', true, '2025-09-13 13:53:11.918769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce28ad15-90a4-4d28-9c2d-469da4982c0c', '637cc348-3377-4e4a-8879-9e3b2a5cd65a', 'd', 'En marcha atrás hace que la popa caiga a estribor.', false, '2025-09-13 13:53:11.918908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7da07c16-b7ec-4068-9f40-76971cc9206f', '1dc55f7a-be1d-4c62-b85a-19479a6c7501', 'a', 'Adrizada.', false, '2025-09-13 13:53:11.919181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9239c8f-6454-4c76-b866-7b29c53237da', '1dc55f7a-be1d-4c62-b85a-19479a6c7501', 'b', 'Escorada.', false, '2025-09-13 13:53:11.91931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65b1982c-9d72-4fb4-b94f-b2c60e976ed4', '1dc55f7a-be1d-4c62-b85a-19479a6c7501', 'c', 'Con asiento positivo.', true, '2025-09-13 13:53:11.919442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb694f91-6bb5-4f54-834c-6eb90d7cae04', '1dc55f7a-be1d-4c62-b85a-19479a6c7501', 'd', 'Con asiento negativo.', false, '2025-09-13 13:53:11.91957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('449a21de-13ee-4fdc-a34f-d677eb708390', '7ff49d5c-acdb-416a-bc13-460713c92c06', 'a', 'Cada uno de los dos cabos o cadenas que van sujetos a la caña del timón y por medio de los cuales se maneja.', false, '2025-09-13 13:53:11.919882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11bffadc-b0b2-4443-8d65-ee2262a1506a', '7ff49d5c-acdb-416a-bc13-460713c92c06', 'b', 'Los herrajes de la pala que permiten situar el timón sobre el espejo de popa de la embarcación.', false, '2025-09-13 13:53:11.920062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0da2f197-c69f-4c6a-902c-5fff8cb81de7', '7ff49d5c-acdb-416a-bc13-460713c92c06', 'c', 'Las piezas que ensamblan la caña con la pala.', true, '2025-09-13 13:53:11.920211+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03fbd9e9-9843-4bfb-84e6-c6d8350693eb', '7ff49d5c-acdb-416a-bc13-460713c92c06', 'd', 'Los elementos que permiten bloquear la rueda del timón.', false, '2025-09-13 13:53:11.920347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9568e96-b7ab-495a-97bd-1a4376eaacd5', '17d0c50f-125f-477a-a382-741295a187fd', 'a', 'El eje de simetría longitudinal de la proyección horizontal del casco.', false, '2025-09-13 13:53:11.920629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae71835b-7957-4bfb-bea2-928b20b15652', '17d0c50f-125f-477a-a382-741295a187fd', 'b', 'La línea sobre el casco que coincide con la superficie del agua cuando flota en su calado de', false, '2025-09-13 13:53:11.920759+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22ba71bc-a1ad-442f-bdba-11fdc482f5b4', '17d0c50f-125f-477a-a382-741295a187fd', 'c', 'La línea vertical del plano de crujía que pasa por el centro de carena.', true, '2025-09-13 13:53:11.920909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2181d3e6-0a7c-471e-a60f-c109c8a6c457', '17d0c50f-125f-477a-a382-741295a187fd', 'd', 'La línea transversal al plano de crujía que pasa por el centro de gravedad. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.921041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b9ad652-6b52-4b30-89b9-7ac69ece24b5', '6c281ecc-fda0-40d8-be0d-1435d29f8896', 'a', 'Nos acercaremos al lugar de fondeo elegido con el ancla a la pendura, dando la popa al viento y con velocidad de gobierno con arrancada.', true, '2025-09-13 13:53:11.921311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5086b63-0718-466b-8df0-7fe514103e8c', '6c281ecc-fda0-40d8-be0d-1435d29f8896', 'b', 'El punto de fondeo debe elegirse de forma que como mínimo se mantenga libre de obstáculos un círculo de radio igual a la longitud de la cadena filada más la eslora de la embarcación.', false, '2025-09-13 13:53:11.921442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a91b2000-b5ca-4538-a2c9-bb45caef4bf6', '6c281ecc-fda0-40d8-be0d-1435d29f8896', 'c', 'Se utilizarán dos anclas, cuyos ángulos de fondeo formen un ángulo entre 60º y 120º.', false, '2025-09-13 13:53:11.921571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35c8f38f-afca-4726-865d-2ca7d3c85a8c', '6c281ecc-fda0-40d8-be0d-1435d29f8896', 'd', 'Se utilizarán dos anclas, una por proa y otra por popa.', false, '2025-09-13 13:53:11.921702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c65df73a-7f9e-45b8-a556-6b292cfe7c76', '038ae07b-267c-4786-9b00-8c08a5a95c40', 'a', 'La gaza es el arco o curvatura que forma el cabo entre los extremos cuando éste no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:11.921974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('761f45b0-fa80-4d1e-82ec-0c0719532012', '038ae07b-267c-4786-9b00-8c08a5a95c40', 'b', 'El as de guía es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:11.922103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0e97031-b5d1-4aa3-b8f4-74bee49a2dd1', '038ae07b-267c-4786-9b00-8c08a5a95c40', 'c', 'Un noray es una pieza de hierro, de forma cilíndrica ensanchada en su parte superior, fijada en los muelles para hacer firmes las amarras de los barcos.', false, '2025-09-13 13:53:11.922232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d179a601-aeb0-4c8d-ba22-65c14ffded9b', '038ae07b-267c-4786-9b00-8c08a5a95c40', 'd', 'Una boya es una pieza que se coloca en el costado de la embarcación para evitar que se dañe cuando está amarrada.', true, '2025-09-13 13:53:11.922364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc0e527b-a8c6-4a69-acd9-188ec3d65b85', '852ddd01-dc30-4cd2-94d2-6351b8974184', 'a', 'La temperatura del aceite.', false, '2025-09-13 13:53:11.922638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3669986-d179-454e-b8ad-ab1f908f071f', '852ddd01-dc30-4cd2-94d2-6351b8974184', 'b', 'La temperatura del combustible.', true, '2025-09-13 13:53:11.922769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6a4db2b-3df1-4d3f-a6ce-e800e2e3c1db', '852ddd01-dc30-4cd2-94d2-6351b8974184', 'c', 'El pararrayos.', false, '2025-09-13 13:53:11.9229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2a32ef4-2302-4fb6-a0fb-e5f0ebb31a12', '852ddd01-dc30-4cd2-94d2-6351b8974184', 'd', 'El desvío de la aguja.', false, '2025-09-13 13:53:11.923031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5890fce5-cd00-4938-a774-74b71ce4c518', '68b76b62-f304-4f2c-b3d0-17a54e4982c5', 'a', 'En llevar la mar por la aleta, navegando a una velocidad que evite sincronizarse con las olas.', false, '2025-09-13 13:53:11.9233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64a5b01a-d31f-4554-a9b2-3ed3580920e7', '68b76b62-f304-4f2c-b3d0-17a54e4982c5', 'b', 'En llevar la mar por la amura, navegando a una velocidad reducida para sincronizarse con las', false, '2025-09-13 13:53:11.923434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5b0931e-f290-4b87-bdab-f59434effa17', '68b76b62-f304-4f2c-b3d0-17a54e4982c5', 'c', 'En llevar la mar por la amura, navegando a una velocidad que evite sincronizarse con las olas.', false, '2025-09-13 13:53:11.923562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c30c9e1-3477-4648-b02a-985a061ecf23', '68b76b62-f304-4f2c-b3d0-17a54e4982c5', 'd', 'En llevar la mar por la aleta, navegando a una velocidad reducida para sincronizarse con las olas.', true, '2025-09-13 13:53:11.923694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9c8452b-840c-4872-9399-391d68d03fdf', '6ca300a0-c792-4f32-bcaf-be8e5ee98dda', 'a', 'Llevar la máxima velocidad disponible.', false, '2025-09-13 13:53:11.923999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9df86995-f978-4b21-9d93-5e03ede5ffa8', '6ca300a0-c792-4f32-bcaf-be8e5ee98dda', 'b', 'Llevar un ancla lista para fondear.', true, '2025-09-13 13:53:11.924134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c1fa39b-eee7-4bc3-bd8d-4112b89b9f70', '6ca300a0-c792-4f32-bcaf-be8e5ee98dda', 'c', 'Gobernar con poco timón, procurando no levantarlo en ningún momento.', false, '2025-09-13 13:53:11.924267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de01a3d7-d44a-4e24-8b81-ed927d3ff923', '6ca300a0-c792-4f32-bcaf-be8e5ee98dda', 'd', 'Al maniobrar a un barco que navegue de “vuelta encontrada”, hacerlo inmediatamente metiendo', false, '2025-09-13 13:53:11.924396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9071630d-5496-4b2f-a6de-13f5c2e9437a', '0bd2a3c4-9660-4882-98ff-ecde5f8298d0', 'a', '36º C.', true, '2025-09-13 13:53:11.924666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e2ec0c8-cdf8-4c36-8fc3-764bd42de1a5', '0bd2a3c4-9660-4882-98ff-ecde5f8298d0', 'b', '35º C.', false, '2025-09-13 13:53:11.924797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04471759-7105-40f7-be1e-e091e7d0161c', '0bd2a3c4-9660-4882-98ff-ecde5f8298d0', 'c', '33º C.', false, '2025-09-13 13:53:11.924926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd4ee451-47e3-422d-a6b6-db48d8423c29', '0bd2a3c4-9660-4882-98ff-ecde5f8298d0', 'd', '32º C.', false, '2025-09-13 13:53:11.925054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f579ea9-7713-4a15-9c76-6fc9794ff280', 'add109b4-411e-4829-8b82-f7333ed178db', 'a', 'Está prohibida en todo caso, sin que quepa excepción alguna.', false, '2025-09-13 13:53:11.925322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b97403c-58df-45bc-8296-a0b930af2017', 'add109b4-411e-4829-8b82-f7333ed178db', 'b', 'Está permitida si se realiza a menos de 12 millas marinas de la tierra más próxima y siempre que no esté contaminado con otro tipo de basuras.', true, '2025-09-13 13:53:11.925462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29a5d957-ba8b-4d80-a819-3bbe6bdd0480', 'add109b4-411e-4829-8b82-f7333ed178db', 'c', 'Está prohibida a no ser que se deba a una pérdida accidental de basuras resultante de una avería y se hubieran tomado toda suerte de precauciones razonables para impedir o reducir a un mínimo tal', false, '2025-09-13 13:53:11.925597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1fa3ba6-b14b-45e3-a1e0-0f0eaf4eee87', 'add109b4-411e-4829-8b82-f7333ed178db', 'd', 'Está permitida siempre que se realice a más de 12 millas marinas de la tierra más próxima, mientras la embarcación no se encuentre en ruta y junto a los demás desechos de alimentos que deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:11.925735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a58a1c1-334c-4220-b4d4-2b68e987ddb2', '0100fb5f-8955-4202-9efc-cf0b569f2f93', 'a', 'A una distancia superior a 3 millas náuticas de la tierra más próxima si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema dotado de medios que permitan almacenarlas temporalmente, siempre que sea aprobado u homologado por la Administración Marítima española.', false, '2025-09-13 13:53:11.926027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb35387-4408-4ea2-8c67-3b0ac42854cf', '0100fb5f-8955-4202-9efc-cf0b569f2f93', 'b', 'A una distancia superior a 3 millas náuticas e inferior a 12 millas náuticas de la tierra más próxima, hayan sido o no previamente desmenuzadas y desinfectadas, si han estado almacenadas en sistemas de retención que se descarguen a un régimen moderado.', false, '2025-09-13 13:53:11.926159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cc35c91-4cce-4ddf-ae78-1b0482d2a951', '0100fb5f-8955-4202-9efc-cf0b569f2f93', 'c', 'A una distancia no superior a zona 7, si se utiliza algún sistema de retención por el que las aguas sucias se descarguen instantáneamente, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', true, '2025-09-13 13:53:11.926288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b4c5fb8-d223-4647-a330-c3c78fde4b5d', '0100fb5f-8955-4202-9efc-cf0b569f2f93', 'd', 'Fuera de zona 7, si las aguas sucias han estado almacenadas en algún sistema de retención que se descargue instantáneamente aprobado u homologado por la Administración Marítima española, hallándose la embarcación en ruta navegando a velocidad no superior a 4 nudos.', false, '2025-09-13 13:53:11.926416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b230883-5468-4d56-84dc-7e2656db285a', '6615ca4e-2bf3-46ba-b7b7-bf1b5ad38e65', 'a', 'Serán siempre de color blanco y su luz (si tiene) tendrá un ritmo de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:11.926684+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3ea196b-7ea3-4ff8-894c-ba749af5e17d', '6615ca4e-2bf3-46ba-b7b7-bf1b5ad38e65', 'b', 'Consistirán en franjas horizontales negras sobre blanco y su luz (si tiene) será de color amarillo.', false, '2025-09-13 13:53:11.926813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0848bbbd-eb41-4f35-8e8c-3d2ae5d01fc8', '6615ca4e-2bf3-46ba-b7b7-bf1b5ad38e65', 'c', 'Serán de color negro con una o varias anchas bandas diagonales rojas y su luz (si tiene) tendrá un ritmo de grupos de dos destellos GpD (2).', false, '2025-09-13 13:53:11.926941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfa76f24-30fd-4ea2-9a22-34455becad48', '6615ca4e-2bf3-46ba-b7b7-bf1b5ad38e65', 'd', 'Serán siempre de color rojo y blanco en franjas verticales y su luz (si tiene) será de color blanco.', true, '2025-09-13 13:53:11.927075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95d20b1a-ed33-405a-81b8-942e4847e7d7', '2e655824-6100-41dc-a433-41591a71f576', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la Marca.', false, '2025-09-13 13:53:11.927342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d41e5f4f-0776-46a8-bf40-442570a07bee', '2e655824-6100-41dc-a433-41591a71f576', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', true, '2025-09-13 13:53:11.927469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d21909fc-93b2-401c-8318-e9169b31aba4', '2e655824-6100-41dc-a433-41591a71f576', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.9276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51b17ebb-bcff-4499-ac25-b20675251d55', '2e655824-6100-41dc-a433-41591a71f576', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la Marca.', false, '2025-09-13 13:53:11.927725+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80bdff3c-1ed8-408f-9b58-1cedb78a553d', '56d07194-b98a-4ed3-9cb6-8a3d7cb7d841', 'a', 'De forma cónica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.927995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84fe9548-0481-4e46-a99e-7eb7a6d5dc5f', '56d07194-b98a-4ed3-9cb6-8a3d7cb7d841', 'b', 'De forma cónica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.928123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21453982-2494-462e-9b9d-62306ceddcd2', '56d07194-b98a-4ed3-9cb6-8a3d7cb7d841', 'c', 'De forma cilíndrica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.928249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7fc6a73-f5d4-4adf-bccc-325a7f2c08cb', '56d07194-b98a-4ed3-9cb6-8a3d7cb7d841', 'd', 'De forma cilíndrica de color verde con una banda ancha horizontal roja.', true, '2025-09-13 13:53:11.928376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05962b09-3970-4818-9d0d-99230c9a32a0', 'f1841758-34dd-457e-9764-ac989ff8fb9b', 'a', 'Roja y continua.', true, '2025-09-13 13:53:11.928643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecbc05f0-57a6-4daa-8d93-f11263c9872e', 'f1841758-34dd-457e-9764-ac989ff8fb9b', 'b', 'Blanca y destellos en grupo de dos.', false, '2025-09-13 13:53:11.928773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae1eda32-f6f2-4e87-b385-6383b6d0db49', 'f1841758-34dd-457e-9764-ac989ff8fb9b', 'c', 'Amarilla y ritmo centelleante rápido.', false, '2025-09-13 13:53:11.9289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b106f19-b2c1-4891-9ce0-52fefdefde4f', 'f1841758-34dd-457e-9764-ac989ff8fb9b', 'd', 'Verde con un destello largo cada diez segundos.', false, '2025-09-13 13:53:11.929026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9a1b43e-1c96-48c5-88bc-16a2c378b642', '25e8dc4b-8623-430d-886a-0c3fccf3431c', 'a', 'Su presencia conlleva para el navegante la necesidad de consultar la carta y las publicaciones náuticas porque indican una zona o configuración particular cuya naturaleza se indica en ellas.', false, '2025-09-13 13:53:11.92929+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3101fe04-3097-4126-9f46-204bea91967e', '25e8dc4b-8623-430d-886a-0c3fccf3431c', 'b', 'Tienen como objetivo principal señalar canales u obstrucciones e indicar zonas o configuraciones particulares de carácter especial.', false, '2025-09-13 13:53:11.929418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('041004ae-884e-4843-90d4-793426fef92e', '25e8dc4b-8623-430d-886a-0c3fccf3431c', 'c', 'Se utilizan para llamar la atención sobre una configuración especial de un canal, tal como un recodo una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.92955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01e9f183-c578-4bd1-adea-0a176fdf9586', '25e8dc4b-8623-430d-886a-0c3fccf3431c', 'd', 'Su uso principal es indicar el sentido convencional del balizamiento, que debe indicarse en los documentos náuticos apropiados, en zonas con una configuración especial. Reglamento (RIPA).', true, '2025-09-13 13:53:11.929678+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7dec06c-46fd-4059-962e-35a0b0954dcd', '30f8fb03-fe8e-409f-8cb2-e37e766d6dee', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:11.929961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('594fa33e-d027-460f-b822-9950f8f13872', '30f8fb03-fe8e-409f-8cb2-e37e766d6dee', 'b', 'Se deberá mantener el rumbo, ya que debe de ser el otro buque el que maniobre.', false, '2025-09-13 13:53:11.930092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46b9e774-ba8a-43b8-bb49-c3cba2196c11', '30f8fb03-fe8e-409f-8cb2-e37e766d6dee', 'c', 'Para la situación indicada no hay norma y por tanto se deberá tener en cuenta lo indicado para la situación de vuelta encontrada.', false, '2025-09-13 13:53:11.930218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7877ac1d-598a-4183-8830-27a461293134', '30f8fb03-fe8e-409f-8cb2-e37e766d6dee', 'd', 'Se deberá maniobrar para caer a estribor de forma que se pase por la banda de babor del velero', true, '2025-09-13 13:53:11.930345+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1aecb854-b666-460f-8c9e-aa6530ab84de', '19e5907f-94d0-4fc4-a099-73c8eead6f54', 'a', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', true, '2025-09-13 13:53:11.930614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08cbea56-a2ba-43e8-a559-0c2dcbd2577c', '19e5907f-94d0-4fc4-a099-73c8eead6f54', 'b', 'Las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:11.930741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e24ee1b1-f6db-44e2-b23c-30d462328005', '19e5907f-94d0-4fc4-a099-73c8eead6f54', 'c', 'Las luces de costado, una luz de alcance y una luz verde todo horizonte.', false, '2025-09-13 13:53:11.930875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d393e21c-03f2-495a-b220-1eb010108e3d', '19e5907f-94d0-4fc4-a099-73c8eead6f54', 'd', 'Dos luces blancas todo horizonte en línea vertical.', false, '2025-09-13 13:53:11.931001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62337cb6-3788-4ce4-8b18-ec9e4c109ded', 'e077c583-4496-4d72-b9bc-88e85ed5fa31', 'a', 'Una luz blanca colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:11.931277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcd1128c-603b-4009-a5af-6f5cb4155b04', 'e077c583-4496-4d72-b9bc-88e85ed5fa31', 'b', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz sin interrupción en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', false, '2025-09-13 13:53:11.931413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c71f272-7d6b-43a0-a2e2-fd68993a13d4', 'e077c583-4496-4d72-b9bc-88e85ed5fa31', 'c', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz centelleante en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', true, '2025-09-13 13:53:11.93155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2716a0c6-6ead-48bb-a242-64372f39157e', 'e077c583-4496-4d72-b9bc-88e85ed5fa31', 'd', 'Una luz amarilla colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:11.93168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('487fbe91-7dd6-4cf7-9c8a-e2f7f3910ecc', 'ca20f18f-768f-4bb6-8ec3-9d3798e23743', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:11.931957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64588a23-03fa-49ae-bf7e-a8727aef57f3', 'ca20f18f-768f-4bb6-8ec3-9d3798e23743', 'b', 'Cuando dos buques o embarcaciones, con independencia del tipo de propulsión que tengan, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.932093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d561c9f0-6cc3-4a06-80f8-c9b1ad75384a', 'ca20f18f-768f-4bb6-8ec3-9d3798e23743', 'c', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.932226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6cd72f1-07c0-479d-9079-7a38d6b00f70', 'ca20f18f-768f-4bb6-8ec3-9d3798e23743', 'd', 'Cuando dos buques o embarcaciones, con independencia del tipo que sean, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.932354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('271edf58-b651-4ebb-aac9-34e8f43bb1eb', 'bf2561c3-83ed-4eba-98c4-4bde2209f930', 'a', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:11.932622+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1b5b290-aa2b-48a1-8076-4725c4901526', 'bf2561c3-83ed-4eba-98c4-4bde2209f930', 'b', 'Únicamente una luz de tope a proa.', false, '2025-09-13 13:53:11.932753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0483e982-e984-477f-8626-3a0cb0086b92', 'bf2561c3-83ed-4eba-98c4-4bde2209f930', 'c', 'Únicamente una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.932888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecdb13e2-ef74-4d37-afa7-112a468a1c92', 'bf2561c3-83ed-4eba-98c4-4bde2209f930', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirán también luces de costado.', false, '2025-09-13 13:53:11.933014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('362793b1-cbf5-48d8-888c-bef8e0fc4e4b', '4c49f90a-6215-41e1-b96b-a491d7ba9c00', 'a', 'Dado que se trata de una situación de buque que alcanza, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:11.933307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15779daa-ef08-4ce6-8c67-11c962a7dd32', '4c49f90a-6215-41e1-b96b-a491d7ba9c00', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.933461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2f5a04f-5b3d-43ee-9aac-38597e60f101', '4c49f90a-6215-41e1-b96b-a491d7ba9c00', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', true, '2025-09-13 13:53:11.933602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f96824d3-7bcb-41be-a84d-b2982e86e4a1', '4c49f90a-6215-41e1-b96b-a491d7ba9c00', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:11.933733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7e6e398-6d33-4171-9b52-cfb63b32ad77', 'bc5e4a89-04f0-464d-b94e-a20c63ba152a', 'a', 'Dos luces de alcance en línea horizontal, de forma que quede señalizada la manga máxima del buque que remolca y del buque remolcado.', false, '2025-09-13 13:53:11.934017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c494e712-ee2c-4099-b17e-98a29ddba713', 'bc5e4a89-04f0-464d-b94e-a20c63ba152a', 'b', 'Dos luces de tope en línea vertical.', false, '2025-09-13 13:53:11.934147+00');
