INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf79ed49-94f3-47a6-9548-aab71b22b75a', 'd515fa43-e474-4616-8eeb-65efcaf9888d', 'b', 'Gira en el sentido de las agujas del reloj cuando la embarcación retrocede.', false, '2025-09-13 13:53:11.939082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('974e3e62-c635-4fa4-a6c9-931d4ac421c4', 'd515fa43-e474-4616-8eeb-65efcaf9888d', 'c', 'En marcha avante hace que la popa caiga a babor.', false, '2025-09-13 13:53:11.93921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('815430c2-796f-48a2-b1f7-1d149afd7bed', 'd515fa43-e474-4616-8eeb-65efcaf9888d', 'd', 'En marcha atrás hace que la popa caiga a estribor. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:11.939336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8db52658-500a-4f44-8d35-f26366704e38', 'e5b6dac6-deec-4afb-986e-2c7c64e4dfda', 'a', 'La gaza es el arco o curvatura que forma el cabo entre los extremos cuando éste no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:11.939619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('831050bf-f1c2-426e-8093-ed6a437c7bed', 'e5b6dac6-deec-4afb-986e-2c7c64e4dfda', 'b', 'El as de guía es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:11.939754+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d90da781-5ba7-4cf7-8207-74a5344826ac', 'e5b6dac6-deec-4afb-986e-2c7c64e4dfda', 'c', 'Un noray es una pieza de hierro, de forma cilíndrica ensanchada en su parte superior, fijada en los muelles para hacer firmes las amarras de los barcos.', true, '2025-09-13 13:53:11.939895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69f39c70-e082-4c88-8aea-df5bf9e8f8a3', '16bcd2c4-001c-461e-a664-23fd02f4b88b', 'a', 'Por el magnetismo que tiene cada aguja.', false, '2025-09-13 13:53:11.981751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8eed3dc-22d0-4059-9a01-e51480ce47a0', 'e5b6dac6-deec-4afb-986e-2c7c64e4dfda', 'd', 'Una boya es una pieza que se coloca en el costado de la embarcación para evitar que se dañe cuando está amarrada.', false, '2025-09-13 13:53:11.940025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3700214-baf1-4c91-ab46-cbd2bf562981', 'db702a7c-d343-42cc-a4fc-38810b899cd6', 'a', 'Nos acercaremos al lugar de fondeo elegido con el ancla a la pendura, dando la popa la viento y con velocidad de gobierno con arrancada.', false, '2025-09-13 13:53:11.940295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c957f137-da19-4a9d-82a4-a18f65dab12a', 'db702a7c-d343-42cc-a4fc-38810b899cd6', 'b', 'El punto de fondeo debe elegirse de forma que como mínimo se mantenga libre de obstáculos un círculo de radio igual a la longitud de la cadena filada más la eslora de la embarcación.', true, '2025-09-13 13:53:11.940431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a25b043b-9a2a-4b8f-82bd-20e4ab898346', 'db702a7c-d343-42cc-a4fc-38810b899cd6', 'c', 'Se utilizarán dos anclas, cuyos ángulos de fondeo formen un ángulo entre 60º y 120º.', false, '2025-09-13 13:53:11.940561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3861c495-3f70-44fa-9575-6158d9335a52', 'db702a7c-d343-42cc-a4fc-38810b899cd6', 'd', 'Se utilizarán dos anclas, una por proa y otra por popa.', false, '2025-09-13 13:53:11.940694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82f7c725-a590-4a02-b4e7-de410ee39539', 'affd7a2c-a3ab-4600-9e7a-c025315c3ced', 'a', 'La temperatura del aceite.', false, '2025-09-13 13:53:11.940971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86d960f1-02eb-45af-85c7-9e97b94e4ee1', 'affd7a2c-a3ab-4600-9e7a-c025315c3ced', 'b', 'La temperatura del combustible.', false, '2025-09-13 13:53:11.941101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('579e7ff8-bf5a-4b06-b73b-61dbef141f86', 'affd7a2c-a3ab-4600-9e7a-c025315c3ced', 'c', 'El pararrayos.', false, '2025-09-13 13:53:11.941231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c9e0ee5-c36e-47b7-b352-0eec4a4ff534', 'affd7a2c-a3ab-4600-9e7a-c025315c3ced', 'd', 'El desvío de la aguja.', true, '2025-09-13 13:53:11.941362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83e6d605-d9a7-46fe-b94c-abd07894cb31', '436436a8-e12f-476b-80d2-e3eccdf988d7', 'a', 'En llevar la mar por la aleta, navegando a una velocidad que evite sincronizarse con las olas.', true, '2025-09-13 13:53:11.941638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a46e301-604a-4b8b-8ad9-3a037cfc5576', '436436a8-e12f-476b-80d2-e3eccdf988d7', 'b', 'En llevar la mar por la amura, navegando a una velocidad reducida para sincronizarse con las', false, '2025-09-13 13:53:11.941791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f35c403-15f8-4c91-afbd-cfef4195141b', '436436a8-e12f-476b-80d2-e3eccdf988d7', 'c', 'En llevar la mar por la amura, navegando a una velocidad que evite sincronizarse con las olas.', false, '2025-09-13 13:53:11.941949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('758076ec-2126-4f44-ad9c-f8d9ad2c4dbd', '436436a8-e12f-476b-80d2-e3eccdf988d7', 'd', 'En llevar la mar por la aleta, navegando a una velocidad reducida para sincronizarse con las olas.', false, '2025-09-13 13:53:11.942086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c70347e-b209-458c-8457-1b31be5091a8', 'b2277c61-64a9-4c24-b0ec-87fe7114c2c2', 'a', '36º C.', false, '2025-09-13 13:53:11.942362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67422fd7-3138-4569-a0cf-47d7d968d8e6', 'b2277c61-64a9-4c24-b0ec-87fe7114c2c2', 'b', '35º C.', true, '2025-09-13 13:53:11.942491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d17d7725-d944-42b4-96d9-608cf54de50e', 'b2277c61-64a9-4c24-b0ec-87fe7114c2c2', 'c', '33º C.', false, '2025-09-13 13:53:11.942618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd0d853f-5017-45dd-8568-2031476a05bf', 'b2277c61-64a9-4c24-b0ec-87fe7114c2c2', 'd', '32º C.', false, '2025-09-13 13:53:11.942748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c43a7708-5742-4192-96e4-b7f8d85f352c', '915db695-d69d-40f2-87de-10174109f06f', 'a', 'Llevar la máxima velocidad disponible.', false, '2025-09-13 13:53:11.943045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e24eda51-51f2-4f1f-a538-4b78d82aa159', '915db695-d69d-40f2-87de-10174109f06f', 'b', 'Llevar un ancla lista para fondear.', true, '2025-09-13 13:53:11.943175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('887f3fae-c4f2-435d-b4d9-4fdeaad7998c', '915db695-d69d-40f2-87de-10174109f06f', 'c', 'Gobernar con poco timón, procurando no levantarlo en ningún momento.', false, '2025-09-13 13:53:11.943305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ef96715-5fe9-4bfa-92f0-307d0717ee78', '915db695-d69d-40f2-87de-10174109f06f', 'd', 'Al maniobrar a un barco que navegue de “vuelta encontrada”, hacerlo inmediatamente metiendo', false, '2025-09-13 13:53:11.943438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfd5d376-cd18-4e1d-b7eb-26b52805e7bb', '0367b05e-bc12-42d3-961e-7a7e56650794', 'a', 'A una distancia superior a 3 millas náuticas de la tierra más próxima si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema dotado de medios que permitan almacenarlas temporalmente, siempre que sea aprobado u homologado por la Administración Marítima española.', true, '2025-09-13 13:53:11.943711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9437678-c5ea-4451-9590-3bcdc522949a', '0367b05e-bc12-42d3-961e-7a7e56650794', 'b', 'A una distancia superior a 3 millas náuticas e inferior a 12 millas náuticas de la tierra más próxima, hayan sido o no previamente desmenuzadas y desinfectadas, si han estado almacenadas en sistemas de retención que se descarguen a un régimen moderado.', false, '2025-09-13 13:53:11.943852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a12135dd-cf4b-43f3-ac33-1854417fb3ae', '0367b05e-bc12-42d3-961e-7a7e56650794', 'c', 'A una distancia no superior a zona 7, si se utiliza algún sistema de retención por el que las aguas sucias se descarguen instantáneamente, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', false, '2025-09-13 13:53:11.943994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('559f4d76-570f-447a-873d-e10ab4b38bf8', '0367b05e-bc12-42d3-961e-7a7e56650794', 'd', 'Fuera de zona 7, si las aguas sucias han estado almacenadas en algún sistema de retención que se descargue instantáneamente aprobado u homologado por la Administración Marítima española, hallándose la embarcación en ruta navegando a velocidad no superior a 4 nudos.', false, '2025-09-13 13:53:11.944125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e993f0c-d6db-4f2b-a428-4e20b0fb7e4e', '331870ee-076e-450c-8fa6-31516d48ed79', 'a', 'Está prohibida en todo caso, sin que quepa excepción alguna.', false, '2025-09-13 13:53:11.944395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dfc0c87-ccc3-4196-b145-ac0874bd1cb3', '331870ee-076e-450c-8fa6-31516d48ed79', 'b', 'Está permitida si se realiza a menos de 12 millas marinas de la tierra más próxima y siempre que no esté contaminado con otro tipo de basuras.', false, '2025-09-13 13:53:11.94453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b96348b2-d3bc-44a9-aa2c-091cc03445e5', '331870ee-076e-450c-8fa6-31516d48ed79', 'c', 'Está prohibida a no ser que se deba a una pérdida accidental de basuras resultante de una avería y se hubieran tomado toda suerte de precauciones razonables para impedir o reducir a un mínimo tal', true, '2025-09-13 13:53:11.944657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6814c98b-c0d6-46ca-aeb8-b0a5a063d700', '331870ee-076e-450c-8fa6-31516d48ed79', 'd', 'Está permitida siempre que se realice a más de 12 millas marinas de la tierra más próxima, mientras la embarcación no se encuentre en ruta y junto a los demás desechos de alimentos que deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:11.944793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ece09423-0137-46ea-aece-aeee93988b7a', '1c82483b-d040-423b-ae94-8b337308e1d3', 'a', 'De forma cónica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.945085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd4e2cd8-04f6-4a18-a75d-f164dd2e479e', '1c82483b-d040-423b-ae94-8b337308e1d3', 'b', 'De forma cónica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.945223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('886208b0-78f8-43d6-a2b6-120cf8b2b850', '1c82483b-d040-423b-ae94-8b337308e1d3', 'c', 'De forma cilíndrica de color rojo con una banda ancha horizontal verde.', true, '2025-09-13 13:53:11.945356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85a3a1cf-6a44-4baf-871f-54b5ea092221', '1c82483b-d040-423b-ae94-8b337308e1d3', 'd', 'De forma cilíndrica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.945487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a17d5c1e-2ddd-4046-b8c1-246a6dfc9a3e', 'dfdd6411-51ec-45a6-95db-95b81c40a842', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la Marca.', false, '2025-09-13 13:53:11.945769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b55c774-2ece-42a0-b7a9-f439b232f33e', 'dfdd6411-51ec-45a6-95db-95b81c40a842', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:11.945927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a2ad09f-7cca-4087-9419-97c2ff9129a4', 'dfdd6411-51ec-45a6-95db-95b81c40a842', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.946093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a30dec2-ae52-4c14-abd8-f2a5140cd435', 'dfdd6411-51ec-45a6-95db-95b81c40a842', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la Marca.', true, '2025-09-13 13:53:11.946237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed5cbb1c-dd42-4275-9773-4a6f1365991b', 'c6134385-b4f4-4b80-b767-cef8ff6cf774', 'a', 'Roja y continua.', false, '2025-09-13 13:53:11.946531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19d7541f-5fb6-41d5-9e78-d8751655308c', 'c6134385-b4f4-4b80-b767-cef8ff6cf774', 'b', 'Blanca y destellos en grupo de dos.', true, '2025-09-13 13:53:11.946673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27f2f6cf-c9fb-4acb-8d97-4b060df34e9d', 'c6134385-b4f4-4b80-b767-cef8ff6cf774', 'c', 'Amarilla y ritmo centelleante rápido.', false, '2025-09-13 13:53:11.946815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90042398-46d8-4c1b-bdd2-de55378b683a', 'c6134385-b4f4-4b80-b767-cef8ff6cf774', 'd', 'Verde con un destello largo cada diez segundos.', false, '2025-09-13 13:53:11.946952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5542ea63-2ddf-48b8-b39f-e1df9927076c', '38ad1d49-17ed-4df4-9d8a-0d2a7fed83ae', 'a', 'Su presencia conlleva para el navegante la necesidad de consultar la carta y las publicaciones náuticas porque indican una zona o configuración particular cuya naturaleza se indica en ellas.', true, '2025-09-13 13:53:11.947237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5abeda1f-e8da-4db4-8095-5316fc614f50', '38ad1d49-17ed-4df4-9d8a-0d2a7fed83ae', 'b', 'Tienen como objetivo principal señalar canales u obstrucciones e indicar zonas o configuraciones particulares de carácter especial.', false, '2025-09-13 13:53:11.947377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2be837f0-cdcb-49de-a394-547a95b8cd72', '38ad1d49-17ed-4df4-9d8a-0d2a7fed83ae', 'c', 'Se utilizan para llamar la atención sobre una configuración especial de un canal, tal como un recodo una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:11.947513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd126555-1667-4fa9-891e-0f308ab54979', '38ad1d49-17ed-4df4-9d8a-0d2a7fed83ae', 'd', 'Su uso principal es indicar el sentido convencional del balizamiento, que debe indicarse en los documentos náuticos apropiados, en zonas con una configuración especial.', false, '2025-09-13 13:53:11.947649+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19f22e15-989f-429c-9469-b9fd6bf64f2a', 'f6411cff-5c4c-4241-aba6-e46d32398477', 'a', 'Serán siempre de color blanco y su luz (si tiene) tendrá un ritmo de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:11.947948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bc3ed59-61a1-496a-a8e8-a519ddd3ae51', 'f6411cff-5c4c-4241-aba6-e46d32398477', 'b', 'Consistirán en franjas horizontales negras sobre blanco y su luz (si tiene) será de color amarillo.', false, '2025-09-13 13:53:11.948089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f63fe75-b798-4208-b44a-0c5270e477d0', 'f6411cff-5c4c-4241-aba6-e46d32398477', 'c', 'Serán de color negro con una o varias anchas bandas diagonales rojas y su luz (si tiene) tendrá un ritmo de grupos de dos destellos GpD (2).', false, '2025-09-13 13:53:11.948232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b06d2cb-5e43-4ae6-bd5e-48d6ce7a9e7a', 'f6411cff-5c4c-4241-aba6-e46d32398477', 'd', 'Serán siempre de color rojo y blanco en franjas verticales y su luz (si tiene) será de color blanco. Reglamento (RIPA).', true, '2025-09-13 13:53:11.948367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4ebabac-0ba1-4af0-9f5f-9026799f8786', '1acfae6b-73dc-44b7-9cb1-e494a80b3bd0', 'a', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', false, '2025-09-13 13:53:11.948656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfccfcf6-2658-4083-acfa-e49280d851d8', '1acfae6b-73dc-44b7-9cb1-e494a80b3bd0', 'b', 'Las luces de costado y una luz de alcance.', true, '2025-09-13 13:53:11.948804+00');
