INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ab4d628-6a15-48a1-bde8-1dd19d56f62e', 'd10c0382-aee2-4a74-8bb5-265fd24dcf2a', 'c', 'Principalmente la velocidad del buque que se aproxima está por encima de la velocidad de', false, '2025-09-13 13:53:11.949639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c96231a-7721-4a19-a73c-e81febaadc4e', 'd10c0382-aee2-4a74-8bb5-265fd24dcf2a', 'd', 'La demora del buque que se aleja varía en forma apreciable.', false, '2025-09-13 13:53:11.949781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86bd4e35-ad94-4c72-af7f-c8396adf58cf', '12381f04-5ad9-42be-8111-b9955abd383d', 'a', 'A intervalos que no excedan de dos minutos, dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:11.950064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91171214-cc2d-40b5-ad5e-52c2a90c7f32', '12381f04-5ad9-42be-8111-b9955abd383d', 'b', 'A intervalos que no excedan de dos minutos, dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:11.950199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee29b6f7-ff29-4aec-9c5a-32fe91005312', '12381f04-5ad9-42be-8111-b9955abd383d', 'c', 'Una pitada larga a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:11.950332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('648e30ea-7aba-4943-bd09-3fdcd2136f83', '12381f04-5ad9-42be-8111-b9955abd383d', 'd', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:11.950467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4161ae7d-6906-467d-9f7c-27a211bbcc5e', '4c79ece9-28b7-4e3d-b48b-984109210527', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:11.950747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d62fc81c-5513-4162-9cd1-35406a703ddc', '4c79ece9-28b7-4e3d-b48b-984109210527', 'b', 'Cuando dos buques o embarcaciones, con independencia del tipo de propulsión que tengan, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.950902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a49d7b4-6c83-493a-b6f7-a516bcd98ea9', '4c79ece9-28b7-4e3d-b48b-984109210527', 'c', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.951036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cac92c4-3c95-4b9b-a75a-cf51060d80b8', '4c79ece9-28b7-4e3d-b48b-984109210527', 'd', 'Cuando dos buques o embarcaciones, con independencia del tipo que sean, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:11.951173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a952b1d-d24d-41e3-9eeb-fe661efd3bb6', 'f5426ef5-eb82-470d-8b37-eb4aab173390', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:11.951452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59775acc-b0e0-46fa-92ee-f202ba28b354', 'f5426ef5-eb82-470d-8b37-eb4aab173390', 'b', 'Se deberá mantener el rumbo, ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:11.951586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('838aaab5-8ab6-4ace-95e6-695a2791c49c', 'f5426ef5-eb82-470d-8b37-eb4aab173390', 'c', 'Para la situación indicada no hay norma y por tanto se deberá tener en cuenta lo indicado para la situación de vuelta encontrada.', false, '2025-09-13 13:53:11.951718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbb21c28-4fe6-4e9e-99f6-d4bb249f304b', 'f5426ef5-eb82-470d-8b37-eb4aab173390', 'd', 'Se deberá maniobrar para caer a estribor de forma que se pase por la banda de babor del velero', false, '2025-09-13 13:53:11.951878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1530d97-3e87-4e0a-a07d-166aa657a73f', 'fee8a5ed-32ec-427a-a832-fa0a0e9034ab', 'a', 'Dado que se trata de una situación de buque que alcanza, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:11.952171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eb0e9b3-30e3-4366-8352-fbf224387f9d', 'fee8a5ed-32ec-427a-a832-fa0a0e9034ab', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:11.952303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a5275ce-93ba-401b-b3ed-429f24d0e56e', 'fee8a5ed-32ec-427a-a832-fa0a0e9034ab', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:11.952433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a2183f7-c67e-41c1-bc6a-01ff5b1d1e8b', 'fee8a5ed-32ec-427a-a832-fa0a0e9034ab', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', true, '2025-09-13 13:53:11.952563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4141ab0-2904-46a1-9479-9e2cc267f1cc', 'aa7f5b12-8235-425f-a29b-95c746dfc29d', 'a', 'Una luz blanca colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:11.952849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8251519-7172-47ba-a843-655d2d51f026', 'aa7f5b12-8235-425f-a29b-95c746dfc29d', 'b', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz sin interrupción en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', true, '2025-09-13 13:53:11.952987+00');
