INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffbf9340-a1f0-4201-8311-5d34c3eb0ace', 'efd98d4e-bf2c-45de-bd72-1aebc38af092', 'a', 'El ballestrinque es un nudo que permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:11.958582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c46aec8-ff2a-4585-a37a-0077a3774670', 'efd98d4e-bf2c-45de-bd72-1aebc38af092', 'b', 'Un noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', true, '2025-09-13 13:53:11.958712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3577446-ea41-41a3-8280-3fe115ad6f37', 'efd98d4e-bf2c-45de-bd72-1aebc38af092', 'c', 'Una boya es un cuerpo flotante sujeto al fondo del mar mediante un lastre, que se coloca para amarrar una embarcación o como elemento de señalización.', false, '2025-09-13 13:53:11.95885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0621e476-baee-486c-abc7-0eea422a28ee', 'efd98d4e-bf2c-45de-bd72-1aebc38af092', 'd', 'El bichero es el extremo libre de un cabo.', false, '2025-09-13 13:53:11.958981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6cb74b0e-708f-42d1-ac8b-1de6c9aa767e', '3ac9740b-2c5c-46b4-81ef-1b1b12a2095d', 'a', 'La embarcación debe disponer de una línea de fondeo cuya longitud será como mínimo cuatro veces la eslora de la embarcación.', true, '2025-09-13 13:53:11.959251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1615fcba-5c3a-400d-9b5f-70a16f505d64', '3ac9740b-2c5c-46b4-81ef-1b1b12a2095d', 'b', 'Hay que tomar referencias a tierra para asegurarnos que el ancla no garrea, y vigilar la sonda marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:11.95938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c882632d-3de1-4136-ba55-7abd558d7a22', '3ac9740b-2c5c-46b4-81ef-1b1b12a2095d', 'c', 'Se utilizará el orinque para medir la profundidad y conocer el tipo de fondo.', false, '2025-09-13 13:53:11.959509+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99edf555-d08c-4129-8689-03e90cf93ca2', '3ac9740b-2c5c-46b4-81ef-1b1b12a2095d', 'd', 'Se elegirá un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:11.959637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43444971-b65c-4c05-98e8-7965039c7146', '7895c56b-67ba-4150-92b0-05cf38eca7b8', 'a', 'No es obligatorio llevar señales de socorro.', false, '2025-09-13 13:53:11.959933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a24b83e4-c027-49ca-8a40-db251e891ce8', '7895c56b-67ba-4150-92b0-05cf38eca7b8', 'b', '6 bengalas de mano y 3 cohetes con luz roja y paracaídas.', false, '2025-09-13 13:53:11.960068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d741baf-1d2e-4c39-898f-c0ef51a1e10f', '7895c56b-67ba-4150-92b0-05cf38eca7b8', 'c', '3 bengalas de mano y 3 cohetes con luz roja y paracaídas.', true, '2025-09-13 13:53:11.960207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c54fdc4-c4cf-44cd-b463-d6778c33c13c', '7895c56b-67ba-4150-92b0-05cf38eca7b8', 'd', 'Sólo 3 bengalas de mano.', false, '2025-09-13 13:53:11.960336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98a6478e-7636-4733-b08d-4bf228775484', 'e0c2950b-09a0-48f0-a83e-3cdc7f4f4ac1', 'a', 'Sólo en embarcaciones con casco metálico.', false, '2025-09-13 13:53:11.960612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beb0d00c-90f5-4a82-812e-b9021aebcde9', 'e0c2950b-09a0-48f0-a83e-3cdc7f4f4ac1', 'b', 'En todas las embarcaciones de recreo.', false, '2025-09-13 13:53:11.960742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13203b4d-e190-4a91-a9cc-d507f145dc23', 'e0c2950b-09a0-48f0-a83e-3cdc7f4f4ac1', 'c', 'En embarcaciones con casco de madera o fibra.', true, '2025-09-13 13:53:11.96088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c66689d2-5891-4179-88f9-6d5898f9dab2', 'e0c2950b-09a0-48f0-a83e-3cdc7f4f4ac1', 'd', 'Sólo en embarcaciones con casco de madera.', false, '2025-09-13 13:53:11.961011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd3fc172-7242-4246-9c00-7838d8da087f', '58dbd210-d9aa-4b10-bb1c-4c966ee39548', 'a', 'Meter el timón inmediatamente a la banda contraria donde ha caído el náufrago para iniciar la maniobra de Anderson o Boutakow.', true, '2025-09-13 13:53:11.961313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dadc1443-568e-482a-973b-2618ac350047', '58dbd210-d9aa-4b10-bb1c-4c966ee39548', 'b', 'Detener inmediatamente la máquina o ponerla en punto muerto.', false, '2025-09-13 13:53:11.961446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9115354c-e574-4565-98ea-89735ddb75bc', '58dbd210-d9aa-4b10-bb1c-4c966ee39548', 'c', 'Hacer una llamada de emergencia.', false, '2025-09-13 13:53:11.961574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc812863-1de0-463f-b29d-f4ec3e591f8d', '58dbd210-d9aa-4b10-bb1c-4c966ee39548', 'd', 'Pulsar el botón “Distress” de la LSD si perdemos de vista al náufrago.', false, '2025-09-13 13:53:11.961703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66330328-33cd-48bf-9529-53778e9be747', '586f47ef-4429-4a87-b889-d35433e108ea', 'a', 'Mantener o recuperar la posición de adrizado.', false, '2025-09-13 13:53:11.962008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa0ae4a8-84d0-47a5-8a1c-8da1d78ca0e5', '586f47ef-4429-4a87-b889-d35433e108ea', 'b', 'Mantener o recuperar el asiento o el trimado.', true, '2025-09-13 13:53:11.962138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a48b6ac-3499-4687-b03d-7e0bfa38b221', '586f47ef-4429-4a87-b889-d35433e108ea', 'c', 'Mantener la escora en un ángulo igual o menor a 15º.', false, '2025-09-13 13:53:11.962268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1f8333a-d05d-4457-b882-24877ce70ea8', '586f47ef-4429-4a87-b889-d35433e108ea', 'd', 'Mantener el francobordo.', false, '2025-09-13 13:53:11.962397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80a76280-392e-4341-9da0-f7fa33dc9ad0', '18ec2cc9-3b02-4290-a1c5-e8a47a0592bb', 'a', 'No se permitirá la descarga de productos avícolas introducidos, incluidas las aves o partes de aves, si dichos productos se han tratado para su esterilización.', false, '2025-09-13 13:53:11.962672+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d246c511-d6cc-4ef8-addc-e582a7ad3a9b', '18ec2cc9-3b02-4290-a1c5-e8a47a0592bb', 'b', 'Sólo se podrá descargar materia plástica que se haya pasado por un desmenuzador o triturador, de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:11.962803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1660406-13bc-441e-9e59-7cbf48acc2da', '18ec2cc9-3b02-4290-a1c5-e8a47a0592bb', 'd', 'En ningún caso se hará a menos de tres millas marinas de la tierra más próxima en el caso de desechos de alimentos que se hayan pasado por un desmenuzador o triturador, de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:11.963081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90268d27-f661-4fec-814c-59529f2c6d7c', 'bcd74ae2-6e30-45d5-8fd5-850304294061', 'a', 'Disponga de depósitos de retención fijos con una conexión universal a tierra.', false, '2025-09-13 13:53:11.963365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('600bb135-1546-442c-bb8c-15541c6436ec', 'bcd74ae2-6e30-45d5-8fd5-850304294061', 'c', 'Efectúe la descarga fuera de zona 7, utilizando una instalación de tratamiento de aguas sucias.', false, '2025-09-13 13:53:11.963628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b3498d7-d1d3-4c14-952d-7261f624a7c6', '503f5113-fb81-40e9-b4a2-1194d9829126', 'd', 'El cero hidrográfico.', false, '2025-09-13 13:53:11.981479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daf5bb3c-cb54-4ea4-adea-142f4bf1950b', 'bcd74ae2-6e30-45d5-8fd5-850304294061', 'b', 'Efectúe la descarga saliendo de zona 7, a través de un inodoro que disponga de una instalación certificada.', false, '2025-09-13 13:53:11.963496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40052ce2-ace2-4cac-a99b-1a4371eb0563', 'fbe6122f-6658-4360-942c-b5700866e6ed', 'd', 'Dejar clara el ancla.', true, '2025-09-13 13:53:11.958307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9cf8a36-9247-4d08-b742-adf608414a7e', '18ec2cc9-3b02-4290-a1c5-e8a47a0592bb', 'c', 'Únicamente se permitirá la descarga de residuos de carga a menos de.', true, '2025-09-13 13:53:11.962934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d00d5b7c-c859-4093-8e55-d30c289ccef0', '53ec21d1-a77c-4a33-bfdc-693247339365', 'a', 'Se coloca próxima o sobre aguas navegables rodeadas por todas partes de un peligro.', false, '2025-09-13 13:53:11.964038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b0f817e-8e4c-4312-83a6-ffe77dc75ebf', '53ec21d1-a77c-4a33-bfdc-693247339365', 'b', 'Según el ritmo y color de su luz especifican el tamaño del peligro y la distancia a la que puede utilizarse con seguridad la embarcación.', false, '2025-09-13 13:53:11.964175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80bae39f-9f5f-4bdd-9582-4ed2ba9c8c6b', '53ec21d1-a77c-4a33-bfdc-693247339365', 'c', 'Es negra, con una o más bandas anchas horizontales rojas. Su marca de tope está formada por dos conos negros superpuestos y la luz es blanca.', true, '2025-09-13 13:53:11.964311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e5e0eec-82ea-47b5-a6f9-fb5830da2282', '53ec21d1-a77c-4a33-bfdc-693247339365', 'd', 'Su presencia obliga al navegante a consultar la carta y las publicaciones náuticas.', false, '2025-09-13 13:53:11.964445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a66e99b-d906-4e9d-b496-783aec5d62e4', 'c154fbe1-5bed-4658-b1bf-060f69ca791f', 'b', 'Pueden incluir un pictograma para indicar su objetivo, utilizando la simbología apropiada de la Organización Hidrográfica Internacional.', false, '2025-09-13 13:53:11.964895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f965fb5a-70d6-48c6-9e55-60503c758307', 'c154fbe1-5bed-4658-b1bf-060f69ca791f', 'c', 'Su marca de tope es amarilla en forma de cruz vertical.', false, '2025-09-13 13:53:11.965065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfd251a4-98fa-4224-bab4-c23430ad5389', 'c154fbe1-5bed-4658-b1bf-060f69ca791f', 'd', 'Su forma es de libre elección entre esférica, de castillete o espeque, pero siempre con una marca de tope en forma de cruz vertical.', true, '2025-09-13 13:53:11.965205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2147f785-b559-4c1c-8be4-e498c4791de4', '7c1f295b-1b0c-4341-9873-4af8d233103e', 'a', 'Grupos de 3 centelleos rápidos cada 5 segundos.', false, '2025-09-13 13:53:11.965485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c14deb9-c819-4b7f-9ae8-5476b56f52f7', '7c1f295b-1b0c-4341-9873-4af8d233103e', 'b', 'Grupos de 9 centelleos rápidos cada 10 segundos.', false, '2025-09-13 13:53:11.965615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ef58693-a242-4c42-b513-f920ab9c4c63', '7c1f295b-1b0c-4341-9873-4af8d233103e', 'c', 'Grupos de 6 centelleos rápidos cada 10 segundos.', false, '2025-09-13 13:53:11.965744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d35bf1b-eefd-4d7c-82a3-6d3c94223f6a', '7c1f295b-1b0c-4341-9873-4af8d233103e', 'd', 'Centelleos rápidos.', true, '2025-09-13 13:53:11.965905+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f90720cf-ab33-4fea-a896-0c2b526164e7', '9435d138-35b1-4c81-85a8-88f464b1afd0', 'a', 'Se aproxima a un puerto, río, estuario u otra vía acuática desde el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección contraria a la de las agujas del reloj alrededor de las masas de tierra.', false, '2025-09-13 13:53:11.966189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adf1746d-eb8e-409a-b7ea-ce46c9185c3e', '9435d138-35b1-4c81-85a8-88f464b1afd0', 'b', 'Se aproxima a un puerto, río, estuario u otra vía acuática desde el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección de las agujas del reloj alrededor de las masas de tierra.', false, '2025-09-13 13:53:11.966327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58a2b0f9-17e2-41cd-86c9-2763ae532142', '9435d138-35b1-4c81-85a8-88f464b1afd0', 'c', 'Se aleja de un puerto, río, estuario u otra vía acuática hacia el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección contraria a la de las agujas del reloj alrededor de las masas de tierra.', false, '2025-09-13 13:53:11.966457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45ff10e6-7b0b-4698-bbb1-633e1c4ebbff', '9435d138-35b1-4c81-85a8-88f464b1afd0', 'd', 'Se aleja de un puerto, río, estuario u otra vía acuática hacia el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección de las agujas del reloj alrededor de las masas', true, '2025-09-13 13:53:11.966586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8a92fee-f76d-4da9-9dc0-921976e45154', '1d0b3e42-98bb-4b32-8376-4c592cb76508', 'a', 'Una luz de tope a proa.', false, '2025-09-13 13:53:11.967519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3322ebe6-a8be-4eb9-b73a-fd74ebcf2c66', '1d0b3e42-98bb-4b32-8376-4c592cb76508', 'b', 'Una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:11.967648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98da3d7b-1086-4296-b781-f09b44348145', '1d0b3e42-98bb-4b32-8376-4c592cb76508', 'c', 'Una luz de alcance.', false, '2025-09-13 13:53:11.967786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60e78210-ace6-4502-b613-61547af6b000', '1d0b3e42-98bb-4b32-8376-4c592cb76508', 'd', 'Una luz blanca todo horizonte.', false, '2025-09-13 13:53:11.967925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('172daeaf-f0ba-4d86-b53e-a66f2ce4420d', '4c59eee1-582f-4a32-b96c-30fe999395e7', 'a', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea inferior a 7 metros.', false, '2025-09-13 13:53:11.968199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('035287ae-78ee-4551-bcfa-823c2bab548b', '4c59eee1-582f-4a32-b96c-30fe999395e7', 'b', 'Cuando la longitud del remolque, medido desde la popa del buque que remolca hasta el extremo de popa del remolque, sea inferior a 15 metros.', true, '2025-09-13 13:53:11.968337+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19f55f44-e2dc-4c9c-a77b-021d52ad4a6f', '4c59eee1-582f-4a32-b96c-30fe999395e7', 'c', 'Cuando estén unidos mediante cualquier tipo de conexión.', false, '2025-09-13 13:53:11.968473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ead0baf3-4cf9-43a8-b6f9-8543627e6c95', '4c59eee1-582f-4a32-b96c-30fe999395e7', 'd', 'Cuando estén unidos mediante una conexión rígida.', false, '2025-09-13 13:53:11.968601+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76c4d67a-8bf5-4420-9cdc-bdd77dcdc4bb', '5ab1947d-79e5-4985-9b6d-ca749af9f834', 'a', 'Siempre, si navegamos en buques de más de 24 metros de eslora. Se trata de una acción potestativa para el resto de buques.', true, '2025-09-13 13:53:11.968925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('570389d8-da83-4fda-90c0-81085c1fbc54', '5ab1947d-79e5-4985-9b6d-ca749af9f834', 'b', 'Se trata de una acción potestativa para todos los buques.', false, '2025-09-13 13:53:11.969076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da159773-7b24-48f7-9b24-774b6f3156f8', '5ab1947d-79e5-4985-9b6d-ca749af9f834', 'c', 'Siempre, si estamos realizando navegación nocturna.', false, '2025-09-13 13:53:11.969214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fd75e8f-34d8-4f86-9e55-060bf1b087c4', '5ab1947d-79e5-4985-9b6d-ca749af9f834', 'd', 'Siempre.', false, '2025-09-13 13:53:11.969344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('580e0e09-278d-4a15-a3f0-3c0f3488c944', '9a8c1cfa-371a-44e6-af9e-2df5963bddf4', 'a', 'Luces de costado y una luz de remolque.', true, '2025-09-13 13:53:11.969626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f18f0e59-dd49-4a6b-8223-a321e330361b', '9a8c1cfa-371a-44e6-af9e-2df5963bddf4', 'b', 'Una luz de tope y una luz de remolque.', false, '2025-09-13 13:53:11.969771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('291eb77e-426a-4795-841a-9323af30c6dc', '9a8c1cfa-371a-44e6-af9e-2df5963bddf4', 'c', 'Un farol que combine las luces de costado y una luz de tope.', false, '2025-09-13 13:53:11.969924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb81cdca-f6b4-40e0-8948-4ac2d6cf0985', '9a8c1cfa-371a-44e6-af9e-2df5963bddf4', 'd', 'Una luz de alcance y las luces de costado.', false, '2025-09-13 13:53:11.970093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7487c00d-c23d-4860-b8d7-e96c61757109', 'fb5d168b-5747-499f-a12e-2d46d7cc4a10', 'a', 'Popa viendo la luz de tope blanca y ambas luces de costado.', true, '2025-09-13 13:53:11.970432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3263bf3c-0933-4e37-91fc-c5a723159e17', 'fb5d168b-5747-499f-a12e-2d46d7cc4a10', 'b', 'Popa viendo la luz de alcance.', false, '2025-09-13 13:53:11.970592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d16d3671-dba7-49aa-b2a7-10057d5d1ec6', 'fb5d168b-5747-499f-a12e-2d46d7cc4a10', 'c', 'Proa viendo la luz de alcance y la verde de costado.', false, '2025-09-13 13:53:11.97075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0436435e-7a8f-4fe8-abff-574f7a9a7dbc', 'fb5d168b-5747-499f-a12e-2d46d7cc4a10', 'd', 'Proa viendo la luz de tope y la roja de costado.', false, '2025-09-13 13:53:11.97092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a66bc86a-c43a-4711-aa45-05e6e39f6064', 'b9fe7fef-98e8-4632-9779-ac70d61d7181', 'a', 'Amarillo con un cuadrado verde y un círculo.', false, '2025-09-13 13:53:11.971216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('918ce8a3-d37b-4b9e-9573-ed6ea1171a66', 'b9fe7fef-98e8-4632-9779-ac70d61d7181', 'b', 'Rojo con un cuadrado amarillo y un círculo.', false, '2025-09-13 13:53:11.971347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12f10ca7-c427-4638-b08d-c767d475226f', 'b9fe7fef-98e8-4632-9779-ac70d61d7181', 'c', 'Verde con un cuadrado rojo y un círculo.', false, '2025-09-13 13:53:11.971477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('572892fb-e884-4d04-aae5-f60d1f896551', 'b9fe7fef-98e8-4632-9779-ac70d61d7181', 'd', 'Naranja con un cuadrado negro y un círculo.', true, '2025-09-13 13:53:11.971609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52c64669-07dd-4bc8-ad3b-174192320c7d', 'a531bbf8-5132-407c-b3b0-0dd13e9b53bc', 'a', 'Cuando uno de los dos buques deba mantenerse apartado de la derrota del otro, este último mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:11.971898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dc7cf78-a506-40bb-b9e7-547d41fda276', 'a531bbf8-5132-407c-b3b0-0dd13e9b53bc', 'b', 'Cuando, por cualquier causa, el buque que haya de mantener su rumbo y velocidad se encuentre tan próximo al otro que no pueda evitarse el abordaje por la sola maniobra del buque que cede el paso, el primero ejecutará la maniobra que mejor pueda ayudar a evitar el abordaje.', false, '2025-09-13 13:53:11.972029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ff5eb23-8df4-47c1-add5-06e8bff55926', 'a531bbf8-5132-407c-b3b0-0dd13e9b53bc', 'c', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, no cambiará su rumbo a babor para maniobrar a un buque que se encuentre por esa misma banda si las circunstancias del caso lo permiten.', true, '2025-09-13 13:53:11.97216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb6bc7e4-48ae-4a28-a7f4-1ce16c45aad9', 'a531bbf8-5132-407c-b3b0-0dd13e9b53bc', 'd', 'La presente Regla exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', false, '2025-09-13 13:53:11.97229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fce1e05-6dc9-4ebd-a996-0af31756b401', 'c154fbe1-5bed-4658-b1bf-060f69ca791f', 'a', 'Su color es de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:11.964729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9327cbd-bd0b-4a27-966a-5b44b3f2d056', 'cf590ab5-2fa2-461b-bcd9-909023826f70', 'a', 'Su maquinaria propulsora, en caso de llevarla, no se esté utilizando.', true, '2025-09-13 13:53:11.972568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('494805b7-57fd-4189-8430-5ffd9af2c90f', 'cf590ab5-2fa2-461b-bcd9-909023826f70', 'b', 'Su maquinaria propulsora principal sean dichas velas y otro medio mecánico que no incluirá en ningún caso motores de combustión interna.', false, '2025-09-13 13:53:11.972703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c5ce608-9848-4445-8be9-464c94491e5d', 'cf590ab5-2fa2-461b-bcd9-909023826f70', 'c', 'Su maquinaria propulsora, en caso de llevarla, se esté utilizando.', false, '2025-09-13 13:53:11.972838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32cea8a9-6062-44c4-84db-7293157a47bf', 'cf590ab5-2fa2-461b-bcd9-909023826f70', 'd', 'El velamen del buque tenga superficie vélica suficiente para maniobrar la embarcación.', false, '2025-09-13 13:53:11.972983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd6629db-7308-477e-aac2-146d5c9ca5d4', 'ebe4ea0f-e614-4f14-94b4-a2dd6511f4e2', 'a', 'En general, un hidroavión amarado se mantendrá alejado de todos los buques y evitará estorbar su navegación. No obstante, en aquellas circunstancias en que exista un riesgo de abordaje, cumplirá con las reglas de rumbo y gobierno.', false, '2025-09-13 13:53:11.973258+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a473976-c6b1-4fa6-b594-24161484e5ea', 'ebe4ea0f-e614-4f14-94b4-a2dd6511f4e2', 'b', 'Cuando despeguen, aterricen o vuelen cerca de la superficie, las naves de vuelo rasante se mantendrán bien alejadas de todos los demás buques y evitarán entorpecer la navegación de éstos.', false, '2025-09-13 13:53:11.973397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17d4cc65-24e5-477e-be1a-6661d14c079a', 'ebe4ea0f-e614-4f14-94b4-a2dd6511f4e2', 'c', 'Un buque restringido por su calado navegará con particular precaución teniendo muy en cuenta su condición especial.', true, '2025-09-13 13:53:11.973531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2609602-5ef3-4552-965d-78103310dcc6', 'ebe4ea0f-e614-4f14-94b4-a2dd6511f4e2', 'd', 'Las naves de vuelo rasante que naveguen por la superficie del agua no estarán obligadas a cumplir lo dispuesto en las reglas de rumbo y gobierno como si fueran buques de propulsión', false, '2025-09-13 13:53:11.973659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd49da66-9ff1-430a-ab38-9c0352657c42', 'a9894f56-d9a3-48eb-b933-c59784d4c3b4', 'a', 'Asegurar el amarre por medio de cruces en forma de ocho.', true, '2025-09-13 13:53:11.974635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('744fdc4a-8669-4c73-977c-fce53ae29b18', 'a9894f56-d9a3-48eb-b933-c59784d4c3b4', 'b', 'Desamarrar sin necesidad de ir a la boya.', false, '2025-09-13 13:53:11.974767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6d1cb1e-ea99-434c-8c16-1e82bf49eed3', 'a9894f56-d9a3-48eb-b933-c59784d4c3b4', 'c', 'Unir dos cabos por sus chicotes.', false, '2025-09-13 13:53:11.974901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a304728d-bb86-40db-a18d-7468db86c9c7', 'a9894f56-d9a3-48eb-b933-c59784d4c3b4', 'd', 'Reducir el tramo de cabo utilizado en el amarre.', false, '2025-09-13 13:53:11.975034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3891187a-190f-4681-bf87-3777a080f403', '2837ba29-b30a-4ba9-b03a-bcd598106393', 'a', 'Del esprín de proa.', false, '2025-09-13 13:53:11.9753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffe1b515-4c20-4c61-aecb-57124b59e8ca', '2837ba29-b30a-4ba9-b03a-bcd598106393', 'b', 'Del largo de popa.', false, '2025-09-13 13:53:11.975431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f010fd3-4e76-461e-98fd-1a8b4aa7c73a', '2837ba29-b30a-4ba9-b03a-bcd598106393', 'c', 'Del esprín de popa.', false, '2025-09-13 13:53:11.975559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('679e1e79-2557-4153-a3da-7f4f83f62ca3', '85f620d3-d3fd-49b2-9721-b1f2828d33e2', 'a', 'Si navega a vela, confiar en que respetarán su preferencia.', false, '2025-09-13 13:53:11.975995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc368a4b-c98c-4c3a-a261-d157a96c83d6', '85f620d3-d3fd-49b2-9721-b1f2828d33e2', 'b', 'Si navega en embarcación a motor, respetar la preferencia del velero.', true, '2025-09-13 13:53:11.976155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61f2ae77-3be3-43f0-a820-1e250a7d9596', '85f620d3-d3fd-49b2-9721-b1f2828d33e2', 'c', 'Estimar el rumbo y velocidad de un buque grande.', false, '2025-09-13 13:53:11.976317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78a63d9c-9076-499d-b061-31a0f6ac1c19', '85f620d3-d3fd-49b2-9721-b1f2828d33e2', 'd', 'Vigilar los ángulos muertos de visión.', false, '2025-09-13 13:53:11.976475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53cc1c6e-57e5-479a-99ae-73040f7c7e1c', '61fbf340-979c-4af5-9226-0c95ad3ee8cc', 'a', 'El combustible.', false, '2025-09-13 13:53:11.976805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6be4588d-491c-44fb-9b57-3d08aaa49369', '61fbf340-979c-4af5-9226-0c95ad3ee8cc', 'b', 'La energía de activación.', false, '2025-09-13 13:53:11.976966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6455d043-69a2-4bf6-81ad-7d023ffc1ce9', '61fbf340-979c-4af5-9226-0c95ad3ee8cc', 'c', 'La reacción en cadena.', false, '2025-09-13 13:53:11.977136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61d31b08-5510-44b4-93a4-6b9e95605bf4', '61fbf340-979c-4af5-9226-0c95ad3ee8cc', 'd', 'El comburente.', true, '2025-09-13 13:53:11.977308+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da8eb3c8-564a-43b7-9639-4b782f281e25', 'f7cd1bbb-76b8-46ce-9547-c20c980235b7', 'a', 'Enfriar las áreas quemadas con agua fría durante unos minutos.', false, '2025-09-13 13:53:11.97764+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7e2d1c9-d798-4176-91ea-f8ddcefff584', 'f7cd1bbb-76b8-46ce-9547-c20c980235b7', 'b', 'Abrir inmediatamente la vía aérea, si la quemadura le impide respirar.', false, '2025-09-13 13:53:11.977814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c095486-0afb-4ef3-8201-6537b5f3871e', 'f7cd1bbb-76b8-46ce-9547-c20c980235b7', 'c', 'Romper las ampollas que se hayan generado y cubrir la zona afectada con un vendaje compresor.', true, '2025-09-13 13:53:11.977959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28df185e-f865-4c6f-9e2d-adb2056dbc6a', 'f7cd1bbb-76b8-46ce-9547-c20c980235b7', 'd', 'Cortar la ropa, pero sin tirar de ella si está pegada al cuerpo. Meteorología', false, '2025-09-13 13:53:11.978094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16c0075f-0ddc-49a9-8173-7055a21b8813', '6363ce3d-012e-4bcc-8d33-38914da686e9', 'a', 'Son las regiones donde la presión atmosférica es más alta que la del aire circundante.', false, '2025-09-13 13:53:11.978373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be2071a3-6e1c-4847-b55d-8905faf4f88b', '6363ce3d-012e-4bcc-8d33-38914da686e9', 'b', 'El aire fluye hacia el exterior de las borrascas y asciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:11.978505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9ae7dcc-4678-4f09-ac24-ed734ba5d52d', '6363ce3d-012e-4bcc-8d33-38914da686e9', 'c', 'Su proceso de formación se denomina ciclogénesis.', false, '2025-09-13 13:53:11.978636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c61f1def-714a-4495-a823-f2d2eae0bfde', '6363ce3d-012e-4bcc-8d33-38914da686e9', 'd', 'También se conocen como altas presiones o simplemente altas.', true, '2025-09-13 13:53:11.978767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08e895f3-bcc2-4c35-a2ad-6420ffd887cb', 'e070499e-5ac2-45c9-8b9f-2fa552ad3fe7', 'a', 'Un aumento en la intensidad del viento.', false, '2025-09-13 13:53:11.979042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bc26e00-71b1-4330-a98f-5e05d2d2031d', 'e070499e-5ac2-45c9-8b9f-2fa552ad3fe7', 'b', 'Un cambio brusco en la dirección del viento.', false, '2025-09-13 13:53:11.979175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b927e955-fa54-497b-b808-3cef8a4c12fb', 'e070499e-5ac2-45c9-8b9f-2fa552ad3fe7', 'c', 'Una disminución en la intensidad del viento.', false, '2025-09-13 13:53:11.979305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e533a380-9766-410e-a093-0edd6541bb2a', 'e070499e-5ac2-45c9-8b9f-2fa552ad3fe7', 'd', 'Un cambio suave en la dirección del viento.', true, '2025-09-13 13:53:11.979436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('487efa25-3a1b-426d-8d4a-9945b2445ad5', '8892c756-68a3-4f40-b9ea-d1643eb1b9e1', 'a', 'Su referencia inferior está basada en el punto de fusión del hielo (0°C) y la superior en el punto de ebullición del agua (100°C). Entre estas dos referencias existen 100 divisiones.', true, '2025-09-13 13:53:11.979708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb5acbe1-dc6c-4d68-936b-a4823cfaeac7', '8892c756-68a3-4f40-b9ea-d1643eb1b9e1', 'b', 'Su referencia inferior está basada en el punto de fusión del mercurio (0°C) y la superior en el punto de ebullición del mercurio (100°C). Entre estas dos referencias existen 100 divisiones.', false, '2025-09-13 13:53:11.979851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a38bdfb-3ebd-4b5c-9588-afd80cb01a72', '8892c756-68a3-4f40-b9ea-d1643eb1b9e1', 'c', 'Su referencia inferior está basada en el punto de fusión del agua (0°C) y la superior en el punto de ebullición del agua (100°C). Entre estas dos referencias existen 1000 divisiones.', false, '2025-09-13 13:53:11.979983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8f2d2ab-72e0-4a82-a78d-6120726568c0', '8892c756-68a3-4f40-b9ea-d1643eb1b9e1', 'd', 'Su referencia superior está basada en el punto de fusión del mercurio (100°C) y la inferior en el punto de fusión del agua (0°C). Entre estas dos referencias existen 1000 divisiones.', false, '2025-09-13 13:53:11.980114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96e3dac6-101f-4c3d-a700-4fdb036a2db9', 'b5069edc-e1e6-465e-b70d-4429a7720c5e', 'a', 'La altura de ola, donde el grado “0” corresponde a la mínima altura de ola y el “9” a la máxima.', false, '2025-09-13 13:53:11.980387+00');
