INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05d6df05-165a-4bf9-b6a8-e33ac09a1d6a', '16bcd2c4-001c-461e-a664-23fd02f4b88b', 'b', 'Porque la aguja se ve afectada por su desvío y por la declinación magnética de la zona.', false, '2025-09-13 13:53:11.981899+00');
