INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2beaefe6-7e65-4fc8-93a5-63ac34429039', 'ca015caa-4dcb-41b1-b220-d9585d868bd7', 'a', 'Gira en el sentido de las agujas del reloj cuando la embarcación avanza.', false, '2025-09-13 13:53:11.987666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee64218c-73ea-4905-8080-a4a111255453', 'ca015caa-4dcb-41b1-b220-d9585d868bd7', 'b', 'Gira en el sentido de las agujas del reloj cuando la embarcación retrocede.', false, '2025-09-13 13:53:11.987795+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27c60c0a-d53d-40e6-aad9-72b04758a757', 'ca015caa-4dcb-41b1-b220-d9585d868bd7', 'c', 'En marcha avante hace que la popa caiga a babor.', true, '2025-09-13 13:53:11.987924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14a60e9c-d1e4-409e-a4c2-dd970bb25e7d', 'ca015caa-4dcb-41b1-b220-d9585d868bd7', 'd', 'En marcha atrás hace que la popa caiga a estribor.', false, '2025-09-13 13:53:11.988051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('742dc44b-2b5b-4dc8-ae8e-cb75a3715514', 'c295fd2b-4652-4817-9da7-f23e2dd81e47', 'a', 'Adrizada.', false, '2025-09-13 13:53:11.988317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed05f4db-894a-43f8-b1b9-895bb521f504', 'c295fd2b-4652-4817-9da7-f23e2dd81e47', 'b', 'Escorada.', false, '2025-09-13 13:53:11.988444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8703651-0d1e-4428-8258-f16e680cc82f', 'c295fd2b-4652-4817-9da7-f23e2dd81e47', 'c', 'Con asiento positivo.', true, '2025-09-13 13:53:11.98857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c90eec09-6b8f-436e-b942-b2f44f52abb1', 'c295fd2b-4652-4817-9da7-f23e2dd81e47', 'd', 'Con asiento negativo.', false, '2025-09-13 13:53:11.988699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ad26437-f206-49c0-acaf-358ddc5a3dc6', 'b9021268-c2cd-421b-a033-4ffbf80e83bb', 'a', 'Cada uno de los dos cabos o cadenas que van sujetos a la caña del timón y por medio de los cuales se maneja.', false, '2025-09-13 13:53:11.98898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4951d1e-7c8e-442f-b2a8-3962709ccea6', 'b9021268-c2cd-421b-a033-4ffbf80e83bb', 'b', 'Los herrajes de la pala que permiten situar el timón sobre el espejo de popa de la embarcación.', false, '2025-09-13 13:53:11.989118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6faf962-705c-4486-9ebf-a178ae1e455d', 'b9021268-c2cd-421b-a033-4ffbf80e83bb', 'c', 'Las piezas que ensamblan la caña con la pala.', true, '2025-09-13 13:53:11.989248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4904a817-1fed-41c9-8b1e-53f0f39dca60', 'b9021268-c2cd-421b-a033-4ffbf80e83bb', 'd', 'Los elementos que permiten bloquear la rueda del timón.', false, '2025-09-13 13:53:11.98938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aab9900e-ca91-4023-a3f0-67cb046458ee', '110d9bb7-c945-4f69-8483-71b913593852', 'a', 'Nos acercaremos al lugar de fondeo elegido con el ancla a la pendura, dando la popa al viento y con velocidad de gobierno con arrancada.', true, '2025-09-13 13:53:11.990317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42eb41f9-84fd-4604-8bc2-614b3fdef85c', '110d9bb7-c945-4f69-8483-71b913593852', 'b', 'El punto de fondeo debe elegirse de forma que como mínimo se mantenga libre de obstáculos un círculo de radio igual a la longitud de la cadena filada más la eslora de la embarcación.', false, '2025-09-13 13:53:11.990453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11ec38e2-ff07-41e9-9d4f-cbe305f86549', '110d9bb7-c945-4f69-8483-71b913593852', 'c', 'Se utilizarán dos anclas, cuyos ángulos de fondeo formen un ángulo entre 60º y 120º.', false, '2025-09-13 13:53:11.990586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0fc199b-7c1b-44d3-bc1d-1ef5c79f0f26', '110d9bb7-c945-4f69-8483-71b913593852', 'd', 'Se utilizarán dos anclas, una por proa y otra por popa.', false, '2025-09-13 13:53:11.990721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d88f987a-65b4-4811-97e5-7f972f64cc79', '3d62c217-91e3-4f79-8bd1-46da1aa72c09', 'a', 'La gaza es el arco o curvatura que forma el cabo entre los extremos cuando éste no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:11.991002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('319eec12-08d8-4442-b935-76dae9d9b147', '3d62c217-91e3-4f79-8bd1-46da1aa72c09', 'b', 'El as de guía es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:11.991136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e28f06e5-71d2-4f50-9dc1-6c56a5e62489', '3d62c217-91e3-4f79-8bd1-46da1aa72c09', 'c', 'Un noray es una pieza de hierro, de forma cilíndrica ensanchada en su parte superior, fijada en los muelles para hacer firmes las amarras de los barcos.', false, '2025-09-13 13:53:11.991267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('634c2740-acfb-4723-9bc7-756fc2666eef', '3d62c217-91e3-4f79-8bd1-46da1aa72c09', 'd', 'Una boya es una pieza que se coloca en el costado de la embarcación para evitar que se dañe cuando está amarrada.', true, '2025-09-13 13:53:11.991397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1f8de47-a293-4af5-bc9d-7b01b9d14cd6', '2bbb1249-ce34-49fb-9f63-7d8738b0ddef', 'a', 'La temperatura del aceite.', false, '2025-09-13 13:53:11.991669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2171093a-8d7d-4032-9b91-be359a93fde1', '2bbb1249-ce34-49fb-9f63-7d8738b0ddef', 'b', 'La temperatura del combustible.', true, '2025-09-13 13:53:11.991813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a337c830-aee3-4897-9434-9d67df951267', '2bbb1249-ce34-49fb-9f63-7d8738b0ddef', 'c', 'El pararrayos.', false, '2025-09-13 13:53:11.991949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e59a28c4-5285-4fde-9c1f-7703047e2b7e', '2bbb1249-ce34-49fb-9f63-7d8738b0ddef', 'd', 'El desvío de la aguja.', false, '2025-09-13 13:53:11.992099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f066bb1e-4831-4119-b660-69547fa56793', '027d9e02-1acd-4340-b84e-31f406574c1a', 'a', 'En llevar la mar por la aleta, navegando a una velocidad que evite sincronizarse con las olas.', false, '2025-09-13 13:53:11.99241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2939e5b5-7456-4d48-a251-eaed9aef6eed', 'c5364466-5384-41af-b6a8-2e3955c7bec8', 'b', 'Dejar el ancla a la pendura.', false, '2025-09-13 13:53:12.024941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f75ccbc4-23df-401f-92fc-bd9e24d3a252', '3ec4cc98-9ad4-425d-84f0-fe9af776296d', 'd', 'Marca el límite de las aguas abrigadas.', false, '2025-09-13 13:53:11.98429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a891ba7-ffc6-4f7c-a353-e8d7153c3679', '027d9e02-1acd-4340-b84e-31f406574c1a', 'c', 'En llevar la mar por la amura, navegando a una velocidad que evite sincronizarse con las olas.', false, '2025-09-13 13:53:11.992705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eb8e16f-6d87-43e6-929e-fb6838e1ee2f', '027d9e02-1acd-4340-b84e-31f406574c1a', 'd', 'En llevar la mar por la aleta, navegando a una velocidad reducida para sincronizarse con las olas.', true, '2025-09-13 13:53:11.992858+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d10ac44d-7ad7-4976-8dc2-0a71408f3969', '6620492d-ca17-4326-9343-c3ded19cb483', 'a', 'Llevar la máxima velocidad disponible.', false, '2025-09-13 13:53:11.993138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd49b693-373e-4bc9-910c-d92338628e4b', '6620492d-ca17-4326-9343-c3ded19cb483', 'b', 'Llevar un ancla lista para fondear.', true, '2025-09-13 13:53:11.993273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f94153d9-f87e-44cf-8f7b-88047c714341', '6620492d-ca17-4326-9343-c3ded19cb483', 'c', 'Gobernar con poco timón, procurando no levantarlo en ningún momento.', false, '2025-09-13 13:53:11.993401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45800212-0c34-4a6f-9187-87d88bf650ef', '6620492d-ca17-4326-9343-c3ded19cb483', 'd', 'Al maniobrar a un barco que navegue de “vuelta encontrada”, hacerlo inmediatamente metiendo', false, '2025-09-13 13:53:11.993536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74db3291-216d-4cf0-bc58-93812a7201cc', '11109e58-a890-40f0-befe-561c91e4f029', 'a', '36º C.', true, '2025-09-13 13:53:11.993834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65051830-1a26-4c9d-9ea3-808f1d512fbd', '11109e58-a890-40f0-befe-561c91e4f029', 'b', '35º C.', false, '2025-09-13 13:53:11.993996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fa40def-cea0-4935-8d36-455348f25c78', '11109e58-a890-40f0-befe-561c91e4f029', 'c', '33º C.', false, '2025-09-13 13:53:11.994155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('922cc517-aa9d-436e-a57a-71444e38fe05', '11109e58-a890-40f0-befe-561c91e4f029', 'd', '32º C.', false, '2025-09-13 13:53:11.994329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a143d263-12f2-4aba-8ab3-96dff13577ca', 'b11a2db5-0546-42a1-9d16-4792f707261a', 'a', 'Está prohibida en todo caso, sin que quepa excepción alguna.', false, '2025-09-13 13:53:11.994657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06064e91-3c6b-4066-8bc4-9da4fbf44aeb', 'b11a2db5-0546-42a1-9d16-4792f707261a', 'b', 'Está permitida si se realiza a menos de 12 millas marinas de la tierra más próxima y siempre que no esté contaminado con otro tipo de basuras.', true, '2025-09-13 13:53:11.994824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70bad536-4a9f-465c-8078-ed662c2eb2fc', 'b11a2db5-0546-42a1-9d16-4792f707261a', 'd', 'Está permitida siempre que se realice a más de 12 millas marinas de la tierra más próxima, mientras la embarcación no se encuentre en ruta y junto a los demás desechos de alimentos que deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:11.995142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92c5acca-b17a-4209-b3fd-20f7fa5c1ecd', '89043e98-c770-4d2d-8370-ca000b475ccd', 'a', 'A una distancia superior a 3 millas náuticas de la tierra más próxima si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema dotado de medios que permitan almacenarlas temporalmente, siempre que sea aprobado u homologado por la Administración Marítima española.', false, '2025-09-13 13:53:11.995477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a740d9d7-08fe-459a-947c-0d6124e50daf', '89043e98-c770-4d2d-8370-ca000b475ccd', 'b', 'A una distancia superior a 3 millas náuticas e inferior a 12 millas náuticas de la tierra más próxima, hayan sido o no previamente desmenuzadas y desinfectadas, si han estado almacenadas en sistemas de retención que se descarguen a un régimen moderado.', false, '2025-09-13 13:53:11.995636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('668120be-a90f-4cd3-ad89-44d9f81b3e59', '89043e98-c770-4d2d-8370-ca000b475ccd', 'c', 'A una distancia no superior a zona 7, si se utiliza algún sistema de retención por el que las aguas sucias se descarguen instantáneamente, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', true, '2025-09-13 13:53:11.995807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9204b7d-12fd-471d-819d-d40e359ae7eb', '89043e98-c770-4d2d-8370-ca000b475ccd', 'd', 'Fuera de zona 7, si las aguas sucias han estado almacenadas en algún sistema de retención que se descargue instantáneamente aprobado u homologado por la Administración Marítima española, hallándose la embarcación en ruta navegando a velocidad no superior a 4 nudos.', false, '2025-09-13 13:53:11.995967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d0d87c8-18a7-4687-b0e0-d2222ccb2451', '6821a2a9-0a7c-49e0-a9aa-6fbf199c0985', 'a', 'Serán siempre de color blanco y su luz (si tiene) tendrá un ritmo de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:11.9963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2127491c-0abf-41e9-b630-f1da635c8c63', '6821a2a9-0a7c-49e0-a9aa-6fbf199c0985', 'b', 'Consistirán en franjas horizontales negras sobre blanco y su luz (si tiene) será de color amarillo.', false, '2025-09-13 13:53:11.996459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7fd6786-5a0a-4e56-b6d7-636adccee229', '6821a2a9-0a7c-49e0-a9aa-6fbf199c0985', 'c', 'Serán de color negro con una o varias anchas bandas diagonales rojas y su luz (si tiene) tendrá un ritmo de grupos de dos destellos GpD (2).', false, '2025-09-13 13:53:11.996624+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ec70961-035d-4ca7-b0e3-501e3fb8cd8f', '6821a2a9-0a7c-49e0-a9aa-6fbf199c0985', 'd', 'Serán siempre de color rojo y blanco en franjas verticales y su luz (si tiene) será de color blanco.', true, '2025-09-13 13:53:11.996789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb76721e-17f0-4cc1-a9d4-9cd199b38fdf', '4bb3377b-7a01-498f-b43e-ba43914f90cf', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la Marca.', false, '2025-09-13 13:53:11.997118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78d3f805-6118-45b1-9c8e-01c5b71d7a02', '4bb3377b-7a01-498f-b43e-ba43914f90cf', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', true, '2025-09-13 13:53:11.997286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a877eab-bc22-433a-aba7-98c2890ecaef', '4bb3377b-7a01-498f-b43e-ba43914f90cf', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:11.997444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4975c8c4-880a-444e-94ba-754ea6ba2b5d', '4bb3377b-7a01-498f-b43e-ba43914f90cf', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la Marca.', false, '2025-09-13 13:53:11.997603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c655e32-4884-4cdd-affd-822c8b9adb35', 'ef60d80e-13c0-4464-8082-33874d78bc60', 'a', 'De forma cónica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.997939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9ab3d05-b61a-46a2-a0c2-4a5fd526bb09', 'ef60d80e-13c0-4464-8082-33874d78bc60', 'b', 'De forma cónica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:11.998077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b36866b-d549-460c-b7c0-c5d897935a08', 'ef60d80e-13c0-4464-8082-33874d78bc60', 'c', 'De forma cilíndrica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:11.998212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5247ae03-a919-4a7e-97f8-628df87b85c8', 'ef60d80e-13c0-4464-8082-33874d78bc60', 'd', 'De forma cilíndrica de color verde con una banda ancha horizontal roja.', true, '2025-09-13 13:53:11.998344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6997dee-3b2b-4dd5-9704-33fdd2470b28', '77d07a6a-4953-4494-8cd4-292dc11290a6', 'a', 'Roja y continua.', true, '2025-09-13 13:53:11.99862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15a09603-43ad-4e5d-a01d-c3ad126c2e6c', '77d07a6a-4953-4494-8cd4-292dc11290a6', 'b', 'Blanca y destellos en grupo de dos.', false, '2025-09-13 13:53:11.998756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e162d301-5d66-4453-a6a7-6ece9968b477', '77d07a6a-4953-4494-8cd4-292dc11290a6', 'c', 'Amarilla y ritmo centelleante rápido.', false, '2025-09-13 13:53:11.999071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48177805-4894-4504-9080-65ea6b55ad68', '77d07a6a-4953-4494-8cd4-292dc11290a6', 'd', 'Verde con un destello largo cada diez segundos.', false, '2025-09-13 13:53:11.999563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('597218ab-3a9a-4267-af92-334b96d53e80', 'fc651acf-2063-4664-b6c1-9689d6dcd9c7', 'a', 'Su presencia conlleva para el navegante la necesidad de consultar la carta y las publicaciones náuticas porque indican una zona o configuración particular cuya naturaleza se indica en ellas.', false, '2025-09-13 13:53:12.000077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbad40cd-8c69-4823-9f43-2c3b984df506', 'fc651acf-2063-4664-b6c1-9689d6dcd9c7', 'b', 'Tienen como objetivo principal señalar canales u obstrucciones e indicar zonas o configuraciones particulares de carácter especial.', false, '2025-09-13 13:53:12.000416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ef66cd3-2fec-401b-8296-569287475636', 'fc651acf-2063-4664-b6c1-9689d6dcd9c7', 'c', 'Se utilizan para llamar la atención sobre una configuración especial de un canal, tal como un recodo una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:12.000771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d58fab2-76c1-4ef2-a5ea-89b5708e9ced', 'fc651acf-2063-4664-b6c1-9689d6dcd9c7', 'd', 'Su uso principal es indicar el sentido convencional del balizamiento, que debe indicarse en los documentos náuticos apropiados, en zonas con una configuración especial. Reglamento (RIPA).', true, '2025-09-13 13:53:12.001001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b19e3f7-bcd6-4146-8fa7-7c8dc5e0e6ad', '44df6e33-130e-4ee6-b5b3-1fdda6a03d5a', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.001398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b5ba379-4372-4058-9e41-ffc85948ef2d', '44df6e33-130e-4ee6-b5b3-1fdda6a03d5a', 'b', 'Se deberá mantener el rumbo, ya que debe de ser el otro buque el que maniobre.', false, '2025-09-13 13:53:12.001639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('526004de-c6a8-4c27-96af-8331fc3d988c', '44df6e33-130e-4ee6-b5b3-1fdda6a03d5a', 'c', 'Para la situación indicada no hay norma y por tanto se deberá tener en cuenta lo indicado para la situación de vuelta encontrada.', false, '2025-09-13 13:53:12.001842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4018a1b3-9f42-4896-a64c-3e07f6013e5e', '44df6e33-130e-4ee6-b5b3-1fdda6a03d5a', 'd', 'Se deberá maniobrar para caer a estribor de forma que se pase por la banda de babor del velero', true, '2025-09-13 13:53:12.002015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1656864a-4dcf-4394-a58d-b228e61747d4', '26fca4c1-b754-45aa-8486-dde15d5158ac', 'a', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', true, '2025-09-13 13:53:12.002342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a8638ac-2dcf-4bba-8a71-68fa641260e1', '26fca4c1-b754-45aa-8486-dde15d5158ac', 'b', 'Las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:12.002542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f662201-bf37-45ce-9183-c676ef4516a6', '26fca4c1-b754-45aa-8486-dde15d5158ac', 'c', 'Las luces de costado, una luz de alcance y una luz verde todo horizonte.', false, '2025-09-13 13:53:12.00273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c83db82d-36ec-4964-b776-55e53c4997bc', '26fca4c1-b754-45aa-8486-dde15d5158ac', 'd', 'Dos luces blancas todo horizonte en línea vertical.', false, '2025-09-13 13:53:12.003012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6760cadf-36f7-4e2f-bd71-1669cbbaadf4', '17482dd8-0a83-45d1-907e-d7b4a1c02f56', 'a', 'Una luz blanca colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:12.003437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b592793f-4fc0-442a-9295-9ffb8c405f7e', '17482dd8-0a83-45d1-907e-d7b4a1c02f56', 'b', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz sin interrupción en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', false, '2025-09-13 13:53:12.003635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33614c93-e709-49bb-bb90-3720f4a3a9ca', '17482dd8-0a83-45d1-907e-d7b4a1c02f56', 'c', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz centelleante en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', true, '2025-09-13 13:53:12.003852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1d6aafb-ec5f-490e-bda0-e97df7ead0e6', '17482dd8-0a83-45d1-907e-d7b4a1c02f56', 'd', 'Una luz amarilla colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:12.004095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e7e2040-446c-431b-8264-3c452ccdfc36', '80b3490d-01bc-4d08-b4df-32141b4fd67c', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:12.004528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11dc182b-d49f-4e2d-a2b2-ac7e08c7f6cd', '80b3490d-01bc-4d08-b4df-32141b4fd67c', 'b', 'Cuando dos buques o embarcaciones, con independencia del tipo de propulsión que tengan, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.004731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe59c864-3ee0-4dee-bf18-8536ed8bc979', '80b3490d-01bc-4d08-b4df-32141b4fd67c', 'c', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.00501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d910970d-5539-40bf-9d12-a203e10e6ec1', '80b3490d-01bc-4d08-b4df-32141b4fd67c', 'd', 'Cuando dos buques o embarcaciones, con independencia del tipo que sean, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.0052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe3363a5-3401-412a-8cc5-08a8a43b1eba', '889d5b81-b37b-420f-95ea-7f8e672b1c52', 'a', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:12.00561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21deaeaf-d1b8-4197-be1b-f62ce24c764e', '889d5b81-b37b-420f-95ea-7f8e672b1c52', 'b', 'Únicamente una luz de tope a proa.', false, '2025-09-13 13:53:12.005799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22da784a-a06f-4091-b730-e3ef876a66fb', '889d5b81-b37b-420f-95ea-7f8e672b1c52', 'c', 'Únicamente una luz blanca todo horizonte.', false, '2025-09-13 13:53:12.005963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3063b5ca-326e-4b78-83ed-e18fb539d398', '889d5b81-b37b-420f-95ea-7f8e672b1c52', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirán también luces de costado.', false, '2025-09-13 13:53:12.00614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('031f34b2-45e9-40aa-a472-e91995f1d5f5', '91db008c-6b55-4502-9f9e-ac7f0b2ab01b', 'a', 'Dado que se trata de una situación de buque que alcanza, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.006478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9121669d-19fa-44b3-8f50-559eaacb289a', '91db008c-6b55-4502-9f9e-ac7f0b2ab01b', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:12.006646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c9a1d97-dd1f-43bc-b8e0-4447d0c371bc', '91db008c-6b55-4502-9f9e-ac7f0b2ab01b', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', true, '2025-09-13 13:53:12.006824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('baa210bc-7ff0-47ca-ae8d-09e29532d666', '91db008c-6b55-4502-9f9e-ac7f0b2ab01b', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:12.006995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a108fbee-f8ff-44db-a5ec-743a8e0de364', 'a3bb9116-efaf-4bc9-b001-de7e5d85d3f4', 'a', 'La demora de un buque que se aproxima no varía en forma apreciable.', false, '2025-09-13 13:53:12.00807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efe0ee56-878e-4bc1-9527-201773952904', 'a3bb9116-efaf-4bc9-b001-de7e5d85d3f4', 'b', 'La demora de un buque que se aproxima varía en forma apreciable.', true, '2025-09-13 13:53:12.008205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32049f53-7a68-4988-8bcb-54fb56608694', 'a3bb9116-efaf-4bc9-b001-de7e5d85d3f4', 'd', 'La demora del buque que se aleja varía en forma apreciable.', false, '2025-09-13 13:53:12.008476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c682362-839f-43ba-a02a-acb4542bae3f', 'd94a49c3-4692-445b-afc0-3b13c46e7cd0', 'a', 'A intervalos que no excedan de dos minutos, dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.008768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c73fc2b4-28f1-42f4-85a4-9d6191467015', 'd94a49c3-4692-445b-afc0-3b13c46e7cd0', 'b', 'A intervalos que no excedan de dos minutos, dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.008904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4aef2efb-1ffe-4be3-9476-58cb02376306', 'd94a49c3-4692-445b-afc0-3b13c46e7cd0', 'c', 'Una pitada larga a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:12.009057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16db0345-8b7d-40ca-842a-38a59a00b6aa', 'd94a49c3-4692-445b-afc0-3b13c46e7cd0', 'd', 'Una pitada corta a intervalos que no excedan de dos minutos.', true, '2025-09-13 13:53:12.009208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('861dde85-3e31-43aa-a8bb-ab71852b2132', '08c6d14b-fe0c-42db-bead-195bda0fad1c', 'a', 'Naranja.', false, '2025-09-13 13:53:12.009516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37b4b260-249b-4764-9d67-53f9f6d1a0f0', '08c6d14b-fe0c-42db-bead-195bda0fad1c', 'b', 'Amarillo.', false, '2025-09-13 13:53:12.009671+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('033764ff-c3fc-414f-abba-695e5c574c44', '08c6d14b-fe0c-42db-bead-195bda0fad1c', 'c', 'Rojo.', true, '2025-09-13 13:53:12.009819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e1350fa-d127-4491-b058-1ca128f277e3', 'b22102fa-4cb4-4fb3-b128-fc07ef84644c', 'a', 'La corriente.', true, '2025-09-13 13:53:12.010394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42ff5889-ae39-4219-b802-c5966d90fb58', 'b22102fa-4cb4-4fb3-b128-fc07ef84644c', 'b', 'El viento.', false, '2025-09-13 13:53:12.01054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1475714b-c5a1-4bca-8ecf-6e12d5aa7989', 'b22102fa-4cb4-4fb3-b128-fc07ef84644c', 'c', 'Las olas.', false, '2025-09-13 13:53:12.010681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77e882d3-ae7e-45c2-ad98-086779142045', 'b22102fa-4cb4-4fb3-b128-fc07ef84644c', 'd', 'El garete.', false, '2025-09-13 13:53:12.010824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3eea0f98-152a-4fe4-b688-a58b60ab8a29', '729b2013-f68e-403b-9571-891a79a24a49', 'a', 'El viento real es nulo. El viento aparente viene de proa con una velocidad constante.', true, '2025-09-13 13:53:12.01113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb3f37a0-9caf-4b24-b6cd-2c5234c12dc0', '729b2013-f68e-403b-9571-891a79a24a49', 'b', 'El viento real es nulo. El viento aparente viene de popa con una velocidad constante.', false, '2025-09-13 13:53:12.011271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0edb4d88-15c8-494c-bac2-a15fd9ab6cb5', '729b2013-f68e-403b-9571-891a79a24a49', 'c', 'El viento aparente es nulo. El viento real viene de proa con una velocidad igual a la del barco.', false, '2025-09-13 13:53:12.011408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57168a9d-9755-4d1f-9469-7239b9cf3529', '729b2013-f68e-403b-9571-891a79a24a49', 'd', 'El viento aparente es nulo. El viento real viene de popa con una velocidad igual a la del barco. Emergencias en la mar.', false, '2025-09-13 13:53:12.011542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('652c57c3-be59-4ba4-9ff4-6ebd60c5221c', 'f703fb51-b631-4794-93f1-bc930de39039', 'a', 'La pleamar, que es el momento en que la marea está más alta.', false, '2025-09-13 13:53:12.011816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4c97acf-c926-42ce-ba3d-25c356439d1a', 'f703fb51-b631-4794-93f1-bc930de39039', 'b', 'La bajamar, que es el momento en que la marea está más alta.', true, '2025-09-13 13:53:12.01195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f3dbfa7-23d5-4eb7-94b2-44ea43734bcf', 'f703fb51-b631-4794-93f1-bc930de39039', 'c', 'La pleamar, que es el momento en que la marea está más baja.', false, '2025-09-13 13:53:12.012089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42208840-f3ba-419f-a8b1-a8b449f4268f', 'f703fb51-b631-4794-93f1-bc930de39039', 'd', 'La bajamar, que es el momento en que la marea está más baja.', false, '2025-09-13 13:53:12.012228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74256ceb-1900-4bf6-8118-2bf21c1d67cb', 'a07f03e2-0223-45d1-b93a-c49cdeb0cc73', 'a', 'Si dispone de balsa salvavidas, tire de la driza para abrirla automáticamente sin amarrarla previamente a bordo.', false, '2025-09-13 13:53:12.012533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('799660ea-21b3-4588-8042-9f09810f1394', '08c6d14b-fe0c-42db-bead-195bda0fad1c', 'd', 'Negro.', false, '2025-09-13 13:53:12.00996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fcea55e-eba2-4d2c-9991-c9702d9033aa', 'a3bb9116-efaf-4bc9-b001-de7e5d85d3f4', 'c', 'Principalmente la velocidad del buque que se aproxima está por encima de la velocidad de seguridad.', false, '2025-09-13 13:53:12.008339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aada18c8-b827-444b-ae1b-fec539dcf1fa', 'a07f03e2-0223-45d1-b93a-c49cdeb0cc73', 'b', 'Realice una llamada de socorro y active la radiobaliza manualmente únicamente una vez haya abandonado la embarcación.', false, '2025-09-13 13:53:12.01267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b522c7b9-02a6-48e9-90dc-be596a0dc71c', 'a07f03e2-0223-45d1-b93a-c49cdeb0cc73', 'c', 'Si precisa voltear la balsa, colóquese a barlovento, súbase sobre la botella de aíre comprimido y tire de las cinchas que cruzan la parte inferior de la balsa.', false, '2025-09-13 13:53:12.012817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68280add-b7dc-4ea8-a07f-2f92eae84123', 'a07f03e2-0223-45d1-b93a-c49cdeb0cc73', 'd', 'Si no dispone de balsa salvavidas, salte al agua y adopte la postura fetal, sin nadar, o flote abrazado a sus compañeros, para evitar la hipotermia.', true, '2025-09-13 13:53:12.012951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab2f7a57-ad0a-45b5-9930-5745c64dfc64', 'f49ed785-ca4d-426a-91fd-0ce809ad5570', 'a', 'Chorro de agua.', false, '2025-09-13 13:53:12.013232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f824ef75-ec0f-4af2-9011-2f339ee06536', 'f49ed785-ca4d-426a-91fd-0ce809ad5570', 'b', 'Agua pulverizada.', false, '2025-09-13 13:53:12.013366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3b705a5-90c8-4612-888f-0da4c5721ef6', 'f49ed785-ca4d-426a-91fd-0ce809ad5570', 'c', 'Polvo seco.', true, '2025-09-13 13:53:12.013504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6260b972-661f-45e9-bff2-2797e520b13d', 'f49ed785-ca4d-426a-91fd-0ce809ad5570', 'd', 'Arena. Meteorología', false, '2025-09-13 13:53:12.013637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b7747e5-56b0-40f3-ba17-1398e5c1eb4f', '8fe620ba-5376-4346-a736-4b98c38d437e', 'a', 'El anemómetro se utiliza para determinar la velocidad del viento.', false, '2025-09-13 13:53:12.013924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b7dfa95-f0ba-4a0c-9292-325b334bd4e2', '8fe620ba-5376-4346-a736-4b98c38d437e', 'b', 'El anemómetro se utiliza para determinar la dirección del viento.', false, '2025-09-13 13:53:12.014091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18f7195b-03f3-4ad4-b10c-96fe0a26cc11', '8fe620ba-5376-4346-a736-4b98c38d437e', 'c', 'La veleta se utiliza para determinar la velocidad del viento.', false, '2025-09-13 13:53:12.014243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2831b569-3dac-49c1-8989-963f7866e223', '8fe620ba-5376-4346-a736-4b98c38d437e', 'd', 'El catavientos se ubica en la parte más alta del palo mayor de la embarcación.', true, '2025-09-13 13:53:12.014387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf38db6f-a370-4f60-9937-180c00f06e95', 'fd98c498-6158-41d4-bd2d-3fa21c2b4a5e', 'a', '1,013.', true, '2025-09-13 13:53:12.014681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4abac91e-b48e-4c9a-b23c-9e3299cd70b8', 'fd98c498-6158-41d4-bd2d-3fa21c2b4a5e', 'b', '1.', false, '2025-09-13 13:53:12.014818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85261696-eb74-4e16-b78d-350139fcb3d6', 'fd98c498-6158-41d4-bd2d-3fa21c2b4a5e', 'c', '13.', false, '2025-09-13 13:53:12.014952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb05a70b-6c91-4f3a-902a-b23d8c9bd1bf', 'fd98c498-6158-41d4-bd2d-3fa21c2b4a5e', 'd', '1013.', false, '2025-09-13 13:53:12.015094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ddba3f3-a462-4efe-8b1e-e5e28a6daee4', 'e3f236a6-17a9-4dd0-9119-9e23a027409a', 'a', 'Su proceso de formación se denomina ciclogénesis.', false, '2025-09-13 13:53:12.015384+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3902e5e7-e1b2-446f-b37f-58e7f857da4b', 'e3f236a6-17a9-4dd0-9119-9e23a027409a', 'b', 'El aire fluye hacia el exterior de los anticiclones y desciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:12.015521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('418c9ff8-be60-49c6-88af-2f31f47afaf9', 'e3f236a6-17a9-4dd0-9119-9e23a027409a', 'c', 'Se llaman también altas presiones o, simplemente, altas.', false, '2025-09-13 13:53:12.015656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f8bccac-ed68-4d00-9eae-6d2a4c8db2a0', 'e3f236a6-17a9-4dd0-9119-9e23a027409a', 'd', 'La presión más baja se localiza siempre en el centro.', true, '2025-09-13 13:53:12.015801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86b8f7e1-1fc0-45ff-a4d2-f852020195ed', 'a89ffe57-9754-4b02-b8c1-aa5a75fca06a', 'a', 'El número de horas que el viento sopla en la misma dirección.', false, '2025-09-13 13:53:12.016084+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7dbe43e-1f1a-4ea2-be79-384800321798', 'a89ffe57-9754-4b02-b8c1-aa5a75fca06a', 'b', 'La rapidez con la que el viento cambia de dirección.', false, '2025-09-13 13:53:12.016225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c11f28e7-e446-49d5-92fd-884ebf2028d1', 'a89ffe57-9754-4b02-b8c1-aa5a75fca06a', 'c', 'La velocidad con la que sopla el viento.', false, '2025-09-13 13:53:12.016359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3248068a-795f-4b24-a588-5e20e53d69b5', 'a89ffe57-9754-4b02-b8c1-aa5a75fca06a', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes. Teoría de la navegación.', true, '2025-09-13 13:53:12.016515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45868711-5157-45d1-82c1-f7265b2e8042', '69bff299-df91-4c38-93e2-1a448af47452', 'a', 'Deriva.', false, '2025-09-13 13:53:12.016813+00');
