INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('510bd1fb-c6c3-483b-8730-eedf41adea61', '911ab958-c83e-4772-9fd5-40b9f40cc4a3', 'a', 'La diferencia entre el calado de popa y el calado de proa. Es positivo cuando el calado a popa es mayor que a proa.', true, '2025-09-13 13:53:12.025498+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9d47ebb-63eb-4aee-a2f4-423b75cdc515', '911ab958-c83e-4772-9fd5-40b9f40cc4a3', 'b', 'La curvatura que se produce en sentido longitudinal de la quilla de una embarcación haciendo que sus extremidades estén más elevadas que el centro.', false, '2025-09-13 13:53:12.025646+00');
