INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f01d4a4d-91d5-4169-b1cf-dce7016447fe', '1eaeeb26-148b-4ae2-9331-9b3fc8d10cf9', 'c', 'La cubierta más baja.', false, '2025-09-13 13:53:12.026757+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5732674c-5792-4ba3-b6d8-d1851e48acc1', '1eaeeb26-148b-4ae2-9331-9b3fc8d10cf9', 'd', 'El fondo interior del casco sobre la quilla de la embarcación, en el que se reúnen las aguas de diferentes procedencias. Elementos de amarre y fondeo.', true, '2025-09-13 13:53:12.027108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cccb0614-816a-46c0-b4b6-432077a95e02', 'f816c49c-73dd-4e60-8cf6-a07dc32e63fb', 'a', 'El ballestrinque es un nudo que permite realizar una gaza no corrediza para encapillar un cabo.', false, '2025-09-13 13:53:12.027653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66a4387b-40d9-4a84-8e22-568331d1aa7f', 'f816c49c-73dd-4e60-8cf6-a07dc32e63fb', 'b', 'Un noray es un poste de hierro o madera que, asegurado a la cubierta, sirve para dar vuelta a los cabos cuando se fondea la embarcación.', false, '2025-09-13 13:53:12.028123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c9524b0-fd41-4f07-8b00-6b3240670fad', 'f816c49c-73dd-4e60-8cf6-a07dc32e63fb', 'c', 'Una boya es un cuerpo flotante sujeto al fondo del mar mediante un lastre, que se coloca para amarrar una embarcación o como elemento de señalización.', true, '2025-09-13 13:53:12.028332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22a70556-21cb-4ec6-9b8e-d7138b6aa71f', 'f816c49c-73dd-4e60-8cf6-a07dc32e63fb', 'd', 'El bichero es el extremo libre de un cabo.', false, '2025-09-13 13:53:12.028499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ffd4a71-8091-4821-a3d9-473fb6a2d653', '6f7fd9c3-dc80-4f20-9bc3-12df63e65550', 'a', 'La embarcación debe disponer de una línea de fondeo cuya longitud será como mínimo cuatro veces la eslora de la embarcación.', false, '2025-09-13 13:53:12.028847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b0f1409-2f33-4544-84c7-a19140f63c3b', '6f7fd9c3-dc80-4f20-9bc3-12df63e65550', 'b', 'Hay que tomar referencias a tierra para asegurarnos que el ancla no garrea, y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-13 13:53:12.029034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffa4e4ac-454a-44ec-a006-75cf22a139eb', '6f7fd9c3-dc80-4f20-9bc3-12df63e65550', 'c', 'Se utilizará el orinque para medir la profundidad y conocer el tipo de fondo.', false, '2025-09-13 13:53:12.029212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13ebdbd1-ebb2-4392-b00c-83abbc5d3479', '6f7fd9c3-dc80-4f20-9bc3-12df63e65550', 'd', 'Se elegirá un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:12.029358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b51add5c-5221-4e5c-9880-a94ac06d8922', 'ee53f03c-7436-412d-8728-3f57210635ac', 'a', 'Mantener o recuperar la posición de adrizado.', true, '2025-09-13 13:53:12.029673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('306e29a7-e935-4f4e-b51b-bd1b5729da3a', 'ee53f03c-7436-412d-8728-3f57210635ac', 'b', 'Mantener o recuperar el asiento o el trimado.', false, '2025-09-13 13:53:12.029821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80c3fd2d-5c92-463f-afa0-8673d688f8aa', 'ee53f03c-7436-412d-8728-3f57210635ac', 'c', 'Mantener la escora en un ángulo igual o menor a 15º.', false, '2025-09-13 13:53:12.030019+00');
