INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a53b3b3a-9489-4a61-a75e-9b87882833dd', '9b89e7b9-1606-4c7e-a139-8daf9c4537c0', 'c', '3 bengalas de mano y 3 cohetes con luz roja y paracaídas.', false, '2025-09-13 13:53:12.031248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cf0c667-9d90-4260-88db-342a2837c8b8', '9b89e7b9-1606-4c7e-a139-8daf9c4537c0', 'd', 'Sólo 3 bengalas de mano.', true, '2025-09-13 13:53:12.031431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b2300b6-934f-495f-ae20-39963dc77150', 'f5cd802d-16b1-415f-866f-e73cfd0e76c7', 'a', 'Sólo en embarcaciones con casco metálico.', false, '2025-09-13 13:53:12.032333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7565ef2d-a244-4e29-bd4a-d62f9af22164', 'f5cd802d-16b1-415f-866f-e73cfd0e76c7', 'b', 'En todas las embarcaciones de recreo.', false, '2025-09-13 13:53:12.032515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c20cacf4-215d-4e75-aeba-09356bccd2fb', 'f5cd802d-16b1-415f-866f-e73cfd0e76c7', 'c', 'En embarcaciones con casco de madera o fibra.', true, '2025-09-13 13:53:12.032661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16e0f8cf-c3ed-4921-a77b-9096bfa357e3', 'f5cd802d-16b1-415f-866f-e73cfd0e76c7', 'd', 'Sólo en embarcaciones con casco de madera.', false, '2025-09-13 13:53:12.032804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d94bef17-31d6-47dd-8815-c04a7f046ae0', '684e6cb1-b3f8-4744-8f06-16f6a429bdc4', 'a', 'Meter el timón inmediatamente a la banda contraria donde ha caído el náufrago para iniciar la maniobra de Anderson o Boutakow.', true, '2025-09-13 13:53:12.033183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65bdcd88-f011-4d5d-87d8-0ae3e1803b40', '684e6cb1-b3f8-4744-8f06-16f6a429bdc4', 'b', 'Detener inmediatamente la máquina o ponerla en punto muerto.', false, '2025-09-13 13:53:12.033419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4554239-a243-4427-b76a-712042bcc8af', '684e6cb1-b3f8-4744-8f06-16f6a429bdc4', 'c', 'Hacer una llamada de emergencia.', false, '2025-09-13 13:53:12.033657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ed7cd20-e257-4228-8d4f-74ac9d826d2f', '684e6cb1-b3f8-4744-8f06-16f6a429bdc4', 'd', 'Pulsar el botón “Distress” de la LSD si perdemos de vista al náufrago.', false, '2025-09-13 13:53:12.033833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1c5d304-0f60-45f2-bc25-1afdcd65b681', 'b28313f5-1132-45c0-83ee-b081b16f63f2', 'a', 'No se permitirá la descarga de productos avícolas introducidos, incluidas las aves o partes de aves, si dichos productos se han tratado para su esterilización.', false, '2025-09-13 13:53:12.034643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a751279-0267-4eff-be11-8f420ddf45b3', 'b28313f5-1132-45c0-83ee-b081b16f63f2', 'b', 'Sólo se podrá descargar materia plástica que se haya pasado por un desmenuzador o triturador, de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:12.035061+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1469ea87-33b6-4bd1-99ba-c8c75ae88b65', 'b28313f5-1132-45c0-83ee-b081b16f63f2', 'd', 'En ningún caso se hará a menos de tres millas marinas de la tierra más próxima en el caso de desechos de alimentos que se hayan pasado por un desmenuzador o triturador, de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', true, '2025-09-13 13:53:12.035411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcee2287-6bde-4e97-aa08-aa21f9a5ba73', '77a042ac-17ff-4222-ac45-9fd803598576', 'a', 'Disponga de depósitos de retención fijos con una conexión universal a tierra.', false, '2025-09-13 13:53:12.035739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec6b5a39-d828-4a35-aace-2445ea111f9a', '77a042ac-17ff-4222-ac45-9fd803598576', 'c', 'Efectúe la descarga fuera de zona 7, utilizando una instalación de tratamiento de aguas sucias.', true, '2025-09-13 13:53:12.036201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc3d9f7b-89fe-4a5c-b565-de558e0b0fae', '77a042ac-17ff-4222-ac45-9fd803598576', 'd', 'Efectúe la descarga a una distancia superior a 3 millas náuticas de la tierra más próxima, si la embarcación está provista de conductos destinados a la descarga al mar que atraviesen el casco con válvulas que puedan cerrarse herméticamente.', false, '2025-09-13 13:53:12.036363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4e66077-ae5b-4b3f-95aa-93cc8aee41da', '7bbd9757-534a-4be9-b602-87441bb86faf', 'b', 'Pueden incluir un pictograma para indicar su objetivo, utilizando la simbología apropiada de la Organización Hidrográfica Internacional.', true, '2025-09-13 13:53:12.036828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfcab3a2-4180-4eff-8bf9-9ad77367f1fb', '7bbd9757-534a-4be9-b602-87441bb86faf', 'c', 'Su marca de tope es amarilla en forma de cruz vertical.', false, '2025-09-13 13:53:12.036969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26868825-742a-41b6-89be-0899c00a4ca1', '7bbd9757-534a-4be9-b602-87441bb86faf', 'd', 'Su forma es de libre elección entre esférica, de castillete o espeque, pero siempre con una marca de tope en forma de cruz vertical.', false, '2025-09-13 13:53:12.037109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b95e8c05-5aae-46d7-ae6b-324e9e34c23c', '405d9963-2987-4c9f-a0e0-878938835801', 'a', 'Grupos de 3 centelleos rápidos cada 5 segundos.', true, '2025-09-13 13:53:12.03741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5635d3d-a537-4bfe-993b-8a5afa4c5807', '405d9963-2987-4c9f-a0e0-878938835801', 'b', 'Grupos de 9 centelleos rápidos cada 10 segundos.', false, '2025-09-13 13:53:12.037549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2666772-d9e2-40c4-95c3-0615ed7a3f8d', '405d9963-2987-4c9f-a0e0-878938835801', 'c', 'Grupos de 6 centelleos rápidos cada 10 segundos.', false, '2025-09-13 13:53:12.037682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2958194-3607-4d4d-8231-ae6cdcd103a2', '77a042ac-17ff-4222-ac45-9fd803598576', 'b', 'Efectúe la descarga saliendo de zona 7, a través de un inodoro que disponga de una instalación certificada.', false, '2025-09-13 13:53:12.035893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b06b0b50-1f67-47f0-b103-84803b39abec', '7bbd9757-534a-4be9-b602-87441bb86faf', 'a', 'Su color es de libre elección, pero que no se preste a confusión con las marcas para ayuda a la navegación.', false, '2025-09-13 13:53:12.036685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebbf237e-9c54-4664-88e8-635218f7aa3a', 'b28313f5-1132-45c0-83ee-b081b16f63f2', 'c', 'Únicamente se permitirá la descarga de residuos de carga a menos de.', false, '2025-09-13 13:53:12.03525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc400138-bd4b-4294-969c-716aabd94a10', '9b98c1ec-ade3-4d28-b430-b8ef2cdcce79', 'a', 'Se aproxima a un puerto, río, estuario u otra vía acuática desde el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección contraria a la de las agujas del reloj alrededor de las masas de tierra.', false, '2025-09-13 13:53:12.038236+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21f52d4e-2f0a-4d57-a399-4524b7dba377', '9b98c1ec-ade3-4d28-b430-b8ef2cdcce79', 'b', 'Se aproxima a un puerto, río, estuario u otra vía acuática desde el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección de las agujas del reloj alrededor de las masas de tierra.', true, '2025-09-13 13:53:12.038399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a015ae5-1f77-4baa-bba4-30b59c609fa1', '9b98c1ec-ade3-4d28-b430-b8ef2cdcce79', 'c', 'Se aleja de un puerto, río, estuario u otra vía acuática hacia el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección contraria a la de las agujas del reloj alrededor de las masas de tierra.', false, '2025-09-13 13:53:12.038549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aed3ebe6-61cd-4ffc-815d-6266e8041956', '9b98c1ec-ade3-4d28-b430-b8ef2cdcce79', 'd', 'Se aleja de un puerto, río, estuario u otra vía acuática hacia el mar o la determinada por autoridad pertinente que, en principio, debe seguir la dirección de las agujas del reloj alrededor de las masas', false, '2025-09-13 13:53:12.03872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dee2a5b6-bed4-4d1f-baa1-3ce54d2f322a', '2bd505fa-e106-4729-9a71-3139eba940a4', 'd', 'Cónicas, de castillete o espeque, con franjas horizontales rojas o blancas, y su marca de tope es una esfera amarilla.', false, '2025-09-13 13:53:12.039483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('420d7aff-65ba-44bb-a6aa-d10f6576f005', '7b3a268a-35ed-4069-a139-0ae955a05982', 'a', 'Se coloca próxima o sobre aguas navegables rodeadas por todas partes de un peligro.', false, '2025-09-13 13:53:12.039789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef799016-d059-4788-8d7e-58429f5b6f2c', '7b3a268a-35ed-4069-a139-0ae955a05982', 'b', 'Según el ritmo y color de su luz especifican el tamaño del peligro y la distancia a la que puede utilizarse con seguridad la embarcación.', false, '2025-09-13 13:53:12.039953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dd56f4d-7cf0-4d32-9aea-aeb7b8605b48', '7b3a268a-35ed-4069-a139-0ae955a05982', 'c', 'Es negra, con una o más bandas anchas horizontales rojas. Su marca de tope está formada por dos conos negros superpuestos y la luz es blanca.', false, '2025-09-13 13:53:12.040117+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8518a2e-2f7a-4f41-850c-927d95dd58c0', '85985e90-2757-4440-a44b-75f843f85dbe', 'a', 'Cuando uno de los dos buques deba mantenerse apartado de la derrota del otro, este último mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:12.040572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b1f7d12-64d1-4ca6-881d-a1d497104296', '85985e90-2757-4440-a44b-75f843f85dbe', 'b', 'Cuando, por cualquier causa, el buque que haya de mantener su rumbo y velocidad se encuentre tan próximo al otro que no pueda evitarse el abordaje por la sola maniobra del buque que cede el paso, el primero ejecutará la maniobra que mejor pueda ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.040711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4e37f79-ef15-444b-a335-82ea2344fb4c', '85985e90-2757-4440-a44b-75f843f85dbe', 'c', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, no cambiará su rumbo a babor para maniobrar a un buque que se encuentre por esa misma banda si las circunstancias del caso lo permiten.', false, '2025-09-13 13:53:12.040851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('506bef8c-ee24-425d-8ea3-383f6d91ece3', '85985e90-2757-4440-a44b-75f843f85dbe', 'd', 'La presente Regla exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:12.040984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d75b35c5-54ed-4638-9446-df3515381b28', '8f425f25-48b4-45a2-bb05-00f522aaf1be', 'a', 'No estorbarán el tránsito de un buque que sólo pueda navegar con seguridad dentro del canal.', true, '2025-09-13 13:53:12.041263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fea41f8-5f37-4c41-b251-16a1f89a5983', '8f425f25-48b4-45a2-bb05-00f522aaf1be', 'b', 'No podrán transitar a vela el canal.', false, '2025-09-13 13:53:12.041396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a463f1f9-9f33-4a98-9458-e68d5f0278c5', '8f425f25-48b4-45a2-bb05-00f522aaf1be', 'c', 'Deberán hacer sonar dos pitadas largas cada 20 segundos para indicar su tránsito por el canal.', false, '2025-09-13 13:53:12.041525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e65b760-a3e8-4292-9003-05d750e97ea1', '8f425f25-48b4-45a2-bb05-00f522aaf1be', 'd', 'No estorbarán el tránsito de un buque dedicado a la pesca que esté faenando en el canal.', false, '2025-09-13 13:53:12.041657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('584dad21-3acd-47a6-8538-66d85450e82d', '0d197c5a-9b62-4f12-aef2-076ce10755ac', 'a', 'Popa viendo la luz de tope blanca y ambas luces de costado.', false, '2025-09-13 13:53:12.041963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8484d6c1-0ee9-4228-8049-5c2ffae24c72', '0d197c5a-9b62-4f12-aef2-076ce10755ac', 'b', 'Popa viendo la luz de alcance.', false, '2025-09-13 13:53:12.042112+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c02c898-8b76-41e5-a300-cf614bc92603', '0d197c5a-9b62-4f12-aef2-076ce10755ac', 'c', 'Proa viendo la luz de alcance y la verde de costado.', false, '2025-09-13 13:53:12.042241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17aa6d9b-c6ca-40c3-b12a-873d6bf21865', '0d197c5a-9b62-4f12-aef2-076ce10755ac', 'd', 'Proa viendo la luz de tope y la roja de costado.', true, '2025-09-13 13:53:12.04237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d4f515e-5844-43a3-b453-4268df536c7b', 'b8ff386b-843f-487b-83da-1010cdccb427', 'a', 'Su maquinaria propulsora, en caso de llevarla, no se esté utilizando.', true, '2025-09-13 13:53:12.042646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cafe4ff2-ff5c-48b2-8c92-54e3ee323db2', 'b8ff386b-843f-487b-83da-1010cdccb427', 'b', 'Su maquinaria propulsora principal sean dichas velas y otro medio mecánico que no incluirá en ningún caso motores de combustión interna.', false, '2025-09-13 13:53:12.042787+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d15a0b06-1ff1-4fae-9f0b-a780bd0a58cb', 'b8ff386b-843f-487b-83da-1010cdccb427', 'c', 'Su maquinaria propulsora, en caso de llevarla, se esté utilizando.', false, '2025-09-13 13:53:12.04292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ac8e378-2497-413f-a2ce-bd9314db8a9b', 'b8ff386b-843f-487b-83da-1010cdccb427', 'd', 'El velamen del buque tenga superficie vélica suficiente para maniobrar la embarcación.', false, '2025-09-13 13:53:12.04305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c4ca433-42d7-4a4f-9a0a-8ad1ec71f4ad', '253a440f-a78f-4207-bec1-1b6d004f33b1', 'a', 'Amarillo con un cuadrado verde y un círculo.', false, '2025-09-13 13:53:12.043334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92cdc315-29f1-4263-a805-a26a7b80d234', '253a440f-a78f-4207-bec1-1b6d004f33b1', 'b', 'Rojo con un cuadrado amarillo y un círculo.', false, '2025-09-13 13:53:12.043464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6251d804-f8ae-4c8f-9924-202fab6904e3', '253a440f-a78f-4207-bec1-1b6d004f33b1', 'c', 'Verde con un cuadrado rojo y un círculo.', false, '2025-09-13 13:53:12.043596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39107c55-ccde-4db1-a596-20a62c444b3f', '253a440f-a78f-4207-bec1-1b6d004f33b1', 'd', 'Naranja con un cuadrado negro y un círculo.', true, '2025-09-13 13:53:12.043741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75c9763e-3802-41cf-86d9-27ae1c829347', '642e7dee-eac3-46a8-a732-5cd87239b916', 'a', 'En general, un hidroavión amarado se mantendrá alejado de todos los buques y evitará estorbar su navegación. No obstante, en aquellas circunstancias en que exista un riesgo de abordaje, cumplirá con las reglas de rumbo y gobierno.', false, '2025-09-13 13:53:12.044046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f27855a-aebb-4e25-9829-f2081c89eeb9', '642e7dee-eac3-46a8-a732-5cd87239b916', 'b', 'Cuando despeguen, aterricen o vuelen cerca de la superficie, las naves de vuelo rasante se mantendrán bien alejadas de todos los demás buques y evitarán entorpecer la navegación de éstos.', false, '2025-09-13 13:53:12.044183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfad39d1-3857-4914-9156-44f1f6eb624d', '642e7dee-eac3-46a8-a732-5cd87239b916', 'c', 'Un buque restringido por su calado navegará con particular precaución teniendo muy en cuenta su condición especial.', false, '2025-09-13 13:53:12.044316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a55545f0-bf95-4369-b9d3-635611a93dc8', '642e7dee-eac3-46a8-a732-5cd87239b916', 'd', 'Las naves de vuelo rasante que naveguen por la superficie del agua no estarán obligadas a cumplir lo dispuesto en las reglas de rumbo y gobierno como si fueran buques de propulsión', true, '2025-09-13 13:53:12.044458+00');
