INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebf7f9d9-00f6-4281-8dac-e0e8dddbbd6c', '865cd8ad-e7c6-4c80-9301-76523bb146ef', 'a', 'Son las regiones donde la presión atmosférica es más alta que la del aire circundante.', false, '2025-09-13 13:53:12.052128+00');
