INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d863a14-f40b-44e2-87b5-d4b133c525fd', '006e4de5-a603-4e80-ae2e-2e85b9509a4d', 'a', 'El eje de simetría longitudinal de la proyección horizontal del casco.', true, '2025-09-13 13:53:12.062137+00');
