INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ed85556-97e1-4e54-9635-28430f8564d2', '006e4de5-a603-4e80-ae2e-2e85b9509a4d', 'd', 'La línea transversal al plano de crujía que pasa por el centro de gravedad.', false, '2025-09-13 13:53:12.062528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ade3d6f-4ca7-4408-a734-58f9793cfc94', 'a9bbcba0-4ad3-4319-bad3-72993f866ccd', 'a', 'Gira en el sentido de las agujas del reloj cuando la embarcación avanza.', true, '2025-09-13 13:53:12.062808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b519c3fc-c628-4591-8ef5-1b2056a6ceca', 'a9bbcba0-4ad3-4319-bad3-72993f866ccd', 'b', 'Gira en el sentido de las agujas del reloj cuando la embarcación retrocede.', false, '2025-09-13 13:53:12.062942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc915f04-aa2c-4fc4-b882-1c9c9e8ec1d3', 'a9bbcba0-4ad3-4319-bad3-72993f866ccd', 'c', 'En marcha avante hace que la popa caiga a babor.', false, '2025-09-13 13:53:12.06307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('838ee05e-7ae9-405b-996f-f0f5e344109c', '2bec025d-8889-435b-bb28-6b66b0f82411', 'a', 'La gaza es el arco o curvatura que forma el cabo entre los extremos cuando éste no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:12.063467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b02af4d1-40ab-47a3-91b3-a7a040e2e611', '2bec025d-8889-435b-bb28-6b66b0f82411', 'b', 'El as de guía es un nudo que sirve para unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:12.063596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d4c056a-5064-4ef8-8bc4-050666f924d0', '2bec025d-8889-435b-bb28-6b66b0f82411', 'c', 'Un noray es una pieza de hierro, de forma cilíndrica ensanchada en su parte superior, fijada en los muelles para hacer firmes las amarras de los barcos.', true, '2025-09-13 13:53:12.063735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('137a45fa-0b19-41fd-bb30-da34a02d855e', '2bec025d-8889-435b-bb28-6b66b0f82411', 'd', 'Una boya es una pieza que se coloca en el costado de la embarcación para evitar que se dañe cuando está amarrada.', false, '2025-09-13 13:53:12.063885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('574d423d-2779-4cc5-9cba-aef6c07ecd28', 'd063990c-464d-45fd-b15f-38059ed2972a', 'a', 'Nos acercaremos al lugar de fondeo elegido con el ancla a la pendura, dando la popa la viento y con velocidad de gobierno con arrancada.', false, '2025-09-13 13:53:12.064158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3543287-1d1b-4962-8d07-0e114dea4143', 'd063990c-464d-45fd-b15f-38059ed2972a', 'b', 'El punto de fondeo debe elegirse de forma que como mínimo se mantenga libre de obstáculos un círculo de radio igual a la longitud de la cadena filada más la eslora de la embarcación.', true, '2025-09-13 13:53:12.064291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fc05171-1c4a-4e4f-ac8d-d69ad1c02885', 'd063990c-464d-45fd-b15f-38059ed2972a', 'c', 'Se utilizarán dos anclas, cuyos ángulos de fondeo formen un ángulo entre 60º y 120º.', false, '2025-09-13 13:53:12.064422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81f1f9d9-c659-4fb0-91d7-fb30b8f1ec09', 'd063990c-464d-45fd-b15f-38059ed2972a', 'd', 'Se utilizarán dos anclas, una por proa y otra por popa.', false, '2025-09-13 13:53:12.064558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf85f1be-7470-4474-9f3c-a1e6c3bcb6d2', '6c18bc84-c639-4cb3-91c3-2cdbff977a67', 'a', 'La temperatura del aceite.', false, '2025-09-13 13:53:12.064833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4909ce0c-8ac5-402e-b1cd-e79469a39006', '6c18bc84-c639-4cb3-91c3-2cdbff977a67', 'b', 'La temperatura del combustible.', false, '2025-09-13 13:53:12.064965+00');
