INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9645819d-3f46-401c-8cfd-e874af0a7581', 'b8975520-4dc3-4a2c-b09f-2e689a016020', 'c', '33º C.', false, '2025-09-13 13:53:12.066484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('278fdde8-9a61-47bf-ba51-63fa2b410076', 'b8975520-4dc3-4a2c-b09f-2e689a016020', 'd', '32º C.', false, '2025-09-13 13:53:12.066613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81b2ab45-25ec-44fe-99e4-6ac601a5feaf', 'b0f7133a-3686-4254-a964-55279da33194', 'a', 'Llevar la máxima velocidad disponible.', false, '2025-09-13 13:53:12.066891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d55233c3-7f23-4a22-b639-81a6b99d2e16', 'b0f7133a-3686-4254-a964-55279da33194', 'b', 'Llevar un ancla lista para fondear.', true, '2025-09-13 13:53:12.067025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb55e578-184c-4d63-8cfc-e23b6d6135af', 'a9bbcba0-4ad3-4319-bad3-72993f866ccd', 'd', 'En marcha atrás hace que la popa caiga a estribor.', false, '2025-09-13 13:53:12.063198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ccbebfa-ce89-4054-89e3-6f37712f6a89', 'b93abd0d-1bdf-462e-862f-d3ee43c12d9a', 'b', 'En llevar la mar por la amura, navegando a una velocidad reducida para sincronizarse con las olas.', false, '2025-09-13 13:53:12.065674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12e99e42-d460-4885-ae83-d809e6e10294', '4020e832-24c7-4727-bced-e1652fba5fbc', 'd', 'Marca el límite de las aguas abrigadas.', false, '2025-09-13 13:53:12.057461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dabebe5b-486a-4da0-beaf-8fb34091f902', 'b0f7133a-3686-4254-a964-55279da33194', 'c', 'Gobernar con poco timón, procurando no levantarlo en ningún momento.', false, '2025-09-13 13:53:12.067154+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23b3770e-ab87-48c7-b029-4229fcf9eeda', 'b0f7133a-3686-4254-a964-55279da33194', 'd', 'Al maniobrar a un barco que navegue de “vuelta encontrada”, hacerlo inmediatamente metiendo', false, '2025-09-13 13:53:12.067289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd3f63b4-0b53-4cda-8f27-1a8bcc615ea5', '5e217e44-a895-4200-bcf7-1549d5101343', 'a', 'A una distancia superior a 3 millas náuticas de la tierra más próxima si las aguas sucias han sido previamente desmenuzadas y desinfectadas mediante un sistema dotado de medios que permitan almacenarlas temporalmente, siempre que sea aprobado u homologado por la Administración Marítima española.', true, '2025-09-13 13:53:12.06756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70d25156-11b1-4abe-875e-984cf25bcc14', '5e217e44-a895-4200-bcf7-1549d5101343', 'b', 'A una distancia superior a 3 millas náuticas e inferior a 12 millas náuticas de la tierra más próxima, hayan sido o no previamente desmenuzadas y desinfectadas, si han estado almacenadas en sistemas de retención que se descarguen a un régimen moderado.', false, '2025-09-13 13:53:12.067699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dd3a39b-2d60-4192-8899-fc994f233a17', '5e217e44-a895-4200-bcf7-1549d5101343', 'c', 'A una distancia no superior a zona 7, si se utiliza algún sistema de retención por el que las aguas sucias se descarguen instantáneamente, hallándose la embarcación en ruta navegando a velocidad no inferior a 4 nudos.', false, '2025-09-13 13:53:12.067839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c276b96c-2fd8-4467-8c9b-b3bb03f1f9c9', '5e217e44-a895-4200-bcf7-1549d5101343', 'd', 'Fuera de zona 7, si las aguas sucias han estado almacenadas en algún sistema de retención que se descargue instantáneamente aprobado u homologado por la Administración Marítima española, hallándose la embarcación en ruta navegando a velocidad no superior a 4 nudos.', false, '2025-09-13 13:53:12.067988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('776eab82-6f8d-4ce8-9d03-fa386a07d81b', 'cc7443aa-174c-4fbd-966f-b78c7d9973f8', 'a', 'Está prohibida en todo caso, sin que quepa excepción alguna.', false, '2025-09-13 13:53:12.068265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f47967da-d387-469d-b6f5-248539448110', 'cc7443aa-174c-4fbd-966f-b78c7d9973f8', 'b', 'Está permitida si se realiza a menos de 12 millas marinas de la tierra más próxima y siempre que no esté contaminado con otro tipo de basuras.', false, '2025-09-13 13:53:12.068397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('190f80d1-60a2-43b4-80b8-79fe5404f080', 'cc7443aa-174c-4fbd-966f-b78c7d9973f8', 'd', 'Está permitida siempre que se realice a más de 12 millas marinas de la tierra más próxima, mientras la embarcación no se encuentre en ruta y junto a los demás desechos de alimentos que deberán estar desmenuzados o triturados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', false, '2025-09-13 13:53:12.068657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8bfb421-2c1c-48d2-909f-71b75992aff0', '69d9fbe5-4b26-4860-8a0f-671148bd545c', 'a', 'De forma cónica de color rojo con una banda ancha horizontal verde.', false, '2025-09-13 13:53:12.068941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8d6ea49-10fe-421d-9f3b-f6a74b80af3c', '69d9fbe5-4b26-4860-8a0f-671148bd545c', 'b', 'De forma cónica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:12.069069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfc9eb00-5db9-4c4d-b025-4abdd142f875', '69d9fbe5-4b26-4860-8a0f-671148bd545c', 'c', 'De forma cilíndrica de color rojo con una banda ancha horizontal verde.', true, '2025-09-13 13:53:12.069197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('328e4e2a-c667-49f2-b363-0c0f6844d93a', '69d9fbe5-4b26-4860-8a0f-671148bd545c', 'd', 'De forma cilíndrica de color verde con una banda ancha horizontal roja.', false, '2025-09-13 13:53:12.069324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89597d98-3b02-4b95-aa09-3483adb0d75b', '1fefb62c-eef4-4364-8e7a-a56c4e41dbeb', 'a', 'Que para salvar un peligro debemos navegar por el cuadrante Norte de la Marca.', false, '2025-09-13 13:53:12.069595+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00f00658-64a1-43db-ac81-7aaf65f5e7b8', '1fefb62c-eef4-4364-8e7a-a56c4e41dbeb', 'b', 'Que las aguas más profundas en esa zona se encuentran en el cuadrante Este.', false, '2025-09-13 13:53:12.069744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5493dca-0ae3-49a3-be90-d4f296fdd690', '1fefb62c-eef4-4364-8e7a-a56c4e41dbeb', 'c', 'Que hay una confluencia en el cuadrante Sur.', false, '2025-09-13 13:53:12.06988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f37b8a7-a163-4f00-b438-e9753ff480ac', '1fefb62c-eef4-4364-8e7a-a56c4e41dbeb', 'd', 'Que para salvar un peligro debemos navegar por el cuadrante Oeste de la Marca.', true, '2025-09-13 13:53:12.070007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b3218b0-d5c8-448b-8cc3-d320eefc3723', 'f96ac416-5b71-47b8-a887-f312a7ad1cd3', 'a', 'Roja y continua.', false, '2025-09-13 13:53:12.070274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b80fa924-a8fe-4611-9230-4425a5b356ad', 'f96ac416-5b71-47b8-a887-f312a7ad1cd3', 'b', 'Blanca y destellos en grupo de dos.', true, '2025-09-13 13:53:12.070402+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdf55a6d-7ae2-464c-a252-3ca17109c89b', 'f96ac416-5b71-47b8-a887-f312a7ad1cd3', 'c', 'Amarilla y ritmo centelleante rápido.', false, '2025-09-13 13:53:12.070534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd9b2927-bc96-4558-9912-9e650906ecba', 'f96ac416-5b71-47b8-a887-f312a7ad1cd3', 'd', 'Verde con un destello largo cada diez segundos.', false, '2025-09-13 13:53:12.070666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ceefea5d-4bb7-4f94-883a-83a5fae90518', '4f18a0f7-3493-4c9e-9353-e3a4b05584de', 'a', 'Su presencia conlleva para el navegante la necesidad de consultar la carta y las publicaciones náuticas porque indican una zona o configuración particular cuya naturaleza se indica en ellas.', true, '2025-09-13 13:53:12.070949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02677ad4-d2a6-4031-bf9a-7593b6355e75', '4f18a0f7-3493-4c9e-9353-e3a4b05584de', 'b', 'Tienen como objetivo principal señalar canales u obstrucciones e indicar zonas o configuraciones particulares de carácter especial.', false, '2025-09-13 13:53:12.071079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('267f1ae1-5f32-4369-b6aa-34f75244ad58', '4f18a0f7-3493-4c9e-9353-e3a4b05584de', 'c', 'Se utilizan para llamar la atención sobre una configuración especial de un canal, tal como un recodo una confluencia, una bifurcación o el extremo de un bajo fondo.', false, '2025-09-13 13:53:12.071206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8eff0d3-fd5b-490f-9e05-df4fb7c27823', '4f18a0f7-3493-4c9e-9353-e3a4b05584de', 'd', 'Su uso principal es indicar el sentido convencional del balizamiento, que debe indicarse en los documentos náuticos apropiados, en zonas con una configuración especial.', false, '2025-09-13 13:53:12.071332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64c38637-faf7-4715-bc82-e975d0df422d', '3d7d5e43-0f7d-430d-a2aa-4424cfcf336e', 'a', 'Serán siempre de color blanco y su luz (si tiene) tendrá un ritmo de ocultaciones, un destello largo cada 10 segundos.', false, '2025-09-13 13:53:12.071602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e367953b-3a49-4693-aa2f-9de75be6fd92', '3d7d5e43-0f7d-430d-a2aa-4424cfcf336e', 'b', 'Consistirán en franjas horizontales negras sobre blanco y su luz (si tiene) será de color amarillo.', false, '2025-09-13 13:53:12.071735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a3ca070-5aa4-4325-a097-e8f7006bccaa', '3d7d5e43-0f7d-430d-a2aa-4424cfcf336e', 'c', 'Serán de color negro con una o varias anchas bandas diagonales rojas y su luz (si tiene) tendrá un ritmo de grupos de dos destellos GpD (2).', false, '2025-09-13 13:53:12.071866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ddc8090-0f7e-4e92-a37c-986bfa6e65dd', '3d7d5e43-0f7d-430d-a2aa-4424cfcf336e', 'd', 'Serán siempre de color rojo y blanco en franjas verticales y su luz (si tiene) será de color blanco. Reglamento (RIPA).', true, '2025-09-13 13:53:12.072001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ac75310-7daf-43ea-9335-c5660efa3807', '48c9eda9-6c0d-4217-81cf-e24c3a06e309', 'a', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior.', false, '2025-09-13 13:53:12.072265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('370cd9d1-775f-44fe-9ca3-40318c1b7180', '48c9eda9-6c0d-4217-81cf-e24c3a06e309', 'b', 'Las luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.072396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('913df317-f2bf-4bde-b3fb-16614d65d0a3', '48c9eda9-6c0d-4217-81cf-e24c3a06e309', 'c', 'Las luces de costado, una luz de alcance y una luz verde todo horizonte.', false, '2025-09-13 13:53:12.072524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05416efb-f1e8-42df-bae4-d5a5a3d0cac2', '48c9eda9-6c0d-4217-81cf-e24c3a06e309', 'd', 'Dos luces blancas todo horizonte en línea vertical.', false, '2025-09-13 13:53:12.07265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c3bf631-364f-483d-894b-782d7feb95f1', '05110f54-9266-469f-817b-7aee9043a360', 'a', 'La demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:12.072928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa292393-ba92-4d0c-ae7c-61a0d5e665d1', '05110f54-9266-469f-817b-7aee9043a360', 'b', 'La demora de un buque que se aproxima varía en forma apreciable.', false, '2025-09-13 13:53:12.073066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38daa565-ace3-455b-b0e6-79c6a07e62e9', '05110f54-9266-469f-817b-7aee9043a360', 'd', 'La demora del buque que se aleja varía en forma apreciable.', false, '2025-09-13 13:53:12.073328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81d1cd69-7b32-4939-bb3c-355f73570bf7', 'eeac7e17-c318-4111-9add-850f4d08e9da', 'a', 'A intervalos que no excedan de dos minutos, dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:12.0736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5859f923-511a-4196-977d-c615787f145a', 'eeac7e17-c318-4111-9add-850f4d08e9da', 'b', 'A intervalos que no excedan de dos minutos, dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.073728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b50f94e-2ec4-46b4-b11d-864b861ad8e3', 'eeac7e17-c318-4111-9add-850f4d08e9da', 'c', 'Una pitada larga a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:12.073875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4a0295c-ef6e-4841-b9de-1ada239700e2', 'eeac7e17-c318-4111-9add-850f4d08e9da', 'd', 'Una pitada corta a intervalos que no excedan de dos minutos.', false, '2025-09-13 13:53:12.074014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac57824c-5038-4369-97c7-64808a2ce665', '8ce6742c-6acc-4f41-ba3f-5ed1131e33b3', 'd', 'La bajamar, que es el momento en que la marea está más baja. Meteorología', false, '2025-09-13 13:53:12.082473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('188f6415-c872-486d-88a5-287b1c13da6c', '78417448-fc50-4af1-8fc5-be15773e5775', 'a', '1,013.', false, '2025-09-13 13:53:12.082748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('497355ef-3331-4a06-8437-6169864f8d54', '05110f54-9266-469f-817b-7aee9043a360', 'c', 'Principalmente la velocidad del buque que se aproxima está por encima de la velocidad de seguridad.', false, '2025-09-13 13:53:12.073196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13752d2c-209e-4bf7-9002-f07b82f55038', '071b49ce-cb37-4a44-a9ff-029da9212d69', 'a', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', true, '2025-09-13 13:53:12.074298+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb2ce8cc-4cb5-491f-9047-ff563c8090a5', '071b49ce-cb37-4a44-a9ff-029da9212d69', 'b', 'Cuando dos buques o embarcaciones, con independencia del tipo de propulsión que tengan, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de estribor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.074433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49c4ca94-b3d6-4dde-a94f-ae281611e533', '071b49ce-cb37-4a44-a9ff-029da9212d69', 'c', 'Cuando dos buques de propulsión mecánica se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.074584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09ad5244-afa8-4672-bfc7-23740de20589', '071b49ce-cb37-4a44-a9ff-029da9212d69', 'd', 'Cuando dos buques o embarcaciones, con independencia del tipo que sean, se crucen con riesgo de abordaje, el buque que tenga al otro por su costado de babor se mantendrá apartado de la derrota de este otro y, si las circunstancias lo permiten, evitará cortarle la proa.', false, '2025-09-13 13:53:12.074713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a58b0efd-bb05-4459-8d8a-8f0c0d57ebb5', 'd45bdae7-b578-4e5a-acdc-8445b7ff5136', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.074987+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5f08b15-5a04-438e-a714-38809ba3a10d', 'd45bdae7-b578-4e5a-acdc-8445b7ff5136', 'b', 'Se deberá mantener el rumbo, ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:12.075115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a155e713-791c-4bf0-8083-3bb7316b0306', 'd45bdae7-b578-4e5a-acdc-8445b7ff5136', 'c', 'Para la situación indicada no hay norma y por tanto se deberá tener en cuenta lo indicado para la situación de vuelta encontrada.', false, '2025-09-13 13:53:12.075243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9196b3e3-c968-46fc-b803-fde3ac18f40f', 'd45bdae7-b578-4e5a-acdc-8445b7ff5136', 'd', 'Se deberá maniobrar para caer a estribor de forma que se pase por la banda de babor del velero', false, '2025-09-13 13:53:12.075381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c433960-6a30-450d-aaf9-780e36e4fed6', '77d4644d-1c2b-4e0f-a808-8bdecc6735a2', 'a', 'Dado que se trata de una situación de buque que alcanza, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.075652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab439dfd-4aea-456a-843c-09f615b8228a', '77d4644d-1c2b-4e0f-a808-8bdecc6735a2', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', false, '2025-09-13 13:53:12.075784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24782cce-206b-4cad-8248-3a131c3223a2', '77d4644d-1c2b-4e0f-a808-8bdecc6735a2', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de babor.', false, '2025-09-13 13:53:12.075944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47b06abc-feac-4582-acc6-c0dbb456b23e', '77d4644d-1c2b-4e0f-a808-8bdecc6735a2', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', true, '2025-09-13 13:53:12.076081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0daa4174-cf08-40e5-ac3f-31846f964866', 'c5e9abde-a996-4320-b6a0-37a94c650f5d', 'a', 'Una luz blanca colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:12.076355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e93394eb-ddf2-4a92-aa7a-f9a394fdb2a8', 'c5e9abde-a996-4320-b6a0-37a94c650f5d', 'b', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz sin interrupción en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', true, '2025-09-13 13:53:12.076489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('078c869a-bcc5-496b-8d2b-fe36ca1f0f4a', 'c5e9abde-a996-4320-b6a0-37a94c650f5d', 'c', 'Una luz blanca colocada lo más cerca posible de la popa que muestra su luz centelleante en todo un arco del horizonte de 135 grados, fijada de forma que sea visible en un arco de 67,5 grados, contados a partir de la popa hacia cada una de las bandas del buque.', false, '2025-09-13 13:53:12.076628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a03d633a-25fa-4fdb-8245-aca132a3cbc8', 'c5e9abde-a996-4320-b6a0-37a94c650f5d', 'd', 'Una luz amarilla colocada lo más cerca posible de la proa que muestra su luz sin interrupción en todo un arco del horizonte de 360 grados.', false, '2025-09-13 13:53:12.076756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8a22102-d790-4f6b-ba0a-5175ee647d33', '023bfebc-db08-455e-b288-a1c848595848', 'a', 'Una luz blanca todo horizonte y luces de costado.', true, '2025-09-13 13:53:12.077034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2843a9ab-846b-489f-8e62-69d18cc78013', '023bfebc-db08-455e-b288-a1c848595848', 'b', 'Únicamente una luz de tope a proa.', false, '2025-09-13 13:53:12.07717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ee2a092-7233-42cf-a790-a8f4c350d516', '023bfebc-db08-455e-b288-a1c848595848', 'c', 'Únicamente una luz blanca todo horizonte.', false, '2025-09-13 13:53:12.077302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84bece67-5f44-479b-b061-28196866056a', '023bfebc-db08-455e-b288-a1c848595848', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirán también luces de costado.', false, '2025-09-13 13:53:12.077435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('278e0441-db4e-429b-9e3c-8ba9ab15ef2e', 'b3e00e5b-b1ab-4f97-a471-3fad5b721625', 'a', 'Dos luces de alcance en línea horizontal, de forma que quede señalizada la manga máxima del buque que remolca y del buque remolcado.', false, '2025-09-13 13:53:12.077707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('396b62b6-ac90-4f89-b148-3bdc95bf14c8', 'b3e00e5b-b1ab-4f97-a471-3fad5b721625', 'b', 'Dos luces de tope en línea vertical.', true, '2025-09-13 13:53:12.077845+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3beb2f5-5f71-46be-846c-e31e5156ca3d', 'b3e00e5b-b1ab-4f97-a471-3fad5b721625', 'c', 'Una luz de alcance amarilla.', false, '2025-09-13 13:53:12.077974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f154c980-9b1b-463a-b1fb-f34a73683a15', 'b3e00e5b-b1ab-4f97-a471-3fad5b721625', 'd', 'Una luz amarilla de centelleos todo horizonte.', false, '2025-09-13 13:53:12.078103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f90456a9-dcb4-4ead-b352-a975b2e8be38', '3ccc6791-6392-4d15-b31a-7e9cb771251b', 'a', 'Naranja.', true, '2025-09-13 13:53:12.078388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46e09b22-160b-4fcd-bcae-8eff0b29aaba', '3ccc6791-6392-4d15-b31a-7e9cb771251b', 'b', 'Amarillo.', false, '2025-09-13 13:53:12.078549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e45b58f-5099-4c33-aef2-f57dc6a0d112', '3ccc6791-6392-4d15-b31a-7e9cb771251b', 'c', 'Rojo.', false, '2025-09-13 13:53:12.078707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a39a5bc-e513-49d1-b723-374bd1d29eb4', '968b12b3-4c3c-4728-8d40-3cb171fe05af', 'a', 'La corriente.', false, '2025-09-13 13:53:12.079215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba91d0c1-b5b5-430b-b140-d11284005b97', '968b12b3-4c3c-4728-8d40-3cb171fe05af', 'b', 'El viento.', true, '2025-09-13 13:53:12.079394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05bb026d-fb70-4ff9-89f6-e93989b72f7f', '968b12b3-4c3c-4728-8d40-3cb171fe05af', 'c', 'Las olas.', false, '2025-09-13 13:53:12.079554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4638ec88-b28c-407b-b913-363e2e18670d', '968b12b3-4c3c-4728-8d40-3cb171fe05af', 'd', 'El garete.', false, '2025-09-13 13:53:12.079695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8336d409-23c1-40fe-9e67-6324940aeb7d', '804b0796-0eb2-4e05-8308-01a46a6fccb4', 'a', 'El viento real es nulo. El viento aparente viene de proa con una velocidad constante.', false, '2025-09-13 13:53:12.079988+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d64fdfd2-aa65-4065-8943-824149eb9635', '804b0796-0eb2-4e05-8308-01a46a6fccb4', 'b', 'El viento real es nulo. El viento aparente viene de popa con una velocidad constante.', false, '2025-09-13 13:53:12.08013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0529921-62f7-42b6-aabf-5e2956b38812', '804b0796-0eb2-4e05-8308-01a46a6fccb4', 'c', 'El viento aparente es nulo. El viento real viene de proa con una velocidad igual a la del barco.', false, '2025-09-13 13:53:12.080279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('430fdc69-a872-4e49-acda-5f3604fd4154', '804b0796-0eb2-4e05-8308-01a46a6fccb4', 'd', 'El viento aparente es nulo. El viento real viene de popa con una velocidad igual a la del barco. Emergencias en la mar.', true, '2025-09-13 13:53:12.080411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc827af8-cfe9-41bc-bf68-8ed1c6bd24c1', 'dd92137a-18cb-450d-aeea-08c255de187c', 'a', 'Si dispone de balsa salvavidas, tire de la driza para abrirla automáticamente sin amarrarla previamente a bordo.', false, '2025-09-13 13:53:12.080696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9253bc88-4320-44b5-ae02-bf048cb8d67c', 'dd92137a-18cb-450d-aeea-08c255de187c', 'b', 'Realice una llamada de socorro y active la radiobaliza manualmente únicamente una vez haya abandonado la embarcación.', false, '2025-09-13 13:53:12.080834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('467e29dc-b44b-40a3-a662-ab099567f377', 'dd92137a-18cb-450d-aeea-08c255de187c', 'c', 'Si precisa voltear la balsa, colóquese a barlovento, súbase sobre la botella de aíre comprimido y tire de las cinchas que cruzan la parte inferior de la balsa.', false, '2025-09-13 13:53:12.08097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94c3cbe6-2e76-4493-99b1-84b2eb8f940d', 'dd92137a-18cb-450d-aeea-08c255de187c', 'd', 'Si no dispone de balsa salvavidas, salte al agua y adopte la postura fetal, sin nadar, o flote abrazado a sus compañeros, para evitar la hipotermia.', true, '2025-09-13 13:53:12.081099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4245c447-1a0f-41be-95a6-8390eb7e799d', 'd4d9d65e-cfb5-46f8-a33b-dea9cbdfbec6', 'a', 'Chorro de agua.', false, '2025-09-13 13:53:12.081378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a24ae0a1-4d55-4a79-9034-a4cfd15874b3', 'd4d9d65e-cfb5-46f8-a33b-dea9cbdfbec6', 'b', 'Agua pulverizada.', false, '2025-09-13 13:53:12.081507+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('babf5c7c-4d61-4954-93e7-15ce3139dceb', 'd4d9d65e-cfb5-46f8-a33b-dea9cbdfbec6', 'c', 'Polvo seco.', true, '2025-09-13 13:53:12.081637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('606d0ec7-5152-4d0b-a5e1-cb36c4065dad', 'd4d9d65e-cfb5-46f8-a33b-dea9cbdfbec6', 'd', 'Arena.', false, '2025-09-13 13:53:12.081768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('749d5de9-0ddb-4774-b02a-6084aa16d637', '8ce6742c-6acc-4f41-ba3f-5ed1131e33b3', 'a', 'La pleamar, que es el momento en que la marea está más alta.', true, '2025-09-13 13:53:12.08205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de35708c-66cc-4192-97a1-a4e75a6a103c', '8ce6742c-6acc-4f41-ba3f-5ed1131e33b3', 'b', 'La bajamar, que es el momento en que la marea está más alta.', false, '2025-09-13 13:53:12.082185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccea9c71-0014-42a7-a597-6726383a8a78', '8ce6742c-6acc-4f41-ba3f-5ed1131e33b3', 'c', 'La pleamar, que es el momento en que la marea está más baja.', false, '2025-09-13 13:53:12.082333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a44753cb-faa8-4068-bd41-fa20d7b1037b', '78417448-fc50-4af1-8fc5-be15773e5775', 'b', '1.', false, '2025-09-13 13:53:12.082887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7012d85-c8dd-4502-8e7f-d1b66daffe8b', '78417448-fc50-4af1-8fc5-be15773e5775', 'c', '13.', false, '2025-09-13 13:53:12.083024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5f8e66f-30b0-463d-9c57-7012b4f1fa73', '78417448-fc50-4af1-8fc5-be15773e5775', 'd', '1013.', true, '2025-09-13 13:53:12.083151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9a139e3-b7cc-4f4c-ae57-b66332e6f2f7', '94d7c0bc-b022-4e4b-94b8-4890cb7b70a3', 'a', 'El anemómetro se utiliza para determinar la velocidad del viento.', true, '2025-09-13 13:53:12.083423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ec1f161-e0c4-4c47-880e-0cc0f71d5ffa', '94d7c0bc-b022-4e4b-94b8-4890cb7b70a3', 'b', 'El anemómetro se utiliza para determinar la dirección del viento.', false, '2025-09-13 13:53:12.08355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7602b56f-3b01-4100-8eac-7b542bb987d2', '94d7c0bc-b022-4e4b-94b8-4890cb7b70a3', 'c', 'La veleta se utiliza para determinar la velocidad del viento.', false, '2025-09-13 13:53:12.083677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a59c8b25-e070-48fe-9666-7a8e894dbd2e', '94d7c0bc-b022-4e4b-94b8-4890cb7b70a3', 'd', 'El catavientos se ubica en la parte más alta del palo mayor de la embarcación.', false, '2025-09-13 13:53:12.083806+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf845a53-097b-4601-ba11-36811157f8d3', '3f2fd7bc-a1a6-4e09-ac2b-b22ae913b017', 'a', 'El número de horas que el viento sopla en la misma dirección.', false, '2025-09-13 13:53:12.084073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03610319-d1f0-44cc-a82d-c3887029c1ff', '3f2fd7bc-a1a6-4e09-ac2b-b22ae913b017', 'b', 'La rapidez con la que el viento cambia de dirección.', false, '2025-09-13 13:53:12.0842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cce4c277-a915-4e12-9adb-cccb27e00e51', '3f2fd7bc-a1a6-4e09-ac2b-b22ae913b017', 'c', 'La velocidad con la que sopla el viento.', true, '2025-09-13 13:53:12.084327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b029ad3-34ea-4c38-9bde-acfedeb77898', '3f2fd7bc-a1a6-4e09-ac2b-b22ae913b017', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando este sopla con una dirección y fuerza constantes.', false, '2025-09-13 13:53:12.084455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aea76607-81fe-41dd-93fa-273135b21041', 'bc91a0be-e79a-4a0b-8dcb-816daed1e924', 'a', 'Su proceso de formación se denomina ciclogénesis.', false, '2025-09-13 13:53:12.08472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2403c3a7-e848-4b61-9b76-bc2d62be4a10', 'bc91a0be-e79a-4a0b-8dcb-816daed1e924', 'b', 'El aire fluye hacia el exterior de los anticiclones y desciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:12.084877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f486c4e9-7bb2-462c-aacb-cefed3ae7b40', 'bc91a0be-e79a-4a0b-8dcb-816daed1e924', 'c', 'Se llaman también altas presiones o, simplemente, altas.', true, '2025-09-13 13:53:12.08502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac77e230-d741-4125-88cd-5d0428ccbcae', '848eb69f-5a8b-4b1d-8658-7a243ba9658f', 'a', 'Publicaciones náuticas relativas a primeros auxilios y seguridad marítima.', false, '2025-09-13 13:53:12.085446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d464d835-662f-406b-a762-06137de5d646', '848eb69f-5a8b-4b1d-8658-7a243ba9658f', 'b', 'Representaciones con información relativa a la costa, impresas sobre la carta náutica en la parte inferior derecha.', false, '2025-09-13 13:53:12.085579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecfaba7e-9d8e-42c0-848c-16f18a5236b7', '848eb69f-5a8b-4b1d-8658-7a243ba9658f', 'c', 'Publicaciones con información adicional sobre la costa.', true, '2025-09-13 13:53:12.08571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52bfa989-3042-4ac8-a9d1-102fa2b4d25f', '848eb69f-5a8b-4b1d-8658-7a243ba9658f', 'd', 'Documentos que contienen información sobre balizamiento, radiocomunicaciones, seguridad marítima e instrucciones emitidas por SASEMAR.', false, '2025-09-13 13:53:12.085851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88313213-354b-4548-9287-be2cbeaf23dc', '6dfcb2ac-3c6d-4349-8c6c-90483bc3e506', 'a', 'Deriva.', true, '2025-09-13 13:53:12.086128+00');
