INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2ac3845-032b-43d9-bc6f-f47a031715ba', 'd58dbdd6-bf08-484d-b8b1-16ab21ecfe83', 'a', 'El viento real es nulo. El viento aparente viene de proa con una velocidad constante.', true, '2025-09-13 13:53:12.092398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b9b72c3-2e0b-4402-9ef2-d7f46c08d13d', 'd58dbdd6-bf08-484d-b8b1-16ab21ecfe83', 'b', 'El viento real es nulo. El viento aparente viene de popa con una velocidad constante.', false, '2025-09-13 13:53:12.092528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19fc75b8-607b-4bc5-8064-3eff1967363d', 'd58dbdd6-bf08-484d-b8b1-16ab21ecfe83', 'c', 'El viento aparente es nulo. El viento real viene de proa con una velocidad igual a la del barco.', false, '2025-09-13 13:53:12.092658+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0f59b37-a565-4ff2-baac-124bd7c736df', 'd58dbdd6-bf08-484d-b8b1-16ab21ecfe83', 'd', 'El viento aparente es nulo. El viento real viene de popa con una velocidad igual a la del barco. Emergencias en la mar.', false, '2025-09-13 13:53:12.092792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53301005-b2c9-4e0b-910c-9f8ac40d9573', 'e7cf5e50-6be0-490f-9da9-0b2fb657bac2', 'a', 'La pleamar, que es el momento en que la marea está más alta.', false, '2025-09-13 13:53:12.093068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c62f3671-5224-4591-82d4-7f7cb0b42c22', 'e7cf5e50-6be0-490f-9da9-0b2fb657bac2', 'b', 'La bajamar, que es el momento en que la marea está más alta.', true, '2025-09-13 13:53:12.093199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa9134e5-0536-4186-bf59-6cc27d7f3103', 'e7cf5e50-6be0-490f-9da9-0b2fb657bac2', 'c', 'La pleamar, que es el momento en que la marea está más baja.', false, '2025-09-13 13:53:12.093325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbff53cb-e8e8-4cbf-93ac-c81bca3b242e', 'e7cf5e50-6be0-490f-9da9-0b2fb657bac2', 'd', 'La bajamar, que es el momento en que la marea está más baja.', false, '2025-09-13 13:53:12.093455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c31de27c-7129-466e-94b1-a3dd29e7b804', '4fa9e3f0-9974-4406-b4cf-fbec5868ea44', 'a', 'Si dispone de balsa salvavidas, tire de la driza para abrirla automáticamente sin amarrarla previamente a bordo.', false, '2025-09-13 13:53:12.093726+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6dffe4c-6dd8-4fc5-ac4f-83a76d98be83', '4fa9e3f0-9974-4406-b4cf-fbec5868ea44', 'b', 'Realice una llamada de socorro y active la radiobaliza manualmente únicamente una vez haya abandonado la embarcación.', false, '2025-09-13 13:53:12.093857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2184132-3fb2-4e27-8f88-87a93a9c5f10', '4fa9e3f0-9974-4406-b4cf-fbec5868ea44', 'c', 'Si precisa voltear la balsa, colóquese a barlovento, súbase sobre la botella de aíre comprimido y tire de las cinchas que cruzan la parte inferior de la balsa.', false, '2025-09-13 13:53:12.093993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('990dd0ef-0a59-45fb-a5ff-6f266b814b60', '4fa9e3f0-9974-4406-b4cf-fbec5868ea44', 'd', 'Si no dispone de balsa salvavidas, salte al agua y adopte la postura fetal, sin nadar, o flote abrazado a sus compañeros, para evitar la hipotermia.', true, '2025-09-13 13:53:12.094121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('356b7667-5d26-4ab2-80c7-5100547f8921', 'd8e2ca87-c5e5-4ed1-819f-86835d320f29', 'a', 'Chorro de agua.', false, '2025-09-13 13:53:12.094401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4778011c-7479-444a-acb8-c10f807e1eb7', 'd8e2ca87-c5e5-4ed1-819f-86835d320f29', 'b', 'Agua pulverizada.', false, '2025-09-13 13:53:12.094535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccac8b91-295d-43db-9853-8408feada5c5', 'd8e2ca87-c5e5-4ed1-819f-86835d320f29', 'c', 'Polvo seco.', true, '2025-09-13 13:53:12.094664+00');
