INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02b453e2-c9df-4982-93b5-165ba09c9983', '23b7ee6f-3d6d-44ca-a079-238d94dd31af', 'a', 'El anemómetro se utiliza para determinar la velocidad del viento.', false, '2025-09-13 13:53:12.095133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ef20512-f27e-47af-9071-4a803bd8c76e', '23b7ee6f-3d6d-44ca-a079-238d94dd31af', 'b', 'El anemómetro se utiliza para determinar la dirección del viento.', false, '2025-09-13 13:53:12.095266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a765788c-e528-4437-951f-cf7c21072adf', '23b7ee6f-3d6d-44ca-a079-238d94dd31af', 'c', 'La veleta se utiliza para determinar la velocidad del viento.', false, '2025-09-13 13:53:12.095399+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('590677d6-8802-4070-bbd2-63d05e0be287', '23b7ee6f-3d6d-44ca-a079-238d94dd31af', 'd', 'El catavientos se ubica en la parte más alta del palo mayor de la embarcación.', true, '2025-09-13 13:53:12.095528+00');
