INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de8bca7d-5497-4ed3-a249-ecce6be57f09', '12a90b78-d515-456d-8ca0-4d4bb5cd2fbe', 'a', 'Su proceso de formación se denomina ciclogénesis.', false, '2025-09-13 13:53:12.096464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cae68638-6cd7-4d6f-b640-67bc22ab51ce', '12a90b78-d515-456d-8ca0-4d4bb5cd2fbe', 'b', 'El aire fluye hacia el exterior de los anticiclones y desciende desde allí, lo que produce formación de nubosidad y precipitaciones.', false, '2025-09-13 13:53:12.096594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f03d3ea-2dca-4bc9-9ed9-8deca3f49aa3', '12a90b78-d515-456d-8ca0-4d4bb5cd2fbe', 'c', 'Se llaman también altas presiones o, simplemente, altas.', false, '2025-09-13 13:53:12.096721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37ab94a7-292c-485c-ab0f-92f1382d0d97', '12a90b78-d515-456d-8ca0-4d4bb5cd2fbe', 'd', 'La presión más baja se localiza siempre en el centro.', true, '2025-09-13 13:53:12.096853+00');
