INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16f096df-a693-4add-af70-212f3688bf79', 'fbd5ac8d-7254-4b90-ad3f-911beca094c7', 'b', 'El viento real es nulo. El viento aparente viene de popa con una velocidad constante.', false, '2025-09-13 13:53:12.104914+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e213802d-74cd-4301-8814-55272f0a03f8', 'fbd5ac8d-7254-4b90-ad3f-911beca094c7', 'c', 'El viento aparente es nulo. El viento real viene de proa con una velocidad igual a la del barco.', false, '2025-09-13 13:53:12.105042+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1dc7ec01-9f14-42dc-b5bb-32911c70a785', 'fbd5ac8d-7254-4b90-ad3f-911beca094c7', 'd', 'El viento aparente es nulo. El viento real viene de popa con una velocidad igual a la del barco. Emergencias en la mar.', true, '2025-09-13 13:53:12.105178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('038d5f37-f433-4be3-8771-df8b435b62a9', '46cbc4d5-285b-4d72-b082-dbab7d4a3347', 'a', 'Si dispone de balsa salvavidas, tire de la driza para abrirla automáticamente sin amarrarla previamente a bordo.', false, '2025-09-13 13:53:12.105451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bac79c34-34c9-480f-88a0-fc3fa9cab8b4', '46cbc4d5-285b-4d72-b082-dbab7d4a3347', 'b', 'Realice una llamada de socorro y active la radiobaliza manualmente únicamente una vez haya abandonado la embarcación.', false, '2025-09-13 13:53:12.10558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64c5cc6c-2cc2-4c68-a02e-8a5a8723a3d2', '46cbc4d5-285b-4d72-b082-dbab7d4a3347', 'c', 'Si precisa voltear la balsa, colóquese a barlovento, súbase sobre la botella de aíre comprimido y tire de las cinchas que cruzan la parte inferior de la balsa.', false, '2025-09-13 13:53:12.10572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02094295-0be3-4a36-a98b-d0194cff276d', '46cbc4d5-285b-4d72-b082-dbab7d4a3347', 'd', 'Si no dispone de balsa salvavidas, salte al agua y adopte la postura fetal, sin nadar, o flote abrazado a sus compañeros, para evitar la hipotermia.', true, '2025-09-13 13:53:12.105862+00');
