INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98715774-86d4-40e6-a44a-8e48ef68bc26', '3e0b17c4-3932-46ef-a4b5-80cc9861417e', 'a', 'Como consecuencia de la escora, el desplazamiento de la embarcación siempre aumenta, pero su centro de gravedad (G) permanece fijo.', false, '2025-09-13 13:53:12.119099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6da8e7ae-dfaa-4af3-95d2-beb8983af06f', '3e0b17c4-3932-46ef-a4b5-80cc9861417e', 'b', 'Con independencia de la escora, el centro de gravedad de la embarcación permanece inalterable.', false, '2025-09-13 13:53:12.119246+00');
