INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45d895a6-eff3-4e78-81c8-30cdd9fd5fb4', '3e0b17c4-3932-46ef-a4b5-80cc9861417e', 'd', 'Cuando el viento cese, la embarcación permanecerá escorada ya que la posición de su centro de gravedad no estará en la misma vertical que el centro de carena.', true, '2025-09-13 13:53:12.11953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26211f83-89dc-4b89-a5eb-207347d9b075', '8e353cdc-4ffa-4f46-9291-d89a48e0106e', 'a', 'Recoger la documentación más imprescindible y ponerse el chaleco salvavidas.', false, '2025-09-13 13:53:12.119805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ec0a97d-d008-44a8-8308-418f7fe0df00', '8e353cdc-4ffa-4f46-9291-d89a48e0106e', 'b', 'Antes de la llegada del helicóptero, contactar con sus tripulantes por el Canal 16 de VHF y atender sus instrucciones.', true, '2025-09-13 13:53:12.119939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d4ee8a0-6732-4cdb-8d52-06618d7cfb08', '8e353cdc-4ffa-4f46-9291-d89a48e0106e', 'c', 'Arriar las velas y poner en marcha el motor.', false, '2025-09-13 13:53:12.120077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e7ca3eb-5d60-4680-a3c1-9ee80aa0c277', '8e353cdc-4ffa-4f46-9291-d89a48e0106e', 'd', 'Lanzar un cohete provisto de paracaídas cuando se aproxime el helicóptero, para facilitar su', false, '2025-09-13 13:53:12.120206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c865831a-2b69-4259-bc7d-2eca375a958f', '33a20abe-f336-4048-adc9-d9880f10089e', 'a', 'Se llevará siempre a bordo una balsa salvavidas, con independencia de que la embarcación limite su navegación a la zona 4 de navegación.', true, '2025-09-13 13:53:12.120481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fd0dd75-8290-40a4-8264-074fade34b23', '33a20abe-f336-4048-adc9-d9880f10089e', 'b', 'La embarcación tiene que llevar, con independencia de la zona de navegación y las condiciones de navegación, un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, más un chaleco adicional.', false, '2025-09-13 13:53:12.120614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c5a73cb-29de-4dc9-8107-2b76778ea0a7', '33a20abe-f336-4048-adc9-d9880f10089e', 'c', 'La embarcación dispondrá de un reflector de radar, en cualquier zona de navegación, siempre que el casco no sea metálico.', false, '2025-09-13 13:53:12.120748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ae78f56-1ee1-43a4-9a0a-481c7028d78e', '33a20abe-f336-4048-adc9-d9880f10089e', 'd', 'La embarcación dispondrá, cuando navegue en zona 2, de dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:12.120888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c221db2-109b-44a5-9cc6-dc50fe934ec1', '2cbda3ce-fabe-4790-9bd3-cfed3d376ab4', 'a', 'A barlovento, por el lado opuesto a la ubicación de la botella de aire comprimido.', false, '2025-09-13 13:53:12.121154+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d03d475-5373-4073-bb84-c7927cdeab45', '2cbda3ce-fabe-4790-9bd3-cfed3d376ab4', 'b', 'A sotavento, por el lado opuesto a la ubicación de la botella de aire comprimido.', false, '2025-09-13 13:53:12.121282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a58decc5-33ed-43c8-bc3a-9c1d69fb5c53', '2cbda3ce-fabe-4790-9bd3-cfed3d376ab4', 'c', 'A sotavento y subido sobre la botella de aire comprimido.', true, '2025-09-13 13:53:12.121409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58e838d8-8380-40f5-b10e-f647a62ae8e2', '2cbda3ce-fabe-4790-9bd3-cfed3d376ab4', 'd', 'A barlovento y subido sobre la botella de aire comprimido.', false, '2025-09-13 13:53:12.121534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1333af08-34ee-4d74-9a2b-3f5b731f8e79', '58fb6469-4dfd-448e-8036-00f61f1f597d', 'a', 'Detener completamente la embarcación.', false, '2025-09-13 13:53:12.121823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9581f5b0-b031-4429-90dc-45e27b7588dd', '58fb6469-4dfd-448e-8036-00f61f1f597d', 'b', 'Hacer una llamada de socorro y activar la radiobaliza manualmente.', false, '2025-09-13 13:53:12.121962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf43d7f9-4dcc-4cb8-ba3c-b706fb4bdeed', '58fb6469-4dfd-448e-8036-00f61f1f597d', 'c', 'Ponerse ropa de abrigo y chaleco salvavidas.', true, '2025-09-13 13:53:12.122103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cdd81441-a440-43d1-91af-95bfd757dfc4', '58fb6469-4dfd-448e-8036-00f61f1f597d', 'd', 'Soltar la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:12.122256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25845817-7124-4f31-9d60-e185eec2e30e', '88e784b3-0543-4c40-ab9d-40b44f4b6910', 'a', 'Coja el arnés antes de que contacte con el agua y colóqueselo.', true, '2025-09-13 13:53:12.122585+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb90524e-5b95-416d-8a17-ce1acddee14c', '88e784b3-0543-4c40-ab9d-40b44f4b6910', 'b', 'Antes de ponerse el arnés quítese el chaleco salvavidas, ya no lo necesita.', false, '2025-09-13 13:53:12.122749+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fd3a50f-91b0-4909-88cb-b331ff333e63', '88e784b3-0543-4c40-ab9d-40b44f4b6910', 'c', 'Mantenga los brazos pegados al cuerpo o cruzados al pecho durante todo el izado.', false, '2025-09-13 13:53:12.122916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34567544-12f2-4141-9745-b7f51b76c2c3', '88e784b3-0543-4c40-ab9d-40b44f4b6910', 'd', 'Al llegar a la puerta del helicóptero, agárrese a la estructura sin soltarse, mientras la tripulación le introduce a bordo.', false, '2025-09-13 13:53:12.123079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a4b4b97-5e41-4658-b941-659a098bf68c', '03431578-6d97-4147-bb19-7a2519a44841', 'a', 'El centro de gravedad del buque para esa flotación.', false, '2025-09-13 13:53:12.123412+00');
