INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5580737a-7182-48d9-8db4-5e98c8deff86', '2507f237-87e7-4b84-9434-b34aca17d97a', 'a', 'Es la relación entre la presión de vapor efectiva y la tensión del vapor saturante con respecto al agua a la misma temperatura y presión.', false, '2025-09-13 13:53:12.125547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9328659-9a40-4f14-823e-c4b6433b7151', '2507f237-87e7-4b84-9434-b34aca17d97a', 'b', 'Es la densidad de moléculas de vapor de agua en el aire.', false, '2025-09-13 13:53:12.125679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d6c6dda-d630-4b1d-8391-7b4ccd6f1952', '2507f237-87e7-4b84-9434-b34aca17d97a', 'c', 'Cuanto mayor sea la temperatura del aire, mayor podrá ser su valor.', true, '2025-09-13 13:53:12.12581+00');
