INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22fd6243-50d2-4ac4-805b-c79b39499be6', '48d3f72c-90af-430f-89d5-f3f5269fd68b', 'c', 'Son líneas que unen puntos con igual dirección del viento.', false, '2025-09-13 13:53:12.127853+00');
