INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fddfcec-7e25-4558-bef4-9a036b66d5ea', '91ce6e80-f01b-4ca1-ba52-ab6bf817f6ac', 'a', 'Sin viento no hay olas, aunque el viento sople en regiones alejadas del lugar donde se observe', false, '2025-09-13 13:53:12.12894+00');
