INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f2810d1-6543-4b42-8632-9d9b8d4c78df', '91ce6e80-f01b-4ca1-ba52-ab6bf817f6ac', 'd', 'La mar de viento es por lo general más regular en su forma y dirección que la mar de fondo.', false, '2025-09-13 13:53:12.129328+00');
