INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d90fc808-09da-429a-be0c-1164d40b2b50', '6bee8c11-46f3-49ce-8b3f-4b5421f5d9da', 'a', 'A barlovento, por el lado opuesto a la ubicación de la botella de aire comprimido.', false, '2025-09-13 13:53:12.145598+00');
