INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ea31e3d-5525-429d-b213-003fa0b0bfc7', '6bee8c11-46f3-49ce-8b3f-4b5421f5d9da', 'd', 'A barlovento y subido sobre la botella de aire comprimido.', false, '2025-09-13 13:53:12.146023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53e06914-1eb9-424a-8d40-65503e78c78b', '13339068-d1e8-4a82-bf1e-91db62accf84', 'a', 'Recoger la documentación más imprescindible y ponerse el chaleco salvavidas.', false, '2025-09-13 13:53:12.146309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02e7132d-c5be-493a-88c9-6561c63c4a99', '13339068-d1e8-4a82-bf1e-91db62accf84', 'b', 'Antes de la llegada del helicóptero, contactar con sus tripulantes por el Canal 16 de VHF y atender sus instrucciones.', false, '2025-09-13 13:53:12.146438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('033a7ea1-bf63-47a8-b5dc-7358271352b7', '13339068-d1e8-4a82-bf1e-91db62accf84', 'c', 'Arriar las velas y poner en marcha el motor.', true, '2025-09-13 13:53:12.146567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a25b6be2-e1e8-4136-9bf9-70a7190b3836', '13339068-d1e8-4a82-bf1e-91db62accf84', 'd', 'Lanzar un cohete provisto de paracaídas cuando se aproxime el helicóptero, para facilitar su', false, '2025-09-13 13:53:12.146695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a70622c2-1bf2-4dc7-b38a-ad7d972be81d', 'b2afc57e-04cf-43e8-b19b-afd38b59d0cb', 'a', 'El centro de gravedad del buque para esa flotación.', false, '2025-09-13 13:53:12.146965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b94e8607-9cf2-4dc4-be31-f04ba20ad06c', 'b2afc57e-04cf-43e8-b19b-afd38b59d0cb', 'b', 'El centro de gravedad de la línea de flotación.', false, '2025-09-13 13:53:12.147093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0391cf48-d43b-48f2-b6e8-8bcfd3df542e', 'b2afc57e-04cf-43e8-b19b-afd38b59d0cb', 'c', 'El centro de gravedad del volumen sumergido para esa flotación.', true, '2025-09-13 13:53:12.147223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff5c8a8b-a55c-46a3-9424-9b3d90fa3cef', 'b2afc57e-04cf-43e8-b19b-afd38b59d0cb', 'd', 'La altura metacéntrica.', false, '2025-09-13 13:53:12.147349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dad48164-b283-46dc-a57b-bb038174178e', '84f74b43-dc04-45f3-abc4-75d0a64558f6', 'a', 'Se llevará siempre a bordo una balsa salvavidas, con independencia de que la embarcación limite su navegación a la zona 4 de navegación.', false, '2025-09-13 13:53:12.147618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18e55404-f7b5-4e3a-9c01-72738dbf8f26', '84f74b43-dc04-45f3-abc4-75d0a64558f6', 'b', 'La embarcación tiene que llevar, con independencia de la zona de navegación y las condiciones de navegación, un chaleco salvavidas por persona a bordo, todos ellos dotados de luz, más un chaleco adicional.', false, '2025-09-13 13:53:12.147755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('377c0a07-7e7e-4722-86b2-cfaae5f7df26', '84f74b43-dc04-45f3-abc4-75d0a64558f6', 'c', 'La embarcación dispondrá de un reflector de radar, en cualquier zona de navegación, siempre que el casco no sea metálico.', true, '2025-09-13 13:53:12.147897+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b616aa0-4ae8-4bc4-bd5f-803134cf7829', '84f74b43-dc04-45f3-abc4-75d0a64558f6', 'd', 'La embarcación dispondrá, cuando navegue en zona 2, de dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:12.148043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1faa5a7c-c2d9-42c9-a572-3166039833e1', '1e5423a6-a0ba-4945-816f-cbbe0761038e', 'a', 'Detener completamente la embarcación.', true, '2025-09-13 13:53:12.148348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f4c14e8-9578-4d0b-aea8-590b26302d66', '1e5423a6-a0ba-4945-816f-cbbe0761038e', 'b', 'Hacer una llamada de socorro y activar la radiobaliza manualmente.', false, '2025-09-13 13:53:12.148483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ec2c042-a4f4-4fbc-b354-1a5cbb7e40e7', '1e5423a6-a0ba-4945-816f-cbbe0761038e', 'c', 'Ponerse ropa de abrigo y chaleco salvavidas.', false, '2025-09-13 13:53:12.148613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('366e657f-d7a9-4c6d-afb7-e6b720a1f1a3', '1e5423a6-a0ba-4945-816f-cbbe0761038e', 'd', 'Soltar la driza de la balsa salvavidas antes de lanzarla al agua.', false, '2025-09-13 13:53:12.148742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d71c2329-7be2-4c5f-93c3-876de0e52704', 'b828e57f-3fcb-4622-9fde-254afb7cb795', 'a', 'Al mojarse.', false, '2025-09-13 13:53:12.149053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d572740-25fa-425f-828f-1d9720f58a10', '5692f3a3-f67a-496b-a8c1-a6c2964ebe32', 'c', '7,7 nudos.', false, '2025-09-13 13:53:12.172206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffe86804-071b-4e61-826c-0bf4a714aad0', 'b828e57f-3fcb-4622-9fde-254afb7cb795', 'b', 'Tras permanecer 2 minutos en contacto con el agua.', false, '2025-09-13 13:53:12.149186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79949144-b3da-4af4-a294-65eff6d5a8e9', 'b828e57f-3fcb-4622-9fde-254afb7cb795', 'c', 'Al darle un golpe.', false, '2025-09-13 13:53:12.149338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2a580b1-1c60-44cb-bd5b-00dc511fbb19', 'b828e57f-3fcb-4622-9fde-254afb7cb795', 'd', 'Al alcanzar una profundidad de 4 metros por hundimiento de la embarcación.', true, '2025-09-13 13:53:12.149473+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed1c0328-ed61-4278-b7a6-a4c5c2ad705a', '26e77bb3-dbda-4ac3-a930-9d085fa02c4a', 'a', 'Emitir una llamada de socorro por fonía en el canal 70 del VHF.', false, '2025-09-13 13:53:12.149747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d29d1f7-7fb6-4866-96fa-bd43169aa9e6', '26e77bb3-dbda-4ac3-a930-9d085fa02c4a', 'b', 'Emitir una llamada de socorro por fonía en el canal 16 del VHF.', true, '2025-09-13 13:53:12.149902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('873b910a-11f4-4dd7-b308-886a49e37f23', '26e77bb3-dbda-4ac3-a930-9d085fa02c4a', 'c', 'Emitir una Llamada Selectiva Digital en el canal 70 del VHF.', false, '2025-09-13 13:53:12.150033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be866247-a632-449e-86a0-42255df5afb8', '26e77bb3-dbda-4ac3-a930-9d085fa02c4a', 'd', 'Pulsar el botón de “DISTRESS” del VHF.', false, '2025-09-13 13:53:12.150164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00ed348e-acff-44df-8e28-da334a7f2713', '8e519c21-3a97-4cfc-ae89-caa7b5f5d42e', 'a', 'Coja el arnés antes de que contacte con el agua y colóqueselo.', false, '2025-09-13 13:53:12.150436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84d56239-6522-4077-a7be-ffe6ae65afdf', '8e519c21-3a97-4cfc-ae89-caa7b5f5d42e', 'b', 'Antes de ponerse el arnés quítese el chaleco salvavidas, ya no lo necesita.', false, '2025-09-13 13:53:12.150568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5df7e2b3-47cd-445b-b7aa-330d291d6795', '8e519c21-3a97-4cfc-ae89-caa7b5f5d42e', 'c', 'Mantenga los brazos pegados al cuerpo o cruzados al pecho durante todo el izado.', false, '2025-09-13 13:53:12.150696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7db4d692-df08-4385-959d-b2bff55dd30e', '8e519c21-3a97-4cfc-ae89-caa7b5f5d42e', 'd', 'Al llegar a la puerta del helicóptero, agárrese a la estructura sin soltarse, mientras la tripulación le introduce a bordo.', true, '2025-09-13 13:53:12.150826+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94d85685-e225-46a4-a6dc-188158413af9', '7a7f1a6f-6c94-4e6d-8f4e-d3c26e3b95c3', 'a', 'Estable.', false, '2025-09-13 13:53:12.151097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c9b04ab-1906-4ac2-88fb-6cc5cfbdec54', '7a7f1a6f-6c94-4e6d-8f4e-d3c26e3b95c3', 'b', 'Indiferente.', true, '2025-09-13 13:53:12.151226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd23e915-3ff9-4f60-924f-7751dde0fff9', '7a7f1a6f-6c94-4e6d-8f4e-d3c26e3b95c3', 'c', 'Inestable.', false, '2025-09-13 13:53:12.151354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a742ce1d-7709-4285-8eb7-3f3a4a2dee1f', '7a7f1a6f-6c94-4e6d-8f4e-d3c26e3b95c3', 'd', 'Es imposible que se de esta situación.', false, '2025-09-13 13:53:12.151483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0a01792-0fb7-4155-8346-b06ad76098c0', 'e2503b59-a773-4b30-9502-fa0b558c6d83', 'a', 'Como consecuencia de la escora, el desplazamiento de la embarcación siempre aumenta, pero su centro de gravedad (G) permanece fijo.', true, '2025-09-13 13:53:12.151752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c302e310-2f2b-4714-940d-42e5db358329', 'e2503b59-a773-4b30-9502-fa0b558c6d83', 'b', 'Con independencia de la escora, el centro de gravedad de la embarcación permanece inalterable.', false, '2025-09-13 13:53:12.151897+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('785fe288-b2a3-47ab-aba5-b70a620779b5', 'e2503b59-a773-4b30-9502-fa0b558c6d83', 'c', 'Como consecuencia de la variación de la posición del centro de carena, el centro de gravedad de la embarcación se desplaza en sentido contrario a la acción del viento.', false, '2025-09-13 13:53:12.152029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3995fb22-9ca8-469b-92db-e327ab65338d', 'e2503b59-a773-4b30-9502-fa0b558c6d83', 'd', 'Cuando el viento cese, la embarcación permanecerá escorada ya que la posición de su centro de gravedad no estará en la misma vertical que el centro de carena. Meteorología', false, '2025-09-13 13:53:12.15216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8ec9b7b-e33d-4cca-851d-4e9458fd0719', '6cba57de-bfcc-49bb-9380-78270f262459', 'a', 'Son líneas que unen puntos con igual valor de presión en una superficie dada.', false, '2025-09-13 13:53:12.152429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('285ff278-5b9e-4352-b9dd-5c1eb299b6ec', '6cba57de-bfcc-49bb-9380-78270f262459', 'b', 'Normalmente, en los mapas de superficie, se trazan isobaras a nivel del mar.', true, '2025-09-13 13:53:12.152558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('946d3b3f-13aa-4416-bae1-608e74481526', '6cba57de-bfcc-49bb-9380-78270f262459', 'c', 'Son líneas que unen puntos con igual dirección del viento.', false, '2025-09-13 13:53:12.152687+00');
