INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c76b666b-b60a-46e0-95ea-11e6a04aaf51', '2fd01aa8-71c6-4751-baf1-258c8b0039e5', 'd', 'Fuego de San Telmo.', true, '2025-09-13 13:53:12.18933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5d8d48e-42f8-40b3-bf32-ec9af6dc5f06', '8b79be1a-4268-4313-9136-d1831016b549', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida por la popa o la aleta de babor. Nos mantendremos corriendo el temporal hasta que el viento amaine.', false, '2025-09-13 13:53:12.189611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b889a8f-a5fa-4fc3-9420-54ef18564136', '8b79be1a-4268-4313-9136-d1831016b549', 'b', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la popa o la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos del ciclón.', false, '2025-09-13 13:53:12.189744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f09d7928-9e15-4e3f-ae2b-d555a349e3d8', '8b79be1a-4268-4313-9136-d1831016b549', 'c', 'Gobernar con toda la máquina disponible y un rumbo tal que el viento incida abierto entre 10° y 45° por la amura de estribor. A medida que el viento continúe rolando, se irá variando el rumbo a estribor hasta quedar en franquía.', true, '2025-09-13 13:53:12.189882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('082280a1-5315-4870-b43d-ebfb4e40361b', '8b79be1a-4268-4313-9136-d1831016b549', 'd', 'Ajustar el rumbo hasta que el viento incida sobre nuestra amura de babor. Incrementaremos máquina hasta la máxima disponible.', false, '2025-09-13 13:53:12.190012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7496b00d-e0ca-43de-bd64-f0c236b3fe74', '2f86d351-f740-4bac-a074-9acedca0add1', 'a', 'Con respecto a su trayectoria, en el hemisferio Norte el semicírculo derecho es el peligroso y el izquierdo el manejable.', true, '2025-09-13 13:53:12.190281+00');
