INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6fc1ece-0385-47b5-947d-68b3cfd0a7d1', 'fe502d2b-3507-4ed4-b53b-e8482e3be817', 'a', 'Se denomina así al cinturón de altas presiones que rodea a la Tierra.', true, '2025-09-13 13:53:12.215324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94e238b0-ad95-42a6-9048-301ba44d0141', 'fe502d2b-3507-4ed4-b53b-e8482e3be817', 'b', 'Es donde convergen los vientos alisios del hemisferio Norte con los del hemisferio Sur.', false, '2025-09-13 13:53:12.215461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a8296379-3008-4572-9c59-05c87a56c4b2', 'fe502d2b-3507-4ed4-b53b-e8482e3be817', 'c', 'La posición de esta región varía en función del ciclo estacional.', false, '2025-09-13 13:53:12.215599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62de9676-c674-4ea5-ab50-c0b346f40703', 'fe502d2b-3507-4ed4-b53b-e8482e3be817', 'd', 'Es un área comprendida entre los trópicos de Cáncer y Capricornio.', false, '2025-09-13 13:53:12.215737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bb7d296-2211-491c-8fd4-76e8347d8b9c', '34039f0c-cc84-4f20-a645-69aee60e6980', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida por la popa o la aleta de babor. Nos mantendremos corriendo el temporal hasta que el viento amaine.', false, '2025-09-13 13:53:12.216027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('947e3ac8-ea64-44d9-b299-84aebffdcd80', '34039f0c-cc84-4f20-a645-69aee60e6980', 'b', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la popa o la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos del ciclón.', false, '2025-09-13 13:53:12.216162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63d99de5-71f2-4841-a474-fd58ff7f766b', '34039f0c-cc84-4f20-a645-69aee60e6980', 'c', 'Gobernar con toda la máquina disponible y un rumbo tal que el viento incida abierto entre 10° y 45° por la amura de estribor. A medida que el viento continúe rolando, se irá variando el rumbo a estribor hasta quedar en franquía.', true, '2025-09-13 13:53:12.216296+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c2192a7-5964-4024-a3b7-402ec1190ef3', '6192fb51-71a0-4d63-9755-7d6b0ae11e0a', 'c', '899,2 millas.', false, '2025-09-13 13:53:12.23694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85006f33-62ab-42fc-b6fa-5cd0fd8241c8', '34039f0c-cc84-4f20-a645-69aee60e6980', 'd', 'Ajustar el rumbo hasta que el viento incida sobre nuestra amura de babor. Incrementaremos máquina hasta la máxima disponible.', false, '2025-09-13 13:53:12.21643+00');
