INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45334427-065f-410d-b426-ed3ca8609beb', 'ba29665a-4ed1-4ccc-9ff7-4aebf108a059', 'a', '15 h 22 m (20/04/2024).', false, '2025-09-13 13:53:12.242102+00');
