INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4366ee3-b7a5-4b3f-80c6-bcf4660ff81f', 'ba29665a-4ed1-4ccc-9ff7-4aebf108a059', 'c', '15 h 22 m (19/04/2024).', true, '2025-09-13 13:53:12.242365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9315a986-e6cb-46ce-b1a9-7fada7f4f10a', 'ba29665a-4ed1-4ccc-9ff7-4aebf108a059', 'd', '10 h 00 m (19/04/2024). Meteorología', false, '2025-09-13 13:53:12.242495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93d13813-2372-4ea9-a408-91de18599968', '57df2e91-2222-46a3-a20c-742505993585', 'a', 'Podemos considerar, mirando en la dirección y sentido de su desplazamiento, dos partes, que son el semicírculo derecho o peligroso, y el semicírculo izquierdo o manejable.', false, '2025-09-13 13:53:12.24277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4738b102-1ab9-4400-bac6-7a201fc99f9f', '57df2e91-2222-46a3-a20c-742505993585', 'b', 'Podemos considerar, mirando en la dirección y sentido de su desplazamiento, dos partes, que son el semicírculo derecho o manejable, y el semicírculo izquierdo o peligroso.', false, '2025-09-13 13:53:12.242934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46f40497-a589-48ba-aa71-2f507ec62033', '57df2e91-2222-46a3-a20c-742505993585', 'c', 'Para determinar la posición del vórtice podemos utilizar la regla de Buy Ballot, de manera que, con la proa de cara al viento verdadero, este se encuentra a proa de la embarcación.', false, '2025-09-13 13:53:12.243078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('916e102f-d68e-41b1-8c24-d7abd6df29af', '57df2e91-2222-46a3-a20c-742505993585', 'd', 'Para determinar la posición del vórtice podemos utilizar la regla de Buy Ballot, de manera que, con la popa de cara al viento verdadero, este se encuentra a proa de la embarcación.', true, '2025-09-13 13:53:12.243214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9818c6be-3a41-421f-814d-1bd49f86486d', '900abf26-8f4c-4691-92cf-36ac78cce275', 'a', 'Estruendo sonoro, asociado al rayo luminoso, producido en las nubes por una descarga eléctrica. Es perceptible después que el rayo luminoso.', true, '2025-09-13 13:53:12.243503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49110685-e1bc-4ea3-9870-feadd15ab7f8', '900abf26-8f4c-4691-92cf-36ac78cce275', 'b', 'Resplandor lumínico vivísimo e instantáneo producido en las nubes por una descarga eléctrica. Es perceptible antes que el rayo.', false, '2025-09-13 13:53:12.243638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b442568-62bc-4b98-912f-df550870f12b', '900abf26-8f4c-4691-92cf-36ac78cce275', 'c', 'Estruendo sonoro, asociado al rayo luminoso, producido en las nubes por una descarga eléctrica. Es perceptible antes que el rayo luminoso.', false, '2025-09-13 13:53:12.24378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('690186f4-eb6a-463c-b2b8-6a2be1577150', '900abf26-8f4c-4691-92cf-36ac78cce275', 'd', 'Resplandor lumínico vivísimo e instantáneo producido en las nubes por una descarga eléctrica. Es perceptible después que el rayo.', false, '2025-09-13 13:53:12.243913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1cdde2b-42d5-4565-9436-1517e4b373ac', '4e5d162a-ebad-457a-af94-477f867380cc', 'a', 'Baja presión en la ZCIT.', true, '2025-09-13 13:53:12.244192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('689c3b30-3f97-4dff-87cb-b929064d5186', '4e5d162a-ebad-457a-af94-477f867380cc', 'b', 'Presencia de viento fuerte en superficie para evitar las corrientes ascendentes.', false, '2025-09-13 13:53:12.244325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e0b8af2-b840-4120-9729-f2d5f21fd74c', '4e5d162a-ebad-457a-af94-477f867380cc', 'c', 'Alta presión en altura, con vientos divergentes que facilitan la convección del aire caliente.', false, '2025-09-13 13:53:12.244456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f456ac71-c49f-430a-b857-28371937e19a', '4e5d162a-ebad-457a-af94-477f867380cc', 'd', 'Alta temperatura del mar que favorece la evaporación.', false, '2025-09-13 13:53:12.244586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40253aff-cfb2-41d1-8606-0a9fe44bbf38', 'fd06b07f-2c70-4d07-8f11-3bfc980241a3', 'a', 'No tienen frentes porque están constituidos por una sola masa de aire ecuatorial homogéneo.', false, '2025-09-13 13:53:12.244899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a46ec4a-9542-4bd6-bd71-adda0db447bb', 'fd06b07f-2c70-4d07-8f11-3bfc980241a3', 'b', 'En ellos la presión puede alcanzar valores superiores a la de los anticiclones.', false, '2025-09-13 13:53:12.245032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ec91d83-83e9-410f-8c1d-dc183b9dc802', 'fd06b07f-2c70-4d07-8f11-3bfc980241a3', 'c', 'Su situación geográfica y la época del año no determinan su formación.', true, '2025-09-13 13:53:12.245162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97f8a817-db83-4ff5-9408-7c64826dcbd3', 'fd06b07f-2c70-4d07-8f11-3bfc980241a3', 'd', 'La sequedad procedente del aire es su fuente de energía principal.', false, '2025-09-13 13:53:12.245292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2e8b241-79df-41eb-9f30-129dfb8c57e8', 'bd2b2c86-b5c8-4546-a9db-13810d2bd324', 'a', 'Estará obligado a navegar sólo de día, a una velocidad moderada, sin modificar su derrota.', false, '2025-09-13 13:53:12.245564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e39eb50a-82e8-4dba-8268-7b463d862593', 'bd2b2c86-b5c8-4546-a9db-13810d2bd324', 'b', 'Determinará la velocidad a la que podrá navegar con seguridad teniendo en cuenta que en el radar se detectan siempre, a distancia adecuada, los hielos flotantes.', false, '2025-09-13 13:53:12.245696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bd18b50-e2ad-4f99-8ed0-5d0defcb8a9b', 'bd2b2c86-b5c8-4546-a9db-13810d2bd324', 'c', 'Estará obligado, durante la noche, a navegar a una velocidad moderada o a modificar su derrota para distanciarse de la zona peligrosa.', false, '2025-09-13 13:53:12.245868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a27bd12d-e6df-4ad0-9489-c6806af2ccab', 'bd2b2c86-b5c8-4546-a9db-13810d2bd324', 'd', 'No tiene ninguna obligación legal de actuar de alguna manera determinada y decidirá lo que más le convenga según las circunstancias particulares de la zona.', true, '2025-09-13 13:53:12.246018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24779628-1270-4736-9063-a34c55984c3d', 'be277125-9836-430a-8659-212de7fb471e', 'a', 'Cumulonimbo, y su formación se produce por la presencia de aire cálido húmedo en sentido', false, '2025-09-13 13:53:12.246319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d069e011-9a9e-4d54-9fb2-59b0efe4af42', 'be277125-9836-430a-8659-212de7fb471e', 'b', 'Cirro o similar, y su formación se produce por la presencia de aire cálido húmedo en sentido', false, '2025-09-13 13:53:12.246454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('634ae657-dd68-4bad-badc-0047f9c1ae13', 'be277125-9836-430a-8659-212de7fb471e', 'c', 'Cumulonimbo, y su formación se produce por la presencia de aire cálido seco en sentido', false, '2025-09-13 13:53:12.246587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e09eee85-9b73-455c-a034-e3b9e314a53f', 'be277125-9836-430a-8659-212de7fb471e', 'd', 'Cirro o similar y su formación se produce por el ascenso de aire frío seco en sentido descendente.', true, '2025-09-13 13:53:12.246718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d0eab10-7f2a-4bda-8d32-bf9be547251b', 'c3abf39f-9557-4a22-98bd-8b0400fecdee', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida abierto entre 10° y 45° por la amura de estribor. Continuaremos cayendo a babor a medida que el viento siga rolando, para capear hasta que estemos en franquía.', true, '2025-09-13 13:53:12.247019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d9a024c-056a-4a16-85af-8463ee4bf698', '0b9e1250-cf8c-484a-a535-b57bd461d0c8', 'b', '09:58:48.', false, '2025-09-13 13:53:12.267503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8322c019-3991-4816-ace7-43544ebee239', 'c3abf39f-9557-4a22-98bd-8b0400fecdee', 'b', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos', false, '2025-09-13 13:53:12.247149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb653f64-a5e0-4072-98ff-b6a3f255d5a0', 'c3abf39f-9557-4a22-98bd-8b0400fecdee', 'c', 'Ajustar el rumbo hasta que el viento venga por proa. Continuaremos cayendo a babor a medida que el viento siga rolando para mantener siempre la incidencia del viento por proa.', false, '2025-09-13 13:53:12.247292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77a14c29-5b7b-4aa4-b2bd-f1dbb88d7484', 'c3abf39f-9557-4a22-98bd-8b0400fecdee', 'd', 'Proceder con toda la máquina a un rumbo tal que dejemos el viento por la aleta de babor. Continuaremos cayendo a estribor a medida que el viento role hasta que poco a poco salgamos de la zona de influencia.', false, '2025-09-13 13:53:12.247421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('feed07d8-02b4-44eb-905d-20ba87963333', 'fa6f4058-f487-4248-9357-9090811becff', 'a', 'Al hielo fijo que tiene más de 2 metros sobre el nivel del mar.', true, '2025-09-13 13:53:12.24769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c715b71-8200-47f7-96a0-0686a6fc1498', 'fa6f4058-f487-4248-9357-9090811becff', 'b', 'Al hielo flotante que tiene más de 2 metros sobre el nivel del mar.', false, '2025-09-13 13:53:12.247819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('575ab23f-c96d-4a8c-8e88-fb3120c98579', 'fa6f4058-f487-4248-9357-9090811becff', 'c', 'A cualquier forma de hielo que se encuentre flotando en el agua.', false, '2025-09-13 13:53:12.247947+00');
