INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ca3deb4-0082-4c93-b3ce-2edfa49f37c3', '6711a596-dc78-4cf9-a458-81e574e1c235', 'b', '43°25,0´N ; 060°51,5´W.', true, '2025-09-13 13:53:12.270179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5db0c6c5-dcb1-47f5-8c41-cb5fab75fb4a', '6711a596-dc78-4cf9-a458-81e574e1c235', 'c', '43°30,3´N ; 060°40,0´W.', false, '2025-09-13 13:53:12.270311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6624a8d1-8301-4282-85ea-b0d3dc008264', '6711a596-dc78-4cf9-a458-81e574e1c235', 'd', '43°42,2´N ; 060°32,9´W. Meteorología', false, '2025-09-13 13:53:12.270437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce3db57b-7e77-497d-9c83-bcd7ceb44ab2', '9c63d1db-b3c1-4f68-a2ed-8de86e8fb81a', 'a', 'Al hielo fijo que tiene más de 2 metros sobre el nivel del mar.', false, '2025-09-13 13:53:12.270703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdbf3498-63ed-41b8-982a-38c482f8ce5f', '9c63d1db-b3c1-4f68-a2ed-8de86e8fb81a', 'b', 'Al hielo flotante que tiene más de 2 metros sobre el nivel del mar.', true, '2025-09-13 13:53:12.270841+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42d410ac-6c58-403e-9ad8-9a00bfa96907', '9c63d1db-b3c1-4f68-a2ed-8de86e8fb81a', 'c', 'A cualquier forma de hielo que se encuentre flotando en el agua.', false, '2025-09-13 13:53:12.27098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69825899-d274-4093-b81e-b307cf7d8027', '9c63d1db-b3c1-4f68-a2ed-8de86e8fb81a', 'd', 'Al cualquier tipo de hielo que tenga más de 2 metros por debajo del nivel del mar.', false, '2025-09-13 13:53:12.271111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c52d27c-7ea9-4b68-8cec-fa526ec31255', '3df0953d-3b31-47cd-8222-f7f05daee4d0', 'a', 'No tienen frentes porque están constituidos por una sola masa de aire ecuatorial homogéneo.', false, '2025-09-13 13:53:12.271383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2b3f401-f53a-4aef-b7a1-7eaa46bd5cd4', '3df0953d-3b31-47cd-8222-f7f05daee4d0', 'b', 'En ellos la presión puede alcanzar valores superiores a la de los anticiclones.', true, '2025-09-13 13:53:12.27151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a043a4dd-8d4b-4bd1-a47a-04010a753591', '3df0953d-3b31-47cd-8222-f7f05daee4d0', 'c', 'Su situación geográfica y la época del año no determinan su formación.', false, '2025-09-13 13:53:12.271636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da9d8ac2-4028-45e1-81d1-c72da5a5bfe9', '3df0953d-3b31-47cd-8222-f7f05daee4d0', 'd', 'La sequedad procedente del aire es su fuente de energía principal.', false, '2025-09-13 13:53:12.27177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('903bf4d5-2aae-425c-900a-f53b5be37bed', 'f5a2d0c8-c6ab-4c06-af22-0116f4369fb2', 'a', 'Estará obligado a navegar sólo de día, a una velocidad moderada, sin modificar su derrota.', false, '2025-09-13 13:53:12.272037+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d950e88-31c6-439d-a09e-b1acee948049', 'f5a2d0c8-c6ab-4c06-af22-0116f4369fb2', 'b', 'Determinará la velocidad a la que podrá navegar con seguridad teniendo en cuenta que en el radar se detectan siempre, a distancia adecuada, los hielos flotantes.', false, '2025-09-13 13:53:12.27217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3436c3c8-b562-4b63-b522-d8d5e7627585', 'f5a2d0c8-c6ab-4c06-af22-0116f4369fb2', 'c', 'Estará obligado, durante la noche, a navegar a una velocidad moderada o a modificar su derrota para distanciarse de la zona peligrosa.', false, '2025-09-13 13:53:12.272297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('386fbc3c-c368-41f5-8a29-3e431010c8b8', 'f5a2d0c8-c6ab-4c06-af22-0116f4369fb2', 'd', 'No tiene ninguna obligación legal de actuar de alguna manera determinada y decidirá lo que más le convenga según las circunstancias particulares de la zona.', true, '2025-09-13 13:53:12.272423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e241a833-7d6c-4060-9404-575583c72a60', 'd707f4ca-ae03-4045-a18a-94f08e507e97', 'a', 'Baja presión en la ZCIT.', true, '2025-09-13 13:53:12.272692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76550364-064c-4351-b8e0-58fc50ac4b20', 'd707f4ca-ae03-4045-a18a-94f08e507e97', 'b', 'Presencia de viento fuerte en superficie para evitar las corrientes ascendentes.', false, '2025-09-13 13:53:12.272828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78e035f3-76ea-4165-b07b-fc90bfeb7ebc', 'd707f4ca-ae03-4045-a18a-94f08e507e97', 'c', 'Alta presión en altura, con vientos divergentes que facilitan la convección del aire caliente.', false, '2025-09-13 13:53:12.272965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dac0f3f3-17ad-4a82-a149-904a50bb2fac', 'd707f4ca-ae03-4045-a18a-94f08e507e97', 'd', 'Alta temperatura del mar que favorece la evaporación.', false, '2025-09-13 13:53:12.273095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73550001-86f3-4da1-9a8e-f76420a68454', 'a197d9c0-88af-4b49-8c69-b0e9765fe65b', 'a', 'La Corriente de Labrador.', false, '2025-09-13 13:53:12.273364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('656f1023-441b-48fd-965b-b40deafeda8b', 'a197d9c0-88af-4b49-8c69-b0e9765fe65b', 'b', 'La Corriente del Caribe.', false, '2025-09-13 13:53:12.273494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd56431e-cd99-4e23-8b5e-2ea797ce6b6e', 'a197d9c0-88af-4b49-8c69-b0e9765fe65b', 'c', 'La Corriente Ecuatorial Norte.', false, '2025-09-13 13:53:12.273625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27cc9bfa-73a8-4045-9802-d5c9e0581b51', 'a197d9c0-88af-4b49-8c69-b0e9765fe65b', 'd', 'La Corriente de Azores.', true, '2025-09-13 13:53:12.273755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3edb9523-c0d6-4fcf-9653-0e141e115fa5', 'cba4f7d5-ede7-4266-bdac-62787d92eeab', 'a', 'Es una franja de altas presiones.', true, '2025-09-13 13:53:12.274047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d194d5a-27d1-4c35-b6ac-cbedd4e5b7ff', 'cba4f7d5-ede7-4266-bdac-62787d92eeab', 'b', 'Está ubicada en la zona ecuatorial.', false, '2025-09-13 13:53:12.274184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a17e6964-194f-46b7-9d8f-76a11d664413', 'cba4f7d5-ede7-4266-bdac-62787d92eeab', 'c', 'Es la zona de convergencia de los vientos generales del Oeste.', false, '2025-09-13 13:53:12.274315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92d18872-b27b-4ff2-afcf-50f538eabad9', 'cba4f7d5-ede7-4266-bdac-62787d92eeab', 'd', 'Predominan los vientos de componente descendente.', false, '2025-09-13 13:53:12.274446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e777fa98-a6c7-4d57-ba84-3de6ae059d31', 'f2d2f7cc-61cb-4a7e-8749-882ac89657d9', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida abierto entre 10° y 45° por la amura de estribor. Continuaremos cayendo a babor a medida que el viento siga rolando, para capear hasta que estemos en franquía.', true, '2025-09-13 13:53:12.274722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d32fd7c7-b261-49d4-ba33-4eee613f2bec', 'f2d2f7cc-61cb-4a7e-8749-882ac89657d9', 'b', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos', false, '2025-09-13 13:53:12.274861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69ffbf11-da15-416d-823b-14cee7fcd5df', 'f2d2f7cc-61cb-4a7e-8749-882ac89657d9', 'c', 'Ajustar el rumbo hasta que el viento venga por proa. Continuaremos cayendo a babor a medida que el viento siga rolando para mantener siempre la incidencia del viento por proa.', false, '2025-09-13 13:53:12.274989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cb599f2-131c-4b9c-b152-b9a9c0115347', 'f2d2f7cc-61cb-4a7e-8749-882ac89657d9', 'd', 'Proceder con toda la máquina a un rumbo tal que dejemos el viento por la aleta de babor. Continuaremos cayendo a estribor a medida que el viento role hasta que poco a poco salgamos de la zona de influencia.', false, '2025-09-13 13:53:12.275117+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64881ea1-9209-44bb-bcd2-f525669251b8', '45022ad6-1f6d-44a0-8bc3-3c5eac19f355', 'a', 'Estruendo sonoro, asociado al rayo luminoso, producido en las nubes por una descarga eléctrica. Es perceptible después que el rayo luminoso.', true, '2025-09-13 13:53:12.27539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d17ac0a3-0d41-4344-96b0-093e8d039eae', '45022ad6-1f6d-44a0-8bc3-3c5eac19f355', 'b', 'Resplandor lumínico vivísimo e instantáneo producido en las nubes por una descarga eléctrica. Es perceptible antes que el rayo.', false, '2025-09-13 13:53:12.275518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d173e21f-57c7-42da-b286-0c3c82ef112c', '45022ad6-1f6d-44a0-8bc3-3c5eac19f355', 'c', 'Estruendo sonoro, asociado al rayo luminoso, producido en las nubes por una descarga eléctrica. Es perceptible antes que el rayo luminoso.', false, '2025-09-13 13:53:12.275647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a87d44e-2316-4931-9c96-9d468221145a', '45022ad6-1f6d-44a0-8bc3-3c5eac19f355', 'd', 'Resplandor lumínico vivísimo e instantáneo producido en las nubes por una descarga eléctrica. Es perceptible después que el rayo.', false, '2025-09-13 13:53:12.275786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('220aa420-ce71-4a45-8158-96778fe295b1', '7a9f6554-0efa-4b05-b3ea-dd4d4ec6c58b', 'a', 'Podemos considerar, mirando en la dirección y sentido de su desplazamiento, dos partes, que son el semicírculo derecho o peligroso, y el semicírculo izquierdo o manejable.', false, '2025-09-13 13:53:12.276063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc0bc1b8-d4ee-4c72-999b-9fe9611c6b34', '7a9f6554-0efa-4b05-b3ea-dd4d4ec6c58b', 'b', 'Podemos considerar, mirando en la dirección y sentido de su desplazamiento, dos partes, que son el semicírculo derecho o manejable, y el semicírculo izquierdo o peligroso.', true, '2025-09-13 13:53:12.276206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('980e2aa0-23af-4d45-a3a7-e30cb4bdf529', '7a9f6554-0efa-4b05-b3ea-dd4d4ec6c58b', 'c', 'Para determinar la posición del vórtice podemos utilizar la regla de Buy Ballot, de manera que, con la proa de cara al viento verdadero, este se encuentra a proa de la embarcación.', false, '2025-09-13 13:53:12.276334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c848075-9ba5-47c5-9930-43b9d274fccf', '7a9f6554-0efa-4b05-b3ea-dd4d4ec6c58b', 'd', 'Para determinar la posición del vórtice podemos utilizar la regla de Buy Ballot, de manera que, con la popa de cara al viento verdadero, este se encuentra a proa de la embarcación.', false, '2025-09-13 13:53:12.276464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4960a4f9-b9e4-481e-be8c-e836c2283275', '4b1cb550-76b0-4d75-89ed-69fdc4b70822', 'a', 'Cumulonimbo, y su formación se produce por la presencia de aire cálido húmedo en sentido', false, '2025-09-13 13:53:12.276734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dd4a592-d1b0-4270-8e11-b4c1c3f019e3', '4b1cb550-76b0-4d75-89ed-69fdc4b70822', 'b', 'Cirro o similar, y su formación se produce por la presencia de aire cálido húmedo en sentido', true, '2025-09-13 13:53:12.276866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ea6df1f-ddb9-44a8-84b6-317b55f0b276', '4b1cb550-76b0-4d75-89ed-69fdc4b70822', 'c', 'Cumulonimbo, y su formación se produce por la presencia de aire cálido seco en sentido', false, '2025-09-13 13:53:12.276993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d893dd4-b69a-463a-8fa1-5357905bbd09', '4b1cb550-76b0-4d75-89ed-69fdc4b70822', 'd', 'Cirro o similar y su formación se produce por el ascenso de aire frío seco en sentido descendente. Inglés', false, '2025-09-13 13:53:12.27713+00');
