INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb993cd1-2677-4e39-824a-4452d29fb643', 'f27b96b9-ae42-422a-bdf5-a1a3add9e63f', 'a', 'Generará una serie de señales de respuesta al ser interrogado por un radar marino de banda X en las proximidades de nuestra embarcación.', false, '2025-09-13 13:53:12.284773+00');
