INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3d047fe-e386-4518-8340-1076d829f4a9', '83d7e3e1-85d7-465d-b0ba-432ba7981d2e', 'a', 'Presión absoluta.', true, '2025-09-13 13:53:12.296465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7257174-468e-4fb8-b513-901bab4d4c6a', 'f27b96b9-ae42-422a-bdf5-a1a3add9e63f', 'c', 'Transmitirá un mensaje de emergencia, la posición y un número identificativo a través de un módulo GNSS integrado en el propio dispositivo.', false, '2025-09-13 13:53:12.285068+00');
