INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f233aae-ea97-42c9-af39-c8ae01930936', '16425bc9-bfcd-4be1-a23e-84a4b0b60bfb', 'a', 'Su activación puede ser manual o automática según el modelo.', false, '2025-09-13 13:53:12.286157+00');
