INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb26b900-19e5-479d-aeb9-5c309a9855ab', '16425bc9-bfcd-4be1-a23e-84a4b0b60bfb', 'c', 'Funciona en una banda de 9 GHz y generará una señal de respuesta en un RADAR de banda X de otro barco o aeronave.', true, '2025-09-13 13:53:12.286433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e7ea70d-8b6f-4991-aebd-1b45f3ddd56c', '16425bc9-bfcd-4be1-a23e-84a4b0b60bfb', 'd', 'Para su activación manual se debe quitar el pasador de bloqueo y poner el interruptor en la', false, '2025-09-13 13:53:12.286559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b0f8f34-e00c-4f1a-a108-ab27b7fb8db9', 'd036450b-9367-498c-8ade-36e8e44c49f5', 'a', 'El centro de gravedad está por encima del metacentro.', false, '2025-09-13 13:53:12.286825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63a7c54c-8553-47d5-b914-c598294ba1ad', 'd036450b-9367-498c-8ade-36e8e44c49f5', 'b', 'El peso del buque y el empuje actúan en diferentes verticales y el par que se crea no tiene fuerza suficiente para devolverlo a la posición de adrizado.', true, '2025-09-13 13:53:12.286953+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('643f6ac7-ed12-46e4-8138-90124affa3a3', 'd036450b-9367-498c-8ade-36e8e44c49f5', 'c', 'El peso y el empuje actúan siempre en la misma vertical y no se genera ningún par de fuerzas que haga adrizarlo.', false, '2025-09-13 13:53:12.287111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38cb68e9-7516-4d90-a009-53482d6cf75e', 'd036450b-9367-498c-8ade-36e8e44c49f5', 'd', 'El metacentro está por encima del centro de gravedad.', false, '2025-09-13 13:53:12.287249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e16d51c4-fae2-46e7-a4ca-6efd0e9dd7d7', '0f1e1cbc-a3a6-44cb-b4fd-8ec321560524', 'a', 'Utilice un bote de humo para señalar su posición, además resultará útil para que el helicóptero observe la dirección del viento.', false, '2025-09-13 13:53:12.287528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d362b981-fdfa-4918-bb5c-cb0096c1e11b', '0f1e1cbc-a3a6-44cb-b4fd-8ec321560524', 'b', 'Utilice un cohete con paracaídas para llamar la atención y que localicen su posición ya que una señal alta será mejor percibida por las unidades aéreas.', false, '2025-09-13 13:53:12.287665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bd29aff-5dc0-41a7-8ed4-2655281621c1', '0f1e1cbc-a3a6-44cb-b4fd-8ec321560524', 'c', 'Use el VHF portátil para guiar al helicóptero usando la técnica de las horas en un reloj.', false, '2025-09-13 13:53:12.287807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb3cea2-7936-44b5-8033-fd0fa3ba86cf', '0f1e1cbc-a3a6-44cb-b4fd-8ec321560524', 'd', 'Utilice un espejo de señales para llamar la atención del helicóptero.', true, '2025-09-13 13:53:12.287955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7109a93-40fc-4f92-b756-c3bf45b8ac3b', '2e839c70-26a7-4025-812d-4b67852ea9dc', 'a', 'Detener completamente la embarcación.', false, '2025-09-13 13:53:12.288246+00');
