INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6f44426-8e04-4b76-8255-cecdc6199330', '2e839c70-26a7-4025-812d-4b67852ea9dc', 'c', 'Disponer de una luz.', false, '2025-09-13 13:53:12.28851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20a9885d-2416-458e-8317-3e7fd69aaa20', '2e839c70-26a7-4025-812d-4b67852ea9dc', 'd', 'Soltar la driza de la balsa salvavidas y lanzarla al agua.', true, '2025-09-13 13:53:12.288641+00');
