INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6163c790-b934-4a14-93ad-d6c589be1457', '48eaf168-00a6-4dd0-acc0-ce7ce561c9a9', 'a', 'El rumbo de aguja no es el rumbo verdadero, ya que le afectan la declinación magnética y el desvío de aguja.', false, '2025-09-13 13:53:12.299821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca60048e-7136-4b83-aa64-403381cf29d3', '48eaf168-00a6-4dd0-acc0-ce7ce561c9a9', 'b', 'El rumbo de superficie es el rumbo de avance de un buque por efecto del abatimiento.', false, '2025-09-13 13:53:12.299947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d7b4329-a90d-4743-b0ea-967a71cfbd6c', '48eaf168-00a6-4dd0-acc0-ce7ce561c9a9', 'c', 'El rumbo efectivo es el rumbo de avance de un buque sometido al efecto de la deriva.', true, '2025-09-13 13:53:12.300079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aaaf38f3-ec34-4ad9-ac8e-35b5f97236be', '48eaf168-00a6-4dd0-acc0-ce7ce561c9a9', 'd', 'El rumbo verdadero es la suma del rumbo de aguja, el rumbo efectivo y el rumbo de superficie.', false, '2025-09-13 13:53:12.300205+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea7a703d-3eea-4f0a-9b04-22e574579864', 'fe5313f4-9859-4e44-a2da-2ae760a94932', 'a', 'Sus elementos principales son la Carta Náutica Electrónica (ENC) y el AIS.', false, '2025-09-13 13:53:12.300468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e350841-3379-4918-a6e1-87240f385324', 'fe5313f4-9859-4e44-a2da-2ae760a94932', 'b', 'En los buques que se les aplica el Convenio SOLAS, son un complemento a la Carta Naútica de', false, '2025-09-13 13:53:12.300607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bfe32c5-21ce-40b3-bf9c-63840a4c6d06', 'fe5313f4-9859-4e44-a2da-2ae760a94932', 'c', 'Sólo puede fabricarlo el Servicio Hidrográfico de cada país de conformidad con la normativa de la Organización Hidrográfica Internacional (OHI).', false, '2025-09-13 13:53:12.300742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4e1ea67-b602-4763-8fac-663053430d23', 'fe5313f4-9859-4e44-a2da-2ae760a94932', 'd', 'Tiene la capacidad para corregir las ENC de forma automática.', true, '2025-09-13 13:53:12.300881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4b5a504-296f-48b4-804f-f016f02cf7bc', '380a3303-0fb3-403a-8da1-1b7fd2a70f88', 'a', 'El abatimiento es la desviación del rumbo que sufre una embarcación hacia barlovento debido a la acción del viento.', false, '2025-09-13 13:53:12.301148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55dccb7e-902b-4c14-9272-e6422519246c', '380a3303-0fb3-403a-8da1-1b7fd2a70f88', 'b', 'La deriva es la desviación del rumbo que sufre una embarcación hacia sotavento debido a la acción del viento.', false, '2025-09-13 13:53:12.301277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5518ed60-c159-472f-a32b-399033adf2bb', '380a3303-0fb3-403a-8da1-1b7fd2a70f88', 'c', 'El abatimiento es el ángulo entre la derrota y la línea de crujía debido a la acción del viento.', false, '2025-09-13 13:53:12.301405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea5e6434-90b3-4048-ac70-a144324a3ebc', '380a3303-0fb3-403a-8da1-1b7fd2a70f88', 'd', 'La deriva es un efecto siempre contrario al abatimiento, anulándose entre sí.', true, '2025-09-13 13:53:12.301533+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d4963f8-8dcf-4f15-8098-13947e2a9562', '7e9ce745-31bf-46c1-8588-6a98b8799304', 'a', 'La declinación magnética y la demora verdadera.', true, '2025-09-13 13:53:12.301814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a309e0ea-cae5-49ad-8f32-5eb1a2288e14', '7e9ce745-31bf-46c1-8588-6a98b8799304', 'b', 'La demora de aguja y la declinación magnética.', false, '2025-09-13 13:53:12.301944+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2abea260-9bef-4506-92a6-207cc42d57bc', '7e9ce745-31bf-46c1-8588-6a98b8799304', 'c', 'La demora verdadera y el desvío de aguja.', false, '2025-09-13 13:53:12.302074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b191efdf-a61e-4dbf-b746-2369f022b921', '7e9ce745-31bf-46c1-8588-6a98b8799304', 'd', 'La demora de aguja y la demora verdadera.', false, '2025-09-13 13:53:12.302204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0210da87-99d2-4cc8-882c-ba6e75a76135', '44e7b96a-0d67-4e5d-9764-ea7098f7617c', 'a', 'Un exceso de ganancia reduce la discriminación de la unidad de radar, pudiendo inducir a error en las lecturas obtenidas.', true, '2025-09-13 13:53:12.302478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b625bf9-d49f-4c40-bd86-faa42be01ff8', '44e7b96a-0d67-4e5d-9764-ea7098f7617c', 'b', 'Una disminución excesiva de la sintonía generará mucho ruido en la imagen, induciendo a error.', false, '2025-09-13 13:53:12.302607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('471a2b34-ed3b-4dd6-8043-f76ab7d6996c', '44e7b96a-0d67-4e5d-9764-ea7098f7617c', 'c', 'Deberemos actuar sobre el filtro de lluvia, aún con buen tiempo, para obtener un perfil de costa', false, '2025-09-13 13:53:12.302734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62ff40a5-cd5f-4a27-a0d1-67cffa1ebc00', '44e7b96a-0d67-4e5d-9764-ea7098f7617c', 'd', 'Deberemos actuar sobre el filtro de mar a fin de mejorar la definición del perfil de la costa cuando ésta se encuentra a más de 3 millas.', false, '2025-09-13 13:53:12.302869+00');
