INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b2cbcad-af13-4f14-992d-240f3a994753', '84f13109-5b42-4c15-93a6-d817151a51b5', 'a', 'El centro de gravedad está por encima del metacentro.', false, '2025-09-13 13:53:12.315453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6d2f48d-bde7-4f3c-97cf-1ae256d46b23', '84f13109-5b42-4c15-93a6-d817151a51b5', 'b', 'El peso del buque y el empuje actúan en diferentes verticales y el par que se crea no tiene fuerza suficiente para devolverlo a la posición de adrizado.', false, '2025-09-13 13:53:12.315607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('863dc8b1-d42c-4e06-9bad-c795627517ad', '84f13109-5b42-4c15-93a6-d817151a51b5', 'c', 'El peso y el empuje actúan siempre en la misma vertical y no se genera ningún par de fuerzas que haga adrizarlo.', true, '2025-09-13 13:53:12.31575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9607ac19-dbc2-4b93-a2ea-39fcaf8250ed', '84f13109-5b42-4c15-93a6-d817151a51b5', 'd', 'El metacentro está por encima del centro de gravedad.', false, '2025-09-13 13:53:12.315903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dcc6fc7-c007-44cf-886c-6e23544e98b9', 'af4b9b7e-c540-43e4-a59d-df9cd37082e5', 'a', 'Generará una serie de señales de respuesta al ser interrogado por un radar marino de banda X en las proximidades de nuestra embarcación.', false, '2025-09-13 13:53:12.31625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fde69e1b-fb55-421d-a232-b19970e36720', 'af4b9b7e-c540-43e4-a59d-df9cd37082e5', 'b', 'Generará una serie de señales de respuesta al ser interrogado por un radar marino de banda S en las proximidades de nuestra embarcación.', true, '2025-09-13 13:53:12.316394+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39fe248f-c316-457f-a6ac-5fea9c3c30e7', 'af4b9b7e-c540-43e4-a59d-df9cd37082e5', 'c', 'Transmitirá un mensaje de emergencia, la posición y un número identificativo a través de un módulo GNSS integrado en el propio dispositivo.', false, '2025-09-13 13:53:12.316532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85d69990-5fc2-4e51-93c6-6865872d505e', 'af4b9b7e-c540-43e4-a59d-df9cd37082e5', 'd', 'Transmitirá en frecuencia HF un aviso a todos los centros de salvamento marítimo.', false, '2025-09-13 13:53:12.316666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d49cab1d-7374-4674-8b74-507b6dbcc5c7', '0888237c-3ed1-46af-8ae6-90419e90b40d', 'a', 'Su activación puede ser manual o automática según el modelo.', false, '2025-09-13 13:53:12.316956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eab3e5c0-faa4-4cd0-9c8c-cff75e38ca55', '0888237c-3ed1-46af-8ae6-90419e90b40d', 'b', 'Su señal se refleja en la pantalla de radar por un único punto.', false, '2025-09-13 13:53:12.317094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cda7a964-355f-464f-a09b-66fc2bc9d9ca', '0888237c-3ed1-46af-8ae6-90419e90b40d', 'c', 'Funciona en una banda de 9 GHz y generará una señal de respuesta en un RADAR de banda X de otro barco o aeronave.', false, '2025-09-13 13:53:12.317235+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90843d15-7429-43f6-b807-24fe4b439ebf', '0888237c-3ed1-46af-8ae6-90419e90b40d', 'd', 'Para su activación manual se debe quitar el pasador de bloqueo y poner el interruptor en la', true, '2025-09-13 13:53:12.317368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c827c2a9-e9e0-4db3-a34d-2ebbe9fb9522', '88e9489b-8caf-4204-82c5-c64d5d1e0fcb', 'a', 'Utilice un bote de humo para señalar su posición, además resultará útil para que el helicóptero observe la dirección del viento.', false, '2025-09-13 13:53:12.317673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('820259e4-58f5-40f5-b207-5fb36624a755', '88e9489b-8caf-4204-82c5-c64d5d1e0fcb', 'b', 'Utilice un cohete con paracaídas para llamar la atención y que localicen su posición ya que una señal alta será mejor percibida por las unidades aéreas.', false, '2025-09-13 13:53:12.317822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14bc5cbd-ca2d-4769-b236-235bdd47088b', '88e9489b-8caf-4204-82c5-c64d5d1e0fcb', 'c', 'Use el VHF portátil para guiar al helicóptero usando la técnica de las horas en un reloj.', false, '2025-09-13 13:53:12.317963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2456cf90-9c71-4eac-aee4-11dba434e550', '88e9489b-8caf-4204-82c5-c64d5d1e0fcb', 'd', 'Utilice un espejo de señales para llamar la atención del helicóptero.', true, '2025-09-13 13:53:12.318096+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bdb4061-3260-41b4-8342-2102e6907ff7', '8969759d-1dd1-42ad-a760-45c5a08dfd0b', 'a', 'Atienda la información e instrucciones del Centro de Salvamento Marítimo.', false, '2025-09-13 13:53:12.31837+00');
