INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d264c7ec-f2b9-44cf-b42e-8454c407e9d5', '8969759d-1dd1-42ad-a760-45c5a08dfd0b', 'c', 'Suba a la cubierta todas las maletas, para facilitar su rápida recogida durante la evacuación.', true, '2025-09-13 13:53:12.318636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47f036d7-fa13-4ece-8b1c-5fff7da4b2c5', '8969759d-1dd1-42ad-a760-45c5a08dfd0b', 'd', 'Quítese el chaleco salvavidas, es un estorbo para ser izado. Meteorología', false, '2025-09-13 13:53:12.318771+00');
