INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8fa8fbd-66b9-4ca5-92bc-a6e4fd5a9652', '081f8587-8a9d-49b3-965a-5ff3b20cc118', 'a', 'El rumbo de aguja no es el rumbo verdadero, ya que le afectan la declinación magnética y el desvío de aguja.', false, '2025-09-13 13:53:12.33321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('818acc9c-8611-4b8a-991f-34412ee79f1b', '081f8587-8a9d-49b3-965a-5ff3b20cc118', 'b', 'El rumbo de superficie es el rumbo de avance de un buque por efecto del abatimiento.', true, '2025-09-13 13:53:12.333351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f802b77-7b23-4b62-879f-c95c47d348e7', '081f8587-8a9d-49b3-965a-5ff3b20cc118', 'c', 'El rumbo efectivo es el rumbo de avance de un buque sometido al efecto de la deriva.', false, '2025-09-13 13:53:12.333489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('093b8846-1291-49b0-a9fe-8dbe520e411e', '081f8587-8a9d-49b3-965a-5ff3b20cc118', 'd', 'El rumbo verdadero es la suma del rumbo de aguja, el rumbo efectivo y el rumbo de superficie. Navegación carta', false, '2025-09-13 13:53:12.333618+00');
