INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2986bec5-9d47-4113-a0f7-c20e6b4e22ea', '490f2d0f-902f-4fe9-bae8-91f7ef32d649', 'a', 'El número de palas que tiene unidas al núcleo es par.', false, '2025-09-13 13:53:12.341281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fecde012-8a55-4632-b28c-82e73966259e', '490f2d0f-902f-4fe9-bae8-91f7ef32d649', 'b', 'Si observamos la embarcación desde popa, dando atrás, la hélice gira en el sentido contrario a las agujas del reloj.', true, '2025-09-13 13:53:12.341419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76d067ec-8826-450a-8288-52e9450fd72d', '490f2d0f-902f-4fe9-bae8-91f7ef32d649', 'c', 'Si observamos la embarcación desde popa, dando avante, la hélice gira en el sentido contrario a las agujas del reloj.', false, '2025-09-13 13:53:12.341576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85ad56d1-3cd5-4179-9a27-e9656c18471c', '490f2d0f-902f-4fe9-bae8-91f7ef32d649', 'd', 'El capacete es plano para evitar cavitaciones en las palas.', false, '2025-09-13 13:53:12.34171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8b09095-5e54-407a-a604-c996ecbc4957', '0c2920d7-b75f-492b-986b-455b190b7517', 'a', 'Guardín.', false, '2025-09-13 13:53:12.342026+00');
