INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32a6b824-e484-4326-a715-04e71a42f76a', '0c2920d7-b75f-492b-986b-455b190b7517', 'd', 'Caña.', true, '2025-09-13 13:53:12.34243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('462ee686-c33a-48d2-b16c-3dab47aaff00', '246e1625-0ce9-4922-b9d9-b815bbf5b6ea', 'a', 'La obra muerta es la sección del casco situada por debajo del plano de flotación.', false, '2025-09-13 13:53:12.34271+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('990177b4-e616-4c52-8cfc-4843d0afaaed', '246e1625-0ce9-4922-b9d9-b815bbf5b6ea', 'b', 'Un portillo es un orificio de desagüe.', false, '2025-09-13 13:53:12.342865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14865a1b-4918-404a-a708-1a75e4311dec', '246e1625-0ce9-4922-b9d9-b815bbf5b6ea', 'd', 'Los guardamancebos son varillas metálicas verticales situadas en el borde exterior de la embarcación para sujetar los candeleros y evitar la caída de los tripulantes al agua.', false, '2025-09-13 13:53:12.343159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('832cf9a8-6bf3-46da-8c47-b97755f4a2ae', '4c074f13-740d-4749-a17d-3b624e776d55', 'a', 'Al giro de una embarcación fondeada en torno al ancla, por efecto del viento o de la corriente, se le denomina garreo.', false, '2025-09-13 13:53:12.344145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a875f64e-dcf8-4768-8390-a9e526ed1e26', '4c074f13-740d-4749-a17d-3b624e776d55', 'b', 'En el momento de fondear se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente en el fondo.', true, '2025-09-13 13:53:12.344278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af66d5bb-e137-4dec-8d36-02e3dd739ed0', '4c074f13-740d-4749-a17d-3b624e776d55', 'c', 'De forma general, la longitud de cadena para un fondeo con mal tiempo no será superior a dos veces la sonda del lugar de fondeo.', false, '2025-09-13 13:53:12.344411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f711e2f-04ac-417c-afa6-dbe20341d218', '4c074f13-740d-4749-a17d-3b624e776d55', 'd', 'Los fondos de algas son los mejores tenederos.', false, '2025-09-13 13:53:12.344545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7273ed50-f2c5-46f5-8e53-fc2ea5a259f2', '78748236-0f80-4078-8aaf-1fc3fc9a037d', 'a', 'Guía.', false, '2025-09-13 13:53:12.344825+00');
