INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2012f8bc-a8a1-45b7-aebf-810074536cee', '18482f2c-8b37-4ba0-be22-6d779523ec2f', 'a', 'El squat o sobrecalado de la embarcación.', false, '2025-09-13 13:53:12.345507+00');
