INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e475e51a-6848-44f3-8f34-f1adf282ee04', '32473e0c-e56a-4e7d-9b1f-f2d8c3f3fbdd', 'c', 'Activar la bocina de niebla para llamar la atención del náufrago.', true, '2025-09-13 13:53:12.346464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73ab62b3-7525-4c8d-b195-655369ced758', '32473e0c-e56a-4e7d-9b1f-f2d8c3f3fbdd', 'd', 'Maniobras de búsqueda cuando no se ve al náufrago.', false, '2025-09-13 13:53:12.346597+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb95760d-039c-467d-aaa8-226063537007', '56c909d2-9ed9-4c3d-8236-8734f90fe46b', 'a', 'Capear o correr el temporal.', false, '2025-09-13 13:53:12.346942+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e5d2e40-45ad-4dc3-97fe-cf282bfd02c0', '56c909d2-9ed9-4c3d-8236-8734f90fe46b', 'b', 'Asegurar una estiba y trinca a son de mar.', false, '2025-09-13 13:53:12.347109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8db52802-2c57-4cff-a07d-def208910971', '56c909d2-9ed9-4c3d-8236-8734f90fe46b', 'c', 'Revisar todas las aberturas.', false, '2025-09-13 13:53:12.347267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81fc8c07-943b-45de-be90-7759a568e49a', '56c909d2-9ed9-4c3d-8236-8734f90fe46b', 'd', 'Abrir los grifos de fondo para ayudar a desaguar el agua embarcada.', true, '2025-09-13 13:53:12.347403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c7841a6-b59e-4431-a57d-00ccdfdbff5c', '8d4775bc-9b9d-457b-b513-ea665f13bcb5', 'a', 'Cabezada.', false, '2025-09-13 13:53:12.347698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c679503-ef59-46e7-9d4b-b2653cbcf90b', '8d4775bc-9b9d-457b-b513-ea665f13bcb5', 'b', 'Balance.', true, '2025-09-13 13:53:12.347836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd5008a7-bc98-490f-a615-84f247758cd5', '8d4775bc-9b9d-457b-b513-ea665f13bcb5', 'c', 'Atravesarse a la mar.', false, '2025-09-13 13:53:12.347975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('556edb56-e914-40e3-aa58-9e7d73a4f135', '8d4775bc-9b9d-457b-b513-ea665f13bcb5', 'd', 'Virada.', false, '2025-09-13 13:53:12.348109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acbaf295-ef9c-42e5-85e1-1f51a95f0180', '12464470-851b-4fd5-8b0c-06cc020b092f', 'a', 'Podrán izarse en puertos nacionales y aguas interiores en solitario, pero si se navega por otros espacios marítimos deberá izarse al mismo tiempo el Pabellón nacional.', false, '2025-09-13 13:53:12.348393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d3e3e7e-9060-44bd-a66d-44bb58a1468d', '12464470-851b-4fd5-8b0c-06cc020b092f', 'b', 'Nunca serán de dimensiones superiores a un tercio del área del Pabellón nacional.', true, '2025-09-13 13:53:12.348531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbe4d7af-20f9-4301-9d9d-53e5f889f3b4', '12464470-851b-4fd5-8b0c-06cc020b092f', 'c', 'Podrán permanecer izadas, aunque no lo esté el Pabellón nacional.', false, '2025-09-13 13:53:12.348669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd49640a-dd99-431b-b389-1cf5cb5fc411', '12464470-851b-4fd5-8b0c-06cc020b092f', 'd', 'Es obligatorio izarlas a las entradas y salidas de puertos y, en éstos, de sol a sol, en los días festivos y cuando así lo disponga la autoridad competente.', false, '2025-09-13 13:53:12.348815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('502375ae-654d-4484-b68a-5a83f8518841', '28db368d-af05-44de-8044-518193c7edfd', 'b', 'Sólo las embarcaciones de recreo o deportivas a motor, incluidas las motos náuticas, con una eslora superior a cinco metros.', false, '2025-09-13 13:53:12.34925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42b6a3ad-4595-4cb5-92bd-6cf5a2b72ebe', '28db368d-af05-44de-8044-518193c7edfd', 'c', 'Sólo las embarcaciones de recreo o deportivas a motor, incluidas las motos náuticas, cualquiera que sea su eslora.', false, '2025-09-13 13:53:12.349386+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b61a587-1a1d-4715-84c3-6bce7263abaf', '28db368d-af05-44de-8044-518193c7edfd', 'd', 'Todos los objetos flotantes destinados a la navegación de recreo y deportiva propulsados a motor, incluidas las motos náuticas, piraguas, kayaks, canoas sin motor y otros artefactos flotantes sin propulsión mecánica, con una eslora superior a cinco metros.', false, '2025-09-13 13:53:12.349544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20defd41-a1dc-4028-bbf7-dd84148e7ca4', '9e1aa134-902a-4a5f-a206-b13adf7e6910', 'a', 'Indicar dónde pueden encontrarse las aguas más profundas en esa zona.', false, '2025-09-13 13:53:12.349887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ea14103-47de-489f-9a36-6d308e551536', '9e1aa134-902a-4a5f-a206-b13adf7e6910', 'b', 'Indicar la entrada de un canal, la aproximación a un puerto o estuario o un punto de recalada.', true, '2025-09-13 13:53:12.350051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d37f007-1efb-4f9a-8486-26c82a9230e2', '9e1aa134-902a-4a5f-a206-b13adf7e6910', 'c', 'Indicar el lado seguro por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:12.350217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42bd5610-3345-4501-a5e6-992ca4038f1c', '9e1aa134-902a-4a5f-a206-b13adf7e6910', 'd', 'Llamar la atención sobre una característica de un canal, tal como una curva, una unión o una', false, '2025-09-13 13:53:12.350382+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('114723e7-7ded-49fb-b9b3-edb9048612aa', '28db368d-af05-44de-8044-518193c7edfd', 'a', 'Todos los objetos flotantes destinados a la navegación de recreo y deportiva propulsados a motor, incluidas las motos náuticas, así como aquellos que carezcan de motor y tengan una eslora superior a seis metros.', true, '2025-09-13 13:53:12.349099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b228dc8-39a7-44ed-9a05-09c28eeb1e01', '246e1625-0ce9-4922-b9d9-b815bbf5b6ea', 'c', 'La amura es la parte de los costados del buque donde este empieza a estrecharse para formar la proa.', true, '2025-09-13 13:53:12.34302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('710a3748-c2a1-4157-a444-fa58d3fdf36e', 'cd1ee89b-2fc5-4a7e-bb49-b44e7c10b601', 'b', 'Son de color amarillo y pueden llevar una marca de tope en forma de X, y si tienen luz es blanca.', false, '2025-09-13 13:53:12.350878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce4f8740-6456-4edc-b6bb-46ab4ee6b398', 'cd1ee89b-2fc5-4a7e-bb49-b44e7c10b601', 'c', 'Tienen luces blancas con ritmos distintos a los empleados en las luces amarillas de las marcas cardinales para evitar confusiones.', false, '2025-09-13 13:53:12.351028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0862e4e9-e4b4-4ec7-845e-521cdf68edd2', 'cd1ee89b-2fc5-4a7e-bb49-b44e7c10b601', 'd', 'Son boyas que, colocadas a babor de un canal, habrán de ser cónicas.', false, '2025-09-13 13:53:12.351164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a574338d-a391-4825-be41-96324e47badb', '6e957fb1-c837-4ecb-91fe-19d6d0de2bca', 'a', 'Únicamente las Marcas laterales de babor.', false, '2025-09-13 13:53:12.351454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('def07be1-290d-4655-b2f4-0aabd2957d3f', '6e957fb1-c837-4ecb-91fe-19d6d0de2bca', 'b', 'Las Marcas laterales de babor y las Marcas laterales modificadas que indican en una bifurcación que el canal principal está a estribor.', true, '2025-09-13 13:53:12.35159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a0eda2a-836f-43d2-8c4d-2e8669b60fc5', '6e957fb1-c837-4ecb-91fe-19d6d0de2bca', 'c', 'Las Marcas laterales de estribor y las Marcas laterales modificadas que indican en una bifurcación que el canal principal está a babor.', false, '2025-09-13 13:53:12.351721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('705ba773-687f-477d-9f72-b94f7a4e002a', '6e957fb1-c837-4ecb-91fe-19d6d0de2bca', 'd', 'Únicamente las Marcas laterales de estribor.', false, '2025-09-13 13:53:12.351866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00f0d6d5-0728-462c-ab63-7e57b4279809', 'e75f4238-20e9-4d3e-91e3-63cc9746bd18', 'a', 'A elegir, pero sin que pueda prestarse a confusión con las marcas laterales, siendo preferibles las formas de castillete o espeque.', false, '2025-09-13 13:53:12.35217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('defb96f8-5d7c-40dd-b07a-216d5b383d1f', 'e75f4238-20e9-4d3e-91e3-63cc9746bd18', 'b', 'Siempre una figura rectangular o triangular.', false, '2025-09-13 13:53:12.352309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd79cfcb-846e-4120-a935-7728cdaa4492', 'e75f4238-20e9-4d3e-91e3-63cc9746bd18', 'c', 'Cualquiera, pero, por su color, ha de constituir una significativa marca diurna.', false, '2025-09-13 13:53:12.352445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9f785f7-463c-4d18-95b8-74fcdb37777b', 'e75f4238-20e9-4d3e-91e3-63cc9746bd18', 'd', 'Esférica, de castillete o espeque, con una marca de tope esférica.', true, '2025-09-13 13:53:12.352582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39343c8b-2597-4eb1-aabd-39d5bcefea33', '410e1d51-684d-4f36-8634-f0365f0b0779', 'a', 'Seguir el lado de babor o estribor de la derrota que indica la señal.', false, '2025-09-13 13:53:12.352865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee35342f-6567-424a-bbd8-90dbd5dbefc4', '410e1d51-684d-4f36-8634-f0365f0b0779', 'b', 'Dar tres pitadas cortas para indicar al resto de embarcaciones que puedan encontrarse en la zona que existe un peligro aislado.', false, '2025-09-13 13:53:12.353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('163e37ab-54bf-490d-bd17-1f36415da4cc', '410e1d51-684d-4f36-8634-f0365f0b0779', 'c', 'Consultar la carta y las publicaciones náuticas, al no poder especificarse con estas marcas el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', true, '2025-09-13 13:53:12.353157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc56f6d9-2536-49fb-957d-1e47f26084c8', '410e1d51-684d-4f36-8634-f0365f0b0779', 'd', 'Aproximarse a la marca todo lo que pueda con su embarcación para evitar el peligro que indica la Reglamento (RIPA).', false, '2025-09-13 13:53:12.353291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cc75670-416f-4d79-b508-3d343adf8b3d', '85242e8a-344a-45da-b15b-de3e443ac66e', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque de propulsión de mecánica.', false, '2025-09-13 13:53:12.353569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8dd1f96d-d864-4e4e-974c-8800340d79ad', '85242e8a-344a-45da-b15b-de3e443ac66e', 'b', 'Reducir la velocidad para estudiar la situación, siempre que sea posible, y si se considera que existe riesgo de abordaje, maniobrar preferiblemente de forma clara y con antelación suficiente.', true, '2025-09-13 13:53:12.353703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3fe98ae-2381-45ff-9589-555e8f446cd2', '85242e8a-344a-45da-b15b-de3e443ac66e', 'c', 'Realizar pequeños cambios de rumbo y velocidad para avisar a la otra embarcación de su obligación de mantenerse apartado de la derrota de nuestra embarcación por ser buque de vela.', false, '2025-09-13 13:53:12.353837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0bbf68d-cbba-4ce9-a2e3-8d2c243fa5a9', '85242e8a-344a-45da-b15b-de3e443ac66e', 'd', 'Dado que esta situación exige la obligación de maniobrar por ser embarcación de vela, cambiar de rumbo ligeramente para desviar nuestro rumbo lo menos posible y evitar el abordaje al mismo', false, '2025-09-13 13:53:12.353996+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f39f3e16-4be0-408d-8bac-1f97c577ae43', 'cb091676-05a1-400d-8863-48882474ccde', 'a', 'Tres luces rojas todo horizonte en línea vertical o un cilindro.', true, '2025-09-13 13:53:12.354345+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d387c9c-657d-4417-93b9-c95dd27e7b0e', 'cb091676-05a1-400d-8863-48882474ccde', 'b', 'Tres luces amarillas todo horizonte en línea vertical o un cilindro.', false, '2025-09-13 13:53:12.35451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3310540b-4f1d-4c8e-8db1-9c973e82dff3', 'cb091676-05a1-400d-8863-48882474ccde', 'c', 'Tres luces rojas todo horizonte en línea vertical o un cono.', false, '2025-09-13 13:53:12.354669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d90cc89-c480-4e18-957d-b5391807cba9', 'cb091676-05a1-400d-8863-48882474ccde', 'd', 'Tres luces amarillas todo horizonte en línea vertical o un cono.', false, '2025-09-13 13:53:12.354847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb6e8d43-8a75-419e-9ccf-e43ec97db696', '2852cb9c-52d6-4309-b003-43b45fe34b4f', 'a', 'Deberá en cualquier caso utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-13 13:53:12.355148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('966ad54d-817b-4742-8a99-9f463952a654', '2852cb9c-52d6-4309-b003-43b45fe34b4f', 'b', 'Navegará preferiblemente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:12.355282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81ec9510-4f94-4b66-8bd4-6fe4c2bb19d2', '2852cb9c-52d6-4309-b003-43b45fe34b4f', 'c', 'Podrá utilizar la zona de navegación costera o, si puede hacerlo en condiciones de seguridad y sin estorbar, la vía de circulación adecuada del dispositivo.', true, '2025-09-13 13:53:12.355421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('007887c1-9f29-4139-88bf-3dd0df653d62', '2852cb9c-52d6-4309-b003-43b45fe34b4f', 'd', 'Deberá en cualquier caso utilizar la zona de navegación costera.', false, '2025-09-13 13:53:12.355556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00fdbeed-535f-40c2-ae53-190f92278cc4', '6914a7f2-4957-4107-bf74-291abe24a03a', 'a', 'La anchura del buque remolcador es superior a 25 metros.', false, '2025-09-13 13:53:12.355837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8beca796-cdf8-4aef-b42f-dc736f88f16e', '6914a7f2-4957-4107-bf74-291abe24a03a', 'b', 'La anchura del buque remolcado es superior a 25 metros.', false, '2025-09-13 13:53:12.355971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cd0ed36-f378-4ccc-90a7-fa5c9c649b62', '6914a7f2-4957-4107-bf74-291abe24a03a', 'c', 'La eslora del buque remolcado es superior a 100 metros.', false, '2025-09-13 13:53:12.356102+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adc6308e-842c-4659-8f11-430fb179c5a7', '6914a7f2-4957-4107-bf74-291abe24a03a', 'd', 'La longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:12.356235+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18186fde-240f-4af3-a658-91805e205bd9', 'a0cb1a2b-0b5f-4fa6-a7fc-c79f07a93858', 'a', 'Con redes, líneas, aparejos de arrastre u otros artes de pesca que restrinjan su maniobrabilidad; esta expresión no incluye a los buques que pesquen con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', true, '2025-09-13 13:53:12.356508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5759469a-f1e0-4d44-af0c-ed4caac48335', 'a0cb1a2b-0b5f-4fa6-a7fc-c79f07a93858', 'b', 'Siempre que las redes, líneas, aparejos de arrastre u otros artes de pesca que utilice no restrinjan su maniobrabilidad.', false, '2025-09-13 13:53:12.356641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9d08697-ed3d-490a-950c-f56cf2ba6890', 'a0cb1a2b-0b5f-4fa6-a7fc-c79f07a93858', 'c', 'Con redes, líneas, aparejos de arrastre u otros artes de pesca que restrinjan su maniobrabilidad; incluyendo los buques que pesquen con curricán.', false, '2025-09-13 13:53:12.356792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d55869e-ca9d-4396-b178-4c9c72cfe9c5', 'a0cb1a2b-0b5f-4fa6-a7fc-c79f07a93858', 'd', 'Con redes de arrastre o de cerco que restrinjan su maniobrabilidad, otorgando al buque la consideración de buque sin gobierno.', false, '2025-09-13 13:53:12.356938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40614cf8-4fd5-4d70-83df-afa58eb4bb28', 'fbc841fc-2866-4c14-98da-f51024a23841', 'a', 'Cinco pitadas cortas y rápidas.', true, '2025-09-13 13:53:12.357287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1d6150e-7901-41b3-969e-125ff6dbfc56', 'fbc841fc-2866-4c14-98da-f51024a23841', 'b', 'Tres pitadas cortas y rápidas.', false, '2025-09-13 13:53:12.35746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07eff44f-4066-4113-99bb-30e1c050d552', 'fbc841fc-2866-4c14-98da-f51024a23841', 'c', 'Cinco pitadas largas.', false, '2025-09-13 13:53:12.357617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a07be3f-cdb2-4d7f-9d31-36bcc0ac3ad6', 'fbc841fc-2866-4c14-98da-f51024a23841', 'd', 'Tres pitadas largas.', false, '2025-09-13 13:53:12.357767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4443f6f2-00ff-4c81-a191-c3b830305fff', 'cd038da6-df02-4c5e-b1cf-21b3814ae454', 'a', 'Que es visible sin interrupción en un arco de horizonte de 360 grados.', false, '2025-09-13 13:53:12.358114+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c27feea-f3b3-4b8a-9cd0-92dc707384d7', 'cd038da6-df02-4c5e-b1cf-21b3814ae454', 'b', 'Con las mismas características que las luces de costado.', false, '2025-09-13 13:53:12.358245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45e48d91-1f61-4806-b8b1-9e1db48bb78f', 'cd038da6-df02-4c5e-b1cf-21b3814ae454', 'c', 'Con las mismas características que la luz de alcance.', true, '2025-09-13 13:53:12.358377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03ac7e72-ee23-44a7-81d5-07c08851ffea', 'cd038da6-df02-4c5e-b1cf-21b3814ae454', 'd', 'Que produce centelleos a intervalos regulares, con una frecuencia de 120 o más centelleos.', false, '2025-09-13 13:53:12.358508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('356c4ccb-199f-44aa-9d81-ceb85fca4e9b', '43acef95-1d4c-490c-b0a6-c32d61240e37', 'a', 'No es posible usar el aparato de señales de niebla para esta finalidad.', false, '2025-09-13 13:53:12.358786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1801f3d5-03fc-406a-b34f-e49176fc2def', '43acef95-1d4c-490c-b0a6-c32d61240e37', 'b', 'La configuración del sonido se especifica en función de la tipología del peligro.', false, '2025-09-13 13:53:12.358945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f9940db-a56e-4c6e-be74-6ca3067eadec', '43acef95-1d4c-490c-b0a6-c32d61240e37', 'c', 'Con un sonido corto, ajustando el número de repeticiones a las circunstancias.', false, '2025-09-13 13:53:12.359087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3840ee11-574b-452d-b4d6-586ee03affb8', '43acef95-1d4c-490c-b0a6-c32d61240e37', 'd', 'Con un sonido continuo.', true, '2025-09-13 13:53:12.359231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a6b2f26-508b-43b0-99ad-0673a9e356a0', 'e6b35bb2-ec5c-4b6d-bf70-e5913330e6ab', 'a', 'Con el compás, tomando la distancia y trasladando esta en la escala de longitudes.', false, '2025-09-13 13:53:12.368718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06e63fe6-d985-4596-9a1d-678667ac6ce5', 'b99029d2-0cd3-4045-b45a-14c5fdd3f49c', 'a', 'Cuando uno de los dos buques deba mantenerse apartado de la derrota del otro, ninguno mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:12.359534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('292f0cca-3be0-43b5-a3c2-276da681b8a0', 'b99029d2-0cd3-4045-b45a-14c5fdd3f49c', 'b', 'Cuando, por cualquier causa, el buque que haya de mantener su rumbo y velocidad se encuentre tan próximo al otro que no pueda evitarse el abordaje por la sola maniobra del buque que cede el paso, el primero no ejecutará ninguna maniobra que pueda ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.359682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b221015d-7b18-4ad0-a208-bdfda784a125', 'b99029d2-0cd3-4045-b45a-14c5fdd3f49c', 'c', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, no cambiará su rumbo a estribor para maniobrar a un buque que se encuentre por esa misma banda si las circunstancias del caso lo permiten.', false, '2025-09-13 13:53:12.359828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f3f24fc-07ce-45ef-96c6-2c59f8e75f82', 'b99029d2-0cd3-4045-b45a-14c5fdd3f49c', 'd', 'La presente Regla no exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:12.359984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad6826fa-eda2-41d0-afb9-515597bad3af', '88754189-7f00-4f2b-8041-859a23d4b98d', 'a', 'En aerodeslizadores, cuando operen en la condición sin desplazamiento.', true, '2025-09-13 13:53:12.360325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21f3bf70-897f-493d-9115-30736904de1b', '88754189-7f00-4f2b-8041-859a23d4b98d', 'b', 'En aerodeslizadores, siempre.', false, '2025-09-13 13:53:12.360491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05953ea6-2f1c-463d-bf21-c187d9b638f4', '88754189-7f00-4f2b-8041-859a23d4b98d', 'c', 'En embarcaciones de propulsión mecánica de menos de 7 metros que puedan navegar a una velocidad máxima de 7 nudos.', false, '2025-09-13 13:53:12.360639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9c57caf-99d1-4d12-912b-e9b58f0528b5', '88754189-7f00-4f2b-8041-859a23d4b98d', 'd', 'En naves de vuelo rasante cuando despeguen, aterricen o vuelen cerca de la superficie. Maniobra y navegación.', false, '2025-09-13 13:53:12.360783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc450801-517b-412f-b0e5-27a96bce1446', '2c84fe4c-78b3-4115-a4c9-257c3763c5a2', 'a', 'Tener el suficiente resguardo de seguridad entre la embarcación y la costa u otros escollos cuando se navega con viento, oleaje y/o corriente que tienden a echar la embarcación sobre el peligro.', true, '2025-09-13 13:53:12.361128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3e62b53-be2c-4594-a9b6-d620fd48c536', '2c84fe4c-78b3-4115-a4c9-257c3763c5a2', 'b', 'Dar la vuelta o hacer girar una embarcación en el menor espacio posible.', false, '2025-09-13 13:53:12.361274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94908bbf-6223-4f57-8552-ba3cd2e020d0', '2c84fe4c-78b3-4115-a4c9-257c3763c5a2', 'c', 'Navegar a barlovento y por lo tanto al socaire de sotavento.', false, '2025-09-13 13:53:12.361434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e23ec768-3da7-4300-8b94-e7093771e201', '2c84fe4c-78b3-4115-a4c9-257c3763c5a2', 'd', 'No contar con el suficiente resguardo de seguridad entre la embarcación y la costa u otros escollos cuando se navega a sotavento de otra embarcación.', false, '2025-09-13 13:53:12.361602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca185e7b-8b6f-4df4-8e26-ecaa652ae03a', '68d526b2-93c3-4e35-bf2c-6335dd20de12', 'a', 'Cobrar del largo de proa y del esprín de popa, lascando a su vez y dentro de lo posible, el largo de popa y el esprín de proa.', true, '2025-09-13 13:53:12.361976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62e2e4f1-2713-4a3d-9c76-e11dee15fd66', '68d526b2-93c3-4e35-bf2c-6335dd20de12', 'b', 'Cobrar del largo de popa.', false, '2025-09-13 13:53:12.362132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('380f2b37-d11f-4374-8371-0c754a225afe', '68d526b2-93c3-4e35-bf2c-6335dd20de12', 'c', 'Largar el través de proa a la vez que se lasca del esprín de proa.', false, '2025-09-13 13:53:12.36229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f74715d-e537-4d5f-b036-e8e9d2cb83b0', '2b4e87b4-495c-4429-8bda-935bfcef7db3', 'a', 'Hacer una llamada de socorro y activar la radiobaliza manualmente.', false, '2025-09-13 13:53:12.362781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6688b087-2428-4190-822b-70a36b6baee4', '2b4e87b4-495c-4429-8bda-935bfcef7db3', 'b', 'Ponerse ropa de abrigo y chaleco salvavidas.', false, '2025-09-13 13:53:12.362945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('449416d4-bf5c-4d94-98cf-baa61714a213', '2b4e87b4-495c-4429-8bda-935bfcef7db3', 'c', 'Si dispone de balsa salvavidas, amarrar a bordo la driza de la balsa antes de lanzarla al agua.', false, '2025-09-13 13:53:12.363108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2171bb83-a050-4c75-bdc3-26572eb4e34d', '2b4e87b4-495c-4429-8bda-935bfcef7db3', 'd', 'Si no dispone de balsa salvavidas, saltar al agua, de pie, con las piernas y rodillas juntas, y mantenerse en continuo movimiento para evitar la hipotermia.', true, '2025-09-13 13:53:12.363251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('775e39b3-6f46-45fd-80ad-15a497b25098', 'cee64e4c-9e76-4433-99f2-6ef8a990bf0d', 'a', 'Inclinar la cabeza hacia atrás y taponar las fosas nasales con una gasa estéril.', false, '2025-09-13 13:53:12.363541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ac87c35-a607-4aaa-a2ea-ed9eb0509c9e', 'cee64e4c-9e76-4433-99f2-6ef8a990bf0d', 'b', 'Aplicar un paño caliente sobre el tabique nasal.', false, '2025-09-13 13:53:12.36369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d980cdbd-37f1-408c-beef-29a389f8a22a', 'cee64e4c-9e76-4433-99f2-6ef8a990bf0d', 'd', 'Introducir algodón empapado con agua oxigenada en las fosas nasales.', false, '2025-09-13 13:53:12.364003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72005cb7-c381-40a6-b512-c9e48af23f41', '538d92ff-62bd-4c58-9780-38949a0c0710', 'a', 'El tipo de fondo, ya que la maniobra depende de si se trata de un fondo duro tipo rocoso o de un fondo blando tipo arena.', false, '2025-09-13 13:53:12.364301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ec7c811-8d46-4db0-9675-fc9dc467c010', '538d92ff-62bd-4c58-9780-38949a0c0710', 'b', 'Las mareas, ya que para liberar la embarcación suele ser preferible esperar a que haya marea alta.', false, '2025-09-13 13:53:12.364437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('834dd589-aaf1-41fb-bef0-e79803040746', '538d92ff-62bd-4c58-9780-38949a0c0710', 'c', 'Los medios de ayuda externa con los que contamos, ya que disponer del apoyo de otro buque o embarcación facilita la maniobra.', false, '2025-09-13 13:53:12.364578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81211a31-e8ef-4705-8f38-02c5e73adcf7', '538d92ff-62bd-4c58-9780-38949a0c0710', 'd', 'La distribución de pesos de la embarcación, ya que estos son inamovibles y nunca es posible redistribuirlos para variar las condiciones de asiento o escora. Meteorología', true, '2025-09-13 13:53:12.364711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99f50a09-efba-4fb4-866d-84e69adf406a', '8be41218-5fbe-420a-9b5d-b0980340cfb2', 'a', 'El número de horas que el viento sopla en la misma dirección.', false, '2025-09-13 13:53:12.365053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fbd4454-46c1-433d-9f16-46bee3f1909c', '8be41218-5fbe-420a-9b5d-b0980340cfb2', 'b', 'La velocidad con la que el viento cambia de dirección.', false, '2025-09-13 13:53:12.365188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8f3e830-d26d-4c76-bd9d-7a5444618f81', '8be41218-5fbe-420a-9b5d-b0980340cfb2', 'c', 'La velocidad con la que sopla el viento.', false, '2025-09-13 13:53:12.365346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b77f46b-e661-45f6-ac98-88aab3208d83', '8be41218-5fbe-420a-9b5d-b0980340cfb2', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando sopla de dirección y fuerza', true, '2025-09-13 13:53:12.365481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6344412-692d-4968-95e6-3fed370cc737', '44c6bccf-4de8-40f5-b26f-d55c0b10a8c1', 'a', 'El generado por el avance de la embarcación.', false, '2025-09-13 13:53:12.36577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('548782f4-2cc5-402f-8fba-c7dd889f986a', '44c6bccf-4de8-40f5-b26f-d55c0b10a8c1', 'b', 'El que percibimos navegando en la embarcación.', false, '2025-09-13 13:53:12.365905+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44818486-4f64-4ea0-a2c3-5afa1743c886', '44c6bccf-4de8-40f5-b26f-d55c0b10a8c1', 'c', 'El que existe en un momento dado, cuando la embarcación está parada.', true, '2025-09-13 13:53:12.366038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0737efe-52dc-437f-a1a5-5bcbe841f212', '44c6bccf-4de8-40f5-b26f-d55c0b10a8c1', 'd', 'El que aparece en la escala Beaufort de nuestra embarcación.', false, '2025-09-13 13:53:12.366169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a426ca1b-9278-4551-ad0b-d38bbc38a9db', 'de2f34a8-ec61-48ed-a3dc-e30a8d1a3608', 'a', 'La presión atmosférica.', true, '2025-09-13 13:53:12.366448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('125c8501-9816-4887-88de-8f195d212a1f', 'de2f34a8-ec61-48ed-a3dc-e30a8d1a3608', 'b', 'La velocidad de la embarcación.', false, '2025-09-13 13:53:12.366581+00');
