INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99489259-7090-471c-b907-94411f319d43', 'c5d52e06-2149-4600-bd0b-d6bd8803e0f7', 'a', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a una boya para señalar la ubicación del ancla.', false, '2025-09-13 13:53:12.378145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9789c3a-c7c5-4944-8687-1ffac6dc8882', 'c5d52e06-2149-4600-bd0b-d6bd8803e0f7', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la naturaleza del fondo y de la sonda.', false, '2025-09-13 13:53:12.378275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff8965fa-dfdd-4835-b3a3-95b4954ea1dd', 'c5d52e06-2149-4600-bd0b-d6bd8803e0f7', 'c', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', true, '2025-09-13 13:53:12.378409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c879e3af-0d0d-43ce-bf4c-fb3cd28c8f24', 'c5d52e06-2149-4600-bd0b-d6bd8803e0f7', 'd', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:12.378538+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecdbd910-2d95-4bd3-9895-84142dfdb150', 'd6b2f6ba-e615-4d07-aafb-d508ee8890a6', 'a', 'Arneses.', false, '2025-09-13 13:53:12.37882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68c15d30-a876-42d9-b927-f2a73a69b1bd', 'd6b2f6ba-e615-4d07-aafb-d508ee8890a6', 'b', 'Grifos de fondo.', true, '2025-09-13 13:53:12.378949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2747bb2c-b6a2-4ad5-8a9f-4361a15faa8b', 'd6b2f6ba-e615-4d07-aafb-d508ee8890a6', 'c', 'Bocina de niebla.', false, '2025-09-13 13:53:12.379091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d9b0355-0390-4d05-b58f-d2d6771c8adb', 'd6b2f6ba-e615-4d07-aafb-d508ee8890a6', 'd', 'Líneas de vida.', false, '2025-09-13 13:53:12.379222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4bfd4ca-52bc-47dc-be28-40f009172530', '23da9a21-bc60-4e3c-bb04-a480317728a6', 'b', 'Una campana, además del pito.', true, '2025-09-13 13:53:12.389515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('841c5280-aa46-4a85-b0c6-0419f4efdad3', 'e1f75bbd-d41f-44e9-ab0f-1b8130d2fba3', 'd', 'Se libere por no haberse podido recuperar.', false, '2025-09-13 13:53:12.377158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('542f52b5-fdf6-48bb-a702-6cfade9b18e3', '6755ecf5-75e6-4326-9f83-55663a9a5666', 'd', 'Transportador.', false, '2025-09-13 13:53:12.371317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f6190af-a41c-4956-9738-51177228e118', '9622728a-3323-4673-bbac-8110583e611f', 'a', 'Debe estar perfectamente establecida y sin ningún tipo de interrupción la comunicación del conductor con el mar.', false, '2025-09-13 13:53:12.379496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bfd70e6-5e96-4a63-b17e-6546a6134f4c', '9622728a-3323-4673-bbac-8110583e611f', 'c', 'El conductor debe evitar ángulos pronunciados.', false, '2025-09-13 13:53:12.379764+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01474ee0-bc36-4dcf-a5a0-c096660d5e12', '9622728a-3323-4673-bbac-8110583e611f', 'd', 'El pararrayos debe estar en contacto con otras antenas y jarcias para reforzar su poder de parar las descargas eléctricas que produzcan los rayos.', true, '2025-09-13 13:53:12.379893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2df871a9-2ff1-4f40-9a11-89eab1a422f8', '65ada75b-217b-4744-a40d-4936eacf24a7', 'a', 'El estado de los alimentos que se lleven a bordo.', false, '2025-09-13 13:53:12.380159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d441739c-7966-4660-8e2d-92ed722254a9', '65ada75b-217b-4744-a40d-4936eacf24a7', 'b', 'El nivel del tanque de almacenamiento de aguas negras, como por ejemplo las procedentes de inodoros y lavabos.', false, '2025-09-13 13:53:12.380287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4de2a63b-0e53-467d-933e-555752ec42bb', '65ada75b-217b-4744-a40d-4936eacf24a7', 'c', 'El nivel del tanque de agua salada.', false, '2025-09-13 13:53:12.380417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b1c591e-7619-4114-9842-d18909637b51', '65ada75b-217b-4744-a40d-4936eacf24a7', 'd', 'La estanqueidad de la embarcación.', true, '2025-09-13 13:53:12.380577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59926304-08ef-4d2b-80ff-4b1c836ad77e', 'cb99945c-80b9-4694-84e5-319fdb425513', 'a', 'Llamar por teléfono al 112.', false, '2025-09-13 13:53:12.380934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd2e34a0-63ef-4ef4-b09a-1c41c48a4ac7', 'cb99945c-80b9-4694-84e5-319fdb425513', 'b', 'Llamar por teléfono al 900 202 202.', false, '2025-09-13 13:53:12.381169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac979d20-870c-4aee-9507-c3602c0ded8a', 'cb99945c-80b9-4694-84e5-319fdb425513', 'c', 'Llamar por teléfono al 900 102 102.', true, '2025-09-13 13:53:12.381355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94a147e4-c653-408d-bbe2-b62a9371d452', 'cb99945c-80b9-4694-84e5-319fdb425513', 'd', 'Emplear la estación de radio de a bordo.', false, '2025-09-13 13:53:12.381518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d202ad48-a559-4765-b60c-9f990bcf1809', '3ddffe51-445a-4c9c-9742-0dfdf3224ceb', 'a', 'Siempre, ya que se encuentran navegando por espacios marítimos españoles.', false, '2025-09-13 13:53:12.382722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adff7a33-fec0-4ce1-82dd-65560dde0a50', '3ddffe51-445a-4c9c-9742-0dfdf3224ceb', 'b', 'Cuando el naviero o propietario lo crea aconsejable.', false, '2025-09-13 13:53:12.382869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e60f676-fc0a-4843-9e88-0291d336ccbd', '3ddffe51-445a-4c9c-9742-0dfdf3224ceb', 'c', 'Siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:12.383025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d11bee2c-1101-4d91-ad31-0dd1ddf63450', '3ddffe51-445a-4c9c-9742-0dfdf3224ceb', 'd', 'Sólo cuando tengan una embarcación de recreo superior a 12 metros de eslora.', false, '2025-09-13 13:53:12.383168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a836eeac-1b69-43ab-8e70-e4aa04b80f4f', '9be88f2b-d3d5-4890-a980-1bd0f52d8796', 'a', 'Oeste.', false, '2025-09-13 13:53:12.383461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('405b372a-0df2-49b0-bbe8-a7b691291335', '9be88f2b-d3d5-4890-a980-1bd0f52d8796', 'b', 'Norte.', false, '2025-09-13 13:53:12.383602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('741725f9-752e-41a3-b187-1a2b0f6ed457', '9be88f2b-d3d5-4890-a980-1bd0f52d8796', 'c', 'Sur.', false, '2025-09-13 13:53:12.383736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1f6bc58-915e-4d0e-81aa-24907b46d21f', '9be88f2b-d3d5-4890-a980-1bd0f52d8796', 'd', 'Este.', true, '2025-09-13 13:53:12.383908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa52df7c-1f5d-4922-9360-e358f72a13f9', '627b6c91-fdc7-4fc7-8de3-850f58a0570c', 'a', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:12.384232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea471be9-288a-47ba-b811-d67e8b595a67', '627b6c91-fdc7-4fc7-8de3-850f58a0570c', 'b', 'Franjas verticales rojas y negras.', false, '2025-09-13 13:53:12.384367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23681d46-21e8-49ea-b1cb-10c272597b00', '627b6c91-fdc7-4fc7-8de3-850f58a0570c', 'c', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:12.384499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c4ea386-33c5-483d-93c2-ad62a11e56ab', '627b6c91-fdc7-4fc7-8de3-850f58a0570c', 'd', 'Franjas horizontales rojas y negras.', false, '2025-09-13 13:53:12.384628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e677efea-cd56-416e-9520-9dd44c4cdfc7', '6c0aa06d-e369-4b4e-ad7e-c1801b9d4e97', 'a', 'Los peligros aislados de dimensiones limitadas enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:12.38494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0463c15e-6e1e-4bd9-b601-42636a96c551', '6c0aa06d-e369-4b4e-ad7e-c1801b9d4e97', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse, a fin de evitar un peligro concreto.', false, '2025-09-13 13:53:12.385075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da394fb7-84e5-4e6c-9b15-acd9f0147868', '6c0aa06d-e369-4b4e-ad7e-c1801b9d4e97', 'c', 'Que las aguas más profundas en esa zona se encuentran rodeadas de algún tipo de peligro no representado aún en la carta náutica.', false, '2025-09-13 13:53:12.385208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('493095a6-1721-4c1c-8c26-d4dbd675cf13', '6c0aa06d-e369-4b4e-ad7e-c1801b9d4e97', 'd', 'Algún tipo de peligro concreto y la marca será distinta según el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', false, '2025-09-13 13:53:12.385356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95e3d056-4229-4cfc-b246-a8467fc323dc', 'a9b0107c-ce29-49ef-a65e-c900f789bebd', 'a', 'Están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.385676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3080106a-c8c8-45fb-847f-74536abbd8fb', 'a9b0107c-ce29-49ef-a65e-c900f789bebd', 'b', 'Pueden prestarse a confusión con la de otras marcas de ayudas a la navegación, por eso la forma de las boyas de las marcas especiales será siempre rectangular.', false, '2025-09-13 13:53:12.385847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63dd1f04-4b15-4543-b180-8df254e44105', 'a9b0107c-ce29-49ef-a65e-c900f789bebd', 'c', 'Serán de color amarillo y las boyas tendrán la forma de castillete o espeque.', false, '2025-09-13 13:53:12.386018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('995123b1-fd9b-4bc9-8dd2-0509e8c3d9e9', 'a9b0107c-ce29-49ef-a65e-c900f789bebd', 'd', 'No tienen una forma preestablecida, pudiendo elegirse cualquiera que no se preste a confusión con la de otras marcas de ayudas a la navegación.', true, '2025-09-13 13:53:12.386177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1f40077-f085-4eff-bf9a-56d8156d1c82', '6fda3060-0d52-40f4-a7de-8c90b482f667', 'a', 'La existencia de un peligro en el canal principal.', false, '2025-09-13 13:53:12.386488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65b58be1-216f-43df-a381-93d93f3bc891', '6fda3060-0d52-40f4-a7de-8c90b482f667', 'b', 'El punto de bifurcación de un canal.', true, '2025-09-13 13:53:12.386628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('108bd8bf-00c5-4c58-aa45-387d19191585', '6fda3060-0d52-40f4-a7de-8c90b482f667', 'c', 'El final de un canal balizado.', false, '2025-09-13 13:53:12.386765+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6280545d-7a10-4105-9732-72573b5b22e1', 'a40ce16b-44c6-45bc-b0a4-60af1dbcb94b', 'a', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:12.387192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b9a6750-4439-4ff2-bb02-ac2d615d2a62', 'a40ce16b-44c6-45bc-b0a4-60af1dbcb94b', 'b', 'Una pitada larga.', false, '2025-09-13 13:53:12.387331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8232f71-79c8-4f4f-bfdc-9defbe853917', 'a40ce16b-44c6-45bc-b0a4-60af1dbcb94b', 'c', 'Dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.387465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86b7afd8-af92-445b-8f7e-6c52737c77b8', 'a40ce16b-44c6-45bc-b0a4-60af1dbcb94b', 'd', 'Una pitada corta.', false, '2025-09-13 13:53:12.3876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4447381-24cb-46e1-8433-55cfb1abe6d2', '1815c48f-7bbf-4cb6-abe8-9d63660ee7c0', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.387923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbefb14c-3b5a-4d22-a494-8f2f3f4bce6f', '1815c48f-7bbf-4cb6-abe8-9d63660ee7c0', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', true, '2025-09-13 13:53:12.388068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('baaa7768-8a27-4a1d-ac49-4f6b153b1231', '1815c48f-7bbf-4cb6-abe8-9d63660ee7c0', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de estribor.', false, '2025-09-13 13:53:12.388204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cab970f-9fb7-4fc1-9605-d2318e076b34', '1815c48f-7bbf-4cb6-abe8-9d63660ee7c0', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:12.388341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0d6e2dd-f93d-432d-93a1-4a7a5f721155', '4fd2dbce-0199-411a-9d6a-696c5c8cede7', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.388636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cee9148c-4e6c-4e47-86ed-374baa6b5f21', '4fd2dbce-0199-411a-9d6a-696c5c8cede7', 'b', 'Se deberá mantener el rumbo ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:12.388789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f861f1c-196c-4904-9ad2-ad4a5e7a97a7', '4fd2dbce-0199-411a-9d6a-696c5c8cede7', 'c', 'Únicamente deberemos maniobrar por ser el buque que alcanza un velero, en cualquier otra situación se mantendría rumbo tal y como recoge la regla.', false, '2025-09-13 13:53:12.388958+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1e83fa3-7b2e-4ff7-a18f-f92ee7af22d6', '4fd2dbce-0199-411a-9d6a-696c5c8cede7', 'd', 'Los datos aportados en el enunciado no son suficientes para determinar por qué banda recibe el viento el velero, siendo esto fundamental para decidir si debemos maniobrar o mantener rumbo.', false, '2025-09-13 13:53:12.389089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc3bd6ec-2049-42a6-a15c-40f3f8c4ff8f', '6fda3060-0d52-40f4-a7de-8c90b482f667', 'd', 'El comienzo de un canal balizado.', false, '2025-09-13 13:53:12.386902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa5b2e5e-7900-43e3-a248-d80a709dae95', '9622728a-3323-4673-bbac-8110583e611f', 'b', 'La punta o puntas del pararrayos deben ser afiladas y con suficiente dureza para no ser fundidas por un rayo.', false, '2025-09-13 13:53:12.379635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5b003cf-12b9-4dda-8ecc-f903bbb08f38', 'de214037-6d84-45f6-94a6-b86a1e17a976', 'a', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:12.3909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09965fee-c5bd-4f15-a3ff-02cffcc8ea64', 'de214037-6d84-45f6-94a6-b86a1e17a976', 'b', 'Las Reglas relativas a las luces deberán cumplirse desde la puesta del sol hasta su salida, y durante ese intervalo no se exhibirá ninguna otra luz, con la excepción de aquellas que no puedan ser confundidas con las luces mencionadas en este Reglamento o que no perjudiquen su visibilidad o carácter distintivo, ni impidan el ejercicio de una vigilancia eficaz.', false, '2025-09-13 13:53:12.391032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5ec0072-6076-496d-a52a-a92b714938f6', 'de214037-6d84-45f6-94a6-b86a1e17a976', 'c', 'Las luces preceptuadas por estas Reglas, en caso de llevarse, deberán exhibirse también desde la salida hasta la puesta del sol si hay visibilidad reducida y podrán exhibirse en cualquier otra circunstancia que se considere necesario.', false, '2025-09-13 13:53:12.391168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01e6e3d1-8112-4892-a028-2bf75d2634de', 'de214037-6d84-45f6-94a6-b86a1e17a976', 'd', 'Las Reglas relativas a las marcas deberán cumplirse de día de manera optativa a juicio del capitán, armador o patrón.', true, '2025-09-13 13:53:12.391302+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b5206ac-0cf0-4592-bf3e-ae264b2e8909', '088b44db-0755-4342-a4f1-05b72b80af21', 'a', 'Luz de tope.', true, '2025-09-13 13:53:12.391577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4354e56b-23ed-4255-acfb-41e3f8c8dba4', '088b44db-0755-4342-a4f1-05b72b80af21', 'b', 'Luz de alcance.', false, '2025-09-13 13:53:12.391706+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20bf311e-ef43-4883-915b-fff2b591c9ca', '088b44db-0755-4342-a4f1-05b72b80af21', 'c', 'Luz de remolque.', false, '2025-09-13 13:53:12.391853+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38f187ee-2c64-496c-b2f5-641aa7772bc0', '088b44db-0755-4342-a4f1-05b72b80af21', 'd', 'Luz de fondeo.', false, '2025-09-13 13:53:12.391984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed1fb8ef-3eb4-4c7b-b03e-424ac7836553', '2e3c4256-a1fb-4d57-ba14-39521b0fea27', 'a', 'Los buques de propulsión mecánica, en navegación, se mantendrán apartados de la derrota de un buque sin gobierno.', false, '2025-09-13 13:53:12.392283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da9b4d77-bedf-45b1-a4e1-779c0f4ed938', '2e3c4256-a1fb-4d57-ba14-39521b0fea27', 'c', 'En la medida de lo posible, los buques dedicados a la pesca, en navegación, se mantendrán apartados de la derrota de un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:12.392613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db827cce-9649-4eda-9dce-f5bc7671682e', '2e3c4256-a1fb-4d57-ba14-39521b0fea27', 'd', 'Los buques de vela, en navegación, se mantendrán apartados de la derrota de un buque de propulsión mecánica.', true, '2025-09-13 13:53:12.392782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45ddf330-06c6-40aa-a112-f6ec8cbfba1f', 'f9986438-d7fc-49e8-ad06-52dccec6fa51', 'a', 'En cualquier embarcación de vela que no supere los 7 metros de eslora y embarcaciones de remo.', true, '2025-09-13 13:53:12.393121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d0efedce-66c2-43c0-bcdd-2a4bdceabfaf', 'f9986438-d7fc-49e8-ad06-52dccec6fa51', 'd', 'Sólo en embarcaciones de remos.', false, '2025-09-13 13:53:12.39359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b3bfc5a-9703-4f2f-b210-682dcc7c8e13', '71d573ce-b8b5-498b-9984-e705176aa923', 'a', 'La escala que esté usando el radar puede imponer restricciones a la hora de detectar objetivos.', true, '2025-09-13 13:53:12.393936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a8210ec-3a34-4c76-b8b4-3791a52f2fdf', '71d573ce-b8b5-498b-9984-e705176aa923', 'b', 'El estado de la mar no influye en la detección de objetivos ya que la señal de alta frecuencia que emite el radar es electromagnética.', false, '2025-09-13 13:53:12.394094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98a35947-e469-46f7-87b6-c59adc48da20', '71d573ce-b8b5-498b-9984-e705176aa923', 'c', 'Sin importar las características del radar, siempre detectará los pequeños objetos flotantes o embarcaciones pequeñas.', false, '2025-09-13 13:53:12.394249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04805e55-dbff-410b-bb18-d274b2d380eb', '71d573ce-b8b5-498b-9984-e705176aa923', 'd', 'De noche, la existencia de resplandor producido por las luces de tierra influirá en la detección del radar de otras embarcaciones. Maniobra y navegación.', false, '2025-09-13 13:53:12.39441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c69f3e85-7c92-448f-bedd-19e4734b6e56', '0b35cf91-190a-4966-aa9d-a61ac549f9b1', 'a', 'Proa al viento.', true, '2025-09-13 13:53:12.394724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9be305cb-7f06-464c-b6e5-cab91d49b27e', '0b35cf91-190a-4966-aa9d-a61ac549f9b1', 'b', 'Con el viento o corriente por popa y la boya por la proa.', false, '2025-09-13 13:53:12.394862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5867f0b-e2d0-4d8f-bcdf-cbfe695b2ea6', '0b35cf91-190a-4966-aa9d-a61ac549f9b1', 'c', 'Con el viento o corriente por una amura y la boya por la amura opuesta.', false, '2025-09-13 13:53:12.394994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d073788-0e68-409f-b76e-96ff26075134', '0b35cf91-190a-4966-aa9d-a61ac549f9b1', 'd', 'Popa al viento.', false, '2025-09-13 13:53:12.395133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25fc331c-2670-468f-a7f0-36cdef846c41', '8dfcb615-725b-477e-85f5-4409c1f129ee', 'a', 'Cazarlo.', false, '2025-09-13 13:53:12.395413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37671a4d-b662-459e-9b7b-987ed3be1ede', '8dfcb615-725b-477e-85f5-4409c1f129ee', 'b', 'Soltarlo un poco.', true, '2025-09-13 13:53:12.395548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4940caf-b336-4f40-986e-c54eeee6de26', '8dfcb615-725b-477e-85f5-4409c1f129ee', 'c', 'Tensarlo un poco.', false, '2025-09-13 13:53:12.395679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('071d418f-a36d-4d39-a03e-12e93bb84134', '07e44b06-18af-4ecd-b2ec-15b756f48fea', 'a', 'Realizar una llamada de socorro, si no puede detener la entrada de agua.', false, '2025-09-13 13:53:12.396082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b546a1ba-22d0-46e3-a086-a85845f9813e', '07e44b06-18af-4ecd-b2ec-15b756f48fea', 'b', 'Abandonar inmediatamente la embarcación.', true, '2025-09-13 13:53:12.396213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2626bc1-0b39-4ab4-bc46-17bede505620', '07e44b06-18af-4ecd-b2ec-15b756f48fea', 'c', 'Aumentar la flotabilidad vaciando el depósito de agua dulce al mínimo imprescindible.', false, '2025-09-13 13:53:12.396344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22a332d4-0b2a-41d0-8560-5e1b496856f4', '07e44b06-18af-4ecd-b2ec-15b756f48fea', 'd', 'Si la vía de agua está originada por el fallo de una válvula o pasa cascos, colocar un espiche.', false, '2025-09-13 13:53:12.396474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e112b7e4-806b-4e46-94ee-8892b247bab7', '2ceed827-07f5-4648-9ce2-99b657212a7c', 'a', 'En condiciones de escasa visibilidad, emplear la bocina de niebla.', false, '2025-09-13 13:53:12.396751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc88f3c9-d566-4665-ae62-5a0944e08870', '2ceed827-07f5-4648-9ce2-99b657212a7c', 'b', 'Izar un reflector de radar.', false, '2025-09-13 13:53:12.396901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c4cf536-d725-4901-ac30-a873484960c3', '2ceed827-07f5-4648-9ce2-99b657212a7c', 'c', 'Si navega a vela, desconfíar de que respetarán su preferencia.', false, '2025-09-13 13:53:12.397038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d13820a9-11e3-487f-a8cb-2b8eb1f3310f', '2ceed827-07f5-4648-9ce2-99b657212a7c', 'd', 'No utilizar en ningún caso el VHF para alertar al buque que navega a rumbo de colisión.', true, '2025-09-13 13:53:12.397174+00');
