INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59445442-b871-4eef-b446-83925524d334', '520d8c18-fc63-4a05-b30f-1d3674e9cc54', 'd', 'Su desvío varía con el rumbo al que se navegue.', false, '2025-09-13 13:53:12.402013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f046a9ab-735a-4fa9-a869-f39b90adbb4b', 'fa5f79b6-9643-478c-844c-4609318b3b8e', 'a', 'Si la medimos en circulares en sentido de las agujas del reloj, es negativa.', false, '2025-09-13 13:53:12.402295+00');
