INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a078244a-a7b4-4409-9b58-be3cbcf998bc', '98feb122-331f-4a2a-b421-ac042d3750c7', 'b', 'Filar es largar o arriar cabo o cadena al fondear o en cualquier otro momento de la maniobra.', false, '2025-09-13 13:53:12.407405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33165fc3-d642-4e7d-b6ed-f6bdb1665705', '98feb122-331f-4a2a-b421-ac042d3750c7', 'c', 'Zarpar es el momento en que el ancla toca el fondo en la maniobra de fondeo.', true, '2025-09-13 13:53:12.407531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49611f8d-2a97-4bf1-abe4-1d653e827e97', '98feb122-331f-4a2a-b421-ac042d3750c7', 'd', 'Levar es virar cadena o cabo para recoger el ancla.', false, '2025-09-13 13:53:12.407661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57483d48-2557-4b0f-83cc-0af111cb3cc0', '2fdfb4d6-e436-4e83-956f-37968dad1603', 'a', 'Guardín.', false, '2025-09-13 13:53:12.407928+00');
