INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78708692-6639-4698-b637-461ef5ec77f6', '2fdfb4d6-e436-4e83-956f-37968dad1603', 'd', 'Caña.', true, '2025-09-13 13:53:12.408315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('938637ee-201f-4173-9e2a-d410cc802238', '9fbc4707-c87d-4e29-985a-f89c78d2864b', 'a', 'La obra muerta es la sección del casco situada por debajo del plano de flotación.', false, '2025-09-13 13:53:12.408589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('837cdcad-8dd5-4640-8700-85a56fe62098', '9fbc4707-c87d-4e29-985a-f89c78d2864b', 'b', 'Un portillo es un orificio de desagüe.', false, '2025-09-13 13:53:12.408722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d97019a4-375f-4dd0-b06d-742b027f0a6b', '9fbc4707-c87d-4e29-985a-f89c78d2864b', 'd', 'Los guardamancebos son varillas metálicas verticales situadas en el borde exterior de la embarcación para sujetar los candeleros y evitar la caída de los tripulantes al agua.', false, '2025-09-13 13:53:12.408983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44ac9166-b9ef-441f-9689-45cc8507b6d8', '4f4fc275-bf23-4b34-b88f-ccb61071e1a6', 'a', 'El número de palas que tiene unidas al núcleo es par.', false, '2025-09-13 13:53:12.40925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce5afe56-77b4-4f6b-bd52-83889cfd7f68', '4f4fc275-bf23-4b34-b88f-ccb61071e1a6', 'b', 'Si observamos la embarcación desde popa, dando atrás, la hélice gira en el sentido contrario a las agujas del reloj.', true, '2025-09-13 13:53:12.409377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ae00fda-4c22-4acc-b18a-7f1eff633a51', '4f4fc275-bf23-4b34-b88f-ccb61071e1a6', 'c', 'Si observamos la embarcación desde popa, dando avante, la hélice gira en el sentido contrario a las agujas del reloj.', false, '2025-09-13 13:53:12.409503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e45ce60d-1670-404e-9778-463387d34f2e', 'fc944419-8b23-421e-b766-c2f9f952fb3c', 'a', 'Guía.', false, '2025-09-13 13:53:12.409929+00');
