INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dccc8c6d-1804-4362-8381-bf2a799d31e1', '18dbc479-2077-49ce-b2ae-1b5f4aa5c418', 'd', 'Nudo llano.', false, '2025-09-13 13:53:12.519783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efd73794-5fc8-4b4b-bb20-324d0ff7bc94', '9fbc4707-c87d-4e29-985a-f89c78d2864b', 'c', 'La amura es la parte de los costados del buque donde este empieza a estrecharse para formar la proa.', true, '2025-09-13 13:53:12.408849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36cc14f4-2ef2-4439-a843-5ed086056f85', '4f4fc275-bf23-4b34-b88f-ccb61071e1a6', 'd', 'El capacete es plano para evitar cavitaciones en las palas.', false, '2025-09-13 13:53:12.40963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57e8030d-ab53-4e29-8ec0-d5fcd8cac9a5', '98feb122-331f-4a2a-b421-ac042d3750c7', 'a', 'Virar es cobrar cabo o cadena de la línea de fondeo al levar anclas o en cualquier momento de la maniobra.', false, '2025-09-13 13:53:12.40727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec824c20-921b-4ee9-8807-607f7ecd79a1', '42bcf580-5fe7-41fe-a31d-d9629c3b8295', 'd', 'Nocturna que tiene dirección desde el mar hacia tierra.', false, '2025-09-13 13:53:12.400612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26a2f661-a287-47a5-8430-4a8674b20129', '04281312-d83e-4630-9b56-a59498673bf4', 'd', 'Intensidad de empuje en superficie.', false, '2025-09-13 13:53:12.404086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c100de0d-3655-4d36-855e-0b60b70ec5eb', '4baf88af-dbb4-4061-9ef6-4f279ac12f7f', 'a', 'Al giro de una embarcación fondeada en torno al ancla, por efecto del viento o de la corriente, se le denomina garreo.', false, '2025-09-13 13:53:12.410742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f251090-ab67-4032-acc2-f2e170549564', '4baf88af-dbb4-4061-9ef6-4f279ac12f7f', 'b', 'En el momento de fondear se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente en el fondo.', true, '2025-09-13 13:53:12.410922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95b3f0b2-868e-499c-b2e7-ab7322c53450', '4baf88af-dbb4-4061-9ef6-4f279ac12f7f', 'c', 'De forma general, la longitud de cadena para un fondeo con mal tiempo no será superior a dos veces la sonda del lugar de fondeo.', false, '2025-09-13 13:53:12.411075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae3e8977-0bbe-4758-8abc-17fd87b5028d', '4baf88af-dbb4-4061-9ef6-4f279ac12f7f', 'd', 'Los fondos de algas son los mejores tenederos.', false, '2025-09-13 13:53:12.411217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af7c3b46-60d8-4c3b-8346-7ab2cce6be97', 'b390d0c0-d486-45e0-81e6-7c1027bea5aa', 'a', 'Lanzamiento de ayudas.', false, '2025-09-13 13:53:12.41153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94fa81c2-7fb7-4e5d-9d78-96e133bd350c', 'b390d0c0-d486-45e0-81e6-7c1027bea5aa', 'b', 'Uso del sistema de navegación por satélite (GNSS).', false, '2025-09-13 13:53:12.411683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7db72e26-d587-440a-9479-5cc9ee5ebccb', 'b390d0c0-d486-45e0-81e6-7c1027bea5aa', 'c', 'Activar la bocina de niebla para llamar la atención del náufrago.', true, '2025-09-13 13:53:12.411837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08faac15-0a92-4d95-9fb8-2e2bca35d421', 'b390d0c0-d486-45e0-81e6-7c1027bea5aa', 'd', 'Maniobras de búsqueda cuando no se ve al náufrago.', false, '2025-09-13 13:53:12.411993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62076cc8-96f7-4222-8bbd-0f8af0903247', '2657ff6f-20a1-48f3-b52d-a9b036aa2158', 'a', 'Cabezada.', false, '2025-09-13 13:53:12.412311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31870927-bb9c-481c-8e30-bcb8bdce431d', '2657ff6f-20a1-48f3-b52d-a9b036aa2158', 'b', 'Balance.', true, '2025-09-13 13:53:12.412468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d7e9f04-695a-4bce-8a90-4a33e6bacf3b', '2657ff6f-20a1-48f3-b52d-a9b036aa2158', 'c', 'Atravesarse a la mar.', false, '2025-09-13 13:53:12.412621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b3bfdf9-0ba5-4c5d-9513-0be29b519e3e', '2657ff6f-20a1-48f3-b52d-a9b036aa2158', 'd', 'Virada.', false, '2025-09-13 13:53:12.412794+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('407b209e-bbbe-4547-991d-8d82859414f3', '1112a987-b5e6-4954-90dd-daccce9be20e', 'a', 'Capear o correr el temporal.', false, '2025-09-13 13:53:12.413089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d442e076-c05b-4c2d-a556-539d8b845ef6', '1112a987-b5e6-4954-90dd-daccce9be20e', 'b', 'Asegurar una estiba y trinca a son de mar.', false, '2025-09-13 13:53:12.413223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1495beed-d87a-4b2c-ae2e-9e5a8b10ad9b', '1112a987-b5e6-4954-90dd-daccce9be20e', 'c', 'Revisar todas las aberturas.', false, '2025-09-13 13:53:12.413352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e27780a-338e-4c15-8435-986d7fa4b879', '1112a987-b5e6-4954-90dd-daccce9be20e', 'd', 'Abrir los grifos de fondo para ayudar a desaguar el agua embarcada.', true, '2025-09-13 13:53:12.413479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3aac7b41-8810-4e69-be40-9f5ee1561b69', '7e3dc30a-f0f2-42f7-a983-481d61c5bb64', 'a', 'El squat o sobrecalado de la embarcación.', false, '2025-09-13 13:53:12.41377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b099a3a0-4b05-4620-afb9-89552679437d', '7e3dc30a-f0f2-42f7-a983-481d61c5bb64', 'b', 'La reflexión del oleaje por efecto del fondo o con la costa próxima.', false, '2025-09-13 13:53:12.413913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01051431-9efd-4347-bc50-60972e8491fe', '7e3dc30a-f0f2-42f7-a983-481d61c5bb64', 'c', 'La disminución de la velocidad de avance de las olas por los rompientes.', false, '2025-09-13 13:53:12.414057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d2c82a8-6f04-4689-a52c-b3c8c346cf3a', '7e3dc30a-f0f2-42f7-a983-481d61c5bb64', 'd', 'El aumento de la velocidad del viento al disminuir la presión hidrostática.', true, '2025-09-13 13:53:12.414189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65ddf244-cd82-4275-9eef-1ff1e1df2395', '8dfd0804-14ed-476b-a263-f11d23c6c965', 'b', 'Sólo las embarcaciones de recreo o deportivas a motor, incluidas las motos náuticas, con una eslora superior a cinco metros.', false, '2025-09-13 13:53:12.414608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec06df73-c323-4c8a-82d5-c2704309d93a', '8dfd0804-14ed-476b-a263-f11d23c6c965', 'c', 'Sólo las embarcaciones de recreo o deportivas a motor, incluidas las motos náuticas, cualquiera que sea su eslora.', false, '2025-09-13 13:53:12.414738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7e7f272-dfd1-4925-a5af-c5d986099f2c', '8dfd0804-14ed-476b-a263-f11d23c6c965', 'd', 'Todos los objetos flotantes destinados a la navegación de recreo y deportiva propulsados a motor, incluidas las motos náuticas, piraguas, kayaks, canoas sin motor y otros artefactos flotantes sin propulsión mecánica, con una eslora superior a cinco metros.', false, '2025-09-13 13:53:12.414878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a889af70-6af2-47cf-9f58-98bfbec82435', '76f58918-a3df-49ba-840e-359f3ae8188e', 'a', 'Podrán izarse en puertos nacionales y aguas interiores en solitario, pero si se navega por otros espacios marítimos deberá izarse al mismo tiempo el Pabellón nacional.', false, '2025-09-13 13:53:12.415184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('736251f3-e248-46d5-bdce-3f4ad3859d07', '76f58918-a3df-49ba-840e-359f3ae8188e', 'b', 'Nunca serán de dimensiones superiores a un tercio del área del Pabellón nacional.', true, '2025-09-13 13:53:12.415314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf5e9b0b-3ad5-44b1-8444-8d845dfd5f56', '76f58918-a3df-49ba-840e-359f3ae8188e', 'c', 'Podrán permanecer izadas, aunque no lo esté el Pabellón nacional.', false, '2025-09-13 13:53:12.415459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('544ea730-46a9-42f9-87de-cbea4f3be712', '76f58918-a3df-49ba-840e-359f3ae8188e', 'd', 'Es obligatorio izarlas a las entradas y salidas de puertos y, en éstos, de sol a sol, en los días festivos y cuando así lo disponga la autoridad competente.', false, '2025-09-13 13:53:12.415587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99ed6094-6b10-4b67-91d8-00eabd73781a', '11ca0bf0-3603-4cbb-96e9-a56204c16eb7', 'a', 'A elegir, pero sin que pueda prestarse a confusión con las marcas laterales, siendo preferibles las formas de castillete o espeque.', false, '2025-09-13 13:53:12.415876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03d259d4-322e-45af-bd1a-13cb09b6e984', '11ca0bf0-3603-4cbb-96e9-a56204c16eb7', 'b', 'Siempre una figura rectangular o triangular.', false, '2025-09-13 13:53:12.416023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7b63dba-630b-4fd5-b54c-31f23382dc53', '11ca0bf0-3603-4cbb-96e9-a56204c16eb7', 'c', 'Cualquiera, pero, por su color, ha de constituir una significativa marca diurna.', false, '2025-09-13 13:53:12.416165+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd5258a9-1444-4567-bf73-42394c05e5e0', '11ca0bf0-3603-4cbb-96e9-a56204c16eb7', 'd', 'Esférica, de castillete o espeque, con una marca de tope esférica.', true, '2025-09-13 13:53:12.416316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6172a85b-2560-4aff-9dbc-a8db881d6614', '3b188c69-72f6-48c2-b9e3-a1373cf47d62', 'a', 'Únicamente las Marcas laterales de babor.', false, '2025-09-13 13:53:12.416674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('640d79a6-9134-4cbd-b789-3682d1c633c2', '3b188c69-72f6-48c2-b9e3-a1373cf47d62', 'b', 'Las Marcas laterales de babor y las Marcas laterales modificadas que indican en una bifurcación que el canal principal está a estribor.', true, '2025-09-13 13:53:12.416821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('693ce145-2938-4abe-9d65-da6e5346b5eb', '3b188c69-72f6-48c2-b9e3-a1373cf47d62', 'c', 'Las Marcas laterales de estribor y las Marcas laterales modificadas que indican en una bifurcación que el canal principal está a babor.', false, '2025-09-13 13:53:12.416961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b5a0b46-6f24-4aaf-a8d7-f913f68958f0', '3b188c69-72f6-48c2-b9e3-a1373cf47d62', 'd', 'Únicamente las Marcas laterales de estribor.', false, '2025-09-13 13:53:12.417097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04e58eab-52b4-4f5b-8348-ea0d9d02736d', 'c39a3b58-cd1c-47e0-b092-6f3790916e30', 'a', 'Indicar dónde pueden encontrarse las aguas más profundas en esa zona.', false, '2025-09-13 13:53:12.417389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbdb6ca5-29f3-4fa7-9884-ad008268ee2b', 'c39a3b58-cd1c-47e0-b092-6f3790916e30', 'b', 'Indicar la entrada de un canal, la aproximación a un puerto o estuario o un punto de recalada.', true, '2025-09-13 13:53:12.417687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('805d38a9-3cc2-4485-849b-31214184f8ad', 'c39a3b58-cd1c-47e0-b092-6f3790916e30', 'c', 'Indicar el lado seguro por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:12.418192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79367826-c7c8-4144-8b8f-ce6a26cc0cb0', 'c39a3b58-cd1c-47e0-b092-6f3790916e30', 'd', 'Llamar la atención sobre una característica de un canal, tal como una curva, una unión o una', false, '2025-09-13 13:53:12.41836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('847f18a0-92ce-431a-8bdb-7c0cebfe83b9', 'a44c47a7-0ad1-416c-a5b2-260b2f36ad1c', 'a', 'Indican una zona o una configuración particular cuya naturaleza exacta está indicada en la carta u otro documento náutico.', true, '2025-09-13 13:53:12.41866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05cd0286-d905-42ee-998a-2b660937e6bf', 'a44c47a7-0ad1-416c-a5b2-260b2f36ad1c', 'b', 'Son de color amarillo y pueden llevar una marca de tope en forma de X, y si tienen luz es blanca.', false, '2025-09-13 13:53:12.418813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ef5bb5b-e095-43fb-b59d-12a122f67ab7', 'a44c47a7-0ad1-416c-a5b2-260b2f36ad1c', 'c', 'Tienen luces blancas con ritmos distintos a los empleados en las luces amarillas de las marcas cardinales para evitar confusiones.', false, '2025-09-13 13:53:12.418956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da431507-d938-4485-9d24-d9c151cb5067', 'a44c47a7-0ad1-416c-a5b2-260b2f36ad1c', 'd', 'Son boyas que, colocadas a babor de un canal, habrán de ser cónicas.', false, '2025-09-13 13:53:12.419088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f18cbce-9aaf-4314-a119-93e25067ca33', '77a108a6-7f49-49b5-8ad9-0364b37e7f49', 'a', 'Seguir el lado de babor o estribor de la derrota que indica la señal.', false, '2025-09-13 13:53:12.41936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d425e2d4-ce45-4daf-bf17-f64552377529', '77a108a6-7f49-49b5-8ad9-0364b37e7f49', 'b', 'Dar tres pitadas cortas para indicar al resto de embarcaciones que puedan encontrarse en la zona que existe un peligro aislado.', false, '2025-09-13 13:53:12.419492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85f5388f-d949-4c4c-8692-256095ada5ed', '77a108a6-7f49-49b5-8ad9-0364b37e7f49', 'c', 'Consultar la carta y las publicaciones náuticas, al no poder especificarse con estas marcas el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', true, '2025-09-13 13:53:12.41963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('232defd9-a931-4382-91b9-e2da496c56ce', '77a108a6-7f49-49b5-8ad9-0364b37e7f49', 'd', 'Aproximarse a la marca todo lo que pueda con su embarcación para evitar el peligro que indica la Reglamento (RIPA).', false, '2025-09-13 13:53:12.419768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb260298-0edf-4b1b-9e38-805a224d8612', '3b9dd8de-8c16-4ce7-bdf5-5185deb41575', 'a', 'Cuando uno de los dos buques deba mantenerse apartado de la derrota del otro, ninguno mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:12.42008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c4bb536-fa8f-4728-af73-b0602429b8ad', '3b9dd8de-8c16-4ce7-bdf5-5185deb41575', 'b', 'Cuando, por cualquier causa, el buque que haya de mantener su rumbo y velocidad se encuentre tan próximo al otro que no pueda evitarse el abordaje por la sola maniobra del buque que cede el paso, el primero no ejecutará ninguna maniobra que pueda ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.420251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('145a73a0-b339-47db-a69f-feb9d4c3a6e4', '3b9dd8de-8c16-4ce7-bdf5-5185deb41575', 'c', 'Un buque de propulsión mecánica que maniobre en una situación de cruce, para evitar el abordaje con otro buque de propulsión mecánica, no cambiará su rumbo a estribor para maniobrar a un buque que se encuentre por esa misma banda si las circunstancias del caso lo permiten.', false, '2025-09-13 13:53:12.420416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('872fa65e-0b53-4d3c-8402-9c2b8ce99116', '3b9dd8de-8c16-4ce7-bdf5-5185deb41575', 'd', 'La presente Regla no exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:12.420555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66605b75-4f86-48c3-a3ac-1102fea5dd52', 'bd0de369-0793-4906-a7a6-5a9d7d06f63d', 'a', 'La anchura del buque remolcador es superior a 25 metros.', false, '2025-09-13 13:53:12.420875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80d80893-7678-4095-8c96-b3a1a1a0dffe', 'bd0de369-0793-4906-a7a6-5a9d7d06f63d', 'b', 'La anchura del buque remolcado es superior a 25 metros.', false, '2025-09-13 13:53:12.421027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9041965a-f84f-41bd-80f7-15cc7a71eb58', 'bd0de369-0793-4906-a7a6-5a9d7d06f63d', 'c', 'La eslora del buque remolcado es superior a 100 metros.', false, '2025-09-13 13:53:12.421159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a8f2f58-f0c3-45e3-a82f-387e5ffe2e75', 'bd0de369-0793-4906-a7a6-5a9d7d06f63d', 'd', 'La longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:12.42129+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88e4470c-df08-4b7a-9d77-376d7e426405', 'ba3b19c6-3294-425f-8bb6-416c186b35e8', 'a', 'Que es visible sin interrupción en un arco de horizonte de 360 grados.', false, '2025-09-13 13:53:12.421574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbd185c0-3cd4-49db-ba2c-bc95cddc6b8c', 'ba3b19c6-3294-425f-8bb6-416c186b35e8', 'b', 'Con las mismas características que las luces de costado.', false, '2025-09-13 13:53:12.421703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eaa1a50f-1d4d-4608-8af3-9296e39359bc', 'ba3b19c6-3294-425f-8bb6-416c186b35e8', 'c', 'Con las mismas características que la luz de alcance.', true, '2025-09-13 13:53:12.421833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97283ec5-f9f4-447f-b4ad-0155d454f98d', 'ba3b19c6-3294-425f-8bb6-416c186b35e8', 'd', 'Que produce centelleos a intervalos regulares, con una frecuencia de 120 o más centelleos.', false, '2025-09-13 13:53:12.421965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('267e5bb5-3cec-4c68-8e0e-65a7cdf6b5f4', 'a0f6ac46-257c-4051-8dd7-f18dc549730b', 'a', 'Tres luces rojas todo horizonte en línea vertical o un cilindro.', true, '2025-09-13 13:53:12.422938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfdf1191-d6c2-4f2a-b7f3-f75389e6db02', 'a0f6ac46-257c-4051-8dd7-f18dc549730b', 'b', 'Tres luces amarillas todo horizonte en línea vertical o un cilindro.', false, '2025-09-13 13:53:12.423069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('614ad317-07b9-400a-9bdf-bcfe1e9c7622', 'a0f6ac46-257c-4051-8dd7-f18dc549730b', 'c', 'Tres luces rojas todo horizonte en línea vertical o un cono.', false, '2025-09-13 13:53:12.423197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49ba1457-5803-4f8d-94fb-846d93d143af', 'a0f6ac46-257c-4051-8dd7-f18dc549730b', 'd', 'Tres luces amarillas todo horizonte en línea vertical o un cono.', false, '2025-09-13 13:53:12.423325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39b0c43b-f3bf-4811-bc95-8058afbb47b2', '4c415811-a974-4d32-87c2-cbdfe6501735', 'a', 'En aerodeslizadores, cuando operen en la condición sin desplazamiento.', true, '2025-09-13 13:53:12.423606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9eac531-e646-4e10-a76d-30257d3f4e2c', '4c415811-a974-4d32-87c2-cbdfe6501735', 'b', 'En aerodeslizadores, siempre.', false, '2025-09-13 13:53:12.423737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e15b278-250a-4f04-88a2-b1caeb3dd0fc', '4c415811-a974-4d32-87c2-cbdfe6501735', 'c', 'En embarcaciones de propulsión mecánica de menos de 7 metros que puedan navegar a una velocidad máxima de 7 nudos.', false, '2025-09-13 13:53:12.423908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ee5b35b-5126-4a6b-bbe0-d58e5244f28a', '4c415811-a974-4d32-87c2-cbdfe6501735', 'd', 'En naves de vuelo rasante cuando despeguen, aterricen o vuelen cerca de la superficie.', false, '2025-09-13 13:53:12.424088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31c7a039-ded8-4327-8b66-39c0e5250dda', 'd82167f3-958b-469b-a8bc-4ebaf282a3ad', 'a', 'Cinco pitadas cortas y rápidas.', true, '2025-09-13 13:53:12.424545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aab953a-4908-40a6-93fd-e680f9e57217', 'd82167f3-958b-469b-a8bc-4ebaf282a3ad', 'b', 'Tres pitadas cortas y rápidas.', false, '2025-09-13 13:53:12.424843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6be8efbf-5018-4a81-800c-74f0aecf7c6b', 'd82167f3-958b-469b-a8bc-4ebaf282a3ad', 'c', 'Cinco pitadas largas.', false, '2025-09-13 13:53:12.425019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf275771-1b2b-4ab5-8589-b959d4c9e352', 'd82167f3-958b-469b-a8bc-4ebaf282a3ad', 'd', 'Tres pitadas largas.', false, '2025-09-13 13:53:12.425164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb11d1b7-065c-4a27-b795-7981a0039a1f', 'd857c64e-071f-4518-8f52-9013c3211efc', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque de propulsión de mecánica.', false, '2025-09-13 13:53:12.425467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6f5817e-a9da-41c7-9f2f-5a5ff65ca0f7', 'd857c64e-071f-4518-8f52-9013c3211efc', 'b', 'Reducir la velocidad para estudiar la situación, siempre que sea posible, y si se considera que existe riesgo de abordaje, maniobrar preferiblemente de forma clara y con antelación suficiente.', true, '2025-09-13 13:53:12.425602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3edd51b-1a3c-449f-af15-600096f03ec2', 'd857c64e-071f-4518-8f52-9013c3211efc', 'c', 'Realizar pequeños cambios de rumbo y velocidad para avisar a la otra embarcación de su obligación de mantenerse apartado de la derrota de nuestra embarcación por ser buque de vela.', false, '2025-09-13 13:53:12.425738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1d83f4c-dee3-4bd1-a450-5d85e1bb8176', 'd857c64e-071f-4518-8f52-9013c3211efc', 'd', 'Dado que esta situación exige la obligación de maniobrar por ser embarcación de vela, cambiar de rumbo ligeramente para desviar nuestro rumbo lo menos posible y evitar el abordaje al mismo', false, '2025-09-13 13:53:12.425883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73517099-1e8b-4d1d-a8fc-eeb9a84afed1', 'da3f5e5f-c756-4c58-b49c-962bf9ed5229', 'a', 'No es posible usar el aparato de señales de niebla para esta finalidad.', false, '2025-09-13 13:53:12.426181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fa0dad3-8e35-4cf9-9657-3889607f5a10', 'da3f5e5f-c756-4c58-b49c-962bf9ed5229', 'b', 'La configuración del sonido se especifica en función de la tipología del peligro.', false, '2025-09-13 13:53:12.426319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38642143-d3d2-4fc4-a114-8a93cab7e519', 'da3f5e5f-c756-4c58-b49c-962bf9ed5229', 'c', 'Con un sonido corto, ajustando el número de repeticiones a las circunstancias.', false, '2025-09-13 13:53:12.426454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d1938cc-ace5-49cd-bff2-4ca5f18a53ed', 'da3f5e5f-c756-4c58-b49c-962bf9ed5229', 'd', 'Con un sonido continuo.', true, '2025-09-13 13:53:12.42659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab3fda62-86bf-4943-ad05-4f47145c72a7', '628724fe-127e-4a3d-9de3-a5fc93f5e119', 'a', 'Con redes, líneas, aparejos de arrastre u otros artes de pesca que restrinjan su maniobrabilidad; esta expresión no incluye a los buques que pesquen con curricán u otro arte de pesca que no restrinja su maniobrabilidad.', true, '2025-09-13 13:53:12.426883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79569620-6f34-4bd5-93b4-022c5fd37810', '628724fe-127e-4a3d-9de3-a5fc93f5e119', 'b', 'Siempre que las redes, líneas, aparejos de arrastre u otros artes de pesca que utilice no restrinjan su maniobrabilidad.', false, '2025-09-13 13:53:12.427047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('908c90d3-4e72-4283-bb6f-e71dcae9f552', '628724fe-127e-4a3d-9de3-a5fc93f5e119', 'c', 'Con redes, líneas, aparejos de arrastre u otros artes de pesca que restrinjan su maniobrabilidad; incluyendo los buques que pesquen con curricán.', false, '2025-09-13 13:53:12.427187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1ccd010-67c1-46c1-a88f-d0da9ef054c7', '628724fe-127e-4a3d-9de3-a5fc93f5e119', 'd', 'Con redes de arrastre o de cerco que restrinjan su maniobrabilidad, otorgando al buque la consideración de buque sin gobierno. Maniobra y navegación.', false, '2025-09-13 13:53:12.427324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f8b0565-821f-4f0c-b964-31d1ac0b9db0', '48e54d2e-5ad6-449a-9f00-f62f154d84f9', 'a', 'Tener el suficiente resguardo de seguridad entre la embarcación y la costa u otros escollos cuando se navega con viento, oleaje y/o corriente que tienden a echar la embarcación sobre el peligro.', true, '2025-09-13 13:53:12.427618+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5379d5ed-328e-4a9f-9c0c-8fc913cafc3c', '48e54d2e-5ad6-449a-9f00-f62f154d84f9', 'b', 'Dar la vuelta o hacer girar una embarcación en el menor espacio posible.', false, '2025-09-13 13:53:12.427757+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f321fa0-0e39-499d-b74f-8324088da517', '48e54d2e-5ad6-449a-9f00-f62f154d84f9', 'c', 'Navegar a barlovento y por lo tanto al socaire de sotavento.', false, '2025-09-13 13:53:12.427899+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d231841-c7ae-4ac8-a8bd-8408f2c48eea', '48e54d2e-5ad6-449a-9f00-f62f154d84f9', 'd', 'No contar con el suficiente resguardo de seguridad entre la embarcación y la costa u otros escollos cuando se navega a sotavento de otra embarcación.', false, '2025-09-13 13:53:12.42815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a54118fe-4743-4f5e-a079-0277d84bde53', '0056dd6f-967e-4334-982d-17fa4af1c57a', 'a', 'Cobrar del largo de proa y del esprín de popa, lascando a su vez y dentro de lo posible, el largo de popa y el esprín de proa.', true, '2025-09-13 13:53:12.428472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8799319e-591a-449e-b3a0-62e21fe55565', '0056dd6f-967e-4334-982d-17fa4af1c57a', 'b', 'Cobrar del largo de popa.', false, '2025-09-13 13:53:12.428615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76837000-7ebc-41e6-ab73-8e196dda9639', '0056dd6f-967e-4334-982d-17fa4af1c57a', 'c', 'Largar el través de proa a la vez que se lasca del esprín de proa.', false, '2025-09-13 13:53:12.428752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a2d6af9-4353-4ab0-ac86-4e08b156df95', 'b062f4a6-0faa-4d09-ad61-6a38b38e8d37', 'a', 'Inclinar la cabeza hacia atrás y taponar las fosas nasales con una gasa estéril.', false, '2025-09-13 13:53:12.429202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c53e4825-ca4c-4646-9371-90b98414ac39', 'b062f4a6-0faa-4d09-ad61-6a38b38e8d37', 'b', 'Aplicar un paño caliente sobre el tabique nasal.', false, '2025-09-13 13:53:12.429339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3de062d2-fb00-42f2-b14d-dfc563580a91', 'b062f4a6-0faa-4d09-ad61-6a38b38e8d37', 'd', 'Introducir algodón empapado con agua oxigenada en las fosas nasales.', false, '2025-09-13 13:53:12.42963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01dd0fee-3cd3-44dc-b9c0-8d86dfa222b1', '18e9bed3-5b38-4835-a3e3-c4c9dcbd56a3', 'a', 'Hacer una llamada de socorro y activar la radiobaliza manualmente.', false, '2025-09-13 13:53:12.429924+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8060c121-baf9-449f-9d42-115c319fec6c', '18e9bed3-5b38-4835-a3e3-c4c9dcbd56a3', 'b', 'Ponerse ropa de abrigo y chaleco salvavidas.', false, '2025-09-13 13:53:12.430077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd4db7c9-6cc4-47b4-a154-a6ed675aa33a', '18e9bed3-5b38-4835-a3e3-c4c9dcbd56a3', 'c', 'Si dispone de balsa salvavidas, amarrar a bordo la driza de la balsa antes de lanzarla al agua.', false, '2025-09-13 13:53:12.430213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('323cf4a4-614c-4db8-9cf6-38e270eb1c96', '18e9bed3-5b38-4835-a3e3-c4c9dcbd56a3', 'd', 'Si no dispone de balsa salvavidas, saltar al agua, de pie, con las piernas y rodillas juntas, y mantenerse en continuo movimiento para evitar la hipotermia.', true, '2025-09-13 13:53:12.430347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0deee1b8-87b4-4430-9a11-0c738b65eef7', '770fcbde-353e-4225-bab7-26b035b2a34c', 'a', 'El tipo de fondo, ya que la maniobra depende de si se trata de un fondo duro tipo rocoso o de un fondo blando tipo arena.', false, '2025-09-13 13:53:12.430633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e3febce-7e9f-4eb4-9d66-34d5f8adfc97', '770fcbde-353e-4225-bab7-26b035b2a34c', 'b', 'Las mareas, ya que para liberar la embarcación suele ser preferible esperar a que haya marea alta.', false, '2025-09-13 13:53:12.43079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('575c85fe-fe46-4adf-bab1-f0ee38bbe27b', '770fcbde-353e-4225-bab7-26b035b2a34c', 'c', 'Los medios de ayuda externa con los que contamos, ya que disponer del apoyo de otro buque o embarcación facilita la maniobra.', false, '2025-09-13 13:53:12.430946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad88472e-73fd-4955-a0aa-b3856be39241', '770fcbde-353e-4225-bab7-26b035b2a34c', 'd', 'La distribución de pesos de la embarcación, ya que estos son inamovibles y nunca es posible redistribuirlos para variar las condiciones de asiento o escora. Meteorología', true, '2025-09-13 13:53:12.431122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1769e48-983e-4640-82c5-c61a8dd0a78e', '6080edf8-e4d6-4e97-9dc6-6946757620c6', 'a', 'El generado por el avance de la embarcación.', false, '2025-09-13 13:53:12.431431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ff518ad-2bc3-485f-b077-85638144de00', '6080edf8-e4d6-4e97-9dc6-6946757620c6', 'b', 'El que percibimos navegando en la embarcación.', false, '2025-09-13 13:53:12.43157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ce9c56c-7de8-42c9-b243-0bd74b01e6a1', '6080edf8-e4d6-4e97-9dc6-6946757620c6', 'c', 'El que existe en un momento dado, cuando la embarcación está parada.', true, '2025-09-13 13:53:12.431703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a817092-1b23-46cc-a46c-a2710f0f074f', '6080edf8-e4d6-4e97-9dc6-6946757620c6', 'd', 'El que aparece en la escala Beaufort de nuestra embarcación.', false, '2025-09-13 13:53:12.431837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3071855-a1b6-42cd-880f-ce223c2fd5cc', 'ca500463-35fd-4373-a19a-39929062b0c4', 'a', 'La presión atmosférica.', true, '2025-09-13 13:53:12.432174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fb11a3d-14b5-4c65-9736-750b29f397b3', 'ca500463-35fd-4373-a19a-39929062b0c4', 'b', 'La velocidad de la embarcación.', false, '2025-09-13 13:53:12.432324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63d02ee3-2185-4c16-a169-20e649af443b', 'ca500463-35fd-4373-a19a-39929062b0c4', 'c', 'La velocidad del viento.', false, '2025-09-13 13:53:12.432458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('125b5282-7e7d-4f37-b2e0-c7da40cbe669', 'ca500463-35fd-4373-a19a-39929062b0c4', 'd', 'La dirección del viento.', false, '2025-09-13 13:53:12.43259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b16ee961-86b5-4c64-86e6-63750ebc8c05', '64c8b8b5-f0a3-4ac2-a450-d6163d014cd6', 'a', 'En el sentido contrario a las agujas del reloj en las capas bajas, convergiendo hacia el núcleo de la borrasca y ascendiendo en altura.', true, '2025-09-13 13:53:12.432948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efe480d2-ce91-4d29-bb73-89afad9fd188', '64c8b8b5-f0a3-4ac2-a450-d6163d014cd6', 'b', 'En el sentido de las agujas del reloj en las capas bajas, convergiendo hacia el núcleo de la borrasca y ascendiendo en altura.', false, '2025-09-13 13:53:12.43309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('855f1026-bf70-46e3-a311-fc07e32989fe', '64c8b8b5-f0a3-4ac2-a450-d6163d014cd6', 'c', 'En el sentido contrario a las agujas del reloj en las capas bajas, divergiendo del núcleo de la borrasca y ascendiendo en altura.', false, '2025-09-13 13:53:12.433227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdc720e2-409e-40c7-9ea0-cc79620639e9', '64c8b8b5-f0a3-4ac2-a450-d6163d014cd6', 'd', 'En el sentido contrario a las agujas del reloj en las capas altas, convergiendo hacia el núcleo de la borrasca y descendiendo en altura.', false, '2025-09-13 13:53:12.433363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db9fdd8f-1562-448a-b413-e010801c0604', 'c665b7e7-4ce3-4630-a2e4-a3aafcad9585', 'a', 'El número de horas que el viento sopla en la misma dirección.', false, '2025-09-13 13:53:12.433647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09a4a762-9789-462e-bacf-1d23110dfd52', 'c665b7e7-4ce3-4630-a2e4-a3aafcad9585', 'b', 'La velocidad con la que el viento cambia de dirección.', false, '2025-09-13 13:53:12.433784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b562ca15-a9b8-4aec-9369-77d1c42997b6', 'c665b7e7-4ce3-4630-a2e4-a3aafcad9585', 'c', 'La velocidad con la que sopla el viento.', false, '2025-09-13 13:53:12.433919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1697f675-635a-406b-884e-0b25616af296', 'c665b7e7-4ce3-4630-a2e4-a3aafcad9585', 'd', 'La extensión o alcance que tiene el viento sobre la mar cuando sopla de dirección y fuerza Teoría de la navegación.', true, '2025-09-13 13:53:12.434088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d93e062-edd8-4a97-8815-86a26aaf2ec8', '0984586e-e3bb-42fe-8a21-0b3781e4bd35', 'a', 'La sonda en la carta.', false, '2025-09-13 13:53:12.43447+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('625641c1-6b1d-4d98-8ede-230063d7b800', '0984586e-e3bb-42fe-8a21-0b3781e4bd35', 'b', 'La amplitud de marea.', true, '2025-09-13 13:53:12.434617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e48ede8-3d21-437d-92a3-5cc239d296b1', '0984586e-e3bb-42fe-8a21-0b3781e4bd35', 'c', 'La sonda de la marea.', false, '2025-09-13 13:53:12.434755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eea48dbc-316a-43c0-bd00-355a5a830e0c', '0984586e-e3bb-42fe-8a21-0b3781e4bd35', 'd', 'La profundidad observada.', false, '2025-09-13 13:53:12.434902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1ea6802-af63-45fc-88da-c5d7b5dcd1ad', 'e78713e5-fd23-4102-ad16-46734e2f0e7a', 'a', 'Los rumbos se cuentan a partir del Norte de 0º a 360º en el sentido de las agujas del reloj y su valor es siempre positivo.', false, '2025-09-13 13:53:12.435225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b05c0c4d-0596-4d76-b288-df45fbd64a74', 'e78713e5-fd23-4102-ad16-46734e2f0e7a', 'b', 'Los rumbos se cuentan a partir del Norte de 0º a 360º en el sentido de las agujas del reloj y su valor positivo o negativo, según sea Norte o Sur.', false, '2025-09-13 13:53:12.435367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f3d97e9-f013-423f-a611-194c3bdc64f0', 'e78713e5-fd23-4102-ad16-46734e2f0e7a', 'c', 'Se divide la rosa en cuatro cuadrantes tomando como referencia el polo Norte hacia el Este u Oeste y el Sur hacia el Este u Oeste. Su signo será positivo para el primer y tercer cuadrante o negativo para el segundo y cuarto cuadrante.', true, '2025-09-13 13:53:12.435503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65dbdd8c-111e-4f42-a9ed-2ae968d7108c', 'e78713e5-fd23-4102-ad16-46734e2f0e7a', 'd', 'Se divide la rosa en cuatro cuadrantes tomando como referencia el polo Norte hacia el Este u Oeste y el Sur hacia el Este u Oeste. Su signo será negativo para el primer y tercer cuadrante o positivo para el segundo y cuarto cuadrante.', false, '2025-09-13 13:53:12.43564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7c78e6a-9141-42b0-bd50-e99d180544ac', '6b18fde5-80ce-4692-966b-68cb7e22f702', 'a', 'Con el compás, tomando la distancia y trasladando esta en la escala de longitudes.', false, '2025-09-13 13:53:12.435933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32092f05-bb49-446a-a4f5-f138881ba90a', '6b18fde5-80ce-4692-966b-68cb7e22f702', 'b', 'Con el compás, calculando la distancia en centímetros y multiplicando esta por 1,852 para convertir a millas.', false, '2025-09-13 13:53:12.436082+00');
