INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75657a35-a19a-4e13-b029-9c9067d9354c', 'fc70cbcc-7d0b-48ec-94a9-e376476922e7', 'b', 'Esté en el fondo lista para su recuperación.', false, '2025-09-13 13:53:12.441708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9dbe0a1a-e6cc-4209-92fe-a4f583e671c0', 'fc70cbcc-7d0b-48ec-94a9-e376476922e7', 'c', 'Esté sumergida en la línea vertical que va hasta el fondo del mar.', false, '2025-09-13 13:53:12.441845+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1098e257-3cec-45a3-a633-4f3c999b59de', 'fc70cbcc-7d0b-48ec-94a9-e376476922e7', 'd', 'Se libere por no haberse podido recuperar.', false, '2025-09-13 13:53:12.44198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e82f1506-7b3a-4e34-b5fb-0e5efc64d172', '95c29632-1c85-4457-9bcd-222499d5b4c7', 'a', 'La distancia vertical medida sobre el costado de la embarcación desde la línea de flotación, en su condición de máxima carga, hasta la cubierta estanca más alta.', true, '2025-09-13 13:53:12.442254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da5c2d32-9fc8-4535-bdbc-f099584fd5b9', '95c29632-1c85-4457-9bcd-222499d5b4c7', 'b', 'La altura de la obra viva.', false, '2025-09-13 13:53:12.442393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2e41a28-065e-4969-80be-78fa3a00f724', '95c29632-1c85-4457-9bcd-222499d5b4c7', 'c', 'La distancia vertical, medida en la mitad de la eslora desde la cara superior de la línea de cubierta hasta el canto superior de la quilla.', false, '2025-09-13 13:53:12.442523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b5bef21-ae50-4ba5-86b7-9aded675920d', '95c29632-1c85-4457-9bcd-222499d5b4c7', 'd', 'La distancia vertical medida entre el canto inferior de la quilla y la línea de flotación.', false, '2025-09-13 13:53:12.442653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36072bca-9566-48aa-b46c-a30906aaf1f1', '9b9a1905-f26c-41e5-94eb-84fbd0f426b1', 'a', 'Barlovento es la parte hacia donde se dirige el viento.', false, '2025-09-13 13:53:12.442925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('282aadb1-a7d2-4a40-a173-53bac7f8825e', '9b9a1905-f26c-41e5-94eb-84fbd0f426b1', 'b', 'Sotavento es la parte de donde viene el viento.', false, '2025-09-13 13:53:12.443054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f2dc484-8d3a-4a06-ae24-ec66d8ca0d74', '9b9a1905-f26c-41e5-94eb-84fbd0f426b1', 'd', 'Adrizar es la acción de inclinar un barco en sentido babor-estribor o en sentido estribor-babor desde su posición normal de equilibrio, hacia los costados. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:12.443313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5298ceff-6280-4bf1-8547-1affe8cc39b6', '3d985077-4a70-41ca-a0cc-7924022a38f6', 'a', 'Ballestrinque.', false, '2025-09-13 13:53:12.443582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47553d4d-90b8-4755-b7d8-c08b27def117', '3d985077-4a70-41ca-a0cc-7924022a38f6', 'b', 'Vuelta de rezón.', false, '2025-09-13 13:53:12.443714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a1d611e-753b-4652-8942-4d6a007de4ca', '3d985077-4a70-41ca-a0cc-7924022a38f6', 'c', 'As de guía.', true, '2025-09-13 13:53:12.443864+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4272fe9-5d4d-470b-922d-7edc25b72002', '3d985077-4a70-41ca-a0cc-7924022a38f6', 'd', 'Nudo llano.', false, '2025-09-13 13:53:12.443997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa0fbdcb-dd04-4e45-9372-9f71ff1ad352', '5744338a-0217-4d81-973a-2d92eb4c5938', 'a', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a una boya para señalar la ubicación del ancla.', false, '2025-09-13 13:53:12.444266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('361d5e95-24e7-48aa-97f9-55b7a0adbf88', '5744338a-0217-4d81-973a-2d92eb4c5938', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la naturaleza del fondo y de la sonda.', false, '2025-09-13 13:53:12.444396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2e4b6b6-a1f2-423b-8b98-171fe973e542', '5744338a-0217-4d81-973a-2d92eb4c5938', 'c', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', true, '2025-09-13 13:53:12.444531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56d467b8-ebf4-430d-a4c5-0958151fb514', '5744338a-0217-4d81-973a-2d92eb4c5938', 'd', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:12.444668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c343d3a7-da34-4541-8704-0309bd5ad42a', '1af497c8-f141-4901-b2f8-66eb4659c0d8', 'a', 'Debe estar perfectamente establecida y sin ningún tipo de interrupción la comunicación del conductor con el mar.', false, '2025-09-13 13:53:12.444937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('402d50f5-bc39-4f42-ad34-8acdf9d6a52a', '1af497c8-f141-4901-b2f8-66eb4659c0d8', 'c', 'El conductor debe evitar ángulos pronunciados.', false, '2025-09-13 13:53:12.445194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4769827c-c2f4-4dfc-bc66-16c071838319', '1af497c8-f141-4901-b2f8-66eb4659c0d8', 'd', 'El pararrayos debe estar en contacto con otras antenas y jarcias para reforzar su poder de parar las descargas eléctricas que produzcan los rayos.', true, '2025-09-13 13:53:12.445323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59a4c6d9-61a9-421f-b121-7bf62dc5dc1a', '1d2c9c47-9a96-42b5-a2cf-a17cb1e2deb1', 'a', 'Llamar por teléfono al 112.', false, '2025-09-13 13:53:12.445589+00');
