INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40018467-e4e2-4b1e-beda-3b9ea0635c06', '34893b71-9e0b-4e57-853d-19174936e25c', 'b', 'Grifos de fondo.', true, '2025-09-13 13:53:12.447127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9e01148-6204-4096-aa02-591e452d1c9a', '34893b71-9e0b-4e57-853d-19174936e25c', 'c', 'Bocina de niebla.', false, '2025-09-13 13:53:12.447258+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61ccf941-0419-40a0-89a4-353a1088dd6a', '34893b71-9e0b-4e57-853d-19174936e25c', 'd', 'Líneas de vida.', false, '2025-09-13 13:53:12.447388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3911afa-22ba-47b4-96d0-eb950d5707a8', 'bb2a9108-d9fa-445e-8e42-86e4b33ade08', 'a', 'Siempre, ya que se encuentran navegando por espacios marítimos españoles.', false, '2025-09-13 13:53:12.44766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5aeecb5e-be30-490b-b353-393aa03a1700', 'bb2a9108-d9fa-445e-8e42-86e4b33ade08', 'b', 'Cuando el naviero o propietario lo crea aconsejable.', false, '2025-09-13 13:53:12.447798+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ede86f87-dc10-44b1-a39a-431758c5feb3', 'bb2a9108-d9fa-445e-8e42-86e4b33ade08', 'c', 'Siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:12.44794+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae4bdd77-fa06-4ef5-86fe-6af33e4426be', 'bb2a9108-d9fa-445e-8e42-86e4b33ade08', 'd', 'Sólo cuando tengan una embarcación de recreo superior a 12 metros de eslora.', false, '2025-09-13 13:53:12.4481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0468972b-9ae3-4044-a531-3bc2f4f9f1d5', 'aced5072-78ff-4da0-add8-76753835c1db', 'a', 'Tienen, en todo caso, la obligación de abanderamiento y matriculación, así como de despacho, si la propia embarcación y su equipo propulsor ostentan el marcado CE.', false, '2025-09-13 13:53:12.448411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed9422d8-073d-4c21-87be-b4fd00acfc3c', 'aced5072-78ff-4da0-add8-76753835c1db', 'b', 'En ningún caso necesitan obtener antes de su entrada en servicio un certificado de inscripción, al tener marcado CE.', false, '2025-09-13 13:53:12.448546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('774796b6-54b6-429a-8943-68506c128205', 'aced5072-78ff-4da0-add8-76753835c1db', 'c', 'Sólo podrán navegar en el mar territorial español y, en cualquier caso, no podrán sobrepasar las zonas de navegación a las que estén limitadas de acuerdo con su categoría de diseño.', true, '2025-09-13 13:53:12.448679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fde2089-c5d1-4248-944b-e7663914d283', '50a602af-96a2-4e18-8fd3-39c2d113cbd5', 'b', 'La sensibilidad y la estabilidad son características importantes de una buena aguja náutica.', false, '2025-09-13 13:53:12.468224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47b38890-bfa8-4e0a-9259-5022e4e1d06d', '1af497c8-f141-4901-b2f8-66eb4659c0d8', 'b', 'La punta o puntas del pararrayos deben ser afiladas y con suficiente dureza para no ser fundidas por un rayo.', false, '2025-09-13 13:53:12.445066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2310819f-7e80-4efd-85e8-27df06c7b1e0', 'aced5072-78ff-4da0-add8-76753835c1db', 'd', 'Deberán llevar pintado o fijado de forma permanente en ambas amuras sólo el nombre, que se colocará a la máxima altura posible de la línea de flotación.', false, '2025-09-13 13:53:12.448809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8004d1c1-7adc-4511-a206-f1413e1f59a5', '27810ca5-f6fa-4974-a6b0-759973feaa2b', 'a', 'Están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.449085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a065d3f-6845-48f0-91ce-3cc601e07b9f', '27810ca5-f6fa-4974-a6b0-759973feaa2b', 'b', 'Pueden prestarse a confusión con la de otras marcas de ayudas a la navegación, por eso la forma de las boyas de las marcas especiales será siempre rectangular.', false, '2025-09-13 13:53:12.449215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('baf991bc-3140-4b34-86cc-2ffaa63a4587', '27810ca5-f6fa-4974-a6b0-759973feaa2b', 'c', 'Serán de color amarillo y las boyas tendrán la forma de castillete o espeque.', false, '2025-09-13 13:53:12.449343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cde45a9-c631-4202-a672-0a52b0c30736', '27810ca5-f6fa-4974-a6b0-759973feaa2b', 'd', 'No tienen una forma preestablecida, pudiendo elegirse cualquiera que no se preste a confusión con la de otras marcas de ayudas a la navegación.', true, '2025-09-13 13:53:12.449471+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7a6a0d7-bf04-4519-a9b3-65859703ef38', 'eedeaaee-74d5-45eb-9f02-ce991f3b9282', 'a', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:12.449738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1612394-c174-4c1f-9eef-b1ff0f0a5a25', 'eedeaaee-74d5-45eb-9f02-ce991f3b9282', 'b', 'Franjas verticales rojas y negras.', false, '2025-09-13 13:53:12.449879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e713d1c3-d980-471b-a83b-e919154dffef', 'eedeaaee-74d5-45eb-9f02-ce991f3b9282', 'c', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:12.450009+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45a4bf04-4219-4926-b6fd-13fb50e53531', 'eedeaaee-74d5-45eb-9f02-ce991f3b9282', 'd', 'Franjas horizontales rojas y negras.', false, '2025-09-13 13:53:12.450135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a54d498-2768-4b4c-ae15-db0e3f087f41', '78c6df75-5c4c-4479-b75e-8a601e38c01b', 'a', 'Los peligros aislados de dimensiones limitadas enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:12.4504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddfbb6d4-15c9-412f-af37-840a0abb2893', '78c6df75-5c4c-4479-b75e-8a601e38c01b', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse, a fin de evitar un peligro concreto.', false, '2025-09-13 13:53:12.450528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('599e0ca9-99cc-42e9-a997-d8d61e4a158f', '78c6df75-5c4c-4479-b75e-8a601e38c01b', 'c', 'Que las aguas más profundas en esa zona se encuentran rodeadas de algún tipo de peligro no representado aún en la carta náutica.', false, '2025-09-13 13:53:12.450662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c428e753-f173-45d8-904b-16268d0d9079', '78c6df75-5c4c-4479-b75e-8a601e38c01b', 'd', 'Algún tipo de peligro concreto y la marca será distinta según el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', false, '2025-09-13 13:53:12.450822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('020f95fd-2c65-4837-bc71-33ca5f758442', '4f762df8-035e-49d4-91fb-0cbfcc2e603e', 'a', 'La existencia de un peligro en el canal principal.', false, '2025-09-13 13:53:12.451166+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcd1579e-fdc0-4f4c-9404-edaae4d67a85', '4f762df8-035e-49d4-91fb-0cbfcc2e603e', 'b', 'El punto de bifurcación de un canal.', true, '2025-09-13 13:53:12.451322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e34e5c41-c790-419b-aaa2-d4ca886a449e', '4f762df8-035e-49d4-91fb-0cbfcc2e603e', 'c', 'El final de un canal balizado.', false, '2025-09-13 13:53:12.451476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be82c0ea-7b05-49f4-9c34-e03d2427b6b9', '4f762df8-035e-49d4-91fb-0cbfcc2e603e', 'd', 'El comienzo de un canal balizado.', false, '2025-09-13 13:53:12.451619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04971afc-6644-493d-b3db-87ee9827acd4', '78449c79-eb10-47df-bd5b-43f656ebde5b', 'a', 'Oeste.', false, '2025-09-13 13:53:12.451957+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce9958f7-aee8-4ee7-858e-44848cb11e17', '78449c79-eb10-47df-bd5b-43f656ebde5b', 'b', 'Norte.', false, '2025-09-13 13:53:12.452104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49faae6a-ac3b-4670-8ca2-198ce64c1311', '78449c79-eb10-47df-bd5b-43f656ebde5b', 'c', 'Sur.', false, '2025-09-13 13:53:12.452244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27210a49-4c26-4571-9904-2741a39a7af9', '546ea097-94d7-462a-a7e0-5d4cddb872e2', 'a', 'Luz de tope.', true, '2025-09-13 13:53:12.452668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3d82681-b137-49e5-87cd-33a856ba449e', '546ea097-94d7-462a-a7e0-5d4cddb872e2', 'b', 'Luz de alcance.', false, '2025-09-13 13:53:12.452805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b4290a5-e307-4303-9b83-27dff1ffef8d', '546ea097-94d7-462a-a7e0-5d4cddb872e2', 'c', 'Luz de remolque.', false, '2025-09-13 13:53:12.452941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2fb0278-ac2a-4118-84b1-d483e243b374', '546ea097-94d7-462a-a7e0-5d4cddb872e2', 'd', 'Luz de fondeo.', false, '2025-09-13 13:53:12.453074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b27dade-9d1c-492b-b4ca-f5f44981c4a5', 'b1eaa87a-c7fa-4adc-914b-9ea88ab6138b', 'b', 'Una luz de tope a proa, luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.453488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41c69bd7-d2cf-47fa-a37f-eb5f2964ccff', 'b1eaa87a-c7fa-4adc-914b-9ea88ab6138b', 'c', 'Una luz blanca todo horizonte y luces de costado.', false, '2025-09-13 13:53:12.453621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1c5c567-ad6e-47fb-a80a-ae317ec15db3', 'b1eaa87a-c7fa-4adc-914b-9ea88ab6138b', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirá también luces de costado.', false, '2025-09-13 13:53:12.453751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9176f39d-e8ee-4217-ba5b-1aa295aaccff', '2cea33f3-d243-49b8-a675-6c4f873d15a0', 'a', 'La escala que esté usando el radar puede imponer restricciones a la hora de detectar objetivos.', true, '2025-09-13 13:53:12.454059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d292c0ce-fc2b-4b21-98c4-2654073fbec6', '2cea33f3-d243-49b8-a675-6c4f873d15a0', 'b', 'El estado de la mar no influye en la detección de objetivos ya que la señal de alta frecuencia que emite el radar es electromagnética.', false, '2025-09-13 13:53:12.454193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2219ab33-3bb3-4717-b050-a1c7299627be', '2cea33f3-d243-49b8-a675-6c4f873d15a0', 'c', 'Sin importar las características del radar, siempre detectará los pequeños objetos flotantes o embarcaciones pequeñas.', false, '2025-09-13 13:53:12.454337+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35cbe103-ffba-483c-8bb4-80ac0fd63fc4', '2cea33f3-d243-49b8-a675-6c4f873d15a0', 'd', 'De noche, la existencia de resplandor producido por las luces de tierra influirá en la detección del radar de otras embarcaciones.', false, '2025-09-13 13:53:12.45449+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b447aea-e6fa-4921-b07c-d9a0a94b1ca2', '12385fb9-aa32-4ae1-a959-5025a722e438', 'a', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:12.454823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa816830-1525-41f4-b61b-60ee387662b0', '12385fb9-aa32-4ae1-a959-5025a722e438', 'b', 'Una pitada larga.', false, '2025-09-13 13:53:12.454959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61630e2a-1579-4a91-91ac-c36f8d5b1e47', '12385fb9-aa32-4ae1-a959-5025a722e438', 'c', 'Dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.455094+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33a52162-0afe-4f40-ad3e-52c7146e65d1', '12385fb9-aa32-4ae1-a959-5025a722e438', 'd', 'Una pitada corta.', false, '2025-09-13 13:53:12.455225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83793f5d-6979-4d80-86ac-7ef2c5e7b698', '96247a4f-4fda-43ec-954c-6ea7d3166863', 'a', 'Los buques de propulsión mecánica, en navegación, se mantendrán apartados de la derrota de un buque sin gobierno.', false, '2025-09-13 13:53:12.455514+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2e7f487-ab31-438e-aea1-e5203ced67ef', '96247a4f-4fda-43ec-954c-6ea7d3166863', 'c', 'En la medida de lo posible, los buques dedicados a la pesca, en navegación, se mantendrán apartados de la derrota de un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:12.455797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4ca599b-b0e5-40f3-b54d-ce19b6e94523', '96247a4f-4fda-43ec-954c-6ea7d3166863', 'd', 'Los buques de vela, en navegación, se mantendrán apartados de la derrota de un buque de propulsión mecánica.', true, '2025-09-13 13:53:12.455949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60412849-4921-46e6-a42e-ab7ca642555f', '7cb8b87f-35b4-47ac-97f9-9d822de5b592', 'a', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:12.456241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f693998-e530-40ff-bbcd-d443a4fcc4d9', '7cb8b87f-35b4-47ac-97f9-9d822de5b592', 'b', 'Las Reglas relativas a las luces deberán cumplirse desde la puesta del sol hasta su salida, y durante ese intervalo no se exhibirá ninguna otra luz, con la excepción de aquellas que no puedan ser confundidas con las luces mencionadas en este Reglamento o que no perjudiquen su visibilidad o carácter distintivo, ni impidan el ejercicio de una vigilancia eficaz.', false, '2025-09-13 13:53:12.456375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcb0c7ce-004a-4813-94b0-be9b06025b6d', '7cb8b87f-35b4-47ac-97f9-9d822de5b592', 'c', 'Las luces preceptuadas por estas Reglas, en caso de llevarse, deberán exhibirse también desde la salida hasta la puesta del sol si hay visibilidad reducida y podrán exhibirse en cualquier otra circunstancia que se considere necesario.', false, '2025-09-13 13:53:12.456508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7029105-5f06-4838-aa6c-4b9ca156b911', '7cb8b87f-35b4-47ac-97f9-9d822de5b592', 'd', 'Las Reglas relativas a las marcas deberán cumplirse de día de manera optativa a juicio del capitán, armador o patrón.', true, '2025-09-13 13:53:12.456647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f6b91dc-da54-4b05-8f48-845250fa087f', '5b84dc85-f694-4ffc-8c61-ce446eaecbe2', 'a', 'Cualquier medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:12.45694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e976ca7-fcc5-4518-b594-a055beb86e5e', '5b84dc85-f694-4ffc-8c61-ce446eaecbe2', 'b', 'Una campana, además del pito.', true, '2025-09-13 13:53:12.457081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83d34e7f-ef13-4a97-8138-c058dee2596e', '5b84dc85-f694-4ffc-8c61-ce446eaecbe2', 'c', 'Sólo una campana.', false, '2025-09-13 13:53:12.457215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7ff5a7a-ae03-479f-878a-73579e5cab1f', '5b84dc85-f694-4ffc-8c61-ce446eaecbe2', 'd', 'Sólo un pito.', false, '2025-09-13 13:53:12.457349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f629721-95b1-498b-abf7-ed3f4a4dd775', 'd752a1f8-7367-4e28-bd13-af10d810e6ac', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.45763+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3030a9f-14e6-4cb4-bb67-bcd15f08eed7', 'd752a1f8-7367-4e28-bd13-af10d810e6ac', 'b', 'Se deberá mantener el rumbo ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:12.457767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10a6b2b4-56f1-4c89-96cd-3c9add27908f', 'd752a1f8-7367-4e28-bd13-af10d810e6ac', 'c', 'Únicamente deberemos maniobrar por ser el buque que alcanza un velero, en cualquier otra situación se mantendría rumbo tal y como recoge la regla.', false, '2025-09-13 13:53:12.457913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3576810-0516-47b9-b9cd-99e2d675fee4', '78449c79-eb10-47df-bd5b-43f656ebde5b', 'd', 'Este.', true, '2025-09-13 13:53:12.452382+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4463b3a4-3a21-450e-95e7-65145c7b5717', 'd752a1f8-7367-4e28-bd13-af10d810e6ac', 'd', 'Los datos aportados en el enunciado no son suficientes para determinar por qué banda recibe el viento el velero, siendo esto fundamental para decidir si debemos maniobrar o mantener rumbo.', false, '2025-09-13 13:53:12.458046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18dfa833-cec7-4d83-9e59-a627944f7d57', '7f6ba9fb-1e6f-420f-b5a4-bc5ed4402a11', 'a', 'En cualquier embarcación de vela que no supere los 7 metros de eslora y embarcaciones de remo.', true, '2025-09-13 13:53:12.458336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c00cc5b-91db-41dc-bdab-00d5c7f78568', '7f6ba9fb-1e6f-420f-b5a4-bc5ed4402a11', 'd', 'Sólo en embarcaciones de remos.', false, '2025-09-13 13:53:12.458784+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cb0e90d-0117-4146-ae14-dfac2f4b9d84', '677ad6df-9ef3-4897-9ede-487f508987a7', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.459093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6a80878-7e4f-4f5f-86fb-eed89b252049', '677ad6df-9ef3-4897-9ede-487f508987a7', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', true, '2025-09-13 13:53:12.459227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e8de96c-77c9-4407-8cac-5091bce45eb1', '677ad6df-9ef3-4897-9ede-487f508987a7', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de estribor.', false, '2025-09-13 13:53:12.459368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('628e67e4-02c7-43c0-be59-6adb115fd104', '677ad6df-9ef3-4897-9ede-487f508987a7', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje. Maniobra y navegación.', false, '2025-09-13 13:53:12.459503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beed24df-c951-4af6-a80e-91000f7efd34', '2ff1e9cf-3112-420a-b3d3-4d45037ed13f', 'a', 'Cazarlo.', false, '2025-09-13 13:53:12.459793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ec62590-352e-4023-95cd-14b7602e9356', '2ff1e9cf-3112-420a-b3d3-4d45037ed13f', 'b', 'Soltarlo un poco.', true, '2025-09-13 13:53:12.459928+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf85a90b-2e1a-4877-bc19-901264023f6a', '2ff1e9cf-3112-420a-b3d3-4d45037ed13f', 'c', 'Tensarlo un poco.', false, '2025-09-13 13:53:12.460066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2da54fb-579c-4231-9938-6e9e99478824', '2ff1e9cf-3112-420a-b3d3-4d45037ed13f', 'd', 'Anudarlo mediante lascas consecutivas.', false, '2025-09-13 13:53:12.4602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd3d0631-1528-455c-9bd7-5f071b14622f', 'bd128865-af63-4630-9632-32ac892a35eb', 'a', 'Proa al viento.', true, '2025-09-13 13:53:12.46048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96fa406e-2de3-4bbf-9cbe-5b8fe4399d81', 'bd128865-af63-4630-9632-32ac892a35eb', 'b', 'Con el viento o corriente por popa y la boya por la proa.', false, '2025-09-13 13:53:12.460617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7618ff16-a941-45f9-aee2-b080bb87640d', 'bd128865-af63-4630-9632-32ac892a35eb', 'c', 'Con el viento o corriente por una amura y la boya por la amura opuesta.', false, '2025-09-13 13:53:12.460751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c21f2678-0ed8-4146-9a2c-efb28e6a1e50', '7c3d8616-5ced-4ef8-ae1f-e0c7a16004aa', 'a', 'Realizar una llamada de socorro, si no puede detener la entrada de agua.', false, '2025-09-13 13:53:12.461172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04d2071e-3389-4c00-80d4-a9778a697531', '7c3d8616-5ced-4ef8-ae1f-e0c7a16004aa', 'b', 'Abandonar inmediatamente la embarcación.', true, '2025-09-13 13:53:12.461305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('348385f4-04bb-4545-93f8-60a437b9c3f7', '7c3d8616-5ced-4ef8-ae1f-e0c7a16004aa', 'c', 'Aumentar la flotabilidad vaciando el depósito de agua dulce al mínimo imprescindible.', false, '2025-09-13 13:53:12.461433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('792f09ca-bf04-4825-b43e-847ca44edc0a', '7c3d8616-5ced-4ef8-ae1f-e0c7a16004aa', 'd', 'Si la vía de agua está originada por el fallo de una válvula o pasa cascos, colocar un espiche.', false, '2025-09-13 13:53:12.461565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be7393df-4865-43e3-8eff-7851731572f1', 'b9a02bb6-d40c-48a5-8f70-6aea7e496e12', 'a', 'En condiciones de escasa visibilidad, emplear la bocina de niebla.', false, '2025-09-13 13:53:12.46186+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1c7617c-2a67-402f-9b7e-19896ab1d706', 'b9a02bb6-d40c-48a5-8f70-6aea7e496e12', 'b', 'Izar un reflector de radar.', false, '2025-09-13 13:53:12.461992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4524ff7-bc8d-48af-8901-d7e2526bb92e', 'b9a02bb6-d40c-48a5-8f70-6aea7e496e12', 'c', 'Si navega a vela, desconfíar de que respetarán su preferencia.', false, '2025-09-13 13:53:12.462122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd5dfc90-4354-4cb0-a18a-28f60fdfb165', 'b9a02bb6-d40c-48a5-8f70-6aea7e496e12', 'd', 'No utilizar en ningún caso el VHF para alertar al buque que navega a rumbo de colisión.', true, '2025-09-13 13:53:12.462253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27a604f8-327a-4af4-84c4-af699e2e1328', '4c7aacc4-d2f1-4e91-9f5b-0f5f08ebbf02', 'a', 'El tipo de agente extintor que se utiliza.', false, '2025-09-13 13:53:12.462524+00');
