INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db269398-94b6-433b-937d-987f3361974d', 'a696ce6e-a754-49c1-a7ca-cd218a35d182', 'a', 'La distancia vertical medida sobre el costado de la embarcación desde la línea de flotación, en su condición de máxima carga, hasta la cubierta estanca más alta.', true, '2025-09-13 13:53:12.498388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f950524-dd15-4a31-95a9-a509c2f34bb7', 'a696ce6e-a754-49c1-a7ca-cd218a35d182', 'b', 'La altura de la obra viva.', false, '2025-09-13 13:53:12.498519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca117a23-073c-4abf-bb8e-8adff129cb97', 'a696ce6e-a754-49c1-a7ca-cd218a35d182', 'c', 'La distancia vertical, medida en la mitad de la eslora desde la cara superior de la línea de cubierta hasta el canto superior de la quilla.', false, '2025-09-13 13:53:12.498657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df5055c6-bde0-41c6-bb5a-524fdf7b6fcc', 'a696ce6e-a754-49c1-a7ca-cd218a35d182', 'd', 'La distancia vertical medida entre el canto inferior de la quilla y la línea de flotación.', false, '2025-09-13 13:53:12.498796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4944617-6b7e-4553-8f15-bef0ff98d96c', '195b97e0-7e9c-40da-baa4-7e7e1453500b', 'a', 'Barlovento es la parte hacia donde se dirige el viento.', false, '2025-09-13 13:53:12.49907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('84cc9610-4507-42ce-9293-50267d345299', '195b97e0-7e9c-40da-baa4-7e7e1453500b', 'b', 'Sotavento es la parte de donde viene el viento.', false, '2025-09-13 13:53:12.499201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71d18fe1-1328-4a36-bede-9dadd501d221', '195b97e0-7e9c-40da-baa4-7e7e1453500b', 'c', 'Los factores principales que producen la escora son la distribución de pesos y la acción del viento', true, '2025-09-13 13:53:12.499334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('728cfb8b-7e2f-47b7-aa58-fdbeff2a2b80', '195b97e0-7e9c-40da-baa4-7e7e1453500b', 'd', 'Adrizar es la acción de inclinar un barco en sentido babor-estribor o en sentido estribor-babor desde su posición normal de equilibrio, hacia los costados.', false, '2025-09-13 13:53:12.499467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c6ddf64-51f7-474b-8780-f3bb29186c04', 'cd8a2aa1-4b50-40fa-ad7a-8205c95ca99b', 'a', 'Cuelgue y esté lista para fondear.', true, '2025-09-13 13:53:12.499735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0370e04-28db-4799-bc71-224e3db53b94', 'cd8a2aa1-4b50-40fa-ad7a-8205c95ca99b', 'b', 'Esté en el fondo lista para su recuperación.', false, '2025-09-13 13:53:12.499874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1025bf41-519f-4b7c-b092-6413bc5c6a54', 'cd8a2aa1-4b50-40fa-ad7a-8205c95ca99b', 'c', 'Esté sumergida en la línea vertical que va hasta el fondo del mar.', false, '2025-09-13 13:53:12.500004+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32e03fcc-f061-4890-b96c-99def5b6176e', 'cd8a2aa1-4b50-40fa-ad7a-8205c95ca99b', 'd', 'Se libere por no haberse podido recuperar. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:12.500133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75823a50-aacc-44cd-bfc3-6c30ceb0b413', '89867ef1-65ee-4666-af0c-b55c4a83f30f', 'a', 'Ballestrinque.', false, '2025-09-13 13:53:12.500405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6651dcf-cd9c-478f-aca2-67ad0876e526', '89867ef1-65ee-4666-af0c-b55c4a83f30f', 'b', 'Vuelta de rezón.', false, '2025-09-13 13:53:12.500535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed758756-3a5a-4bf9-8e3f-95fdeafbde01', '89867ef1-65ee-4666-af0c-b55c4a83f30f', 'c', 'As de guía.', true, '2025-09-13 13:53:12.500683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c4a37a8-bfdf-4386-bc04-fa6d8b09e36d', '89867ef1-65ee-4666-af0c-b55c4a83f30f', 'd', 'Nudo llano.', false, '2025-09-13 13:53:12.500816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a987fbcc-ba25-4e2b-88ee-63e6b51a517b', 'a0b744bf-6660-451c-9d25-3afa66bc9851', 'a', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a una boya para señalar la ubicación del ancla.', false, '2025-09-13 13:53:12.501085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81cc4451-2ef9-47b2-9852-c64e1b4e068b', 'a0b744bf-6660-451c-9d25-3afa66bc9851', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la naturaleza del fondo y de la sonda.', false, '2025-09-13 13:53:12.501215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e037ebe0-1fa5-45db-aaaa-e476865a76c5', 'a0b744bf-6660-451c-9d25-3afa66bc9851', 'c', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', true, '2025-09-13 13:53:12.501349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc579420-4840-4faa-859f-fd85ac9fc896', 'a0b744bf-6660-451c-9d25-3afa66bc9851', 'd', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:12.50149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd40c0d1-d251-4016-a90c-639f22749031', 'b9c0dc1e-d64d-4cb5-be05-77b214e34e2c', 'a', 'Arneses.', false, '2025-09-13 13:53:12.501803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20a69fb9-c612-4f16-99b4-208df6eb96d8', 'b9c0dc1e-d64d-4cb5-be05-77b214e34e2c', 'b', 'Grifos de fondo.', true, '2025-09-13 13:53:12.501948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6983434e-6dea-4d2a-98ac-846ddd938ea5', 'b9c0dc1e-d64d-4cb5-be05-77b214e34e2c', 'c', 'Bocina de niebla.', false, '2025-09-13 13:53:12.502088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('031ef237-19b5-47b5-a6be-0e8e154b83a3', 'b9c0dc1e-d64d-4cb5-be05-77b214e34e2c', 'd', 'Líneas de vida.', false, '2025-09-13 13:53:12.502219+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20c1dee2-e950-4c19-bf3e-eb8f21c83434', 'fd6db2e9-9122-42a7-9827-fc361f408b71', 'a', 'Debe estar perfectamente establecida y sin ningún tipo de interrupción la comunicación del conductor con el mar.', false, '2025-09-13 13:53:12.502495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd1df8b5-d740-4954-bfdd-92d739237452', 'fd6db2e9-9122-42a7-9827-fc361f408b71', 'b', 'La punta o puntas del pararrayos deben ser afiladas y con suficiente dureza para no ser fundidas', false, '2025-09-13 13:53:12.50263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c014ebbe-098b-4e10-a2d9-77fa60d316da', 'fd6db2e9-9122-42a7-9827-fc361f408b71', 'c', 'El conductor debe evitar ángulos pronunciados.', false, '2025-09-13 13:53:12.50277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cdc261ad-c27b-4b2d-beb7-586252b21ebc', 'fd6db2e9-9122-42a7-9827-fc361f408b71', 'd', 'El pararrayos debe estar en contacto con otras antenas y jarcias para reforzar su poder de parar las descargas eléctricas que produzcan los rayos.', true, '2025-09-13 13:53:12.502902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('496b22ca-4587-4c4b-9b48-9730b1d1f396', '70ddf9eb-750c-4229-8f49-3f1caba64a6f', 'a', 'El estado de los alimentos que se lleven a bordo.', false, '2025-09-13 13:53:12.503171+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0b28323-daae-4d27-acd4-5c6ae3c2e158', '70ddf9eb-750c-4229-8f49-3f1caba64a6f', 'b', 'El nivel del tanque de almacenamiento de aguas negras, como por ejemplo las procedentes de inodoros y lavabos.', false, '2025-09-13 13:53:12.503311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bee50b83-839b-4496-8b7b-f9e9a5f004b0', '70ddf9eb-750c-4229-8f49-3f1caba64a6f', 'c', 'El nivel del tanque de agua salada.', false, '2025-09-13 13:53:12.503442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e35a4a6-fe2e-423d-9f57-330e4dfb8143', '70ddf9eb-750c-4229-8f49-3f1caba64a6f', 'd', 'La estanqueidad de la embarcación.', true, '2025-09-13 13:53:12.50357+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d681855b-9f9a-48d8-9fcc-e4c58d23f916', 'aad353ef-0da4-4137-a3e3-7ad08022070a', 'a', 'Llamar por teléfono al 112.', false, '2025-09-13 13:53:12.503852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('661aa449-9e0e-423a-b7cd-4578c146da7f', 'aad353ef-0da4-4137-a3e3-7ad08022070a', 'b', 'Llamar por teléfono al 900 202 202.', false, '2025-09-13 13:53:12.503985+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33d8cbf2-baae-4bcf-89f3-ab02020a0248', 'aad353ef-0da4-4137-a3e3-7ad08022070a', 'c', 'Llamar por teléfono al 900 102 102.', true, '2025-09-13 13:53:12.504122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad954195-354e-4709-9537-c5adb4250609', 'aad353ef-0da4-4137-a3e3-7ad08022070a', 'd', 'Emplear la estación de radio de a bordo.', false, '2025-09-13 13:53:12.504273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4aa7ee03-90fb-4a15-bc0b-99bc78d4b293', 'ba8c3785-6f99-471c-b9d9-dd409938d274', 'a', 'Tienen, en todo caso, la obligación de abanderamiento y matriculación, así como de despacho, si la propia embarcación y su equipo propulsor ostentan el marcado CE.', false, '2025-09-13 13:53:12.504546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02fabced-cb45-43b7-97b0-47f61b45e654', 'ba8c3785-6f99-471c-b9d9-dd409938d274', 'b', 'En ningún caso necesitan obtener antes de su entrada en servicio un certificado de inscripción, al tener marcado CE.', false, '2025-09-13 13:53:12.504675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83a82464-fa11-4686-b197-066bd550c984', 'ba8c3785-6f99-471c-b9d9-dd409938d274', 'c', 'Sólo podrán navegar en el mar territorial español y, en cualquier caso, no podrán sobrepasar las zonas de navegación a las que estén limitadas de acuerdo con su categoría de diseño.', true, '2025-09-13 13:53:12.504805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd8dda8c-4530-46d7-a5ea-6b0025748566', 'ba8c3785-6f99-471c-b9d9-dd409938d274', 'd', 'Deberán llevar pintado o fijado de forma permanente en ambas amuras sólo el nombre, que se colocará a la máxima altura posible de la línea de flotación.', false, '2025-09-13 13:53:12.504935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f50a939b-1954-4f13-8980-8407267de52b', 'c1d1a6d0-34f2-4d86-863a-4eb9488ddefb', 'a', 'Siempre, ya que se encuentran navegando por espacios marítimos españoles.', false, '2025-09-13 13:53:12.505206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0055e0a3-20de-41e1-8a5a-0fe86117067c', 'c1d1a6d0-34f2-4d86-863a-4eb9488ddefb', 'b', 'Cuando el naviero o propietario lo crea aconsejable.', false, '2025-09-13 13:53:12.505347+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21916c27-0cdf-4e32-a58a-90239721b98b', 'c1d1a6d0-34f2-4d86-863a-4eb9488ddefb', 'c', 'Siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:12.505492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9721f3c-0388-4c26-bfdb-c1f5e5be6372', 'c1d1a6d0-34f2-4d86-863a-4eb9488ddefb', 'd', 'Sólo cuando tengan una embarcación de recreo superior a 12 metros de eslora.', false, '2025-09-13 13:53:12.505626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6dacd883-df21-4356-bebf-a24670236efb', 'a658172c-e588-4b7e-b867-07bd0a7e5e27', 'a', 'Oeste.', false, '2025-09-13 13:53:12.505918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38b0608c-0091-4d92-925c-401971d4d97a', 'a658172c-e588-4b7e-b867-07bd0a7e5e27', 'b', 'Norte.', false, '2025-09-13 13:53:12.506053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4edde74-e0e2-44bf-8b8b-7b8f78061fbf', 'a658172c-e588-4b7e-b867-07bd0a7e5e27', 'c', 'Sur.', false, '2025-09-13 13:53:12.506185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85469bd7-561e-467f-b5ff-598a1e72d684', 'a658172c-e588-4b7e-b867-07bd0a7e5e27', 'd', 'Este.', true, '2025-09-13 13:53:12.506318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48126b4d-f3b1-4736-bb63-0fc8775ad23f', '64062bd1-b8b5-479b-958b-479d79b82416', 'a', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:12.506603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2abd78c-94e7-482f-bce3-60fdde3e7beb', '64062bd1-b8b5-479b-958b-479d79b82416', 'b', 'Franjas verticales rojas y negras.', false, '2025-09-13 13:53:12.506739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa32f436-12d0-4056-9b57-67598ee542ad', '64062bd1-b8b5-479b-958b-479d79b82416', 'c', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:12.506877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1405ad9-3df5-4146-983e-09df9c453bef', '64062bd1-b8b5-479b-958b-479d79b82416', 'd', 'Franjas horizontales rojas y negras.', false, '2025-09-13 13:53:12.507005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7df5ecd-dc86-49ae-9938-7883e8f8be20', '03ae1f52-24b9-408f-ac68-fd969e423e77', 'a', 'Los peligros aislados de dimensiones limitadas enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:12.507282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1641c9f-610a-4022-b45e-0da38639ea28', '03ae1f52-24b9-408f-ac68-fd969e423e77', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse, a fin de evitar un peligro concreto.', false, '2025-09-13 13:53:12.507416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a83c4f1-b33c-440e-bc40-f3eadd8c5c9e', '03ae1f52-24b9-408f-ac68-fd969e423e77', 'c', 'Que las aguas más profundas en esa zona se encuentran rodeadas de algún tipo de peligro no representado aún en la carta náutica.', false, '2025-09-13 13:53:12.507545+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4983775a-4aa3-4829-afcd-ee5506641331', '03ae1f52-24b9-408f-ac68-fd969e423e77', 'd', 'Algún tipo de peligro concreto y la marca será distinta según el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', false, '2025-09-13 13:53:12.507673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbad73bb-a64b-44e8-beff-4e4d0e8c44a6', 'd61ff762-c962-48c6-99a1-8e78836670a3', 'a', 'Están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.507943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb9b4734-7380-49c8-8b53-d32d9c1d3607', 'd61ff762-c962-48c6-99a1-8e78836670a3', 'b', 'Pueden prestarse a confusión con la de otras marcas de ayudas a la navegación, por eso la forma de las boyas de las marcas especiales será siempre rectangular.', false, '2025-09-13 13:53:12.508073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3db8f8ae-3918-417f-8a2c-cbb24a62f0e9', 'd61ff762-c962-48c6-99a1-8e78836670a3', 'c', 'Serán de color amarillo y las boyas tendrán la forma de castillete o espeque.', false, '2025-09-13 13:53:12.508202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e847377f-1f10-43c6-b1c4-d22883c21f10', 'd61ff762-c962-48c6-99a1-8e78836670a3', 'd', 'No tienen una forma preestablecida, pudiendo elegirse cualquiera que no se preste a confusión con la de otras marcas de ayudas a la navegación.', true, '2025-09-13 13:53:12.508331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afd06e5a-f651-4283-bd0c-dfea80f3a32e', 'b52ecbd5-5b50-4810-9ede-07be6b058a7f', 'a', 'La existencia de un peligro en el canal principal.', false, '2025-09-13 13:53:12.508598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb5880ab-6fa5-480f-b880-88470f8bc58f', 'b52ecbd5-5b50-4810-9ede-07be6b058a7f', 'b', 'El punto de bifurcación de un canal.', true, '2025-09-13 13:53:12.50873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20a92ef8-e058-40d5-8a28-c8e247305408', 'b52ecbd5-5b50-4810-9ede-07be6b058a7f', 'c', 'El final de un canal balizado.', false, '2025-09-13 13:53:12.508879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fa8e251-a4a4-43a5-b1c2-f82ac87c52ed', 'b52ecbd5-5b50-4810-9ede-07be6b058a7f', 'd', 'El comienzo de un canal balizado. Reglamento (RIPA).', false, '2025-09-13 13:53:12.509024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d0c40de-b178-4bad-8f79-4845955297b0', '934b8aa3-4696-43af-8fb8-3554c5900cad', 'a', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:12.509319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26363784-678b-43d4-ab39-0d1a86515d24', '934b8aa3-4696-43af-8fb8-3554c5900cad', 'b', 'Una pitada larga.', false, '2025-09-13 13:53:12.509451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b508a1e5-1307-480f-9bcf-c7e4d7fae4f8', '934b8aa3-4696-43af-8fb8-3554c5900cad', 'c', 'Dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.509579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('baa84dd7-39c9-4ef9-b2d5-f0a6da4cd551', '934b8aa3-4696-43af-8fb8-3554c5900cad', 'd', 'Una pitada corta.', false, '2025-09-13 13:53:12.50971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d13bc2bc-9bc5-45e3-b887-b87fd8bbc4f1', '398e5d6c-142f-4ca9-a25f-cf77db2d8531', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.510024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a72822e-02f8-4a87-ad01-2b5c0daf5bcf', '398e5d6c-142f-4ca9-a25f-cf77db2d8531', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', true, '2025-09-13 13:53:12.510157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02078079-88a8-4a7f-bcef-35c2cee5f82d', '398e5d6c-142f-4ca9-a25f-cf77db2d8531', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de estribor.', false, '2025-09-13 13:53:12.510295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f254903-7019-423a-8d86-d85c66ab3bf9', '398e5d6c-142f-4ca9-a25f-cf77db2d8531', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:12.510432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3be39e92-3e0f-4202-89cd-5441d9efa3af', 'e7958403-4e08-4e27-857d-000f27cb09fd', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.510705+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76985d50-ac38-484a-a635-3655fa53e0d0', 'e7958403-4e08-4e27-857d-000f27cb09fd', 'b', 'Se deberá mantener el rumbo ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:12.510842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0c0ec5c-abaa-4f6f-b9ed-cb7b71e45824', 'e7958403-4e08-4e27-857d-000f27cb09fd', 'c', 'Únicamente deberemos maniobrar por ser el buque que alcanza un velero, en cualquier otra situación se mantendría rumbo tal y como recoge la regla.', false, '2025-09-13 13:53:12.510977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57f0ffa7-dca5-4c1b-ac11-944ea9f6d76e', 'e7958403-4e08-4e27-857d-000f27cb09fd', 'd', 'Los datos aportados en el enunciado no son suficientes para determinar por qué banda recibe el viento el velero, siendo esto fundamental para decidir si debemos maniobrar o mantener rumbo.', false, '2025-09-13 13:53:12.511107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7021bb8e-440c-4baf-8e38-8ee5dcfa9bad', '2716f1a4-8241-42d3-9c94-55023bef00ce', 'a', 'Cualquier medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:12.511378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85f9e600-523c-4493-93e8-59e61d05b62d', '2716f1a4-8241-42d3-9c94-55023bef00ce', 'b', 'Una campana, además del pito.', true, '2025-09-13 13:53:12.511506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e60633e-2f3d-4f89-9787-4d6bd6d9a352', '2716f1a4-8241-42d3-9c94-55023bef00ce', 'c', 'Sólo una campana.', false, '2025-09-13 13:53:12.511654+00');
