INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2b074b9-aec0-46c9-9656-3dc10bb12450', '39013f63-ca2c-4d3b-968c-71615f75e80b', 'a', 'Una luz de tope a proa, una luz de tope a popa más alta que la de proa, luces de costado y una luz', false, '2025-09-13 13:53:12.51211+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b479fdc5-7a8f-4b8b-ba70-d192c52c2b47', '39013f63-ca2c-4d3b-968c-71615f75e80b', 'b', 'Una luz de tope a proa, luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.512241+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78ff69d7-5eea-4899-b9ef-2e1263089e2b', '39013f63-ca2c-4d3b-968c-71615f75e80b', 'c', 'Una luz blanca todo horizonte y luces de costado.', false, '2025-09-13 13:53:12.512369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24e0817e-3ce4-4654-93c2-371560a6c851', '39013f63-ca2c-4d3b-968c-71615f75e80b', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirá también luces de costado.', false, '2025-09-13 13:53:12.512496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb0e0030-90c6-47a4-9568-91a27f86c1a8', 'a2756590-c0f9-4769-944b-bb00347741cf', 'a', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:12.512771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e082a15-92cb-4778-a46c-9ce9a58f097b', 'a2756590-c0f9-4769-944b-bb00347741cf', 'b', 'Las Reglas relativas a las luces deberán cumplirse desde la puesta del sol hasta su salida, y durante ese intervalo no se exhibirá ninguna otra luz, con la excepción de aquellas que no puedan ser confundidas con las luces mencionadas en este Reglamento o que no perjudiquen su visibilidad o carácter distintivo, ni impidan el ejercicio de una vigilancia eficaz.', false, '2025-09-13 13:53:12.512901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c60161b2-cd2c-469f-971a-09673fdfe3fb', 'a2756590-c0f9-4769-944b-bb00347741cf', 'c', 'Las luces preceptuadas por estas Reglas, en caso de llevarse, deberán exhibirse también desde la salida hasta la puesta del sol si hay visibilidad reducida y podrán exhibirse en cualquier otra circunstancia que se considere necesario.', false, '2025-09-13 13:53:12.513031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea5e6294-cb57-4b86-94bd-25be6b56249b', 'a2756590-c0f9-4769-944b-bb00347741cf', 'd', 'Las Reglas relativas a las marcas deberán cumplirse de día de manera optativa a juicio del capitán, armador o patrón.', true, '2025-09-13 13:53:12.513162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a5ac9b3-54ec-40d4-9f69-e4b483f5aeaa', '6807198e-7ea4-462c-8f65-cd01964b8771', 'a', 'Luz de tope.', true, '2025-09-13 13:53:12.513431+00');
