INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94c3ab5b-f2dd-4d76-ae41-dfb917a3c064', '4b0214fe-6f02-4b63-ae42-3a9c38186321', 'c', 'En la medida de lo posible, los buques dedicados a la pesca, en navegación, se mantendrán apartados de la derrota de un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:12.514345+00');
