INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10eb72da-cb9a-4776-b52d-e5908107f6fd', 'dd99bbe6-e04f-43b6-8aaf-c7ddba92eb12', 'a', 'En cualquier embarcación de vela que no supere los 7 metros de eslora y embarcaciones de remo.', true, '2025-09-13 13:53:12.51475+00');
