INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97aa43f1-ba14-44d9-8abc-f669a0eea01d', '70520c25-6f3b-408e-a67e-e0b12561fe99', 'a', 'La escala que esté usando el radar puede imponer restricciones a la hora de detectar objetivos.', true, '2025-09-13 13:53:12.515432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a61ea7e6-8232-4cbb-9e4f-e01241bd40f0', '70520c25-6f3b-408e-a67e-e0b12561fe99', 'b', 'El estado de la mar no influye en la detección de objetivos ya que la señal de alta frecuencia que emite el radar es electromagnética.', false, '2025-09-13 13:53:12.515575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8aba4f53-d7e3-455e-9d64-4fa3ba7f0d9e', '70520c25-6f3b-408e-a67e-e0b12561fe99', 'c', 'Sin importar las características del radar, siempre detectará los pequeños objetos flotantes o embarcaciones pequeñas.', false, '2025-09-13 13:53:12.515707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f96e98c-7e3f-4471-ad65-ab4c04da8fc0', '70520c25-6f3b-408e-a67e-e0b12561fe99', 'd', 'De noche, la existencia de resplandor producido por las luces de tierra influirá en la detección del radar de otras embarcaciones. DE TRANSPORTES                                                                                       DE TRANSPORTES Y MOVILIDAD SOSTENIBLE Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO Código de Test 04 Nomenclatura náutica.', false, '2025-09-13 13:53:12.515854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dd6c02f-e268-437f-8b50-d36f3348d730', '4223bafd-0bf2-487c-9d0a-74450032451a', 'a', 'Roda.', false, '2025-09-13 13:53:12.516256+00');
