INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f51d15a3-01cc-4980-a634-f2a173f030ef', '4223bafd-0bf2-487c-9d0a-74450032451a', 'c', 'Codaste.', false, '2025-09-13 13:53:12.516512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4480656-eb67-4df0-babe-0f0838ae13c8', '4223bafd-0bf2-487c-9d0a-74450032451a', 'd', 'Bao.', false, '2025-09-13 13:53:12.516642+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2d76666-57b3-41cf-8fab-48010fa6f3dc', '7b3555a5-efb5-4e91-9a4d-f972730b7e15', 'a', 'Cuelgue y esté lista para fondear.', true, '2025-09-13 13:53:12.516959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('298b507c-73a6-4f9f-b1ad-4d0317825681', '7b3555a5-efb5-4e91-9a4d-f972730b7e15', 'b', 'Esté en el fondo lista para su recuperación.', false, '2025-09-13 13:53:12.517118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cd79a1b-84a8-4951-8711-53488c1265ea', '7b3555a5-efb5-4e91-9a4d-f972730b7e15', 'c', 'Esté sumergida en la línea vertical que va hasta el fondo del mar.', false, '2025-09-13 13:53:12.51727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('167094a6-6d33-4916-96c2-3526f39164e5', '7b3555a5-efb5-4e91-9a4d-f972730b7e15', 'd', 'Se libere por no haberse podido recuperar.', false, '2025-09-13 13:53:12.517422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4f09a2b-b12c-44d0-9ad6-cdb2d9b506fb', '970340d8-4b91-4e9f-868e-d30f546a4822', 'a', 'La distancia vertical medida sobre el costado de la embarcación desde la línea de flotación, en su condición de máxima carga, hasta la cubierta estanca más alta.', true, '2025-09-13 13:53:12.517739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8e4782c-c66d-45a6-982d-044f2e15c999', '970340d8-4b91-4e9f-868e-d30f546a4822', 'b', 'La altura de la obra viva.', false, '2025-09-13 13:53:12.517916+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79d32c7f-1c3c-409b-b63c-9aa02ebebabd', '970340d8-4b91-4e9f-868e-d30f546a4822', 'c', 'La distancia vertical, medida en la mitad de la eslora desde la cara superior de la línea de cubierta hasta el canto superior de la quilla.', false, '2025-09-13 13:53:12.518077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfda4107-702a-4593-8d74-1a5ebe240e80', '970340d8-4b91-4e9f-868e-d30f546a4822', 'd', 'La distancia vertical medida entre el canto inferior de la quilla y la línea de flotación.', false, '2025-09-13 13:53:12.518232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f7fdc2b-388a-4425-a445-884388f50277', 'f08387d8-cee2-4649-a28f-e571bfd9ea97', 'a', 'Barlovento es la parte hacia donde se dirige el viento.', false, '2025-09-13 13:53:12.51857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23300275-7804-4f80-9cf0-ae467b1cec03', 'f08387d8-cee2-4649-a28f-e571bfd9ea97', 'b', 'Sotavento es la parte de donde viene el viento.', false, '2025-09-13 13:53:12.518798+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('613c60c8-a32b-4d8e-94ec-335ec3a7a39e', 'f08387d8-cee2-4649-a28f-e571bfd9ea97', 'c', 'Los factores principales que producen la escora son la distribución de pesos y la acción del viento', true, '2025-09-13 13:53:12.518978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('394f3e52-82d9-43bc-9cf0-b0f7e2d12f18', 'f08387d8-cee2-4649-a28f-e571bfd9ea97', 'd', 'Adrizar es la acción de inclinar un barco en sentido babor-estribor o en sentido estribor-babor desde su posición normal de equilibrio, hacia los costados. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:12.519115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6878e14-17b3-405f-84ca-15bca6d4f3be', '18dbc479-2077-49ce-b2ae-1b5f4aa5c418', 'a', 'Ballestrinque.', false, '2025-09-13 13:53:12.519396+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57e027c3-573e-4f00-abed-8ee6d25a2f38', '18dbc479-2077-49ce-b2ae-1b5f4aa5c418', 'b', 'Vuelta de rezón.', false, '2025-09-13 13:53:12.519528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fca492a-0f8c-45f1-8afe-745bc424851f', '18dbc479-2077-49ce-b2ae-1b5f4aa5c418', 'c', 'As de guía.', true, '2025-09-13 13:53:12.519656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c26154c-aa3d-492e-9dce-6c4c3fc55c0a', '9ca691a8-5016-4d1c-b618-eae058c50d35', 'a', 'El orinque es el cabo que se amarra por un chicote al ancla y por el otro a una boya para señalar la ubicación del ancla.', false, '2025-09-13 13:53:12.520051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90bc1fbe-490f-46e5-8175-632539010970', '9ca691a8-5016-4d1c-b618-eae058c50d35', 'b', 'En la maniobra de fondeo hay que elegir el fondeadero y su tenedero en función, entre otros aspectos, de la naturaleza del fondo y de la sonda.', false, '2025-09-13 13:53:12.520187+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54db67ad-d4e6-4ecd-8b67-d1ce36ff00db', '9ca691a8-5016-4d1c-b618-eae058c50d35', 'c', 'Para levar el ancla se dará siempre atrás la embarcación mientras se cobra el elemento de fondeo hasta que el ancla esté a la pendura y tocando el fondo.', true, '2025-09-13 13:53:12.520331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('756c5046-2324-401c-a9ed-c0d22506df44', '9ca691a8-5016-4d1c-b618-eae058c50d35', 'd', 'Durante el fondeo, se precisa vigilar la sonda, marcando un fondo mínimo con la alarma, y tomar referencias a tierra para asegurarnos que el ancla no ha garreado.', false, '2025-09-13 13:53:12.520465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1793193-fe0c-4913-a231-b38b5ec70006', '03e1d698-7a49-4f3c-afc2-0c9052d60e6f', 'a', 'Debe estar perfectamente establecida y sin ningún tipo de interrupción la comunicación del conductor con el mar.', false, '2025-09-13 13:53:12.520738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81a7cff4-cb1d-491a-8460-f7a37f5d21bd', '03e1d698-7a49-4f3c-afc2-0c9052d60e6f', 'b', 'La punta o puntas del pararrayos deben ser afiladas y con suficiente dureza para no ser fundidas', false, '2025-09-13 13:53:12.520889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20a2c61e-346b-4cac-8604-aa1583f17cc6', '03e1d698-7a49-4f3c-afc2-0c9052d60e6f', 'c', 'El conductor debe evitar ángulos pronunciados.', false, '2025-09-13 13:53:12.521027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b375135-18b5-416d-b46f-e4331c81550e', '03e1d698-7a49-4f3c-afc2-0c9052d60e6f', 'd', 'El pararrayos debe estar en contacto con otras antenas y jarcias para reforzar su poder de parar las descargas eléctricas que produzcan los rayos.', true, '2025-09-13 13:53:12.521162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c67fb71b-ca16-42db-bca0-05579a215b28', '76a86c27-cf0e-45a9-a53d-e1e96c03e5af', 'a', 'Llamar por teléfono al 112.', false, '2025-09-13 13:53:12.521432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4121f69-7c83-41d4-965c-f46feefe4150', '76a86c27-cf0e-45a9-a53d-e1e96c03e5af', 'b', 'Llamar por teléfono al 900 202 202.', false, '2025-09-13 13:53:12.521562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b23ccf5e-7be7-42d2-8282-388e52ca7108', '76a86c27-cf0e-45a9-a53d-e1e96c03e5af', 'c', 'Llamar por teléfono al 900 102 102.', true, '2025-09-13 13:53:12.521693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70c0d50d-1ef5-412d-a732-cc898ae5c02c', '76a86c27-cf0e-45a9-a53d-e1e96c03e5af', 'd', 'Emplear la estación de radio de a bordo.', false, '2025-09-13 13:53:12.521834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1976cd6-428b-4ea4-acea-882f33f04289', '0ea8b017-0455-4725-a133-5503b8954237', 'a', 'El estado de los alimentos que se lleven a bordo.', false, '2025-09-13 13:53:12.522124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6fccbc5-b2e5-4835-a3b5-7ec19eabed19', '0ea8b017-0455-4725-a133-5503b8954237', 'b', 'El nivel del tanque de almacenamiento de aguas negras, como por ejemplo las procedentes de inodoros y lavabos.', false, '2025-09-13 13:53:12.522265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22820df8-1f42-41b2-a895-afa959cdc096', '0ea8b017-0455-4725-a133-5503b8954237', 'c', 'El nivel del tanque de agua salada.', false, '2025-09-13 13:53:12.522401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4eee1809-0e2d-4f07-81a4-c8431127a0c1', '0ea8b017-0455-4725-a133-5503b8954237', 'd', 'La estanqueidad de la embarcación.', true, '2025-09-13 13:53:12.522532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a8d9ad0-2df6-41f0-a428-f9b09126f219', '45c6b674-f20d-4e7d-b322-aeb25a30fa3a', 'a', 'Arneses.', false, '2025-09-13 13:53:12.5228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de9e4e33-3738-40de-aadf-2ea05f694797', '45c6b674-f20d-4e7d-b322-aeb25a30fa3a', 'b', 'Grifos de fondo.', true, '2025-09-13 13:53:12.522947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1791777-ddde-4dd4-93ab-6610ef8817a9', '45c6b674-f20d-4e7d-b322-aeb25a30fa3a', 'c', 'Bocina de niebla.', false, '2025-09-13 13:53:12.523085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c58e24fc-1efa-4cf1-8364-e4bfc4fe7c9b', '45c6b674-f20d-4e7d-b322-aeb25a30fa3a', 'd', 'Líneas de vida.', false, '2025-09-13 13:53:12.523216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d8196cc-a45f-4095-8177-d8111187be72', '89e843b9-b6e3-43ef-a39b-818805421b5b', 'a', 'Siempre, ya que se encuentran navegando por espacios marítimos españoles.', false, '2025-09-13 13:53:12.523487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efe9cda2-77b8-4c39-b579-46d99ce27f3e', '89e843b9-b6e3-43ef-a39b-818805421b5b', 'b', 'Cuando el naviero o propietario lo crea aconsejable.', false, '2025-09-13 13:53:12.523636+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c41aa2ad-a885-4b30-97c1-294a333dba59', '89e843b9-b6e3-43ef-a39b-818805421b5b', 'c', 'Siempre que tengan entrada o salida en un puerto español.', true, '2025-09-13 13:53:12.523766+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2a8f23d-399b-49f3-94e5-d750c0163816', '89e843b9-b6e3-43ef-a39b-818805421b5b', 'd', 'Sólo cuando tengan una embarcación de recreo superior a 12 metros de eslora.', false, '2025-09-13 13:53:12.523901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd043cc6-7c3e-44c9-b34c-0298ce10334b', '173fbdcd-d502-46c3-8fb2-c9e448055fc9', 'a', 'Tienen, en todo caso, la obligación de abanderamiento y matriculación, así como de despacho, si la propia embarcación y su equipo propulsor ostentan el marcado CE.', false, '2025-09-13 13:53:12.524173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae22aef0-19ed-4fd9-ba3c-3ed74b3e65af', '173fbdcd-d502-46c3-8fb2-c9e448055fc9', 'b', 'En ningún caso necesitan obtener antes de su entrada en servicio un certificado de inscripción, al tener marcado CE.', false, '2025-09-13 13:53:12.524327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2534a103-0e0b-4a05-b11f-e3f5fd5433c9', '173fbdcd-d502-46c3-8fb2-c9e448055fc9', 'c', 'Sólo podrán navegar en el mar territorial español y, en cualquier caso, no podrán sobrepasar las zonas de navegación a las que estén limitadas de acuerdo con su categoría de diseño.', true, '2025-09-13 13:53:12.524468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98f36ebc-f1e1-47eb-940b-215aa2631b44', '173fbdcd-d502-46c3-8fb2-c9e448055fc9', 'd', 'Deberán llevar pintado o fijado de forma permanente en ambas amuras sólo el nombre, que se colocará a la máxima altura posible de la línea de flotación.', false, '2025-09-13 13:53:12.5246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc049faa-11cf-4dde-ad7a-a6a5388336f4', '3d2d972a-06e0-44d1-9425-7c8b17ea73b1', 'a', 'Están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.524888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19859a1e-5d8a-44e1-a9fa-448c53c1391c', '3d2d972a-06e0-44d1-9425-7c8b17ea73b1', 'b', 'Pueden prestarse a confusión con la de otras marcas de ayudas a la navegación, por eso la forma de las boyas de las marcas especiales será siempre rectangular.', false, '2025-09-13 13:53:12.52502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b7103ac-38c3-4f20-bbd1-932b709fa949', '3d2d972a-06e0-44d1-9425-7c8b17ea73b1', 'c', 'Serán de color amarillo y las boyas tendrán la forma de castillete o espeque.', false, '2025-09-13 13:53:12.525149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7434b40f-8261-4450-8902-990fbb57aab7', '3d2d972a-06e0-44d1-9425-7c8b17ea73b1', 'd', 'No tienen una forma preestablecida, pudiendo elegirse cualquiera que no se preste a confusión con la de otras marcas de ayudas a la navegación.', true, '2025-09-13 13:53:12.525277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('732b1df8-5a45-4cd1-9bfe-9c088474bb55', '66f2ff89-bbca-4256-8c71-9175eab53341', 'a', 'Franjas horizontales rojas y blancas.', false, '2025-09-13 13:53:12.525544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b506201f-08c7-4965-8792-1611c784e7d2', '66f2ff89-bbca-4256-8c71-9175eab53341', 'b', 'Franjas verticales rojas y negras.', false, '2025-09-13 13:53:12.525674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dffeeed6-8eda-4852-ab01-2d9392d7ab6a', '66f2ff89-bbca-4256-8c71-9175eab53341', 'c', 'Franjas verticales rojas y blancas.', true, '2025-09-13 13:53:12.525802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac2eb21b-45b8-4544-ad58-cce77368afdf', '66f2ff89-bbca-4256-8c71-9175eab53341', 'd', 'Franjas horizontales rojas y negras.', false, '2025-09-13 13:53:12.525931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('615f0007-d693-4129-970b-67b669849f61', '0ec9ea41-0cdf-4316-8093-fbb945343ed5', 'a', 'Los peligros aislados de dimensiones limitadas enteramente rodeadas de aguas navegables.', true, '2025-09-13 13:53:12.526197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0718e36-7d09-4cbd-9b28-37c974732207', '0ec9ea41-0cdf-4316-8093-fbb945343ed5', 'b', 'Los lados de babor y estribor de la derrota que debe seguirse, a fin de evitar un peligro concreto.', false, '2025-09-13 13:53:12.526324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('529d2e6b-26d6-47d7-b6a8-d8a7524def6e', '0ec9ea41-0cdf-4316-8093-fbb945343ed5', 'c', 'Que las aguas más profundas en esa zona se encuentran rodeadas de algún tipo de peligro no representado aún en la carta náutica.', false, '2025-09-13 13:53:12.52647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5d5cd6d-6d2b-4e92-9266-d592cb897e90', '0ec9ea41-0cdf-4316-8093-fbb945343ed5', 'd', 'Algún tipo de peligro concreto y la marca será distinta según el tamaño del peligro y la distancia a la que puede utilizarse con seguridad esta señal.', false, '2025-09-13 13:53:12.5266+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94d55eac-b281-49da-98a2-136b48592c41', '0c453c72-48d9-49e5-b679-77f450824d3d', 'a', 'La existencia de un peligro en el canal principal.', false, '2025-09-13 13:53:12.526891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7dce275-4ebc-4d82-8ce1-2882498667f3', '0c453c72-48d9-49e5-b679-77f450824d3d', 'b', 'El punto de bifurcación de un canal.', true, '2025-09-13 13:53:12.52703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fe82256-6dde-48f0-b361-ca06b8d0d9a0', '0c453c72-48d9-49e5-b679-77f450824d3d', 'c', 'El final de un canal balizado.', false, '2025-09-13 13:53:12.527165+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b65e318-03fa-4cdf-ad56-3026ebbb95d9', '0c453c72-48d9-49e5-b679-77f450824d3d', 'd', 'El comienzo de un canal balizado.', false, '2025-09-13 13:53:12.527297+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b61d580-1a66-4cc7-8289-96563d43cc4c', '9650afd3-4a3a-4126-b6e0-76a3ec248aaf', 'a', 'Oeste.', false, '2025-09-13 13:53:12.527568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('043191d6-767c-47a7-9a97-8305a9ea8419', '9650afd3-4a3a-4126-b6e0-76a3ec248aaf', 'b', 'Norte.', false, '2025-09-13 13:53:12.527701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7850059-d69d-407c-88cf-735a09ff4c92', '9650afd3-4a3a-4126-b6e0-76a3ec248aaf', 'c', 'Sur.', false, '2025-09-13 13:53:12.527837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d86863f6-55ca-4a6b-8274-d2f67ae588c1', '9650afd3-4a3a-4126-b6e0-76a3ec248aaf', 'd', 'Este. Reglamento (RIPA).', true, '2025-09-13 13:53:12.52797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1625040e-b187-4a12-8a4c-9f6386b31f2e', '535bd422-77ba-4cfd-ad3b-f901e3d9f723', 'a', 'Luz de tope.', true, '2025-09-13 13:53:12.528251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9fa6186-18c4-4e18-950c-a51b0fb7f3b0', '535bd422-77ba-4cfd-ad3b-f901e3d9f723', 'b', 'Luz de alcance.', false, '2025-09-13 13:53:12.528384+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6c1fe67-7c63-4906-b79b-363f841adb64', '535bd422-77ba-4cfd-ad3b-f901e3d9f723', 'c', 'Luz de remolque.', false, '2025-09-13 13:53:12.528514+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b309ef7d-0999-4211-92c8-18ca93e68b8f', '535bd422-77ba-4cfd-ad3b-f901e3d9f723', 'd', 'Luz de fondeo.', false, '2025-09-13 13:53:12.528643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a32eb213-d080-4146-b15d-0e38f908aa19', '91848ffa-42b1-495f-820f-1ccfa95882ec', 'a', 'Una luz de tope a proa, una luz de tope a popa más alta que la de proa, luces de costado y una luz', false, '2025-09-13 13:53:12.52893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3756feb6-fbd3-42d5-a9cd-7f6049f5d874', '91848ffa-42b1-495f-820f-1ccfa95882ec', 'b', 'Una luz de tope a proa, luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.529067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf105d2c-f0a9-4244-a392-d87cebce6c88', '91848ffa-42b1-495f-820f-1ccfa95882ec', 'c', 'Una luz blanca todo horizonte y luces de costado.', false, '2025-09-13 13:53:12.529197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ccd6eca-20d5-4a01-81cf-85bb2872a74e', '7487c535-5aae-4dd0-b7c0-980cf5cf098c', 'a', 'Es un buque de gran calado y está restringido por el mismo.', false, '2025-09-13 13:53:12.547414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0a93b88-a274-4b7b-90d0-d6fc2d78fd37', '91848ffa-42b1-495f-820f-1ccfa95882ec', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirá también luces de costado.', false, '2025-09-13 13:53:12.529327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f31856c7-8e6d-4c5d-801e-b885c04bd84e', '98c07ae6-1f36-4251-be70-d6bcd1de2e77', 'a', 'La escala que esté usando el radar puede imponer restricciones a la hora de detectar objetivos.', true, '2025-09-13 13:53:12.529604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5f06f6c-2734-487b-8821-ae8331bc18e7', '98c07ae6-1f36-4251-be70-d6bcd1de2e77', 'b', 'El estado de la mar no influye en la detección de objetivos ya que la señal de alta frecuencia que emite el radar es electromagnética.', false, '2025-09-13 13:53:12.529738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4c92d8f-e4a2-41c5-a39f-34a94b8a3860', '98c07ae6-1f36-4251-be70-d6bcd1de2e77', 'c', 'Sin importar las características del radar, siempre detectará los pequeños objetos flotantes o embarcaciones pequeñas.', false, '2025-09-13 13:53:12.529885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8255b57-995d-451f-8c84-bacf301fd9ac', '98c07ae6-1f36-4251-be70-d6bcd1de2e77', 'd', 'De noche, la existencia de resplandor producido por las luces de tierra influirá en la detección del radar de otras embarcaciones.', false, '2025-09-13 13:53:12.530017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c46967b-dad6-41c2-a343-6bff617f939c', '7d8c8abb-3620-4c71-8ae5-ad85d9f1e1ba', 'a', 'Dos pitadas largas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', true, '2025-09-13 13:53:12.530294+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32841073-a3d4-4912-b72d-c22c208a69cb', '7d8c8abb-3620-4c71-8ae5-ad85d9f1e1ba', 'b', 'Una pitada larga.', false, '2025-09-13 13:53:12.530424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7b30097-5220-4911-9644-878a9332cc68', '7d8c8abb-3620-4c71-8ae5-ad85d9f1e1ba', 'c', 'Dos pitadas cortas consecutivas separadas por un intervalo de unos dos segundos entre ambas.', false, '2025-09-13 13:53:12.530569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5e70631-d37a-4714-b9f0-ff15beca6a34', '7d8c8abb-3620-4c71-8ae5-ad85d9f1e1ba', 'd', 'Una pitada corta.', false, '2025-09-13 13:53:12.530699+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d28ec79b-f32f-488c-bbaa-35f96929bb7c', '62be32dc-a512-4ce4-8afd-2409a89a169f', 'a', 'Los buques de propulsión mecánica, en navegación, se mantendrán apartados de la derrota de un buque sin gobierno.', false, '2025-09-13 13:53:12.530984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87fdf410-1216-4698-8529-d97a4d4f178b', '62be32dc-a512-4ce4-8afd-2409a89a169f', 'b', 'Los buques de vela, en navegación, se mantendrán apartados de la derrota de un buque dedicado', false, '2025-09-13 13:53:12.531115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('107fe33c-9728-4f99-888e-f19bf8b15cc8', '62be32dc-a512-4ce4-8afd-2409a89a169f', 'c', 'En la medida de lo posible, los buques dedicados a la pesca, en navegación, se mantendrán apartados de la derrota de un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:12.531253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab70fe1b-09d0-4936-8051-10821e98bed5', '62be32dc-a512-4ce4-8afd-2409a89a169f', 'd', 'Los buques de vela, en navegación, se mantendrán apartados de la derrota de un buque de propulsión mecánica.', true, '2025-09-13 13:53:12.531385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78e80061-3a1c-4517-8fe6-1cab7ba401b6', '26862541-d607-422d-9ace-886ee304b115', 'a', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:12.531659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebf95b37-6889-46dd-ac52-6245229d4ead', '26862541-d607-422d-9ace-886ee304b115', 'b', 'Las Reglas relativas a las luces deberán cumplirse desde la puesta del sol hasta su salida, y durante ese intervalo no se exhibirá ninguna otra luz, con la excepción de aquellas que no puedan ser confundidas con las luces mencionadas en este Reglamento o que no perjudiquen su visibilidad o carácter distintivo, ni impidan el ejercicio de una vigilancia eficaz.', false, '2025-09-13 13:53:12.531801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a6d9103-11a6-4452-93fc-f7d2e56056cc', '26862541-d607-422d-9ace-886ee304b115', 'c', 'Las luces preceptuadas por estas Reglas, en caso de llevarse, deberán exhibirse también desde la salida hasta la puesta del sol si hay visibilidad reducida y podrán exhibirse en cualquier otra circunstancia que se considere necesario.', false, '2025-09-13 13:53:12.531933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b662a84-324e-41e9-8544-fdf15ec792ac', '26862541-d607-422d-9ace-886ee304b115', 'd', 'Las Reglas relativas a las marcas deberán cumplirse de día de manera optativa a juicio del capitán, armador o patrón.', true, '2025-09-13 13:53:12.53207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0f36902-6daf-4d3a-88c5-0da09c03f3a9', '91af9da8-550c-4a7a-b1f8-f6015fdf9852', 'a', 'Cualquier medio para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:12.532346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6a1b89f2-6172-4b57-9213-1349c94d272b', '91af9da8-550c-4a7a-b1f8-f6015fdf9852', 'b', 'Una campana, además del pito.', true, '2025-09-13 13:53:12.532477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('773e5529-b884-4c09-9dc5-c5b2047f1522', '91af9da8-550c-4a7a-b1f8-f6015fdf9852', 'c', 'Sólo una campana.', false, '2025-09-13 13:53:12.532607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1da4d9ab-b4bd-44c1-97fc-bb4f85339130', '91af9da8-550c-4a7a-b1f8-f6015fdf9852', 'd', 'Sólo un pito.', false, '2025-09-13 13:53:12.532734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87fb5d26-db7f-445c-ab4f-366bdd69bf57', 'ed7f04f1-0cb4-4b0e-896f-88a796975e6e', 'a', 'Se deberá maniobrar para mantenernos apartados de su derrota.', false, '2025-09-13 13:53:12.533019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d484ec4d-80fd-4a83-9355-9b21924e862d', 'ed7f04f1-0cb4-4b0e-896f-88a796975e6e', 'b', 'Se deberá mantener el rumbo ya que debe de ser el otro buque el que maniobre.', true, '2025-09-13 13:53:12.533152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('276414c6-9b13-40bd-825f-71b4d5bd7efe', 'ed7f04f1-0cb4-4b0e-896f-88a796975e6e', 'c', 'Únicamente deberemos maniobrar por ser el buque que alcanza un velero, en cualquier otra situación se mantendría rumbo tal y como recoge la regla.', false, '2025-09-13 13:53:12.533288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e535fc8-6cb0-48d5-bb79-eba450f5c159', 'ed7f04f1-0cb4-4b0e-896f-88a796975e6e', 'd', 'Los datos aportados en el enunciado no son suficientes para determinar por qué banda recibe el viento el velero, siendo esto fundamental para decidir si debemos maniobrar o mantener rumbo.', false, '2025-09-13 13:53:12.53342+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca4b8f44-7080-4855-9892-99f3d4a26612', 'd40b12ba-5678-4e63-9ffa-14d2cc09cbdd', 'a', 'En cualquier embarcación de vela que no supere los 7 metros de eslora y embarcaciones de remo.', true, '2025-09-13 13:53:12.533688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f960c23f-3ae0-418e-b4d2-9c9fb9989e89', 'd40b12ba-5678-4e63-9ffa-14d2cc09cbdd', 'b', 'En cualquier embarcación de vela que no supere los 12 metros de eslora y embarcaciones de', false, '2025-09-13 13:53:12.533837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7845f4f-8368-4282-9242-693792b3fffe', 'd40b12ba-5678-4e63-9ffa-14d2cc09cbdd', 'c', 'En cualquier embarcación de vela que no supere los 20 metros de eslora y embarcaciones de', false, '2025-09-13 13:53:12.533981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63b6e225-9a62-4fd7-b14e-dfbd6ad68d41', 'd40b12ba-5678-4e63-9ffa-14d2cc09cbdd', 'd', 'Sólo en embarcaciones de remos.', false, '2025-09-13 13:53:12.534122+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acb18d2e-90e8-42a5-90e4-2869cb846f3d', '5743f991-f2e7-461b-8e9d-b88cff62c7a8', 'a', 'Dado que se trata de una situación de alcance, deberemos mantenernos siempre apartados de la otra embarcación y maniobrar en consecuencia.', false, '2025-09-13 13:53:12.534417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af7fed83-e698-4969-a864-040a5e2252b6', '5743f991-f2e7-461b-8e9d-b88cff62c7a8', 'b', 'Dado que se trata de una vuelta encontrada, deberemos caer a estribor de forma que pasemos por la banda de babor del otro.', true, '2025-09-13 13:53:12.534549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0087a197-1aaa-46b2-a943-3c294d7ac8ad', '5743f991-f2e7-461b-8e9d-b88cff62c7a8', 'c', 'Dado que se trata de una situación de cruce con riesgo de abordaje, maniobraremos por estar al costado de estribor.', false, '2025-09-13 13:53:12.534683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cde23742-c02e-4f30-acc3-5984b4859de8', '5743f991-f2e7-461b-8e9d-b88cff62c7a8', 'd', 'Dado que se trata de una maniobra de buque que sigue a rumbo, mantendremos rumbo y velocidad excepto si observamos que la otra embarcación no efectúa la maniobra necesaria para evitar el abordaje.', false, '2025-09-13 13:53:12.534819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1805745-cea1-4699-9b2b-b41f4038cbe3', '4086759e-c9bb-4b7c-8988-cec363ae3470', 'a', 'A pique.', true, '2025-09-13 13:53:12.535231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0436ead4-84cb-4fe5-bb4b-e7c0cd5e6832', '4086759e-c9bb-4b7c-8988-cec363ae3470', 'b', 'A la pendura.', false, '2025-09-13 13:53:12.535375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a86b6f3d-f4ac-496d-99a5-d053a2db856d', '4086759e-c9bb-4b7c-8988-cec363ae3470', 'c', 'Clara.', false, '2025-09-13 13:53:12.535518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1403dcb3-a9e2-4f42-a5d4-a7a79f4f8a23', '4086759e-c9bb-4b7c-8988-cec363ae3470', 'd', 'Libre.', false, '2025-09-13 13:53:12.535656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfe51b28-bc1e-4bb9-97d6-4a553baeebd5', 'f5f32df5-b3c9-4b89-8b3e-8eb7bda4d742', 'a', 'Enderezarse o ponerse vertical.', false, '2025-09-13 13:53:12.535933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3be6f54f-72f3-42e0-a58e-84c03ddc5f93', 'f5f32df5-b3c9-4b89-8b3e-8eb7bda4d742', 'b', 'Inclinarse sobre uno de sus costados.', true, '2025-09-13 13:53:12.536065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffe54123-9f30-477e-b9b3-99fdda5fd3e4', 'f5f32df5-b3c9-4b89-8b3e-8eb7bda4d742', 'c', 'Hundir la proa y levantar la popa.', false, '2025-09-13 13:53:12.536201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa9c7835-9ab5-4a93-960e-4b4e3a26956c', 'f5f32df5-b3c9-4b89-8b3e-8eb7bda4d742', 'd', 'Hundir la popa y levantar la proa.', false, '2025-09-13 13:53:12.536335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22d2a147-a551-4b7a-86aa-efa2aa969d3a', '518f2395-3fa0-435c-a874-ff9238fea02d', 'a', 'El través.', true, '2025-09-13 13:53:12.536606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('931951e6-0850-44f0-ba27-4e15cadf48ed', '518f2395-3fa0-435c-a874-ff9238fea02d', 'b', 'El plano de crujía.', false, '2025-09-13 13:53:12.536737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17ab4c59-b917-4066-b424-127dc9b03f7f', '518f2395-3fa0-435c-a874-ff9238fea02d', 'c', 'La aleta.', false, '2025-09-13 13:53:12.536876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6af38bff-4900-4fe8-ab23-9c3b2e1992cc', '518f2395-3fa0-435c-a874-ff9238fea02d', 'd', 'La línea de costado.', false, '2025-09-13 13:53:12.53701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16910e10-44e9-4b0a-8909-4825caa4d1bb', '20d7b2fa-6bd3-4b7e-b529-2b3d85140808', 'a', 'Mecha.', false, '2025-09-13 13:53:12.537281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf4e4913-d67e-4691-872f-60c52fda014c', '20d7b2fa-6bd3-4b7e-b529-2b3d85140808', 'b', 'Limera.', true, '2025-09-13 13:53:12.53741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d070a387-7d2a-48e9-951b-28c85ec88a2e', '20d7b2fa-6bd3-4b7e-b529-2b3d85140808', 'c', 'Guardines.', false, '2025-09-13 13:53:12.537546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77d3bbf6-f4c4-45ba-9942-740185214c02', '7ec8bd5c-f32e-493e-8396-5a3da6cea75e', 'b', 'Un poste de madera o de hierro que, asegurado a la cubierta en las proximidades de la proa, sirve para dar vuelta a los cables del ancla cuando se fondea la embarcación.', false, '2025-09-13 13:53:12.538095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('146cf6ea-be76-446d-98e7-5a61f3f01b81', '7487c535-5aae-4dd0-b7c0-980cf5cf098c', 'b', 'Tiene intención de fondear.', false, '2025-09-13 13:53:12.547543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06e059a5-82f7-43cc-9f5b-d6ead2d6cef2', '20d7b2fa-6bd3-4b7e-b529-2b3d85140808', 'd', 'Pala.', false, '2025-09-13 13:53:12.537679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a29876d6-20e5-4ada-8614-9008be2ad788', '7ec8bd5c-f32e-493e-8396-5a3da6cea75e', 'c', 'Una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio, sirve para amarrar los cabos.', false, '2025-09-13 13:53:12.538227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba884346-4d37-4349-bc51-d2283166a7b5', '7ec8bd5c-f32e-493e-8396-5a3da6cea75e', 'd', 'Una rueda acanalada por donde corre el cabo en un motón.', true, '2025-09-13 13:53:12.538362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fcf59ec-880f-421a-a0e1-7dfee7ffeb73', 'c972232a-c515-4346-8cd8-4870526ac5b2', 'b', 'A la hora de elegir el lugar de fondeo, uno de los aspectos fundamentales a tener en cuenta es la sonda existente en la zona.', false, '2025-09-13 13:53:12.538769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62f77c1c-4510-4fee-9ab4-5d2538387bef', 'c972232a-c515-4346-8cd8-4870526ac5b2', 'c', 'De forma general, se seleccionarán para fondear tenederos de fondo blando.', false, '2025-09-13 13:53:12.538902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d9abb89-2714-49a9-921a-7f60e1f507c4', 'c972232a-c515-4346-8cd8-4870526ac5b2', 'd', 'Hay que tomar referencias a tierra para asegurarnos que el ancla no garrea, y vigilar la sonda marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:12.539031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8016a8a7-64d1-4161-8a63-9aa05f3b8ddd', '07fcaf2d-da0d-4d05-87a4-0927f715f3a8', 'a', 'Reducir la velocidad a la mínima de gobierno.', true, '2025-09-13 13:53:12.539298+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2125b06-74c7-403d-a96f-0de4a74f15cf', '07fcaf2d-da0d-4d05-87a4-0927f715f3a8', 'b', 'Parar la arrancada.', false, '2025-09-13 13:53:12.539429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f7e5153-9ffe-4780-8259-0cc344ab2bfb', '07fcaf2d-da0d-4d05-87a4-0927f715f3a8', 'c', 'Atravesarnos a la mar.', false, '2025-09-13 13:53:12.539561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57d62291-9dd5-4a04-be1b-2b6661e8a057', '07fcaf2d-da0d-4d05-87a4-0927f715f3a8', 'd', 'Aumentar la velocidad.', false, '2025-09-13 13:53:12.539688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b428b36-dd31-408c-a1fe-9f7aaa837583', '0ede8124-2457-4a4b-a817-320b62e14cf0', 'b', 'Si no dispone de aseos, tenga mucho cuidado si decide hacer sus necesidades por la borda.', false, '2025-09-13 13:53:12.540089+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e46e34fc-0c9b-41d3-b788-16dbb38f62e0', '0ede8124-2457-4a4b-a817-320b62e14cf0', 'c', 'Agárrese al menos con una mano a la embarcación.', false, '2025-09-13 13:53:12.540217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aae7bbfd-5e57-493c-9003-3c8d75d0a2d3', '0ede8124-2457-4a4b-a817-320b62e14cf0', 'd', 'No se fíe de los candeleros.', false, '2025-09-13 13:53:12.540351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6d220cb-8261-4502-be5b-6416ebf72d23', 'd0e2a5dc-0bbe-4006-ba23-ad9005e622c5', 'a', 'Los chalecos salvavidas inflables deben ser revisados anualmente por Salvamento Marítimo.', true, '2025-09-13 13:53:12.540625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8cb66b0-8b59-4d55-977c-cf8d786e09f8', 'd0e2a5dc-0bbe-4006-ba23-ad9005e622c5', 'b', 'En navegación en zona 4 la flotabilidad mínima del chaleco será de 150N.', false, '2025-09-13 13:53:12.540755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61dfef32-f574-4170-bc50-a9f95ee7eb5c', 'd0e2a5dc-0bbe-4006-ba23-ad9005e622c5', 'd', 'La embarcación debe disponer, como mínimo, de un chaleco para cada persona a bordo adaptado a su talla, peso y edad.', false, '2025-09-13 13:53:12.541021+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c9a5bcd-c6fb-4f3e-b22d-a07dbb148ca0', '5dca3e0c-67b7-4c3a-9597-32b5f01dcf62', 'a', 'Que la estabilidad transversal se ve afectada de forma negativa.', true, '2025-09-13 13:53:12.541288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab1df05d-b695-4b40-8d25-2b70850f87e0', '5dca3e0c-67b7-4c3a-9597-32b5f01dcf62', 'b', 'Que la estabilidad longitudinal mejora significativamente.', false, '2025-09-13 13:53:12.54142+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b04db106-e195-4c3b-80f0-6eee8d8a48e7', '5dca3e0c-67b7-4c3a-9597-32b5f01dcf62', 'c', 'Que aumenta la frecuencia del balance.', false, '2025-09-13 13:53:12.541547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d3f2853-60d2-444d-9822-4e2fa7fc61b4', '5dca3e0c-67b7-4c3a-9597-32b5f01dcf62', 'd', 'Que aumenta el francobordo.', false, '2025-09-13 13:53:12.541673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cd8f842-9e1d-4a8c-9d85-fa127ead5fa1', 'fb6c1786-071b-41cf-91b5-ff48833a29b0', 'a', 'Está obligado, en cualquier circunstancia, a acudir a toda máquina en su auxilio.', true, '2025-09-13 13:53:12.541951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87f8b105-3f1e-4ab6-a68a-2efc9cc10e59', 'fb6c1786-071b-41cf-91b5-ff48833a29b0', 'b', 'La obligación de prestar auxilio es independiente de la nacionalidad y la condición jurídica de dichas personas y de las circunstancias en que hayan sido encontradas.', false, '2025-09-13 13:53:12.54208+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ad7c341-71c1-4cd1-9fc1-93cd416be032', 'fb6c1786-071b-41cf-91b5-ff48833a29b0', 'd', 'En caso de que acuda a toda máquina en su auxilio, informará de ello, si es posible, a dichas personas o al servicio de búsqueda y salvamento.', false, '2025-09-13 13:53:12.542338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2eede9f6-c187-4aa2-b888-3758cdf7225d', '8a74a274-5f55-463d-8f49-c1e969eb9fd4', 'a', '25 metros.', false, '2025-09-13 13:53:12.54261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fdfb6ecb-c894-4a85-9ede-526267d8c9a5', '8a74a274-5f55-463d-8f49-c1e969eb9fd4', 'b', '50 metros.', true, '2025-09-13 13:53:12.54274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd9cab01-8c81-4857-958a-bb6738d5f62d', '8a74a274-5f55-463d-8f49-c1e969eb9fd4', 'c', '200 metros.', false, '2025-09-13 13:53:12.542896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f150730-c659-4a72-b7eb-c4df8dabc71b', '8a74a274-5f55-463d-8f49-c1e969eb9fd4', 'd', 'A aquella que a criterio del patrón se considere suficiente para garantizar la seguridad del', false, '2025-09-13 13:53:12.543024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7689ee8f-f477-4115-a495-830518a4867a', '77cb799f-112f-4eee-98eb-7a04b43edbbc', 'a', 'Tienen la boya cilíndrica, de castillete o espeque y la marca de tope cilíndrica roja.', false, '2025-09-13 13:53:12.543292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b38b416-67a2-4da0-8878-422514cc1883', '77cb799f-112f-4eee-98eb-7a04b43edbbc', 'b', 'No se pueden utilizar para indicar la entrada de un canal, la aproximación a un puerto o estuario, o un punto de recalada.', false, '2025-09-13 13:53:12.543421+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9754406f-6ba5-49fe-9230-e6caf2b25e57', '77cb799f-112f-4eee-98eb-7a04b43edbbc', 'd', 'Se utilizan para llamar la atención sobre una característica de un canal, como una curva, una bifurcación o el final de un banco de arena.', false, '2025-09-13 13:53:12.543676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1031089e-5761-4f0d-95dd-fc676f9cd728', '80bc2759-4805-4e37-ba0a-80c712987247', 'a', 'Por un canal principal.', false, '2025-09-13 13:53:12.544013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1df469dd-43d9-4252-a481-2a8ec8d27c5c', '80bc2759-4805-4e37-ba0a-80c712987247', 'b', 'Por un canal secundario.', true, '2025-09-13 13:53:12.544153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53a09e9d-7afc-4f3f-939a-d45d0e620894', '80bc2759-4805-4e37-ba0a-80c712987247', 'c', 'Entre una Marca lateral y una Marca cardinal Norte.', false, '2025-09-13 13:53:12.544283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7ab2b8b-2c45-4de4-8ebf-8da52e10c4d8', '80bc2759-4805-4e37-ba0a-80c712987247', 'd', 'Entre una Marca lateral modificada y una Marca de peligro aislado.', false, '2025-09-13 13:53:12.544414+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4eb8f523-db56-4b18-be28-f7c626b490e8', '98f491d2-6fa6-41c4-bfb5-cafafcbde097', 'b', 'Indican una zona o una configuración particular cuya naturaleza exacta está indicada en la carta u otro documento náutico.', false, '2025-09-13 13:53:12.544827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57b0e993-2812-4f02-8c35-d8e2afd477ee', '98f491d2-6fa6-41c4-bfb5-cafafcbde097', 'c', 'También se pueden utilizar como una ayuda móvil a la navegación (MAtoN), sujetándola a objetos flotantes que pudieran suponer un peligro de colisión.', false, '2025-09-13 13:53:12.544955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85d21e7a-dbb6-4822-857f-ab344a31d298', '98f491d2-6fa6-41c4-bfb5-cafafcbde097', 'd', 'Son de color amarillo y podrán llevar una marca de tope en forma de X, preferiblemente tridimensional, para ser visible en todas las direcciones y, si tuvieran luz, esta será roja.', true, '2025-09-13 13:53:12.545091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fea550d9-1951-4e13-9263-2444eb8db4e3', '05109a24-380b-4c51-b212-3d843f3bdb40', 'a', 'Dos esferas negras superpuestas.', true, '2025-09-13 13:53:12.545358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('669a5264-b14c-42bf-a0e7-31112e775da6', '05109a24-380b-4c51-b212-3d843f3bdb40', 'b', 'Una esfera negra.', false, '2025-09-13 13:53:12.545486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88f06a93-5939-4aed-ae1e-85b8ce7a2745', '05109a24-380b-4c51-b212-3d843f3bdb40', 'c', 'Tres esferas negras superpuestas.', false, '2025-09-13 13:53:12.545615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f77ba989-1a81-494f-8937-c5ca78fd9583', '05109a24-380b-4c51-b212-3d843f3bdb40', 'd', 'Dos conos negros superpuestos.', false, '2025-09-13 13:53:12.545741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81019c4e-d126-46f6-b8ca-927d267a4eeb', '5db534af-e790-4170-b775-63cba97169b6', 'a', 'Norte.', false, '2025-09-13 13:53:12.546066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c29fff9-3ebf-48e8-a80f-4b1e2205e549', '5db534af-e790-4170-b775-63cba97169b6', 'b', 'Sur.', false, '2025-09-13 13:53:12.546197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8862c301-7d87-4348-9f95-46ed72a573ae', '5db534af-e790-4170-b775-63cba97169b6', 'c', 'Este.', false, '2025-09-13 13:53:12.546328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce6752e7-d9b0-4076-b071-08056d91d8a8', '4c52e244-28cd-4447-9422-4468a1d3d1ef', 'a', 'Mantenernos apartados de la derrota del buque a barlovento.', true, '2025-09-13 13:53:12.546734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2ab12ab-3f3f-4145-947f-a5849c35f5f1', '4c52e244-28cd-4447-9422-4468a1d3d1ef', 'b', 'Seguir a rumbo, ya que será el buque a barlovento quién deberá maniobrar.', false, '2025-09-13 13:53:12.546867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d87b2885-0197-4c78-bbb1-4d478d98bc37', '4c52e244-28cd-4447-9422-4468a1d3d1ef', 'd', 'Parar siempre nuestro buque hasta que el buque a barlovento quede en franquía.', false, '2025-09-13 13:53:12.547135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0011ca38-76d1-4936-b1cc-d64030b3bca6', 'd0e2a5dc-0bbe-4006-ba23-ad9005e622c5', 'c', 'Se deben mantener en perfectas condiciones, con las hebillas, pasadores y cierres limpios y engrasados.', false, '2025-09-13 13:53:12.540894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67aaf6bb-57a8-421a-b0f8-282ee558f721', '77cb799f-112f-4eee-98eb-7a04b43edbbc', 'c', 'Tienen la boya esférica, de castillete o espeque y la marca de tope, si la tiene, es una única esfera roja.', true, '2025-09-13 13:53:12.543548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27455350-73aa-4d3a-8722-85d6183f8b58', '98f491d2-6fa6-41c4-bfb5-cafafcbde097', 'a', 'Pueden ir con letras o numeradas y, también, pueden incluir el uso de un pictograma para indicar su finalidad, usando la simbología de la Organización Hidrográfica Internacional (OIH), cuando proceda.', false, '2025-09-13 13:53:12.544691+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4ea06d9-96a3-4bad-9e86-439f3df65cf6', '4c52e244-28cd-4447-9422-4468a1d3d1ef', 'c', 'Seguir a rumbo y realizar las señales correspondientes para avisar de nuestras intenciones si fuera necesario.', false, '2025-09-13 13:53:12.546997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3094fd67-45f4-4eb8-a361-4148659ae505', '5db534af-e790-4170-b775-63cba97169b6', 'd', 'Oeste.', true, '2025-09-13 13:53:12.546455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17b13b85-b227-486b-88fb-135ff4c15c87', '0ede8124-2457-4a4b-a817-320b62e14cf0', 'a', 'Desplácese deprisa por cubierta, alejándose de cualquier equipo de seguridad para no dañarlo en caso de caída.', true, '2025-09-13 13:53:12.539961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fac95479-1623-4fa5-8f7b-4c86738e9a50', '7487c535-5aae-4dd0-b7c0-980cf5cf098c', 'c', 'Está fondeado.', false, '2025-09-13 13:53:12.547693+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87de57b8-86b0-4cad-a815-5b40ffa634a9', '7487c535-5aae-4dd0-b7c0-980cf5cf098c', 'd', 'Está sin gobierno.', true, '2025-09-13 13:53:12.54785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69d8e3b7-bdc3-459c-95b2-37822ec162bb', '55fe78d1-d47f-4d27-8687-e96c72ae1943', 'a', 'No estorbar el tránsito del portacontenedores.', true, '2025-09-13 13:53:12.548145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f91dc106-0610-4b7f-912a-a1242fbdc6c1', '55fe78d1-d47f-4d27-8687-e96c72ae1943', 'b', 'Seguir el sentido de la corriente pasando en cualquier caso por la banda de estribor del portacontenedores.', false, '2025-09-13 13:53:12.548277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12aaa48f-f924-4f92-afd3-b32c1136d2f4', '55fe78d1-d47f-4d27-8687-e96c72ae1943', 'c', 'Hacer sonar una pitada larga cada 5 segundos y caer a babor.', false, '2025-09-13 13:53:12.548413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3ce0e88-9c26-47e9-b29d-8708c650c9be', '55fe78d1-d47f-4d27-8687-e96c72ae1943', 'd', 'No estorbar el tránsito, navegando en cualquier caso lo más cerca posible del límite exterior del canal por su costado de babor.', false, '2025-09-13 13:53:12.548554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23716441-9aa8-49af-a39a-ed4f818a1db2', 'e3d1c753-9f5e-422a-9d91-c14145d02c77', 'a', 'Deberán exhibirse a pesar de no haberse puesto el sol.', true, '2025-09-13 13:53:12.548844+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01e444e0-5a7c-4857-89ef-f1b4a69ec6fa', 'e3d1c753-9f5e-422a-9d91-c14145d02c77', 'b', 'Podrán exhibirse si el patrón lo considera necesario.', false, '2025-09-13 13:53:12.549002+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4163c09-70c9-4d1a-9133-0e456eb2e735', 'e3d1c753-9f5e-422a-9d91-c14145d02c77', 'c', 'No deberán exhibirse hasta la puesta del sol.', false, '2025-09-13 13:53:12.549139+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c215ae53-01b4-47c8-a541-00b36053cc4a', 'e3d1c753-9f5e-422a-9d91-c14145d02c77', 'd', 'Deberán exhibirse únicamente si los aguaceros van asociados a tormentas eléctricas.', false, '2025-09-13 13:53:12.549269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('421a0cfd-9b54-4731-9be8-d9bd8ef3dd5e', '8491021f-8066-4997-8861-eafb2aaa52fd', 'a', 'El buque que sigue a rumbo mantendrá siempre su rumbo y velocidad.', false, '2025-09-13 13:53:12.549577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff931b94-a16b-4b94-a749-d953847b0a0f', '8491021f-8066-4997-8861-eafb2aaa52fd', 'b', 'El buque que cede el paso no está eximido, de acuerdo con esta regla, de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:12.549713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ef2bf65-a1f5-4cb9-8598-6c517d09abb3', '8491021f-8066-4997-8861-eafb2aaa52fd', 'c', 'El buque que sigue a rumbo mantendrá siempre su rumbo, pero puede actuar variando la velocidad para ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.549873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4de27974-7aa9-4d0b-a4ca-47aa8bc2205a', '8491021f-8066-4997-8861-eafb2aaa52fd', 'd', 'El buque que cede el paso mantendrá siempre su velocidad, y actuará cambiando el rumbo para ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.550025+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bb2553d-2bb4-4dc9-8390-6e1fdef149dc', 'cb898e86-7ccb-4946-9cbe-c42029fc0667', 'a', 'Una luz blanca todo horizonte y una luz de alcance.', false, '2025-09-13 13:53:12.550305+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('388972e8-0a57-451f-a973-2c689e222798', 'cb898e86-7ccb-4946-9cbe-c42029fc0667', 'b', 'Luces de costado, una luz de alcance y una luz de remolque en línea vertical y por encima de la luz de alcance.', false, '2025-09-13 13:53:12.550439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d73da728-1bf4-4b20-8224-eddd84a2c36a', 'cb898e86-7ccb-4946-9cbe-c42029fc0667', 'c', 'Luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.55057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c1df973-88d9-4a05-a1f9-7fc6b112ccdb', 'cb898e86-7ccb-4946-9cbe-c42029fc0667', 'd', 'Luces de costado y una luz blanca todo horizonte.', false, '2025-09-13 13:53:12.550703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2317994c-e0e7-479b-8f23-6fdd44899ec5', '8b4a514c-67fd-4150-b923-b7f0cdc8ecbf', 'a', 'Deberá, en cualquier caso, utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-13 13:53:12.550978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('987ec00b-36d4-4b76-93f9-1d0f10c653eb', '8b4a514c-67fd-4150-b923-b7f0cdc8ecbf', 'b', 'Navegará exclusivamente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:12.551109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d88cbc7-7097-469f-8aea-6516a7057c3c', '8b4a514c-67fd-4150-b923-b7f0cdc8ecbf', 'd', 'Deberá en cualquier caso utilizar la zona de navegación costera.', false, '2025-09-13 13:53:12.551369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29849ffe-942f-4ca0-bfd8-432c95807ab8', '0ffa10ba-f390-4db8-90c9-b7d2dfc84124', 'a', 'Un cohete-bengala con paracaídas o una bengala de mano que produzca una luz roja.', true, '2025-09-13 13:53:12.551639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ca5da53-c2fc-4dcd-b810-b9f7ec8dc529', '0ffa10ba-f390-4db8-90c9-b7d2dfc84124', 'b', 'Una señal fumígena que produzca una densa humareda de color amarillo.', false, '2025-09-13 13:53:12.55177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72835639-f8bd-49b5-9749-79aec0058c75', '0ffa10ba-f390-4db8-90c9-b7d2dfc84124', 'c', 'La señal de peligro "AL" del Código Internacional de Señales.', false, '2025-09-13 13:53:12.5519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf33a5e3-c424-44fc-9153-27be8dbf9f72', '0ffa10ba-f390-4db8-90c9-b7d2dfc84124', 'd', 'Una señal emitida por radiotelefonía consistente en la palabra "pan-pan”.', false, '2025-09-13 13:53:12.552046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('623635fe-ca1c-47aa-a8d9-79685f18c251', '6d79a56c-839e-4f48-a415-a747f2cac33f', 'a', 'De noche, el resplandor de las luces de tierra ilumina nuestro entorno aumentando la capacidad de detección de las luces de navegación de otros buques en las inmediaciones.', false, '2025-09-13 13:53:12.552331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f046b5d2-dde1-4cc1-bba3-72b459adf890', '6d79a56c-839e-4f48-a415-a747f2cac33f', 'b', 'Se deberá aumentar al máximo la velocidad en zonas de alta densidad de tráfico para reducir el tiempo de exposición al riesgo.', false, '2025-09-13 13:53:12.552465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f23814e8-cd69-4096-86f9-36414d96c9bc', '6d79a56c-839e-4f48-a415-a747f2cac33f', 'c', 'En ningún caso se hará uso del radar para determinar con exactitud la visibilidad existente.', false, '2025-09-13 13:53:12.552599+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3831948-e341-427d-9058-57bdc0c9e81f', '6d79a56c-839e-4f48-a415-a747f2cac33f', 'd', 'Se tendrá en cuenta la posibilidad de no detectar en el radar, a distancia adecuada, buques pequeños, hielos y otros objetos flotantes.', true, '2025-09-13 13:53:12.552733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('650dbd60-e6c9-4401-b1d4-24b6a67d1f67', 'a6c4a722-302d-4439-af5a-6a8c7d5aa8ea', 'a', 'Está fondeado y las luces que muestra son adecuadas, tanto por sus características, número y su ubicación a bordo.', true, '2025-09-13 13:53:12.553027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1587778a-1b4e-4510-868b-f8367144fe48', 'a6c4a722-302d-4439-af5a-6a8c7d5aa8ea', 'b', 'Está fondeado y el número y las características de las luces que muestra son las correctas, pero la de popa debería situarse a una altura superior a la de proa.', false, '2025-09-13 13:53:12.553167+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3086b737-02a8-49f7-819b-2d9869bcfacc', 'a6c4a722-302d-4439-af5a-6a8c7d5aa8ea', 'c', 'Está mostrando luces de fondeo que no se corresponden con su eslora, ya que los de menos de 100 metros exhibirán únicamente una luz blanca todo horizonte en el lugar más visible.', false, '2025-09-13 13:53:12.553308+00');
