INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e1cc90-34ba-40df-84a9-9dc39c850a22', '182fc3f1-9369-4476-b243-c1e9564560ab', 'c', 'Si se realiza tan lejos como sea posible de la tierra más próxima, pero en ningún caso a menos de 12 millas marinas de la tierra más próxima.', false, '2025-09-13 13:53:12.574452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fb7cda4-1ce1-4f64-adee-975732eb8a6a', '182fc3f1-9369-4476-b243-c1e9564560ab', 'd', 'A cualquier distancia de la tierra más próxima, siempre que el buque esté en ruta.', false, '2025-09-13 13:53:12.574581+00');
