INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('844a31ce-1790-4a43-8dbe-1387f2075a3c', '3a53e091-75c4-4819-9cfd-7bf5c73d6053', 'a', 'Negras, con una o más bandas anchas horizontales rojas.', true, '2025-09-13 13:53:12.576813+00');
