INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39f14904-0b46-421a-af5b-166eeb26267e', 'c7062003-d754-48cc-92a8-f03896e02124', 'c', 'Se utilizan para señalizar una vía navegable.', false, '2025-09-13 13:53:12.577719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9cae070d-e710-44a2-8e14-b9b895870e0a', '8c545faa-f7e5-443e-831d-3ec27376ffe2', 'd', 'Oeste.', true, '2025-09-13 13:53:12.607393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f05c06aa-fd52-48ac-9e80-f9793f946cc0', 'c7062003-d754-48cc-92a8-f03896e02124', 'a', 'Están destinadas a señalar canales u obstrucciones, al no ofrecer el IALA alternativas más apropiadas.', false, '2025-09-13 13:53:12.577465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2126cb4b-af75-4dc6-aba5-6371b1e367d6', 'c7062003-d754-48cc-92a8-f03896e02124', 'b', 'Pueden ir con letras o numeradas y, también, pueden incluir el uso de un pictograma para indicar su finalidad, usando la simbología de la Organización Hidrográfica Internacional (OIH), cuando proceda.', true, '2025-09-13 13:53:12.577593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c4d0da4-92ed-4b38-94aa-a8c1d1095669', 'f335e54a-c919-40f4-92f9-2e203186b9a7', 'd', 'La parte del casco que está por encima de la línea de flotación.', true, '2025-09-13 13:53:12.569184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beee7903-9197-4e36-8ddc-c39fe38ab351', '198c7cd1-ebde-44fd-914b-8b5cb9aa3f38', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:12.570157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42f740d5-0d8f-499a-996d-44ad485e099b', 'c7062003-d754-48cc-92a8-f03896e02124', 'd', 'Pueden llevar una marca de tope en forma de X, preferiblemente tridimensional, para ser visible en todas las direcciones y, si tuvieran luz, ésta será blanca. Reglamento (RIPA).', false, '2025-09-13 13:53:12.577876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6530b438-761b-4d9f-9892-394e7aa5cbbe', '1b262297-ef2f-45ed-8fb5-923f14032d9a', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.57819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('175752dd-41e9-4519-92df-2e269f03b0bb', '1b262297-ef2f-45ed-8fb5-923f14032d9a', 'b', 'Si es necesario, reducir la velocidad para estudiar la situación siempre que sea posible, y maniobrar preferiblemente de forma clara y con antelación suficiente.', true, '2025-09-13 13:53:12.578326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af70ed1d-4cf2-4873-87d5-a73f5444fddd', '1b262297-ef2f-45ed-8fb5-923f14032d9a', 'c', 'Realizar pequeños cambios de rumbo y velocidad para avisar a la embarcación dedicada a la pesca de su obligación de mantenerse apartado de la derrota de nuestra embarcación.', false, '2025-09-13 13:53:12.578462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa95fdbf-a43e-43e9-b630-fc6b7035ebf8', '1b262297-ef2f-45ed-8fb5-923f14032d9a', 'd', 'Cambiar de rumbo ligeramente para desviar nuestra derrota lo menos posible y evitar al mismo tiempo el abordaje, dado que esta situación exige la obligación de maniobrar por ser embarcación de propulsión mecánica.', false, '2025-09-13 13:53:12.578594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3e5a2a5-c155-4407-89b4-c0813448cf9e', '944eff93-bcb3-4357-940d-3ec6c1079bf1', 'a', 'Un destello para indicar “caigo a babor”.', false, '2025-09-13 13:53:12.578881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4da7a13b-5447-4b32-988b-6271cf3ea91c', '944eff93-bcb3-4357-940d-3ec6c1079bf1', 'b', 'Un destello de duración aproximada de un segundo para indicar “caigo a estribor”.', true, '2025-09-13 13:53:12.579019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5d14f84-15b8-4049-b640-134c3ddbd2d4', '944eff93-bcb3-4357-940d-3ec6c1079bf1', 'c', 'Dos destellos de aproximadamente un segundo de duración para indicar “estoy dando atrás”.', false, '2025-09-13 13:53:12.579151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7593f15-bafc-4b67-a72d-ebdc3b5d507f', '944eff93-bcb3-4357-940d-3ec6c1079bf1', 'd', 'Dos destellos para indicar “caigo a estribor”.', false, '2025-09-13 13:53:12.579281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9766f39-3a8b-4f76-af27-e370a7ece376', '011299c5-86e5-4951-afa5-84613d6310bf', 'a', 'Cada uno de nosotros caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:12.579581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a228fe30-1480-420d-9707-dbe86b2178ed', '011299c5-86e5-4951-afa5-84613d6310bf', 'b', 'Hay que esperar a que el otro nos maniobre.', false, '2025-09-13 13:53:12.579721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cdb5349c-30d4-4dea-ae1b-6455d44eec7e', '011299c5-86e5-4951-afa5-84613d6310bf', 'c', 'Acordaremos por radio que uno de nosotros caerá a estribor y el otro caerá a babor.', false, '2025-09-13 13:53:12.579855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddbc80bc-aab2-43e4-8ad7-f363ac8688a0', '011299c5-86e5-4951-afa5-84613d6310bf', 'd', 'Cada uno de nosotros caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:12.579987+00');
