INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e651d04e-f41a-4ed1-b465-3ebc4753316f', '5bd24b63-6e5a-477e-a706-7ab24eaf5cd7', 'd', 'El propietario o capitán de un buque sin gobierno estará exento de seguir lo estipulado en este', false, '2025-09-13 13:53:12.583359+00');
