INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25573f75-fbda-42e3-89e9-1a32b326d578', '5a7d5d9d-c115-4635-9c8e-05da7b61f5d7', 'b', 'A la hora de elegir el lugar de fondeo, uno de los aspectos fundamentales a tener en cuenta es la sonda existente en la zona.', false, '2025-09-13 13:53:12.600441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b352d6e-bc01-48e5-856e-aff72dfba672', '5a7d5d9d-c115-4635-9c8e-05da7b61f5d7', 'c', 'De forma general, se seleccionarán para fonderar tenederos de fondo blando.', false, '2025-09-13 13:53:12.600569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c0f9397-a5ee-4c1f-baf2-64c360897958', '5a7d5d9d-c115-4635-9c8e-05da7b61f5d7', 'd', 'Hay que tomar referencias a tierra para asegurarnos que el ancla no garrea, y vigilar la sonda marcando un fondo mínimo con la alarma.', false, '2025-09-13 13:53:12.600702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa39d53c-8e55-4b22-923e-7e95820ee26a', '677e77b0-9793-415c-8d43-d38660821a59', 'b', 'Un poste de madera o de hierro que, asegurado a la cubierta en las proximidades de la proa, sirve para dar vuelta a los cables del ancla cuando se fondea la embarcación.', false, '2025-09-13 13:53:12.601127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0a556a1-05b7-44c9-9886-b8cd76e75ba8', '677e77b0-9793-415c-8d43-d38660821a59', 'c', 'Una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio, sirve para amarrar los cabos.', false, '2025-09-13 13:53:12.601259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2970ff4d-2208-484d-9147-e723258f3f3e', '677e77b0-9793-415c-8d43-d38660821a59', 'd', 'Una rueda acanalada por donde corre el cabo en un motón.', true, '2025-09-13 13:53:12.601391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ef30d74-2257-4e50-ba9b-35f7201e31bd', '2d130dbd-f1df-4750-af68-8f435fa17670', 'b', 'Si no dispone de aseos, tenga mucho cuidado si decide hacer sus necesidades por la borda.', false, '2025-09-13 13:53:12.601791+00');
