INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c47f385-6828-47b2-a248-d63a14b7da8d', '2d130dbd-f1df-4750-af68-8f435fa17670', 'd', 'No se fíe de los candeleros.', false, '2025-09-13 13:53:12.602068+00');
