INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a104e040-ae0a-47eb-9f3d-048b6858b2d8', 'f9875bff-f705-41b0-af62-c474f45f8866', 'a', 'Los chalecos salvavidas inflables deben ser revisados anualmente por Salvamento Marítimo.', true, '2025-09-13 13:53:12.602996+00');
