INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9556a603-1b8e-45b5-9c52-0ec5a09e08a1', 'f9875bff-f705-41b0-af62-c474f45f8866', 'd', 'La embarcación debe disponer, como mínimo, de un chaleco para cada persona a bordo adaptado a su talla, peso y edad.', false, '2025-09-13 13:53:12.603387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7385a18a-c085-4ec0-a6da-603cd7f55188', 'cf3f988c-1a3d-4845-bd18-d82b2eff1f67', 'a', 'Que la estabilidad transversal se ve afectada de forma negativa.', true, '2025-09-13 13:53:12.60368+00');
