INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ad9abf5-fe95-4bfa-aa48-bd60a2411aae', 'cf3f988c-1a3d-4845-bd18-d82b2eff1f67', 'c', 'Que aumenta la frecuencia del balance.', false, '2025-09-13 13:53:12.603943+00');
