INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('531e6272-de5d-4288-bfdb-e274c4bbe1c4', 'f483d745-8c06-43cd-8916-6db553c6972e', 'a', 'Está obligado, en cualquier circunstancia, a acudir a toda máquina en su auxilio.', true, '2025-09-13 13:53:12.60435+00');
