INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25cdafcb-d104-4f23-a115-34437c5bdb45', 'f483d745-8c06-43cd-8916-6db553c6972e', 'd', 'En caso de que acuda a toda máquina en su auxilio, informará de ello, si es posible, a dichas personas o al servicio de búsqueda y salvamento.', false, '2025-09-13 13:53:12.604734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('771e5ed7-b029-46a3-94ee-c218aa8ff8ec', '16f3ef5e-4818-46c5-914e-ea6756ce6f5e', 'a', '25 metros.', false, '2025-09-13 13:53:12.605003+00');
