INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('708e9f89-ccea-4ab1-88da-e56ad9d11975', '943455ea-26a5-43fd-a6bc-13fc2d00a9a8', 'b', 'Una esfera negra.', false, '2025-09-13 13:53:12.607834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e936fb12-6611-4581-849a-df39dc1cbbc7', '943455ea-26a5-43fd-a6bc-13fc2d00a9a8', 'c', 'Tres esferas negras superpuestas.', false, '2025-09-13 13:53:12.607986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c35678dc-b2e8-48fa-a80d-62036788e770', '943455ea-26a5-43fd-a6bc-13fc2d00a9a8', 'd', 'Dos conos negros superpuestos.', false, '2025-09-13 13:53:12.608123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d765f8fd-a23c-464c-bad0-692b1f8fbea9', '96d813fd-3139-4281-80ee-cfd5110dfdb2', 'a', 'Tienen la boya cilíndrica, de castillete o espeque y la marca de tope cilíndrica roja.', false, '2025-09-13 13:53:12.608416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('679c5d12-aa94-4c88-9963-6f9a3ab9879e', '96d813fd-3139-4281-80ee-cfd5110dfdb2', 'b', 'No se pueden utilizar para indicar la entrada de un canal, la aproximación a un puerto o estuario, o un punto de recalada.', false, '2025-09-13 13:53:12.608553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b51d2ad-afbf-41ce-a598-1449c13cae00', '96d813fd-3139-4281-80ee-cfd5110dfdb2', 'd', 'Se utilizan para llamar la atención sobre una característica de un canal, como una curva, una bifurcación o el final de un banco de arena. Reglamento (RIPA).', false, '2025-09-13 13:53:12.608825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c51eb2d-18a3-45ec-b3c5-0284c876c7b6', 'e4831855-c930-4590-aba6-eb938e3d7532', 'a', 'El buque que sigue a rumbo mantendrá siempre su rumbo y velocidad.', false, '2025-09-13 13:53:12.609108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('954a74ba-ebe5-4112-b57b-be1db6ca6a07', 'e4831855-c930-4590-aba6-eb938e3d7532', 'b', 'El buque que cede el paso no está eximido, de acuerdo con esta regla, de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:12.609243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('427bbd7f-4b14-40a4-96bb-095911471c8d', 'e4831855-c930-4590-aba6-eb938e3d7532', 'c', 'El buque que sigue a rumbo mantendrá siempre su rumbo, pero puede actuar variando la velocidad para ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.609377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b9c41f8-d5e9-4514-ab35-c63d90134ef4', 'e4831855-c930-4590-aba6-eb938e3d7532', 'd', 'El buque que cede el paso mantendrá siempre su velocidad, y actuará cambiando el rumbo para ayudar a evitar el abordaje.', false, '2025-09-13 13:53:12.609511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cefdca71-1832-48f7-b432-a7f0130accbc', '3939136e-f188-4b3f-ac4e-f70c46f2b7b4', 'a', 'Está fondeado y las luces que muestra son adecuadas, tanto por sus características, número y su ubicación a bordo.', true, '2025-09-13 13:53:12.609823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44f3ae78-e25c-40c6-b8e9-764e9e56caf5', '3939136e-f188-4b3f-ac4e-f70c46f2b7b4', 'b', 'Está fondeado y el número y las características de las luces que muestra son las correctas, pero la de popa debería situarse a una altura superior a la de proa.', false, '2025-09-13 13:53:12.60997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45ceac26-29ed-4e0a-8406-ef44a741533e', '3939136e-f188-4b3f-ac4e-f70c46f2b7b4', 'c', 'Está mostrando luces de fondeo que no se corresponden con su eslora, ya que los de menos de 100 metros exhibirán únicamente una luz blanca todo horizonte en el lugar más visible.', false, '2025-09-13 13:53:12.610104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6b97aa1-9cb9-4c98-ade5-c3666d1bd301', '3939136e-f188-4b3f-ac4e-f70c46f2b7b4', 'd', 'Está varado.', false, '2025-09-13 13:53:12.610237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3090cc88-ed89-44b0-9541-3ee5b63678f0', 'dbd143b0-ac38-4284-9ff9-7137941a21b4', 'a', 'De noche, el resplandor de las luces de tierra ilumina nuestro entorno aumentando la capacidad de detección de las luces de navegación de otros buques en las inmediaciones.', false, '2025-09-13 13:53:12.610513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c70b1fd8-f390-443e-817e-d9e1b24dc8a3', 'dbd143b0-ac38-4284-9ff9-7137941a21b4', 'b', 'Se deberá aumentar al máximo la velocidad en zonas de alta densidad de tráfico para reducir el tiempo de exposición al riesgo.', false, '2025-09-13 13:53:12.610645+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('537ae1c2-ce41-44f3-96e5-0b9578bf9f60', 'dbd143b0-ac38-4284-9ff9-7137941a21b4', 'c', 'En ningún caso se hará uso del radar para determinar con exactitud la visibilidad existente.', false, '2025-09-13 13:53:12.610786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6205c2d-b390-4725-b50f-db8d3c5cf24d', 'dbd143b0-ac38-4284-9ff9-7137941a21b4', 'd', 'Se tendrá en cuenta la posibilidad de no detectar en el radar, a distancia adecuada, buques pequeños, hielos y otros objetos flotantes.', true, '2025-09-13 13:53:12.610917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58be6ea4-5822-49ce-beaf-2e2fd29c2a2d', 'ac686b67-39ae-42ce-92bc-a0dbc89ce020', 'a', 'Deberá, en cualquier caso, utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-13 13:53:12.611191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2636bc6-4e14-4472-bc56-8b332039c53a', 'ac686b67-39ae-42ce-92bc-a0dbc89ce020', 'b', 'Navegará exclusivamente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:12.611321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce7614e4-22b2-4e82-956f-e8f64b0b2e0a', 'ac686b67-39ae-42ce-92bc-a0dbc89ce020', 'd', 'Deberá en cualquier caso utilizar la zona de navegación costera.', false, '2025-09-13 13:53:12.61158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d89555db-c9ab-47ef-a693-664d57b32125', 'd2c54e5d-f703-4e42-8e84-402220761634', 'a', 'Deberán exhibirse a pesar de no haberse puesto el sol.', true, '2025-09-13 13:53:12.611855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26b7b7e2-4b69-4ea0-aa4d-ec666fd72440', 'd2c54e5d-f703-4e42-8e84-402220761634', 'b', 'Podrán exhibirse si el patrón lo considera necesario.', false, '2025-09-13 13:53:12.611989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75a90e0e-f994-4fa7-bd32-5e6399c579a8', 'd2c54e5d-f703-4e42-8e84-402220761634', 'c', 'No deberán exhibirse hasta la puesta del sol.', false, '2025-09-13 13:53:12.612118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c2cdee1-67ea-453a-b98f-3136bb88e73a', 'd2c54e5d-f703-4e42-8e84-402220761634', 'd', 'Deberán exhibirse únicamente si los aguaceros van asociados a tormentas eléctricas.', false, '2025-09-13 13:53:12.612248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76ea0dd9-0f45-4819-86c0-1c999da9eeae', '06a82377-4ef7-456e-813b-b181624794bf', 'a', 'Un cohete-bengala con paracaídas o una bengala de mano que produzca una luz roja.', true, '2025-09-13 13:53:12.612524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2564abaa-4f1c-47ae-b110-b61ffab6388d', '06a82377-4ef7-456e-813b-b181624794bf', 'b', 'Una señal fumígena que produzca una densa humareda de color amarillo.', false, '2025-09-13 13:53:12.612653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1133d5a5-95e3-4b21-8555-e5fdbcfc3284', '06a82377-4ef7-456e-813b-b181624794bf', 'c', 'La señal de peligro "AL" del Código Internacional de Señales.', false, '2025-09-13 13:53:12.612782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c12435ce-988a-4ea0-b89a-80416292be15', '06a82377-4ef7-456e-813b-b181624794bf', 'd', 'Una señal emitida por radiotelefonía consistente en la palabra "pan-pan”.', false, '2025-09-13 13:53:12.612912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9795b61-5ae0-4f4d-a2ca-35f90fcfb3e8', '033dcda4-5b7b-4a58-8bf6-eacaa0029c6e', 'a', 'Es un buque de gran calado y está restringido por el mismo.', false, '2025-09-13 13:53:12.613181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c118803d-139a-4d23-bbf2-8d45898f3c5a', '033dcda4-5b7b-4a58-8bf6-eacaa0029c6e', 'b', 'Tiene intención de fondear.', false, '2025-09-13 13:53:12.613312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a59b9ee8-d1f7-46e9-9e6e-cb51fde09969', '033dcda4-5b7b-4a58-8bf6-eacaa0029c6e', 'c', 'Está fondeado.', false, '2025-09-13 13:53:12.613439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef85c298-b7ef-43c9-afba-b16ca0aedc20', '033dcda4-5b7b-4a58-8bf6-eacaa0029c6e', 'd', 'Está sin gobierno.', true, '2025-09-13 13:53:12.613579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bad97a6c-64c9-4f95-b00b-1126a58a07f8', '702ddbd4-2f27-4724-8710-d22ad1322958', 'a', 'Una luz blanca todo horizonte y una luz de alcance.', false, '2025-09-13 13:53:12.613865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('357a6db4-f8a8-46e6-b513-e59daee26712', '702ddbd4-2f27-4724-8710-d22ad1322958', 'b', 'Luces de costado, una luz de alcance y una luz de remolque en línea vertical y por encima de la luz de alcance.', false, '2025-09-13 13:53:12.614015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ce7e4ac-3342-4aa2-9b24-1c92c70eca83', '702ddbd4-2f27-4724-8710-d22ad1322958', 'c', 'Luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.614147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48061a24-9198-4e51-8f60-c41baf3ece91', '702ddbd4-2f27-4724-8710-d22ad1322958', 'd', 'Luces de costado y una luz blanca todo horizonte.', false, '2025-09-13 13:53:12.614277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48785036-334f-42c8-bc51-2963cdc1c0af', '2a68f0b4-11f6-47f6-b91d-2e1ebd4cccac', 'a', 'Mantenernos apartados de la derrota del buque a barlovento.', true, '2025-09-13 13:53:12.615367+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('748c4057-73ba-4283-94a9-1d9d2ffd3b2f', '2a68f0b4-11f6-47f6-b91d-2e1ebd4cccac', 'b', 'Seguir a rumbo, ya que será el buque a barlovento quién deberá maniobrar.', false, '2025-09-13 13:53:12.615506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c9ac0fa-6136-4f52-a018-68b5dd0b39b5', 'd1e7ea43-0ae4-41ed-9480-710853fb2b54', 'a', 'La popa e impide el movimiento por el que se aleja la popa de la embarcación del muelle.', false, '2025-09-13 13:53:12.616065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('714c4a67-9ae7-43df-acf9-34b414cf9750', 'd1e7ea43-0ae4-41ed-9480-710853fb2b54', 'b', 'La proa e impide el movimiento hacia la proa.', true, '2025-09-13 13:53:12.616198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce8ed7ba-819f-4582-b211-3e8a1ccbf9e3', 'd1e7ea43-0ae4-41ed-9480-710853fb2b54', 'c', 'La proa e impide el movimiento hacia la popa.', false, '2025-09-13 13:53:12.616344+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79a70ee7-2f5d-4a09-8bf0-fd1fb53379dc', 'ac686b67-39ae-42ce-92bc-a0dbc89ce020', 'c', 'Quedará exento del cumplimiento de esta regla en la medida necesaria para llevar a cabo dicha operación.', true, '2025-09-13 13:53:12.611451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2a9e64f-b45c-4c0a-8427-31b313ce46f9', '2a68f0b4-11f6-47f6-b91d-2e1ebd4cccac', 'c', 'Seguir a rumbo y realizar las señales correspondientes para avisar de nuestras intenciones si fuera necesario.', false, '2025-09-13 13:53:12.615641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a86df88f-2c2d-44fc-a48b-04e2fc2ca0b2', '2a68f0b4-11f6-47f6-b91d-2e1ebd4cccac', 'd', 'Parar siempre nuestro buque hasta que el buque a barlovento quede en franquía.', false, '2025-09-13 13:53:12.615769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94021255-ef70-4b32-9254-5ecd1ff76b43', '96d813fd-3139-4281-80ee-cfd5110dfdb2', 'c', 'Tienen la boya esférica, de castillete o espeque y la marca de tope, si la tiene, es una única esfera roja.', true, '2025-09-13 13:53:12.608689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a626f1b6-31db-4ec9-ba58-893e7a012e99', 'd1e7ea43-0ae4-41ed-9480-710853fb2b54', 'd', 'La proa e impide el movimiento por el que se aleja la popa de la embarcación del muelle.', false, '2025-09-13 13:53:12.616481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a6d3758-4f1b-4425-974c-ed6f3b0fa2b4', 'dba2c0a9-026a-46d9-8ddc-a20049d133d5', 'a', 'Aumento de velocidad, desplazamiento lateral y escora, ambos a la banda de metida.', false, '2025-09-13 13:53:12.616805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb17215f-a105-47e5-bc4d-883fa4342db9', 'dba2c0a9-026a-46d9-8ddc-a20049d133d5', 'b', 'Pérdida de velocidad, desplazamiento lateral a la banda contraria y escora a la banda de metida.', true, '2025-09-13 13:53:12.616943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4abf40af-3191-4a00-9862-a86dc7a806c0', 'dba2c0a9-026a-46d9-8ddc-a20049d133d5', 'c', 'Aumento de velocidad, desplazamiento lateral a la banda contraria y escora a la banda de metida.', false, '2025-09-13 13:53:12.61708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e411f03-e622-4e9f-b6d4-d346dfda2aba', 'dba2c0a9-026a-46d9-8ddc-a20049d133d5', 'd', 'Pérdida de velocidad, desplazamiento lateral y escora, ambos a la banda contraria. Emergencias en la mar.', false, '2025-09-13 13:53:12.617212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5b71c13-6a98-43c8-9e34-925e030e5914', '38c5151a-0981-419e-bba9-feddafa92982', 'a', 'La investigación de la gravedad de las averías sufridas en las embarcaciones.', false, '2025-09-13 13:53:12.6175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2feb3f49-5e4c-4aa6-b99c-b37543ebb489', '38c5151a-0981-419e-bba9-feddafa92982', 'b', 'La comunicación del abordaje al Centro de Coordinación de Salvamento.', false, '2025-09-13 13:53:12.61763+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16edb690-9f6b-497f-82e4-289a37c13174', '38c5151a-0981-419e-bba9-feddafa92982', 'c', 'El cierre de los compartimentos estancos de las embarcaciones.', false, '2025-09-13 13:53:12.617759+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34d1ef57-2b5a-47d0-ab4b-a676b0e2f6ac', '38c5151a-0981-419e-bba9-feddafa92982', 'd', 'La separación de las embarcaciones sin evaluar previamente las averías sufridas.', true, '2025-09-13 13:53:12.6179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd6fa867-3603-46c1-b45f-0454e0a16c41', '7c697436-112b-4bfc-bb8c-265ebd3286a4', 'a', 'Dar pequeños sorbos de agua fresca.', false, '2025-09-13 13:53:12.618199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63ab526a-d283-44a4-98b7-70248c3875b4', '7c697436-112b-4bfc-bb8c-265ebd3286a4', 'b', 'Llevar a un lugar fresco, seco y bien ventilado, para que le baje la temperatura.', false, '2025-09-13 13:53:12.618334+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e213044-d2c9-4ed2-b2e0-c75fd700436a', '7c697436-112b-4bfc-bb8c-265ebd3286a4', 'c', 'Acostar en horizontal, salvo si pierde el conocimiento; en este caso se colocará en la posición lateral de seguridad.', true, '2025-09-13 13:53:12.618469+00');
