INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ee55ea7-5f92-4228-898c-6c09cbcb97ac', 'b114dd92-cbc5-48da-86a9-b7f2aa3c1e56', 'b', 'Atar las escotas y brazas.', false, '2025-09-13 13:53:12.631635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78f37d62-2da9-4605-acc7-fc89a16f1780', 'b114dd92-cbc5-48da-86a9-b7f2aa3c1e56', 'c', 'Afirmar rápidamente un cabo a un palo, cáncamo o argolla.', true, '2025-09-13 13:53:12.63177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d5f4f58-8498-413f-9123-25386ad0a7a0', 'b114dd92-cbc5-48da-86a9-b7f2aa3c1e56', 'd', 'Unir por sus chicotes dos cabos de una misma mena.', false, '2025-09-13 13:53:12.631904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('200c2e6e-9dde-4dd0-b710-64a6ac659546', '1a8ffaa8-8ce2-4447-af78-65864da24ece', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no garrea, y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-13 13:53:12.63231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1eed3fd6-4ea2-458a-a038-0e320a99fe81', '1a8ffaa8-8ce2-4447-af78-65864da24ece', 'c', 'Si se opta por el fondeo a la gira, se utilizarán dos anclas de forma que las líneas de fondeo formen un ángulo de entre 90º y 120º.', false, '2025-09-13 13:53:12.632438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a8292ba-8c0c-4fff-a101-3e4517e67564', '1a8ffaa8-8ce2-4447-af78-65864da24ece', 'd', 'Nuestra embarcación debe disponer de una línea de fondeo cuya longitud será tres veces la', false, '2025-09-13 13:53:12.632565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a6a9aee-87e7-42d1-9218-a670c12d4e36', 'c47b9357-5663-4073-b724-ea8655178912', 'a', 'Todos los grifos de fondo estén cerrados.', false, '2025-09-13 13:53:12.632833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33b76299-5520-4320-a72c-5841e03366d8', 'c47b9357-5663-4073-b724-ea8655178912', 'b', 'Todas las lumbreras están herméticamente cerradas.', false, '2025-09-13 13:53:12.632962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4f1e73d-166b-4f90-9a39-fc289826dc57', 'c47b9357-5663-4073-b724-ea8655178912', 'c', 'Se ha comunicado el Plan de navegación a alguien en tierra.', true, '2025-09-13 13:53:12.63309+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('beb06f15-83a0-4a42-bbf0-f688f1761ac3', 'c47b9357-5663-4073-b724-ea8655178912', 'd', 'La batería del móvil está cargada, para utilizarlo siempre como vía para realizar una llamada de', false, '2025-09-13 13:53:12.633217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb648226-86ab-481d-a338-2d42fc5369cb', 'e68d0f89-ee31-4c11-b156-45a7eb09e41b', 'a', 'Llame por teléfono al 112.', false, '2025-09-13 13:53:12.633483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73c6b80e-399d-4348-8acf-54572368e9a5', 'e68d0f89-ee31-4c11-b156-45a7eb09e41b', 'b', 'Llame por teléfono al 900 202 202.', false, '2025-09-13 13:53:12.633613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('528c8ee8-77b3-464d-b3f8-c0e076705744', 'e68d0f89-ee31-4c11-b156-45a7eb09e41b', 'c', 'Realice una llamada de voz por el canal 70 de VHF.', true, '2025-09-13 13:53:12.633744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62bff705-563e-4001-9803-185ea6c46a1c', 'e68d0f89-ee31-4c11-b156-45a7eb09e41b', 'd', 'Utilice los procedimientos internacionales reglamentados para ello.', false, '2025-09-13 13:53:12.633896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('393c74fd-b8ad-4034-a83a-8389b725fec6', '6760192c-3590-41c2-a06c-2a0c777393fb', 'a', 'Deben colocarse en la proa sujetos por medios de fijación permanente.', false, '2025-09-13 13:53:12.634184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4ffbb02-99d9-462b-8a9a-5784b54835e5', '6760192c-3590-41c2-a06c-2a0c777393fb', 'b', 'Si pierde un aro salvavidas en el mar no debe tomar ninguna acción mientras siga teniendo aros salvavidas suficientes a bordo.', false, '2025-09-13 13:53:12.63432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('484cefaa-d0b5-40a8-8178-51e367cfdeda', '6760192c-3590-41c2-a06c-2a0c777393fb', 'c', 'No deben ir identificados con el nombre de la embarcación, ya que deben cumplir un estándar igual para todos.', false, '2025-09-13 13:53:12.634454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70de5e54-5299-4efd-b66b-365f6ea66c36', '6760192c-3590-41c2-a06c-2a0c777393fb', 'd', 'Deben colocarse en las bandas (aletas) o en popa y estibados de modo que sea posible soltarlos', true, '2025-09-13 13:53:12.634587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('227b572a-c000-4706-8410-ae0d89a22710', '0dd6b6e4-afea-49b9-8b62-9b5df2c22b58', 'a', 'Corriendo el temporal.', false, '2025-09-13 13:53:12.634881+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a944c1c-a981-4641-b302-397ef8c9fc90', '0dd6b6e4-afea-49b9-8b62-9b5df2c22b58', 'b', 'Capeando el temporal.', true, '2025-09-13 13:53:12.635018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e92d4e1d-8e6d-4309-8c30-751da7372048', '0dd6b6e4-afea-49b9-8b62-9b5df2c22b58', 'c', 'Navegando a son de mar.', false, '2025-09-13 13:53:12.635154+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0be287bb-b474-44b8-81e2-11d84a43b74f', '0dd6b6e4-afea-49b9-8b62-9b5df2c22b58', 'd', 'Ciñendo.', false, '2025-09-13 13:53:12.635291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8caf704f-62d5-4d62-b119-e5d5cdacd285', '5884fde8-a948-4cec-9456-bb07494ac0d3', 'a', '3 días hábiles.', false, '2025-09-13 13:53:12.635577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9257c779-b0ff-44b1-8214-ae9722953b32', '5884fde8-a948-4cec-9456-bb07494ac0d3', 'b', '5 días hábiles.', true, '2025-09-13 13:53:12.635712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dac25a0b-2697-4f56-b9eb-1a38c93fa74c', '5884fde8-a948-4cec-9456-bb07494ac0d3', 'c', '10 días hábiles.', false, '2025-09-13 13:53:12.635852+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('872f325a-de1a-4891-91bb-499c0152613a', '5884fde8-a948-4cec-9456-bb07494ac0d3', 'd', 'No hay plazo, puesto que la ausencia a bordo de la documentación motiva una sanción inmediata.', false, '2025-09-13 13:53:12.635986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fa3240d-684e-4ddc-9e28-fe33f42a3031', 'd84bcd22-bda7-485c-9116-61b8a5333407', 'a', 'A cualquier distancia de la tierra más próxima, siempre que los desechos puedan pasar por cribas con mallas de una abertura mínima de 50 mm.', false, '2025-09-13 13:53:12.636262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75b56716-b78d-4128-bbff-b67c8ab3e6d0', 'd84bcd22-bda7-485c-9116-61b8a5333407', 'b', 'Estando la embarcación en ruta al menos a tres millas marinas de la tierra más próxima y siempre que los desechos puedan pasar por cribas con mallas de una abertura máxima de 25 mm.', true, '2025-09-13 13:53:12.636397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45dc8ebb-ec20-458f-a719-ecc6bab44571', 'd84bcd22-bda7-485c-9116-61b8a5333407', 'c', 'Si se realiza tan lejos como sea posible de la tierra más próxima, pero en ningún caso a menos de 12 millas marinas de la tierra más próxima.', false, '2025-09-13 13:53:12.636532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4eea0d87-c6de-43f0-b76b-315307748273', 'd84bcd22-bda7-485c-9116-61b8a5333407', 'd', 'A cualquier distancia de la tierra más próxima, siempre que el buque esté en ruta.', false, '2025-09-13 13:53:12.636665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e7e4b64-cf44-4849-b62b-168e4a3feae2', '0627ac2a-f543-479a-aa07-b4f18318e431', 'a', 'Definir los ejes de los canales y las marcas de centro del canal.', true, '2025-09-13 13:53:12.636953+00');
