INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7707e6bb-416b-4fd6-ae57-992caec9d22e', '0627ac2a-f543-479a-aa07-b4f18318e431', 'c', 'Indicar el lado de la marca por el que se debe pasar.', false, '2025-09-13 13:53:12.637235+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5351b299-4ad2-42cb-ac39-4dc98c1daf3a', '0627ac2a-f543-479a-aa07-b4f18318e431', 'd', 'Señalizar los límites de las áreas de fondeo.', false, '2025-09-13 13:53:12.637369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f170e9c-9cfd-42ac-a2b0-e9fe79b5ad23', 'bcef6568-a562-4217-8c85-9936cc55bbbe', 'd', 'Imbornales.', false, '2025-09-13 13:53:12.631231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1e695c6-99ca-4fdf-b9b6-dc92f28e60b6', '1a8ffaa8-8ce2-4447-af78-65864da24ece', 'a', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-13 13:53:12.632181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03d89b2d-9ec6-4585-98cf-cda7cfe5574a', 'd619b1c4-1ee2-4b35-9165-09d30493cc93', 'a', 'Negras, con una o más bandas anchas horizontales rojas.', true, '2025-09-13 13:53:12.637647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('790b0038-10f4-4c3a-bd26-1b0e0e329164', 'd619b1c4-1ee2-4b35-9165-09d30493cc93', 'b', 'Amarillas, con una o más bandas anchas horizontales negras.', false, '2025-09-13 13:53:12.637787+00');
