INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68596641-eafe-421b-bd92-d6404f02415c', 'd619b1c4-1ee2-4b35-9165-09d30493cc93', 'd', 'Rojas, con una o más bandas anchas verticales negras.', false, '2025-09-13 13:53:12.638072+00');
