INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20390e32-7e08-44a3-9623-3d54f7852a64', '1579d3c0-39ab-4be1-ba86-e1f418e81726', 'a', 'Con los vértices hacia arriba.', false, '2025-09-13 13:53:12.639189+00');
