INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2aba8b16-a5fc-4bc2-8f48-24e99917eefd', '2e806389-9504-44dd-9398-0905901b0385', 'c', 'Una embarcación de prácticos que navega por el canal de vuelta encontrada.', true, '2025-09-13 13:53:12.642513+00');
