INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70cafdfd-e285-4903-9e1b-6dc3ac0179f6', '25773b0e-1c5e-49ed-a0b3-8e59836fd83c', 'a', 'El buque de propulsión mecánica en navegación.', false, '2025-09-13 13:53:12.642934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f24a4e6e-11de-421e-b8e6-af0a7e850a07', '25773b0e-1c5e-49ed-a0b3-8e59836fd83c', 'b', 'El buque dedicado a la pesca.', true, '2025-09-13 13:53:12.643068+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9d74ab7-413b-40d5-bc16-298ac0423d91', '25773b0e-1c5e-49ed-a0b3-8e59836fd83c', 'c', 'El hidroavión amarado.', false, '2025-09-13 13:53:12.643199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('722347c7-7c0b-4cae-a38b-d67dbc765fa3', '25773b0e-1c5e-49ed-a0b3-8e59836fd83c', 'd', 'El buque de vela.', false, '2025-09-13 13:53:12.643328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edfe6f74-d237-4514-b897-fbef7de889e4', 'd162ae5d-b732-4491-8d2b-c967b3e94aef', 'a', 'Cada uno de nosotros caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:12.643604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f4f8774-8a96-4e06-b41d-e977a1fcdc19', 'd162ae5d-b732-4491-8d2b-c967b3e94aef', 'b', 'Hay que esperar a que el otro nos maniobre.', false, '2025-09-13 13:53:12.643736+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31a7885d-d20f-42ae-9292-0312c20d648f', 'd162ae5d-b732-4491-8d2b-c967b3e94aef', 'c', 'Acordaremos por radio que uno de nosotros caerá a estribor y el otro caerá a babor.', false, '2025-09-13 13:53:12.643868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('795374f3-83ce-4e64-90ce-72b0e49bca19', 'd162ae5d-b732-4491-8d2b-c967b3e94aef', 'd', 'Cada uno de nosotros caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:12.644029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d16cb3e-448b-49c7-be97-9147083e3782', 'a9bb1555-c324-4ceb-8803-e0207ba46c56', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.644339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e4119cf-c21e-4d92-a410-d37de19c2332', 'a9bb1555-c324-4ceb-8803-e0207ba46c56', 'b', 'Si es necesario, reducir la velocidad para estudiar la situación siempre que sea posible, y maniobrar preferiblemente de forma clara y con antelación suficiente.', true, '2025-09-13 13:53:12.644483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef88f851-c5f9-48a6-9044-1ae42f980fb2', 'a9bb1555-c324-4ceb-8803-e0207ba46c56', 'c', 'Realizar pequeños cambios de rumbo y velocidad para avisar a la embarcación dedicada a la pesca de su obligación de mantenerse apartado de la derrota de nuestra embarcación.', false, '2025-09-13 13:53:12.644633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11133a57-74d1-41fe-bf82-af409e3ac90d', 'a9bb1555-c324-4ceb-8803-e0207ba46c56', 'd', 'Cambiar de rumbo ligeramente para desviar nuestra derrota lo menos posible y evitar al mismo tiempo el abordaje, dado que esta situación exige la obligación de maniobrar por ser embarcación de propulsión mecánica.', false, '2025-09-13 13:53:12.644781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('106634af-872c-44ad-8136-c5700565fd54', '89f0309b-2140-49ae-a32b-906b94cf5e09', 'a', 'Buque de vela.', true, '2025-09-13 13:53:12.645085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96096b64-4725-4966-a7d8-62a2036bd6b8', '89f0309b-2140-49ae-a32b-906b94cf5e09', 'b', 'Buque dedicado a operaciones de limpieza de minas.', false, '2025-09-13 13:53:12.64522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9ada725-e32e-4098-a091-d89f6a27bd72', '89f0309b-2140-49ae-a32b-906b94cf5e09', 'c', 'Buque dedicado a dragados.', false, '2025-09-13 13:53:12.645352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6ab7335-fe3a-412e-a36a-055d2586c670', '89f0309b-2140-49ae-a32b-906b94cf5e09', 'd', 'Buque en navegación haciendo combustible.', false, '2025-09-13 13:53:12.645484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5cf1192-a1cb-4aef-b290-4b3d982cd2f9', '1381449a-28d7-4c5c-bdb2-32967b32e889', 'a', 'Un buque de propulsión mecánica, con arrancada.', true, '2025-09-13 13:53:12.645804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b6beb8e-1ab5-47a5-b483-46c4a90d936b', '1381449a-28d7-4c5c-bdb2-32967b32e889', 'b', 'Un buque sin gobierno o con su capacidad de maniobra restringida.', false, '2025-09-13 13:53:12.645941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aea33249-2808-40b2-ac2b-46a25803923f', '1381449a-28d7-4c5c-bdb2-32967b32e889', 'c', 'Un buque fondeado.', false, '2025-09-13 13:53:12.646071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86494b17-1ebe-487e-9858-7aeea15c3c91', '1381449a-28d7-4c5c-bdb2-32967b32e889', 'd', 'Un buque de propulsión mecánica en navegación, pero parado y sin arrancada.', false, '2025-09-13 13:53:12.646202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b4584b1-c0b8-4df0-945a-d387215b85c7', '096500ad-e4da-4b66-b432-5499fca5d3bb', 'a', 'Un destello para indicar “caigo a babor”.', false, '2025-09-13 13:53:12.646475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12cef71a-91b9-47b3-8389-3c05727c84dc', '096500ad-e4da-4b66-b432-5499fca5d3bb', 'b', 'Un destello de duración aproximada de un segundo para indicar “caigo a estribor”.', true, '2025-09-13 13:53:12.646607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb1a0b3d-fc02-4590-85e1-caea2f29889b', 'd14b026d-f88d-40f9-84a2-4c9ff10d529b', 'c', 'Suspensión cardán.', false, '2025-09-13 13:53:12.65698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ca3429b-8e54-40e8-85d4-7e7864507088', '96f51e51-ae90-4f59-8430-2fc2bc266828', 'd', 'Bordeando una marca de peligro aislado.', false, '2025-09-13 13:53:12.640486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40e0179f-d89d-4c88-a0b0-f9b9ef9762cf', '2e806389-9504-44dd-9398-0905901b0385', 'a', 'Una embarcación pesquera que no sea de arrastre, que navega por el canal en el mismo sentido que nosotros.', false, '2025-09-13 13:53:12.642255+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b5a76c4-4ca1-460d-98c4-be46b0051e54', '096500ad-e4da-4b66-b432-5499fca5d3bb', 'c', 'Dos destellos de aproximadamente un segundo de duración para indicar “estoy dando atrás”.', false, '2025-09-13 13:53:12.646737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daead90f-c7da-401d-a63a-6db685d0087e', '096500ad-e4da-4b66-b432-5499fca5d3bb', 'd', 'Dos destellos para indicar “caigo a estribor”.', false, '2025-09-13 13:53:12.646888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebcf28dc-89b9-4da3-a514-90dd361e996c', '94106f25-812b-4978-834e-51265d73c8d9', 'a', 'Podría ser necesario apartarse de este Reglamento, para evitar un peligro inmediato, al tomar en consideración todos aquellos peligros de navegación y todas las circunstancias especiales.', true, '2025-09-13 13:53:12.647157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a63044eb-eee1-4a02-b950-c538fc0fdd79', '94106f25-812b-4978-834e-51265d73c8d9', 'b', 'En ningún caso el propietario o capitán del buque podrá apartarse de las reglas estipuladas en el presente Reglamento incurriendo en la correspondiente responsabilidad.', false, '2025-09-13 13:53:12.647288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60e01ee5-41a6-4a7f-b881-599e5737b524', '94106f25-812b-4978-834e-51265d73c8d9', 'c', 'El propietario o capitán del buque podrá apartarse de lo establecido en este Reglamento solamente cuando reciba una recomendación de un servicio de control de tráfico marítimo.', false, '2025-09-13 13:53:12.647418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d031d1a6-857b-46f2-b727-6e1582b388b7', '94106f25-812b-4978-834e-51265d73c8d9', 'd', 'El propietario o capitán de un buque sin gobierno estará exento de seguir lo estipulado en este Maniobra y navegación.', false, '2025-09-13 13:53:12.647558+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8286f62-0535-4547-aff4-e07e703e75e8', '306cc714-03c1-4fa1-b197-1e8fde9e697e', 'a', 'Al dar atrás con arrancada avante.', false, '2025-09-13 13:53:12.647833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d35f505-fcc6-4f6d-945c-87127e301fd9', '306cc714-03c1-4fa1-b197-1e8fde9e697e', 'b', 'Al meter el timón completamente a una banda.', false, '2025-09-13 13:53:12.647971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b558136-ce36-4118-82e5-7a486b24f22d', '306cc714-03c1-4fa1-b197-1e8fde9e697e', 'c', 'Al perder arrancada.', true, '2025-09-13 13:53:12.648105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe0303ce-ad99-4694-b334-3d48dac9bedd', '306cc714-03c1-4fa1-b197-1e8fde9e697e', 'd', 'Al poner el piloto automático.', false, '2025-09-13 13:53:12.648231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('880bbec1-79a1-481c-99a0-4dde75b7123c', 'a0709595-067c-4add-b18a-7f4fb8881ff0', 'a', 'Tensarlo hasta que quede sin seno.', true, '2025-09-13 13:53:12.648508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8de907ab-7bca-4ab2-af0e-8b403710f58f', 'a0709595-067c-4add-b18a-7f4fb8881ff0', 'b', 'Aflojarlo.', false, '2025-09-13 13:53:12.648641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab58d6b4-9bad-4ad6-a35a-655b06a68c36', 'a0709595-067c-4add-b18a-7f4fb8881ff0', 'c', 'Soltarlo.', false, '2025-09-13 13:53:12.648782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69b55af9-b76f-499b-a1c4-4a7acd63fa6e', '513b9b0d-76c3-4ce6-b624-59f9ed84d45f', 'a', 'Manténgase en continuo movimiento para conservar el calor.', false, '2025-09-13 13:53:12.64919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e47e7742-1776-4ca4-a55d-68b2292ea8fd', '513b9b0d-76c3-4ce6-b624-59f9ed84d45f', 'b', 'Beba agua del mar en pequeñas cantidades, a medida que lo necesite, para evitar la deshidratación.', false, '2025-09-13 13:53:12.649322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3796e4ac-0681-4c48-95ad-e219bf2433b2', '513b9b0d-76c3-4ce6-b624-59f9ed84d45f', 'c', 'Adopte la postura fetal o flote abrazado a otros supervivientes, sin nadar.', true, '2025-09-13 13:53:12.649455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af1e35e2-45b3-450b-9c0f-59fdf347977b', '513b9b0d-76c3-4ce6-b624-59f9ed84d45f', 'd', 'Si hay varios supervivientes, quítense el chaleco salvavidas y permanezcan abrazados para mantener el calor corporal.', false, '2025-09-13 13:53:12.649585+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff347d70-66a0-4329-8d8a-0c4137e8c620', '27f3dd01-703d-41a1-961e-2f3fe9572007', 'a', 'Trasladar pesos para cambiar el asiento.', false, '2025-09-13 13:53:12.649867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fbc79da1-a302-48e1-8beb-e56f1b237ddf', '27f3dd01-703d-41a1-961e-2f3fe9572007', 'b', 'Esperar al momento de la bajamar.', true, '2025-09-13 13:53:12.650001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e322e8fc-dada-4040-b629-88ff365b0421', '27f3dd01-703d-41a1-961e-2f3fe9572007', 'c', 'Balancear el barco para que se despegue del fondo, ya que el fango hace de ventosa.', false, '2025-09-13 13:53:12.650133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a39a4a40-91b1-4f76-b0a6-68be57421d40', '27f3dd01-703d-41a1-961e-2f3fe9572007', 'd', 'Utilizar el servicio de un remolcador, si se considera necesario.', false, '2025-09-13 13:53:12.650282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d591aa6e-1f23-4aca-9c2a-d0cf8f36974e', '0acf6914-261b-4c15-8159-d56bfd205fa7', 'b', 'Recortar las ampollas de la quemadura que se hayan roto y cubrirlas con gasas grasas y un vendaje de compresión.', false, '2025-09-13 13:53:12.65069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8884dcb4-92bb-465e-a921-f1e804a1c9d1', '0acf6914-261b-4c15-8159-d56bfd205fa7', 'c', 'Evacuar inmediatamente a un centro hospitalario para su tratamiento.', true, '2025-09-13 13:53:12.650851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e037479-6b50-4c73-85da-f7496ae555c1', '0acf6914-261b-4c15-8159-d56bfd205fa7', 'd', 'Inmovilizar la zona y administrar un antibiótico para prevenir la infección. Meteorología', false, '2025-09-13 13:53:12.650993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b18c02bf-7921-4b62-8e5b-8f8cce99aad0', '186c6f2a-013f-4690-be92-e2a7be82a826', 'a', 'El viento gira en sentido horario y la presión atmosférica es inferior a 1013 milibares.', false, '2025-09-13 13:53:12.651267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd9b5ccf-47c4-47cb-b8d8-79dd26c89706', '186c6f2a-013f-4690-be92-e2a7be82a826', 'b', 'El viento gira en sentido antihorario y la presión atmosférica es superior a 1013 milibares.', false, '2025-09-13 13:53:12.651402+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b8450e9-6eff-434c-ad06-f2553754e3b2', '186c6f2a-013f-4690-be92-e2a7be82a826', 'c', 'El viento gira en sentido horario y la presión atmosférica es superior a 1013 milibares.', false, '2025-09-13 13:53:12.651534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd6efafc-8ab6-4b62-b509-677e22c9b77c', '186c6f2a-013f-4690-be92-e2a7be82a826', 'd', 'El viento gira en sentido antihorario y la presión atmosférica es inferior a 1013 milibares.', true, '2025-09-13 13:53:12.651665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ceecac3d-9e3e-4dea-a023-fef611052984', '5c0cfdd5-77de-4965-8a92-799c783b033b', 'a', 'El viento real es el que percibimos cuando nuestra embarcación está parada.', true, '2025-09-13 13:53:12.651949+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26f67bdb-9238-4f02-87c3-761fb9315b5a', '5c0cfdd5-77de-4965-8a92-799c783b033b', 'b', 'El viento aparente no sufre alteración alguna con el movimiento de la propia embarcación.', false, '2025-09-13 13:53:12.65209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cf3a372-4e5d-4da6-849c-2dc1b4997b87', '5c0cfdd5-77de-4965-8a92-799c783b033b', 'c', 'El viento relativo es la resultante del viento real y del rumbo de la embarcación.', false, '2025-09-13 13:53:12.652223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7f9265f-4f39-45ac-9167-8dd7242a5777', '5c0cfdd5-77de-4965-8a92-799c783b033b', 'd', 'El viento real es el que medimos cuando nuestra embarcación está navegando con arrancada y con viento presente.', false, '2025-09-13 13:53:12.652352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b31c31bd-c7a1-4956-bdd6-74e0405694e2', '314db2fa-a46a-4bc9-9e90-440f9aad50d7', 'a', 'Un aumento en la intensidad del viento.', true, '2025-09-13 13:53:12.65263+00');
