INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e71c668-7773-43f0-b2e8-6f2e64b64015', 'd2e2bc78-c37d-4ac2-864e-07e74d8720c9', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.697531+00');
