INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0ffbbc9-8eab-4273-960a-10d3d08085e7', 'd88989b6-10ef-4337-9948-8ec82286ae98', 'c', 'Si se realiza tan lejos como sea posible de la tierra más próxima, pero en ningún caso a menos de 12 millas marinas de la tierra más próxima.', false, '2025-09-13 13:53:12.712548+00');
