INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('372cfba1-2f5b-4482-ae94-5f6279c0b097', 'da8e8390-0967-41e2-b8da-bf1b2161c9f2', 'a', 'Una embarcación pesquera que no sea de arrastre, que navega por el canal en el mismo sentido', false, '2025-09-13 13:53:12.717796+00');
