INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('424e6b9e-a757-41f5-9111-dde583cc99a4', 'd0b36d53-a86c-45c3-a466-bc9477e798b2', 'b', 'El buque dedicado a la pesca.', true, '2025-09-13 13:53:12.718632+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b81814af-cb8f-41b7-94eb-d59b6cde4ec1', 'd0b36d53-a86c-45c3-a466-bc9477e798b2', 'c', 'El hidroavión amarado.', false, '2025-09-13 13:53:12.718773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb9cb498-f37e-479f-968f-358662f15907', 'd0b36d53-a86c-45c3-a466-bc9477e798b2', 'd', 'El buque de vela.', false, '2025-09-13 13:53:12.718906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('244d81c6-13aa-4970-bae7-6ca346f6fdc0', '8399fcf8-1f31-4645-bb07-7476f3fdbb06', 'a', 'Cada uno de nosotros caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:12.71919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f719d6b-caab-4c09-9d32-353f44447409', '8399fcf8-1f31-4645-bb07-7476f3fdbb06', 'b', 'Hay que esperar a que el otro nos maniobre.', false, '2025-09-13 13:53:12.719331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7d80449-2737-471b-be3d-4a6823362b75', '8399fcf8-1f31-4645-bb07-7476f3fdbb06', 'c', 'Acordaremos por radio que uno de nosotros caerá a estribor y el otro caerá a babor.', false, '2025-09-13 13:53:12.719477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34249719-9f5f-4800-9f96-2129aa66dfee', '8399fcf8-1f31-4645-bb07-7476f3fdbb06', 'd', 'Cada uno de nosotros caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:12.719614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e642290-6359-479a-ab20-86a6a7d6a24c', 'e6a51300-f76f-4756-8d41-efeae3a51a53', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.719921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f699f893-56ae-4ee0-ba22-6ca2f20027f2', 'e6a51300-f76f-4756-8d41-efeae3a51a53', 'b', 'Si es necesario, reducir la velocidad para estudiar la situación siempre que sea posible, y maniobrar preferiblemente de forma clara y con antelación suficiente.', true, '2025-09-13 13:53:12.720055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4c99e8f-442b-4c3d-a992-6e4167423e8c', 'e6a51300-f76f-4756-8d41-efeae3a51a53', 'c', 'Realizar pequeños cambios de rumbo y velocidad para avisar a la embarcación dedicada a la pesca de su obligación de mantenerse apartado de la derrota de nuestra embarcación.', false, '2025-09-13 13:53:12.720195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57c74035-1486-47d5-bf60-d349f1389fb7', 'e6a51300-f76f-4756-8d41-efeae3a51a53', 'd', 'Cambiar de rumbo ligeramente para desviar nuestra derrota lo menos posible y evitar al mismo tiempo el abordaje, dado que esta situación exige la obligación de maniobrar por ser embarcación de propulsión mecánica.', false, '2025-09-13 13:53:12.72033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20e96867-d16a-4d27-9c52-404db9bfe0be', '3c5f7793-cd35-40a2-962b-ae4fd857e203', 'a', 'Buque de vela.', true, '2025-09-13 13:53:12.720611+00');
