INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f169500a-04ce-46bb-90d5-2d397efaf900', '60f8fe53-fa36-4c4e-872b-ca199155f80f', 'a', 'Podría ser necesario apartarse de este Reglamento, para evitar un peligro inmediato, al tomar en consideración todos aquellos peligros de navegación y todas las circunstancias especiales.', true, '2025-09-13 13:53:12.72262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71e80844-211c-43fb-8e37-bb9adeecbdff', '60f8fe53-fa36-4c4e-872b-ca199155f80f', 'b', 'En ningún caso el propietario o capitán del buque podrá apartarse de las reglas estipuladas en el presente Reglamento incurriendo en la correspondiente responsabilidad.', false, '2025-09-13 13:53:12.722751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03c4df1a-f834-4b79-9e91-104aa1eb322e', '60f8fe53-fa36-4c4e-872b-ca199155f80f', 'c', 'El propietario o capitán del buque podrá apartarse de lo establecido en este Reglamento solamente cuando reciba una recomendación de un servicio de control de tráfico marítimo.', false, '2025-09-13 13:53:12.722895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50944773-f703-4723-ba23-1311d1850d01', '60f8fe53-fa36-4c4e-872b-ca199155f80f', 'd', 'El propietario o capitán de un buque sin gobierno estará exento de seguir lo estipulado en este', false, '2025-09-13 13:53:12.723025+00');
