INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb254531-8079-47fa-bb35-8568d897d66c', '2e5e1688-1f35-4b05-9397-59c98debfaa5', 'd', 'Respete las fechas de caducidad.', false, '2025-09-13 13:53:12.728834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('530c9cf4-22f6-46ad-8464-559b40113749', '18334ab6-111b-424c-9247-bbb14f29bdad', 'a', 'Active la radiobaliza, ya que no dispone de los dispositivos de salvamento mínimos.', true, '2025-09-13 13:53:12.729121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a35e00ab-2773-4ff3-aff8-fb59e77b69bf', '18334ab6-111b-424c-9247-bbb14f29bdad', 'b', 'Informe al pasaje de que será obligatorio navegar con el chaleco salvavidas puesto.', false, '2025-09-13 13:53:12.729256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('281b2ea2-a8d2-43f5-b65d-c3d432f53a28', '18334ab6-111b-424c-9247-bbb14f29bdad', 'd', 'Informe a Salvamento Marítimo para evitar la activación de una falsa alarma.', false, '2025-09-13 13:53:12.729527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aad73bfd-68d3-48e5-8ef3-64d372bed118', 'c32622df-732e-4061-880e-72589ff15a43', 'a', 'El balance es el movimiento de oscilación longitudinal del barco.', false, '2025-09-13 13:53:12.729813+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d6a934d-3a0c-4635-b073-74e5e2da7612', 'c32622df-732e-4061-880e-72589ff15a43', 'b', 'La estabilidad longitudinal no depende de la posición del centro de carena.', true, '2025-09-13 13:53:12.729947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6626b605-f8e9-401c-a7aa-7d47351a972f', 'c32622df-732e-4061-880e-72589ff15a43', 'd', 'Un fuerte movimiento de cabezada es consecuencia directa de la mala estabilidad transversal.', false, '2025-09-13 13:53:12.730206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf8fbb07-c95f-4fc3-8ebf-3488ab5e46d8', '15be615b-8ead-4b19-a0db-dd1cb7674246', 'a', 'Tengo un buzo sumergido. Manténgase en comunicación con su embarcación de apoyo.', false, '2025-09-13 13:53:12.730476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('871fe1c7-e100-4ace-b139-547022a56082', '15be615b-8ead-4b19-a0db-dd1cb7674246', 'c', 'Estoy cargando, descargando o transportando mercancías peligrosas.', true, '2025-09-13 13:53:12.73074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5356ebb-d85a-4eb2-8b42-c43fcc0efcf4', '15be615b-8ead-4b19-a0db-dd1cb7674246', 'd', 'Manténgase alejado de mí, estoy maniobrando con dificultad porque hay un buzo sumergido.', false, '2025-09-13 13:53:12.730878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1423fbae-a01d-41b5-8cab-a79a98168fbc', 'dd9357e5-ebf2-45bd-b4e8-b94de8105d90', 'a', 'Desplazarse a velocidad inferior a 3 nudos para vararla.', true, '2025-09-13 13:53:12.731143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a1b692c-38d3-4ed2-bd9a-dff308bcdd96', 'dd9357e5-ebf2-45bd-b4e8-b94de8105d90', 'b', 'Navegar en la franja de mar contigua a la costa en una anchura de 200 m.', false, '2025-09-13 13:53:12.731279+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d12102d-5e28-40db-b3b9-41d1d3c09395', 'dd9357e5-ebf2-45bd-b4e8-b94de8105d90', 'c', 'Salir al mar desde dichos tramos.', false, '2025-09-13 13:53:12.73141+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afe4e30f-099b-41a1-a6b5-ae5bb2bf147e', 'dd9357e5-ebf2-45bd-b4e8-b94de8105d90', 'd', 'Seguir una trayectoria perpendicular a la línea de costa en ningún caso.', false, '2025-09-13 13:53:12.731537+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9173d6d0-f44a-409a-9145-f2d4d9191d16', 'e5d74b68-1ece-40a7-96bb-2288bf311635', 'a', 'Con bandas horizontales amarillas y negras.', true, '2025-09-13 13:53:12.731802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93b1f12a-5663-48b2-845b-7114feaca4f0', 'e5d74b68-1ece-40a7-96bb-2288bf311635', 'b', 'Con bandas horizontales verdes y rojas.', false, '2025-09-13 13:53:12.731934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8350b451-b04f-4ec7-8774-27fe2d046245', 'e5d74b68-1ece-40a7-96bb-2288bf311635', 'c', 'Con franjas verticales amarillas y negras.', false, '2025-09-13 13:53:12.732062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('796761d2-900b-4203-a1db-d79466099572', 'e5d74b68-1ece-40a7-96bb-2288bf311635', 'd', 'Con bandas horizontales rojas y blancas.', false, '2025-09-13 13:53:12.732188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40a8eace-c625-4904-b21f-2039a7cd97da', 'fe14895d-5179-42ff-8dbd-9516645bcc24', 'a', 'Una única esfera roja.', false, '2025-09-13 13:53:12.732456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d579c49-c0d9-44b0-b0d7-fff5e278463a', 'fe14895d-5179-42ff-8dbd-9516645bcc24', 'b', 'Un único cilindro rojo.', true, '2025-09-13 13:53:12.732585+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1bcc0c8-0c5f-4730-8bcb-0d5d325e1f9f', 'fe14895d-5179-42ff-8dbd-9516645bcc24', 'c', 'Dos esferas negras, una encima de la otra.', false, '2025-09-13 13:53:12.732715+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dc403f4-14cf-41df-b98d-3dc8528e42b5', 'fe14895d-5179-42ff-8dbd-9516645bcc24', 'd', 'Una esfera roja encima de otra blanca.', false, '2025-09-13 13:53:12.732861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ee9bd92-e4a8-4418-b10c-8394becb1199', '636b2666-cf4e-4836-bedb-7f9a78a99aa4', 'a', 'Pueden ir con letras o numeradas.', false, '2025-09-13 13:53:12.733158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab389d92-de30-44d0-adc9-2990c890f570', '636b2666-cf4e-4836-bedb-7f9a78a99aa4', 'b', 'Generalmente no están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.733287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d697a26-ac63-403e-9578-3753beb55130', '636b2666-cf4e-4836-bedb-7f9a78a99aa4', 'c', 'Pueden utilizarse para indicar la aproximación a un puerto o estuario.', false, '2025-09-13 13:53:12.733415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06e222f0-3968-4f65-8811-027ea81c466d', '636b2666-cf4e-4836-bedb-7f9a78a99aa4', 'd', 'Cuando la visibilidad no sea buena, los ritmos de las luces amarillas serán distintos a los empleados en las luces blancas.', true, '2025-09-13 13:53:12.733543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e890b9d-e020-47dc-bc49-dcbfa9c35206', 'c450aa5e-205c-4c82-b826-0c63ecb849e9', 'a', 'Dado que navegamos en contra del sentido convencional de balizamiento, deberemos dejar la boya por estribor ya que ésta es una Marca Lateral de estribor.', false, '2025-09-13 13:53:12.733808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23ce6152-6f5f-4e26-ab9d-1df6e994262a', 'c450aa5e-205c-4c82-b826-0c63ecb849e9', 'b', 'Dado que navegamos en el sentido convencional de balizamiento, deberemos dejar la boya por babor ya que ésta es una Marca Lateral de babor.', false, '2025-09-13 13:53:12.733937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9828c22-e39a-4d88-a3ef-872b0cee06da', 'c450aa5e-205c-4c82-b826-0c63ecb849e9', 'c', 'Deberemos alejarnos de dicha Marca ya que indica un peligro aislado.', true, '2025-09-13 13:53:12.734071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c49ddc8-ef80-4f27-b9f9-c068e929060e', 'c450aa5e-205c-4c82-b826-0c63ecb849e9', 'd', 'Deberemos consultar la carta náutica para saber si nos queremos dirigir al canal principal o al secundario ya que ésta Marca indica el punto de bifurcación del canal principal a babor.', false, '2025-09-13 13:53:12.734199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8741e944-80fc-4f08-8e88-2edd276dd180', '8da067da-e69e-46be-8454-ccde0c02a9e6', 'a', 'La Marca de Peligro Aislado, se colocará encima, amarrada, o próxima a un peligro, que esté rodeado, por todas partes, de aguas navegables.', false, '2025-09-13 13:53:12.734477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ec58430-a0d5-4408-af17-6c8ea63b358b', '8da067da-e69e-46be-8454-ccde0c02a9e6', 'b', 'Su marca de tope es una esfera negra.', false, '2025-09-13 13:53:12.734608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b769cd3-0950-4d64-b71f-c46fad78c355', '8da067da-e69e-46be-8454-ccde0c02a9e6', 'c', 'La Marca de Peligro Aislado se colocará encima, amarrada, o próxima a aguas navegables, que estén próximas, en alguna dirección, a algún peligro aislado.', false, '2025-09-13 13:53:12.734737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3f633b9-2725-487d-bacf-65e86a57e46c', '8da067da-e69e-46be-8454-ccde0c02a9e6', 'd', 'Sobre su numeración o rotulación, no podrán utilizarse números o letras para identificar dichas marcas de Peligro Aislado. Reglamento (RIPA).', true, '2025-09-13 13:53:12.734868+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4553e01b-8517-4d7c-bf9d-ff236ea1c03e', '5068efcf-bab5-4b3b-8b0e-c117fea7cd72', 'b', 'No tendremos la obligación de exhibir la luz blanca todo horizonte de fondeo.', true, '2025-09-13 13:53:12.735335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8fcc4db-eae7-48de-b577-a56c1e19915c', '5068efcf-bab5-4b3b-8b0e-c117fea7cd72', 'c', 'Estamos obligados a exhibir una marca con forma de bola.', false, '2025-09-13 13:53:12.735471+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bd62e9d-61d7-41c2-964d-c61d117b5e2f', '5068efcf-bab5-4b3b-8b0e-c117fea7cd72', 'd', 'No podremos utilizar luces para iluminar la zona de cubierta ni la bañera, debiendo exhibir obligatoriamente dos luces todo horizonte blancas, una a proa y otra a popa.', false, '2025-09-13 13:53:12.735602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc50f66a-8db7-4ca4-9bff-ac181e994f1d', '111279d1-fbee-48b2-9345-4254228fb4a2', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.735896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d753d4a3-6e1f-428f-8efe-f3c3e98a82c4', '111279d1-fbee-48b2-9345-4254228fb4a2', 'b', 'Aumentar la velocidad ligeramente para tratar de propiciar que la otra embarcación haga la maniobra ante el posible peligro de abordaje, y así evitar un cambio de rumbo en nuestra derrota.', false, '2025-09-13 13:53:12.736028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a79234b9-6a82-4562-bc80-c067a4a55ab6', '111279d1-fbee-48b2-9345-4254228fb4a2', 'c', 'Si las circunstancias del caso lo permiten, realizar cambios de rumbo y velocidad amplios que sean fácilmente percibidos por la otra embarcación.', true, '2025-09-13 13:53:12.736163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('838e33b3-19dd-4808-83c7-99810cbe8ee1', '111279d1-fbee-48b2-9345-4254228fb4a2', 'd', 'Cambiar de rumbo ligeramente para desviar nuestra derrota lo menos posible y, ante todo, nunca suprimir la arrancada ya que una disminución de la velocidad siempre se traduce en una pérdida de capacidad de maniobra.', false, '2025-09-13 13:53:12.736295+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e6670c3-8e87-48ca-9f43-f142c3b09e3b', '750cafcd-0ddb-44b0-8026-16d17ce6ee69', 'a', 'Varado.', false, '2025-09-13 13:53:12.736578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('210a0afe-cca7-4568-ac95-c2bc86b24957', '750cafcd-0ddb-44b0-8026-16d17ce6ee69', 'b', 'Fondeado.', false, '2025-09-13 13:53:12.73671+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dc216b2-34d8-4107-828b-5708901e640a', '750cafcd-0ddb-44b0-8026-16d17ce6ee69', 'c', 'Restringido por su calado.', true, '2025-09-13 13:53:12.736847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e949e0be-ea31-4480-a707-8be5ac7dc13b', '750cafcd-0ddb-44b0-8026-16d17ce6ee69', 'd', 'Sin gobierno.', false, '2025-09-13 13:53:12.736977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3dd525f5-5f8f-4425-9a88-06a621c9438b', '278bfe76-427e-45d0-81bb-b5b97324b9c7', 'a', 'Siempre que no disponga de maquinaria propulsora instalada a bordo.', false, '2025-09-13 13:53:12.737348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('005803b0-1b0d-463e-a2b0-e8daebd03aef', '278bfe76-427e-45d0-81bb-b5b97324b9c7', 'b', 'Que sea incapaz de apartarse de la derrota de otro buque debido a su posición relativa al viento.', false, '2025-09-13 13:53:12.737615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c75ea29-bec0-48ab-bf88-d87901ec43c0', '278bfe76-427e-45d0-81bb-b5b97324b9c7', 'c', 'Cuya forma de sus velas no restrinja su maniobrabilidad.', true, '2025-09-13 13:53:12.737756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9768ee3d-ba3f-4927-acfa-1585dc155ad3', '278bfe76-427e-45d0-81bb-b5b97324b9c7', 'd', 'Siempre que su maquinaria propulsora, en caso de llevarla, no se esté utilizando.', false, '2025-09-13 13:53:12.737932+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0234f928-a0a0-4ce0-86d8-bb833aeaaf39', '15ee85ce-5674-4233-b335-7d837b056d6d', 'c', 'Cruce.', true, '2025-09-13 13:53:12.78603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c03c887a-cc29-479f-94ef-0e0f5a125389', '15be615b-8ead-4b19-a0db-dd1cb7674246', 'b', 'Tengo un buzo sumergido.', false, '2025-09-13 13:53:12.730609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed41cdf5-c800-44bb-ac87-3e34e3d2aad3', 'c32622df-732e-4061-880e-72589ff15a43', 'c', 'La estabilidad transversal depende de la posición relativa del centro de carena y del centro de gravedad.', false, '2025-09-13 13:53:12.730077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e7c1e04-28df-46da-b3a7-48f56ea83b73', 'aed2ea34-165f-4c7d-9e2c-b665c6ffe1b7', 'b', 'Las Reglas relativas a las marcas deberán cumplirse tanto de día como de noche.', true, '2025-09-13 13:53:12.73838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c01bd0a-1c2b-4e0d-94d2-b7be3e4ce032', 'aed2ea34-165f-4c7d-9e2c-b665c6ffe1b7', 'c', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', false, '2025-09-13 13:53:12.73851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('064524e7-33eb-4e25-810b-111a6aa5dcde', 'aed2ea34-165f-4c7d-9e2c-b665c6ffe1b7', 'd', 'Las luces preceptuadas por estas Reglas podrán no exhibirse desde la salida hasta la puesta del sol aunque haya visibilidad reducida, si el patrón no lo considera necesario.', false, '2025-09-13 13:53:12.738659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa30820b-c3d2-4784-9adb-c2a5095d8a17', '8ebe6e5d-4dd0-41df-b93b-e935282c9581', 'a', 'Dos luces todo horizonte en línea vertical, blanca la superior y verde la inferior, una luz de tope a popa y más elevada que la luz verde todo horizonte.', true, '2025-09-13 13:53:12.738968+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6119ffb8-2f68-4a05-8634-da8cbcb96652', '8ebe6e5d-4dd0-41df-b93b-e935282c9581', 'c', 'Dos luces todo horizonte en línea vertical, roja la superior y blanca la inferior, una luz blanca todo horizonte en la dirección del aparejo, además de las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:12.740029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec42e1a0-4b07-41f9-851e-b51ad2019f43', '8ebe6e5d-4dd0-41df-b93b-e935282c9581', 'd', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior, una luz blanca todo horizonte en la dirección del aparejo, además de las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:12.740317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d054dff8-d0d8-4f27-be67-81de032888ea', '5d267d69-1a24-452a-b09a-c4cdb71cb9cf', 'a', 'Podrá usar la zona de navegación costera.', false, '2025-09-13 13:53:12.740934+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24712535-eee1-4b11-a9d7-128565b8c7a8', '5d267d69-1a24-452a-b09a-c4cdb71cb9cf', 'b', 'Deberá en cualquier caso utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-13 13:53:12.741236+00');
