INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52ef5925-f56b-4134-b611-c04ea9e16858', '3813e06c-c020-40ea-8212-3d387ae88187', 'a', 'En el momento del fondeo se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente por el fondo.', false, '2025-09-13 13:53:12.770188+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48464e44-10e8-44ab-a1d8-6a6819358a4f', '3813e06c-c020-40ea-8212-3d387ae88187', 'b', 'De forma general, la longitud de cadena para un fondeo con buen tiempo no será inferior a tres veces la sonda del lugar de fondeo.', true, '2025-09-13 13:53:12.770388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a844be1-82ae-4910-b9c5-87e528b18741', '15ee85ce-5674-4233-b335-7d837b056d6d', 'd', 'Buque de pesca faenando.', false, '2025-09-13 13:53:12.786242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('abeacbd1-3cdf-47d4-b03a-76e31bebe8b0', 'ba27ebf1-d750-428a-941d-0a93e2c70fc2', 'd', 'Hundir la popa y levantar la proa.', false, '2025-09-13 13:53:12.768772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6534b13-5c94-463d-bc2b-3154b91541eb', '3fd19d35-302f-45b4-a617-5e8cc0332ed1', 'd', 'Aumentará la temperatura y bajará el viento.', false, '2025-09-13 13:53:12.754859+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5c42ad7-cd1a-4750-8596-c3433284f39f', '3813e06c-c020-40ea-8212-3d387ae88187', 'c', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de la embarcación, dando la proa al viento.', false, '2025-09-13 13:53:12.77059+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dad77610-cf5d-4a7b-aba1-89f4f3474179', '3813e06c-c020-40ea-8212-3d387ae88187', 'd', 'Si se comprueba que la embarcación garrea, se recomienda virar el ancla y volver a fondear.', false, '2025-09-13 13:53:12.770817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ee5a29e-0461-4150-bd01-6b0757058f93', '15048453-b30a-4240-a4b5-4228f22e2b7e', 'a', 'Librar al náufrago de la hélice, no perderle de vista y lanzarle ayudas.', false, '2025-09-13 13:53:12.771228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('659d3e98-3b43-4bb0-9aa5-d97ae4a5a1f1', '15048453-b30a-4240-a4b5-4228f22e2b7e', 'b', 'Librar al náufrago de la hélice, parar el motor, lanzarle ayudas y saltar al agua en su busca.', true, '2025-09-13 13:53:12.771448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95a431cb-cf4b-4aa1-9cfb-970d916072a7', '15048453-b30a-4240-a4b5-4228f22e2b7e', 'c', 'Dar atrás y acercarnos lentamente por la popa, sin perder de vista al náufrago, para evitar que la proa pueda dañarlo.', false, '2025-09-13 13:53:12.771647+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d2beb45-d6df-4240-a510-da45d4458720', '15048453-b30a-4240-a4b5-4228f22e2b7e', 'd', 'Saltar al agua en su busca para evitar que se ahogue.', false, '2025-09-13 13:53:12.771847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b7f2bab-2f68-4272-80d7-6ed243efdda9', '07f791b1-7a76-4f1a-a087-3fa593933f6a', 'a', 'Un sistema de detección de barcos que es obligatorio en cualquier tipo de embarcación.', false, '2025-09-13 13:53:12.772277+00');
