INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef3dfe28-6ef4-4ab5-8164-555ebb7b7045', 'ccd00cfb-c5a0-40db-9bf9-e46ab4e762f3', 'd', 'Por teléfono, llamando al 900 202 202.', false, '2025-09-13 13:53:12.773956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44496a70-040f-49a9-a23f-9f6825475a73', '0c65e5b7-1392-46e9-b828-4ac7665e2bb0', 'a', 'Al capear el temporal debemos reducir la velocidad incluso parando la arrancada.', false, '2025-09-13 13:53:12.774366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1992966-4880-43cb-8231-d3f35ccd541f', '0c65e5b7-1392-46e9-b828-4ac7665e2bb0', 'b', 'Correr el temporal es una maniobra cómoda, pero, con mal tiempo, existe el problema de que pueden embarcar fuertes golpes de mar.', false, '2025-09-13 13:53:12.774563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2fe0436-6875-4a92-889a-ff5cb54dffb1', '0c65e5b7-1392-46e9-b828-4ac7665e2bb0', 'd', 'Para capear el temporal nos podemos ayudar mediante el uso de un ancla flotante.', false, '2025-09-13 13:53:12.774968+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0faf4d1-9d20-4bb9-86bb-dd7fb83b48a6', 'b253b4df-5144-4186-be49-2e64a810d987', 'a', 'Cuando las basuras estén mezcladas con otras sustancias cuya descarga esté prohibida o para las que rijan distintas prescripciones de descarga, se aplicarán las prescripciones más rigurosas.', false, '2025-09-13 13:53:12.775389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56a1362e-91a8-4a3f-bb39-d66253c3ed15', 'b253b4df-5144-4186-be49-2e64a810d987', 'b', 'Los aditivos de limpieza contenidos en las aguas de lavado podrán descargarse al mar, aunque sean perjudiciales para el medio marino.', false, '2025-09-13 13:53:12.775583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('271b2883-5a85-47dc-a82b-08f49b298615', 'b253b4df-5144-4186-be49-2e64a810d987', 'c', 'La descarga de basuras en el mar fuera de las zonas especiales está prohibida sin excepciones.', false, '2025-09-13 13:53:12.775785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61c66413-8a26-4ed8-801d-ed53c755f0c5', 'b253b4df-5144-4186-be49-2e64a810d987', 'd', 'Los restos de alimentos a descargar estarán desmenuzados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', true, '2025-09-13 13:53:12.775979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('547ebf0b-86fb-4709-adce-818e141acc3e', 'b4fecefe-04fd-473c-9740-c7cb42dd4840', 'a', 'Tres días hábiles.', true, '2025-09-13 13:53:12.776375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f192d4b1-0ec2-4021-ad89-3fbe0b2bc1a2', 'b4fecefe-04fd-473c-9740-c7cb42dd4840', 'b', 'Diez días hábiles.', false, '2025-09-13 13:53:12.776583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7308a9e-0f45-4554-b638-16e73b241628', 'b4fecefe-04fd-473c-9740-c7cb42dd4840', 'c', 'Cinco días hábiles.', false, '2025-09-13 13:53:12.776774+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61b29bc6-a51b-4621-8e38-50da67c225cb', 'b4fecefe-04fd-473c-9740-c7cb42dd4840', 'd', 'Quince días hábiles.', false, '2025-09-13 13:53:12.776971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42301649-7dad-468a-9349-9281db132415', 'c5790310-5949-4f94-85e3-89f537a2afc6', 'a', 'Será de color blanco.', false, '2025-09-13 13:53:12.777417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2586f2fb-6bf8-4bf6-852e-6aca4403320a', 'c5790310-5949-4f94-85e3-89f537a2afc6', 'b', 'Será de color azul.', false, '2025-09-13 13:53:12.777613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34d5e538-303f-46cc-885d-a6186d6a9855', 'c5790310-5949-4f94-85e3-89f537a2afc6', 'c', 'Será de color amarillo.', true, '2025-09-13 13:53:12.777851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13df27ca-16c5-4be8-964f-ec7aaca6ad6d', 'c5790310-5949-4f94-85e3-89f537a2afc6', 'd', 'Tendrá ritmo de grupos de 3 destellos.', false, '2025-09-13 13:53:12.778083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12aff822-f772-4963-bbf9-673620345d48', '147e5442-516c-4d3c-aa5e-29df1aa33dae', 'a', 'Con los vértices hacia arriba.', false, '2025-09-13 13:53:12.778488+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62f9fdc9-e68b-44ac-b0ad-d28162c40797', '147e5442-516c-4d3c-aa5e-29df1aa33dae', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:12.778683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('402bcc76-dae8-4b61-b6b0-6116e2ad518d', '147e5442-516c-4d3c-aa5e-29df1aa33dae', 'c', 'Opuestos por sus bases.', false, '2025-09-13 13:53:12.77891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aff58083-dbbe-4ab6-9b56-e1390f1b0835', '147e5442-516c-4d3c-aa5e-29df1aa33dae', 'd', 'Opuestos por sus vértices.', true, '2025-09-13 13:53:12.779116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3a50637-265e-47d4-ba19-6db0252038ab', '8d66141a-8f48-4b18-a7f6-48268fa4bd41', 'a', 'Estructuras artificiales.', false, '2025-09-13 13:53:12.779511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77e889e5-a330-4d9a-92f7-dfb6cbab9fd4', '8d66141a-8f48-4b18-a7f6-48268fa4bd41', 'b', 'Zonas de recreo.', true, '2025-09-13 13:53:12.779711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('542885c8-31aa-4f86-8234-f8ea73757537', '8d66141a-8f48-4b18-a7f6-48268fa4bd41', 'c', 'Límites de las áreas de fondeo.', false, '2025-09-13 13:53:12.779906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ddc08f3-2734-4958-ad8d-d8f4e44f5a94', '8d66141a-8f48-4b18-a7f6-48268fa4bd41', 'd', 'La aproximación a un puerto o estuario.', false, '2025-09-13 13:53:12.7801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad96d6d8-4a85-4d76-a287-f6eddc1c4686', 'b645687e-ed41-40cb-a06f-7634ca36aebb', 'a', 'Si tienen luz, es amarilla.', false, '2025-09-13 13:53:12.780494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a2c02b2-ba6e-494f-a489-d2266cb0e47e', 'b645687e-ed41-40cb-a06f-7634ca36aebb', 'b', 'Indican una zona o una configuración particular cuya naturaleza exacta está indicada en la carta u otro documento náutico.', false, '2025-09-13 13:53:12.78069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c6ee690-86b4-4000-ae38-4bee2f372e8a', 'b645687e-ed41-40cb-a06f-7634ca36aebb', 'c', 'No señalan ningún peligro.', true, '2025-09-13 13:53:12.780898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d91668e1-62c5-42e2-a1f2-fe01603d59a2', 'b645687e-ed41-40cb-a06f-7634ca36aebb', 'd', 'Si tienen marca de tope es una única esfera verde.', false, '2025-09-13 13:53:12.781099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b431cec-a4fa-4ef9-bff0-2930dcd6059d', '10e65fef-f849-49e7-a87f-7519056dfcf2', 'a', 'Verde con una banda ancha horizontal roja.', true, '2025-09-13 13:53:12.781514+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c067257-7447-4bbe-b89f-f7b5f99627aa', '10e65fef-f849-49e7-a87f-7519056dfcf2', 'b', 'Verde con una luz verde centelleante rápida continua.', false, '2025-09-13 13:53:12.781727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dc012e2-5190-457a-88e2-c0be1838844c', '10e65fef-f849-49e7-a87f-7519056dfcf2', 'c', 'Roja con una luz roja con ritmo de destello en grupos de 2+1.', false, '2025-09-13 13:53:12.781917+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('555a3bde-6cb2-42ff-98c3-1e56c90bc68f', '0d602081-a308-4b0c-97e2-ef82e6ad6946', 'a', 'Únicamente una campana.', false, '2025-09-13 13:53:12.782524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba1077af-54d4-4dae-95b7-1f70ecd77ff2', '0d602081-a308-4b0c-97e2-ef82e6ad6946', 'b', 'Un pito y una campana.', false, '2025-09-13 13:53:12.782719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2deaba1-c224-422e-8dab-bfa7b182e20d', '0d602081-a308-4b0c-97e2-ef82e6ad6946', 'c', 'Una campana y un gong.', true, '2025-09-13 13:53:12.782913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('723bc404-be7e-4ed9-8155-7631c2b7d18d', '0d602081-a308-4b0c-97e2-ef82e6ad6946', 'd', 'Únicamente un pito.', false, '2025-09-13 13:53:12.783107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07988096-7c2d-42ed-a707-6126f59c95ba', '987d6176-4469-4785-943b-a4eb0255ac8d', 'a', 'Un buque dedicado a la pesca, fondeado.', false, '2025-09-13 13:53:12.783506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bc8a667-c38a-42c1-9c2a-b6188a75d0ea', '987d6176-4469-4785-943b-a4eb0255ac8d', 'b', 'Una embarcación de prácticos, con arrancada, en servicio de practicaje.', true, '2025-09-13 13:53:12.783717+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a265a49-437c-4cd8-b13b-d2885c857b3c', '987d6176-4469-4785-943b-a4eb0255ac8d', 'c', 'Un buque de eslora igual o superior a 100 metros, fondeado.', false, '2025-09-13 13:53:12.783931+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be26cbd1-1e8f-4194-bf49-2171b4982ed8', '987d6176-4469-4785-943b-a4eb0255ac8d', 'd', 'Un buque remolcador que tenga restringida su maniobra.', false, '2025-09-13 13:53:12.784128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a579007-aab4-4f02-aa07-eda8c5650b3b', '66548e3c-9fc3-4405-9e8b-980eb1644bbf', 'a', 'Exhibirá luces que, por sus características y situación, sean lo más parecidas posible a las prescritas en dicha regla.', false, '2025-09-13 13:53:12.784536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('032d6fa9-919c-4834-8c2b-73c2a01da49f', '66548e3c-9fc3-4405-9e8b-980eb1644bbf', 'b', 'Tendrá prohibida la navegación.', false, '2025-09-13 13:53:12.784742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e31578f5-4352-4316-980f-07985e71319a', '66548e3c-9fc3-4405-9e8b-980eb1644bbf', 'c', 'Lo indicará colocando en el lugar más visible una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:12.784943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4d03a9e-f05b-43dd-b30d-b2f97bedb2d8', '66548e3c-9fc3-4405-9e8b-980eb1644bbf', 'd', 'Las sustituirá todas por una única luz roja centelleante todo horizonte de gran intensidad.', false, '2025-09-13 13:53:12.785155+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c64e7f04-d623-4e44-9d00-6e6833fe2298', '15ee85ce-5674-4233-b335-7d837b056d6d', 'a', 'Vuelta encontrada.', false, '2025-09-13 13:53:12.785614+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cebe65ba-4c28-4d5f-8156-8b8627fbc604', '10e65fef-f849-49e7-a87f-7519056dfcf2', 'd', 'Roja con una banda ancha horizontal verde.', false, '2025-09-13 13:53:12.782127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7939101a-8417-44de-b29d-78a39a1085d2', '7af0c046-960f-42cf-be3c-71614c2f5f79', 'a', 'El resplandor de las luces de tierra siempre beneficiará la distinción de otros buques o marcas de balizamiento de noche.', false, '2025-09-13 13:53:12.786656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6aca57e4-19bf-4133-a811-6a9cd44302bb', '7af0c046-960f-42cf-be3c-71614c2f5f79', 'b', 'Un equipo radar funcionando correctamente nunca debe ser utilizado para determinar la velocidad de seguridad en condiciones de mala visibilidad.', false, '2025-09-13 13:53:12.786866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f8a34c63-06cc-4169-b59f-0a9426b030d2', '7af0c046-960f-42cf-be3c-71614c2f5f79', 'c', 'En condiciones de mala visibilidad, se debe aumentar la velocidad al máximo para evitar pasar más tiempo de lo necesario expuestos a posibles peligros.', false, '2025-09-13 13:53:12.787063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c414fa30-5590-4f61-86cf-83f839a95c12', '7af0c046-960f-42cf-be3c-71614c2f5f79', 'd', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca, condicionará la maniobra adecuada y eficaz para evitar un abordaje.', true, '2025-09-13 13:53:12.787265+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5574a450-c7fc-42df-be86-7fbf93d8392e', '16153749-1240-4cd0-b1e3-657309d55387', 'b', 'A estribor respecto a un buque situado a proa del través, especialmente si el otro buque está siendo alcanzado.', false, '2025-09-13 13:53:12.787901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57c00a65-288c-49ba-ae75-2aa79a624701', '16153749-1240-4cd0-b1e3-657309d55387', 'c', 'A babor respecto a todo buque situado a popa del través.', true, '2025-09-13 13:53:12.788112+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf973858-a5af-4d23-9aaf-a5f565f7987d', '16153749-1240-4cd0-b1e3-657309d55387', 'd', 'A estribor respecto a un buque situado a proa del través, si el otro buque no está siendo', false, '2025-09-13 13:53:12.78833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61ef6175-05e9-4bef-a65d-d7e76b05beee', 'c5901335-66d5-48d2-965a-4e5a4cbd94f7', 'a', 'Para evitar un peligro inmediato.', false, '2025-09-13 13:53:12.788739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c096eeb-2e2e-4aa1-9d9e-97e04111aa9d', 'c5901335-66d5-48d2-965a-4e5a4cbd94f7', 'b', 'Exclusivamente cuando estén en ruta hacia un puerto dentro de la zona de navegación costera.', true, '2025-09-13 13:53:12.788961+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f50ad176-4ec9-42e3-87e1-e1a43a721857', 'c5901335-66d5-48d2-965a-4e5a4cbd94f7', 'c', 'Por ser un buque menor de 30 metros de eslora puede utilizar la zona de navegación costera siempre que lo necesite.', false, '2025-09-13 13:53:12.789176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b9af89d-640e-4e23-b06c-cf30d386fee0', 'c5901335-66d5-48d2-965a-4e5a4cbd94f7', 'd', 'Únicamente en el caso de que deba maniobrar a un buque que tenga preferencia de paso, y el ancho del dispositivo no sea suficiente para realizar la maniobra con seguridad.', false, '2025-09-13 13:53:12.789376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('793f6627-4712-4ea4-be2c-4199898b6859', 'e17150c5-ab51-4065-af7f-a9db331a5910', 'a', 'Navegue a vela y no sea propulsado mecánicamente.', true, '2025-09-13 13:53:12.7898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89225d86-b441-473a-bbf4-e7ea9daa3088', 'e17150c5-ab51-4065-af7f-a9db331a5910', 'c', 'Navegue a vela y también sea propulsado mecánicamente.', false, '2025-09-13 13:53:12.790216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae8984ef-8404-4167-8ccb-64957f5ad656', 'e17150c5-ab51-4065-af7f-a9db331a5910', 'd', 'Navegue solo propulsado mecánicamente.', false, '2025-09-13 13:53:12.790422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4011488-cd8f-4a08-9fbf-fa4b1d31587f', '45a40ca7-eae8-44ec-8920-2ee39cd42271', 'a', 'Emitirá una señal acústica de al menos cinco pitadas cortas y rápidas y se maniobrará al buque de vela si fuera necesario para evitar el abordaje.', false, '2025-09-13 13:53:12.790817+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ba2ce71-f0a0-4093-ab8a-48ea59c18a91', '45a40ca7-eae8-44ec-8920-2ee39cd42271', 'c', 'Cederá el paso al buque de vela, aun no existiendo riesgo de abordaje, ya que tienen la preferencia de tránsito por el canal al ir sin maquinaria propulsora.', true, '2025-09-13 13:53:12.79123+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55842389-0ed5-492f-9c64-b472d371228e', '45a40ca7-eae8-44ec-8920-2ee39cd42271', 'd', 'Fondeará en el canal, en cualquier caso, hasta que el buque de vela termine de estorbar nuestro', false, '2025-09-13 13:53:12.79144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c4bceef-ff5c-47aa-bec1-0f14be6d2a33', '2830a002-1de2-46c1-bf1f-b60e3d142eb6', 'a', 'Un aerodeslizador navegando a gran velocidad.', true, '2025-09-13 13:53:12.791868+00');
