INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7aba2ec4-180a-4c4c-9772-0fd041b9b66c', 'aa4710c5-028f-43ce-86cc-3bbbdfa6fe04', 'c', 'Dos esferas negras, una encima de la otra.', false, '2025-09-13 13:53:12.825452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab0e6038-b1dc-4f6c-977a-96e99d903f60', 'aa4710c5-028f-43ce-86cc-3bbbdfa6fe04', 'd', 'Una esfera roja encima de otra blanca.', false, '2025-09-13 13:53:12.825661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c26e9747-4e1f-4ff7-a256-e533a548dc50', 'fcc126aa-a6b9-44e0-895e-aed88f85ed01', 'a', 'Dado que navegamos en contra del sentido convencional de balizamiento, deberemos dejar la boya por estribor ya que ésta es una Marca Lateral de estribor.', false, '2025-09-13 13:53:12.826121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60cb9ed1-29e8-4288-9fb0-f4a1c82a2172', 'fcc126aa-a6b9-44e0-895e-aed88f85ed01', 'b', 'Dado que navegamos en el sentido convencional de balizamiento, deberemos dejar la boya por babor ya que ésta es una Marca Lateral de babor.', true, '2025-09-13 13:53:12.826354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4887a62-6db7-4d89-92ef-fd46e127dfe3', 'fcc126aa-a6b9-44e0-895e-aed88f85ed01', 'c', 'Deberemos alejarnos de dicha Marca ya que indica un peligro aislado.', false, '2025-09-13 13:53:12.826553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6ca040c-e017-4ec1-a1fd-d3ac1620b4be', 'fcc126aa-a6b9-44e0-895e-aed88f85ed01', 'd', 'Deberemos consultar la carta náutica para saber si nos queremos dirigir al canal principal o al secundario ya que ésta Marca indica el punto de bifurcación del canal principal a babor.', false, '2025-09-13 13:53:12.826767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e065767-0611-4a57-a8d4-b5135d29e878', '1d934612-d112-4c28-935b-5f822a7d5112', 'a', 'Pueden ir con letras o numeradas.', false, '2025-09-13 13:53:12.827209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('25914953-aa51-4bfa-be6d-d0d278452830', '1d934612-d112-4c28-935b-5f822a7d5112', 'b', 'Generalmente no están destinadas a señalar canales u obstrucciones.', false, '2025-09-13 13:53:12.827402+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd0dadc6-7bd5-4c54-b93b-5707d6ddd279', '1d934612-d112-4c28-935b-5f822a7d5112', 'c', 'Pueden utilizarse para indicar la aproximación a un puerto o estuario.', true, '2025-09-13 13:53:12.827598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dfbd896-9af3-4375-a384-9c706d90cb34', '1d934612-d112-4c28-935b-5f822a7d5112', 'd', 'Cuando la visibilidad no sea buena, los ritmos de las luces amarillas serán distintos a los empleados en las luces blancas.', false, '2025-09-13 13:53:12.827802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b073f8f6-274a-40af-bafa-48de00e383e7', 'e8fc7249-1825-4342-91e6-1d2fa3606ad2', 'a', 'La Marca de Peligro Aislado, se colocará encima, amarrada, o próxima a un peligro, que esté rodeado, por todas partes, de aguas navegables.', true, '2025-09-13 13:53:12.828204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('282dcfc7-00c9-4ff5-8ac6-509a61702e3d', 'e8fc7249-1825-4342-91e6-1d2fa3606ad2', 'b', 'Su marca de tope es una esfera negra.', false, '2025-09-13 13:53:12.828401+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7428298f-861b-4065-86cc-a76662eeba86', 'e8fc7249-1825-4342-91e6-1d2fa3606ad2', 'c', 'La Marca de Peligro Aislado se colocará encima, amarrada, o próxima a aguas navegables, que estén próximas, en alguna dirección, a algún peligro aislado.', false, '2025-09-13 13:53:12.828598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86f407d4-1bbe-4e31-aef6-fb0604a632c4', 'e8fc7249-1825-4342-91e6-1d2fa3606ad2', 'd', 'Sobre su numeración o rotulación, no podrán utilizarse números o letras para identificar dichas marcas de Peligro Aislado. Reglamento (RIPA).', false, '2025-09-13 13:53:12.828797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('801af31d-62e9-40c4-baaa-4f2324826c69', '2d75ea34-9b6a-4777-a6ac-157acf376bc8', 'a', 'Dos luces todo horizonte en línea vertical, blanca la superior y verde la inferior, una luz de tope a popa y más elevada que la luz verde todo horizonte.', false, '2025-09-13 13:53:12.829232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f88f543-f941-450d-b595-89dfd09ad01d', '2d75ea34-9b6a-4777-a6ac-157acf376bc8', 'c', 'Dos luces todo horizonte en línea vertical, roja la superior y blanca la inferior, una luz blanca todo horizonte en la dirección del aparejo, además de las luces de costado y una luz de alcance.', true, '2025-09-13 13:53:12.829635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f35fb495-ffaa-45d1-9fc9-ae9e2d4d427d', '092df105-b4cb-430a-b38d-f8c18773ad7f', 'c', 'Salga al mar repitiendo su última travesía. Si no lo encuentra, solicite ayuda a embarcaciones cercanas.', false, '2025-09-13 13:53:12.820157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbedc857-fc66-4444-b9a5-341a106a151b', 'c0d10d08-85f5-4712-bda2-bdda7b16e799', 'b', 'Tengo un buzo sumergido.', true, '2025-09-13 13:53:12.822054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35cd7ea1-0925-40e8-b126-d6276c65ebe2', '071d3ac4-2c37-41a4-8a1b-c24a536c5ac0', 'c', 'La estabilidad transversal depende de la posición relativa del centro de carena y del centro de gravedad.', true, '2025-09-13 13:53:12.818027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0b05cff-a21b-4166-b942-ff0b0a0e6b87', '2d75ea34-9b6a-4777-a6ac-157acf376bc8', 'd', 'Dos luces todo horizonte en línea vertical, verde la superior y blanca la inferior, una luz blanca todo horizonte en la dirección del aparejo, además de las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:12.829872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb63ef96-7a1f-4095-b05b-fe3081015023', '05501b30-1d6b-4bd4-94c1-df6f4f1e1799', 'b', 'Las Reglas relativas a las marcas deberán cumplirse tanto de día como de noche.', false, '2025-09-13 13:53:12.830483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29d0df80-900a-4884-94a5-3820c9bd380b', '05501b30-1d6b-4bd4-94c1-df6f4f1e1799', 'c', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', true, '2025-09-13 13:53:12.83069+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da53f3f9-ff83-4c53-a457-e24227df367f', '05501b30-1d6b-4bd4-94c1-df6f4f1e1799', 'd', 'Las luces preceptuadas por estas Reglas podrán no exhibirse desde la salida hasta la puesta del sol aunque haya visibilidad reducida, si el patrón no lo considera necesario.', false, '2025-09-13 13:53:12.83092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('254b5a9c-15e8-49e1-b7d5-77e5d31adcac', '44058b74-2e30-45ff-a9c9-eaddfa02cb2a', 'a', 'Siempre que no disponga de maquinaria propulsora instalada a bordo.', false, '2025-09-13 13:53:12.83138+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6230bc93-4ed7-4931-9024-046c6828ef64', '44058b74-2e30-45ff-a9c9-eaddfa02cb2a', 'b', 'Que sea incapaz de apartarse de la derrota de otro buque debido a su posición relativa al viento.', false, '2025-09-13 13:53:12.831607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38df482b-4409-41ed-882e-ed04abf728b2', '44058b74-2e30-45ff-a9c9-eaddfa02cb2a', 'c', 'Cuya forma de sus velas no restrinja su maniobrabilidad.', false, '2025-09-13 13:53:12.831801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('880f75e4-9c41-45b1-9bfd-e9fe66f75c27', '44058b74-2e30-45ff-a9c9-eaddfa02cb2a', 'd', 'Siempre que su maquinaria propulsora, en caso de llevarla, no se esté utilizando.', true, '2025-09-13 13:53:12.832005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42d7a66d-7b5f-4073-944c-d20b592a7a62', '6c363d20-abd9-4d25-abda-1a90f784fc93', 'a', 'Un sonido de una duración aproximada de 4 a 6 segundos.', true, '2025-09-13 13:53:12.832442+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc357be4-f2f3-4d02-a206-51f2de9af270', '6c363d20-abd9-4d25-abda-1a90f784fc93', 'b', 'Un sonido de una duración aproximada de 8 a 10 segundos.', false, '2025-09-13 13:53:12.832641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed5ba0ec-8d8f-4fc9-a271-fe31e467a841', '6c363d20-abd9-4d25-abda-1a90f784fc93', 'c', 'Un sonido de una duración de 7 segundos.', false, '2025-09-13 13:53:12.832843+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb68a2ee-fd95-4ff8-b8da-828ea732dfbd', '6c363d20-abd9-4d25-abda-1a90f784fc93', 'd', 'Un sonido de una duración de 8 segundos.', false, '2025-09-13 13:53:12.833078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d6396ce-90ca-4269-b6bc-c7fe1fb27815', 'cb57e348-6823-4897-a6a3-ffd45bd0a22d', 'a', 'Un buque de propulsión mecánica en navegación.', false, '2025-09-13 13:53:12.833502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6dfb7357-e508-458b-8057-47f030cdaa1b', 'cb57e348-6823-4897-a6a3-ffd45bd0a22d', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:12.833692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4298459d-e68b-4ab2-9722-3c6b5fb0ea16', 'cb57e348-6823-4897-a6a3-ffd45bd0a22d', 'c', 'Un hidroavión amarado.', false, '2025-09-13 13:53:12.833905+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0600319-1b88-47c7-acff-6bc0943581ac', 'cb57e348-6823-4897-a6a3-ffd45bd0a22d', 'd', 'Una nave de vuelo rasante cerca de la superficie.', false, '2025-09-13 13:53:12.834113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7dc5967-29c1-441e-8a25-48cecf680c00', 'a3bd9d03-e42f-432f-9d25-1740d69231ca', 'b', 'No tendremos la obligación de exhibir la luz blanca todo horizonte de fondeo.', true, '2025-09-13 13:53:12.834731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5cfda53-78bf-4dde-ada4-97c4b1e8bae6', 'a3bd9d03-e42f-432f-9d25-1740d69231ca', 'c', 'Estamos obligados a exhibir una marca con forma de bola.', false, '2025-09-13 13:53:12.834959+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef61951d-d369-4be1-841f-3bb9db888519', 'a3bd9d03-e42f-432f-9d25-1740d69231ca', 'd', 'No podremos utilizar luces para iluminar la zona de cubierta ni la bañera, debiendo exhibir obligatoriamente dos luces todo horizonte blancas, una a proa y otra a popa.', false, '2025-09-13 13:53:12.835182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15c04df0-9587-4171-a763-a4823a0c2ded', '11af0acc-6d83-4795-8db8-3d90f1508048', 'a', 'Podrá usar la zona de navegación costera.', true, '2025-09-13 13:53:12.835604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9935b5b3-7465-43ec-9c75-ecb714e09188', '11af0acc-6d83-4795-8db8-3d90f1508048', 'b', 'Deberá en cualquier caso utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-13 13:53:12.835819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70bb90a9-9a9e-43be-9a58-a007f562432e', '11af0acc-6d83-4795-8db8-3d90f1508048', 'c', 'Navegará exclusivamente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:12.836026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5efcb78d-6d11-4688-9838-bfe69227b653', '11af0acc-6d83-4795-8db8-3d90f1508048', 'd', 'En caso de necesidad de cruce del dispositivo, deberá hacerlo siguiendo un rumbo que en la medida de lo posible forme una paralela a la dirección general de la corriente del tráfico.', false, '2025-09-13 13:53:12.836226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a19ad42-fbe6-4246-a04d-5bd2457889c1', '142db55a-4e52-47e8-aa9b-8e95529bb8a3', 'a', 'Mayor de 22,5° a popa del través de este último.', true, '2025-09-13 13:53:12.836635+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('203f1240-3d57-4eaf-b29e-67bcd19b066b', '142db55a-4e52-47e8-aa9b-8e95529bb8a3', 'b', 'Menor de 22,5° a popa del través de este último.', false, '2025-09-13 13:53:12.836835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7bb3af4-8ed6-4847-8102-5fa104bf3f7d', '142db55a-4e52-47e8-aa9b-8e95529bb8a3', 'c', 'Mayor de 22,5° a proa del través de este último.', false, '2025-09-13 13:53:12.837044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f94aa029-4a4f-44c6-b322-943764a4c301', '142db55a-4e52-47e8-aa9b-8e95529bb8a3', 'd', 'Menor de 22,5° a proa del través de este último.', false, '2025-09-13 13:53:12.837259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f23da621-d7b8-4f2e-84a4-8532b4a31133', '7d091313-971d-478e-8226-5a1278533839', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un buque dedicado a la pesca.', false, '2025-09-13 13:53:12.837679+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aeb032e9-e399-42ff-8763-2be0e5156d34', '7d091313-971d-478e-8226-5a1278533839', 'b', 'Aumentar la velocidad ligeramente para tratar de propiciar que la otra embarcación haga la maniobra ante el posible peligro de abordaje, y así evitar un cambio de rumbo en nuestra derrota.', false, '2025-09-13 13:53:12.83792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86460cae-0234-4c6a-9e5e-036dee4ace29', '7d091313-971d-478e-8226-5a1278533839', 'c', 'Si las circunstancias del caso lo permiten, realizar cambios de rumbo y velocidad amplios que sean fácilmente percibidos por la otra embarcación.', true, '2025-09-13 13:53:12.838213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b7d0d54-ad8b-4be1-bbdb-60c5400ed6a7', '7d091313-971d-478e-8226-5a1278533839', 'd', 'Cambiar de rumbo ligeramente para desviar nuestra derrota lo menos posible y, ante todo, nunca suprimir la arrancada ya que una disminución de la velocidad siempre se traduce en una pérdida de capacidad de maniobra.', false, '2025-09-13 13:53:12.838432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcfa4b0a-0667-43a1-9470-cc70aafbc65f', '333627e2-bd53-4e4a-8aef-95c3f712e0a0', 'a', 'Varado.', false, '2025-09-13 13:53:12.838841+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44c816ac-f5a7-4c6a-93f2-a571bba3e5b1', '333627e2-bd53-4e4a-8aef-95c3f712e0a0', 'b', 'Fondeado.', false, '2025-09-13 13:53:12.839046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd6b276f-5f56-4a33-8f93-27063a5ad4dc', '333627e2-bd53-4e4a-8aef-95c3f712e0a0', 'c', 'Restringido por su calado.', true, '2025-09-13 13:53:12.839248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8b4c3dd-b026-4147-85aa-89517c613493', 'c61f465b-07c2-4ce0-8015-1119e51e5773', 'a', 'Dificulta la maniobra.', false, '2025-09-13 13:53:12.839986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('792cc2c2-c068-49ac-a5e9-ad6c69bca450', 'c61f465b-07c2-4ce0-8015-1119e51e5773', 'b', 'Facilita la maniobra.', true, '2025-09-13 13:53:12.840224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfdbd9fa-1f43-47a5-8e55-cc720ecbe054', 'c61f465b-07c2-4ce0-8015-1119e51e5773', 'c', 'Es indiferente la banda por la que se reciba el viento.', false, '2025-09-13 13:53:12.840435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddbcec54-5879-4c4e-94ec-b2c7b836019b', 'c61f465b-07c2-4ce0-8015-1119e51e5773', 'd', 'Solo afecta a los buques con vela o mercantes.', false, '2025-09-13 13:53:12.840653+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('272470c1-16fb-43dd-9602-e5cfc915d686', '49c5b4b6-5a1e-450f-b49f-e95f0e97b281', 'a', 'La popa caerá a babor.', true, '2025-09-13 13:53:12.841127+00');
