INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95d7ce0c-4e6f-48dd-9e90-bc33e84b9438', '0f07c0db-b616-45ed-88d8-c5fe6668c03e', 'b', 'Piezas en forma de «T» o «doble T» que suelen ir en cubierta para amarrar cabos ligeros o en un palo para amarrar las drizas de las banderas.', false, '2025-09-13 13:53:12.860679+00');
