INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0bff141-6d14-44db-9f62-62ed5298b427', '52abfbf3-35db-4393-ad65-7196c7802bd1', 'd', 'El desvío.', true, '2025-09-13 13:53:12.854523+00');
