INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35564bdc-9e35-4f92-8982-f1ddc0df6f04', 'f08af29e-9308-4ff9-bcea-c34314a43266', 'd', 'Orinque.', true, '2025-09-13 13:53:12.864231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f589a128-1344-413d-a611-c8d67ae3170c', '6f05797a-40cb-4dcc-84da-0675559336fb', 'a', 'En el momento del fondeo se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente por el fondo.', false, '2025-09-13 13:53:12.864678+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30c0a106-1f60-4293-a102-9f0d8acd3992', '6f05797a-40cb-4dcc-84da-0675559336fb', 'b', 'De forma general, la longitud de cadena para un fondeo con buen tiempo no será inferior a tres veces la sonda del lugar de fondeo.', false, '2025-09-13 13:53:12.864885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a14ef603-f9e9-41f8-a9d0-688d5e48a330', '6f05797a-40cb-4dcc-84da-0675559336fb', 'c', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de la embarcación, dando la proa al viento.', true, '2025-09-13 13:53:12.865075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe7597fd-ab28-4cef-bd3c-846d316752d8', '6f05797a-40cb-4dcc-84da-0675559336fb', 'd', 'Si se comprueba que la embarcación garrea, se recomienda virar el ancla y volver a fondear.', false, '2025-09-13 13:53:12.865292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7c485fd-177d-43ef-8c0b-a8296ff8219c', 'b58e99fb-c993-4bfa-ac53-ca7de853b045', 'a', 'Al capear el temporal debemos reducir la velocidad incluso parando la arrancada.', true, '2025-09-13 13:53:12.865758+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b3ebc08-61b2-4aaa-b699-18aeed37fee4', 'b58e99fb-c993-4bfa-ac53-ca7de853b045', 'b', 'Correr el temporal es una maniobra cómoda, pero, con mal tiempo, existe el problema de que pueden embarcar fuertes golpes de mar.', false, '2025-09-13 13:53:12.865974+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f176d65-a465-4f39-9a71-32c430910cc5', 'b58e99fb-c993-4bfa-ac53-ca7de853b045', 'd', 'Para capear el temporal nos podemos ayudar mediante el uso de un ancla flotante.', false, '2025-09-13 13:53:12.866395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c71992d-9eda-4fef-882f-f0680fbf6d63', '911eb9fe-0e9e-4d7b-98a3-d756e1108300', 'a', 'Con la estación de radio, canal 70 VHF.', false, '2025-09-13 13:53:12.866821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c80b2117-a035-4455-9327-91cf7b2f608d', '911eb9fe-0e9e-4d7b-98a3-d756e1108300', 'b', 'Con la estación de radio, canal 16 VHF.', false, '2025-09-13 13:53:12.867041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f25850c2-1082-421a-a6cd-551961d63e98', '911eb9fe-0e9e-4d7b-98a3-d756e1108300', 'c', 'Por teléfono, llamando al 900 200 200.', true, '2025-09-13 13:53:12.86724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ecf4a6c-1abf-49ab-afff-29b7e13aea57', '911eb9fe-0e9e-4d7b-98a3-d756e1108300', 'd', 'Por teléfono, llamando al 900 202 202.', false, '2025-09-13 13:53:12.867437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('063be320-93a7-47e3-827e-37dcf1bacb3c', 'e83fea86-d3f7-416d-9ab2-8e43362119f1', 'a', 'Librar al náufrago de la hélice, no perderle de vista y lanzarle ayudas.', true, '2025-09-13 13:53:12.867855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d588453-2310-46bc-ae83-e2a460fa2b8f', 'e83fea86-d3f7-416d-9ab2-8e43362119f1', 'b', 'Librar al náufrago de la hélice, parar el motor, lanzarle ayudas y saltar al agua en su busca.', false, '2025-09-13 13:53:12.868049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d71cd8cd-6798-486e-859d-4726a4e4a82d', 'e83fea86-d3f7-416d-9ab2-8e43362119f1', 'c', 'Dar atrás y acercarnos lentamente por la popa, sin perder de vista al náufrago, para evitar que la proa pueda dañarlo.', false, '2025-09-13 13:53:12.868244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41caae09-5e7f-43c0-8ddf-95a98b4fbcae', 'e83fea86-d3f7-416d-9ab2-8e43362119f1', 'd', 'Saltar al agua en su busca para evitar que se ahogue.', false, '2025-09-13 13:53:12.868466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a56594aa-fb11-4cc4-942e-020e5d8ccbbf', '35886648-3a1e-46ca-bd6f-67ebcb3ec459', 'a', 'Un sistema de detección de barcos que es obligatorio en cualquier tipo de embarcación.', false, '2025-09-13 13:53:12.868906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c0b9796-7a2b-4e3a-89b3-182afd42bdd0', '35886648-3a1e-46ca-bd6f-67ebcb3ec459', 'b', 'Un elemento de ayuda para que las embarcaciones de casco no metálico produzcan ecos en las pantallas de radar de otros barcos.', true, '2025-09-13 13:53:12.869136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35036939-0cd7-4997-8016-e00837bc22ec', '35886648-3a1e-46ca-bd6f-67ebcb3ec459', 'c', 'Un dispositivo destinado a evitar la detección de nuestra embarcación por el radar de otros barcos, por motivos de protección.', false, '2025-09-13 13:53:12.869336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eb34322-0dfd-4354-9766-d4b244632de5', '35886648-3a1e-46ca-bd6f-67ebcb3ec459', 'd', 'La antena del sistema de radar del barco, siendo obligatorio sólo en embarcaciones de fibra o', false, '2025-09-13 13:53:12.869564+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddbe5676-78ea-4262-a774-b89a98feaf9a', 'd7f1cc07-d503-4960-9459-06072f089bae', 'a', 'Tres días hábiles.', false, '2025-09-13 13:53:12.870011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6d3e622-2d55-4f4b-99b4-b1393437aaca', 'd7f1cc07-d503-4960-9459-06072f089bae', 'b', 'Diez días hábiles.', false, '2025-09-13 13:53:12.870213+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('335b711e-9eb9-4b4d-9196-3e97e7d0190f', 'd7f1cc07-d503-4960-9459-06072f089bae', 'c', 'Cinco días hábiles.', true, '2025-09-13 13:53:12.870426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80cd1a3a-84ad-427b-86d3-7ea5f7238997', 'd7f1cc07-d503-4960-9459-06072f089bae', 'd', 'Quince días hábiles.', false, '2025-09-13 13:53:12.870626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf3783ff-35f0-4b08-a9f7-5efc8bfbd2b9', '3f9fd893-d69f-4bb7-b245-4fc108a775d0', 'a', 'Cuando las basuras estén mezcladas con otras sustancias cuya descarga esté prohibida o para las que rijan distintas prescripciones de descarga, se aplicarán las prescripciones más rigurosas.', true, '2025-09-13 13:53:12.871034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d811415b-c257-402c-8d60-0214cfd6eae6', '3f9fd893-d69f-4bb7-b245-4fc108a775d0', 'b', 'Los aditivos de limpieza contenidos en las aguas de lavado podrán descargarse al mar, aunque sean perjudiciales para el medio marino.', false, '2025-09-13 13:53:12.871233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('245b6a7a-e4ac-48fe-850a-6306e787bd9b', '3f9fd893-d69f-4bb7-b245-4fc108a775d0', 'c', 'La descarga de basuras en el mar fuera de las zonas especiales está prohibida sin excepciones.', false, '2025-09-13 13:53:12.871445+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c872d9e8-878f-4ec6-9158-7e16595a3da1', '3f9fd893-d69f-4bb7-b245-4fc108a775d0', 'd', 'Los restos de alimentos a descargar estarán desmenuzados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', false, '2025-09-13 13:53:12.871643+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6937941d-c7d2-4acf-ab33-406687725208', '709516c5-93f7-4bee-85a8-3028f8754d43', 'a', 'Si tienen luz, es amarilla.', false, '2025-09-13 13:53:12.872052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39cfe09b-61a3-4d92-8480-77c96d8d7147', '709516c5-93f7-4bee-85a8-3028f8754d43', 'b', 'Indican una zona o una configuración particular cuya naturaleza exacta está indicada en la carta u otro documento náutico.', false, '2025-09-13 13:53:12.872262+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27f12a91-8e40-40d9-8d88-cd35292aad7b', '709516c5-93f7-4bee-85a8-3028f8754d43', 'c', 'No señalan ningún peligro.', true, '2025-09-13 13:53:12.87248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e083ec8-122b-433f-b4da-1e15277d09e6', '709516c5-93f7-4bee-85a8-3028f8754d43', 'd', 'Si tienen marca de tope es una única esfera verde.', false, '2025-09-13 13:53:12.872682+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22fd1af0-44ed-41a7-b937-cd5fe5636f50', 'bc3d5b6e-365d-4205-9971-b9bdf2717939', 'a', 'Con los vértices hacia arriba.', false, '2025-09-13 13:53:12.873102+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02456b38-dca2-4162-9939-4a321f253375', 'bc3d5b6e-365d-4205-9971-b9bdf2717939', 'b', 'Con los vértices hacia abajo.', false, '2025-09-13 13:53:12.873313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cef6a8d9-e0d2-4560-ac9a-9b681bf73062', 'bc3d5b6e-365d-4205-9971-b9bdf2717939', 'c', 'Opuestos por sus bases.', false, '2025-09-13 13:53:12.87351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42cdfdb7-d301-4bcd-ae42-728b746bf33e', 'bc3d5b6e-365d-4205-9971-b9bdf2717939', 'd', 'Opuestos por sus vértices.', true, '2025-09-13 13:53:12.873728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9a82175-70be-4fca-bb06-717b8066f59b', 'd18ee032-3859-4dac-a012-cbbc56276a7c', 'a', 'Será de color blanco.', true, '2025-09-13 13:53:12.874196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2906a8d7-3d67-421b-b6e2-bab72061a40c', 'd18ee032-3859-4dac-a012-cbbc56276a7c', 'b', 'Será de color azul.', false, '2025-09-13 13:53:12.874409+00');
