INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e00779b-8913-4896-a772-16fbe9726f4d', 'c6eee892-08f1-4df8-b4c6-e0bf3233d917', 'c', 'Límites de las áreas de fondeo.', false, '2025-09-13 13:53:12.875668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9326cba0-d3ce-495c-b2ad-f04fb05ffab0', 'c6eee892-08f1-4df8-b4c6-e0bf3233d917', 'd', 'La aproximación a un puerto o estuario.', true, '2025-09-13 13:53:12.875879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea1dc5bd-6393-4690-b0a7-aa2a7c6539d3', 'd76c6498-ac62-4712-a785-e082c75a304c', 'a', 'Verde con una banda ancha horizontal roja.', true, '2025-09-13 13:53:12.876286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daf47648-4c77-4926-9ad2-78526ef973c8', 'd76c6498-ac62-4712-a785-e082c75a304c', 'b', 'Verde con una luz verde centelleante rápida continua.', false, '2025-09-13 13:53:12.876482+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e2f285a-9033-441d-9f18-964ac915c450', 'd76c6498-ac62-4712-a785-e082c75a304c', 'c', 'Roja con una luz roja con ritmo de destello en grupos de 2+1.', false, '2025-09-13 13:53:12.876676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c6f9b04-252f-46de-bbc5-61312b6763ee', 'bd358518-3633-42a7-80eb-bf0451228255', 'd', 'Capacete.', false, '2025-09-13 13:53:12.863226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ea16e99-8ef7-4610-a71f-0719acb6c7fe', '90bdfd55-0435-401e-a93f-2acb39a4fe9c', 'a', 'A babor respecto a un buque situado a proa del través, salvo que el otro buque esté siendo alcanzado.', true, '2025-09-13 13:53:12.877313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08261aca-164f-400b-a01f-5da0f3ac8bf4', 'd76c6498-ac62-4712-a785-e082c75a304c', 'd', 'Roja con una banda ancha horizontal verde.', false, '2025-09-13 13:53:12.876874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7259856c-9a75-42ec-aae3-a60749b9a595', '90bdfd55-0435-401e-a93f-2acb39a4fe9c', 'b', 'A estribor respecto a un buque situado a proa del través, especialmente si el otro buque está siendo alcanzado.', false, '2025-09-13 13:53:12.877522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e028d045-ce3a-416a-9f2e-891039bbac11', '90bdfd55-0435-401e-a93f-2acb39a4fe9c', 'c', 'A babor respecto a todo buque situado a popa del través.', false, '2025-09-13 13:53:12.877739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3ac8558-71b5-4fc6-9a62-0dfffb8ff844', '90bdfd55-0435-401e-a93f-2acb39a4fe9c', 'd', 'A estribor respecto a un buque situado a proa del través, si el otro buque no está siendo', false, '2025-09-13 13:53:12.877964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eafdfcf7-4058-439c-b73d-1936e55f966a', '751b6197-325a-4110-aba2-1bda4e8dd364', 'a', 'Vuelta encontrada.', true, '2025-09-13 13:53:12.87841+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('330b4814-5cb8-44e6-96b0-fb6400df2991', '751b6197-325a-4110-aba2-1bda4e8dd364', 'b', 'Alcance.', false, '2025-09-13 13:53:12.878607+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab9c4082-346d-4520-9230-ab2a34fbb8b5', '751b6197-325a-4110-aba2-1bda4e8dd364', 'c', 'Cruce.', false, '2025-09-13 13:53:12.878804+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e138d26c-5fa2-403f-83bc-27d8b9cae23e', '751b6197-325a-4110-aba2-1bda4e8dd364', 'd', 'Buque de pesca faenando.', false, '2025-09-13 13:53:12.878997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3be3c588-bd5f-4db9-bdee-1a0496ea9e06', '0d9587cd-370a-4738-84b6-7c5f43518445', 'a', 'Navegue a vela y no sea propulsado mecánicamente.', false, '2025-09-13 13:53:12.879413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fe50d00-b06b-4193-a0dc-6e05cc4d1bd1', '0d9587cd-370a-4738-84b6-7c5f43518445', 'c', 'Navegue a vela y también sea propulsado mecánicamente.', true, '2025-09-13 13:53:12.879827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68c3b43f-7753-4aac-81ad-320a3ec83ba2', '0d9587cd-370a-4738-84b6-7c5f43518445', 'd', 'Navegue solo propulsado mecánicamente.', false, '2025-09-13 13:53:12.880023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('019af5d7-7954-4098-9b34-8413bd323fab', '3efcd3ea-6510-4949-82d3-171c6aa11d66', 'a', 'Exhibirá luces que, por sus características y situación, sean lo más parecidas posible a las prescritas en dicha regla.', true, '2025-09-13 13:53:12.880464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f706bad-f3b6-462d-9b5b-2edd42474f35', '3efcd3ea-6510-4949-82d3-171c6aa11d66', 'b', 'Tendrá prohibida la navegación.', false, '2025-09-13 13:53:12.880655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4652844-c784-4661-9600-c2e4ccfa5294', '3efcd3ea-6510-4949-82d3-171c6aa11d66', 'c', 'Lo indicará colocando en el lugar más visible una luz amarilla de centelleos todo horizonte.', false, '2025-09-13 13:53:12.880848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e5a318a-d7cb-4595-929b-f744de957e81', '3efcd3ea-6510-4949-82d3-171c6aa11d66', 'd', 'Las sustituirá todas por una única luz roja centelleante todo horizonte de gran intensidad.', false, '2025-09-13 13:53:12.881053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcb30f44-88d8-4587-a336-9d4c5fb8ce32', '7dead5a9-fa64-475c-b988-708c74696a22', 'a', 'El resplandor de las luces de tierra siempre beneficiará la distinción de otros buques o marcas de balizamiento de noche.', false, '2025-09-13 13:53:12.881483+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('956c5ef0-0212-4595-9d67-4d9d25f614ec', '7dead5a9-fa64-475c-b988-708c74696a22', 'b', 'Un equipo radar funcionando correctamente nunca debe ser utilizado para determinar la velocidad de seguridad en condiciones de mala visibilidad.', false, '2025-09-13 13:53:12.881696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('126164ae-019c-4b9a-8721-608e98920cf6', '7dead5a9-fa64-475c-b988-708c74696a22', 'c', 'En condiciones de mala visibilidad, se debe aumentar la velocidad al máximo para evitar pasar más tiempo de lo necesario expuestos a posibles peligros.', false, '2025-09-13 13:53:12.881918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81b886ec-382d-42d3-8486-38650de9b1f1', '7dead5a9-fa64-475c-b988-708c74696a22', 'd', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca, condicionará la maniobra adecuada y eficaz para evitar un abordaje.', true, '2025-09-13 13:53:12.88214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2459253e-e477-4402-9ff3-dc8a3ad29744', '3e76c868-f200-4ce9-9733-023348876bae', 'a', 'Para evitar un peligro inmediato.', true, '2025-09-13 13:53:12.882543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab088c19-ba21-404b-b99d-c3872f0045cd', '3e76c868-f200-4ce9-9733-023348876bae', 'b', 'Exclusivamente cuando estén en ruta hacia un puerto dentro de la zona de navegación costera.', false, '2025-09-13 13:53:12.88275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b71ee048-85ac-478a-9b5d-dc430098b52f', '3e76c868-f200-4ce9-9733-023348876bae', 'c', 'Por ser un buque menor de 30 metros de eslora puede utilizar la zona de navegación costera siempre que lo necesite.', false, '2025-09-13 13:53:12.882963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bc0f6d2-4ba0-4e93-8246-f473017dcac7', '3e76c868-f200-4ce9-9733-023348876bae', 'd', 'Únicamente en el caso de que deba maniobrar a un buque que tenga preferencia de paso, y el ancho del dispositivo no sea suficiente para realizar la maniobra con seguridad.', false, '2025-09-13 13:53:12.883159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d15a0b7d-6ac3-43f2-9050-3a6f833ec840', 'a67cf75a-b67d-444b-a0ca-a854c8fcedd5', 'a', 'Un aerodeslizador navegando a gran velocidad.', false, '2025-09-13 13:53:12.883591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f361a08-6294-4dbf-bacb-f24d35de23dd', 'a67cf75a-b67d-444b-a0ca-a854c8fcedd5', 'b', 'Una nave de vuelo rasante, despegando, aterrizando o volando cerca de la superficie.', true, '2025-09-13 13:53:12.883807+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d339fac2-3d28-42b1-aa28-c5b8ec9afed5', 'a67cf75a-b67d-444b-a0ca-a854c8fcedd5', 'c', 'Una nave de gran velocidad navegando a una velocidad superior a 30 nudos.', false, '2025-09-13 13:53:12.884034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('012cc65d-b186-436c-ad66-ae3ddb713ac2', 'a67cf75a-b67d-444b-a0ca-a854c8fcedd5', 'd', 'Un submarino navegando en superficie.', false, '2025-09-13 13:53:12.88425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7271239-96c0-458f-b9a8-e4a952bb9fd6', 'f67dce85-943e-48f8-a35d-f02c1f7b0b54', 'a', 'Emitirá una señal acústica de al menos cinco pitadas cortas y rápidas y se maniobrará al buque de vela si fuera necesario para evitar el abordaje.', true, '2025-09-13 13:53:12.884648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8066c78-af81-4ae6-bb0e-134c3d405ae1', 'f67dce85-943e-48f8-a35d-f02c1f7b0b54', 'c', 'Cederá el paso al buque de vela, aun no existiendo riesgo de abordaje, ya que tienen la preferencia de tránsito por el canal al ir sin maquinaria propulsora.', false, '2025-09-13 13:53:12.885066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f6ba4a2-c3cc-4150-8327-8e315941b319', 'f67dce85-943e-48f8-a35d-f02c1f7b0b54', 'd', 'Fondeará en el canal, en cualquier caso, hasta que el buque de vela termine de estorbar nuestro', false, '2025-09-13 13:53:12.88526+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17900168-7447-4802-8f68-3d1da191adbc', '96f2cd88-269d-41ad-9e77-d9c31d8fdeb5', 'a', 'Un buque dedicado a la pesca, fondeado.', false, '2025-09-13 13:53:12.88566+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f46caa25-3e26-45b6-92dc-becc9992fbab', '96f2cd88-269d-41ad-9e77-d9c31d8fdeb5', 'b', 'Una embarcación de prácticos, con arrancada, en servicio de practicaje.', true, '2025-09-13 13:53:12.885855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('12bde38e-ec16-4161-9af2-19812b66b3ba', '96f2cd88-269d-41ad-9e77-d9c31d8fdeb5', 'c', 'Un buque de eslora igual o superior a 100 metros, fondeado.', false, '2025-09-13 13:53:12.886036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48ebd571-f741-4d01-96b9-eddb274ed3cc', '96f2cd88-269d-41ad-9e77-d9c31d8fdeb5', 'd', 'Un buque remolcador que tenga restringida su maniobra.', false, '2025-09-13 13:53:12.886221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('775388b9-eed3-426e-8e0a-ccf8d55bfbef', '89e8832e-b156-493d-b33b-6c434de87bb5', 'a', 'Únicamente una campana.', false, '2025-09-13 13:53:12.886623+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27b82d69-e462-4d33-9d96-6b2253942312', '89e8832e-b156-493d-b33b-6c434de87bb5', 'b', 'Un pito y una campana.', true, '2025-09-13 13:53:12.886823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a9d9b03-f134-4b37-8b63-94bd4e03f562', '89e8832e-b156-493d-b33b-6c434de87bb5', 'c', 'Una campana y un gong.', false, '2025-09-13 13:53:12.887022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b09a6e4-c355-416c-8ed9-07b0c1b098cb', 'f18e51f9-46dd-440a-9d5b-fd0816c0c4eb', 'a', 'Embobinar.', false, '2025-09-13 13:53:12.887631+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c79403c1-2841-4366-809c-16eb5f874ff4', 'f18e51f9-46dd-440a-9d5b-fd0816c0c4eb', 'b', 'Enroscar.', false, '2025-09-13 13:53:12.887829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c203e3dc-f6ea-4ffd-b6bd-aa0bde44fe5e', 'f18e51f9-46dd-440a-9d5b-fd0816c0c4eb', 'c', 'Adujar.', true, '2025-09-13 13:53:12.888031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('158d5175-0cae-4382-a71c-f965f90065fc', 'f18e51f9-46dd-440a-9d5b-fd0816c0c4eb', 'd', 'Ordenar.', false, '2025-09-13 13:53:12.888221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('575d9d83-ad13-46a1-b8a7-0805ed409aa0', 'bdb4a18d-04a0-462f-a242-7063f2a6c034', 'b', 'Aproximarnos a la boya por su barlovento para facilitar el amarre.', true, '2025-09-13 13:53:12.888816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a2d065f-861e-47a5-a8c9-60e564fd4499', 'bdb4a18d-04a0-462f-a242-7063f2a6c034', 'c', 'Aproximarnos a la boya por su sotavento para facilitar el amarre.', false, '2025-09-13 13:53:12.889028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a333d0a-f7ce-467e-9928-2c7258e6e593', 'fa422869-9ae1-47e0-809b-b38a4e117e89', 'a', 'Sofocar el fuego mediante la eliminación del comburente.', false, '2025-09-13 13:53:12.889616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('391bce3e-e581-4193-8721-2b54f2bf9321', 'fa422869-9ae1-47e0-809b-b38a4e117e89', 'b', 'Poner la embarcación en la misma dirección que sopla el viento y a la misma velocidad para que el viento aparente sea cero.', true, '2025-09-13 13:53:12.889829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd5e7cf7-20c4-4b81-a25a-da3a3cdc55a2', 'fa422869-9ae1-47e0-809b-b38a4e117e89', 'c', 'Confinar el fuego para eliminar el combustible.', false, '2025-09-13 13:53:12.890029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcca04bd-1c15-4671-a7d1-3e4262947509', 'fa422869-9ae1-47e0-809b-b38a4e117e89', 'd', 'Neutralizar los radicales libres que actúan en la reacción en cadena.', false, '2025-09-13 13:53:12.890242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c092e5e-3e2a-41cc-8242-ad8e46a5c0a8', 'dafa6f38-c874-425a-8b3b-b46b0525e426', 'a', 'Lo primero que debemos hacer siempre, es, lo antes posible, separar las embarcaciones involucradas en el abordaje.', false, '2025-09-13 13:53:12.890668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48919467-2a91-4135-915e-bea5f92c18c6', 'dafa6f38-c874-425a-8b3b-b46b0525e426', 'b', 'La evaluación de las averías sufridas debe realizarse durante la peritación de los daños una vez llegados a puerto.', false, '2025-09-13 13:53:12.890884+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db0a1373-eb89-46e9-a2b4-31c40eb1048c', 'dafa6f38-c874-425a-8b3b-b46b0525e426', 'c', 'Estamos obligados a prestar asistencia legal al patrón de la otra embarcación involucrada en caso de que lo necesite.', false, '2025-09-13 13:53:12.891093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e656f9c8-20bc-43d4-a2c4-d1742555515f', 'bdb4a18d-04a0-462f-a242-7063f2a6c034', 'a', 'Dar máquina atrás hasta tener arrancada y aproximarnos a la boya popa al viento para facilitar el amarre.', false, '2025-09-13 13:53:12.88862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c176c8d-5270-4827-88fc-720773990565', '89e8832e-b156-493d-b33b-6c434de87bb5', 'd', 'Únicamente un pito.', false, '2025-09-13 13:53:12.887229+00');
