INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2810cba-36b7-4347-a979-f03723745f65', '7ba175dc-3bd1-4a19-86c0-6039c2f48c69', 'a', 'En el momento del fondeo se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente por el fondo.', false, '2025-09-13 13:53:12.950126+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('026506ce-0928-41a7-8dba-ea1f6aa3ebf1', '7ba175dc-3bd1-4a19-86c0-6039c2f48c69', 'b', 'De forma general, la longitud de cadena para un fondeo con buen tiempo no será inferior a tres veces la sonda del lugar de fondeo.', true, '2025-09-13 13:53:12.950356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fc09e0c-1fbd-47a1-8461-54323bfaa1a0', '7ba175dc-3bd1-4a19-86c0-6039c2f48c69', 'c', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de la embarcación, dando la proa al viento.', false, '2025-09-13 13:53:12.950569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35aad109-df07-4fac-91b1-da90f7bc0dc4', '7ba175dc-3bd1-4a19-86c0-6039c2f48c69', 'd', 'Si se comprueba que la embarcación garrea, se recomienda virar el ancla y volver a fondear.', false, '2025-09-13 13:53:12.950785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('472869b9-0277-4d15-8ba8-4501d93011f2', '3d058026-b048-49ab-9fea-daebf253fb9e', 'a', 'Librar al náufrago de la hélice, no perderle de vista y lanzarle ayudas.', false, '2025-09-13 13:53:12.951217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('087e57e4-0f2b-4c48-8698-7a7433b23a81', '3d058026-b048-49ab-9fea-daebf253fb9e', 'b', 'Librar al náufrago de la hélice, parar el motor, lanzarle ayudas y saltar al agua en su busca.', true, '2025-09-13 13:53:12.951417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bde58fcb-eca1-4acb-9b77-e4327a54ac71', '3d058026-b048-49ab-9fea-daebf253fb9e', 'c', 'Dar atrás y acercarnos lentamente por la popa, sin perder de vista al náufrago, para evitar que la proa pueda dañarlo.', false, '2025-09-13 13:53:12.951616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e761b171-6a3f-4d37-af95-d673f401481c', '3d058026-b048-49ab-9fea-daebf253fb9e', 'd', 'Saltar al agua en su busca para evitar que se ahogue.', false, '2025-09-13 13:53:12.951808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61a23650-ba72-4019-9974-b229219e663a', 'b5182b6b-2f3e-4ae5-b7f2-f39398f7ca32', 'a', 'Un sistema de detección de barcos que es obligatorio en cualquier tipo de embarcación.', false, '2025-09-13 13:53:12.952218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('faaaabe2-7761-434b-ad18-942b6b47665b', 'b5182b6b-2f3e-4ae5-b7f2-f39398f7ca32', 'b', 'Un elemento de ayuda para que las embarcaciones de casco no metálico produzcan ecos en las pantallas de radar de otros barcos.', false, '2025-09-13 13:53:12.952417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea6f4e25-b8e1-4587-aac2-57b0d95c8a91', 'b5182b6b-2f3e-4ae5-b7f2-f39398f7ca32', 'c', 'Un dispositivo destinado a evitar la detección de nuestra embarcación por el radar de otros barcos, por motivos de protección.', true, '2025-09-13 13:53:12.952615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('480c5662-cbaf-4eef-9f2b-25e27c93332c', 'b5182b6b-2f3e-4ae5-b7f2-f39398f7ca32', 'd', 'La antena del sistema de radar del barco, siendo obligatorio sólo en embarcaciones de fibra o', false, '2025-09-13 13:53:12.952842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6757805c-aa40-4d65-a05f-3bca3ceb7293', '210f7cd9-0ff5-4333-9c3a-07da26127210', 'a', 'Con la estación de radio, canal 70 VHF.', true, '2025-09-13 13:53:12.953318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fcf6bd9-98a8-4fbc-ab58-8be22bbb28e0', '210f7cd9-0ff5-4333-9c3a-07da26127210', 'b', 'Con la estación de radio, canal 16 VHF.', false, '2025-09-13 13:53:12.953519+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4e62bec-a8f2-49e7-ba9a-ca92dca3d122', '210f7cd9-0ff5-4333-9c3a-07da26127210', 'c', 'Por teléfono, llamando al 900 200 200.', false, '2025-09-13 13:53:12.953733+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2300b3c2-9333-4a80-8bf5-b9d41b6296a3', '210f7cd9-0ff5-4333-9c3a-07da26127210', 'd', 'Por teléfono, llamando al 900 202 202.', false, '2025-09-13 13:53:12.953973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03381d89-7ef3-47f4-8387-a8510bf8cc6c', '2ec6b192-b0b7-4069-baab-a300f567866b', 'a', 'Al capear el temporal debemos reducir la velocidad incluso parando la arrancada.', false, '2025-09-13 13:53:12.954397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32824705-d3ba-43f4-a8e0-15c1f1bc216f', '2ec6b192-b0b7-4069-baab-a300f567866b', 'b', 'Correr el temporal es una maniobra cómoda, pero, con mal tiempo, existe el problema de que pueden embarcar fuertes golpes de mar.', false, '2025-09-13 13:53:12.954611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ab1d627-a7ab-4c65-8f5c-8dbac4d5837d', '2ec6b192-b0b7-4069-baab-a300f567866b', 'c', 'Elegir capear o correr el temporal dependerá de la embarcación y del grado de fuerza del', true, '2025-09-13 13:53:12.954835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bb362e0-9639-4833-aeee-93f1f0e7bbe4', '2ec6b192-b0b7-4069-baab-a300f567866b', 'd', 'Para capear el temporal nos podemos ayudar mediante el uso de un ancla flotante.', false, '2025-09-13 13:53:12.955048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfff770f-fe7d-410f-9e14-832012a14d09', '34a2eec4-3398-4499-a6ad-7a1378117f95', 'd', 'Un buque remolcador que tenga restringida su maniobra.', false, '2025-09-13 13:53:13.000443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae24dda0-6c6b-453a-a87a-40f6ef732275', 'd7723ef8-71f9-42fe-bd37-b5794a112b05', 'a', 'Cuando las basuras estén mezcladas con otras sustancias cuya descarga esté prohibida o para las que rijan distintas prescripciones de descarga, se aplicarán las prescripciones más rigurosas.', false, '2025-09-13 13:53:12.955489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('300479b8-7052-4818-a902-4cad7600df6d', 'd7723ef8-71f9-42fe-bd37-b5794a112b05', 'b', 'Los aditivos de limpieza contenidos en las aguas de lavado podrán descargarse al mar, aunque sean perjudiciales para el medio marino.', false, '2025-09-13 13:53:12.955732+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f861529-792e-40a0-b37e-d23f97d1a1bd', 'd7723ef8-71f9-42fe-bd37-b5794a112b05', 'c', 'La descarga de basuras en el mar fuera de las zonas especiales está prohibida sin excepciones.', false, '2025-09-13 13:53:12.955947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e521b10-a4f9-44e0-90b9-534ab0c592f7', 'd7723ef8-71f9-42fe-bd37-b5794a112b05', 'd', 'Los restos de alimentos a descargar estarán desmenuzados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', true, '2025-09-13 13:53:12.956193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b554a419-f505-40e7-ba84-b5a71828afec', '792cac4d-c0ef-4baa-b210-0e110b0692ac', 'a', 'Tres días hábiles.', true, '2025-09-13 13:53:12.95665+00');
