INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('117a687d-aaa3-4f5e-810e-acc90822cccc', '46de5e2f-d105-4fbe-9bc0-54e084c9e52c', 'a', 'Un buque dedicado a la pesca, fondeado.', false, '2025-09-13 13:53:12.963848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cbb036ac-c422-489b-9bf0-ae365ee55412', '46de5e2f-d105-4fbe-9bc0-54e084c9e52c', 'b', 'Una embarcación de prácticos, con arrancada, en servicio de practicaje.', true, '2025-09-13 13:53:12.964083+00');
