INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('137e912b-2feb-4d98-a2ca-bff5312cd284', 'a82692a3-b1e6-4870-83d4-222a8af406b0', 'a', 'Exhibirá luces que, por sus características y situación, sean lo más parecidas posible a las prescritas en dicha regla.', false, '2025-09-13 13:53:12.964948+00');
