INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7b718a4-d7c5-45b5-bdf9-d06e6bb3659b', 'a82692a3-b1e6-4870-83d4-222a8af406b0', 'c', 'Lo indicará colocando en el lugar más visible una luz amarilla de centelleos todo horizonte.', true, '2025-09-13 13:53:12.965321+00');
