INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31c7e200-4094-4e8c-bc39-ae6ab99911d3', '9af0a3b4-32f4-4493-902b-4c19bcc215ac', 'a', 'Vuelta encontrada.', false, '2025-09-13 13:53:12.965999+00');
