INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15f40c02-a8b6-4d49-a2ff-cb56215bd399', 'afd937c0-027f-45cd-8b05-aded0935da6c', 'a', 'El resplandor de las luces de tierra siempre beneficiará la distinción de otros buques o marcas de balizamiento de noche.', false, '2025-09-13 13:53:12.967073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14bbbb4d-7a6f-49fc-a89a-3ae4c6c5b210', 'afd937c0-027f-45cd-8b05-aded0935da6c', 'b', 'Un equipo radar funcionando correctamente nunca debe ser utilizado para determinar la velocidad de seguridad en condiciones de mala visibilidad.', false, '2025-09-13 13:53:12.967291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce6b6b42-ed5c-4e4d-b4d9-6b67ee18ae10', 'afd937c0-027f-45cd-8b05-aded0935da6c', 'c', 'En condiciones de mala visibilidad, se debe aumentar la velocidad al máximo para evitar pasar más tiempo de lo necesario expuestos a posibles peligros.', false, '2025-09-13 13:53:12.967491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('199cabaf-acc5-4b13-a0a5-f991b8b6bd32', 'afd937c0-027f-45cd-8b05-aded0935da6c', 'd', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca, condicionará la maniobra adecuada y eficaz para evitar un abordaje.', true, '2025-09-13 13:53:12.967702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b97d620-2cc1-4a47-b5f2-80325122305d', '201d06e4-8794-4bf3-9b58-ee4faec4218a', 'a', 'A babor respecto a un buque situado a proa del través, salvo que el otro buque esté siendo', false, '2025-09-13 13:53:12.968133+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db2b4ae9-c9f9-46f8-b21e-68bb06f8e1ed', '201d06e4-8794-4bf3-9b58-ee4faec4218a', 'b', 'A estribor respecto a un buque situado a proa del través, especialmente si el otro buque está siendo alcanzado.', false, '2025-09-13 13:53:12.968366+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a20e8171-c672-4594-93f1-1146d7277254', '201d06e4-8794-4bf3-9b58-ee4faec4218a', 'c', 'A babor respecto a todo buque situado a popa del través.', true, '2025-09-13 13:53:12.9686+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('17cc8380-f293-4284-8a89-278a8cf2c769', '201d06e4-8794-4bf3-9b58-ee4faec4218a', 'd', 'A estribor respecto a un buque situado a proa del través, si el otro buque no está siendo', false, '2025-09-13 13:53:12.968809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b664005-0b80-427a-ba3c-9a013cb18976', '932d504e-aa9a-4077-8ad4-34cbb0587da6', 'a', 'Para evitar un peligro inmediato.', false, '2025-09-13 13:53:12.969246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1151699-647c-4ac3-9e81-6f067159e80b', '932d504e-aa9a-4077-8ad4-34cbb0587da6', 'b', 'Exclusivamente cuando estén en ruta hacia un puerto dentro de la zona de navegación costera.', true, '2025-09-13 13:53:12.969464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6e05b56-17c7-4028-936b-591a0b9b8ae8', '932d504e-aa9a-4077-8ad4-34cbb0587da6', 'c', 'Por ser un buque menor de 30 metros de eslora puede utilizar la zona de navegación costera siempre que lo necesite.', false, '2025-09-13 13:53:12.969697+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c7362aba-ffbf-4d3b-b977-39b31fa05824', '932d504e-aa9a-4077-8ad4-34cbb0587da6', 'd', 'Únicamente en el caso de que deba maniobrar a un buque que tenga preferencia de paso, y el ancho del dispositivo no sea suficiente para realizar la maniobra con seguridad.', false, '2025-09-13 13:53:12.969901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bc8a76d-bd05-46df-9306-8fab3c087a5d', 'e402a836-7d92-4f20-a4d1-6879c9d1fb09', 'a', 'Navegue a vela y no sea propulsado mecánicamente.', true, '2025-09-13 13:53:12.970325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fc56b71-9df5-4e73-8132-d7630772dbdf', 'e402a836-7d92-4f20-a4d1-6879c9d1fb09', 'b', 'Navegue a vela, no sea propulsado mecánicamente y se encuentre sin arrancada por falta de', false, '2025-09-13 13:53:12.970532+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e258183f-cf52-4fd1-a329-da27a98d3a81', 'e402a836-7d92-4f20-a4d1-6879c9d1fb09', 'c', 'Navegue a vela y también sea propulsado mecánicamente.', false, '2025-09-13 13:53:12.970728+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0262efdd-b8df-45a6-ab1c-a3451c74e4ed', '56d84720-e1ae-4ed1-ba25-709c15e41e7b', 'a', 'Emitirá una señal acústica de al menos cinco pitadas cortas y rápidas y se maniobrará al buque de vela si fuera necesario para evitar el abordaje.', false, '2025-09-13 13:53:12.971359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0d7ef1d-785b-4159-8e3f-2815a936e518', '56d84720-e1ae-4ed1-ba25-709c15e41e7b', 'b', 'Hará sonar una pitada larga para indicar al otro buque que no entiendes sus intenciones y que está', false, '2025-09-13 13:53:12.971575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03d37c0f-11fe-4ba4-9c91-9c8c904c1f8f', '56d84720-e1ae-4ed1-ba25-709c15e41e7b', 'c', 'Cederá el paso al buque de vela, aun no existiendo riesgo de abordaje, ya que tienen la preferencia de tránsito por el canal al ir sin maquinaria propulsora.', true, '2025-09-13 13:53:12.971809+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9c62216-d498-4f6d-8941-52a7344e88bc', '56d84720-e1ae-4ed1-ba25-709c15e41e7b', 'd', 'Fondeará en el canal, en cualquier caso, hasta que el buque de vela termine de estorbar nuestro', false, '2025-09-13 13:53:12.972031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b61e4ef7-b7a8-440c-9883-b1c76ba918be', 'd24ab3eb-e794-4414-8aab-38e4a1545d37', 'a', 'Un aerodeslizador navegando a gran velocidad.', true, '2025-09-13 13:53:12.972472+00');
