INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7154df7f-44ee-47be-be37-8581a0335ef2', '38cfddeb-6803-404b-9ab5-3b738dda7c74', 'a', 'Enderezarse o ponerse vertical.', true, '2025-09-13 13:53:12.973698+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed0603f4-6374-4ba2-9c44-ba394fe16ec2', '38cfddeb-6803-404b-9ab5-3b738dda7c74', 'b', 'Inclinarse sobre uno de sus costados.', false, '2025-09-13 13:53:12.973895+00');
