INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97db9065-0488-4874-ac81-cf542297f2cf', '1840a9e5-9ae0-44fe-b069-a14f1c114e22', 'a', 'En el momento del fondeo se recomienda llevar una ligera arrancada atrás con objeto de que, al caer el ancla, la cadena se extienda correctamente por el fondo.', false, '2025-09-13 13:53:12.978842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79c89027-8a4d-4902-a38f-025d5632df2c', '1840a9e5-9ae0-44fe-b069-a14f1c114e22', 'b', 'De forma general, la longitud de cadena para un fondeo con buen tiempo no será inferior a tres veces la sonda del lugar de fondeo.', false, '2025-09-13 13:53:12.979045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45b5efd7-ed95-4522-b872-d4a9c4cf3447', '1840a9e5-9ae0-44fe-b069-a14f1c114e22', 'c', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de la embarcación, dando la proa al viento.', true, '2025-09-13 13:53:12.979244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7302de56-3e3e-4eeb-81f6-c341733e9de5', '1840a9e5-9ae0-44fe-b069-a14f1c114e22', 'd', 'Si se comprueba que la embarcación garrea, se recomienda virar el ancla y volver a fondear.', false, '2025-09-13 13:53:12.979452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb53e8a4-3ead-4106-a186-25db7f288a68', 'c20842ad-3a4d-4aa4-98d4-4cc7027a4f5f', 'a', 'Al capear el temporal debemos reducir la velocidad incluso parando la arrancada.', true, '2025-09-13 13:53:12.979869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('143d94e2-1100-48e6-a7b8-d00e64449140', 'c20842ad-3a4d-4aa4-98d4-4cc7027a4f5f', 'b', 'Correr el temporal es una maniobra cómoda, pero, con mal tiempo, existe el problema de que pueden embarcar fuertes golpes de mar.', false, '2025-09-13 13:53:12.980081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5fc3f9d-4365-4954-b6b0-8ec15e92e25e', 'c20842ad-3a4d-4aa4-98d4-4cc7027a4f5f', 'c', 'Elegir capear o correr el temporal dependerá de la embarcación y del grado de fuerza del', false, '2025-09-13 13:53:12.980276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3884b68f-fe9a-436f-859d-9c951aa42623', 'c20842ad-3a4d-4aa4-98d4-4cc7027a4f5f', 'd', 'Para capear el temporal nos podemos ayudar mediante el uso de un ancla flotante.', false, '2025-09-13 13:53:12.980499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8572594d-079f-4b71-974e-ee8f667bef90', 'd7c72f23-c376-42fc-9c7b-b7d1166493ef', 'a', 'Con la estación de radio, canal 70 VHF.', false, '2025-09-13 13:53:12.980911+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f024443-da8d-463e-8fbe-f34a95bff9d2', 'd7c72f23-c376-42fc-9c7b-b7d1166493ef', 'b', 'Con la estación de radio, canal 16 VHF.', false, '2025-09-13 13:53:12.98111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86a51b19-d584-48ca-984b-47c771ee0ed8', 'd7c72f23-c376-42fc-9c7b-b7d1166493ef', 'c', 'Por teléfono, llamando al 900 200 200.', true, '2025-09-13 13:53:12.981333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5defd879-fca9-4c13-823c-5d07766ccb1b', 'd7c72f23-c376-42fc-9c7b-b7d1166493ef', 'd', 'Por teléfono, llamando al 900 202 202.', false, '2025-09-13 13:53:12.981531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69863599-7936-461d-a3ff-fdedd6b73b3b', '197ed313-f6ae-4e78-8cc0-8824a6ee15ec', 'a', 'Librar al náufrago de la hélice, no perderle de vista y lanzarle ayudas.', true, '2025-09-13 13:53:12.981941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c100f780-17ee-4891-8e40-69a079cc8125', '197ed313-f6ae-4e78-8cc0-8824a6ee15ec', 'b', 'Librar al náufrago de la hélice, parar el motor, lanzarle ayudas y saltar al agua en su busca.', false, '2025-09-13 13:53:12.982151+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47aca950-167b-4422-8e32-27d87bc94c37', '197ed313-f6ae-4e78-8cc0-8824a6ee15ec', 'c', 'Dar atrás y acercarnos lentamente por la popa, sin perder de vista al náufrago, para evitar que la proa pueda dañarlo.', false, '2025-09-13 13:53:12.982378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f1cf1775-e095-49d4-80ae-c40ddb2380ea', '197ed313-f6ae-4e78-8cc0-8824a6ee15ec', 'd', 'Saltar al agua en su busca para evitar que se ahogue.', false, '2025-09-13 13:53:12.982587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc3774ec-4da1-4931-9f2f-179a44d1ff23', '5b015c74-5365-4e80-bc47-73d984f6dd56', 'a', 'Un sistema de detección de barcos que es obligatorio en cualquier tipo de embarcación.', false, '2025-09-13 13:53:12.983017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9af80091-c8bf-476f-929b-6227bc28cb89', '5b015c74-5365-4e80-bc47-73d984f6dd56', 'b', 'Un elemento de ayuda para que las embarcaciones de casco no metálico produzcan ecos en las pantallas de radar de otros barcos.', true, '2025-09-13 13:53:12.983229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9af36b9e-b950-4569-82ec-ba17e8fe5953', '5b015c74-5365-4e80-bc47-73d984f6dd56', 'c', 'Un dispositivo destinado a evitar la detección de nuestra embarcación por el radar de otros barcos, por motivos de protección.', false, '2025-09-13 13:53:12.983458+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('721d75a5-30de-4a9e-9991-a6b8b99967c3', '5b015c74-5365-4e80-bc47-73d984f6dd56', 'd', 'La antena del sistema de radar del barco, siendo obligatorio sólo en embarcaciones de fibra o', false, '2025-09-13 13:53:12.983652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44a7395d-8e93-4138-85aa-15b4a18c726e', '0fdaa6e4-3700-4bd5-88dd-fe50022625d9', 'a', 'Tres días hábiles.', false, '2025-09-13 13:53:12.984075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7cf09fa-bed4-4c8e-896e-3524c4e67b85', '0fdaa6e4-3700-4bd5-88dd-fe50022625d9', 'b', 'Diez días hábiles.', false, '2025-09-13 13:53:12.984292+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0aa4d34c-ef11-4b21-beaf-76d87c5c39f4', '0fdaa6e4-3700-4bd5-88dd-fe50022625d9', 'c', 'Cinco días hábiles.', true, '2025-09-13 13:53:12.984521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba6e00b6-b9de-41bb-83ee-a51206f6f728', '0fdaa6e4-3700-4bd5-88dd-fe50022625d9', 'd', 'Quince días hábiles.', false, '2025-09-13 13:53:12.984737+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e247e5ba-f593-45de-8ea9-22e51630ee19', 'f454786a-07ff-49ba-a362-849046e17951', 'a', 'Cuando las basuras estén mezcladas con otras sustancias cuya descarga esté prohibida o para las que rijan distintas prescripciones de descarga, se aplicarán las prescripciones más rigurosas.', true, '2025-09-13 13:53:12.985193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9221b9e5-25ac-4404-832f-b324521e48ef', 'f454786a-07ff-49ba-a362-849046e17951', 'b', 'Los aditivos de limpieza contenidos en las aguas de lavado podrán descargarse al mar, aunque sean perjudiciales para el medio marino.', false, '2025-09-13 13:53:12.985408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('610c1196-11d2-4aa6-b2ce-13eac84e01df', 'f454786a-07ff-49ba-a362-849046e17951', 'c', 'La descarga de basuras en el mar fuera de las zonas especiales está prohibida sin excepciones.', false, '2025-09-13 13:53:12.985628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80e9b3d9-b833-4863-8547-8f764ccf8da1', 'f454786a-07ff-49ba-a362-849046e17951', 'd', 'Los restos de alimentos a descargar estarán desmenuzados de manera que puedan pasar por cribas con mallas de una abertura máxima de 25 cm.', false, '2025-09-13 13:53:12.985845+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19ed59b9-31db-4d2a-b5f4-76f8efe929be', 'f15e4ade-378b-41d7-9870-f89ce65ba60c', 'a', 'Si tienen luz, es amarilla.', false, '2025-09-13 13:53:12.986286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4336e293-4668-41eb-baf1-31012e6697cf', 'f15e4ade-378b-41d7-9870-f89ce65ba60c', 'b', 'Indican una zona o una configuración particular cuya naturaleza exacta está indicada en la carta u otro documento náutico.', false, '2025-09-13 13:53:12.986501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbd9d602-c2ab-464c-aa06-c53a1dce2ca7', 'f15e4ade-378b-41d7-9870-f89ce65ba60c', 'c', 'No señalan ningún peligro.', true, '2025-09-13 13:53:12.986714+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15d60a09-8343-4fbb-a3e0-75469e8182a9', 'f15e4ade-378b-41d7-9870-f89ce65ba60c', 'd', 'Si tienen marca de tope es una única esfera verde.', false, '2025-09-13 13:53:12.986898+00');
