INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4318ac30-6ae6-4de4-b194-678046549182', 'eace21ed-122a-433c-834a-31c91ba906f2', 'b', 'Navegue a vela, no sea propulsado mecánicamente y se encuentre sin arrancada por falta de', false, '2025-09-13 13:53:12.993886+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('696444ff-233a-4efd-b65e-e1b0eaab8085', 'eace21ed-122a-433c-834a-31c91ba906f2', 'c', 'Navegue a vela y también sea propulsado mecánicamente.', true, '2025-09-13 13:53:12.994104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('022d57ff-1688-49f3-999c-82dce075c58f', 'eace21ed-122a-433c-834a-31c91ba906f2', 'd', 'Navegue solo propulsado mecánicamente.', false, '2025-09-13 13:53:12.994311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d9d15a9-8171-4364-9d79-cb03fa970f93', '7b7ca1a2-c97c-4545-86df-a67317d34808', 'a', 'Exhibirá luces que, por sus características y situación, sean lo más parecidas posible a las prescritas en dicha regla.', true, '2025-09-13 13:53:12.994729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd458508-ed95-467f-a0a6-8223c7460d6d', '7b7ca1a2-c97c-4545-86df-a67317d34808', 'b', 'Tendrá prohibida la navegación.', false, '2025-09-13 13:53:12.994933+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8352922e-9696-4ea0-8024-db756d427c90', '7b7ca1a2-c97c-4545-86df-a67317d34808', 'c', 'Lo indicará colocando en el lugar más visible una luz amarilla de centelleos todo horizonte.', false, '2025-09-13 13:53:12.995129+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b91c7f5d-a992-460a-8190-61f98214dbe3', '7b7ca1a2-c97c-4545-86df-a67317d34808', 'd', 'Las sustituirá todas por una única luz roja centelleante todo horizonte de gran intensidad.', false, '2025-09-13 13:53:12.995326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('241e7fa1-66e2-4f44-a01d-2eedae20fd4a', '5f1f0a5c-2102-403e-907d-552ee22ddea3', 'a', 'El resplandor de las luces de tierra siempre beneficiará la distinción de otros buques o marcas de balizamiento de noche.', false, '2025-09-13 13:53:12.995727+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b220892d-df7d-4a87-ab9d-71e164fa3c3d', '5f1f0a5c-2102-403e-907d-552ee22ddea3', 'b', 'Un equipo radar funcionando correctamente nunca debe ser utilizado para determinar la velocidad de seguridad en condiciones de mala visibilidad.', false, '2025-09-13 13:53:12.995948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd9451f6-e799-410d-8480-d897670fda35', '5f1f0a5c-2102-403e-907d-552ee22ddea3', 'c', 'En condiciones de mala visibilidad, se debe aumentar la velocidad al máximo para evitar pasar más tiempo de lo necesario expuestos a posibles peligros.', false, '2025-09-13 13:53:12.996149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e545eb96-06c0-4a0b-953b-bf3131ede1d6', '5f1f0a5c-2102-403e-907d-552ee22ddea3', 'd', 'La densidad de tráfico, incluidas las concentraciones de buques de pesca, condicionará la maniobra adecuada y eficaz para evitar un abordaje.', true, '2025-09-13 13:53:12.996383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('870d225c-e467-4722-88b3-62c29469094f', '0f33f0d4-ffbc-41ed-b8e6-628db95045dd', 'a', 'Para evitar un peligro inmediato.', true, '2025-09-13 13:53:12.996782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f84a5ea-cc30-4822-8c80-299490c3fbea', '0f33f0d4-ffbc-41ed-b8e6-628db95045dd', 'b', 'Exclusivamente cuando estén en ruta hacia un puerto dentro de la zona de navegación costera.', false, '2025-09-13 13:53:12.996983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bea74b0-54fa-4cc3-bb72-0552f26c396c', '0f33f0d4-ffbc-41ed-b8e6-628db95045dd', 'c', 'Por ser un buque menor de 30 metros de eslora puede utilizar la zona de navegación costera siempre que lo necesite.', false, '2025-09-13 13:53:12.997191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac182f46-1ad6-4c7b-86da-c65b1bdfc82d', '0f33f0d4-ffbc-41ed-b8e6-628db95045dd', 'd', 'Únicamente en el caso de que deba maniobrar a un buque que tenga preferencia de paso, y el ancho del dispositivo no sea suficiente para realizar la maniobra con seguridad.', false, '2025-09-13 13:53:12.997387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('28ba9035-a086-4f1b-810a-67739c9fcd6a', 'd5a17034-17b1-44e1-ac13-9c34b66cf27b', 'a', 'Un aerodeslizador navegando a gran velocidad.', false, '2025-09-13 13:53:12.99779+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1de25795-16c6-45a3-b55e-1c7107ea591d', 'd5a17034-17b1-44e1-ac13-9c34b66cf27b', 'b', 'Una nave de vuelo rasante, despegando, aterrizando o volando cerca de la superficie.', true, '2025-09-13 13:53:12.998029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d62456b1-b1aa-453a-8b33-9dd3e1cbb3fa', 'd5a17034-17b1-44e1-ac13-9c34b66cf27b', 'c', 'Una nave de gran velocidad navegando a una velocidad superior a 30 nudos.', false, '2025-09-13 13:53:12.998217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42e9561e-1eb2-4df0-8abb-fae76911e9ef', 'd5a17034-17b1-44e1-ac13-9c34b66cf27b', 'd', 'Un submarino navegando en superficie.', false, '2025-09-13 13:53:12.998409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2152de92-8dcf-4fba-a243-2c47d7e03dd6', 'a123fd8a-f7bf-4a84-869a-6817fed08a36', 'a', 'Emitirá una señal acústica de al menos cinco pitadas cortas y rápidas y se maniobrará al buque de vela si fuera necesario para evitar el abordaje.', true, '2025-09-13 13:53:12.998823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70a8f7e7-9ddf-4cf4-9588-47d3af800959', 'a123fd8a-f7bf-4a84-869a-6817fed08a36', 'b', 'Hará sonar una pitada larga para indicar al otro buque que no entiendes sus intenciones y que está', false, '2025-09-13 13:53:12.999027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f5810b8-5a96-4f25-8719-df35a4cec94a', 'a123fd8a-f7bf-4a84-869a-6817fed08a36', 'c', 'Cederá el paso al buque de vela, aun no existiendo riesgo de abordaje, ya que tienen la preferencia de tránsito por el canal al ir sin maquinaria propulsora.', false, '2025-09-13 13:53:12.999234+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b37835c-37c8-4d0e-b739-ddaae5b7ba29', 'a123fd8a-f7bf-4a84-869a-6817fed08a36', 'd', 'Fondeará en el canal, en cualquier caso, hasta que el buque de vela termine de estorbar nuestro', false, '2025-09-13 13:53:12.999433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46b0fc86-1ef8-467b-92de-cb510b3936f2', '34a2eec4-3398-4499-a6ad-7a1378117f95', 'a', 'Un buque dedicado a la pesca, fondeado.', false, '2025-09-13 13:53:12.999848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e68fb0f-eac2-4f29-9ae8-027e1b8a18af', '34a2eec4-3398-4499-a6ad-7a1378117f95', 'b', 'Una embarcación de prácticos, con arrancada, en servicio de practicaje.', true, '2025-09-13 13:53:13.000053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a3c51a0-cda8-4e46-8e0a-24280c29e020', '34a2eec4-3398-4499-a6ad-7a1378117f95', 'c', 'Un buque de eslora igual o superior a 100 metros, fondeado.', false, '2025-09-13 13:53:13.000249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70ee2653-47e9-4a75-84da-fe040ebd2586', '7a337623-c761-4439-a72b-8077e1b34ded', 'a', 'Únicamente una campana.', false, '2025-09-13 13:53:13.000856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6160585-34b8-44ae-b7f5-370046d8da21', '7a337623-c761-4439-a72b-8077e1b34ded', 'b', 'Un pito y una campana.', true, '2025-09-13 13:53:13.001071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1239ce07-f611-4e7c-930c-eeb08f721b65', '7a337623-c761-4439-a72b-8077e1b34ded', 'c', 'Una campana y un gong.', false, '2025-09-13 13:53:13.001276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('263976b7-1ee8-4856-9f15-fa5b9abc46b4', '7a337623-c761-4439-a72b-8077e1b34ded', 'd', 'Únicamente un pito. DE TRANSPORTES                                                                                     DE TRANSPORTES Y MOVILIDAD SOSTENIBLE Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO Código de Test 01 Seguridad en la mar', false, '2025-09-13 13:53:13.001472+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8ef6061-cad5-493c-a762-59fdfc4003b6', 'd101c2ff-300c-4234-8769-3f45c7cd5212', 'a', 'El metacentro debe estar situado por encima del centro de gravedad.', false, '2025-09-13 13:53:13.00207+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89c90e7c-2777-4773-b493-0db8afd3a1a8', 'd101c2ff-300c-4234-8769-3f45c7cd5212', 'b', 'El metacentro debe estar situado por debajo del centro de carena.', false, '2025-09-13 13:53:13.002269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('661be3ff-3dcb-4fec-bf6d-fbc4df68bb0f', 'd101c2ff-300c-4234-8769-3f45c7cd5212', 'c', 'El metacentro debe estar situado en el mismo punto que el centro de gravedad.', true, '2025-09-13 13:53:13.002466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5283cee-2250-4a6a-9be8-2f7cbee0d765', 'd101c2ff-300c-4234-8769-3f45c7cd5212', 'd', 'El centro de carena debe estar situado por encima del centro de gravedad.', false, '2025-09-13 13:53:13.002662+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfcdbb62-efec-497e-9e39-92d0d76a679c', '9826fa69-d58f-4616-a9ab-dc99164a27f0', 'a', 'Dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:13.003075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06644460-7703-4e88-8405-a7fecda5440c', '9826fa69-d58f-4616-a9ab-dc99164a27f0', 'b', 'Dos extintores tipo 34 B.', false, '2025-09-13 13:53:13.003274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d14d8601-149a-42bf-a116-52a029c9d658', '9826fa69-d58f-4616-a9ab-dc99164a27f0', 'c', 'Seis bengalas de mano y dos señales fumígenas flotantes.', true, '2025-09-13 13:53:13.003468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b3a2a1f-1087-4d17-9362-99f6e31200a4', '9826fa69-d58f-4616-a9ab-dc99164a27f0', 'd', 'Tantos chalecos salvavidas como personas a bordo, de los cuales la mitad podrán prescindir de la', false, '2025-09-13 13:53:13.003664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98c9ba21-854d-4465-93b7-4189a552b8d1', '7ae77bba-890f-4340-9dac-f80cf78687fb', 'a', 'Quitaremos el tapón, tiraremos del dispositivo de encendido y luego la lanzaremos al mar.', false, '2025-09-13 13:53:13.004075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adbe4b7a-d08b-43e7-80aa-5aa4d6dab20d', '7ae77bba-890f-4340-9dac-f80cf78687fb', 'b', 'Quitaremos el tapón, tiraremos del dispositivo de encendido y luego la mantendremos con una sola mano hasta que se haya consumido.', false, '2025-09-13 13:53:13.004272+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbab0976-5555-4c07-a5fa-92d87ec0f3a0', '7ae77bba-890f-4340-9dac-f80cf78687fb', 'c', 'Quitaremos el tapón y la arrojaremos directamente al mar, ya que se activa en contacto directo', true, '2025-09-13 13:53:13.004467+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a93716c-0a17-441b-860c-7a987b090033', '7ae77bba-890f-4340-9dac-f80cf78687fb', 'd', 'Con guantes, alejándola de la cara, por sotavento y con ella prácticamente en vertical, un poco inclinada hacia afuera y sin lanzarla al agua.', false, '2025-09-13 13:53:13.004661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50ba6f74-a857-4302-ab2e-cfd7130d8395', '640273a5-eca1-4226-a0f2-900b0bb1e21f', 'a', 'No lance un bote fumígeno ya que el humo evitará que le detecten.', false, '2025-09-13 13:53:13.005083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd54d4f2-e56f-4294-bd14-ed8fa1df198e', '640273a5-eca1-4226-a0f2-900b0bb1e21f', 'b', 'Use el VHF portátil para guiar al helicóptero.', true, '2025-09-13 13:53:13.005281+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49e6e845-11c0-494c-9791-a8b5d7a07965', '640273a5-eca1-4226-a0f2-900b0bb1e21f', 'c', 'No le haga señales con espejos para evitar deslumbrarle.', false, '2025-09-13 13:53:13.005478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('403aa8d2-0902-401c-9f84-86025d1c5997', '640273a5-eca1-4226-a0f2-900b0bb1e21f', 'd', 'Lance un cohete provisto de paracaídas cuando se aproxime.', false, '2025-09-13 13:53:13.005671+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45d7368c-04d4-4b9b-9a1f-8eaecad0ac64', '895b232f-f244-4637-b3b3-767b5a1edb68', 'a', 'El traslado vertical de un peso en un barco hará subir o bajar el centro de gravedad (G).', false, '2025-09-13 13:53:13.006101+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cceb0b28-7022-4db6-b799-0e72282d87bb', '895b232f-f244-4637-b3b3-767b5a1edb68', 'b', 'En el traslado vertical de pesos no hay variación de desplazamiento (D).', true, '2025-09-13 13:53:13.006335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('309fe93d-94e3-42bd-9735-79e283896de3', '895b232f-f244-4637-b3b3-767b5a1edb68', 'c', 'Si baja el centro de gravedad (G), tendremos menor altura metacéntrica (GM) y menor brazo del par de estabilidad (GZ).', false, '2025-09-13 13:53:13.006548+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2a91c62-73a0-422d-a5ea-d488b3c087f0', '895b232f-f244-4637-b3b3-767b5a1edb68', 'd', 'Si trasladamos un peso verticalmente hacia arriba asciende el centro de gravedad (G).', false, '2025-09-13 13:53:13.006752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4aba146d-3bd1-4da9-a95b-ff73140f4c96', '60d8985c-aac0-49fb-a344-7cd7eaf010c2', 'a', 'Apretando el botón de activación de forma manual.', false, '2025-09-13 13:53:13.007193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a39e65ca-8685-4038-8974-e45141040929', '60d8985c-aac0-49fb-a344-7cd7eaf010c2', 'b', 'Mediante el interruptor de agua automático cuando se sumerja en el agua desde la balsa, siendo muy importante que la radiobaliza flote por encima del agua.', true, '2025-09-13 13:53:13.007405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('965f9eb6-cbe1-47e2-9395-6b7a160dc424', '60d8985c-aac0-49fb-a344-7cd7eaf010c2', 'c', 'Automáticamente al entrar en contacto con el agua tras su liberación hidrostática en caso de hundimiento de la embarcación.', false, '2025-09-13 13:53:13.007602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67b90372-f346-43be-ad5a-ca7b5df206de', '60d8985c-aac0-49fb-a344-7cd7eaf010c2', 'd', 'Al retirarla de su estiba la radiobaliza se activará automáticamente.', false, '2025-09-13 13:53:13.007801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc67ff4e-f207-447f-a393-d9f9be99e71a', 'a659a3ae-9ffa-4878-a2d8-66d0f2975ea5', 'a', 'Atienda la información e instrucciones del Centro de Salvamento Marítimo.', false, '2025-09-13 13:53:13.008224+00');
