INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c18a79e-3fb3-4080-b022-0187eb85ddef', '6bad388a-f950-4484-9753-d0b6cc4ec0fe', 'a', 'La fuerza de empuje.', true, '2025-09-13 13:53:13.009235+00');
