INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8624a82f-0681-4860-8c00-8363368c8d10', '6bad388a-f950-4484-9753-d0b6cc4ec0fe', 'c', 'El volumen sumergido del buque.', false, '2025-09-13 13:53:13.009648+00');
