INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8cca6e1-a918-48cb-b13c-d99828b27d44', '29e13356-7ac4-48a4-8eeb-8dd7db43f696', 'b', 'Ra= 333°.', false, '2025-09-13 13:53:13.043771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0a42721-b35a-4f15-8a4f-e5e08ec3f82f', '29e13356-7ac4-48a4-8eeb-8dd7db43f696', 'c', 'Ra= 344º.', false, '2025-09-13 13:53:13.043995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7a5e857-e05e-4567-b8a1-82c2ad654488', '29e13356-7ac4-48a4-8eeb-8dd7db43f696', 'd', 'Ra= 335º. DE TRANSPORTES DE TRANSPORTES Y MOVILIDAD SOSTENIBLE Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO Código de Test 02 Seguridad en la mar', true, '2025-09-13 13:53:13.044206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cecb5cc-ba82-477b-8068-da721804de06', '8c57d1fd-20c2-4895-8576-68c81aa699cb', 'a', 'No amarrar la driza de la balsa salvavidas a la embarcación antes de lanzarla al agua.', false, '2025-09-13 13:53:13.044874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1cf67fc-f5c1-467c-b9a5-2dc44a562aac', '8c57d1fd-20c2-4895-8576-68c81aa699cb', 'b', 'Detener completamente la embarcación.', false, '2025-09-13 13:53:13.045073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07269e06-b0f4-4c8d-b013-f37cf8c45659', '8c57d1fd-20c2-4895-8576-68c81aa699cb', 'c', 'Volver a leer las instrucciones de la balsa y lanzarla.', true, '2025-09-13 13:53:13.045291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4f6288d-d54d-46ec-92f1-2757cdadacec', '8c57d1fd-20c2-4895-8576-68c81aa699cb', 'd', 'Distribuir pastillas contra el mareo.', false, '2025-09-13 13:53:13.045506+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2805a1c-ae46-44f5-88d0-5bb2cc6397ad', 'dd90c677-7d98-4e25-9e1d-71c887d5b19e', 'a', 'El metacentro debe estar situado por encima del centro de gravedad.', true, '2025-09-13 13:53:13.045966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('186829dc-264a-4f3b-bc43-4888b897f5d9', 'dd90c677-7d98-4e25-9e1d-71c887d5b19e', 'b', 'El metacentro debe estar situado por debajo del centro de carena.', false, '2025-09-13 13:53:13.046176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79b383c8-974f-4a05-bf8b-fcb64c06ebd8', 'dd90c677-7d98-4e25-9e1d-71c887d5b19e', 'c', 'El metacentro debe estar situado en el mismo punto que el centro de gravedad.', false, '2025-09-13 13:53:13.046384+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47eb0a49-2658-444c-86df-a99e50f0fb34', 'dd90c677-7d98-4e25-9e1d-71c887d5b19e', 'd', 'El centro de carena debe estar situado por encima del centro de gravedad.', false, '2025-09-13 13:53:13.046617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eff59c5-4f66-4baa-a345-651429bfa205', 'ea540358-a3b0-413a-ab1d-a69e25a3e202', 'a', 'El traslado vertical de un peso en un barco hará subir o bajar el centro de gravedad (G).', false, '2025-09-13 13:53:13.047074+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19e98d77-9b34-4875-bdf0-e4612f22a0ac', 'ea540358-a3b0-413a-ab1d-a69e25a3e202', 'b', 'En el traslado vertical de pesos no hay variación de desplazamiento (D).', true, '2025-09-13 13:53:13.047282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('390ca0a6-fe62-4549-80bb-69dd7c4e1aea', 'ea540358-a3b0-413a-ab1d-a69e25a3e202', 'c', 'Si baja el centro de gravedad (G), tendremos menor altura metacéntrica (GM) y menor brazo del par de estabilidad (GZ).', false, '2025-09-13 13:53:13.047493+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ceea9c3-c44e-4e08-8fec-8c4237ceef0b', 'ea540358-a3b0-413a-ab1d-a69e25a3e202', 'd', 'Si trasladamos un peso verticalmente hacia arriba asciende el centro de gravedad (G).', false, '2025-09-13 13:53:13.047703+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3d20dd3-01c8-4dd5-9196-af82d5d092b7', '7f8a4cc4-05c4-40ef-b333-fb92710eea7b', 'a', 'Dos aros salvavidas con luz y rabiza.', false, '2025-09-13 13:53:13.048163+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90430a9d-58a4-4dcb-940c-388416b139eb', '7f8a4cc4-05c4-40ef-b333-fb92710eea7b', 'b', 'Dos extintores tipo 34 B.', true, '2025-09-13 13:53:13.048385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcc8d4e9-2df9-42fb-97f1-e86c67ffce89', '7f8a4cc4-05c4-40ef-b333-fb92710eea7b', 'c', 'Seis bengalas de mano y dos señales fumígenas flotantes.', false, '2025-09-13 13:53:13.048612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3437cf44-c73d-45a8-bf3e-23613f7d21d9', '7f8a4cc4-05c4-40ef-b333-fb92710eea7b', 'd', 'Tantos chalecos salvavidas como personas a bordo, de los cuales la mitad podrán prescindir de la', false, '2025-09-13 13:53:13.048838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66f43606-dc8a-4c44-abbb-38656df701a1', '7db49007-502f-4f97-9b1a-9a80d01e67cb', 'a', 'Amarrar firmemente la línea que nos lance el helicóptero a la embarcación.', false, '2025-09-13 13:53:13.049276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a2008086-b727-497a-83eb-8dcf35542e9b', '7db49007-502f-4f97-9b1a-9a80d01e67cb', 'b', 'En veleros, arriar las velas y arrancar el motor.', false, '2025-09-13 13:53:13.049486+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('098af38d-9c81-40dc-8ab4-329ca64b547a', '7db49007-502f-4f97-9b1a-9a80d01e67cb', 'c', 'Ponerse el chaleco salvavidas antes de la llegada del helicóptero.', false, '2025-09-13 13:53:13.049696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac92bf25-cb4d-4a4c-8e79-61a2baf7814a', '7db49007-502f-4f97-9b1a-9a80d01e67cb', 'd', 'Utilizar la técnica de las horas del reloj, desde el punto de vista del helicóptero, a modo de guía.', true, '2025-09-13 13:53:13.04993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('048a5cd3-53cf-4063-a8af-e71d5ea02656', 'dc1aba4b-7352-4cd6-8d4e-01ea02ae5f3e', 'a', 'Apretando el botón de activación de forma manual.', false, '2025-09-13 13:53:13.050377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d6e273a-4412-4190-b107-4da44061ab52', 'dc1aba4b-7352-4cd6-8d4e-01ea02ae5f3e', 'b', 'Mediante el interruptor de agua automático cuando se sumerja en el agua desde la balsa, siendo muy importante que la radiobaliza flote por encima del agua.', true, '2025-09-13 13:53:13.050604+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0be26a4f-a00e-4541-be01-9bf2929e3790', 'dc1aba4b-7352-4cd6-8d4e-01ea02ae5f3e', 'c', 'Automáticamente al entrar en contacto con el agua tras su liberación hidrostática en caso de hundimiento de la embarcación.', false, '2025-09-13 13:53:13.05081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c976c6f4-57ec-40ab-847b-80335b9ffa98', 'dc1aba4b-7352-4cd6-8d4e-01ea02ae5f3e', 'd', 'Al retirarla de su estiba la radiobaliza se activará automáticamente.', false, '2025-09-13 13:53:13.051005+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ac29ba3-efa5-449e-9445-01cfa5a8193f', '4dd003db-29f8-4ca4-91e0-5c602a108584', 'a', 'Quitaremos el tapón, tiraremos del dispositivo de encendido y luego la lanzaremos al mar.', false, '2025-09-13 13:53:13.051453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('acbe8577-ba19-4382-aaf2-06532ae81993', '4dd003db-29f8-4ca4-91e0-5c602a108584', 'b', 'Quitaremos el tapón, tiraremos del dispositivo de encendido y luego la mantendremos con una sola mano hasta que se haya consumido.', true, '2025-09-13 13:53:13.051687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcfff980-fec8-4613-9ca9-bc9bfb4b2efa', '4dd003db-29f8-4ca4-91e0-5c602a108584', 'c', 'Quitaremos el tapón y la arrojaremos directamente al mar, ya que se activa en contacto directo', false, '2025-09-13 13:53:13.051902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4657276-3947-4d41-9bcb-88cb9febe00c', '4dd003db-29f8-4ca4-91e0-5c602a108584', 'd', 'Con guantes, alejándola de la cara, por sotavento y con ella prácticamente en vertical, un poco inclinada hacia afuera y sin lanzarla al agua.', false, '2025-09-13 13:53:13.052113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ef683e7-a1b2-491d-8341-1b4d1b14aa10', 'b4807adf-5f85-4274-9a43-bd770bee8ad6', 'a', 'La fuerza de empuje.', false, '2025-09-13 13:53:13.052531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a29b199-88ea-4232-889e-a9f863cf4e47', 'b4807adf-5f85-4274-9a43-bd770bee8ad6', 'b', 'La fuerza de resistencia lateral.', false, '2025-09-13 13:53:13.052731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fddd77e-9734-48a4-985c-be2fa8e60128', 'b4807adf-5f85-4274-9a43-bd770bee8ad6', 'c', 'El volumen sumergido del buque.', true, '2025-09-13 13:53:13.052946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dc00456-381e-4c63-8923-3a7dacb2e486', 'b4807adf-5f85-4274-9a43-bd770bee8ad6', 'd', 'La suma de todos los pesos existentes a bordo, incluido el del propio barco.', false, '2025-09-13 13:53:13.053144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a863f7b6-de0a-4a24-b485-b7435af66334', 'd58e147c-e73e-4934-a2b4-046e7dbbe1d5', 'a', 'No lance un bote fumígeno ya que el humo evitará que le detecten.', true, '2025-09-13 13:53:13.053568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0497c8c7-20d9-40bd-957d-502322788de3', 'd58e147c-e73e-4934-a2b4-046e7dbbe1d5', 'b', 'Use el VHF portátil para guiar al helicóptero.', false, '2025-09-13 13:53:13.053772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e64aebfb-d79e-49b2-a703-49d7cca13b6f', 'd58e147c-e73e-4934-a2b4-046e7dbbe1d5', 'c', 'No le haga señales con espejos para evitar deslumbrarle.', false, '2025-09-13 13:53:13.053971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd1fd5b2-8b7d-45aa-babb-ed1c4ec2a191', 'd58e147c-e73e-4934-a2b4-046e7dbbe1d5', 'd', 'Lance un cohete provisto de paracaídas cuando se aproxime.', false, '2025-09-13 13:53:13.054178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40ef0eea-f0b0-4b32-ac5c-e97989ed7ef1', 'e65c802e-faf6-4667-8e52-4bacfd183fee', 'a', 'Atienda la información e instrucciones del Centro de Salvamento Marítimo.', false, '2025-09-13 13:53:13.054651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93fa3828-7145-4775-a6c9-8d7031f61814', 'e65c802e-faf6-4667-8e52-4bacfd183fee', 'b', 'Recoja la documentación más imprescindible.', false, '2025-09-13 13:53:13.054847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('156c2002-0837-49aa-8b15-14d160efe5d1', 'e65c802e-faf6-4667-8e52-4bacfd183fee', 'c', 'No se impaciente aguardando la llegada.', true, '2025-09-13 13:53:13.055049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bd455f6-b668-40b3-b991-69f5e66549fb', 'e65c802e-faf6-4667-8e52-4bacfd183fee', 'd', 'Prepare sus maletas para que pueda izarlas con usted, o asegúrelas al cable que le envíe el Meteorología', false, '2025-09-13 13:53:13.055268+00');
