INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4aefb385-8119-4f39-a68b-969cbebcfbe3', 'cf426d24-6c00-478d-acb1-222d093994b9', 'd', '18° 17,6´. Meteorología', false, '2025-09-13 13:53:13.107433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15d6b923-128f-42f0-ab30-6bcf65ffb6b6', '6d332f28-e516-4a07-95a8-9c314e60aa10', 'a', 'Alta presión en la Zona de Convergencia Intertropical.', false, '2025-09-13 13:53:13.107835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4a2a4ee-a3db-46ff-9ef7-78a12c552393', '6d332f28-e516-4a07-95a8-9c314e60aa10', 'b', 'Presencia de viento fuerte en superficie para facilitar las corrientes ascendentes.', false, '2025-09-13 13:53:13.108032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ace85935-74be-48e4-b2dc-090be0f56058', '6d332f28-e516-4a07-95a8-9c314e60aa10', 'c', 'Calor y humedad en la atmósfera.', true, '2025-09-13 13:53:13.108225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83663655-ce5b-4cb3-83f8-de06c9a10c5b', '6d332f28-e516-4a07-95a8-9c314e60aa10', 'd', 'Baja temperatura del mar, lo cual previene la evaporación.', false, '2025-09-13 13:53:13.108419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9267c37b-7b65-4a1b-a2fc-b1380a2d98df', '60763747-5d7d-43db-a703-db4a76c46e18', 'a', 'No tienen frentes porque están constituidos por una sola masa de aire ecuatorial.', false, '2025-09-13 13:53:13.108844+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ce847ac-f503-49a1-b221-10ab3cbe7ab9', '60763747-5d7d-43db-a703-db4a76c46e18', 'b', 'En ellos la presión puede alcanzar valores muy elevados, superiores a los 1100mb.', true, '2025-09-13 13:53:13.10904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('006073fc-51c5-4d23-b173-22c319cc7553', '60763747-5d7d-43db-a703-db4a76c46e18', 'c', 'La energía de los ciclones proviene del calor latente de evaporación liberado por el aire húmedo al condensarse.', false, '2025-09-13 13:53:13.109248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13167907-640d-466d-a19b-9a71c18f1c14', '60763747-5d7d-43db-a703-db4a76c46e18', 'd', 'Existe una escala para categorizar a los ciclones en función de la intensidad de sus vientos, así como para dar a conocer los posibles daños que pueden producir.', false, '2025-09-13 13:53:13.109435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24edde31-84a5-4cdf-9407-d64f0b082bd0', 'c556730b-ac08-4737-bfc8-26d3184f02d4', 'a', 'En el hemisferio Norte, si el viento rola en sentido horario el buque está en el semicírculo peligroso. Debe navegar a la mayor velocidad posible con el viento abierto de 1 a 4 cuartas (según su velocidad) por la amura de estribor y continuar cayendo a estribor a medida que role el viento para alejarse de la succión.', true, '2025-09-13 13:53:13.109824+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbdf775d-09b4-458b-a84a-fa5c04425d13', 'c556730b-ac08-4737-bfc8-26d3184f02d4', 'b', 'En el hemisferio Sur, si el viento rola en sentido horario el buque está en el semicírculo peligroso. Debe navegar a la mayor velocidad posible con el viento abierto de 1 a 4 cuartas (según su velocidad) por la amura de estribor y continuar cayendo a estribor a medida que role el viento para alejarse de la succión.', false, '2025-09-13 13:53:13.110012+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ac81a60-33fd-4444-af6f-4db62df6d9b3', 'c556730b-ac08-4737-bfc8-26d3184f02d4', 'c', 'En el hemisferio Norte, si nos encontramos en el semicírculo navegable se debe mantener el viento sobre la aleta de babor y cambiar el rumbo poco a poco a estribor a medida que nos alejamos', false, '2025-09-13 13:53:13.110217+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('789dc83b-19ab-4f3e-8311-c7f7259d13fd', 'c556730b-ac08-4737-bfc8-26d3184f02d4', 'd', 'En el hemisferio Sur, si nos encontramos en el semicírculo navegable se debe mantener el viento sobre la aleta de estribor y cambiar el rumbo poco a poco a babor a medida que nos alejamos del', false, '2025-09-13 13:53:13.110412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('800e1341-9346-4469-bad3-c64fa423fb7c', 'c996f57f-9734-4b7f-bb73-faf6d8659f8d', 'a', 'Anterior derecho.', false, '2025-09-13 13:53:13.110847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e92ad2dc-db51-45a7-99ed-5221ceb4093f', 'c996f57f-9734-4b7f-bb73-faf6d8659f8d', 'b', 'Anterior izquierdo.', false, '2025-09-13 13:53:13.111054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fee449e-3193-409b-addb-f2d2d8cd28de', 'c996f57f-9734-4b7f-bb73-faf6d8659f8d', 'c', 'Posterior derecho.', true, '2025-09-13 13:53:13.111252+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0eb03adc-be6d-495b-b512-126112434486', 'c996f57f-9734-4b7f-bb73-faf6d8659f8d', 'd', 'Posterior izquierdo.', false, '2025-09-13 13:53:13.111463+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50dc7705-9000-4ae5-80a2-21a5ce84f8f3', 'b2ecc290-445b-45e1-b9fc-0c7160e446b9', 'a', 'Las condiciones necesarias para su formación son un aire frío denso y con escasa humedad en las capas inferiores de la atmósfera, y un aire cálido en las superiores.', false, '2025-09-13 13:53:13.111893+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a088939-68e4-4ed9-9cd3-23d79c9d0bb6', 'b2ecc290-445b-45e1-b9fc-0c7160e446b9', 'b', 'Aparecen asociadas a nubes de tipo cirro o similar, típicas de formas tormentosas.', false, '2025-09-13 13:53:13.11209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6f0f4d1-347e-4350-acfc-bae39ced0000', 'b2ecc290-445b-45e1-b9fc-0c7160e446b9', 'c', 'En su fase de madurez producen chubascos a veces acompañados de aparato eléctrico.', true, '2025-09-13 13:53:13.112293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('097be87c-f106-4e24-a938-1397e7f61bd2', 'b2ecc290-445b-45e1-b9fc-0c7160e446b9', 'd', 'No se desarrollan temporalmente por fases.', false, '2025-09-13 13:53:13.112501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('408cfe0c-e7ee-4569-a45f-bd1dc492e3ea', 'ca15fd01-b2ea-4083-9098-fcf6758934ae', 'a', 'En el Atlántico Norte.', false, '2025-09-13 13:53:13.112901+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7b33884-8896-449c-a688-980f569c756c', 'ca15fd01-b2ea-4083-9098-fcf6758934ae', 'b', 'En todo el Atlántico.', false, '2025-09-13 13:53:13.113104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e1288cb-a6cd-4185-8541-4aaf8aecd634', 'ca15fd01-b2ea-4083-9098-fcf6758934ae', 'c', 'En ninguna zona del Atlántico.', false, '2025-09-13 13:53:13.113314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('edf9f44e-e643-4ed3-bb0f-090272136699', 'ca15fd01-b2ea-4083-9098-fcf6758934ae', 'd', 'En el Atlántico Sur.', true, '2025-09-13 13:53:13.113509+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e1a3986-05a0-420c-9123-907605e0a2e1', 'dbc0b3d9-d8c6-4792-b95f-2f6c6d2b0fe6', 'a', 'Es una franja de bajas presiones.', false, '2025-09-13 13:53:13.113954+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9611929a-499f-4d85-afc1-df345a908979', 'dbc0b3d9-d8c6-4792-b95f-2f6c6d2b0fe6', 'b', 'Está ubicada en los alrededores del ecuador terrestre.', false, '2025-09-13 13:53:13.114152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efc98647-2b37-41fd-b814-aa56e7b43ee5', 'dbc0b3d9-d8c6-4792-b95f-2f6c6d2b0fe6', 'c', 'Es la zona de confluencia de los vientos alisios del noroeste, procedentes del hemisferio Norte, y los alisios del sudoeste, que llegan del hemisferio Sur.', true, '2025-09-13 13:53:13.114371+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e65203cd-f1ba-433b-839c-28a3f5a60763', 'dbc0b3d9-d8c6-4792-b95f-2f6c6d2b0fe6', 'd', 'En general predominan en ella los vientos de componente ascendente.', false, '2025-09-13 13:53:13.114602+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8af638db-2442-43e0-a2a2-7883037f0613', '84c3ac67-ada9-48a4-89f1-abd271961ae2', 'a', 'Por todos los medios de que disponga.', true, '2025-09-13 13:53:13.11505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62a6474c-1984-4c69-a495-0941a88035d2', '84c3ac67-ada9-48a4-89f1-abd271961ae2', 'b', 'En inglés.', false, '2025-09-13 13:53:13.115251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6275969-7c07-48f2-bdc0-19d6c711bd24', '84c3ac67-ada9-48a4-89f1-abd271961ae2', 'c', 'Únicamente a las autoridades competentes.', false, '2025-09-13 13:53:13.115468+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6de68b15-e1f0-4b52-9e5c-9814d68e1099', '84c3ac67-ada9-48a4-89f1-abd271961ae2', 'd', 'Utilizando el canal 406 MHz.', false, '2025-09-13 13:53:13.115663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f3cc4a9-1dd9-4259-9ab9-e58a34577664', '6ed2c861-99a7-4ad4-902c-31ff8ebde3e5', 'a', 'El rayo verde es un destello vivo e instantáneo que a veces se observa durante el mediodía del lugar en latitudes elevadas, superiores a los 70º N/S.', false, '2025-09-13 13:53:13.116076+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2995c86-d467-4c00-8524-7bddb0a091a1', '6ed2c861-99a7-4ad4-902c-31ff8ebde3e5', 'b', 'El halo es un meteoro luminoso consistente en un cerco muy colorido, que suele aparecer alrededor de la estrella polar.', false, '2025-09-13 13:53:13.116282+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adf8b078-e396-4b0b-8916-151167fc4bdb', '6ed2c861-99a7-4ad4-902c-31ff8ebde3e5', 'c', 'Una corona solar es una aureola que rodea al Sol y que se puede observar durante los eclipses', true, '2025-09-13 13:53:13.116493+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8152fc76-3889-4ff3-aa55-7b773ce0be0a', '6ed2c861-99a7-4ad4-902c-31ff8ebde3e5', 'd', 'Un parhelio es un fenómeno luminoso que consiste en la aparición simultánea de varias imágenes de una misma estrella, por lo general dispuestas simétricamente sobre un halo.', false, '2025-09-13 13:53:13.116688+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56d02031-f2c1-4f03-bed7-a8248ddb1fb0', '525fff2b-9b72-43ca-bb34-1cc409236bfd', 'a', 'Están unidos a la costa.', false, '2025-09-13 13:53:13.117143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f70a2e6-4109-4497-93fe-338b9d9d7c8e', '525fff2b-9b72-43ca-bb34-1cc409236bfd', 'b', 'Flotan libremente arrastrados por las corrientes.', true, '2025-09-13 13:53:13.117369+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('941ad647-395f-446f-ae0a-3aef14a3e13d', '525fff2b-9b72-43ca-bb34-1cc409236bfd', 'c', 'Son de origen terrestre.', false, '2025-09-13 13:53:13.117563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7912c8c-7514-41d7-b646-e6fa00c8e3ec', '525fff2b-9b72-43ca-bb34-1cc409236bfd', 'd', 'Se extienden de tierra hacia la mar formando lenguas de glaciar. Inglés', false, '2025-09-13 13:53:13.117769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5237b1d7-d6ac-442b-ab43-9b5c79763442', 'e5551323-473e-4c21-b069-625d6ece2635', 'a', 'Un libro de faros.', false, '2025-09-13 13:53:13.118232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd288183-bbdb-4519-967a-fbf489b19f59', 'e5551323-473e-4c21-b069-625d6ece2635', 'b', 'Una tabla de mareas.', false, '2025-09-13 13:53:13.118429+00');
