INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c48f30b1-148b-4a63-9f5c-01ccee079138', 'e5551323-473e-4c21-b069-625d6ece2635', 'd', 'Un catálogo de cartas náuticas.', false, '2025-09-13 13:53:13.118897+00');
