INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6aa9ad24-472b-48cc-8271-14ab83e97160', 'b7736827-c4db-4310-8774-391ad5f103a4', 'c', 'Son de origen terrestre.', false, '2025-09-13 13:53:13.153243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fbbbed3-8a65-4d31-86c9-ce6310ffa570', 'b7736827-c4db-4310-8774-391ad5f103a4', 'd', 'Se extienden de tierra hacia la mar formando lenguas de glaciar.', false, '2025-09-13 13:53:13.153436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fae9af79-eafb-4cbe-b076-f74f314c8c34', '8e130af8-6d5f-4ad1-b525-9b60fd333c8f', 'a', 'En el hemisferio Norte, si el viento rola en sentido horario el buque está en el semicírculo peligroso. Debe navegar a la mayor velocidad posible con el viento abierto de 1 a 4 cuartas (según su velocidad) por la amura de estribor y continuar cayendo a estribor a medida que role el viento para alejarse de la succión.', true, '2025-09-13 13:53:13.153837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bb94554-2c73-4704-91e2-85210e5dc593', '8e130af8-6d5f-4ad1-b525-9b60fd333c8f', 'b', 'En el hemisferio Sur, si el viento rola en sentido horario el buque está en el semicírculo peligroso. Debe navegar a la mayor velocidad posible con el viento abierto de 1 a 4 cuartas (según su velocidad) por la amura de estribor y continuar cayendo a estribor a medida que role el viento para alejarse de la succión.', false, '2025-09-13 13:53:13.154046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ce5da86-9cd8-463e-bee1-c8c0a6163de2', '8e130af8-6d5f-4ad1-b525-9b60fd333c8f', 'c', 'En el hemisferio Norte, si nos encontramos en el semicírculo navegable se debe mantener el viento sobre la aleta de babor y cambiar el rumbo poco a poco a estribor a medida que nos alejamos', false, '2025-09-13 13:53:13.154268+00');
