INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3c66a30-b4f0-43ed-8d43-080827ad86e8', 'c6d81e4a-6809-4d7c-b2aa-4b4fd33e83fc', 'a', 'Las condiciones necesarias para su formación son un aire frío denso y con escasa humedad en las capas inferiores de la atmósfera, y un aire cálido en las superiores.', false, '2025-09-13 13:53:13.154913+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b7bd73a-d387-44b7-ac38-30c969db4312', 'c6d81e4a-6809-4d7c-b2aa-4b4fd33e83fc', 'b', 'Aparecen asociadas a nubes de tipo cirro o similar, típicas de formas tormentosas.', false, '2025-09-13 13:53:13.155139+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68787f05-fa3d-4549-ab74-88537693346e', 'c6d81e4a-6809-4d7c-b2aa-4b4fd33e83fc', 'c', 'En su fase de madurez producen chubascos a veces acompañados de aparato eléctrico.', true, '2025-09-13 13:53:13.155338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c636cc88-7862-475c-8984-c065e2a49d12', 'c6d81e4a-6809-4d7c-b2aa-4b4fd33e83fc', 'd', 'No se desarrollan temporalmente por fases.', false, '2025-09-13 13:53:13.155542+00');
