INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2319d88e-8e5e-4b33-aa2d-adbaed7cbd7b', 'b623f570-3052-40dc-b137-67c609ea17d0', 'b', 'En ellos la presión puede alcanzar valores muy elevados, superiores a los 1100mb.', true, '2025-09-13 13:53:13.159458+00');
