INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('222ba85d-cc8f-4938-8c1a-4bb8482105bd', '4a7589e4-4027-476b-9775-bade86e48842', 'a', 'La Corriente del Labrador.', true, '2025-09-13 13:53:13.19277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8610aeb1-39b5-4747-babc-9064cb79ae58', '4a7589e4-4027-476b-9775-bade86e48842', 'b', 'La Corriente del Caribe.', false, '2025-09-13 13:53:13.192966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4a0077d-6bba-415f-8d9a-ff547dd12d91', '4a7589e4-4027-476b-9775-bade86e48842', 'c', 'La Corriente Ecuatorial del Norte.', false, '2025-09-13 13:53:13.193185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f98915d5-9561-428e-b3b6-97caf9d8ec78', '4a7589e4-4027-476b-9775-bade86e48842', 'd', 'La Corriente de las Azores.', false, '2025-09-13 13:53:13.19338+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('104f3c24-b407-4e20-aaab-136ac3b9259f', '2604578c-8f68-491b-81ce-232e6eb68f06', 'a', 'Es una franja de altas presiones.', true, '2025-09-13 13:53:13.193802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f1e6ec7-cc16-4b12-9c65-355f6f2b9a5d', '2604578c-8f68-491b-81ce-232e6eb68f06', 'b', 'Está ubicada en los alrededores del ecuador terrestre.', false, '2025-09-13 13:53:13.194041+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0a319a5-45a8-4e2b-93e9-39cc714f794c', '2604578c-8f68-491b-81ce-232e6eb68f06', 'c', 'Es la zona de confluencia de los vientos alisios del noreste, procedentes del hemisferio Norte, y los alisios del sudeste, que llegan del hemisferio Sur.', false, '2025-09-13 13:53:13.19426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66af972f-f044-4080-a974-67d27f031f07', '2604578c-8f68-491b-81ce-232e6eb68f06', 'd', 'En general, predominan en ella los vientos de componente ascendente.', false, '2025-09-13 13:53:13.194496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac179dc8-f58a-4a58-b5a7-a88e0aeb0920', '3ddff315-ffa4-43d3-a3dc-6f95952ff5f7', 'a', 'Entrar a la máxima velocidad para atravesarlo.', false, '2025-09-13 13:53:13.19494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('678219ad-751b-4411-985a-0bfb9528207c', '3ddff315-ffa4-43d3-a3dc-6f95952ff5f7', 'b', 'Esperar a que cambie la dirección de su movimiento.', true, '2025-09-13 13:53:13.195139+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba4d3e16-c736-4583-acb7-41a0ba1eeda2', '3ddff315-ffa4-43d3-a3dc-6f95952ff5f7', 'c', 'Nunca dar atrás a toda máquina durante la navegación.', false, '2025-09-13 13:53:13.195348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67f27687-2dab-46ec-b657-31c18874c71b', '3ddff315-ffa4-43d3-a3dc-6f95952ff5f7', 'd', 'Entrar al hielo a favor del viento.', false, '2025-09-13 13:53:13.195606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ad68cb2-ac46-4e27-8c95-04e782bcae4a', '7f79a72b-e2b4-4e68-8760-8320b07e0158', 'a', 'Posición del hielo cuando se observó por última vez.', false, '2025-09-13 13:53:13.196075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2267ecf-ff24-4a79-8f2c-9f4493f41b15', '7f79a72b-e2b4-4e68-8760-8320b07e0158', 'b', 'Naturaleza del hielo observado.', false, '2025-09-13 13:53:13.196288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('563720f4-f24c-4f0c-a6d7-44bede6afd77', '7f79a72b-e2b4-4e68-8760-8320b07e0158', 'c', 'Estado de la mar, fuerza y dirección del viento en el momento de la observación.', true, '2025-09-13 13:53:13.196491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('057a634a-9154-4580-922c-e85320de42a5', '7f79a72b-e2b4-4e68-8760-8320b07e0158', 'd', 'Fecha y hora (tiempo universal coordinado) de la última vez en que se observó el peligro.', false, '2025-09-13 13:53:13.196713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5fe2769e-70e4-40f8-96d2-9e15c238c7b5', '9016819d-64de-49d6-964f-96c36075152a', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida abierto entre 10° y 45° por la amura de estribor. Continuaremos cayendo a babor a medida que el viento siga rolando, para capear hasta que estemos en franquía.', false, '2025-09-13 13:53:13.197121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6929aa66-af59-43a4-9659-38edbdf1b477', '9016819d-64de-49d6-964f-96c36075152a', 'b', 'Proceder con toda la máquina a un rumbo tal que dejemos el viento por la aleta de babor. Continuaremos cayendo a estribor a medida que el viento role hasta que poco a poco salgamos de la zona de influencia.', true, '2025-09-13 13:53:13.197343+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d11fe6c5-2002-4a90-99c8-44d981e05cad', '9016819d-64de-49d6-964f-96c36075152a', 'c', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos', false, '2025-09-13 13:53:13.197561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('563e23b0-5b17-444b-b2d9-5833a2fdf7a1', '9016819d-64de-49d6-964f-96c36075152a', 'd', 'Ajustar el rumbo hasta que el viento venga por proa. Continuaremos cayendo a babor a medida que el viento siga rolando para mantener siempre la incidencia del viento por proa.', false, '2025-09-13 13:53:13.197769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb2a30bc-7de1-49cf-9731-818ed8220af9', '9bdc48e7-b92b-45c5-9a34-557e475d297c', 'a', 'Tienen corta duración y su comienzo y fin son, además, repentinos.', false, '2025-09-13 13:53:13.198182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e0e7bf06-92cb-4112-9719-5453ebb7cda5', '9bdc48e7-b92b-45c5-9a34-557e475d297c', 'b', 'Presentan variaciones violentas en la intensidad y dirección del viento.', false, '2025-09-13 13:53:13.198388+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b113d22-da21-4f5e-9b05-8b15ff62907b', '9bdc48e7-b92b-45c5-9a34-557e475d297c', 'c', 'Son capaces de descargar grandes cantidades de agua en poco tiempo.', true, '2025-09-13 13:53:13.19861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a105a75-62af-424e-81c9-64e4fec53e17', '9bdc48e7-b92b-45c5-9a34-557e475d297c', 'd', 'No se encuentran asociados a nubes de tipo cúmulo o cumulonimbo.', false, '2025-09-13 13:53:13.198834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ecbbfec-9d56-43eb-b2b0-814ca6c620c1', '9d83169d-baaf-4005-bd3d-4ae91dd1c446', 'a', 'Empezamos a ver las primeras nubes altas tipo cirro en el cielo que, a veces, parecen converger hacia un punto en el horizonte.', true, '2025-09-13 13:53:13.199284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f097363-29e3-46f0-b83a-b5cee93cd85c', '9d83169d-baaf-4005-bd3d-4ae91dd1c446', 'b', 'Mar tendida (olas largas en periodo) pero que no coincide con la dirección del viento.', false, '2025-09-13 13:53:13.199504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ff892c7-3ee2-4bf6-b233-a0fa498a6107', '9d83169d-baaf-4005-bd3d-4ae91dd1c446', 'c', 'Bajada del barómetro conforme se acerca el ciclón.', false, '2025-09-13 13:53:13.199695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90a7d908-faaa-49e2-ae9c-474124a33a91', '9d83169d-baaf-4005-bd3d-4ae91dd1c446', 'd', 'Descenso en la intensidad del viento.', false, '2025-09-13 13:53:13.19989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4faa130-e12e-4ac2-9c98-7db1386995f7', '496b6e26-b810-43fa-bd18-1f72fd90e33b', 'a', 'Se producen auroras boreales en el hemisferio Sur y auroras australes en el hemisferio Norte.', false, '2025-09-13 13:53:13.200317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47b624f2-bd35-4195-a1f7-ee02cacb0c57', '496b6e26-b810-43fa-bd18-1f72fd90e33b', 'b', 'Se producen auroras boreales en el hemisferio Norte y auroras australes en el hemisferio Sur.', false, '2025-09-13 13:53:13.20053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('558dd9be-d53c-4c15-bf52-46af4a0b0f70', '496b6e26-b810-43fa-bd18-1f72fd90e33b', 'c', 'Se producen por la refracción de la luz solar en la atmosfera.', true, '2025-09-13 13:53:13.200738+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('934133ef-1a3a-4041-be48-99c7c9b7eef8', '496b6e26-b810-43fa-bd18-1f72fd90e33b', 'd', 'Se producen por la reflexión de la luz solar en la atmosfera.', false, '2025-09-13 13:53:13.200965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecd767ed-df67-4fc1-81e4-0a0ae052923d', '4a11615f-c388-4311-8e83-1ba7e7b7395e', 'a', 'Giran en sentido anti-horario en el hemisferio Norte.', false, '2025-09-13 13:53:13.201424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e063f0b4-fc7b-472b-9307-2d292e9f369a', '4a11615f-c388-4311-8e83-1ba7e7b7395e', 'b', 'Giran en sentido horario en el hemisferio Norte.', false, '2025-09-13 13:53:13.201613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22d1e812-1aa3-4669-b258-b219235a4227', '4a11615f-c388-4311-8e83-1ba7e7b7395e', 'c', 'Se forman generalmente bajo nubes tipo cirro.', true, '2025-09-13 13:53:13.201823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9df26338-cf9c-44fb-9e13-d2be1f1a28bf', '4a11615f-c388-4311-8e83-1ba7e7b7395e', 'd', 'Se forman generalmente bajo nubes tipo estrato.', false, '2025-09-13 13:53:13.202029+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41a4b29b-c846-461a-89ba-50e5baa2df4e', 'b7f113b9-01fb-499d-b55d-deef53755d58', 'a', 'Baja presión en la Zona de Convergencia Intertropical.', false, '2025-09-13 13:53:13.202441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45879172-3687-460a-bf9f-f2566c49e0c7', 'b7f113b9-01fb-499d-b55d-deef53755d58', 'b', 'Alta presión en altura (con vientos divergentes que facilitan la convección del aire', false, '2025-09-13 13:53:13.202623+00');
