INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('182193f4-d6de-4f67-9101-2bd19cefe294', '553fa0f3-9607-4702-a056-92e2d7102199', 'a', 'Alejar la proa del viento.', false, '2025-09-13 13:53:13.518144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9bf2146f-a28d-473d-9965-125919cf288a', 'dbbd3736-953d-4e11-9f78-f45c2f002935', 'c', 'Se producen por la refracción de la luz solar en la atmosfera.', false, '2025-09-13 13:53:13.235017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a87101ac-edeb-49d5-9827-a24f29445f4c', 'dbbd3736-953d-4e11-9f78-f45c2f002935', 'd', 'Se producen por la reflexión de la luz solar en la atmosfera.', false, '2025-09-13 13:53:13.235236+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87c5d53c-3d11-49f7-8876-299f32dd4a51', '05ab2afc-cccd-4f4e-ae1b-231884351f63', 'a', 'La Corriente del Labrador.', false, '2025-09-13 13:53:13.235664+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('755675e4-96f6-46a3-9e1f-2fea5bba9b89', '05ab2afc-cccd-4f4e-ae1b-231884351f63', 'b', 'La Corriente del Caribe.', false, '2025-09-13 13:53:13.235888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8be2ead-d44e-46a8-9638-194cb1699166', '05ab2afc-cccd-4f4e-ae1b-231884351f63', 'c', 'La Corriente Ecuatorial del Norte.', true, '2025-09-13 13:53:13.23612+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('065aa61c-e240-4ef6-97fb-0f79713dce1d', '05ab2afc-cccd-4f4e-ae1b-231884351f63', 'd', 'La Corriente de las Azores.', false, '2025-09-13 13:53:13.236361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0da2bd99-ac43-4a36-bc31-9376b04f6084', '12a013af-17e8-4c9a-bd5f-291e390aa725', 'a', 'Posición del hielo cuando se observó por última vez.', false, '2025-09-13 13:53:13.236805+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('972712e8-fe30-4ddb-a58c-e5a54325d18a', '12a013af-17e8-4c9a-bd5f-291e390aa725', 'b', 'Naturaleza del hielo observado.', true, '2025-09-13 13:53:13.237014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5449a715-410d-4f6b-af4f-130901863043', '12a013af-17e8-4c9a-bd5f-291e390aa725', 'c', 'Estado de la mar, fuerza y dirección del viento en el momento de la observación.', false, '2025-09-13 13:53:13.237194+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4d3b023-856c-4d34-8949-04522c4cbfc7', '12a013af-17e8-4c9a-bd5f-291e390aa725', 'd', 'Fecha y hora (tiempo universal coordinado) de la última vez en que se observó el peligro.', false, '2025-09-13 13:53:13.237393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a76f4f30-dd94-40ce-963f-f68669125331', '0c457aa7-9b3b-4198-b2c7-acdcf4088851', 'a', 'Empezamos a ver las primeras nubes altas tipo cirro en el cielo que, a veces, parecen converger hacia un punto en el horizonte.', false, '2025-09-13 13:53:13.23783+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0d043ad-e01c-4248-8a43-8106ed391379', '0c457aa7-9b3b-4198-b2c7-acdcf4088851', 'b', 'Mar tendida (olas largas en periodo) pero que no coincide con la dirección del viento.', false, '2025-09-13 13:53:13.238043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4588572d-a2db-4478-9bab-cbb57e585912', '0c457aa7-9b3b-4198-b2c7-acdcf4088851', 'c', 'Bajada del barómetro conforme se acerca el ciclón.', false, '2025-09-13 13:53:13.238275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c9b869c-2566-4f42-9a87-3ad773f504b0', '0c457aa7-9b3b-4198-b2c7-acdcf4088851', 'd', 'Descenso en la intensidad del viento.', true, '2025-09-13 13:53:13.23846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab25196f-9abf-49e9-8571-d2300d416dbe', '7b820db7-4b63-484f-bb5d-a1477ecc1b10', 'a', 'Baja presión en la Zona de Convergencia Intertropical.', true, '2025-09-13 13:53:13.238857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d811c8ca-f9df-4bfd-9c89-bdef51c6545d', '7b820db7-4b63-484f-bb5d-a1477ecc1b10', 'b', 'Alta presión en altura (con vientos divergentes que facilitan la convección del aire', false, '2025-09-13 13:53:13.239072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ff920c3-8a8f-4bec-8d9a-4f26f3bc2ece', '7b820db7-4b63-484f-bb5d-a1477ecc1b10', 'c', 'Alta temperatura del mar que favorece la evaporación.', false, '2025-09-13 13:53:13.239277+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73c17aee-9734-43a9-88aa-53f9794f3b8b', '7b820db7-4b63-484f-bb5d-a1477ecc1b10', 'd', 'Presencia de viento fuerte en superficie para impedir las corrientes ascendentes.', false, '2025-09-13 13:53:13.239489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5081d730-2b89-48cc-aa4d-2c1d47181fb7', '71033882-c1eb-403a-b634-6136c1879780', 'a', 'Poner máquina toda avante y gobernar con un rumbo tal que el viento nos incida abierto entre 10° y 45° por la amura de estribor. Continuaremos cayendo a babor a medida que el viento siga rolando, para capear hasta que estemos en franquía.', false, '2025-09-13 13:53:13.239912+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d95e7b6b-bd13-4396-a149-a1e1c00506c5', '71033882-c1eb-403a-b634-6136c1879780', 'b', 'Proceder con toda la máquina a un rumbo tal que dejemos el viento por la aleta de babor. Continuaremos cayendo a estribor a medida que el viento role hasta que poco a poco salgamos de la zona de influencia.', false, '2025-09-13 13:53:13.240106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd980a46-5cef-4d55-bc34-cf43c9366fb3', '71033882-c1eb-403a-b634-6136c1879780', 'c', 'Reducir máquina hasta la mínima de gobierno y alterar el rumbo hasta que el viento nos incida por la aleta de estribor. Nos mantendremos corriendo el temporal hasta que poco a poco salgamos', false, '2025-09-13 13:53:13.240319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69e04d44-2fe9-483d-a47d-69f69f8fd6f9', '71033882-c1eb-403a-b634-6136c1879780', 'd', 'Ajustar el rumbo hasta que el viento venga por proa. Continuaremos cayendo a babor a medida que el viento siga rolando para mantener siempre la incidencia del viento por proa.', true, '2025-09-13 13:53:13.240551+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06afc9f0-a0b6-4b6d-a335-edfbf9c1173e', '5ecf2821-2c5a-4144-ae39-cab5f5a97aee', 'a', 'Es una franja de altas presiones.', false, '2025-09-13 13:53:13.241024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99d8d27f-638b-462c-8430-cb680b9540a1', '5ecf2821-2c5a-4144-ae39-cab5f5a97aee', 'b', 'Está ubicada en los alrededores del ecuador terrestre.', true, '2025-09-13 13:53:13.241243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a260cc4-47cf-4bcd-9b9b-a190ca513364', '5ecf2821-2c5a-4144-ae39-cab5f5a97aee', 'c', 'Es la zona de confluencia de los vientos alisios del noreste, procedentes del hemisferio Norte, y los alisios del sudeste, que llegan del hemisferio Sur.', false, '2025-09-13 13:53:13.241443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea185fec-7597-481e-9162-6ef846a0e064', '5ecf2821-2c5a-4144-ae39-cab5f5a97aee', 'd', 'En general, predominan en ella los vientos de componente ascendente.', false, '2025-09-13 13:53:13.241651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('271bfb5d-cea3-4cad-be5b-3afa7df6ade5', '0c5deba1-a7d1-4d3c-a11d-de0e06d067a3', 'a', 'Entrar a la máxima velocidad para atravesarlo.', true, '2025-09-13 13:53:13.242071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bab0dae-62ea-4ca6-9106-c94684979582', '0c5deba1-a7d1-4d3c-a11d-de0e06d067a3', 'b', 'Esperar a que cambie la dirección de su movimiento.', false, '2025-09-13 13:53:13.24225+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9235aa77-7150-4ef0-b18f-1e8c85a59a6a', '0c5deba1-a7d1-4d3c-a11d-de0e06d067a3', 'c', 'Nunca dar atrás a toda máquina durante la navegación.', false, '2025-09-13 13:53:13.242434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86c68912-201d-4e5f-b791-cfaf572ec1e9', '0c5deba1-a7d1-4d3c-a11d-de0e06d067a3', 'd', 'Entrar al hielo a favor del viento.', false, '2025-09-13 13:53:13.242661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('704c6bc6-9aa0-4213-a76d-4a24a6f6fdb7', '56d03058-4933-41e6-8be5-cf45903fe307', 'a', 'Tienen corta duración y su comienzo y fin son, además, repentinos.', false, '2025-09-13 13:53:13.243086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4bcf0a7-2925-4332-93ea-d68f1e45dcf6', '56d03058-4933-41e6-8be5-cf45903fe307', 'b', 'Presentan variaciones violentas en la intensidad y dirección del viento.', true, '2025-09-13 13:53:13.24333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78a57f39-1d2d-4b38-8de1-f33e09ea9225', '56d03058-4933-41e6-8be5-cf45903fe307', 'c', 'Son capaces de descargar grandes cantidades de agua en poco tiempo.', false, '2025-09-13 13:53:13.243523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a5786e39-e11a-4cf4-8b20-37f96b8065c6', '56d03058-4933-41e6-8be5-cf45903fe307', 'd', 'No se encuentran asociados a nubes de tipo cúmulo o cumulonimbo.', false, '2025-09-13 13:53:13.243716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d491b653-7d3f-4b62-bd72-4916add41ccf', '888b31ba-5f70-4283-a028-e56e6928e014', 'a', 'Giran en sentido anti-horario en el hemisferio Norte.', false, '2025-09-13 13:53:13.244144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7966048f-b621-4830-83ad-e6a565f1eb4e', '888b31ba-5f70-4283-a028-e56e6928e014', 'b', 'Giran en sentido horario en el hemisferio Norte.', true, '2025-09-13 13:53:13.244356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('549046bf-2402-4c61-980d-7c9e3010ccbe', '888b31ba-5f70-4283-a028-e56e6928e014', 'c', 'Se forman generalmente bajo nubes tipo cirro.', false, '2025-09-13 13:53:13.244562+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('445a68d1-8045-4c1d-b73d-09c8a5412b8b', '888b31ba-5f70-4283-a028-e56e6928e014', 'd', 'Se forman generalmente bajo nubes tipo estrato. Inglés', false, '2025-09-13 13:53:13.24477+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4266da2-f7ba-4c1a-ac54-735030f65fd9', '508dc8ca-0af6-4bf3-8940-8d96a5e3b0f6', 'a', 'Abatimiento / Acompañar / Rumbo.', false, '2025-09-13 13:53:13.24517+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cde8143-67a0-4bd2-a8ad-ffc62ff35a40', '508dc8ca-0af6-4bf3-8940-8d96a5e3b0f6', 'b', 'Deriva / Ceder el paso / Derrota.', false, '2025-09-13 13:53:13.245363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af6876d8-9f6d-4900-a91f-8c9e29be2103', '508dc8ca-0af6-4bf3-8940-8d96a5e3b0f6', 'c', 'Deriva / Acompañar / Rumbo.', false, '2025-09-13 13:53:13.245571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1eefb5f-2f85-4452-bef0-f34454c453c8', '508dc8ca-0af6-4bf3-8940-8d96a5e3b0f6', 'd', 'Abatimiento / Ceder el paso / Derrota. 32 39. Elija la traducción correcta de «Bilge pump switched on».', true, '2025-09-13 13:53:13.245774+00');
