INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb435f01-012f-4864-93ea-74cd2da67c6c', 'e5aae334-88ef-4ab6-8770-9cc09c6b8c92', 'a', 'La motonave (…) está sin gobierno. Tengo problemas con el sistema de gobierno. Manténgase apartado de mí.', false, '2025-09-13 13:53:13.249332+00');
