INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ff31c78-a33a-476d-8b39-200787351e43', '66a7b505-2060-4817-8cdc-c04c7bd63938', 'd', 'El agua no es lo suficientemente clara en la situación …', false, '2025-09-13 13:53:13.251035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7262302f-bc4a-4846-9e3f-a403d851cd60', '76953da7-097b-4971-add5-eb92337c080b', 'a', 'Atención. Rocas desconocidas en la situación (…). Riesgo de zozobra a la altamar.', false, '2025-09-13 13:53:13.251456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c8c9b40-ade6-420a-a390-e03babed5b5e', '76953da7-097b-4971-add5-eb92337c080b', 'b', 'Aviso. Rocas no señaladas en las cartas en la situación (…). Riesgo de varada a la bajamar.', false, '2025-09-13 13:53:13.251649+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d189574-8d5f-48e0-86ee-b29f3108dc8e', '76953da7-097b-4971-add5-eb92337c080b', 'c', 'Atención. Rocas identificadas en las cartas en la situación (…). Riesgo de varada a la altamar.', false, '2025-09-13 13:53:13.251855+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec3fe927-cd3f-482f-8a52-284c363e5571', '76953da7-097b-4971-add5-eb92337c080b', 'd', 'Aviso. Rocas señalizadas en las cartas en la situación (…). Riesgo de encallar a la bajamar.', true, '2025-09-13 13:53:13.252049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b678fb70-21fe-4de3-8022-414cfab508fe', '631220e6-f0df-402c-8e78-af1475971488', 'a', 'Casco / Puente / Adrizar.', false, '2025-09-13 13:53:13.252466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52d5a8ee-3b39-442b-99ff-112c228ce33d', '631220e6-f0df-402c-8e78-af1475971488', 'b', 'Bodega / Puente / Remolque.', true, '2025-09-13 13:53:13.252661+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b9ee837-7cc9-4bab-b468-8698ea96bb5f', '631220e6-f0df-402c-8e78-af1475971488', 'c', 'Casco / Cubierta / Remolque.', false, '2025-09-13 13:53:13.252875+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bea40f9f-1f22-4bc7-b471-dad3367930bd', '631220e6-f0df-402c-8e78-af1475971488', 'd', 'Bodega / Cubierta / Adrizar.', false, '2025-09-13 13:53:13.253087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d71f320c-2f2e-473e-aabc-f9ba7b9241cb', '08249213-df1a-4c52-86b1-9ed12bf684a5', 'a', 'La motonave… tiene un trimado peligroso a babor de … grados.', true, '2025-09-13 13:53:13.253531+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba64ad30-2594-4314-817a-a0b340e43962', '08249213-df1a-4c52-86b1-9ed12bf684a5', 'b', 'La motonave… tiene un balance peligroso a babor de … grados.', false, '2025-09-13 13:53:13.253735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01012ded-ced0-46eb-9ea8-f7ddf64faf26', '08249213-df1a-4c52-86b1-9ed12bf684a5', 'c', 'La motonave… tiene una escora peligrosa a estribor de … grados.', false, '2025-09-13 13:53:13.253967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad92b440-e5cf-4e8f-b28d-772f97bcf5d9', '08249213-df1a-4c52-86b1-9ed12bf684a5', 'd', 'La motonave… tiene un asiento peligroso a estribor de … grados.', false, '2025-09-13 13:53:13.25418+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c90a7489-4e7b-4336-b19b-22ee232c11a7', 'ab78b855-5e96-4b12-8906-fd003c49f5c6', 'a', 'Procedan inmediatamente a la cámara de máquinas / a sus cabinas. Cierren todas las aberturas.', true, '2025-09-13 13:53:13.254629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f4fc4be-0d62-4837-852e-f22be5296f43', 'ab78b855-5e96-4b12-8906-fd003c49f5c6', 'b', 'Abandonen inmediatamente la cámara de máquinas / sus cabinas. Ignoren todas las aberturas.', false, '2025-09-13 13:53:13.254837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34b3fc39-b25e-498e-abd0-8ab61281271e', 'ab78b855-5e96-4b12-8906-fd003c49f5c6', 'c', 'Diríjanse inmediatamente a la cámara de máquinas / a sus camarotes. Abran todas las aberturas.', false, '2025-09-13 13:53:13.255028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f86567ac-1cce-4b28-a3bf-c4dcd42142e5', 'ab78b855-5e96-4b12-8906-fd003c49f5c6', 'd', 'Abandonen inmediatamente la cámara de máquinas / sus camarotes. Cierren todas las aberturas. DE TRANSPORTES                                                                                    DE TRANSPORTES Y MOVILIDAD SOSTENIBLE Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO Código de Test 01 Seguridad en la mar', false, '2025-09-13 13:53:13.255244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eeacefd-b33b-4ba0-af0a-c9bc7fcfe0c6', '1b80f59e-9cd8-4377-9ebd-b221b6b3e4a8', 'a', 'La posición del metacentro respecto al centro de gravedad determina que el equilibrio sea estable', false, '2025-09-13 13:53:13.255848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a4ad257-3ca3-4d4a-a5c4-d9c876a6e34a', '1b80f59e-9cd8-4377-9ebd-b221b6b3e4a8', 'b', 'Una embarcación con altura metacéntrica pequeña tiene mucha estabilidad.', true, '2025-09-13 13:53:13.256056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92218784-c54b-4f45-aad8-f58828f35333', '1b80f59e-9cd8-4377-9ebd-b221b6b3e4a8', 'c', 'El centro de carena es el centro de gravedad de la obra muerta.', false, '2025-09-13 13:53:13.256254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c31fce40-399d-4398-a2f4-dd83c9615888', '1b80f59e-9cd8-4377-9ebd-b221b6b3e4a8', 'd', 'Cuando el empuje y el peso están en la misma horizontal, con el barco escorado, nos encontramos ante una situación de equilibrio estable.', false, '2025-09-13 13:53:13.256463+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('073e2f31-751c-48ac-b53e-8df3a1c9b0f9', 'f3e678a5-459a-4fa0-a9e7-6768a0cbcd66', 'a', 'Ponerse el chaleco salvavidas.', false, '2025-09-13 13:53:13.256889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8379ecab-581b-4291-a917-3f10919175ea', 'f3e678a5-459a-4fa0-a9e7-6768a0cbcd66', 'b', 'Lanzar un cohete provisto de paracaídas cuando se aproxime el helicóptero.', true, '2025-09-13 13:53:13.257099+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc0de7f0-5d29-4150-a601-940f134250e4', 'f3e678a5-459a-4fa0-a9e7-6768a0cbcd66', 'c', 'Usar el VHF para guiar al helicóptero usando la técnica de las horas en un reloj.', false, '2025-09-13 13:53:13.257293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd93e8ca-5413-4637-8dd0-61305881ca47', 'f3e678a5-459a-4fa0-a9e7-6768a0cbcd66', 'd', 'Despejar la cubierta de todo material y equipos que puedan salir volando.', false, '2025-09-13 13:53:13.257478+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b17b036a-87e2-48fd-81de-307aeba3d1e7', 'ab2305bb-7a26-41f5-94d7-da76d8831669', 'a', 'A babor y por encima de la cubierta principal.', false, '2025-09-13 13:53:13.257921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0c19f3b-1152-4464-bed9-1f5fec7e3a2f', 'ab2305bb-7a26-41f5-94d7-da76d8831669', 'b', 'Solamente a babor, ya que la altura metacéntrica no se puede corregir.', true, '2025-09-13 13:53:13.258139+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b18a6ff9-26db-4cf7-8623-5c637243127a', 'ab2305bb-7a26-41f5-94d7-da76d8831669', 'c', 'A estribor y por debajo de la cubierta principal.', false, '2025-09-13 13:53:13.258351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6c6a48a-3603-444f-aaab-2969fdca9223', 'ab2305bb-7a26-41f5-94d7-da76d8831669', 'd', 'A babor y por debajo de la cubierta principal.', false, '2025-09-13 13:53:13.258553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2490792-5423-4030-bea8-1f657c947abc', '4c3b7d8f-c679-45d0-9820-4f887b617725', 'a', 'Arriar las velas y arrancar el motor.', false, '2025-09-13 13:53:13.258997+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02fbd8a1-c94f-460c-8b3f-5d32b91b5d9e', '4c3b7d8f-c679-45d0-9820-4f887b617725', 'b', 'Izar las velas y apagar el motor.', false, '2025-09-13 13:53:13.259197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c19d2305-7655-444f-8b2f-e485c9fb639b', '4c3b7d8f-c679-45d0-9820-4f887b617725', 'c', 'Izar las velas y arrancar el motor.', true, '2025-09-13 13:53:13.259393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39589c59-6833-44d4-9622-ae2feb817861', '4c3b7d8f-c679-45d0-9820-4f887b617725', 'd', 'Arriar las velas y apagar el motor.', false, '2025-09-13 13:53:13.259589+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44df6b5c-552b-4278-b3b8-65d22885cda2', '740ea879-6049-4d26-9659-6769ec8f679a', 'a', 'Tire la driza de la balsa salvavidas al agua antes de abandonar la embarcación.', false, '2025-09-13 13:53:13.259995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cfb7ae0-9ddf-4cfc-bfc9-cd27963e4e81', '740ea879-6049-4d26-9659-6769ec8f679a', 'b', 'Nunca ate la driza a la embarcación.', false, '2025-09-13 13:53:13.26019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1350a5ab-bbbe-4396-ba86-d58d6dbdf564', '740ea879-6049-4d26-9659-6769ec8f679a', 'c', 'Voltee la balsa salvavidas colocándose a barlovento y nunca se suba a la botella de aire', true, '2025-09-13 13:53:13.260406+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7b4a4fc-00eb-4746-9025-36ba16444ab7', '740ea879-6049-4d26-9659-6769ec8f679a', 'd', 'Corte la driza de la balsa salvavidas en el último momento.', false, '2025-09-13 13:53:13.260606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85430a8a-b07c-4e80-8386-e06df1b4289e', 'da19edcc-5cb8-4a0a-9177-f8ca5a4c5fe3', 'a', 'Dos aros salvavidas, uno de ellos con luz y rabiza.', false, '2025-09-13 13:53:13.261032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38e28e57-99ff-4baa-ad32-635551692466', 'da19edcc-5cb8-4a0a-9177-f8ca5a4c5fe3', 'b', 'Una balsa salvavidas con capacidad para el 80% del máximo número de personas autorizado en el certificado de navegabilidad de la embarcación.', false, '2025-09-13 13:53:13.261231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c85aaaf-5550-4b18-a6f8-80686ace2d30', 'da19edcc-5cb8-4a0a-9177-f8ca5a4c5fe3', 'c', 'Seis bengalas de mano y tres cohetes con luz roja y paracaídas.', true, '2025-09-13 13:53:13.261437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2da4cae8-da5a-4b0b-9e2e-c9833ecd718d', 'da19edcc-5cb8-4a0a-9177-f8ca5a4c5fe3', 'd', 'Tantos chalecos como personas haya a bordo e irán dotados con luz.', false, '2025-09-13 13:53:13.261633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b6d8573-301d-41d5-b01a-fc884fc26b2c', 'a24ef1fe-7c81-41b7-a8cb-8befcd338933', 'a', 'Llevarla consigo a la balsa salvavidas.', false, '2025-09-13 13:53:13.262044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7bbacc0d-3b22-48df-8e68-c3053de4a68e', 'a24ef1fe-7c81-41b7-a8cb-8befcd338933', 'b', 'Dejarla flotar libremente amarrada con la rabiza.', true, '2025-09-13 13:53:13.262256+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dc32acd-8927-4091-81f4-524341952a2f', 'a24ef1fe-7c81-41b7-a8cb-8befcd338933', 'c', 'Activarla para poder ser localizado.', false, '2025-09-13 13:53:13.262489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbd0406f-9c03-4b6b-8d8e-b8a16b3d8183', 'a24ef1fe-7c81-41b7-a8cb-8befcd338933', 'd', 'Mantenerla siempre a bordo de la embarcación, ya que podrá activarla de forma remota.', false, '2025-09-13 13:53:13.262673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bf26bc99-1fc6-4ea1-8a89-8d0cb0e7eb37', '4302ff3b-6448-42cd-b80c-c660acd3f812', 'a', 'Las balsas salvavidas tendrán suficiente estabilidad para que, con su dotación completa de personal y equipos, puedan ser remolcadas a una velocidad de hasta 3 nudos en aguas tranquilas.', false, '2025-09-13 13:53:13.263107+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18326b70-984d-4c72-a467-ca7168dcfc13', '4302ff3b-6448-42cd-b80c-c660acd3f812', 'b', 'Las bengalas de mano deben dispararse siempre hacia sotavento y deben ser almacenadas en un lugar seco, accesible y apartado de cualquier fuente de calor.', false, '2025-09-13 13:53:13.26331+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95ba1a12-cdb1-4a68-bd4a-7a87b117335c', 'd44706da-2381-4774-bff6-61a41b051a15', 'b', 'Es perpendicular al eje de rotación de la Tierra.', true, '2025-09-13 13:53:13.279363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1a8b209-13a8-4ce5-b401-766755e6867b', '4302ff3b-6448-42cd-b80c-c660acd3f812', 'c', 'Los baldes contraincendios podrán utilizarse para achique y otros usos, pero nunca para apagar fuegos de origen eléctrico.', false, '2025-09-13 13:53:13.263513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a92a82d4-658d-4385-928f-b0e20c873af4', '4302ff3b-6448-42cd-b80c-c660acd3f812', 'd', 'Las embarcaciones de casco metálico llevarán siempre instalado un reflector de radar para las zonas de navegación 1 y 2.', true, '2025-09-13 13:53:13.263719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e243e3-27ae-4324-8e3a-f7cc6f2515da', 'fbaf5e8b-7065-421a-9246-1844afc6b384', 'a', 'Centro de gravedad.', false, '2025-09-13 13:53:13.264148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bcbff53-d898-4582-8baf-2a4c80f8464b', 'fbaf5e8b-7065-421a-9246-1844afc6b384', 'b', 'Centro de carena.', true, '2025-09-13 13:53:13.264352+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('217fe018-e348-42e2-bb0e-8c2065812b00', 'fbaf5e8b-7065-421a-9246-1844afc6b384', 'c', 'Metacentro.', false, '2025-09-13 13:53:13.264544+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec3e2272-395c-4359-9664-98ced2132861', 'fbaf5e8b-7065-421a-9246-1844afc6b384', 'd', 'Altura metacéntrica.', false, '2025-09-13 13:53:13.264769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ccfd6ba0-7443-4a8f-9d7a-c946ed0ab1a5', '1f82fb54-16d6-462f-bee6-bf18f8b58254', 'a', 'EPIRB.', false, '2025-09-13 13:53:13.265199+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('393b2714-49b7-437f-8ac6-5dc3f1f83295', '1f82fb54-16d6-462f-bee6-bf18f8b58254', 'b', 'AIS SART.', false, '2025-09-13 13:53:13.265415+00');
