INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d013e07-a168-4dc2-86d9-d8b14a54f5ac', '7bb05053-86c2-4e6a-a7c6-ade51bb50c4a', 'b', 'Son nubes de tipo alto.', false, '2025-09-13 13:53:13.266489+00');
