INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b078d73d-12c2-4688-8b04-b073d2141411', '7bb05053-86c2-4e6a-a7c6-ade51bb50c4a', 'd', 'Son nubes de desarrollo vertical.', false, '2025-09-13 13:53:13.266908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7441611-6d5a-4078-bb89-a51d56f28a7e', '89f7756e-6183-4378-9f17-eb786a290e41', 'a', 'Es el volumen del vapor de agua existente por unidad de volumen de aire.', true, '2025-09-13 13:53:13.267358+00');
