INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dddf20c4-9d97-4214-bf6f-63efc054c570', '89f7756e-6183-4378-9f17-eb786a290e41', 'c', 'Es el peso del vapor de agua existente por unidad de volumen de aire.', false, '2025-09-13 13:53:13.2678+00');
