INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3164f725-264b-44f0-914b-606a0411234f', '5f0d293f-7951-4594-8f74-e432eb7afd0b', 'a', 'Dos aros salvavidas, uno de ellos con luz y rabiza.', true, '2025-09-13 13:53:13.299935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6fcb4653-6c88-40bd-9231-4ba1ef1ff649', '5f0d293f-7951-4594-8f74-e432eb7afd0b', 'b', 'Una balsa salvavidas con capacidad para el 80% del máximo número de personas autorizado en el certificado de navegabilidad de la embarcación.', false, '2025-09-13 13:53:13.300132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51eb4704-5942-425a-9c56-5bf5f562c154', '5f0d293f-7951-4594-8f74-e432eb7afd0b', 'c', 'Seis bengalas de mano y tres cohetes con luz roja y paracaídas.', false, '2025-09-13 13:53:13.300349+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ee7989d-ba23-4ae3-af6d-a94165c615dc', '5f0d293f-7951-4594-8f74-e432eb7afd0b', 'd', 'Tantos chalecos como personas haya a bordo e irán dotados con luz.', false, '2025-09-13 13:53:13.300549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3cfb4a88-7a45-4467-a0a7-203124dbfd45', 'd8bdf113-dfaf-4ba6-9088-412cce892af3', 'a', 'Arriar las velas y arrancar el motor.', false, '2025-09-13 13:53:13.300994+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('847612a0-12a7-47bd-b1b4-6535daede1ab', 'd8bdf113-dfaf-4ba6-9088-412cce892af3', 'b', 'Izar las velas y apagar el motor.', true, '2025-09-13 13:53:13.301206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee1263c4-8a08-43dc-bf68-15878b834387', 'd8bdf113-dfaf-4ba6-9088-412cce892af3', 'c', 'Izar las velas y arrancar el motor.', false, '2025-09-13 13:53:13.301409+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30953f56-2f76-4584-bb0f-e6b1ca701b8b', 'd8bdf113-dfaf-4ba6-9088-412cce892af3', 'd', 'Arriar las velas y apagar el motor.', false, '2025-09-13 13:53:13.30161+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0337a445-f20e-44b6-bae1-6e08b91cb4a9', '0c62768c-04ee-4857-9943-862051359c19', 'a', 'Las balsas salvavidas tendrán suficiente estabilidad para que, con su dotación completa de personal y equipos, puedan ser remolcadas a una velocidad de hasta 3 nudos en aguas tranquilas.', true, '2025-09-13 13:53:13.302045+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf557f35-e4e6-4199-aa10-6d1a0b3d87c8', '0c62768c-04ee-4857-9943-862051359c19', 'b', 'Las bengalas de mano deben dispararse siempre hacia sotavento y deben ser almacenadas en un lugar seco, accesible y apartado de cualquier fuente de calor.', false, '2025-09-13 13:53:13.302247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('795e1b57-43ee-4bea-867d-6cd9437964aa', '0c62768c-04ee-4857-9943-862051359c19', 'c', 'Los baldes contraincendios podrán utilizarse para achique y otros usos, pero nunca para apagar fuegos de origen eléctrico.', false, '2025-09-13 13:53:13.302454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e010c0e-9d3c-4b01-ac6b-23c0f8f9cfed', '0c62768c-04ee-4857-9943-862051359c19', 'd', 'Las embarcaciones de casco metálico llevarán siempre instalado un reflector de radar para las zonas de navegación 1 y 2.', false, '2025-09-13 13:53:13.302673+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f3ccef8-d4b6-4b92-94a0-cd968d3c7bb8', '0a736d62-789a-4185-8fe4-b16895500bd2', 'a', 'Centro de gravedad.', false, '2025-09-13 13:53:13.30312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('561e1c90-b380-4d84-a090-e93efea67ba3', '0a736d62-789a-4185-8fe4-b16895500bd2', 'b', 'Centro de carena.', false, '2025-09-13 13:53:13.303327+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac5b0352-246c-47e7-8d90-88940bab5dac', '0a736d62-789a-4185-8fe4-b16895500bd2', 'c', 'Metacentro.', true, '2025-09-13 13:53:13.303553+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6198c649-c219-4e0a-bec4-05a50690c520', '0a736d62-789a-4185-8fe4-b16895500bd2', 'd', 'Altura metacéntrica.', false, '2025-09-13 13:53:13.303772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80ec52d0-1f80-4496-9126-29ad73d90817', 'ee95794e-a9e8-407e-bb65-dddc7c26a9dd', 'a', 'Tire la driza de la balsa salvavidas al agua antes de abandonar la embarcación.', false, '2025-09-13 13:53:13.30422+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b61af7e-f23f-48d1-aaa0-a1aab7e1caad', 'ee95794e-a9e8-407e-bb65-dddc7c26a9dd', 'b', 'Nunca ate la driza a la embarcación.', true, '2025-09-13 13:53:13.304441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b7655d3-c345-4fdb-b58d-afec981be50b', 'ee95794e-a9e8-407e-bb65-dddc7c26a9dd', 'c', 'Voltee la balsa salvavidas colocándose a barlovento y nunca se suba a la botella de aire', false, '2025-09-13 13:53:13.304658+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1004bc99-2eac-41cd-836b-4f7ae8f6187c', 'ee95794e-a9e8-407e-bb65-dddc7c26a9dd', 'd', 'Corte la driza de la balsa salvavidas en el último momento.', false, '2025-09-13 13:53:13.304876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57b50861-c246-495c-8d77-70eb104431af', 'fa69a7b1-1bb4-4acd-bde7-f59a3526fef6', 'a', 'Llevarla consigo a la balsa salvavidas.', false, '2025-09-13 13:53:13.305317+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da5b760e-1e6f-4fef-98d0-abd9ce0b3250', 'fa69a7b1-1bb4-4acd-bde7-f59a3526fef6', 'b', 'Dejarla flotar libremente amarrada con la rabiza.', false, '2025-09-13 13:53:13.305534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9e3ba93-406c-473a-a5d3-9937048aa309', 'fa69a7b1-1bb4-4acd-bde7-f59a3526fef6', 'c', 'Activarla para poder ser localizado.', true, '2025-09-13 13:53:13.305746+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e980421c-ac86-4a62-ab78-ce6ddb723ac1', 'fa69a7b1-1bb4-4acd-bde7-f59a3526fef6', 'd', 'Mantenerla siempre a bordo de la embarcación, ya que podrá activarla de forma remota.', false, '2025-09-13 13:53:13.305971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1d282d5-1dbc-4956-9c2f-883a90435adc', 'e4fd29d2-12d0-47ed-b609-c52296208dfb', 'a', 'EPIRB.', false, '2025-09-13 13:53:13.306411+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('950f31a1-3084-4b9f-9371-19364b7aa8f7', 'e4fd29d2-12d0-47ed-b609-c52296208dfb', 'b', 'AIS SART.', true, '2025-09-13 13:53:13.306619+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9322b71c-a6e3-41b2-beb9-9920e02243ff', 'e4fd29d2-12d0-47ed-b609-c52296208dfb', 'c', 'RADAR SART.', false, '2025-09-13 13:53:13.306842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d6ffb7f-662c-4351-a77e-b9598d1d2be6', 'e4fd29d2-12d0-47ed-b609-c52296208dfb', 'd', 'Llamada Selectiva Digital (LSD).', false, '2025-09-13 13:53:13.307044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60369969-e3a7-448a-a6b0-da23dc3bd708', '8f7cd279-2a6c-4cd7-98e6-acc61eee3122', 'a', 'La posición del metacentro respecto al centro de gravedad determina que el equilibrio sea estable', false, '2025-09-13 13:53:13.307487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe75ff8b-51b2-4a40-a6c5-eae9a27fae75', '8f7cd279-2a6c-4cd7-98e6-acc61eee3122', 'b', 'Una embarcación con altura metacéntrica pequeña tiene mucha estabilidad.', false, '2025-09-13 13:53:13.307694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2ec22c22-a5cd-4c9d-b75f-474c5c77669f', '8f7cd279-2a6c-4cd7-98e6-acc61eee3122', 'c', 'El centro de carena es el centro de gravedad de la obra muerta.', true, '2025-09-13 13:53:13.307902+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a66320f-151a-47fc-b5df-730c20c4a0df', '8f7cd279-2a6c-4cd7-98e6-acc61eee3122', 'd', 'Cuando el empuje y el peso están en la misma horizontal, con el barco escorado, nos encontramos ante una situación de equilibrio estable.', false, '2025-09-13 13:53:13.308121+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('888ad941-efd9-42f9-af03-2789d5f68d5f', '29f1e756-c929-4503-834e-9c6762693f4b', 'a', 'A babor y por encima de la cubierta principal.', true, '2025-09-13 13:53:13.308549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a9e16ec-fb77-4ce8-8dd2-5cea514b3737', '29f1e756-c929-4503-834e-9c6762693f4b', 'b', 'Solamente a babor, ya que la altura metacéntrica no se puede corregir.', false, '2025-09-13 13:53:13.308772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e9615a7-c415-44ec-9db5-cf51253a8156', '29f1e756-c929-4503-834e-9c6762693f4b', 'c', 'A estribor y por debajo de la cubierta principal.', false, '2025-09-13 13:53:13.308982+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5ca6bb1-7920-4e9d-a072-895425c5e05f', '29f1e756-c929-4503-834e-9c6762693f4b', 'd', 'A babor y por debajo de la cubierta principal. Meteorología', false, '2025-09-13 13:53:13.309175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6185d94-176f-495d-bc8e-a30d741cbec3', 'b48e7978-bfb4-4d46-aa6b-e39ec78a5f71', 'a', 'La lluvia.', false, '2025-09-13 13:53:13.309613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53a95bf0-c57b-48d3-95eb-53b748650666', 'b48e7978-bfb4-4d46-aa6b-e39ec78a5f71', 'b', 'El viento.', false, '2025-09-13 13:53:13.309829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33ed772c-625b-4747-a3af-75b312eae598', 'b48e7978-bfb4-4d46-aa6b-e39ec78a5f71', 'c', 'La niebla.', false, '2025-09-13 13:53:13.310034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a63f66f-f5b1-45bd-aac9-999a53b3da7a', 'b48e7978-bfb4-4d46-aa6b-e39ec78a5f71', 'd', 'Las heladas.', true, '2025-09-13 13:53:13.310248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bcd8894-a908-49c5-806d-d5010241f902', 'f96ce470-7594-40e9-b5f8-095c57464f35', 'a', 'Es el volumen del vapor de agua existente por unidad de volumen de aire.', false, '2025-09-13 13:53:13.310674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d0ddf56-7f76-4f19-b194-bf1d6fdff071', 'f96ce470-7594-40e9-b5f8-095c57464f35', 'b', 'Es la masa de vapor de agua por unidad de masa de aire húmedo, expresada en gramos de vapor por kg. de aire húmedo.', true, '2025-09-13 13:53:13.310885+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d0c346d-5a01-4324-a286-6b6eb22f99ab', 'f96ce470-7594-40e9-b5f8-095c57464f35', 'c', 'Es el peso del vapor de agua existente por unidad de volumen de aire.', false, '2025-09-13 13:53:13.311092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('694e5ece-ab2e-41d1-b706-55b47f66496f', 'f96ce470-7594-40e9-b5f8-095c57464f35', 'd', 'Es la relación que existe entre la cantidad de vapor de agua que contiene una masa de aire y la que contendría manteniendo la misma temperatura y presión si estuviese saturada.', false, '2025-09-13 13:53:13.31131+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00bc3401-03ef-4837-98cd-41e73f64cf9e', 'c7c7a00d-fd24-486d-81b6-81211c8650be', 'a', 'Si las isobaras están muy juntas, el gradiente horizontal de presión será grande y, por lo tanto, los vientos fuertes.', false, '2025-09-13 13:53:13.311771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('338ce51b-6d8a-4ff0-a640-204031ece534', 'c7c7a00d-fd24-486d-81b6-81211c8650be', 'b', 'Si las isobaras están muy alejadas, el gradiente de presión será grande y, por lo tanto, los vientos', false, '2025-09-13 13:53:13.311967+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ac28ed5-4950-41fc-b6f9-ce8648c56d2a', 'c7c7a00d-fd24-486d-81b6-81211c8650be', 'c', 'Si las isobaras están muy juntas, el gradiente horizontal de presión será pequeño y, por lo tanto, los vientos flojos.', false, '2025-09-13 13:53:13.31216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('495cdc61-e112-47a1-ad55-c59af910715b', 'c7c7a00d-fd24-486d-81b6-81211c8650be', 'd', 'Si las isobaras están muy alejadas, el gradiente horizontal de presión será grande y, por lo tanto, los vientos flojos.', true, '2025-09-13 13:53:13.312364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebff7fb7-e772-4988-9bef-08bc5e798f30', '3626a31b-4525-4954-b4f5-8d67fa14ded8', 'a', 'Viento de Euler.', true, '2025-09-13 13:53:13.312782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('616f6507-1d66-4be6-8a99-171b075ceae4', '3626a31b-4525-4954-b4f5-8d67fa14ded8', 'b', 'Viento Geostrófico.', false, '2025-09-13 13:53:13.312983+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00a73189-2097-4e27-9142-f44e37c82552', '3626a31b-4525-4954-b4f5-8d67fa14ded8', 'c', 'Viento Ciclostrófico.', false, '2025-09-13 13:53:13.313185+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5198e36a-f027-426c-b234-55703c9a98aa', '3626a31b-4525-4954-b4f5-8d67fa14ded8', 'd', 'Viento de gradiente.', false, '2025-09-13 13:53:13.313389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2703b4e6-56df-4f66-aa7e-bfd3669ecc0a', '0d44fb63-39ec-4b77-9872-6d8fced14040', 'a', 'Se aclara a medida que se va desplazando sobre aguas más templadas.', false, '2025-09-13 13:53:13.313812+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6103888e-8a18-46d3-ac27-df27d819e7d7', '0d44fb63-39ec-4b77-9872-6d8fced14040', 'b', 'Se aclara a medida que se va desplazando sobre aguas más frías.', true, '2025-09-13 13:53:13.314014+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('52623c29-a834-4599-85ff-58050384b9af', '0d44fb63-39ec-4b77-9872-6d8fced14040', 'c', 'Se intensifica a medida que se va desplazando sobre aguas más templadas.', false, '2025-09-13 13:53:13.314218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cfc8ba8-98ab-427b-88df-c4d20f8a023c', '0d44fb63-39ec-4b77-9872-6d8fced14040', 'd', 'No se dispersa hasta que el sol ha brillado un mínimo de 12 horas.', false, '2025-09-13 13:53:13.314437+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10364048-270b-4396-a919-1ffba34f2116', '7a0178be-89af-4159-9894-fd22b1fc0a1f', 'a', 'El aire frío va desplazando en su avance al aire caliente hacia abajo.', false, '2025-09-13 13:53:13.314878+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ae4d2b6-a6ea-4cb5-85c2-337d5cccb085', '7a0178be-89af-4159-9894-fd22b1fc0a1f', 'b', 'El aire caliente va desplazando en su avance al aire frío.', false, '2025-09-13 13:53:13.31508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('275bf4ff-5e94-452f-8802-15723b1ebee8', '7a0178be-89af-4159-9894-fd22b1fc0a1f', 'c', 'Siendo inicialmente caliente, ha sido alcanzado por su parte posterior por una masa de aire frío que lo desplaza hacia arriba.', true, '2025-09-13 13:53:13.315291+00');
