INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18e0d2d3-8cf2-4b2d-91bb-b0ec4158ab71', '373e951f-0b7e-45a6-93ca-d4cb9914d862', 'a', 'Esta emerge lo máximo posible disminuyendo la parte sumergida al mínimo.', false, '2025-09-13 13:53:13.34427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9af67871-40b0-46bc-be3c-66f531591b8f', '373e951f-0b7e-45a6-93ca-d4cb9914d862', 'b', 'Esta está cargada al máximo permitido.', true, '2025-09-13 13:53:13.344534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1a0382d-b514-49bd-b2fb-dcceeef74631', '373e951f-0b7e-45a6-93ca-d4cb9914d862', 'c', 'El calado a proa es mayor que el calado a popa.', false, '2025-09-13 13:53:13.344744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9668d487-52f1-45b4-8712-e790c49fbea0', '373e951f-0b7e-45a6-93ca-d4cb9914d862', 'd', 'El calado a popa es mayor que el calado a proa.', false, '2025-09-13 13:53:13.344948+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('04d7504b-460b-4736-aa3b-da4e7f8f92e7', 'b56d625f-d962-40b5-9769-dd214cf8115a', 'a', 'Divide la embarcación en dos mitades transversalmente, la de popa y la de proa.', false, '2025-09-13 13:53:13.345383+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e9c8b19d-cac1-4647-947f-fa98b387ea49', 'b56d625f-d962-40b5-9769-dd214cf8115a', 'b', 'Divide la embarcación en dos mitades horizontales, la de la obra viva y la de la obra muerta.', false, '2025-09-13 13:53:13.345595+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e70042e-fac2-4074-bc7d-624a4117c00c', 'b56d625f-d962-40b5-9769-dd214cf8115a', 'c', 'Divide la embarcación en dos mitades longitudinalmente, la de babor y la de estribor.', true, '2025-09-13 13:53:13.345826+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('72b69c88-9416-43f6-90f4-ff7930cd903f', 'b56d625f-d962-40b5-9769-dd214cf8115a', 'd', 'Se traza horizontalmente a la altura de la quilla y sirve como base de la embarcación. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:13.346023+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('882fb9a4-127c-4159-844c-d9972cd0e35f', '7585d74d-84de-4895-90b7-31fb0ea0d97b', 'a', 'El nudo llano se utiliza para afirmar un cabo con rapidez a un pasamanos, poste o argolla.', false, '2025-09-13 13:53:13.346501+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c02f4c4-2b6d-4d9f-8cfc-abd301244abb', '7585d74d-84de-4895-90b7-31fb0ea0d97b', 'b', 'La gaza es la curvatura que forma el cabo cuando este no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:13.346752+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fffaf728-16a9-46ed-85e2-05eec3da47f5', '7585d74d-84de-4895-90b7-31fb0ea0d97b', 'c', 'La cornamusa es una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio, sirve para amarrar los cabos.', true, '2025-09-13 13:53:13.346999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('98378fe5-8dd7-42b6-9fd5-e6decefb4d0d', '7585d74d-84de-4895-90b7-31fb0ea0d97b', 'd', 'El chicote es un bucle en el cabo que queda al anudarlo.', false, '2025-09-13 13:53:13.34721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('309ac57a-79ab-49a4-b32c-d63cc9674d8d', '0bb339b5-911f-43a0-93b1-df8667d81694', 'a', 'Son elementos de seguridad en el caso de persona al agua.', false, '2025-09-13 13:53:13.34909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a010973-def1-4c8f-9264-4c7ff642ae3f', '0bb339b5-911f-43a0-93b1-df8667d81694', 'c', 'El nombre de la embarcación debe figurar en ellos.', false, '2025-09-13 13:53:13.349527+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('246a285b-de2c-4771-bd15-a40b6302f340', '0bb339b5-911f-43a0-93b1-df8667d81694', 'd', 'Si pierde uno durante la navegación debe informar a Salvamento Marítimo.', false, '2025-09-13 13:53:13.349741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f366bee-dcc1-42ca-ad7f-d57f61c3f5d9', '1e12be21-7f40-49e0-b2f3-6e7398da7495', 'a', 'Reducir la velocidad.', false, '2025-09-13 13:53:13.350198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68654352-7652-4be9-b833-83bfb3b9c1d3', '1e12be21-7f40-49e0-b2f3-6e7398da7495', 'b', 'Realizar la secuencia de señales fónicas reglamentarias.', false, '2025-09-13 13:53:13.350413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd3fe2c9-2045-43c3-8481-37e19236fa4b', '1e12be21-7f40-49e0-b2f3-6e7398da7495', 'c', 'Reforzar la vigilancia.', false, '2025-09-13 13:53:13.350628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc55c0d1-65ef-4169-9b12-0de011968048', '1e12be21-7f40-49e0-b2f3-6e7398da7495', 'd', 'Navegar lo más próximos a la costa.', true, '2025-09-13 13:53:13.350848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54212161-10cb-41e3-bdfc-f38d4cf67f87', 'b486a559-1107-49bc-ace8-60b6f895cfa9', 'a', 'El centro geométrico y la cota cero de la quilla de la embarcación.', false, '2025-09-13 13:53:13.351296+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e42851c5-ec1e-4cb7-bd3b-5af3a0c0e2d0', '0bb339b5-911f-43a0-93b1-df8667d81694', 'b', 'Deben estibarse a proa y en el interior de la embarcación, para evitar que sufran las inclemencias del tiempo.', true, '2025-09-13 13:53:13.349312+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efbb6aec-4b30-4e40-9a03-71d2573451e9', 'b486a559-1107-49bc-ace8-60b6f895cfa9', 'b', 'El centro de gravedad y el centro de carena de la embarcación.', true, '2025-09-13 13:53:13.351513+00');
