INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('268ecdf7-4dda-4573-8fd5-5f8656fcf978', '7fcb6505-0194-4575-899e-5f18d04eaf03', 'a', 'Llevar puesto un chaleco salvavidas.', false, '2025-09-13 13:53:13.35248+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9e8b4ba9-71ec-4a7d-98b3-086e1c7c7980', '7fcb6505-0194-4575-899e-5f18d04eaf03', 'b', 'Realizar la maniobra de Boutakow.', false, '2025-09-13 13:53:13.352685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c79b8f12-5b7f-4a6f-9bd8-37492aa33fc9', '7fcb6505-0194-4575-899e-5f18d04eaf03', 'c', 'Utilizar un arnés de seguridad.', true, '2025-09-13 13:53:13.352907+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56224c7c-f9ec-4ff3-bdbd-cb9df8742add', '7fcb6505-0194-4575-899e-5f18d04eaf03', 'd', 'Instruir a la tripulación en el lanzamiento de ayudas.', false, '2025-09-13 13:53:13.353144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05bc8849-e574-49b3-8ab9-2aedad92935b', '25d8c235-38d0-41e6-8bab-c55cfd2d978f', 'a', 'Se permite la descarga en el mar de desechos de alimentos a menos de 12 millas marinas de la tierra más próxima cuando la embarcación no esté en ruta.', false, '2025-09-13 13:53:13.35368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f21b0935-8899-4e45-9df5-9f1ec72b1ad4', '25d8c235-38d0-41e6-8bab-c55cfd2d978f', 'b', 'Los desechos de alimentos podrán descargarse sin excepciones, incluso si están contaminados con otro tipo de basuras.', false, '2025-09-13 13:53:13.353908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16911064-279d-47ac-bdc4-bce48d9fe4dc', '25d8c235-38d0-41e6-8bab-c55cfd2d978f', 'c', 'La descarga en el mar de desechos de alimentos se realizará tan lejos como sea posible de la tierra más próxima, pero nunca a menos de 12 millas marinas de la tierra más próxima.', true, '2025-09-13 13:53:13.354132+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('682da92b-8bcd-4a36-9b39-ca156c1ac457', '25d8c235-38d0-41e6-8bab-c55cfd2d978f', 'd', 'Se permite la descarga en el mar de desechos de alimentos a menos de 12 millas marinas de la tierra más próxima si los desechos están desmenuzados o triturados de forma que pasen por cribas de abertura máxima de 15 mm.', false, '2025-09-13 13:53:13.35434+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88bd7c48-0cce-4e2a-9ae0-8637afbfe1c8', 'b3d4b002-9c8e-4fa5-92df-2091b1ddca2a', 'a', 'Si el buque que recibe la alerta de socorro no puede prestar auxilio, el patrón anotará en la carta de navegación la razón por la cual no acudió en auxilio de las personas en peligro.', true, '2025-09-13 13:53:13.354808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6144def2-4419-4494-b4c6-c4c77fd24942', 'b3d4b002-9c8e-4fa5-92df-2091b1ddca2a', 'b', 'Los patrones de las embarcaciones que embarquen a personas en peligro en el mar tratarán a esas personas con humanidad, conforme a la capacidad de la embarcación.', false, '2025-09-13 13:53:13.355028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4a7406c-1e88-4a69-b552-effb0f62b589', 'b3d4b002-9c8e-4fa5-92df-2091b1ddca2a', 'c', 'La obligación de prestar auxilio es independiente de la nacionalidad y de las circunstancias en que hayan sido encontradas.', false, '2025-09-13 13:53:13.355246+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a87723f6-debb-46f4-9f17-7d73596cf5e2', 'b3d4b002-9c8e-4fa5-92df-2091b1ddca2a', 'd', 'El patrón de la embarcación que se halle en peligro tiene derecho a requerir auxilio de uno o varios de los buques que mejor auxilio puedan prestarle.', false, '2025-09-13 13:53:13.355456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a0e161a-03b5-4096-8e90-fc3a53516bc0', '8fef2087-21d0-48dc-bb6b-e07c782217ec', 'a', 'Marca de Emergencia.', false, '2025-09-13 13:53:13.355916+00');
