INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0bbbcb25-dbc7-45d7-be3e-df4b769b6bf3', '5ab054b8-df4d-49c1-bfa0-379a47be5864', 'a', 'La marca de tope, formada por dos esferas superpuestas, es la característica diurna más importante de la marca.', true, '2025-09-13 13:53:13.359229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5dc0bfe4-0084-4873-9aab-1dcc5fed7909', '5ab054b8-df4d-49c1-bfa0-379a47be5864', 'b', 'Una aplicación importante de la Marca es la de señalizar un canal/área de interés para una clase particular de buque.', false, '2025-09-13 13:53:13.359446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('691e48a9-7223-463e-8722-42562ba40b5a', '5ab054b8-df4d-49c1-bfa0-379a47be5864', 'c', 'Si la Marca tuviese luz, sería amarilla.', false, '2025-09-13 13:53:13.359665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6bdd1654-b3f5-45a5-bef1-d46fbe648519', '5ab054b8-df4d-49c1-bfa0-379a47be5864', 'd', 'La Marca puede incluir el uso de un pictograma para indicar su finalidad, usando la simbología de la Organización Hidrográfica Internacional (OHI).', false, '2025-09-13 13:53:13.359878+00');
