INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a91a16b1-7f84-4d3a-9b33-48264b85ac6c', '6da0f5bc-10bd-4a7e-8e6e-0e6e6269c56f', 'b', 'El buque de propulsión mecánica en navegación.', false, '2025-09-13 13:53:13.361615+00');
