INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03682bb1-be34-4502-8c8b-94f4ccb7a818', '397dd909-c4df-4e98-a977-fe9570ccafc4', 'a', 'Cambiando el rumbo con anticipación suficiente y manteniendo de forma decidida siempre nuestra velocidad para quedar bien francos del otro buque.', false, '2025-09-13 13:53:13.362432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0616c5e5-b96b-4693-95c9-fcd5d9f6d994', '397dd909-c4df-4e98-a977-fe9570ccafc4', 'c', 'Manteniendo siempre nuestro rumbo y modificando con anticipación suficiente la velocidad de forma decidida para evitar el abordaje.', false, '2025-09-13 13:53:13.362862+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99a50393-28c6-4e07-b61e-1e6bf79e2d84', '397dd909-c4df-4e98-a977-fe9570ccafc4', 'd', 'Manteniendo de forma decidida nuestro rumbo y velocidad para no generar dudas de nuestras intenciones al otro buque.', false, '2025-09-13 13:53:13.363063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3ae8647-dc48-4658-9b6e-d2014b714527', 'b1b8542b-84b4-47cb-b091-a5e45ef8202d', 'a', 'Dirigir un haz de luz de nuestro proyector en la dirección del peligro, haciéndolo de forma que no moleste a otros buques.', true, '2025-09-13 13:53:13.364617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7cb55a4e-7f94-45e4-9648-8b37152c87e5', 'b1b8542b-84b4-47cb-b091-a5e45ef8202d', 'b', 'Utilizar luces intermitentes de gran intensidad.', false, '2025-09-13 13:53:13.364838+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('689a18f4-383d-4b85-bc73-5365de554571', 'b1b8542b-84b4-47cb-b091-a5e45ef8202d', 'c', 'Utilizar luces giratorias de gran intensidad, como las luces estroboscópicas.', false, '2025-09-13 13:53:13.365051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a231e7a4-2520-46a2-896b-6226a0b2a126', 'bf40bb4e-bda0-46ac-9e36-1606c4c7ced1', 'c', 'l= 35º 57,2’N; L= 005º 46,4’W.', true, '2025-09-13 13:53:13.536273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c33c46d-62a1-4ac4-bc70-d33f8f934d3c', 'b2fc7863-ab6f-4bb9-8419-446d03981328', 'd', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de babor.', false, '2025-09-13 13:53:13.36097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9f69a302-8f7f-48b4-ae2c-ca4c064dd91a', '397dd909-c4df-4e98-a977-fe9570ccafc4', 'b', 'Maniobrando con anticipación suficiente y de forma decidida para quedar bien francos del otro buque.', true, '2025-09-13 13:53:13.362637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0b0b5c3-562f-4b86-9f56-5b957a147123', 'b1b8542b-84b4-47cb-b091-a5e45ef8202d', 'd', 'Hacer cualquier señal acústica o luminosa de las autorizadas en cualquiera de las reglas del RIPA.', false, '2025-09-13 13:53:13.365253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c4fd711-04bd-44ed-a991-f530cc2a9bad', '57f0dc79-0ae8-44a8-bf13-e8c142f848a5', 'a', 'Cada uno caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:13.36569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d2aea83-57a1-4859-bbd2-6209b388ae2d', '57f0dc79-0ae8-44a8-bf13-e8c142f848a5', 'b', 'Cada uno caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:13.365906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31d1ca21-0180-4329-8178-deec5f318273', '57f0dc79-0ae8-44a8-bf13-e8c142f848a5', 'c', 'El yate caerá a babor y el buque de recreo a estribor.', false, '2025-09-13 13:53:13.366109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9963067f-92e7-48b1-84e8-33b19b18b4ab', '57f0dc79-0ae8-44a8-bf13-e8c142f848a5', 'd', 'El yate caerá a estribor y el buque de recreo a babor.', false, '2025-09-13 13:53:13.366322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c413f94-70ea-4e43-8c1e-7625d4fa2831', '90ef266b-fe34-41fe-94fb-e90fb6c6442b', 'a', 'En cualquier caso, usará la zona de navegación costera.', false, '2025-09-13 13:53:13.366753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5012f320-18c8-4303-84af-38a7f5f4128d', '90ef266b-fe34-41fe-94fb-e90fb6c6442b', 'b', 'Deberá utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', true, '2025-09-13 13:53:13.366971+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e1ca4d4-1f64-467d-9c06-b90e063aaca2', '90ef266b-fe34-41fe-94fb-e90fb6c6442b', 'c', 'Navegará exclusivamente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:13.367184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f28c967c-bae3-43db-8eba-64ace8925c83', '90ef266b-fe34-41fe-94fb-e90fb6c6442b', 'd', 'En caso de necesidad de cruce del dispositivo, deberá hacerlo siguiendo un rumbo que en la medida de lo posible forme una paralela a la dirección general de la corriente del tráfico.', false, '2025-09-13 13:53:13.367407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a36ccf48-5fa6-44ed-aaba-013097b81130', '48bedeb1-a17d-4408-856b-e088005b19cf', 'a', 'Luces de costado, una luz de alcance y dos luces todo horizonte en línea vertical, roja la superior y verde la inferior.', false, '2025-09-13 13:53:13.367832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0ee44303-3e9e-478e-bad4-143bedcd4156', '48bedeb1-a17d-4408-856b-e088005b19cf', 'b', 'Luces de costado y una luz de alcance en un farol combinado en el tope del palo o cerca de él, en el lugar más visible.', false, '2025-09-13 13:53:13.368042+00');
