INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afe1ea7e-b03b-40c4-be32-ed7e37180a10', '48bedeb1-a17d-4408-856b-e088005b19cf', 'd', 'Luces de costado y una luz de alcance.', false, '2025-09-13 13:53:13.368454+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab7efcf3-3de8-495f-b735-bd4af8ae9a32', '6d28f2d1-b2f4-458d-8bb3-a9047c594106', 'a', 'Un tope, las luces de costado, la luz de alcance, la luz de remolque y tres luces rojas todo horizonte, en el lugar más visible.', false, '2025-09-13 13:53:13.368879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b580ae23-cee9-4d8d-aa83-d79931a2ab3b', '6d28f2d1-b2f4-458d-8bb3-a9047c594106', 'b', 'Dos topes, las luces de costado, luz de alcance y, además, tres luces todo horizonte en línea vertical, en el lugar más visible. De estas últimas, la más elevada y la más baja de estas luces serán rojas y la luz central será blanca.', true, '2025-09-13 13:53:13.369088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc2b8479-4c17-496b-9337-d07a08f404a1', '6d28f2d1-b2f4-458d-8bb3-a9047c594106', 'd', 'Un tope, las luces de costado, la luz de alcance, y, además, dos luces todo horizonte en línea vertical, en el lugar más visible. De estas últimas, será roja la superior y blanca la inferior.', false, '2025-09-13 13:53:13.369504+00');
