INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d4ca03b-4d87-4000-9e45-133058e7e612', '85c7cb53-a6ca-4153-b9db-676b50ce34c2', 'c', 'Atracar la proa, desplazar la embarcación hacia atrás y desatracar la popa.', true, '2025-09-13 13:53:13.373578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bec37824-f416-49d4-aeca-5c155191e14d', 'a7356854-db7a-454b-b620-c24447f5922d', 'a', 'Lo primero que debemos hacer siempre es separar las embarcaciones involucradas en el abordaje lo antes posible.', false, '2025-09-13 13:53:13.374217+00');
