INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5e7d25ef-c2e0-4b5f-901d-5aab32764095', 'a7356854-db7a-454b-b620-c24447f5922d', 'c', 'En caso de que seamos responsables del mismo, estamos obligados a prestar asistencia legal al patrón de la otra embarcación involucrada en caso de que lo necesite.', false, '2025-09-13 13:53:13.374609+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74ad9b66-8b83-49e9-8ab9-4ad8afb2ea61', 'a7356854-db7a-454b-b620-c24447f5922d', 'd', 'La evaluación de las averías sufridas debe realizarse a la mayor brevedad posible.', true, '2025-09-13 13:53:13.374814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2820b010-0e05-46c6-91a3-21c808156747', '2401c8c3-b440-4224-bbea-2f8fbe2633be', 'a', 'Avisar a Salvamento Marítimo y esperar instrucciones sin tomar ninguna otra medida.', false, '2025-09-13 13:53:13.37523+00');
