INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05210339-7ef6-4701-872d-5edf322499a4', '39be8e81-6e87-420c-8f28-e8639fd8d6d2', 'b', 'Limera.', true, '2025-09-13 13:53:13.392141+00');
