INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac16d6d1-7db0-4fe4-a0ec-1124adabe714', '39be8e81-6e87-420c-8f28-e8639fd8d6d2', 'd', 'Pala.', false, '2025-09-13 13:53:13.392574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb267300-096e-44bb-9b13-172a67564615', '90e3da0b-afa2-451f-bfca-7ff9fdfe8337', 'a', 'La prolongación estructural de la quilla hacia la proa.', true, '2025-09-13 13:53:13.393011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f0f4d08-af17-4e77-b0d2-500a13974ff8', '90e3da0b-afa2-451f-bfca-7ff9fdfe8337', 'b', 'La prolongación estructural de la quilla hacia la popa.', false, '2025-09-13 13:53:13.393232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9fbaa56-cd29-4b95-a202-8995b4125cc5', '90e3da0b-afa2-451f-bfca-7ff9fdfe8337', 'c', 'La pieza estructural de la embarcación que va de proa a popa en su parte inferior.', false, '2025-09-13 13:53:13.393432+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8191a54c-6822-483a-9768-c5146bd94032', '90e3da0b-afa2-451f-bfca-7ff9fdfe8337', 'd', 'La pieza estructural curva que sale de la quilla y va por el costado.', false, '2025-09-13 13:53:13.393651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('422afae8-ac9f-4331-9b9c-1186332f1344', '6e177d75-055f-443b-b64b-efc054c6ffa8', 'b', 'La aleta es la parte de los costados entre el través y la proa.', true, '2025-09-13 13:53:13.394329+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c4591eb-6cac-4540-8735-f3b69adf2e79', '6e177d75-055f-443b-b64b-efc054c6ffa8', 'c', 'El través es la parte media, en sentido longitudinal, de cada uno de los costados.', false, '2025-09-13 13:53:13.394543+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cf04413-fa01-4a84-ba1f-fae9a08ed3c1', '6e177d75-055f-443b-b64b-efc054c6ffa8', 'd', 'La obra viva es la parte sumergida del casco.', false, '2025-09-13 13:53:13.394753+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13bc101c-1871-47c9-a731-752ae1b55df2', '054a117a-dde5-46eb-9169-42205eafcb4b', 'a', 'Enderezarse o ponerse vertical.', true, '2025-09-13 13:53:13.395242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('742b444a-d1c7-4179-98ba-ee9a62a54ace', '054a117a-dde5-46eb-9169-42205eafcb4b', 'b', 'Inclinarse sobre uno de sus costados.', false, '2025-09-13 13:53:13.395461+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('237fb6d7-5046-4599-90d7-f51e69d64ad6', '054a117a-dde5-46eb-9169-42205eafcb4b', 'c', 'Hundir la proa y levantar la popa.', false, '2025-09-13 13:53:13.395665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('01a69976-91fe-459e-ac2b-376b959eaab6', 'f9c2e8ca-fd60-4067-bd35-de69a6d6a5fd', 'a', 'Un noray es cada uno de los postes de madera o hierro que, asegurados a la cubierta en las proximidades de la proa, sirven para dar vuelta a los cabos cuando se fondea.', false, '2025-09-13 13:53:13.396288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f10b9fdc-0ce6-4f1c-b9c1-bc16c48e4412', '0bc1c21f-8dd1-46b2-a7cb-4def58db4745', 'b', 'Abrir las escotillas, puertas y tomas de aire, para facilitar su extinción.', true, '2025-09-13 13:53:13.426567+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad038ce8-3e6c-436b-9526-55b5542b6c11', '054a117a-dde5-46eb-9169-42205eafcb4b', 'd', 'Hundir la popa y levantar la proa.', false, '2025-09-13 13:53:13.395865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43b44bc6-85fc-4f50-859f-875bb5359638', '6e177d75-055f-443b-b64b-efc054c6ffa8', 'a', 'Los imbornales son aberturas en los costados que sirven para evacuar el agua de las zonas de cubierta.', false, '2025-09-13 13:53:13.394119+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('498d1e21-0b1d-4f60-87d3-b1c42720bd42', '16508ad5-0659-4bfd-97ab-5329255751be', 'd', 'La aplicación METEOYACHT publicada por el Servicio Hidrográfico Naval.', false, '2025-09-13 13:53:13.381403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aab5854c-e698-4c67-8714-c9a7b0c2b4ee', '69fc40fe-c628-4146-8967-696156f44e23', 'd', 'El desvío de la aguja magnética.', true, '2025-09-13 13:53:13.386745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca464054-7a60-48db-a7a4-4ccbc4cc5392', 'f9c2e8ca-fd60-4067-bd35-de69a6d6a5fd', 'b', 'El chicote es un palo con punta y gancho metálico en un extremo que sirve para tomarse o abrirse al atracar o desatracar la embarcación.', false, '2025-09-13 13:53:13.396496+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d5a9c77b-61fe-44fd-aaee-d1e2b51d0050', 'f9c2e8ca-fd60-4067-bd35-de69a6d6a5fd', 'c', 'Un muerto es un bloque de cemento o ancla de gran peso depositado en el fondo que, unido por un orinque a la superficie, permite anclar una embarcación.', true, '2025-09-13 13:53:13.396731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5023f1f-71f0-4e4b-85b1-f2ed9a64328a', 'f9c2e8ca-fd60-4067-bd35-de69a6d6a5fd', 'd', 'El As de guía permite unir dos cabos de la misma mena que vayan a trabajar en tensión.', false, '2025-09-13 13:53:13.396937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5798f36c-922e-46f3-b801-06b5a2b79b4b', '4344cd6b-5557-4f50-8220-6b3b8e26d1d7', 'a', 'Se estudiará la carta y el derrotero para elegir un lugar protegido y un tenedero de fondo rocoso.', false, '2025-09-13 13:53:13.397393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7052cd22-1c48-4ac7-9b91-5dd46eea2460', '4344cd6b-5557-4f50-8220-6b3b8e26d1d7', 'd', 'En el momento del fondeo aumentaremos la arrancada dando marcha avante y largaremos cadena, para que esta se extienda correctamente por el fondo.', false, '2025-09-13 13:53:13.398435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ac856c6d-62bb-4d4b-b17e-7795720aa3c7', '43a0079f-dc1a-44b3-8300-fdce458574fd', 'a', 'Se deben almacenar a bordo en lugar seco.', false, '2025-09-13 13:53:13.398935+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cdb2c9f-c223-427a-a2a9-d2ea2a9a33f5', '43a0079f-dc1a-44b3-8300-fdce458574fd', 'b', 'Se debe respetar escrupulosamente sus fechas de caducidad.', false, '2025-09-13 13:53:13.399157+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80784a98-bcc7-4771-a10a-c9dd2de34a04', '43a0079f-dc1a-44b3-8300-fdce458574fd', 'c', 'Si pierde una, informe a Salvamento Marítimo, alguien puede encontrarla y activar una alarma.', true, '2025-09-13 13:53:13.399474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c71af78e-c84a-4603-9e13-d9707ed51c9c', '43a0079f-dc1a-44b3-8300-fdce458574fd', 'd', 'Se deben leer y aprender de memoria las instrucciones de uso.', false, '2025-09-13 13:53:13.399702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55780324-0b9e-4d76-a67c-132caa9f5853', '16521d0e-cbb1-45f0-9e52-1926bcabef23', 'a', 'Originar una inducción magnética peligrosa en el reflector radar pasivo.', false, '2025-09-13 13:53:13.401237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60631f61-5e97-49c2-93bd-30be36dafb9e', '16521d0e-cbb1-45f0-9e52-1926bcabef23', 'b', 'Disminuir la temperatura de ignición de los combustibles a bordo.', false, '2025-09-13 13:53:13.401444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bdf3542-98f9-49bb-b1fa-4ae7650462a2', '16521d0e-cbb1-45f0-9e52-1926bcabef23', 'c', 'Influir en la aguja náutica.', true, '2025-09-13 13:53:13.401655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0c0b3ec-431d-4b38-b2cf-17fe8703784c', '16521d0e-cbb1-45f0-9e52-1926bcabef23', 'd', 'Producir un fenómeno conocido como “rayo verde”.', false, '2025-09-13 13:53:13.401872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ac596ec-04cd-4b0f-9dc4-406144cef99c', '624b2f6f-f1dc-46e4-b972-692289ef51e2', 'b', 'Llevar la mar por la aleta con una velocidad prudencial para evitar los movimientos de cabeceo.', false, '2025-09-13 13:53:13.402539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3bd2081-53f7-47c9-80b6-0c3d860a9e1e', '624b2f6f-f1dc-46e4-b972-692289ef51e2', 'c', 'Buscar refugio de forma inmediata.', false, '2025-09-13 13:53:13.40275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f47f8004-9a11-4768-bc0a-7da8dcdf70f5', '624b2f6f-f1dc-46e4-b972-692289ef51e2', 'd', 'Maniobrar para ponerse “a son de mar”.', false, '2025-09-13 13:53:13.403072+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('902854b1-0572-40c6-9ee6-e8ee1cd6b762', '57739ce9-289e-40d1-a00e-2eb09d5a11cd', 'a', '40 metros.', false, '2025-09-13 13:53:13.403571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40277dd0-c0da-4e5c-ad76-3524ccd55e30', '57739ce9-289e-40d1-a00e-2eb09d5a11cd', 'b', '200 metros.', false, '2025-09-13 13:53:13.403801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff2a6f7c-4caf-46ff-9b37-e582c96ae8c5', '57739ce9-289e-40d1-a00e-2eb09d5a11cd', 'c', '25 metros.', false, '2025-09-13 13:53:13.40407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6506f748-3b98-4e9b-987e-62e8c5f7238a', '57739ce9-289e-40d1-a00e-2eb09d5a11cd', 'd', '50 metros.', true, '2025-09-13 13:53:13.404291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2fdc0ce2-d745-411f-9fb4-6d5a31b48386', '1f2f7865-fd17-4c80-8e3a-22b644c270be', 'a', 'Un incidente o accidente que afecte a la seguridad de la embarcación tales como abordajes, varadas o daños.', false, '2025-09-13 13:53:13.404744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c9f2771-be5f-4c14-930f-e862a856cc9c', '1f2f7865-fd17-4c80-8e3a-22b644c270be', 'b', 'La decisión de fondear en calas o lugares de baño, siempre que no estén balizados y no pongan en peligro la seguridad de la navegación.', true, '2025-09-13 13:53:13.404966+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eaff11c2-4e67-49a0-bb3a-4329812d51fd', '1f2f7865-fd17-4c80-8e3a-22b644c270be', 'd', 'Un incidente o accidente que comprometa la seguridad de la navegación o que puedan afectar a la maniobrabilidad.', false, '2025-09-13 13:53:13.405387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1726a26a-12aa-4c29-a1fd-a2b08a39c84e', '8d2cb614-59db-4936-bf66-52716dc378c0', 'a', 'Un doble cilindro amarillo.', false, '2025-09-13 13:53:13.4058+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b9e6592-f310-4827-9e0b-d1851c34509d', '8d2cb614-59db-4936-bf66-52716dc378c0', 'b', 'Un doble cilindro negro.', false, '2025-09-13 13:53:13.406001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('742d885e-2a94-48c6-9c0d-fa411458e2b2', '8d2cb614-59db-4936-bf66-52716dc378c0', 'c', 'Un doble cono amarillo.', false, '2025-09-13 13:53:13.406197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77a5510b-24f5-4bbc-b4d1-1c1db64e65bd', '8d2cb614-59db-4936-bf66-52716dc378c0', 'd', 'Un doble cono negro.', true, '2025-09-13 13:53:13.406397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57a9502b-d9b7-4479-a1f8-6db2ba56073c', '799e3af6-bb11-4318-9ea2-d1334dc312fd', 'a', 'Las Marcas de peligro aislado nunca tendrán forma de castillete o espeque.', true, '2025-09-13 13:53:13.406866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9d66c5b-becf-49e9-b43c-73f325ed7967', '799e3af6-bb11-4318-9ea2-d1334dc312fd', 'b', 'Siempre, estarán pintadas de color negro con una o más bandas anchas horizontales rojas.', false, '2025-09-13 13:53:13.407087+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f4c8162-92e9-4714-976b-e52e8ea3c602', '799e3af6-bb11-4318-9ea2-d1334dc312fd', 'd', 'Su luz tendrá ritmo de Grupo de dos destellos GpD (2) para distinguirlas de las Marcas', false, '2025-09-13 13:53:13.407534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('138728df-71dd-42c0-935a-754f90bce1d7', '3db63ea7-ae47-456e-92c4-4a27632f3451', 'a', 'Indican el lugar donde se encuentran las aguas más seguras, en relación con un punto de interés.', false, '2025-09-13 13:53:13.407992+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('151238a7-3804-4680-98b2-47d24b7e8eac', '3db63ea7-ae47-456e-92c4-4a27632f3451', 'b', 'La luz, si tiene, es de color blanco.', true, '2025-09-13 13:53:13.408206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a683a9e-ad25-47d9-a8b6-307d6575115d', '3db63ea7-ae47-456e-92c4-4a27632f3451', 'c', 'Pueden señalizar límites de las áreas de fondeo.', false, '2025-09-13 13:53:13.408405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92058414-4e36-47c3-9642-835179fcebee', '3db63ea7-ae47-456e-92c4-4a27632f3451', 'd', 'Pueden emplearse para indicar el lado seguro por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:13.408595+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('923e3ed6-2533-4c67-830e-dfa15e8e9cca', '0acd4f07-2954-41bd-9ef7-7864fd9be873', 'a', 'Una única esfera roja.', false, '2025-09-13 13:53:13.409071+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1722adf2-aaec-4a16-a49f-63ad35b540e0', '0acd4f07-2954-41bd-9ef7-7864fd9be873', 'b', 'De color amarillo sobre negro.', false, '2025-09-13 13:53:13.409286+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75dad3ce-6514-4423-a95d-9044ba42aad5', '0acd4f07-2954-41bd-9ef7-7864fd9be873', 'c', 'Un aspa amarilla en forma de "X".', true, '2025-09-13 13:53:13.409495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62e6ccab-33e9-40dc-a353-02ba026f08af', '0acd4f07-2954-41bd-9ef7-7864fd9be873', 'd', 'Dos esferas negras, una encima de la otra.', false, '2025-09-13 13:53:13.409712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e3ea6763-fece-4670-9ceb-dae01eaf52df', '92dfa971-d4cb-43f9-a097-460767b119ab', 'a', 'Dejaremos la “Marca de canal principal a estribor” por nuestro costado de estribor.', false, '2025-09-13 13:53:13.410183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('45340203-c7c1-4c35-ad6b-eda93fe3d5ff', '92dfa971-d4cb-43f9-a097-460767b119ab', 'b', 'Dejaremos la “Marca de canal principal a estribor” por nuestro costado de babor.', true, '2025-09-13 13:53:13.410398+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d23094c2-100d-475e-958d-0b2295590e1f', '92dfa971-d4cb-43f9-a097-460767b119ab', 'c', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de estribor.', false, '2025-09-13 13:53:13.41062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e77e7828-e8f2-4291-bef8-165091eb86c4', 'edcba08c-4b1d-4267-851e-7cf113d97b8b', 'a', 'Únicamente los buques de vela.', false, '2025-09-13 13:53:13.411289+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e6ca003-9d3a-48d5-a2c8-8108accb47d9', 'edcba08c-4b1d-4267-851e-7cf113d97b8b', 'b', 'Los buques de eslora inferior a 24 metros y los buques de vela.', false, '2025-09-13 13:53:13.411512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bba45499-4be6-4fcc-bff3-665ec691d001', 'edcba08c-4b1d-4267-851e-7cf113d97b8b', 'c', 'Los buques de eslora inferior a 20 metros, los buques de vela y los buques dedicados a la pesca.', true, '2025-09-13 13:53:13.411721+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73a0e080-13f5-4974-b2a0-ecc82ec6c4a8', 'edcba08c-4b1d-4267-851e-7cf113d97b8b', 'd', 'Únicamente los buques dedicados a la pesca y los buques de vela.', false, '2025-09-13 13:53:13.411943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50372ec1-c521-467c-bf44-37a6c261680b', '2d9c24a1-d676-4d1e-aa54-05335c934a35', 'a', 'Un pito.', true, '2025-09-13 13:53:13.412415+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6abe42b-b9c6-4075-92d5-dd0a1e929e52', 'f95342a8-836f-430f-8410-8efd20a3b440', 'd', 'Ra = 074º; HRB: 15:55.', false, '2025-09-13 13:53:13.572485+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dc6fc377-2419-4ebc-b023-b88f61729a53', '4344cd6b-5557-4f50-8220-6b3b8e26d1d7', 'c', 'Se comprobará que no haya obstáculos en un círculo de borneo de radio igual a la eslora de la embarcación.', false, '2025-09-13 13:53:13.398191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0b48415-92ef-46bc-aea4-499d4af664f5', '624b2f6f-f1dc-46e4-b972-692289ef51e2', 'a', 'Llevar la mar por la amura con poca arrancada, pero la suficiente para permitir el gobierno de la embarcación.', true, '2025-09-13 13:53:13.402321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3a1df010-4c37-4bc5-aa42-cff1b67e7a91', '1f2f7865-fd17-4c80-8e3a-22b644c270be', 'c', 'La visualización de cualquier mancha de materiales contaminantes o contenedores a la deriva en el mar.', false, '2025-09-13 13:53:13.405184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cd3204e-1c28-42a0-a71b-9061adf97d1b', '799e3af6-bb11-4318-9ea2-d1334dc312fd', 'c', 'Su marca de tope estará formada por dos esferas negras superpuestas.', false, '2025-09-13 13:53:13.407315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c33338b0-1139-41f9-87ed-ee3059295087', '92dfa971-d4cb-43f9-a097-460767b119ab', 'd', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de babor.', false, '2025-09-13 13:53:13.410834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e334daa4-5f3a-4650-9108-8bd7ce5e4ed3', '4344cd6b-5557-4f50-8220-6b3b8e26d1d7', 'b', 'La aproximación al lugar de fondeo se hará a la mínima velocidad de gobierno y con el viento por la proa.', true, '2025-09-13 13:53:13.397611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1695d15d-564c-4760-ae96-b831c80d9b0d', '2d9c24a1-d676-4d1e-aa54-05335c934a35', 'b', 'No tendremos obligación de llevar ningún dispositivo de señales acuáticas, ya que solamente son obligatorios para buques cuya eslora es mayor de 12 metros.', false, '2025-09-13 13:53:13.412663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f36f4468-cd29-4cc7-8eee-ebc18da35773', '2d9c24a1-d676-4d1e-aa54-05335c934a35', 'c', 'No tendremos obligación de llevar los dispositivos de señales acústicas prescritos de esta Regla, pero debemos ir dotados de otros medios para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:13.412874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fe675aa-130b-4451-8c7f-0888aa8235e3', '2d9c24a1-d676-4d1e-aa54-05335c934a35', 'd', 'Una campana y un pito.', false, '2025-09-13 13:53:13.413077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('814291d6-9a74-49b2-b119-7cd2e1ce60cc', '3f1c94ef-6696-41e3-9d99-d877c1dd1cec', 'a', 'Deberá mantener un resguardo mínimo de 1 milla con el buque alcanzado.', false, '2025-09-13 13:53:13.41351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('863c1f70-0241-4680-b5fe-83ea0114437a', '3f1c94ef-6696-41e3-9d99-d877c1dd1cec', 'b', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:13.413719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9fef3a9a-0ee7-4602-a195-7cc605d362c1', '3f1c94ef-6696-41e3-9d99-d877c1dd1cec', 'c', 'Virará claramente hacia cualquiera de las bandas para indicar su intención de adelantar.', false, '2025-09-13 13:53:13.413939+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fd76375-a79f-4b1a-8725-24b0e51979aa', '3f1c94ef-6696-41e3-9d99-d877c1dd1cec', 'd', 'No podrá rebasarlo si la velocidad del buque alcanzado es superior a 12 nudos.', false, '2025-09-13 13:53:13.414148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d8321515-96d2-4b52-ae1d-914f911433b7', '17343efc-bad8-45d0-9f5f-43765f4c97cc', 'a', 'Con una frecuencia de 120 o más centelleos por minuto, a intervalos regulares.', true, '2025-09-13 13:53:13.414594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('742862dc-cb04-402e-807f-b70ba31323ea', '17343efc-bad8-45d0-9f5f-43765f4c97cc', 'b', 'Con una frecuencia de 60 o menos centelleos por minuto, a intervalos regulares.', false, '2025-09-13 13:53:13.414822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bce0c17-5cee-4264-8ef1-c3bd12d8ab46', '17343efc-bad8-45d0-9f5f-43765f4c97cc', 'c', 'Con una duración cada centelleo de 1 segundo aproximadamente, con un intervalo entre centelleos de 1 segundo aproximadamente.', false, '2025-09-13 13:53:13.415034+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30835a7c-6eeb-47f0-86c7-7e751d5fb17b', '17343efc-bad8-45d0-9f5f-43765f4c97cc', 'd', 'Con una duración cada centelleo de medio segundo aproximadamente, a intervalos irregulares.', false, '2025-09-13 13:53:13.415254+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('850ca30c-0c72-49a7-b935-3a678b4cf3fd', 'bc354ffb-4ddd-4efc-9307-ccbaa5e9ae66', 'b', 'Remolcando a otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.415891+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0b10c2d-89e3-41f8-b050-250b7776049f', 'bc354ffb-4ddd-4efc-9307-ccbaa5e9ae66', 'c', 'Remolcando a otro, cuando la longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:13.416103+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53975d40-bd21-41f9-aa88-acaf2b5a8bae', 'bc354ffb-4ddd-4efc-9307-ccbaa5e9ae66', 'd', 'Remolcado por otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.416293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6950c1d-e26b-4236-b799-c2f5c6e0fece', '74d0eb0a-93b4-463f-9fe1-c0f39df7ad2c', 'b', 'Blanca todo horizonte visible a una distancia mínima de 5 millas.', true, '2025-09-13 13:53:13.416964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('829a3077-c572-491e-a869-45df9f5d7dcb', '74d0eb0a-93b4-463f-9fe1-c0f39df7ad2c', 'c', 'Amarilla, que muestra su luz en un arco de horizonte de 225 grados, de forma que sea visible desde la proa hasta 22,5 grados a popa del través de cada costado, visible a una distancia máxima de 5 millas.', false, '2025-09-13 13:53:13.417164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c4169c4-5622-411a-9eba-5deddddb5c20', '74d0eb0a-93b4-463f-9fe1-c0f39df7ad2c', 'd', 'Amarilla todo horizonte visible a una distancia mínima de 3 millas.', false, '2025-09-13 13:53:13.417376+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f954820-778b-494e-b979-65ba9be8edd8', 'c839256c-aa10-4c3f-a62c-16bcaceb4c5a', 'a', 'Reducirá su velocidad hasta la mínima de gobierno.', false, '2025-09-13 13:53:13.417815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('53eadd9c-144f-4a98-9c9b-8b80c18c6e35', 'c839256c-aa10-4c3f-a62c-16bcaceb4c5a', 'b', 'Suprimirá su arrancada, si fuese necesario.', false, '2025-09-13 13:53:13.418033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d450540f-c111-448b-831f-750be0b4a4f7', 'c839256c-aa10-4c3f-a62c-16bcaceb4c5a', 'c', 'Navegará con extremada precaución hasta que desaparezca el peligro de abordaje.', false, '2025-09-13 13:53:13.418233+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30645ad5-6a29-4286-b715-7d332122aafe', 'c839256c-aa10-4c3f-a62c-16bcaceb4c5a', 'd', 'Aumentará su velocidad hasta la máxima de gobierno para minimizar la aproximación excesiva y en ningún caso se quedará sin arrancada.', true, '2025-09-13 13:53:13.418459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c00b273e-90b0-4d38-95e0-9b9a510ceeb4', 'f75cb3e9-5aae-44fb-bd1c-dabafa9b0295', 'a', 'Buque sin gobierno.', true, '2025-09-13 13:53:13.418894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c85972ba-cc72-41cc-824b-e1c0f3186fe7', 'f75cb3e9-5aae-44fb-bd1c-dabafa9b0295', 'b', 'Buque de pesca.', false, '2025-09-13 13:53:13.419113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66dfb00b-8e8f-4dea-a735-a7e9c1a7af77', 'f75cb3e9-5aae-44fb-bd1c-dabafa9b0295', 'c', 'Buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.419332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9a47942-49f7-4de0-bf7d-e6b395bd260f', 'f75cb3e9-5aae-44fb-bd1c-dabafa9b0295', 'd', 'Buque restringido por su calado.', false, '2025-09-13 13:53:13.419535+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('649f37fe-abf5-4448-bb77-5a7118857bba', '2a5b5d41-72a6-4921-8ae2-9812bdf25a80', 'a', 'Uno de propulsión mecánica de 60 metros de eslora con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.419964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5736830e-85a7-4935-bf7c-ec2a34aefdc3', '2a5b5d41-72a6-4921-8ae2-9812bdf25a80', 'b', 'Uno de propulsión mecánica de más de 50 metros sin gobierno, pero con arrancada.', false, '2025-09-13 13:53:13.42017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b2b0671-6ac4-46fe-9d16-3b3386ff331a', '2a5b5d41-72a6-4921-8ae2-9812bdf25a80', 'c', 'Un pesquero no de arrastre faenando.', false, '2025-09-13 13:53:13.420385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c640fa38-5a10-4422-9474-44cffcd438e4', '2a5b5d41-72a6-4921-8ae2-9812bdf25a80', 'd', 'Uno de propulsión mecánica de 40 metros de eslora restringido por su calado.', true, '2025-09-13 13:53:13.420591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bcc45bad-9e28-48b6-8fb7-a4d4c9dc0c56', '264c33be-fa10-48c0-8395-3fe085e9a73d', 'a', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse a un buque de pequeño tamaño a mucha distancia.', false, '2025-09-13 13:53:13.421011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('80a85492-6a45-4683-8007-770f1e288866', '264c33be-fa10-48c0-8395-3fe085e9a73d', 'b', 'Que existe el riesgo, si la demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:13.421214+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d554d3e-f327-4ba6-92bd-a2a6d2934612', '264c33be-fa10-48c0-8395-3fe085e9a73d', 'd', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse en la lejanía un buque de pequeño tamaño a poca velocidad. Maniobra y navegación.', false, '2025-09-13 13:53:13.421639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5d24aa1f-adde-4eb8-b19b-f229b78db974', 'ea6ad522-952a-49b9-91b9-df089d35d54b', 'a', 'Adujar.', true, '2025-09-13 13:53:13.422062+00');
