INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b27ddddb-46fe-4be2-bb08-49d6da4ce752', '3c357059-4e9b-4300-bda4-168a6237744f', 'c', 'Nunca es de utilidad trasladar pesos para cambiar la escora.', false, '2025-09-13 13:53:13.424666+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c95672fd-ab42-414a-a403-bffb168c854c', '3c357059-4e9b-4300-bda4-168a6237744f', 'd', 'Siempre será necesario el servicio de un remolcador, de manera que deberemos ponernos en contacto con quien preste dicho servicio.', false, '2025-09-13 13:53:13.424882+00');
