INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0eacf959-b883-4490-acd7-6a3535294148', 'cb0543d0-0fc2-42d9-bc41-d7448fdd9cb0', 'd', 'Evacuar inmediatamente al accidentado a un centro hospitalario para su tratamiento.', true, '2025-09-13 13:53:13.425919+00');
