INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73aaeea3-e123-49a3-8964-df7095a53129', '9de9bb33-e6df-494a-be5b-f43c536c5fce', 'c', 'Impide que entre el agua en la embarcación.', false, '2025-09-13 13:53:13.444216+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3d18f78-e2e4-48f9-95ce-6bee72cd3688', '9de9bb33-e6df-494a-be5b-f43c536c5fce', 'd', 'Atraviesa el casco de la embarcación.', false, '2025-09-13 13:53:13.444412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c5b6bc0-368c-4df0-8e5d-dfec10dd9b39', '68eeae5d-f075-4cf6-9d86-68c51f33c0f6', 'a', 'Divide la embarcación en dos mitades transversalmente, la de popa y la de proa.', false, '2025-09-13 13:53:13.444851+00');
