INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3b757f2-27b5-41d0-a9f7-ec39779c3808', '68eeae5d-f075-4cf6-9d86-68c51f33c0f6', 'c', 'Divide la embarcación en dos mitades longitudinalmente, la de babor y la de estribor.', true, '2025-09-13 13:53:13.445253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('753b27b1-822a-4ff5-bdfd-35599379f771', 'fa43ed9e-6106-47e6-878f-9eab69c530b6', 'a', 'Un doble cilindro amarillo.', false, '2025-09-13 13:53:13.587718+00');
