INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4db9f0e-aca0-4270-8aad-dc9a700f7d89', 'f5bd48b3-eba2-4745-b17b-f6b8d67eadf4', 'a', 'De 8 a 10 metros.', false, '2025-09-13 13:53:13.44586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47ca9aaa-e661-41cb-84ed-1178bc2fc775', 'f5bd48b3-eba2-4745-b17b-f6b8d67eadf4', 'b', 'De 10 a 18 metros.', false, '2025-09-13 13:53:13.446065+00');
