INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec8303f5-c44f-4b97-b596-5fbfba6167d7', 'f5bd48b3-eba2-4745-b17b-f6b8d67eadf4', 'd', 'De 48 a 56 metros.', false, '2025-09-13 13:53:13.446493+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bbfe697-14a8-4734-b402-d192de6becfe', '5259033b-75d2-4e00-8812-4fd514feb3b6', 'a', 'El nudo llano se utiliza para afirmar un cabo con rapidez a un pasamanos, poste o argolla.', false, '2025-09-13 13:53:13.44694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a11fb4b3-2475-49d0-a100-367de1b2dd45', '5259033b-75d2-4e00-8812-4fd514feb3b6', 'b', 'La gaza es la curvatura que forma el cabo cuando este no trabaja o cuando se hace un nudo.', false, '2025-09-13 13:53:13.447134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0fc3063-184b-40ce-b80c-2ba9d740a93a', '5259033b-75d2-4e00-8812-4fd514feb3b6', 'c', 'La cornamusa es una pieza de metal o madera que, encorvada en sus extremos y fija por su punto medio, sirve para amarrar los cabos.', true, '2025-09-13 13:53:13.447346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('61eac215-9dfe-4392-ad0f-3dfa57db0e1e', '5259033b-75d2-4e00-8812-4fd514feb3b6', 'd', 'El chicote es un bucle en el cabo que queda al anudarlo.', false, '2025-09-13 13:53:13.447539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('57276765-b70b-4d8f-a090-0a6404af21c1', 'b085e8bd-ef69-450a-b037-51a707510e52', 'a', 'Llevar puesto un chaleco salvavidas.', false, '2025-09-13 13:53:13.447951+00');
