INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a0c393c-87d1-47c1-8be1-766f7dab6a89', 'b085e8bd-ef69-450a-b037-51a707510e52', 'c', 'Utilizar un arnés de seguridad.', true, '2025-09-13 13:53:13.448388+00');
