INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11f5db8c-4958-4b61-9210-b46a148566fa', 'd58b35c4-937c-49da-b3b6-e1cc02db7f94', 'a', 'Son elementos de seguridad en el caso de persona al agua.', false, '2025-09-13 13:53:13.449022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f5f5a0d-e7ea-4f34-b6d5-8f32be5eeefa', 'd58b35c4-937c-49da-b3b6-e1cc02db7f94', 'c', 'El nombre de la embarcación debe figurar en ellos.', false, '2025-09-13 13:53:13.449417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d5190fc-5527-4f7e-9510-a7f85d79aae0', 'd58b35c4-937c-49da-b3b6-e1cc02db7f94', 'd', 'Si pierde uno durante la navegación debe informar a Salvamento Marítimo.', false, '2025-09-13 13:53:13.449613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f19489dd-b4c8-4939-b636-accb2ebfb044', '634ef56c-49be-4d2d-bf99-6bcd20067ac8', 'a', 'Reducir la velocidad.', false, '2025-09-13 13:53:13.450026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5942a6be-6d49-41c3-a5c7-6f039d621343', '634ef56c-49be-4d2d-bf99-6bcd20067ac8', 'b', 'Realizar la secuencia de señales fónicas reglamentarias.', false, '2025-09-13 13:53:13.450232+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ec79db8-a012-4931-bf1e-29205111c53d', '634ef56c-49be-4d2d-bf99-6bcd20067ac8', 'c', 'Reforzar la vigilancia.', false, '2025-09-13 13:53:13.450435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43d42d97-3368-4f0c-bcc8-5b2989858e39', '634ef56c-49be-4d2d-bf99-6bcd20067ac8', 'd', 'Navegar lo más próximos a la costa.', true, '2025-09-13 13:53:13.45064+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02e2a8e5-9e4b-44c6-a3e8-fefe6ff9df60', 'f9186ce2-7f57-48b6-b51b-eaa2419e0a39', 'a', 'El centro geométrico y la cota cero de la quilla de la embarcación.', false, '2025-09-13 13:53:13.451054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6778bf24-de69-48ee-baea-db13556659a0', 'f9186ce2-7f57-48b6-b51b-eaa2419e0a39', 'b', 'El centro de gravedad y el centro de carena de la embarcación.', true, '2025-09-13 13:53:13.451251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a68e7ed-6306-4ae6-a5b9-0ab871629eb3', 'f9186ce2-7f57-48b6-b51b-eaa2419e0a39', 'c', 'El centro de la flotación y el centro geométrico de la embarcación.', false, '2025-09-13 13:53:13.451457+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f212003c-ed24-440e-b3c6-c6163284f500', 'f9186ce2-7f57-48b6-b51b-eaa2419e0a39', 'd', 'El centro de gravedad de los pesos por encima de la cubierta y el centro de carena de la', false, '2025-09-13 13:53:13.45164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fff56959-e883-49c8-b610-04b25ca2b0be', '87e86341-0ece-4a53-876b-670bfc42a844', 'a', 'Si el buque que recibe la alerta de socorro no puede prestar auxilio, el patrón anotará en la carta de navegación la razón por la cual no acudió en auxilio de las personas en peligro.', true, '2025-09-13 13:53:13.452082+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9010993-ccd5-4bad-b443-cfb415fd6dd1', '87e86341-0ece-4a53-876b-670bfc42a844', 'b', 'Los patrones de las embarcaciones que embarquen a personas en peligro en el mar tratarán a esas personas con humanidad, conforme a la capacidad de la embarcación.', false, '2025-09-13 13:53:13.452319+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41df4a82-9b9f-4a4b-a2a2-630c1c75485e', '87e86341-0ece-4a53-876b-670bfc42a844', 'c', 'La obligación de prestar auxilio es independiente de la nacionalidad y de las circunstancias en que hayan sido encontradas.', false, '2025-09-13 13:53:13.452507+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('20ab0502-a88c-4352-a53e-600f7ef9ac37', '87e86341-0ece-4a53-876b-670bfc42a844', 'd', 'El patrón de la embarcación que se halle en peligro tiene derecho a requerir auxilio de uno o varios de los buques que mejor auxilio puedan prestarle.', false, '2025-09-13 13:53:13.452687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a0b3d5e-01bb-4a9e-806f-e8752737f6d1', 'b4340522-5605-4bbd-a33c-79087a87b228', 'a', 'Se permite la descarga en el mar de desechos de alimentos a menos de 12 millas marinas de la tierra más próxima cuando la embarcación no esté en ruta.', false, '2025-09-13 13:53:13.453183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65de1d64-4e30-4b58-ba70-b147bfeb31ce', 'b4340522-5605-4bbd-a33c-79087a87b228', 'b', 'Los desechos de alimentos podrán descargarse sin excepciones, incluso si están contaminados con otro tipo de basuras.', false, '2025-09-13 13:53:13.453392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f368312-4fe1-4d8a-831b-fffe24bf7d60', 'b4340522-5605-4bbd-a33c-79087a87b228', 'c', 'La descarga en el mar de desechos de alimentos se realizará tan lejos como sea posible de la tierra más próxima, pero nunca a menos de 12 millas marinas de la tierra más próxima.', true, '2025-09-13 13:53:13.453586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0712f763-9cf7-4ef1-bbb6-951ae8350d84', 'b4340522-5605-4bbd-a33c-79087a87b228', 'd', 'Se permite la descarga en el mar de desechos de alimentos a menos de 12 millas marinas de la tierra más próxima si los desechos están desmenuzados o triturados de forma que pasen por cribas de abertura máxima de 15 mm.', false, '2025-09-13 13:53:13.453814+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58a21159-ac30-42ff-8ac5-851229c53535', '43ee8a1c-1e0a-4c2c-aa9e-0539693f136a', 'a', 'La marca de tope, formada por dos esferas superpuestas, es la característica diurna más importante de la marca.', true, '2025-09-13 13:53:13.45427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93a68b6c-9dae-4c09-a910-b65719b7a8e0', '43ee8a1c-1e0a-4c2c-aa9e-0539693f136a', 'b', 'Una aplicación importante de la Marca es la de señalizar un canal/área de interés para una clase particular de buque.', false, '2025-09-13 13:53:13.454479+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('681822b5-6306-4df6-be08-0f697945ea15', '43ee8a1c-1e0a-4c2c-aa9e-0539693f136a', 'c', 'Si la Marca tuviese luz, sería amarilla.', false, '2025-09-13 13:53:13.454711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2c2ab3b-d36e-452f-8996-23453c198354', '43ee8a1c-1e0a-4c2c-aa9e-0539693f136a', 'd', 'La Marca puede incluir el uso de un pictograma para indicar su finalidad, usando la simbología de la Organización Hidrográfica Internacional (OHI).', false, '2025-09-13 13:53:13.454945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd8e43f4-b327-48ec-9efc-3211535cb481', 'cdc043bb-230b-4f5e-a38b-4adb5eb3cf51', 'a', 'Dejaremos la “Marca de canal principal a estribor” por nuestro costado de estribor.', true, '2025-09-13 13:53:13.455371+00');
