INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9a6d57c-20ec-431e-8ced-c9e82e1964f3', 'cdc043bb-230b-4f5e-a38b-4adb5eb3cf51', 'c', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de estribor.', false, '2025-09-13 13:53:13.455771+00');
