INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0947e4e9-b3d1-4484-96a3-88adef46ca99', 'af4cd8f9-0e73-4fa6-b0a8-514d7b1d9f00', 'b', 'Los límites de un área de fondeo.', false, '2025-09-13 13:53:13.458836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e41e0295-8261-4674-a29c-3d162ece1740', 'af4cd8f9-0e73-4fa6-b0a8-514d7b1d9f00', 'c', 'Las aguas más seguras de la zona en relación con un punto de interés.', true, '2025-09-13 13:53:13.459046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1e15c2a-78f1-4336-a445-0199934163c5', 'de2d1bc8-1cae-4e20-a473-a5506a6d7876', 'a', 'En cualquier caso, usará la zona de navegación costera.', false, '2025-09-13 13:53:13.459648+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('840a107d-7325-4759-94b9-07b9cf41e965', '8edc851c-204c-49bc-ac2f-d2ae8ce73fe6', 'b', 'La luz, si tiene, es de color blanco.', true, '2025-09-13 13:53:13.503707+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('243956f1-8593-4a4a-bc79-8f840a8eff32', 'af4cd8f9-0e73-4fa6-b0a8-514d7b1d9f00', 'd', 'La prohibición de la navegación en sus alrededores.', false, '2025-09-13 13:53:13.459257+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e04951cf-cf3c-48a3-9dbd-f87ad4e9340c', 'de2d1bc8-1cae-4e20-a473-a5506a6d7876', 'b', 'Deberá utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', true, '2025-09-13 13:53:13.459849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9235e39e-da0e-4a4b-bd81-c5f070829aff', 'de2d1bc8-1cae-4e20-a473-a5506a6d7876', 'c', 'Navegará exclusivamente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-13 13:53:13.46007+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40e0b6ae-6b4f-49a9-a6f4-12d1c14321a7', 'de2d1bc8-1cae-4e20-a473-a5506a6d7876', 'd', 'En caso de necesidad de cruce del dispositivo, deberá hacerlo siguiendo un rumbo que en la medida de lo posible forme una paralela a la dirección general de la corriente del tráfico.', false, '2025-09-13 13:53:13.460276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('afb66e3e-3dbd-4bb1-9f4f-deba0a790793', '585aac90-3db5-47ee-a7d4-b5cea9c30cee', 'a', 'Un tope, las luces de costado, la luz de alcance, la luz de remolque y tres luces rojas todo horizonte, en el lugar más visible.', false, '2025-09-13 13:53:13.460716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47354791-9f4a-47dc-82e4-050c5e39f574', '585aac90-3db5-47ee-a7d4-b5cea9c30cee', 'b', 'Dos topes, las luces de costado, luz de alcance y, además, tres luces todo horizonte en línea vertical, en el lugar más visible. De estas últimas, la más elevada y la más baja de estas luces serán rojas y la luz central será blanca.', true, '2025-09-13 13:53:13.460922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be67da98-4a10-4535-a669-32a3928b8561', '585aac90-3db5-47ee-a7d4-b5cea9c30cee', 'd', 'Un tope, las luces de costado, la luz de alcance, y, además, dos luces todo horizonte en línea vertical, en el lugar más visible. De estas últimas, será roja la superior y blanca la inferior.', false, '2025-09-13 13:53:13.461351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6b5947d-fda4-4861-83bc-4a7147413c4d', '6cc881db-f0da-4e5d-a1f2-e35d54d43d0f', 'a', 'Una embarcación de 20 metros de eslora varada.', true, '2025-09-13 13:53:13.461743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb08d689-dede-44d8-88bc-89dce6477a91', '6cc881db-f0da-4e5d-a1f2-e35d54d43d0f', 'b', 'Un buque de 100 metros de eslora al cual estamos visualizando por su costado de babor.', false, '2025-09-13 13:53:13.461965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ded5ab84-7624-44cc-a8a2-0f4e5a817bca', '6cc881db-f0da-4e5d-a1f2-e35d54d43d0f', 'c', 'Un pesquero de arrastre faenando con su aparejo tendido.', false, '2025-09-13 13:53:13.462177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2cf2fa8d-e9a6-4524-b36f-a76d6a4ee6c3', '6cc881db-f0da-4e5d-a1f2-e35d54d43d0f', 'd', 'Una embarcación de prácticos sin arrancada.', false, '2025-09-13 13:53:13.462381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8dc23663-7d32-498e-a5be-125eda3c7bc6', 'e12fdf25-3ee3-4ce1-b677-ab9e6c2919dc', 'a', 'Luces de costado, una luz de alcance y dos luces todo horizonte en línea vertical, roja la superior y verde la inferior.', false, '2025-09-13 13:53:13.462796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('580a718a-1b04-43b9-8f76-43362b3f506d', 'e12fdf25-3ee3-4ce1-b677-ab9e6c2919dc', 'b', 'Luces de costado y una luz de alcance en un farol combinado en el tope del palo o cerca de él, en el lugar más visible.', false, '2025-09-13 13:53:13.463004+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7e37664-bb77-4ef5-a50e-5780bb183c44', 'e12fdf25-3ee3-4ce1-b677-ab9e6c2919dc', 'c', 'Luces de costado y una luz blanca todo horizonte.', true, '2025-09-13 13:53:13.463222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ddcdbf3-1d4f-4740-b34d-02527607ef19', 'e12fdf25-3ee3-4ce1-b677-ab9e6c2919dc', 'd', 'Luces de costado y una luz de alcance.', false, '2025-09-13 13:53:13.463419+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aadd6d36-30f0-4a90-ad79-7cb87393e6da', '75323c33-8335-40ad-a88a-8cd650143de3', 'a', 'El hidroavión amarado.', false, '2025-09-13 13:53:13.463865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6dc4fd24-e26f-4cd0-a020-b515cbf63feb', '75323c33-8335-40ad-a88a-8cd650143de3', 'b', 'El buque de propulsión mecánica en navegación.', false, '2025-09-13 13:53:13.464078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2ef5151-cfc6-47ee-a5b1-0a91da568dfd', '75323c33-8335-40ad-a88a-8cd650143de3', 'c', 'El buque de vela.', false, '2025-09-13 13:53:13.464287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('584e615e-4605-41ad-a48a-a269307e8ff6', '75323c33-8335-40ad-a88a-8cd650143de3', 'd', 'El buque dedicado a la pesca.', true, '2025-09-13 13:53:13.464498+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21254ff0-e03c-4e5b-8e4a-0439eb68daaf', '8019cd1d-db88-4b7b-a146-3d218452d04d', 'b', 'Maniobrar de forma clara, con antelación y respetando las buenas prácticas marineras para apartarnos de su derrota.', true, '2025-09-13 13:53:13.465106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4027ce57-7fe4-42fa-8fb6-e26a54cab55b', '8019cd1d-db88-4b7b-a146-3d218452d04d', 'c', 'Aumentar la velocidad ligeramente para tratar de propiciar que la otra embarcación haga la maniobra ante el posible peligro de abordaje, y así evitar un cambio de rumbo en nuestra derrota.', false, '2025-09-13 13:53:13.465311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5caefcc1-baeb-4254-8452-e3eb573af493', '8019cd1d-db88-4b7b-a146-3d218452d04d', 'd', 'Maniobrar cambiando de rumbo ligeramente con poca antelación para no confundir a la otra embarcación y que ella maniobre por tener obligación de hacerlo.', false, '2025-09-13 13:53:13.4655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b323d484-4ac2-4842-8338-4fae97471c2c', 'c69512a1-1201-4c46-998f-f5537d1341b7', 'a', 'Cambiando el rumbo con anticipación suficiente y manteniendo de forma decidida siempre nuestra velocidad para quedar bien francos del otro buque.', false, '2025-09-13 13:53:13.465927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fae6885e-c1d0-43c9-a446-0a5cd766b290', 'c69512a1-1201-4c46-998f-f5537d1341b7', 'c', 'Manteniendo siempre nuestro rumbo y modificando con anticipación suficiente la velocidad de forma decidida para evitar el abordaje.', false, '2025-09-13 13:53:13.466364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('672e7c84-3e15-48c6-86cd-8367a780cc50', 'c69512a1-1201-4c46-998f-f5537d1341b7', 'd', 'Manteniendo de forma decidida nuestro rumbo y velocidad para no generar dudas de nuestras intenciones al otro buque.', false, '2025-09-13 13:53:13.466559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9af93b3d-6820-4a25-bc92-cc051e37eaa1', '1bf2f5f4-ee8a-4be9-ac62-e0350e7d4b00', 'a', 'Buque sin gobierno.', false, '2025-09-13 13:53:13.466978+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55091a55-5bfc-4cbb-ae21-5b42d7a2f22b', '1bf2f5f4-ee8a-4be9-ac62-e0350e7d4b00', 'b', 'Buque de pesca.', false, '2025-09-13 13:53:13.467173+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cf1c9fc-97fe-4476-a87b-039295d5d345', '1bf2f5f4-ee8a-4be9-ac62-e0350e7d4b00', 'c', 'Buque con capacidad de maniobra restringida.', true, '2025-09-13 13:53:13.467372+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d90a47d4-ac91-4b5a-baa8-8e95e141e43a', '1bf2f5f4-ee8a-4be9-ac62-e0350e7d4b00', 'd', 'Buque restringido por su calado.', false, '2025-09-13 13:53:13.467565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4e00829-c4cb-475e-86ec-4c05fa6bf0ca', 'b7dac3ed-eff9-4c7c-9dec-f5d60fffb97f', 'a', 'Dirigir un haz de luz de nuestro proyector en la dirección del peligro, haciéndolo de forma que no moleste a otros buques.', true, '2025-09-13 13:53:13.467999+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7468294-1e77-488a-ac97-5271793107c2', 'b7dac3ed-eff9-4c7c-9dec-f5d60fffb97f', 'b', 'Utilizar luces intermitentes de gran intensidad.', false, '2025-09-13 13:53:13.46822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f56a09bc-d5f0-475e-9553-90cf3b82946c', 'b7dac3ed-eff9-4c7c-9dec-f5d60fffb97f', 'c', 'Utilizar luces giratorias de gran intensidad, como las luces estroboscópicas.', false, '2025-09-13 13:53:13.468397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c64685cf-75bd-455e-a536-3e3a8e367065', 'b7dac3ed-eff9-4c7c-9dec-f5d60fffb97f', 'd', 'Hacer cualquier señal acústica o luminosa de las autorizadas en cualquiera de las reglas del RIPA.', false, '2025-09-13 13:53:13.468603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5eaa7d9c-9a95-4667-ba9a-f436cd02c1d4', 'ee750df1-92b1-4bfc-b525-7dc6320b26e2', 'a', 'Cada uno caerá a estribor de forma que pase por la banda de babor del otro.', true, '2025-09-13 13:53:13.469003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('030278b7-48e9-4fd1-895a-913da6ab8275', 'ee750df1-92b1-4bfc-b525-7dc6320b26e2', 'b', 'Cada uno caerá a babor de forma que pase por la banda de estribor del otro.', false, '2025-09-13 13:53:13.469196+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06e39463-5852-44ec-a1e4-db9cb1491576', 'ee750df1-92b1-4bfc-b525-7dc6320b26e2', 'c', 'El yate caerá a babor y el buque de recreo a estribor.', false, '2025-09-13 13:53:13.469397+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea20e5aa-6710-48b2-9722-f62d803bb535', '1cc66208-b9a3-4bb2-a55f-ae84445c6598', 'a', 'Atracar la proa, sin imprimir movimiento avante o atrás a la embarcación.', false, '2025-09-13 13:53:13.470028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('320cb263-3df2-423f-a3a0-27b7fd4e997c', '1cc66208-b9a3-4bb2-a55f-ae84445c6598', 'b', 'Atracar la popa, desplazar la embarcación hacia avante y desatracar la proa.', false, '2025-09-13 13:53:13.470244+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71746b78-252d-4d74-b098-80a504b9a238', '1cc66208-b9a3-4bb2-a55f-ae84445c6598', 'c', 'Atracar la proa, desplazar la embarcación hacia atrás y desatracar la popa.', true, '2025-09-13 13:53:13.470451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af8544c2-085a-403f-a0f8-6a010b2abf0d', '1cc66208-b9a3-4bb2-a55f-ae84445c6598', 'd', 'Atracar la proa, desplazar la embarcación hacia avante y desatracar la popa.', false, '2025-09-13 13:53:13.470663+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae44705d-cf9e-431f-8938-cefde942179c', '5084d543-8de0-4064-83cf-3dbb17b6462b', 'a', 'Hacerlo firme.', false, '2025-09-13 13:53:13.471127+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d87a160-6997-40cd-b5df-ced7b2349b69', '5084d543-8de0-4064-83cf-3dbb17b6462b', 'b', 'Amarrarle un objeto.', false, '2025-09-13 13:53:13.471346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae83239b-c438-46a3-8cb0-25916ad323bf', '5084d543-8de0-4064-83cf-3dbb17b6462b', 'c', 'Aflojarlo cuando está tenso.', true, '2025-09-13 13:53:13.471568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6667d8f-d0d3-4430-a323-f5ed13e72d30', 'a39f8048-8018-4e3b-ab9e-4d0c29710c0e', 'a', 'Avisar a Salvamento Marítimo y esperar instrucciones sin tomar ninguna otra medida.', false, '2025-09-13 13:53:13.472247+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0222d643-38de-4925-a195-acc5dfcf7e57', 'a39f8048-8018-4e3b-ab9e-4d0c29710c0e', 'b', 'Comenzar a achicar el agua utilizando la bomba de achique y proceder, si es posible, al taponamiento de los orificios con espiches o colchonetas.', true, '2025-09-13 13:53:13.472448+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76b46f52-5f90-49b7-a987-89d24efd6611', 'a39f8048-8018-4e3b-ab9e-4d0c29710c0e', 'c', 'Poner de inmediato rumbo a puerto sin intentar achicar el agua.', false, '2025-09-13 13:53:13.472676+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13187523-2d79-42fb-b780-377779b25f90', 'c69512a1-1201-4c46-998f-f5537d1341b7', 'b', 'Maniobrando con anticipación suficiente y de forma decidida para quedar bien francos del otro buque.', true, '2025-09-13 13:53:13.46615+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c9acf7b2-1b70-4515-975e-ba10b1234914', 'ee750df1-92b1-4bfc-b525-7dc6320b26e2', 'd', 'El yate caerá a estribor y el buque de recreo a babor.', false, '2025-09-13 13:53:13.469595+00');
