INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('79b514af-2096-49cb-b4fb-31f35ee8da7e', '0fdba350-0c79-4fae-b134-95e11c900393', 'a', 'Lo primero que debemos hacer siempre es separar las embarcaciones involucradas en el abordaje lo antes posible.', false, '2025-09-13 13:53:13.473355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('10a167dc-2bad-4af0-8568-049b6c3d90a4', '0fdba350-0c79-4fae-b134-95e11c900393', 'b', 'El modo de proceder será siempre el mismo, sin importar si el abordaje resulta en una avería por debajo o por encima de la línea de flotación.', false, '2025-09-13 13:53:13.473571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d5c22fe-9bcc-47c9-b181-5ac9b804f3c0', '0fdba350-0c79-4fae-b134-95e11c900393', 'c', 'En caso de que seamos responsables del mismo, estamos obligados a prestar asistencia legal al patrón de la otra embarcación involucrada en caso de que lo necesite.', false, '2025-09-13 13:53:13.473792+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3735871-d55a-4f52-a553-9853ce6f63c0', '0fdba350-0c79-4fae-b134-95e11c900393', 'd', 'La evaluación de las averías sufridas debe realizarse a la mayor brevedad posible.', true, '2025-09-13 13:53:13.474024+00');
