INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e91b2fcc-4a59-48ae-b9ac-5a0ad4085970', 'f72caef7-fc08-494c-9f74-a692539f50a9', 'a', 'Mecha.', false, '2025-09-13 13:53:13.489529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b342c1c-0b7d-41bc-9585-cb7448f604b4', 'f72caef7-fc08-494c-9f74-a692539f50a9', 'b', 'Limera.', true, '2025-09-13 13:53:13.489755+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9117b5b8-c11c-4ade-89f8-72123a37cb58', 'f72caef7-fc08-494c-9f74-a692539f50a9', 'c', 'Guardín.', false, '2025-09-13 13:53:13.489984+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('444c87b1-7121-4df6-82f5-ce8e94cfb886', 'f72caef7-fc08-494c-9f74-a692539f50a9', 'd', 'Pala.', false, '2025-09-13 13:53:13.490192+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c9c49f5-8de5-40b6-902b-647254235eb0', 'a98a65df-70a7-4995-9dec-9338b9f99385', 'b', 'La aleta es la parte de los costados entre el través y la proa.', true, '2025-09-13 13:53:13.49088+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21f48a58-f68c-47ac-9ba8-10b23d10ed91', 'a98a65df-70a7-4995-9dec-9338b9f99385', 'c', 'El través es la parte media, en sentido longitudinal, de cada uno de los costados.', false, '2025-09-13 13:53:13.491078+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bec97954-7f1a-4cf9-a5c4-358b5c4602fb', 'a98a65df-70a7-4995-9dec-9338b9f99385', 'd', 'La obra viva es la parte sumergida del casco.', false, '2025-09-13 13:53:13.491276+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fcfedca3-f6e4-482a-a259-04fc1f8fc50d', 'bce3413f-a951-4634-826c-59278cd6ee2e', 'a', 'La prolongación estructural de la quilla hacia la proa.', true, '2025-09-13 13:53:13.491701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('58c08557-b084-4987-8346-d7f9479db43f', 'bce3413f-a951-4634-826c-59278cd6ee2e', 'b', 'La prolongación estructural de la quilla hacia la popa.', false, '2025-09-13 13:53:13.491894+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('444e1e97-1bea-41cc-aec1-5b08f3f0c9d6', 'bce3413f-a951-4634-826c-59278cd6ee2e', 'c', 'La pieza estructural de la embarcación que va de proa a popa en su parte inferior.', false, '2025-09-13 13:53:13.492086+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f7e30e5-06c3-436b-bc72-becd0ea4150e', 'bce3413f-a951-4634-826c-59278cd6ee2e', 'd', 'La pieza estructural curva que sale de la quilla y va por el costado.', false, '2025-09-13 13:53:13.492288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('94946685-55d7-4b9f-a6dc-e0566dda614e', '17dd9daf-5283-4418-88dc-cbaef87e8c48', 'a', 'Enderezarse o ponerse vertical.', true, '2025-09-13 13:53:13.492681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15d8769f-a5de-4f25-b5c6-0ae9e17225f8', '17dd9daf-5283-4418-88dc-cbaef87e8c48', 'b', 'Inclinarse sobre uno de sus costados.', false, '2025-09-13 13:53:13.492883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4c13f92a-2014-41e4-a489-9aaa6fc3d718', '17dd9daf-5283-4418-88dc-cbaef87e8c48', 'c', 'Hundir la proa y levantar la popa.', false, '2025-09-13 13:53:13.493077+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d18e13c-f402-4c29-8388-fe4ba99b4fe0', '89a3f483-27e2-49e7-9a0e-47a9cb0c395a', 'a', 'Un noray es cada uno de los postes de madera o hierro que, asegurados a la cubierta en las proximidades de la proa, sirven para dar vuelta a los cabos cuando se fondea.', false, '2025-09-13 13:53:13.493708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cc81642-a8a7-46a1-9ee1-9c763cd2f9f0', '89a3f483-27e2-49e7-9a0e-47a9cb0c395a', 'b', 'El chicote es un palo con punta y gancho metálico en un extremo que sirve para tomarse o abrirse al atracar o desatracar la embarcación.', false, '2025-09-13 13:53:13.493918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f66c72f5-e78d-49ff-8d27-d7695696a4ba', '89a3f483-27e2-49e7-9a0e-47a9cb0c395a', 'c', 'Un muerto es un bloque de cemento o ancla de gran peso depositado en el fondo que, unido por un orinque a la superficie, permite anclar una embarcación.', true, '2025-09-13 13:53:13.494124+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('30877c30-2f1e-4acd-bb43-cdba5141b957', '89a3f483-27e2-49e7-9a0e-47a9cb0c395a', 'd', 'El As de guía permite unir dos cabos de la misma mena que vayan a trabajar en tensión.', false, '2025-09-13 13:53:13.494328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a114443-d2fe-43a6-8da9-83dd25117a61', 'fdc2d43e-e937-45c9-bb0d-1661c3c0eebf', 'a', 'Se estudiará la carta y el derrotero para elegir un lugar protegido y un tenedero de fondo rocoso.', false, '2025-09-13 13:53:13.494741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f50ff2b5-89d7-414d-a65d-715e6c6b5407', 'fdc2d43e-e937-45c9-bb0d-1661c3c0eebf', 'd', 'En el momento del fondeo aumentaremos la arrancada dando marcha avante y largaremos cadena, para que esta se extienda correctamente por el fondo.', false, '2025-09-13 13:53:13.495375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c55e4bd2-51e9-4bd7-8c83-7c7113274825', '4c61d98b-71f0-4e52-bd65-b763aac549a1', 'b', 'Llevar la mar por la aleta con una velocidad prudencial para evitar los movimientos de cabeceo.', false, '2025-09-13 13:53:13.496145+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f83f19d-f79d-4609-a008-c3b70a018342', '4c61d98b-71f0-4e52-bd65-b763aac549a1', 'c', 'Buscar refugio de forma inmediata.', false, '2025-09-13 13:53:13.496364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5759cd75-79ea-40ff-88e4-1a65579e2523', '4c61d98b-71f0-4e52-bd65-b763aac549a1', 'd', 'Maniobrar para ponerse “a son de mar”.', false, '2025-09-13 13:53:13.496583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75cad6bb-055c-4d24-9893-6b7a440779d4', '79783ace-3a90-4014-83c6-828bdda040b3', 'a', 'Se deben almacenar a bordo en lugar seco.', false, '2025-09-13 13:53:13.497019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d17bde7-2c0c-4e38-9786-936096e7d660', '79783ace-3a90-4014-83c6-828bdda040b3', 'b', 'Se debe respetar escrupulosamente sus fechas de caducidad.', false, '2025-09-13 13:53:13.497236+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b84452a-cac6-4e89-8a49-4b560d3a4814', '79783ace-3a90-4014-83c6-828bdda040b3', 'c', 'Si pierde una, informe a Salvamento Marítimo, alguien puede encontrarla y activar una alarma.', true, '2025-09-13 13:53:13.497515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7fd9e6df-0ef5-4c97-9a3c-28b53dac08c4', '79783ace-3a90-4014-83c6-828bdda040b3', 'd', 'Se deben leer y aprender de memoria las instrucciones de uso.', false, '2025-09-13 13:53:13.497722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae99fc27-873a-4fdd-a624-2f8b85fdb00b', 'ac685023-7dac-477c-a869-f4628e1081ac', 'a', 'Es un equipo personal adaptado a la talla de cada tripulante.', true, '2025-09-13 13:53:13.498169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('499b40c9-4c10-4432-91ca-41a391d7cb7a', 'ac685023-7dac-477c-a869-f4628e1081ac', 'b', 'Utilice el arnés de cinta en lugar de cabo. Así se evita que, al pisar el arnés, ruede y pueda', false, '2025-09-13 13:53:13.498393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2f63bb94-23ba-4061-9ad5-6797dcb74405', 'ac685023-7dac-477c-a869-f4628e1081ac', 'c', 'Su función es mantenerle unido a la embarcación si se cae por la borda.', false, '2025-09-13 13:53:13.498593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0debe07e-b39d-45c0-9a7f-02e31ed48e94', 'ac685023-7dac-477c-a869-f4628e1081ac', 'd', 'Es preferible el arnés más completo, fijado al cuerpo bajo los brazos y entre las piernas.', false, '2025-09-13 13:53:13.498808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fb68a810-15bb-4512-996d-d4fa247f02f8', '2f67fb25-abdc-404f-9418-deb469136df0', 'a', 'Originar una inducción magnética peligrosa en el reflector radar pasivo.', false, '2025-09-13 13:53:13.499221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('90a633a4-5d57-41f7-949d-c4dd0b4047c0', '2f67fb25-abdc-404f-9418-deb469136df0', 'b', 'Disminuir la temperatura de ignición de los combustibles a bordo.', false, '2025-09-13 13:53:13.499447+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9885d07d-7b64-4819-a55b-bea06fbdffc6', '2f67fb25-abdc-404f-9418-deb469136df0', 'c', 'Influir en la aguja náutica.', true, '2025-09-13 13:53:13.499669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa530f4d-9cfd-4766-8541-7272ac326773', '2f67fb25-abdc-404f-9418-deb469136df0', 'd', 'Producir un fenómeno conocido como “rayo verde”.', false, '2025-09-13 13:53:13.499879+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4553482-a54d-4b8a-a6f1-48ac17713cf0', '1b36352a-c526-44e7-82f0-823529ba6962', 'a', '40 metros.', false, '2025-09-13 13:53:13.500315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a605eee9-4a9e-40ad-876f-4bb88db5f456', '1b36352a-c526-44e7-82f0-823529ba6962', 'b', '200 metros.', false, '2025-09-13 13:53:13.500524+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c90afef-4aaa-4cca-ae8d-56f0005f1f27', '1b36352a-c526-44e7-82f0-823529ba6962', 'c', '25 metros.', false, '2025-09-13 13:53:13.500731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9046d27e-2f48-4688-8ffd-5beab00beffc', '1b36352a-c526-44e7-82f0-823529ba6962', 'd', '50 metros.', true, '2025-09-13 13:53:13.500973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ba98360-6f02-49bc-b06d-deb12dd21d0c', 'c052f2eb-664e-44da-9231-d0a7cd6a3d20', 'a', 'Un incidente o accidente que afecte a la seguridad de la embarcación tales como abordajes, varadas o daños.', false, '2025-09-13 13:53:13.501429+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('165abe26-ec14-4d8a-aad9-980c0b23fb79', 'c052f2eb-664e-44da-9231-d0a7cd6a3d20', 'b', 'La decisión de fondear en calas o lugares de baño, siempre que no estén balizados y no pongan en peligro la seguridad de la navegación.', true, '2025-09-13 13:53:13.501641+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0898dfbf-3539-4088-a8e4-7fc64c5c646c', 'c052f2eb-664e-44da-9231-d0a7cd6a3d20', 'd', 'Un incidente o accidente que comprometa la seguridad de la navegación o que puedan afectar a la maniobrabilidad.', false, '2025-09-13 13:53:13.502033+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05bc07f2-8ec7-4833-8f98-314502492d93', 'bc732015-35a0-43b0-8162-6c1247f58ecb', 'a', 'Dejaremos la “Marca de canal principal a estribor” por nuestro costado de estribor.', false, '2025-09-13 13:53:13.502438+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43fae708-912f-42e0-ae1d-3acd96bdedb4', 'bc732015-35a0-43b0-8162-6c1247f58ecb', 'b', 'Dejaremos la “Marca de canal principal a estribor” por nuestro costado de babor.', true, '2025-09-13 13:53:13.502637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bda5c896-3f1a-4191-835f-b1e65a49742d', 'bc732015-35a0-43b0-8162-6c1247f58ecb', 'c', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de estribor.', false, '2025-09-13 13:53:13.502869+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('615dc278-2954-4f19-acb8-f4dcbdc63b2c', 'bc732015-35a0-43b0-8162-6c1247f58ecb', 'd', 'Dejaremos la “Marca de canal principal a babor” por nuestro costado de babor.', false, '2025-09-13 13:53:13.503062+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81110898-f347-4e30-83c5-c5418e2a9bb7', '8edc851c-204c-49bc-ac2f-d2ae8ce73fe6', 'a', 'Indican el lugar donde se encuentran las aguas más seguras, en relación con un punto de interés.', false, '2025-09-13 13:53:13.503512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a88f9ed-f3e5-415b-a4fc-a20c144e5fe4', 'fdc2d43e-e937-45c9-bb0d-1661c3c0eebf', 'b', 'La aproximación al lugar de fondeo se hará a la mínima velocidad de gobierno y con el viento por la proa.', true, '2025-09-13 13:53:13.494956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('64572abb-a395-4941-8c59-edcf601fcdc3', 'fdc2d43e-e937-45c9-bb0d-1661c3c0eebf', 'c', 'Se comprobará que no haya obstáculos en un círculo de borneo de radio igual a la eslora de la embarcación.', false, '2025-09-13 13:53:13.495159+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a19ba8c-1b26-43b0-a34d-f3bf648aa09c', '4c61d98b-71f0-4e52-bd65-b763aac549a1', 'a', 'Llevar la mar por la amura con poca arrancada, pero la suficiente para permitir el gobierno de la embarcación.', true, '2025-09-13 13:53:13.49588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21fc422d-0df9-4042-805f-9eb1756dc3eb', 'c052f2eb-664e-44da-9231-d0a7cd6a3d20', 'c', 'La visualización de cualquier mancha de materiales contaminantes o contenedores a la deriva en el mar.', false, '2025-09-13 13:53:13.501833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e40488f4-628d-4bf0-b2e1-ace894f37e96', '17dd9daf-5283-4418-88dc-cbaef87e8c48', 'd', 'Hundir la popa y levantar la proa.', false, '2025-09-13 13:53:13.493299+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ef79f40-d0d6-47b6-8b56-7c708e9bc141', 'a98a65df-70a7-4995-9dec-9338b9f99385', 'a', 'Los imbornales son aberturas en los costados que sirven para evacuar el agua de las zonas de cubierta.', false, '2025-09-13 13:53:13.490658+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('854ba03b-d7e5-48ca-9bda-035d4beb7cb7', '8edc851c-204c-49bc-ac2f-d2ae8ce73fe6', 'd', 'Pueden emplearse para indicar el lado seguro por el que se ha de pasar para salvar un peligro.', false, '2025-09-13 13:53:13.504128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b786c49-f9bc-4cc7-9d95-a0819fa1c8fa', '3801c17e-8816-4088-bad2-3a8f47938d97', 'a', 'Las Marcas de peligro aislado nunca tendrán forma de castillete o espeque.', true, '2025-09-13 13:53:13.50452+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa188454-b971-4e0b-98fd-fdcb7cdc7e4b', '3801c17e-8816-4088-bad2-3a8f47938d97', 'b', 'Siempre, estarán pintadas de color negro con una o más bandas anchas horizontales rojas.', false, '2025-09-13 13:53:13.504731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9227250-a6f7-4f20-90e0-175ac0a52eac', '3801c17e-8816-4088-bad2-3a8f47938d97', 'd', 'Su luz tendrá ritmo de Grupo de dos destellos GpD (2) para distinguirlas de las Marcas', false, '2025-09-13 13:53:13.505158+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9abbc67-44e3-49b3-8839-da82af1dcf8c', '62e1c835-3414-4bbc-a5a7-39bef357aebc', 'a', 'Un doble cilindro amarillo.', false, '2025-09-13 13:53:13.505587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2fe3f01-6854-4de2-9f7d-6344b0d060d1', '62e1c835-3414-4bbc-a5a7-39bef357aebc', 'b', 'Un doble cilindro negro.', false, '2025-09-13 13:53:13.505808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('499e1acd-7cb7-4033-9949-0ea109e77882', '62e1c835-3414-4bbc-a5a7-39bef357aebc', 'c', 'Un doble cono amarillo.', false, '2025-09-13 13:53:13.50601+00');
