INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4252651b-2117-4d90-9a59-bffa8ee06beb', 'cb9c09d7-7d8c-4193-be7d-8800fa22f298', 'a', 'Una única esfera roja.', false, '2025-09-13 13:53:13.506646+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c507db9a-feb2-4bae-abcb-481794e48492', 'cb9c09d7-7d8c-4193-be7d-8800fa22f298', 'b', 'De color amarillo sobre negro.', false, '2025-09-13 13:53:13.506842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7041f175-3ba8-4fdb-a63e-209d5a5dd2fa', 'cb9c09d7-7d8c-4193-be7d-8800fa22f298', 'c', 'Un aspa amarilla en forma de "X".', true, '2025-09-13 13:53:13.507048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3bd1103a-a7c9-4736-8a74-9a502b6586d5', '7de66956-1ca4-4ae1-80e1-e31590fb6e7a', 'a', 'Uno de propulsión mecánica de 60 metros de eslora con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.507657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b9d8d9f-5750-42d9-952f-739811ca22fc', '7de66956-1ca4-4ae1-80e1-e31590fb6e7a', 'b', 'Uno de propulsión mecánica de más de 50 metros sin gobierno, pero con arrancada.', false, '2025-09-13 13:53:13.50786+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c8e6918-720c-4ba4-aced-592711027566', '7de66956-1ca4-4ae1-80e1-e31590fb6e7a', 'c', 'Un pesquero no de arrastre faenando.', false, '2025-09-13 13:53:13.508055+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e24e8808-8c7b-4351-a580-4bd65078acbd', '7de66956-1ca4-4ae1-80e1-e31590fb6e7a', 'd', 'Uno de propulsión mecánica de 40 metros de eslora restringido por su calado.', true, '2025-09-13 13:53:13.508251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b952a6db-7906-4e0e-8647-f63c919f4f33', '7ca6dbed-7a8d-4d9d-9e44-a93ab972fdd9', 'a', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse a un buque de pequeño tamaño a mucha distancia.', false, '2025-09-13 13:53:13.508674+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b9c7bc15-f2fb-44b6-aee9-1ed13d019da5', '7ca6dbed-7a8d-4d9d-9e44-a93ab972fdd9', 'b', 'Que existe el riesgo, si la demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:13.508865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2479ef25-0162-4153-9155-8236d4aa9d95', '7ca6dbed-7a8d-4d9d-9e44-a93ab972fdd9', 'd', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse en la lejanía un buque de pequeño tamaño a poca velocidad.', false, '2025-09-13 13:53:13.50926+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31306e5f-1c72-4c9c-a816-2661e5d178fe', '668c971c-4530-480b-9793-4c16bedc1263', 'a', 'Deberá mantener un resguardo mínimo de 1 milla con el buque alcanzado.', false, '2025-09-13 13:53:13.509689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96119e2c-16b2-4949-90d1-2f3c4fb8f3e0', '668c971c-4530-480b-9793-4c16bedc1263', 'b', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:13.509906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('95875c38-ae79-4a96-b94e-c40399950aa1', '668c971c-4530-480b-9793-4c16bedc1263', 'c', 'Virará claramente hacia cualquiera de las bandas para indicar su intención de adelantar.', false, '2025-09-13 13:53:13.510108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6516a4e1-edb1-49b8-b92f-52bb0fa91a4f', '668c971c-4530-480b-9793-4c16bedc1263', 'd', 'No podrá rebasarlo si la velocidad del buque alcanzado es superior a 12 nudos.', false, '2025-09-13 13:53:13.510304+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15db0ef5-18e7-443f-bce1-7b17b4bbdcda', '675cbff2-a5cf-489f-80c8-2bf1830703b7', 'b', 'Blanca todo horizonte visible a una distancia mínima de 5 millas.', true, '2025-09-13 13:53:13.510955+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27957013-3a06-42d1-8448-51376e0b1f51', '675cbff2-a5cf-489f-80c8-2bf1830703b7', 'c', 'Amarilla, que muestra su luz en un arco de horizonte de 225 grados, de forma que sea visible desde la proa hasta 22,5 grados a popa del través de cada costado, visible a una distancia máxima de 5 millas.', false, '2025-09-13 13:53:13.511164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f44cd6a-f3af-46b4-aeee-cceee4603ab2', '675cbff2-a5cf-489f-80c8-2bf1830703b7', 'd', 'Amarilla todo horizonte visible a una distancia mínima de 3 millas.', false, '2025-09-13 13:53:13.51137+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a03bf72-8bef-430f-b975-e512cccbe0db', '4d1268c9-7ec0-4d75-865c-fd9d0fc9b9c7', 'a', 'Un pito.', true, '2025-09-13 13:53:13.511798+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8cca0759-8e9b-4f72-92ab-4f5ef7665431', '4d1268c9-7ec0-4d75-865c-fd9d0fc9b9c7', 'b', 'No tendremos obligación de llevar ningún dispositivo de señales acuáticas, ya que solamente son obligatorios para buques cuya eslora es mayor de 12 metros.', false, '2025-09-13 13:53:13.511989+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e2659e9-525a-4aa9-8331-953894e69c3a', '4d1268c9-7ec0-4d75-865c-fd9d0fc9b9c7', 'c', 'No tendremos obligación de llevar los dispositivos de señales acústicas prescritos de esta Regla, pero debemos ir dotados de otros medios para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:13.512193+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93ff3d6a-2001-46d3-b158-c9cb9ba624e1', '4d1268c9-7ec0-4d75-865c-fd9d0fc9b9c7', 'd', 'Una campana y un pito.', false, '2025-09-13 13:53:13.512391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69de589e-079a-4f12-8b2e-2e62300c87c6', 'e38b7343-c8ff-4a7c-af5f-7a3461f93b03', 'a', 'Únicamente los buques de vela.', false, '2025-09-13 13:53:13.512811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f7c814c-07b5-4543-8657-ed3b3f9c6206', 'e38b7343-c8ff-4a7c-af5f-7a3461f93b03', 'b', 'Los buques de eslora inferior a 24 metros y los buques de vela.', false, '2025-09-13 13:53:13.513046+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43758cae-07c7-47cb-b229-8baaabdf984a', 'e38b7343-c8ff-4a7c-af5f-7a3461f93b03', 'c', 'Los buques de eslora inferior a 20 metros, los buques de vela y los buques dedicados a la pesca.', true, '2025-09-13 13:53:13.513267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('405e6b8e-19ca-4581-91cc-ad7ccf15fc3f', 'e38b7343-c8ff-4a7c-af5f-7a3461f93b03', 'd', 'Únicamente los buques dedicados a la pesca y los buques de vela.', false, '2025-09-13 13:53:13.513469+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('103bff58-cd6b-4cc4-9bff-1dfc3767b6d8', 'e7781e26-ff2c-4ae3-8f19-f378c9c19d5c', 'b', 'Remolcando a otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.514148+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07166e9e-f24f-4e58-b5fe-3ef3901ea4c3', 'e7781e26-ff2c-4ae3-8f19-f378c9c19d5c', 'c', 'Remolcando a otro, cuando la longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:13.514377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfce0e64-1b94-49bf-a239-1c2748b63ec3', 'e7781e26-ff2c-4ae3-8f19-f378c9c19d5c', 'd', 'Remolcado por otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.514582+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a412651b-4972-46c4-b88a-618234e52eeb', '15272c6d-cb78-41b7-bd81-5aee6fbdfaa8', 'a', 'Reducirá su velocidad hasta la mínima de gobierno.', false, '2025-09-13 13:53:13.51503+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d87b63e-0fca-4136-8225-e069e00e0383', '15272c6d-cb78-41b7-bd81-5aee6fbdfaa8', 'b', 'Suprimirá su arrancada, si fuese necesario.', false, '2025-09-13 13:53:13.515258+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0084eb70-cccc-403e-8f88-6629cf94178a', '15272c6d-cb78-41b7-bd81-5aee6fbdfaa8', 'c', 'Navegará con extremada precaución hasta que desaparezca el peligro de abordaje.', false, '2025-09-13 13:53:13.515455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e121a4c0-0f3f-41d5-846e-6514c1ebb067', '15272c6d-cb78-41b7-bd81-5aee6fbdfaa8', 'd', 'Aumentará su velocidad hasta la máxima de gobierno para minimizar la aproximación excesiva y en ningún caso se quedará sin arrancada.', true, '2025-09-13 13:53:13.515655+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a00afac-d696-411e-bd48-17bbe23116af', '6f4b7263-e162-47ad-a5cd-4f4831e0a560', 'a', 'Con una frecuencia de 120 o más centelleos por minuto, a intervalos regulares.', true, '2025-09-13 13:53:13.516079+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a0f13da-fe48-4ef7-9ae2-629511e1a958', '6f4b7263-e162-47ad-a5cd-4f4831e0a560', 'b', 'Con una frecuencia de 60 o menos centelleos por minuto, a intervalos regulares.', false, '2025-09-13 13:53:13.516273+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4e57af9-f8bd-47de-ada6-7aa16920ad18', '6f4b7263-e162-47ad-a5cd-4f4831e0a560', 'c', 'Con una duración cada centelleo de 1 segundo aproximadamente, con un intervalo entre centelleos de 1 segundo aproximadamente.', false, '2025-09-13 13:53:13.516482+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89fa8469-050b-45c8-bed3-fca4e2d4b79b', '6f4b7263-e162-47ad-a5cd-4f4831e0a560', 'd', 'Con una duración cada centelleo de medio segundo aproximadamente, a intervalos irregulares.', false, '2025-09-13 13:53:13.516677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f93603bc-a077-45dd-83e8-75c4485d8399', '7848de60-0f65-424f-be33-55f83b9e78b2', 'a', 'Buque sin gobierno.', true, '2025-09-13 13:53:13.517125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a855efe1-f4d3-4b97-898e-755f2ba9e563', '7848de60-0f65-424f-be33-55f83b9e78b2', 'b', 'Buque de pesca.', false, '2025-09-13 13:53:13.517326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8377b95a-47ec-49a4-95f9-2b14c26ba2fb', '7848de60-0f65-424f-be33-55f83b9e78b2', 'c', 'Buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.517539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1e03a7c-8b64-4b14-8acb-fd44914b6e35', '675cbff2-a5cf-489f-80c8-2bf1830703b7', 'a', 'Blanca, que muestra su luz en un arco de horizonte de.', false, '2025-09-13 13:53:13.510731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('823ca4d2-0256-49f8-b764-9f1af5fdf8b8', 'e7781e26-ff2c-4ae3-8f19-f378c9c19d5c', 'a', 'Empujando a otro, cuando forman una unidad compuesta y la longitud del conjunto es superior a.', false, '2025-09-13 13:53:13.513936+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2dfcb825-d0a1-462c-82a6-418eb62cfa1a', 'cb9c09d7-7d8c-4193-be7d-8800fa22f298', 'd', 'Dos esferas negras, una encima de la otra.', false, '2025-09-13 13:53:13.507242+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('017de736-35f6-4b95-935a-321d2945aea4', '7ca6dbed-7a8d-4d9d-9e44-a93ab972fdd9', 'c', 'Que un equipo de radar funcionando correctamente no es una fuente de información fiable a tener en cuenta.', false, '2025-09-13 13:53:13.509053+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f7cf9f0-0165-46dc-9f3a-16d9854ddc1f', '7848de60-0f65-424f-be33-55f83b9e78b2', 'd', 'Buque restringido por su calado.', false, '2025-09-13 13:53:13.517743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ead7288d-05bf-4b47-a014-f0d9bbc39afe', '553fa0f3-9607-4702-a056-92e2d7102199', 'c', 'Quedarse estático, ya que a la estructura del buque no le afecta el viento.', false, '2025-09-13 13:53:13.518554+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea95d1a8-ba4f-4825-b3c0-7803fe9c554e', '553fa0f3-9607-4702-a056-92e2d7102199', 'd', 'Cruzarse al viento.', false, '2025-09-13 13:53:13.518793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6863619-716f-47d4-9b7f-221901d12d7e', '62b389c3-6eb8-4c56-ac59-2e4f75b1fc68', 'a', 'Adujar.', true, '2025-09-13 13:53:13.519206+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('140bf7f6-12fb-4c83-8602-050e6799c927', '62b389c3-6eb8-4c56-ac59-2e4f75b1fc68', 'b', 'Tomar vueltas.', false, '2025-09-13 13:53:13.519423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae169e8b-dbd9-4a07-a9ae-332e0b11c898', '62b389c3-6eb8-4c56-ac59-2e4f75b1fc68', 'c', 'Amollar.', false, '2025-09-13 13:53:13.519656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('337a55a4-cbd3-4b8c-9fee-90f12a8bbb58', 'f1f9676a-cda7-41da-a068-e4a893c385c7', 'a', 'Desnudar la zona afectada, recortar cuidadosamente todas las ampollas y frotar la quemadura con alcohol para desinfectarla.', false, '2025-09-13 13:53:13.520301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6f60a1db-9a9c-4498-87f9-5939729a01a7', 'f1f9676a-cda7-41da-a068-e4a893c385c7', 'b', 'Cubrir la quemadura, una vez limpia, con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.520509+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6ae5897-3ec3-4877-81b1-1ba956651b55', 'f1f9676a-cda7-41da-a068-e4a893c385c7', 'c', 'En el caso de la mano, inmovilizarla vendando todos los dedos juntos y colocando un almohadillado para mantener las articulaciones en ligera flexión.', false, '2025-09-13 13:53:13.520724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50f15af4-8807-42eb-a970-2aaab23999bf', 'f1f9676a-cda7-41da-a068-e4a893c385c7', 'd', 'Evacuar inmediatamente al accidentado a un centro hospitalario para su tratamiento.', true, '2025-09-13 13:53:13.52092+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('807b0a2f-a7d6-404d-af45-2e3992d6ad60', 'd1336e18-b6ea-4554-b383-9141abbd3441', 'a', 'Parar el motor y colocarse el chaleco salvavidas.', false, '2025-09-13 13:53:13.521368+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdd17944-83c6-4498-8f34-c60756589839', 'd1336e18-b6ea-4554-b383-9141abbd3441', 'b', 'Abrir las escotillas, puertas y tomas de aire, para facilitar su extinción.', true, '2025-09-13 13:53:13.521572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40f7aed3-93cd-424d-ab1f-bb64776db774', 'd1336e18-b6ea-4554-b383-9141abbd3441', 'c', 'Realizar una llamada de socorro, en el caso de que se vea incapaz de apagar el fuego.', false, '2025-09-13 13:53:13.521769+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('38ee8408-3bb0-44af-944e-7aa175ba4971', 'd1336e18-b6ea-4554-b383-9141abbd3441', 'd', 'Utilizar los extintores, atacando directamente la base del fuego.', false, '2025-09-13 13:53:13.52196+00');
