INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4668b1fc-f6de-4439-b88a-c979eb0deeb7', '865e63e9-e141-40ad-9e9f-c583224e9dba', 'a', 'Desnudar la zona afectada, recortar cuidadosamente todas las ampollas y frotar la quemadura con alcohol para desinfectarla.', false, '2025-09-13 13:53:13.540322+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fbb825a-9f57-4290-8295-d79d5023b1b1', '865e63e9-e141-40ad-9e9f-c583224e9dba', 'b', 'Cubrir la quemadura, una vez limpia, con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.54052+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92dac844-d69b-43fd-bfd8-635837601c77', '865e63e9-e141-40ad-9e9f-c583224e9dba', 'c', 'En el caso de la mano, inmovilizarla vendando todos los dedos juntos y colocando un almohadillado para mantener las articulaciones en ligera flexión.', false, '2025-09-13 13:53:13.540724+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49654135-eefb-4e95-9e02-a589d44bacf5', '865e63e9-e141-40ad-9e9f-c583224e9dba', 'd', 'Evacuar inmediatamente al accidentado a un centro hospitalario para su tratamiento.', true, '2025-09-13 13:53:13.540921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b32af054-3dd3-4052-8fa0-10638f9a2932', 'b8e7621a-2539-473e-9377-b7fa7a8fdb36', 'a', 'Parar el motor y colocarse el chaleco salvavidas.', false, '2025-09-13 13:53:13.541348+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22645179-a4b0-427d-832f-300176fc8b6e', 'b8e7621a-2539-473e-9377-b7fa7a8fdb36', 'b', 'Abrir las escotillas, puertas y tomas de aire, para facilitar su extinción.', true, '2025-09-13 13:53:13.541556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae7923cb-40b5-4f86-8a89-ddceda6eef00', 'b8e7621a-2539-473e-9377-b7fa7a8fdb36', 'c', 'Realizar una llamada de socorro, en el caso de que se vea incapaz de apagar el fuego.', false, '2025-09-13 13:53:13.54174+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('467ddb46-c2e6-4715-b5f4-c2ae51638a30', 'b8e7621a-2539-473e-9377-b7fa7a8fdb36', 'd', 'Utilizar los extintores, atacando directamente la base del fuego. Meteorología', false, '2025-09-13 13:53:13.541958+00');
