INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b1414e9-df8c-40ef-af5e-aae2326c1d23', '1b4eb66a-c722-4165-9187-35eb0b2e0386', 'a', 'Desnudar la zona afectada, recortar cuidadosamente todas las ampollas y frotar la quemadura con alcohol para desinfectarla.', false, '2025-09-13 13:53:13.55837+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00715488-d738-486b-b8ce-a4f39f9d46c3', '1b4eb66a-c722-4165-9187-35eb0b2e0386', 'b', 'Cubrir la quemadura, una vez limpia, con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.55857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13c1bb58-82ad-47af-ad79-ba01f902e97b', '1b4eb66a-c722-4165-9187-35eb0b2e0386', 'c', 'En el caso de la mano, inmovilizarla vendando todos los dedos juntos y colocando un almohadillado para mantener las articulaciones en ligera flexión.', false, '2025-09-13 13:53:13.558785+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5377cd38-9502-407c-ae94-a17e3bb42b90', '1b4eb66a-c722-4165-9187-35eb0b2e0386', 'd', 'Evacuar inmediatamente al accidentado a un centro hospitalario para su tratamiento.', true, '2025-09-13 13:53:13.558975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a899063d-247d-43dd-b198-5f54c7907c10', 'd7a1ce11-dbe5-4d8e-9a2c-e763beadcc39', 'a', 'Parar el motor y colocarse el chaleco salvavidas.', false, '2025-09-13 13:53:13.559417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9329cc2f-fa59-44d7-b1f5-41eea997984e', 'd7a1ce11-dbe5-4d8e-9a2c-e763beadcc39', 'b', 'Abrir las escotillas, puertas y tomas de aire, para facilitar su extinción.', true, '2025-09-13 13:53:13.559611+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('117c682b-5603-4737-9de6-2832705e3695', 'd7a1ce11-dbe5-4d8e-9a2c-e763beadcc39', 'c', 'Realizar una llamada de socorro, en el caso de que se vea incapaz de apagar el fuego.', false, '2025-09-13 13:53:13.5598+00');
