INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0470dea-2c35-46c2-b21f-28fd4e9c2412', 'd47197a6-c282-4a6c-8c18-e4ac6171e130', 'a', 'Los imbornales son aberturas en los costados que sirven para evacuar el agua de las zonas de', false, '2025-09-13 13:53:13.577322+00');
