INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6356df86-37d7-4fac-97f1-430f18f42159', '6443c710-ebeb-4955-97af-ee5492704b56', 'a', 'Un noray es cada uno de los postes de madera o hierro que, asegurados a la cubierta en las proximidades de la proa, sirven para dar vuelta a los cabos cuando se fondea.', false, '2025-09-13 13:53:13.579365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('192dd226-0625-41d9-b303-d2dbb13b5222', '6443c710-ebeb-4955-97af-ee5492704b56', 'b', 'El chicote es un palo con punta y gancho metálico en un extremo que sirve para tomarse o abrirse al atracar o desatracar la embarcación.', false, '2025-09-13 13:53:13.579596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb99749f-cf06-4dc2-a098-1273044e6850', '6443c710-ebeb-4955-97af-ee5492704b56', 'c', 'Un muerto es un bloque de cemento o ancla de gran peso depositado en el fondo que, unido por un orinque a la superficie, permite anclar una embarcación.', true, '2025-09-13 13:53:13.579808+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('54701c0f-ee0d-4207-9117-2c18e16b1c0c', '6443c710-ebeb-4955-97af-ee5492704b56', 'd', 'El As de guía permite unir dos cabos de la misma mena que vayan a trabajar en tensión.', false, '2025-09-13 13:53:13.580005+00');
