INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1757e2c7-9f04-4e20-9705-ca16afd0019b', '57ea9bf0-22ae-43ef-9df9-eef50d8ecec2', 'a', 'Un pito.', true, '2025-09-13 13:53:13.593988+00');
