INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da7d326d-da92-4e3a-92af-7cd2ae06327b', '80ef8e87-2de4-48cd-9c54-afc9e26b1add', 'c', 'Hundir la proa y levantar la popa.', false, '2025-09-13 13:53:13.607145+00');
