INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cdd068fb-7ac6-4c04-a729-6831d111a1b4', '2115703b-bbec-4e5a-8f12-a8edfb1030b0', 'a', 'Un noray es cada uno de los postes de madera o hierro que, asegurados a la cubierta en las proximidades de la proa, sirven para dar vuelta a los cabos cuando se fondea.', false, '2025-09-13 13:53:13.607816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c02ffde-7871-4503-a47b-3331b5078e00', '2115703b-bbec-4e5a-8f12-a8edfb1030b0', 'b', 'El chicote es un palo con punta y gancho metálico en un extremo que sirve para tomarse o abrirse al atracar o desatracar la embarcación.', false, '2025-09-13 13:53:13.608026+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec46d46b-fb55-434c-8e11-0eb9d3595ffe', '2115703b-bbec-4e5a-8f12-a8edfb1030b0', 'c', 'Un muerto es un bloque de cemento o ancla de gran peso depositado en el fondo que, unido por un orinque a la superficie, permite anclar una embarcación.', true, '2025-09-13 13:53:13.608245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('034f9f50-8155-47e5-8692-53be70f26690', '2115703b-bbec-4e5a-8f12-a8edfb1030b0', 'd', 'El As de guía permite unir dos cabos de la misma mena que vayan a trabajar en tensión.', false, '2025-09-13 13:53:13.608459+00');
