INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbcf5e02-940d-4dc7-8450-5b4919aadc2d', '9289c6db-f758-4b44-b21c-5a2b9443fb1a', 'b', 'Uno de propulsión mecánica de más de 50 metros sin gobierno, pero con arrancada.', false, '2025-09-13 13:53:13.621713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39a04bc2-7732-4600-967b-280d39901128', '9289c6db-f758-4b44-b21c-5a2b9443fb1a', 'c', 'Un pesquero no de arrastre faenando.', false, '2025-09-13 13:53:13.621921+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea632ed4-6077-4059-8aef-292813cd47ad', '9289c6db-f758-4b44-b21c-5a2b9443fb1a', 'd', 'Uno de propulsión mecánica de 40 metros de eslora restringido por su calado.', true, '2025-09-13 13:53:13.622149+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5da95b94-7f6c-4aa5-bd25-a76025144f6b', '413dfceb-146e-4184-aa2c-0a9968bab192', 'a', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse a un buque de pequeño tamaño a mucha distancia.', false, '2025-09-13 13:53:13.622581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d00837a-9989-412e-bd31-e737a192606f', '413dfceb-146e-4184-aa2c-0a9968bab192', 'b', 'Que existe el riesgo, si la demora de un buque que se aproxima no varía en forma apreciable.', true, '2025-09-13 13:53:13.6228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a684f40-bf81-4f69-9cf0-b2197189cae1', '413dfceb-146e-4184-aa2c-0a9968bab192', 'c', 'Que un equipo de radar funcionando correctamente no es una fuente de información fiable a tener', false, '2025-09-13 13:53:13.623011+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18d5af97-eff5-4239-b007-94cb6dba29ed', '413dfceb-146e-4184-aa2c-0a9968bab192', 'd', 'Que puede existir riesgo aun cuando sea evidente una variación apreciable de la demora, en particular al aproximarse en la lejanía un buque de pequeño tamaño a poca velocidad.', false, '2025-09-13 13:53:13.623224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2229b32-68e4-4483-9d43-25902f0d204c', 'f10fe2c1-9740-491c-9638-155a15b79e4d', 'a', 'Deberá mantener un resguardo mínimo de 1 milla con el buque alcanzado.', false, '2025-09-13 13:53:13.623669+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3d34c9b-60c1-4e1b-9c2e-d2021abf5012', 'f10fe2c1-9740-491c-9638-155a15b79e4d', 'b', 'Se mantendrá apartado de la derrota del buque alcanzado.', true, '2025-09-13 13:53:13.6239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08e8800b-8175-4d61-bb2a-3cfc1ea8144d', 'f10fe2c1-9740-491c-9638-155a15b79e4d', 'c', 'Virará claramente hacia cualquiera de las bandas para indicar su intención de adelantar.', false, '2025-09-13 13:53:13.624115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4ef9ce85-50c1-4f90-995d-827adf016f47', 'f10fe2c1-9740-491c-9638-155a15b79e4d', 'd', 'No podrá rebasarlo si la velocidad del buque alcanzado es superior a 12 nudos.', false, '2025-09-13 13:53:13.624328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('150529b1-4b58-443b-a251-085d38f19be5', 'd2431dc3-8bd4-4eae-b32a-6abab5683cbb', 'a', 'Blanca, que muestra su luz en un arco de horizonte de 225 grados, de forma que sea visible desde la proa hasta 22,5 grados a popa del través de cada costado, visible a una distancia mínima de 3', false, '2025-09-13 13:53:13.624745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab2f8dab-004b-45d4-8e1d-a6a50e5df628', 'd2431dc3-8bd4-4eae-b32a-6abab5683cbb', 'b', 'Blanca todo horizonte visible a una distancia mínima de 5 millas.', true, '2025-09-13 13:53:13.624969+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7d247b8-07dd-4561-ae46-97edfe5cb149', 'd2431dc3-8bd4-4eae-b32a-6abab5683cbb', 'c', 'Amarilla, que muestra su luz en un arco de horizonte de 225 grados, de forma que sea visible desde la proa hasta 22,5 grados a popa del través de cada costado, visible a una distancia máxima de 5 millas.', false, '2025-09-13 13:53:13.625189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e2c1c60d-1306-4c6f-8391-243ce91ce0d3', 'd2431dc3-8bd4-4eae-b32a-6abab5683cbb', 'd', 'Amarilla todo horizonte visible a una distancia mínima de 3 millas.', false, '2025-09-13 13:53:13.625391+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd53011b-7eae-453b-b730-747ab68b1f84', 'd052e4c5-a199-4165-a5be-52eece52935b', 'a', 'Un pito.', true, '2025-09-13 13:53:13.625825+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bd7db62-faa1-4e25-9d15-72c00e29bca7', 'd052e4c5-a199-4165-a5be-52eece52935b', 'b', 'No tendremos obligación de llevar ningún dispositivo de señales acuáticas, ya que solamente son obligatorios para buques cuya eslora es mayor de 12 metros.', false, '2025-09-13 13:53:13.626039+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb2ec82a-f5e6-4450-a748-05c27f6e86cf', 'd052e4c5-a199-4165-a5be-52eece52935b', 'c', 'No tendremos obligación de llevar los dispositivos de señales acústicas prescritos de esta Regla, pero debemos ir dotados de otros medios para hacer señales acústicas eficaces.', false, '2025-09-13 13:53:13.62625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcebf262-af11-480d-b3a9-549dea5f29fa', 'd052e4c5-a199-4165-a5be-52eece52935b', 'd', 'Una campana y un pito.', false, '2025-09-13 13:53:13.626451+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42a030a2-d800-409a-97fc-b59744aa627b', 'd4e2ca7e-ebd3-437d-8b26-daf2fb747635', 'a', 'Únicamente los buques de vela.', false, '2025-09-13 13:53:13.626887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62bda02a-01f1-4c82-b750-d2adfa9a0008', 'd4e2ca7e-ebd3-437d-8b26-daf2fb747635', 'b', 'Los buques de eslora inferior a 24 metros y los buques de vela.', false, '2025-09-13 13:53:13.627109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('333db1d2-30df-45c8-b16e-a19b8d15c805', 'd4e2ca7e-ebd3-437d-8b26-daf2fb747635', 'c', 'Los buques de eslora inferior a 20 metros, los buques de vela y los buques dedicados a la pesca.', true, '2025-09-13 13:53:13.627333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de1dfa3f-dad5-4fc6-9ad8-0c108258dc25', 'd4e2ca7e-ebd3-437d-8b26-daf2fb747635', 'd', 'Únicamente los buques dedicados a la pesca y los buques de vela.', false, '2025-09-13 13:53:13.627546+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69d9771b-cbb6-422c-ab52-49caa984ce4d', 'a9ae9e00-e5c7-4f4b-9e3e-2c7e2756c22d', 'a', 'Empujando a otro, cuando forman una unidad compuesta y la longitud del conjunto es superior a', false, '2025-09-13 13:53:13.627982+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f647483-3096-4adf-bcd5-3170ae658035', 'a9ae9e00-e5c7-4f4b-9e3e-2c7e2756c22d', 'b', 'Remolcando a otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.628178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7a941a8-5d14-4d42-9599-ac430e4de05f', 'a9ae9e00-e5c7-4f4b-9e3e-2c7e2756c22d', 'c', 'Remolcando a otro, cuando la longitud del remolque es superior a 200 metros.', true, '2025-09-13 13:53:13.628395+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49a47b75-8324-4e42-ae9c-c7a1ae8d615f', 'a9ae9e00-e5c7-4f4b-9e3e-2c7e2756c22d', 'd', 'Remolcado por otro, cuando la longitud del remolque es inferior a 200 metros.', false, '2025-09-13 13:53:13.628586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('966658ed-0c55-4a9e-a65b-3a981501e912', '9a03d0f5-6c41-447a-ac39-e84172d1799f', 'a', 'Reducirá su velocidad hasta la mínima de gobierno.', false, '2025-09-13 13:53:13.629006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('33580f70-640f-40b2-9fa3-77bc1600cee4', '9a03d0f5-6c41-447a-ac39-e84172d1799f', 'b', 'Suprimirá su arrancada, si fuese necesario.', false, '2025-09-13 13:53:13.629197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b81f78ae-bda4-48ee-a63b-311ac3b5e40c', '9a03d0f5-6c41-447a-ac39-e84172d1799f', 'c', 'Navegará con extremada precaución hasta que desaparezca el peligro de abordaje.', false, '2025-09-13 13:53:13.629408+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a53a0e4-5cb7-4a8c-8514-7df79e9a4f00', '9a03d0f5-6c41-447a-ac39-e84172d1799f', 'd', 'Aumentará su velocidad hasta la máxima de gobierno para minimizar la aproximación excesiva y en ningún caso se quedará sin arrancada.', true, '2025-09-13 13:53:13.629608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4dd1e2e-04cf-451c-876b-87008157a901', 'd3aedee5-9244-4eab-8a3f-025d1e7f01c5', 'a', 'Normalmente tienen forma de castillete o espeque.', true, '2025-09-13 13:53:13.644793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b6d8df9-ae48-425e-89b2-e1ca62d35a2d', '07c84083-0876-4e13-a674-0e0b6d92384b', 'a', 'Con una frecuencia de 120 o más centelleos por minuto, a intervalos regulares.', true, '2025-09-13 13:53:13.630024+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('490ebd9d-236a-487a-b8d6-d159f6db755c', '07c84083-0876-4e13-a674-0e0b6d92384b', 'b', 'Con una frecuencia de 60 o menos centelleos por minuto, a intervalos regulares.', false, '2025-09-13 13:53:13.630231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e3de42d-d152-4afa-a2f3-731c6a67d34c', '07c84083-0876-4e13-a674-0e0b6d92384b', 'c', 'Con una duración cada centelleo de 1 segundo aproximadamente, con un intervalo entre centelleos de 1 segundo aproximadamente.', false, '2025-09-13 13:53:13.630425+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b15b143-1c7f-4490-bafc-a594d61e4ace', '07c84083-0876-4e13-a674-0e0b6d92384b', 'd', 'Con una duración cada centelleo de medio segundo aproximadamente, a intervalos irregulares.', false, '2025-09-13 13:53:13.63063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb106a55-86be-4019-b047-0a53d7ac3e47', '5d269773-26e2-43f8-bce2-f846bd975ad5', 'a', 'Buque sin gobierno.', true, '2025-09-13 13:53:13.631067+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('14f31c0c-e18a-425d-a77a-f1a18029f901', '5d269773-26e2-43f8-bce2-f846bd975ad5', 'b', 'Buque de pesca.', false, '2025-09-13 13:53:13.631303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8d554533-341e-472b-93c7-1f3a5bc6f481', '5d269773-26e2-43f8-bce2-f846bd975ad5', 'c', 'Buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.631529+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15c6e946-6daf-474d-993e-307f79bc1001', '5d269773-26e2-43f8-bce2-f846bd975ad5', 'd', 'Buque restringido por su calado.', false, '2025-09-13 13:53:13.631734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('47ac029d-a41f-4754-8808-08be89e0a112', '97a72680-c778-4e80-8ef8-50893b04018e', 'a', 'El tubo dentro del cual gira el eje del timón.', false, '2025-09-13 13:53:13.633361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b45954e-bfcb-43f4-a073-6d85c7cb84c8', '97a72680-c778-4e80-8ef8-50893b04018e', 'b', 'El eje del timón.', true, '2025-09-13 13:53:13.633557+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85d8bfde-ff85-4e24-b7b5-611a98e58b87', '97a72680-c778-4e80-8ef8-50893b04018e', 'c', 'El aparejo que se arma a cada lado de la caña del timón para gobernarlo con menos esfuerzo.', false, '2025-09-13 13:53:13.633768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('546e7016-5a5f-4b99-8a76-3c3165f4d7e2', '97a72680-c778-4e80-8ef8-50893b04018e', 'd', 'La parte plana del timón que va sumergida.', false, '2025-09-13 13:53:13.633973+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db04feda-88e7-4556-b756-972da48587ff', 'a492f895-ee18-4bef-baf0-f27b978882bb', 'a', 'Enderezarse o ponerse vertical.', false, '2025-09-13 13:53:13.634378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0481a31b-f82a-44d5-8418-49069e2b7247', 'a492f895-ee18-4bef-baf0-f27b978882bb', 'b', 'Inclinarse sobre uno de sus costados.', true, '2025-09-13 13:53:13.634574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e7040ccc-3f7c-4810-851a-71a7138b7935', 'a492f895-ee18-4bef-baf0-f27b978882bb', 'c', 'Hundir la proa y levantar la popa.', false, '2025-09-13 13:53:13.634793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3cb7c7b-531f-406b-b993-c217fb3b5e62', 'a492f895-ee18-4bef-baf0-f27b978882bb', 'd', 'Hundir la popa y levantar la proa.', false, '2025-09-13 13:53:13.634993+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06da60c0-3c67-4762-8a01-ad3fec7d719d', 'd69be177-6ae9-4c1c-a785-b7eb97ac2a46', 'a', 'El plano de crujía es aquel que divide la embarcación en la mitad de proa y en la mitad de popa.', false, '2025-09-13 13:53:13.635417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74bb192e-e6c7-4a93-9046-ce68e182e0dd', 'd69be177-6ae9-4c1c-a785-b7eb97ac2a46', 'b', 'La obra muerta es la parte sumergida de la embarcación que se separa de la obra viva por el plano de flotación.', false, '2025-09-13 13:53:13.63563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7d761ccb-bd0a-45f3-a855-f67bf585eb49', 'd69be177-6ae9-4c1c-a785-b7eb97ac2a46', 'c', 'La bañera es la cámara abierta a popa de la embarcación donde generalmente va instalada la caña o rueda del timón.', true, '2025-09-13 13:53:13.635844+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ffef2502-8f5b-42a1-9173-d32d654cffe0', 'd69be177-6ae9-4c1c-a785-b7eb97ac2a46', 'd', 'Los portillos son aberturas practicadas en los costados de la embarcación que tienen por objeto la evacuación del agua embarcada en la cubierta. Elementos de amarre y fondeo.', false, '2025-09-13 13:53:13.636035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ee09c95f-cfc3-4daa-8109-5454c7af2f92', '4a6948b4-f4ae-49e8-9634-e228a17a2e55', 'a', 'Un cabo que une y sujeta una boya a un ancla fondeada.', false, '2025-09-13 13:53:13.636456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51066b0d-7901-4a4b-bfa6-e4aacddf8487', '4a6948b4-f4ae-49e8-9634-e228a17a2e55', 'b', 'Vuelta en forma de ojo que se hace con un cabo.', true, '2025-09-13 13:53:13.63665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfa6d419-f606-4dc3-bdc9-5ffbad6c34c8', '4a6948b4-f4ae-49e8-9634-e228a17a2e55', 'c', 'Cualquiera de los dos extremos de un cabo.', false, '2025-09-13 13:53:13.636854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7555c0be-f9f0-4a93-a5c2-64b2179f66eb', '4a6948b4-f4ae-49e8-9634-e228a17a2e55', 'd', 'El arco o curvatura en un cabo cuando no está tirante o tenso.', false, '2025-09-13 13:53:13.637091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32456869-c5f6-4324-b4ef-87f3126a1b46', '1d1ef1c1-abb8-4984-899c-17571f542fe8', 'a', 'Al giro de una embarcación fondeada en torno al ancla, por efecto del viento o de la corriente, se le denomina garreo.', false, '2025-09-13 13:53:13.637513+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb3d94c9-5167-4d33-b7da-37ac74046294', '1d1ef1c1-abb8-4984-899c-17571f542fe8', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no garrea y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-13 13:53:13.63772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d6c2bf7-d2f2-4c6d-846b-aa8c6062cc6b', '1d1ef1c1-abb8-4984-899c-17571f542fe8', 'c', 'De forma general, la longitud de cadena para un fondeo con mal tiempo no será superior a una o dos veces la sonda del lugar de fondeo.', false, '2025-09-13 13:53:13.637915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1730480c-ed4e-4d2a-bb06-52c1c86dabe5', '1d1ef1c1-abb8-4984-899c-17571f542fe8', 'd', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del', false, '2025-09-13 13:53:13.638155+00');
