INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0caf89a-dce7-4bea-b6b7-6686af248b62', '903df40f-2bdc-4633-ae7f-6aae391b9128', 'c', 'Caer a estribor.', false, '2025-09-13 13:53:13.655771+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2455a8e-156b-47fc-b4b8-435605d73ee7', '903df40f-2bdc-4633-ae7f-6aae391b9128', 'd', 'Caer a babor.', false, '2025-09-13 13:53:13.655941+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('63557caa-c2a8-4706-9156-492f60511c45', 'b8c90a95-dc54-4873-914b-5999723ebacf', 'a', 'Toda clase de embarcación, incluidas las embarcaciones sin desplazamiento, las naves de vuelo rasante y los hidroaviones, utilizadas como medio de transporte sobre el agua.', true, '2025-09-13 13:53:13.656364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d25f9dde-1d0c-4fcb-bfe3-dc8f14b76f89', 'b8c90a95-dc54-4873-914b-5999723ebacf', 'b', 'Toda clase de embarcación con o sin desplazamiento, pero en ningún caso los hidroaviones, que se utilice como medio de transporte en el agua.', false, '2025-09-13 13:53:13.656575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3033988-9577-40d0-93b4-b4a36c74cb46', 'b8c90a95-dc54-4873-914b-5999723ebacf', 'd', 'Toda clase de embarcación con desplazamiento, que se utilice como medio de transporte en el agua, propulsada mecánicamente o a vela, quedando excluida todo tipo de embarcación de remo.', false, '2025-09-13 13:53:13.657003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('711fb25c-2d55-4d66-bf2d-fca207e0fc9d', '0ed2778f-c494-4473-a695-6fc2787d808d', 'a', 'Un buque de propulsión mecánica en navegación.', false, '2025-09-13 13:53:13.657435+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a0df398-f95b-4da4-ba55-d73c6950bec2', '0ed2778f-c494-4473-a695-6fc2787d808d', 'b', 'Un buque dedicado a la pesca.', true, '2025-09-13 13:53:13.657634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('833f02ad-2ec2-4802-b339-897ec1ae794b', '0ed2778f-c494-4473-a695-6fc2787d808d', 'c', 'Un hidroavión amarado.', false, '2025-09-13 13:53:13.657835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9aa304b9-753b-408a-a47c-f9a28ee3bf22', '0ed2778f-c494-4473-a695-6fc2787d808d', 'd', 'Un hidroavión volando cerca de la superficie.', false, '2025-09-13 13:53:13.658056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b7eac453-41ae-43b7-b25a-f48742353f4b', '60681402-3273-4c7b-b44d-ffeae0ac0538', 'a', 'Únicamente en la parte superior del palo dos luces todo horizonte en línea vertical, siendo blanca la superior y roja la inferior.', false, '2025-09-13 13:53:13.65846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('749075ed-ed53-4949-88d4-a133b9ecb2b8', '60681402-3273-4c7b-b44d-ffeae0ac0538', 'b', 'Las luces de costado, la luz de alcance y, además, dos luces todo horizonte en línea vertical, siendo blanca la superior y roja la inferior.', false, '2025-09-13 13:53:13.658651+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e115d0a6-0051-471f-954a-9848f0f24566', '60681402-3273-4c7b-b44d-ffeae0ac0538', 'c', 'Una luz de tope, luces de costado y una luz de alcance.', true, '2025-09-13 13:53:13.658842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a5e3d48-0d80-4cde-8c5e-a15a4315b608', '60681402-3273-4c7b-b44d-ffeae0ac0538', 'd', 'Las luces de costado, la luz de alcance y, además, dos luces todo horizonte en línea vertical, siendo roja la superior y blanca la inferior.', false, '2025-09-13 13:53:13.659043+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c3b240c-56c8-43a9-b105-f41dd22bf152', '465afe84-6604-4379-bf88-fa2cb985ae36', 'a', 'Una pitada larga complementándola necesariamente con un destello durante la duración de toda la maniobra, por ser de noche.', false, '2025-09-13 13:53:13.659426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9624c8c7-32a2-407e-88c2-6a7f4ac57787', 'bf83818b-4401-4e40-a4c6-da7c37402638', 'a', 'Nocturna, con dirección y sentido de tierra a mar.', true, '2025-09-13 13:53:13.714638+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3dcf850f-048e-41cd-a84c-19ae34141dcd', 'b8c90a95-dc54-4873-914b-5999723ebacf', 'c', 'Únicamente las embarcaciones con desplazamiento que se utilicen como medio de transporte en el agua.', false, '2025-09-13 13:53:13.656782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c33117ff-136e-4c60-bdf6-896de8a47a14', '857b6af9-3338-4735-bafe-13747af4c870', 'd', 'Opuestos por sus vértices.', false, '2025-09-13 13:53:13.649694+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d66622a0-0f76-495a-9c00-b37bd6b47064', '51e532c3-e653-4a03-873b-1f757010c53c', 'b', 'Embarcación dedicada a la pesca, que no sea de arrastre, cuyo aparejo se extiende más.', true, '2025-09-13 13:53:13.652427+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('31651cd0-3c46-4d1f-96b3-fcd50fa7c740', '465afe84-6604-4379-bf88-fa2cb985ae36', 'c', 'Una pitada corta pudiéndola completar con un destello durante la duración de toda la maniobra.', true, '2025-09-13 13:53:13.659835+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc2a59a0-1167-44da-8044-62c104df07ae', '9155edd2-1f84-489d-922b-305a0a0567eb', 'a', 'Fase de deriva, fase variable y fase alterna.', false, '2025-09-13 13:53:13.660385+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d58efd7d-d4da-4743-9b98-6f0d6023bcea', '9155edd2-1f84-489d-922b-305a0a0567eb', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:13.660598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('81a6c656-440f-401b-a38f-d6e1dbfb727b', '9155edd2-1f84-489d-922b-305a0a0567eb', 'c', 'Fase de maniobra, fase de abatimiento y fase alterna.', false, '2025-09-13 13:53:13.660848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb6f72b0-c3e9-4945-934f-f3cf2285162c', '9155edd2-1f84-489d-922b-305a0a0567eb', 'd', 'Fase de deriva, fase de abatimiento y fase uniforme.', false, '2025-09-13 13:53:13.661035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8bddebdd-393b-4229-b9de-e7c2fb7e537a', 'a6aeb499-142c-4966-a4b2-2f4bcea9565b', 'a', 'Paso 1: Largar amarras excepto el largo de proa, timón a babor y poca atrás. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.661474+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('497b52b9-7c9d-4d71-aea4-285df234fd8b', 'a6aeb499-142c-4966-a4b2-2f4bcea9565b', 'b', 'Paso 1: Largar amarras excepto el esprín de proa, timón a estribor y poca avante. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.661677+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a15e88e-04db-41a6-ba4c-9d6012fee68e', 'a6aeb499-142c-4966-a4b2-2f4bcea9565b', 'c', 'Paso 1: Largar todo, timón a estribor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', true, '2025-09-13 13:53:13.661872+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('682990c6-71ad-4d26-8ed7-3388e5d51420', 'a6aeb499-142c-4966-a4b2-2f4bcea9565b', 'd', 'Paso 1: Largar todo, timón a babor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida. Emergencias en la mar.', false, '2025-09-13 13:53:13.662097+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c446634f-91ca-4dc4-9b9c-13ca4633e809', 'cc73ece7-c55d-4829-b9fb-a5056cd1af19', 'a', 'La responsabilidad recae siempre en la embarcación que navegue a mayor velocidad.', false, '2025-09-13 13:53:13.662504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1be8b234-1b42-4639-8276-4c051611be9c', 'cc73ece7-c55d-4829-b9fb-a5056cd1af19', 'b', 'La prioridad absoluta es elaborar parte amistoso y dar traslado de toda la información que figure en nuestro seguro, siempre que nos la solicite la parte contraria.', false, '2025-09-13 13:53:13.662695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7e87b897-2d92-4136-87fb-7ddd6c6618aa', 'cc73ece7-c55d-4829-b9fb-a5056cd1af19', 'c', 'Solamente en ciertos casos una vía de agua producirá un aumento del calado, por lo que no debe preocuparnos hasta haber completado el parte amistoso.', false, '2025-09-13 13:53:13.662923+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9916480-acf8-4ff5-9c98-b379d8295ec7', 'cc73ece7-c55d-4829-b9fb-a5056cd1af19', 'd', 'La evaluación de las averías sufridas y asistencia a las personas que puedan encontrarse heridas debe realizarse a la mayor brevedad posible.', true, '2025-09-13 13:53:13.663118+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('83f9879e-b44d-4306-aa87-b8aa31984a56', 'f383ec0d-fbaf-408a-a4da-5bad07100e49', 'a', 'En caso de producirse una quemadura, recorte la ampolla, limpie la quemadura y cúbrala con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.663523+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43900e9d-6003-43f8-9afc-898949d15fc9', 'f383ec0d-fbaf-408a-a4da-5bad07100e49', 'b', 'Ante una hemorragia externa, en una zona compresible y sin síntomas de hipotermia, comprima fuertemente con la mano sobre gasas limpias al menos 4 o 5 minutos, pudiendo aplicar posteriormente un vendaje compresivo.', true, '2025-09-13 13:53:13.663719+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2c0d8d26-bf39-4f35-bcf7-d17c19a53234', 'f383ec0d-fbaf-408a-a4da-5bad07100e49', 'c', 'Si se presenta una herida leve, alargada y profunda, limpie la herida con agua y jabón, frotando con un algodón, séquela con una gasa aplicando un antiséptico y tapónela con un apósito autoadhesivo estéril.', false, '2025-09-13 13:53:13.663938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e1ea7703-8e69-4abd-b910-e53fa1d578b8', 'f383ec0d-fbaf-408a-a4da-5bad07100e49', 'd', 'En caso de sufrir un golpe de calor, sitúe al afectado en un lugar fresco, seco y bien ventilado, quítele la ropa y enfríelo mediante paños de agua fría hasta que la temperatura corporal alcance los 37,5º C, administrándole al tiempo una bebida estimulante.', false, '2025-09-13 13:53:13.66416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bea2c124-8603-4e68-8879-41b80c544752', 'a5d05a3b-caa7-494a-9140-29fc273feeae', 'a', 'Nocturna, con dirección y sentido de tierra a mar.', true, '2025-09-13 13:53:13.665621+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dab21bc4-072a-4e9d-9fa0-27ee7823ef49', 'a5d05a3b-caa7-494a-9140-29fc273feeae', 'b', 'Diurna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.66583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f38db797-cbc8-4ff2-a7ff-e077723bf498', 'a5d05a3b-caa7-494a-9140-29fc273feeae', 'c', 'Diurna, con dirección y sentido de tierra a mar.', false, '2025-09-13 13:53:13.666054+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('515a875a-d4e7-4a5b-aa7e-7476c641b565', 'a5d05a3b-caa7-494a-9140-29fc273feeae', 'd', 'Nocturna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.66626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bad3cb28-7218-43c2-90a3-418d3b90744d', '473c81c0-f7a0-44d0-b553-d8ac1bf0d0ff', 'a', 'La temperatura de fusión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.666659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f454067-1a85-4930-a3f7-9d85b96c3086', '473c81c0-f7a0-44d0-b553-d8ac1bf0d0ff', 'b', 'La temperatura de fusión del hielo y la temperatura de congelación del agua al nivel del mar.', false, '2025-09-13 13:53:13.666867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca6fda1f-1786-4554-9192-46adddf3bb90', '473c81c0-f7a0-44d0-b553-d8ac1bf0d0ff', 'c', 'La temperatura de fusión del hielo y la temperatura de ebullición del agua al nivel del mar.', true, '2025-09-13 13:53:13.667065+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b034f8d-62de-4286-87e6-36b6c26c3d17', '473c81c0-f7a0-44d0-b553-d8ac1bf0d0ff', 'd', 'La temperatura de fisión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.667245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a14b9ca3-0816-426a-83ac-cbfa91ba1050', '630e49eb-4d81-4f39-8100-8052869c8176', 'a', 'Se puede determinar empleando solamente la escala Beaufort ya que tienen el mismo sistema de medida (velocidad).', false, '2025-09-13 13:53:13.668713+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f747e534-5b90-4784-aa8c-0e7ab070e6bd', '630e49eb-4d81-4f39-8100-8052869c8176', 'b', 'Es el número de horas que ha soplado el aire en una misma dirección.', false, '2025-09-13 13:53:13.668915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd0b8087-c93c-431a-aa0d-3788e85639f3', '630e49eb-4d81-4f39-8100-8052869c8176', 'c', 'Es un incremento brusco en la intensidad del viento.', false, '2025-09-13 13:53:13.669111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd653fe8-c7e4-4b2e-87a7-3d875df36d41', '630e49eb-4d81-4f39-8100-8052869c8176', 'd', 'Es la extensión o alcance que tienen el viento sobre la mar con una dirección y fuerza constantes. Teoría de la navegación.', true, '2025-09-13 13:53:13.669324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a3cbbf72-c54d-4e63-9a50-d61bea146f06', '137e83ed-3a50-4ada-9111-c6614a81edf8', 'a', 'Es un círculo menor paralelo al ecuador.', true, '2025-09-13 13:53:13.669716+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b6949d4-d7b3-4599-b073-61f8361f3d09', '137e83ed-3a50-4ada-9111-c6614a81edf8', 'b', 'Es un círculo máximo perpendicular al eje de la tierra.', false, '2025-09-13 13:53:13.66991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('18bfd698-d3c7-4bce-b7a2-361fa36baf52', '137e83ed-3a50-4ada-9111-c6614a81edf8', 'c', 'En un círculo máximo que pasa por los polos.', false, '2025-09-13 13:53:13.670125+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9449235e-3955-43e7-afe4-60867eeab4b8', '137e83ed-3a50-4ada-9111-c6614a81edf8', 'd', 'En un círculo menor paralelo al eje de la tierra.', false, '2025-09-13 13:53:13.670332+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e860253-ff7f-4da6-a352-b3547620f815', 'fb2c9c91-fe44-4260-a2f8-4ad3fc5b8d78', 'b', 'De 0º a 360º desde la proa en sentido contrario a las agujas del reloj, en cuyo caso su signo siempre es positivo.', false, '2025-09-13 13:53:13.670947+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3c5e5d5d-604b-44a7-8e57-8d2cb89722f3', 'fb2c9c91-fe44-4260-a2f8-4ad3fc5b8d78', 'c', 'De 0º a 180º, por cada banda, a partir de la proa, considerándose positivas las tomadas por babor y negativas las tomadas por estribor.', false, '2025-09-13 13:53:13.671152+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('51e1704a-87cd-435c-b2e9-02ac19ae1b3a', 'fb2c9c91-fe44-4260-a2f8-4ad3fc5b8d78', 'a', 'A partir de la proa, de 0º a 360º en el sentido de las agujas del reloj o de 0º a 180º por cada banda.', true, '2025-09-13 13:53:13.670744+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('70e6fdb2-b492-4337-a778-7f1cfb3ace12', '465afe84-6604-4379-bf88-fa2cb985ae36', 'b', 'Una pitada corta complementándola obligatoriamente con un destello durante la duración de toda la maniobra.', false, '2025-09-13 13:53:13.659648+00');
