INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6c59bb4e-b620-4986-bef2-fd8396decd0f', '524355d8-0b15-456c-abce-9b757e00893d', 'd', 'Una señal emitida por radiotelefonía consistente en la palabra "Securité".', false, '2025-09-13 13:53:13.705952+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('86cf8837-7af6-4dd7-af65-3fc2ce6a24e2', 'a89d7cee-ed7f-4c68-be06-1e9ad570707b', 'a', 'Paso 1: Largar amarras excepto el largo de proa, timón a babor y poca atrás. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.707403+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d91f6997-a32d-4a82-9414-d3843a7baf9a', 'a89d7cee-ed7f-4c68-be06-1e9ad570707b', 'b', 'Paso 1: Largar amarras excepto el esprín de proa, timón a estribor y poca avante. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.707616+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('451a9459-cffd-4990-a275-c1611d9f8927', 'a89d7cee-ed7f-4c68-be06-1e9ad570707b', 'c', 'Paso 1: Largar todo, timón a estribor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', true, '2025-09-13 13:53:13.70781+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('081db91d-52d3-492f-998b-622ceda25e58', 'a89d7cee-ed7f-4c68-be06-1e9ad570707b', 'd', 'Paso 1: Largar todo, timón a babor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', false, '2025-09-13 13:53:13.708017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce2cbc6f-d722-4147-bacf-b935c1cff0b1', 'adf05916-d645-4b5f-9f70-28fe725116aa', 'a', 'Fase de deriva, fase variable y fase alterna.', false, '2025-09-13 13:53:13.708412+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad3bf687-c9a4-438f-b214-0bc7118c7526', 'adf05916-d645-4b5f-9f70-28fe725116aa', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:13.708625+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2b48f70-464f-4a7e-ba94-ec119d837554', 'adf05916-d645-4b5f-9f70-28fe725116aa', 'c', 'Fase de maniobra, fase de abatimiento y fase alterna.', false, '2025-09-13 13:53:13.708832+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cae9bd23-228a-46f3-aafc-d34ca06e0203', '0cc7f376-3b07-46b5-9841-2022fcabf180', 'a', 'Atacaremos el fuego por la base de las llamas y nos aproximaremos siempre mirando al fuego.', false, '2025-09-13 13:53:13.709441+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f43bc40c-f5bd-4485-b256-2b4f650df39b', '0cc7f376-3b07-46b5-9841-2022fcabf180', 'b', 'Si existe corriente de aire nos aproximaremos con ésta a nuestra espalda.', false, '2025-09-13 13:53:13.709633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('efd6e099-97b4-4f11-a3bb-fbc11723f817', '0cc7f376-3b07-46b5-9841-2022fcabf180', 'c', 'Utilizaremos como agente extintor el polvo seco.', false, '2025-09-13 13:53:13.709834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('359bf3b4-14df-4846-a04e-b0864b56ab5f', '0cc7f376-3b07-46b5-9841-2022fcabf180', 'd', 'Posicionaremos la embarcación de forma que el foco principal del incendio quede a barlovento para evitar la propagación del fuego.', true, '2025-09-13 13:53:13.710035+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a85be40-6bd5-456a-853a-33e5f91c105d', 'f7a17391-8dd9-4073-a991-6fc1e183937d', 'a', 'En caso de producirse una quemadura, recorte la ampolla, limpie la quemadura y cúbrala con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.710459+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ddf28fd-e352-42e1-a5aa-06f19e0bcc06', 'f7a17391-8dd9-4073-a991-6fc1e183937d', 'b', 'Ante una hemorragia externa, en una zona compresible y sin síntomas de hipotermia, comprima fuertemente con la mano sobre gasas limpias al menos 4 o 5 minutos, pudiendo aplicar posteriormente un vendaje compresivo.', true, '2025-09-13 13:53:13.71066+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f7842158-632a-41f3-9cc6-f57d4531d3fc', 'f7a17391-8dd9-4073-a991-6fc1e183937d', 'c', 'Si se presenta una herida leve, alargada y profunda, limpie la herida con agua y jabón, frotando con un algodón, séquela con una gasa aplicando un antiséptico y tapónela con un apósito autoadhesivo estéril.', false, '2025-09-13 13:53:13.710859+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02fc19c8-3657-452c-9866-d00435f36f8b', 'f7a17391-8dd9-4073-a991-6fc1e183937d', 'd', 'En caso de sufrir un golpe de calor, sitúe al afectado en un lugar fresco, seco y bien ventilado, quítele la ropa y enfríelo mediante paños de agua fría hasta que la temperatura corporal alcance los 37,5º C, administrándole al tiempo una bebida estimulante.', false, '2025-09-13 13:53:13.711048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('687f6951-eebf-4fd9-8acd-a8d677129c2b', '9dc7f518-3d2a-4b78-8ba9-c5e145c72f30', 'a', 'La responsabilidad recae siempre en la embarcación que navegue a mayor velocidad.', false, '2025-09-13 13:53:13.711443+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db1c2945-7df8-4c8c-bbde-ea940b07f7e5', '9dc7f518-3d2a-4b78-8ba9-c5e145c72f30', 'b', 'La prioridad absoluta es elaborar parte amistoso y dar traslado de toda la información que figure en nuestro seguro, siempre que nos la solicite la parte contraria.', false, '2025-09-13 13:53:13.711652+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c06ccbb-b68e-476e-81f4-c290cf3267f4', '9dc7f518-3d2a-4b78-8ba9-c5e145c72f30', 'c', 'Solamente en ciertos casos una vía de agua producirá un aumento del calado, por lo que no debe preocuparnos hasta haber completado el parte amistoso.', false, '2025-09-13 13:53:13.71184+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0cd73221-458d-4de6-b40c-0afa4f3cd66c', '9dc7f518-3d2a-4b78-8ba9-c5e145c72f30', 'd', 'La evaluación de las averías sufridas y asistencia a las personas que puedan encontrarse heridas debe realizarse a la mayor brevedad posible. Meteorología', true, '2025-09-13 13:53:13.712038+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe061c16-1d15-45ad-9eb6-3dadad522146', 'a07692f7-196e-4aac-8eda-8d1f823c1a10', 'a', 'La temperatura de fusión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.712475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('24eb6533-9cad-4d37-a2fb-166d907b38aa', 'a07692f7-196e-4aac-8eda-8d1f823c1a10', 'b', 'La temperatura de fusión del hielo y la temperatura de congelación del agua al nivel del mar.', false, '2025-09-13 13:53:13.712695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9741a8f8-ca33-4a1b-9609-38e3d3d9a697', 'a07692f7-196e-4aac-8eda-8d1f823c1a10', 'c', 'La temperatura de fusión del hielo y la temperatura de ebullición del agua al nivel del mar.', true, '2025-09-13 13:53:13.712927+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6022589b-ae06-46dd-814e-3a078d11bba1', 'a07692f7-196e-4aac-8eda-8d1f823c1a10', 'd', 'La temperatura de fisión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.71314+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('951c05ff-f25c-4240-b800-be20f5149afb', 'c05f3734-5035-452b-97df-b6a1353ffa68', 'a', 'Sí, siempre y cuando ésta haya sido emitida en formato LSD en el canal 9 por un usuario con autorización emitida por la Comunidad Autónoma correspondiente.', false, '2025-09-13 13:53:13.71359+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('03f84f8f-cd04-44d9-8aa9-9b79f3ac2121', 'c05f3734-5035-452b-97df-b6a1353ffa68', 'b', 'No, debe ser emitida en formato papel, a través de la AEMET.', false, '2025-09-13 13:53:13.713797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b5df1bf-aa83-45cf-8c54-f544e4a7b26a', 'c05f3734-5035-452b-97df-b6a1353ffa68', 'd', 'Sí, pero para ser válida ésta debe ser recibida expresamente por NAVTEX.', false, '2025-09-13 13:53:13.714202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('438a5b3b-fda1-420a-a0af-8f97c58bf4a5', '524355d8-0b15-456c-abce-9b757e00893d', 'b', 'Una señal emitida por cualquier sistema de señales consistente en el grupo ---… --- del Código Morse.', false, '2025-09-13 13:53:13.705525+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08b7ba70-ade1-4eff-9d3a-4abe2edef9fe', 'c05f3734-5035-452b-97df-b6a1353ffa68', 'c', 'Sí, pero la transmisión debe ser emitida por un Centro de Salvamento Marítimo o Estación Radiocostera.', true, '2025-09-13 13:53:13.714001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c56a6620-0755-430a-8bf5-60c962d16538', 'adf05916-d645-4b5f-9f70-28fe725116aa', 'd', 'Fase de deriva, fase de abatimiento y fase uniforme.', false, '2025-09-13 13:53:13.709044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9b43df24-974f-4d7b-bebe-c73083805c52', 'de722f1c-068e-401e-b1eb-eebdadc38bd0', 'b', 'Una pitada corta complementándola obligatoriamente con un destello durante la duración de toda la maniobra.', false, '2025-09-13 13:53:13.704512+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af0eaab2-59e4-46b7-9da9-b65158fec440', 'bf83818b-4401-4e40-a4c6-da7c37402638', 'b', 'Diurna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.714834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('720590a3-e9d0-4b16-b53a-2dc88148d0c8', 'bf83818b-4401-4e40-a4c6-da7c37402638', 'c', 'Diurna, con dirección y sentido de tierra a mar.', false, '2025-09-13 13:53:13.715016+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('06abbcb2-87d7-457e-819d-dd4e6aad8143', 'bf83818b-4401-4e40-a4c6-da7c37402638', 'd', 'Nocturna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.71522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c20a582e-8191-4d29-bf06-410ea782eafa', '4257bd2f-b07a-44c5-8731-cdac4c87d4eb', 'a', 'Se puede determinar empleando solamente la escala Beaufort ya que tienen el mismo sistema de medida (velocidad).', false, '2025-09-13 13:53:13.71565+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16b3d4e1-b3e2-450f-8a83-afd43dbf5429', '4257bd2f-b07a-44c5-8731-cdac4c87d4eb', 'b', 'Es el número de horas que ha soplado el aire en una misma dirección.', false, '2025-09-13 13:53:13.715861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ed32027-f8fd-4141-b4ca-abf9afe0381c', '4257bd2f-b07a-44c5-8731-cdac4c87d4eb', 'c', 'Es un incremento brusco en la intensidad del viento.', false, '2025-09-13 13:53:13.716073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00bdbc26-9c0d-430f-9c18-1273a9284533', '4257bd2f-b07a-44c5-8731-cdac4c87d4eb', 'd', 'Es la extensión o alcance que tienen el viento sobre la mar con una dirección y fuerza constantes. Teoría de la navegación.', true, '2025-09-13 13:53:13.716274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a2c3159-8efb-4471-866b-0958390716d7', 'e596c3bb-8dcb-4028-a264-962912bfe34d', 'b', 'De 0º a 360º desde la proa en sentido contrario a las agujas del reloj, en cuyo caso su signo siempre es positivo.', false, '2025-09-13 13:53:13.716963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6151f27b-0662-43e0-b0a3-72b0bd74c0d3', 'e596c3bb-8dcb-4028-a264-962912bfe34d', 'c', 'De 0º a 180º, por cada banda, a partir de la proa, considerándose positivas las tomadas por babor y negativas las tomadas por estribor.', false, '2025-09-13 13:53:13.717182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e8f6ba74-2b6c-4036-a569-3b41348c5965', 'e596c3bb-8dcb-4028-a264-962912bfe34d', 'd', 'A partir del Norte, de 0º a 360º en el sentido de las agujas del reloj, teniendo la ventaja de que su signo siempre será positivo.', false, '2025-09-13 13:53:13.717404+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3af422a0-a018-41c6-9c41-ec506069fb7a', 'f4bad8d4-d317-4dee-88c3-c78a150f71fd', 'a', 'Es un círculo menor paralelo al ecuador.', true, '2025-09-13 13:53:13.717822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ebad6ac-3248-4ccd-ac8d-80210eabaa01', 'f4bad8d4-d317-4dee-88c3-c78a150f71fd', 'b', 'Es un círculo máximo perpendicular al eje de la tierra.', false, '2025-09-13 13:53:13.718027+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc6df98d-5e33-4487-add2-11872db328b8', 'f4bad8d4-d317-4dee-88c3-c78a150f71fd', 'c', 'En un círculo máximo que pasa por los polos.', false, '2025-09-13 13:53:13.718231+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bbbe3495-63c4-40ea-987c-fbf2667a73f5', 'f4bad8d4-d317-4dee-88c3-c78a150f71fd', 'd', 'En un círculo menor paralelo al eje de la tierra.', false, '2025-09-13 13:53:13.718455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d40091b9-7f96-46db-9d7f-73e19f2e5a65', '5c15ab8a-94af-44dd-a7f2-038047835fbd', 'a', 'Desvío.', false, '2025-09-13 13:53:13.718856+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6ddda66-564e-4826-a043-899e25a53a26', '5c15ab8a-94af-44dd-a7f2-038047835fbd', 'b', 'Corrección total.', false, '2025-09-13 13:53:13.719056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d9bffb49-d860-42b0-baeb-318519fc977e', '5c15ab8a-94af-44dd-a7f2-038047835fbd', 'c', 'Declinación magnética.', true, '2025-09-13 13:53:13.719264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('075d61d0-2da2-4494-8418-f6c83d2f66d6', '5c15ab8a-94af-44dd-a7f2-038047835fbd', 'd', 'Demora.', false, '2025-09-13 13:53:13.719475+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9076d7ef-922c-452c-86ed-b6ccd5570bf3', '84bc26de-dd0f-4c06-882d-a7e38768292e', 'a', 'Un viento en calma y una presión atmosférica de 998 mbar.', false, '2025-09-13 13:53:13.720945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('78228613-d8e2-4450-8bf3-81afce775977', '84bc26de-dd0f-4c06-882d-a7e38768292e', 'b', 'Un viento que sopla de la mar hacia tierra y una presión atmosférica de 993 mbar.', false, '2025-09-13 13:53:13.721147+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4724275-7669-4563-9354-0bde8f944c32', '84bc26de-dd0f-4c06-882d-a7e38768292e', 'c', 'Un viento en calma y una presión atmosférica de 1.013 mbar.', false, '2025-09-13 13:53:13.721353+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5979ebc0-6ca3-4fe3-b533-afa977ba4101', '84bc26de-dd0f-4c06-882d-a7e38768292e', 'd', 'Un viento que sopla de tierra hacia la mar y una presión atmosférica de 1.028 mbar. Carta de navegación.', true, '2025-09-13 13:53:13.721569+00');
