INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0d8fd349-a6ba-488d-afd1-7352c34ca516', '022b3caf-a1af-487a-b3c9-c46264683bc1', 'c', '8,56 m.', true, '2025-09-13 13:53:13.725572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cddb1305-eab3-4d9d-954f-e04d3d0cf0a7', '022b3caf-a1af-487a-b3c9-c46264683bc1', 'd', '8,22 m. DE TRANSPORTES, Y MOVILIDAD SOSTENIBLE                                                                            DE TRANSPORTES AÉREO Y MARÍTIMO (Con PNB Liberado) Código de Test 01 Maniobra y navegación.', false, '2025-09-13 13:53:13.725756+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('37132981-0bb4-45f5-9852-c65ced17db7b', '45cfbfed-dfca-4fac-8d8f-f2d3de839913', 'a', 'Fase de deriva, fase variable y fase alterna.', false, '2025-09-13 13:53:13.726362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4bf062e2-8e69-4c35-bb9d-42f22848a202', '45cfbfed-dfca-4fac-8d8f-f2d3de839913', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:13.726555+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1f39858-e77b-4178-a864-b70899cd3365', '45cfbfed-dfca-4fac-8d8f-f2d3de839913', 'c', 'Fase de maniobra, fase de abatimiento y fase alterna.', false, '2025-09-13 13:53:13.726772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dd649ed9-f969-4469-8a26-e19e78920728', '45cfbfed-dfca-4fac-8d8f-f2d3de839913', 'd', 'Fase de deriva, fase de abatimiento y fase uniforme.', false, '2025-09-13 13:53:13.726977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ae29b3ee-b4f7-411a-a7dc-0cf6f71edff0', 'de70a0de-9460-47af-9991-0aa62052fa49', 'a', 'Paso 1: Largar amarras excepto el largo de proa, timón a babor y poca atrás. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.72739+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bbf2239-d347-4987-94b5-a669fb5ba77a', 'de70a0de-9460-47af-9991-0aa62052fa49', 'b', 'Paso 1: Largar amarras excepto el esprín de proa, timón a estribor y poca avante. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.727591+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e10e098-4d5f-4ed9-9c3d-dd08fd8373e2', 'de70a0de-9460-47af-9991-0aa62052fa49', 'c', 'Paso 1: Largar todo, timón a estribor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', true, '2025-09-13 13:53:13.727818+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('febf3da1-7ea7-4bf3-b51e-c558ab179f91', 'de70a0de-9460-47af-9991-0aa62052fa49', 'd', 'Paso 1: Largar todo, timón a babor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida. Emergencias en la mar.', false, '2025-09-13 13:53:13.728017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0776b2a-f530-49a8-9aa0-4ce5b8bf0b52', '44475688-ada3-4a86-b049-bfc7af918f58', 'a', 'La responsabilidad recae siempre en la embarcación que navegue a mayor velocidad.', false, '2025-09-13 13:53:13.728423+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('65c2b220-0037-4cf9-aafd-d0ae2ada9ed3', '44475688-ada3-4a86-b049-bfc7af918f58', 'b', 'La prioridad absoluta es elaborar parte amistoso y dar traslado de toda la información que figure en nuestro seguro, siempre que nos la solicite la parte contraria.', false, '2025-09-13 13:53:13.728626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca47d636-bcdd-4c05-8aae-34b434b42b9d', '44475688-ada3-4a86-b049-bfc7af918f58', 'c', 'Solamente en ciertos casos una vía de agua producirá un aumento del calado, por lo que no debe preocuparnos hasta haber completado el parte amistoso.', false, '2025-09-13 13:53:13.728829+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75ffc1b3-e42e-4e31-b849-f3db32c26948', '44475688-ada3-4a86-b049-bfc7af918f58', 'd', 'La evaluación de las averías sufridas y asistencia a las personas que puedan encontrarse heridas debe realizarse a la mayor brevedad posible.', true, '2025-09-13 13:53:13.729051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d042bab-d7f3-42ab-a243-0a85274a5475', '9b0b80b4-9cb2-40ef-9c7d-76d2ce983646', 'a', 'En caso de producirse una quemadura, recorte la ampolla, limpie la quemadura y cúbrala con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.72945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41830ac8-ea45-425c-8b85-8abb77f532d7', '1e1c16ab-5997-4bc1-8518-515f956901cf', 'c', '8,56 m.', true, '2025-09-13 13:53:13.7444+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8ef1680b-2a52-4e40-9cf4-24a8162a3818', 'b7b7a84e-24cf-46bf-92f2-48d3fc237821', 'b', 'Corrección total.', false, '2025-09-13 13:53:13.756767+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0b29cab-21b2-4a55-940a-e1b0bf218bd2', 'e596c3bb-8dcb-4028-a264-962912bfe34d', 'a', 'A partir de la proa, de 0º a 360º en el sentido de las agujas del reloj o de 0º a 180º por cada banda.', true, '2025-09-13 13:53:13.716725+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fb20114-343c-41ea-97fe-21f898c3c033', '9b0b80b4-9cb2-40ef-9c7d-76d2ce983646', 'b', 'Ante una hemorragia externa, en una zona compresible y sin síntomas de hipotermia, comprima fuertemente con la mano sobre gasas limpias al menos 4 o 5 minutos, pudiendo aplicar posteriormente un vendaje compresivo.', true, '2025-09-13 13:53:13.729659+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('26cd7e27-5a90-4094-bd8c-b7153eac48bc', '9b0b80b4-9cb2-40ef-9c7d-76d2ce983646', 'c', 'Si se presenta una herida leve, alargada y profunda, limpie la herida con agua y jabón, frotando con un algodón, séquela con una gasa aplicando un antiséptico y tapónela con un apósito autoadhesivo estéril.', false, '2025-09-13 13:53:13.729884+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc0be126-368a-4ddd-b228-e77643e63362', '9b0b80b4-9cb2-40ef-9c7d-76d2ce983646', 'd', 'En caso de sufrir un golpe de calor, sitúe al afectado en un lugar fresco, seco y bien ventilado, quítele la ropa y enfríelo mediante paños de agua fría hasta que la temperatura corporal alcance los 37,5º C, administrándole al tiempo una bebida estimulante.', false, '2025-09-13 13:53:13.7301+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b8c2529c-e555-471c-af51-a667b6ea78d3', 'd6d81351-936f-4573-94d8-cf434d31cb56', 'a', 'Nocturna, con dirección y sentido de tierra a mar.', true, '2025-09-13 13:53:13.731556+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75679d7a-1430-41bb-90da-a8e6aefa3a53', 'd6d81351-936f-4573-94d8-cf434d31cb56', 'b', 'Diurna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.731768+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ad56e865-7249-48d9-929e-b17afe275a19', 'd6d81351-936f-4573-94d8-cf434d31cb56', 'c', 'Diurna, con dirección y sentido de tierra a mar.', false, '2025-09-13 13:53:13.731972+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ffbe98d-4451-4156-bb31-e60181c5593b', 'd6d81351-936f-4573-94d8-cf434d31cb56', 'd', 'Nocturna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.732178+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5932d687-8e83-44c2-9c84-bb6f5fc2646d', 'be83a141-a63d-4858-80dd-a9c05a5f1908', 'a', 'La temperatura de fusión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.732579+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2decf87-896b-4e03-b051-10aff997751a', 'be83a141-a63d-4858-80dd-a9c05a5f1908', 'b', 'La temperatura de fusión del hielo y la temperatura de congelación del agua al nivel del mar.', false, '2025-09-13 13:53:13.732776+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7286c04f-2608-42d3-9473-dc0f28f80b1f', 'be83a141-a63d-4858-80dd-a9c05a5f1908', 'c', 'La temperatura de fusión del hielo y la temperatura de ebullición del agua al nivel del mar.', true, '2025-09-13 13:53:13.732979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9746e002-d36c-49fb-95d9-c7172d9d3210', 'be83a141-a63d-4858-80dd-a9c05a5f1908', 'd', 'La temperatura de fisión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.733182+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3aa79084-eb78-47b0-b686-b48259a966d2', '28fcc8b0-3340-4624-ad1e-ad5e6f3bfe77', 'a', 'Sí, siempre y cuando ésta haya sido emitida en formato LSD en el canal 9 por un usuario con autorización emitida por la Comunidad Autónoma correspondiente.', false, '2025-09-13 13:53:13.733608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('840e4463-62f4-4626-8323-7b12aa37f8af', '28fcc8b0-3340-4624-ad1e-ad5e6f3bfe77', 'b', 'No, debe ser emitida en formato papel, a través de la AEMET.', false, '2025-09-13 13:53:13.733793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa09ae63-df34-405c-85f0-2faae7920536', '28fcc8b0-3340-4624-ad1e-ad5e6f3bfe77', 'd', 'Sí, pero para ser válida ésta debe ser recibida expresamente por NAVTEX.', false, '2025-09-13 13:53:13.734198+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a8a6392-89e7-4f17-ab1c-3ec7ed52a387', '39f3f6a2-3628-41f0-8710-2dcdb4813ba0', 'a', 'Se puede determinar empleando solamente la escala Beaufort ya que tienen el mismo sistema de medida (velocidad).', false, '2025-09-13 13:53:13.734626+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc5545d1-ab9a-4298-9c34-20db79bb5e6b', '39f3f6a2-3628-41f0-8710-2dcdb4813ba0', 'b', 'Es el número de horas que ha soplado el aire en una misma dirección.', false, '2025-09-13 13:53:13.734823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc78f8de-1d99-49b6-822a-0436fc8afbc1', '39f3f6a2-3628-41f0-8710-2dcdb4813ba0', 'c', 'Es un incremento brusco en la intensidad del viento.', false, '2025-09-13 13:53:13.735028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca76fdf9-448e-4d8b-ab7f-0eea98f040bb', '39f3f6a2-3628-41f0-8710-2dcdb4813ba0', 'd', 'Es la extensión o alcance que tienen el viento sobre la mar con una dirección y fuerza constantes. Teoría de la navegación.', true, '2025-09-13 13:53:13.735251+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('343c1190-e955-4b77-9702-3d65246addba', '4d2b80ca-27c1-4e3b-b552-fecffefdb119', 'a', 'Es un círculo menor paralelo al ecuador.', true, '2025-09-13 13:53:13.735671+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1951a3e-5fa2-40b5-945a-076a8bb2ebda', '4d2b80ca-27c1-4e3b-b552-fecffefdb119', 'b', 'Es un círculo máximo perpendicular al eje de la tierra.', false, '2025-09-13 13:53:13.735882+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('99c5349e-c64a-4c5d-b3d9-5f184185cbd1', '4d2b80ca-27c1-4e3b-b552-fecffefdb119', 'c', 'En un círculo máximo que pasa por los polos.', false, '2025-09-13 13:53:13.736113+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76410a86-7da1-49a3-925c-015df27136b7', '4d2b80ca-27c1-4e3b-b552-fecffefdb119', 'd', 'En un círculo menor paralelo al eje de la tierra.', false, '2025-09-13 13:53:13.736339+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67be01de-15d5-4eb3-a014-90ec946f54f3', '893e2d9b-3107-4160-82b2-086f232d22a1', 'b', 'De 0º a 360º desde la proa en sentido contrario a las agujas del reloj, en cuyo caso su signo siempre es positivo.', false, '2025-09-13 13:53:13.736986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02a7c3cf-46c3-40a1-8de3-a07a5046a8a5', '893e2d9b-3107-4160-82b2-086f232d22a1', 'c', 'De 0º a 180º, por cada banda, a partir de la proa, considerándose positivas las tomadas por babor y negativas las tomadas por estribor.', false, '2025-09-13 13:53:13.737197+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aaa8f242-7487-4abf-98ce-aa974282471f', '893e2d9b-3107-4160-82b2-086f232d22a1', 'd', 'A partir del Norte, de 0º a 360º en el sentido de las agujas del reloj, teniendo la ventaja de que su signo siempre será positivo.', false, '2025-09-13 13:53:13.737407+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ceeee5f7-a035-401d-bccc-2304b841ecf8', '87390beb-cba8-4364-baeb-4ea58eb52113', 'a', '15º (+).', false, '2025-09-13 13:53:13.737827+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dcd16651-5159-4fbc-a08f-5a5dca2c7150', '87390beb-cba8-4364-baeb-4ea58eb52113', 'b', '7º (­).', true, '2025-09-13 13:53:13.738001+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1e9ac07f-adf2-4432-894b-589989c3d9c9', '87390beb-cba8-4364-baeb-4ea58eb52113', 'c', '7º (+).', false, '2025-09-13 13:53:13.73819+00');
