INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d1d5cd20-2686-4624-9372-be1bb791510c', '4a704bfd-3d5c-43e5-bca9-eb993fdc595b', 'a', 'Ra= 256º; Hrb= 13:30.', true, '2025-09-13 13:53:13.742963+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d95404c6-ba86-4d17-8310-23abfebbc629', '4a704bfd-3d5c-43e5-bca9-eb993fdc595b', 'b', 'Ra= 262º; Hrb= 13:42.', false, '2025-09-13 13:53:13.743165+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41891d56-38d3-4b37-a3f6-da2985375767', '4a704bfd-3d5c-43e5-bca9-eb993fdc595b', 'c', 'Ra= 271º; Hrb= 13:42.', false, '2025-09-13 13:53:13.743377+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef0aaec2-36cf-444a-9e62-127f2a083985', '4a704bfd-3d5c-43e5-bca9-eb993fdc595b', 'd', 'Ra= 250º; Hrb= 13:45.', false, '2025-09-13 13:53:13.743578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0e6ae782-13b3-47b1-b67e-222f498d7f18', '1e1c16ab-5997-4bc1-8518-515f956901cf', 'a', '8,82 m.', false, '2025-09-13 13:53:13.744015+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67b355bb-17e6-4380-9c9f-cac7178f6cf0', '1e1c16ab-5997-4bc1-8518-515f956901cf', 'b', '7,78 m.', false, '2025-09-13 13:53:13.744223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a608036b-e21f-4442-864e-5e364f68646a', '893e2d9b-3107-4160-82b2-086f232d22a1', 'a', 'A partir de la proa, de 0º a 360º en el sentido de las agujas del reloj o de 0º a 180º por cada banda.', true, '2025-09-13 13:53:13.736751+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('929e89b6-eb54-4937-829a-fc5b1d8e421f', '28fcc8b0-3340-4624-ad1e-ad5e6f3bfe77', 'c', 'Sí, pero la transmisión debe ser emitida por un Centro de Salvamento Marítimo o Estación Radiocostera.', true, '2025-09-13 13:53:13.733995+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('440bf21a-f9cb-4a51-94dc-0c795d5f14fe', '1e1c16ab-5997-4bc1-8518-515f956901cf', 'd', '8,22 m. DE TRANSPORTES Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO (Con PNB Liberado) Código de Test 02 Maniobra y navegación.', false, '2025-09-13 13:53:13.744594+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('133680f9-301c-4087-8a93-595d3d693608', '5ec89aad-6080-4ffc-97d2-d72c549a0b53', 'a', 'Paso 1: Largar amarras excepto el largo de proa, timón a babor y poca atrás. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.745195+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('07a3c4c9-f3e3-4fe4-9a96-6cc7ebd29d41', '5ec89aad-6080-4ffc-97d2-d72c549a0b53', 'b', 'Paso 1: Largar amarras excepto el esprín de proa, timón a estribor y poca avante. Paso 2: Una vez abierta la popa del muelle, soltar cabo y gobernar hacia la salida.', false, '2025-09-13 13:53:13.745417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a0e58417-efdb-4c14-abe5-5b54eeb700c9', '5ec89aad-6080-4ffc-97d2-d72c549a0b53', 'c', 'Paso 1: Largar todo, timón a estribor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', true, '2025-09-13 13:53:13.745606+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6a83778-d388-4cc2-813a-1456510f9d9e', '5ec89aad-6080-4ffc-97d2-d72c549a0b53', 'd', 'Paso 1: Largar todo, timón a babor y poca avante. Paso 2: Una vez abiertos del muelle gobernar hacia la salida.', false, '2025-09-13 13:53:13.74581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('75daae52-fcbd-43fb-ada0-8b4d908a0141', 'dd53a335-b41d-477b-a0de-d2948f9755e0', 'a', 'Fase de deriva, fase variable y fase alterna.', false, '2025-09-13 13:53:13.746223+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0788b918-8ee8-4997-9746-e9594ee8e354', 'dd53a335-b41d-477b-a0de-d2948f9755e0', 'b', 'Fase de maniobra, fase variable y fase uniforme.', true, '2025-09-13 13:53:13.746416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('573c78ac-eef8-43e1-8ca7-cf01bae41b7b', 'dd53a335-b41d-477b-a0de-d2948f9755e0', 'c', 'Fase de maniobra, fase de abatimiento y fase alterna.', false, '2025-09-13 13:53:13.746629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48d8aaf8-59ea-4ddd-9b34-964c9b227e3f', '7206ecf0-01c6-4ae9-a68e-bd262ff649e3', 'a', 'Atacaremos el fuego por la base de las llamas y nos aproximaremos siempre mirando al fuego.', false, '2025-09-13 13:53:13.747237+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5ce98884-d19f-4702-9e9f-a1a19fc85d9a', '7206ecf0-01c6-4ae9-a68e-bd262ff649e3', 'b', 'Si existe corriente de aire nos aproximaremos con ésta a nuestra espalda.', false, '2025-09-13 13:53:13.747426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d2128aa8-afce-4299-a53d-f56660ec8dab', '7206ecf0-01c6-4ae9-a68e-bd262ff649e3', 'c', 'Utilizaremos como agente extintor el polvo seco.', false, '2025-09-13 13:53:13.747665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db1cc37e-ea61-4ea0-8338-a8cfd539cc54', '7206ecf0-01c6-4ae9-a68e-bd262ff649e3', 'd', 'Posicionaremos la embarcación de forma que el foco principal del incendio quede a barlovento para evitar la propagación del fuego.', true, '2025-09-13 13:53:13.747865+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2041619e-f625-4421-8202-a752ec90950c', '0e5051a3-e034-4524-a8e1-1aa596f1b273', 'a', 'En caso de producirse una quemadura, recorte la ampolla, limpie la quemadura y cúbrala con gasas grasas y un vendaje que la comprima.', false, '2025-09-13 13:53:13.748293+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0c86a12-4a08-4665-8e45-1d03e45182a6', '0e5051a3-e034-4524-a8e1-1aa596f1b273', 'b', 'Ante una hemorragia externa, en una zona compresible y sin síntomas de hipotermia, comprima fuertemente con la mano sobre gasas limpias al menos 4 o 5 minutos, pudiendo aplicar posteriormente un vendaje compresivo.', true, '2025-09-13 13:53:13.74849+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1fa5ba96-a9f2-4b4c-b7cf-00f1cb83296c', '0e5051a3-e034-4524-a8e1-1aa596f1b273', 'c', 'Si se presenta una herida leve, alargada y profunda, limpie la herida con agua y jabón, frotando con un algodón, séquela con una gasa aplicando un antiséptico y tapónela con un apósito autoadhesivo estéril.', false, '2025-09-13 13:53:13.748692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a261aea-454c-4210-ae51-df91dbfb3a1f', '0e5051a3-e034-4524-a8e1-1aa596f1b273', 'd', 'En caso de sufrir un golpe de calor, sitúe al afectado en un lugar fresco, seco y bien ventilado, quítele la ropa y enfríelo mediante paños de agua fría hasta que la temperatura corporal alcance los 37,5º C, administrándole al tiempo una bebida estimulante.', false, '2025-09-13 13:53:13.748897+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73668da8-cdd2-401d-9fbf-fa0045560588', 'f36f7a99-b9f9-4af8-9896-bbd0bbf47660', 'a', 'La responsabilidad recae siempre en la embarcación que navegue a mayor velocidad.', false, '2025-09-13 13:53:13.749328+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c22c6a96-8a12-497c-b627-026726cc94f3', 'f36f7a99-b9f9-4af8-9896-bbd0bbf47660', 'b', 'La prioridad absoluta es elaborar parte amistoso y dar traslado de toda la información que figure en nuestro seguro, siempre que nos la solicite la parte contraria.', false, '2025-09-13 13:53:13.749528+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1517ff5a-5bff-474e-b8ee-fe3bdb289686', 'f36f7a99-b9f9-4af8-9896-bbd0bbf47660', 'c', 'Solamente en ciertos casos una vía de agua producirá un aumento del calado, por lo que no debe preocuparnos hasta haber completado el parte amistoso.', false, '2025-09-13 13:53:13.749735+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0a9bc185-1106-4a39-a4f7-d093032a352d', 'f36f7a99-b9f9-4af8-9896-bbd0bbf47660', 'd', 'La evaluación de las averías sufridas y asistencia a las personas que puedan encontrarse heridas debe realizarse a la mayor brevedad posible. Meteorología', true, '2025-09-13 13:53:13.749943+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7e2e98a-59c7-4b51-8869-e4feae9bebd6', '5d55a79d-3241-44c6-88da-e7eb81071444', 'a', 'La temperatura de fusión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.750346+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('00ae2480-425d-41d2-8796-39ce5157ed54', '5d55a79d-3241-44c6-88da-e7eb81071444', 'b', 'La temperatura de fusión del hielo y la temperatura de congelación del agua al nivel del mar.', false, '2025-09-13 13:53:13.75056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7690e52b-9842-48ae-ad9a-9530aeaa6cf6', '5d55a79d-3241-44c6-88da-e7eb81071444', 'c', 'La temperatura de fusión del hielo y la temperatura de ebullición del agua al nivel del mar.', true, '2025-09-13 13:53:13.750741+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('858ed249-7531-4a59-ba75-f9702a7c6421', '5d55a79d-3241-44c6-88da-e7eb81071444', 'd', 'La temperatura de fisión del hielo y la temperatura de condensación del agua al nivel del mar.', false, '2025-09-13 13:53:13.750945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('844faf20-a578-4e04-b660-f8b5f0700024', '467a3058-08c1-4283-8921-7fbd6eabdd09', 'a', 'Sí, siempre y cuando ésta haya sido emitida en formato LSD en el canal 9 por un usuario con autorización emitida por la Comunidad Autónoma correspondiente.', false, '2025-09-13 13:53:13.75136+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cba8aca9-9653-47fb-a745-06dbdb54acc4', '467a3058-08c1-4283-8921-7fbd6eabdd09', 'b', 'No, debe ser emitida en formato papel, a través de la AEMET.', false, '2025-09-13 13:53:13.75156+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1c033557-1028-487c-9407-b3c96e85bb35', '467a3058-08c1-4283-8921-7fbd6eabdd09', 'd', 'Sí, pero para ser válida ésta debe ser recibida expresamente por NAVTEX.', false, '2025-09-13 13:53:13.751965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7ab1c46f-4ef1-496c-9d09-88351eb73346', 'fe057504-228a-4256-acd8-db9cca436b49', 'a', 'Nocturna, con dirección y sentido de tierra a mar.', true, '2025-09-13 13:53:13.752387+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bd6622e-2ac0-42d2-8f02-e0cf4409da2d', 'fe057504-228a-4256-acd8-db9cca436b49', 'b', 'Diurna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.752578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f3ad63f6-0e8c-4e36-a487-fa9449282b6c', 'fe057504-228a-4256-acd8-db9cca436b49', 'c', 'Diurna, con dirección y sentido de tierra a mar.', false, '2025-09-13 13:53:13.752794+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b78a8f0e-93f5-4bae-a9e1-135228568939', 'fe057504-228a-4256-acd8-db9cca436b49', 'd', 'Nocturna, con dirección y sentido de mar a tierra.', false, '2025-09-13 13:53:13.752977+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02bafe06-d799-4817-b8da-0d2ab68b9f66', '56934c86-3006-4062-aa3b-4c77c82f92d2', 'a', 'Se puede determinar empleando solamente la escala Beaufort ya que tienen el mismo sistema de medida (velocidad).', false, '2025-09-13 13:53:13.753405+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8b064617-35fe-40ec-b1df-f3c9ca5d4bec', '56934c86-3006-4062-aa3b-4c77c82f92d2', 'b', 'Es el número de horas que ha soplado el aire en una misma dirección.', false, '2025-09-13 13:53:13.75361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8c6b067f-2160-4369-9be3-610da91f3c3b', '56934c86-3006-4062-aa3b-4c77c82f92d2', 'c', 'Es un incremento brusco en la intensidad del viento.', false, '2025-09-13 13:53:13.753819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd3bc290-1dd1-422d-a2b0-01e7a4126e9e', '56934c86-3006-4062-aa3b-4c77c82f92d2', 'd', 'Es la extensión o alcance que tienen el viento sobre la mar con una dirección y fuerza constantes. Teoría de la navegación.', true, '2025-09-13 13:53:13.754028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e70ad854-49ec-4c34-be9e-da0f1cc56e0b', '4dc738ab-9398-46f6-9e10-998d3b278b8b', 'b', 'De 0º a 360º desde la proa en sentido contrario a las agujas del reloj, en cuyo caso su signo siempre es positivo.', false, '2025-09-13 13:53:13.754639+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0a2779f-3674-4c4a-8ea1-5db93e17b7e2', '4dc738ab-9398-46f6-9e10-998d3b278b8b', 'c', 'De 0º a 180º, por cada banda, a partir de la proa, considerándose positivas las tomadas por babor y negativas las tomadas por estribor.', false, '2025-09-13 13:53:13.754834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1d495ac7-27c9-4843-b2fa-71169d80c478', '4dc738ab-9398-46f6-9e10-998d3b278b8b', 'd', 'A partir del Norte, de 0º a 360º en el sentido de las agujas del reloj, teniendo la ventaja de que su signo siempre será positivo.', false, '2025-09-13 13:53:13.755067+00');
