INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1b684160-7a41-437d-8973-8c808e1a56f4', 'a4dda011-451f-4af5-8196-c9fc5dedd3f4', 'a', '“Filar” es largar o arriar cabo o cadena al fondear.', false, '2025-09-13 13:53:13.764107+00');
