INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('34dd931f-4d6e-44b9-985c-e02c875db860', 'a4dda011-451f-4af5-8196-c9fc5dedd3f4', 'c', '“A pique” indica el momento en el que el ancla toca el pique de proa o la roda.', true, '2025-09-13 13:53:13.76449+00');
