INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1ce3e91a-a2a5-47ad-90ab-d6fe67e1b85c', '6f5c387d-8bd2-4b70-be4b-20761ba30551', 'a', 'El oleaje siempre se reduce, por lo que navegaremos con más seguridad.', false, '2025-09-13 13:53:13.771354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3f0cd07-27bf-442b-8c33-6b962c15091e', '6f5c387d-8bd2-4b70-be4b-20761ba30551', 'b', 'Es recomendable disminuir la velocidad.', true, '2025-09-13 13:53:13.771568+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3e6c26fc-d822-45a3-aae7-9a03773c74e4', '6f5c387d-8bd2-4b70-be4b-20761ba30551', 'c', 'Aumenta la sonda, por lo que la embarcación es más maniobrable.', false, '2025-09-13 13:53:13.771773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('318bd7f4-6824-4c3f-ac14-af27ef763d5c', '6f5c387d-8bd2-4b70-be4b-20761ba30551', 'd', 'Disminuye la resistencia a la propulsión.', false, '2025-09-13 13:53:13.771991+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff80220d-7b9c-4fe3-ae37-4cb9b9effcb5', 'aed97046-f06b-48d5-a81a-71e73865613b', 'a', 'Cerciorarse de que todos los grifos de fondo estén cerrados.', true, '2025-09-13 13:53:13.772379+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05c93bea-f08d-41bc-89f4-787b0d0bc8a2', 'aed97046-f06b-48d5-a81a-71e73865613b', 'b', 'Revisar la limpieza de los filtros de decantación.', false, '2025-09-13 13:53:13.772596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e77f4046-d4de-497a-8348-af041f2aefe7', 'aed97046-f06b-48d5-a81a-71e73865613b', 'c', 'Verificar el nivel de combustible y que no existan fugas.', false, '2025-09-13 13:53:13.772796+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('96075b58-19e7-4510-ab77-2f583d4259ac', 'aed97046-f06b-48d5-a81a-71e73865613b', 'd', 'Examinar el estado de los elementos de seguridad.', false, '2025-09-13 13:53:13.773016+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8eb7e5b7-f350-4447-b90f-49e30c5ace48', 'ced51284-9659-45df-8ba5-91dfbb40ecdc', 'a', 'Elija el punto o puntos más fuertes de su embarcación para hacer firme el cabo de remolque.', false, '2025-09-13 13:53:13.773456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c07af7e-c1af-4171-8274-1826b7b63a5d', 'ced51284-9659-45df-8ba5-91dfbb40ecdc', 'b', 'Asegúrese de amarrar el cabo que le entreguen a los candeleros de la embarcación, mediante un nudo que no pueda ser deshecho bajo tensión.', true, '2025-09-13 13:53:13.773657+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a211af10-a776-4f88-962f-f848757b73f9', 'ced51284-9659-45df-8ba5-91dfbb40ecdc', 'c', 'Colabore en todo momento con la tripulación del remolcador.', false, '2025-09-13 13:53:13.773863+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ed846cd5-abc3-4c22-a8eb-874dc8fab362', 'ced51284-9659-45df-8ba5-91dfbb40ecdc', 'd', 'Manténgase lejos del cabo o estacha de remolque mientras es remolcado.', false, '2025-09-13 13:53:13.774085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d75065c-cf2a-414c-b3ff-cf20291c315c', 'bd1a6690-d83d-43ae-8e44-1ffd82e7926d', 'a', 'Mi barco está parado y no se pone en marcha.', false, '2025-09-13 13:53:13.774537+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e57012a-d007-4b7f-82b7-2898acd270ab', 'bd1a6690-d83d-43ae-8e44-1ffd82e7926d', 'b', 'Maniobro con dificultad. Manténgase alejado.', false, '2025-09-13 13:53:13.774731+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dfe7ed13-ef60-49f7-9686-44c04d8fc4dc', 'bd1a6690-d83d-43ae-8e44-1ffd82e7926d', 'c', 'Tengo un buzo sumergido. Manténgase alejado y reduzca velocidad.', true, '2025-09-13 13:53:13.774951+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f26fd96f-e5b7-4c26-a961-f9c55b56d1df', 'bd1a6690-d83d-43ae-8e44-1ffd82e7926d', 'd', 'Estoy descargando mercancías peligrosas.', false, '2025-09-13 13:53:13.775153+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f466b88-9c64-4faf-a219-90a01a461462', '441e1320-a986-47d9-afee-dde923ee2355', 'a', 'Pueden detenerse o fondear en cualquier lugar, solo y exclusivamente cuando cuenten con la autorización expresa de la Administración Marítima.', false, '2025-09-13 13:53:13.775587+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dba6bf23-412b-4f53-92af-65a1cb2611bf', '441e1320-a986-47d9-afee-dde923ee2355', 'b', 'Pueden detenerse en calas o lugares de baño si no están balizados y ello no supone un riesgo para', true, '2025-09-13 13:53:13.775812+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b4332c98-f9b4-4c68-ac9a-ced8363b524e', '441e1320-a986-47d9-afee-dde923ee2355', 'c', 'Están exentas de comunicar a la Administración Marítima si se detienen o fondean debido a peligro o fuerza mayor.', false, '2025-09-13 13:53:13.776013+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('772a78b2-9f21-4e7f-99df-b27c9dbd1c0e', '441e1320-a986-47d9-afee-dde923ee2355', 'd', 'Deben comunicar siempre a la Administración Marítima más cercana, por cualquier medio, la detención o fondeo en cualquier lugar fuera de puertos.', false, '2025-09-13 13:53:13.776218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22b767c2-0d42-4e4a-aa66-51191f896b37', '0d63ecc1-2522-4133-bfd3-2cada24389a2', 'a', 'De estribor.', false, '2025-09-13 13:53:13.776651+00');
