INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('74176a47-9dae-4899-aeaf-7391f3ec10b3', '8b714111-d92a-4d61-8fb3-68c3ec958663', 'a', 'Seguiremos a rumbo, vigilando su derrota y cuando estemos muy cerca maniobramos para evitar el abordaje cayendo todo a babor.', false, '2025-09-13 13:53:13.782849+00');
