INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('608a2719-082d-46ab-b050-be009b074c05', 'c712fccb-48a4-411e-b747-ec65cfcd7024', 'b', 'Un buque dedicado a operaciones submarinas, las cuales se están llevando a cabo por su costado', false, '2025-09-13 13:53:13.787307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff3b0537-2710-41f5-a5ea-e132afa609ea', 'c712fccb-48a4-411e-b747-ec65cfcd7024', 'c', 'Un pesquero faenando con el aparejo tendido por su costado de estribor.', false, '2025-09-13 13:53:13.787499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8e0764f3-9c3a-4ef6-a274-4ca7139d2e8f', 'c712fccb-48a4-411e-b747-ec65cfcd7024', 'd', 'Una draga realizando operaciones de dragado, donde la zona de obstrucción se encuentra por su costado de babor.', true, '2025-09-13 13:53:13.787709+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d721a2c8-4098-43b6-a67f-691baa01a71a', '2065b2e8-da6b-4399-ae0a-695a25e89723', 'a', 'El buque que sigue a rumbo mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:13.788106+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c16949a1-3ec0-4d09-8e1c-01a29f627364', '2065b2e8-da6b-4399-ae0a-695a25e89723', 'b', 'El buque que cede el paso está eximido, de acuerdo con esta regla, de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:13.788313+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b446e5ba-c7fe-4fbb-aaba-ac88e0694d64', '2065b2e8-da6b-4399-ae0a-695a25e89723', 'c', 'El buque que sigue a rumbo maniobrará para evitar el abordaje tan pronto como le resulte evidente que el buque que debería apartarse no actúe de acuerdo con lo establecido.', false, '2025-09-13 13:53:13.788511+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9270bf7f-dc51-4c82-afe7-5a7db03e14d8', '2065b2e8-da6b-4399-ae0a-695a25e89723', 'd', 'El buque que cede el paso se mantendrá apartado de la derrota del que sigue a rumbo.', false, '2025-09-13 13:53:13.788729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('260db02e-3483-4f5d-b631-40f5f11e2d6d', '0f6f82c9-7530-465b-a0bf-afd9f529d450', 'a', 'En ningún caso está permitido realizar dicha maniobra.', false, '2025-09-13 13:53:13.78918+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55d573f2-7fc0-4c6b-b491-6c5aa9081654', '0f6f82c9-7530-465b-a0bf-afd9f529d450', 'b', 'La maniobra está permitida únicamente si se está alcanzando a un buque de eslora inferior a 20 metros o a un buque de vela.', false, '2025-09-13 13:53:13.789392+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('44e34386-b6e9-4b84-8068-755d10437222', '0f6f82c9-7530-465b-a0bf-afd9f529d450', 'c', 'Se debe indicar nuestra intención haciendo sonar dos pitadas largas seguidas de dos cortas, y antes de proceder deberemos escuchar la señal de conformidad del buque alcanzado.', true, '2025-09-13 13:53:13.789586+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3786288-6a6d-4bb5-874d-5d5941a32382', '0f6f82c9-7530-465b-a0bf-afd9f529d450', 'd', 'Aumentaremos velocidad progresivamente mientras maniobramos a babor a la vez que hacemos sonar una pitada larga, una corta, una larga y una corta.', false, '2025-09-13 13:53:13.789788+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2db89be2-401b-4f3c-9c4a-1e212dcd3d42', '064a33d3-9020-40da-bce3-7b2ce7c4e06f', 'a', 'Fuera del ámbito de aplicación del reglamento.', false, '2025-09-13 13:53:13.790222+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('19011e10-a663-4afb-82dc-513c552507b2', '064a33d3-9020-40da-bce3-7b2ce7c4e06f', 'b', 'Un hidroavión.', false, '2025-09-13 13:53:13.790433+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e111d41d-4a34-4a94-a717-c8f05f3afded', '064a33d3-9020-40da-bce3-7b2ce7c4e06f', 'c', 'Una nave de vuelo rasante.', true, '2025-09-13 13:53:13.790633+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2162990a-81b8-45a0-b479-78916450e20e', '064a33d3-9020-40da-bce3-7b2ce7c4e06f', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.790836+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('532fecb4-4b07-4ff5-91ff-dcf97d777485', '3a0bd986-3450-4a10-abd7-98313e8106ab', 'a', 'Un buque fondeado de eslora inferior a 100 metros.', true, '2025-09-13 13:53:13.791275+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6141c9a8-4d42-4b0f-9c19-28597cd1c806', '3a0bd986-3450-4a10-abd7-98313e8106ab', 'b', 'Un buque llamando la atención de otro.', false, '2025-09-13 13:53:13.791492+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f52f6d7-af33-442d-ae1e-55ce7671dd73', '3a0bd986-3450-4a10-abd7-98313e8106ab', 'c', 'Un buque sin gobierno de eslora igual o superior a 100 metros.', false, '2025-09-13 13:53:13.791711+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('106d080a-d026-4edc-acb3-1d618c8b8c12', '3a0bd986-3450-4a10-abd7-98313e8106ab', 'd', 'Un buque varado de eslora superior a 100 metros. DE TRANSPORTES                                                                                      DE TRANSPORTES Y MOVILIDAD SOSTENIBLE Y MOVILIDAD SOSTENIBLE DE TRANSPORTES AÉREO Y MARÍTIMO Código de Test 03 Nomenclatura náutica.', false, '2025-09-13 13:53:13.791922+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6969063f-ff8c-4c9e-88f3-5481f1d065a4', '3b4d8c37-8973-4c1d-90c2-0de0af18b372', 'a', 'Elementos estructurales transversales cuya parte inferior encaja en la quilla del buque y desde allí arrancan en dos ramas simétricas hacia babor y estribor.', false, '2025-09-13 13:53:13.79259+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('eb7128f5-1766-4cc1-a4ab-db69a2de8604', '3b4d8c37-8973-4c1d-90c2-0de0af18b372', 'b', 'Elementos estructurales transversales que apoyan en las cabezas de las cuadernas y sirven de consolidación para sostener las cubiertas.', true, '2025-09-13 13:53:13.792834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ba1db9b8-be77-4576-932e-0eb1c359c9cd', '3b4d8c37-8973-4c1d-90c2-0de0af18b372', 'c', 'Elementos estructurales longitudinales dispuestos de proa a popa por la parte inferior donde asientan las cuadernas.', false, '2025-09-13 13:53:13.793056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4fec9f23-f0b1-4603-a872-19ca6667faf7', '3b4d8c37-8973-4c1d-90c2-0de0af18b372', 'd', 'Prolongaciones verticales o inclinadas de la quilla en su parte de popa, donde generalmente se apoya el timón.', false, '2025-09-13 13:53:13.793267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3015504e-1c61-4ba0-b44c-988c585c0f78', '8433424b-d59b-4c5d-ab3a-bbde32795e2b', 'a', '“Filar” es largar o arriar cabo o cadena al fondear.', false, '2025-09-13 13:53:13.793689+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c5820579-9caf-49ec-a058-42c0971ad896', '8433424b-d59b-4c5d-ab3a-bbde32795e2b', 'b', '“A la pendura” consiste en destrincar el ancla, bajarla y dejarla colgando y en disposición de darle fondo en el momento que se decida iniciar la maniobra de fondeo.', false, '2025-09-13 13:53:13.79389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6459267-99d9-4c32-a596-3f43ea7e310a', '8433424b-d59b-4c5d-ab3a-bbde32795e2b', 'c', '“A pique” indica el momento en el que el ancla toca el pique de proa o la roda.', true, '2025-09-13 13:53:13.794105+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7a4bbede-3983-481c-bb0b-43ed78ed7c6a', '8433424b-d59b-4c5d-ab3a-bbde32795e2b', 'd', '“Clara y libre” es la voz que indica que el ancla ha salido a la superficie sin nada que impida que pueda ser estibada adecuadamente.', false, '2025-09-13 13:53:13.794315+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('574b1d96-9763-4150-9a19-9bfea4fc96f1', '5e6e8c0a-e8fa-4934-8879-5e7099050f7a', 'a', 'Bocina.', false, '2025-09-13 13:53:13.794759+00');
