INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c4a24f46-fe99-47ed-85dd-d3a53328141a', '5d2cfd5b-c610-4b29-b7dd-4533eab80c95', 'b', 'A la mínima velocidad de gobierno y con el viento por la popa.', false, '2025-09-13 13:53:13.798111+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('120b4285-434a-4899-817b-8eac46a38a25', '5d2cfd5b-c610-4b29-b7dd-4533eab80c95', 'c', 'A la máxima velocidad de gobierno y con el viento por la popa.', false, '2025-09-13 13:53:13.798318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d53bd21-2834-4399-a278-29f03433e32b', '5d2cfd5b-c610-4b29-b7dd-4533eab80c95', 'd', 'A la máxima velocidad de gobierno y con el viento por la proa.', false, '2025-09-13 13:53:13.798508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c3b76009-bfdf-45e0-86e7-5682e232b945', 'c587626f-68d5-400f-903c-b9a2ba62ea62', 'a', 'Cerciorarse de que todos los grifos de fondo estén cerrados.', true, '2025-09-13 13:53:13.798887+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1af33aeb-a791-49cd-9cb6-375693f78b11', 'c587626f-68d5-400f-903c-b9a2ba62ea62', 'b', 'Revisar la limpieza de los filtros de decantación.', false, '2025-09-13 13:53:13.799104+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e82c207-e882-4ff0-9050-512bea4edca6', 'c587626f-68d5-400f-903c-b9a2ba62ea62', 'c', 'Verificar el nivel de combustible y que no existan fugas.', false, '2025-09-13 13:53:13.799303+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cd7a4b9-e629-4166-a286-ec3672ee5890', 'c587626f-68d5-400f-903c-b9a2ba62ea62', 'd', 'Examinar el estado de los elementos de seguridad.', false, '2025-09-13 13:53:13.799499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4af274e-8e65-405d-8e47-292c5ca815ce', '1ec01eda-e8ca-46f8-92c4-6e6e86f4728c', 'a', 'El oleaje siempre se reduce, por lo que navegaremos con más seguridad.', false, '2025-09-13 13:53:13.799908+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9346d4f-f921-4670-81e2-7826256c0d75', '1ec01eda-e8ca-46f8-92c4-6e6e86f4728c', 'b', 'Es recomendable disminuir la velocidad.', true, '2025-09-13 13:53:13.800112+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0f14562-130d-456f-8e98-553f29877fd7', '1ec01eda-e8ca-46f8-92c4-6e6e86f4728c', 'c', 'Aumenta la sonda, por lo que la embarcación es más maniobrable.', false, '2025-09-13 13:53:13.800323+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b3bd41ac-a8e0-4c50-a4da-9252008f9663', '1ec01eda-e8ca-46f8-92c4-6e6e86f4728c', 'd', 'Disminuye la resistencia a la propulsión.', false, '2025-09-13 13:53:13.800516+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46daa208-c47c-4744-8b48-1cf522e03e22', '110e327b-83dd-4622-8ba7-070ff29dc31b', 'a', 'Se debe disponer, como mínimo, de un chaleco para cada persona.', false, '2025-09-13 13:53:13.800904+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b86460d-405b-4941-9e37-c1ee1ea7a2ff', '110e327b-83dd-4622-8ba7-070ff29dc31b', 'b', 'Todos los chalecos deben disponer de una luz, excepto cuando la embarcación realice exclusivamente navegación diurna en las zonas 4, 5, 6 y 7.', false, '2025-09-13 13:53:13.801116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ed2d66a-dc52-42e5-8d4f-50b762d03d7d', '110e327b-83dd-4622-8ba7-070ff29dc31b', 'c', 'En la zona 7 se debe llevar un chaleco adicional.', true, '2025-09-13 13:53:13.801316+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd2488e1-2db5-4029-90ad-d4d93b3aca00', '110e327b-83dd-4622-8ba7-070ff29dc31b', 'd', 'Los menores deben disponer de un chaleco salvavidas a su medida.', false, '2025-09-13 13:53:13.801539+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('32a0aa71-d73b-49af-8a7b-a90597a2f188', '7504ccda-3929-4853-bac0-8755e47635c5', 'a', 'Elija el punto o puntos más fuertes de su embarcación para hacer firme el cabo de remolque.', false, '2025-09-13 13:53:13.801965+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7b0b5f96-be88-4534-b50e-7031edb83255', '7504ccda-3929-4853-bac0-8755e47635c5', 'b', 'Asegúrese de amarrar el cabo que le entreguen a los candeleros de la embarcación, mediante un nudo que no pueda ser deshecho bajo tensión.', true, '2025-09-13 13:53:13.802162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87f843a0-0369-4a58-bb72-229b821884a3', '7504ccda-3929-4853-bac0-8755e47635c5', 'c', 'Colabore en todo momento con la tripulación del remolcador.', false, '2025-09-13 13:53:13.802356+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16b4dfe2-08ec-4e1a-a8b8-e6c8465489ea', '7504ccda-3929-4853-bac0-8755e47635c5', 'd', 'Manténgase lejos del cabo o estacha de remolque mientras es remolcado.', false, '2025-09-13 13:53:13.802559+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8a0ede46-fc73-42e1-9060-04314e4131fa', '113b6b23-7877-4cf5-a5a8-bf36acc14ead', 'a', 'El buque que sigue a rumbo mantendrá su rumbo y velocidad.', false, '2025-09-13 13:53:13.817499+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7371450-31a7-45f3-90af-b1222fbc3311', '9256104c-7f52-461b-9ce8-28629bc87f13', 'a', 'Pueden detenerse o fondear en cualquier lugar, solo y exclusivamente cuando cuenten con la autorización expresa de la Administración Marítima.', false, '2025-09-13 13:53:13.802981+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c84c305b-f0cb-4742-a81a-675476c2a909', '9256104c-7f52-461b-9ce8-28629bc87f13', 'b', 'Pueden detenerse en calas o lugares de baño si no están balizados y ello no supone un riesgo para', true, '2025-09-13 13:53:13.80318+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2abb66b-069d-476a-b2ba-399997285719', '9256104c-7f52-461b-9ce8-28629bc87f13', 'c', 'Están exentas de comunicar a la Administración Marítima si se detienen o fondean debido a peligro o fuerza mayor.', false, '2025-09-13 13:53:13.803381+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69b8f9d4-b75e-4b4c-a264-528daeff5e1a', '9256104c-7f52-461b-9ce8-28629bc87f13', 'd', 'Deben comunicar siempre a la Administración Marítima más cercana, por cualquier medio, la detención o fondeo en cualquier lugar fuera de puertos.', false, '2025-09-13 13:53:13.80358+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b83bbf97-eeb3-40bd-8937-12face61aa6e', '9b9408f4-2566-4c9d-a790-5177ba2854f0', 'a', 'Mi barco está parado y no se pone en marcha.', false, '2025-09-13 13:53:13.804006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('56a5221d-b7fc-4162-8507-12b467b969e7', '9b9408f4-2566-4c9d-a790-5177ba2854f0', 'b', 'Maniobro con dificultad. Manténgase alejado.', false, '2025-09-13 13:53:13.804202+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('812b78ca-235b-410b-84a7-3312c3465266', '9b9408f4-2566-4c9d-a790-5177ba2854f0', 'c', 'Tengo un buzo sumergido. Manténgase alejado y reduzca velocidad.', true, '2025-09-13 13:53:13.804416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6b29a9b8-e932-4af0-bd39-1438375e06c3', '9b9408f4-2566-4c9d-a790-5177ba2854f0', 'd', 'Estoy descargando mercancías peligrosas.', false, '2025-09-13 13:53:13.804617+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a588c860-45a9-4b55-ac61-7a78e97a9e77', '8449409b-aad0-47ec-8446-c1abd287f821', 'a', 'Nunca señalan un nuevo peligro.', true, '2025-09-13 13:53:13.805061+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bfea1e7-1e31-4930-a9cb-94005bfe33cb', '8449409b-aad0-47ec-8446-c1abd287f821', 'b', 'Si tuviesen marca de tope, sería amarilla en forma de cruz vertical.', false, '2025-09-13 13:53:13.805283+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c24b199f-0e1a-48f5-9506-14e8ecb485d7', '8449409b-aad0-47ec-8446-c1abd287f821', 'c', 'Indican donde se encuentran las aguas más seguras de la zona en relación con un punto de interés.', false, '2025-09-13 13:53:13.805491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c63930bc-0819-4a67-8318-52b6652ed70d', '8449409b-aad0-47ec-8446-c1abd287f821', 'd', 'Nunca indican límites de áreas de anclaje.', false, '2025-09-13 13:53:13.805702+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2a249c71-ea54-45ec-b5bb-fe16f472102b', '918c67af-105a-44f0-8e5f-247cecfd2ca4', 'a', 'De Canal Principal.', false, '2025-09-13 13:53:13.806116+00');
