INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b8a9cc0-d13a-400f-b289-d4586b5ed996', '918c67af-105a-44f0-8e5f-247cecfd2ca4', 'c', 'De Naufragio.', false, '2025-09-13 13:53:13.806534+00');
