INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('177b29dd-686f-4dfb-bad2-5d2ca900859d', 'a5386af6-566b-4acc-8b89-34ef9ebbb605', 'a', 'Negro con una ancha banda horizontal amarilla.', true, '2025-09-13 13:53:13.807202+00');
