INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('69becc53-2ea1-461f-b052-7ebbbc2566f7', 'b4bab5f5-48de-4a84-ac23-82df74042a3f', 'c', 'Una esfera negra.', false, '2025-09-13 13:53:13.809748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bfa36cba-ea86-42e4-94b4-1b848a8e2568', 'b4bab5f5-48de-4a84-ac23-82df74042a3f', 'd', 'Ninguna, en cualquier caso. Reglamento (RIPA).', false, '2025-09-13 13:53:13.809969+00');
