INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('840e56ec-dd8a-4e07-b5da-95f3385f50d5', '3bb56bdc-8199-4838-90c0-f3c4eb7d5526', 'd', 'Un buque con capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.811006+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b647a1f2-de10-4b52-b93f-dc4754551c78', 'd1008946-30dc-46d4-9034-2bd4d1386fee', 'a', 'Un buque de vela transitando por la zona costera adyacente, aunque podría hacerlo por la vía de circulación apropiada.', false, '2025-09-13 13:53:13.811413+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02cc4120-133b-4e7c-b6c4-6b1e966005cb', 'd1008946-30dc-46d4-9034-2bd4d1386fee', 'b', 'Un buque de 20 metros de eslora transitando por la zona costera adyacente, aunque podría hacerlo por la vía de circulación apropiada.', true, '2025-09-13 13:53:13.81162+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d241b94d-5e8f-4908-a3b9-74c06839ce35', 'd1008946-30dc-46d4-9034-2bd4d1386fee', 'c', 'Un buque de 20 metros de eslora transitando por la zona costera adyacente para evitar un peligro', false, '2025-09-13 13:53:13.811821+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc3bef97-ecdc-4e83-bbd9-ba3005400141', 'd1008946-30dc-46d4-9034-2bd4d1386fee', 'd', 'Un buque dedicado a la pesca pescando en la zona costera adyacente.', false, '2025-09-13 13:53:13.812044+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a671a625-7931-4d2f-b80b-ede9aaf4ff03', '99f275a9-c128-4edd-bb76-599b1d3ec69d', 'a', 'Un buque de propulsión mecánica de más de 50 metros en navegación.', false, '2025-09-13 13:53:13.812439+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1338e510-d068-47bd-83ec-2e6d9c4dc739', '99f275a9-c128-4edd-bb76-599b1d3ec69d', 'b', 'Un buque a vela y a motor que navega solo a vela.', false, '2025-09-13 13:53:13.812634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aabda64a-4d16-4d7c-ae67-949fb443b425', '99f275a9-c128-4edd-bb76-599b1d3ec69d', 'c', 'Un buque remolcando cuando la longitud del remolque excede los 200 metros.', true, '2025-09-13 13:53:13.812857+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('55367483-f898-482f-b737-4a71126f4d36', '99f275a9-c128-4edd-bb76-599b1d3ec69d', 'd', 'Un buque de pesca, que no sea de arrastre, cuya longitud del aparejo se extiende más de 150', false, '2025-09-13 13:53:13.813063+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('881c5ee1-803a-4579-b6b8-f8c1f73ae745', '517d2baf-643f-40b7-ad61-3ea395605ba9', 'a', 'En ningún caso está permitido realizar dicha maniobra.', false, '2025-09-13 13:53:13.813465+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f532fda0-91c4-4425-a6d9-0e1f30eaa943', '517d2baf-643f-40b7-ad61-3ea395605ba9', 'b', 'La maniobra está permitida únicamente si se está alcanzando a un buque de eslora inferior a 20 metros o a un buque de vela.', false, '2025-09-13 13:53:13.813671+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef1ef3cf-afd9-4032-91b2-71a158376645', '517d2baf-643f-40b7-ad61-3ea395605ba9', 'c', 'Se debe indicar nuestra intención haciendo sonar dos pitadas largas seguidas de dos cortas, y antes de proceder deberemos escuchar la señal de conformidad del buque alcanzado.', true, '2025-09-13 13:53:13.813834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7eb96192-9e38-45ff-9bce-90888cec3fc3', '517d2baf-643f-40b7-ad61-3ea395605ba9', 'd', 'Aumentaremos velocidad progresivamente mientras maniobramos a babor a la vez que hacemos sonar una pitada larga, una corta, una larga y una corta.', false, '2025-09-13 13:53:13.814028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7e4266d-5ee9-4453-bff1-d6a59bbdfca1', 'c15d91a0-7e72-4815-9a00-f9990a8736ee', 'a', 'Un buque fondeado de eslora inferior a 100 metros.', true, '2025-09-13 13:53:13.814446+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c15bad84-b1e0-4f8d-bf0a-925918f0b994', 'c15d91a0-7e72-4815-9a00-f9990a8736ee', 'b', 'Un buque llamando la atención de otro.', false, '2025-09-13 13:53:13.814665+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0dfc37e0-ae03-4ff0-b179-9d03bf18053e', 'c15d91a0-7e72-4815-9a00-f9990a8736ee', 'c', 'Un buque sin gobierno de eslora igual o superior a 100 metros.', false, '2025-09-13 13:53:13.814854+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0178ff4d-c415-4add-a072-c5cb7f48d8ef', 'c15d91a0-7e72-4815-9a00-f9990a8736ee', 'd', 'Un buque varado de eslora superior a 100 metros.', false, '2025-09-13 13:53:13.815049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e6500348-99d2-4eeb-a278-4c0e04bce961', '68abe924-0a60-4dc0-b12d-d94ac159b8a3', 'a', 'Las Reglas de esta Parte deberán cumplirse en todas las condiciones meteorológicas.', true, '2025-09-13 13:53:13.815471+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9666507e-e41f-495e-af05-482ab71f8ff0', '68abe924-0a60-4dc0-b12d-d94ac159b8a3', 'b', 'Las luces preceptuadas por estas Reglas podrán no exhibirse desde la salida hasta la puesta del sol cuando haya visibilidad reducida, si el patrón lo considera necesario.', false, '2025-09-13 13:53:13.815668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c4f2b49-1fd2-42dc-b890-24a354716128', '68abe924-0a60-4dc0-b12d-d94ac159b8a3', 'c', 'Las Reglas relativas a las luces deberán exhibirse obligatoriamente desde la salida hasta la puesta', false, '2025-09-13 13:53:13.815888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f46598fe-4bff-41e7-a2fb-63bf0fef0ad1', '68abe924-0a60-4dc0-b12d-d94ac159b8a3', 'd', 'Las Reglas relativas a las marcas deberán cumplirse en todo momento, tanto de día como de', false, '2025-09-13 13:53:13.816091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d3b68bc9-b08f-4f2b-9f9e-549170986b88', '5cad536e-e454-44d0-a1a3-c5171cebdbdb', 'a', 'Seguiremos a rumbo, vigilando su derrota y cuando estemos muy cerca maniobramos para evitar el abordaje cayendo todo a babor.', false, '2025-09-13 13:53:13.816487+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3707d530-21c9-4c1b-9b95-2cc489abb4f8', '5cad536e-e454-44d0-a1a3-c5171cebdbdb', 'b', 'Caeremos a estribor buscando la popa del otro buque para evitar cortarle la proa.', true, '2025-09-13 13:53:13.816712+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('208a0f20-0237-4fca-b003-681d59c35541', '5cad536e-e454-44d0-a1a3-c5171cebdbdb', 'c', 'Caeremos a babor y aumentaremos la velocidad a toda máquina para cruzarle por su proa.', false, '2025-09-13 13:53:13.816903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f4fc4705-d4d3-44c1-b9f4-947ccd50a472', '5cad536e-e454-44d0-a1a3-c5171cebdbdb', 'd', 'Le avisaremos por radio para que nos maniobre y le advertiremos que seguiremos a rumbo para evitar la colisión.', false, '2025-09-13 13:53:13.817095+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ce6b950-0ce8-4508-b14a-9b09d189b1e1', '113b6b23-7877-4cf5-a5a8-bf36acc14ead', 'b', 'El buque que cede el paso está eximido, de acuerdo con esta regla, de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-13 13:53:13.8177+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cefea883-b4e0-4c46-a4c9-58efb9ab60af', '113b6b23-7877-4cf5-a5a8-bf36acc14ead', 'c', 'El buque que sigue a rumbo maniobrará para evitar el abordaje tan pronto como le resulte evidente que el buque que debería apartarse no actúe de acuerdo con lo establecido.', false, '2025-09-13 13:53:13.817925+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('332f6771-384a-4ab8-b244-81bf16ce725d', '113b6b23-7877-4cf5-a5a8-bf36acc14ead', 'd', 'El buque que cede el paso se mantendrá apartado de la derrota del que sigue a rumbo.', false, '2025-09-13 13:53:13.818115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('88bdda4c-d285-405d-a25b-088a5b53fc90', '41a40716-ffd9-4e7b-821e-a70d8c934324', 'a', 'Está varado.', false, '2025-09-13 13:53:13.818542+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1dff2273-e277-43c0-85b9-263cf79ed3f2', '41a40716-ffd9-4e7b-821e-a70d8c934324', 'b', 'Tiene su capacidad de maniobra restringida.', false, '2025-09-13 13:53:13.818742+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3d18ec27-5340-4b68-8b83-7d9f72e35f9c', '41a40716-ffd9-4e7b-821e-a70d8c934324', 'c', 'Se encuentra restringido por su calado.', true, '2025-09-13 13:53:13.81898+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c82482c-d150-4fd5-b87a-b7afeee4bc54', '41a40716-ffd9-4e7b-821e-a70d8c934324', 'd', 'Está remolcando a otro buque.', false, '2025-09-13 13:53:13.819175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('904fc01a-c180-455a-84a9-e4f234de70d0', '387b6430-8f7c-40e4-8d97-d90e504d9ffa', 'a', 'Un buque dedicado a la limpieza de operaciones de minas, siendo peligroso acercarse a menos de 1000 metros de su costado de babor.', false, '2025-09-13 13:53:13.819588+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c440f3ce-7fb0-4e9d-a3bf-24091bf77134', '387b6430-8f7c-40e4-8d97-d90e504d9ffa', 'b', 'Un buque dedicado a operaciones submarinas, las cuales se están llevando a cabo por su costado', false, '2025-09-13 13:53:13.819793+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f9a9f8b6-702e-46c7-abb1-4846b6bbd503', '387b6430-8f7c-40e4-8d97-d90e504d9ffa', 'c', 'Un pesquero faenando con el aparejo tendido por su costado de estribor.', false, '2025-09-13 13:53:13.820017+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97d73882-8aba-4aed-a7ba-e5e3ea4430fb', '387b6430-8f7c-40e4-8d97-d90e504d9ffa', 'd', 'Una draga realizando operaciones de dragado, donde la zona de obstrucción se encuentra por su costado de babor.', true, '2025-09-13 13:53:13.820227+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6c6ebf9-7b22-4fda-a802-e3db89d6d3f4', '63a5ee5d-d877-4bbc-a606-2d79c8e7b09b', 'a', 'El plano de crujía es aquel que divide la embarcación en la mitad de proa y en la mitad de popa.', false, '2025-09-14 14:34:29.14889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a6f05b1a-22bb-4f5e-a22e-c65b422bef8a', '63a5ee5d-d877-4bbc-a606-2d79c8e7b09b', 'c', 'La bañera es la cámara abierta a popa de la embarcación donde generalmente va instalada la caña o rueda del timón.', true, '2025-09-14 14:34:29.149896+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76b5211e-def5-483f-8ce6-bde80276ab0e', '63a5ee5d-d877-4bbc-a606-2d79c8e7b09b', 'd', 'Los portillos son aberturas practicadas en los costados de la embarcación que tienen por objeto la evacuación del agua embarcada en la cubierta.', false, '2025-09-14 14:34:29.150168+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d33f95e2-72a2-4957-a7c1-8f5e44dcbb8e', 'f73b465d-76c2-4ec8-8f62-9ef6c0b299f6', 'a', 'Se debe volver a leer las instrucciones de la balsa antes de lanzarla.', true, '2025-09-14 14:34:29.689536+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('87a2740b-e8f0-405c-812c-d837c7f8e94c', 'f73b465d-76c2-4ec8-8f62-9ef6c0b299f6', 'b', 'Sus revisiones periódicas serán realizadas sólo por el patrón de la embarcación, ya que su titulación le habilita para ello.', false, '2025-09-14 14:34:29.689895+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d4d28261-d51d-48e0-84b2-16cde4e7894f', 'f73b465d-76c2-4ec8-8f62-9ef6c0b299f6', 'c', 'Si dispone de zafa de liberación hidrostática no estibe la balsa en cubierta, para evitar que la humedad la libere accidentalmente.', false, '2025-09-14 14:34:29.690364+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f0cd71c-e859-438f-a493-c5d81161e91b', 'f73b465d-76c2-4ec8-8f62-9ef6c0b299f6', 'd', 'Sólo el patrón podrá destrincar y lanzar una balsa al mar, para evitar que pueda ser dañada por cualquier otro miembro de la tripulación.', false, '2025-09-14 14:34:29.690668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e847abce-fd23-4cf7-bb4e-621cc5baea0f', '7999752b-6e3a-4b6c-b580-5457cf09795c', 'a', 'Atravesándonos a la mar.', false, '2025-09-14 14:34:29.961593+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d215b09b-177f-45c6-bee2-d1a8ef30c0a6', '7999752b-6e3a-4b6c-b580-5457cf09795c', 'b', 'Disminuyendo la velocidad y cambiando ligeramente el rumbo, ajustando ambos a las condiciones particulares del momento.', true, '2025-09-14 14:34:29.962307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e13c2a9-f446-4457-9ba0-ed61f29a04d5', '7999752b-6e3a-4b6c-b580-5457cf09795c', 'c', 'Elevando el centro de gravedad del buque con pesos en cubierta.', false, '2025-09-14 14:34:29.962598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d521447a-aee5-4a7a-939f-65b057500466', '7999752b-6e3a-4b6c-b580-5457cf09795c', 'd', 'Aumentando la velocidad para cortar las olas.', false, '2025-09-14 14:34:29.962986+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0379d708-535f-4c5a-9053-ce9a88b46066', '3b66a590-c7c9-4c63-8912-9657607320e7', 'a', 'Vire momentáneamente 70º a la banda de la caída al agua.', true, '2025-09-14 14:34:30.238226+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('804a5d57-67e1-484c-a969-ccf03434e099', '3b66a590-c7c9-4c63-8912-9657607320e7', 'b', 'Vire momentáneamente 70º a la banda contraria de la caída al agua.', false, '2025-09-14 14:34:30.238816+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c28ab242-62c4-43eb-9909-2b95b0c81fa5', '3b66a590-c7c9-4c63-8912-9657607320e7', 'c', 'Vire momentáneamente 180º a la banda de la caída al agua.', false, '2025-09-14 14:34:30.239073+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0c877cc9-936d-40e6-bd89-1fd3d0e79a63', '3b66a590-c7c9-4c63-8912-9657607320e7', 'd', 'Dé marcha atrás sin mover el timón hasta volver al punto de caída al agua.', false, '2025-09-14 14:34:30.239489+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e4016ed0-37b6-4769-9c34-e41bc792d18e', '6223f6bc-3ff0-449d-af84-4c3d655e41bd', 'a', '6 nudos.', false, '2025-09-14 14:34:30.504417+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('46afa9f8-9d60-4666-b2a8-dc817a17d023', '6223f6bc-3ff0-449d-af84-4c3d655e41bd', 'b', '4 nudos.', true, '2025-09-14 14:34:30.505115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('49d1b9a8-aa7e-466e-82bc-fc7724d983ce', '6223f6bc-3ff0-449d-af84-4c3d655e41bd', 'c', '3 nudos.', false, '2025-09-14 14:34:30.505462+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ce7cb14e-5c75-4bae-b441-9ebd358d1a83', '6223f6bc-3ff0-449d-af84-4c3d655e41bd', 'd', '12 nudos.', false, '2025-09-14 14:34:30.505953+00');
