INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('76ba1bdf-abe6-4c22-a10c-7d166b03ce3e', 'd0164073-4c7c-4d0a-8312-54e09636437e', 'b', 'De babor.', false, '2025-09-14 14:34:31.050946+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21104d4b-59f2-471d-b475-e576fcd4ad34', 'd0164073-4c7c-4d0a-8312-54e09636437e', 'c', 'Canal principal a estribor.', false, '2025-09-14 14:34:31.051128+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cf16b6b7-f50e-42d4-a5b5-caf4e8defb98', 'd0164073-4c7c-4d0a-8312-54e09636437e', 'd', 'Canal principal a babor.', false, '2025-09-14 14:34:31.051284+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebb5a534-68bf-4956-8f4f-fb72f28e0b80', 'd17fd59a-df2d-4d33-9a76-a70d9842c329', 'a', 'Pueden ser amarillas, y si llevan luz debe ser de color distinto al de la marca.', false, '2025-09-14 14:34:31.330249+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe4b2e26-fcc4-4a98-b9ce-1ce3d427f151', 'd17fd59a-df2d-4d33-9a76-a70d9842c329', 'b', 'Sus luces pueden emplear alguno de los ritmos utilizados para las luces blancas.', false, '2025-09-14 14:34:31.33057+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0b6351ef-0c7e-47a9-868e-2bf79ece6977', '63a5ee5d-d877-4bbc-a606-2d79c8e7b09b', 'b', 'La obra muerta es la parte sumergida de la embarcación que se separa de la obra viva por el plano de flotación.', false, '2025-09-14 14:34:29.149578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ebb16e66-bdca-4ff9-9a6a-d20301f3fb12', 'd17fd59a-df2d-4d33-9a76-a70d9842c329', 'c', 'El uso de pictogramas no está autorizado para este tipo de marcas.', false, '2025-09-14 14:34:31.330888+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c6f2e714-a0d4-48f9-93e1-e7ae0fc4af2b', 'd17fd59a-df2d-4d33-9a76-a70d9842c329', 'd', 'Si tuviesen marca de tope sería una "X" amarilla.', true, '2025-09-14 14:34:31.331047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cb79abde-8bc3-4934-ab49-3e25d0056af8', '4c2c5c48-0bca-4a20-9b90-46ee1bc5574b', 'a', 'Con los vértices hacia arriba.', false, '2025-09-14 14:34:31.607288+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02facec8-f660-422d-87e2-aced9748a0f6', '4c2c5c48-0bca-4a20-9b90-46ee1bc5574b', 'b', 'Con los vértices hacia abajo.', false, '2025-09-14 14:34:31.607797+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d96c3569-4064-4bfa-bddd-233bcf200205', '4c2c5c48-0bca-4a20-9b90-46ee1bc5574b', 'c', 'Opuestos por sus bases.', true, '2025-09-14 14:34:31.60803+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec977365-56e5-4c01-8678-9912cc92a4f0', '4c2c5c48-0bca-4a20-9b90-46ee1bc5574b', 'd', 'Opuestos por sus vértices.', false, '2025-09-14 14:34:31.608291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa9a0a7e-1f62-4b27-b5bf-6b5c6407ff51', 'e2a9ee39-6a71-4ea2-8c74-6fcf6d7542a4', 'a', 'Emplearse como una Ayuda a la Navegación Móvil (MatoN).', false, '2025-09-14 14:34:31.881291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0db445d2-3543-41e3-a3e4-d4b3aef06739', 'e2a9ee39-6a71-4ea2-8c74-6fcf6d7542a4', 'b', 'Incluir el uso de pictogramas para indicar su finalidad.', false, '2025-09-14 14:34:31.881773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6506b58-5a70-4d8c-a671-9046ea4b4129', 'e2a9ee39-6a71-4ea2-8c74-6fcf6d7542a4', 'c', 'Utilizarse para indicar la aproximación a un puerto.', true, '2025-09-14 14:34:31.881964+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21c5d54a-faf7-4011-b703-6c1ed045cd8c', 'b7eee57e-2c03-47b5-b36e-1fde0f13fd67', 'a', 'Toda clase de embarcación, incluidas las embarcaciones sin desplazamiento, las naves de vuelo rasante y los hidroaviones, utilizadas como medio de transporte sobre el agua.', true, '2025-09-14 14:34:32.153378+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e088fd84-6d24-4c0f-8b71-66dcd4a221cd', 'b7eee57e-2c03-47b5-b36e-1fde0f13fd67', 'b', 'Toda clase de embarcación con o sin desplazamiento, pero en ningún caso los hidroaviones, que se utilice como medio de transporte en el agua.', false, '2025-09-14 14:34:32.153833+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4dcfaaa-e633-4943-a4b8-cd477530f8b3', 'b7eee57e-2c03-47b5-b36e-1fde0f13fd67', 'd', 'Toda clase de embarcación con desplazamiento, que se utilice como medio de transporte en el agua, propulsada mecánicamente o a vela, quedando excluida todo tipo de embarcación de remo.', false, '2025-09-14 14:34:32.154668+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cfb15de4-eddd-4a53-ad3d-54ce1399369f', 'a5c81631-fd70-48f2-8dd0-9979f244b6a5', 'a', 'Una luz de tope a proa, luces de costado y una luz de alcance.', true, '2025-09-14 14:34:32.421799+00');
