INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cca5af37-2179-42ad-8561-fd15fa2315fc', 'a5c81631-fd70-48f2-8dd0-9979f244b6a5', 'c', 'Una luz de tope a proa, una segunda luz de tope a popa y luces de costado.', false, '2025-09-14 14:34:32.422583+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e5bed58f-fa85-4320-a0e0-d582df1eeafd', 'a5c81631-fd70-48f2-8dd0-9979f244b6a5', 'd', 'Una luz blanca todo horizonte a proa, luces de costado y una luz de alcance.', false, '2025-09-14 14:34:32.422772+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5b20a6f2-362d-4e48-b9d8-badd29097c33', '5855fdd7-319a-4edb-b1c5-0f7b794593a6', 'a', 'El estado de visibilidad.', false, '2025-09-14 14:34:32.688108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f11fd390-6dff-481b-825f-a2ad704a2831', '5855fdd7-319a-4edb-b1c5-0f7b794593a6', 'b', 'Las concentraciones de buques de pesca.', false, '2025-09-14 14:34:32.688549+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('454db289-ec94-4b12-8d2a-a793dca30fd1', '5855fdd7-319a-4edb-b1c5-0f7b794593a6', 'c', 'El calado en relación con la profundidad disponible.', false, '2025-09-14 14:34:32.689081+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('23ad5b15-dd58-4128-af20-4d12cbc8523e', '5855fdd7-319a-4edb-b1c5-0f7b794593a6', 'd', 'La pericia del patrón.', true, '2025-09-14 14:34:32.689311+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2b9adf67-d738-4f22-87f6-87d8cd2f3822', '2d7327c7-c50d-4969-b4d0-50efc579ec97', 'a', 'Mantenerse apartado de la derrota del otro buque.', false, '2025-09-14 14:34:32.964179+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77a212bc-90ee-4708-ae1b-ef010c05adca', '2d7327c7-c50d-4969-b4d0-50efc579ec97', 'b', 'Mantener su rumbo y velocidad.', true, '2025-09-14 14:34:32.964577+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9d9d7e83-f7cf-4c38-b22a-054bc7e685c9', '2d7327c7-c50d-4969-b4d0-50efc579ec97', 'c', 'Caer a estribor.', false, '2025-09-14 14:34:32.964842+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('42026c5a-9ca4-4411-b31b-482f2fc90f74', '2d7327c7-c50d-4969-b4d0-50efc579ec97', 'd', 'Caer a babor.', false, '2025-09-14 14:34:32.965261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ceeb8a97-6642-4e94-b8ff-67da34463e7a', '9f8676cd-9a1d-4476-ae1f-c54a0f1109e5', 'b', 'Navegar alerta y con precaución haciendo sonar una pitada larga.', true, '2025-09-14 14:34:33.22024+00');
