INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2177e65a-7a2a-4c06-b2d0-345485933bdc', '42035d47-b665-4c15-b4c4-5c0a392308f9', 'a', 'Se debe elegir siempre que sea posible un tenedero de fango duro, arena fangosa o arena dura, para facilitar el agarre del ancla.', true, '2025-09-16 14:37:39.661915+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5aaed84f-ec2a-4f82-ab5b-0d27b5cd5faf', '42035d47-b665-4c15-b4c4-5c0a392308f9', 'b', 'La embarcación debe disponer de una línea de fondeo cuya longitud será cuatro veces su eslora.', false, '2025-09-16 14:37:39.663354+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0f280a4f-5c78-4f7f-9233-e50f63d778df', '42035d47-b665-4c15-b4c4-5c0a392308f9', 'c', 'El punto de fondeo debe elegirse de forma que en un círculo de radio como mínimo igual a la longitud de la cadena filada se mantenga libre de obstáculos.', false, '2025-09-16 14:37:39.664175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('260475c9-99e0-429b-a301-bab9231176d1', '42035d47-b665-4c15-b4c4-5c0a392308f9', 'd', 'La aproximación al lugar de fondeo se hará a la velocidad máxima de gobierno, de través al viento.', false, '2025-09-16 14:37:39.664877+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('138172fa-da9e-46df-8f4a-7d758b0ae1f3', '67a6b543-c485-48c8-9a07-d59704266213', 'a', 'Tienen, en todo caso, la obligación de abanderamiento y matriculación, así como de despacho, si la propia embarcación y su equipo propulsor ostentan el marcado CE.', false, '2025-09-16 15:10:06.40687+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ca45dc7c-fcaf-4ce1-bcc7-aba0937e495a', '67a6b543-c485-48c8-9a07-d59704266213', 'b', 'En ningún caso necesitan obtener antes de su entrada en servicio un certificado de inscripción, al tener marcado CE.', false, '2025-09-16 15:10:06.408143+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92bc4dd7-343a-4570-b870-04b060616df2', '67a6b543-c485-48c8-9a07-d59704266213', 'c', 'Sólo podrán navegar en el mar territorial español y, en cualquier caso, no podrán sobrepasar las zonas de navegación a las que estén limitadas de acuerdo con su categoría de diseño.', true, '2025-09-16 15:10:06.408861+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1210cf36-8592-4c71-bcb8-cecd43eedbf3', '67a6b543-c485-48c8-9a07-d59704266213', 'd', 'Deberán llevar pintado o fijado de forma permanente en ambas amuras sólo el nombre, que se colocará a la máxima altura posible de la línea de flotación.', false, '2025-09-16 15:10:06.409598+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('feaeed10-8b37-4c00-8313-c7a2d0a3d9ea', '227dfa52-8426-41c7-aee1-87271cd80b59', 'a', 'Un cohete-bengala con paracaídas que produzca una luz roja.', true, '2025-09-16 15:16:36.249177+00');
