INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f50bc479-3de4-428d-854c-8012cce175a0', 'a38654ad-9df9-4d57-b24d-6d61bf81ca68', 'c', 'l= 36°45,4´N; L= 006°14,8´W.', false, '2025-09-16 15:29:00.582268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b8f2c3a-4b6b-4411-ab5d-991fa247a7d4', 'a38654ad-9df9-4d57-b24d-6d61bf81ca68', 'd', 'l= 35°45,4´N; L= 006°14,8´W.', false, '2025-09-16 15:29:00.582909+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('753a6b54-8edb-4b1b-b079-4f65362f0905', 'de64cad7-7cd5-4940-a3a3-aeb8bb0615b8', 'a', 'Mantenernos a rumbo ya que en ningún caso debemos maniobrar por tener preferencia frente a un velero.', false, '2025-09-16 16:00:18.570569+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9a7651e9-87f7-4cb8-8449-3c7506f1e5cf', 'de64cad7-7cd5-4940-a3a3-aeb8bb0615b8', 'b', 'Maniobrar de forma clara, con antelación y respetando las buenas prácticas marineras para apartarnos de su derrota.', true, '2025-09-16 16:00:18.571828+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('302720b7-bb7b-4a7e-99e8-f5102f7adf8f', 'de64cad7-7cd5-4940-a3a3-aeb8bb0615b8', 'c', 'Aumentar la velocidad ligeramente para tratar de propiciar que la otra embarcación haga la maniobra ante el posible peligro de abordaje, y así evitar un cambio de rumbo en nuestra derrota.', false, '2025-09-16 16:00:18.572563+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4d0452d5-72ba-4243-ad95-c41412ec64e5', 'de64cad7-7cd5-4940-a3a3-aeb8bb0615b8', 'd', 'Maniobrar cambiando de rumbo ligeramente con poca antelación para no confundir a la otra embarcación y que ella maniobre por tener obligación de hacerlo.', false, '2025-09-16 16:00:18.573287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4a953ee2-eff1-423a-a9a1-147bd84c0738', 'a42f3366-c728-45f8-908d-90e729153a5f', 'a', 'Pasar el chicote de un cabo o amarra por el grillete o argolla de la boya para hacerla firme en el barco; con ello se facilita el desamarre, pues sólo bastará arriar y después cobrar sin necesidad de ir a la boya.', true, '2025-09-16 16:09:48.070228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6da74a89-c04f-4c96-a254-e19d3940bbcd', 'a42f3366-c728-45f8-908d-90e729153a5f', 'b', 'Dar un medio nudo y encima otro hecho al revés, uniendo dos cabos por sus chicotes.', false, '2025-09-16 16:09:48.071791+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b5e5cade-a928-418d-b247-66e7f793b18a', 'a42f3366-c728-45f8-908d-90e729153a5f', 'c', 'Amarrar un cabo a una bita o cornamusa por medio de cruces en forma de ocho, aunque también se refiere al «abrazo» que se hace con el chicote de un cabo a una percha, por ejemplo, y entonces se llama vuelta mordida.', false, '2025-09-16 16:09:48.072613+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('71f37781-47da-4326-b148-9e03be3a830f', 'a42f3366-c728-45f8-908d-90e729153a5f', 'd', 'Hacer una especie de aro y meter el chicote por dentro.', false, '2025-09-16 16:09:48.073574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e07b71a8-7408-42f1-879d-171f794b72d9', 'bf63dcd7-a83e-4092-ac17-1bd669169864', 'a', 'Todo a estribor.', false, '2025-09-16 16:10:50.003116+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6db4f79c-6228-4072-91b6-8615460ad01b', 'bf63dcd7-a83e-4092-ac17-1bd669169864', 'b', 'Todo a babor.', false, '2025-09-16 16:10:50.004049+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('646dc77f-323f-4ee9-b708-6b0fdb0d8d65', 'bf63dcd7-a83e-4092-ac17-1bd669169864', 'c', 'Trincar el timón.', false, '2025-09-16 16:10:50.004494+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02f06ca3-3b1e-4903-9cd7-e130ade5764b', 'bf63dcd7-a83e-4092-ac17-1bd669169864', 'd', 'Que el plano del timón coincide con el plano de crujía de la embarcación.', true, '2025-09-16 16:10:50.005093+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('012cbfa5-b477-43ea-9327-e9ba8cc9bac6', 'e2ce41cc-c332-4f1c-9183-cf7f2d9b298a', 'a', 'Si tras la varada ha quedado en seco, hay que apuntalarla y reflotarla en bajamar mediante remolque y escora.', false, '2025-09-16 16:12:46.534008+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1cf6df3e-e118-4b32-9937-3e07db93b5f4', 'e2ce41cc-c332-4f1c-9183-cf7f2d9b298a', 'b', 'Si la varada se produjo en fondo rocoso, y no se detectan vías de agua, se dará rápidamente avante.', false, '2025-09-16 16:12:46.534726+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc86fed2-af30-43d1-a485-b23e800fcd1c', 'e2ce41cc-c332-4f1c-9183-cf7f2d9b298a', 'c', 'Si la varada es en fondo fangoso, hay que trasladar pesos para cambiar el asiento, mover lateralmente a uno y otro lado la embarcación para abrir la cama y esperar el mejor momento de la marea.', true, '2025-09-16 16:12:46.535291+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9980ef83-d800-4964-b71d-ad1e6de8fffd', '8b3accd2-00b6-4195-8e0f-35725b9870e2', 'd', 'Pleamar: Ho= 13:26, S= 6,07 ; Bajamar: Ho= 06:21 S= 5,18', false, '2025-09-25 14:19:47.911873+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3527f070-e290-4628-8a00-76374beaf091', '8b3accd2-00b6-4195-8e0f-35725b9870e2', 'c', 'Pleamar: Ho= 12:36, S= 3,06 ; Bajamar: Ho=06:21, S=1,18.', false, '2025-09-25 14:19:47.911466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1f41bf81-9784-40e7-9b88-d6969f142be5', 'e2ce41cc-c332-4f1c-9183-cf7f2d9b298a', 'd', 'Si se trata de un velero, se arriará todo el aparejo y se templará una driza desde la perilla del palo a la popa del remolque, que dará avante para provocar una escora que permita al velero dando atrás salir reflotado.', false, '2025-09-16 16:12:46.53574+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3668f41b-90ef-4293-8850-4f106081aa8f', 'df43c388-a149-4f20-abb7-652dc48eec11', 'a', 'Realizar una evaluación de los daños sufridos.', false, '2025-09-16 16:14:31.83267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0196cf11-3947-432a-ac2c-9ea292e567e4', 'df43c388-a149-4f20-abb7-652dc48eec11', 'b', 'Separar los dos barcos que se hayan visto involucrados.', true, '2025-09-16 16:14:31.833823+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('dbf5c0a2-2d0a-4736-85df-f4dcd66e30f1', 'df43c388-a149-4f20-abb7-652dc48eec11', 'c', 'Proporcionar ayuda al barco que haya sufrido daños.', false, '2025-09-16 16:14:31.83416+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('62599706-6c00-41ae-8f56-2ba61690554e', 'df43c388-a149-4f20-abb7-652dc48eec11', 'd', 'Comprobar si los tripulantes y personas a bordo han sufridos daños físicos.', false, '2025-09-16 16:14:31.835109+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c8ace613-45ce-4e50-a8fd-ff121ba78841', '0c650696-2562-4f1e-88bc-3ea910cd0af5', 'a', 'La escala Beaufort clasifica los estados de la mar en 13 grados tomando como referencia la altura de las olas.', false, '2025-09-16 16:16:26.036515+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3fa76139-8b13-415e-b2f5-32aef8882855', '0c650696-2562-4f1e-88bc-3ea910cd0af5', 'b', 'La escala Douglas clasifica los estados de la mar en 10 grados tomando como referencia la altura de las olas.', true, '2025-09-16 16:16:26.037811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('59e8b5ef-6cda-4b45-89e4-9cbc30313fd2', '0c650696-2562-4f1e-88bc-3ea910cd0af5', 'c', 'La escala Beaufort mide la intensidad del viento en 10 grados, basándose en el estado de la mar y su oleaje.', false, '2025-09-16 16:16:26.038476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e38217eb-060b-4f81-836c-63d6f48228a8', '0c650696-2562-4f1e-88bc-3ea910cd0af5', 'd', 'La escala Douglas mide la intensidad del viento en 13 grados, basándose en el estado de la mar y su oleaje.', false, '2025-09-16 16:16:26.038979+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fd59de3a-8e66-4843-9bf9-d563ef15147c', 'c4e562d8-b256-464f-9537-e4a5acfd45d3', 'a', 'Es invariable con el tiempo.', false, '2025-09-16 16:18:53.78547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('537a3a16-3b94-4317-bb9d-c09d4ae01a71', 'c4e562d8-b256-464f-9537-e4a5acfd45d3', 'b', 'Es el ángulo que forma la aguja imantada con la horizontal.', false, '2025-09-16 16:18:53.786634+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('351241ae-2be4-4c16-a1fd-d359d064e9d4', 'c4e562d8-b256-464f-9537-e4a5acfd45d3', 'c', 'Es el ángulo formado por el meridiano geográfico y el meridiano magnético.', true, '2025-09-16 16:18:53.787424+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('809e8648-fe4b-4354-a465-1c48c45cbac0', 'c4e562d8-b256-464f-9537-e4a5acfd45d3', 'd', 'Es la fuerza que hace que la aguja se oriente en el plano horizontal de forma que su norte apunte al norte magnético.', false, '2025-09-16 16:18:53.788215+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('330c319f-145f-43b5-b4a4-913df5d1bef4', '59346961-c6cb-463c-9b8e-83896928d179', 'a', 'Un viento en calma y una presión atmosférica de 998 mbar.', false, '2025-09-16 16:20:08.581204+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('21df162e-cef9-4401-94ab-238901c454bd', '59346961-c6cb-463c-9b8e-83896928d179', 'b', 'Un viento que sopla de la mar hacia tierra y una presión atmosférica de 993 mbar.', false, '2025-09-16 16:20:08.582108+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('029a509c-a1a2-4f6c-8f70-2ce4bfae9009', '59346961-c6cb-463c-9b8e-83896928d179', 'c', 'Un viento en calma y una presión atmosférica de 1.013 mbar.', false, '2025-09-16 16:20:08.58243+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f0305ca-85a8-4b47-b607-1f2c05e6cc73', '59346961-c6cb-463c-9b8e-83896928d179', 'd', 'Un viento que sopla de tierra hacia la mar y una presión atmosférica de 1.028 mbar.', true, '2025-09-16 16:20:08.582722+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7c683005-8008-4625-a997-130747060f48', '8ff54857-473f-41ad-9074-77d9bc7aad40', 'a', 'Dos luces de alcance en línea horizontal, de forma que quede señalizada la manga máxima del buque que remolca y del buque remolcado.', false, '2025-09-17 09:20:01.378522+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f6f51c77-181e-4c82-b9e8-8cedddfc6a86', '8ff54857-473f-41ad-9074-77d9bc7aad40', 'b', 'Dos luces de tope en línea vertical.', true, '2025-09-17 09:20:01.38019+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22d13479-2011-4554-a01d-66fbd25d0488', '8ff54857-473f-41ad-9074-77d9bc7aad40', 'c', 'Una luz de alcance amarilla.', false, '2025-09-17 09:20:01.380575+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85e74416-2fad-428d-ad49-be4987af68b1', '8ff54857-473f-41ad-9074-77d9bc7aad40', 'd', 'Una luz amarilla de centelleos todo horizonte.', false, '2025-09-17 09:20:01.381169+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2dad68d-5f18-422a-b388-04ff93d1a97b', '0f8d2534-c574-47fb-bc47-da022fe29844', 'a', 'Utilizaremos o exhibiremos, juntas o por separado, las distintas señales de peligro recogidas en el RIPA.', true, '2025-09-17 09:40:40.071547+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36811bfb-3291-47d8-bdab-ea7b000a5e26', '0f8d2534-c574-47fb-bc47-da022fe29844', 'b', 'Nunca utilizaremos más de una señal de peligro a la vez, ya que podrían confundir a los servicios de salvamento sobre si necesitamos ayuda o no.', false, '2025-09-17 09:40:40.072268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('101b9c11-f817-4f1d-922e-bbfd7784c006', '0f8d2534-c574-47fb-bc47-da022fe29844', 'c', 'Exhibiremos una luz amarilla de centelleos todo horizonte.', false, '2025-09-17 09:40:40.072685+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c0b63ed-dbfa-4eca-844e-a5ab7bd28ab2', '0f8d2534-c574-47fb-bc47-da022fe29844', 'd', 'Exhibiremos una luz amarilla de centelleos todo horizonte, junto con una marca bicónica.', false, '2025-09-17 09:40:40.073278+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('394df808-1150-443d-a4e9-06d0aa8d049b', '43e76036-c579-46f4-b8ed-64edb1619cfd', 'a', 'Largando amarras de proa y dando atrás toda a la par que largamos la del muerto.', false, '2025-09-17 10:04:54.795708+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13f077fc-19c4-4f3a-991e-7fbc6374aae5', '43e76036-c579-46f4-b8ed-64edb1619cfd', 'b', 'Largando amarras de proa, a continuación, la del muerto y después, dando atrás poca controlando el efecto de la hélice en la maniobra.', true, '2025-09-17 10:04:54.796789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e90ec91b-9f73-4ea4-9d6b-04594c7bd070', '43e76036-c579-46f4-b8ed-64edb1619cfd', 'c', 'Dando atrás poca a la par que largamos todas las amarras menos el esprín de proa que nos ayudará a salir girando lentamente la embarcación.', false, '2025-09-17 10:04:54.797212+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2acec876-498c-4dd8-b2fe-7f8cb05c7819', '43e76036-c579-46f4-b8ed-64edb1619cfd', 'd', 'Largando amarras de popa y dando avante poca a la par que largamos la del muerto.', false, '2025-09-17 10:04:54.797851+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('790746ba-62e2-401a-849c-1b0f6f751ff0', '606b231f-ec7f-4f8b-b8de-1ea5695cb26a', 'a', 'Para prevenir una vía de agua se debe, entre otras cosas, cerrar las válvulas que no se utilicen, asegurar la estanquidad de portillos y escotillas, fijar las baterías y todo el material pesado y evitar el agua en la sentina.', true, '2025-09-17 10:31:04.342115+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5a84e10b-989c-43ad-9e14-4b7e2a22ff77', '606b231f-ec7f-4f8b-b8de-1ea5695cb26a', 'b', 'Si falla una válvula o un pasa cascos, se taponará desde el interior con colchonetas, manteniendo apretado el cierre.', false, '2025-09-17 10:31:04.342846+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a38c1df8-898d-44be-994d-cd9a13e36981', '606b231f-ec7f-4f8b-b8de-1ea5695cb26a', 'c', 'Si a bordo detecta agua salada y fría, siempre indicará una fuga procedente de la refrigeración del motor.', false, '2025-09-17 10:31:04.343426+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5da3e6f4-b271-4a99-9c22-0722fc9713aa', '606b231f-ec7f-4f8b-b8de-1ea5695cb26a', 'd', 'Una embarcación medio hundida es peor lugar para esperar ayuda que una balsa, por lo que deberá pasar a esta en cuanto detecte una vía de agua a bordo.', false, '2025-09-17 10:31:04.343681+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('df1b5134-8442-4c4f-9eb6-28c78f92e674', '9639ab08-6d13-43f0-bb39-e9d285d4628a', 'a', 'Son regiones donde la presión atmosférica es más elevada que la de sus alrededores para el mismo nivel.', true, '2025-09-17 10:33:15.683362+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4dee975d-d011-4878-818d-484b4e4432e8', '9639ab08-6d13-43f0-bb39-e9d285d4628a', 'b', 'El aire fluye hacia su interior y allí asciende.', false, '2025-09-17 10:33:15.684333+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c0c1aa64-02e2-4654-bdb1-57e59a9da783', '9639ab08-6d13-43f0-bb39-e9d285d4628a', 'c', 'El aire asciende en su interior, lo que se conoce como subsidencia, y fluye hacia el exterior del mismo.', false, '2025-09-17 10:33:15.684656+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c50e4c50-63d2-43b1-b6f4-b5d82f56e982', '9639ab08-6d13-43f0-bb39-e9d285d4628a', 'd', 'Son regiones donde la presión atmosférica es más baja que la del aire circundante.', false, '2025-09-17 10:33:15.68484+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4cccc717-ff18-4c37-9c12-0cdefd5fc9ea', '67de96c0-aa5a-4a9a-9d84-9e86ae3c175b', 'a', 'La zona central posee una presión mayor que la de la periferia.', false, '2025-09-17 10:34:57.417508+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6716b35e-1b32-4d80-9c1e-16148c140da2', '67de96c0-aa5a-4a9a-9d84-9e86ae3c175b', 'b', 'El aire circula en sentido horario en el hemisferio norte.', false, '2025-09-17 10:34:57.418018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aadfad31-a4b4-4b9d-a978-553326c56371', '67de96c0-aa5a-4a9a-9d84-9e86ae3c175b', 'c', 'La zona central posee una presión menor que la de la periferia.', true, '2025-09-17 10:34:57.418605+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('290eab9e-e3ca-4c2c-a9a7-6a5243583ce3', '67de96c0-aa5a-4a9a-9d84-9e86ae3c175b', 'd', 'El aire circula en sentido antihorario en el hemisferio sur.', false, '2025-09-17 10:34:57.419022+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4eff08b5-20dc-4650-9adc-3df22473fcd5', 'de97cb43-1003-4ae9-8c98-776ce33cbfc0', 'a', 'La embarcación de estribor está a sotavento.', false, '2025-09-17 10:59:32.582919+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7f243a84-b935-4979-bec4-1208f667d783', 'de97cb43-1003-4ae9-8c98-776ce33cbfc0', 'b', 'La embarcación de babor está a barlovento.', false, '2025-09-17 10:59:32.583819+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('828bcebb-fcad-411a-ab63-708fc5ad3413', 'de97cb43-1003-4ae9-8c98-776ce33cbfc0', 'c', 'La embarcación de estribor está a barlovento.', true, '2025-09-17 10:59:32.584201+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e00b37a7-48b7-45c2-8894-414feec869dd', 'de97cb43-1003-4ae9-8c98-776ce33cbfc0', 'd', 'La embarcación de babor recibe el viento por la banda opuesta a la de estribor.', false, '2025-09-17 10:59:32.584937+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f0f348f-2584-42e7-aa4b-5f736a64afe5', '5bef4320-2178-4d74-9d6b-1e599e460b06', 'a', 'Opción A de prueba', true, '2025-09-17 11:03:36.024263+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93fba94a-0f24-4dec-aa35-957ea364eccd', '5bef4320-2178-4d74-9d6b-1e599e460b06', 'b', 'Opción B de prueba', false, '2025-09-17 11:03:36.025224+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0fcc41e8-a396-4451-a629-311ad779a48a', '5bef4320-2178-4d74-9d6b-1e599e460b06', 'c', 'Opción C de prueba', false, '2025-09-17 11:03:36.025782+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9c223e3a-4b06-4aee-a995-a12cb4a8def0', '5bef4320-2178-4d74-9d6b-1e599e460b06', 'd', 'Opción D de prueba', false, '2025-09-17 11:03:36.026135+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67194fc7-dd97-423e-a7e6-c920b7e9d223', 'd0a067ac-f343-45e8-b6a9-4e169e27ebcb', 'a', 'Áreas en las que está prohibida la navegación para la protección de hábitats de especies en excedente.', false, '2025-09-17 11:05:12.859361+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6634e905-f289-4c51-acfc-5185f03cb348', 'd0a067ac-f343-45e8-b6a9-4e169e27ebcb', 'b', 'Reservas de biodiversidad que tienen un interés económico-industrial especial.', false, '2025-09-17 11:05:12.86028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d664ecfd-3b7e-4fb4-8e6e-bb67731447f4', 'd0a067ac-f343-45e8-b6a9-4e169e27ebcb', 'c', 'Áreas protegidas y exclusivas para la pesca en el Mediterráneo.', false, '2025-09-17 11:05:12.860866+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c167edff-0bf4-42b3-9c62-1b6d1318f25d', 'd0a067ac-f343-45e8-b6a9-4e169e27ebcb', 'd', 'Zonas que albergan ecosistemas específicos de la zona mediterránea o hábitats de especies en peligro.', true, '2025-09-17 11:05:12.861628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('be21b6be-5ed9-41cc-9bd1-425aab19f3b1', 'f3c5b923-7276-4f38-b43f-d0125489957c', 'a', 'Ra = 008°; Hrb = 12:26.', false, '2025-09-19 22:34:16.774481+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cd2ee224-7588-44ec-8a05-6a62356e6db8', 'f3c5b923-7276-4f38-b43f-d0125489957c', 'b', 'Ra = 012°; Hrb = 11:26.', true, '2025-09-19 22:34:16.776098+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a7aebde0-a1c9-42b7-ab52-3e9db2bdc5a0', 'f3c5b923-7276-4f38-b43f-d0125489957c', 'c', 'Ra = 017°; Hrb = 11:46.', false, '2025-09-19 22:34:16.776628+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f0838bdb-50fa-400d-b659-58e9737d68af', 'f3c5b923-7276-4f38-b43f-d0125489957c', 'd', 'Ra = 019°; Hrb = 12:06.', false, '2025-09-19 22:34:16.777032+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('82cb1339-d519-4c6e-9b50-16f0204fdd1e', 'b2ba3802-55ef-42c0-8e7b-6ed8e8df029a', 'a', 'La distancia medida verticalmente entre la quilla y la cubierta.', false, '2025-09-20 22:58:50.518789+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2d0ad0cf-3bb3-4750-b6ac-bd103b51fb21', 'b2ba3802-55ef-42c0-8e7b-6ed8e8df029a', 'b', 'La distancia medida verticalmente entre la línea de flotación en máxima carga y la cubierta.', true, '2025-09-20 22:58:50.520218+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a4b56e02-2ee8-4646-aaf9-f42420b80e4d', 'b2ba3802-55ef-42c0-8e7b-6ed8e8df029a', 'c', 'La distancia medida horizontalmente entre la línea de crujía y la cubierta.', false, '2025-09-20 22:58:50.521164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('484de6e5-0383-4995-9e80-21292a97950a', 'b2ba3802-55ef-42c0-8e7b-6ed8e8df029a', 'd', 'La distancia medida horizontalmente entre la línea de flotación sin carga y la cubierta.', false, '2025-09-20 22:58:50.521839+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('787714b1-0601-41bd-9344-413aa979e0f0', '26475eec-6379-4acc-8407-c1ea25a97eef', 'a', 'Son aquellas que, vistas desde popa, giran en el mismo sentido de las agujas del reloj, es decir, a la derecha.', true, '2025-09-20 23:01:18.383495+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b95ce864-298d-415e-8711-bdb00e2d2589', '26475eec-6379-4acc-8407-c1ea25a97eef', 'b', 'Son aquellas que, vistas desde proa, giran en el mismo sentido de las agujas del reloj, es decir, a la derecha.', false, '2025-09-20 23:01:18.384578+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ea20bc4e-d99e-41a8-b30d-cd0552dc7486', '26475eec-6379-4acc-8407-c1ea25a97eef', 'c', 'Cuando navegamos con una hélice dextrógira en marcha avante la popa es empujada hacia babor (en el mismo sentido de giro).', false, '2025-09-20 23:01:18.384962+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('16f12890-46e6-49f6-abf8-4aa3069822a7', '26475eec-6379-4acc-8407-c1ea25a97eef', 'd', 'Cuando navegamos con una hélice dextrógira en marcha atrás la popa es empujada hacia estribor (en el mismo sentido de giro).', false, '2025-09-20 23:01:18.385307+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('15c853d3-dff2-4c22-893a-245132a5cce0', 'abf41ba0-838f-4ca4-93eb-cd462cf7d385', 'a', 'Al giro de una embarcación fondeada en torno al ancla, por efecto del viento o de la corriente, se le denomina garreo.', false, '2025-09-20 23:05:22.459734+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('981bbd6c-cace-46e2-bc55-54a3962088c1', 'abf41ba0-838f-4ca4-93eb-cd462cf7d385', 'b', 'Se deben tomar referencias a tierra para asegurarnos que el ancla no garrea y vigilar la sonda marcando un fondo mínimo con la alarma.', true, '2025-09-20 23:05:22.460269+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1911f61-3e78-4b81-8faa-d2be07571fdd', 'abf41ba0-838f-4ca4-93eb-cd462cf7d385', 'c', 'De forma general, la longitud de cadena para un fondeo con mal tiempo no será superior a una o dos veces la sonda del lugar de fondeo.', false, '2025-09-20 23:05:22.460581+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('047516c3-8e18-4bb3-8711-ca7c0de2516d', 'abf41ba0-838f-4ca4-93eb-cd462cf7d385', 'd', 'Se debe elegir siempre que sea posible un tenedero rocoso o con algas, para facilitar el agarre del ancla.', false, '2025-09-20 23:05:22.460876+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('05585e3b-7e90-4316-b131-b87134ddfa44', '0fdf1edc-85b0-45be-9ec4-fd2abaf18e5c', 'a', 'Dedicadas exclusivamente al recreo que se detengan en calas o lugares de baño balizados como zona o lugar de baño, si fondean a menos de 50 metros de la costa.', false, '2025-09-22 21:30:51.393047+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('09df4f3a-3d5d-49f5-bdc3-c46f312c0d19', '0fdf1edc-85b0-45be-9ec4-fd2abaf18e5c', 'b', 'De cualquier clase que se detengan con una finalidad recreativa, en calas o lugares de baño balizados como zona o lugar de baño, si fondean a menos de 200 metros de la costa.', false, '2025-09-22 21:30:51.394466+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ddd32e85-2b3c-43d9-bba2-0d1c65a4083f', '0fdf1edc-85b0-45be-9ec4-fd2abaf18e5c', 'c', 'De cualquier clase que se detengan con una finalidad recreativa en calas o lugares de baño balizados como tal y no pongan en peligro la seguridad de la vida humana en la mar o de la navegación.', false, '2025-09-22 21:30:51.395608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('85deb701-7ce6-48fc-b09b-f16b2bdb4d1f', '0fdf1edc-85b0-45be-9ec4-fd2abaf18e5c', 'd', 'Exclusivamente de recreo que se detengan con tal finalidad en calas o lugares de baño no balizados y no pongan en peligro la seguridad de la vida humana en la mar o de la navegación.', true, '2025-09-22 21:30:51.396075+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11b1ef57-e3b6-4f84-a72b-fba1b1a511a5', 'e8865659-a952-4fcd-9b25-d65d8f17f335', 'a', 'Puntal.', false, '2025-09-24 13:29:23.148365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b48656cc-7ffc-416d-a3d2-ad26be6c5b9f', 'e8865659-a952-4fcd-9b25-d65d8f17f335', 'b', 'Plan.', true, '2025-09-24 13:29:23.149701+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f5be78ba-8b78-43b2-87b9-b30f3019f91d', 'e8865659-a952-4fcd-9b25-d65d8f17f335', 'c', 'Mamparo.', false, '2025-09-24 13:29:23.150261+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('97644061-9502-49e8-8d42-6973e80ca958', 'e8865659-a952-4fcd-9b25-d65d8f17f335', 'd', 'Crujía.', false, '2025-09-24 13:29:23.150743+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fe0c4378-b084-4f65-adcb-5b12ac8fe106', 'ab11fb9e-9df0-401f-826a-14cc7527f793', 'a', 'Virar es cobrar cabo o cadena de la línea de fondeo al levar anclas o en cualquier momento de la maniobra.', false, '2025-09-24 13:34:02.830453+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9018f484-9514-4f0e-9ad4-4deb50d0081f', 'ab11fb9e-9df0-401f-826a-14cc7527f793', 'b', 'Filar es largar o arriar cabo o cadena al fondear o en cualquier otro momento de la maniobra.', false, '2025-09-24 13:34:02.830834+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1c407f9-d44d-429f-b5e1-952ff0ab8719', 'ab11fb9e-9df0-401f-826a-14cc7527f793', 'c', 'Zarpar es el momento en que el ancla toca el fondo en la maniobra de fondeo.', true, '2025-09-24 13:34:02.831191+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('adb2ccc2-ca80-4505-8774-f84e5ee5c917', '2b3a6bdb-9d9b-4d44-ac4e-5389442c7ece', 'a', 'De 8 a 10 metros.', false, '2025-09-24 13:43:42.482031+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('68093a5d-5d15-43a2-a4bc-d613eefe3318', '2b3a6bdb-9d9b-4d44-ac4e-5389442c7ece', 'b', 'De 10 a 18 metros.', false, '2025-09-24 13:43:42.483268+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6e3ece15-4233-48e3-a649-efea380c28b6', '2b3a6bdb-9d9b-4d44-ac4e-5389442c7ece', 'c', 'De 24 a 40 metros.', true, '2025-09-24 13:43:42.483883+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b787d649-4bed-4d3b-8eeb-f4b5ef2bd94d', '2b3a6bdb-9d9b-4d44-ac4e-5389442c7ece', 'd', 'De 48 a 56 metros.', false, '2025-09-24 13:43:42.484365+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f2b2d2e-9c2b-41bc-a26a-81c8f3f2ca5b', '7e328c12-bb6c-4b62-b355-af8b23686086', 'a', 'Todos los grifos de fondo estén cerrados.', false, '2025-09-24 13:55:49.571938+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f2e156c8-8d2e-41a9-8dd2-f4f5d71ea659', '7e328c12-bb6c-4b62-b355-af8b23686086', 'b', 'Todas las lumbreras están herméticamente cerradas.', false, '2025-09-24 13:55:49.573181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bc9e8672-0b66-46da-a308-ec55d2a29ce5', '7e328c12-bb6c-4b62-b355-af8b23686086', 'c', 'Se ha comunicado el Plan de navegación a alguien en tierra.', true, '2025-09-24 13:55:49.573747+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7776e955-2905-49c0-9327-3e1d4cd0f0fe', '7e328c12-bb6c-4b62-b355-af8b23686086', 'd', 'La batería del móvil está cargada, para utilizarlo siempre como vía para realizar una llamada de emergencia.', false, '2025-09-24 13:55:49.574164+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('02608d0d-bc43-4283-8ee7-a45b32ef1416', '72498e81-3cae-40eb-be1c-28c199e67eda', 'a', 'Una luz de tope a proa, una luz de tope a popa más alta que la de proa, luces de costado y una luz', false, '2025-09-24 14:29:09.947091+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa93091c-4002-4048-9efe-35fd1c1e0e6c', '72498e81-3cae-40eb-be1c-28c199e67eda', 'b', 'Una luz de tope a proa, luces de costado y una luz de alcance.', true, '2025-09-24 14:29:09.948183+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('842b86db-c87d-48d4-b3b0-fd640c90496d', '72498e81-3cae-40eb-be1c-28c199e67eda', 'c', 'Una luz blanca todo horizonte y luces de costado.', false, '2025-09-24 14:29:09.948637+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5f6ba2e0-863d-4a43-b615-2365e7361503', '72498e81-3cae-40eb-be1c-28c199e67eda', 'd', 'Una luz blanca todo horizonte y, si es posible, exhibirá también luces de costado.', false, '2025-09-24 14:29:09.94906+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1bd98ca4-0ad7-45e6-98b4-8ee2b06044d5', '541407a1-907e-40e8-87c9-fd77ba722160', 'a', 'Ciando despacio.', false, '2025-09-24 14:42:06.067264+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36e2cf08-ebee-44a5-91f9-fa555faaccc0', '541407a1-907e-40e8-87c9-fd77ba722160', 'b', 'A favor del viento o de la corriente.', false, '2025-09-24 14:42:06.068253+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('567f3832-fef4-4cd0-a413-c793ed6ea123', '541407a1-907e-40e8-87c9-fd77ba722160', 'c', 'En contra del viento o de la corriente.', true, '2025-09-24 14:42:06.069436+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de0df15f-1cc5-4328-a24c-b0e413de6e39', '541407a1-907e-40e8-87c9-fd77ba722160', 'd', 'No influye el viento ni la corriente.', false, '2025-09-24 14:42:06.07085+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d174dc41-b8e1-47bc-8358-58c9188a9dcc', 'd9c200dc-eda4-4e3b-9a65-e80f5f56761a', 'a', 'Dando avante poca, rueda a estribor y el esprín de proa firme.', false, '2025-09-24 14:43:51.05675+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('27972f9b-33b3-4d96-afb8-015f77c594f7', 'd9c200dc-eda4-4e3b-9a65-e80f5f56761a', 'b', 'Dando atrás poca y con el esprín de popa firme.', true, '2025-09-24 14:43:51.057603+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('89f23365-f786-42b3-b217-f8a1b14d3137', 'd9c200dc-eda4-4e3b-9a65-e80f5f56761a', 'c', 'Sin emplear máquina ni timón, iremos lascando poco a poco el largo de popa.', false, '2025-09-24 14:43:51.058084+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3ecab5a0-a181-4a61-bb1b-d81c7d9162be', 'd9c200dc-eda4-4e3b-9a65-e80f5f56761a', 'd', 'Dando avante poca, rueda a estribor y el largo de popa firme.', false, '2025-09-24 14:43:51.0584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bf9a375-5173-43ef-a031-4dba43e52670', '4ff792b9-6f17-4cd0-8a2e-501ededd4537', 'a', 'Atacaremos el fuego por la base de las llamas y nos aproximaremos siempre mirando al fuego.', false, '2025-09-24 14:45:29.005975+00');
