INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('67ee758c-6451-4223-8f27-c7e9aceda6f0', '4ff792b9-6f17-4cd0-8a2e-501ededd4537', 'c', 'Utilizaremos como agente extintor el polvo seco.', false, '2025-09-24 14:45:29.007456+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('de35c14d-7c51-4615-984c-acb2e7ad86ee', '4ff792b9-6f17-4cd0-8a2e-501ededd4537', 'd', 'Posicionaremos la embarcación de forma que el foco principal del incendio quede a barlovento para evitar la propagación del fuego.', true, '2025-09-24 14:45:29.007903+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('73a51b4e-9288-48cb-adfd-70b3a8001aa0', 'c9d81194-2bbf-4777-ad77-359a118b2fc2', 'a', 'El eje de simetría longitudinal de la proyección horizontal del casco.', true, '2025-09-24 21:59:58.577886+00');
