INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b32031ef-0dec-4d0f-be41-2336e0a56ce9', '154c97a8-7ba9-4ca3-ac91-8e2d9716a372', 'a', 'Podría indicar la presencia de un buque fondeado de 75 metros de eslora.', true, '2025-09-24 22:09:40.897699+00');
