INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9de14c20-7e44-4ec1-98ce-d601b08ff1a7', '154c97a8-7ba9-4ca3-ac91-8e2d9716a372', 'c', 'Podría indicar la presencia de un buque de propulsión mecánica en navegación, de 5 metros de eslora, con una velocidad máxima inferior a 7 nudos.', false, '2025-09-24 22:09:40.899018+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b1db3d93-fd13-4e85-a461-1c1e5bab6780', '154c97a8-7ba9-4ca3-ac91-8e2d9716a372', 'd', 'Podría indicar la presencia de un buque de propulsión mecánica en navegación, de 6 metros de eslora, con una velocidad máxima inferior a 6 nudos.', false, '2025-09-24 22:09:40.899389+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c88db394-725a-4fef-b6c3-9d77cbefb977', 'c2633abd-4463-4903-b2b0-f1d7db60393f', 'a', 'El buque que deba mantenerse apartado de la derrota del otro mantendrá su rumbo y velocidad.', false, '2025-09-24 22:13:09.004028+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f5c582c-6513-4a82-852e-eeebbf926150', 'c2633abd-4463-4903-b2b0-f1d7db60393f', 'b', 'No exime al buque que cede el paso de su obligación de mantenerse apartado de la derrota del otro.', true, '2025-09-24 22:13:09.005336+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fc3b5c03-083c-4856-9f29-c5cbd9e59446', 'c2633abd-4463-4903-b2b0-f1d7db60393f', 'c', 'Solamente el buque que ceda el paso podrá ejecutar la maniobra que mejor pueda ayudar a evitar el abordaje.', false, '2025-09-24 22:13:09.005848+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9515e0ce-f7aa-4794-b707-d5ec2f0ff2a9', 'c2633abd-4463-4903-b2b0-f1d7db60393f', 'd', 'Cuando uno de los buques deba mantenerse apartado de la derrota del otro, éste último se detendrá obligatoriamente.', false, '2025-09-24 22:13:09.006571+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2fcc592-0f01-4ba8-92b1-0da8ad6e63e0', '0b2aa1e1-6739-47f1-92c1-054de3e03455', 'a', 'Disminuye la acción del timón con marcha avante y hélice avante.', false, '2025-09-24 22:20:13.828049+00');
