INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('43ac00fb-9852-45ee-b34c-45346a284e20', '99545ed9-dc68-4dc5-827c-bbf3cae3e1b1', 'a', 'Viento intenso que se produce en invierno en la zona tropical al rolar los alisios.', false, '2025-09-24 22:23:48.359305+00');
