INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8fd0c564-c876-403e-8dfd-239b4dda5bb3', '0e3e59c7-c22a-4d1e-8563-26f73c9c5b47', 'a', 'Es el ángulo que forma la visual dirigida a un objeto con la línea Norte-Sur.', false, '2025-09-24 22:27:22.771184+00');
