INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7386f7bc-a53e-4488-b3fb-161aff21dd81', '10a8d200-ae12-438e-808e-a27366238556', 'a', 'No estorbar el tránsito del portacontenedores.', true, '2025-09-25 13:36:22.922608+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e271326a-72d8-4131-b95a-ab048a3e7813', '10a8d200-ae12-438e-808e-a27366238556', 'b', 'Seguir el sentido de la corriente pasando en cualquier caso por la banda de estribor del portacontenedores.', false, '2025-09-25 13:36:22.923541+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('948fc9b8-6abc-42c8-9462-9e3c3c7bfea5', '10a8d200-ae12-438e-808e-a27366238556', 'c', 'Hacer sonar una pitada larga cada 5 segundos y caer a babor.', false, '2025-09-25 13:36:22.924502+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('29d527c0-62d7-403d-b0d9-0a11515a4d22', '10a8d200-ae12-438e-808e-a27366238556', 'd', 'No estorbar el tránsito, navegando en cualquier caso lo más cerca posible del límite exterior del canal por su costado de babor.', false, '2025-09-25 13:36:22.924874+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d7af2034-4bc1-4466-aea1-23ee95fa54f7', '03520a6d-4a8b-49d6-a818-fcd9a72cb7df', 'a', 'Un sonido continuo producido por cualquier aparato de señales de niebla.', false, '2025-09-25 13:43:41.787135+00');
