INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d556eeba-eee0-4a7a-97dd-391284503987', '03520a6d-4a8b-49d6-a818-fcd9a72cb7df', 'c', 'Una alerta de socorro buque-costera transmitido por la estación terrena de buque de Inmarsat u otro proveedor de servicios móviles por satélite.', false, '2025-09-25 13:43:41.788425+00');
