INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3f0e9966-9e88-4f3f-a4a1-a5fc4466a9ae', '1e1d57ae-35d2-433b-bf4c-3dbbaa942d9d', 'a', 'Consiste en hacer girar la embarcación sobre sí misma.', false, '2025-09-25 13:46:27.202975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('92f53d82-ce8b-4b9f-b4ab-eaa37785fd64', '1e1d57ae-35d2-433b-bf4c-3dbbaa942d9d', 'b', 'Es el período final de la curva de evolución que se caracteriza principalmente por una caída de la velocidad superior al 50%.', false, '2025-09-25 13:46:27.204335+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bdc042f5-48a6-47d5-9d5a-ccf0568995a5', '1e1d57ae-35d2-433b-bf4c-3dbbaa942d9d', 'c', 'Es el movimiento uniforme de caída que se crea una vez se ha alcanzado el grado deseado con la acción del timón y las fuerzas actuantes se han equilibrado.', false, '2025-09-25 13:46:27.205234+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('60bbb627-edd5-4c9c-87de-7ca2f4cc08cd', '1e1d57ae-35d2-433b-bf4c-3dbbaa942d9d', 'd', 'Se inicia en el momento en el que se mete el timón a la banda y finaliza al alcanzar el grado deseado.', true, '2025-09-25 13:46:27.205696+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8f56f54e-419c-408b-8bbb-573830a0e6c1', '0b3e71de-9284-4868-acb3-3e07ef70272b', 'a', 'Nunca.', false, '2025-09-25 14:06:03.561229+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41e66af5-6a3d-4db3-a96b-3b82ec0d7ff3', '0b3e71de-9284-4868-acb3-3e07ef70272b', 'b', 'Sólo cuando se produzca un incendio.', false, '2025-09-25 14:06:03.56209+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('41fb415b-1ee4-4f28-a1c4-31985f251299', '0b3e71de-9284-4868-acb3-3e07ef70272b', 'c', 'Sin precipitarnos, cuando tengamos la completa seguridad de que se va a hundir.', true, '2025-09-25 14:06:03.562576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c2084b27-ac2a-4fb6-b5d3-651ef57ec974', '0b3e71de-9284-4868-acb3-3e07ef70272b', 'd', 'Sólo cuando tengamos la completa certeza de que otro barco nos está viendo.', false, '2025-09-25 14:06:03.562975+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fad3ded8-e802-43ea-b688-6bfb8dbac7c8', '3da080f5-7f1f-4e4d-a7c5-b449703b5295', 'a', 'Sí, siempre y cuando ésta haya sido emitida en formato LSD en el canal 9 por un usuario con autorización emitida por la Comunidad Autónoma correspondiente.', false, '2025-09-25 14:08:12.603189+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('fa2fc986-970e-409f-a377-3fa7faa96251', '3da080f5-7f1f-4e4d-a7c5-b449703b5295', 'b', 'No, debe ser emitida en formato papel, a través de la AEMET.', false, '2025-09-25 14:08:12.604324+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('77247e5f-6f97-4981-a958-7b36ecfe0a7d', '3da080f5-7f1f-4e4d-a7c5-b449703b5295', 'c', 'Sí, pero la transmisión debe ser emitida por un Centro de Salvamento Marítimo o Estación Radiocostera.', true, '2025-09-25 14:08:12.604801+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b0f51eb-338b-44bc-bfd9-0044ea76af08', '3da080f5-7f1f-4e4d-a7c5-b449703b5295', 'd', 'Sí, pero para ser válida ésta debe ser recibida expresamente por NAVTEX.', false, '2025-09-25 14:08:12.60518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('daa96259-192e-4ecb-939b-e59c91585ecd', '8b3accd2-00b6-4195-8e0f-35725b9870e2', 'b', 'Pleamar: Ho= 12:36, S= 3,06 ; Bajamar: Ho=06:21, S=1,18.', false, '2025-09-25 14:19:47.911097+00');
