INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ef50ae79-b336-4313-87a3-4242a299e18f', '8b3accd2-00b6-4195-8e0f-35725b9870e2', 'a', 'Pleamar: Ho= 13:36, S= 7,06 ; Bajamar: Ho= 07:21, S= 5,18.', true, '2025-09-25 14:19:47.910561+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ab727211-77a7-4789-a9ce-0b3ccf894f15', '669d96cb-71e1-4f17-8226-4668709119c6', 'a', 'Esféricas, de castillete o espeque, con franjas verticales rojas y blancas, y su marca de tope es una esfera roja.', true, '2025-09-25 22:03:59.050341+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d6530fa2-559c-4754-baec-e3bbe838b536', '669d96cb-71e1-4f17-8226-4668709119c6', 'b', 'Esféricas, de castillete o espeque, con franjas horizontales azules y blancas, y su marca de tope es un aspa roja.', false, '2025-09-25 22:03:59.051287+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('d234cfbe-e79f-48ea-bf34-12640e3c82c4', '669d96cb-71e1-4f17-8226-4668709119c6', 'c', 'Cónicas, de castillete o espeque, con franjas verticales azules o blancas, y su marca de tope es un aspa amarilla.', false, '2025-09-25 22:03:59.052021+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5c4fa770-2a17-4bc8-9ad8-d120d37f3b8d', '669d96cb-71e1-4f17-8226-4668709119c6', 'd', 'Cónicas, de castillete o espeque, con franjas horizontales rojas o blancas, y su marca de tope es una esfera amarilla.', false, '2025-09-25 22:03:59.052572+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7598e9b2-099c-4fe9-bfbf-3733cfacd562', 'f01d4dea-9942-4a83-88b3-99ac2fb78d35', 'a', 'Números pares para las verdes, números impares para las rojas.', false, '2025-09-25 22:05:55.999051+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ec2cc902-898f-4777-a76c-8955079fa109', 'f01d4dea-9942-4a83-88b3-99ac2fb78d35', 'b', 'Números pares para las rojas, números impares para las blancas.', false, '2025-09-25 22:05:56.000036+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2af10148-9e6a-436b-a5a7-3dde8cb4fd65', 'f01d4dea-9942-4a83-88b3-99ac2fb78d35', 'c', 'Números pares para las verdes, números impares para las blancas.', false, '2025-09-25 22:05:56.000576+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b0edf458-e0df-4e46-84a9-7872e387822f', 'f01d4dea-9942-4a83-88b3-99ac2fb78d35', 'd', 'Números pares para las rojas, números impares para las verdes.', true, '2025-09-25 22:05:56.000867+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('93b4c5d9-4290-4ec8-838e-49268885d255', '2cdac66f-a0b8-47e4-bd9d-a352faf28529', 'a', 'No estorbarán el tránsito de un buque que sólo pueda navegar con seguridad dentro del canal.', true, '2025-09-25 22:10:08.676718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('50ced690-a67e-4d70-8b9e-df95d742ecd7', '2cdac66f-a0b8-47e4-bd9d-a352faf28529', 'b', 'No podrán transitar a vela el canal.', false, '2025-09-25 22:10:08.677504+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('975c01b6-65b3-44de-9cdd-c7204b892b02', '2cdac66f-a0b8-47e4-bd9d-a352faf28529', 'c', 'Deberán hacer sonar dos pitadas largas cada 20 segundos para indicar su tránsito por el canal.', false, '2025-09-25 22:10:08.678221+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('914c5899-21a5-41e5-941d-c5c9126449da', '2cdac66f-a0b8-47e4-bd9d-a352faf28529', 'd', 'No estorbarán el tránsito de un buque dedicado a la pesca que esté faenando en el canal.', false, '2025-09-25 22:10:08.678596+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6ddea600-f774-4416-ab2b-6fef00c210ef', 'd759844f-4560-48fa-b779-f289de30a928', 'a', 'Se evitarán las suposiciones basadas en información insuficiente, especialmente la obtenida por radar.', true, '2025-09-26 08:25:36.802518+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35a4721d-d148-459f-971d-87a6c79c1e75', 'd759844f-4560-48fa-b779-f289de30a928', 'b', 'En caso de abrigarse alguna duda respecto a si existe riesgo de abordaje, se considerará que no existe.', false, '2025-09-26 08:25:36.803847+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9ee5665e-c24d-48f9-bfea-9f1abc5fbc20', 'd759844f-4560-48fa-b779-f289de30a928', 'c', 'Por regla general, se considerará que existe riesgo de abordaje, si la demora de un buque que se aproxima varía en forma apreciable.', false, '2025-09-26 08:25:36.804393+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a79be9a8-b8c8-4aaa-b64b-fc6978262680', 'd759844f-4560-48fa-b779-f289de30a928', 'd', 'No se utilizará el equipo radar para determinar si existe riesgo de abordaje.', false, '2025-09-26 08:25:36.805003+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('aa5803c2-32fc-46fe-ab4f-66e7969875cc', '47e2752c-e135-48de-9d26-95046b721b36', 'a', 'Deberá en cualquier caso utilizar las vías de circulación siguiendo la dirección general de la corriente de tráfico.', false, '2025-09-26 08:33:26.949321+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36b09fa4-e238-4452-af02-de140e66b702', '47e2752c-e135-48de-9d26-95046b721b36', 'b', 'Navegará preferiblemente por la zona de separación del tráfico para no estorbar el tránsito de los buques mercantes.', false, '2025-09-26 08:33:26.950592+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5857fdc2-646d-4daa-b759-77d46cc15d32', '47e2752c-e135-48de-9d26-95046b721b36', 'c', 'Podrá utilizar la zona de navegación costera o, si puede hacerlo en condiciones de seguridad y sin estorbar, la vía de circulación adecuada del dispositivo.', true, '2025-09-26 08:33:26.95146+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b6ad867e-909a-4876-ac88-79b1710b7831', '47e2752c-e135-48de-9d26-95046b721b36', 'd', 'Deberá en cualquier caso utilizar la zona de navegación costera.', false, '2025-09-26 08:33:26.952325+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('35774489-3690-4a48-a8e2-db8404ccaa4c', '455e474a-e7f0-416c-af71-132b0ca5ef76', 'a', 'Atacaremos el fuego por la base de las llamas y nos aproximaremos siempre mirando al fuego.', false, '2025-09-26 08:39:31.30181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a1112d43-4312-447b-beeb-ab07c4d5f635', '455e474a-e7f0-416c-af71-132b0ca5ef76', 'b', 'Si existe corriente de aire nos aproximaremos con ésta a nuestra espalda.', false, '2025-09-26 08:39:31.302799+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e68e759d-593b-40c7-b260-b2f72637f263', '455e474a-e7f0-416c-af71-132b0ca5ef76', 'c', 'Utilizaremos como agente extintor el polvo seco.', false, '2025-09-26 08:39:31.303521+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('8971c13b-a020-41b8-8b77-cdcee004c96e', '455e474a-e7f0-416c-af71-132b0ca5ef76', 'd', 'Posicionaremos la embarcación de forma que el foco principal del incendio quede a barlovento para evitar la propagación del fuego.', true, '2025-09-26 08:39:31.304048+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('7aff99f8-8ca7-46aa-a350-78b497917182', '79c5b5ae-b3b4-4138-9aa0-a57af98339e2', 'a', 'Si una persona sufre una fuerte contusión en el abdomen, se le proporcionara reposo absoluto, manteniéndose en observación y se realizarán consultas radiomédicas.', false, '2025-09-26 08:42:56.518272+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('330d16a1-e9b5-43db-b76b-ae78266fca03', '79c5b5ae-b3b4-4138-9aa0-a57af98339e2', 'b', 'En una hemorragia arterial la sangre mana a impulsos y habrá que realizar un torniquete un poco por encima de la herida.', false, '2025-09-26 08:42:56.519355+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a455e3e4-3865-4759-b5bf-fbeaff47847b', '79c5b5ae-b3b4-4138-9aa0-a57af98339e2', 'c', 'En caso de insolación hay que sumergir al afectado en agua fría para bajar la temperatura hasta los 35º.', true, '2025-09-26 08:42:56.519748+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('f148a310-017b-4a59-afe6-637caf1249b5', '79c5b5ae-b3b4-4138-9aa0-a57af98339e2', 'd', 'Las quemaduras de tercer grado son las producidas por acción intensa y directa de una llama o sólido incandescente y la costra que se produce no debe ser destruida. Meteorología', false, '2025-09-26 08:42:56.520134+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('519951d0-bba6-41d3-af09-f2947bf16c98', 'efe49d36-adbc-4861-9d96-78e6ff89011b', 'b', 'El punto de congelación del agua es la temperatura más baja que se puede medir.', false, '2025-09-26 08:44:55.614326+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2bd0f6d5-28e1-4420-866b-568fc5cf56b6', 'efe49d36-adbc-4861-9d96-78e6ff89011b', 'c', 'El punto de ebullición del agua es la temperatura más alta que se puede medir.', false, '2025-09-26 08:44:55.614534+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('48d62a1c-d5dd-48f7-b64c-c58f013652c5', 'efe49d36-adbc-4861-9d96-78e6ff89011b', 'd', 'Su unidad es el grado centígrado.', true, '2025-09-26 08:44:55.614822+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ecbd6f8a-fc58-470d-8c74-548d0a729f82', '13a7d1b8-f5a7-4e7b-b5a6-d36a40e13dd7', 'a', 'Terral.', false, '2025-09-26 08:47:18.247729+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b2f554d2-9062-4aca-b0e3-317443d7c10b', '13a7d1b8-f5a7-4e7b-b5a6-d36a40e13dd7', 'b', 'Viento aparente.', false, '2025-09-26 08:47:18.248505+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bb2f9b22-3bea-413c-ba54-a1ab8ede20e5', '13a7d1b8-f5a7-4e7b-b5a6-d36a40e13dd7', 'c', 'Viento real.', false, '2025-09-26 08:47:18.248945+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e89bb328-44dc-4aea-8a7f-dd1fdf745ada', '13a7d1b8-f5a7-4e7b-b5a6-d36a40e13dd7', 'd', 'Virazón.', true, '2025-09-26 08:47:18.249889+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('08a7a4c3-d9d0-44d4-90d4-25cfd192333e', '7db6c9a1-27dc-435b-9ae3-2bc3e1e956ae', 'a', 'Pleamar: 7,15 m. / Bajamar: 8,38 m.', false, '2025-09-26 08:50:32.033718+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('5bc4a348-137e-4475-b333-fb37053abfaf', '7db6c9a1-27dc-435b-9ae3-2bc3e1e956ae', 'b', 'Pleamar: 3,22 m. / Bajamar: 4,45 m.', false, '2025-09-26 08:50:32.034491+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3746fcd3-39a6-4339-b977-96bb2c3a8a48', '7db6c9a1-27dc-435b-9ae3-2bc3e1e956ae', 'c', 'Pleamar: 8,58 m. / Bajamar: 7,35 m.', false, '2025-09-26 08:50:32.034802+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('40e85b1f-36c3-456f-bf15-d6cdbd4d3cf8', '7db6c9a1-27dc-435b-9ae3-2bc3e1e956ae', 'd', 'Pleamar: 8,38 m. / Bajamar: 7,15 m.', true, '2025-09-26 08:50:32.035267+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2157dbee-102f-419d-bbf9-7d3dc9b3829d', 'e2c567a1-0c62-4d62-a6af-edca7db7a73e', 'a', '9,32 metros.', true, '2025-09-26 08:51:59.177373+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e6ed3b8-d6df-4a8f-8eca-a1da63c34867', 'e2c567a1-0c62-4d62-a6af-edca7db7a73e', 'b', '9,02 metros.', false, '2025-09-26 08:51:59.178476+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3684eb19-e0d3-4b9a-bfe3-8c386332deaf', 'e2c567a1-0c62-4d62-a6af-edca7db7a73e', 'c', '10,02 metros.', false, '2025-09-26 08:51:59.178892+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('36600922-e8c9-423d-88c8-7324911c7298', 'e2c567a1-0c62-4d62-a6af-edca7db7a73e', 'd', '9,72 metros.', false, '2025-09-26 08:51:59.179239+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('bd432cd3-db19-40ff-a33d-d0a50530227d', 'c148c34e-6b71-4ffe-856e-d3570860c473', 'a', 'Una pieza metálica que por un lado tiene un aro, gancho o argolla, y por el otro una rosca para fijarlo en el lugar del barco que nos interese, y que se usa para unir o afirmar algo.', false, '2025-09-26 09:52:18.252811+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e14aeb2-d980-4941-a38b-5c1c86b32e9b', 'c148c34e-6b71-4ffe-856e-d3570860c473', 'b', 'Una pieza de metal, comúnmente en forma de U, atravesada en sus extremos perforados por un perno.', true, '2025-09-26 09:52:18.253815+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('453d99b3-52e5-4aae-9363-a6461938e93f', 'c148c34e-6b71-4ffe-856e-d3570860c473', 'c', 'Una pieza de metal, encorvada en sus extremos y fija por su punto medio que sirve para amarrar los cabos.', false, '2025-09-26 09:52:18.254274+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c48cefa1-1e54-4659-8446-53ec5237d660', 'c148c34e-6b71-4ffe-856e-d3570860c473', 'd', 'Un utensilio en forma de anilla, de acero o aleaciones de aluminio, que tiene un pasador o gozne que se abre y se cierra mediante un muelle.', false, '2025-09-26 09:52:18.254976+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('db7fa31a-d82b-43e7-82e1-691ced09b4b9', 'dcb8111b-2997-4922-8efe-57ac516ccea9', 'a', 'Una pieza metálica que por un lado tiene un aro, gancho o argolla, y por el otro una rosca para fijarlo en el lugar del barco que nos interese, y que se usa para unir o afirmar algo.', false, '2025-09-26 09:53:10.75172+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('987fe166-8648-4bfe-918b-78c9a913a039', 'dcb8111b-2997-4922-8efe-57ac516ccea9', 'b', 'Una pieza de metal, comúnmente en forma de U, atravesada en sus extremos perforados por un perno.', true, '2025-09-26 09:53:10.752431+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('c1d19110-c376-452a-828d-39e747997bd7', 'dcb8111b-2997-4922-8efe-57ac516ccea9', 'c', 'Una pieza de metal, encorvada en sus extremos y fija por su punto medio que sirve para amarrar los cabos.', false, '2025-09-26 09:53:10.752773+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('ff6f8c96-257b-4387-a3e9-1fea29925076', 'dcb8111b-2997-4922-8efe-57ac516ccea9', 'd', 'Un utensilio en forma de anilla, de acero o aleaciones de aluminio, que tiene un pasador o gozne que se abre y se cierra mediante un muelle.', false, '2025-09-26 09:53:10.753056+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('104b746a-1e89-4507-89c3-72c8a0827606', 'dbe01fe7-d78a-47fa-8577-ff15da5e1385', 'a', 'Son aquellas que, vistas desde popa, giran en el mismo sentido de las agujas del reloj, es decir, a la derecha.', true, '2025-09-26 09:55:24.603745+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('3b9ebaa5-abd0-4333-a21c-96a38f3d64b1', 'dbe01fe7-d78a-47fa-8577-ff15da5e1385', 'b', 'Son aquellas que, vistas desde proa, giran en el mismo sentido de las agujas del reloj, es decir, a la derecha.', false, '2025-09-26 09:55:24.60464+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4e02aa5f-a85d-431c-98d8-7966f6058eb8', 'dbe01fe7-d78a-47fa-8577-ff15da5e1385', 'c', 'Cuando navegamos con una hélice dextrógira en marcha avante la popa es empujada hacia babor (en el mismo sentido de giro).', false, '2025-09-26 09:55:24.605363+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('da1a901c-592d-4d65-b137-a587c3b57cf6', 'dbe01fe7-d78a-47fa-8577-ff15da5e1385', 'd', 'Cuando navegamos con una hélice dextrógira en marcha atrás la popa es empujada hacia estribor (en el mismo sentido de giro).', false, '2025-09-26 09:55:24.605683+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('b30c7f73-77d9-4dab-8bbb-dd19dbc2dbe4', 'af35415d-8051-4b3b-bab9-fb49a7b9d8dd', 'a', 'El rezón es un ancla pequeña, de tres uñas y sin cepo, que sirve para embarcaciones menores.', false, '2025-09-26 09:58:13.584181+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4f6b5342-6b39-4a7d-9c50-a02be60df990', 'af35415d-8051-4b3b-bab9-fb49a7b9d8dd', 'b', 'El ancla Danforth tiene una forma plana, mucho agarre y grandes dimensiones. Se trata de un ancla que se recomienda para cualquier tipo de fondo.', false, '2025-09-26 09:58:13.585245+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('e63a9b9d-860b-4918-9ef5-b947b51dbe5c', 'af35415d-8051-4b3b-bab9-fb49a7b9d8dd', 'c', 'El ancla sin cepo ofrece mejor maniobrabilidad, operación de recogida y menor peso que el ancla de cepo.', true, '2025-09-26 09:58:13.585692+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('91d90735-194a-449d-afdb-644eea784aee', 'af35415d-8051-4b3b-bab9-fb49a7b9d8dd', 'd', 'El ancla de arado es capaz de anclar, aunque se encuentre en zonas de barro, arena o algas, pero es en zonas rocosas donde es más recomendable.', false, '2025-09-26 09:58:13.586083+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('11b88460-fc40-461e-b74d-df468cf030b9', '64ff3ef2-5080-4694-9648-e354a0cc5532', 'a', 'El tenedero es un palo o percha larga, con un gancho metálico en un extremo, para coger las guías o las amarras.', true, '2025-09-26 09:59:21.506885+00');
