INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6db59fe5-570a-4d2a-86a1-7058fa70444e', '64ff3ef2-5080-4694-9648-e354a0cc5532', 'c', 'Los barcos deben llevar una longitud total de cadena de cinco veces su eslora.', false, '2025-09-26 09:59:21.507956+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('502eefc9-e545-462f-8ea0-e82f572ea495', '64ff3ef2-5080-4694-9648-e354a0cc5532', 'd', 'El garreo de un ancla se puede producir si no se ha filado suficiente cadena para el fondo o el viento reinante, o si el fondo es duro o demasiado blando.', false, '2025-09-26 09:59:21.508748+00');
