INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('0404f9d9-ba24-49f1-894a-c7c6195198c8', '746eae87-8541-4e4d-95c4-7e53022645f8', 'a', 'i) en la parte de proa, una luz roja todo horizonte o una bola; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz roja todo horizonte.', false, '2025-09-26 12:31:28.45228+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('4b9f9074-274b-44c4-97f7-9cb947553ac9', '746eae87-8541-4e4d-95c4-7e53022645f8', 'b', 'i) en la parte de proa, una luz roja todo horizonte o un cilindro; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz roja todo horizonte.', false, '2025-09-26 12:31:28.453455+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('af8d55ec-2854-4150-a327-f92bcfe0015a', '746eae87-8541-4e4d-95c4-7e53022645f8', 'c', 'i) en la parte de proa, una luz blanca todo horizonte o una bola; y ii) en la popa, o cerca de ella, y a una altura inferior a la de la luz prescrita en el apartado i), una luz blanca todo horizonte.', true, '2025-09-26 12:31:28.454175+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('981864fb-4ea6-4f0c-96c1-3b46f41e8e43', '746eae87-8541-4e4d-95c4-7e53022645f8', 'd', 'i) en la parte de proa, una luz blanca todo horizonte o una marca bicónica; y ii) en la popa, o cerca de ella, y a una altura superior a la de la luz prescrita en el apartado i), una luz blanca todo horizonte.', false, '2025-09-26 12:31:28.454584+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('13cde352-dee5-40d5-ae85-b7d846d8e18c', '225d632b-420e-4b10-8885-8d6355e65564', 'a', 'El buque remolcador y el remolcado pueden apartarse, en todo caso, de mi derrota sin problemas.', false, '2025-09-26 12:35:31.602669+00');
