INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('cc6895df-6bf2-4b7e-8be9-859f94c8d981', '31567dd2-5d60-48b4-92e8-c5b2b6451d8f', 'd', 'Cada una de las aberturas que hay en las diversas cubiertas para el servicio del buque.', false, '2025-09-29 13:31:31.015144+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('39cc8c1d-c549-4ee0-829c-06708aabd06f', '467ef435-0154-4f7d-bff2-e446ae084ae0', 'a', 'El rezón es un ancla pequeña, de tres uñas y sin cepo, que sirve para embarcaciones menores.', false, '2025-09-29 13:35:05.064838+00');
