INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('2e07fe15-b5e7-4c50-96e5-11d5166087b0', '467ef435-0154-4f7d-bff2-e446ae084ae0', 'c', 'El ancla sin cepo ofrece mejor maniobrabilidad, operación de recogida y menor peso que el ancla de cepo.', true, '2025-09-29 13:35:05.06629+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('566d811e-06c0-4d0b-8d8c-6c74327c7994', '467ef435-0154-4f7d-bff2-e446ae084ae0', 'd', 'El ancla de arado es capaz de anclar, aunque se encuentre en zonas de barro, arena o algas, pero es en zonas rocosas donde es más recomendable.', false, '2025-09-29 13:35:05.066682+00');
