INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('a9225e80-b80f-42c8-9e30-9a48a3a40e37', '250fdf3d-278d-40be-892c-ebceac8beec8', 'a', 'La hélice es el conjunto de palas que giran alrededor de un eje y empujan el fluido ambiente produciendo en él una fuerza de reacción que se utiliza principalmente para la propulsión de barcos y aeronaves.', true, '2025-09-13 13:53:11.294695+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('1a34500b-6ca5-4994-9074-5c0e17fff08d', '99dbd486-e89f-43de-8bf4-da4d89e291a0', 'c', 'Barlovento es la parte opuesta a aquella de donde viene el viento con respecto a un punto o lugar determinado.', true, '2025-09-13 13:53:11.23175+00');
