INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('6d0918da-f875-4d49-ac36-f0e1626e1389', '2d75ea34-9b6a-4777-a6ac-157acf376bc8', 'b', 'Dos luces todo horizonte en línea vertical, blanca la superior y roja la inferior, una luz de tope a popa y más elevada que la luz verde todo horizonte, además de las luces de costado y una luz de alcance.', false, '2025-09-13 13:53:12.829435+00');
