INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('9eb7156a-a8ed-499c-866a-98fe6d011729', 'f002dc0a-0ae4-49b5-8264-9aaa37a9faea', 'd', 'Si la medimos en semicirculares por estribor, es negativa.', false, '2025-09-13 13:53:12.494484+00');
