INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('782e0312-367e-4e42-9516-ffab6e3cbe2a', 'f0f391f5-de2f-4db9-a738-60a98682e9a6', 'a', 'La quilla es la pieza, que va de popa a proa por la parte inferior del barco y en que se asienta todo su armazón.', false, '2025-09-30 15:40:48.792176+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('524e459f-bab3-473e-a1db-1f48b40f6499', 'f0f391f5-de2f-4db9-a738-60a98682e9a6', 'b', 'La roda es la pieza gruesa y curva, que forma la proa de la embarcación.', false, '2025-09-30 15:40:48.793351+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('22568a52-60dd-45e0-9067-7950285d8cae', 'f0f391f5-de2f-4db9-a738-60a98682e9a6', 'c', 'El codaste es la pieza gruesa dispuesta verticalmente sobre el extremo de la quilla inmediato a la popa, que sirve de fundamento a toda la armazón de esta parte del buque.', false, '2025-09-30 15:40:48.79375+00');
INSERT INTO public.answer_options (id, question_id, opcion, texto, es_correcta, created_at) VALUES ('66faaeb5-a4c0-46eb-8c94-71c75173bc3c', 'f0f391f5-de2f-4db9-a738-60a98682e9a6', 'd', 'Los baos son cada una de las piezas curvas cuya base o parte inferior encaja en la quilla del buque y desde allí arrancan a babor y estribor, en dos ramas simétricas, formando las “costillas” del casco.', true, '2025-09-30 15:40:48.794165+00');
